window.DB = {"version": "anking-step1-65topics-2690q", "fuentes": [{"id": "anking", "nombre": "AnKing Overhaul — Step 1 (v11)", "idioma": "en", "descripcion": "USMLE Step 1 questions derived from the AnKing Overhaul Anki deck (cloze cards converted to single-best-answer MCQs).", "licencia": "Personal study use. Deck by the AnKing team, based on First Aid / Pathoma / Boards & Beyond / Sketchy."}], "temas": [{"id": 1, "nombre": "Medical Ethics", "sistema": "Public Health & Ethics", "fuente": "anking"}, {"id": 2, "nombre": "Histamine & Antihistamines", "sistema": "Respiratory Pharmacology", "fuente": "anking"}, {"id": 3, "nombre": "Reproductive Pharmacology", "sistema": "Reproductive System", "fuente": "anking"}, {"id": 4, "nombre": "Antimicrobials", "sistema": "Microbiology", "fuente": "anking"}, {"id": 5, "nombre": "Endocrine Pathology", "sistema": "Endocrine", "fuente": "anking"}, {"id": 6, "nombre": "Hematology & Oncology Pathology", "sistema": "Hematology & Oncology", "fuente": "anking"}, {"id": 7, "nombre": "Autonomic Drugs", "sistema": "Pharmacology", "fuente": "anking"}, {"id": 8, "nombre": "Reproductive System Pathology", "sistema": "Reproductive System", "fuente": "anking"}, {"id": 9, "nombre": "Neurology & Special Senses Pathology", "sistema": "Neurology & Special Senses", "fuente": "anking"}, {"id": 10, "nombre": "Gastrointestinal Pathology", "sistema": "Gastrointestinal", "fuente": "anking"}, {"id": 11, "nombre": "Immune Responses", "sistema": "Immunology", "fuente": "anking"}, {"id": 12, "nombre": "Renal Physiology", "sistema": "Renal", "fuente": "anking"}, {"id": 13, "nombre": "Metabolism", "sistema": "Biochemistry", "fuente": "anking"}, {"id": 14, "nombre": "Neoplasia", "sistema": "Pathology", "fuente": "anking"}, {"id": 15, "nombre": "Cardiovascular Pathology", "sistema": "Cardiovascular", "fuente": "anking"}, {"id": 16, "nombre": "Musculoskeletal Pathology", "sistema": "Musculoskeletal, Skin & Connective Tissue", "fuente": "anking"}, {"id": 17, "nombre": "Respiratory Pathology", "sistema": "Respiratory", "fuente": "anking"}, {"id": 18, "nombre": "Psychiatry Pathology", "sistema": "Psychiatry", "fuente": "anking"}, {"id": 19, "nombre": "Epidemiology & Biostatistics", "sistema": "Public Health & Ethics", "fuente": "anking"}, {"id": 20, "nombre": "Virology", "sistema": "Microbiology", "fuente": "anking"}, {"id": 21, "nombre": "Clinical Bacteriology", "sistema": "Microbiology", "fuente": "anking"}, {"id": 22, "nombre": "Parasitology", "sistema": "Microbiology", "fuente": "anking"}, {"id": 23, "nombre": "Endocrine Physiology", "sistema": "Endocrine", "fuente": "anking"}, {"id": 24, "nombre": "Endocrine Pharmacology", "sistema": "Endocrine", "fuente": "anking"}, {"id": 25, "nombre": "Endocrine Anatomy", "sistema": "Endocrine", "fuente": "anking"}, {"id": 26, "nombre": "Hematology & Oncology Pharmacology", "sistema": "Hematology & Oncology", "fuente": "anking"}, {"id": 27, "nombre": "Hematology & Oncology Anatomy", "sistema": "Hematology & Oncology", "fuente": "anking"}, {"id": 28, "nombre": "Hematology & Oncology Physiology", "sistema": "Hematology & Oncology", "fuente": "anking"}, {"id": 29, "nombre": "Toxicities & Side Effects", "sistema": "Pharmacology", "fuente": "anking"}, {"id": 30, "nombre": "Miscellaneous Pharmacology", "sistema": "Pharmacology", "fuente": "anking"}, {"id": 31, "nombre": "Pharmacokinetics & Pharmacodynamics", "sistema": "Pharmacology", "fuente": "anking"}, {"id": 32, "nombre": "Reproductive System Physiology", "sistema": "Reproductive System", "fuente": "anking"}, {"id": 33, "nombre": "Reproductive System Embryology", "sistema": "Reproductive System", "fuente": "anking"}, {"id": 34, "nombre": "Reproductive System Anatomy", "sistema": "Reproductive System", "fuente": "anking"}, {"id": 35, "nombre": "Neurology & Special Senses Anatomy & Physiology", "sistema": "Neurology & Special Senses", "fuente": "anking"}, {"id": 36, "nombre": "Neurology & Special Senses Pharmacology", "sistema": "Neurology & Special Senses", "fuente": "anking"}, {"id": 37, "nombre": "Ophthalmology", "sistema": "Neurology & Special Senses", "fuente": "anking"}, {"id": 38, "nombre": "Gastrointestinal Anatomy", "sistema": "Gastrointestinal", "fuente": "anking"}, {"id": 39, "nombre": "Gastrointestinal Physiology", "sistema": "Gastrointestinal", "fuente": "anking"}, {"id": 40, "nombre": "Gastrointestinal Pharmacology", "sistema": "Gastrointestinal", "fuente": "anking"}, {"id": 41, "nombre": "Immunosuppressants", "sistema": "Immunology", "fuente": "anking"}, {"id": 42, "nombre": "Cellular Immunology", "sistema": "Immunology", "fuente": "anking"}, {"id": 43, "nombre": "Lymphoid Structures", "sistema": "Immunology", "fuente": "anking"}, {"id": 44, "nombre": "Molecular Biology", "sistema": "Biochemistry", "fuente": "anking"}, {"id": 45, "nombre": "Genetics", "sistema": "Biochemistry", "fuente": "anking"}, {"id": 46, "nombre": "Nutrition", "sistema": "Biochemistry", "fuente": "anking"}, {"id": 47, "nombre": "Cardiovascular Physiology", "sistema": "Cardiovascular", "fuente": "anking"}, {"id": 48, "nombre": "Cardiovascular Pharmacology", "sistema": "Cardiovascular", "fuente": "anking"}, {"id": 49, "nombre": "Cardiovascular Anatomy", "sistema": "Cardiovascular", "fuente": "anking"}, {"id": 50, "nombre": "Dermatology", "sistema": "Musculoskeletal, Skin & Connective Tissue", "fuente": "anking"}, {"id": 51, "nombre": "Musculoskeletal Anatomy & Physiology", "sistema": "Musculoskeletal, Skin & Connective Tissue", "fuente": "anking"}, {"id": 52, "nombre": "Musculoskeletal Pharmacology", "sistema": "Musculoskeletal, Skin & Connective Tissue", "fuente": "anking"}, {"id": 53, "nombre": "Respiratory Physiology", "sistema": "Respiratory", "fuente": "anking"}, {"id": 54, "nombre": "Respiratory Anatomy", "sistema": "Respiratory", "fuente": "anking"}, {"id": 55, "nombre": "Respiratory Embryology", "sistema": "Respiratory", "fuente": "anking"}, {"id": 56, "nombre": "Cellular Injury", "sistema": "Pathology", "fuente": "anking"}, {"id": 57, "nombre": "Inflammation", "sistema": "Pathology", "fuente": "anking"}, {"id": 58, "nombre": "Renal Pathology", "sistema": "Renal", "fuente": "anking"}, {"id": 59, "nombre": "Renal Pharmacology", "sistema": "Renal", "fuente": "anking"}, {"id": 60, "nombre": "Renal Embryology", "sistema": "Renal", "fuente": "anking"}, {"id": 61, "nombre": "Psychiatry Pharmacology", "sistema": "Psychiatry", "fuente": "anking"}, {"id": 62, "nombre": "Psychology", "sistema": "Psychiatry", "fuente": "anking"}, {"id": 63, "nombre": "Healthcare Delivery", "sistema": "Public Health & Ethics", "fuente": "anking"}, {"id": 64, "nombre": "Quality & Safety", "sistema": "Public Health & Ethics", "fuente": "anking"}, {"id": 65, "nombre": "Communication Skills", "sistema": "Public Health & Ethics", "fuente": "anking"}], "preguntas": [{"id": "anking-ethics-001", "fuente": "anking", "tema": 1, "anki": "1521934672882", "q": "A legal determination that the care provided fell below the accepted standard of practice and resulted in injury or death to the patient is termed:", "o": {"A": "Malpractice", "B": "Battery", "C": "Informed refusal", "D": "Abandonment"}, "r": "A", "e": {"correcta": "Malpractice is professional negligence. It requires the '4 D's': a Duty of care, Dereliction (breach of the standard of care), Damage to the patient, and the breach being the Direct cause of that damage.", "incorrectas": {"B": "Battery is intentional, non-consented physical contact with a patient — not a standard-of-care failure.", "C": "Informed refusal is a competent patient declining recommended care after being told the risks; it is a patient right, not negligence.", "D": "Abandonment is the unilateral termination of the physician–patient relationship without adequate notice; it is one specific act, not the general term for harmful substandard care."}}}, {"id": "anking-ethics-002", "fuente": "anking", "tema": 1, "anki": "1522552355675", "q": "Which core ethical principle centers on treating patients fairly and equitably?", "o": {"A": "Justice", "B": "Autonomy", "C": "Beneficence", "D": "Nonmaleficence"}, "r": "A", "e": {"correcta": "Justice concerns the fair and equitable distribution of benefits, risks and resources among patients.", "incorrectas": {"B": "Autonomy is respecting the patient's right to self-determination.", "C": "Beneficence is acting in the patient's best interest.", "D": "Nonmaleficence is the duty to avoid harm ('do no harm')."}}}, {"id": "anking-ethics-003", "fuente": "anking", "tema": 1, "anki": "1522553684804", "q": "In triage, patients are prioritized unequally according to acuity. Which core ethical principle remains preserved despite this unequal treatment?", "o": {"A": "Justice", "B": "Autonomy", "C": "Fidelity", "D": "Nonmaleficence"}, "r": "A", "e": {"correcta": "Justice demands fairness, not identical treatment. Allocating scarce resources by medical need is equitable, so triage keeps justice intact.", "incorrectas": {"B": "Autonomy concerns honoring individual patient choices, not resource allocation.", "C": "Fidelity refers to loyalty and keeping commitments to the patient.", "D": "Nonmaleficence is avoiding harm, which is a separate consideration from fair allocation."}}}, {"id": "anking-ethics-004", "fuente": "anking", "tema": 1, "anki": "1522553752122", "q": "The dictum 'first, do no harm' expresses which ethical principle?", "o": {"A": "Nonmaleficence", "B": "Beneficence", "C": "Justice", "D": "Autonomy"}, "r": "A", "e": {"correcta": "Nonmaleficence is the obligation to avoid causing harm to the patient.", "incorrectas": {"B": "Beneficence is the positive duty to act for the patient's benefit — related but distinct from avoiding harm.", "C": "Justice concerns fairness and equitable treatment.", "D": "Autonomy concerns respecting patient self-determination."}}}, {"id": "anking-ethics-005", "fuente": "anking", "tema": 1, "anki": "1522553952175", "q": "A physician's special fiduciary duty to act in the patient's best interest reflects which principle?", "o": {"A": "Beneficence", "B": "Nonmaleficence", "C": "Autonomy", "D": "Justice"}, "r": "A", "e": {"correcta": "Beneficence is the positive obligation to act for the good of the patient.", "incorrectas": {"B": "Nonmaleficence is the duty to avoid harm, not the duty to actively benefit.", "C": "Autonomy is respecting the patient's own choices.", "D": "Justice is fair, equitable treatment across patients."}}}, {"id": "anking-ethics-006", "fuente": "anking", "tema": 1, "anki": "1522554099595", "q": "Respecting a competent patient's right to accept or refuse recommended treatment reflects which principle?", "o": {"A": "Autonomy", "B": "Beneficence", "C": "Justice", "D": "Nonmaleficence"}, "r": "A", "e": {"correcta": "Autonomy is the obligation to respect patients as individuals and to honor their preferences regarding their own care.", "incorrectas": {"B": "Beneficence would emphasize doing what benefits the patient, even over their stated wish.", "C": "Justice concerns fairness across patients.", "D": "Nonmaleficence concerns avoiding harm."}}}, {"id": "anking-ethics-007", "fuente": "anking", "tema": 1, "anki": "1525459102217", "q": "When a patient lacks decision-making capacity, does a validly designated health-care proxy's decision override those of other family members?", "o": {"A": "Yes — the proxy speaks with the patient's authority", "B": "No — the next of kin always takes precedence", "C": "No — the attending physician has final say", "D": "Only if every family member agrees"}, "r": "A", "e": {"correcta": "A validly appointed health-care proxy (durable power of attorney for health care) legally stands in for the patient and overrules other family members, regardless of relationship.", "incorrectas": {"B": "Next of kin are consulted only when no proxy has been designated.", "C": "The physician provides information and options but is not the surrogate decision-maker.", "D": "The proxy's authority does not require unanimous family consent."}}}, {"id": "anking-ethics-008", "fuente": "anking", "tema": 1, "anki": "1526341083111", "q": "Which physician-placed advance directive specifies that a patient should NOT receive CPR, including both basic and advanced cardiac life support?", "o": {"A": "Do-not-resuscitate (DNR) order", "B": "Living will", "C": "Durable power of attorney for health care", "D": "Health-care proxy designation"}, "r": "A", "e": {"correcta": "A DNR is a physician order directing that CPR (BLS and ACLS) be withheld if the patient arrests.", "incorrectas": {"B": "A living will is the patient's own written statement of future care preferences, not a physician order.", "C": "A durable power of attorney appoints a surrogate decision-maker; it does not itself specify no-CPR.", "D": "A health-care proxy names who decides, not the specific resuscitation instruction."}}}, {"id": "anking-ethics-009", "fuente": "anking", "tema": 1, "anki": "1524801828125", "q": "You suspect child abuse in a pediatric patient. What is the most appropriate next step?", "o": {"A": "Ask permission to interview the child alone", "B": "Openly confront the parents with the accusation", "C": "Discharge the child and arrange outpatient follow-up", "D": "Wait for a police investigation before examining the child"}, "r": "A", "e": {"correcta": "Interviewing the child alone allows a candid history and examination away from a possible abuser. (Suspected abuse must still be reported to Child Protective Services — reporting and interviewing are not mutually exclusive.)", "incorrectas": {"B": "Confronting the parents can escalate danger to the child and compromise the evaluation.", "C": "Discharging a child with suspected abuse fails the duty to protect.", "D": "Mandatory evaluation and reporting should not be delayed while awaiting law enforcement."}}}, {"id": "anking-ethics-010", "fuente": "anking", "tema": 1, "anki": "1525915872970", "q": "Which factor most strongly precipitates a patient's decision to file a malpractice lawsuit?", "o": {"A": "The perception that the physician was uncaring", "B": "The absolute severity of the medical outcome", "C": "The physician's number of years in practice", "D": "The size of the hospital"}, "r": "A", "e": {"correcta": "The strongest predictor of litigation is the patient's perception of a poor, uncaring physician relationship — communication matters more than the outcome itself.", "incorrectas": {"B": "Bad outcomes alone poorly predict lawsuits; many severe outcomes never lead to suits when rapport is good.", "C": "Experience level is not the primary driver.", "D": "Institution size is unrelated to the individual decision to sue."}}}, {"id": "anking-ethics-011", "fuente": "anking", "tema": 1, "anki": "1525914380350", "q": "What is the best setting in which to begin a conversation about advance care planning?", "o": {"A": "The outpatient (ambulatory) setting", "B": "During an active cardiac arrest", "C": "In the ICU immediately after intubation", "D": "Only once the patient is imminently terminal"}, "r": "A", "e": {"correcta": "The stable, unhurried outpatient setting is ideal for starting advance care planning; it should then be re-addressed at hospital admission.", "incorrectas": {"B": "An arrest is far too late to begin a values-based discussion.", "C": "Post-intubation, the patient often cannot participate.", "D": "Waiting until imminent death eliminates the patient's chance to plan meaningfully."}}}, {"id": "anking-resp-001", "fuente": "anking", "tema": 2, "anki": "1474571576716", "q": "Mast cells degranulate on antigen exposure once they have been sensitized by which antibody class bound to their surface?", "o": {"A": "IgE", "B": "IgG", "C": "IgM", "D": "IgA"}, "r": "A", "e": {"correcta": "Allergen-specific IgE binds Fcε receptors on mast cells; cross-linking by antigen triggers degranulation (type I hypersensitivity).", "incorrectas": {"B": "IgG mediates type II/III reactions and opsonization, not mast-cell sensitization.", "C": "IgM is the first antibody in a primary response and activates complement, not mast cells.", "D": "IgA protects mucosal surfaces and does not sensitize mast cells."}}}, {"id": "anking-resp-002", "fuente": "anking", "tema": 2, "anki": "1474571583341", "q": "Allergic symptoms such as nasal itching, urticaria and bronchoconstriction are mediated by histamine acting primarily on which receptor?", "o": {"A": "H1", "B": "H2", "C": "H3", "D": "H4"}, "r": "A", "e": {"correcta": "H1 receptors mediate the classic allergic/inflammatory effects of histamine.", "incorrectas": {"B": "H2 receptors mainly drive gastric acid secretion.", "C": "H3 receptors are presynaptic autoreceptors in the CNS.", "D": "H4 receptors modulate chemotaxis of immune cells and are not the main allergic mediator."}}}, {"id": "anking-resp-003", "fuente": "anking", "tema": 2, "anki": "1474571586703", "q": "The H1 histamine receptor is coupled to which G protein?", "o": {"A": "Gq", "B": "Gs", "C": "Gi", "D": "G12/13"}, "r": "A", "e": {"correcta": "H1 → Gq → phospholipase C → IP3/DAG → increased intracellular Ca2+.", "incorrectas": {"B": "Gs raises cAMP and is used by the H2 receptor.", "C": "Gi lowers cAMP (e.g., H3/H4 receptors).", "D": "G12/13 signals through Rho, not the histamine H1 pathway."}}}, {"id": "anking-resp-004", "fuente": "anking", "tema": 2, "anki": "1474571591865", "q": "The H2 histamine receptor is coupled to which G protein?", "o": {"A": "Gs", "B": "Gq", "C": "Gi", "D": "G12/13"}, "r": "A", "e": {"correcta": "H2 → Gs → adenylyl cyclase → increased cAMP, which drives gastric acid secretion by parietal cells.", "incorrectas": {"B": "Gq is the H1 pathway (PLC/Ca2+).", "C": "Gi decreases cAMP.", "D": "G12/13 uses the Rho pathway, unrelated to H2."}}}, {"id": "anking-resp-005", "fuente": "anking", "tema": 2, "anki": "1474571599295", "q": "Which histamine receptor on gastric parietal cells mediates gastric acid secretion?", "o": {"A": "H2", "B": "H1", "C": "H3", "D": "H4"}, "r": "A", "e": {"correcta": "H2 receptors on parietal cells stimulate acid secretion — the target of H2 blockers such as ranitidine and famotidine.", "incorrectas": {"B": "H1 mediates allergic and smooth-muscle effects, not acid secretion.", "C": "H3 receptors are CNS presynaptic autoreceptors.", "D": "H4 receptors are found mainly on hematopoietic cells."}}}, {"id": "anking-resp-006", "fuente": "anking", "tema": 2, "anki": "1474571653671", "q": "Histamine acting on H1 receptors of bronchial smooth muscle — especially in asthmatic patients — causes:", "o": {"A": "Bronchoconstriction", "B": "Bronchodilation", "C": "No change in airway tone", "D": "Ciliary paralysis"}, "r": "A", "e": {"correcta": "H1 activation contracts bronchial smooth muscle, narrowing airways — clinically important in asthma.", "incorrectas": {"B": "Bronchodilation is produced by beta-2 agonists, not histamine.", "C": "Histamine clearly alters airway tone (constriction).", "D": "Histamine does not paralyze cilia."}}}, {"id": "anking-resp-007", "fuente": "anking", "tema": 2, "anki": "1474571630796", "q": "Histamine-induced urticaria (hives) results primarily from which H1-mediated vascular effect?", "o": {"A": "Increased vascular permeability", "B": "Vasoconstriction of dermal arterioles", "C": "Decreased capillary hydrostatic pressure", "D": "Platelet aggregation"}, "r": "A", "e": {"correcta": "H1 activation increases vascular permeability, causing fluid extravasation into the dermis — the wheal of urticaria.", "incorrectas": {"B": "Histamine causes vasodilation, not vasoconstriction.", "C": "Permeability and vasodilation raise, not lower, local fluid movement.", "D": "Platelet aggregation is unrelated to the hives mechanism."}}}, {"id": "anking-resp-008", "fuente": "anking", "tema": 2, "anki": "1474571658398", "q": "In the central nervous system, histamine regulates arousal and wakefulness mainly through which receptor — explaining the sedation caused by first-generation antihistamines?", "o": {"A": "H1", "B": "H2", "C": "H3", "D": "H4"}, "r": "A", "e": {"correcta": "Central H1 receptors promote wakefulness; first-generation H1 blockers cross the blood–brain barrier and block them, causing sedation.", "incorrectas": {"B": "H2 is primarily a peripheral (gastric) receptor.", "C": "H3 is a presynaptic autoreceptor that regulates histamine release but is not the sedation target of antihistamines.", "D": "H4 is mainly involved in immune-cell chemotaxis."}}}, {"id": "anking-resp-009", "fuente": "anking", "tema": 2, "anki": "1474571667626", "q": "To which drug class do diphenhydramine and dimenhydrinate belong?", "o": {"A": "First-generation H1 antagonists", "B": "Second-generation H1 antagonists", "C": "H2 antagonists", "D": "Mast-cell stabilizers"}, "r": "A", "e": {"correcta": "Diphenhydramine and dimenhydrinate are first-generation H1 blockers: lipophilic, cross the BBB (sedation) and have antimuscarinic effects.", "incorrectas": {"B": "Second-generation agents (loratadine, fexofenadine, cetirizine) are non-sedating.", "C": "H2 antagonists (famotidine) reduce gastric acid, not allergy symptoms.", "D": "Mast-cell stabilizers (cromolyn) prevent degranulation rather than block H1 receptors."}}}, {"id": "anking-resp-010", "fuente": "anking", "tema": 2, "anki": "1474571672988", "q": "Which of the following is a first-generation (sedating) H1 antihistamine?", "o": {"A": "Chlorpheniramine", "B": "Loratadine", "C": "Fexofenadine", "D": "Cetirizine"}, "r": "A", "e": {"correcta": "Chlorpheniramine is a first-generation H1 antagonist and crosses the blood–brain barrier.", "incorrectas": {"B": "Loratadine is second-generation and minimally sedating.", "C": "Fexofenadine is second-generation and essentially non-sedating.", "D": "Cetirizine is second-generation (though mildly more sedating than the others in its class)."}}}, {"id": "anking-resp-011", "fuente": "anking", "tema": 2, "anki": "1474571606722", "q": "Histamine acting on H1 receptors changes nasal and bronchial mucus production in which direction?", "o": {"A": "Increases secretion", "B": "Decreases secretion", "C": "No effect on secretion", "D": "Thickens and halts secretion"}, "r": "A", "e": {"correcta": "H1 activation increases nasal and bronchial mucus production, contributing to rhinorrhea and airway symptoms.", "incorrectas": {"B": "Antimuscarinic drugs, not histamine, dry secretions.", "C": "Histamine clearly increases secretion.", "D": "Histamine does not halt secretion."}}}, {"id": "anking-repro-001", "fuente": "anking", "tema": 3, "anki": "1462996334267", "q": "Combined oral contraceptives prevent ovulation mainly by inhibiting the release of which pituitary hormones?", "o": {"A": "FSH and LH", "B": "GnRH and prolactin", "C": "hCG and progesterone", "D": "Oxytocin and estrogen"}, "r": "A", "e": {"correcta": "Exogenous estrogen/progestin exert negative feedback on the anterior pituitary, suppressing FSH and LH and blocking the LH surge needed for ovulation.", "incorrectas": {"B": "GnRH is hypothalamic; prolactin is not the ovulation trigger.", "C": "hCG is a placental hormone of pregnancy; progesterone is a component of the pill, not a suppressed target.", "D": "Oxytocin governs labor/letdown and is unrelated to ovulation suppression."}}}, {"id": "anking-repro-002", "fuente": "anking", "tema": 3, "anki": "1463080993949", "q": "Penile erection is mediated by which substance released in response to parasympathetic (pelvic nerve) stimulation?", "o": {"A": "Nitric oxide (increasing cGMP)", "B": "Norepinephrine (increasing cAMP)", "C": "Acetylcholine acting on nicotinic receptors", "D": "Endothelin-1"}, "r": "A", "e": {"correcta": "Parasympathetic input releases nitric oxide, which raises cGMP, relaxing corpus cavernosum smooth muscle → erection ('Point and Shoot': Parasympathetic = erection).", "incorrectas": {"B": "Norepinephrine (sympathetic) promotes detumescence, not erection.", "C": "Erection is mediated by NO, not a direct nicotinic effect.", "D": "Endothelin-1 is a vasoconstrictor and does not drive erection."}}}, {"id": "anking-repro-003", "fuente": "anking", "tema": 3, "anki": "1474666117993", "q": "Besides erectile dysfunction, sildenafil is also indicated to treat:", "o": {"A": "Pulmonary arterial hypertension", "B": "Hypertensive emergency", "C": "Heart failure with reduced ejection fraction", "D": "Benign prostatic hyperplasia"}, "r": "A", "e": {"correcta": "As a PDE-5 inhibitor, sildenafil causes pulmonary vasodilation and is approved for pulmonary arterial hypertension.", "incorrectas": {"B": "It is not used for hypertensive emergencies; combining it with nitrates can cause dangerous hypotension.", "C": "It is not a therapy for systolic heart failure.", "D": "BPH is treated with α1 blockers or 5α-reductase inhibitors, not sildenafil."}}}, {"id": "anking-repro-004", "fuente": "anking", "tema": 3, "anki": "1463346003581", "q": "Tamsulosin, used for benign prostatic hyperplasia, is best classified as a:", "o": {"A": "Selective α1A/α1D antagonist", "B": "Non-selective α1 antagonist", "C": "5α-reductase inhibitor", "D": "β1-adrenergic antagonist"}, "r": "A", "e": {"correcta": "Tamsulosin preferentially blocks α1A/α1D receptors in the prostate and bladder neck, relaxing smooth muscle with relatively little effect on blood pressure.", "incorrectas": {"B": "Non-selective α1 blockers (terazosin, doxazosin) also lower systemic BP.", "C": "5α-reductase inhibitors (finasteride) shrink the gland over months by blocking DHT synthesis.", "D": "β1 blockade is unrelated to BPH treatment."}}}, {"id": "anking-repro-005", "fuente": "anking", "tema": 3, "anki": "1463345994680", "q": "Terazosin, used for benign prostatic hyperplasia, acts as a:", "o": {"A": "Non-selective α1 antagonist", "B": "Selective α1A antagonist", "C": "5α-reductase inhibitor", "D": "GnRH analog"}, "r": "A", "e": {"correcta": "Terazosin (like prazosin and doxazosin) non-selectively blocks α1 receptors, relaxing prostatic smooth muscle but also lowering blood pressure (first-dose orthostatic hypotension).", "incorrectas": {"B": "Selective α1A blockade describes tamsulosin/silodosin.", "C": "5α-reductase inhibitors act hormonally, not on adrenergic receptors.", "D": "GnRH analogs (leuprolide) are used in prostate cancer, not BPH."}}}, {"id": "anking-repro-006", "fuente": "anking", "tema": 3, "anki": "1463346102353", "q": "Prostatic adenocarcinoma may be treated with leuprolide. Leuprolide is a:", "o": {"A": "GnRH analog", "B": "Androgen-receptor antagonist", "C": "5α-reductase inhibitor", "D": "Aromatase inhibitor"}, "r": "A", "e": {"correcta": "Leuprolide is a GnRH analog. Given continuously it downregulates pituitary GnRH receptors, lowering FSH/LH and testosterone (an initial 'flare' can occur).", "incorrectas": {"B": "Androgen-receptor antagonists (flutamide) block the receptor directly.", "C": "5α-reductase inhibitors block conversion of testosterone to DHT.", "D": "Aromatase inhibitors block estrogen synthesis, used chiefly in breast cancer."}}}, {"id": "anking-repro-007", "fuente": "anking", "tema": 3, "anki": "1463346102353", "q": "Flutamide, used in prostate cancer, works as a(n):", "o": {"A": "Androgen-receptor inhibitor", "B": "GnRH analog", "C": "Aromatase inhibitor", "D": "5α-reductase inhibitor"}, "r": "A", "e": {"correcta": "Flutamide is a non-steroidal androgen-receptor antagonist that blocks testosterone/DHT signaling in prostate tissue.", "incorrectas": {"B": "GnRH analogs (leuprolide) act at the pituitary.", "C": "Aromatase inhibitors block estrogen synthesis.", "D": "5α-reductase inhibitors (finasteride) reduce DHT formation but do not block the receptor."}}}, {"id": "anking-repro-008", "fuente": "anking", "tema": 3, "anki": "1463172352600", "q": "Endometrial hyperplasia is most commonly caused by:", "o": {"A": "Unopposed estrogen", "B": "Excess progesterone", "C": "Androgen excess", "D": "Hyperprolactinemia"}, "r": "A", "e": {"correcta": "Chronic estrogen stimulation without the opposing effect of progesterone drives endometrial proliferation and hyperplasia (a risk factor for endometrial carcinoma).", "incorrectas": {"B": "Progesterone opposes estrogen and protects the endometrium.", "C": "Androgen excess causes hirsutism/virilization, not endometrial hyperplasia directly.", "D": "Hyperprolactinemia causes galactorrhea and amenorrhea, not hyperplasia."}}}, {"id": "anking-repro-009", "fuente": "anking", "tema": 3, "anki": "1475803210175", "q": "In polycystic ovary syndrome, spironolactone reduces symptoms of androgen excess (e.g., hirsutism) mainly by:", "o": {"A": "Antagonizing the androgen receptor", "B": "Blocking aromatase", "C": "Stimulating LH release", "D": "Activating the estrogen receptor"}, "r": "A", "e": {"correcta": "Spironolactone antagonizes the androgen receptor (and also inhibits 17α-hydroxylase, lowering androgen synthesis), improving hirsutism in PCOS.", "incorrectas": {"B": "Aromatase converts androgens to estrogens; spironolactone is not an aromatase inhibitor.", "C": "It does not stimulate LH; excess LH would worsen androgen production.", "D": "Its benefit is anti-androgenic, not via direct estrogen-receptor activation."}}}, {"id": "anking-repro-010", "fuente": "anking", "tema": 3, "anki": "1475803214768", "q": "Which anti-androgenic adverse effect may spironolactone cause in male patients?", "o": {"A": "Gynecomastia", "B": "Priapism", "C": "Increased libido", "D": "Worsening male-pattern baldness"}, "r": "A", "e": {"correcta": "By antagonizing androgen receptors, spironolactone can cause gynecomastia (as well as decreased libido and impotence) in men.", "incorrectas": {"B": "Priapism is not a spironolactone effect; it is associated with PDE-5 inhibitors and certain antipsychotics.", "C": "Its anti-androgen action tends to decrease, not increase, libido.", "D": "Anti-androgen effects would not worsen androgenic alopecia."}}}, {"id": "anking-repro-011", "fuente": "anking", "tema": 3, "anki": "1477433035666", "q": "Prazosin, terazosin, doxazosin and tamsulosin all belong to which drug class?", "o": {"A": "α1-adrenergic antagonists (the '-osins')", "B": "β-adrenergic antagonists", "C": "5α-reductase inhibitors", "D": "GnRH analogs"}, "r": "A", "e": {"correcta": "The '-osin' drugs are α1 antagonists. Non-selective ones (prazosin, terazosin, doxazosin) also lower blood pressure; tamsulosin is α1A/D-selective for the prostate.", "incorrectas": {"B": "β-blockers end in '-olol' and are unrelated to this class.", "C": "5α-reductase inhibitors (finasteride, dutasteride) act hormonally.", "D": "GnRH analogs (leuprolide) act at the pituitary in prostate cancer."}}}, {"id": "anking-antimicrobials-001", "fuente": "anking", "tema": 4, "anki": "1402963462795", "q": "What is the treatment of choice for Pneumocystis jirovecii pneumonia?", "o": {"A": "TMP-SMX", "B": "Vancomycin", "C": "Fluconazole", "D": "Isoniazid"}, "r": "A", "e": {"correcta": "TMP-SMX is first-line treatment for Pneumocystis jirovecii pneumonia; pentamidine is an alternative in patients who cannot tolerate sulfa drugs.", "incorrectas": {"B": "Vancomycin treats gram-positive bacterial infections, not fungal PCP.", "C": "Fluconazole is used for Candida and Cryptococcus, not Pneumocystis.", "D": "Isoniazid is an anti-tuberculosis drug, not effective against Pneumocystis."}}}, {"id": "anking-antimicrobials-002", "fuente": "anking", "tema": 4, "anki": "1403470070980", "q": "How do cephalosporin antibiotics affect the nephrotoxicity risk of aminoglycosides when co-administered?", "o": {"A": "They increase nephrotoxicity", "B": "They decrease nephrotoxicity", "C": "They have no effect on nephrotoxicity", "D": "They convert nephrotoxicity into ototoxicity"}, "r": "A", "e": {"correcta": "Cephalosporins potentiate the nephrotoxic effects of aminoglycosides when used concurrently, increasing renal injury risk.", "incorrectas": {"B": "Cephalosporins do not protect against aminoglycoside nephrotoxicity; they worsen it.", "C": "There is a well-documented additive nephrotoxic interaction, not a neutral one.", "D": "Ototoxicity is a separate aminoglycoside toxicity and is not converted from nephrotoxicity by cephalosporins."}}}, {"id": "anking-antimicrobials-003", "fuente": "anking", "tema": 4, "anki": "1403542843264", "q": "Which bacterial ribosomal subunit does chloramphenicol target?", "o": {"A": "50S subunit", "B": "30S subunit", "C": "40S subunit", "D": "60S subunit"}, "r": "A", "e": {"correcta": "Chloramphenicol binds the 50S ribosomal subunit and inhibits peptidyltransferase activity, blocking peptide bond formation.", "incorrectas": {"B": "The 30S subunit is the target of aminoglycosides and tetracyclines, not chloramphenicol.", "C": "The 40S subunit is a eukaryotic ribosomal subunit, not a bacterial target.", "D": "The 60S subunit is also eukaryotic, not the bacterial ribosomal target of chloramphenicol."}}}, {"id": "anking-antimicrobials-004", "fuente": "anking", "tema": 4, "anki": "1403542915862", "q": "Which bacterial ribosomal subunit does linezolid target?", "o": {"A": "50S subunit", "B": "30S subunit", "C": "40S subunit", "D": "70S subunit as a whole complex only"}, "r": "A", "e": {"correcta": "Linezolid binds the 50S ribosomal subunit and inhibits formation of the initiation complex, preventing bacterial protein synthesis.", "incorrectas": {"B": "The 30S subunit is targeted by drugs like tetracyclines and aminoglycosides, not linezolid.", "C": "The 40S subunit is a eukaryotic ribosomal component, irrelevant to linezolid's bacterial target.", "D": "Linezolid acts specifically at the 50S subunit during initiation complex formation, not by binding the assembled 70S ribosome nonspecifically."}}}, {"id": "anking-antimicrobials-005", "fuente": "anking", "tema": 4, "anki": "1403560526372", "q": "What is the mechanism of action of chloramphenicol?", "o": {"A": "Blocks peptidyltransferase at the 50S ribosomal subunit", "B": "Inhibits DNA gyrase", "C": "Inhibits cell wall peptidoglycan cross-linking", "D": "Blocks the 30S subunit to prevent tRNA binding"}, "r": "A", "e": {"correcta": "Chloramphenicol inhibits peptidyltransferase activity at the bacterial 50S ribosomal subunit, blocking peptide bond formation during protein synthesis.", "incorrectas": {"B": "DNA gyrase inhibition is the mechanism of fluoroquinolones, not chloramphenicol.", "C": "Cell wall cross-linking inhibition describes beta-lactams, not chloramphenicol.", "D": "Blocking tRNA binding at the 30S subunit describes tetracyclines, not chloramphenicol."}}}, {"id": "anking-antimicrobials-006", "fuente": "anking", "tema": 4, "anki": "1403560979085", "q": "What hematological complications are associated with chloramphenicol use, and how do they differ in dose dependence?", "o": {"A": "Anemia (dose-dependent) and aplastic anemia (dose-independent)", "B": "Thrombocytopenia (dose-dependent) and hemolysis (dose-independent)", "C": "Neutropenia (dose-dependent) and megaloblastic anemia (dose-independent)", "D": "Aplastic anemia (dose-dependent) and anemia (dose-independent)"}, "r": "A", "e": {"correcta": "Chloramphenicol causes a reversible, dose-dependent anemia from bone marrow suppression, and a rare, dose-independent (idiosyncratic) aplastic anemia.", "incorrectas": {"B": "Thrombocytopenia and hemolysis are not the classic paired hematologic toxicities described for chloramphenicol.", "C": "Neutropenia and megaloblastic anemia are not the characteristic chloramphenicol toxicities taught in this context.", "D": "The dose-dependence is reversed here: anemia is dose-dependent while aplastic anemia is the dose-independent reaction, not vice versa."}}}, {"id": "anking-antimicrobials-007", "fuente": "anking", "tema": 4, "anki": "1403561122259", "q": "What is the mechanism of bacterial resistance to chloramphenicol?", "o": {"A": "Plasmid-encoded acetyltransferases that inactivate the drug", "B": "Efflux pumps that expel the drug from the 30S subunit", "C": "Mutation of DNA gyrase preventing drug binding", "D": "Beta-lactamase enzymes that hydrolyze the drug"}, "r": "A", "e": {"correcta": "Resistance to chloramphenicol occurs via plasmid-encoded acetyltransferases that chemically inactivate the drug, preventing it from binding the ribosome.", "incorrectas": {"B": "Efflux pumps affecting the 30S subunit are more characteristic of tetracycline resistance, not the classic chloramphenicol resistance mechanism.", "C": "DNA gyrase mutations confer fluoroquinolone resistance, not chloramphenicol resistance.", "D": "Beta-lactamases inactivate beta-lactam antibiotics, not chloramphenicol."}}}, {"id": "anking-antimicrobials-008", "fuente": "anking", "tema": 4, "anki": "1403571546141", "q": "Which class of antibiotics can cause leg cramps, myalgias, and cartilage damage (tendinopathy)?", "o": {"A": "Fluoroquinolones", "B": "Macrolides", "C": "Aminoglycosides", "D": "Tetracyclines"}, "r": "A", "e": {"correcta": "Fluoroquinolones are associated with tendinopathy, tendon rupture, myalgias, and cartilage damage, likely related to chelation of magnesium in cartilage.", "incorrectas": {"B": "Macrolides are more known for GI upset and QT prolongation, not cartilage/tendon damage.", "C": "Aminoglycosides are known for nephrotoxicity and ototoxicity, not cartilage damage.", "D": "Tetracyclines cause tooth discoloration and bone growth inhibition in children, not the classic tendinopathy of fluoroquinolones."}}}, {"id": "anking-antimicrobials-009", "fuente": "anking", "tema": 4, "anki": "1403635238503", "q": "Which viral enzyme monophosphorylates acyclovir, famciclovir, and valacyclovir, activating them (the rate-limiting step)?", "o": {"A": "Thymidine kinase", "B": "DNA polymerase", "C": "Reverse transcriptase", "D": "Neuraminidase"}, "r": "A", "e": {"correcta": "Viral thymidine kinase phosphorylates acyclovir (and related prodrugs) to the monophosphate form, which is the rate-limiting step in its activation; host kinases complete conversion to the active triphosphate.", "incorrectas": {"B": "Viral DNA polymerase is the enzyme these drugs ultimately inhibit, not the enzyme that activates them.", "C": "Reverse transcriptase is relevant to retroviruses like HIV, not to herpesvirus activation of acyclovir.", "D": "Neuraminidase is an influenza enzyme targeted by drugs like oseltamivir, unrelated to acyclovir activation."}}}, {"id": "anking-antimicrobials-010", "fuente": "anking", "tema": 4, "anki": "1403635898739", "q": "What is the mechanism of viral resistance to acyclovir, famciclovir, and valacyclovir?", "o": {"A": "Mutated or absent thymidine kinase", "B": "Mutated viral DNA polymerase only, with normal thymidine kinase", "C": "Increased efflux of the drug from infected cells", "D": "Enzymatic degradation of the drug by viral proteases"}, "r": "A", "e": {"correcta": "The most common mechanism of resistance to acyclovir-family drugs is mutation or loss of viral thymidine kinase, preventing the initial phosphorylation needed for activation.", "incorrectas": {"B": "While DNA polymerase mutations can also cause resistance, this is far less common than thymidine kinase mutations, making this not the best answer as stated.", "C": "Efflux pump-mediated resistance is not the described mechanism for herpesvirus resistance to acyclovir.", "D": "Viral proteases degrading the drug is not a recognized resistance mechanism for acyclovir-class drugs."}}}, {"id": "anking-antimicrobials-011", "fuente": "anking", "tema": 4, "anki": "1403636433207", "q": "What is the treatment for CMV retinitis in immunocompromised patients when ganciclovir fails?", "o": {"A": "Foscarnet or cidofovir", "B": "Acyclovir or valacyclovir", "C": "Amphotericin B or fluconazole", "D": "Oseltamivir or zanamivir"}, "r": "A", "e": {"correcta": "Foscarnet and cidofovir are second-line agents for CMV retinitis when ganciclovir fails or resistance develops, as they do not require viral kinase activation.", "incorrectas": {"B": "Acyclovir and valacyclovir are not effective against CMV and are used for HSV/VZV instead.", "C": "Amphotericin B and fluconazole are antifungals, not appropriate for a viral CMV infection.", "D": "Oseltamivir and zanamivir are anti-influenza drugs, not used for CMV retinitis."}}}, {"id": "anking-antimicrobials-012", "fuente": "anking", "tema": 4, "anki": "1403636465989", "q": "What is the treatment for acyclovir-resistant HSV infection?", "o": {"A": "Foscarnet or cidofovir", "B": "Ganciclovir or valganciclovir", "C": "TMP-SMX or pentamidine", "D": "Ribavirin or interferon"}, "r": "A", "e": {"correcta": "Foscarnet and cidofovir do not require thymidine kinase activation, making them effective against acyclovir-resistant HSV strains with mutated or absent thymidine kinase.", "incorrectas": {"B": "Ganciclovir and valganciclovir are primarily used for CMV, not as the standard for acyclovir-resistant HSV.", "C": "TMP-SMX and pentamidine treat Pneumocystis jirovecii, not HSV.", "D": "Ribavirin and interferon are used for other viral infections like hepatitis C or RSV, not acyclovir-resistant HSV."}}}, {"id": "anking-antimicrobials-013", "fuente": "anking", "tema": 4, "anki": "1403636599345", "q": "What is the mechanism of action of cidofovir?", "o": {"A": "Preferential direct inhibition of viral DNA polymerase without requiring viral kinase activation", "B": "Inhibition of viral thymidine kinase", "C": "Inhibition of viral protease", "D": "Inhibition of viral neuraminidase"}, "r": "A", "e": {"correcta": "Cidofovir is a nucleotide analog that directly inhibits viral DNA polymerase; it does not require phosphorylation by viral thymidine kinase, so it remains active against thymidine kinase-deficient resistant strains.", "incorrectas": {"B": "Cidofovir does not act by inhibiting thymidine kinase; rather it bypasses the need for that enzyme.", "C": "Protease inhibition is the mechanism of drugs like HIV protease inhibitors, not cidofovir.", "D": "Neuraminidase inhibition describes anti-influenza drugs, not cidofovir's mechanism against DNA viruses."}}}, {"id": "anking-antimicrobials-014", "fuente": "anking", "tema": 4, "anki": "1403663273810", "q": "Which class of antibiotics is generally avoided in pregnancy due to risk of cartilage damage in the fetus?", "o": {"A": "Fluoroquinolones", "B": "Penicillins", "C": "Cephalosporins", "D": "Macrolides"}, "r": "A", "e": {"correcta": "Fluoroquinolones are avoided in pregnancy because of their potential to damage developing cartilage, based on animal studies showing arthropathy.", "incorrectas": {"B": "Penicillins are generally considered safe in pregnancy and are not associated with cartilage damage.", "C": "Cephalosporins are also generally considered safe in pregnancy, without the cartilage toxicity concern.", "D": "Macrolides (aside from some specific concerns) are not classically linked to fetal cartilage damage the way fluoroquinolones are."}}}, {"id": "anking-antimicrobials-015", "fuente": "anking", "tema": 4, "anki": "1403663585680", "q": "Which antibiotic is avoided in pregnancy/neonates because it can cause \"Gray Baby\" syndrome?", "o": {"A": "Chloramphenicol", "B": "Tetracycline", "C": "Sulfonamides", "D": "Fluoroquinolones"}, "r": "A", "e": {"correcta": "Chloramphenicol causes Gray Baby syndrome in neonates due to their immature liver UDP-glucuronyltransferase, which is needed to conjugate and excrete the drug, leading to toxic accumulation.", "incorrectas": {"B": "Tetracyclines cause discoloration of teeth and inhibited bone growth, not Gray Baby syndrome.", "C": "Sulfonamides can cause kernicterus in neonates by displacing bilirubin, a different toxicity than Gray Baby syndrome.", "D": "Fluoroquinolones are associated with cartilage damage, not Gray Baby syndrome."}}}, {"id": "anking-antimicrobials-016", "fuente": "anking", "tema": 4, "anki": "1461794799767", "q": "Which two factors determine whether a patient with hepatitis C infection should be treated and what regimen to use?", "o": {"A": "HCV genotype and stage of liver disease (fibrosis)", "B": "Patient age and viral load only", "C": "HCV genotype and presence of hepatitis B coinfection", "D": "Stage of liver disease and patient's blood type"}, "r": "A", "e": {"correcta": "Treatment decisions and regimen selection for chronic HCV are guided primarily by the HCV genotype and the stage of liver disease (degree of fibrosis).", "incorrectas": {"B": "Age and viral load alone are not the two defining factors used to select HCV treatment regimens.", "C": "Hepatitis B coinfection status is not one of the two classic determining factors for HCV treatment selection.", "D": "Blood type has no bearing on HCV treatment decisions."}}}, {"id": "anking-antimicrobials-017", "fuente": "anking", "tema": 4, "anki": "1461797573387", "q": "All patients with virologic evidence of chronic HCV infection should be considered for treatment except those with which condition?", "o": {"A": "Limited life expectancy", "B": "Mild elevation in liver enzymes", "C": "Genotype 1 infection", "D": "History of prior interferon therapy"}, "r": "A", "e": {"correcta": "Treatment is not recommended for patients with limited life expectancy due to non-liver-related comorbid conditions, since the benefits of curing HCV would not be realized.", "incorrectas": {"B": "Mild liver enzyme elevation alone is not a contraindication to considering HCV treatment.", "C": "Genotype 1 is a common and treatable genotype, not an exclusion criterion.", "D": "Prior interferon therapy does not exclude a patient from being considered for current HCV treatment regimens."}}}, {"id": "anking-antimicrobials-018", "fuente": "anking", "tema": 4, "anki": "1461797583285", "q": "What is the term for the inability to detect HCV RNA by PCR for 6 months after stopping treatment, which is the goal of HCV therapy?", "o": {"A": "Sustained virologic response (SVR)", "B": "Complete remission", "C": "Seroconversion", "D": "Functional cure"}, "r": "A", "e": {"correcta": "Sustained virologic response (SVR) is defined as undetectable HCV RNA by PCR 6 months (or per newer definitions, 12 weeks) after completing treatment, and is considered a virologic cure.", "incorrectas": {"B": "\"Complete remission\" is a term more commonly used in oncology, not the standard HCV treatment outcome term.", "C": "Seroconversion refers to the development of antibodies, not the endpoint used to define HCV treatment success.", "D": "\"Functional cure\" is a term more associated with hepatitis B or HIV management, not the specific defined HCV treatment endpoint."}}}, {"id": "anking-endocrine-pathology-019", "fuente": "anking", "tema": 5, "anki": "1461878049146", "q": "A child presents with failure to grow, short stature, mild obesity, and delayed puberty. Which hormone deficiency is most likely responsible?", "o": {"A": "Growth hormone deficiency", "B": "Thyroid hormone deficiency", "C": "Cortisol deficiency", "D": "Insulin deficiency"}, "r": "A", "e": {"correcta": "Growth hormone deficiency in childhood classically presents with short stature, failure to grow, mild obesity, and delayed puberty due to inadequate GH-driven growth and metabolic effects.", "incorrectas": {"B": "Thyroid hormone deficiency (cretinism) causes mental retardation and developmental delay, not this classic growth pattern.", "C": "Cortisol deficiency presents with fatigue, hypotension, and hyperpigmentation (if primary), not this growth phenotype.", "D": "Insulin deficiency causes hyperglycemia and diabetic symptoms, not short stature with delayed puberty."}}}, {"id": "anking-endocrine-pathology-020", "fuente": "anking", "tema": 5, "anki": "1461878103457", "q": "Excess growth hormone in adults is most often caused by which of the following?", "o": {"A": "A growth hormone-secreting pituitary adenoma", "B": "A thyroid-stimulating hormone-secreting adenoma", "C": "An adrenal cortical adenoma", "D": "A prolactin-secreting adenoma"}, "r": "A", "e": {"correcta": "Acromegaly (excess GH in adults) is most often caused by a GH-secreting pituitary adenoma, typically a somatotroph adenoma.", "incorrectas": {"B": "A TSH-secreting adenoma causes secondary hyperthyroidism, not GH excess.", "C": "Adrenal cortical adenomas cause Cushing syndrome or hyperaldosteronism, not GH excess.", "D": "Prolactin-secreting adenomas cause galactorrhea/amenorrhea, not GH excess (though mixed tumors exist, isolated GH excess is due to somatotroph adenomas)."}}}, {"id": "anking-endocrine-pathology-021", "fuente": "anking", "tema": 5, "anki": "1461878128995", "q": "When excess growth hormone occurs after the epiphyseal growth plates have closed (i.e., after puberty), what condition results, causing increased periosteal bone growth, organ enlargement, glucose intolerance, and coarsened facial features?", "o": {"A": "Acromegaly", "B": "Gigantism", "C": "Cushing syndrome", "D": "Hyperthyroidism"}, "r": "A", "e": {"correcta": "When GH excess occurs after puberty (closed growth plates), it causes acromegaly, characterized by periosteal (appositional) bone growth, organomegaly, glucose intolerance, and coarse facial features rather than increased height.", "incorrectas": {"B": "Gigantism results from GH excess before puberty, when growth plates are still open, leading to increased linear height.", "C": "Cushing syndrome results from cortisol excess, causing central obesity, striae, and moon facies, not coarsened features from bone growth.", "D": "Hyperthyroidism causes weight loss, tachycardia, and heat intolerance, not coarsened facial features from bone overgrowth."}}}, {"id": "anking-endocrine-pathology-022", "fuente": "anking", "tema": 5, "anki": "1461978083695", "q": "Which ADH-related disorder is characterized by low circulating ADH levels resulting in large volumes of dilute urine?", "o": {"A": "Central diabetes insipidus", "B": "Nephrogenic diabetes insipidus", "C": "Syndrome of inappropriate ADH secretion (SIADH)", "D": "Primary polydipsia"}, "r": "A", "e": {"correcta": "Central diabetes insipidus results from decreased ADH secretion by the posterior pituitary, leading to decreased water reabsorption, large volumes of dilute urine, and increased serum osmolarity/Na+.", "incorrectas": {"B": "Nephrogenic diabetes insipidus has high, not low, ADH levels, with renal resistance to its action.", "C": "SIADH is characterized by excess, not deficient, ADH secretion, leading to concentrated urine and hyponatremia.", "D": "Primary polydipsia results from excessive water intake with appropriately suppressed ADH, not a primary ADH deficiency."}}}, {"id": "anking-endocrine-pathology-023", "fuente": "anking", "tema": 5, "anki": "1461978108106", "q": "Which type of diabetes insipidus results from an inability of the posterior pituitary to secrete adequate ADH?", "o": {"A": "Central diabetes insipidus", "B": "Nephrogenic diabetes insipidus", "C": "Gestational diabetes insipidus", "D": "Dipsogenic diabetes insipidus"}, "r": "A", "e": {"correcta": "Central diabetes insipidus arises from a deficiency of ADH secretion from the posterior pituitary (or hypothalamic damage), causing impaired water reabsorption.", "incorrectas": {"B": "Nephrogenic DI is due to renal resistance to ADH, with ADH secretion intact or elevated.", "C": "Gestational DI is caused by placental vasopressinase degrading ADH, not a pituitary secretion defect.", "D": "Dipsogenic DI (primary polydipsia) is due to excessive thirst/fluid intake, not impaired ADH secretion."}}}, {"id": "anking-endocrine-pathology-024", "fuente": "anking", "tema": 5, "anki": "1461978112272", "q": "Which type of diabetes insipidus is characterized by renal unresponsiveness to ADH despite its secretion by the posterior pituitary?", "o": {"A": "Nephrogenic diabetes insipidus", "B": "Central diabetes insipidus", "C": "SIADH", "D": "Diabetes mellitus type 1"}, "r": "A", "e": {"correcta": "Nephrogenic diabetes insipidus is caused by collecting duct resistance to ADH, so despite normal or elevated ADH levels, the kidney cannot concentrate urine appropriately.", "incorrectas": {"B": "Central DI is due to inadequate ADH secretion from the pituitary, not renal resistance.", "C": "SIADH involves excess ADH action with concentrated urine, the opposite clinical picture.", "D": "Diabetes mellitus type 1 is due to insulin deficiency and hyperglycemia, unrelated to ADH signaling."}}}, {"id": "anking-endocrine-pathology-025", "fuente": "anking", "tema": 5, "anki": "1461978118121", "q": "Which type of diabetes insipidus is associated with elevated circulating ADH levels (due to compensatory stimulation by increased serum osmolarity)?", "o": {"A": "Nephrogenic diabetes insipidus", "B": "Central diabetes insipidus", "C": "SIADH", "D": "Cerebral salt wasting"}, "r": "A", "e": {"correcta": "In nephrogenic diabetes insipidus, renal resistance to ADH leads to persistent water loss and increased serum osmolarity, which stimulates further ADH secretion, so ADH levels are elevated.", "incorrectas": {"B": "Central DI has low ADH levels because the defect is in pituitary secretion itself.", "C": "SIADH has elevated ADH but with concentrated urine and hyponatremia, a different mechanism and presentation.", "D": "Cerebral salt wasting causes hyponatremia via renal sodium loss, not primarily an ADH resistance disorder."}}}, {"id": "anking-endocrine-pathology-026", "fuente": "anking", "tema": 5, "anki": "1461978145086", "q": "Nephrogenic diabetes insipidus is treated with which class of diuretics, which paradoxically decreases urine output?", "o": {"A": "Thiazide diuretics", "B": "Loop diuretics", "C": "Potassium-sparing diuretics", "D": "Carbonic anhydrase inhibitors"}, "r": "A", "e": {"correcta": "Thiazide diuretics are used to treat nephrogenic DI; they cause mild volume depletion that increases proximal Na+ and water reabsorption, paradoxically decreasing urine output.", "incorrectas": {"B": "Loop diuretics impair the countercurrent multiplier and would worsen the kidney's diluting/concentrating problems in DI.", "C": "Potassium-sparing diuretics are not the mainstay treatment for nephrogenic DI.", "D": "Carbonic anhydrase inhibitors are used for conditions like glaucoma or altitude sickness, not nephrogenic DI."}}}, {"id": "anking-endocrine-pathology-027", "fuente": "anking", "tema": 5, "anki": "1461978156443", "q": "In which syndrome is excess ADH secreted from an autonomous, ectopic source, such as a small cell lung carcinoma?", "o": {"A": "Syndrome of inappropriate ADH secretion (SIADH)", "B": "Central diabetes insipidus", "C": "Nephrogenic diabetes insipidus", "D": "Cushing syndrome"}, "r": "A", "e": {"correcta": "SIADH occurs when ADH is secreted autonomously from an ectopic or abnormal source, classically small cell carcinoma of the lung, leading to water retention and hyponatremia.", "incorrectas": {"B": "Central DI involves ADH deficiency, the opposite of SIADH.", "C": "Nephrogenic DI involves renal resistance to ADH, not autonomous ADH oversecretion.", "D": "Cushing syndrome involves excess cortisol, not ADH, though ectopic ACTH can also occur with small cell lung cancer separately."}}}, {"id": "anking-endocrine-pathology-028", "fuente": "anking", "tema": 5, "anki": "1461978165029", "q": "Which ADH disorder is characterized by high circulating ADH levels causing inappropriately concentrated urine, diluted body fluids, and hyponatremia?", "o": {"A": "Syndrome of inappropriate ADH (SIADH)", "B": "Central diabetes insipidus", "C": "Nephrogenic diabetes insipidus", "D": "Primary hyperaldosteronism"}, "r": "A", "e": {"correcta": "SIADH features high ADH levels causing excess water reabsorption, concentrated urine, diluted body fluids, and hyponatremia.", "incorrectas": {"B": "Central DI produces dilute urine and hypernatremia from ADH deficiency, the opposite picture.", "C": "Nephrogenic DI also produces dilute urine due to renal ADH resistance, not concentrated urine.", "D": "Primary hyperaldosteronism causes hypertension and hypokalemia via aldosterone excess, not an ADH-mediated water problem."}}}, {"id": "anking-endocrine-pathology-029", "fuente": "anking", "tema": 5, "anki": "1461978191219", "q": "Which endocrine pathology is treated with demeclocycline, which acts as an ADH antagonist at the collecting duct?", "o": {"A": "SIADH", "B": "Central diabetes insipidus", "C": "Nephrogenic diabetes insipidus", "D": "Hyperaldosteronism"}, "r": "A", "e": {"correcta": "Demeclocycline induces a state of nephrogenic diabetes insipidus by antagonizing ADH action at the renal collecting duct, making it useful to treat the water retention of SIADH.", "incorrectas": {"B": "Central DI already has deficient ADH action; giving an ADH antagonist would worsen it.", "C": "Nephrogenic DI already involves ADH resistance, so an ADH antagonist would not be therapeutic.", "D": "Hyperaldosteronism is treated with aldosterone antagonists like spironolactone, not demeclocycline."}}}, {"id": "anking-endocrine-pathology-030", "fuente": "anking", "tema": 5, "anki": "1462038674313", "q": "Excess thyroid hormone can lead to which cardiac complication due to increased metabolic demand and cardiac output?", "o": {"A": "High-output heart failure", "B": "Low-output heart failure", "C": "Restrictive cardiomyopathy", "D": "Constrictive pericarditis"}, "r": "A", "e": {"correcta": "Excess thyroid hormone increases metabolic rate and peripheral oxygen demand, driving a compensatory increase in cardiac output that can progress to high-output heart failure.", "incorrectas": {"B": "Low-output heart failure is typically due to reduced contractility or ischemic damage, not thyrotoxicosis.", "C": "Restrictive cardiomyopathy is usually due to infiltrative diseases like amyloidosis, unrelated to thyroid hormone excess.", "D": "Constrictive pericarditis results from pericardial scarring/calcification, not thyroid hormone excess."}}}, {"id": "anking-endocrine-pathology-031", "fuente": "anking", "tema": 5, "anki": "1462038745473", "q": "In thyroid hormone deficiency, how does bone age compare to chronologic age?", "o": {"A": "Bone age is less than chronologic age", "B": "Bone age is greater than chronologic age", "C": "Bone age equals chronologic age", "D": "Bone age cannot be assessed"}, "r": "A", "e": {"correcta": "Thyroid hormone is required for normal bone maturation, so in hypothyroidism, bone age lags behind chronologic age.", "incorrectas": {"B": "Advanced bone age relative to chronologic age is more typical of conditions with excess growth-promoting hormones or precocious puberty, not hypothyroidism.", "C": "Bone age does not equal chronologic age in hypothyroidism because maturation is delayed.", "D": "Bone age is readily assessed radiographically and is a standard clinical measure in hypothyroidism."}}}, {"id": "anking-endocrine-pathology-032", "fuente": "anking", "tema": 5, "anki": "1462038777530", "q": "Hypothyroidism occurring in the perinatal period, if untreated, causes what irreversible outcome?", "o": {"A": "Mental retardation (cretinism)", "B": "Precocious puberty", "C": "Gigantism", "D": "Adrenal insufficiency"}, "r": "A", "e": {"correcta": "Perinatal hypothyroidism causes irreversible mental retardation (cretinism) if not treated promptly, which is why neonatal thyroid screening is mandatory.", "incorrectas": {"B": "Precocious puberty is not a consequence of perinatal hypothyroidism.", "C": "Gigantism results from GH excess before puberty, unrelated to thyroid hormone deficiency.", "D": "Adrenal insufficiency is a distinct endocrine disorder not caused by perinatal hypothyroidism."}}}, {"id": "anking-endocrine-pathology-033", "fuente": "anking", "tema": 5, "anki": "1462038801103", "q": "In adulthood, which thyroid disorder presents with listlessness, slowed speech, somnolence, impaired memory, and decreased mental capacity?", "o": {"A": "Hypothyroidism", "B": "Hyperthyroidism", "C": "Hyperparathyroidism", "D": "Hypoparathyroidism"}, "r": "A", "e": {"correcta": "Adult hypothyroidism slows metabolism throughout the body, producing listlessness, slowed speech, somnolence, and impaired cognition.", "incorrectas": {"B": "Hyperthyroidism causes hyperexcitability, hyperreflexia, and irritability, the opposite presentation.", "C": "Hyperparathyroidism causes hypercalcemia symptoms (bones, stones, groans, psychiatric overtones) rather than this specific hypothyroid picture.", "D": "Hypoparathyroidism causes hypocalcemia symptoms like tetany and paresthesias, not this cognitive slowing picture."}}}, {"id": "anking-endocrine-pathology-034", "fuente": "anking", "tema": 5, "anki": "1462038815493", "q": "Which thyroid disorder causes hyperexcitability, hyperreflexia, and irritability in adults?", "o": {"A": "Hyperthyroidism", "B": "Hypothyroidism", "C": "Hypoparathyroidism", "D": "Adrenal insufficiency"}, "r": "A", "e": {"correcta": "Hyperthyroidism increases the metabolic and sympathetic tone of tissues, producing hyperexcitability, hyperreflexia, and irritability.", "incorrectas": {"B": "Hypothyroidism causes listlessness and slowed mentation, the opposite of hyperexcitability.", "C": "Hypoparathyroidism causes hypocalcemic tetany and neuromuscular irritability but is not classically described this way in relation to thyroid status.", "D": "Adrenal insufficiency causes fatigue and hypotension, not hyperexcitability."}}}, {"id": "anking-endocrine-pathology-035", "fuente": "anking", "tema": 5, "anki": "1462038872057", "q": "What is the most common cause of hyperthyroidism?", "o": {"A": "Graves disease", "B": "Toxic multinodular goiter", "C": "Subacute (de Quervain) thyroiditis", "D": "Pituitary TSH-secreting adenoma"}, "r": "A", "e": {"correcta": "Graves disease, an autoimmune condition with TSH receptor-stimulating antibodies, is the most common cause of hyperthyroidism.", "incorrectas": {"B": "Toxic multinodular goiter is a cause of hyperthyroidism but is less common than Graves disease.", "C": "Subacute thyroiditis typically causes transient hyperthyroidism followed by hypothyroidism and is less common than Graves disease as an overall cause.", "D": "TSH-secreting pituitary adenomas are a rare cause of hyperthyroidism."}}}, {"id": "anking-endocrine-pathology-036", "fuente": "anking", "tema": 5, "anki": "1462038885820", "q": "What are the TSH levels in hyperthyroidism due to Graves disease or a thyroid neoplasm, and why?", "o": {"A": "Decreased, due to negative feedback from increased free T3/T4", "B": "Increased, due to loss of negative feedback", "C": "Normal, because the pituitary is unaffected", "D": "Increased, due to a TSH-secreting pituitary tumor driving the process"}, "r": "A", "e": {"correcta": "In primary hyperthyroidism (Graves disease or thyroid neoplasm), elevated free thyroid hormone exerts negative feedback on the pituitary, suppressing TSH secretion.", "incorrectas": {"B": "TSH is decreased, not increased, because negative feedback is intact and functioning appropriately in primary hyperthyroidism.", "C": "TSH is measurably decreased, not normal, reflecting appropriate pituitary response to excess thyroid hormone.", "D": "A TSH-secreting pituitary tumor would be a separate, rare cause of secondary hyperthyroidism with elevated (not decreased) TSH, not the mechanism in Graves disease or thyroid neoplasm."}}}, {"id": "anking-hematology-oncology-pathology-037", "fuente": "anking", "tema": 6, "anki": "1463279905770", "q": "A pregnant patient presents with HELLP syndrome. Which finding is characteristic on peripheral blood smear?", "o": {"A": "Schistocytes", "B": "Target cells", "C": "Howell-Jolly bodies", "D": "Heinz bodies"}, "r": "A", "e": {"correcta": "HELLP syndrome (Hemolysis, Elevated Liver enzymes, Low Platelets) causes microangiopathic hemolytic anemia due to thrombotic microangiopathy, producing schistocytes (fragmented RBCs) as blood cells are sheared passing through fibrin strands in damaged small vessels.", "incorrectas": {"A": "", "B": "Target cells are seen in liver disease, thalassemia, and hemoglobinopathies, not thrombotic microangiopathy.", "C": "Howell-Jolly bodies indicate asplenia/hyposplenism, unrelated to HELLP syndrome.", "D": "Heinz bodies are seen in G6PD deficiency and oxidative hemolysis, not HELLP syndrome."}}}, {"id": "anking-hematology-oncology-pathology-038", "fuente": "anking", "tema": 6, "anki": "1473385315636", "q": "In polycythemia, what are the typical changes in SaO2, O2 content, and PaO2?", "o": {"A": "Normal SaO2 / increased O2 content / normal PaO2", "B": "Decreased SaO2 / decreased O2 content / decreased PaO2", "C": "Increased SaO2 / normal O2 content / increased PaO2", "D": "Normal SaO2 / decreased O2 content / normal PaO2"}, "r": "A", "e": {"correcta": "In polycythemia (e.g., primary polycythemia vera or appropriate secondary polycythemia), SaO2 and PaO2 remain normal because oxygenation of hemoglobin is unaffected, but total O2 content increases because there is more hemoglobin available to carry oxygen.", "incorrectas": {"B": "Decreased SaO2 and PaO2 would suggest hypoxemia, which is not required for polycythemia and does not describe the typical isolated increase in red cell mass.", "C": "O2 content increases (not stays normal) due to increased hemoglobin mass, and SaO2/PaO2 typically stay normal, not increased.", "D": "O2 content increases rather than decreases because there are more oxygen-carrying red cells."}}}, {"id": "anking-hematology-oncology-pathology-039", "fuente": "anking", "tema": 6, "anki": "1473385319290", "q": "How does hemoglobin concentration change in polycythemia?", "o": {"A": "It increases", "B": "It decreases", "C": "It remains unchanged", "D": "It fluctuates unpredictably"}, "r": "A", "e": {"correcta": "Polycythemia is defined by an increase in red blood cell mass, which directly raises hemoglobin concentration and hematocrit.", "incorrectas": {"B": "A decrease in hemoglobin would indicate anemia, the opposite of polycythemia.", "C": "By definition, polycythemia involves a change (increase), not a stable hemoglobin level.", "D": "Polycythemia produces a consistent increase in hemoglobin, not unpredictable fluctuation."}}}, {"id": "anking-hematology-oncology-pathology-040", "fuente": "anking", "tema": 6, "anki": "1473466761107", "q": "Chronic hypoxia from living at high altitude increases synthesis of which hormone, leading to polycythemia?", "o": {"A": "Erythropoietin", "B": "Thrombopoietin", "C": "Angiotensin II", "D": "Aldosterone"}, "r": "A", "e": {"correcta": "Chronic hypoxia is sensed via HIF-1a, which stimulates renal peritubular interstitial fibroblasts to secrete erythropoietin (EPO). EPO increases hematocrit and hemoglobin to improve O2 transport, though it also increases blood viscosity.", "incorrectas": {"B": "Thrombopoietin stimulates platelet production, not red blood cell production.", "C": "Angiotensin II regulates blood pressure and aldosterone release, not erythropoiesis.", "D": "Aldosterone regulates sodium and water balance, not red blood cell production."}}}, {"id": "anking-hematology-oncology-pathology-041", "fuente": "anking", "tema": 6, "anki": "1473986126890", "q": "Disorders of primary hemostasis are classically divided into which two categories?", "o": {"A": "Qualitative and quantitative disorders", "B": "Congenital and acquired disorders", "C": "Intrinsic and extrinsic pathway disorders", "D": "Arterial and venous disorders"}, "r": "A", "e": {"correcta": "Primary hemostasis disorders are divided into qualitative disorders (platelets are normal in number but dysfunctional) and quantitative disorders (abnormal platelet numbers, i.e., thrombocytopenia).", "incorrectas": {"B": "Congenital vs. acquired is a valid distinction for many diseases but is not the primary classification scheme used for primary hemostasis disorders.", "C": "Intrinsic/extrinsic pathways refer to the coagulation cascade (secondary hemostasis), not primary hemostasis.", "D": "Arterial vs. venous classification applies to thrombosis location, not primary hemostasis disorders."}}}, {"id": "anking-hematology-oncology-pathology-042", "fuente": "anking", "tema": 6, "anki": "1473986130048", "q": "Disorders of primary hemostasis characteristically present with which type of symptoms?", "o": {"A": "Mucosal and skin bleeding", "B": "Deep muscle hematomas", "C": "Hemarthroses", "D": "Delayed rebleeding after trauma"}, "r": "A", "e": {"correcta": "Primary hemostasis (platelet plug formation) disorders classically cause mucosal and skin bleeding, such as epistaxis, gum bleeding, petechiae, and easy bruising.", "incorrectas": {"B": "Deep muscle hematomas are more characteristic of secondary hemostasis (coagulation factor) disorders like hemophilia.", "C": "Hemarthroses (joint bleeding) are classic for coagulation factor deficiencies (e.g., hemophilia A/B), not primary hemostasis disorders.", "D": "Delayed rebleeding after trauma is typical of coagulation cascade defects, not platelet disorders."}}}, {"id": "anking-hematology-oncology-pathology-043", "fuente": "anking", "tema": 6, "anki": "1473986132369", "q": "What is the most common overall symptom of mucosal bleeding in primary hemostasis disorders?", "o": {"A": "Epistaxis", "B": "Hemoptysis", "C": "Hematuria", "D": "Menorrhagia"}, "r": "A", "e": {"correcta": "Epistaxis (nosebleed) is the most common overall symptom of mucosal bleeding in primary hemostasis disorders, though hemoptysis, GI bleeding, hematuria, and menorrhagia can also occur.", "incorrectas": {"B": "Hemoptysis is a recognized mucosal bleeding symptom but is not the most common one overall.", "C": "Hematuria can occur in primary hemostasis disorders but is less common than epistaxis.", "D": "Menorrhagia is a recognized symptom in affected women but is not the most common overall symptom across the general population."}}}, {"id": "anking-hematology-oncology-pathology-044", "fuente": "anking", "tema": 6, "anki": "1473986139292", "q": "What is a feared complication of severe thrombocytopenia?", "o": {"A": "Intracranial bleeding", "B": "Deep vein thrombosis", "C": "Pulmonary embolism", "D": "Ischemic stroke"}, "r": "A", "e": {"correcta": "Severe thrombocytopenia can lead to spontaneous intracranial hemorrhage, a life-threatening complication that is the most feared consequence of very low platelet counts.", "incorrectas": {"B": "Deep vein thrombosis is a clotting disorder, the opposite problem from thrombocytopenia-related bleeding.", "C": "Pulmonary embolism results from thrombus formation, not from a bleeding tendency due to low platelets.", "D": "Ischemic stroke results from vascular occlusion, not from the bleeding tendency seen in thrombocytopenia."}}}, {"id": "anking-hematology-oncology-pathology-045", "fuente": "anking", "tema": 6, "anki": "1473986144525", "q": "Quantitative disorders of primary hemostasis (thrombocytopenia) present with which small (1-2 mm) skin bleeding finding?", "o": {"A": "Petechiae", "B": "Purpura", "C": "Ecchymoses", "D": "Hematoma"}, "r": "A", "e": {"correcta": "Petechiae are 1-2 mm pinpoint hemorrhages that are a hallmark sign of thrombocytopenia (a quantitative platelet disorder); they are not typically seen in qualitative platelet disorders.", "incorrectas": {"B": "Purpura refers to larger skin bleeding (>3 mm), not the 1-2 mm lesions described.", "C": "Ecchymoses are larger bruises (>1 cm), much bigger than petechiae.", "D": "A hematoma is a larger, palpable collection of blood, not a 1-2 mm lesion."}}}, {"id": "anking-hematology-oncology-pathology-046", "fuente": "anking", "tema": 6, "anki": "1473986157280", "q": "What term describes skin bleeding lesions greater than 3 mm seen in primary hemostasis disorders?", "o": {"A": "Purpura", "B": "Petechiae", "C": "Ecchymoses", "D": "Telangiectasia"}, "r": "A", "e": {"correcta": "Purpura refers to skin hemorrhages greater than 3 mm in size, intermediate between petechiae (1-2 mm) and ecchymoses (>1 cm).", "incorrectas": {"B": "Petechiae are smaller (1-2 mm), not the >3 mm lesions described.", "C": "Ecchymoses are larger still, typically greater than 1 cm.", "D": "Telangiectasias are dilated superficial blood vessels, not hemorrhagic skin lesions from platelet disorders."}}}, {"id": "anking-hematology-oncology-pathology-047", "fuente": "anking", "tema": 6, "anki": "1473986160718", "q": "What term describes skin bleeding lesions greater than 1 cm in primary hemostasis disorders?", "o": {"A": "Ecchymoses", "B": "Petechiae", "C": "Purpura", "D": "Spider angiomata"}, "r": "A", "e": {"correcta": "Ecchymoses are larger bruises, greater than 1 cm in size, representing the largest category of skin hemorrhage in this size-based classification.", "incorrectas": {"B": "Petechiae are the smallest lesions (1-2 mm), not >1 cm.", "C": "Purpura describes intermediate-sized lesions (>3 mm), smaller than ecchymoses.", "D": "Spider angiomata are vascular lesions associated with liver disease/hyperestrogenism, not hemostasis disorders."}}}, {"id": "anking-hematology-oncology-pathology-048", "fuente": "anking", "tema": 6, "anki": "1473986163852", "q": "Disorders of primary hemostasis present with which easily-occurring skin finding?", "o": {"A": "Easy bruising", "B": "Hyperpigmentation", "C": "Urticaria", "D": "Jaundice"}, "r": "A", "e": {"correcta": "Easy bruising is a classic skin manifestation of primary hemostasis disorders, reflecting impaired platelet plug formation that allows minor trauma to cause visible hemorrhage.", "incorrectas": {"B": "Hyperpigmentation is not a typical feature of primary hemostasis disorders.", "C": "Urticaria (hives) is an allergic skin reaction, unrelated to platelet function.", "D": "Jaundice reflects hyperbilirubinemia (e.g., from hemolysis or liver disease), not a bleeding disorder finding."}}}, {"id": "anking-hematology-oncology-pathology-049", "fuente": "anking", "tema": 6, "anki": "1473986166644", "q": "Petechiae are a sign of thrombocytopenia and are typically NOT seen in which category of platelet disorders?", "o": {"A": "Qualitative platelet disorders", "B": "Quantitative platelet disorders", "C": "Coagulation factor disorders", "D": "Vitamin K deficiency"}, "r": "A", "e": {"correcta": "Petechiae specifically indicate thrombocytopenia (a quantitative disorder); qualitative platelet disorders (normal platelet count but abnormal function) do not typically cause petechiae.", "incorrectas": {"B": "Quantitative disorders (thrombocytopenia) are precisely the category that DOES cause petechiae.", "C": "Coagulation factor disorders (secondary hemostasis) more typically cause deep bleeding like hemarthrosis rather than petechiae specifically.", "D": "Vitamin K deficiency affects coagulation factors (secondary hemostasis), a distinct category from the qualitative/quantitative platelet distinction being tested."}}}, {"id": "anking-hematology-oncology-pathology-050", "fuente": "anking", "tema": 6, "anki": "1473986169357", "q": "Below what platelet count does thrombocytopenia typically become symptomatic?", "o": {"A": "50,000/uL", "B": "150,000/uL", "C": "10,000/uL", "D": "100,000/uL"}, "r": "A", "e": {"correcta": "Symptoms of thrombocytopenia (such as petechiae and easy bruising) typically begin to appear when the platelet count falls below approximately 50,000/uL.", "incorrectas": {"B": "150,000/uL is near the lower limit of the normal platelet range and is not the symptomatic threshold.", "C": "10,000/uL is a much lower threshold associated with risk of spontaneous severe/life-threatening bleeding, not the general onset of symptoms.", "D": "100,000/uL is above the level at which symptoms classically begin to appear."}}}, {"id": "anking-hematology-oncology-pathology-051", "fuente": "anking", "tema": 6, "anki": "1473986182575", "q": "What is the most common cause of thrombocytopenia in both children and adults?", "o": {"A": "Immune thrombocytopenic purpura", "B": "Disseminated intravascular coagulation", "C": "Thrombotic thrombocytopenic purpura", "D": "Heparin-induced thrombocytopenia"}, "r": "A", "e": {"correcta": "Immune thrombocytopenic purpura (ITP) is the most common cause of thrombocytopenia in both children and adults, resulting from autoantibody-mediated platelet destruction.", "incorrectas": {"B": "DIC is a less common, typically acute and critically ill-associated cause of thrombocytopenia, not the most common overall cause.", "C": "TTP is a rare cause of thrombocytopenia involving microangiopathic hemolysis, much less common than ITP.", "D": "Heparin-induced thrombocytopenia occurs only in the specific context of heparin exposure, making it far less common overall than ITP."}}}, {"id": "anking-hematology-oncology-pathology-052", "fuente": "anking", "tema": 6, "anki": "1473986200310", "q": "In ITP, antibody-bound platelets are consumed by which cells, resulting in thrombocytopenia?", "o": {"A": "Splenic macrophages", "B": "Kupffer cells", "C": "Neutrophils", "D": "Renal mesangial cells"}, "r": "A", "e": {"correcta": "In ITP, platelets coated with autoantibodies (typically IgG against platelet glycoproteins) are recognized and phagocytosed by splenic macrophages, leading to accelerated platelet destruction and thrombocytopenia.", "incorrectas": {"B": "Kupffer cells are hepatic macrophages; the spleen is the primary and classically tested site of antibody-coated platelet clearance in ITP.", "C": "Neutrophils are not the primary phagocytic cells responsible for antibody-coated platelet clearance in ITP.", "D": "Renal mesangial cells are involved in glomerular immune complex clearance, not platelet destruction."}}}, {"id": "anking-hematology-oncology-pathology-053", "fuente": "anking", "tema": 6, "anki": "1473986202821", "q": "Immune thrombocytopenic purpura commonly follows what type of preceding infection?", "o": {"A": "Viral infection", "B": "Bacterial infection", "C": "Fungal infection", "D": "Parasitic infection"}, "r": "A", "e": {"correcta": "ITP, especially in children, commonly follows a viral infection, which is thought to trigger the autoimmune antibody response against platelets.", "incorrectas": {"B": "Bacterial infections are not the classic preceding trigger for ITP; viral infections are far more strongly associated.", "C": "Fungal infections are not a recognized common antecedent trigger for ITP.", "D": "Parasitic infections are not the classic preceding trigger for ITP."}}}, {"id": "anking-autonomic-drugs-054", "fuente": "anking", "tema": 7, "anki": "1461615074564", "q": "Histamine released from enterochromaffin-like (ECL) cells acts on which receptor, and to which G-protein is it coupled, on the basolateral membrane of gastric parietal cells?", "o": {"A": "H2 receptor / Gs", "B": "H1 receptor / Gq", "C": "M3 receptor / Gq", "D": "CCK-B receptor / Gq"}, "r": "A", "e": {"correcta": "Histamine acts on H2 receptors coupled to Gs proteins on parietal cells, activating adenylyl cyclase and increasing cAMP, which stimulates the H+/K+ ATPase to increase acid secretion.", "incorrectas": {"B": "H1 receptors are Gq-coupled and mediate allergic/inflammatory responses, not parietal cell acid secretion via this pathway.", "C": "M3 receptors mediate acetylcholine's stimulatory effect on parietal cells but are Gq-coupled, not the histamine receptor described.", "D": "CCK-B (gastrin) receptors are Gq-coupled and respond to gastrin, not histamine."}}}, {"id": "anking-autonomic-drugs-055", "fuente": "anking", "tema": 7, "anki": "1461806819909", "q": "Misoprostol is a synthetic analog of which endogenous compound?", "o": {"A": "PGE1", "B": "PGE2", "C": "Thromboxane A2", "D": "Leukotriene B4"}, "r": "A", "e": {"correcta": "Misoprostol is a synthetic prostaglandin E1 (PGE1) analog used to protect the gastric mucosa and induce labor.", "incorrectas": {"B": "PGE2 is a different prostaglandin involved in labor and fever but is not what misoprostol mimics.", "C": "Thromboxane A2 promotes platelet aggregation and vasoconstriction, unrelated to misoprostol's mechanism.", "D": "Leukotriene B4 is a chemotactic mediator in inflammation, not a prostaglandin analog target of misoprostol."}}}, {"id": "anking-autonomic-drugs-056", "fuente": "anking", "tema": 7, "anki": "1461806838245", "q": "Misoprostol protects the stomach by increasing production/secretion of which barrier and decreasing production of what substance?", "o": {"A": "Increased mucous barrier / decreased acid production", "B": "Increased bicarbonate barrier / decreased pepsin production", "C": "Increased mucous barrier / decreased gastrin production", "D": "Increased surfactant barrier / decreased acid production"}, "r": "A", "e": {"correcta": "Misoprostol increases gastric mucous production and secretion while decreasing gastric acid production, making it useful in preventing NSAID-induced peptic ulcers.", "incorrectas": {"B": "Bicarbonate and pepsin are not the specific barrier/substance pair described for misoprostol's mechanism.", "C": "Misoprostol's acid-reducing effect is on gastric acid, not gastrin secretion directly.", "D": "Surfactant is unrelated to gastric mucosal protection; this is a distractor from pulmonary physiology."}}}, {"id": "anking-autonomic-drugs-057", "fuente": "anking", "tema": 7, "anki": "1461806919056", "q": "Misoprostol promotes what type of contraction, making it useful for which obstetric indication?", "o": {"A": "Uterine contraction / induction of labor (cervical ripening)", "B": "Uterine contraction / prevention of preterm labor", "C": "Vascular smooth muscle contraction / treatment of hypotension", "D": "Bronchial smooth muscle contraction / treatment of asthma"}, "r": "A", "e": {"correcta": "Misoprostol stimulates uterine smooth muscle contraction and ripens the cervix, making it useful for labor induction and management of postpartum hemorrhage.", "incorrectas": {"B": "Misoprostol promotes labor rather than preventing it, the opposite effect.", "C": "It does not act on vascular smooth muscle to treat hypotension; this is an unrelated indication.", "D": "It causes uterine, not bronchial, smooth muscle contraction, and would not treat asthma."}}}, {"id": "anking-autonomic-drugs-058", "fuente": "anking", "tema": 7, "anki": "1461806938449", "q": "Misoprostol is contraindicated in which population due to what type of effect?", "o": {"A": "Women of childbearing potential / abortifacient effects", "B": "Elderly patients / nephrotoxic effects", "C": "Children / hepatotoxic effects", "D": "Men with peptic ulcers / androgenic effects"}, "r": "A", "e": {"correcta": "Because misoprostol can induce uterine contractions and cervical ripening, it has abortifacient potential and is contraindicated in women who could be pregnant.", "incorrectas": {"B": "Misoprostol is not primarily known for nephrotoxicity in the elderly.", "C": "Hepatotoxicity in children is not the described contraindication for misoprostol.", "D": "Misoprostol has no androgenic effects; this option is fabricated for this context."}}}, {"id": "anking-autonomic-drugs-059", "fuente": "anking", "tema": 7, "anki": "1461806954057", "q": "Misoprostol use is limited in practice mainly due to which common side effect?", "o": {"A": "Diarrhea", "B": "Constipation", "C": "Hepatotoxicity", "D": "Agranulocytosis"}, "r": "A", "e": {"correcta": "Diarrhea is a common and often limiting side effect of misoprostol due to its prostaglandin-mediated effects on GI motility.", "incorrectas": {"B": "Misoprostol causes increased GI motility and diarrhea, not constipation.", "C": "Hepatotoxicity is not a characteristic side effect of misoprostol.", "D": "Agranulocytosis is associated with other drugs (e.g., clozapine), not misoprostol."}}}, {"id": "anking-autonomic-drugs-060", "fuente": "anking", "tema": 7, "anki": "1461884871184", "q": "ADH acts on principal cells of the late distal tubule and collecting duct via which receptor?", "o": {"A": "V2 receptor", "B": "V1 receptor", "C": "Oxytocin receptor", "D": "Angiotensin II type 1 receptor"}, "r": "A", "e": {"correcta": "ADH (vasopressin) binds V2 receptors on renal principal cells, promoting water reabsorption via aquaporin-2 channel insertion.", "incorrectas": {"B": "V1 receptors are located on vascular smooth muscle, not renal principal cells.", "C": "Oxytocin receptors mediate uterine contraction and milk ejection, unrelated to renal water handling.", "D": "AT1 receptors respond to angiotensin II and mediate vasoconstriction/aldosterone release, not ADH's renal action."}}}, {"id": "anking-autonomic-drugs-061", "fuente": "anking", "tema": 7, "anki": "1461884917022", "q": "Which second messenger propagates signaling from the ADH-bound V2 receptor?", "o": {"A": "cAMP", "B": "IP3/Ca2+", "C": "cGMP", "D": "DAG"}, "r": "A", "e": {"correcta": "V2 receptors are Gs-coupled, activating adenylyl cyclase to increase cAMP, which drives aquaporin-2 translocation.", "incorrectas": {"B": "IP3/Ca2+ is the second messenger pathway for V1 receptors (Gq-coupled), not V2.", "C": "cGMP is used in nitric oxide/natriuretic peptide signaling, not V2 receptor signaling.", "D": "DAG is generated alongside IP3 in Gq signaling, which applies to V1, not V2 receptors."}}}, {"id": "anking-autonomic-drugs-062", "fuente": "anking", "tema": 7, "anki": "1461884968628", "q": "The receptor for ADH on vascular smooth muscle is which type?", "o": {"A": "V1 receptor", "B": "V2 receptor", "C": "Alpha-1 receptor", "D": "Beta-2 receptor"}, "r": "A", "e": {"correcta": "ADH acts on V1 receptors located on vascular smooth muscle to cause vasoconstriction.", "incorrectas": {"B": "V2 receptors are found in the renal collecting duct, not vascular smooth muscle.", "C": "Alpha-1 receptors also cause vasoconstriction but are activated by catecholamines, not ADH's primary vascular receptor.", "D": "Beta-2 receptors cause vasodilation and are not the ADH receptor on vascular smooth muscle."}}}, {"id": "anking-autonomic-drugs-063", "fuente": "anking", "tema": 7, "anki": "1461884982922", "q": "Which second messenger(s) propagate signaling from the ADH-bound V1 receptor?", "o": {"A": "IP3/Ca2+", "B": "cAMP", "C": "cGMP", "D": "Arachidonic acid alone"}, "r": "A", "e": {"correcta": "V1 receptors are Gq-coupled, activating phospholipase C to generate IP3 and increase intracellular Ca2+, leading to smooth muscle contraction.", "incorrectas": {"B": "cAMP is the second messenger for V2 receptor signaling (Gs-coupled), not V1.", "C": "cGMP is not part of the Gq/PLC pathway used by V1 receptors.", "D": "Arachidonic acid alone is not the defining second messenger system of V1 receptor signaling."}}}, {"id": "anking-autonomic-drugs-064", "fuente": "anking", "tema": 7, "anki": "1461884987103", "q": "What is the end result of ADH binding to V1 receptors on vascular smooth muscle?", "o": {"A": "Contraction of vascular smooth muscle (vasoconstriction)", "B": "Relaxation of vascular smooth muscle (vasodilation)", "C": "Increased renal water reabsorption", "D": "Decreased total peripheral resistance"}, "r": "A", "e": {"correcta": "V1 receptor activation on vascular smooth muscle leads to contraction, arteriolar constriction, and increased total peripheral resistance.", "incorrectas": {"B": "V1 activation causes contraction, not relaxation, of vascular smooth muscle.", "C": "Increased water reabsorption is the result of V2, not V1, receptor activation.", "D": "V1 activation increases, rather than decreases, total peripheral resistance."}}}, {"id": "anking-autonomic-drugs-065", "fuente": "anking", "tema": 7, "anki": "1461885006895", "q": "Which receptor does ADH (vasopressin) bind to regulate serum osmolarity?", "o": {"A": "V2 receptors", "B": "V1 receptors", "C": "Oxytocin receptors", "D": "Aldosterone receptors"}, "r": "A", "e": {"correcta": "ADH regulates serum osmolarity primarily through V2 receptors in the renal collecting duct, promoting free water reabsorption.", "incorrectas": {"B": "V1 receptors regulate vascular tone and blood pressure, not primarily osmolarity.", "C": "Oxytocin receptors are unrelated to osmolarity regulation.", "D": "Aldosterone acts on mineralocorticoid receptors to regulate sodium/potassium, not via ADH's osmolarity-regulating receptor."}}}, {"id": "anking-autonomic-drugs-066", "fuente": "anking", "tema": 7, "anki": "1463844488060", "q": "The ADH-activated V1 receptor is coupled to which G-protein?", "o": {"A": "Gq", "B": "Gs", "C": "Gi", "D": "G12/13"}, "r": "A", "e": {"correcta": "V1 receptors are coupled to Gq, which activates phospholipase C to increase IP3/Ca2+, causing vascular smooth muscle contraction.", "incorrectas": {"B": "Gs coupling and cAMP generation describe the V2 receptor pathway, not V1.", "C": "Gi coupling inhibits adenylyl cyclase and is not the pathway used by V1 receptors.", "D": "G12/13 mediates Rho-GTPase signaling and is not the classic V1 receptor pathway described in this context."}}}, {"id": "anking-autonomic-drugs-067", "fuente": "anking", "tema": 7, "anki": "1463844501109", "q": "ADH activation of which receptor on vascular smooth muscle causes vasoconstriction and increased blood pressure?", "o": {"A": "V1 receptor", "B": "V2 receptor", "C": "Beta-1 receptor", "D": "Angiotensin II type 2 receptor"}, "r": "A", "e": {"correcta": "V1 receptor activation on vascular smooth muscle mediates vasoconstriction, raising blood pressure.", "incorrectas": {"B": "V2 receptors act on the kidney to increase water reabsorption, not directly causing vasoconstriction.", "C": "Beta-1 receptors increase cardiac contractility and heart rate, not the ADH vasoconstrictor receptor.", "D": "AT2 receptors generally oppose AT1-mediated vasoconstriction and are not ADH receptors."}}}, {"id": "anking-autonomic-drugs-068", "fuente": "anking", "tema": 7, "anki": "1463844507593", "q": "The ADH-activated V2 receptor is coupled to which G-protein?", "o": {"A": "Gs", "B": "Gq", "C": "Gi", "D": "Golf"}, "r": "A", "e": {"correcta": "V2 receptors couple to Gs, activating adenylyl cyclase to increase cAMP, promoting aquaporin-2 insertion into the apical membrane.", "incorrectas": {"B": "Gq coupling with IP3/Ca2+ signaling describes the V1 receptor, not V2.", "C": "Gi inhibits adenylyl cyclase and is not the V2 receptor pathway.", "D": "Golf is specific to olfactory receptor signaling, unrelated to V2 receptors."}}}, {"id": "anking-autonomic-drugs-069", "fuente": "anking", "tema": 7, "anki": "1463844517299", "q": "The V2 receptor for ADH is located on which membrane of the collecting duct principal cell?", "o": {"A": "Basolateral membrane", "B": "Apical membrane", "C": "Luminal brush border", "D": "Tight junction complex"}, "r": "A", "e": {"correcta": "V2 receptors are located on the basolateral membrane, where ADH binds to trigger a cAMP cascade that causes aquaporin-2 channels to translocate to the apical membrane.", "incorrectas": {"B": "Aquaporin-2 channels translocate to the apical membrane, but the V2 receptor itself is on the basolateral membrane.", "C": "The brush border refers to proximal tubule microvilli, not the collecting duct principal cell membrane where V2 resides.", "D": "Tight junctions are cell-cell adhesion structures, not the location of the V2 receptor."}}}, {"id": "anking-autonomic-drugs-070", "fuente": "anking", "tema": 7, "anki": "1463844524624", "q": "ADH-activated V2 receptors cause translocation of which channels to the renal apical membrane, increasing free water reabsorption?", "o": {"A": "Aquaporin 2 channels", "B": "Aquaporin 1 channels", "C": "ENaC sodium channels", "D": "ROMK potassium channels"}, "r": "A", "e": {"correcta": "V2 receptor activation increases cAMP, causing aquaporin-2 channels to translocate to the apical membrane, allowing water reabsorption.", "incorrectas": {"B": "Aquaporin 1 channels are constitutively expressed in the proximal tubule and are not regulated by ADH/V2 signaling.", "C": "ENaC channels mediate sodium reabsorption and are regulated by aldosterone, not directly by ADH's aquaporin effect.", "D": "ROMK channels mediate potassium secretion in the collecting duct and are not the ADH-regulated water channel."}}}, {"id": "anking-autonomic-drugs-071", "fuente": "anking", "tema": 7, "anki": "1463845075159", "q": "Desmopressin (DDAVP) has high specificity for which ADH receptor?", "o": {"A": "V2 receptor", "B": "V1 receptor", "C": "Oxytocin receptor", "D": "Angiotensin II receptor"}, "r": "A", "e": {"correcta": "Desmopressin is a selective V2 receptor agonist, used to treat central diabetes insipidus and nocturnal enuresis by promoting renal water reabsorption.", "incorrectas": {"B": "Desmopressin has minimal V1 activity compared to natural ADH, distinguishing it from vasopressin's vasoconstrictive effects.", "C": "Desmopressin does not target oxytocin receptors; it is selective for vasopressin V2 receptors.", "D": "Angiotensin II receptors are unrelated to desmopressin's mechanism of action."}}}, {"id": "anking-reproductive-system-pathology-072", "fuente": "anking", "tema": 8, "anki": "1462981993876", "q": "Androgen insensitivity syndrome in genotypic males (46,XY) is caused by a deficiency of which receptor in target tissues?", "o": {"A": "Androgen receptors", "B": "Estrogen receptors", "C": "5-alpha-reductase enzyme", "D": "LH receptors"}, "r": "A", "e": {"correcta": "Androgen insensitivity syndrome results from a defective/absent androgen receptor, so target tissues cannot respond to testosterone/DHT despite normal or elevated levels, producing a 46,XY genotype with female external genitalia.", "incorrectas": {"B": "Estrogen receptor deficiency is not the mechanism; these patients actually have unopposed estrogen effects due to lack of androgen action.", "C": "5-alpha-reductase deficiency is a distinct disorder impairing conversion of testosterone to DHT, causing ambiguous genitalia rather than complete receptor unresponsiveness.", "D": "LH receptor defects (e.g., Leydig cell hypoplasia) impair testosterone synthesis itself, not the tissue response to androgens."}}}, {"id": "anking-reproductive-system-pathology-073", "fuente": "anking", "tema": 8, "anki": "1463093900462", "q": "A cystic dilation of the Bartholin gland is known by what name?", "o": {"A": "Bartholin cyst", "B": "Skene gland cyst", "C": "Nabothian cyst", "D": "Gartner duct cyst"}, "r": "A", "e": {"correcta": "A Bartholin cyst is a cystic dilation of the Bartholin gland, often associated with Neisseria gonorrhoeae infection.", "incorrectas": {"B": "Skene gland cysts arise from the periurethral Skene glands, not the Bartholin glands.", "C": "Nabothian cysts are mucus-filled cysts on the cervix, unrelated to the Bartholin gland.", "D": "Gartner duct cysts arise from remnants of the mesonephric (Wolffian) duct along the lateral vaginal wall."}}}, {"id": "anking-reproductive-system-pathology-074", "fuente": "anking", "tema": 8, "anki": "1463093911940", "q": "Which gland, located on each side of the vaginal canal, produces a mucus-like fluid that drains via ducts into the lower vestibule?", "o": {"A": "Bartholin gland", "B": "Skene gland", "C": "Cowper gland", "D": "Adrenal gland"}, "r": "A", "e": {"correcta": "The Bartholin glands are paired glands at the vaginal introitus that secrete mucus-like fluid via ducts into the lower vestibule, aiding lubrication.", "incorrectas": {"B": "Skene glands are periurethral glands, not located adjacent to the vaginal canal.", "C": "Cowper (bulbourethral) glands are male accessory glands, not present in females.", "D": "The adrenal gland is an endocrine gland unrelated to vaginal/vulvar lubrication."}}}, {"id": "anking-reproductive-system-pathology-075", "fuente": "anking", "tema": 8, "anki": "1463093944484", "q": "Bartholin cysts arise due to inflammation and what process affecting the Bartholin gland?", "o": {"A": "Obstruction of the gland duct", "B": "Neoplastic transformation", "C": "Autoimmune destruction", "D": "Ischemic infarction"}, "r": "A", "e": {"correcta": "Bartholin cysts form when inflammation causes obstruction of the gland's duct, leading to accumulation of secretions and cystic dilation.", "incorrectas": {"B": "Neoplastic transformation is not the mechanism of simple Bartholin cyst formation.", "C": "Autoimmune destruction is not implicated in Bartholin cyst pathogenesis.", "D": "Ischemic infarction does not cause the cystic dilation seen in Bartholin cysts."}}}, {"id": "anking-reproductive-system-pathology-076", "fuente": "anking", "tema": 8, "anki": "1463093952878", "q": "Bartholin cysts are most commonly seen in which demographic?", "o": {"A": "Women of reproductive age", "B": "Postmenopausal women", "C": "Prepubertal girls", "D": "Elderly men"}, "r": "A", "e": {"correcta": "Bartholin cysts most commonly occur in women of reproductive age, when the glands are hormonally active.", "incorrectas": {"B": "Postmenopausal women are more classically associated with lichen sclerosus, not Bartholin cysts.", "C": "Prepubertal girls rarely develop Bartholin cysts since the glands are not yet hormonally active.", "D": "Bartholin glands are female structures, so this condition does not occur in men."}}}, {"id": "anking-reproductive-system-pathology-077", "fuente": "anking", "tema": 8, "anki": "1463093959932", "q": "A unilateral, painful cystic lesion at the lower vestibule adjacent to the vaginal canal, which may develop into an abscess, describes what condition?", "o": {"A": "Bartholin cyst", "B": "Vulvar condyloma", "C": "Lichen sclerosus", "D": "Vaginal fibroma"}, "r": "A", "e": {"correcta": "A Bartholin cyst classically presents as a unilateral, painful cystic lesion near the vaginal introitus and can become a Bartholin abscess if infected.", "incorrectas": {"B": "Vulvar condyloma presents as warty, verrucous lesions rather than a cystic mass.", "C": "Lichen sclerosus presents with thinned, whitish, atrophic vulvar skin, not a discrete cystic lesion.", "D": "Vaginal fibroma is a rare benign tumor, not typically presenting as a painful unilateral cyst."}}}, {"id": "anking-reproductive-system-pathology-078", "fuente": "anking", "tema": 8, "anki": "1463093999696", "q": "A warty neoplasm of genital skin, often caused by low-risk HPV strains and often large, is called what?", "o": {"A": "Condyloma", "B": "Melanoma", "C": "Squamous cell carcinoma", "D": "Lipoma"}, "r": "A", "e": {"correcta": "Condyloma (condyloma acuminatum) is a warty outgrowth of genital skin caused by low-risk HPV types, most commonly types 6 and 11.", "incorrectas": {"B": "Melanoma is a pigmented malignant neoplasm of melanocytes, not a warty HPV-related lesion.", "C": "Squamous cell carcinoma is a malignant lesion, typically linked to high-risk HPV types, not the benign warty condyloma.", "D": "Lipoma is a benign fatty tumor unrelated to HPV infection."}}}, {"id": "anking-reproductive-system-pathology-079", "fuente": "anking", "tema": 8, "anki": "1463094017212", "q": "What is the most common cause of condyloma acuminata?", "o": {"A": "HPV types 6 and 11", "B": "HPV types 16 and 18", "C": "HSV-2", "D": "Treponema pallidum"}, "r": "A", "e": {"correcta": "Condyloma acuminata is most commonly caused by low-risk HPV types 6 and 11.", "incorrectas": {"B": "HPV types 16 and 18 are high-risk types associated with cervical and other carcinomas, not typical condyloma.", "C": "HSV-2 causes genital herpes with painful vesicles/ulcers, not warty condylomas.", "D": "Treponema pallidum causes syphilis, whose secondary stage produces condyloma lata, a different flat, moist lesion."}}}, {"id": "anking-reproductive-system-pathology-080", "fuente": "anking", "tema": 8, "anki": "1463094049348", "q": "What are the three areas of the female lower genital tract most commonly affected by HPV?", "o": {"A": "Vulva, vaginal canal, and cervix", "B": "Ovary, fallopian tube, and uterus", "C": "Bladder, urethra, and vulva", "D": "Cervix, endometrium, and myometrium"}, "r": "A", "e": {"correcta": "HPV most commonly affects the lower genital tract structures: the vulva, vaginal canal, and cervix.", "incorrectas": {"B": "The ovary, fallopian tube, and uterus are upper genital tract structures not typically the primary sites of HPV infection.", "C": "The bladder and urethra are not classic sites of HPV-related genital lesions.", "D": "The endometrium and myometrium are uterine layers not typically involved by HPV."}}}, {"id": "anking-reproductive-system-pathology-081", "fuente": "anking", "tema": 8, "anki": "1463094084820", "q": "Histologically, HPV-associated condylomas are characterized by which cellular finding?", "o": {"A": "Koilocytes", "B": "Reed-Sternberg cells", "C": "Psammoma bodies", "D": "Councilman bodies"}, "r": "A", "e": {"correcta": "Koilocytes, squamous cells with raisin-shaped nuclei and perinuclear clearing, are the classic histologic finding in HPV-associated condylomas.", "incorrectas": {"B": "Reed-Sternberg cells are characteristic of Hodgkin lymphoma, not HPV lesions.", "C": "Psammoma bodies are seen in papillary carcinomas (e.g., papillary thyroid, serous ovarian), not condylomas.", "D": "Councilman bodies are apoptotic hepatocytes seen in viral hepatitis and yellow fever."}}}, {"id": "anking-reproductive-system-pathology-082", "fuente": "anking", "tema": 8, "anki": "1463094128418", "q": "How often do condylomas (caused by low-risk HPV types 6/11) progress to carcinoma?", "o": {"A": "Rarely", "B": "Almost always", "C": "In about 50% of cases", "D": "Only in immunocompromised men"}, "r": "A", "e": {"correcta": "Condylomas caused by low-risk HPV types 6 and 11 rarely progress to carcinoma, unlike lesions caused by high-risk HPV types such as 16 and 18.", "incorrectas": {"B": "Malignant progression is uncommon with low-risk HPV types; this is more typical of high-risk types.", "C": "A 50% malignant transformation rate is far higher than what is actually observed with condyloma.", "D": "Progression risk is related to HPV type/immune status broadly, not restricted specifically to immunocompromised men."}}}, {"id": "anking-reproductive-system-pathology-083", "fuente": "anking", "tema": 8, "anki": "1463094144885", "q": "Lichen sclerosus is characterized by thinning of the epidermis and what change in the dermis?", "o": {"A": "Fibrosis (sclerosis)", "B": "Granuloma formation", "C": "Amyloid deposition", "D": "Fatty infiltration"}, "r": "A", "e": {"correcta": "Lichen sclerosus shows epidermal thinning combined with dermal fibrosis (sclerosis), giving the vulvar skin a whitish, parchment-like appearance.", "incorrectas": {"B": "Granuloma formation is not a feature of lichen sclerosus; it is more typical of infections like TB or sarcoidosis.", "C": "Amyloid deposition characterizes amyloidosis, unrelated to lichen sclerosus.", "D": "Fatty infiltration is not a histologic feature of lichen sclerosus."}}}, {"id": "anking-reproductive-system-pathology-084", "fuente": "anking", "tema": 8, "anki": "1463094181362", "q": "Lichen sclerosus is most commonly seen in which demographic?", "o": {"A": "Postmenopausal women", "B": "Prepubertal girls only", "C": "Young reproductive-age men", "D": "Adolescent males"}, "r": "A", "e": {"correcta": "Lichen sclerosus most commonly affects postmenopausal women and may have an autoimmune etiology.", "incorrectas": {"B": "While lichen sclerosus can rarely occur in prepubertal girls, it is not the classic or most common demographic.", "C": "Lichen sclerosus is primarily a vulvar condition seen in women, not typically young men.", "D": "Adolescent males are not the characteristic demographic for this vulvar dermatosis."}}}, {"id": "anking-reproductive-system-pathology-085", "fuente": "anking", "tema": 8, "anki": "1463094190367", "q": "Does lichen sclerosus carry an increased risk of squamous cell carcinoma?", "o": {"A": "Yes, a slightly increased risk", "B": "No increased risk at all", "C": "Yes, a markedly increased risk of over 50%", "D": "It causes basal cell carcinoma instead"}, "r": "A", "e": {"correcta": "Lichen sclerosus is associated with a slightly increased risk of vulvar squamous cell carcinoma, so patients require monitoring.", "incorrectas": {"B": "There is a small but real increased risk, so 'no increased risk' is incorrect.", "C": "The increased risk is only slight, not on the order of 50%.", "D": "Lichen sclerosus is linked to squamous cell carcinoma, not basal cell carcinoma."}}}, {"id": "anking-reproductive-system-pathology-086", "fuente": "anking", "tema": 8, "anki": "1463094195758", "q": "Does lichen simplex chronicus carry an increased risk of squamous cell carcinoma?", "o": {"A": "No", "B": "Yes, markedly increased", "C": "Yes, slightly increased", "D": "Only if HPV co-infection is present"}, "r": "A", "e": {"correcta": "Unlike lichen sclerosus, lichen simplex chronicus does not carry an increased risk of squamous cell carcinoma.", "incorrectas": {"B": "Lichen simplex chronicus is not associated with a markedly increased malignancy risk.", "C": "It is lichen sclerosus, not lichen simplex chronicus, that carries a slightly increased risk.", "D": "HPV co-infection is not a recognized factor linking lichen simplex chronicus to carcinoma."}}}, {"id": "anking-reproductive-system-pathology-087", "fuente": "anking", "tema": 8, "anki": "1463094201489", "q": "Lichen sclerosus and lichen simplex chronicus are both generally what kind of condition?", "o": {"A": "Benign", "B": "Malignant", "C": "Premalignant in all cases", "D": "Infectious"}, "r": "A", "e": {"correcta": "Both lichen sclerosus and lichen simplex chronicus are generally benign vulvar conditions, though lichen sclerosus carries a small malignancy risk.", "incorrectas": {"B": "Neither condition is malignant in itself.", "C": "Only lichen sclerosus carries a small increased malignancy risk; neither is universally premalignant.", "D": "Both are inflammatory/reactive dermatologic conditions, not infectious diseases."}}}, {"id": "anking-reproductive-system-pathology-088", "fuente": "anking", "tema": 8, "anki": "1463094212090", "q": "Hyperplasia of the vulvar squamous epithelium describes which condition?", "o": {"A": "Lichen simplex chronicus", "B": "Lichen sclerosus", "C": "Condyloma acuminatum", "D": "Vulvar intraepithelial neoplasia"}, "r": "A", "e": {"correcta": "Lichen simplex chronicus is characterized by hyperplasia (thickening) of the vulvar squamous epithelium, typically from chronic rubbing or scratching.", "incorrectas": {"B": "Lichen sclerosus features epidermal thinning, the opposite of hyperplasia.", "C": "Condyloma acuminatum is an HPV-induced warty growth, not simple epithelial hyperplasia.", "D": "Vulvar intraepithelial neoplasia is a precancerous dysplastic lesion, not simple hyperplasia."}}}, {"id": "anking-reproductive-system-pathology-089", "fuente": "anking", "tema": 8, "anki": "1463094263813", "q": "Lichen simplex chronicus is associated with chronic irritation/inflammation and what behavior?", "o": {"A": "Scratching", "B": "Sexual intercourse", "C": "Tampon use", "D": "Douching"}, "r": "A", "e": {"correcta": "Lichen simplex chronicus results from chronic irritation and repetitive scratching, leading to epithelial hyperplasia (thickened, leathery skin).", "incorrectas": {"B": "Sexual intercourse is not the classic association driving lichen simplex chronicus.", "C": "Tampon use is not specifically linked to this condition's pathogenesis.", "D": "Douching is not the recognized behavioral trigger for lichen simplex chronicus."}}}, {"id": "anking-neurology-special-senses-pathology-090", "fuente": "anking", "tema": 9, "anki": "1480519696929", "q": "Hemisection of the spinal cord (loss of one lateral half) produces which classic clinical syndrome?", "o": {"A": "Brown-Sequard syndrome", "B": "Anterior cord syndrome", "C": "Central cord syndrome", "D": "Werdnig-Hoffmann disease"}, "r": "A", "e": {"correcta": "Brown-Sequard syndrome results from hemisection of the spinal cord, producing a characteristic combination of ipsilateral and contralateral deficits below the lesion.", "incorrectas": {"B": "Anterior cord syndrome results from occlusion of the anterior spinal artery, causing bilateral loss of pain/temperature and motor function, not hemisection.", "C": "Central cord syndrome typically results from hyperextension injury or syringomyelia, causing bilateral upper extremity weakness/sensory loss.", "D": "Werdnig-Hoffmann disease is an infantile motor neuron disease (SMA type 1), unrelated to spinal cord hemisection."}}}, {"id": "anking-neurology-special-senses-pathology-091", "fuente": "anking", "tema": 9, "anki": "1480519732488", "q": "In Brown-Sequard syndrome, loss of vibration, proprioception, and touch (dorsal column damage) occurs on which side relative to the lesion?", "o": {"A": "Ipsilateral", "B": "Contralateral", "C": "Bilateral", "D": "None of the above (unaffected)"}, "r": "A", "e": {"correcta": "The dorsal columns carry vibration, proprioception, and fine touch information that ascends ipsilaterally before decussating in the medulla, so damage causes ipsilateral loss below the lesion.", "incorrectas": {"B": "Contralateral loss below the lesion applies to the spinothalamic tract (pain/temperature), not the dorsal columns.", "C": "The deficit is unilateral (ipsilateral), not bilateral, in a hemisection injury.", "D": "Dorsal column function is definitely impaired ipsilaterally after hemisection."}}}, {"id": "anking-neurology-special-senses-pathology-092", "fuente": "anking", "tema": 9, "anki": "1480519737086", "q": "In Brown-Sequard syndrome, loss of pain and temperature sensation (spinothalamic tract damage) occurs on which side relative to the lesion?", "o": {"A": "Ipsilateral", "B": "Contralateral", "C": "Bilateral", "D": "There is no sensory loss"}, "r": "B", "e": {"correcta": "The spinothalamic tract decussates near the level of entry, so fibers ascending in the tract on the side of the lesion actually carry pain/temperature information from the opposite side of the body, producing contralateral loss below the lesion.", "incorrectas": {"A": "Ipsilateral loss below the lesion is characteristic of dorsal column damage, not the spinothalamic tract.", "C": "The deficit is unilateral (contralateral), not bilateral.", "D": "Pain and temperature sensation is lost contralaterally due to the crossed spinothalamic tract."}}}, {"id": "anking-neurology-special-senses-pathology-093", "fuente": "anking", "tema": 9, "anki": "1480519741494", "q": "In Brown-Sequard syndrome, loss of ALL sensory modalities occurring specifically AT the level of the lesion (rather than below it) is on which side?", "o": {"A": "Ipsilateral", "B": "Contralateral", "C": "Bilateral", "D": "No sensory loss occurs at the level of the lesion"}, "r": "A", "e": {"correcta": "At the level of the lesion, the damage affects the entering dorsal root and gray matter on the same side, causing complete ipsilateral loss of all sensory modalities (vibration, proprioception, touch, pain, temperature) at that segmental level.", "incorrectas": {"B": "Contralateral loss occurs below the lesion for pain/temperature due to the crossed spinothalamic tract, not at the level of the lesion.", "C": "The loss at the level of the lesion is unilateral (ipsilateral), reflecting local segmental damage.", "D": "There is in fact a band of complete ipsilateral sensory loss at the level of the lesion."}}}, {"id": "anking-neurology-special-senses-pathology-094", "fuente": "anking", "tema": 9, "anki": "1480545346945", "q": "Poliomyelitis is caused by infection with which pathogen?", "o": {"A": "Poliovirus", "B": "Coxsackievirus", "C": "Rabies virus", "D": "West Nile virus"}, "r": "A", "e": {"correcta": "Poliomyelitis is caused directly by poliovirus, an enterovirus that infects and destroys anterior horn motor neurons.", "incorrectas": {"B": "Coxsackievirus is another enterovirus causing distinct diseases (e.g., hand-foot-mouth disease, myocarditis), not classic poliomyelitis.", "C": "Rabies virus causes a fatal encephalitis transmitted by animal bites, not poliomyelitis.", "D": "West Nile virus can cause a poliomyelitis-like flaccid paralysis but is a distinct flavivirus, not the cause of classic poliomyelitis."}}}, {"id": "anking-neurology-special-senses-pathology-095", "fuente": "anking", "tema": 9, "anki": "1480549817498", "q": "Poliovirus is transmitted primarily via which route?", "o": {"A": "Fecal-oral route", "B": "Respiratory droplets", "C": "Sexual contact", "D": "Vector-borne (mosquito)"}, "r": "A", "e": {"correcta": "Poliovirus spreads via the fecal-oral route, replicating initially in the oropharynx and gut before potentially reaching the CNS.", "incorrectas": {"B": "Respiratory droplet transmission is characteristic of viruses like influenza, not poliovirus.", "C": "Sexual transmission is not a route for poliovirus spread.", "D": "Poliovirus is not vector-borne; it is transmitted through contaminated food/water via the fecal-oral route."}}}, {"id": "anking-neurology-special-senses-pathology-096", "fuente": "anking", "tema": 9, "anki": "1480549839004", "q": "Which region of the spinal cord gray matter is most affected by poliovirus infection?", "o": {"A": "Ventral (anterior) horn", "B": "Dorsal (posterior) horn", "C": "Lateral horn", "D": "Dorsal columns"}, "r": "A", "e": {"correcta": "Poliovirus has a tropism for anterior (ventral) horn motor neurons, leading to their destruction and resultant flaccid paralysis.", "incorrectas": {"B": "The dorsal horn contains sensory neurons, which are typically spared in poliomyelitis (sensation is preserved).", "C": "The lateral horn contains preganglionic autonomic neurons, not the primary site of poliovirus damage.", "D": "The dorsal columns are white matter sensory tracts, not gray matter motor neurons, and are not the target of poliovirus."}}}, {"id": "anking-neurology-special-senses-pathology-097", "fuente": "anking", "tema": 9, "anki": "1480549844650", "q": "What spinal cord level is most commonly affected by poliovirus?", "o": {"A": "Lumbar levels", "B": "Cervical levels", "C": "Thoracic levels", "D": "Sacral levels"}, "r": "A", "e": {"correcta": "Poliovirus most commonly affects the lumbar spinal cord levels, which is why lower extremity weakness is a classic presentation.", "incorrectas": {"B": "Cervical levels can be involved but are not the most commonly affected site.", "C": "Thoracic levels are less characteristically affected compared to lumbar levels.", "D": "Sacral levels are not the most commonly cited site of involvement in poliomyelitis."}}}, {"id": "anking-neurology-special-senses-pathology-098", "fuente": "anking", "tema": 9, "anki": "1480549851019", "q": "Does poliomyelitis classically present with symmetric or asymmetric weakness?", "o": {"A": "Asymmetric weakness", "B": "Symmetric weakness", "C": "Purely proximal symmetric weakness", "D": "Purely distal symmetric weakness"}, "r": "A", "e": {"correcta": "Poliomyelitis classically presents with asymmetric weakness, which is a key feature distinguishing it from Werdnig-Hoffmann disease (infantile SMA), which causes symmetric weakness.", "incorrectas": {"B": "Symmetric weakness is characteristic of Werdnig-Hoffmann disease (SMA), not poliomyelitis.", "C": "Poliomyelitis weakness is not specifically described as purely proximal and symmetric.", "D": "Poliomyelitis weakness is asymmetric, not a symmetric distal pattern."}}}, {"id": "anking-neurology-special-senses-pathology-099", "fuente": "anking", "tema": 9, "anki": "1480549859622", "q": "Poliomyelitis presents with weakness that is asymmetric and affecting which distribution of the body?", "o": {"A": "Bilateral (though asymmetric between sides)", "B": "Strictly unilateral, sparing the other side entirely", "C": "Only the upper extremities", "D": "Only the cranial nerves"}, "r": "A", "e": {"correcta": "Poliomyelitis causes bilateral involvement, but the weakness is asymmetric in severity between the two sides, distinguishing it from a symmetric bilateral pattern.", "incorrectas": {"B": "Poliomyelitis is not strictly unilateral; it typically involves both sides, just asymmetrically.", "C": "Weakness is not limited to the upper extremities; the lumbar (lower extremity) region is most classically affected.", "D": "While bulbar/cranial nerve involvement can occur in severe cases, the classic finding is bilateral asymmetric limb weakness, not isolated cranial nerve involvement."}}}, {"id": "anking-neurology-special-senses-pathology-100", "fuente": "anking", "tema": 9, "anki": "1480549890498", "q": "Werdnig-Hoffmann disease is the infantile (type 1) form of which disease?", "o": {"A": "Spinal muscular atrophy (SMA)", "B": "Poliomyelitis", "C": "Amyotrophic lateral sclerosis (ALS)", "D": "Charcot-Marie-Tooth disease"}, "r": "A", "e": {"correcta": "Werdnig-Hoffmann disease is the severe infantile form (type 1) of spinal muscular atrophy, caused by mutation of the SMN1 gene leading to loss of anterior horn motor neurons.", "incorrectas": {"B": "Poliomyelitis is a viral infection of anterior horn cells, a distinct entity from the genetic disease SMA.", "C": "ALS is an adult-onset motor neuron disease affecting both upper and lower motor neurons, not the infantile SMA.", "D": "Charcot-Marie-Tooth disease is a hereditary peripheral neuropathy, not a motor neuron disease like SMA."}}}, {"id": "anking-neurology-special-senses-pathology-101", "fuente": "anking", "tema": 9, "anki": "1480549898334", "q": "Spinal muscular atrophy damages which type of motor neurons?", "o": {"A": "Lower motor neurons", "B": "Upper motor neurons", "C": "Both upper and lower motor neurons equally", "D": "Neither; it damages sensory neurons"}, "r": "A", "e": {"correcta": "Spinal muscular atrophy selectively destroys lower motor neurons (anterior horn cells), producing flaccid paralysis, hyporeflexia, and fasciculations.", "incorrectas": {"B": "Upper motor neuron damage would cause spasticity and hyperreflexia, which is not the pattern seen in SMA.", "C": "SMA does not involve upper motor neurons; only lower motor neurons are affected.", "D": "SMA is a motor neuron disease; sensory neurons are characteristically spared."}}}, {"id": "anking-neurology-special-senses-pathology-102", "fuente": "anking", "tema": 9, "anki": "1480549901442", "q": "What is the median age of death for infants with untreated Werdnig-Hoffmann disease (SMA type 1)?", "o": {"A": "7 months", "B": "7 years", "C": "2 months", "D": "18 years"}, "r": "A", "e": {"correcta": "Werdnig-Hoffmann disease (SMA type 1) has a median age of death around 7 months without treatment, reflecting its severe, rapidly progressive course; newer therapies like nusinersen can prolong survival.", "incorrectas": {"B": "7 years overstates typical untreated survival for this severe infantile form.", "C": "2 months understates the typical median survival age.", "D": "18 years is far beyond the natural history of untreated SMA type 1 and would be more consistent with milder SMA subtypes."}}}, {"id": "anking-neurology-special-senses-pathology-103", "fuente": "anking", "tema": 9, "anki": "1480549909273", "q": "Does spinal muscular atrophy present with symmetric or asymmetric weakness?", "o": {"A": "Symmetric weakness", "B": "Asymmetric weakness", "C": "Weakness limited to one limb", "D": "No weakness, only sensory loss"}, "r": "A", "e": {"correcta": "Spinal muscular atrophy presents with symmetric weakness, an important distinguishing feature from poliomyelitis, which presents with asymmetric weakness.", "incorrectas": {"B": "Asymmetric weakness is characteristic of poliomyelitis, not SMA.", "C": "SMA is not limited to one limb; it causes diffuse symmetric weakness.", "D": "SMA causes motor weakness, not primary sensory loss, since it is a motor neuron disease."}}}, {"id": "anking-neurology-special-senses-pathology-104", "fuente": "anking", "tema": 9, "anki": "1480549920521", "q": "Spinal muscular atrophy presents with weakness affecting which distribution?", "o": {"A": "Bilateral, symmetric weakness", "B": "Bilateral, asymmetric weakness", "C": "Unilateral weakness only", "D": "Weakness confined to the cranial nerves"}, "r": "A", "e": {"correcta": "SMA causes bilateral and symmetric weakness, in contrast to the bilateral but asymmetric weakness pattern seen in poliomyelitis.", "incorrectas": {"B": "Bilateral asymmetric weakness is the pattern seen in poliomyelitis, not SMA.", "C": "SMA is not unilateral; it affects both sides symmetrically.", "D": "Bulbar weakness can occur in severe SMA, but the hallmark is symmetric bilateral limb weakness, not isolated cranial nerve findings."}}}, {"id": "anking-neurology-special-senses-pathology-105", "fuente": "anking", "tema": 9, "anki": "1480549940609", "q": "Which neurologic complication is classically associated with tertiary syphilis?", "o": {"A": "Tabes dorsalis", "B": "Guillain-Barre syndrome", "C": "Multiple sclerosis", "D": "Wernicke encephalopathy"}, "r": "A", "e": {"correcta": "Tabes dorsalis is a classic neurologic manifestation of tertiary (late) syphilis, resulting from Treponema pallidum-induced degeneration of the dorsal columns and dorsal roots.", "incorrectas": {"B": "Guillain-Barre syndrome is an autoimmune polyneuropathy often triggered by antecedent infection (e.g., Campylobacter), not a manifestation of syphilis.", "C": "Multiple sclerosis is a demyelinating autoimmune disease of the CNS unrelated to syphilis infection.", "D": "Wernicke encephalopathy results from thiamine (B1) deficiency, not from syphilis infection."}}}, {"id": "anking-neurology-special-senses-pathology-106", "fuente": "anking", "tema": 9, "anki": "1480549946177", "q": "Tabes dorsalis involves progressive demyelination of which two structures?", "o": {"A": "Dorsal columns and dorsal roots", "B": "Corticospinal tracts and anterior horn cells", "C": "Spinothalamic tracts and ventral roots", "D": "Cerebellar peduncles and dentate nucleus"}, "r": "A", "e": {"correcta": "Tabes dorsalis is characterized by progressive demyelination of the dorsal columns and dorsal (posterior) roots, leading to loss of proprioception and vibration sense.", "incorrectas": {"B": "The corticospinal tracts and anterior horn cells are affected in motor neuron diseases like ALS, not tabes dorsalis.", "C": "The spinothalamic tracts and ventral roots are not the primary structures damaged in tabes dorsalis.", "D": "The cerebellar peduncles and dentate nucleus are cerebellar structures unrelated to tabes dorsalis pathology."}}}, {"id": "anking-neurology-special-senses-pathology-107", "fuente": "anking", "tema": 9, "anki": "1480549960718", "q": "Tabes dorsalis may present with progressive sensory ataxia due to impairment of which sensory modality?", "o": {"A": "Proprioception", "B": "Pain sensation", "C": "Temperature sensation", "D": "Auditory sensation"}, "r": "A", "e": {"correcta": "Impaired proprioception due to dorsal column degeneration in tabes dorsalis leads to poor coordination and a characteristic high-stepping, slapping gait (sensory ataxia).", "incorrectas": {"B": "Pain sensation is carried by the spinothalamic tract, which is not the primary tract damaged in tabes dorsalis.", "C": "Temperature sensation is also carried by the spinothalamic tract, not the dorsal columns affected in tabes dorsalis.", "D": "Auditory sensation is unrelated to the dorsal column pathology causing sensory ataxia in tabes dorsalis."}}}, {"id": "anking-gastrointestinal-pathology-108", "fuente": "anking", "tema": 10, "anki": "1463150148468", "q": "What is the most common cause of hematochezia (lower GI bleeding) in adults?", "o": {"A": "Diverticulosis", "B": "Angiodysplasia", "C": "Hemorrhoids", "D": "Colorectal carcinoma"}, "r": "A", "e": {"correcta": "Diverticulosis is the most common cause of hematochezia in adults, due to rupture of the vasa recta at the neck or dome of a diverticulum.", "incorrectas": {"B": "Angiodysplasia is the second most common cause of hematochezia, not the most common.", "C": "Hemorrhoids typically cause minor bright red bleeding but are not the leading overall cause.", "D": "Colorectal carcinoma can cause bleeding but is a less common cause of significant hematochezia than diverticulosis."}}}, {"id": "anking-gastrointestinal-pathology-109", "fuente": "anking", "tema": 10, "anki": "1464478560360", "q": "Ursodeoxycholic acid (ursodiol) is used clinically for the prevention or dissolution of which condition?", "o": {"A": "Gallstones", "B": "Renal calculi", "C": "Peptic ulcers", "D": "Esophageal varices"}, "r": "A", "e": {"correcta": "Ursodeoxycholic acid reduces cholesterol saturation of bile, helping to prevent and dissolve cholesterol gallstones.", "incorrectas": {"B": "Ursodiol is not used for renal stones, which are managed with other agents (e.g., thiazides, citrate).", "C": "Peptic ulcers are treated with acid suppression (PPIs, H2 blockers), not ursodiol.", "D": "Esophageal varices are managed with beta-blockers or endoscopic therapy, not ursodiol."}}}, {"id": "anking-gastrointestinal-pathology-110", "fuente": "anking", "tema": 10, "anki": "1464478566239", "q": "Ursodeoxycholic acid promotes gallstone dissolution primarily by which mechanism?", "o": {"A": "Increasing bile secretion and decreasing cholesterol secretion/reabsorption", "B": "Increasing cholesterol secretion into bile", "C": "Inhibiting bile acid synthesis entirely", "D": "Increasing gallbladder contraction via CCK stimulation"}, "r": "A", "e": {"correcta": "Ursodeoxycholic acid increases bile flow and decreases cholesterol secretion and intestinal reabsorption, lowering the cholesterol saturation index of bile.", "incorrectas": {"B": "It decreases, not increases, cholesterol secretion into bile.", "C": "It does not eliminate bile acid synthesis; it alters the bile acid pool composition.", "D": "Its mechanism is biochemical (bile composition), not primarily related to gallbladder motility."}}}, {"id": "anking-gastrointestinal-pathology-111", "fuente": "anking", "tema": 10, "anki": "1471825802842", "q": "Hemangiomas are benign tumors composed of which cell/tissue type?", "o": {"A": "Blood vessels", "B": "Smooth muscle", "C": "Adipocytes", "D": "Lymphatic channels"}, "r": "A", "e": {"correcta": "Hemangiomas are benign vascular tumors composed of proliferating blood vessels, most commonly found in the skin and liver.", "incorrectas": {"B": "Smooth muscle tumors are leiomyomas, not hemangiomas.", "C": "Adipocyte tumors are lipomas.", "D": "Tumors of lymphatic channels are lymphangiomas, a distinct entity."}}}, {"id": "anking-gastrointestinal-pathology-112", "fuente": "anking", "tema": 10, "anki": "1471825973147", "q": "Hemangiomas most often involve which two organs?", "o": {"A": "Skin and liver", "B": "Lung and spleen", "C": "Kidney and pancreas", "D": "Brain and bone"}, "r": "A", "e": {"correcta": "Hemangiomas most commonly arise in the skin and liver, and blanch with pressure (distinguishing them from purpura).", "incorrectas": {"B": "Lung and spleen are not the classic sites for hemangiomas.", "C": "Kidney and pancreas are not typical hemangioma locations.", "D": "Brain and bone are less typical sites; cavernous hemangiomas can rarely occur in brain but skin/liver are classic."}}}, {"id": "anking-gastrointestinal-pathology-113", "fuente": "anking", "tema": 10, "anki": "1471825985658", "q": "Hemangiomas commonly present at birth and often do what during childhood?", "o": {"A": "Regress spontaneously", "B": "Rapidly metastasize", "C": "Transform into angiosarcoma", "D": "Calcify completely"}, "r": "A", "e": {"correcta": "Infantile hemangiomas typically appear at birth or shortly after and often regress spontaneously during childhood.", "incorrectas": {"B": "Hemangiomas are benign and do not metastasize.", "C": "Malignant transformation to angiosarcoma from a hemangioma is not a typical natural history.", "D": "Complete calcification is not the typical course; regression is the classic pattern."}}}, {"id": "anking-gastrointestinal-pathology-114", "fuente": "anking", "tema": 10, "anki": "1471825988252", "q": "Which tumor is a highly aggressive malignant proliferation of endothelial cells, commonly affecting skin, breast, and liver?", "o": {"A": "Angiosarcoma", "B": "Hemangioma", "C": "Kaposi sarcoma", "D": "Lymphangiosarcoma"}, "r": "A", "e": {"correcta": "Angiosarcomas are highly aggressive malignant tumors of endothelial cell origin, commonly involving skin, breast, and liver (the latter associated with vinyl chloride, arsenic, and Thorotrast exposure).", "incorrectas": {"B": "Hemangiomas are benign, not aggressive malignant tumors.", "C": "Kaposi sarcoma is associated with HHV-8 and is a distinct endothelial malignancy, classically in HIV/immunosuppressed patients, not the general description given.", "D": "Lymphangiosarcoma arises from lymphatic endothelium, classically after chronic lymphedema (e.g., post-mastectomy), not the classic answer here."}}}, {"id": "anking-gastrointestinal-pathology-115", "fuente": "anking", "tema": 10, "anki": "1473628000924", "q": "Which liver pathology is associated with alpha-1-antitrypsin deficiency?", "o": {"A": "Cirrhosis", "B": "Hepatic adenoma", "C": "Primary biliary cholangitis", "D": "Hemochromatosis"}, "r": "A", "e": {"correcta": "Alpha-1-antitrypsin deficiency causes cirrhosis due to accumulation of misfolded, polymerized alpha-1-antitrypsin protein within hepatocytes.", "incorrectas": {"B": "Hepatic adenoma is associated with oral contraceptive use, not alpha-1-antitrypsin deficiency.", "C": "Primary biliary cholangitis is an autoimmune disease of intrahepatic bile ducts, unrelated to alpha-1-antitrypsin.", "D": "Hemochromatosis is caused by iron overload, a distinct genetic disorder (HFE gene)."}}}, {"id": "anking-gastrointestinal-pathology-116", "fuente": "anking", "tema": 10, "anki": "1473628007883", "q": "In alpha-1-antitrypsin deficiency, where does the mutant protein polymerize and accumulate, causing liver damage?", "o": {"A": "Endoplasmic reticulum", "B": "Golgi apparatus", "C": "Mitochondria", "D": "Nucleus"}, "r": "A", "e": {"correcta": "Mutant alpha-1-antitrypsin misfolds and accumulates in the endoplasmic reticulum of hepatocytes, visible as PAS-positive, diastase-resistant globules.", "incorrectas": {"B": "The Golgi is not the site of accumulation; the protein never properly progresses beyond the ER.", "C": "Mitochondria are not involved in alpha-1-antitrypsin protein accumulation.", "D": "The nucleus is not the site of accumulation of the misfolded protein."}}}, {"id": "anking-gastrointestinal-pathology-117", "fuente": "anking", "tema": 10, "anki": "1473628016236", "q": "What is the normal (wild-type) allele for alpha-1-antitrypsin?", "o": {"A": "PiM", "B": "PiZ", "C": "PiS", "D": "PiNull"}, "r": "A", "e": {"correcta": "PiM is the normal, most common allele for alpha-1-antitrypsin, associated with normal enzyme levels and function.", "incorrectas": {"B": "PiZ is the most clinically significant mutant allele, associated with disease.", "C": "PiS is a variant allele associated with intermediate reduction in AAT levels, not the normal allele.", "D": "PiNull alleles produce no AAT protein at all and are associated with severe emphysema without liver disease."}}}, {"id": "anking-gastrointestinal-pathology-118", "fuente": "anking", "tema": 10, "anki": "1473628019626", "q": "What is the most clinically significant mutant allele for alpha-1-antitrypsin?", "o": {"A": "PiZ", "B": "PiM", "C": "PiS", "D": "PiF"}, "r": "A", "e": {"correcta": "PiZ is the most clinically significant mutant allele; it is a codominant trait, so even PiMZ heterozygotes carry risk, especially with smoking.", "incorrectas": {"B": "PiM is the normal allele, not the pathogenic mutant.", "C": "PiS is associated with a milder reduction in AAT and is less clinically significant than PiZ.", "D": "PiF is not a recognized major clinically significant allele in alpha-1-antitrypsin deficiency."}}}, {"id": "anking-gastrointestinal-pathology-119", "fuente": "anking", "tema": 10, "anki": "1473628022683", "q": "Which genotype is associated with an asymptomatic phenotype with decreased alpha-1-antitrypsin levels?", "o": {"A": "PiMZ heterozygotes", "B": "PiZZ homozygotes", "C": "PiMM homozygotes", "D": "PiSS homozygotes"}, "r": "A", "e": {"correcta": "PiMZ heterozygotes have decreased but still substantial alpha-1-antitrypsin levels and are typically asymptomatic unless additional risk factors (e.g., smoking) are present.", "incorrectas": {"B": "PiZZ homozygotes have severely reduced AAT and are at high risk for both emphysema and liver cirrhosis, not asymptomatic.", "C": "PiMM homozygotes are the normal genotype with normal AAT levels.", "D": "PiSS homozygotes have a milder deficiency phenotype but are not the classic asymptomatic heterozygote answer."}}}, {"id": "anking-gastrointestinal-pathology-120", "fuente": "anking", "tema": 10, "anki": "1473628025370", "q": "PiMZ heterozygotes with alpha-1-antitrypsin deficiency are at significant risk for emphysema if they do what?", "o": {"A": "Smoke", "B": "Drink alcohol", "C": "Take NSAIDs", "D": "Have high dietary iron intake"}, "r": "A", "e": {"correcta": "Smoking significantly increases the risk of emphysema in PiMZ heterozygotes by overwhelming their already reduced antiprotease reserve.", "incorrectas": {"B": "Alcohol use is a risk factor for liver disease broadly but is not the classic trigger described for AAT-related emphysema.", "C": "NSAID use is not linked to increased emphysema risk in AAT deficiency.", "D": "Dietary iron intake relates to hemochromatosis, not alpha-1-antitrypsin-associated emphysema."}}}, {"id": "anking-gastrointestinal-pathology-121", "fuente": "anking", "tema": 10, "anki": "1473628028243", "q": "Which genotype is associated with significant risk for panacinar emphysema and liver cirrhosis in alpha-1-antitrypsin deficiency?", "o": {"A": "PiZZ homozygotes", "B": "PiMZ heterozygotes", "C": "PiMM homozygotes", "D": "PiMS heterozygotes"}, "r": "A", "e": {"correcta": "PiZZ homozygotes have markedly reduced alpha-1-antitrypsin levels, leading to significant risk of panacinar emphysema (often in young, nonsmoking patients) and liver cirrhosis.", "incorrectas": {"B": "PiMZ heterozygotes have a milder phenotype, with risk mainly if they smoke.", "C": "PiMM homozygotes are normal with no increased risk.", "D": "PiMS heterozygotes have only mildly reduced AAT and low disease risk."}}}, {"id": "anking-gastrointestinal-pathology-122", "fuente": "anking", "tema": 10, "anki": "1474503557098", "q": "Oropharyngeal carcinoma is most strongly associated with which virus?", "o": {"A": "HPV-16", "B": "Epstein-Barr virus", "C": "HSV-1", "D": "HHV-8"}, "r": "A", "e": {"correcta": "HPV-16, a high-risk HPV subtype, is strongly associated with oropharyngeal (tonsillar/base of tongue) squamous cell carcinoma.", "incorrectas": {"B": "Epstein-Barr virus is associated with nasopharyngeal carcinoma, not oropharyngeal carcinoma.", "C": "HSV-1 causes oral herpes (cold sores), not oropharyngeal carcinoma.", "D": "HHV-8 is associated with Kaposi sarcoma, not oropharyngeal carcinoma."}}}, {"id": "anking-gastrointestinal-pathology-123", "fuente": "anking", "tema": 10, "anki": "1478834249508", "q": "Which condition presents with a triad of iron deficiency anemia, dysphagia, and a beefy red tongue?", "o": {"A": "Plummer-Vinson syndrome", "B": "Zenker diverticulum", "C": "Achalasia", "D": "Eosinophilic esophagitis"}, "r": "A", "e": {"correcta": "Plummer-Vinson syndrome classically presents with the triad of iron deficiency anemia, esophageal webs causing dysphagia, and glossitis (beefy red tongue).", "incorrectas": {"B": "Zenker diverticulum causes dysphagia and halitosis but not the anemia/glossitis triad.", "C": "Achalasia presents with dysphagia to both solids and liquids due to LES dysfunction, not this triad.", "D": "Eosinophilic esophagitis presents with dysphagia and food impaction, often with allergy history, not this classic triad."}}}, {"id": "anking-gastrointestinal-pathology-124", "fuente": "anking", "tema": 10, "anki": "1482191360472", "q": "Painful, shallow, red ulcers involving the oral mucosa, commonly called \"cold sores,\" describe which condition?", "o": {"A": "Oral herpes", "B": "Aphthous ulcers", "C": "Oral candidiasis", "D": "Herpangina"}, "r": "A", "e": {"correcta": "Oral herpes (cold sores) presents as painful, shallow, red ulcers of the oral mucosa and lips, typically due to HSV-1 reactivation.", "incorrectas": {"B": "Aphthous ulcers (canker sores) are non-infectious, painful ulcers not caused by a virus.", "C": "Oral candidiasis (thrush) presents as white plaques, not vesicular ulcers.", "D": "Herpangina, caused by coxsackievirus, causes posterior oropharyngeal ulcers, distinct from herpes labialis."}}}, {"id": "anking-gastrointestinal-pathology-125", "fuente": "anking", "tema": 10, "anki": "1482191366011", "q": "Oral herpes (cold sores) is usually caused by infection with which virus?", "o": {"A": "HSV-1", "B": "HSV-2", "C": "VZV", "D": "CMV"}, "r": "A", "e": {"correcta": "Oral herpes (herpes labialis) is usually caused by HSV-1, which establishes latency in the trigeminal ganglion and reactivates to cause cold sores.", "incorrectas": {"B": "HSV-2 is more classically associated with genital herpes, though overlap can occur.", "C": "VZV causes chickenpox and shingles, not typical cold sores.", "D": "CMV causes mononucleosis-like illness and congenital infection, not oral cold sores."}}}, {"id": "anking-immune-responses-126", "fuente": "anking", "tema": 11, "anki": "1461794583601", "q": "Upregulation of interferon synthesis in virus-infected cells is primarily accomplished by which class of signaling molecules?", "o": {"A": "Interleukins", "B": "Complement proteins", "C": "Immunoglobulins", "D": "Histamine"}, "r": "A", "e": {"correcta": "Interleukins (particularly type I interferon-inducing cytokine signals) upregulate interferon synthesis in infected cells, enhancing the antiviral state of surrounding cells.", "incorrectas": {"B": "Complement proteins mediate opsonization and lysis, not interferon gene upregulation.", "C": "Immunoglobulins are antibodies that neutralize antigens; they do not directly upregulate interferon synthesis.", "D": "Histamine is a mediator of allergic/inflammatory responses, not interferon induction."}}}, {"id": "anking-immune-responses-127", "fuente": "anking", "tema": 11, "anki": "1471806482193", "q": "Which laboratory finding is classically associated with granulomatosis with polyangiitis (Wegener granulomatosis)?", "o": {"A": "Positive c-ANCA", "B": "Positive p-ANCA", "C": "Positive ANA", "D": "Positive anti-dsDNA"}, "r": "A", "e": {"correcta": "Granulomatosis with polyangiitis is associated with positive c-ANCA (cytoplasmic ANCA), also known as PR3-ANCA or anti-proteinase 3 antibody.", "incorrectas": {"B": "p-ANCA is associated with microscopic polyangiitis and Churg-Strauss syndrome, not Wegener.", "C": "ANA is associated with lupus and other connective tissue diseases, not vasculitis of this type.", "D": "Anti-dsDNA is specific for systemic lupus erythematosus, not vasculitis."}}}, {"id": "anking-immune-responses-128", "fuente": "anking", "tema": 11, "anki": "1471806505942", "q": "How does microscopic polyangiitis present differently from granulomatosis with polyangiitis (Wegener)?", "o": {"A": "Microscopic polyangiitis lacks nasopharyngeal involvement and granulomas", "B": "Microscopic polyangiitis always involves asthma and eosinophilia", "C": "Microscopic polyangiitis is associated with c-ANCA rather than p-ANCA", "D": "Microscopic polyangiitis causes granulomatous inflammation of the upper respiratory tract"}, "r": "A", "e": {"correcta": "Microscopic polyangiitis lacks nasopharyngeal involvement and granuloma formation, distinguishing it from granulomatosis with polyangiitis, which is p-ANCA vs c-ANCA respectively.", "incorrectas": {"B": "Asthma and eosinophilia are features of Churg-Strauss syndrome (eosinophilic granulomatosis with polyangiitis), not microscopic polyangiitis.", "C": "Microscopic polyangiitis is associated with p-ANCA, while Wegener is associated with c-ANCA — this option reverses the association.", "D": "Granulomatous inflammation of the upper respiratory tract is characteristic of Wegener, not microscopic polyangiitis."}}}, {"id": "anking-immune-responses-129", "fuente": "anking", "tema": 11, "anki": "1471806519835", "q": "Which serologic marker is classically positive in microscopic polyangiitis?", "o": {"A": "p-ANCA", "B": "c-ANCA", "C": "Anti-GBM antibody", "D": "Rheumatoid factor"}, "r": "A", "e": {"correcta": "Microscopic polyangiitis is associated with positive p-ANCA (perinuclear ANCA), also known as MPO-ANCA or anti-myeloperoxidase antibody.", "incorrectas": {"B": "c-ANCA is associated with granulomatosis with polyangiitis (Wegener), not microscopic polyangiitis.", "C": "Anti-GBM antibody is characteristic of Goodpasture syndrome, a distinct disease.", "D": "Rheumatoid factor is associated with rheumatoid arthritis, not ANCA-associated vasculitis."}}}, {"id": "anking-immune-responses-130", "fuente": "anking", "tema": 11, "anki": "1471806647224", "q": "Which serologic marker is classically positive in Churg-Strauss syndrome (eosinophilic granulomatosis with polyangiitis)?", "o": {"A": "p-ANCA", "B": "c-ANCA", "C": "Anti-Smith antibody", "D": "Anti-centromere antibody"}, "r": "A", "e": {"correcta": "Churg-Strauss syndrome is associated with positive p-ANCA (perinuclear ANCA), also known as MPO-ANCA or anti-myeloperoxidase antibody.", "incorrectas": {"B": "c-ANCA is characteristic of granulomatosis with polyangiitis (Wegener), a different vasculitis.", "C": "Anti-Smith antibody is specific for systemic lupus erythematosus.", "D": "Anti-centromere antibody is associated with limited systemic sclerosis (CREST syndrome)."}}}, {"id": "anking-immune-responses-131", "fuente": "anking", "tema": 11, "anki": "1473388953084", "q": "Which two vasculitides are classically associated with a positive serum p-ANCA?", "o": {"A": "Churg-Strauss syndrome and microscopic polyangiitis", "B": "Granulomatosis with polyangiitis and Kawasaki disease", "C": "Polyarteritis nodosa and Takayasu arteritis", "D": "Giant cell arteritis and Behçet disease"}, "r": "A", "e": {"correcta": "Churg-Strauss syndrome and microscopic polyangiitis are both associated with positive p-ANCA (MPO-ANCA); microscopic polyangiitis additionally lacks the asthma and eosinophilia seen in Churg-Strauss.", "incorrectas": {"B": "Granulomatosis with polyangiitis is associated with c-ANCA, not p-ANCA, and Kawasaki disease is not an ANCA-associated vasculitis.", "C": "Polyarteritis nodosa and Takayasu arteritis are not typically ANCA-associated vasculitides.", "D": "Giant cell arteritis and Behçet disease are large/variable vessel vasculitides not associated with ANCA."}}}, {"id": "anking-immune-responses-132", "fuente": "anking", "tema": 11, "anki": "1473986197639", "q": "In immune thrombocytopenic purpura (ITP), the autoantibodies against platelets are produced by plasma cells located primarily in which organ?", "o": {"A": "Spleen", "B": "Liver", "C": "Bone marrow", "D": "Thymus"}, "r": "A", "e": {"correcta": "In ITP, autoantibodies against platelet antigens (e.g., GpIIb/IIIa) are produced by plasma cells in the spleen, which is also the primary site of antibody-coated platelet destruction.", "incorrectas": {"B": "The liver is not the primary site of autoantibody production in ITP, though it can contribute to platelet clearance.", "C": "Bone marrow is the site of platelet production, not the main source of the pathogenic autoantibodies in ITP.", "D": "The thymus is involved in T-cell maturation and central tolerance, not plasma cell antibody production in ITP."}}}, {"id": "anking-immune-responses-133", "fuente": "anking", "tema": 11, "anki": "1475376623320", "q": "Which cause of pauci-immune glomerulonephritis is associated with c-ANCA (PR3-ANCA)?", "o": {"A": "Granulomatosis with polyangiitis (Wegener)", "B": "Microscopic polyangiitis", "C": "Churg-Strauss syndrome", "D": "Goodpasture syndrome"}, "r": "A", "e": {"correcta": "Granulomatosis with polyangiitis (Wegener granulomatosis) is the cause of pauci-immune glomerulonephritis associated with c-ANCA (PR3-ANCA), showing no significant Ig/C3 deposition on biopsy.", "incorrectas": {"B": "Microscopic polyangiitis causes pauci-immune GN but is associated with p-ANCA, not c-ANCA.", "C": "Churg-Strauss syndrome causes pauci-immune GN but is associated with p-ANCA, not c-ANCA.", "D": "Goodpasture syndrome is an immune-complex (anti-GBM) mediated GN, not pauci-immune, and is not ANCA-related by definition."}}}, {"id": "anking-immune-responses-134", "fuente": "anking", "tema": 11, "anki": "1475376628335", "q": "Which causes of pauci-immune glomerulonephritis are associated with p-ANCA (MPO-ANCA)?", "o": {"A": "Microscopic polyangiitis and Churg-Strauss syndrome", "B": "Granulomatosis with polyangiitis and Goodpasture syndrome", "C": "IgA nephropathy and lupus nephritis", "D": "Post-streptococcal glomerulonephritis and membranous nephropathy"}, "r": "A", "e": {"correcta": "Microscopic polyangiitis and Churg-Strauss syndrome are the pauci-immune glomerulonephritides associated with p-ANCA (MPO-ANCA), both showing no Ig/C3 deposition on immunofluorescence.", "incorrectas": {"B": "Granulomatosis with polyangiitis is associated with c-ANCA, and Goodpasture syndrome is an immune-complex-mediated disease, not pauci-immune or ANCA-associated.", "C": "IgA nephropathy and lupus nephritis are immune-complex-mediated glomerulonephritides, not pauci-immune.", "D": "Post-streptococcal GN and membranous nephropathy are immune-complex-mediated, not pauci-immune ANCA-associated diseases."}}}, {"id": "anking-immune-responses-135", "fuente": "anking", "tema": 11, "anki": "1478994988572", "q": "Decay accelerating factor (DAF/CD55) and membrane inhibitor of reactive lysis (MIRL/CD59) are anchored to the RBC membrane by which glycolipid anchor?", "o": {"A": "GPI (glycosylphosphatidylinositol)", "B": "Phosphatidylserine", "C": "Sphingomyelin", "D": "Cholesterol"}, "r": "A", "e": {"correcta": "DAF (CD55) and MIRL (CD59) are anchored to the cell membrane via a GPI (glycosylphosphatidylinositol) anchor, which tethers these complement-regulatory proteins to the outer membrane leaflet.", "incorrectas": {"B": "Phosphatidylserine is a membrane phospholipid involved in apoptotic signaling, not a protein anchor.", "C": "Sphingomyelin is a structural membrane lipid, not an anchoring molecule for these proteins.", "D": "Cholesterol is a membrane stabilizing lipid but does not serve as the anchor for CD55/CD59."}}}, {"id": "anking-immune-responses-136", "fuente": "anking", "tema": 11, "anki": "1478994993913", "q": "Absence of GPI anchors on blood cells (with resulting loss of DAF and MIRL) renders cells susceptible to destruction mediated by which system?", "o": {"A": "Complement", "B": "Cell-mediated cytotoxicity (NK cells)", "C": "Antibody-dependent phagocytosis", "D": "Oxidative stress from neutrophils"}, "r": "A", "e": {"correcta": "Without GPI-anchored DAF and MIRL, blood cells lose protection against complement-mediated lysis, resulting in paroxysmal nocturnal hemoglobinuria (PNH).", "incorrectas": {"B": "NK cell-mediated cytotoxicity is not the primary mechanism of cell destruction in PNH.", "C": "Antibody-dependent phagocytosis is not the mechanism; PNH involves unchecked complement activation, not antibody-mediated clearance.", "D": "Neutrophil oxidative burst is not the underlying mechanism of hemolysis in PNH."}}}, {"id": "anking-immune-responses-137", "fuente": "anking", "tema": 11, "anki": "1478995007169", "q": "Paroxysmal nocturnal hemoglobinuria (PNH) classically causes which type of anemia (based on red cell size)?", "o": {"A": "Normocytic anemia", "B": "Macrocytic anemia", "C": "Microcytic anemia (as the primary/classic type)", "D": "Anemia of chronic disease pattern only"}, "r": "A", "e": {"correcta": "PNH is classically a normocytic anemia due to complement-mediated intravascular hemolysis, although chronic iron loss can secondarily cause microcytosis.", "incorrectas": {"B": "Macrocytic anemia is not the classic pattern seen in PNH; it is more typical of B12/folate deficiency.", "C": "While iron deficiency (microcytic) can occur secondarily from chronic hemoglobinuria, the classic/primary anemia of PNH is normocytic.", "D": "PNH is a hemolytic process, not simply anemia of chronic disease."}}}, {"id": "anking-immune-responses-138", "fuente": "anking", "tema": 11, "anki": "1478995010616", "q": "Paroxysmal nocturnal hemoglobinuria is primarily characterized by which type of hemolysis?", "o": {"A": "Intravascular hemolysis", "B": "Extravascular hemolysis", "C": "Hemolysis confined to the spleen only", "D": "Hemolysis mediated exclusively by IgE antibodies"}, "r": "A", "e": {"correcta": "PNH is primarily characterized by intravascular hemolysis due to unchecked complement-mediated lysis of RBCs lacking protective GPI-anchored proteins.", "incorrectas": {"B": "Extravascular hemolysis (in spleen/liver macrophages) is characteristic of conditions like hereditary spherocytosis or warm AIHA, not the primary mechanism in PNH.", "C": "Hemolysis in PNH occurs within the vasculature itself, not confined to splenic destruction.", "D": "PNH hemolysis is complement-mediated, not IgE/mast cell mediated."}}}, {"id": "anking-immune-responses-139", "fuente": "anking", "tema": 11, "anki": "1478995013918", "q": "The intravascular hemolysis of paroxysmal nocturnal hemoglobinuria occurs episodically, often during which activity/state?", "o": {"A": "Sleeping", "B": "Exercise", "C": "Eating", "D": "Sun exposure"}, "r": "A", "e": {"correcta": "Hemolytic episodes in PNH often occur during sleep, likely due to mild respiratory acidosis during sleep that can activate the complement system.", "incorrectas": {"B": "Exercise is not the classic trigger described for PNH hemolytic episodes.", "C": "Eating is not associated with triggering complement activation in PNH.", "D": "Sun exposure triggers hemolysis in conditions like erythropoietic protoporphyria, not PNH."}}}, {"id": "anking-immune-responses-140", "fuente": "anking", "tema": 11, "anki": "1478995020091", "q": "Which test is classically used to screen for paroxysmal nocturnal hemoglobinuria?", "o": {"A": "Sucrose test", "B": "Coombs test (direct antiglobulin test)", "C": "Osmotic fragility test", "D": "Ham's acid hemolysis test as the initial screen only, never sucrose"}, "r": "A", "e": {"correcta": "The sucrose test is used to screen for PNH; sucrose promotes complement activation and binding to RBCs, causing hemolysis of complement-sensitive PNH cells in a low-ionic-strength solution.", "incorrectas": {"B": "The Coombs test detects antibody-mediated hemolysis (autoimmune hemolytic anemia), not complement-mediated PNH.", "C": "The osmotic fragility test is used to diagnose hereditary spherocytosis, not PNH.", "D": "While the acidified serum (Ham) test is a confirmatory test for PNH, the sucrose test is the classic screening test described here."}}}, {"id": "anking-immune-responses-141", "fuente": "anking", "tema": 11, "anki": "1478995028457", "q": "Patients with paroxysmal nocturnal hemoglobinuria can develop abdominal pain, dysphagia, and erectile dysfunction because free hemoglobin acts as a scavenger of which molecule?", "o": {"A": "Nitric oxide", "B": "Prostaglandin E2", "C": "Serotonin", "D": "Acetylcholine"}, "r": "A", "e": {"correcta": "Free hemoglobin released during intravascular hemolysis scavenges nitric oxide, a smooth muscle relaxant, leading to smooth muscle dystonia manifesting as abdominal pain, dysphagia, and erectile dysfunction.", "incorrectas": {"B": "Prostaglandin E2 is not the molecule scavenged by free hemoglobin in this mechanism.", "C": "Serotonin scavenging is not the mechanism implicated in PNH smooth muscle symptoms.", "D": "Acetylcholine is not scavenged by hemoglobin; it is a neurotransmitter unrelated to this mechanism."}}}, {"id": "anking-immune-responses-142", "fuente": "anking", "tema": 11, "anki": "1478995055944", "q": "What is the main cause of death in patients with paroxysmal nocturnal hemoglobinuria?", "o": {"A": "Venous thrombosis", "B": "Sepsis from neutropenia", "C": "Acute renal failure from hemoglobin cast nephropathy", "D": "Hemorrhagic stroke"}, "r": "A", "e": {"correcta": "Venous thrombosis (e.g., hepatic, portal, or cerebral vein thrombosis) is the leading cause of death in PNH, as destroyed platelets release procoagulant cytoplasmic contents into circulation.", "incorrectas": {"B": "While cytopenias occur in PNH, sepsis from neutropenia is not the main cause of death.", "C": "Renal impairment can occur from chronic hemoglobinuria but is not the primary cause of death.", "D": "Hemorrhagic stroke is not the characteristic complication; thrombotic events are far more common in PNH."}}}, {"id": "anking-immune-responses-143", "fuente": "anking", "tema": 11, "anki": "1478995063743", "q": "Which type of anemia, characterized by microcytosis, may develop as a complication of paroxysmal nocturnal hemoglobinuria?", "o": {"A": "Iron deficiency anemia", "B": "Thalassemia", "C": "Sideroblastic anemia", "D": "Anemia of chronic kidney disease"}, "r": "A", "e": {"correcta": "Chronic loss of hemoglobin in the urine (hemoglobinuria) in PNH leads to iron loss over time, resulting in iron deficiency anemia, which is microcytic.", "incorrectas": {"B": "Thalassemia is an inherited hemoglobinopathy unrelated to PNH's iron-loss mechanism.", "C": "Sideroblastic anemia results from defective heme synthesis, not iron loss via hemoglobinuria.", "D": "Anemia of chronic kidney disease results from reduced erythropoietin production, not iron loss."}}}, {"id": "anking-renal-physiology-144", "fuente": "anking", "tema": 12, "anki": "1462054352273", "q": "Which hormone's secretion from the zona glomerulosa is under tonic, but not exclusive, control by ACTH?", "o": {"A": "Aldosterone", "B": "Cortisol", "C": "Renin", "D": "Angiotensin II"}, "r": "A", "e": {"correcta": "Aldosterone secretion from the zona glomerulosa requires ACTH as an essential permissive first step, though its primary regulators are angiotensin II and potassium.", "incorrectas": {"B": "Cortisol is secreted from the zona fasciculata and is under direct, primary (not just tonic) ACTH control.", "C": "Renin is produced by the juxtaglomerular cells of the kidney, not the adrenal cortex.", "D": "Angiotensin II is a circulating peptide hormone, not a secretory product of the zona glomerulosa."}}}, {"id": "anking-renal-physiology-145", "fuente": "anking", "tema": 12, "anki": "1462054842563", "q": "Which hormone increases renal Na+ reabsorption, thereby restoring ECF volume and blood volume to normal?", "o": {"A": "Aldosterone", "B": "Atrial natriuretic peptide", "C": "Cortisol", "D": "Erythropoietin"}, "r": "A", "e": {"correcta": "Aldosterone acts on the distal tubule and collecting duct to increase Na+ (and secondarily water) reabsorption, restoring ECF and blood volume.", "incorrectas": {"B": "ANP promotes natriuresis and volume loss, the opposite effect of aldosterone.", "C": "Cortisol has some mineralocorticoid activity but is not the primary regulator of Na+ reabsorption for volume homeostasis.", "D": "Erythropoietin stimulates red blood cell production and has no direct role in Na+ reabsorption."}}}, {"id": "anking-renal-physiology-146", "fuente": "anking", "tema": 12, "anki": "1462054857059", "q": "To which receptor does angiotensin II bind to exert its main physiologic effects?", "o": {"A": "AT1 receptor", "B": "AT2 receptor", "C": "V1 receptor", "D": "V2 receptor"}, "r": "A", "e": {"correcta": "Angiotensin II binds the AT1 receptor, mediating vasoconstriction, aldosterone secretion, and increased Na+ reabsorption.", "incorrectas": {"B": "AT2 receptors generally oppose AT1 effects (vasodilation, antiproliferative) and are not the primary mediator of angiotensin II's classic actions.", "C": "V1 receptors are targets of vasopressin (ADH), not angiotensin II.", "D": "V2 receptors are also ADH receptors, located on the collecting duct, unrelated to angiotensin II."}}}, {"id": "anking-renal-physiology-147", "fuente": "anking", "tema": 12, "anki": "1462054869905", "q": "Through which secondary messenger system does the angiotensin II-bound AT1 receptor propagate its signal?", "o": {"A": "IP3/Ca2+", "B": "cAMP", "C": "cGMP", "D": "Tyrosine kinase"}, "r": "A", "e": {"correcta": "The AT1 receptor is Gq-coupled, activating phospholipase C to generate IP3 and increase intracellular Ca2+.", "incorrectas": {"B": "cAMP is the second messenger for Gs-coupled receptors such as the V2 receptor for ADH, not AT1.", "C": "cGMP is used by natriuretic peptide and nitric oxide signaling pathways, not AT1.", "D": "Tyrosine kinase signaling is characteristic of receptors like the insulin receptor, not AT1, which is a GPCR."}}}, {"id": "anking-renal-physiology-148", "fuente": "anking", "tema": 12, "anki": "1462054872908", "q": "How does hyperkalemia influence aldosterone secretion?", "o": {"A": "Increased aldosterone secretion", "B": "Decreased aldosterone secretion", "C": "No effect on aldosterone secretion", "D": "Increased renin secretion but no change in aldosterone"}, "r": "A", "e": {"correcta": "Increased K+ depolarizes zona glomerulosa cells, causing Ca2+ influx that stimulates aldosterone synthesis, similarly to angiotensin II signaling.", "incorrectas": {"B": "Hyperkalemia stimulates, rather than suppresses, aldosterone release as a compensatory mechanism to excrete excess potassium.", "C": "Potassium is one of the primary physiologic regulators of aldosterone, so it clearly affects its secretion.", "D": "Hyperkalemia acts directly on the adrenal zona glomerulosa; it does not require renin release to increase aldosterone."}}}, {"id": "anking-renal-physiology-149", "fuente": "anking", "tema": 12, "anki": "1462381603797", "q": "Aldosterone increases reabsorption of which ion (along with H2O) at the distal tubules and collecting duct?", "o": {"A": "Na+", "B": "K+", "C": "Ca2+", "D": "PO43-"}, "r": "A", "e": {"correcta": "Aldosterone upregulates Na+ channels (ENaC) and the Na+/K+-ATPase in principal cells, increasing Na+ (and water) reabsorption, which can cause hypertension.", "incorrectas": {"B": "Aldosterone promotes K+ secretion (loss), not reabsorption.", "C": "Ca2+ reabsorption is primarily regulated by PTH and vitamin D, not aldosterone.", "D": "Phosphate handling is mainly controlled by PTH and FGF23, not aldosterone."}}}, {"id": "anking-renal-physiology-150", "fuente": "anking", "tema": 12, "anki": "1471456202579", "q": "Which system is a slow, hormonally mediated mechanism for regulating arterial pressure?", "o": {"A": "Renin-angiotensin-aldosterone system", "B": "Baroreceptor reflex", "C": "Chemoreceptor reflex", "D": "Cushing reflex"}, "r": "A", "e": {"correcta": "The RAAS is a slow-acting, hormone-based system (renin, angiotensin II, aldosterone) that regulates arterial pressure primarily via blood volume changes over hours to days.", "incorrectas": {"B": "The baroreceptor reflex is a fast, neurally mediated mechanism acting within seconds, not a slow hormonal one.", "C": "Chemoreceptors primarily respond to changes in blood gases and pH, providing rapid neural regulation, not slow hormonal control of pressure.", "D": "The Cushing reflex is an acute response to rising intracranial pressure, not a slow hormonal blood pressure regulator."}}}, {"id": "anking-renal-physiology-151", "fuente": "anking", "tema": 12, "anki": "1471457755859", "q": "The renin-angiotensin-aldosterone system regulates mean arterial pressure primarily by adjusting what parameter?", "o": {"A": "Blood volume", "B": "Heart rate", "C": "Vascular compliance", "D": "Cardiac contractility"}, "r": "A", "e": {"correcta": "RAAS chiefly regulates arterial pressure by modulating renal Na+ and water handling, thereby adjusting circulating blood volume.", "incorrectas": {"B": "Heart rate is primarily regulated by the autonomic nervous system, not RAAS.", "C": "Vascular compliance is a structural/passive vessel property not directly set by RAAS.", "D": "Cardiac contractility is modulated mainly by sympathetic tone and catecholamines, not primarily by RAAS."}}}, {"id": "anking-renal-physiology-152", "fuente": "anking", "tema": 12, "anki": "1471457759434", "q": "The renin-angiotensin-aldosterone system is activated in response to what change in mean arterial pressure?", "o": {"A": "A decrease", "B": "An increase", "C": "No change, only changes in serum osmolarity", "D": "Only changes in serum potassium"}, "r": "A", "e": {"correcta": "A decrease in mean arterial pressure (sensed by the juxtaglomerular apparatus) triggers renin release, activating the RAAS cascade to restore pressure.", "incorrectas": {"B": "An increase in arterial pressure would suppress, not activate, renin release.", "C": "While osmolarity changes affect ADH release, RAAS activation is primarily driven by pressure/volume changes, not osmolarity alone.", "D": "Potassium directly affects aldosterone at the adrenal gland, but RAAS activation as a whole is triggered by decreased arterial pressure."}}}, {"id": "anking-renal-physiology-153", "fuente": "anking", "tema": 12, "anki": "1471457767523", "q": "Which enzyme catalyzes the conversion of angiotensin I to angiotensin II?", "o": {"A": "Angiotensin-converting enzyme (ACE)", "B": "Renin", "C": "Chymase", "D": "Aldosterone synthase"}, "r": "A", "e": {"correcta": "ACE cleaves angiotensin I to form the active peptide angiotensin II, primarily in the pulmonary vasculature.", "incorrectas": {"B": "Renin converts angiotensinogen to angiotensin I, not angiotensin I to angiotensin II.", "C": "Chymase is an alternative (ACE-independent) enzyme that can generate angiotensin II but is not the primary/classic enzyme referenced here.", "D": "Aldosterone synthase catalyzes the final steps of aldosterone synthesis in the adrenal cortex, unrelated to angiotensin conversion."}}}, {"id": "anking-renal-physiology-154", "fuente": "anking", "tema": 12, "anki": "1471457770358", "q": "In which organ does ACE primarily catalyze the conversion of angiotensin I to angiotensin II?", "o": {"A": "Lungs", "B": "Kidneys", "C": "Liver", "D": "Adrenal glands"}, "r": "A", "e": {"correcta": "The pulmonary vascular endothelium has abundant ACE, making the lungs the primary site of angiotensin II generation.", "incorrectas": {"B": "The kidneys are the primary source of renin, not the main site of ACE-mediated conversion.", "C": "The liver produces angiotensinogen, the precursor protein, not the site of ACE activity.", "D": "The adrenal glands are the target organ for angiotensin II (stimulating aldosterone), not the site of its formation."}}}, {"id": "anking-renal-physiology-155", "fuente": "anking", "tema": 12, "anki": "1471457773070", "q": "Angiotensin II stimulates the synthesis and secretion of which hormone by the adrenal cortex?", "o": {"A": "Aldosterone", "B": "Cortisol", "C": "DHEA", "D": "Epinephrine"}, "r": "A", "e": {"correcta": "Angiotensin II acts on the zona glomerulosa to stimulate aldosterone synthesis and secretion, increasing Na+ reabsorption.", "incorrectas": {"B": "Cortisol secretion from the zona fasciculata is primarily driven by ACTH, not angiotensin II.", "C": "DHEA is produced in the zona reticularis under ACTH control, not primarily by angiotensin II.", "D": "Epinephrine is produced by the adrenal medulla in response to sympathetic stimulation, unrelated to angiotensin II."}}}, {"id": "anking-renal-physiology-156", "fuente": "anking", "tema": 12, "anki": "1471457792149", "q": "Angiotensin II increases which exchange process in the proximal convoluted tubule?", "o": {"A": "Na+-H+ exchange", "B": "K+-H+ exchange", "C": "Cl−-HCO3− exchange", "D": "Na+-Ca2+ exchange"}, "r": "A", "e": {"correcta": "Angiotensin II directly stimulates the Na+-H+ exchanger in the proximal tubule, increasing Na+ reabsorption independent of its aldosterone-mediated effects.", "incorrectas": {"B": "K+-H+ exchange is not a major angiotensin II target in the proximal tubule.", "C": "Cl−-HCO3− exchange is involved in acid-base handling in other nephron segments, not the primary angiotensin II effect described.", "D": "Na+-Ca2+ exchange is not the mechanism by which angiotensin II increases proximal tubular Na+ reabsorption."}}}, {"id": "anking-renal-physiology-157", "fuente": "anking", "tema": 12, "anki": "1471457806709", "q": "Angiotensin II increases which sensation via its action on the hypothalamus?", "o": {"A": "Thirst", "B": "Hunger", "C": "Satiety", "D": "Sleepiness"}, "r": "A", "e": {"correcta": "Angiotensin II acts on the hypothalamus (via the organum vasculosum) to stimulate thirst, promoting water intake to help restore blood volume.", "incorrectas": {"B": "Hunger regulation involves hypothalamic centers responsive to leptin and ghrelin, not primarily angiotensin II.", "C": "Satiety is regulated by different hypothalamic signals (e.g., leptin, POMC neurons), not angiotensin II.", "D": "Angiotensin II is not known to promote sleepiness; its hypothalamic effect is on thirst."}}}, {"id": "anking-renal-physiology-158", "fuente": "anking", "tema": 12, "anki": "1471457814120", "q": "What effect does angiotensin II have on arterioles?", "o": {"A": "Constriction", "B": "Dilation", "C": "No effect", "D": "Selective venodilation only"}, "r": "A", "e": {"correcta": "Angiotensin II is a potent vasoconstrictor of arterioles, increasing total peripheral resistance and arterial pressure.", "incorrectas": {"B": "Dilation is the opposite of angiotensin II's known vasoconstrictive effect.", "C": "Angiotensin II has a well-established, potent hemodynamic effect on arterioles, not a neutral one.", "D": "Angiotensin II acts on arterioles causing constriction, not selectively on veins causing dilation."}}}, {"id": "anking-renal-physiology-159", "fuente": "anking", "tema": 12, "anki": "1473385338969", "q": "Decreased O2 delivery to the kidneys due to hypoxia causes increased production of which factor, which then stimulates EPO synthesis?", "o": {"A": "Hypoxia-inducible factor 1α (HIF-1α)", "B": "Angiotensin II", "C": "Vascular endothelial growth factor (VEGF)", "D": "Renin"}, "r": "A", "e": {"correcta": "Renal hypoxia stabilizes HIF-1α in peritubular interstitial fibroblasts, which then drives transcription of the erythropoietin gene.", "incorrectas": {"B": "Angiotensin II is part of the RAAS and is not the transcription factor responsible for EPO induction under hypoxia.", "C": "VEGF is a downstream target of HIF signaling important in angiogenesis, but it is not what stimulates EPO synthesis in this pathway.", "D": "Renin initiates the RAAS cascade for blood pressure regulation, unrelated to hypoxia-driven EPO production."}}}, {"id": "anking-renal-physiology-160", "fuente": "anking", "tema": 12, "anki": "1473385372338", "q": "Erythropoietin (EPO) causes differentiation of which cell type, which undergoes further development into mature erythrocytes?", "o": {"A": "Proerythroblasts", "B": "Megakaryocytes", "C": "Myeloblasts", "D": "Reticulocytes"}, "r": "A", "e": {"correcta": "EPO binds receptors on early erythroid progenitors, promoting their differentiation into proerythroblasts, which mature further into erythrocytes.", "incorrectas": {"B": "Megakaryocytes are the precursors to platelets, regulated by thrombopoietin, not EPO.", "C": "Myeloblasts are precursors of the granulocyte lineage, not the erythroid lineage stimulated by EPO.", "D": "Reticulocytes are already a later maturation stage of the erythroid line, downstream of proerythroblasts, not the cell EPO first differentiates."}}}, {"id": "anking-renal-physiology-161", "fuente": "anking", "tema": 12, "anki": "1473957534401", "q": "Aldosterone increases secretion of which two ions at the distal tubules and collecting duct?", "o": {"A": "K+ and H+", "B": "Na+ and Ca2+", "C": "Cl− and HCO3−", "D": "Mg2+ and PO43-"}, "r": "A", "e": {"correcta": "Aldosterone stimulates principal cells to secrete K+ and intercalated cells to secrete H+, while promoting Na+ reabsorption.", "incorrectas": {"B": "Aldosterone promotes Na+ reabsorption (not secretion), and it does not directly regulate Ca2+ secretion.", "C": "Cl− and HCO3− handling in the collecting duct is not the primary ion secretion effect attributed to aldosterone.", "D": "Mg2+ and PO43- secretion are regulated by other hormonal systems (e.g., PTH, FGF23), not aldosterone."}}}, {"id": "anking-metabolism-162", "fuente": "anking", "tema": 13, "anki": "1464371990594", "q": "Which enzyme metabolizes sorbitol into fructose?", "o": {"A": "Sorbitol dehydrogenase", "B": "Aldose reductase", "C": "Fructokinase", "D": "Hexokinase"}, "r": "A", "e": {"correcta": "Sorbitol dehydrogenase converts sorbitol to fructose; tissues lacking this enzyme (e.g., Schwann cells, lens, retina) are prone to osmotic damage when sorbitol accumulates, as in diabetes.", "incorrectas": {"B": "Aldose reductase converts glucose to sorbitol, the opposite reaction.", "C": "Fructokinase phosphorylates fructose to fructose-1-phosphate, acting downstream of sorbitol dehydrogenase.", "D": "Hexokinase phosphorylates glucose to glucose-6-phosphate and is unrelated to sorbitol metabolism."}}}, {"id": "anking-metabolism-163", "fuente": "anking", "tema": 13, "anki": "1472423439563", "q": "Which stereoisomeric form of amino acids is found in mammalian proteins?", "o": {"A": "D-amino acids", "B": "L-amino acids", "C": "Racemic mixtures", "D": "Meso forms"}, "r": "B", "e": {"correcta": "Only L-amino acids are incorporated into proteins by ribosomes; D-amino acids occur in bacterial cell walls but not in human proteins.", "incorrectas": {"A": "D-amino acids are found in bacterial peptidoglycan, not in human proteins.", "C": "Racemic mixtures contain equal D and L forms, which does not describe protein synthesis.", "D": "Meso compounds are achiral molecules with internal symmetry, not a relevant category here."}}}, {"id": "anking-metabolism-164", "fuente": "anking", "tema": 13, "anki": "1472426358537", "q": "Which amino acids are the branched-chain amino acids (BCAAs)?", "o": {"A": "Valine, Leucine, Isoleucine", "B": "Alanine, Glycine, Serine", "C": "Lysine, Arginine, Histidine", "D": "Phenylalanine, Tyrosine, Tryptophan"}, "r": "A", "e": {"correcta": "Valine, leucine, and isoleucine are the branched-chain amino acids, all essential and metabolized primarily in skeletal muscle.", "incorrectas": {"B": "Alanine, glycine, and serine have small, unbranched side chains.", "C": "Lysine, arginine, and histidine are basic amino acids, not branched-chain.", "D": "Phenylalanine, tyrosine, and tryptophan are aromatic amino acids, not branched-chain."}}}, {"id": "anking-metabolism-165", "fuente": "anking", "tema": 13, "anki": "1472426367341", "q": "Which amino acids serve as precursors to catecholamines and melanin?", "o": {"A": "Tyrosine, Phenylalanine", "B": "Tryptophan, Histidine", "C": "Glutamate, Aspartate", "D": "Lysine, Arginine"}, "r": "A", "e": {"correcta": "Phenylalanine is converted to tyrosine, which is the precursor for dopamine, norepinephrine, epinephrine, and melanin.", "incorrectas": {"B": "Tryptophan gives rise to serotonin and niacin, not catecholamines or melanin; histidine gives rise to histamine.", "C": "Glutamate and aspartate are involved in neurotransmission and the urea cycle, not catecholamine or melanin synthesis.", "D": "Lysine and arginine are basic amino acids involved in collagen crosslinking and the urea cycle/nitric oxide synthesis, not catecholamine synthesis."}}}, {"id": "anking-metabolism-166", "fuente": "anking", "tema": 13, "anki": "1472426371617", "q": "Which amino acid is the precursor to serotonin and niacin?", "o": {"A": "Tryptophan", "B": "Tyrosine", "C": "Histidine", "D": "Glycine"}, "r": "A", "e": {"correcta": "Tryptophan is converted to serotonin (and subsequently melatonin) and can also be used to synthesize niacin (vitamin B3); this pathway requires BH4.", "incorrectas": {"B": "Tyrosine is the precursor to catecholamines and melanin, not serotonin or niacin.", "C": "Histidine is the precursor to histamine, not serotonin or niacin.", "D": "Glycine is used in heme, purine, and creatine synthesis, not serotonin or niacin production."}}}, {"id": "anking-metabolism-167", "fuente": "anking", "tema": 13, "anki": "1472426375356", "q": "Which amino acid is the precursor to histamine?", "o": {"A": "Histidine", "B": "Tryptophan", "C": "Tyrosine", "D": "Arginine"}, "r": "A", "e": {"correcta": "Histidine is decarboxylated by histidine decarboxylase to form histamine; this enzyme remains active at room temperature, contributing to scombroid poisoning in improperly stored fish.", "incorrectas": {"B": "Tryptophan produces serotonin and niacin, not histamine.", "C": "Tyrosine produces catecholamines and melanin, not histamine.", "D": "Arginine is a substrate for nitric oxide and urea cycle intermediates, not histamine."}}}, {"id": "anking-metabolism-168", "fuente": "anking", "tema": 13, "anki": "1472426379400", "q": "Which two amino acids are negatively charged (acidic) at body pH?", "o": {"A": "Aspartate and Glutamate", "B": "Lysine and Arginine", "C": "Serine and Threonine", "D": "Cysteine and Methionine"}, "r": "A", "e": {"correcta": "Aspartate and glutamate have acidic side chains with carboxylic acid groups that are deprotonated and negatively charged at physiologic pH.", "incorrectas": {"B": "Lysine and arginine are basic amino acids that carry a positive charge at body pH.", "C": "Serine and threonine are neutral, hydroxyl-containing amino acids and targets of kinase phosphorylation.", "D": "Cysteine and methionine are neutral, sulfur-containing amino acids."}}}, {"id": "anking-metabolism-169", "fuente": "anking", "tema": 13, "anki": "1472426383267", "q": "Which two amino acids are positively charged (basic) at body pH?", "o": {"A": "Lysine and Arginine", "B": "Aspartate and Glutamate", "C": "Valine and Leucine", "D": "Serine and Threonine"}, "r": "A", "e": {"correcta": "Lysine and arginine have basic side chains that are protonated and positively charged at physiologic pH, with arginine being the most basic amino acid.", "incorrectas": {"B": "Aspartate and glutamate are acidic amino acids, negatively charged at body pH.", "C": "Valine and leucine are branched-chain, nonpolar amino acids with no charge at body pH.", "D": "Serine and threonine are neutral, hydroxyl-containing amino acids."}}}, {"id": "anking-metabolism-170", "fuente": "anking", "tema": 13, "anki": "1472426393413", "q": "What is the charge of the amino acid histidine at body pH?", "o": {"A": "No charge", "B": "Strongly negative", "C": "Strongly positive", "D": "Zwitterionic with net negative charge"}, "r": "A", "e": {"correcta": "Histidine's imidazole side chain has a pKa near physiologic pH, so it is largely uncharged at body pH, though it is still classified as a basic amino acid.", "incorrectas": {"B": "Histidine's side chain is basic, not acidic, so it does not carry a strongly negative charge.", "C": "At body pH histidine's imidazole ring is mostly deprotonated/neutral rather than strongly positive, unlike arginine or lysine.", "D": "While all amino acids exist as zwitterions in solution, histidine's side chain itself is essentially uncharged at body pH, not net negative."}}}, {"id": "anking-metabolism-171", "fuente": "anking", "tema": 13, "anki": "1472426400291", "q": "Which amino acids are the target residues phosphorylated by protein kinase A and protein kinase C?", "o": {"A": "Serine, Threonine", "B": "Tyrosine, Histidine", "C": "Lysine, Arginine", "D": "Cysteine, Methionine"}, "r": "A", "e": {"correcta": "Protein kinase A and protein kinase C are serine/threonine kinases that phosphorylate serine and threonine residues on target proteins.", "incorrectas": {"B": "Tyrosine is phosphorylated by tyrosine kinases (e.g., insulin receptor), not PKA/PKC; histidine is not a typical kinase target in mammalian signaling.", "C": "Lysine and arginine are basic amino acids not phosphorylated by these kinases.", "D": "Cysteine and methionine are sulfur-containing amino acids not targeted by PKA/PKC phosphorylation."}}}, {"id": "anking-metabolism-172", "fuente": "anking", "tema": 13, "anki": "1472426404020", "q": "Which amino acids contain sulfur in their side chains?", "o": {"A": "Cysteine, Methionine", "B": "Serine, Threonine", "C": "Aspartate, Glutamate", "D": "Valine, Isoleucine"}, "r": "A", "e": {"correcta": "Cysteine and methionine both contain sulfur atoms in their side chains; cysteine's thiol group also allows disulfide bond formation.", "incorrectas": {"B": "Serine and threonine contain hydroxyl groups, not sulfur.", "C": "Aspartate and glutamate are acidic amino acids with carboxylic acid side chains, no sulfur.", "D": "Valine and isoleucine are branched-chain nonpolar amino acids without sulfur."}}}, {"id": "anking-metabolism-173", "fuente": "anking", "tema": 13, "anki": "1472426408050", "q": "Which amino acids are considered essential/required during periods of rapid growth (e.g., in children)?", "o": {"A": "Arginine, Histidine", "B": "Alanine, Glutamine", "C": "Tyrosine, Cysteine", "D": "Glycine, Serine"}, "r": "A", "e": {"correcta": "Arginine and histidine are generally classified as non-essential in adults but become essential during periods of rapid growth, such as childhood, due to increased demand.", "incorrectas": {"B": "Alanine and glutamine are non-essential amino acids not classically singled out for growth-related essentiality.", "C": "Tyrosine and cysteine are conditionally non-essential, synthesized from phenylalanine and methionine respectively, but not specifically tied to growth requirements.", "D": "Glycine and serine are non-essential amino acids readily synthesized by the body at all ages."}}}, {"id": "anking-metabolism-174", "fuente": "anking", "tema": 13, "anki": "1472426420971", "q": "Which amino acids are purely ketogenic (not glucogenic)?", "o": {"A": "Leucine, Lysine", "B": "Valine, Methionine", "C": "Alanine, Glycine", "D": "Aspartate, Glutamate"}, "r": "A", "e": {"correcta": "Leucine and lysine are the only two amino acids that are purely ketogenic, being degraded solely into acetyl-CoA/acetoacetate without contributing to gluconeogenesis.", "incorrectas": {"B": "Valine and methionine are glucogenic amino acids, converted to succinyl-CoA.", "C": "Alanine and glycine are glucogenic, feeding into pyruvate for gluconeogenesis.", "D": "Aspartate and glutamate are glucogenic, feeding into oxaloacetate and alpha-ketoglutarate respectively."}}}, {"id": "anking-metabolism-175", "fuente": "anking", "tema": 13, "anki": "1472426425105", "q": "Are the essential amino acids methionine, valine, and histidine ketogenic or glucogenic?", "o": {"A": "Glucogenic", "B": "Ketogenic", "C": "Both ketogenic and glucogenic", "D": "Neither (nitrogen-only metabolism)"}, "r": "A", "e": {"correcta": "Methionine, valine, and histidine are purely glucogenic amino acids, their carbon skeletons being converted into intermediates that can enter gluconeogenesis.", "incorrectas": {"B": "Purely ketogenic amino acids are only leucine and lysine, not this group.", "C": "Amino acids that are both ketogenic and glucogenic include phenylalanine, tyrosine, tryptophan, isoleucine, and threonine, not this trio.", "D": "All amino acids undergo carbon skeleton metabolism beyond just nitrogen handling; these three do contribute carbon to glucose synthesis."}}}, {"id": "anking-metabolism-176", "fuente": "anking", "tema": 13, "anki": "1472426435478", "q": "Are the amino acids phenylalanine, isoleucine, threonine, tryptophan, and tyrosine ketogenic, glucogenic, or both?", "o": {"A": "Both ketogenic and glucogenic", "B": "Purely ketogenic", "C": "Purely glucogenic", "D": "Neither, they are only used for protein synthesis"}, "r": "A", "e": {"correcta": "Phenylalanine, isoleucine, threonine, tryptophan, and tyrosine are classified as both ketogenic and glucogenic since their metabolism yields intermediates usable for both ketone body and glucose synthesis.", "incorrectas": {"B": "Purely ketogenic amino acids are limited to leucine and lysine, not this group.", "C": "Purely glucogenic amino acids include methionine, valine, and histidine, distinct from this group.", "D": "These amino acids are catabolized for energy and metabolic intermediates in addition to their role in protein synthesis."}}}, {"id": "anking-metabolism-177", "fuente": "anking", "tema": 13, "anki": "1472435618038", "q": "What happens to the insulin receptor upon insulin binding that leads to activation of its tyrosine kinase activity?", "o": {"A": "It dimerizes", "B": "It undergoes proteolytic cleavage", "C": "It is internalized into a coated vesicle immediately", "D": "It dissociates into monomeric subunits"}, "r": "A", "e": {"correcta": "Insulin binding causes the insulin receptor to dimerize (or its pre-existing dimer to undergo conformational change), triggering autophosphorylation and activation of its intrinsic tyrosine kinase activity.", "incorrectas": {"B": "Proteolytic cleavage is not the mechanism of insulin receptor activation.", "C": "Receptor internalization occurs later for signal termination/recycling, not as the initial activation step.", "D": "The insulin receptor is normally a disulfide-linked dimer (alpha2-beta2) already; activation involves conformational change and autophosphorylation, not dissociation into monomers."}}}, {"id": "anking-metabolism-178", "fuente": "anking", "tema": 13, "anki": "1472435632014", "q": "Following binding of insulin receptor substrate 1 (IRS-1) to the insulin receptor, proteins with which domain bind to IRS-1?", "o": {"A": "SH2 domain", "B": "PDZ domain", "C": "Death domain", "D": "Bromodomain"}, "r": "A", "e": {"correcta": "SH2 (Src homology 2) domain-containing proteins recognize phosphotyrosine residues on IRS-1, allowing them to bind and propagate the insulin signaling cascade.", "incorrectas": {"B": "PDZ domains mediate protein-protein interactions in scaffolding complexes, typically at cell junctions, not in IRS-1 signaling.", "C": "Death domains are involved in apoptotic signaling complexes (e.g., Fas/TNF receptor signaling), not insulin signaling.", "D": "Bromodomains recognize acetylated lysines in chromatin-associated proteins, unrelated to IRS-1 signaling."}}}, {"id": "anking-metabolism-179", "fuente": "anking", "tema": 13, "anki": "1472435639812", "q": "Which SH2-domain protein, when activated by binding IRS-1, results in translocation of GLUT-4 to the membrane in adipose and muscle tissue?", "o": {"A": "PI3 kinase", "B": "Protein kinase A", "C": "MAP kinase", "D": "Adenylate cyclase"}, "r": "A", "e": {"correcta": "PI3 kinase (phosphoinositide 3-kinase) is recruited via its SH2 domains to phosphorylated IRS-1, activating downstream signaling (via Akt) that drives GLUT-4 translocation to the plasma membrane in muscle and adipose tissue.", "incorrectas": {"B": "Protein kinase A is primarily activated by cAMP-dependent pathways (e.g., glucagon signaling), not by IRS-1 binding.", "C": "MAP kinase is involved in the mitogenic/growth effects of insulin signaling, not primarily GLUT-4 translocation.", "D": "Adenylate cyclase generates cAMP in G-protein coupled receptor signaling and is not part of the insulin receptor SH2-domain cascade."}}}, {"id": "anking-neoplasia-180", "fuente": "anking", "tema": 14, "anki": "1462229092555", "q": "Detection of a germline RET oncogene mutation (MEN 2A/2B) warrants which prophylactic procedure?", "o": {"A": "Thyroidectomy", "B": "Adrenalectomy", "C": "Parathyroidectomy", "D": "Pancreatectomy"}, "r": "A", "e": {"correcta": "A germline RET mutation confers a very high lifetime risk of medullary thyroid carcinoma, so prophylactic thyroidectomy is recommended in these patients.", "incorrectas": {"B": "Adrenalectomy is performed for pheochromocytoma (also seen in MEN2) once diagnosed, not as prophylaxis for the RET mutation itself.", "C": "Parathyroidectomy addresses hyperparathyroidism (MEN2A) but is not the prophylactic procedure indicated by RET mutation detection.", "D": "Pancreatectomy is not associated with RET mutations; it relates to MEN1 pancreatic tumors instead."}}}, {"id": "anking-neoplasia-181", "fuente": "anking", "tema": 14, "anki": "1462818332334", "q": "Amplification/overexpression of which oncogene is classically associated with neuroblastoma?", "o": {"A": "N-myc", "B": "C-myc", "C": "L-myc", "D": "HER2/neu"}, "r": "A", "e": {"correcta": "N-myc amplification is the classic oncogenic driver in neuroblastoma and correlates with poor prognosis.", "incorrectas": {"B": "C-myc is associated with Burkitt lymphoma, not neuroblastoma.", "C": "L-myc is associated with small cell lung carcinoma, not neuroblastoma.", "D": "HER2/neu amplification is associated with breast and gastric adenocarcinoma, not neuroblastoma."}}}, {"id": "anking-neoplasia-182", "fuente": "anking", "tema": 14, "anki": "1463106007081", "q": "HPV infection is an established risk factor for which subtype(s) of cervical carcinoma?", "o": {"A": "Both squamous cell carcinoma and adenocarcinoma", "B": "Only squamous cell carcinoma", "C": "Only adenocarcinoma", "D": "Neither subtype (HPV-independent for both)"}, "r": "A", "e": {"correcta": "HPV (especially high-risk types 16 and 18) is associated with both squamous cell carcinoma and adenocarcinoma of the cervix, making it the driving etiologic agent for cervical cancer overall.", "incorrectas": {"B": "This is incomplete since adenocarcinoma is also HPV-associated (particularly type 18).", "C": "This is incomplete since squamous cell carcinoma, the more common subtype, is also strongly HPV-associated.", "D": "HPV is the major driver of cervical carcinogenesis for both histologic subtypes, not unrelated to either."}}}, {"id": "anking-neoplasia-183", "fuente": "anking", "tema": 14, "anki": "1463172510273", "q": "Which histological finding is classically seen in serous papillary endometrial carcinoma (the sporadic, non-estrogen-driven pathway)?", "o": {"A": "Psammoma bodies", "B": "Reinke crystals", "C": "Call-Exner bodies", "D": "Auer rods"}, "r": "A", "e": {"correcta": "Serous papillary endometrial carcinoma often shows psammoma bodies, which are concentric, laminated calcified structures seen on histology.", "incorrectas": {"B": "Reinke crystals are found in Leydig cell tumors of the testis, not endometrial carcinoma.", "C": "Call-Exner bodies are characteristic of granulosa cell tumors of the ovary.", "D": "Auer rods are seen in acute myeloid leukemia blasts, unrelated to endometrial carcinoma."}}}, {"id": "anking-neoplasia-184", "fuente": "anking", "tema": 14, "anki": "1473536796723", "q": "Nasopharyngeal carcinoma is strongly associated with infection by which virus?", "o": {"A": "Epstein-Barr virus (EBV)", "B": "Human papillomavirus (HPV)", "C": "Hepatitis B virus (HBV)", "D": "Human herpesvirus 8 (HHV-8)"}, "r": "A", "e": {"correcta": "EBV is strongly linked to nasopharyngeal carcinoma, particularly in populations of Southern Chinese and African descent, and to Burkitt lymphoma.", "incorrectas": {"B": "HPV is associated with cervical, oropharyngeal, and anal carcinomas, not nasopharyngeal carcinoma.", "C": "HBV is associated with hepatocellular carcinoma, not nasopharyngeal carcinoma.", "D": "HHV-8 is associated with Kaposi sarcoma, not nasopharyngeal carcinoma."}}}, {"id": "anking-neoplasia-185", "fuente": "anking", "tema": 14, "anki": "1473638489682", "q": "Berylliosis results from prolonged occupational exposure to which agent?", "o": {"A": "Beryllium", "B": "Asbestos", "C": "Silica", "D": "Coal dust"}, "r": "A", "e": {"correcta": "Berylliosis is a granulomatous lung disease caused by chronic exposure to beryllium, seen in workers in aerospace and electronics manufacturing.", "incorrectas": {"B": "Asbestos exposure causes asbestosis and mesothelioma, a distinct entity from berylliosis.", "C": "Silica exposure causes silicosis, a different pneumoconiosis.", "D": "Coal dust exposure causes coal workers' pneumoconiosis, not berylliosis."}}}, {"id": "anking-neoplasia-186", "fuente": "anking", "tema": 14, "anki": "1473732886065", "q": "Which radioactive gas is formed by the decay of uranium present in soil?", "o": {"A": "Radon", "B": "Thoron", "C": "Argon", "D": "Krypton"}, "r": "A", "e": {"correcta": "Radon is a radioactive noble gas produced by the decay chain of uranium naturally present in soil and rock.", "incorrectas": {"B": "Thoron is a decay product of thorium, a related but distinct decay series from uranium.", "C": "Argon is an inert atmospheric gas not produced by uranium decay.", "D": "Krypton is an inert atmospheric gas unrelated to uranium decay chains."}}}, {"id": "anking-neoplasia-187", "fuente": "anking", "tema": 14, "anki": "1473732889878", "q": "Radon gas tends to accumulate in which type of location?", "o": {"A": "Basements", "B": "Rooftops", "C": "Open fields", "D": "High-altitude offices"}, "r": "A", "e": {"correcta": "Being denser than air and seeping up from soil, radon accumulates in enclosed, low-lying spaces such as basements.", "incorrectas": {"B": "Rooftops are open, elevated spaces where radon would readily disperse rather than accumulate.", "C": "Open fields lack the enclosure needed for radon to concentrate.", "D": "High-altitude offices are far from the soil source and well-ventilated, unlike basements."}}}, {"id": "anking-neoplasia-188", "fuente": "anking", "tema": 14, "anki": "1473732893483", "q": "Which source is responsible for most public exposure to ionizing radiation?", "o": {"A": "Radon", "B": "Medical X-rays", "C": "Nuclear power plants", "D": "Cosmic radiation"}, "r": "A", "e": {"correcta": "Radon gas from natural uranium decay in soil is the largest contributor to background ionizing radiation exposure in the general population.", "incorrectas": {"B": "Medical X-rays contribute significantly but are not the largest source of public radiation exposure overall.", "C": "Nuclear power plants contribute a very small fraction of public radiation exposure under normal operation.", "D": "Cosmic radiation contributes to background exposure but is less than radon's contribution."}}}, {"id": "anking-neoplasia-189", "fuente": "anking", "tema": 14, "anki": "1473732897393", "q": "Exposure to which agent is the second most frequent cause of lung carcinoma in the United States?", "o": {"A": "Radon", "B": "Asbestos", "C": "Secondhand smoke", "D": "Air pollution"}, "r": "A", "e": {"correcta": "Radon exposure is the second leading cause of lung cancer in the U.S. after cigarette smoking.", "incorrectas": {"B": "Asbestos increases lung cancer risk, especially synergistically with smoking, but is not the second most frequent cause overall.", "C": "Secondhand smoke is a risk factor for lung cancer but ranks below radon as a cause.", "D": "General air pollution contributes to lung cancer risk but is not the second most frequent cause in the U.S."}}}, {"id": "anking-neoplasia-190", "fuente": "anking", "tema": 14, "anki": "1473732900803", "q": "Increased risk of lung cancer due to radon exposure is particularly notable in which occupational group?", "o": {"A": "Uranium miners", "B": "Coal miners", "C": "Shipyard workers", "D": "Farmers"}, "r": "A", "e": {"correcta": "Uranium miners have markedly increased radon exposure underground, leading to elevated lung cancer risk.", "incorrectas": {"B": "Coal miners are at risk for coal workers' pneumoconiosis, not primarily radon-related lung cancer.", "C": "Shipyard workers have classically elevated asbestos exposure, not radon.", "D": "Farmers are not a classically described high-radon-exposure occupational group."}}}, {"id": "anking-neoplasia-191", "fuente": "anking", "tema": 14, "anki": "1473733443878", "q": "Which histological finding may be associated with mesothelioma?", "o": {"A": "Psammoma bodies", "B": "Councilman bodies", "C": "Mallory bodies", "D": "Negri bodies"}, "r": "A", "e": {"correcta": "Mesothelioma, especially the papillary subtype, may show psammoma bodies (laminated calcific concretions) on histology.", "incorrectas": {"B": "Councilman bodies are apoptotic hepatocytes seen in viral hepatitis and yellow fever, unrelated to mesothelioma.", "C": "Mallory bodies are seen in alcoholic liver disease, not mesothelioma.", "D": "Negri bodies are cytoplasmic inclusions seen in rabies infection, unrelated to mesothelioma."}}}, {"id": "anking-neoplasia-192", "fuente": "anking", "tema": 14, "anki": "1475462985903", "q": "Which renal neoplasm is classically associated with paraneoplastic syndromes?", "o": {"A": "Renal cell carcinoma", "B": "Wilms tumor", "C": "Renal oncocytoma", "D": "Angiomyolipoma"}, "r": "A", "e": {"correcta": "Renal cell carcinoma is well known for producing paraneoplastic syndromes through ectopic hormone secretion, including polycythemia, hypercalcemia, and Stauffer syndrome.", "incorrectas": {"B": "Wilms tumor is a pediatric renal tumor not classically known for paraneoplastic hormone syndromes.", "C": "Renal oncocytoma is a benign tumor not associated with paraneoplastic syndromes.", "D": "Angiomyolipoma is a benign renal tumor associated with tuberous sclerosis, not paraneoplastic syndromes."}}}, {"id": "anking-neoplasia-193", "fuente": "anking", "tema": 14, "anki": "1475462988602", "q": "Renal cell carcinoma may present with which paraneoplastic hematologic finding due to ectopic EPO production?", "o": {"A": "Secondary polycythemia", "B": "Anemia of chronic disease", "C": "Thrombocytopenia", "D": "Neutropenia"}, "r": "A", "e": {"correcta": "Renal cell carcinoma can ectopically secrete erythropoietin, causing secondary polycythemia (elevated red cell mass).", "incorrectas": {"B": "Anemia of chronic disease can occur in malignancy generally but is not the classic EPO-driven paraneoplastic finding here.", "C": "Thrombocytopenia is not the classic paraneoplastic effect of ectopic EPO; EPO raises red cell counts, not lowers platelets.", "D": "Neutropenia is unrelated to ectopic EPO secretion in renal cell carcinoma."}}}, {"id": "anking-neoplasia-194", "fuente": "anking", "tema": 14, "anki": "1475463024437", "q": "Loss of the VHL tumor suppressor gene in renal cell carcinoma leads to increased levels of which growth-promoting factor?", "o": {"A": "IGF-1", "B": "TGF-beta", "C": "EGFR", "D": "FGF23"}, "r": "A", "e": {"correcta": "VHL loss stabilizes HIF, which among other effects increases IGF-1 signaling that promotes tumor cell growth.", "incorrectas": {"B": "TGF-beta is typically a growth inhibitor in normal cells and is not the growth factor classically increased by VHL loss in this pathway.", "C": "EGFR overexpression is important in other cancers (e.g., lung, colorectal) but is not the classic VHL-HIF pathway growth factor.", "D": "FGF23 regulates phosphate homeostasis and is not part of the VHL-HIF-driven growth pathway in RCC."}}}, {"id": "anking-neoplasia-195", "fuente": "anking", "tema": 14, "anki": "1475463026584", "q": "Loss of the VHL tumor suppressor gene in renal cell carcinoma leads to increased activity of which transcription factor, which in turn increases VEGF and PDGF?", "o": {"A": "HIF (hypoxia-inducible factor)", "B": "NF-kB", "C": "p53", "D": "STAT3"}, "r": "A", "e": {"correcta": "VHL normally targets HIF for degradation; its loss causes HIF accumulation, driving transcription of VEGF and PDGF that promote angiogenesis and tumor growth.", "incorrectas": {"B": "NF-kB is involved in inflammatory and immune signaling, not the classic VHL-associated pathway in RCC.", "C": "p53 is a tumor suppressor itself and is not upregulated by VHL loss; it is typically inactivated in other cancers.", "D": "STAT3 is involved in various cytokine signaling pathways but is not the transcription factor classically linked to VHL loss in RCC."}}}, {"id": "anking-neoplasia-196", "fuente": "anking", "tema": 14, "anki": "1480647032473", "q": "HTLV-1 infection (the cause of adult T-cell leukemia/lymphoma, ATLL) is classically associated with which population?", "o": {"A": "IV drug users", "B": "Organ transplant recipients", "C": "Agricultural workers", "D": "Healthcare workers"}, "r": "A", "e": {"correcta": "HTLV-1 is transmitted via blood, sexual contact, and breastfeeding, and is classically associated with IV drug users due to needle-sharing transmission.", "incorrectas": {"B": "Organ transplant recipients are at risk for other infections (e.g., CMV, PTLD) but are not the classic HTLV-1-associated population.", "C": "Agricultural workers are not the classic risk group for HTLV-1/ATLL.", "D": "Healthcare workers are not the classic population associated with HTLV-1 transmission."}}}, {"id": "anking-neoplasia-197", "fuente": "anking", "tema": 14, "anki": "1481335519028", "q": "Gastric MALT lymphomas (MALTomas) may regress with eradication treatment of which organism?", "o": {"A": "Helicobacter pylori", "B": "Epstein-Barr virus", "C": "Helicobacter heilmannii", "D": "Campylobacter jejuni"}, "r": "A", "e": {"correcta": "H. pylori infection drives chronic antigenic stimulation in gastric MALT lymphoma, and antibiotic eradication of H. pylori can cause tumor regression in early-stage disease.", "incorrectas": {"B": "EBV is linked to other lymphomas (e.g., Burkitt, Hodgkin) but is not the organism whose eradication causes gastric MALToma regression.", "C": "H. heilmannii is a rarer cause of gastritis and not the classic organism linked to MALToma regression with treatment.", "D": "Campylobacter jejuni is associated with immunoproliferative small intestinal disease, not gastric MALToma."}}}, {"id": "anking-cardiovascular-pathology-198", "fuente": "anking", "tema": 15, "anki": "1462381664335", "q": "Secondary hyperaldosteronism is caused by activation of which system?", "o": {"A": "Renin-angiotensin system", "B": "Sympathetic nervous system", "C": "Natriuretic peptide system", "D": "Hypothalamic-pituitary-adrenal axis"}, "r": "A", "e": {"correcta": "Secondary hyperaldosteronism results from extra-adrenal activation of the renin-angiotensin system, as seen in renal artery stenosis, JG cell tumors, and edematous states like cirrhosis, heart failure, and nephrotic syndrome.", "incorrectas": {"B": "Sympathetic activation raises renin secretion but is not itself the defining cause of secondary hyperaldosteronism.", "C": "The natriuretic peptide system opposes aldosterone/sodium retention rather than driving it.", "D": "The HPA axis governs cortisol, not aldosterone, secretion."}}}, {"id": "anking-cardiovascular-pathology-199", "fuente": "anking", "tema": 15, "anki": "1471797120815", "q": "What term describes inflammation of the blood vessel wall?", "o": {"A": "Vasculitis", "B": "Atherosclerosis", "C": "Thrombophlebitis", "D": "Arteriosclerosis"}, "r": "A", "e": {"correcta": "Vasculitis is defined as inflammation of the blood vessel wall.", "incorrectas": {"B": "Atherosclerosis is lipid/plaque accumulation in vessel walls, not primarily an inflammatory vasculitic process.", "C": "Thrombophlebitis is inflammation associated with a thrombus in a vein, not a general term for vessel wall inflammation.", "D": "Arteriosclerosis refers to hardening/thickening of arterial walls, not inflammation."}}}, {"id": "anking-cardiovascular-pathology-200", "fuente": "anking", "tema": 15, "anki": "1471806043495", "q": "Which layer forms the innermost part of the arterial wall, consisting of endothelial cells on a basement membrane?", "o": {"A": "Intima", "B": "Media", "C": "Adventitia", "D": "Serosa"}, "r": "A", "e": {"correcta": "The tunica intima is the innermost arterial layer, composed of endothelial cells resting on a basement membrane.", "incorrectas": {"B": "The media is the middle, smooth muscle layer, not the innermost.", "C": "The adventitia is the outermost connective tissue layer.", "D": "The serosa is a serous membrane covering organs, not a layer of the arterial wall."}}}, {"id": "anking-cardiovascular-pathology-201", "fuente": "anking", "tema": 15, "anki": "1471806048024", "q": "Which layer forms the middle part of the arterial wall and consists of smooth muscle?", "o": {"A": "Media", "B": "Intima", "C": "Adventitia", "D": "Endothelium"}, "r": "A", "e": {"correcta": "The tunica media is the middle arterial layer, composed of smooth muscle that regulates vessel tone.", "incorrectas": {"B": "The intima is the innermost endothelial layer, not the muscular middle layer.", "C": "The adventitia is the outer connective tissue layer.", "D": "The endothelium is a single cell layer within the intima, not the muscular media."}}}, {"id": "anking-cardiovascular-pathology-202", "fuente": "anking", "tema": 15, "anki": "1471806052273", "q": "Which layer forms the outer part of the arterial wall and consists of connective tissue surrounding the vessel?", "o": {"A": "Adventitia", "B": "Intima", "C": "Media", "D": "Basement membrane"}, "r": "A", "e": {"correcta": "The tunica adventitia is the outermost layer, composed of connective tissue that surrounds and supports the vessel.", "incorrectas": {"B": "The intima is the innermost endothelial layer.", "C": "The media is the middle smooth muscle layer.", "D": "The basement membrane underlies the endothelium within the intima, not the outer layer."}}}, {"id": "anking-cardiovascular-pathology-203", "fuente": "anking", "tema": 15, "anki": "1471806065717", "q": "Giant cell (temporal) arteritis is classified as which type of vasculitis based on vessel size?", "o": {"A": "Large-vessel vasculitis", "B": "Medium-vessel vasculitis", "C": "Small-vessel vasculitis", "D": "Variable-vessel vasculitis"}, "r": "A", "e": {"correcta": "Giant cell (temporal) arteritis is a large-vessel vasculitis, typically affecting branches of the carotid artery including the temporal artery.", "incorrectas": {"B": "Medium-vessel vasculitis includes conditions like polyarteritis nodosa and Kawasaki disease, not giant cell arteritis.", "C": "Small-vessel vasculitis includes ANCA-associated and immune-complex vasculitides, not giant cell arteritis.", "D": "Variable-vessel vasculitis (e.g., Behçet disease) affects vessels of any size, which is not the classic categorization for giant cell arteritis."}}}, {"id": "anking-cardiovascular-pathology-204", "fuente": "anking", "tema": 15, "anki": "1471806073709", "q": "Which demographic is classically affected by giant cell (temporal) arteritis?", "o": {"A": "Elderly females (>50 years)", "B": "Young Asian females (<40 years)", "C": "Middle-aged men", "D": "Young children"}, "r": "A", "e": {"correcta": "Giant cell (temporal) arteritis classically affects elderly females over age 50.", "incorrectas": {"B": "Young Asian females under 40 are classically affected by Takayasu arteritis, not giant cell arteritis.", "C": "Middle-aged men are classically affected by polyarteritis nodosa.", "D": "Young children are affected by Kawasaki disease, not giant cell arteritis."}}}, {"id": "anking-cardiovascular-pathology-205", "fuente": "anking", "tema": 15, "anki": "1471806078219", "q": "Involvement of the temporal artery in giant cell (temporal) arteritis classically causes what symptom?", "o": {"A": "Unilateral headache", "B": "Bilateral leg claudication", "C": "Hematuria", "D": "Abdominal pain"}, "r": "A", "e": {"correcta": "Temporal artery involvement classically produces a unilateral headache due to inflammation of the vessel supplying the scalp and temporal region.", "incorrectas": {"B": "Bilateral leg claudication suggests peripheral or aortic involvement, not the classic temporal artery presentation.", "C": "Hematuria suggests renal or small-vessel vasculitis involvement, not giant cell arteritis.", "D": "Abdominal pain is more typical of medium-vessel vasculitis such as polyarteritis nodosa."}}}, {"id": "anking-cardiovascular-pathology-206", "fuente": "anking", "tema": 15, "anki": "1471806086201", "q": "Giant cell (temporal) arteritis may present with claudication of which structure?", "o": {"A": "Jaw", "B": "Calf", "C": "Arm", "D": "Tongue base"}, "r": "A", "e": {"correcta": "Jaw claudication, pain with chewing due to ischemia of the muscles of mastication, is a classic finding in giant cell arteritis.", "incorrectas": {"B": "Calf claudication is typical of peripheral arterial disease, not giant cell arteritis.", "C": "Arm claudication suggests subclavian involvement as seen in Takayasu arteritis.", "D": "Tongue claudication can occur but jaw claudication is the classically tested finding."}}}, {"id": "anking-cardiovascular-pathology-207", "fuente": "anking", "tema": 15, "anki": "1471806095511", "q": "Involvement of the ophthalmic artery in giant cell (temporal) arteritis may cause what type of disturbance?", "o": {"A": "Visual disturbances", "B": "Auditory disturbances", "C": "Olfactory disturbances", "D": "Gustatory disturbances"}, "r": "A", "e": {"correcta": "Ophthalmic artery involvement can cause visual disturbances, including sudden vision loss, making prompt treatment critical.", "incorrectas": {"B": "Auditory disturbances are not a classic feature of ophthalmic artery involvement in giant cell arteritis.", "C": "Olfactory disturbances are not associated with this vessel's involvement.", "D": "Gustatory disturbances are not associated with ophthalmic artery ischemia."}}}, {"id": "anking-cardiovascular-pathology-208", "fuente": "anking", "tema": 15, "anki": "1471806114242", "q": "Biopsy of a patient with giant cell (temporal) arteritis classically reveals fibrosis of which layer?", "o": {"A": "Intimal fibrosis", "B": "Adventitial fibrosis", "C": "Medial fibrosis only", "D": "Perivascular fat necrosis"}, "r": "A", "e": {"correcta": "Biopsy in giant cell arteritis classically shows intimal fibrosis along with granulomatous inflammation and giant cells within the vessel wall.", "incorrectas": {"B": "Adventitial fibrosis is not the classic biopsy finding described for this disease.", "C": "Medial fibrosis alone does not capture the characteristic intimal involvement seen in giant cell arteritis.", "D": "Perivascular fat necrosis is not a described feature of giant cell arteritis biopsies."}}}, {"id": "anking-cardiovascular-pathology-209", "fuente": "anking", "tema": 15, "anki": "1471806124315", "q": "Why does diagnosis of giant cell (temporal) arteritis require biopsy of a long vessel segment?", "o": {"A": "Because the lesions are segmental", "B": "Because the lesions are diffuse and continuous", "C": "Because the lesions only occur in the media", "D": "Because the artery is normally very short"}, "r": "A", "e": {"correcta": "The lesions of giant cell arteritis are segmental (skip lesions), so a long segment must be biopsied to avoid a false-negative result; a negative biopsy does not exclude disease.", "incorrectas": {"B": "If the lesions were diffuse and continuous, a short segment biopsy would suffice, contrary to actual practice.", "C": "The lesions are not confined solely to the media; intimal involvement is characteristic.", "D": "The requirement for a long segment relates to the patchy distribution of disease, not the artery's normal length."}}}, {"id": "anking-cardiovascular-pathology-210", "fuente": "anking", "tema": 15, "anki": "1471806144718", "q": "Takayasu arteritis is classified as which type of vasculitis based on vessel size?", "o": {"A": "Large-vessel vasculitis", "B": "Medium-vessel vasculitis", "C": "Small-vessel vasculitis", "D": "Capillary-vessel vasculitis"}, "r": "A", "e": {"correcta": "Takayasu arteritis is a large-vessel vasculitis typically involving the aorta and its major branches.", "incorrectas": {"B": "Medium-vessel vasculitis includes polyarteritis nodosa and Kawasaki disease, not Takayasu arteritis.", "C": "Small-vessel vasculitis affects arterioles, capillaries, and venules, not the large vessels typical of Takayasu.", "D": "Capillary-vessel vasculitis is not a standard classification, and Takayasu spares capillaries."}}}, {"id": "anking-cardiovascular-pathology-211", "fuente": "anking", "tema": 15, "anki": "1471806157855", "q": "Which demographic is classically affected by Takayasu arteritis?", "o": {"A": "Young Asian females (<40 years)", "B": "Elderly females (>50 years)", "C": "Middle-aged men", "D": "Young Caucasian males"}, "r": "A", "e": {"correcta": "Takayasu arteritis classically affects young Asian females under age 40, earning it the nickname 'pulseless disease.'", "incorrectas": {"B": "Elderly females over 50 are classically affected by giant cell arteritis, not Takayasu.", "C": "Middle-aged men are classically affected by polyarteritis nodosa.", "D": "Young Caucasian males are not the classic demographic; Takayasu is most associated with young Asian women."}}}, {"id": "anking-cardiovascular-pathology-212", "fuente": "anking", "tema": 15, "anki": "1471806162437", "q": "Takayasu arteritis may present with which two types of symptoms?", "o": {"A": "Visual and neurologic symptoms", "B": "Cardiac and renal symptoms only", "C": "Gastrointestinal and hepatic symptoms", "D": "Dermatologic and articular symptoms only"}, "r": "A", "e": {"correcta": "Takayasu arteritis, due to involvement of the aortic arch branches, can present with visual and neurologic symptoms, along with fever, night sweats, arthritis, myalgias, and skin nodules.", "incorrectas": {"B": "Cardiac and renal symptoms can occur but are not the paired findings highlighted as classic for this presentation.", "C": "Gastrointestinal and hepatic symptoms are not characteristic features of Takayasu arteritis.", "D": "Dermatologic and articular symptoms may occur as additional features but are not the primary paired symptom set described."}}}, {"id": "anking-cardiovascular-pathology-213", "fuente": "anking", "tema": 15, "anki": "1471806184543", "q": "What is the treatment of choice for a patient with Takayasu arteritis?", "o": {"A": "Corticosteroids", "B": "Methotrexate alone", "C": "Aspirin alone", "D": "Antibiotics"}, "r": "A", "e": {"correcta": "Corticosteroids are the mainstay treatment for Takayasu arteritis to suppress vascular inflammation.", "incorrectas": {"B": "Methotrexate may be used as a steroid-sparing agent in refractory cases but is not the primary first-line treatment.", "C": "Aspirin alone does not address the underlying inflammatory process driving the disease.", "D": "Antibiotics have no role since Takayasu arteritis is not an infectious process."}}}, {"id": "anking-cardiovascular-pathology-214", "fuente": "anking", "tema": 15, "anki": "1471806188325", "q": "Polyarteritis nodosa is classified as which type of vasculitis based on vessel size?", "o": {"A": "Medium-vessel vasculitis", "B": "Large-vessel vasculitis", "C": "Small-vessel vasculitis", "D": "Venous-only vasculitis"}, "r": "A", "e": {"correcta": "Polyarteritis nodosa is an immune-complex-mediated medium-vessel vasculitis.", "incorrectas": {"B": "Large-vessel vasculitis includes giant cell and Takayasu arteritis, not polyarteritis nodosa.", "C": "Small-vessel vasculitis includes ANCA-associated conditions, not polyarteritis nodosa.", "D": "Polyarteritis nodosa affects arteries, not exclusively veins."}}}, {"id": "anking-cardiovascular-pathology-215", "fuente": "anking", "tema": 15, "anki": "1471806197883", "q": "Which demographic is classically affected by polyarteritis nodosa?", "o": {"A": "Middle-aged men", "B": "Young Asian females (<40 years)", "C": "Elderly females (>50 years)", "D": "Infants and toddlers"}, "r": "A", "e": {"correcta": "Polyarteritis nodosa classically affects middle-aged men and is associated with hepatitis B infection in some cases.", "incorrectas": {"B": "Young Asian females are the classic demographic for Takayasu arteritis, not polyarteritis nodosa.", "C": "Elderly females are the classic demographic for giant cell arteritis, not polyarteritis nodosa.", "D": "Infants and toddlers are classically affected by Kawasaki disease, not polyarteritis nodosa."}}}, {"id": "anking-musculoskeletal-pathology-216", "fuente": "anking", "tema": 16, "anki": "1463279694569", "q": "Spontaneous abortion is more common in patients with which type of hemostatic state, as seen in antiphospholipid syndrome?", "o": {"A": "Hypercoagulable state", "B": "Hypocoagulable state", "C": "Hemodilutional state", "D": "Hypofibrinogenemic state"}, "r": "A", "e": {"correcta": "Antiphospholipid syndrome produces a hypercoagulable state due to antiphospholipid antibodies (e.g., lupus anticoagulant, anticardiolipin), which increases the risk of thrombosis and recurrent spontaneous abortion. Other risk factors for spontaneous abortion include congenital infection and teratogen exposure.", "incorrectas": {"B": "A hypocoagulable state would predispose to bleeding, not the thrombotic complications and pregnancy loss seen in antiphospholipid syndrome.", "C": "Hemodilution is not a recognized mechanism of pregnancy loss in antiphospholipid syndrome.", "D": "Low fibrinogen would impair, not promote, clot formation, which is the opposite of the pathophysiology in antiphospholipid syndrome."}}}, {"id": "anking-musculoskeletal-pathology-217", "fuente": "anking", "tema": 16, "anki": "1475363908883", "q": "Which type of nephrotic syndrome is a patient with systemic lupus erythematosus (SLE) most likely to develop?", "o": {"A": "Membranous nephropathy", "B": "Minimal change disease", "C": "Focal segmental glomerulosclerosis", "D": "Membranoproliferative glomerulonephritis"}, "r": "A", "e": {"correcta": "Membranous nephropathy is the classic nephrotic-range renal manifestation of SLE, characterized by subepithelial immune complex deposits causing a 'spike and dome' appearance on electron microscopy.", "incorrectas": {"B": "Minimal change disease is typically idiopathic or associated with Hodgkin lymphoma, not a classic lupus nephropathy.", "C": "Focal segmental glomerulosclerosis is more commonly associated with HIV, heroin use, or obesity rather than being the classic lupus nephrotic pattern.", "D": "Membranoproliferative glomerulonephritis can occur in lupus but is not the classic nephrotic syndrome pattern associated with SLE; it more often presents with a mixed nephrotic/nephritic picture."}}}, {"id": "anking-musculoskeletal-pathology-218", "fuente": "anking", "tema": 16, "anki": "1475376588139", "q": "Which type of nephritic syndrome is a patient with SLE most likely to develop?", "o": {"A": "Diffuse proliferative glomerulonephritis", "B": "IgA nephropathy", "C": "Post-streptococcal glomerulonephritis", "D": "Goodpasture syndrome (anti-GBM disease)"}, "r": "A", "e": {"correcta": "Diffuse proliferative glomerulonephritis is the most common and most severe renal manifestation of SLE, resulting from subendothelial immune complex deposition and causing nephritic-range disease.", "incorrectas": {"B": "IgA nephropathy is a distinct primary glomerular disease, typically following mucosal infections, not the classic lupus nephritis pattern.", "C": "Post-streptococcal glomerulonephritis follows streptococcal infection and is unrelated to SLE.", "D": "Goodpasture syndrome is caused by anti-glomerular basement membrane antibodies, a distinct mechanism from the immune complex disease seen in lupus nephritis."}}}, {"id": "anking-musculoskeletal-pathology-219", "fuente": "anking", "tema": 16, "anki": "1475376595559", "q": "Diffuse proliferative glomerulonephritis is a common cause of death in patients with which autoimmune disease?", "o": {"A": "Systemic lupus erythematosus", "B": "Rheumatoid arthritis", "C": "Sjögren syndrome", "D": "Systemic sclerosis (scleroderma)"}, "r": "A", "e": {"correcta": "Diffuse proliferative glomerulonephritis is the most common and most severe form of lupus nephritis and is a leading cause of morbidity and mortality in SLE patients.", "incorrectas": {"B": "Rheumatoid arthritis primarily causes joint destruction and is not classically associated with diffuse proliferative glomerulonephritis as a major cause of death.", "C": "Sjögren syndrome mainly affects exocrine glands and is not typically associated with this renal pathology as a leading cause of death.", "D": "Systemic sclerosis causes renal crisis via vascular pathology (malignant hypertension), not classic immune complex diffuse proliferative glomerulonephritis."}}}, {"id": "anking-musculoskeletal-pathology-220", "fuente": "anking", "tema": 16, "anki": "1475704608986", "q": "A deficiency of which electrolyte causes bone loss, osteomalacia in adults, and rickets in children?", "o": {"A": "Phosphate (PO4 3-)", "B": "Calcium (Ca2+)", "C": "Magnesium (Mg2+)", "D": "Potassium (K+)"}, "r": "A", "e": {"correcta": "Low phosphate impairs mineralization of osteoid, leading to defective bone mineralization that manifests as osteomalacia in adults and rickets in children.", "incorrectas": {"B": "While calcium is also important for mineralization, this card specifically identifies phosphate as the electrolyte in question.", "C": "Magnesium deficiency can cause secondary hypocalcemia but is not the classic cause of osteomalacia/rickets described here.", "D": "Potassium disturbances affect cardiac and neuromuscular function, not bone mineralization."}}}, {"id": "anking-musculoskeletal-pathology-221", "fuente": "anking", "tema": 16, "anki": "1485127545269", "q": "Which anti-epileptic drug may be used to treat peripheral neuropathy and fibromyalgia (chronic pain)?", "o": {"A": "Gabapentin", "B": "Phenytoin", "C": "Valproic acid", "D": "Lamotrigine"}, "r": "A", "e": {"correcta": "Gabapentin, an anti-epileptic that modulates voltage-gated calcium channels, is commonly used off-label for neuropathic pain conditions such as peripheral neuropathy and fibromyalgia.", "incorrectas": {"B": "Phenytoin is primarily used for seizure control and is not a first-line choice for fibromyalgia or peripheral neuropathy.", "C": "Valproic acid is used for epilepsy, bipolar disorder, and migraine prophylaxis, not typically for fibromyalgia.", "D": "Lamotrigine is used mainly for seizures and bipolar disorder, not as a standard treatment for peripheral neuropathy or fibromyalgia."}}}, {"id": "anking-musculoskeletal-pathology-222", "fuente": "anking", "tema": 16, "anki": "1487815304836", "q": "Which demographic group is most commonly associated with systemic lupus erythematosus (SLE)?", "o": {"A": "Middle-aged females", "B": "Elderly males", "C": "Young males", "D": "Prepubescent children of either sex"}, "r": "A", "e": {"correcta": "SLE predominantly affects middle-aged females, reflecting a strong female predominance; the female bias is less pronounced in children and older adults.", "incorrectas": {"B": "Elderly males are not the typical demographic; SLE shows a strong female predominance rather than affecting men preferentially.", "C": "Young males are not the classic demographic for SLE; the disease favors females, particularly in the reproductive/middle-aged years.", "D": "While SLE can occur in children, this is not the demographic with the strongest association, and the female bias is actually less dramatic in children."}}}, {"id": "anking-musculoskeletal-pathology-223", "fuente": "anking", "tema": 16, "anki": "1487815310898", "q": "Which ethnicities are more commonly affected by SLE?", "o": {"A": "African Americans and Hispanics", "B": "Caucasians and Scandinavians", "C": "East Asians and Ashkenazi Jews only", "D": "Native Americans exclusively"}, "r": "A", "e": {"correcta": "SLE has a higher prevalence and often more severe disease course in African Americans and Hispanic populations compared to other ethnic groups.", "incorrectas": {"B": "Caucasian populations, particularly of Northern European descent, have lower rates of SLE compared to African American and Hispanic populations.", "C": "While SLE occurs in East Asian populations, this option incorrectly limits and mischaracterizes the ethnic groups with the highest recognized risk.", "D": "SLE is not exclusive to Native Americans; African Americans and Hispanics are the ethnicities classically noted for higher risk."}}}, {"id": "anking-musculoskeletal-pathology-224", "fuente": "anking", "tema": 16, "anki": "1487815313912", "q": "What type of hypersensitivity reaction is systemic lupus erythematosus (SLE) primarily classified as?", "o": {"A": "Type III hypersensitivity (immune complex deposition)", "B": "Type I hypersensitivity (IgE-mediated)", "C": "Type II hypersensitivity (antibody-mediated cytotoxicity)", "D": "Type IV hypersensitivity (T cell-mediated)"}, "r": "A", "e": {"correcta": "SLE is primarily a type III hypersensitivity reaction due to immune complex deposition in tissues such as the kidneys and skin; an exception is the hematologic complications (anemia, thrombocytopenia, leukopenia), which are type II reactions.", "incorrectas": {"B": "Type I hypersensitivity is IgE-mediated and involves mast cell degranulation, as seen in allergies and anaphylaxis, not SLE.", "C": "Type II hypersensitivity is the mechanism behind SLE's hematologic complications specifically, not the primary overall classification of the disease.", "D": "Type IV hypersensitivity is T cell-mediated (delayed-type), as seen in contact dermatitis or tuberculin reactions, not the primary mechanism in SLE."}}}, {"id": "anking-musculoskeletal-pathology-225", "fuente": "anking", "tema": 16, "anki": "1487815330412", "q": "What is the most common and most severe form of renal disease in patients with SLE?", "o": {"A": "Diffuse proliferative glomerulonephritis (DPGN)", "B": "Minimal change disease", "C": "Focal segmental glomerulosclerosis", "D": "Amyloidosis"}, "r": "A", "e": {"correcta": "Diffuse proliferative glomerulonephritis is the most common and most severe form of lupus nephritis; patients may also have coexisting membranous glomerulonephritis.", "incorrectas": {"B": "Minimal change disease is not a typical or severe manifestation of lupus nephritis.", "C": "Focal segmental glomerulosclerosis is not the classic or most common renal lesion in SLE.", "D": "Renal amyloidosis is associated with chronic inflammatory conditions and plasma cell dyscrasias, not classically with SLE."}}}, {"id": "anking-musculoskeletal-pathology-226", "fuente": "anking", "tema": 16, "anki": "1487815337003", "q": "What type of endocarditis is associated with SLE?", "o": {"A": "Libman-Sacks endocarditis", "B": "Infective (bacterial) endocarditis", "C": "Marantic (nonbacterial thrombotic) endocarditis of malignancy", "D": "Rheumatic endocarditis"}, "r": "A", "e": {"correcta": "Libman-Sacks endocarditis is a nonbacterial, verrucous endocarditis characterized by sterile vegetations on the mitral and/or aortic valve, classically associated with SLE.", "incorrectas": {"B": "Infective endocarditis is caused by bacterial infection of heart valves, not by lupus-associated immune mechanisms.", "C": "Marantic endocarditis is associated with malignancy and hypercoagulable states from cancer, a distinct entity from the lupus-specific Libman-Sacks endocarditis.", "D": "Rheumatic endocarditis follows rheumatic fever due to streptococcal infection, not SLE."}}}, {"id": "anking-musculoskeletal-pathology-227", "fuente": "anking", "tema": 16, "anki": "1487815353788", "q": "Which SLE-associated antibody is a useful predictor of disease activity and renal involvement?", "o": {"A": "Anti-dsDNA antibodies", "B": "Anti-histone antibodies", "C": "Anti-centromere antibodies", "D": "Anti-Jo-1 antibodies"}, "r": "A", "e": {"correcta": "Anti-dsDNA antibody titers correlate with disease activity and are particularly useful for monitoring renal involvement (lupus nephritis) in SLE.", "incorrectas": {"B": "Anti-histone antibodies are characteristic of drug-induced lupus, not a marker of disease activity in SLE.", "C": "Anti-centromere antibodies are associated with limited cutaneous systemic sclerosis (CREST syndrome), not SLE.", "D": "Anti-Jo-1 antibodies are associated with polymyositis/dermatomyositis, not SLE."}}}, {"id": "anking-musculoskeletal-pathology-228", "fuente": "anking", "tema": 16, "anki": "1487815356381", "q": "SLE is characterized by which change in complement levels of C3 and C4?", "o": {"A": "Decreased levels", "B": "Increased levels", "C": "No change in levels", "D": "Increased C3 with decreased C4 only"}, "r": "A", "e": {"correcta": "Active SLE is characterized by decreased C3 and C4 levels due to consumption during immune complex formation.", "incorrectas": {"B": "Increased complement levels would not reflect the consumptive process occurring with immune complex formation in active lupus.", "C": "Complement levels are not unchanged in active SLE; they decrease due to consumption in immune complex reactions.", "D": "Both C3 and C4 are decreased in SLE, not selectively one over the other."}}}, {"id": "anking-musculoskeletal-pathology-229", "fuente": "anking", "tema": 16, "anki": "1487815366607", "q": "SLE is characterized by which change in CH50 (total hemolytic complement) levels?", "o": {"A": "Decreased levels", "B": "Increased levels", "C": "Normal levels", "D": "Levels that fluctuate unpredictably with no clinical correlation"}, "r": "A", "e": {"correcta": "CH50 is decreased in SLE due to consumption of complement components during immune complex formation, similar to the decreases seen in C3 and C4.", "incorrectas": {"B": "Increased CH50 would not be consistent with a consumptive complement process as occurs in active lupus.", "C": "CH50 levels are not normal in active SLE; they are decreased due to ongoing complement consumption.", "D": "CH50 levels do correlate with disease activity in lupus, decreasing with active immune complex-mediated inflammation, rather than fluctuating without correlation."}}}, {"id": "anking-musculoskeletal-pathology-230", "fuente": "anking", "tema": 16, "anki": "1487815392099", "q": "Is the elevated PTT caused by lupus anticoagulant correctable by addition of normal plasma (mixing study)?", "o": {"A": "No, the PTT remains elevated", "B": "Yes, the PTT fully corrects", "C": "Yes, but only after a 2-hour incubation", "D": "Partially, correcting to half the baseline value"}, "r": "A", "e": {"correcta": "Lupus anticoagulant is an inhibitor, so the elevated PTT is not corrected by mixing with normal plasma; this is an important distinguishing feature from clotting factor deficiencies, which do correct with normal plasma.", "incorrectas": {"B": "Full correction would indicate a factor deficiency rather than the presence of an inhibitor like lupus anticoagulant.", "C": "Lupus anticoagulant does not correct even with incubation; this pattern would be more suggestive of a factor VIII inhibitor with time-dependent effect.", "D": "There is no partial correction pattern classically described for lupus anticoagulant; the hallmark is non-correction on mixing studies."}}}, {"id": "anking-musculoskeletal-pathology-231", "fuente": "anking", "tema": 16, "anki": "1487815398186", "q": "Antiphospholipid syndrome can occur as a primary disorder or as a secondary disorder associated with which condition?", "o": {"A": "Systemic lupus erythematosus (SLE)", "B": "Rheumatoid arthritis", "C": "Type 1 diabetes mellitus", "D": "Hashimoto thyroiditis"}, "r": "A", "e": {"correcta": "Antiphospholipid syndrome is most commonly seen as a primary disorder but can also occur secondary to SLE.", "incorrectas": {"B": "Rheumatoid arthritis is not the classic secondary association for antiphospholipid syndrome.", "C": "Type 1 diabetes is an autoimmune condition but is not classically linked to secondary antiphospholipid syndrome.", "D": "Hashimoto thyroiditis is not the classic secondary association described for antiphospholipid syndrome."}}}, {"id": "anking-musculoskeletal-pathology-232", "fuente": "anking", "tema": 16, "anki": "1487815405384", "q": "Antiphospholipid syndrome is characterized by what type of coagulable state, increasing the risk of thrombosis and recurrent pregnancy loss?", "o": {"A": "Hypercoagulable state", "B": "Hypocoagulable state", "C": "Euvolemic coagulable state", "D": "Dilutional coagulopathy state"}, "r": "A", "e": {"correcta": "Antiphospholipid syndrome produces a hypercoagulable state, increasing the risk for thrombosis (arterial and venous) and recurrent pregnancy loss.", "incorrectas": {"B": "A hypocoagulable state would cause bleeding tendencies, which is the opposite of the thrombotic risk seen in antiphospholipid syndrome.", "C": "There is no such standard classification as 'euvolemic coagulable state' relevant to antiphospholipid syndrome.", "D": "Dilutional coagulopathy occurs with massive transfusion or fluid resuscitation, not the pathophysiology of antiphospholipid syndrome."}}}, {"id": "anking-musculoskeletal-pathology-233", "fuente": "anking", "tema": 16, "anki": "1487815417093", "q": "What is the treatment for antiphospholipid syndrome?", "o": {"A": "Anticoagulants", "B": "High-dose corticosteroids alone", "C": "Antiplatelet agents alone (e.g., aspirin monotherapy in all cases)", "D": "Intravenous immunoglobulin (IVIG) as first-line therapy"}, "r": "A", "e": {"correcta": "Anticoagulation is the mainstay of treatment for antiphospholipid syndrome to prevent recurrent thrombotic events.", "incorrectas": {"B": "Corticosteroids alone do not address the thrombotic risk and are not the standard treatment for antiphospholipid syndrome itself.", "C": "While aspirin may be used in some contexts, anticoagulants (e.g., warfarin/heparin) are the primary treatment, not antiplatelet monotherapy alone.", "D": "IVIG is not a first-line treatment for antiphospholipid syndrome; it is reserved for select refractory or pregnancy-related cases."}}}, {"id": "anking-respiratory-pathology-234", "fuente": "anking", "tema": 17, "anki": "1473535947702", "q": "Which condition is defined as inflammation of the nasal mucosa?", "o": {"A": "Rhinitis", "B": "Sinusitis", "C": "Pharyngitis", "D": "Laryngitis"}, "r": "A", "e": {"correcta": "Rhinitis is by definition inflammation of the nasal mucosa, commonly caused by viral infection or allergy.", "incorrectas": {"B": "Sinusitis refers to inflammation of the paranasal sinuses, not the nasal mucosa itself.", "C": "Pharyngitis is inflammation of the pharynx (throat), a distinct anatomic site.", "D": "Laryngitis is inflammation of the larynx, not the nasal mucosa."}}}, {"id": "anking-respiratory-pathology-235", "fuente": "anking", "tema": 17, "anki": "1473536750240", "q": "What is the most common cause of rhinitis (the common cold)?", "o": {"A": "Rhinovirus", "B": "Respiratory syncytial virus", "C": "Adenovirus", "D": "Influenza virus"}, "r": "A", "e": {"correcta": "Rhinovirus is the most common cause of rhinitis/the common cold, accounting for the majority of cases.", "incorrectas": {"B": "RSV more classically causes bronchiolitis in infants, not the typical common cold.", "C": "Adenovirus can cause upper respiratory infections and conjunctivitis but is a less common cause of rhinitis than rhinovirus.", "D": "Influenza virus causes a more systemic illness (fever, myalgias) rather than the typical common cold picture."}}}, {"id": "anking-respiratory-pathology-236", "fuente": "anking", "tema": 17, "anki": "1473536754044", "q": "Which condition presents with sneezing, congestion, and runny nose, characteristic of the common cold?", "o": {"A": "Rhinitis", "B": "Epiglottitis", "C": "Nasopharyngeal carcinoma", "D": "Croup"}, "r": "A", "e": {"correcta": "Rhinitis presents classically with sneezing, nasal congestion, and rhinorrhea, the hallmark of the common cold.", "incorrectas": {"B": "Epiglottitis presents with drooling, muffled voice, and stridor, not sneezing/congestion.", "C": "Nasopharyngeal carcinoma presents with cervical lymphadenopathy and nasal obstruction, not an acute cold-like picture.", "D": "Croup presents with a barking cough and inspiratory stridor, not typical cold symptoms."}}}, {"id": "anking-respiratory-pathology-237", "fuente": "anking", "tema": 17, "anki": "1473536759678", "q": "Allergic rhinitis is characterized by an inflammatory infiltrate composed predominantly of which cell type?", "o": {"A": "Eosinophils", "B": "Neutrophils", "C": "Plasma cells", "D": "Mast cells alone"}, "r": "A", "e": {"correcta": "Allergic rhinitis is a type I hypersensitivity reaction characterized by an eosinophil-rich inflammatory infiltrate in the nasal mucosa.", "incorrectas": {"B": "Neutrophils are more typical of acute bacterial infections, not allergic rhinitis.", "C": "Plasma cells are not the characteristic infiltrate of allergic rhinitis.", "D": "While mast cells trigger the immediate reaction via IgE, the infiltrate classically described is eosinophilic, not isolated mast cells."}}}, {"id": "anking-respiratory-pathology-238", "fuente": "anking", "tema": 17, "anki": "1473536767081", "q": "What are protrusions of edematous, inflamed nasal mucosa called?", "o": {"A": "Nasal polyps", "B": "Angiofibromas", "C": "Nasopharyngeal carcinoma", "D": "Adenoid hypertrophy"}, "r": "A", "e": {"correcta": "Nasal polyps are protrusions of edematous, chronically inflamed nasal mucosa, often from recurrent rhinitis.", "incorrectas": {"B": "Angiofibromas are benign vascular tumors, not simple mucosal protrusions from inflammation.", "C": "Nasopharyngeal carcinoma is a malignant epithelial tumor, not a benign inflammatory mucosal protrusion.", "D": "Adenoid hypertrophy refers to enlargement of pharyngeal tonsillar tissue, not nasal mucosal polyps."}}}, {"id": "anking-respiratory-pathology-239", "fuente": "anking", "tema": 17, "anki": "1473536769801", "q": "Nasal polyps are usually secondary to repeated bouts of which condition?", "o": {"A": "Rhinitis", "B": "Sinusitis-only fungal infection", "C": "Nasopharyngeal carcinoma", "D": "Epiglottitis"}, "r": "A", "e": {"correcta": "Nasal polyps typically arise from chronic or repeated bouts of rhinitis causing persistent mucosal edema and inflammation.", "incorrectas": {"B": "While sinus disease can coexist, the classic association taught is with recurrent rhinitis, not isolated fungal sinusitis.", "C": "Nasopharyngeal carcinoma is a separate malignant process, not a precursor causing polyps.", "D": "Epiglottitis affects the epiglottis/larynx and is unrelated to nasal polyp formation."}}}, {"id": "anking-respiratory-pathology-240", "fuente": "anking", "tema": 17, "anki": "1473536772473", "q": "In children, nasal polyps are classically associated with which underlying condition?", "o": {"A": "Cystic fibrosis", "B": "Aspirin-induced asthma", "C": "Kartagener syndrome only", "D": "Chronic granulomatous disease"}, "r": "A", "e": {"correcta": "In children, nasal polyps are classically associated with cystic fibrosis, and any child with nasal polyps should be evaluated for CF.", "incorrectas": {"B": "Aspirin-induced asthma is the classic association in adults, not children.", "C": "Kartagener syndrome (primary ciliary dyskinesia) can cause sinus disease but is not the classic pediatric association tested for nasal polyps.", "D": "Chronic granulomatous disease predisposes to infections with catalase-positive organisms, not specifically nasal polyps."}}}, {"id": "anking-respiratory-pathology-241", "fuente": "anking", "tema": 17, "anki": "1473536775019", "q": "In adults, nasal polyps are classically associated with which condition?", "o": {"A": "Aspirin-induced asthma", "B": "Cystic fibrosis", "C": "Nasopharyngeal carcinoma", "D": "Kartagener syndrome"}, "r": "A", "e": {"correcta": "In adults, nasal polyps are classically associated with aspirin-induced (aspirin-intolerant) asthma.", "incorrectas": {"B": "Cystic fibrosis is the classic pediatric association, not the adult one.", "C": "Nasopharyngeal carcinoma is a distinct malignant tumor, not linked to polyp formation via this mechanism.", "D": "Kartagener syndrome is not the classic adult association taught for nasal polyps."}}}, {"id": "anking-respiratory-pathology-242", "fuente": "anking", "tema": 17, "anki": "1473536778562", "q": "Which condition is characterized by the triad of asthma, aspirin-induced bronchospasm, and nasal polyps?", "o": {"A": "Aspirin-induced asthma", "B": "Churg-Strauss syndrome", "C": "Samter's triad variant (allergic rhinitis)", "D": "Loeffler syndrome"}, "r": "A", "e": {"correcta": "Aspirin-induced (aspirin-intolerant) asthma presents as a triad of asthma, aspirin-induced bronchospasm, and nasal polyps, due to shunting of arachidonic acid toward the leukotriene pathway.", "incorrectas": {"B": "Churg-Strauss syndrome (eosinophilic granulomatosis with polyangiitis) involves vasculitis and eosinophilia, a distinct systemic disease.", "C": "Allergic rhinitis alone does not comprise this specific triad with aspirin sensitivity.", "D": "Loeffler syndrome involves transient pulmonary infiltrates with eosinophilia, unrelated to this triad."}}}, {"id": "anking-respiratory-pathology-243", "fuente": "anking", "tema": 17, "anki": "1473536785588", "q": "What are benign tumors of the nasal mucosa composed of large blood vessels and fibrous tissue called?", "o": {"A": "Angiofibromas", "B": "Nasal polyps", "C": "Nasopharyngeal carcinoma", "D": "Hemangiomas of the skin"}, "r": "A", "e": {"correcta": "Angiofibromas are benign, highly vascular tumors of the nasal mucosa composed of large blood vessels and fibrous stroma.", "incorrectas": {"B": "Nasal polyps are edematous inflammatory mucosal protrusions, not true vascular neoplasms.", "C": "Nasopharyngeal carcinoma is a malignant epithelial tumor, not a benign vascular one.", "D": "Cutaneous hemangiomas are a different entity located in the skin, not nasal mucosa."}}}, {"id": "anking-respiratory-pathology-244", "fuente": "anking", "tema": 17, "anki": "1473536788532", "q": "Which demographic is classically associated with angiofibroma?", "o": {"A": "Adolescent males", "B": "Elderly females", "C": "Young children of either sex", "D": "Middle-aged smokers"}, "r": "A", "e": {"correcta": "Angiofibromas classically occur in adolescent males, presenting with profuse epistaxis.", "incorrectas": {"B": "Elderly females are not the classic demographic; angiofibroma is a disease of young males.", "C": "Angiofibroma is not typically seen in young children of either sex; it is specific to adolescent males.", "D": "Middle-aged smokers are more associated with malignancies like squamous cell carcinoma, not angiofibroma."}}}, {"id": "anking-respiratory-pathology-245", "fuente": "anking", "tema": 17, "anki": "1473536790852", "q": "Nasopharyngeal angiofibromas often present with profuse occurrence of which symptom?", "o": {"A": "Epistaxis", "B": "Hemoptysis", "C": "Otorrhea", "D": "Dysphagia"}, "r": "A", "e": {"correcta": "Nasopharyngeal angiofibromas are highly vascular tumors that classically present with profuse, recurrent epistaxis.", "incorrectas": {"B": "Hemoptysis refers to coughing up blood from the lower respiratory tract, not a nasal tumor symptom.", "C": "Otorrhea (ear discharge) is not a typical presentation of a nasal mass.", "D": "Dysphagia (difficulty swallowing) is not the classic presenting symptom of angiofibroma."}}}, {"id": "anking-respiratory-pathology-246", "fuente": "anking", "tema": 17, "anki": "1473536793729", "q": "What is the malignant tumor arising from nasopharyngeal epithelium called?", "o": {"A": "Nasopharyngeal carcinoma", "B": "Angiofibroma", "C": "Nasal polyp", "D": "Laryngeal papilloma"}, "r": "A", "e": {"correcta": "Nasopharyngeal carcinoma is a malignant tumor of the nasopharyngeal epithelium, associated with EBV infection.", "incorrectas": {"B": "Angiofibroma is a benign vascular tumor, not a malignant epithelial one.", "C": "Nasal polyps are benign inflammatory lesions, not malignant tumors.", "D": "Laryngeal papilloma is a benign lesion of the larynx associated with HPV, a different site and tumor type."}}}, {"id": "anking-respiratory-pathology-247", "fuente": "anking", "tema": 17, "anki": "1473536807246", "q": "Nasopharyngeal carcinoma often presents with involvement of which lymph nodes?", "o": {"A": "Cervical", "B": "Axillary", "C": "Inguinal", "D": "Mediastinal"}, "r": "A", "e": {"correcta": "Nasopharyngeal carcinoma commonly presents with painless cervical lymphadenopathy due to early lymphatic spread.", "incorrectas": {"B": "Axillary nodes drain the upper extremity and breast, not the nasopharynx.", "C": "Inguinal nodes drain the lower body, unrelated to nasopharyngeal drainage.", "D": "Mediastinal nodes are an atypical and late finding, not the classic presenting site."}}}, {"id": "anking-respiratory-pathology-248", "fuente": "anking", "tema": 17, "anki": "1473536815967", "q": "What is the most common cause of acute epiglottitis, especially in non-immunized children?", "o": {"A": "Haemophilus influenzae type B", "B": "Streptococcus pyogenes", "C": "Parainfluenza virus", "D": "Staphylococcus aureus"}, "r": "A", "e": {"correcta": "Haemophilus influenzae type B is the classic cause of acute epiglottitis, particularly in unvaccinated children.", "incorrectas": {"B": "Streptococcus pyogenes classically causes pharyngitis, not epiglottitis.", "C": "Parainfluenza virus is the classic cause of croup (laryngotracheobronchitis), not epiglottitis.", "D": "Staphylococcus aureus is not the classic pathogen associated with epiglottitis."}}}, {"id": "anking-respiratory-pathology-249", "fuente": "anking", "tema": 17, "anki": "1473536833722", "q": "Acute epiglottitis may present with a muffled voice and what type of respiratory sound?", "o": {"A": "Inspiratory stridor", "B": "Expiratory wheeze", "C": "Pleural friction rub", "D": "Crackles"}, "r": "A", "e": {"correcta": "Acute epiglottitis classically presents with muffled 'hot potato' voice, drooling, and inspiratory stridor due to upper airway obstruction.", "incorrectas": {"B": "Expiratory wheeze is more typical of lower airway obstruction, such as asthma.", "C": "Pleural friction rub suggests pleuritis, unrelated to epiglottitis.", "D": "Crackles suggest alveolar/interstitial disease such as pneumonia, not upper airway obstruction."}}}, {"id": "anking-respiratory-pathology-250", "fuente": "anking", "tema": 17, "anki": "1473536836879", "q": "Acute epiglottitis carries a risk of which life-threatening acute complication?", "o": {"A": "Airway obstruction", "B": "Pneumothorax", "C": "Pulmonary embolism", "D": "Cardiac tamponade"}, "r": "A", "e": {"correcta": "Acute epiglottitis can cause rapid, severe swelling of the epiglottis leading to acute airway obstruction, a medical emergency.", "incorrectas": {"B": "Pneumothorax is not a typical complication of epiglottitis.", "C": "Pulmonary embolism is unrelated to upper airway inflammation.", "D": "Cardiac tamponade is a pericardial process, not associated with epiglottitis."}}}, {"id": "anking-respiratory-pathology-251", "fuente": "anking", "tema": 17, "anki": "1473536839980", "q": "What is the most common cause of laryngotracheobronchitis (croup)?", "o": {"A": "Parainfluenza virus", "B": "Haemophilus influenzae type B", "C": "Respiratory syncytial virus", "D": "Rhinovirus"}, "r": "A", "e": {"correcta": "Parainfluenza virus is the most common cause of croup (laryngotracheobronchitis), typically presenting with a barking cough and stridor.", "incorrectas": {"B": "Haemophilus influenzae type B is the classic cause of epiglottitis, not croup.", "C": "RSV is more classically associated with bronchiolitis in infants than croup.", "D": "Rhinovirus is the classic cause of the common cold, not croup."}}}, {"id": "anking-psychiatry-pathology-252", "fuente": "anking", "tema": 18, "anki": "1474666102186", "q": "Combining dextromethorphan with other serotonergic agents (e.g., SSRIs, MAOIs) puts a patient at risk for which condition?", "o": {"A": "Serotonin syndrome", "B": "Neuroleptic malignant syndrome", "C": "Malignant hyperthermia", "D": "Anticholinergic toxicity"}, "r": "A", "e": {"correcta": "Dextromethorphan has serotonergic activity and combining it with other serotonergic drugs (SSRIs, MAOIs) can precipitate serotonin syndrome, characterized by hyperthermia, clonus, hyperreflexia, and autonomic instability.", "incorrectas": {"B": "Neuroleptic malignant syndrome is caused by dopamine receptor antagonists (antipsychotics), not serotonergic combinations.", "C": "Malignant hyperthermia is triggered by inhaled anesthetics and succinylcholine in genetically susceptible individuals.", "D": "Anticholinergic toxicity results from muscarinic receptor blockade, not serotonergic excess."}}}, {"id": "anking-psychiatry-pathology-253", "fuente": "anking", "tema": 18, "anki": "1484016780394", "q": "What is the first-line treatment for nocturnal enuresis (bedwetting) in children?", "o": {"A": "Motivational therapy (e.g., star charts)", "B": "Desmopressin", "C": "Imipramine", "D": "Bladder augmentation surgery"}, "r": "A", "e": {"correcta": "Motivational/behavioral therapy such as star charts and bedwetting alarms is the first-line, least invasive treatment for enuresis before pharmacologic options are considered.", "incorrectas": {"B": "Desmopressin is a pharmacologic second-line option used if behavioral therapy fails.", "C": "Imipramine is an older, less preferred pharmacologic agent reserved for refractory cases due to side effects.", "D": "Surgery is not indicated for primary nocturnal enuresis and is reserved for rare anatomic causes."}}}, {"id": "anking-psychiatry-pathology-254", "fuente": "anking", "tema": 18, "anki": "1484618155233", "q": "Long-term infant deprivation of affection classically results in failure to do what?", "o": {"A": "Thrive", "B": "Ambulate", "C": "Wean", "D": "Regulate temperature"}, "r": "A", "e": {"correcta": "Chronic emotional deprivation in infancy is associated with failure to thrive, part of the classic \"weak, wordless, wary, wanting\" presentation.", "incorrectas": {"B": "Motor milestones like ambulation are not the classic feature emphasized in deprivation syndromes.", "C": "Weaning difficulty is not a described feature of infant deprivation.", "D": "Temperature dysregulation is not part of the classic deprivation presentation."}}}, {"id": "anking-psychiatry-pathology-255", "fuente": "anking", "tema": 18, "anki": "1484623875483", "q": "Long-term infant deprivation of affection may result in poor development of which skills?", "o": {"A": "Language/socialization skills", "B": "Fine motor skills", "C": "Gross motor skills", "D": "Visual-spatial skills"}, "r": "A", "e": {"correcta": "Emotional deprivation impairs the infant's ability to develop normal language and social skills, consistent with the \"wordless\" component of the classic description.", "incorrectas": {"B": "Fine motor skill delay is not the classic feature highlighted in deprivation syndromes.", "C": "Gross motor delay is not specifically emphasized in this condition.", "D": "Visual-spatial skill deficits are not part of the described syndrome."}}}, {"id": "anking-psychiatry-pathology-256", "fuente": "anking", "tema": 18, "anki": "1484623890671", "q": "Long-term infant deprivation of affection may result in a lack of what fundamental psychological attribute?", "o": {"A": "Basic trust", "B": "Object permanence", "C": "Self-esteem", "D": "Autonomy"}, "r": "A", "e": {"correcta": "Deprived infants fail to develop basic trust, an Eriksonian developmental milestone normally established through consistent caregiving in the first year of life.", "incorrectas": {"B": "Object permanence is a cognitive (Piagetian) milestone, not the trust-related feature described here.", "C": "Self-esteem issues develop later and are not the specific infancy-stage deficit described.", "D": "Autonomy is the toddler-stage Eriksonian task, not the infancy-stage trust deficit."}}}, {"id": "anking-psychiatry-pathology-257", "fuente": "anking", "tema": 18, "anki": "1484623897163", "q": "Severe, long-term infant deprivation of affection can lead to which named disorder, in which the infant is emotionally withdrawn and unresponsive to comfort?", "o": {"A": "Reactive attachment disorder", "B": "Disinhibited social engagement disorder", "C": "Autism spectrum disorder", "D": "Separation anxiety disorder"}, "r": "A", "e": {"correcta": "Reactive attachment disorder occurs when a deprived infant becomes emotionally withdrawn and does not seek or respond to comfort, distinguishing it from disinhibited social engagement disorder.", "incorrectas": {"B": "Disinhibited social engagement disorder features indiscriminate, overly familiar behavior toward strangers rather than withdrawal.", "C": "Autism spectrum disorder is a neurodevelopmental condition not caused by deprivation and has different diagnostic criteria.", "D": "Separation anxiety disorder involves excessive distress upon separation from an attachment figure, not global withdrawal."}}}, {"id": "anking-psychiatry-pathology-258", "fuente": "anking", "tema": 18, "anki": "1484623900452", "q": "Infant deprivation lasting longer than approximately how long can lead to irreversible developmental changes?", "o": {"A": "6 months", "B": "2 weeks", "C": "1 month", "D": "2 years"}, "r": "A", "e": {"correcta": "Deprivation persisting beyond about 6 months is associated with irreversible developmental and psychological changes in the infant.", "incorrectas": {"B": "Two weeks is too short a duration to be the classically cited threshold for irreversibility.", "C": "One month is shorter than the classically described threshold.", "D": "Two years overstates the threshold; irreversible changes are described as occurring before this point."}}}, {"id": "anking-psychiatry-pathology-259", "fuente": "anking", "tema": 18, "anki": "1484623902681", "q": "What is the most severe possible outcome of severe infant deprivation?", "o": {"A": "Death", "B": "Chronic constipation", "C": "Precocious puberty", "D": "Hyperactivity disorder"}, "r": "A", "e": {"correcta": "In its most severe form, infant deprivation (lack of nutrition, stimulation, and affection) can be fatal.", "incorrectas": {"B": "Chronic constipation is not a recognized severe outcome of emotional/physical deprivation.", "C": "Precocious puberty is unrelated to deprivation and has distinct endocrine causes.", "D": "Hyperactivity disorder is not the described severe consequence of deprivation."}}}, {"id": "anking-psychiatry-pathology-260", "fuente": "anking", "tema": 18, "anki": "1484623905318", "q": "Which finding on physical exam, especially rib fractures or spiral long-bone fractures in different stages of healing, is classic evidence of child physical abuse?", "o": {"A": "Fractures", "B": "Dislocations", "C": "Osteoporosis", "D": "Growth plate widening"}, "r": "A", "e": {"correcta": "Fractures of the ribs or long bones (especially spiral fractures) in multiple stages of healing are a classic red flag for non-accidental trauma in children.", "incorrectas": {"B": "Dislocations are not the classically cited abuse indicator; fractures in varying stages of healing are.", "C": "Osteoporosis is a bone density disorder unrelated to abuse and rare in children.", "D": "Growth plate widening is associated with conditions like rickets, not classically with abuse."}}}, {"id": "anking-psychiatry-pathology-261", "fuente": "anking", "tema": 18, "anki": "1484623907739", "q": "Which skin finding, especially on the trunk, ears, or neck, or in a pattern resembling an implement, suggests child physical abuse?", "o": {"A": "Bruises", "B": "Petechiae", "C": "Vitiligo lesions", "D": "Café-au-lait spots"}, "r": "A", "e": {"correcta": "Bruises in unusual locations (trunk, ears, neck) or in patterns matching an object (belt, cord) are highly suspicious for physical abuse in children.", "incorrectas": {"B": "Petechiae typically suggest thrombocytopenia or increased venous pressure, not classically abuse patterning.", "C": "Vitiligo is an autoimmune depigmentation disorder unrelated to trauma.", "D": "Café-au-lait spots are associated with neurofibromatosis, not abuse."}}}, {"id": "anking-psychiatry-pathology-262", "fuente": "anking", "tema": 18, "anki": "1484623909853", "q": "Which type of skin injury, such as from a cigarette or located on the buttocks/thighs, is classic evidence of child physical abuse?", "o": {"A": "Burns", "B": "Lacerations", "C": "Abrasions", "D": "Ulcers"}, "r": "A", "e": {"correcta": "Burns, particularly small circular cigarette burns or burns localized to the buttocks/thighs (as from forced immersion), are classic signs of physical abuse.", "incorrectas": {"B": "Lacerations are not the specifically cited classic abuse finding in this context.", "C": "Abrasions are nonspecific and less classically diagnostic than patterned burns.", "D": "Ulcers are typically related to vascular or pressure injury, not classic abuse presentations."}}}, {"id": "anking-psychiatry-pathology-263", "fuente": "anking", "tema": 18, "anki": "1484623913909", "q": "Children who are victims of physical abuse often display what behavior on exam?", "o": {"A": "Avoidance of eye contact", "B": "Excessive eye contact", "C": "Hyperverbal speech", "D": "Increased physical affection toward the examiner"}, "r": "A", "e": {"correcta": "Abused children often avoid eye contact during examination, reflecting fear, withdrawal, or learned hypervigilance around adults.", "incorrectas": {"B": "Excessive eye contact is not the described behavior; avoidance is more typical.", "C": "Hyperverbal speech is not a classic described feature of abused children.", "D": "Increased affection toward examiners is atypical; withdrawal is more characteristic."}}}, {"id": "anking-psychiatry-pathology-264", "fuente": "anking", "tema": 18, "anki": "1484623916085", "q": "In cases of child physical abuse, the abuser is usually which individual?", "o": {"A": "The biological mother", "B": "A stranger", "C": "A teacher", "D": "An older sibling"}, "r": "A", "e": {"correcta": "Statistically, the biological mother is most often the perpetrator of physical abuse against children, frequently related to caregiver stress.", "incorrectas": {"B": "Strangers are rarely the perpetrators; abuse is usually committed by caregivers or family members.", "C": "Teachers are not the typically cited perpetrators of child physical abuse.", "D": "Older siblings are not the most commonly cited abusers in this context."}}}, {"id": "anking-psychiatry-pathology-265", "fuente": "anking", "tema": 18, "anki": "1484623918068", "q": "Approximately 40% of deaths related to child abuse or neglect occur in children younger than what age?", "o": {"A": "1 year old", "B": "3 years old", "C": "5 years old", "D": "10 years old"}, "r": "A", "e": {"correcta": "Infants under 1 year old account for approximately 40% of fatalities from child abuse or neglect, reflecting their extreme vulnerability.", "incorrectas": {"B": "Three years old is older than the age group cited for this statistic.", "C": "Five years old overstates the age range associated with this mortality statistic.", "D": "Ten years old is far older than the vulnerable infant age group described."}}}, {"id": "anking-psychiatry-pathology-266", "fuente": "anking", "tema": 18, "anki": "1484623919894", "q": "Genital, anal, or oral trauma in a child is evidence of which type of abuse?", "o": {"A": "Sexual abuse", "B": "Physical abuse", "C": "Emotional abuse", "D": "Medical neglect"}, "r": "A", "e": {"correcta": "Genital, anal, or oral trauma is characteristic physical evidence used to identify sexual abuse in children.", "incorrectas": {"B": "Physical abuse is more classically evidenced by fractures, bruises, and burns rather than genital/anal trauma.", "C": "Emotional abuse does not produce physical trauma findings.", "D": "Medical neglect refers to withholding needed care, not causing traumatic injury."}}}, {"id": "anking-psychiatry-pathology-267", "fuente": "anking", "tema": 18, "anki": "1484623924102", "q": "The perpetrator of child sexual abuse is usually which of the following?", "o": {"A": "A male known to the victim", "B": "A female stranger", "C": "A male stranger", "D": "A female known to the victim"}, "r": "A", "e": {"correcta": "Child sexual abuse is most commonly perpetrated by a male who is known to the victim, such as a family member or acquaintance, rather than a stranger.", "incorrectas": {"B": "Female strangers are not the typical perpetrator profile described.", "C": "Strangers, whether male or female, are less commonly the perpetrators compared to known individuals.", "D": "While known individuals are correct, the perpetrator is usually male, not female."}}}, {"id": "anking-psychiatry-pathology-268", "fuente": "anking", "tema": 18, "anki": "1484623925893", "q": "What is the peak age incidence for child sexual abuse?", "o": {"A": "9-12 years old", "B": "0-2 years old", "C": "3-5 years old", "D": "15-17 years old"}, "r": "A", "e": {"correcta": "The peak incidence of child sexual abuse occurs between 9 and 12 years old.", "incorrectas": {"B": "Ages 0-2 are not the peak incidence range cited for sexual abuse.", "C": "Ages 3-5, while a vulnerable period, are not the cited peak incidence range.", "D": "Ages 15-17 are older than the classically cited peak incidence range."}}}, {"id": "anking-psychiatry-pathology-269", "fuente": "anking", "tema": 18, "anki": "1484623929161", "q": "Failure to provide a child with adequate food, shelter, supervision, education, and/or affection is defined as what?", "o": {"A": "Child neglect", "B": "Child physical abuse", "C": "Child sexual abuse", "D": "Munchausen syndrome by proxy"}, "r": "A", "e": {"correcta": "Child neglect is defined as the failure to provide a child's basic needs, including food, shelter, supervision, education, and affection.", "incorrectas": {"B": "Physical abuse involves active infliction of physical harm, not failure to provide basic needs.", "C": "Sexual abuse involves sexual exploitation or contact, not failure to provide basic needs.", "D": "Munchausen syndrome by proxy involves a caregiver fabricating or inducing illness in a child, not simple neglect of needs."}}}, {"id": "anking-epidemiology-biostatistics-270", "fuente": "anking", "tema": 19, "anki": "1485736698405", "q": "What is the mathematical relationship expressed by prevalence / (1 - prevalence)?", "o": {"A": "Incidence × average duration of disease", "B": "Sensitivity × specificity", "C": "Relative risk × attributable risk", "D": "Positive predictive value / negative predictive value"}, "r": "A", "e": {"correcta": "Prevalence odds equal incidence multiplied by the average duration of disease; if people with the disease live longer, prevalence rises even without a change in incidence.", "incorrectas": {"B": "Sensitivity and specificity describe test performance, not the prevalence-incidence relationship.", "C": "Relative risk and attributable risk are measures of association between exposure and outcome, unrelated to this formula.", "D": "Predictive values depend on prevalence but their ratio is not equivalent to this formula."}}}, {"id": "anking-epidemiology-biostatistics-271", "fuente": "anking", "tema": 19, "anki": "1485736701018", "q": "For a short-duration disease such as the common cold, how does prevalence compare to incidence?", "o": {"A": "Prevalence is similar to incidence", "B": "Prevalence is much greater than incidence", "C": "Prevalence is always zero", "D": "Prevalence cannot be measured for short-duration disease"}, "r": "A", "e": {"correcta": "Because the disease resolves quickly, few cases accumulate at any one time, so prevalence approximates incidence.", "incorrectas": {"B": "A prevalence much greater than incidence occurs with chronic, long-duration diseases, not short ones.", "C": "Prevalence is not zero; cases do exist at any given time, just briefly.", "D": "Prevalence can be measured for any disease duration, including short ones."}}}, {"id": "anking-epidemiology-biostatistics-272", "fuente": "anking", "tema": 19, "anki": "1485736703297", "q": "For a chronic disease such as diabetes, how does prevalence compare to incidence?", "o": {"A": "Prevalence is greater than incidence", "B": "Prevalence is similar to incidence", "C": "Prevalence is less than incidence", "D": "Prevalence equals incidence divided by duration"}, "r": "A", "e": {"correcta": "Chronic diseases accumulate a large pool of existing cases over time, so prevalence exceeds incidence.", "incorrectas": {"B": "Similarity between prevalence and incidence occurs with short-duration diseases, not chronic ones.", "C": "Prevalence is not less than incidence in chronic disease; the opposite is true.", "D": "This is not the correct relationship; prevalence relates to incidence × duration, not incidence divided by duration."}}}, {"id": "anking-epidemiology-biostatistics-273", "fuente": "anking", "tema": 19, "anki": "1485736708068", "q": "What happens to incidence and prevalence when an effective treatment for a disease is developed (without a cure)?", "o": {"A": "No change in incidence; decreased prevalence", "B": "Decreased incidence; decreased prevalence", "C": "No change in incidence; increased prevalence", "D": "Decreased incidence; no change in prevalence"}, "r": "A", "e": {"correcta": "Treatment does not prevent new cases (no change in incidence) but shortens disease duration or leads to cure, thereby decreasing prevalence.", "incorrectas": {"B": "Decreased incidence would require prevention of new cases, which treatment alone does not achieve.", "C": "Prevalence decreases, not increases, when effective treatment shortens disease duration.", "D": "Incidence is unaffected by treatment, and prevalence does change (decreases), not remains the same."}}}, {"id": "anking-epidemiology-biostatistics-274", "fuente": "anking", "tema": 19, "anki": "1485736711892", "q": "What happens to incidence and prevalence when an effective vaccine for a disease is developed?", "o": {"A": "Decreased incidence and decreased prevalence", "B": "No change in incidence; decreased prevalence", "C": "Decreased incidence; no change in prevalence", "D": "Increased incidence; decreased prevalence"}, "r": "A", "e": {"correcta": "A vaccine prevents new infections, lowering incidence, which in turn lowers prevalence as well.", "incorrectas": {"B": "Vaccines do reduce incidence by preventing new cases, unlike treatments which do not.", "C": "Prevalence also decreases because fewer new cases accumulate over time.", "D": "Vaccination decreases, not increases, incidence by preventing disease occurrence."}}}, {"id": "anking-epidemiology-biostatistics-275", "fuente": "anking", "tema": 19, "anki": "1485736715527", "q": "If people with a chronic disease live longer (without a change in new case detection), what happens to incidence and prevalence?", "o": {"A": "No change in incidence; increased prevalence", "B": "Decreased incidence; increased prevalence", "C": "No change in incidence; decreased prevalence", "D": "Increased incidence; no change in prevalence"}, "r": "A", "e": {"correcta": "Longer survival does not affect the rate of new cases (incidence) but increases the pool of existing cases, raising prevalence.", "incorrectas": {"B": "Incidence remains unchanged since longer survival does not affect new case occurrence.", "C": "Prevalence increases, not decreases, when patients live longer with disease.", "D": "Incidence does not increase from longer survival; only prevalence rises."}}}, {"id": "anking-epidemiology-biostatistics-276", "fuente": "anking", "tema": 19, "anki": "1485905125428", "q": "Which type of prevalence refers to the amount of an existing condition present in a population at a single point in time?", "o": {"A": "Point prevalence", "B": "Period prevalence", "C": "Cumulative incidence", "D": "Attack rate"}, "r": "A", "e": {"correcta": "Point prevalence measures existing cases of disease at one specific moment in time.", "incorrectas": {"B": "Period prevalence measures cases over a defined time interval, not a single point.", "C": "Cumulative incidence measures new cases occurring over time, not existing cases at a point.", "D": "Attack rate is a form of cumulative incidence used in outbreak settings, not a point-in-time prevalence measure."}}}, {"id": "anking-epidemiology-biostatistics-277", "fuente": "anking", "tema": 19, "anki": "1485905310769", "q": "Which type of prevalence refers to the amount of an existing condition present in a population during a particular time period?", "o": {"A": "Period prevalence", "B": "Point prevalence", "C": "Incidence rate", "D": "Case fatality rate"}, "r": "A", "e": {"correcta": "Period prevalence captures all existing cases (old and new) during a defined interval, such as a year.", "incorrectas": {"B": "Point prevalence refers to a single moment in time, not a duration.", "C": "Incidence rate measures new cases over time, not the total existing burden.", "D": "Case fatality rate measures the proportion of deaths among diagnosed cases, unrelated to prevalence."}}}, {"id": "anking-epidemiology-biostatistics-278", "fuente": "anking", "tema": 19, "anki": "1485905312055", "q": "Which study design is an observational study that compares a group of people with a disease to a group without the disease?", "o": {"A": "Case-control study", "B": "Cohort study", "C": "Cross-sectional study", "D": "Randomized controlled trial"}, "r": "A", "e": {"correcta": "Case-control studies select participants based on disease status and look backward to compare prior exposure rates, asking 'what happened?'", "incorrectas": {"B": "Cohort studies select participants based on exposure status, not disease status, and follow them forward.", "C": "Cross-sectional studies assess exposure and disease simultaneously in one population sample, not by pre-selecting diseased vs non-diseased groups.", "D": "A randomized controlled trial is an experimental study, not an observational one, and assigns exposure rather than comparing existing disease status."}}}, {"id": "anking-epidemiology-biostatistics-279", "fuente": "anking", "tema": 19, "anki": "1485913601502", "q": "Case-control studies are almost always which type of design with respect to time?", "o": {"A": "Retrospective", "B": "Prospective", "C": "Cross-sectional", "D": "Ambispective"}, "r": "A", "e": {"correcta": "Case-control studies look backward in time from disease status to prior exposures, making them retrospective.", "incorrectas": {"B": "Prospective design (following subjects forward in time) is characteristic of cohort studies, not case-control studies.", "C": "Cross-sectional describes studies assessing exposure and outcome at one time point, a distinct design from case-control.", "D": "Ambispective (combining retrospective and prospective elements) is not the typical design for case-control studies."}}}, {"id": "anking-epidemiology-biostatistics-280", "fuente": "anking", "tema": 19, "anki": "1485913607195", "q": "Are case-control studies useful for directly measuring incidence and/or prevalence?", "o": {"A": "Neither incidence nor prevalence", "B": "Only incidence", "C": "Only prevalence", "D": "Both incidence and prevalence"}, "r": "A", "e": {"correcta": "Because subjects are selected based on disease status rather than sampled from the general population, case-control studies cannot calculate true incidence or prevalence; they primarily estimate odds ratios.", "incorrectas": {"B": "Incidence requires following a population over time from exposure, which case-control studies do not do since cases are pre-selected.", "C": "Prevalence requires sampling the general population at one time, which is not how case-control studies are structured.", "D": "Case-control studies are not designed to measure either incidence or prevalence directly."}}}, {"id": "anking-epidemiology-biostatistics-281", "fuente": "anking", "tema": 19, "anki": "1485913618153", "q": "Which type of study is an observational study that compares the frequency of disease and frequency of risk-related factors at one time point?", "o": {"A": "Cross-sectional survey", "B": "Case-control study", "C": "Cohort study", "D": "Twin concordance study"}, "r": "A", "e": {"correcta": "Cross-sectional surveys measure exposure and outcome simultaneously in a population, asking 'what is happening?' but cannot establish temporal relationships.", "incorrectas": {"B": "Case-control studies select groups based on disease status and look backward for exposure, unlike simultaneous assessment in cross-sectional studies.", "C": "Cohort studies select groups based on exposure and follow them forward over time, not at a single time point.", "D": "Twin concordance studies compare disease frequency between monozygotic and dizygotic twins, not general population risk factors at one time point."}}}, {"id": "anking-epidemiology-biostatistics-282", "fuente": "anking", "tema": 19, "anki": "1485913626221", "q": "Are cross-sectional surveys useful for measuring incidence and/or prevalence?", "o": {"A": "Prevalence", "B": "Incidence", "C": "Both incidence and prevalence", "D": "Neither incidence nor prevalence"}, "r": "A", "e": {"correcta": "Because cross-sectional surveys capture a snapshot of the population at one time, they are useful for measuring prevalence, not incidence.", "incorrectas": {"B": "Incidence requires tracking new cases over time, which cross-sectional surveys cannot do since they capture only one time point.", "C": "Cross-sectional surveys cannot measure incidence, so 'both' is incorrect.", "D": "Cross-sectional surveys can measure prevalence, so 'neither' is incorrect."}}}, {"id": "anking-epidemiology-biostatistics-283", "fuente": "anking", "tema": 19, "anki": "1485913637098", "q": "Which type of study is an observational study that compares groups with a given exposure or risk factor to a group without such exposure?", "o": {"A": "Cohort study", "B": "Case-control study", "C": "Cross-sectional study", "D": "Case series"}, "r": "A", "e": {"correcta": "Cohort studies select participants based on exposure status and follow them to see if the exposure is associated with later development of disease.", "incorrectas": {"B": "Case-control studies select groups based on disease status, not exposure status.", "C": "Cross-sectional studies assess exposure and outcome simultaneously rather than following exposed vs unexposed groups over time.", "D": "A case series simply describes a group of patients with a disease and includes no comparison group."}}}, {"id": "anking-epidemiology-biostatistics-284", "fuente": "anking", "tema": 19, "anki": "1485913642965", "q": "Which type of observational study can be designed as either retrospective or prospective?", "o": {"A": "Cohort study", "B": "Case-control study", "C": "Cross-sectional study", "D": "Ecological study"}, "r": "A", "e": {"correcta": "Cohort studies can follow subjects forward in time (prospective) or use existing exposure records to look backward (retrospective).", "incorrectas": {"B": "Case-control studies are almost always retrospective by design.", "C": "Cross-sectional studies assess exposure and outcome at a single time point, so the retro/prospective distinction does not apply in the same way.", "D": "Ecological studies analyze population-level, not individual-level, data and are not classified this way."}}}, {"id": "anking-epidemiology-biostatistics-285", "fuente": "anking", "tema": 19, "anki": "1485913647193", "q": "Which type of study design is useful for calculating relative risk (RR)?", "o": {"A": "Cohort study", "B": "Case-control study", "C": "Cross-sectional study", "D": "Case series"}, "r": "A", "e": {"correcta": "Because cohort studies follow exposed and unexposed groups over time, they allow direct calculation of relative risk, e.g., comparing COPD risk in smokers versus nonsmokers.", "incorrectas": {"B": "Case-control studies calculate odds ratios, not relative risk, since incidence cannot be directly determined.", "C": "Cross-sectional studies typically report prevalence ratios or odds ratios, not relative risk based on incident cases.", "D": "Case series lack a comparison group entirely, so no risk ratio can be calculated."}}}, {"id": "anking-epidemiology-biostatistics-286", "fuente": "anking", "tema": 19, "anki": "1485913653603", "q": "Are cohort studies useful for measuring incidence and/or prevalence?", "o": {"A": "Incidence", "B": "Prevalence", "C": "Neither incidence nor prevalence", "D": "Both incidence and prevalence equally well"}, "r": "A", "e": {"correcta": "Cohort studies follow exposed and unexposed groups forward over time, allowing calculation of the incidence of new disease cases.", "incorrectas": {"B": "Prevalence measurement is better suited to cross-sectional studies, which capture existing cases at one time point.", "C": "Cohort studies are useful for incidence, so 'neither' is incorrect.", "D": "Cohort studies are primarily suited for incidence, not prevalence, so they are not equally useful for both."}}}, {"id": "anking-epidemiology-biostatistics-287", "fuente": "anking", "tema": 19, "anki": "1485913657551", "q": "Which type of study is an observational study that compares the frequency with which monozygotic and dizygotic twins develop the same disease?", "o": {"A": "Twin concordance study", "B": "Cohort study", "C": "Case-control study", "D": "Adoption study"}, "r": "A", "e": {"correcta": "Twin concordance studies compare disease concordance rates between monozygotic and dizygotic twins to estimate the genetic contribution to a disease.", "incorrectas": {"B": "Cohort studies compare exposed versus unexposed groups in a general population, not twin pairs specifically.", "C": "Case-control studies compare diseased versus non-diseased individuals, not twin concordance rates.", "D": "Adoption studies compare biological versus adoptive relatives to separate genetic and environmental influences, a different design from twin concordance studies."}}}, {"id": "anking-virology-001", "fuente": "anking", "tema": 20, "anki": "1382060386627", "q": "The E6 protein of Human Papillomavirus (HPV) binds to and inhibits which tumor suppressor gene product?", "o": {"A": "p53", "B": "Rb (retinoblastoma protein)", "C": "BRCA1", "D": "p16"}, "r": "A", "e": {"correcta": "E6 protein from high-risk HPV strains binds and promotes degradation of p53, a key tumor suppressor that normally halts the cell cycle in response to DNA damage, removing this checkpoint and promoting oncogenesis.", "incorrectas": {"B": "Rb is inhibited by the HPV E7 protein, not E6.", "C": "BRCA1 is a DNA repair tumor suppressor associated with hereditary breast/ovarian cancer, not targeted by HPV E6.", "D": "p16 is actually upregulated (not inhibited) in HPV-associated cancers as a surrogate marker, due to loss of Rb function."}}}, {"id": "anking-virology-002", "fuente": "anking", "tema": 20, "anki": "1382060716767", "q": "The E7 protein of Human Papillomavirus (HPV) binds to and inhibits which tumor suppressor?", "o": {"A": "p53", "B": "Rb (retinoblastoma protein, p105-Rb)", "C": "PTEN", "D": "APC"}, "r": "B", "e": {"correcta": "E7 protein binds and inactivates the retinoblastoma protein (Rb), releasing E2F transcription factors and driving the cell into S phase inappropriately, contributing to HPV-mediated carcinogenesis.", "incorrectas": {"A": "p53 is targeted by the E6 protein, not E7.", "C": "PTEN is a tumor suppressor in the PI3K/AKT pathway and is not the target of HPV E7.", "D": "APC is a tumor suppressor mutated in colorectal cancer (FAP), unrelated to HPV E7 activity."}}}, {"id": "anking-virology-003", "fuente": "anking", "tema": 20, "anki": "1385334070939", "q": "What benign tumor of the squamous mucosa of the sinuses is thought to be caused by HPV infection?", "o": {"A": "Sinonasal papilloma", "B": "Nasopharyngeal angiofibroma", "C": "Esthesioneuroblastoma", "D": "Antrochoanal polyp"}, "r": "A", "e": {"correcta": "Sinonasal papilloma is a benign squamous mucosal tumor of the sinuses associated with HPV infection.", "incorrectas": {"B": "Nasopharyngeal angiofibroma is a vascular tumor typically seen in adolescent males, not linked to HPV.", "C": "Esthesioneuroblastoma is a malignant neuroendocrine tumor of the olfactory epithelium, not HPV-related.", "D": "Antrochoanal polyp is an inflammatory nasal polyp unrelated to HPV infection."}}}, {"id": "anking-virology-004", "fuente": "anking", "tema": 20, "anki": "1394068322402", "q": "What is the most common cause of Condyloma acuminata?", "o": {"A": "HPV6 and HPV11", "B": "HPV16 and HPV18", "C": "Herpes simplex virus 2", "D": "Molluscum contagiosum virus"}, "r": "A", "e": {"correcta": "Condyloma acuminata (genital warts) is most commonly caused by low-risk HPV types 6 and 11.", "incorrectas": {"B": "HPV16 and 18 are high-risk oncogenic types associated with cervical cancer, not typical genital warts.", "C": "HSV-2 causes genital herpes with painful vesicular lesions, not warty condylomas.", "D": "Molluscum contagiosum virus causes umbilicated papules, a distinct entity from genital warts."}}}, {"id": "anking-virology-005", "fuente": "anking", "tema": 20, "anki": "1394068343387", "q": "Which condition, caused by HPV (typically types 6 and 11), presents as genital warts?", "o": {"A": "Condyloma acuminatum", "B": "Condyloma latum", "C": "Molluscum contagiosum", "D": "Bowenoid papulosis"}, "r": "A", "e": {"correcta": "Condyloma acuminatum refers to genital warts caused by HPV, typically low-risk types 6 and 11.", "incorrectas": {"B": "Condyloma latum is a flat, moist wart-like lesion seen in secondary syphilis, not caused by HPV.", "C": "Molluscum contagiosum is caused by a poxvirus and presents with umbilicated papules, not warts.", "D": "Bowenoid papulosis is associated with high-risk HPV types and can show dysplastic changes, distinct from typical condyloma acuminatum."}}}, {"id": "anking-virology-006", "fuente": "anking", "tema": 20, "anki": "1394068386223", "q": "Which histological feature, characterized by raisin-like nuclei with perinuclear halos, is a hallmark of HPV infection?", "o": {"A": "Koilocytes", "B": "Councilman bodies", "C": "Negri bodies", "D": "Owl's eye inclusions"}, "r": "A", "e": {"correcta": "Koilocytes are squamous epithelial cells with raisin-like, wrinkled nuclei and perinuclear halos, a classic histologic hallmark of HPV infection, especially prominent in condyloma acuminatum.", "incorrectas": {"B": "Councilman bodies are apoptotic hepatocytes seen in viral hepatitis, unrelated to HPV.", "C": "Negri bodies are cytoplasmic inclusions seen in rabies virus infection.", "D": "Owl's eye inclusions are intranuclear inclusions characteristic of CMV infection."}}}, {"id": "anking-virology-007", "fuente": "anking", "tema": 20, "anki": "1394068608346", "q": "What is the carcinoma risk associated with HPV types 6 and 11?", "o": {"A": "Low", "B": "High", "C": "Intermediate", "D": "No risk at all, they are never oncogenic"}, "r": "A", "e": {"correcta": "HPV 6 and 11 are classified as low-risk types, primarily causing benign genital warts (condyloma acuminatum) with low potential for malignant transformation.", "incorrectas": {"B": "High carcinoma risk is associated with types like HPV 16, 18, 31, and 33, not 6 or 11.", "C": "HPV types are typically classified as either low-risk or high-risk, not intermediate, in standard USMLE classification.", "D": "While rare, low-risk HPV types can occasionally be found in some lesions, so 'no risk at all' is an overstatement; the accurate classification is 'low risk.'"}}}, {"id": "anking-virology-008", "fuente": "anking", "tema": 20, "anki": "1394068945521", "q": "Which HPV types are the cause of HPV-related vulvar carcinoma?", "o": {"A": "High-risk HPVs (16, 18, 31, 33)", "B": "Low-risk HPVs (6, 11)", "C": "HPV 2 and 4", "D": "HPV 5 and 8"}, "r": "A", "e": {"correcta": "HPV-related vulvar carcinoma is caused by high-risk HPV subtypes, primarily 16, 18, 31, and 33, which have oncogenic E6/E7 proteins driving malignant transformation.", "incorrectas": {"B": "HPV 6 and 11 are low-risk types causing genital warts, not carcinoma.", "C": "HPV 2 and 4 are associated with common cutaneous warts (verruca vulgaris), not vulvar carcinoma.", "D": "HPV 5 and 8 are associated with epidermodysplasia verruciformis and skin cancers, not vulvar carcinoma."}}}, {"id": "anking-virology-009", "fuente": "anking", "tema": 20, "anki": "1394069562561", "q": "Vulvar carcinoma seen in women of reproductive age is typically related to which virus?", "o": {"A": "HPV", "B": "Herpes simplex virus", "C": "Epstein-Barr virus", "D": "Human papillomavirus is unrelated; it is due to chronic lichen sclerosus instead"}, "r": "A", "e": {"correcta": "HPV-related vulvar carcinoma is the type typically seen in younger, reproductive-age women, in contrast to the non-HPV-related type seen in older women associated with lichen sclerosus.", "incorrectas": {"B": "HSV causes genital ulcerative disease, not the classic HPV-related vulvar carcinoma subtype.", "C": "EBV is associated with lymphomas and nasopharyngeal carcinoma, not vulvar carcinoma.", "D": "Lichen sclerosus is associated with the non-HPV-related vulvar carcinoma subtype typically seen in older women, not the reproductive-age subtype."}}}, {"id": "anking-virology-010", "fuente": "anking", "tema": 20, "anki": "1394134318361", "q": "What is the most common cause of vaginal carcinoma?", "o": {"A": "High-risk HPV subtypes (16, 18, 31, 33)", "B": "Low-risk HPV subtypes (6, 11)", "C": "Herpes simplex virus type 2", "D": "Diethylstilbestrol (DES) exposure"}, "r": "A", "e": {"correcta": "High-risk HPV subtypes, particularly 16 and 18 (accounting for about 70% of cases), are the most common cause of vaginal carcinoma, typically squamous cell carcinoma.", "incorrectas": {"B": "Low-risk HPV types 6 and 11 cause genital warts but are not the major cause of vaginal carcinoma.", "C": "HSV-2 causes genital herpes but is not the leading cause of vaginal carcinoma.", "D": "DES exposure in utero is classically associated with clear cell adenocarcinoma of the vagina, a less common cause than high-risk HPV."}}}, {"id": "anking-virology-011", "fuente": "anking", "tema": 20, "anki": "1394238351603", "q": "Which area of the cervix is especially targeted by HPV infection?", "o": {"A": "Transformation zone", "B": "Endocervical canal exclusively", "C": "Ectocervix exclusively", "D": "Cervical stroma"}, "r": "A", "e": {"correcta": "The transformation zone, where columnar epithelium (endocervix) meets stratified squamous epithelium (ectocervix) and undergoes metaplasia, is especially vulnerable to HPV infection and dysplastic transformation.", "incorrectas": {"B": "The endocervical canal alone, lined by columnar epithelium, is not the primary site of HPV-induced squamous dysplasia.", "C": "The ectocervix alone, already stratified squamous epithelium, is not the specific vulnerable zone; it's the transition area that is targeted.", "D": "The cervical stroma is connective tissue beneath the epithelium and is not the primary site targeted by HPV infection."}}}, {"id": "anking-virology-012", "fuente": "anking", "tema": 20, "anki": "1394238400609", "q": "What is the cancer risk associated with HPV16?", "o": {"A": "High", "B": "Low", "C": "None", "D": "Risk only in immunocompromised patients"}, "r": "A", "e": {"correcta": "HPV16 is one of the high-risk oncogenic HPV types, strongly associated with cervical and other anogenital cancers.", "incorrectas": {"B": "Low risk describes types like HPV 6 and 11, not HPV16.", "C": "HPV16 carries significant oncogenic potential and is not risk-free.", "D": "HPV16 is oncogenic in the general population, not only in immunocompromised individuals."}}}, {"id": "anking-virology-013", "fuente": "anking", "tema": 20, "anki": "1394239208489", "q": "What is the cancer risk associated with HPV18?", "o": {"A": "High", "B": "Low", "C": "None", "D": "Moderate, lower than HPV16"}, "r": "A", "e": {"correcta": "HPV18 is a high-risk oncogenic HPV type, second only to HPV16 in association with cervical cancer.", "incorrectas": {"B": "Low risk applies to HPV 6 and 11, not HPV18.", "C": "HPV18 has significant oncogenic potential and is not risk-free.", "D": "HPV18 is classified as high risk, not an intermediate/moderate category, in standard classification."}}}, {"id": "anking-virology-014", "fuente": "anking", "tema": 20, "anki": "1394239213546", "q": "What is the cancer risk associated with HPV31?", "o": {"A": "High", "B": "Low", "C": "None", "D": "Risk limited to oral cavity only"}, "r": "A", "e": {"correcta": "HPV31 is one of the high-risk oncogenic HPV types associated with cervical and anogenital carcinomas.", "incorrectas": {"B": "Low risk describes types like HPV 6 and 11, not HPV31.", "C": "HPV31 has oncogenic potential and is not risk-free.", "D": "HPV31 is associated with anogenital cancers broadly, not limited to the oral cavity."}}}, {"id": "anking-virology-015", "fuente": "anking", "tema": 20, "anki": "1394239217626", "q": "What is the cancer risk associated with HPV33?", "o": {"A": "High", "B": "Low", "C": "None", "D": "Risk only for skin cancer, not mucosal cancer"}, "r": "A", "e": {"correcta": "HPV33 is one of the high-risk oncogenic HPV types linked to cervical, vulvar, and vaginal carcinoma.", "incorrectas": {"B": "Low risk describes types like HPV 6 and 11, not HPV33.", "C": "HPV33 carries oncogenic potential and is not risk-free.", "D": "HPV33 is associated with mucosal anogenital cancers, not primarily skin cancer."}}}, {"id": "anking-virology-016", "fuente": "anking", "tema": 20, "anki": "1394239228891", "q": "What is the cancer risk associated with HPV6?", "o": {"A": "Low", "B": "High", "C": "None whatsoever, HPV6 cannot cause any lesions", "D": "High, similar to HPV16"}, "r": "A", "e": {"correcta": "HPV6 is a low-risk HPV type primarily responsible for benign genital warts (condyloma acuminatum), with low oncogenic potential.", "incorrectas": {"B": "High risk describes types like HPV16 and 18, not HPV6.", "C": "HPV6 does cause benign lesions such as genital warts, so it is not without effect, just low oncogenic risk.", "D": "HPV6 is low risk, not comparable in oncogenicity to HPV16."}}}, {"id": "anking-virology-017", "fuente": "anking", "tema": 20, "anki": "1394239234121", "q": "What is the cancer risk associated with HPV11?", "o": {"A": "Low", "B": "High", "C": "Intermediate", "D": "High, especially for laryngeal carcinoma"}, "r": "A", "e": {"correcta": "HPV11 is a low-risk type, along with HPV6, primarily causing genital warts and recurrent respiratory papillomatosis, with low malignant potential.", "incorrectas": {"B": "High risk is characteristic of types like HPV16, 18, 31, and 33, not HPV11.", "C": "HPV types are classified as low-risk or high-risk, not intermediate, per standard classification.", "D": "Although HPV11 can cause laryngeal papillomatosis, this is a benign condition, and the type is still classified as low cancer risk."}}}, {"id": "anking-virology-018", "fuente": "anking", "tema": 20, "anki": "1394239238481", "q": "Which protein from high-risk HPV strains binds to and inhibits p53?", "o": {"A": "E6", "B": "E7", "C": "L1", "D": "E2"}, "r": "A", "e": {"correcta": "The E6 protein from high-risk HPV strains binds to and promotes degradation of p53, inactivating this tumor suppressor and contributing to carcinogenesis (mnemonic: E6 before E7, p53 before Rb).", "incorrectas": {"B": "E7 protein binds and inhibits Rb, not p53.", "C": "L1 is the major capsid protein of HPV, used in HPV vaccines, and does not target p53.", "D": "E2 is a regulatory protein controlling viral transcription and replication, not a p53 inhibitor."}}}, {"id": "anking-clinical-bacteriology-019", "fuente": "anking", "tema": 21, "anki": "1402175671704", "q": "Why does Rickettsia species not gram stain well?", "o": {"A": "It is an obligate intracellular bacterium", "B": "It lacks a cell wall entirely", "C": "It forms endospores that resist staining", "D": "It has a mycolic acid-rich cell wall like Mycobacteria"}, "r": "A", "e": {"correcta": "Rickettsia are obligate intracellular bacteria; because they depend on host cell machinery and have a cell wall that stains poorly with standard reagents, they are difficult to visualize with Gram stain and are typically visualized with Giemsa stain instead.", "incorrectas": {"B": "Rickettsia does have a (weakly staining) cell wall; lack of a cell wall describes organisms like Mycoplasma.", "C": "Rickettsia does not form endospores; this describes organisms like Bacillus and Clostridium.", "D": "A mycolic acid-rich cell wall is characteristic of Mycobacteria, which require acid-fast staining, not Rickettsia."}}}, {"id": "anking-clinical-bacteriology-020", "fuente": "anking", "tema": 21, "anki": "1402177515133", "q": "Which special culture medium is used to isolate Neisseria gonorrhoeae or Neisseria meningitidis?", "o": {"A": "Thayer-Martin (VPN) media", "B": "MacConkey agar", "C": "Eaton's agar", "D": "Bordet-Gengou agar"}, "r": "A", "e": {"correcta": "Thayer-Martin (VPN, containing Vancomycin, Polymyxin, and Nystatin) selective media is used to culture Neisseria species by inhibiting the growth of competing bacterial and fungal flora.", "incorrectas": {"B": "MacConkey agar is used to differentiate lactose-fermenting gram-negative enteric bacteria, not Neisseria.", "C": "Eaton's agar is used to culture Mycoplasma pneumoniae, not Neisseria.", "D": "Bordet-Gengou agar is a selective medium for Bordetella pertussis, not Neisseria."}}}, {"id": "anking-clinical-bacteriology-021", "fuente": "anking", "tema": 21, "anki": "1402347679561", "q": "Which species of Neisseria is encapsulated?", "o": {"A": "Neisseria meningitidis", "B": "Neisseria gonorrhoeae", "C": "Neisseria sicca", "D": "Neisseria lactamica"}, "r": "A", "e": {"correcta": "Neisseria meningitidis possesses a polysaccharide capsule, which is a key virulence factor and the basis for serogroup classification and vaccine targets (e.g., serogroups A, B, C, Y, W-135).", "incorrectas": {"B": "Neisseria gonorrhoeae characteristically lacks a polysaccharide capsule.", "C": "Neisseria sicca is a commensal, non-encapsulated Neisseria species.", "D": "Neisseria lactamica is a nonpathogenic commensal species that is not encapsulated."}}}, {"id": "anking-clinical-bacteriology-022", "fuente": "anking", "tema": 21, "anki": "1402352728938", "q": "What is the urease expression of Staphylococcus epidermidis?", "o": {"A": "Positive", "B": "Negative", "C": "Variable, strain-dependent only in acidic media", "D": "Absent due to lack of the urease gene"}, "r": "A", "e": {"correcta": "Staphylococcus epidermidis is urease-positive, hydrolyzing urea to ammonia and carbon dioxide, which helps distinguish it in laboratory identification.", "incorrectas": {"B": "Negative urease would misclassify S. epidermidis, which reliably produces urease.", "C": "Urease production in S. epidermidis is a stable species characteristic, not a variable or pH-dependent trait.", "D": "S. epidermidis does carry a functional urease gene cluster, contradicting this option."}}}, {"id": "anking-clinical-bacteriology-023", "fuente": "anking", "tema": 21, "anki": "1402352742276", "q": "What is the urease expression of Staphylococcus saprophyticus?", "o": {"A": "Positive", "B": "Negative", "C": "Only in the presence of coagulase", "D": "Only expressed in stationary phase"}, "r": "A", "e": {"correcta": "Staphylococcus saprophyticus is urease-positive, which contributes to its virulence in the urinary tract by raising urine pH.", "incorrectas": {"B": "Negative urease is incorrect since S. saprophyticus reliably hydrolyzes urea.", "C": "Urease activity is not linked to coagulase status; S. saprophyticus is actually coagulase-negative.", "D": "Urease production is a constitutive species trait, not restricted to a particular growth phase."}}}, {"id": "anking-clinical-bacteriology-024", "fuente": "anking", "tema": 21, "anki": "1402441976942", "q": "What is the Novobiocin sensitivity of Staphylococcus saprophyticus?", "o": {"A": "Resistant", "B": "Sensitive", "C": "Intermediate, requiring repeat testing", "D": "Sensitivity depends on coagulase status"}, "r": "A", "e": {"correcta": "Staphylococcus saprophyticus is Novobiocin-resistant, a key laboratory feature used to distinguish it from S. epidermidis (mnemonic: \"NO StRESs\" - Saprophyticus is Resistant).", "incorrectas": {"B": "Sensitivity to Novobiocin describes S. epidermidis, not S. saprophyticus.", "C": "Novobiocin sensitivity testing gives a clear resistant result for S. saprophyticus, not an ambiguous intermediate one.", "D": "Novobiocin sensitivity is unrelated to coagulase status; both S. saprophyticus and S. epidermidis are coagulase-negative."}}}, {"id": "anking-clinical-bacteriology-025", "fuente": "anking", "tema": 21, "anki": "1402442693838", "q": "What is the Novobiocin sensitivity of Staphylococcus epidermidis?", "o": {"A": "Sensitive", "B": "Resistant", "C": "Sensitivity varies by anatomic site of isolation", "D": "Cannot be tested due to slow growth"}, "r": "A", "e": {"correcta": "Staphylococcus epidermidis is Novobiocin-sensitive, which helps differentiate it from the Novobiocin-resistant S. saprophyticus (mnemonic: \"NO StRESs\").", "incorrectas": {"B": "Resistance to Novobiocin is characteristic of S. saprophyticus, not S. epidermidis.", "C": "Novobiocin sensitivity is an intrinsic species characteristic, not dependent on the site of isolation.", "D": "S. epidermidis grows readily on standard media and can be routinely tested for Novobiocin sensitivity."}}}, {"id": "anking-clinical-bacteriology-026", "fuente": "anking", "tema": 21, "anki": "1402457468984", "q": "Which Staphylococcus species is the second most common cause of uncomplicated UTI in young women?", "o": {"A": "Staphylococcus saprophyticus", "B": "Staphylococcus aureus", "C": "Staphylococcus epidermidis", "D": "Staphylococcus lugdunensis"}, "r": "A", "e": {"correcta": "Staphylococcus saprophyticus is the second most common cause of uncomplicated UTIs in young, sexually active women, after Escherichia coli.", "incorrectas": {"B": "Staphylococcus aureus is not a typical cause of uncomplicated community-acquired UTI; it is more associated with skin/soft tissue infections and bacteremia.", "C": "Staphylococcus epidermidis is a skin commensal and common cause of catheter/device infections, not a leading cause of uncomplicated UTI.", "D": "Staphylococcus lugdunensis is notable for causing aggressive endocarditis, not typical uncomplicated UTI."}}}, {"id": "anking-clinical-bacteriology-027", "fuente": "anking", "tema": 21, "anki": "1402457591435", "q": "Which bacterium is the most common cause of meningitis overall?", "o": {"A": "Streptococcus pneumoniae", "B": "Neisseria meningitidis", "C": "Haemophilus influenzae", "D": "Listeria monocytogenes"}, "r": "A", "e": {"correcta": "Streptococcus pneumoniae is the most common overall cause of bacterial meningitis across age groups (mnemonic \"C-MOPS\": Cryptococcus, Meningococcus, Others, Pneumococcus, Strep agalactiae, listing common causes by age with pneumococcus predominating).", "incorrectas": {"B": "Neisseria meningitidis is a major cause of meningitis, especially in adolescents/young adults, but is not the overall most common cause.", "C": "Haemophilus influenzae was historically important but has declined greatly due to vaccination and is not the most common cause today.", "D": "Listeria monocytogenes causes meningitis mainly in neonates, the elderly, and immunocompromised patients, but is not the most common overall cause."}}}, {"id": "anking-clinical-bacteriology-028", "fuente": "anking", "tema": 21, "anki": "1402524036532", "q": "Where in the body are Group D Streptococci (Enterococcus faecalis and Enterococcus faecium) normally found?", "o": {"A": "Colon (GI) and urogenital (GU) tract", "B": "Nasopharynx and oropharynx", "C": "Skin and nares", "D": "Lower respiratory tract"}, "r": "A", "e": {"correcta": "Group D Streptococci, including Enterococcus faecalis and E. faecium, are normal flora of the GI (colon) and GU tract, which explains their association with infections following instrumentation of these areas, such as UTIs and endocarditis.", "incorrectas": {"B": "The nasopharynx/oropharynx is the normal habitat of organisms like Streptococcus pyogenes and S. pneumoniae, not Enterococcus.", "C": "Skin and nares are typical habitats for Staphylococcus species, not Enterococcus.", "D": "The lower respiratory tract is not the normal reservoir for Enterococcus species."}}}, {"id": "anking-clinical-bacteriology-029", "fuente": "anking", "tema": 21, "anki": "1402526056674", "q": "Which toxin produced by Clostridium tetani causes tetanus?", "o": {"A": "Tetanospasmin", "B": "Botulinum toxin", "C": "Alpha toxin (lecithinase)", "D": "Diphtheria toxin"}, "r": "A", "e": {"correcta": "Tetanospasmin, an exotoxin produced by Clostridium tetani, travels retrograde through motor neurons and cleaves SNARE proteins, blocking release of the inhibitory neurotransmitters GABA and glycine, resulting in spastic paralysis, trismus, and risus sardonicus.", "incorrectas": {"B": "Botulinum toxin is produced by Clostridium botulinum and causes flaccid paralysis by blocking acetylcholine release, the opposite clinical picture of tetanus.", "C": "Alpha toxin (lecithinase) is produced by Clostridium perfringens and causes myonecrosis (gas gangrene), not tetanus.", "D": "Diphtheria toxin is produced by Corynebacterium diphtheriae and inhibits protein synthesis via ADP-ribosylation of EF-2, unrelated to tetanus."}}}, {"id": "anking-clinical-bacteriology-030", "fuente": "anking", "tema": 21, "anki": "1402600814505", "q": "What color do colonies of lactose-fermenting enteric bacteria produce on MacConkey agar?", "o": {"A": "Pink", "B": "Colorless (clear)", "C": "Green with metallic sheen", "D": "Black"}, "r": "A", "e": {"correcta": "Lactose-fermenting bacteria produce acid byproducts that lower the local pH, causing a pH indicator in MacConkey agar to turn the colonies pink (mnemonic \"MacConKEE'S\": Citrobacter, Klebsiella, Enterobacter, Escherichia, Serratia).", "incorrectas": {"B": "Colorless colonies on MacConkey agar indicate non-lactose fermenters, such as Salmonella, Shigella, or Pseudomonas.", "C": "A green metallic sheen is characteristic of E. coli specifically on EMB agar, not the pink color seen on MacConkey agar.", "D": "Black colonies suggest hydrogen sulfide production (e.g., on Hektoen or XLD agar), which is unrelated to lactose fermentation on MacConkey agar."}}}, {"id": "anking-clinical-bacteriology-031", "fuente": "anking", "tema": 21, "anki": "1402675610097", "q": "Which species of Neisseria ferments both glucose and maltose?", "o": {"A": "Neisseria meningitidis", "B": "Neisseria gonorrhoeae", "C": "Neisseria sicca", "D": "Neisseria cinerea"}, "r": "A", "e": {"correcta": "Neisseria meningitidis ferments both glucose and maltose, which distinguishes it from N. gonorrhoeae, which ferments only glucose.", "incorrectas": {"B": "Neisseria gonorrhoeae ferments glucose but not maltose, the opposite of the pattern described.", "C": "Neisseria sicca is a nonpathogenic commensal species and is not the answer being tested for this classic fermentation distinction.", "D": "Neisseria cinerea is a commensal species and not the organism classically distinguished by maltose fermentation in this context."}}}, {"id": "anking-clinical-bacteriology-032", "fuente": "anking", "tema": 21, "anki": "1402676951058", "q": "Which serotype of Neisseria meningitidis historically lacked a vaccine (though one has now been developed)?", "o": {"A": "Type B", "B": "Type A", "C": "Type C", "D": "Type Y"}, "r": "A", "e": {"correcta": "Serogroup B was long the type without an available vaccine, since its capsular polysaccharide is poorly immunogenic (it resembles host neural cell adhesion molecules); type B vaccines have only recently become available. Type B causes a large share of meningococcal disease in the U.S. and other developed countries.", "incorrectas": {"B": "Serogroup A is covered by conjugate meningococcal vaccines.", "C": "Serogroup C is covered by conjugate meningococcal vaccines (e.g., MenACWY).", "D": "Serogroup Y is covered by conjugate meningococcal vaccines (e.g., MenACWY)."}}}, {"id": "anking-clinical-bacteriology-033", "fuente": "anking", "tema": 21, "anki": "1402678102937", "q": "What is the causative organism of meningococcemia?", "o": {"A": "Neisseria meningitidis", "B": "Neisseria gonorrhoeae", "C": "Streptococcus pneumoniae", "D": "Haemophilus influenzae"}, "r": "A", "e": {"correcta": "Meningococcemia, a bloodstream infection that can present with petechiae, purpura, and disseminated intravascular coagulation (e.g., Waterhouse-Friderichsen syndrome), is caused by Neisseria meningitidis.", "incorrectas": {"B": "Neisseria gonorrhoeae causes gonococcemia (disseminated gonococcal infection), a distinct entity from meningococcemia.", "C": "Streptococcus pneumoniae commonly causes pneumonia and meningitis but does not cause the classic meningococcemia syndrome.", "D": "Haemophilus influenzae can cause invasive disease including meningitis but is not the organism defining meningococcemia."}}}, {"id": "anking-clinical-bacteriology-034", "fuente": "anking", "tema": 21, "anki": "1402794276603", "q": "What organism causes relapsing fever?", "o": {"A": "Borrelia recurrentis", "B": "Borrelia burgdorferi", "C": "Rickettsia rickettsii", "D": "Leptospira interrogans"}, "r": "A", "e": {"correcta": "Borrelia recurrentis is a spirochete that causes relapsing fever, characterized by recurring febrile episodes due to antigenic variation of its surface proteins.", "incorrectas": {"B": "Borrelia burgdorferi causes Lyme disease, transmitted by Ixodes ticks, not relapsing fever.", "C": "Rickettsia rickettsii causes Rocky Mountain spotted fever, a different tick-borne illness.", "D": "Leptospira interrogans causes leptospirosis, transmitted via contact with animal urine-contaminated water, not relapsing fever."}}}, {"id": "anking-clinical-bacteriology-035", "fuente": "anking", "tema": 21, "anki": "1402794294219", "q": "How is relapsing fever (Borrelia recurrentis) transmitted?", "o": {"A": "Louse", "B": "Ixodes tick", "C": "Mosquito", "D": "Deer fly"}, "r": "A", "e": {"correcta": "Borrelia recurrentis causing epidemic relapsing fever is transmitted by the human body louse, in contrast to endemic relapsing fever caused by other Borrelia species transmitted by soft ticks.", "incorrectas": {"B": "Ixodes ticks transmit Borrelia burgdorferi (Lyme disease) and Babesia/Anaplasma, not louse-borne relapsing fever.", "C": "Mosquitoes transmit organisms like Plasmodium and arboviruses, not Borrelia recurrentis.", "D": "Deer flies are vectors for Francisella tularensis (tularemia), not Borrelia recurrentis."}}}, {"id": "anking-clinical-bacteriology-036", "fuente": "anking", "tema": 21, "anki": "1402795042313", "q": "Which pet animals are classically associated with Campylobacter infection?", "o": {"A": "Puppies", "B": "Kittens", "C": "Turtles", "D": "Parrots"}, "r": "A", "e": {"correcta": "Puppies (and other young pets) are classically associated with Campylobacter jejuni transmission, which causes bloody diarrhea and can be acquired from contact with infected animals in addition to contaminated poultry/food.", "incorrectas": {"B": "Kittens are more classically associated with Bartonella henselae (cat-scratch disease), not Campylobacter.", "C": "Turtles are classically associated with Salmonella transmission, not Campylobacter.", "D": "Parrots and other birds are classically associated with Chlamydophila psittaci (psittacosis), not Campylobacter."}}}, {"id": "anking-parasitology-037", "fuente": "anking", "tema": 22, "anki": "1403024912124", "q": "Which subspecies of Trypanosoma brucei causes African sleeping sickness in East Africa and is transmitted by the tsetse fly, typically causing a more acute course?", "o": {"A": "Trypanosoma brucei rhodesiense", "B": "Trypanosoma brucei gambiense", "C": "Trypanosoma cruzi", "D": "Leishmania donovani"}, "r": "A", "e": {"correcta": "Trypanosoma brucei rhodesiense is the East African subspecies of African sleeping sickness, transmitted by the tsetse fly, and causes a more acute, rapidly progressive disease than its West African counterpart.", "incorrectas": {"B": "T. b. gambiense causes the West African (chronic) form of sleeping sickness, not the East African form.", "C": "Trypanosoma cruzi causes Chagas disease in South America, transmitted by the reduviid bug, not African sleeping sickness.", "D": "Leishmania donovani causes visceral leishmaniasis (kala-azar), not African trypanosomiasis."}}}, {"id": "anking-parasitology-038", "fuente": "anking", "tema": 22, "anki": "1403025021992", "q": "Which subspecies of Trypanosoma brucei causes the chronic West African form of African sleeping sickness?", "o": {"A": "Trypanosoma brucei rhodesiense", "B": "Trypanosoma brucei gambiense", "C": "Trypanosoma cruzi", "D": "Trichomonas vaginalis"}, "r": "B", "e": {"correcta": "Trypanosoma brucei gambiense is the West African subspecies, producing a more chronic, indolent form of sleeping sickness ('the G's are from the West side').", "incorrectas": {"A": "T. b. rhodesiense is the East African subspecies, causing a more acute disease course.", "C": "Trypanosoma cruzi causes Chagas disease, transmitted in South America by the reduviid bug, unrelated to African sleeping sickness.", "D": "Trichomonas vaginalis is a sexually transmitted flagellate causing vaginitis, not African trypanosomiasis."}}}, {"id": "anking-parasitology-039", "fuente": "anking", "tema": 22, "anki": "1403025074063", "q": "A CNS protozoal infection caused by Trypanosoma brucei subspecies, diagnosed by identifying trypomastigotes on blood smear, is known as what condition?", "o": {"A": "African Sleeping Sickness", "B": "Chagas Disease", "C": "Malaria", "D": "Toxoplasmosis"}, "r": "A", "e": {"correcta": "African sleeping sickness (human African trypanosomiasis) is caused by T. b. rhodesiense or T. b. gambiense, and is diagnosed by visualizing trypomastigotes on a blood smear, with CNS involvement causing sleep disturbances.", "incorrectas": {"B": "Chagas disease is caused by Trypanosoma cruzi in South America and typically causes cardiomyopathy and megacolon/megaesophagus rather than the classic CNS sleep disturbance.", "C": "Malaria is caused by Plasmodium species and diagnosed by ring forms/schizonts on blood smear, not trypomastigotes.", "D": "Toxoplasmosis is caused by Toxoplasma gondii and typically diagnosed serologically or by seeing tachyzoites/cysts, not trypomastigotes."}}}, {"id": "anking-parasitology-040", "fuente": "anking", "tema": 22, "anki": "1403046937622", "q": "In which geographic region does Chagas disease predominantly occur?", "o": {"A": "South America", "B": "East Africa", "C": "Southeast Asia", "D": "Western Europe"}, "r": "A", "e": {"correcta": "Chagas disease, caused by Trypanosoma cruzi, predominantly occurs in South and Central America, where the reduviid bug vector is endemic.", "incorrectas": {"B": "East Africa is associated with Trypanosoma brucei rhodesiense (African sleeping sickness), not Chagas disease.", "C": "Southeast Asia is not a predominant region for Chagas disease.", "D": "Western Europe is not endemic for the reduviid bug vector or Chagas disease."}}}, {"id": "anking-parasitology-041", "fuente": "anking", "tema": 22, "anki": "1403046948446", "q": "How is Chagas disease (Trypanosoma cruzi) transmitted to humans?", "o": {"A": "Reduviid bug (\"kissing bug\") feces", "B": "Tsetse fly bite", "C": "Contaminated drinking water", "D": "Sandfly bite"}, "r": "A", "e": {"correcta": "Chagas disease is transmitted when the painless bite of the reduviid (kissing) bug is followed by scratching its feces, which contain Trypanosoma cruzi, into the wound or mucous membranes.", "incorrectas": {"B": "The tsetse fly transmits Trypanosoma brucei (African sleeping sickness), not Chagas disease.", "C": "Contaminated water is the transmission route for Giardia, not Chagas disease.", "D": "Sandflies transmit Leishmania species, not Trypanosoma cruzi."}}}, {"id": "anking-parasitology-042", "fuente": "anking", "tema": 22, "anki": "1499805244428", "q": "What is the primary route of transmission for Giardia infection?", "o": {"A": "Fecal-oral", "B": "Vector-borne (insect bite)", "C": "Airborne droplet", "D": "Sexual contact"}, "r": "A", "e": {"correcta": "Giardia is transmitted via the fecal-oral route, classically through ingestion of unfiltered water contaminated with cysts, common among campers and travelers.", "incorrectas": {"B": "Giardia is not transmitted by insect vectors, unlike Trypanosoma or Leishmania species.", "C": "Giardia is not spread via airborne droplets.", "D": "Sexual transmission is not the typical route for Giardia (unlike Trichomonas vaginalis)."}}}, {"id": "anking-parasitology-043", "fuente": "anking", "tema": 22, "anki": "1499805446684", "q": "Ingestion of which infective form of Giardia in contaminated water leads to human infection?", "o": {"A": "Cysts", "B": "Trophozoites", "C": "Oocysts", "D": "Sporozoites"}, "r": "A", "e": {"correcta": "Giardia cysts are the environmentally resistant, infective form ingested via contaminated water, which then excyst into trophozoites in the small intestine.", "incorrectas": {"B": "Trophozoites are the motile, feeding form found in the intestine but are not the typical infective form transmitted via water.", "C": "Oocysts are the infective form of organisms like Cryptosporidium and Toxoplasma, not Giardia.", "D": "Sporozoites are a stage seen in apicomplexan parasites like Plasmodium, not Giardia."}}}, {"id": "anking-parasitology-044", "fuente": "anking", "tema": 22, "anki": "1499805623100", "q": "Which parasite is classically associated with campers who drink unpurified water from streams or lakes?", "o": {"A": "Giardia", "B": "Trypanosoma cruzi", "C": "Toxoplasma gondii", "D": "Plasmodium falciparum"}, "r": "A", "e": {"correcta": "Giardia is the classic 'camper's diarrhea' parasite, acquired by drinking water contaminated with cysts from streams or lakes.", "incorrectas": {"B": "Trypanosoma cruzi is transmitted by the reduviid bug, not contaminated water.", "C": "Toxoplasma gondii is typically acquired from cat feces or undercooked meat, not water.", "D": "Plasmodium falciparum is transmitted by mosquito bite, not water ingestion."}}}, {"id": "anking-parasitology-045", "fuente": "anking", "tema": 22, "anki": "1499805711183", "q": "Giardia infection is commonly transmitted through consumption of poorly purified what substance?", "o": {"A": "Water", "B": "Meat", "C": "Dairy products", "D": "Soil"}, "r": "A", "e": {"correcta": "Giardia is classically transmitted via ingestion of poorly purified water contaminated with cysts.", "incorrectas": {"B": "Undercooked meat is more associated with Toxoplasma or Taenia infections, not Giardia.", "C": "Dairy products are not a typical vehicle for Giardia transmission.", "D": "Direct soil ingestion is not the classic transmission route for Giardia (unlike some helminths)."}}}, {"id": "anking-parasitology-046", "fuente": "anking", "tema": 22, "anki": "1499805758022", "q": "Giardia infection commonly presents with bloating and which combination of symptoms?", "o": {"A": "Flatulence and foul-smelling diarrhea", "B": "Bloody diarrhea and tenesmus", "C": "Constipation and abdominal rigidity", "D": "High fever and rigors"}, "r": "A", "e": {"correcta": "Giardia classically causes bloating, flatulence, and foul-smelling diarrhea (steatorrhea) due to malabsorption in the small intestine.", "incorrectas": {"B": "Bloody diarrhea and tenesmus suggest an invasive pathogen like Entamoeba histolytica or Shigella; Giardia trophozoites do not invade tissue.", "C": "Constipation and rigidity are not characteristic of Giardia, which causes diarrhea rather than constipation.", "D": "High fever and rigors are more typical of systemic infections like malaria, not Giardia."}}}, {"id": "anking-parasitology-047", "fuente": "anking", "tema": 22, "anki": "1499806016690", "q": "The steatorrhea seen in Giardia infection is hypothesized to result from excess production of what substance impairing fat absorption in which location?", "o": {"A": "Mucus in the intestines", "B": "Bile in the gallbladder", "C": "Gastric acid in the stomach", "D": "Pancreatic enzymes in the pancreas"}, "r": "A", "e": {"correcta": "Giardia trophozoites are hypothesized to stimulate excess mucus production that coats the intestinal mucosa, impairing fat absorption and producing fatty, foul-smelling stools.", "incorrectas": {"B": "Excess bile is not the proposed mechanism; Giardia does not primarily affect gallbladder bile secretion.", "C": "Excess gastric acid is not implicated in Giardia-related steatorrhea.", "D": "Pancreatic enzyme excess is not the mechanism; if anything, malabsorption relates to mucosal mucus, not enzyme overproduction."}}}, {"id": "anking-parasitology-048", "fuente": "anking", "tema": 22, "anki": "1499806145121", "q": "Deficiencies of which class of vitamins can occur with Giardia infection due to fat malabsorption?", "o": {"A": "Fat-soluble vitamins (A, D, E, K)", "B": "Water-soluble B vitamins", "C": "Vitamin C only", "D": "Vitamin B12 only"}, "r": "A", "e": {"correcta": "Because Giardia causes fat malabsorption (steatorrhea) from excess intestinal mucus, deficiencies of the fat-soluble vitamins A, D, E, and K can occur.", "incorrectas": {"B": "Water-soluble B vitamin deficiency is not the classic consequence of Giardia-induced fat malabsorption.", "C": "Isolated vitamin C deficiency (scurvy) is unrelated to fat malabsorption from Giardia.", "D": "Isolated B12 deficiency is classically linked to conditions like pernicious anemia or Diphyllobothrium latum infection, not Giardia."}}}, {"id": "anking-parasitology-049", "fuente": "anking", "tema": 22, "anki": "1499806234933", "q": "What body weight change is commonly seen with Giardia infection?", "o": {"A": "Weight loss", "B": "Significant weight gain", "C": "No change in weight", "D": "Rapid fluid-related weight gain (edema)"}, "r": "A", "e": {"correcta": "Giardia infection commonly causes weight loss due to malabsorption of fats and nutrients from excess intestinal mucus production and chronic diarrhea.", "incorrectas": {"B": "Weight gain is not associated with Giardia; malabsorption leads to weight loss, not gain.", "C": "Weight is typically affected (loss), not unchanged, due to chronic malabsorptive diarrhea.", "D": "Edema-related weight gain is not a typical feature of Giardia infection."}}}, {"id": "anking-parasitology-050", "fuente": "anking", "tema": 22, "anki": "1499806454395", "q": "Does the trophozoite form of Giardia invade the intestinal wall?", "o": {"A": "No, it only attaches to the intestinal wall without invading", "B": "Yes, it invades deeply causing bloody dysentery", "C": "Yes, it invades the liver via portal circulation", "D": "Yes, it invades the muscularis layer causing perforation"}, "r": "A", "e": {"correcta": "Giardia trophozoites attach to the intestinal mucosa via a ventral sucking disc but do not invade the intestinal wall, which is why bloody diarrhea (dysentery) is not seen.", "incorrectas": {"B": "Invasive bloody dysentery is characteristic of Entamoeba histolytica, not Giardia, which does not invade tissue.", "C": "Giardia does not have a hepatic invasive phase like Entamoeba histolytica abscesses.", "D": "Giardia does not invade deep bowel layers or cause perforation; it remains attached at the mucosal surface."}}}, {"id": "anking-parasitology-051", "fuente": "anking", "tema": 22, "anki": "1499806564833", "q": "Does Giardia infection classically present with bloody diarrhea (dysentery)?", "o": {"A": "No, because trophozoites attach to but do not invade the intestinal wall", "B": "Yes, because trophozoites invade and ulcerate the colonic mucosa", "C": "Yes, because of associated bacterial superinfection", "D": "Yes, due to hemorrhagic cyst rupture"}, "r": "A", "e": {"correcta": "Giardia does not cause bloody diarrhea because its trophozoites attach to the intestinal wall without invading it, resulting in nonbloody, foul-smelling, fatty diarrhea instead.", "incorrectas": {"B": "Invasive ulceration causing bloody diarrhea is characteristic of Entamoeba histolytica, not Giardia.", "C": "Bacterial superinfection is not the accepted explanation for diarrhea in giardiasis.", "D": "Giardia cysts do not rupture hemorrhagically; this is not a recognized mechanism of disease."}}}, {"id": "anking-parasitology-052", "fuente": "anking", "tema": 22, "anki": "1499806605015", "q": "Identification of what form, in what specimen, is diagnostic of Giardia infection?", "o": {"A": "Trophozoites in stool", "B": "Cysts in blood", "C": "Sporozoites in urine", "D": "Tachyzoites in cerebrospinal fluid"}, "r": "A", "e": {"correcta": "Finding Giardia trophozoites (or cysts) in the stool via microscopy is diagnostic of giardiasis, reflecting the organism's attachment to the intestinal mucosa.", "incorrectas": {"B": "Giardia cysts are not found in blood; diagnosis relies on stool examination, not blood smear.", "C": "Sporozoites are relevant to organisms like Plasmodium or Toxoplasma, not Giardia, and are not found in urine.", "D": "Tachyzoites in CSF would suggest Toxoplasma or another CNS parasitic infection, not Giardia."}}}, {"id": "anking-parasitology-053", "fuente": "anking", "tema": 22, "anki": "1499806740474", "q": "Which diagnostic tests are used to confirm a Giardia infection?", "o": {"A": "Stool ova and parasites (O&P) exam and stool ELISA antigen test", "B": "Blood smear for trypomastigotes", "C": "Serum antibody titers only", "D": "Skin scraping microscopy"}, "r": "A", "e": {"correcta": "Giardia is diagnosed via stool ova and parasites (O&P) microscopy to identify cysts/trophozoites, and/or a stool ELISA antigen test, which has higher sensitivity.", "incorrectas": {"B": "Blood smear for trypomastigotes is used to diagnose Trypanosoma infections, not Giardia.", "C": "Serum antibody titers are not the standard diagnostic approach for Giardia; stool-based tests are preferred.", "D": "Skin scraping microscopy is used for conditions like scabies or cutaneous leishmaniasis, not Giardia."}}}, {"id": "anking-parasitology-054", "fuente": "anking", "tema": 22, "anki": "1499806797037", "q": "Giardia trophozoites in the stool transform into which form, allowing transmission to other people?", "o": {"A": "Cysts", "B": "Oocysts", "C": "Sporozoites", "D": "Merozoites"}, "r": "A", "e": {"correcta": "Giardia trophozoites encyst in the colon to form environmentally resistant cysts that are shed in stool and transmitted fecal-orally to new hosts.", "incorrectas": {"B": "Oocysts are the transmissible form of organisms like Cryptosporidium and Toxoplasma, not Giardia.", "C": "Sporozoites are a stage of apicomplexan parasites (e.g., Plasmodium), not part of the Giardia life cycle.", "D": "Merozoites are a Plasmodium life cycle stage involved in red blood cell infection, not relevant to Giardia."}}}, {"id": "anking-endocrine-physiology-055", "fuente": "anking", "tema": 23, "anki": "1461849983680", "q": "Translation of a preprohormone begins with a signal peptide at the N terminus in which cellular compartment?", "o": {"A": "Cytoplasm", "B": "Nucleus", "C": "Golgi apparatus", "D": "Mitochondria"}, "r": "A", "e": {"correcta": "Translation of preprohormone mRNA begins on free ribosomes in the cytoplasm/cytosol, producing a signal peptide at the N-terminus that directs the growing polypeptide to the rough ER.", "incorrectas": {"B": "The nucleus is where transcription of the mRNA occurs, not translation of the protein.", "C": "The Golgi apparatus processes and packages proteins after translation, not where translation begins.", "D": "Mitochondria have their own separate translation machinery for mitochondrial proteins, not for peptide hormone synthesis."}}}, {"id": "anking-endocrine-physiology-056", "fuente": "anking", "tema": 23, "anki": "1461852688246", "q": "In the first step of peptide hormone synthesis, which molecule is synthesized in the cytosol under the direction of specific mRNA?", "o": {"A": "Preprohormone", "B": "Prohormone", "C": "Mature hormone", "D": "Signal peptidase"}, "r": "A", "e": {"correcta": "The preprohormone is the initial translation product synthesized in the cytosol from specific mRNA; it is later cleaved to form the prohormone and eventually the mature hormone.", "incorrectas": {"B": "The prohormone is formed later, after cleavage of the signal peptide from the preprohormone in the ER.", "C": "The mature hormone results from further processing (cleavage) of the prohormone, typically in secretory vesicles.", "D": "Signal peptidase is an enzyme that cleaves the signal peptide; it is not the synthesized product itself."}}}, {"id": "anking-endocrine-physiology-057", "fuente": "anking", "tema": 23, "anki": "1461852697255", "q": "All steroid hormones are derivatives of which molecule?", "o": {"A": "Cholesterol", "B": "Tyrosine", "C": "Arachidonic acid", "D": "Glycine"}, "r": "A", "e": {"correcta": "Steroid hormones (glucocorticoids, mineralocorticoids, sex steroids) are all synthesized from cholesterol via enzymatic modification in steroidogenic tissues.", "incorrectas": {"B": "Tyrosine is the precursor for amine hormones like catecholamines and thyroid hormones, not steroids.", "C": "Arachidonic acid is the precursor for eicosanoids (prostaglandins, leukotrienes), not steroid hormones.", "D": "Glycine is an amino acid used in protein/peptide synthesis and heme synthesis, not a steroid precursor."}}}, {"id": "anking-endocrine-physiology-058", "fuente": "anking", "tema": 23, "anki": "1461852700804", "q": "Amine hormones such as catecholamines and thyroid hormones are derivatives of which amino acid?", "o": {"A": "Tyrosine", "B": "Tryptophan", "C": "Histidine", "D": "Phenylalanine"}, "r": "A", "e": {"correcta": "Amine hormones, including catecholamines (epinephrine, norepinephrine, dopamine) and thyroid hormones, are synthesized from the amino acid tyrosine.", "incorrectas": {"B": "Tryptophan is the precursor for serotonin and melatonin, not catecholamines or thyroid hormones.", "C": "Histidine is the precursor for histamine, not amine hormones like catecholamines.", "D": "Phenylalanine is converted to tyrosine but is not itself the direct precursor named for these hormones."}}}, {"id": "anking-endocrine-physiology-059", "fuente": "anking", "tema": 23, "anki": "1461852703655", "q": "Amine hormones include thyroid hormones and which other class of hormones (epinephrine, norepinephrine, and dopamine)?", "o": {"A": "Catecholamines", "B": "Glucocorticoids", "C": "Eicosanoids", "D": "Gonadotropins"}, "r": "A", "e": {"correcta": "Amine hormones are divided into thyroid hormones and catecholamines (epinephrine, norepinephrine, dopamine), both derived from tyrosine.", "incorrectas": {"B": "Glucocorticoids are steroid hormones derived from cholesterol, not amine hormones.", "C": "Eicosanoids are lipid-derived signaling molecules from arachidonic acid, not amine hormones.", "D": "Gonadotropins (like LH, FSH) are peptide/glycoprotein hormones, not amine hormones."}}}, {"id": "anking-endocrine-physiology-060", "fuente": "anking", "tema": 23, "anki": "1461852716510", "q": "In which type of feedback does a feature of hormone action inhibit further secretion of that hormone?", "o": {"A": "Negative feedback", "B": "Positive feedback", "C": "Feedforward regulation", "D": "Autocrine signaling"}, "r": "A", "e": {"correcta": "Negative feedback is the mechanism by which the effect of a hormone suppresses further secretion of that same hormone, maintaining homeostasis (e.g., cortisol inhibiting ACTH/CRH).", "incorrectas": {"B": "Positive feedback amplifies further secretion rather than inhibiting it.", "C": "Feedforward regulation anticipates a change rather than responding to inhibit ongoing secretion.", "D": "Autocrine signaling refers to a cell responding to its own secreted signal, not a feedback loop type."}}}, {"id": "anking-endocrine-physiology-061", "fuente": "anking", "tema": 23, "anki": "1461852729909", "q": "In which type of feedback does a feature of hormone action cause more secretion of that hormone?", "o": {"A": "Positive feedback", "B": "Negative feedback", "C": "Paracrine inhibition", "D": "Down-regulation"}, "r": "A", "e": {"correcta": "Positive feedback occurs when hormone action stimulates further secretion of that hormone, as seen with the LH surge triggered by estrogen before ovulation.", "incorrectas": {"B": "Negative feedback would inhibit rather than increase further secretion.", "C": "Paracrine inhibition refers to a nearby cell suppressing signaling, not a hormone increasing its own secretion.", "D": "Down-regulation refers to decreased receptor number/affinity, not increased hormone secretion."}}}, {"id": "anking-endocrine-physiology-062", "fuente": "anking", "tema": 23, "anki": "1461852733375", "q": "Which term is defined as the hormone concentration that produces 50% of the maximal response?", "o": {"A": "Sensitivity", "B": "Efficacy", "C": "Potency ceiling", "D": "Bioavailability"}, "r": "A", "e": {"correcta": "Sensitivity is defined as the hormone concentration needed to produce 50% of the maximal response (similar to EC50), reflecting how responsive the target tissue is.", "incorrectas": {"B": "Efficacy refers to the maximal effect a hormone can produce, not the concentration needed for half-maximal response.", "C": "\"Potency ceiling\" is not a standard physiological term for this concept.", "D": "Bioavailability refers to the fraction of administered substance reaching systemic circulation, unrelated to this definition."}}}, {"id": "anking-endocrine-physiology-063", "fuente": "anking", "tema": 23, "anki": "1461852736440", "q": "If more hormone is required to produce 50% of the maximal response, what has happened to the sensitivity of the target tissue?", "o": {"A": "Decrease", "B": "Increase", "C": "No change", "D": "Doubling"}, "r": "A", "e": {"correcta": "Requiring more hormone to achieve the same half-maximal response indicates decreased sensitivity of the target tissue, often due to receptor down-regulation.", "incorrectas": {"B": "An increase in sensitivity would mean less hormone is needed, not more.", "C": "A true \"no change\" would mean the same hormone concentration still produces 50% response.", "D": "\"Doubling\" is not a recognized description of a sensitivity change in this context."}}}, {"id": "anking-endocrine-physiology-064", "fuente": "anking", "tema": 23, "anki": "1461852748718", "q": "Hormone sensitivity of a target tissue can be changed by altering the number of receptors and by altering which other receptor property?", "o": {"A": "Affinity", "B": "Location", "C": "Molecular weight", "D": "Color"}, "r": "A", "e": {"correcta": "Target tissue sensitivity can be modulated either by changing the number of receptors or by changing their affinity for the hormone.", "incorrectas": {"B": "Receptor location within the cell is not the classic mechanism described for altering sensitivity in this context.", "C": "Molecular weight of receptors is not a regulated variable affecting hormone sensitivity.", "D": "Color is not a relevant physiological property of receptors."}}}, {"id": "anking-endocrine-physiology-065", "fuente": "anking", "tema": 23, "anki": "1461852752397", "q": "What is the term for the mechanism in which a hormone decreases the number or affinity of its own receptors in a target tissue?", "o": {"A": "Down-regulation", "B": "Up-regulation", "C": "Positive feedback", "D": "Receptor priming"}, "r": "A", "e": {"correcta": "Down-regulation occurs when chronically elevated hormone levels decrease the number or affinity of their receptors, reducing target tissue sensitivity.", "incorrectas": {"B": "Up-regulation is the opposite process, increasing receptor number or affinity.", "C": "Positive feedback describes a hormone promoting its own secretion, not receptor regulation.", "D": "\"Receptor priming\" is not the standard term for this receptor down-modulation process."}}}, {"id": "anking-endocrine-physiology-066", "fuente": "anking", "tema": 23, "anki": "1461852760390", "q": "What is the term for the mechanism in which a hormone increases the number or affinity of its own receptors in a target tissue?", "o": {"A": "Up-regulation", "B": "Down-regulation", "C": "Negative feedback", "D": "Desensitization"}, "r": "A", "e": {"correcta": "Up-regulation is the process by which a hormone increases the number or affinity of its receptors, enhancing target tissue sensitivity.", "incorrectas": {"B": "Down-regulation is the opposite process, decreasing receptor number or affinity.", "C": "Negative feedback describes inhibition of hormone secretion, not a change in receptor number/affinity.", "D": "Desensitization typically refers to reduced responsiveness, the opposite of up-regulation."}}}, {"id": "anking-endocrine-physiology-067", "fuente": "anking", "tema": 23, "anki": "1461856470859", "q": "How many subunits do heterotrimeric G proteins have?", "o": {"A": "Three", "B": "Two", "C": "Four", "D": "Five"}, "r": "A", "e": {"correcta": "Heterotrimeric G proteins consist of three subunits: alpha, beta, and gamma.", "incorrectas": {"B": "Two subunits would not account for the beta and gamma subunits in addition to alpha.", "C": "Four subunits overstates the composition; only alpha, beta, and gamma are present.", "D": "Five subunits is incorrect; the canonical G protein complex has three subunits."}}}, {"id": "anking-endocrine-physiology-068", "fuente": "anking", "tema": 23, "anki": "1461857120583", "q": "Which proteins facilitate dissociation of GDP so that GTP can bind more rapidly, increasing the rate of G protein activation?", "o": {"A": "Guanine nucleotide releasing factors (GRFs)", "B": "GTPase activating proteins (GAPs)", "C": "Adenylyl cyclase", "D": "Phospholipase C"}, "r": "A", "e": {"correcta": "Guanine nucleotide releasing factors (GRFs) promote GDP release from the G protein alpha subunit, allowing GTP to bind and activate the G protein.", "incorrectas": {"B": "GTPase activating proteins (GAPs) promote GTP hydrolysis, which decreases (not increases) G protein activation.", "C": "Adenylyl cyclase is a downstream effector enzyme activated by G proteins, not a regulator of GDP/GTP exchange.", "D": "Phospholipase C is also a downstream effector enzyme, not involved in nucleotide exchange on G proteins."}}}, {"id": "anking-endocrine-physiology-069", "fuente": "anking", "tema": 23, "anki": "1461857134573", "q": "Which proteins facilitate hydrolysis of GTP, decreasing the rate of G protein activation?", "o": {"A": "GTPase activating proteins (GAPs)", "B": "Guanine nucleotide releasing factors (GRFs)", "C": "Protein kinase A", "D": "Beta-arrestin"}, "r": "A", "e": {"correcta": "GTPase activating proteins (GAPs) accelerate the hydrolysis of GTP to GDP on the G protein alpha subunit, terminating G protein activation.", "incorrectas": {"B": "Guanine nucleotide releasing factors (GRFs) promote GDP release to allow GTP binding, increasing (not decreasing) activation.", "C": "Protein kinase A is a downstream effector activated by cAMP, not a regulator of G protein GTP hydrolysis.", "D": "Beta-arrestin is involved in receptor desensitization and internalization, not directly in GTP hydrolysis on G-alpha."}}}, {"id": "anking-endocrine-physiology-070", "fuente": "anking", "tema": 23, "anki": "1461857141003", "q": "In the first step of the adenylyl cyclase/phospholipase C signaling mechanism, hormone binding to its receptor causes release of which nucleotide from the alpha subunit, with replacement by which nucleotide?", "o": {"A": "GDP is released and replaced by GTP", "B": "GTP is released and replaced by GDP", "C": "ATP is released and replaced by ADP", "D": "cAMP is released and replaced by AMP"}, "r": "A", "e": {"correcta": "Hormone binding to its receptor promotes release of GDP from the G-alpha subunit, which is then replaced by GTP, activating the G protein to signal through adenylyl cyclase or phospholipase C.", "incorrectas": {"B": "This reverses the actual sequence; GTP replaces GDP, not the other way around, during activation.", "C": "ATP/ADP exchange is not the mechanism of G protein activation; it involves guanine nucleotides, not adenine nucleotides.", "D": "cAMP is a downstream second messenger produced by adenylyl cyclase, not the nucleotide exchanged on the G-alpha subunit."}}}, {"id": "anking-endocrine-physiology-071", "fuente": "anking", "tema": 23, "anki": "1461864718849", "q": "Which hormone acts through a receptor guanylyl cyclase?", "o": {"A": "Atrial natriuretic peptide (ANP)", "B": "Insulin", "C": "Cortisol", "D": "Glucagon"}, "r": "A", "e": {"correcta": "Atrial natriuretic peptide (ANP), along with other natriuretic peptides like BNP, signals through a receptor guanylyl cyclase, generating cGMP as a second messenger.", "incorrectas": {"B": "Insulin signals through a receptor tyrosine kinase, not a guanylyl cyclase.", "C": "Cortisol is a steroid hormone that acts via intracellular nuclear receptors, not a membrane guanylyl cyclase.", "D": "Glucagon acts through a G protein-coupled receptor linked to adenylyl cyclase, not guanylyl cyclase."}}}, {"id": "anking-endocrine-physiology-072", "fuente": "anking", "tema": 23, "anki": "1461865790194", "q": "Binding of atrial natriuretic peptide to its receptor guanylyl cyclase causes conversion of which molecule into which second messenger?", "o": {"A": "GTP is converted to cGMP", "B": "ATP is converted to cAMP", "C": "GDP is converted to GTP", "D": "cGMP is converted to GMP"}, "r": "A", "e": {"correcta": "Receptor guanylyl cyclase activation by ANP catalyzes conversion of GTP to cGMP, which serves as the intracellular second messenger mediating ANP's effects (e.g., vasodilation, natriuresis).", "incorrectas": {"B": "ATP to cAMP conversion is catalyzed by adenylyl cyclase in a different signaling pathway, not the ANP-guanylyl cyclase pathway.", "C": "GDP to GTP conversion describes G protein nucleotide exchange, not the guanylyl cyclase reaction.", "D": "cGMP to GMP is a degradation reaction performed by phosphodiesterases, the reverse of what occurs upon ANP receptor activation."}}}, {"id": "anking-endocrine-pharmacology-073", "fuente": "anking", "tema": 24, "anki": "1391740893804", "q": "Which drug is a recombinant form of T4 used as thyroid hormone replacement, acting as an agonist at thyroid hormone receptors?", "o": {"A": "Levothyroxine", "B": "Liothyronine", "C": "Propylthiouracil", "D": "Methimazole"}, "r": "A", "e": {"correcta": "Levothyroxine is synthetic T4 and is the standard replacement therapy for hypothyroidism, acting as a direct agonist at thyroid hormone receptors after peripheral conversion to T3.", "incorrectas": {"B": "Liothyronine is synthetic T3, not a recombinant form of T4, and is used less commonly as first-line replacement.", "C": "Propylthiouracil is an antithyroid drug that inhibits thyroid hormone synthesis, not a replacement hormone.", "D": "Methimazole is an antithyroid drug used to treat hyperthyroidism, not a hormone replacement agent."}}}, {"id": "anking-endocrine-pharmacology-074", "fuente": "anking", "tema": 24, "anki": "1405141731050", "q": "Which teratogenic complication is associated with methimazole use in the first trimester of pregnancy?", "o": {"A": "Aplasia cutis", "B": "Neural tube defects", "C": "Limb reduction defects", "D": "Ebstein anomaly"}, "r": "A", "e": {"correcta": "Methimazole crosses the placenta and, when used in the first trimester, is associated with aplasia cutis congenita (a scalp defect) and other congenital anomalies (methimazole embryopathy).", "incorrectas": {"B": "Neural tube defects are classically linked to folate deficiency or valproate use, not methimazole.", "C": "Limb reduction defects are associated with thalidomide, not methimazole.", "D": "Ebstein anomaly is classically associated with lithium use during pregnancy."}}}, {"id": "anking-endocrine-pharmacology-075", "fuente": "anking", "tema": 24, "anki": "1405141793183", "q": "Which drug used to treat hyperthyroidism is particularly associated with hepatotoxicity, making it preferred mainly in the first trimester of pregnancy despite this risk?", "o": {"A": "Propylthiouracil", "B": "Methimazole", "C": "Levothyroxine", "D": "Octreotide"}, "r": "A", "e": {"correcta": "Propylthiouracil (PTU) carries a well-known risk of severe hepatotoxicity, including liver failure, which limits its long-term use compared to methimazole.", "incorrectas": {"B": "Methimazole is the preferred antithyroid drug outside of the first trimester because it has a better hepatic safety profile than PTU.", "C": "Levothyroxine is a thyroid hormone replacement, not a treatment for hyperthyroidism, and is not linked to hepatotoxicity.", "D": "Octreotide is a somatostatin analog unrelated to thyroid hormone synthesis or hepatotoxicity."}}}, {"id": "anking-endocrine-pharmacology-076", "fuente": "anking", "tema": 24, "anki": "1461634834294", "q": "Which drug, a somatostatin analog, may be used to treat the secretory diarrhea caused by VIPoma and carcinoid syndrome?", "o": {"A": "Octreotide", "B": "Levothyroxine", "C": "Glipizide", "D": "Metformin"}, "r": "A", "e": {"correcta": "Octreotide is a somatostatin analog that inhibits secretion of hormones such as VIP and serotonin, making it effective for the secretory diarrhea of VIPoma and carcinoid syndrome.", "incorrectas": {"B": "Levothyroxine is a thyroid hormone replacement with no role in secretory diarrhea.", "C": "Glipizide is a sulfonylurea used for type 2 diabetes, unrelated to VIPoma or carcinoid syndrome.", "D": "Metformin is a biguanide antidiabetic drug with no effect on VIP or serotonin secretion."}}}, {"id": "anking-endocrine-pharmacology-077", "fuente": "anking", "tema": 24, "anki": "1462844350121", "q": "Activation of which adrenergic receptor increases production of insulin from pancreatic beta cells?", "o": {"A": "β2", "B": "α1", "C": "α2", "D": "β1"}, "r": "A", "e": {"correcta": "β2-adrenergic receptor activation on pancreatic beta cells stimulates insulin secretion, which is why β2-agonists can slightly increase insulin release.", "incorrectas": {"B": "α1 receptors mediate vasoconstriction and other effects but do not primarily drive increased insulin secretion.", "C": "α2 receptor activation on beta cells actually inhibits insulin release, the opposite effect of β2 stimulation.", "D": "β1 receptors primarily mediate cardiac and renin effects, not pancreatic insulin secretion."}}}, {"id": "anking-endocrine-pharmacology-078", "fuente": "anking", "tema": 24, "anki": "1462844554684", "q": "What effect does insulin have on Na+-K+-ATPase activity in cells?", "o": {"A": "Increased activity, causing increased K+ uptake into cells", "B": "Decreased activity, causing K+ efflux from cells", "C": "No effect on Na+-K+-ATPase activity", "D": "Increased activity, causing increased Na+ uptake into cells"}, "r": "A", "e": {"correcta": "Insulin stimulates Na+-K+-ATPase activity, driving potassium into cells; this is exploited clinically by giving IV insulin (with glucose) to treat hyperkalemia.", "incorrectas": {"B": "Insulin increases, not decreases, Na+-K+-ATPase activity, so it does not cause potassium efflux.", "C": "Insulin has a clear stimulatory effect on this pump, so 'no effect' is incorrect.", "D": "The pump moves Na+ out of the cell and K+ into the cell; insulin enhances K+ uptake, not Na+ uptake."}}}, {"id": "anking-endocrine-pharmacology-079", "fuente": "anking", "tema": 24, "anki": "1462845596752", "q": "When insulin acts on liver tissue, what happens to glycogenesis and glycogenolysis, respectively?", "o": {"A": "Increased glycogenesis / decreased glycogenolysis", "B": "Decreased glycogenesis / increased glycogenolysis", "C": "Increased glycogenesis / increased glycogenolysis", "D": "Decreased glycogenesis / decreased glycogenolysis"}, "r": "A", "e": {"correcta": "Insulin promotes glycogen storage in the liver by increasing glycogenesis while simultaneously suppressing glycogenolysis (glycogen breakdown), lowering blood glucose.", "incorrectas": {"B": "This describes the effect of glucagon (a catabolic, glucose-raising hormone), the opposite of insulin's action.", "C": "Insulin cannot simultaneously increase both synthesis and breakdown of glycogen; these are reciprocally regulated.", "D": "Insulin does not decrease glycogenesis; it promotes glycogen storage, so this pairing is incorrect."}}}, {"id": "anking-endocrine-pharmacology-080", "fuente": "anking", "tema": 24, "anki": "1462849100249", "q": "When insulin acts on adipose tissue, what happens to triglyceride storage and lipolysis, respectively?", "o": {"A": "Increased triglyceride storage / decreased lipolysis", "B": "Decreased triglyceride storage / increased lipolysis", "C": "Increased triglyceride storage / increased lipolysis", "D": "Decreased triglyceride storage / decreased lipolysis"}, "r": "A", "e": {"correcta": "Insulin is anabolic in adipose tissue: it increases triglyceride storage (via lipoprotein lipase activation) and inhibits hormone-sensitive lipase, decreasing lipolysis.", "incorrectas": {"B": "This pattern (decreased storage, increased lipolysis) describes a catabolic, fasting state driven by glucagon and catecholamines, not insulin.", "C": "Insulin cannot simultaneously promote storage and increase breakdown of triglycerides; these processes are reciprocally regulated.", "D": "Insulin does not decrease triglyceride storage; it promotes fat storage in adipocytes."}}}, {"id": "anking-endocrine-pharmacology-081", "fuente": "anking", "tema": 24, "anki": "1462849107376", "q": "Insulin Glulisine, Aspart, and Lispro are characterized by what type of action and duration?", "o": {"A": "Rapid", "B": "Short", "C": "Intermediate", "D": "Long"}, "r": "A", "e": {"correcta": "Glulisine, aspart, and lispro are rapid-acting insulin analogs with onset around 15 minutes and peak effect at 45-75 minutes, ideal for controlling postprandial glucose spikes.", "incorrectas": {"B": "Short-acting describes regular insulin, which has a slower onset (~30 minutes) and later peak (2-4 hours) than these rapid-acting analogs.", "C": "Intermediate-acting describes NPH insulin, which has a much later onset and longer duration.", "D": "Long-acting describes insulin detemir and glargine, which provide steady background insulin levels rather than rapid peaks."}}}, {"id": "anking-endocrine-pharmacology-082", "fuente": "anking", "tema": 24, "anki": "1462849116753", "q": "Rapid-acting insulins such as glulisine, aspart, and lispro are especially useful for controlling which type of glucose spike?", "o": {"A": "Postprandial", "B": "Fasting", "C": "Nocturnal", "D": "Stress-induced hyperglycemia"}, "r": "A", "e": {"correcta": "Because rapid-acting insulins have a fast onset and short peak, they are given with meals to blunt the postprandial (after-meal) rise in blood glucose.", "incorrectas": {"B": "Fasting glucose levels are better controlled by long-acting basal insulins like glargine or detemir.", "C": "Nocturnal glucose control is typically managed with long- or intermediate-acting basal insulin, not rapid-acting insulin.", "D": "Stress-induced hyperglycemia is not the specific target of rapid-acting insulin dosing; these are meal-timed doses."}}}, {"id": "anking-endocrine-pharmacology-083", "fuente": "anking", "tema": 24, "anki": "1462849123696", "q": "Regular insulin is characterized by what type of action and duration?", "o": {"A": "Short", "B": "Rapid", "C": "Intermediate", "D": "Long"}, "r": "A", "e": {"correcta": "Regular insulin is short-acting, with onset around 30 minutes and peak effect at 2-4 hours, making it less ideal for controlling immediate postprandial spikes compared to rapid-acting analogs.", "incorrectas": {"B": "Rapid-acting describes analogs like lispro, aspart, and glulisine, which have a faster onset than regular insulin.", "C": "Intermediate-acting describes NPH insulin, which has a later onset and longer duration than regular insulin.", "D": "Long-acting describes glargine and detemir, which provide steady basal coverage rather than a defined short peak."}}}, {"id": "anking-endocrine-pharmacology-084", "fuente": "anking", "tema": 24, "anki": "1462849149554", "q": "IV regular insulin (given with glucose) is useful in the acute management of which electrolyte abnormality?", "o": {"A": "Hyperkalemia", "B": "Hypokalemia", "C": "Hypercalcemia", "D": "Hyponatremia"}, "r": "A", "e": {"correcta": "IV regular insulin drives potassium into cells via stimulation of Na+-K+-ATPase, making it a rapid treatment for hyperkalemia; glucose is co-administered to prevent hypoglycemia.", "incorrectas": {"B": "Insulin lowers serum potassium, so it would worsen, not treat, hypokalemia.", "C": "Insulin has no direct role in lowering serum calcium; hypercalcemia is treated with fluids, bisphosphonates, or calcitonin.", "D": "Insulin does not correct sodium imbalances; hyponatremia management depends on its underlying cause."}}}, {"id": "anking-endocrine-pharmacology-085", "fuente": "anking", "tema": 24, "anki": "1462849159965", "q": "Neutral Protamine Hagedorn (NPH) insulin is characterized by what type of action and duration?", "o": {"A": "Intermediate", "B": "Rapid", "C": "Short", "D": "Long"}, "r": "A", "e": {"correcta": "NPH is an intermediate-acting insulin with onset of action within about 2 hours, bridging the gap between rapid/short-acting insulins and long-acting basal insulins.", "incorrectas": {"B": "Rapid-acting describes lispro, aspart, and glulisine, which act much faster than NPH.", "C": "Short-acting describes regular insulin, which has an earlier onset than NPH.", "D": "Long-acting describes glargine and detemir, which have a longer duration of action than NPH."}}}, {"id": "anking-endocrine-pharmacology-086", "fuente": "anking", "tema": 24, "anki": "1462849196492", "q": "Insulin Detemir and Glargine are characterized by what type of action and duration?", "o": {"A": "Long", "B": "Rapid", "C": "Short", "D": "Intermediate"}, "r": "A", "e": {"correcta": "Detemir and glargine are long-acting basal insulin analogs that provide constant background insulin activity throughout the day, typically dosed once or twice daily.", "incorrectas": {"B": "Rapid-acting describes lispro, aspart, and glulisine, used for mealtime dosing rather than steady background coverage.", "C": "Short-acting describes regular insulin, which has a defined peak rather than a flat, prolonged profile.", "D": "Intermediate-acting describes NPH insulin, which has a more defined peak and shorter duration than glargine or detemir."}}}, {"id": "anking-endocrine-pharmacology-087", "fuente": "anking", "tema": 24, "anki": "1462849233061", "q": "Which type(s) of diabetes may be treated with insulin therapy, given that it is exogenous and does not require endogenous beta cell activity?", "o": {"A": "T1DM, T2DM, and gestational diabetes mellitus", "B": "T1DM only", "C": "T2DM only", "D": "Gestational diabetes mellitus only"}, "r": "A", "e": {"correcta": "Because insulin therapy is exogenous, it can be used to treat type 1 diabetes, type 2 diabetes, and gestational diabetes mellitus, regardless of the patient's own beta cell function.", "incorrectas": {"B": "Insulin is also effective and commonly used in T2DM and gestational diabetes, not just T1DM.", "C": "Insulin is essential (not just useful) in T1DM since these patients lack endogenous insulin production, so restricting to T2DM is incorrect.", "D": "Insulin is used in T1DM and T2DM as well, not exclusively in gestational diabetes."}}}, {"id": "anking-endocrine-pharmacology-088", "fuente": "anking", "tema": 24, "anki": "1462849297574", "q": "Which second-generation sulfonylurea has the shortest duration of action, and thus the least risk of hypoglycemia among agents in its class?", "o": {"A": "Glipizide", "B": "Glyburide", "C": "Glimepiride", "D": "Chlorpropamide"}, "r": "A", "e": {"correcta": "Glipizide has the shortest half-life and duration of action among second-generation sulfonylureas, which translates to the lowest risk of hypoglycemia in this class.", "incorrectas": {"B": "Glyburide has a longer duration of action and is associated with a higher risk of hypoglycemia than glipizide.", "C": "Glimepiride, while a second-generation sulfonylurea, has a longer duration of action compared to glipizide.", "D": "Chlorpropamide is a first-generation sulfonylurea with a very long duration of action and high hypoglycemia risk, not a short-acting second-generation agent."}}}, {"id": "anking-endocrine-pharmacology-089", "fuente": "anking", "tema": 24, "anki": "1462849313819", "q": "Which class of short-acting diabetic medications act similarly to sulfonylureas, sharing the same mechanism of action (closing ATP-dependent K+ channels) but binding a different site?", "o": {"A": "Meglitinides", "B": "Biguanides", "C": "Thiazolidinediones", "D": "GLP-1 agonists"}, "r": "A", "e": {"correcta": "Meglitinides (e.g., repaglinide, nateglinide) are short-acting insulin secretagogues that close ATP-dependent K+ channels on beta cells, similar to sulfonylureas, but bind a different receptor site.", "incorrectas": {"B": "Biguanides (e.g., metformin) work by decreasing hepatic gluconeogenesis and increasing insulin sensitivity, an entirely different mechanism.", "C": "Thiazolidinediones act on PPAR-gamma receptors to increase insulin sensitivity, unrelated to K+ channel closure.", "D": "GLP-1 agonists enhance glucose-dependent insulin secretion via incretin pathways, not by closing ATP-dependent K+ channels."}}}, {"id": "anking-endocrine-pharmacology-090", "fuente": "anking", "tema": 24, "anki": "1462849345929", "q": "Meglitinides are not which class of drugs, making them useful for treating T2DM patients who have an allergy to sulfonylureas?", "o": {"A": "Sulfa drugs", "B": "Biguanides", "C": "Thiazolidinediones", "D": "Alpha-glucosidase inhibitors"}, "r": "A", "e": {"correcta": "Meglitinides are not sulfa drugs, unlike sulfonylureas, so they can be safely used in type 2 diabetic patients who have a sulfa allergy while still working via a similar insulin secretagogue mechanism.", "incorrectas": {"B": "Biguanides are a distinct drug class (e.g., metformin) and are not relevant to the sulfa-allergy distinction being tested here.", "C": "Thiazolidinediones are also a separate class unrelated to the sulfa chemical structure issue.", "D": "Alpha-glucosidase inhibitors are unrelated to sulfa chemistry and are not the class being contrasted with meglitinides here."}}}, {"id": "anking-endocrine-anatomy-091", "fuente": "anking", "tema": 25, "anki": "1461867909640", "q": "The pituitary gland is also known by which other name?", "o": {"A": "Hypophysis", "B": "Adenohypophysis only", "C": "Diencephalon", "D": "Infundibulum"}, "r": "A", "e": {"correcta": "The pituitary gland is also called the hypophysis, consisting of anterior and posterior lobes.", "incorrectas": {"B": "Adenohypophysis refers only to the anterior lobe, not the entire gland.", "C": "The diencephalon is the brain region from which the posterior pituitary derives, not another name for the whole gland.", "D": "The infundibulum is the stalk connecting the hypothalamus to the pituitary, not the gland itself."}}}, {"id": "anking-endocrine-anatomy-092", "fuente": "anking", "tema": 25, "anki": "1461869987440", "q": "What is the name of the thin stalk connecting the hypothalamus to the pituitary gland?", "o": {"A": "Infundibulum", "B": "Rathke's pouch", "C": "Median eminence only", "D": "Pituitary fossa"}, "r": "A", "e": {"correcta": "The infundibulum is the thin stalk that structurally and functionally connects the hypothalamus to the pituitary gland.", "incorrectas": {"B": "Rathke's pouch is the embryologic origin of the anterior pituitary, not the connecting stalk.", "C": "The median eminence is part of the hypothalamus involved in portal blood release, not the stalk itself.", "D": "The pituitary fossa (sella turcica) is the bony structure housing the pituitary, not the connecting stalk."}}}, {"id": "anking-endocrine-anatomy-093", "fuente": "anking", "tema": 25, "anki": "1461869991748", "q": "The posterior lobe of the pituitary gland is derived from which type of tissue?", "o": {"A": "Neural tissue", "B": "Oral ectoderm", "C": "Mesoderm", "D": "Neural crest tissue"}, "r": "A", "e": {"correcta": "The posterior pituitary (neurohypophysis) is derived from neural tissue, specifically an outgrowth of the diencephalon.", "incorrectas": {"B": "Oral ectoderm (Rathke's pouch) gives rise to the anterior pituitary, not the posterior lobe.", "C": "Mesoderm is not the embryologic origin of either pituitary lobe.", "D": "Neural crest tissue gives rise to structures like the adrenal medulla, not the posterior pituitary."}}}, {"id": "anking-endocrine-anatomy-094", "fuente": "anking", "tema": 25, "anki": "1461870006406", "q": "The connections between the hypothalamus and which part of the pituitary are purely neural (not endocrine)?", "o": {"A": "Posterior pituitary", "B": "Anterior pituitary", "C": "Pars intermedia", "D": "Rathke's pouch"}, "r": "A", "e": {"correcta": "The hypothalamus connects to the posterior pituitary exclusively via neural axonal projections, without a vascular portal system.", "incorrectas": {"B": "The anterior pituitary connection is both neural and endocrine (via portal blood), not purely neural.", "C": "The pars intermedia is a vestigial region between lobes, not the site of the purely neural connection.", "D": "Rathke's pouch is an embryologic structure, not a site of hypothalamic connection."}}}, {"id": "anking-endocrine-anatomy-095", "fuente": "anking", "tema": 25, "anki": "1461870083093", "q": "The hypothalamus and anterior pituitary are linked directly by what system?", "o": {"A": "Hypothalamic-hypophysial portal system", "B": "Direct neural axonal connections", "C": "Systemic arterial circulation", "D": "Lymphatic drainage system"}, "r": "A", "e": {"correcta": "The hypothalamic-hypophysial portal system delivers hypothalamic-releasing hormones directly to the anterior pituitary via portal vessels.", "incorrectas": {"B": "Direct neural axonal connections link the hypothalamus to the posterior, not anterior, pituitary.", "C": "Systemic arterial circulation would dilute hormone concentrations rather than deliver them directly and concentrated.", "D": "There is no lymphatic system linking the hypothalamus and anterior pituitary."}}}, {"id": "anking-endocrine-anatomy-096", "fuente": "anking", "tema": 25, "anki": "1461870088700", "q": "Blood from the hypothalamus containing high concentrations of hypothalamic hormones is delivered directly to which structure?", "o": {"A": "Anterior pituitary", "B": "Posterior pituitary", "C": "Adrenal medulla", "D": "Thyroid gland"}, "r": "A", "e": {"correcta": "Via the hypophysial portal system, hypothalamic hormone-rich blood is delivered directly to the anterior pituitary, the only site in the body to receive such high concentrations.", "incorrectas": {"B": "The posterior pituitary receives neural input, not portal blood carrying hypothalamic hormones.", "C": "The adrenal medulla receives direct sympathetic innervation, unrelated to the hypophysial portal system.", "D": "The thyroid gland responds to TSH from the anterior pituitary but does not receive hypothalamic portal blood directly."}}}, {"id": "anking-endocrine-anatomy-097", "fuente": "anking", "tema": 25, "anki": "1461870100824", "q": "Hypothalamic hormones stimulate or inhibit the release of hormones from which gland?", "o": {"A": "Anterior pituitary", "B": "Posterior pituitary", "C": "Adrenal cortex", "D": "Thyroid gland"}, "r": "A", "e": {"correcta": "Hypothalamic releasing and inhibiting hormones act on the anterior pituitary to regulate secretion of its six major hormones.", "incorrectas": {"B": "The posterior pituitary simply releases hormones (ADH, oxytocin) made in the hypothalamus, rather than being regulated by separate releasing hormones.", "C": "The adrenal cortex is regulated by ACTH from the anterior pituitary, not directly by hypothalamic releasing hormones.", "D": "The thyroid gland is regulated by TSH from the anterior pituitary, not directly by hypothalamic hormones."}}}, {"id": "anking-endocrine-anatomy-098", "fuente": "anking", "tema": 25, "anki": "1461870110912", "q": "How does the blood supply of the anterior pituitary differ from that of most other organs?", "o": {"A": "Most of its blood supply is venous blood from the hypothalamus via portal vessels", "B": "It receives no blood supply and relies on diffusion", "C": "It is supplied only by direct arterial branches with no portal system", "D": "It receives blood exclusively from the posterior pituitary"}, "r": "A", "e": {"correcta": "Unlike most organs supplied primarily by arterial blood, the anterior pituitary receives most of its blood supply as venous blood from the hypothalamus via the long and short hypophysial portal vessels.", "incorrectas": {"B": "The anterior pituitary is highly vascularized and does not rely on diffusion alone.", "C": "The defining feature is precisely the presence of a unique portal venous system, not pure arterial supply.", "D": "The anterior and posterior pituitary lobes have separate, distinct blood supplies."}}}, {"id": "anking-endocrine-anatomy-099", "fuente": "anking", "tema": 25, "anki": "1461870128102", "q": "The connections between the hypothalamus and which part of the pituitary are both neural and endocrine?", "o": {"A": "Anterior pituitary", "B": "Posterior pituitary", "C": "Adrenal medulla", "D": "Pars intermedia"}, "r": "A", "e": {"correcta": "The anterior pituitary connection to the hypothalamus is both endocrine, via the portal system, and neurally regulated at the level of the hypothalamus, making it distinct from the purely neural posterior connection.", "incorrectas": {"B": "The posterior pituitary connection to the hypothalamus is purely neural, not endocrine.", "C": "The adrenal medulla is regulated by direct sympathetic innervation, not by hypothalamic portal or neural pituitary connections.", "D": "The pars intermedia is a vestigial region, not the site referenced for combined neural/endocrine connection."}}}, {"id": "anking-endocrine-anatomy-100", "fuente": "anking", "tema": 25, "anki": "1461870794373", "q": "Which set of hormones represents the six major hormones secreted by the anterior lobe of the pituitary?", "o": {"A": "FSH, LH, ACTH, TSH, Prolactin, Growth hormone", "B": "ADH, Oxytocin, FSH, LH, TSH, ACTH", "C": "Cortisol, Aldosterone, Epinephrine, TSH, FSH, LH", "D": "Insulin, Glucagon, GH, TSH, ACTH, Prolactin"}, "r": "A", "e": {"correcta": "The anterior pituitary secretes FSH, LH, ACTH, TSH, Prolactin, and Growth hormone, mnemonically remembered as 'FLAT PG'.", "incorrectas": {"B": "ADH and oxytocin are posterior, not anterior, pituitary hormones.", "C": "Cortisol, aldosterone, and epinephrine are adrenal hormones, not pituitary hormones.", "D": "Insulin and glucagon are pancreatic hormones, not anterior pituitary hormones."}}}, {"id": "anking-endocrine-anatomy-101", "fuente": "anking", "tema": 25, "anki": "1461871639955", "q": "Which subunit of the anterior pituitary hormones TSH, FSH, hCG, and LH is identical across all of them?", "o": {"A": "Alpha (α) subunit", "B": "Beta (β) subunit", "C": "Gamma subunit", "D": "Delta subunit"}, "r": "A", "e": {"correcta": "The alpha subunit is structurally identical among TSH, FSH, hCG, and LH, while the beta subunit confers hormone specificity.", "incorrectas": {"B": "The beta subunit is different among these hormones and determines their unique biologic activity.", "C": "There is no gamma subunit in these glycoprotein hormones.", "D": "There is no delta subunit in these glycoprotein hormones."}}}, {"id": "anking-endocrine-anatomy-102", "fuente": "anking", "tema": 25, "anki": "1461871660443", "q": "Which subunit of TSH, FSH, and LH differs between the hormones and is responsible for their unique biologic activity?", "o": {"A": "Beta (β) subunit", "B": "Alpha (α) subunit", "C": "Gamma subunit", "D": "Signal peptide"}, "r": "A", "e": {"correcta": "The beta subunit is unique to each hormone (TSH, FSH, LH) and confers receptor specificity and distinct biologic activity.", "incorrectas": {"B": "The alpha subunit is identical across these hormones and does not confer specificity.", "C": "There is no gamma subunit in these glycoprotein hormones.", "D": "The signal peptide is cleaved during hormone processing and does not determine biologic specificity."}}}, {"id": "anking-endocrine-anatomy-103", "fuente": "anking", "tema": 25, "anki": "1461878628938", "q": "What is the embryonic origin of the anterior pituitary?", "o": {"A": "Oral ectoderm, specifically Rathke's pouch", "B": "Neural ectoderm from the diencephalon", "C": "Neural crest cells", "D": "Mesodermal somites"}, "r": "A", "e": {"correcta": "The anterior pituitary arises from oral ectoderm, specifically an upward invagination called Rathke's pouch.", "incorrectas": {"B": "Neural ectoderm from the diencephalon gives rise to the posterior pituitary, not the anterior lobe.", "C": "Neural crest cells give rise to structures such as the adrenal medulla, not the anterior pituitary.", "D": "Mesodermal somites are not involved in pituitary gland development."}}}, {"id": "anking-endocrine-anatomy-104", "fuente": "anking", "tema": 25, "anki": "1461878671855", "q": "What is the source of prolactin and growth hormone secretion?", "o": {"A": "Anterior pituitary", "B": "Posterior pituitary", "C": "Hypothalamus", "D": "Adrenal cortex"}, "r": "A", "e": {"correcta": "Prolactin and growth hormone are two of the six major hormones secreted by the anterior pituitary.", "incorrectas": {"B": "The posterior pituitary secretes ADH and oxytocin, not prolactin or growth hormone.", "C": "The hypothalamus regulates anterior pituitary secretion via releasing hormones but is not the direct source of prolactin or GH.", "D": "The adrenal cortex secretes steroid hormones like cortisol and aldosterone, not prolactin or GH."}}}, {"id": "anking-endocrine-anatomy-105", "fuente": "anking", "tema": 25, "anki": "1461883823047", "q": "What two hormones are secreted by the posterior lobe of the pituitary gland?", "o": {"A": "ADH and oxytocin", "B": "FSH and LH", "C": "TSH and ACTH", "D": "Prolactin and growth hormone"}, "r": "A", "e": {"correcta": "The posterior pituitary secretes ADH and oxytocin, which are neuropeptides released from nerve terminals originating in hypothalamic neurons.", "incorrectas": {"B": "FSH and LH are gonadotropins secreted by the anterior, not posterior, pituitary.", "C": "TSH and ACTH are anterior pituitary hormones, not posterior pituitary hormones.", "D": "Prolactin and growth hormone are secreted by the anterior pituitary, not the posterior lobe."}}}, {"id": "anking-endocrine-anatomy-106", "fuente": "anking", "tema": 25, "anki": "1461884702127", "q": "ADH and oxytocin are neuropeptides synthesized in hypothalamic neurons and secreted from nerve terminals in which structure?", "o": {"A": "Posterior pituitary", "B": "Anterior pituitary", "C": "Adrenal medulla", "D": "Median eminence only, with no pituitary release"}, "r": "A", "e": {"correcta": "ADH and oxytocin are synthesized in hypothalamic neurons and transported down axons to be released from nerve terminals in the posterior pituitary.", "incorrectas": {"B": "The anterior pituitary secretes hormones synthesized locally by its own cells, not neuropeptides transported from the hypothalamus.", "C": "The adrenal medulla secretes catecholamines, unrelated to ADH and oxytocin release.", "D": "ADH and oxytocin are released into systemic circulation specifically from the posterior pituitary, not only the median eminence."}}}, {"id": "anking-endocrine-anatomy-107", "fuente": "anking", "tema": 25, "anki": "1462039139240", "q": "The adrenal medulla is located in which zone of the adrenal gland, comprising approximately 20% of glandular tissue?", "o": {"A": "Inner (central) zone", "B": "Outer cortical zone", "C": "Zona glomerulosa", "D": "Zona fasciculata"}, "r": "A", "e": {"correcta": "The adrenal medulla occupies the inner zone of the adrenal gland, sharply demarcated from the surrounding cortex, and makes up about 20% of the gland's tissue.", "incorrectas": {"B": "The outer cortical zone refers to the adrenal cortex, which surrounds the medulla rather than being the medulla itself.", "C": "The zona glomerulosa is the outermost cortical layer producing aldosterone, not the medulla.", "D": "The zona fasciculata is a middle cortical layer producing cortisol, not the medulla."}}}, {"id": "anking-endocrine-anatomy-108", "fuente": "anking", "tema": 25, "anki": "1462043406009", "q": "The adrenal medulla is of what embryologic origin?", "o": {"A": "Neural crest", "B": "Mesoderm", "C": "Oral ectoderm", "D": "Neural tube (diencephalon)"}, "r": "A", "e": {"correcta": "The adrenal medulla derives from neural crest cells, consistent with its composition of chromaffin cells that function like sympathetic postganglionic neurons.", "incorrectas": {"B": "Mesoderm gives rise to the adrenal cortex, not the medulla.", "C": "Oral ectoderm gives rise to the anterior pituitary, not the adrenal medulla.", "D": "The neural tube/diencephalon gives rise to the posterior pituitary, not the adrenal medulla."}}}, {"id": "anking-hematology-oncology-pharmacology-109", "fuente": "anking", "tema": 26, "anki": "1488763721560", "q": "Which vitamin acts as a cofactor for the enzymatic activation (γ-carboxylation) of clotting factors II, VII, IX, and X?", "o": {"A": "Vitamin K", "B": "Vitamin C", "C": "Vitamin B12", "D": "Vitamin D"}, "r": "A", "e": {"correcta": "Vitamin K is required as a cofactor for the hepatic γ-carboxylation of glutamate residues on factors II, VII, IX, X, and proteins C/S, which is necessary for their calcium-dependent activity.", "incorrectas": {"B": "Vitamin C is a cofactor for collagen synthesis (prolyl/lysyl hydroxylase), not clotting factor activation.", "C": "Vitamin B12 is required for DNA synthesis and myelin maintenance, not clotting factor carboxylation.", "D": "Vitamin D regulates calcium and bone metabolism, not clotting factor activation."}}}, {"id": "anking-hematology-oncology-pharmacology-110", "fuente": "anking", "tema": 26, "anki": "1488765214688", "q": "What chemical modification does vitamin K promote on clotting factors II, VII, IX, X and proteins C/S?", "o": {"A": "γ-carboxylation", "B": "Phosphorylation", "C": "Glycosylation", "D": "Hydroxylation"}, "r": "A", "e": {"correcta": "Vitamin K is a cofactor for the γ-carboxylation of glutamic acid residues on factors II, VII, IX, X and proteins C/S, allowing them to bind calcium and participate in coagulation.", "incorrectas": {"B": "Phosphorylation is not the modification vitamin K mediates on clotting factors.", "C": "Glycosylation is unrelated to vitamin K's role in coagulation factor activation.", "D": "Hydroxylation (e.g., of proline/lysine) is characteristic of collagen synthesis, not clotting factor activation."}}}, {"id": "anking-hematology-oncology-pharmacology-111", "fuente": "anking", "tema": 26, "anki": "1488765219096", "q": "Vitamin K–dependent γ-carboxylation acts on which amino acid residues of clotting factors?", "o": {"A": "Glutamic acid residues", "B": "Aspartic acid residues", "C": "Lysine residues", "D": "Proline residues"}, "r": "A", "e": {"correcta": "Vitamin K promotes γ-carboxylation specifically at glutamic acid residues, converting them to γ-carboxyglutamate (Gla), which enables calcium binding.", "incorrectas": {"B": "Aspartic acid residues are not the target of vitamin K–dependent carboxylation.", "C": "Lysine residues undergo hydroxylation in collagen, not vitamin K–dependent carboxylation.", "D": "Proline residues undergo hydroxylation in collagen synthesis (vitamin C–dependent), not γ-carboxylation."}}}, {"id": "anking-hematology-oncology-pharmacology-112", "fuente": "anking", "tema": 26, "anki": "1488765222541", "q": "Which enzyme is responsible for activating (regenerating the reduced form of) vitamin K?", "o": {"A": "Epoxide reductase", "B": "Cytochrome P450 oxidase", "C": "Glutathione reductase", "D": "Dihydrofolate reductase"}, "r": "A", "e": {"correcta": "Vitamin K epoxide reductase (VKORC1) converts vitamin K epoxide back to its active reduced form, which is required for γ-carboxylation of clotting factors.", "incorrectas": {"B": "Cytochrome P450 oxidase metabolizes drugs like warfarin but does not activate vitamin K itself.", "C": "Glutathione reductase regenerates reduced glutathione, unrelated to vitamin K cycling.", "D": "Dihydrofolate reductase regenerates tetrahydrofolate for nucleotide synthesis, unrelated to vitamin K."}}}, {"id": "anking-hematology-oncology-pharmacology-113", "fuente": "anking", "tema": 26, "anki": "1488765226036", "q": "What is the mechanism of action of warfarin?", "o": {"A": "Vitamin K epoxide reductase inhibitor", "B": "Direct thrombin inhibitor", "C": "Antithrombin III activator", "D": "Factor Xa inhibitor"}, "r": "A", "e": {"correcta": "Warfarin inhibits vitamin K epoxide reductase, preventing regeneration of active vitamin K and thereby blocking γ-carboxylation of factors II, VII, IX, X and proteins C/S.", "incorrectas": {"B": "Direct thrombin inhibition describes drugs like dabigatran, not warfarin.", "C": "Activating antithrombin III describes heparin's mechanism, not warfarin's.", "D": "Direct factor Xa inhibition describes drugs like rivaroxaban/apixaban, not warfarin."}}}, {"id": "anking-hematology-oncology-pharmacology-114", "fuente": "anking", "tema": 26, "anki": "1488765233649", "q": "Which clotting factor is the first to decrease after starting warfarin therapy?", "o": {"A": "Factor VII", "B": "Factor II (prothrombin)", "C": "Factor IX", "D": "Factor X"}, "r": "A", "e": {"correcta": "Factor VII has the shortest half-life (~6 hours) among the vitamin K–dependent factors, so its levels fall first after starting warfarin.", "incorrectas": {"B": "Factor II (prothrombin) has a much longer half-life and declines later.", "C": "Factor IX has an intermediate half-life and does not decline first.", "D": "Factor X also has a longer half-life than factor VII and does not decline first."}}}, {"id": "anking-hematology-oncology-pharmacology-115", "fuente": "anking", "tema": 26, "anki": "1488765239779", "q": "What is the approximate onset of action of warfarin?", "o": {"A": "8-12 hours", "B": "5-10 minutes", "C": "1-2 hours", "D": "24-48 hours only after loading dose"}, "r": "A", "e": {"correcta": "Warfarin has a slow onset of action, typically taking about 8-12 hours before initial effects begin, reflecting the time needed to deplete existing clotting factors.", "incorrectas": {"B": "5-10 minutes is far too rapid and describes something like IV heparin's onset, not warfarin.", "C": "1-2 hours is too fast for warfarin's mechanism, which requires depletion of existing factors.", "D": "While full anticoagulant effect takes days, the initial onset window is 8-12 hours, not simply described as 24-48 hours."}}}, {"id": "anking-hematology-oncology-pharmacology-116", "fuente": "anking", "tema": 26, "anki": "1488765243586", "q": "What is the standard route of administration for warfarin?", "o": {"A": "Oral", "B": "Intravenous", "C": "Subcutaneous", "D": "Intramuscular"}, "r": "A", "e": {"correcta": "Warfarin is administered orally, which is one of its key advantages for long-term outpatient anticoagulation.", "incorrectas": {"B": "Intravenous administration is used for heparin, not warfarin.", "C": "Subcutaneous administration is used for low molecular weight heparins like enoxaparin, not warfarin.", "D": "Intramuscular administration is avoided in anticoagulated patients and is not how warfarin is given."}}}, {"id": "anking-hematology-oncology-pharmacology-117", "fuente": "anking", "tema": 26, "anki": "1488765248074", "q": "Warfarin is characterized by having what type of half-life?", "o": {"A": "Long half-life", "B": "Very short half-life", "C": "Half-life of only a few minutes", "D": "No measurable half-life (irreversible binding)"}, "r": "A", "e": {"correcta": "Warfarin has a long half-life (approximately 20-60 hours), contributing to its slow onset and offset of action.", "incorrectas": {"B": "A very short half-life would not explain warfarin's slow onset and prolonged duration of action.", "C": "A half-life of minutes is inconsistent with warfarin's pharmacokinetics and clinical dosing.", "D": "Warfarin is reversibly metabolized by the liver, not irreversibly bound with no half-life."}}}, {"id": "anking-hematology-oncology-pharmacology-118", "fuente": "anking", "tema": 26, "anki": "1488765251203", "q": "Which laboratory test is used to monitor the therapeutic effect of warfarin?", "o": {"A": "PT/INR", "B": "aPTT", "C": "Bleeding time", "D": "Platelet count"}, "r": "A", "e": {"correcta": "PT/INR measures the extrinsic pathway (factor VII-dependent) and is used to monitor and titrate warfarin therapy.", "incorrectas": {"B": "aPTT measures the intrinsic pathway and is used to monitor heparin, not warfarin.", "C": "Bleeding time assesses platelet function, not the vitamin K–dependent coagulation factors affected by warfarin.", "D": "Platelet count assesses thrombocytopenia risk but does not reflect warfarin's anticoagulant effect."}}}, {"id": "anking-hematology-oncology-pharmacology-119", "fuente": "anking", "tema": 26, "anki": "1488765255379", "q": "What is the typical target INR range for standard warfarin anticoagulation therapy?", "o": {"A": "2-3", "B": "0.5-1", "C": "4-5", "D": "1-1.5"}, "r": "A", "e": {"correcta": "The target INR for most indications (e.g., atrial fibrillation, VTE prophylaxis) on warfarin therapy is 2-3, balancing efficacy and bleeding risk.", "incorrectas": {"B": "An INR of 0.5-1 is subtherapeutic and would not represent adequate anticoagulation.", "C": "An INR of 4-5 is supratherapeutic and associated with excessive bleeding risk.", "D": "An INR of 1-1.5 is essentially within the normal (non-anticoagulated) range and is subtherapeutic."}}}, {"id": "anking-hematology-oncology-pharmacology-120", "fuente": "anking", "tema": 26, "anki": "1488765259902", "q": "Which anticoagulant is preferred for chronic, long-term anticoagulation (e.g., VTE prophylaxis, atrial fibrillation stroke prevention)?", "o": {"A": "Warfarin", "B": "Unfractionated heparin", "C": "Argatroban", "D": "Bivalirudin"}, "r": "A", "e": {"correcta": "Warfarin, taken orally, is used for chronic anticoagulation such as long-term VTE prophylaxis and stroke prevention in atrial fibrillation.", "incorrectas": {"B": "Unfractionated heparin is given parenterally and used for acute/short-term anticoagulation, not chronic outpatient therapy.", "C": "Argatroban is a parenteral direct thrombin inhibitor used acutely, particularly in heparin-induced thrombocytopenia.", "D": "Bivalirudin is a parenteral direct thrombin inhibitor used during procedures like PCI, not for chronic therapy."}}}, {"id": "anking-hematology-oncology-pharmacology-121", "fuente": "anking", "tema": 26, "anki": "1488765273230", "q": "Does warfarin cross the placenta, and why?", "o": {"A": "Yes, because it is lipid soluble", "B": "No, because it is a large protein-bound molecule", "C": "No, because it is highly water soluble", "D": "Yes, but only in the third trimester due to placental thinning"}, "r": "A", "e": {"correcta": "Warfarin is lipid soluble and readily crosses the placenta, causing fetal warfarin syndrome, so it is contraindicated in pregnancy.", "incorrectas": {"B": "Warfarin does cross the placenta; being protein-bound in plasma does not prevent placental transfer of this lipid-soluble drug.", "C": "Warfarin is lipid soluble, not water soluble, and this property is exactly why it crosses the placenta.", "D": "Warfarin crosses the placenta throughout pregnancy, not only in the third trimester."}}}, {"id": "anking-hematology-oncology-pharmacology-122", "fuente": "anking", "tema": 26, "anki": "1488765277192", "q": "In utero exposure to warfarin can cause hemorrhage and abnormal formation of which tissue?", "o": {"A": "Bone", "B": "Cardiac septum", "C": "Neural tube", "D": "Renal parenchyma"}, "r": "A", "e": {"correcta": "Fetal warfarin syndrome includes abnormal bone formation (e.g., stippled epiphyses, hypoplastic nasal bone) along with hemorrhage, due to warfarin's teratogenic effects.", "incorrectas": {"B": "Cardiac septal defects are not the classic warfarin embryopathy finding; skeletal abnormalities are characteristic.", "C": "Neural tube defects are classically associated with folate antagonists (e.g., valproate, methotrexate), not warfarin.", "D": "Renal abnormalities are not the hallmark finding of fetal warfarin syndrome; skeletal defects are."}}}, {"id": "anking-hematology-oncology-pharmacology-123", "fuente": "anking", "tema": 26, "anki": "1488765290929", "q": "What medication is co-administered when starting warfarin therapy to prevent the transient hypercoagulable state?", "o": {"A": "Heparin", "B": "Aspirin", "C": "Vitamin K", "D": "Clopidogrel"}, "r": "A", "e": {"correcta": "Heparin is bridged with warfarin at initiation because heparin activates antithrombin to provide immediate anticoagulation while warfarin depletes protein C/S, which initially causes a transient hypercoagulable state.", "incorrectas": {"B": "Aspirin is an antiplatelet agent and does not address the transient hypercoagulability from protein C/S depletion.", "C": "Vitamin K would reverse/antagonize warfarin's effect, not help bridge therapy during initiation.", "D": "Clopidogrel is an antiplatelet agent, not used for anticoagulant bridging during warfarin initiation."}}}, {"id": "anking-hematology-oncology-pharmacology-124", "fuente": "anking", "tema": 26, "anki": "1488765303577", "q": "Warfarin undergoes what process via cytochrome P450, explaining its many drug interactions?", "o": {"A": "Metabolism", "B": "Renal excretion", "C": "Biliary conjugation without metabolism", "D": "Protein synthesis inhibition"}, "r": "A", "e": {"correcta": "Warfarin is metabolized by cytochrome P450 enzymes (notably CYP2C9), making it susceptible to numerous drug interactions that induce or inhibit these enzymes.", "incorrectas": {"B": "Renal excretion is not warfarin's primary elimination pathway; hepatic metabolism is.", "C": "Warfarin is actively metabolized (oxidized) by CYP450, not simply conjugated without metabolism.", "D": "Warfarin does not inhibit protein synthesis; it inhibits vitamin K epoxide reductase."}}}, {"id": "anking-hematology-oncology-pharmacology-125", "fuente": "anking", "tema": 26, "anki": "1488765310513", "q": "Which anticoagulant has a slow onset of action, taking days to reach full therapeutic effect?", "o": {"A": "Warfarin", "B": "Unfractionated heparin", "C": "Enoxaparin (LMWH)", "D": "Fondaparinux"}, "r": "A", "e": {"correcta": "Warfarin has a slow onset of action (days) because it works by preventing synthesis of new clotting factors rather than inhibiting existing ones.", "incorrectas": {"B": "Unfractionated heparin has a rapid onset of action (minutes) since it directly potentiates antithrombin.", "C": "Enoxaparin (LMWH) also has a rapid onset of action compared to warfarin.", "D": "Fondaparinux has a rapid onset of action, acting directly on factor Xa via antithrombin."}}}, {"id": "anking-hematology-oncology-pharmacology-126", "fuente": "anking", "tema": 26, "anki": "1488765314397", "q": "What is the primary site of action (metabolism/effect) of warfarin in the body?", "o": {"A": "Liver", "B": "Kidney", "C": "Bone marrow", "D": "Spleen"}, "r": "A", "e": {"correcta": "Warfarin acts in the liver, where it inhibits vitamin K epoxide reductase and blocks hepatic synthesis of active vitamin K–dependent clotting factors.", "incorrectas": {"B": "The kidney is not warfarin's site of action; it is primarily involved in eliminating many other drugs.", "C": "Bone marrow is the site of blood cell production, not where warfarin exerts its anticoagulant mechanism.", "D": "The spleen is involved in blood filtration and immune function, not warfarin's mechanism of action."}}}, {"id": "anking-hematology-oncology-anatomy-127", "fuente": "anking", "tema": 27, "anki": "1473289622374", "q": "Which phagocytic cells reside within the alveoli and clear debris as part of the innate immune response in the lung?", "o": {"A": "Alveolar macrophages (dust cells)", "B": "Kupffer cells", "C": "Langerhans cells", "D": "Microglia"}, "r": "A", "e": {"correcta": "Alveolar macrophages (dust cells) live within the alveolar spaces, phagocytosing inhaled particles and debris; when filled with debris they migrate up the mucociliary escalator to be cleared.", "incorrectas": {"B": "Kupffer cells are the resident macrophages of the liver sinusoids, not the lung alveoli.", "C": "Langerhans cells are dendritic antigen-presenting cells found in the skin epidermis, not the alveoli.", "D": "Microglia are the resident macrophage-like cells of the central nervous system, not the lung."}}}, {"id": "anking-hematology-oncology-anatomy-128", "fuente": "anking", "tema": 27, "anki": "1474056842486", "q": "Along with fibrinogen, which large adhesive glycoprotein is stored in the alpha granules of platelets?", "o": {"A": "von Willebrand factor (vWF)", "B": "Tissue factor", "C": "Protein C", "D": "Antithrombin"}, "r": "A", "e": {"correcta": "Alpha granules store large proteins including von Willebrand factor, fibrinogen, factor V, fibronectin, PF4, and PDGF, which support platelet adhesion and aggregation.", "incorrectas": {"B": "Tissue factor is expressed on subendothelial cells and initiates the extrinsic coagulation pathway; it is not a major alpha granule constituent.", "C": "Protein C is a plasma anticoagulant synthesized by the liver, not stored in platelet alpha granules.", "D": "Antithrombin is a plasma protease inhibitor produced by the liver, not a platelet granule content."}}}, {"id": "anking-hematology-oncology-anatomy-129", "fuente": "anking", "tema": 27, "anki": "1476661124964", "q": "After approximately 120 days, senescent red blood cells are removed by macrophages of which system?", "o": {"A": "Reticuloendothelial system", "B": "Renin-angiotensin system", "C": "Complement system", "D": "Lymphatic system"}, "r": "A", "e": {"correcta": "The reticuloendothelial (mononuclear phagocyte) system, mainly in the spleen and liver, removes aged and damaged erythrocytes after their roughly 120-day lifespan.", "incorrectas": {"B": "The renin-angiotensin system regulates blood pressure and fluid balance, not RBC clearance.", "C": "The complement system is a humoral defense cascade, not a macrophage system responsible for RBC removal.", "D": "The lymphatic system drains interstitial fluid and transports immune cells but does not itself remove senescent RBCs."}}}, {"id": "anking-hematology-oncology-anatomy-130", "fuente": "anking", "tema": 27, "anki": "1479267245077", "q": "Do erythrocytes (RBCs) contain a nucleus?", "o": {"A": "No, they are anucleate", "B": "Yes, they retain a single nucleus", "C": "Yes, but only during the reticulocyte stage in circulation", "D": "Yes, they are multinucleated"}, "r": "A", "e": {"correcta": "Mature erythrocytes extrude their nucleus during maturation and circulate as anucleate cells, maximizing space for hemoglobin and gas exchange.", "incorrectas": {"B": "Mature circulating RBCs have lost their nucleus; only earlier erythroid precursors retain one.", "C": "Reticulocytes have already extruded their nucleus by the time they enter circulation; they retain only residual ribosomal RNA.", "D": "RBCs are never multinucleated; that describes megakaryocytes, not erythrocytes."}}}, {"id": "anking-hematology-oncology-anatomy-131", "fuente": "anking", "tema": 27, "anki": "1479267249308", "q": "Do mature erythrocytes (RBCs) contain organelles such as mitochondria?", "o": {"A": "No, they lack organelles", "B": "Yes, they contain abundant mitochondria", "C": "Yes, they contain a prominent Golgi apparatus", "D": "Yes, they retain rough endoplasmic reticulum"}, "r": "A", "e": {"correcta": "Mature RBCs extrude their organelles along with the nucleus during maturation, relying on glycolysis rather than oxidative phosphorylation for energy.", "incorrectas": {"B": "RBCs lack mitochondria, which is why they generate ATP exclusively via anaerobic glycolysis.", "C": "A Golgi apparatus is absent in mature RBCs since they no longer synthesize or process proteins for secretion.", "D": "Rough ER is lost during erythropoiesis; mature RBCs do not synthesize new proteins."}}}, {"id": "anking-hematology-oncology-anatomy-132", "fuente": "anking", "tema": 27, "anki": "1479267251984", "q": "What shape do erythrocytes have that maximizes their surface area-to-volume ratio for rapid gas exchange?", "o": {"A": "Biconcave disc", "B": "Spherical", "C": "Crescent (sickle)", "D": "Biconvex disc"}, "r": "A", "e": {"correcta": "Erythrocytes are biconcave discs, a shape that increases surface area relative to volume and allows flexibility for passing through capillaries while optimizing gas diffusion.", "incorrectas": {"B": "A spherical shape (as in hereditary spherocytosis) reduces surface area-to-volume ratio and is pathologic, not normal.", "C": "A crescent (sickle) shape is pathologic, seen in sickle cell disease, not the normal RBC morphology.", "D": "A biconvex shape is not the normal RBC morphology; RBCs are biconcave, not biconvex."}}}, {"id": "anking-hematology-oncology-anatomy-133", "fuente": "anking", "tema": 27, "anki": "1479267257908", "q": "What is the average lifespan of a circulating erythrocyte?", "o": {"A": "Approximately 120 days", "B": "Approximately 10 days", "C": "Approximately 7 days", "D": "Approximately 365 days"}, "r": "A", "e": {"correcta": "Erythrocytes circulate for approximately 120 days before being removed by macrophages of the reticuloendothelial system.", "incorrectas": {"B": "10 days is far shorter than the true RBC lifespan and is closer to the platelet lifespan (8-10 days).", "C": "7 days is far too short; this is closer to the lifespan of circulating neutrophils.", "D": "365 days overestimates RBC survival; RBCs are cleared well before a full year."}}}, {"id": "anking-hematology-oncology-anatomy-134", "fuente": "anking", "tema": 27, "anki": "1479267261208", "q": "What is the primary source of energy for mature erythrocytes?", "o": {"A": "Glucose", "B": "Fatty acids", "C": "Ketone bodies", "D": "Amino acids"}, "r": "A", "e": {"correcta": "Since mature RBCs lack mitochondria, they rely entirely on glucose metabolized via glycolysis (and the HMP shunt) for ATP and NADPH production.", "incorrectas": {"B": "Fatty acid oxidation requires mitochondria, which mature RBCs lack.", "C": "Ketone body utilization also requires mitochondrial enzymes that RBCs do not possess.", "D": "Amino acids are not a significant energy source for erythrocytes, which depend on glucose."}}}, {"id": "anking-hematology-oncology-anatomy-135", "fuente": "anking", "tema": 27, "anki": "1479267263688", "q": "In erythrocytes, approximately 90% of glucose metabolism is directed toward which pathway?", "o": {"A": "Glycolysis", "B": "HMP (pentose phosphate) shunt", "C": "Gluconeogenesis", "D": "Glycogenolysis"}, "r": "A", "e": {"correcta": "About 90% of glucose in RBCs is used for glycolysis to generate ATP and 2,3-BPG, while the remaining 10% enters the HMP shunt to generate NADPH.", "incorrectas": {"B": "The HMP shunt accounts for only about 10% of glucose use in RBCs, not the majority.", "C": "RBCs do not perform gluconeogenesis; they lack the necessary enzymatic machinery and mitochondria.", "D": "RBCs do not store significant glycogen, so glycogenolysis is not a relevant glucose-handling pathway here."}}}, {"id": "anking-hematology-oncology-anatomy-136", "fuente": "anking", "tema": 27, "anki": "1479267268809", "q": "In erythrocytes, approximately 10% of glucose metabolism is directed toward which pathway, generating NADPH?", "o": {"A": "HMP (pentose phosphate) shunt", "B": "Glycolysis", "C": "Beta-oxidation", "D": "Citric acid cycle"}, "r": "A", "e": {"correcta": "About 10% of glucose in RBCs enters the HMP shunt, producing NADPH that maintains glutathione in its reduced form to protect against oxidative stress.", "incorrectas": {"B": "Glycolysis accounts for the majority (about 90%) of glucose use in RBCs, not the minor 10% pathway.", "C": "Beta-oxidation requires mitochondria, which mature RBCs lack, so it does not occur in these cells.", "D": "The citric acid cycle occurs in mitochondria, which are absent in mature erythrocytes."}}}, {"id": "anking-hematology-oncology-anatomy-137", "fuente": "anking", "tema": 27, "anki": "1479267275681", "q": "Which antiporter present in the erythrocyte membrane allows export of bicarbonate and facilitates CO2 transport from peripheral tissues to the lungs?", "o": {"A": "Cl-/HCO3- antiporter", "B": "Na+/K+-ATPase", "C": "Na+/H+ exchanger", "D": "Ca2+/Na+ exchanger"}, "r": "A", "e": {"correcta": "The Cl-/HCO3- antiporter (band 3 protein) in the RBC membrane exchanges chloride for bicarbonate, enabling the 'chloride shift' that allows CO2 transport as bicarbonate to the lungs for elimination.", "incorrectas": {"B": "The Na+/K+-ATPase maintains the RBC's ionic gradient and membrane potential but is not involved in the chloride shift for CO2 transport.", "C": "The Na+/H+ exchanger regulates intracellular pH in many cell types but is not the transporter responsible for the RBC chloride shift.", "D": "The Ca2+/Na+ exchanger regulates intracellular calcium and is not involved in bicarbonate/CO2 handling in RBCs."}}}, {"id": "anking-hematology-oncology-anatomy-138", "fuente": "anking", "tema": 27, "anki": "1479267324516", "q": "Platelets (thrombocytes) are small cytoplasmic fragments derived from which cell type?", "o": {"A": "Megakaryocytes", "B": "Erythroblasts", "C": "Myeloblasts", "D": "Lymphoblasts"}, "r": "A", "e": {"correcta": "Platelets bud off from megakaryocytes in the bone marrow, with final fragmentation occurring largely within the pulmonary circulation.", "incorrectas": {"B": "Erythroblasts are precursors to erythrocytes (red blood cells), not platelets.", "C": "Myeloblasts are precursors to granulocytes (neutrophils, eosinophils, basophils), not platelets.", "D": "Lymphoblasts are precursors to lymphocytes, not platelets."}}}, {"id": "anking-hematology-oncology-anatomy-139", "fuente": "anking", "tema": 27, "anki": "1479267329028", "q": "What is the approximate lifespan range of platelets (thrombocytes) in circulation?", "o": {"A": "8 to 10 days", "B": "120 to 130 days", "C": "1 to 2 days", "D": "30 to 40 days"}, "r": "A", "e": {"correcta": "Platelets survive in circulation for approximately 8 to 10 days before being removed, primarily by the spleen.", "incorrectas": {"B": "120 to 130 days is the approximate lifespan of erythrocytes, not platelets.", "C": "1 to 2 days is far shorter than the actual platelet lifespan of 8-10 days.", "D": "30 to 40 days overestimates the platelet lifespan, which is closer to a week and a half."}}}, {"id": "anking-hematology-oncology-anatomy-140", "fuente": "anking", "tema": 27, "anki": "1479267335124", "q": "Which skin finding is classically associated with thrombocytopenia and/or decreased platelet function?", "o": {"A": "Petechiae", "B": "Malar rash", "C": "Erythema nodosum", "D": "Target lesions"}, "r": "A", "e": {"correcta": "Petechiae, small non-blanching pinpoint hemorrhages, result from impaired primary hemostasis due to low platelet count or dysfunctional platelets.", "incorrectas": {"B": "Malar rash is characteristic of systemic lupus erythematosus, not primarily a platelet disorder.", "C": "Erythema nodosum is a panniculitis associated with infections, sarcoidosis, and other systemic conditions, not thrombocytopenia.", "D": "Target lesions are typical of erythema multiforme, not platelet abnormalities."}}}, {"id": "anking-hematology-oncology-anatomy-141", "fuente": "anking", "tema": 27, "anki": "1479267337680", "q": "Which type of platelet granule contains ADP and Ca2+?", "o": {"A": "Dense granules", "B": "Alpha granules", "C": "Azurophilic granules", "D": "Specific (secondary) granules"}, "r": "A", "e": {"correcta": "Dense granules (delta granules) store small molecules including ADP, ATP, serotonin, and calcium, which are released to promote platelet aggregation.", "incorrectas": {"B": "Alpha granules contain larger proteins such as vWF, fibrinogen, factor V, fibronectin, PF4, and PDGF, not ADP/Ca2+.", "C": "Azurophilic granules are found in neutrophils and contain enzymes like myeloperoxidase, not platelet ADP/Ca2+.", "D": "Specific (secondary) granules are also a neutrophil granule type containing lactoferrin and other proteins, not a platelet granule."}}}, {"id": "anking-hematology-oncology-anatomy-142", "fuente": "anking", "tema": 27, "anki": "1479267349398", "q": "What is the most common type of leukocyte in peripheral blood, comprising approximately 54-62% of the total?", "o": {"A": "Neutrophils", "B": "Lymphocytes", "C": "Monocytes", "D": "Eosinophils"}, "r": "A", "e": {"correcta": "Neutrophils are the most abundant circulating leukocyte, making up roughly 54-62% of the white blood cell differential, and serve as the primary responders to bacterial infection.", "incorrectas": {"B": "Lymphocytes are the second most common leukocyte (about 25-33%), not the most common.", "C": "Monocytes typically make up only about 3-7% of circulating leukocytes.", "D": "Eosinophils typically comprise only about 1-3% of circulating leukocytes."}}}, {"id": "anking-hematology-oncology-anatomy-143", "fuente": "anking", "tema": 27, "anki": "1479267366025", "q": "Neutrophil counts characteristically increase in response to which type of infection?", "o": {"A": "Bacterial infections", "B": "Viral infections", "C": "Parasitic (helminthic) infections", "D": "Fungal infections limited to mucocutaneous sites"}, "r": "A", "e": {"correcta": "Neutrophilia is the classic acute-phase response to bacterial infections, as neutrophils are recruited to sites of bacterial invasion for phagocytosis.", "incorrectas": {"B": "Viral infections more typically cause lymphocytosis rather than neutrophilia.", "C": "Parasitic and helminthic infections classically cause eosinophilia, not neutrophilia.", "D": "Mucocutaneous fungal infections are more classically associated with T-cell/Th17 defects rather than a neutrophilic response."}}}, {"id": "anking-hematology-oncology-physiology-144", "fuente": "anking", "tema": 28, "anki": "1473982141617", "q": "Which phase of hemostasis is responsible for forming a weak platelet plug?", "o": {"A": "Primary hemostasis", "B": "Secondary hemostasis", "C": "Fibrinolysis", "D": "Coagulation cascade activation"}, "r": "A", "e": {"correcta": "Primary hemostasis involves vasoconstriction, platelet adhesion, activation, and aggregation to form a weak, unstable platelet plug at the site of vascular injury.", "incorrectas": {"B": "Secondary hemostasis stabilizes the weak platelet plug by forming a cross-linked fibrin mesh; it does not form the initial plug.", "C": "Fibrinolysis is the process of breaking down clots, not forming the initial platelet plug.", "D": "The coagulation cascade is the mechanism of secondary hemostasis, which stabilizes rather than initially forms the platelet plug."}}}, {"id": "anking-hematology-oncology-physiology-145", "fuente": "anking", "tema": 28, "anki": "1473985984856", "q": "Which phase of hemostasis stabilizes the weak platelet plug into a durable thrombus?", "o": {"A": "Primary hemostasis", "B": "Secondary hemostasis", "C": "Vasoconstriction", "D": "Platelet degranulation"}, "r": "B", "e": {"correcta": "Secondary hemostasis stabilizes the weak platelet plug by generating a cross-linked fibrin mesh via the coagulation cascade, forming a stable thrombus.", "incorrectas": {"A": "Primary hemostasis only forms the initial weak, unstable platelet plug; it does not stabilize it.", "C": "Vasoconstriction is an early, transient step in primary hemostasis that reduces blood flow but does not stabilize the plug.", "D": "Platelet degranulation is part of primary hemostasis (activation), releasing mediators like ADP and TXA2, but does not stabilize the plug with fibrin."}}}, {"id": "anking-hematology-oncology-physiology-146", "fuente": "anking", "tema": 28, "anki": "1473985992028", "q": "Secondary hemostasis is mediated primarily by which process?", "o": {"A": "The coagulation cascade", "B": "Platelet aggregation via GpIIb/IIIa", "C": "Vasoconstriction of the injured vessel", "D": "Release of von Willebrand factor from endothelium"}, "r": "A", "e": {"correcta": "Secondary hemostasis is mediated by the coagulation cascade, initiated by the tissue factor (extrinsic) pathway and amplified by the contact activation (intrinsic) pathway, culminating in fibrin formation.", "incorrectas": {"B": "GpIIb/IIIa-mediated platelet aggregation is a hallmark of primary hemostasis, not secondary hemostasis.", "C": "Vasoconstriction is the initial vascular response in primary hemostasis, not the mediator of secondary hemostasis.", "D": "vWF release supports platelet adhesion in primary hemostasis, not the fibrin-forming coagulation cascade of secondary hemostasis."}}}, {"id": "anking-hematology-oncology-physiology-147", "fuente": "anking", "tema": 28, "anki": "1473986004354", "q": "Is the platelet plug formed during primary hemostasis stable?", "o": {"A": "Yes, it is permanently stable and requires no further stabilization", "B": "No, it is unstable and easily dislodged", "C": "Yes, but only after fibrin cross-linking occurs", "D": "No, because it lacks GpIIb/IIIa receptors"}, "r": "B", "e": {"correcta": "The platelet plug formed by primary hemostasis is unstable and easily dislodged, though it temporarily stops bleeding until secondary hemostasis stabilizes it with fibrin.", "incorrectas": {"A": "The plug is not permanently stable on its own; it requires secondary hemostasis for stabilization.", "C": "Fibrin cross-linking is part of secondary, not primary, hemostasis; the primary plug itself remains unstable regardless of this later process.", "D": "The primary platelet plug does contain GpIIb/IIIa receptors, which mediate fibrinogen cross-linking; its instability stems from lack of fibrin mesh, not receptor absence."}}}, {"id": "anking-hematology-oncology-physiology-148", "fuente": "anking", "tema": 28, "anki": "1473986009866", "q": "After transient vasoconstriction in primary hemostasis, platelets undergo which process at the site of vessel injury?", "o": {"A": "Degranulation", "B": "Adhesion", "C": "Aggregation", "D": "Fibrinolysis"}, "r": "B", "e": {"correcta": "Following vasoconstriction, platelets adhere to the exposed subendothelial collagen via von Willebrand factor (vWF) cross-linking through the GpIb receptor.", "incorrectas": {"A": "Degranulation occurs after adhesion, when activated platelets release granule contents such as ADP, Ca2+, and TXA2.", "C": "Aggregation occurs later, after activation and GpIIb/IIIa upregulation, when platelets cross-link via fibrinogen.", "D": "Fibrinolysis is the breakdown of clots and occurs much later in hemostasis, unrelated to this initial adhesion step."}}}, {"id": "anking-hematology-oncology-physiology-149", "fuente": "anking", "tema": 28, "anki": "1473986031590", "q": "Following platelet adhesion in primary hemostasis, what is the next step platelets undergo?", "o": {"A": "Aggregation", "B": "Vasoconstriction", "C": "Degranulation", "D": "Fibrin cross-linking"}, "r": "C", "e": {"correcta": "After adhesion, platelets become activated and undergo degranulation, releasing alpha-granule contents (fibrinogen, vWF, PF4), dense-granule contents (ADP, Ca2+, serotonin), and TXA2.", "incorrectas": {"A": "Aggregation occurs after degranulation, once ADP and TXA2 have upregulated GpIIb/IIIa receptors.", "B": "Vasoconstriction is the earliest step in primary hemostasis, occurring before adhesion, not after it.", "D": "Fibrin cross-linking is part of secondary hemostasis and occurs much later than platelet degranulation."}}}, {"id": "anking-hematology-oncology-physiology-150", "fuente": "anking", "tema": 28, "anki": "1473986036899", "q": "Binding of ADP to the P2Y12 receptor promotes optimal surface exposure of which platelet receptor?", "o": {"A": "GPIb", "B": "GPIIb/IIIa", "C": "Thromboxane receptor (TP)", "D": "Protease-activated receptor (PAR-1)"}, "r": "B", "e": {"correcta": "ADP binding to P2Y12 induces a conformational change that increases GPIIb/IIIa affinity for fibrinogen and upregulates more GPIIb/IIIa receptors to the platelet surface, forming the basis for P2Y12 inhibitors like clopidogrel.", "incorrectas": {"A": "GPIb mediates platelet adhesion to vWF/collagen, an earlier step, and is not the receptor upregulated by P2Y12 signaling.", "C": "The thromboxane receptor mediates TXA2 signaling for aggregation but is not the receptor whose surface exposure is promoted by ADP-P2Y12 binding.", "D": "PAR-1 is a thrombin receptor involved in platelet activation by thrombin, not the target of ADP-P2Y12 signaling described here."}}}, {"id": "anking-hematology-oncology-physiology-151", "fuente": "anking", "tema": 28, "anki": "1473986043060", "q": "Which ion is released from platelet dense granules during degranulation?", "o": {"A": "Ca2+", "B": "K+", "C": "Mg2+", "D": "Na+"}, "r": "A", "e": {"correcta": "Dense granules release Ca2+ (along with ADP and serotonin), which helps activate calcium-dependent steps of the coagulation cascade occurring simultaneously.", "incorrectas": {"B": "Potassium is not a characteristic dense granule constituent released during platelet degranulation.", "C": "Magnesium is not a primary dense granule content involved in platelet degranulation or coagulation cascade activation.", "D": "Sodium is not released from platelet dense granules as part of degranulation."}}}, {"id": "anking-hematology-oncology-physiology-152", "fuente": "anking", "tema": 28, "anki": "1473986052600", "q": "Thromboxane A2 (TXA2) is synthesized in platelets by which enzyme?", "o": {"A": "Cyclooxygenase-1 (COX-1)", "B": "Cyclooxygenase-2 (COX-2)", "C": "Lipoxygenase", "D": "Phospholipase A2 alone (without COX)"}, "r": "A", "e": {"correcta": "TXA2 is synthesized by platelet COX-1 upon platelet adhesion and activation; drugs like aspirin irreversibly inhibit COX-1 to reduce TXA2-mediated aggregation.", "incorrectas": {"B": "COX-2 is primarily involved in inflammatory prostaglandin synthesis in other tissues, not platelet TXA2 production; selective COX-2 inhibitors like celecoxib spare COX-1 activity.", "C": "Lipoxygenase produces leukotrienes from arachidonic acid, not thromboxane A2.", "D": "Phospholipase A2 releases arachidonic acid from membrane phospholipids but does not itself synthesize TXA2; that requires COX-1 (and thromboxane synthase)."}}}, {"id": "anking-hematology-oncology-physiology-153", "fuente": "anking", "tema": 28, "anki": "1473986059652", "q": "Thromboxane A2 primarily promotes which platelet function?", "o": {"A": "Aggregation", "B": "Adhesion to collagen", "C": "Degranulation of dense granules only", "D": "Synthesis of fibrinogen by the liver"}, "r": "A", "e": {"correcta": "TXA2 promotes platelet aggregation by upregulating the GpIIb/IIIa receptor complex; this is the pharmacologic basis for aspirin's antiplatelet effect.", "incorrectas": {"B": "Adhesion to collagen is mediated by vWF and GpIb, occurring earlier and independent of TXA2 signaling.", "C": "TXA2 is a product of platelet activation/degranulation, not a trigger specifically limited to dense granule release.", "D": "Fibrinogen synthesis occurs in the liver and is unrelated to TXA2's local platelet-aggregating action."}}}, {"id": "anking-hematology-oncology-physiology-154", "fuente": "anking", "tema": 28, "anki": "1473986065214", "q": "Platelets aggregate at the site of injury via cross-linking of GpIIb/IIIa receptors with which molecule to form a temporary platelet plug?", "o": {"A": "Fibrinogen", "B": "Thrombin", "C": "von Willebrand factor", "D": "Factor XIII"}, "r": "A", "e": {"correcta": "GpIIb/IIIa receptors on adjacent platelets cross-link via fibrinogen, which is released from platelet alpha granules and the liver, forming the temporary platelet plug.", "incorrectas": {"B": "Thrombin activates platelets and converts fibrinogen to fibrin in secondary hemostasis, but it is not the cross-linking molecule for GpIIb/IIIa aggregation.", "C": "von Willebrand factor mediates platelet adhesion via GpIb, not GpIIb/IIIa-mediated aggregation.", "D": "Factor XIII cross-links fibrin strands in secondary hemostasis, not GpIIb/IIIa receptors in platelet aggregation."}}}, {"id": "anking-hematology-oncology-physiology-155", "fuente": "anking", "tema": 28, "anki": "1473986093686", "q": "Regarding platelet aggregation, how do pro-aggregation and anti-aggregation conditions relate to blood flow?", "o": {"A": "Pro-aggregation is favored by decreased blood flow; anti-aggregation by increased blood flow", "B": "Pro-aggregation is favored by increased blood flow; anti-aggregation by decreased blood flow", "C": "Both pro- and anti-aggregation are favored by increased blood flow", "D": "Blood flow rate has no effect on platelet aggregation"}, "r": "A", "e": {"correcta": "Decreased blood flow (stasis) encourages accumulation of pro-clotting factors and favors aggregation, whereas increased blood flow washes out clotting factors and opposes aggregation.", "incorrectas": {"B": "This reverses the actual relationship; increased flow washes away clotting factors and opposes, rather than promotes, aggregation.", "C": "Increased and decreased flow have opposite effects on aggregation; they cannot both favor the same outcome.", "D": "Blood flow rate significantly affects local concentration of clotting factors and thus aggregation, contrary to this statement."}}}, {"id": "anking-hematology-oncology-physiology-156", "fuente": "anking", "tema": 28, "anki": "1473986117229", "q": "Binding between GPIIb/IIIa and fibrinogen results in the formation of what structure?", "o": {"A": "A weak platelet plug", "B": "A stable fibrin clot", "C": "A cross-linked thrombus", "D": "An endothelial repair patch"}, "r": "A", "e": {"correcta": "GPIIb/IIIa-fibrinogen cross-linking between platelets forms a weak, temporary platelet plug, which is subsequently stabilized by secondary hemostasis.", "incorrectas": {"B": "A stable fibrin clot requires the coagulation cascade of secondary hemostasis, not just GPIIb/IIIa-fibrinogen binding.", "C": "A cross-linked thrombus results from Factor XIII-mediated fibrin cross-linking in secondary hemostasis, a later stage than this initial plug formation.", "D": "Endothelial repair is a separate, longer-term vascular healing process unrelated to this platelet receptor-fibrinogen interaction."}}}, {"id": "anking-hematology-oncology-physiology-157", "fuente": "anking", "tema": 28, "anki": "1473986172487", "q": "What is the normal range for platelet counts?", "o": {"A": "150,000 to 400,000/μL", "B": "50,000 to 150,000/μL", "C": "400,000 to 700,000/μL", "D": "5,000 to 50,000/μL"}, "r": "A", "e": {"correcta": "Normal platelet counts range from 150,000 to 400,000 per microliter of blood; values below this range indicate thrombocytopenia.", "incorrectas": {"B": "This range is below normal and would represent mild to moderate thrombocytopenia, not the normal reference range.", "C": "This range exceeds the normal upper limit and would represent thrombocytosis rather than a normal count.", "D": "This range is far below normal and would represent severe thrombocytopenia, not the physiologic normal range."}}}, {"id": "anking-hematology-oncology-physiology-158", "fuente": "anking", "tema": 28, "anki": "1473986174744", "q": "What is the normal range for bleeding time?", "o": {"A": "2 to 7 minutes", "B": "10 to 15 minutes", "C": "30 to 60 seconds", "D": "20 to 30 minutes"}, "r": "A", "e": {"correcta": "Normal bleeding time, which reflects primary hemostasis function, is between 2 and 7 minutes.", "incorrectas": {"B": "This range is prolonged compared to normal and would suggest a defect in primary hemostasis (e.g., platelet dysfunction or von Willebrand disease).", "C": "This range is too short to be physiologically accurate for bleeding time testing, which typically takes several minutes.", "D": "This range is markedly prolonged and would indicate a significant bleeding disorder, not the normal reference range."}}}, {"id": "anking-hematology-oncology-physiology-159", "fuente": "anking", "tema": 28, "anki": "1473995463276", "q": "Coagulation cascade factors are produced in an inactive state by which organ?", "o": {"A": "Liver", "B": "Spleen", "C": "Bone marrow", "D": "Kidney"}, "r": "A", "e": {"correcta": "Most coagulation factors are synthesized by the liver in inactive (zymogen) forms, which are later activated during the coagulation cascade.", "incorrectas": {"B": "The spleen filters blood and stores platelets but does not synthesize coagulation factors.", "C": "Bone marrow produces blood cells, including platelet-producing megakaryocytes, but not the plasma coagulation factors.", "D": "The kidney is not a site of coagulation factor synthesis, though it does affect factor clearance and fluid balance."}}}, {"id": "anking-hematology-oncology-physiology-160", "fuente": "anking", "tema": 28, "anki": "1473995466091", "q": "Activation of the coagulation cascade requires which platelet surface component?", "o": {"A": "Phospholipid surface", "B": "GpIb receptor", "C": "P2Y12 receptor", "D": "Thromboxane receptor"}, "r": "A", "e": {"correcta": "The coagulation cascade requires the exposed phospholipid surface of activated platelets (along with Ca2+ from dense granules) as a scaffold for coagulation factor complex assembly.", "incorrectas": {"B": "GpIb mediates platelet adhesion to vWF/collagen in primary hemostasis, not the phospholipid scaffold needed for the coagulation cascade.", "C": "P2Y12 is the ADP receptor that promotes platelet activation and aggregation, not the surface required for coagulation factor assembly.", "D": "The thromboxane receptor mediates TXA2 signaling for aggregation, unrelated to providing the phospholipid surface for the coagulation cascade."}}}, {"id": "anking-hematology-oncology-physiology-161", "fuente": "anking", "tema": 28, "anki": "1473995492923", "q": "International normalized ratio (INR) is calculated from which coagulation test?", "o": {"A": "Prothrombin time (PT)", "B": "Partial thromboplastin time (PTT)", "C": "Bleeding time", "D": "Thrombin time"}, "r": "A", "e": {"correcta": "INR is calculated from the prothrombin time (PT), standardizing PT results across laboratories; a value of 1 is normal, and values greater than 1 indicate prolonged clotting (e.g., with warfarin therapy).", "incorrectas": {"B": "PTT assesses the intrinsic pathway and is used to monitor heparin therapy, but INR is not derived from it.", "C": "Bleeding time assesses primary hemostasis (platelet function), not the extrinsic pathway measured by PT/INR.", "D": "Thrombin time assesses the final common pathway (fibrinogen to fibrin conversion) but is not the basis for INR calculation."}}}, {"id": "anking-toxicities-side-effects-162", "fuente": "anking", "tema": 29, "anki": "1405141770453", "q": "A patient on propylthiouracil for hyperthyroidism presents with fever and sore throat. Which rare hematological complications are most associated with this drug class (PTU/methimazole)?", "o": {"A": "Agranulocytosis and aplastic anemia", "B": "Hemolytic anemia and thrombocytosis", "C": "Polycythemia vera and eosinophilia", "D": "Megaloblastic anemia and neutrophilia"}, "r": "A", "e": {"correcta": "Propylthiouracil and methimazole can rarely cause agranulocytosis and aplastic anemia, which can present with signs of infection such as sore throat, making a CBC essential in a febrile patient on these drugs.", "incorrectas": {"B": "Hemolytic anemia and thrombocytosis are not characteristic toxicities of thionamide antithyroid drugs.", "C": "Polycythemia and eosinophilia are not associated with PTU or methimazole use.", "D": "Megaloblastic anemia and neutrophilia are not known complications of thionamide therapy."}}}, {"id": "anking-toxicities-side-effects-163", "fuente": "anking", "tema": 29, "anki": "1461601445180", "q": "Metoclopramide's extrapyramidal side effects (dystonia, akathisia) also include which movement disorder feature due to central D2 receptor blockade?", "o": {"A": "Choreiform features", "B": "Parkinsonian features", "C": "Myoclonic features", "D": "Ballismic features"}, "r": "B", "e": {"correcta": "Metoclopramide blocks central D2 receptors, producing extrapyramidal symptoms including parkinsonian features (bradykinesia, rigidity, tremor), similar to antipsychotic-induced parkinsonism.", "incorrectas": {"A": "Chorea is associated with basal ganglia disorders like Huntington disease, not typically a D2-blockade side effect of metoclopramide.", "C": "Myoclonus is not a typical extrapyramidal feature described with metoclopramide.", "D": "Ballismus is classically linked to subthalamic nucleus lesions, not D2 blockade from metoclopramide."}}}, {"id": "anking-toxicities-side-effects-164", "fuente": "anking", "tema": 29, "anki": "1461601459701", "q": "Chronic use of metoclopramide, especially in elderly patients, may lead to which delayed movement disorder?", "o": {"A": "Tardive dyskinesia", "B": "Restless legs syndrome", "C": "Essential tremor", "D": "Wilson disease"}, "r": "A", "e": {"correcta": "Chronic dopamine receptor blockade from metoclopramide can cause tardive dyskinesia, characterized by involuntary repetitive movements such as grimacing, tongue protrusion, and lip smacking, more common in elderly patients.", "incorrectas": {"B": "Restless legs syndrome is a distinct sensorimotor disorder unrelated to chronic D2 blockade from metoclopramide.", "C": "Essential tremor is an idiopathic condition, not a drug-induced complication of metoclopramide.", "D": "Wilson disease is a genetic copper-storage disorder, not a metoclopramide side effect."}}}, {"id": "anking-toxicities-side-effects-165", "fuente": "anking", "tema": 29, "anki": "1463675427032", "q": "Oral bisphosphonates commonly cause which category of adverse effects?", "o": {"A": "Upper GI effects such as esophagitis and acid reflux", "B": "Lower GI bleeding and colitis", "C": "Hepatotoxicity with jaundice", "D": "Pancreatitis with elevated lipase"}, "r": "A", "e": {"correcta": "Oral bisphosphonates can cause upper GI side effects including acid reflux, esophagitis, and esophageal ulcers, so patients are advised to take them with water and remain upright afterward.", "incorrectas": {"B": "Bisphosphonates are not typically associated with lower GI bleeding or colitis.", "C": "Hepatotoxicity is not a recognized major side effect of oral bisphosphonates.", "D": "Pancreatitis is not a characteristic adverse effect of bisphosphonates."}}}, {"id": "anking-toxicities-side-effects-166", "fuente": "anking", "tema": 29, "anki": "1463675434980", "q": "Which osteoporosis medication is classically associated with acid reflux, esophagitis, and esophageal ulcers?", "o": {"A": "Oral bisphosphonates", "B": "Denosumab", "C": "Teriparatide", "D": "Calcitonin"}, "r": "A", "e": {"correcta": "Oral bisphosphonates are well known to cause esophageal irritation, including acid reflux, esophagitis, and esophageal ulcers, so patients should take them with plenty of water and stay upright for 30 minutes.", "incorrectas": {"B": "Denosumab is a subcutaneous RANKL inhibitor and is not associated with esophageal irritation.", "C": "Teriparatide is an injectable PTH analog and does not cause esophageal side effects.", "D": "Calcitonin is administered via injection or nasal spray and is not linked to esophagitis."}}}, {"id": "anking-toxicities-side-effects-167", "fuente": "anking", "tema": 29, "anki": "1463845215297", "q": "Which adverse effects are classically associated with the tetracycline derivative demeclocycline?", "o": {"A": "Photosensitivity and bone/teeth abnormalities", "B": "Ototoxicity and nephrotoxicity", "C": "Cartilage damage and tendon rupture", "D": "Red-orange body fluid discoloration"}, "r": "A", "e": {"correcta": "Demeclocycline, like other tetracyclines, is associated with photosensitivity and abnormalities of bone and teeth, including tooth discoloration, especially when used in children or during pregnancy.", "incorrectas": {"B": "Ototoxicity and nephrotoxicity are classically associated with aminoglycosides, not tetracyclines.", "C": "Cartilage damage and tendon rupture are characteristic of fluoroquinolones, not tetracyclines.", "D": "Red-orange body fluid discoloration is a hallmark of rifampin, not demeclocycline."}}}, {"id": "anking-toxicities-side-effects-168", "fuente": "anking", "tema": 29, "anki": "1464478365999", "q": "Which antacid is associated with diarrhea when overused ('must go to the bathroom')?", "o": {"A": "Magnesium hydroxide", "B": "Aluminum hydroxide", "C": "Calcium carbonate", "D": "Sodium bicarbonate"}, "r": "A", "e": {"correcta": "Magnesium hydroxide causes diarrhea when overused, remembered by the mnemonic 'Mg2+ = must go to the bathroom.'", "incorrectas": {"B": "Aluminum hydroxide causes constipation and proximal muscle weakness, not diarrhea.", "C": "Calcium carbonate is more associated with constipation and can cause milk-alkali syndrome.", "D": "Sodium bicarbonate can cause metabolic alkalosis, not classically diarrhea."}}}, {"id": "anking-toxicities-side-effects-169", "fuente": "anking", "tema": 29, "anki": "1464478389699", "q": "Which antacid is associated with proximal muscle weakness and seizures when overused?", "o": {"A": "Aluminum hydroxide", "B": "Magnesium hydroxide", "C": "Calcium carbonate", "D": "Sodium bicarbonate"}, "r": "A", "e": {"correcta": "Aluminum hydroxide overuse can cause hypophosphatemia, leading to proximal muscle weakness, osteodystrophy, and seizures, along with constipation.", "incorrectas": {"B": "Magnesium hydroxide is associated with diarrhea and hyporeflexia/hypotension in overdose, not primarily muscle weakness and seizures.", "C": "Calcium carbonate overuse is linked to milk-alkali syndrome and constipation, not seizures from hypophosphatemia.", "D": "Sodium bicarbonate overuse causes metabolic alkalosis, not proximal muscle weakness and seizures."}}}, {"id": "anking-toxicities-side-effects-170", "fuente": "anking", "tema": 29, "anki": "1472091136098", "q": "Which class III antiarrhythmic drug is known for numerous neurologic side effects such as tremor, ataxia, peripheral neuropathy, and sleep disturbances?", "o": {"A": "Amiodarone", "B": "Sotalol", "C": "Ibutilide", "D": "Flecainide"}, "r": "A", "e": {"correcta": "Amiodarone has a broad adverse effect profile including numerous neurologic effects such as tremor, ataxia, peripheral neuropathy, and sleep disturbances, in addition to thyroid, pulmonary, and hepatic toxicity.", "incorrectas": {"B": "Sotalol is a class III antiarrhythmic mainly known for causing torsades de pointes, not prominent neurologic toxicity.", "C": "Ibutilide is primarily associated with QT prolongation and torsades de pointes, not neurologic side effects.", "D": "Flecainide is a class IC antiarrhythmic associated with proarrhythmia, not the neurologic effects described."}}}, {"id": "anking-toxicities-side-effects-171", "fuente": "anking", "tema": 29, "anki": "1472091220986", "q": "Sotalol, dofetilide, and ibutilide (class III antiarrhythmics) share which common adverse effect?", "o": {"A": "Torsades de pointes", "B": "Pulmonary fibrosis", "C": "Blue-gray skin discoloration", "D": "Hepatotoxicity"}, "r": "A", "e": {"correcta": "These class III antiarrhythmics prolong the QT interval by blocking potassium channels, predisposing patients to torsades de pointes.", "incorrectas": {"B": "Pulmonary fibrosis is a well-known toxicity of amiodarone, not sotalol, dofetilide, or ibutilide.", "C": "Blue-gray skin discoloration is characteristic of amiodarone, not these other class III agents.", "D": "Hepatotoxicity is more associated with amiodarone than with sotalol, dofetilide, or ibutilide."}}}, {"id": "anking-toxicities-side-effects-172", "fuente": "anking", "tema": 29, "anki": "1462849213386", "q": "What is the most common complication of insulin therapy?", "o": {"A": "Hypoglycemia", "B": "Hyperkalemia", "C": "Weight loss", "D": "Hepatotoxicity"}, "r": "A", "e": {"correcta": "Hypoglycemia is the most common complication of insulin therapy, presenting with tachycardia, palpitations, sweating, and nausea due to increased autonomic activity; lipodystrophy and hypersensitivity reactions are rarer complications.", "incorrectas": {"B": "Insulin actually drives potassium into cells and is used to treat hyperkalemia, not cause it.", "C": "Insulin therapy is more commonly associated with weight gain, not weight loss.", "D": "Hepatotoxicity is not a recognized common complication of insulin therapy."}}}, {"id": "anking-toxicities-side-effects-173", "fuente": "anking", "tema": 29, "anki": "1462849240470", "q": "Sulfonylureas belong to which drug category that may cause adverse reactions in allergic patients?", "o": {"A": "Sulfa drugs", "B": "Penicillin derivatives", "C": "Nitrofuran derivatives", "D": "Salicylates"}, "r": "A", "e": {"correcta": "Sulfonylureas are sulfa drugs, so patients with sulfa allergies may experience adverse hypersensitivity reactions when taking them.", "incorrectas": {"B": "Sulfonylureas are not chemically related to penicillins, so penicillin allergy is not the relevant cross-reactivity concern.", "C": "Sulfonylureas are not nitrofuran derivatives; nitrofurantoin is a different drug class.", "D": "Sulfonylureas are not salicylates, which are aspirin-related compounds."}}}, {"id": "anking-toxicities-side-effects-174", "fuente": "anking", "tema": 29, "anki": "1462849277484", "q": "Tolbutamide and chlorpropamide belong to which drug class?", "o": {"A": "1st generation sulfonylureas", "B": "2nd generation sulfonylureas", "C": "Meglitinides", "D": "Biguanides"}, "r": "A", "e": {"correcta": "Tolbutamide and chlorpropamide are 1st generation sulfonylureas, which must be given in larger doses and are therefore less commonly used today.", "incorrectas": {"B": "2nd generation sulfonylureas include glyburide, glimepiride, and glipizide, not tolbutamide or chlorpropamide.", "C": "Meglitinides (e.g., repaglinide, nateglinide) are a different class of insulin secretagogues.", "D": "Biguanides refer to metformin, a distinct drug class with a different mechanism of action."}}}, {"id": "anking-toxicities-side-effects-175", "fuente": "anking", "tema": 29, "anki": "1462849289458", "q": "Glyburide, glimepiride, and glipizide belong to which drug class?", "o": {"A": "2nd generation sulfonylureas", "B": "1st generation sulfonylureas", "C": "Alpha-glucosidase inhibitors", "D": "GLP-1 agonists"}, "r": "A", "e": {"correcta": "Glyburide, glimepiride, and glipizide are 2nd generation sulfonylureas, which can be given in smaller doses than 1st generation agents, resulting in less risk of hypoglycemia.", "incorrectas": {"B": "1st generation sulfonylureas include tolbutamide and chlorpropamide, not these three drugs.", "C": "Alpha-glucosidase inhibitors include acarbose and miglitol, a mechanistically different drug class.", "D": "GLP-1 agonists include drugs like exenatide and liraglutide, unrelated to sulfonylureas."}}}, {"id": "anking-toxicities-side-effects-176", "fuente": "anking", "tema": 29, "anki": "1462849457192", "q": "GLP-1 agonists can cause which serious adverse effect, in addition to nausea and vomiting?", "o": {"A": "Pancreatitis", "B": "Lactic acidosis", "C": "Hepatotoxicity", "D": "Agranulocytosis"}, "r": "A", "e": {"correcta": "GLP-1 agonists carry a risk of pancreatitis as a possible serious adverse effect, alongside common GI side effects like nausea and vomiting.", "incorrectas": {"B": "Lactic acidosis is a classic risk associated with metformin, not GLP-1 agonists.", "C": "Hepatotoxicity is not a characteristic adverse effect of GLP-1 agonists.", "D": "Agranulocytosis is not a recognized side effect of GLP-1 agonist therapy."}}}, {"id": "anking-toxicities-side-effects-177", "fuente": "anking", "tema": 29, "anki": "1462913257878", "q": "What is the most common side effect of metformin?", "o": {"A": "GI upset (nausea, vomiting, diarrhea)", "B": "Hypoglycemia", "C": "Weight gain", "D": "Pancreatitis"}, "r": "A", "e": {"correcta": "The most common side effect of metformin is GI upset, including nausea, vomiting, anorexia, and diarrhea; the more serious but rare risk is lactic acidosis.", "incorrectas": {"B": "Metformin does not typically cause hypoglycemia when used as monotherapy, unlike sulfonylureas or insulin.", "C": "Metformin is actually weight-neutral or associated with modest weight loss, not weight gain.", "D": "Pancreatitis is more characteristic of GLP-1 agonists, not metformin."}}}, {"id": "anking-toxicities-side-effects-178", "fuente": "anking", "tema": 29, "anki": "1462913732310", "q": "Alpha-glucosidase inhibitors such as acarbose and miglitol are infrequently prescribed because they can cause which side effects?", "o": {"A": "Diarrhea and flatulence", "B": "Hypoglycemia and weight gain", "C": "Lactic acidosis and renal failure", "D": "Hepatotoxicity and rash"}, "r": "A", "e": {"correcta": "Alpha-glucosidase inhibitors cause diarrhea and flatulence due to fermentation of undigested carbohydrates by gut bacteria, along with abdominal pain, limiting their use.", "incorrectas": {"B": "These drugs do not typically cause hypoglycemia or weight gain; they work by delaying carbohydrate absorption.", "C": "Lactic acidosis and renal failure are concerns with metformin, not alpha-glucosidase inhibitors.", "D": "Hepatotoxicity and rash are not the primary limiting side effects of this drug class."}}}, {"id": "anking-miscellaneous-pharmacology-179", "fuente": "anking", "tema": 30, "anki": "1461615646774", "q": "Cimetidine, ranitidine, famotidine, and nizatidine (the '-tidine' drugs) belong to which drug class?", "o": {"A": "H2 receptor antagonists", "B": "Proton pump inhibitors", "C": "Muscarinic receptor antagonists", "D": "5-HT3 receptor antagonists"}, "r": "A", "e": {"correcta": "All four drugs share the '-tidine' suffix and act as H2 receptor antagonists, reducing gastric acid secretion by blocking histamine H2 receptors on parietal cells.", "incorrectas": {"B": "Proton pump inhibitors (e.g., omeprazole, the '-prazole' drugs) act on H+/K+ ATPase, not the histamine receptor.", "C": "Muscarinic antagonists like atropine block acetylcholine receptors, unrelated to these '-tidine' drugs.", "D": "5-HT3 antagonists (e.g., ondansetron) are antiemetics that block serotonin receptors, not histamine receptors."}}}, {"id": "anking-miscellaneous-pharmacology-180", "fuente": "anking", "tema": 30, "anki": "1471999921983", "q": "Quinidine belongs to which antiarrhythmic drug class?", "o": {"A": "Class IA antiarrhythmics", "B": "Class IB antiarrhythmics", "C": "Class IC antiarrhythmics", "D": "Class III antiarrhythmics"}, "r": "A", "e": {"correcta": "Quinidine is a Class IA antiarrhythmic (sodium channel blocker with intermediate dissociation kinetics that also prolongs the action potential); it is also used as an antimalarial.", "incorrectas": {"B": "Class IB drugs (e.g., lidocaine, mexiletine) have fast dissociation and shorten the action potential, unlike quinidine.", "C": "Class IC drugs (e.g., flecainide, propafenone) have slow dissociation but do not prolong the action potential like Class IA.", "D": "Class III drugs (e.g., dofetilide, ibutilide) block potassium channels rather than acting primarily on sodium channels."}}}, {"id": "anking-miscellaneous-pharmacology-181", "fuente": "anking", "tema": 30, "anki": "1471999942205", "q": "Procainamide belongs to which antiarrhythmic drug class?", "o": {"A": "Class IA antiarrhythmics", "B": "Class IB antiarrhythmics", "C": "Class IC antiarrhythmics", "D": "Class II antiarrhythmics"}, "r": "A", "e": {"correcta": "Procainamide is a Class IA antiarrhythmic, a sodium channel blocker that also prolongs the QT interval and can cause drug-induced lupus.", "incorrectas": {"B": "Class IB agents (lidocaine, mexiletine, phenytoin) are used preferentially in ischemic/ventricular tissue and shorten the action potential.", "C": "Class IC agents (flecainide, propafenone) markedly slow conduction without affecting action potential duration.", "D": "Class II antiarrhythmics are beta-blockers, a mechanistically distinct class from sodium channel blockers."}}}, {"id": "anking-miscellaneous-pharmacology-182", "fuente": "anking", "tema": 30, "anki": "1471999956293", "q": "Disopyramide belongs to which antiarrhythmic drug class?", "o": {"A": "Class IA antiarrhythmics", "B": "Class IB antiarrhythmics", "C": "Class IC antiarrhythmics", "D": "Class IV antiarrhythmics"}, "r": "A", "e": {"correcta": "Disopyramide is a Class IA antiarrhythmic, sharing the sodium channel-blocking and action potential-prolonging properties of quinidine and procainamide.", "incorrectas": {"B": "Class IB drugs like lidocaine and mexiletine shorten rather than prolong the action potential.", "C": "Class IC drugs like flecainide have the strongest sodium channel blockade with no effect on repolarization.", "D": "Class IV antiarrhythmics are non-dihydropyridine calcium channel blockers (verapamil, diltiazem), a different mechanism entirely."}}}, {"id": "anking-miscellaneous-pharmacology-183", "fuente": "anking", "tema": 30, "anki": "1472000064700", "q": "Lidocaine, used as an antiarrhythmic, belongs to which class?", "o": {"A": "Class IB antiarrhythmics", "B": "Class IA antiarrhythmics", "C": "Class IC antiarrhythmics", "D": "Class II antiarrhythmics"}, "r": "A", "e": {"correcta": "Lidocaine is a Class IB antiarrhythmic with fast on/off sodium channel kinetics, preferentially affecting ischemic or depolarized tissue; it is also used as a topical anesthetic and for nerve blocks.", "incorrectas": {"B": "Class IA drugs like quinidine and procainamide prolong the action potential, unlike lidocaine.", "C": "Class IC drugs like flecainide have slow dissociation kinetics, opposite to lidocaine's fast kinetics.", "D": "Class II antiarrhythmics are beta-blockers, unrelated to lidocaine's sodium channel mechanism."}}}, {"id": "anking-miscellaneous-pharmacology-184", "fuente": "anking", "tema": 30, "anki": "1472000071465", "q": "Phenytoin, though primarily an anti-epileptic, has properties of which antiarrhythmic class?", "o": {"A": "Class IB antiarrhythmics", "B": "Class IA antiarrhythmics", "C": "Class IC antiarrhythmics", "D": "Class III antiarrhythmics"}, "r": "A", "e": {"correcta": "Phenytoin has Class IB antiarrhythmic properties, similar to lidocaine and mexiletine, despite being used clinically mainly as an anticonvulsant.", "incorrectas": {"B": "Class IA drugs prolong the action potential and QT interval, which phenytoin does not typically do.", "C": "Class IC drugs have the slowest dissociation kinetics among sodium channel blockers, unlike phenytoin.", "D": "Class III drugs block potassium channels, a mechanism distinct from phenytoin's sodium channel action."}}}, {"id": "anking-miscellaneous-pharmacology-185", "fuente": "anking", "tema": 30, "anki": "1472000097100", "q": "Mexiletine belongs to which antiarrhythmic drug class?", "o": {"A": "Class IB antiarrhythmics", "B": "Class IA antiarrhythmics", "C": "Class IC antiarrhythmics", "D": "Class IV antiarrhythmics"}, "r": "A", "e": {"correcta": "Mexiletine is a Class IB antiarrhythmic, often remembered by the mnemonic 'I'd Buy Liddy's Pheny Mexican Tacos' (lidocaine, phenytoin, mexiletine, tocainide).", "incorrectas": {"B": "Class IA drugs (quinidine, procainamide, disopyramide) prolong the action potential duration, unlike mexiletine.", "C": "Class IC drugs (flecainide, propafenone) cause the most pronounced conduction slowing without affecting repolarization.", "D": "Class IV antiarrhythmics are calcium channel blockers, a different drug class and mechanism."}}}, {"id": "anking-miscellaneous-pharmacology-186", "fuente": "anking", "tema": 30, "anki": "1472000146226", "q": "Flecainide belongs to which antiarrhythmic drug class?", "o": {"A": "Class IC antiarrhythmics", "B": "Class IA antiarrhythmics", "C": "Class IB antiarrhythmics", "D": "Class III antiarrhythmics"}, "r": "A", "e": {"correcta": "Flecainide is a Class IC antiarrhythmic, causing marked slowing of cardiac conduction with minimal effect on action potential duration, and is contraindicated post-MI.", "incorrectas": {"B": "Class IA drugs like quinidine also prolong the action potential, which flecainide does not significantly do.", "C": "Class IB drugs like lidocaine have fast dissociation kinetics, unlike flecainide's slow kinetics.", "D": "Class III drugs primarily block potassium channels rather than sodium channels."}}}, {"id": "anking-miscellaneous-pharmacology-187", "fuente": "anking", "tema": 30, "anki": "1472000153006", "q": "Propafenone belongs to which antiarrhythmic drug class?", "o": {"A": "Class IC antiarrhythmics", "B": "Class IA antiarrhythmics", "C": "Class IB antiarrhythmics", "D": "Class II antiarrhythmics"}, "r": "A", "e": {"correcta": "Propafenone is a Class IC antiarrhythmic, sharing flecainide's property of strong sodium channel blockade with slow dissociation kinetics.", "incorrectas": {"B": "Class IA agents prolong repolarization, a property propafenone lacks.", "C": "Class IB agents have fast dissociation kinetics and act preferentially on ischemic tissue, unlike propafenone.", "D": "Class II antiarrhythmics are beta-blockers, mechanistically unrelated to propafenone."}}}, {"id": "anking-miscellaneous-pharmacology-188", "fuente": "anking", "tema": 30, "anki": "1472091088106", "q": "Dofetilide and ibutilide belong to which antiarrhythmic drug class?", "o": {"A": "Class III antiarrhythmics (K+ channel blockers)", "B": "Class IA antiarrhythmics", "C": "Class IV antiarrhythmics", "D": "Class II antiarrhythmics"}, "r": "A", "e": {"correcta": "Dofetilide and ibutilide are Class III antiarrhythmics that block potassium channels, prolonging the action potential and QT interval.", "incorrectas": {"B": "Class IA drugs like quinidine block sodium channels, not primarily potassium channels.", "C": "Class IV antiarrhythmics are non-dihydropyridine calcium channel blockers (verapamil, diltiazem).", "D": "Class II antiarrhythmics are beta-blockers that reduce sympathetic activity on the heart, a different mechanism."}}}, {"id": "anking-miscellaneous-pharmacology-189", "fuente": "anking", "tema": 30, "anki": "1472261861671", "q": "Diltiazem and verapamil belong to which antiarrhythmic drug class?", "o": {"A": "Class IV antiarrhythmics (non-dihydropyridine Ca2+ channel blockers)", "B": "Class III antiarrhythmics", "C": "Class IA antiarrhythmics", "D": "Class II antiarrhythmics"}, "r": "A", "e": {"correcta": "Diltiazem and verapamil are Class IV antiarrhythmics, non-dihydropyridine calcium channel blockers that slow conduction through the AV node.", "incorrectas": {"B": "Class III antiarrhythmics like dofetilide block potassium channels rather than calcium channels.", "C": "Class IA antiarrhythmics like quinidine block sodium channels, a different mechanism from calcium channel blockade.", "D": "Class II antiarrhythmics are beta-blockers, not calcium channel blockers."}}}, {"id": "anking-miscellaneous-pharmacology-190", "fuente": "anking", "tema": 30, "anki": "1472502484635", "q": "What suffix do dihydropyridine calcium channel blockers (e.g., nifedipine, amlodipine, nicardipine) share?", "o": {"A": "-dipine", "B": "-azosin", "C": "-olol", "D": "-artan"}, "r": "A", "e": {"correcta": "Dihydropyridine calcium channel blockers share the '-dipine' suffix, as seen in nifedipine, amlodipine, nicardipine, clevidipine, and nimodipine.", "incorrectas": {"B": "The '-azosin' suffix belongs to alpha-1 blockers like prazosin and doxazosin, not calcium channel blockers.", "C": "The '-olol' suffix denotes beta-blockers such as metoprolol and propranolol.", "D": "The '-artan' suffix denotes angiotensin II receptor blockers such as losartan and valsartan."}}}, {"id": "anking-miscellaneous-pharmacology-191", "fuente": "anking", "tema": 30, "anki": "1472672275670", "q": "Cholestyramine, colestipol, and colesevelam belong to which drug class?", "o": {"A": "Bile acid resins", "B": "Fibrates", "C": "Statins", "D": "Niacin (nicotinic acid) derivatives"}, "r": "A", "e": {"correcta": "Cholestyramine, colestipol, and colesevelam are bile acid resins that bind bile acids in the gut, increasing hepatic conversion of cholesterol to bile acids and lowering LDL.", "incorrectas": {"B": "Fibrates (e.g., gemfibrozil, fenofibrate) activate PPAR-alpha to lower triglycerides, a different class and mechanism.", "C": "Statins inhibit HMG-CoA reductase to reduce cholesterol synthesis, unlike bile acid resins.", "D": "Niacin reduces VLDL and LDL production and raises HDL through a distinct mechanism from bile acid sequestration."}}}, {"id": "anking-miscellaneous-pharmacology-192", "fuente": "anking", "tema": 30, "anki": "1472676030952", "q": "Gemfibrozil and fenofibrate belong to which drug class?", "o": {"A": "Fibrates", "B": "Bile acid resins", "C": "Statins", "D": "PCSK9 inhibitors"}, "r": "A", "e": {"correcta": "Gemfibrozil and fenofibrate are fibrates, which activate PPAR-alpha to upregulate lipoprotein lipase and are especially effective at lowering triglycerides.", "incorrectas": {"B": "Bile acid resins like cholestyramine work by binding bile acids in the intestine, unrelated to PPAR-alpha activation.", "C": "Statins inhibit HMG-CoA reductase, mainly lowering LDL rather than triglycerides.", "D": "PCSK9 inhibitors (e.g., evolocumab) are monoclonal antibodies that increase LDL receptor recycling, a very different mechanism."}}}, {"id": "anking-miscellaneous-pharmacology-193", "fuente": "anking", "tema": 30, "anki": "1472747829983", "q": "Isosorbide mononitrate/dinitrate and nitroglycerin belong to which drug class?", "o": {"A": "Nitrates", "B": "Class IA antiarrhythmics", "C": "Non-dihydropyridine calcium channel blockers", "D": "Beta-blockers"}, "r": "A", "e": {"correcta": "Isosorbide mononitrate/dinitrate and nitroglycerin are nitrates, which release nitric oxide to cause venodilation and reduce cardiac preload, relieving angina.", "incorrectas": {"B": "Class IA antiarrhythmics like quinidine block sodium channels and are unrelated to nitric oxide donors.", "C": "Non-dihydropyridine calcium channel blockers like verapamil act on calcium channels, not nitric oxide pathways.", "D": "Beta-blockers reduce heart rate and contractility via sympathetic blockade, a different antianginal mechanism."}}}, {"id": "anking-miscellaneous-pharmacology-194", "fuente": "anking", "tema": 30, "anki": "1474571783356", "q": "Cetirizine belongs to which drug class?", "o": {"A": "2nd generation H1 receptor antagonists", "B": "1st generation H1 receptor antagonists", "C": "H2 receptor antagonists", "D": "Leukotriene receptor antagonists"}, "r": "A", "e": {"correcta": "Cetirizine is a 2nd generation H1 receptor antagonist, offering antihistamine effects with reduced sedation compared to 1st generation agents because it crosses the blood-brain barrier less readily.", "incorrectas": {"B": "1st generation H1 blockers like diphenhydramine cause significant sedation due to CNS penetration, unlike cetirizine.", "C": "H2 receptor antagonists like ranitidine act on gastric parietal cells, not on allergic histamine responses.", "D": "Leukotriene receptor antagonists like montelukast act on a different mediator pathway used mainly in asthma."}}}, {"id": "anking-miscellaneous-pharmacology-195", "fuente": "anking", "tema": 30, "anki": "1474571788333", "q": "Loratadine belongs to which drug class?", "o": {"A": "2nd generation H1 receptor antagonists", "B": "1st generation H1 receptor antagonists", "C": "Mast cell stabilizers", "D": "Corticosteroids"}, "r": "A", "e": {"correcta": "Loratadine is a 2nd generation H1 receptor antagonist with minimal sedation, used for allergic rhinitis and urticaria.", "incorrectas": {"B": "1st generation antihistamines such as diphenhydramine and chlorpheniramine are more sedating due to CNS penetration.", "C": "Mast cell stabilizers like cromolyn prevent degranulation rather than blocking histamine receptors.", "D": "Corticosteroids act via anti-inflammatory gene regulation, a mechanism distinct from histamine receptor blockade."}}}, {"id": "anking-miscellaneous-pharmacology-196", "fuente": "anking", "tema": 30, "anki": "1474580731345", "q": "Fluticasone, budesonide, and beclomethasone belong to which drug class?", "o": {"A": "Inhaled corticosteroids", "B": "Leukotriene receptor antagonists", "C": "Long-acting beta-2 agonists", "D": "Mast cell stabilizers"}, "r": "A", "e": {"correcta": "Fluticasone, budesonide, and beclomethasone are inhaled corticosteroids used as first-line controller therapy for asthma, reducing airway inflammation.", "incorrectas": {"B": "Leukotriene receptor antagonists like montelukast block leukotriene receptors rather than acting as corticosteroids.", "C": "Long-acting beta-2 agonists like salmeterol cause bronchodilation via beta-2 receptor stimulation, a different mechanism.", "D": "Mast cell stabilizers like cromolyn prevent mediator release from mast cells rather than exerting anti-inflammatory steroid effects."}}}, {"id": "anking-pharmacokinetics-pharmacodynamics-197", "fuente": "anking", "tema": 31, "anki": "1472426456195", "q": "For a chemical reaction, if the Gibbs free energy change (ΔG) is less than zero, what does this indicate about the reaction?", "o": {"A": "The reaction occurs spontaneously", "B": "The reaction requires continuous energy input to proceed", "C": "The reaction is at equilibrium and will not proceed further", "D": "The reaction rate is independent of substrate concentration"}, "r": "A", "e": {"correcta": "A negative ΔG (ΔG < 0) means the reaction is exergonic and thermodynamically favorable, so it proceeds spontaneously without net energy input.", "incorrectas": {"B": "A reaction requiring added energy has a positive ΔG (endergonic), not a negative one.", "C": "At equilibrium ΔG = 0, not less than zero.", "D": "ΔG reflects thermodynamic favorability, not kinetics or substrate dependence."}}}, {"id": "anking-pharmacokinetics-pharmacodynamics-198", "fuente": "anking", "tema": 31, "anki": "1472426481431", "q": "For a chemical reaction, if ΔG is greater than zero, what is true of the reaction?", "o": {"A": "It proceeds spontaneously without input", "B": "Energy must be added for the reaction to occur", "C": "It is a zero-order reaction", "D": "The enzyme concentration must be doubled"}, "r": "B", "e": {"correcta": "A positive ΔG indicates an endergonic reaction, meaning it is not thermodynamically favorable and requires an external energy input to proceed.", "incorrectas": {"A": "Spontaneous reactions have a negative ΔG, not positive.", "C": "Reaction order describes kinetics, not the sign of ΔG.", "D": "Enzyme concentration affects reaction rate (Vmax), not the thermodynamics (ΔG) of the reaction."}}}, {"id": "anking-pharmacokinetics-pharmacodynamics-199", "fuente": "anking", "tema": 31, "anki": "1472426485090", "q": "By what mechanism do enzymes increase the rate of a chemical reaction?", "o": {"A": "By increasing the ΔG of the reaction", "B": "By decreasing the energy of activation", "C": "By increasing the concentration of substrate", "D": "By converting the reaction from first-order to zero-order kinetics"}, "r": "B", "e": {"correcta": "Enzymes function as catalysts by lowering the activation energy required for a reaction to proceed, thereby increasing reaction rate without altering the overall ΔG.", "incorrectas": {"A": "Enzymes do not affect ΔG; they only lower the activation energy barrier.", "C": "Enzymes do not change substrate concentration; they facilitate the reaction between existing substrate molecules.", "D": "Reaction order depends on concentrations and saturation kinetics, not simply on the presence of an enzyme."}}}, {"id": "anking-pharmacokinetics-pharmacodynamics-200", "fuente": "anking", "tema": 31, "anki": "1472426491309", "q": "The rate of an enzyme-catalyzed reaction depends on the concentration of which two components?", "o": {"A": "The enzyme and the substrate", "B": "The product and the cofactor", "C": "The pH and the temperature only", "D": "The activation energy and the ΔG"}, "r": "A", "e": {"correcta": "Reaction rate in enzyme kinetics is determined by the concentrations of both the enzyme and its substrate, which together dictate whether the reaction is enzyme-limited or substrate-limited.", "incorrectas": {"B": "Product concentration and cofactors can influence reactions but are not the primary determinants described by basic rate dependence.", "C": "While pH and temperature affect enzyme activity, they are not the concentration variables referenced here.", "D": "Activation energy and ΔG are thermodynamic/kinetic barriers, not concentration variables."}}}, {"id": "anking-pharmacokinetics-pharmacodynamics-201", "fuente": "anking", "tema": 31, "anki": "1472426494725", "q": "The Michaelis-Menten constant (Km) is defined as the concentration of which substance at which the reaction rate equals half of Vmax?", "o": {"A": "The enzyme", "B": "The substrate", "C": "The product", "D": "The cofactor"}, "r": "B", "e": {"correcta": "Km is defined as the substrate concentration at which the reaction velocity is half of Vmax (Vmax/2), reflecting enzyme-substrate affinity.", "incorrectas": {"A": "Km refers to substrate concentration, not enzyme concentration.", "C": "Product concentration is not part of the Km definition.", "D": "Cofactor concentration is not what Km measures."}}}, {"id": "anking-pharmacokinetics-pharmacodynamics-202", "fuente": "anking", "tema": 31, "anki": "1472426501144", "q": "How does the Michaelis-Menten constant (Km) relate to the affinity of an enzyme for its substrate?", "o": {"A": "Km is directly proportional to affinity", "B": "Km is inversely proportional to affinity", "C": "Km has no relationship to affinity", "D": "Km equals affinity multiplied by Vmax"}, "r": "B", "e": {"correcta": "Km is inversely proportional to enzyme-substrate affinity; a low Km indicates high affinity (the enzyme reaches half-maximal velocity at a low substrate concentration), while a high Km indicates low affinity.", "incorrectas": {"A": "A direct proportionality would mean high affinity gives a high Km, which is incorrect.", "C": "Km is a well-established indirect measure of affinity, not unrelated to it.", "D": "Km is not calculated as a product of affinity and Vmax."}}}, {"id": "anking-pharmacokinetics-pharmacodynamics-203", "fuente": "anking", "tema": 31, "anki": "1472426513341", "q": "How does Vmax of a reaction relate to enzyme concentration?", "o": {"A": "Vmax is directly proportional to enzyme concentration", "B": "Vmax is inversely proportional to enzyme concentration", "C": "Vmax is unrelated to enzyme concentration", "D": "Vmax is directly proportional to substrate concentration only"}, "r": "A", "e": {"correcta": "Vmax, the maximum reaction velocity at enzyme saturation, increases directly with the amount of enzyme present, since more enzyme molecules can process substrate simultaneously.", "incorrectas": {"B": "An inverse relationship would mean more enzyme gives a lower Vmax, which is incorrect.", "C": "Vmax is fundamentally tied to enzyme concentration in Michaelis-Menten kinetics.", "D": "At Vmax the reaction is saturated with substrate, so further substrate increases do not raise Vmax; enzyme amount is the determining factor."}}}, {"id": "anking-pharmacokinetics-pharmacodynamics-204", "fuente": "anking", "tema": 31, "anki": "1472426521266", "q": "In what order of kinetics is the reaction rate directly proportional to the substrate (drug) concentration?", "o": {"A": "Zero-order kinetics", "B": "First-order kinetics", "C": "Second-order kinetics", "D": "Mixed-order kinetics"}, "r": "B", "e": {"correcta": "In first-order kinetics, the rate of reaction is directly proportional to substrate concentration because the substrate is the rate-limiting reagent (enzyme is not saturated).", "incorrectas": {"A": "In zero-order kinetics, rate is constant and independent of substrate concentration because the enzyme (not substrate) is limiting.", "C": "Second-order kinetics involves proportionality to the concentrations of two reactants multiplied together, which is not the standard description used here.", "D": "Mixed-order is not a standard kinetics classification used in this context."}}}, {"id": "anking-pharmacokinetics-pharmacodynamics-205", "fuente": "anking", "tema": 31, "anki": "1472426529103", "q": "In what order of kinetics is the rate of reaction constant, regardless of substrate concentration?", "o": {"A": "First-order kinetics", "B": "Zero-order kinetics", "C": "Second-order kinetics", "D": "Exponential-order kinetics"}, "r": "B", "e": {"correcta": "In zero-order kinetics the rate of reaction is constant because the enzyme is saturated with substrate and becomes the limiting factor, so further increases in substrate do not change the rate.", "incorrectas": {"A": "First-order kinetics has a rate directly proportional to substrate concentration, not constant.", "C": "Second-order kinetics implies rate depends on the concentration of two reactants, not a constant rate.", "D": "There is no standard 'exponential-order' kinetics classification in this context."}}}, {"id": "anking-pharmacokinetics-pharmacodynamics-206", "fuente": "anking", "tema": 31, "anki": "1472426537468", "q": "If the amount of enzyme in a reaction doubles, what happens to Vmax and Km?", "o": {"A": "Vmax doubles, while Km remains constant", "B": "Vmax remains constant, while Km doubles", "C": "Both Vmax and Km double", "D": "Both Vmax and Km remain constant"}, "r": "A", "e": {"correcta": "Doubling enzyme concentration doubles Vmax (since more enzyme can process more substrate per unit time), but Km, which reflects substrate affinity, is an intrinsic property of the enzyme-substrate interaction and remains unchanged.", "incorrectas": {"B": "Vmax, not Km, changes with enzyme concentration; Km is independent of enzyme amount.", "C": "Km does not change with enzyme concentration, so it does not double.", "D": "Vmax does change (doubles) when enzyme concentration doubles."}}}, {"id": "anking-pharmacokinetics-pharmacodynamics-207", "fuente": "anking", "tema": 31, "anki": "1472426541101", "q": "On a Lineweaver-Burk plot, which axis intercept represents -1/Km?", "o": {"A": "The Y-intercept", "B": "The X-intercept", "C": "The origin", "D": "The slope of the line"}, "r": "B", "e": {"correcta": "The X-intercept of a Lineweaver-Burk plot (a double-reciprocal plot of 1/v vs 1/[S]) corresponds to -1/Km.", "incorrectas": {"A": "The Y-intercept represents 1/Vmax, not -1/Km.", "C": "The origin is simply the point (0,0) and does not represent -1/Km.", "D": "The slope of the line represents Km/Vmax, not -1/Km itself."}}}, {"id": "anking-pharmacokinetics-pharmacodynamics-208", "fuente": "anking", "tema": 31, "anki": "1472426549510", "q": "On a Lineweaver-Burk plot, which axis intercept represents 1/Vmax?", "o": {"A": "The X-intercept", "B": "The Y-intercept", "C": "The slope", "D": "The midpoint of the line"}, "r": "B", "e": {"correcta": "The Y-intercept of a Lineweaver-Burk plot corresponds to 1/Vmax, since the plot graphs 1/v against 1/[S].", "incorrectas": {"A": "The X-intercept represents -1/Km, not 1/Vmax.", "C": "The slope of the Lineweaver-Burk line equals Km/Vmax, not 1/Vmax alone.", "D": "There is no standard 'midpoint' value used to represent 1/Vmax on this plot."}}}, {"id": "anking-pharmacokinetics-pharmacodynamics-209", "fuente": "anking", "tema": 31, "anki": "1472426560728", "q": "If the Y-intercept increases on a Lineweaver-Burk plot, what has happened to Vmax?", "o": {"A": "Vmax has increased", "B": "Vmax has decreased", "C": "Vmax has remained unchanged", "D": "Vmax has become negative"}, "r": "B", "e": {"correcta": "Since the Y-intercept equals 1/Vmax, an increase in the Y-intercept value means 1/Vmax has increased, which mathematically corresponds to a decrease in Vmax.", "incorrectas": {"A": "Because the Y-axis is an inverse (1/Vmax), a rising Y-intercept means Vmax is falling, not rising.", "C": "A change in the Y-intercept directly reflects a change in Vmax, so it does not remain unchanged.", "D": "Vmax is a physical rate and does not become negative; only the graphed value could be misinterpreted, but Vmax itself simply decreases."}}}, {"id": "anking-pharmacokinetics-pharmacodynamics-210", "fuente": "anking", "tema": 31, "anki": "1472426600174", "q": "When an irreversible competitive inhibitor is bound to an enzyme, which kinetic parameter changes and which remains the same?", "o": {"A": "Vmax changes, while Km remains the same", "B": "Km changes, while Vmax remains the same", "C": "Both Vmax and Km change", "D": "Neither Vmax nor Km changes"}, "r": "A", "e": {"correcta": "An irreversible competitive inhibitor permanently binds active enzyme, effectively reducing the amount of functional enzyme, which lowers Vmax, while the intrinsic affinity (Km) of the remaining active enzyme for substrate is unchanged.", "incorrectas": {"B": "Km reflects substrate affinity of the unbound active enzyme and does not change with irreversible inhibition; it is Vmax that changes.", "C": "Km is not altered by irreversible competitive inhibition; only Vmax changes.", "D": "Vmax does change because less functional enzyme is available to catalyze the reaction."}}}, {"id": "anking-pharmacokinetics-pharmacodynamics-211", "fuente": "anking", "tema": 31, "anki": "1472426609949", "q": "Do reversible competitive inhibitors structurally resemble the substrate of the enzyme they inhibit?", "o": {"A": "Yes, they resemble the substrate and compete for the active site", "B": "No, they bind an allosteric site distinct from the active site", "C": "No, they covalently modify the enzyme regardless of substrate shape", "D": "No, they only affect the enzyme's cofactor binding site"}, "r": "A", "e": {"correcta": "Reversible competitive inhibitors resemble the substrate structurally, allowing them to bind reversibly to the enzyme's active site and compete with the true substrate.", "incorrectas": {"B": "Binding to an allosteric site describes noncompetitive inhibition, not competitive inhibition.", "C": "Covalent, irreversible modification is a feature of irreversible inhibitors, and competitive inhibitors still resemble the substrate.", "D": "Competitive inhibitors act at the substrate-binding active site, not a separate cofactor site."}}}, {"id": "anking-pharmacokinetics-pharmacodynamics-212", "fuente": "anking", "tema": 31, "anki": "1472426614133", "q": "Do irreversible competitive inhibitors structurally resemble the substrate of the enzyme they inhibit?", "o": {"A": "No, they resemble cofactors rather than substrate", "B": "Yes, they resemble the substrate and bind the active site permanently", "C": "No, they act only at allosteric sites", "D": "No, resemblance to substrate is irrelevant to their mechanism"}, "r": "B", "e": {"correcta": "Irreversible competitive inhibitors resemble the substrate structurally (allowing them to bind the active site) but then form a permanent (often covalent) bond with the enzyme, unlike reversible competitive inhibitors.", "incorrectas": {"A": "Their resemblance is to the substrate, not to cofactors.", "C": "Competitive inhibitors, whether reversible or irreversible, act at the active site, not an allosteric site.", "D": "Substrate resemblance is essential to how competitive inhibitors, including irreversible ones, gain access to the active site."}}}, {"id": "anking-pharmacokinetics-pharmacodynamics-213", "fuente": "anking", "tema": 31, "anki": "1472426616871", "q": "Do noncompetitive inhibitors structurally resemble the substrate of the enzyme they inhibit?", "o": {"A": "Yes, they closely mimic the substrate's structure", "B": "No, they do not resemble the substrate and bind an allosteric site", "C": "Yes, but only in enzymes with multiple substrates", "D": "No, but they still compete directly for the active site"}, "r": "B", "e": {"correcta": "Noncompetitive inhibitors do not resemble the substrate; they bind to an allosteric site separate from the active site, changing enzyme conformation and reducing activity regardless of substrate concentration.", "incorrectas": {"A": "Resembling the substrate is characteristic of competitive inhibitors, not noncompetitive ones.", "C": "Noncompetitive inhibitors do not resemble substrate in any enzyme system, single- or multi-substrate.", "D": "Noncompetitive inhibitors bind an allosteric site, not the active site, so they do not compete directly with substrate."}}}, {"id": "anking-pharmacokinetics-pharmacodynamics-214", "fuente": "anking", "tema": 31, "anki": "1472426619514", "q": "Can the inhibitory effect of a reversible competitive inhibitor be overcome by increasing the substrate concentration [S]?", "o": {"A": "Yes, because it competes with substrate for the same active site", "B": "No, because it binds irreversibly to the enzyme", "C": "No, because it binds an allosteric site unaffected by substrate levels", "D": "No, because it permanently destroys enzyme activity"}, "r": "A", "e": {"correcta": "Because reversible competitive inhibitors compete with substrate for the same active site, increasing substrate concentration can outcompete the inhibitor and restore Vmax, overcoming the inhibition.", "incorrectas": {"B": "Irreversible binding describes irreversible inhibitors, not reversible competitive inhibitors, whose effect can be overcome by substrate.", "C": "Noncompetitive inhibitors act at an allosteric site and are not overcome by increasing substrate; this does not describe reversible competitive inhibitors.", "D": "Reversible competitive inhibitors do not permanently destroy enzyme activity; their effect is transient and substrate-competitive."}}}, {"id": "anking-reproductive-system-physiology-215", "fuente": "anking", "tema": 32, "anki": "1462933136208", "q": "During puberty and throughout the reproductive years, how do FSH levels compare to LH levels?", "o": {"A": "FSH levels are less than LH levels", "B": "FSH levels are greater than LH levels", "C": "FSH and LH levels are equal", "D": "FSH levels fluctuate independently of LH with no consistent relationship"}, "r": "A", "e": {"correcta": "Throughout puberty and the reproductive years, FSH levels remain lower than LH levels in both sexes.", "incorrectas": {"B": "This reverses the actual relationship; LH is higher than FSH, not the other way around.", "C": "FSH and LH are not equal during these periods; LH consistently exceeds FSH.", "D": "There is a consistent relationship (FSH < LH), not an unpredictable one."}}}, {"id": "anking-reproductive-system-physiology-216", "fuente": "anking", "tema": 32, "anki": "1462933237929", "q": "What is the term for the onset of menstrual cycles in females?", "o": {"A": "Menarche", "B": "Menopause", "C": "Thelarche", "D": "Adrenarche"}, "r": "A", "e": {"correcta": "Menarche is the medical term for the first menstrual cycle, marking the onset of menstruation in females.", "incorrectas": {"B": "Menopause refers to the permanent cessation of menstrual cycles, the opposite event.", "C": "Thelarche refers to the onset of breast development during puberty, not menstruation.", "D": "Adrenarche refers to the maturation of the adrenal glands leading to increased androgen production, not the onset of menses."}}}, {"id": "anking-reproductive-system-physiology-217", "fuente": "anking", "tema": 32, "anki": "1462935633329", "q": "Which set of changes occurs during spermiogenesis?", "o": {"A": "Loss of cytoplasmic contents, gain of an acrosomal cap, and development of flagella", "B": "Duplication of chromosomes, gain of a nuclear envelope, and loss of centrioles", "C": "Loss of the acrosomal cap, gain of cytoplasmic contents, and loss of flagella", "D": "Crossing over of homologous chromosomes and reduction of ploidy from diploid to haploid"}, "r": "A", "e": {"correcta": "Spermiogenesis is the final maturation of spermatids into spermatozoa, involving loss of excess cytoplasm, formation of the acrosomal cap (containing hydrolytic enzymes for fertilization), and development of the flagellum for motility.", "incorrectas": {"B": "Chromosome duplication and centriole loss are not features of spermiogenesis; this describes unrelated cellular events.", "C": "This reverses the actual changes—spermiogenesis involves gaining (not losing) the acrosomal cap and developing (not losing) flagella.", "D": "Crossing over and reduction to haploidy occur during meiosis, which precedes spermiogenesis (a purely morphological maturation process, not a division)."}}}, {"id": "anking-reproductive-system-physiology-218", "fuente": "anking", "tema": 32, "anki": "1462935652670", "q": "After which stage of spermatogenesis does the diploid cell become haploid?", "o": {"A": "Meiosis I (primary spermatocyte to secondary spermatocyte)", "B": "Mitosis of spermatogonia", "C": "Meiosis II (secondary spermatocyte to spermatid)", "D": "Spermiogenesis (spermatid to spermatozoon)"}, "r": "A", "e": {"correcta": "Meiosis I reduces the diploid primary spermatocyte to two haploid secondary spermatocytes, marking the transition from diploid to haploid.", "incorrectas": {"B": "Mitosis of spermatogonia produces more diploid spermatogonia and does not reduce ploidy.", "C": "Meiosis II further divides haploid secondary spermatocytes into haploid spermatids; the cells are already haploid before this step.", "D": "Spermiogenesis is a maturation process (not a division) that transforms haploid spermatids into spermatozoa; no ploidy change occurs here."}}}, {"id": "anking-reproductive-system-physiology-219", "fuente": "anking", "tema": 32, "anki": "1462935662591", "q": "Approximately how many days does one full cycle of spermatogenesis take?", "o": {"A": "64 days", "B": "28 days", "C": "9 months", "D": "120 days"}, "r": "A", "e": {"correcta": "A full cycle of spermatogenesis takes approximately 64 days, mediated by the temporal organization of the spermatogenic wave.", "incorrectas": {"B": "28 days corresponds to the average length of the female menstrual cycle, not spermatogenesis.", "C": "9 months is the duration of a human pregnancy, unrelated to the sperm production cycle.", "D": "120 days is closer to the lifespan of a circulating red blood cell, not the duration of spermatogenesis."}}}, {"id": "anking-reproductive-system-physiology-220", "fuente": "anking", "tema": 32, "anki": "1462935673020", "q": "Where in the testis does spermatogenesis occur?", "o": {"A": "Seminiferous tubules", "B": "Epididymis", "C": "Rete testis", "D": "Leydig cell interstitium"}, "r": "A", "e": {"correcta": "Spermatogenesis occurs within the seminiferous tubules, where Sertoli cells support developing germ cells.", "incorrectas": {"B": "The epididymis stores and matures sperm after they leave the testis; it is not the site of spermatogenesis.", "C": "The rete testis is a network of ducts that transports sperm from the seminiferous tubules toward the epididymis, not a site of sperm production.", "D": "The Leydig cell interstitium (between tubules) is the site of testosterone production, not spermatogenesis."}}}, {"id": "anking-reproductive-system-physiology-221", "fuente": "anking", "tema": 32, "anki": "1462979508082", "q": "In the first step of testosterone synthesis, which enzyme converts cholesterol to pregnenolone?", "o": {"A": "Cholesterol desmolase", "B": "5α-reductase", "C": "Aromatase", "D": "17β-hydroxysteroid dehydrogenase"}, "r": "A", "e": {"correcta": "Cholesterol desmolase (side-chain cleavage enzyme) converts cholesterol to pregnenolone, the rate-limiting first step of steroidogenesis; this enzyme is stimulated by LH in Leydig cells.", "incorrectas": {"B": "5α-reductase converts testosterone to dihydrotestosterone, a later step, not the conversion of cholesterol to pregnenolone.", "C": "Aromatase converts androgens to estrogens, unrelated to the cholesterol-to-pregnenolone step.", "D": "17β-hydroxysteroid dehydrogenase converts androstenedione to testosterone, a later step in the synthetic pathway."}}}, {"id": "anking-reproductive-system-physiology-222", "fuente": "anking", "tema": 32, "anki": "1462979580165", "q": "In tissues such as the prostate, which hormone serves as the active androgen instead of testosterone?", "o": {"A": "Dihydrotestosterone", "B": "Estradiol", "C": "Androstenedione", "D": "Dehydroepiandrosterone (DHEA)"}, "r": "A", "e": {"correcta": "In tissues containing 5α-reductase, such as the prostate, testosterone is converted to dihydrotestosterone (DHT), which is the biologically active androgen in those tissues.", "incorrectas": {"B": "Estradiol is an estrogen, not an androgen, and is not the active hormone in the prostate.", "C": "Androstenedione is a weak precursor androgen, not the active hormone produced locally in the prostate.", "D": "DHEA is a weak adrenal androgen precursor, not the potent active androgen formed in 5α-reductase-containing tissues."}}}, {"id": "anking-reproductive-system-physiology-223", "fuente": "anking", "tema": 32, "anki": "1462979590648", "q": "Which enzyme converts testosterone to dihydrotestosterone?", "o": {"A": "5α-reductase", "B": "Cholesterol desmolase", "C": "Aromatase", "D": "21-hydroxylase"}, "r": "A", "e": {"correcta": "5α-reductase converts testosterone into dihydrotestosterone (DHT), the more potent androgen in tissues like the prostate and skin.", "incorrectas": {"B": "Cholesterol desmolase catalyzes the first step of steroidogenesis (cholesterol to pregnenolone), not the testosterone-to-DHT conversion.", "C": "Aromatase converts testosterone to estradiol, not to dihydrotestosterone.", "D": "21-hydroxylase is involved in adrenal corticosteroid synthesis (cortisol and aldosterone pathways), not androgen activation."}}}, {"id": "anking-reproductive-system-physiology-224", "fuente": "anking", "tema": 32, "anki": "1462979605920", "q": "Along with albumin, what is the main plasma protein that binds the majority (about 98%) of circulating testosterone?", "o": {"A": "Sex steroid-binding globulin (SSBG)", "B": "Thyroxine-binding globulin (TBG)", "C": "Corticosteroid-binding globulin (CBG)", "D": "Alpha-fetoprotein"}, "r": "A", "e": {"correcta": "About 98% of circulating testosterone is bound to plasma proteins, primarily sex steroid-binding globulin (SSBG, also called SHBG) and albumin, leaving only a small free fraction biologically active.", "incorrectas": {"B": "TBG binds thyroid hormones (T3/T4), not testosterone.", "C": "CBG (transcortin) primarily binds cortisol and other corticosteroids, not testosterone.", "D": "Alpha-fetoprotein binds estrogens in the fetal circulation, not testosterone."}}}, {"id": "anking-reproductive-system-physiology-225", "fuente": "anking", "tema": 32, "anki": "1462981814472", "q": "Which two anterior pituitary hormones regulate spermatogenesis and testosterone secretion?", "o": {"A": "FSH and LH", "B": "ACTH and TSH", "C": "Prolactin and GH", "D": "Oxytocin and ADH"}, "r": "A", "e": {"correcta": "FSH acts on Sertoli cells to support spermatogenesis, while LH acts on Leydig cells to stimulate testosterone secretion; together these gonadotropins regulate male reproductive function.", "incorrectas": {"B": "ACTH stimulates adrenal cortisol production and TSH stimulates thyroid hormone release; neither directly regulates spermatogenesis or testicular testosterone secretion.", "C": "Prolactin and GH have other endocrine roles (lactation, growth) and are not the primary regulators of spermatogenesis/testosterone secretion.", "D": "Oxytocin and ADH are posterior pituitary hormones involved in labor/lactation and water balance, not gonadal regulation."}}}, {"id": "anking-reproductive-system-physiology-226", "fuente": "anking", "tema": 32, "anki": "1462981851888", "q": "Through what type of intratesticular mechanism does testosterone reinforce the spermatogenic effects of FSH on Sertoli cells?", "o": {"A": "Paracrine", "B": "Endocrine", "C": "Autocrine", "D": "Juxtacrine"}, "r": "A", "e": {"correcta": "Testosterone acts via a paracrine mechanism within the testis, diffusing from Leydig cells to nearby Sertoli cells to reinforce the spermatogenic effects of FSH, in addition to its separate endocrine actions on distant target tissues.", "incorrectas": {"B": "Endocrine signaling refers to testosterone's actions on distant extratesticular tissues, not its local action within the testis.", "C": "Autocrine signaling would mean Leydig cells act on themselves, not on neighboring Sertoli cells.", "D": "Juxtacrine signaling requires direct cell-to-cell contact, which is not the mechanism by which testosterone reinforces FSH effects."}}}, {"id": "anking-reproductive-system-physiology-227", "fuente": "anking", "tema": 32, "anki": "1462981895638", "q": "What effect does testosterone have on LH secretion?", "o": {"A": "Decreased", "B": "Increased", "C": "No effect", "D": "Increased only during puberty, then no effect thereafter"}, "r": "A", "e": {"correcta": "Testosterone exerts negative feedback on the hypothalamic-pituitary axis, decreasing LH secretion.", "incorrectas": {"B": "Testosterone suppresses, rather than increases, LH secretion via negative feedback.", "C": "Testosterone does have an effect on LH secretion—it decreases it through negative feedback, so 'no effect' is incorrect.", "D": "The negative feedback suppression of LH by testosterone persists throughout reproductive life, not only during puberty."}}}, {"id": "anking-reproductive-system-physiology-228", "fuente": "anking", "tema": 32, "anki": "1462981916104", "q": "Which hormone directly inhibits LH secretion in males?", "o": {"A": "Testosterone", "B": "Inhibin", "C": "Estrogen from the adrenal cortex", "D": "Prolactin"}, "r": "A", "e": {"correcta": "Testosterone directly inhibits LH secretion via negative feedback on the hypothalamus and anterior pituitary, in contrast to FSH, which is inhibited by inhibin (produced by Sertoli cells).", "incorrectas": {"B": "Inhibin selectively inhibits FSH secretion, not LH.", "C": "Adrenal estrogen is not the primary regulator of LH feedback in males; testosterone from the testes is.", "D": "Prolactin is not the physiologic feedback inhibitor of LH in normal male reproductive regulation (though pathologic hyperprolactinemia can suppress GnRH, it is not the direct feedback hormone described here)."}}}, {"id": "anking-reproductive-system-physiology-229", "fuente": "anking", "tema": 32, "anki": "1462981928631", "q": "Which androgen drives differentiation of the internal male genitalia (epididymis, vas deferens, seminal vesicles)?", "o": {"A": "Testosterone", "B": "Dihydrotestosterone", "C": "Estradiol", "D": "Anti-Müllerian hormone"}, "r": "A", "e": {"correcta": "Testosterone, secreted by the fetal Leydig cells, directly stimulates differentiation of the Wolffian duct structures into the epididymis, vas deferens, and seminal vesicles.", "incorrectas": {"B": "Dihydrotestosterone is responsible for differentiation of the external genitalia (penis, scrotum, prostate), not the internal Wolffian duct derivatives.", "C": "Estradiol is not responsible for male internal genital differentiation; it is an estrogen with a different developmental role.", "D": "Anti-Müllerian hormone (from Sertoli cells) causes regression of the Müllerian ducts; it does not drive differentiation of the Wolffian (internal genitalia) structures."}}}, {"id": "anking-reproductive-system-physiology-230", "fuente": "anking", "tema": 32, "anki": "1462981933728", "q": "Which androgen is responsible for the pubertal growth spurt, including growth of the penis, seminal vesicles, sperm, and muscle?", "o": {"A": "Testosterone", "B": "Dihydrotestosterone", "C": "Estrogen", "D": "Growth hormone alone, independent of androgens"}, "r": "A", "e": {"correcta": "Testosterone drives the pubertal growth spurt in males, promoting growth of the penis, seminal vesicles, spermatogenesis, and increased muscle mass.", "incorrectas": {"B": "Dihydrotestosterone is primarily responsible for external genitalia differentiation and secondary sexual hair/prostate growth, not the systemic pubertal growth spurt described here.", "C": "Estrogen (partly derived from testosterone) plays a role in epiphyseal closure, not primarily in driving the male pubertal growth spurt itself.", "D": "Growth hormone contributes to overall growth, but the pubertal growth spurt features described (penis, seminal vesicles, sperm, muscle) are specifically androgen (testosterone)-driven, not GH-independent."}}}, {"id": "anking-reproductive-system-physiology-231", "fuente": "anking", "tema": 32, "anki": "1462981937884", "q": "Which androgen is responsible for deepening of the voice during puberty?", "o": {"A": "Testosterone", "B": "Dihydrotestosterone", "C": "Estradiol", "D": "Progesterone"}, "r": "A", "e": {"correcta": "Testosterone causes laryngeal growth and thickening of the vocal cords, resulting in deepening of the voice during male puberty.", "incorrectas": {"B": "Dihydrotestosterone acts on hair follicles, skin, and external genitalia/prostate rather than being the hormone specifically responsible for voice deepening.", "C": "Estradiol is an estrogen and does not mediate the laryngeal changes causing voice deepening in males.", "D": "Progesterone has no role in male secondary sexual characteristics such as voice deepening."}}}, {"id": "anking-reproductive-system-physiology-232", "fuente": "anking", "tema": 32, "anki": "1462981942283", "q": "Which androgen is responsible for closure of the epiphyseal plates, ending pubertal growth?", "o": {"A": "Testosterone", "B": "Dihydrotestosterone", "C": "Follicle-stimulating hormone", "D": "Cortisol"}, "r": "A", "e": {"correcta": "Testosterone (via its peripheral conversion to estrogen) promotes closure of the epiphyseal growth plates, halting further pubertal skeletal growth.", "incorrectas": {"B": "Dihydrotestosterone is not converted to estrogen and is not responsible for epiphyseal plate closure.", "C": "FSH regulates spermatogenesis, not epiphyseal plate closure or bone maturation.", "D": "Cortisol is a glucocorticoid involved in stress and metabolic regulation, not the mediator of epiphyseal closure via androgen-to-estrogen conversion."}}}, {"id": "anking-reproductive-system-embryology-233", "fuente": "anking", "tema": 33, "anki": "1405188274504", "q": "On what day after fertilization is the zygote formed?", "o": {"A": "Day 1", "B": "Day 3", "C": "Day 5", "D": "Day 8"}, "r": "A", "e": {"correcta": "Fertilization itself creates the zygote, so the zygote is formed on day 1 post-fertilization.", "incorrectas": {"B": "Day 3 corresponds to formation of the morula, not the zygote.", "C": "Day 5 corresponds to formation of the blastocyst.", "D": "Day 8 corresponds to when hCG becomes detectable in serum, well after the zygote stage."}}}, {"id": "anking-reproductive-system-embryology-234", "fuente": "anking", "tema": 33, "anki": "1405189423019", "q": "On which days following fertilization is the morula formed?", "o": {"A": "Day 1", "B": "Days 3-4", "C": "Days 4-5", "D": "Days 6-10"}, "r": "B", "e": {"correcta": "The morula, a solid ball of cells, forms around days 3-4 after fertilization, following several rounds of cleavage of the zygote.", "incorrectas": {"A": "Day 1 is when the zygote itself forms, before cleavage produces the morula.", "C": "Days 4-5 corresponds to blastocyst formation, which follows the morula stage.", "D": "Days 6-10 corresponds to implantation, which occurs after the blastocyst stage."}}}, {"id": "anking-reproductive-system-embryology-235", "fuente": "anking", "tema": 33, "anki": "1405189436675", "q": "On which days following fertilization is the blastocyst formed?", "o": {"A": "Days 1-2", "B": "Days 3-4", "C": "Days 4-5", "D": "Days 6-10"}, "r": "C", "e": {"correcta": "The blastocyst, containing the inner cell mass and trophoblast, forms around days 4-5 after fertilization, following the morula stage.", "incorrectas": {"A": "Days 1-2 corresponds to the zygote stage, prior to compaction and cavitation.", "B": "Days 3-4 corresponds to formation of the morula, which precedes the blastocyst.", "D": "Days 6-10 corresponds to implantation, which follows blastocyst formation."}}}, {"id": "anking-reproductive-system-embryology-236", "fuente": "anking", "tema": 33, "anki": "1405189449032", "q": "On which days following fertilization does implantation typically occur?", "o": {"A": "Days 1-2", "B": "Days 3-4", "C": "Days 4-5", "D": "Days 6-10"}, "r": "D", "e": {"correcta": "Implantation of the blastocyst into the endometrium typically occurs on days 6-10 after fertilization (\"sticks at day 6 to 10\").", "incorrectas": {"A": "Days 1-2 corresponds to the zygote stage, far before implantation.", "B": "Days 3-4 corresponds to formation of the morula, before the blastocyst has even formed.", "C": "Days 4-5 corresponds to blastocyst formation, which precedes its implantation."}}}, {"id": "anking-reproductive-system-embryology-237", "fuente": "anking", "tema": 33, "anki": "1405189480591", "q": "During which week of gestation is the bilaminar disc (composed of epiblast and hypoblast) formed?", "o": {"A": "Week 1", "B": "Week 2", "C": "Week 3", "D": "Week 4"}, "r": "B", "e": {"correcta": "The bilaminar germ disc, consisting of the epiblast and hypoblast layers, forms during week 2 of gestation.", "incorrectas": {"A": "Week 1 involves fertilization, cleavage, and blastocyst formation/early implantation, not the bilaminar disc.", "C": "Week 3 is when gastrulation converts the bilaminar disc into the trilaminar disc.", "D": "Week 4 is well after the bilaminar disc has already been converted into three germ layers."}}}, {"id": "anking-reproductive-system-embryology-238", "fuente": "anking", "tema": 33, "anki": "1405189572077", "q": "During which week of gestation is the trilaminar disc formed?", "o": {"A": "Week 1", "B": "Week 2", "C": "Week 3", "D": "Week 4"}, "r": "C", "e": {"correcta": "The trilaminar germ disc, containing ectoderm, mesoderm, and endoderm, forms during week 3 via gastrulation.", "incorrectas": {"A": "Week 1 corresponds to fertilization through early implantation, long before germ layers exist.", "B": "Week 2 is when the bilaminar disc (epiblast/hypoblast) forms, prior to gastrulation.", "D": "Week 4 occurs after the trilaminar disc has already formed and organogenesis is beginning."}}}, {"id": "anking-reproductive-system-embryology-239", "fuente": "anking", "tema": 33, "anki": "1405189607684", "q": "During which week of gestation does gastrulation occur?", "o": {"A": "Week 1", "B": "Week 2", "C": "Week 3", "D": "Week 4"}, "r": "C", "e": {"correcta": "Gastrulation, which forms the trilaminar germ disc, occurs during week 3 of gestation (mnemonic: gasTRIlation).", "incorrectas": {"A": "Week 1 is dominated by fertilization and blastocyst formation, before gastrulation.", "B": "Week 2 is when the bilaminar disc forms, prior to gastrulation.", "D": "Week 4 comes after gastrulation, during early organ development (neurulation, limb bud formation)."}}}, {"id": "anking-reproductive-system-embryology-240", "fuente": "anking", "tema": 33, "anki": "1405189616150", "q": "During which week of gestation does the primitive streak appear?", "o": {"A": "Week 1", "B": "Week 2", "C": "Week 3", "D": "Week 4"}, "r": "C", "e": {"correcta": "The primitive streak, which establishes the embryonic axis and initiates gastrulation, appears during week 3 of gestation.", "incorrectas": {"A": "Week 1 is limited to fertilization and blastocyst formation, before the primitive streak forms.", "B": "Week 2 corresponds to bilaminar disc formation, prior to primitive streak appearance.", "D": "Week 4 is after the primitive streak has appeared and gastrulation has largely concluded."}}}, {"id": "anking-reproductive-system-embryology-241", "fuente": "anking", "tema": 33, "anki": "1405189647980", "q": "Typically, on what day post-fertilization do serum hCG levels first rise to detectable levels?", "o": {"A": "Day 1", "B": "Day 4", "C": "Day 8", "D": "Day 14"}, "r": "C", "e": {"correcta": "Serum hCG becomes detectable around day 8 post-fertilization (about &lt;5 IU/L), after the syncytiotrophoblast begins producing hCG following endometrial invasion around days 6-7.", "incorrectas": {"A": "Day 1 is the day of fertilization/zygote formation, long before trophoblast invasion or hCG production.", "B": "Day 4 corresponds to blastocyst formation, before implantation and hCG secretion begin.", "D": "Day 14 is roughly when urine hCG becomes detectable (once serum levels reach ~20 IU/L), not the earliest detectable serum level."}}}, {"id": "anking-reproductive-system-embryology-242", "fuente": "anking", "tema": 33, "anki": "1405189766131", "q": "The alveoli and epithelium of the trachea/bronchi are derived from which embryonic germ layer?", "o": {"A": "Ectoderm", "B": "Mesoderm", "C": "Endoderm", "D": "Neural crest"}, "r": "C", "e": {"correcta": "The epithelial lining of the respiratory tract, including alveoli and tracheobronchial epithelium, arises from the endoderm.", "incorrectas": {"A": "Ectoderm gives rise to skin epidermis and nervous system, not respiratory epithelium.", "B": "Mesoderm gives rise to the airway cartilage and connective tissue, not the epithelial lining itself.", "D": "Neural crest gives rise to structures like peripheral ganglia and melanocytes, not respiratory epithelium."}}}, {"id": "anking-reproductive-system-embryology-243", "fuente": "anking", "tema": 33, "anki": "1461871685256", "q": "Which placental hormone is structurally related to the TSH, FSH, and LH family, sharing an identical alpha chain and a unique beta chain?", "o": {"A": "Human placental lactogen (hPL)", "B": "Human chorionic gonadotropin (hCG)", "C": "Progesterone", "D": "Estriol"}, "r": "B", "e": {"correcta": "hCG is a glycoprotein hormone that shares an identical alpha subunit with TSH, FSH, and LH, while its beta subunit is unique and confers its specific biological activity.", "incorrectas": {"A": "Human placental lactogen is structurally related to growth hormone and prolactin, not the TSH/FSH/LH family.", "C": "Progesterone is a steroid hormone, not a glycoprotein hormone, and has no alpha/beta subunit structure.", "D": "Estriol is a steroid hormone produced by the placenta and fetal adrenal/liver, not a glycoprotein related to TSH/FSH/LH."}}}, {"id": "anking-reproductive-system-embryology-244", "fuente": "anking", "tema": 33, "anki": "1462930407913", "q": "Which category of sex is defined by the sex chromosomes, XY in males and XX in females?", "o": {"A": "Genetic sex", "B": "Gonadal sex", "C": "Phenotypic sex", "D": "Psychological sex"}, "r": "A", "e": {"correcta": "Genetic sex is determined by the sex chromosome complement, XY in males and XX in females.", "incorrectas": {"B": "Gonadal sex is defined by the presence of testes or ovaries, not chromosome complement.", "C": "Phenotypic sex refers to internal genital tract and external genitalia characteristics, not chromosomes.", "D": "Psychological sex/gender identity is not defined by chromosomal makeup and is a distinct concept from genetic sex."}}}, {"id": "anking-reproductive-system-embryology-245", "fuente": "anking", "tema": 33, "anki": "1462931923754", "q": "Which category of sex is defined by the presence of testes in males and ovaries in females?", "o": {"A": "Genetic sex", "B": "Gonadal sex", "C": "Phenotypic sex", "D": "Chromosomal sex"}, "r": "B", "e": {"correcta": "Gonadal sex is defined by the presence of testes (males) or ovaries (females), reflecting differentiation of the bipotential gonad.", "incorrectas": {"A": "Genetic sex refers to the sex chromosome complement (XY or XX), not the gonads themselves.", "C": "Phenotypic sex refers to the internal genital tract and external genitalia, not gonadal type.", "D": "Chromosomal sex is another term essentially synonymous with genetic sex, defined by chromosomes rather than gonads."}}}, {"id": "anking-reproductive-system-embryology-246", "fuente": "anking", "tema": 33, "anki": "1462931932797", "q": "Which category of sex is defined by the characteristics of the internal genital tract and external genitalia?", "o": {"A": "Genetic sex", "B": "Gonadal sex", "C": "Phenotypic sex", "D": "Chromosomal sex"}, "r": "C", "e": {"correcta": "Phenotypic sex is defined by the characteristics of the internal genital tract and external genitalia, which develop under the influence of gonadal hormones.", "incorrectas": {"A": "Genetic sex refers to the sex chromosome complement, not genital tract anatomy.", "B": "Gonadal sex refers to the presence of testes or ovaries, not the genital tract or external genitalia.", "D": "Chromosomal sex refers to the chromosome complement, not physical genital characteristics."}}}, {"id": "anking-reproductive-system-embryology-247", "fuente": "anking", "tema": 33, "anki": "1462931942401", "q": "At approximately which gestational weeks do the testes begin to develop in genetic males?", "o": {"A": "Weeks 2-3", "B": "Weeks 4-5", "C": "Weeks 6-7", "D": "Weeks 10-12"}, "r": "C", "e": {"correcta": "In genetic males, the testes begin to develop at approximately gestational weeks 6-7 under the influence of the SRY gene.", "incorrectas": {"A": "Weeks 2-3 correspond to bilaminar/trilaminar disc formation, well before gonadal differentiation.", "B": "Weeks 4-5 are too early; the bipotential gonad has not yet differentiated into testes at this stage.", "D": "Weeks 10-12 is later than testicular development actually begins, which starts at weeks 6-7."}}}, {"id": "anking-reproductive-system-embryology-248", "fuente": "anking", "tema": 33, "anki": "1462931966569", "q": "The male gonads (testes) are composed of which three cell types?", "o": {"A": "Germ cells, Sertoli cells, and Leydig cells", "B": "Germ cells, granulosa cells, and theca cells", "C": "Sertoli cells, theca cells, and Leydig cells", "D": "Granulosa cells, Leydig cells, and germ cells"}, "r": "A", "e": {"correcta": "The testes contain germ cells (which produce spermatogonia), Sertoli cells (epithelial, non-germ supporting cells), and Leydig cells (mesenchymal, endocrine/testosterone-producing cells).", "incorrectas": {"B": "Granulosa and theca cells are found in the female gonad (ovary), not the testis.", "C": "Theca cells are an ovarian cell type and are not present in the testis; the testis instead has germ cells.", "D": "Granulosa cells belong to the ovary, not the testis, which instead contains Sertoli cells."}}}, {"id": "anking-reproductive-system-embryology-249", "fuente": "anking", "tema": 33, "anki": "1462932018812", "q": "What do the germ cells of the male gonads (testes) produce?", "o": {"A": "Spermatogonia", "B": "Testosterone", "C": "Anti-Müllerian hormone", "D": "Inhibin"}, "r": "A", "e": {"correcta": "The germ cells of the testes give rise to spermatogonia, the precursor cells of sperm.", "incorrectas": {"B": "Testosterone is produced by Leydig cells, which are endocrine (mesenchymal-derived) cells, not germ cells.", "C": "Anti-Müllerian hormone is secreted by Sertoli cells, not germ cells.", "D": "Inhibin is also secreted by Sertoli cells, not by the germ cell line."}}}, {"id": "anking-reproductive-system-embryology-250", "fuente": "anking", "tema": 33, "anki": "1462932106262", "q": "The female gonads (ovaries) are composed of which three cell types?", "o": {"A": "Germ cells, Sertoli cells, and Leydig cells", "B": "Germ cells, granulosa cells, and theca cells", "C": "Granulosa cells, theca cells, and Leydig cells", "D": "Sertoli cells, granulosa cells, and germ cells"}, "r": "B", "e": {"correcta": "The ovaries are composed of germ cells (oogonia/oocytes), granulosa cells, and theca cells, which together support oocyte development and produce sex steroids.", "incorrectas": {"A": "Sertoli and Leydig cells are testicular cell types, not found in the ovary.", "C": "Leydig cells are a testicular endocrine cell type, not present in the ovary, which instead has germ cells.", "D": "Sertoli cells are found in the testis, not the ovary, which instead contains theca cells."}}}, {"id": "anking-reproductive-system-anatomy-251", "fuente": "anking", "tema": 34, "anki": "1462933248555", "q": "Approximately 80% of the adult testis by volume is composed of which structures, which produce sperm?", "o": {"A": "Seminiferous tubules", "B": "Leydig cell interstitium", "C": "Rete testis", "D": "Tunica albuginea"}, "r": "A", "e": {"correcta": "The seminiferous tubules make up about 80% of adult testicular volume and are the site of spermatogenesis.", "incorrectas": {"B": "The Leydig cell-containing interstitium makes up only about 20% of testicular volume and produces testosterone, not sperm.", "C": "The rete testis is a small network of ducts that transports sperm out of the testis; it is not the bulk of testicular tissue.", "D": "The tunica albuginea is the fibrous capsule surrounding the testis, not a sperm-producing structure."}}}, {"id": "anking-reproductive-system-anatomy-252", "fuente": "anking", "tema": 34, "anki": "1462935396323", "q": "The connective tissue interspersed among the seminiferous tubules (about 20% of testicular volume) contains which cells that synthesize and secrete testosterone?", "o": {"A": "Leydig cells", "B": "Sertoli cells", "C": "Spermatogonia", "D": "Theca cells"}, "r": "A", "e": {"correcta": "Leydig (interstitial) cells reside in the connective tissue between seminiferous tubules and produce testosterone in response to LH.", "incorrectas": {"B": "Sertoli cells line the seminiferous tubules and support spermatogenesis; they do not produce testosterone.", "C": "Spermatogonia are germ cells that give rise to sperm; they do not secrete testosterone.", "D": "Theca cells are found in the ovary and produce androgens as precursors for ovarian estrogen synthesis, not in the testis."}}}, {"id": "anking-reproductive-system-anatomy-253", "fuente": "anking", "tema": 34, "anki": "1462935407964", "q": "Which cells maintain the germ cell pool and give rise to primary spermatocytes?", "o": {"A": "Germ cells (spermatogonia)", "B": "Sertoli cells", "C": "Leydig cells", "D": "Myoid cells"}, "r": "A", "e": {"correcta": "Spermatogonia are the germ cells that undergo mitosis to maintain the germ pool and differentiate into primary spermatocytes, which then undergo meiosis.", "incorrectas": {"B": "Sertoli cells are somatic support cells that nourish developing germ cells but are not themselves germ cells.", "C": "Leydig cells are interstitial cells that secrete testosterone; they play no role in generating spermatocytes.", "D": "Peritubular myoid cells provide contractile support to the seminiferous tubules and are not germ cells."}}}, {"id": "anking-reproductive-system-anatomy-254", "fuente": "anking", "tema": 34, "anki": "1462935456368", "q": "Which cells support and nourish developing spermatogonia within the seminiferous tubules?", "o": {"A": "Sertoli cells", "B": "Leydig cells", "C": "Spermatogonia", "D": "Peritubular myoid cells"}, "r": "A", "e": {"correcta": "Sertoli cells form the blood-testis barrier and provide structural and nutritive support to developing germ cells; they also secrete androgen-binding protein to maintain local testosterone levels.", "incorrectas": {"B": "Leydig cells are located in the interstitium and produce testosterone, but they do not directly nourish germ cells.", "C": "Spermatogonia are the germ cells being supported, not the supporting cells.", "D": "Peritubular myoid cells provide contractile function around the tubule but are not the primary nourishing cell type."}}}, {"id": "anking-reproductive-system-anatomy-255", "fuente": "anking", "tema": 34, "anki": "1462935476863", "q": "What is the effect of increased scrotal/testicular temperature on sperm production?", "o": {"A": "Decreased sperm production", "B": "Increased sperm production", "C": "No effect on sperm production", "D": "Complete cessation of testosterone production"}, "r": "A", "e": {"correcta": "Elevated testicular temperature impairs spermatogenesis, which is why the testes are located in the scrotum to maintain a temperature below core body temperature.", "incorrectas": {"B": "Increased temperature impairs, rather than enhances, spermatogenesis.", "C": "Temperature does have an effect on sperm production, unlike its lack of effect on testosterone production.", "D": "Testosterone production by Leydig cells is largely unaffected by increased temperature, and cessation would be an overstatement in any case."}}}, {"id": "anking-reproductive-system-anatomy-256", "fuente": "anking", "tema": 34, "anki": "1462935491830", "q": "What is the effect of increased testicular temperature on inhibin B secretion by Sertoli cells?", "o": {"A": "Decreased inhibin B secretion", "B": "Increased inhibin B secretion", "C": "No effect on inhibin B secretion", "D": "Conversion of inhibin B to inhibin A"}, "r": "A", "e": {"correcta": "Increased temperature damages the seminiferous tubule environment and impairs Sertoli cell function, decreasing inhibin B secretion (paralleling decreased spermatogenesis).", "incorrectas": {"B": "Increased temperature impairs rather than enhances Sertoli cell secretory function.", "C": "Inhibin B secretion is in fact reduced by heat stress, unlike testosterone which is unaffected.", "D": "Inhibin B and inhibin A are distinct hormones produced by different tissues (testis vs. ovary/placenta); there is no such conversion."}}}, {"id": "anking-reproductive-system-anatomy-257", "fuente": "anking", "tema": 34, "anki": "1462935498037", "q": "Which cell type within the seminiferous tubule is primarily responsible for regulating spermatogenesis?", "o": {"A": "Sertoli cells", "B": "Leydig cells", "C": "Spermatogonia", "D": "Peritubular myoid cells"}, "r": "A", "e": {"correcta": "Sertoli cells regulate spermatogenesis by responding to FSH and testosterone, forming the blood-testis barrier, and providing the microenvironment necessary for germ cell maturation.", "incorrectas": {"B": "Leydig cells regulate testosterone production in response to LH but are located outside the tubule and do not directly regulate spermatogenesis within it.", "C": "Spermatogonia are the cells undergoing regulation (differentiation into sperm), not the regulators.", "D": "Peritubular myoid cells assist in propelling sperm and fluid but do not regulate the process of spermatogenesis itself."}}}, {"id": "anking-reproductive-system-anatomy-258", "fuente": "anking", "tema": 34, "anki": "1462935518262", "q": "What is the effect of increased testicular temperature on testosterone production by Leydig cells?", "o": {"A": "No effect", "B": "Marked increase", "C": "Marked decrease", "D": "Testosterone production stops entirely"}, "r": "A", "e": {"correcta": "Unlike spermatogenesis and inhibin B secretion, Leydig cell testosterone production is relatively insensitive to increased temperature.", "incorrectas": {"B": "Temperature elevation does not stimulate increased testosterone secretion.", "C": "Testosterone production, unlike sperm production and inhibin B secretion, is not significantly decreased by heat.", "D": "Testosterone synthesis continues; it does not cease with increased temperature."}}}, {"id": "anking-reproductive-system-anatomy-259", "fuente": "anking", "tema": 34, "anki": "1462935534563", "q": "Where are germ cells and Sertoli cells located in relation to the seminiferous tubules?", "o": {"A": "They form the lining (epithelium) of the tubules", "B": "They are present in the interstitium between tubules", "C": "They form the tunica vaginalis", "D": "They reside within the epididymis only"}, "r": "A", "e": {"correcta": "Germ cells and Sertoli cells together compose the seminiferous epithelium that lines the tubule, with germ cells progressing toward the lumen as they mature.", "incorrectas": {"B": "The interstitium (between tubules) is where Leydig cells reside, not germ or Sertoli cells.", "C": "The tunica vaginalis is a serous covering of the testis unrelated to the seminiferous epithelium.", "D": "The epididymis is a separate structure for sperm maturation and storage, distinct from the seminiferous tubules themselves."}}}, {"id": "anking-reproductive-system-anatomy-260", "fuente": "anking", "tema": 34, "anki": "1462935553838", "q": "Where are Leydig cells located in relation to the seminiferous tubules?", "o": {"A": "Present in the interstitium (connective tissue between tubules)", "B": "They form the lining of the tubules", "C": "Within the lumen of the tubules", "D": "In the epididymal duct epithelium"}, "r": "A", "e": {"correcta": "Leydig cells are interstitial cells located in the connective tissue between seminiferous tubules, where they secrete testosterone in response to LH.", "incorrectas": {"B": "The tubule lining (epithelium) is composed of Sertoli cells and germ cells, not Leydig cells.", "C": "The tubule lumen contains maturing sperm and fluid, not Leydig cells.", "D": "The epididymal duct epithelium is a distinct structure involved in sperm maturation and storage, not where Leydig cells reside."}}}, {"id": "anking-reproductive-system-anatomy-261", "fuente": "anking", "tema": 34, "anki": "1462935686800", "q": "What is the primary anatomic site for maturation and storage of sperm after leaving the testis?", "o": {"A": "Epididymis", "B": "Seminal vesicle", "C": "Vas deferens", "D": "Prostate gland"}, "r": "A", "e": {"correcta": "The epididymis is where sperm undergo functional maturation (acquiring motility) and are stored prior to ejaculation.", "incorrectas": {"B": "The seminal vesicles contribute fructose-rich alkaline fluid to semen but do not mature or store sperm.", "C": "The vas deferens is a conduit that transports mature sperm from the epididymis to the ejaculatory duct; it is not a storage/maturation site.", "D": "The prostate gland adds alkaline, citrate- and enzyme-rich secretions to semen but does not mature or store sperm."}}}, {"id": "anking-reproductive-system-anatomy-262", "fuente": "anking", "tema": 34, "anki": "1462935696447", "q": "The seminal vesicles secrete a fluid rich in citrate, prostaglandins, fibrinogen, and which nutritive sugar for ejaculated sperm?", "o": {"A": "Fructose", "B": "Glucose", "C": "Galactose", "D": "Sucrose"}, "r": "A", "e": {"correcta": "Seminal vesicle secretions are rich in fructose, which serves as the primary energy substrate for ejaculated sperm, along with citrate, prostaglandins, and fibrinogen.", "incorrectas": {"B": "Glucose is not the characteristic sugar of seminal vesicle fluid; fructose is the key nutritive sugar in semen.", "C": "Galactose is not a component of seminal vesicle secretions.", "D": "Sucrose is not secreted by the seminal vesicles as an energy source for sperm."}}}, {"id": "anking-reproductive-system-anatomy-263", "fuente": "anking", "tema": 34, "anki": "1462935732854", "q": "Which gland adds a slightly alkaline secretion rich in citrate, calcium, and enzymes to the sperm ejaculate?", "o": {"A": "Prostate gland", "B": "Seminal vesicle", "C": "Bulbourethral (Cowper's) gland", "D": "Epididymis"}, "r": "A", "e": {"correcta": "The prostate gland contributes an alkaline, citrate-, calcium-, and enzyme-rich secretion (including PSA) that helps liquefy semen and protect sperm.", "incorrectas": {"B": "The seminal vesicles contribute a fructose-, prostaglandin-, and fibrinogen-rich fluid, distinct from the prostate's citrate/calcium/enzyme secretion.", "C": "The bulbourethral glands secrete a clear mucus-like fluid that lubricates the urethra prior to ejaculation, not the citrate/calcium/enzyme fluid described.", "D": "The epididymis is a site of sperm maturation and storage, not a secretory gland contributing to seminal fluid composition."}}}, {"id": "anking-reproductive-system-anatomy-264", "fuente": "anking", "tema": 34, "anki": "1462935737696", "q": "Ejaculated sperm cannot immediately fertilize an ovum and must undergo which process within the female reproductive tract (taking about 4-6 hours)?", "o": {"A": "Capacitation", "B": "Acrosome reaction alone (without capacitation)", "C": "Meiosis II completion", "D": "Spermiogenesis"}, "r": "A", "e": {"correcta": "Capacitation is the process by which sperm gain the ability to fertilize an oocyte, involving changes in the sperm membrane and increased motility, and takes about 4-6 hours in the female reproductive tract.", "incorrectas": {"B": "The acrosome reaction occurs after capacitation and is triggered upon contact with the zona pellucida, not as an isolated first step.", "C": "Sperm complete meiosis II only after fertilization occurs (upon oocyte activation), not during transit in the female tract.", "D": "Spermiogenesis is the transformation of spermatids into mature spermatozoa in the testis, occurring before ejaculation, not in the female reproductive tract."}}}, {"id": "anking-reproductive-system-anatomy-265", "fuente": "anking", "tema": 34, "anki": "1462979034635", "q": "Leydig cells lack which two steroidogenic enzymes, explaining why they cannot synthesize glucocorticoids or mineralocorticoids?", "o": {"A": "21β-hydroxylase and 11β-hydroxylase", "B": "Aromatase and 5α-reductase", "C": "17α-hydroxylase and 3β-hydroxysteroid dehydrogenase", "D": "Desmolase and 17,20-lyase"}, "r": "A", "e": {"correcta": "Leydig cells lack 21β-hydroxylase and 11β-hydroxylase, the enzymes needed to convert progesterone/17-hydroxyprogesterone into mineralocorticoids and glucocorticoids, so they are restricted to producing androgens.", "incorrectas": {"B": "Leydig cells do possess 5α-reductase (converts testosterone to DHT) and some aromatase activity; these are not the enzymes that limit them to androgen synthesis.", "C": "Leydig cells do express 17α-hydroxylase and 3β-HSD, which are needed to produce testosterone; lacking these would abolish androgen synthesis entirely, not just glucocorticoid/mineralocorticoid production.", "D": "Desmolase (cholesterol side-chain cleavage) and 17,20-lyase are present and required in Leydig cells for testosterone synthesis; their absence would prevent all steroidogenesis, not selectively block cortisol/aldosterone synthesis."}}}, {"id": "anking-reproductive-system-anatomy-266", "fuente": "anking", "tema": 34, "anki": "1463080214517", "q": "The ovaries and testes primarily drain lymphatically into which lymph nodes?", "o": {"A": "Para-aortic (lumbar) lymph nodes", "B": "Deep inguinal lymph nodes", "C": "Internal iliac lymph nodes", "D": "External iliac lymph nodes"}, "r": "A", "e": {"correcta": "The ovaries and testes originate near the posterior abdominal wall and retain lymphatic drainage to the para-aortic (lumbar) lymph nodes, following the gonadal vessels.", "incorrectas": {"B": "Deep inguinal nodes drain the glans penis, clitoris, and penile urethra, not the gonads themselves.", "C": "Internal iliac nodes drain pelvic structures like the prostate, cervix, and inferior bladder, not the gonads.", "D": "External iliac nodes drain the body of the uterus and superior bladder, not the ovaries or testes."}}}, {"id": "anking-reproductive-system-anatomy-267", "fuente": "anking", "tema": 34, "anki": "1463080268843", "q": "The glans penis, clitoris, and penile urethra drain lymphatically into which lymph nodes?", "o": {"A": "Deep inguinal lymph nodes", "B": "Para-aortic lymph nodes", "C": "Internal iliac lymph nodes", "D": "External iliac lymph nodes"}, "r": "A", "e": {"correcta": "The glans penis, clitoris, and penile urethra drain into the deep inguinal nodes, which also receive afferents from the superficial inguinal nodes and deep lymphatic trunks along the femoral vessels.", "incorrectas": {"B": "Para-aortic nodes drain the gonads (ovaries/testes), not the glans penis or clitoris.", "C": "Internal iliac nodes drain deeper pelvic structures such as the prostate and cervix, not the glans/clitoris.", "D": "External iliac nodes drain structures like the uterine body and superior bladder, not the glans penis or clitoris."}}}, {"id": "anking-reproductive-system-anatomy-268", "fuente": "anking", "tema": 34, "anki": "1463080271705", "q": "The prostate, cervix, corpus cavernosum, inferior bladder, and proximal vagina drain lymphatically into which lymph nodes?", "o": {"A": "Internal iliac lymph nodes", "B": "External iliac lymph nodes", "C": "Para-aortic lymph nodes", "D": "Deep inguinal lymph nodes"}, "r": "A", "e": {"correcta": "The prostate, cervix, corpus cavernosum, inferior bladder, and proximal vagina drain into the internal iliac nodes, while the body of the uterus and superior bladder drain into the external iliac nodes.", "incorrectas": {"B": "External iliac nodes drain the body of the uterus and superior bladder, distinct from the structures listed here.", "C": "Para-aortic nodes drain the gonads (ovaries/testes), not these pelvic organs.", "D": "Deep inguinal nodes drain the glans penis, clitoris, and penile urethra, not the prostate or proximal vagina."}}}, {"id": "anking-neurology-special-senses-anatomy-physiology-269", "fuente": "anking", "tema": 35, "anki": "1474511979294", "q": "At what vertebral level does the common carotid artery typically bifurcate into internal and external carotid arteries?", "o": {"A": "C2", "B": "C4", "C": "C6", "D": "T1"}, "r": "B", "e": {"correcta": "The common carotid artery bifurcates at the level of C4, corresponding roughly to the upper border of the thyroid cartilage; this landmark is important for carotid ultrasound and surgical exposure.", "incorrectas": {"A": "C2 is too high and does not correspond to the typical bifurcation point.", "C": "C6 corresponds instead to the level of the cricoid cartilage, not the carotid bifurcation.", "D": "T1 is well below the neck region where the bifurcation actually occurs."}}}, {"id": "anking-neurology-special-senses-anatomy-physiology-270", "fuente": "anking", "tema": 35, "anki": "1479425811082", "q": "In terms of cell cycle classification (permanent, stable, or labile), how are neurons categorized?", "o": {"A": "Labile cells that divide continuously", "B": "Stable cells that can re-enter the cell cycle when needed", "C": "Permanent cells that do not divide in adulthood", "D": "Cells that undergo rapid turnover like epithelium"}, "r": "C", "e": {"correcta": "Neurons are permanent cells, meaning they remain in G0 and do not divide in adulthood; this is why CNS neuronal injury is generally irreversible.", "incorrectas": {"A": "Labile cells (e.g., skin, gut epithelium, bone marrow) divide continuously, unlike neurons.", "B": "Stable cells (e.g., hepatocytes) are quiescent but can re-enter the cell cycle upon stimulus, which neurons cannot do.", "D": "Rapid turnover describes labile tissues, not permanent tissues like neurons."}}}, {"id": "anking-neurology-special-senses-anatomy-physiology-271", "fuente": "anking", "tema": 35, "anki": "1479430330034", "q": "Which structure of a neuron receives synaptic input from the axons of other neurons?", "o": {"A": "Axon hillock", "B": "Dendrites", "C": "Axon terminal", "D": "Cell body only"}, "r": "B", "e": {"correcta": "Dendrites are specialized to receive input from other neurons' axons; they often contain spines that dramatically increase surface area for synaptic contacts.", "incorrectas": {"A": "The axon hillock is the site of action potential initiation, not the primary site of synaptic input.", "C": "The axon terminal is the output structure that releases neurotransmitter, not a receiving structure.", "D": "While the cell body can receive some synapses, the dendrites are the principal receiving structures."}}}, {"id": "anking-neurology-special-senses-anatomy-physiology-272", "fuente": "anking", "tema": 35, "anki": "1479430341680", "q": "Which part of the neuron contains organelles such as the Golgi apparatus and endoplasmic reticulum?", "o": {"A": "Axon", "B": "Dendrite spine", "C": "Cell body (soma)", "D": "Node of Ranvier"}, "r": "C", "e": {"correcta": "The cell body (soma) houses the nucleus and major organelles like the Golgi apparatus and rough ER (Nissl substance), supporting protein synthesis for the neuron.", "incorrectas": {"A": "The axon is largely devoid of these organelles and relies on axonal transport from the soma.", "B": "Dendritic spines are specialized postsynaptic sites, not the main organelle-containing compartment.", "D": "The node of Ranvier is a gap in myelin along the axon, not an organelle-rich region."}}}, {"id": "anking-neurology-special-senses-anatomy-physiology-273", "fuente": "anking", "tema": 35, "anki": "1479430346525", "q": "Which structure of a neuron sends electrical output (impulses) to other neurons?", "o": {"A": "Dendrites", "B": "Axons", "C": "Cell body", "D": "Nucleus"}, "r": "B", "e": {"correcta": "Axons conduct action potentials away from the soma toward target neurons, muscles, or glands, functioning as the neuron's output structure.", "incorrectas": {"A": "Dendrites are input structures, receiving signals rather than sending them.", "C": "The cell body integrates signals but is not the primary conducting/output structure.", "D": "The nucleus contains genetic material and is not involved in impulse transmission."}}}, {"id": "anking-neurology-special-senses-anatomy-physiology-274", "fuente": "anking", "tema": 35, "anki": "1479430351568", "q": "The proximal part of an axon is marked by a tapered extension of the cell body lacking Nissl substance. What is this structure called?", "o": {"A": "Axon hillock", "B": "Synaptic bouton", "C": "Node of Ranvier", "D": "Dendritic spine"}, "r": "A", "e": {"correcta": "The axon hillock is the tapered region connecting the soma to the axon; it lacks Nissl substance and is the site where action potentials are typically initiated due to high density of voltage-gated sodium channels.", "incorrectas": {"B": "A synaptic bouton is the axon terminal's ending that forms synapses, not the proximal axon region.", "C": "Nodes of Ranvier are gaps between myelin segments along the axon's length, not at its origin.", "D": "Dendritic spines are on dendrites, not related to the axon's origin from the soma."}}}, {"id": "anking-neurology-special-senses-anatomy-physiology-275", "fuente": "anking", "tema": 35, "anki": "1479430397471", "q": "Which neuronal structure contains synaptic vesicles that store and release neurotransmitter into the synapse?", "o": {"A": "Dendrite", "B": "Axon hillock", "C": "Axon (nerve) terminal", "D": "Soma"}, "r": "C", "e": {"correcta": "The axon (nerve) terminal contains synaptic vesicles filled with neurotransmitter, which are released via exocytosis upon arrival of an action potential to transmit the signal across the synapse.", "incorrectas": {"A": "Dendrites are primarily postsynaptic, receiving neurotransmitter rather than storing/releasing it.", "B": "The axon hillock initiates action potentials but does not store synaptic vesicles.", "D": "The soma is the cell body responsible for protein synthesis and metabolic functions, not neurotransmitter release."}}}, {"id": "anking-neurology-special-senses-anatomy-physiology-276", "fuente": "anking", "tema": 35, "anki": "1479430428553", "q": "Approximately how many axons can a single oligodendrocyte myelinate in the CNS?", "o": {"A": "Only one axon", "B": "Many axons (up to ~30)", "C": "None; oligodendrocytes myelinate only PNS axons", "D": "Exactly two axons"}, "r": "B", "e": {"correcta": "Each oligodendrocyte can myelinate multiple CNS axons, roughly up to 30, extending processes to wrap segments of several different axons simultaneously.", "incorrectas": {"A": "Myelinating only one axon describes Schwann cells in the PNS, not oligodendrocytes.", "C": "Oligodendrocytes are specifically the myelinating glial cells of the CNS.", "D": "Two axons understates the actual capacity of oligodendrocytes, which myelinate many more."}}}, {"id": "anking-neurology-special-senses-anatomy-physiology-277", "fuente": "anking", "tema": 35, "anki": "1479430443097", "q": "Oligodendrocytes classically have what histological appearance?", "o": {"A": "Fried egg appearance", "B": "Signet ring appearance", "C": "Owl's eye appearance", "D": "Fried onion appearance"}, "r": "A", "e": {"correcta": "Oligodendrocytes classically show a 'fried egg' appearance on histology, with a round nucleus surrounded by a clear halo of cytoplasm due to processing artifact.", "incorrectas": {"B": "Signet ring appearance is classically associated with signet ring cell carcinoma (e.g., diffuse gastric cancer), not oligodendrocytes.", "C": "Owl's eye appearance describes CMV-infected cells (intranuclear inclusions), not oligodendrocytes.", "D": "Fried onion appearance describes onion-skin lesions seen in some vascular/perineural pathology, not oligodendrocyte morphology."}}}, {"id": "anking-neurology-special-senses-anatomy-physiology-278", "fuente": "anking", "tema": 35, "anki": "1479430459987", "q": "Which glial cell type acts as a glycogen fuel reserve buffer in the CNS?", "o": {"A": "Microglia", "B": "Oligodendrocytes", "C": "Astrocytes", "D": "Ependymal cells"}, "r": "C", "e": {"correcta": "Astrocytes store glycogen and can mobilize it to buffer neuronal energy demands, in addition to their many other homeostatic roles in the CNS.", "incorrectas": {"A": "Microglia are the resident CNS phagocytes/immune cells and are not primarily glycogen reservoirs.", "B": "Oligodendrocytes are responsible for CNS myelination, not glycogen storage.", "D": "Ependymal cells line the ventricles and produce CSF; they do not serve as glycogen buffers."}}}, {"id": "anking-neurology-special-senses-anatomy-physiology-279", "fuente": "anking", "tema": 35, "anki": "1479430470116", "q": "Which glial cells help maintain the blood-brain barrier via their foot processes?", "o": {"A": "Microglia", "B": "Astrocytes", "C": "Schwann cells", "D": "Ependymal cells"}, "r": "B", "e": {"correcta": "Astrocytes extend foot processes that surround CNS capillaries, contributing structurally and functionally to maintenance of the blood-brain barrier.", "incorrectas": {"A": "Microglia serve immune surveillance functions in the CNS but do not form the foot processes maintaining the BBB.", "C": "Schwann cells myelinate PNS axons and are not involved in the CNS blood-brain barrier.", "D": "Ependymal cells line the ventricular system and are involved in CSF production, not BBB maintenance."}}}, {"id": "anking-neurology-special-senses-anatomy-physiology-280", "fuente": "anking", "tema": 35, "anki": "1479430475147", "q": "Which glial cells are capable of removing excess neurotransmitters (e.g., glutamate and GABA) from the synapse?", "o": {"A": "Astrocytes", "B": "Oligodendrocytes", "C": "Microglia", "D": "Schwann cells"}, "r": "A", "e": {"correcta": "Astrocytes reuptake and metabolize excess neurotransmitters like glutamate and GABA, converting glutamate to glutamine which is shuttled back to neurons; this process is disrupted in hyperammonemia.", "incorrectas": {"B": "Oligodendrocytes function in myelination, not neurotransmitter clearance.", "C": "Microglia are phagocytic immune cells of the CNS and are not primarily responsible for neurotransmitter reuptake.", "D": "Schwann cells myelinate peripheral axons and do not perform CNS neurotransmitter clearance."}}}, {"id": "anking-neurology-special-senses-anatomy-physiology-281", "fuente": "anking", "tema": 35, "anki": "1479430479241", "q": "Which protein is commonly used as a histological marker for astrocytes?", "o": {"A": "S-100", "B": "Synaptophysin", "C": "GFAP (glial fibrillary acidic protein)", "D": "Neurofilament protein"}, "r": "C", "e": {"correcta": "GFAP (glial fibrillary acidic protein) is an intermediate filament protein used as an immunohistochemical marker specific for astrocytes.", "incorrectas": {"A": "S-100 is a marker used for Schwann cells, melanocytes, and other neural crest-derived cells, not specifically astrocytes.", "B": "Synaptophysin is a marker of neuroendocrine differentiation and synaptic vesicles, not astrocytes.", "D": "Neurofilament protein is a marker of neurons/axons, not glial astrocytes."}}}, {"id": "anking-neurology-special-senses-anatomy-physiology-282", "fuente": "anking", "tema": 35, "anki": "1479430500748", "q": "How many axons can a single Schwann cell myelinate in the peripheral nervous system?", "o": {"A": "One axon", "B": "Up to 30 axons", "C": "Ten axons", "D": "None; Schwann cells only support unmyelinated fibers"}, "r": "A", "e": {"correcta": "Each Schwann cell myelinates only one internodal segment of a single axon in the PNS, in contrast to oligodendrocytes which myelinate multiple CNS axons.", "incorrectas": {"B": "Myelinating up to 30 axons describes oligodendrocytes in the CNS, not Schwann cells.", "C": "Ten axons is an incorrect number; Schwann cells myelinate only one axon segment each.", "D": "Schwann cells do myelinate axons (one per cell); some Schwann cells also ensheath unmyelinated fibers, but the statement that they never myelinate is false."}}}, {"id": "anking-neurology-special-senses-anatomy-physiology-283", "fuente": "anking", "tema": 35, "anki": "1479430512463", "q": "At the nodes of Ranvier, there is a high concentration of which ion channels, enabling saltatory conduction?", "o": {"A": "Ca2+ channels", "B": "K+ channels", "C": "Cl- channels", "D": "Na+ channels"}, "r": "D", "e": {"correcta": "Nodes of Ranvier have a high density of voltage-gated Na+ channels, which regenerate the action potential at each node, allowing saltatory conduction and increased conduction velocity.", "incorrectas": {"A": "Ca2+ channels are important at presynaptic terminals for neurotransmitter release, not concentrated at nodes of Ranvier.", "B": "K+ channels contribute to repolarization but are not the defining high-density channel at nodes of Ranvier.", "C": "Cl- channels are not characteristically concentrated at the nodes of Ranvier."}}}, {"id": "anking-neurology-special-senses-anatomy-physiology-284", "fuente": "anking", "tema": 35, "anki": "1479430516390", "q": "How does myelination of an axon affect its length (space) constant?", "o": {"A": "It increases the space constant", "B": "It decreases the space constant", "C": "It has no effect on the space constant", "D": "It abolishes the space constant entirely"}, "r": "A", "e": {"correcta": "Myelin insulates the axon membrane, reducing current leakage and thereby increasing the space (length) constant, allowing electrical signals to travel farther without decaying before reaching the next node.", "incorrectas": {"B": "A decreased space constant would impair signal propagation and actually occurs with demyelination (e.g., multiple sclerosis), the opposite of myelination's effect.", "C": "Myelination has a clear and significant effect on the space constant, not a neutral one.", "D": "Myelin does not abolish the space constant; it enhances it, allowing longer-distance passive current spread."}}}, {"id": "anking-neurology-special-senses-anatomy-physiology-285", "fuente": "anking", "tema": 35, "anki": "1479430523319", "q": "How does myelination of an axon affect the membrane time constant?", "o": {"A": "It increases the time constant", "B": "It decreases the time constant", "C": "It has no effect on the time constant", "D": "It makes the time constant infinite"}, "r": "B", "e": {"correcta": "Myelin decreases membrane capacitance and increases membrane resistance, which together decrease the time constant, allowing faster depolarization of the membrane in response to current.", "incorrectas": {"A": "An increased time constant would slow membrane depolarization, which is the opposite of myelin's actual effect.", "C": "Myelination clearly alters the time constant by changing capacitance and resistance properties of the membrane.", "D": "Myelin does not make the time constant infinite; it reduces it to a smaller, finite value."}}}, {"id": "anking-neurology-special-senses-anatomy-physiology-286", "fuente": "anking", "tema": 35, "anki": "1479430529292", "q": "A decreased membrane time constant results in what change in conduction velocity?", "o": {"A": "Increased conduction velocity", "B": "Decreased conduction velocity", "C": "No change in conduction velocity", "D": "Conduction velocity becomes unpredictable"}, "r": "A", "e": {"correcta": "A decreased time constant means the membrane depolarizes more quickly, which increases conduction velocity; this is achieved through myelination, and conduction velocity decreases when myelin is lost, as in multiple sclerosis.", "incorrectas": {"B": "Decreased conduction velocity would correspond to an increased (not decreased) time constant, or to demyelination.", "C": "The time constant directly affects how quickly the membrane responds, so a change in it does affect conduction velocity.", "D": "The relationship between time constant and conduction velocity is well-defined and predictable, not random."}}}, {"id": "anking-neurology-special-senses-pharmacology-287", "fuente": "anking", "tema": 36, "anki": "1473375617796", "q": "Which local anesthetic is known to cause methemoglobinemia when used in toxic doses?", "o": {"A": "Benzocaine", "B": "Lidocaine", "C": "Bupivacaine", "D": "Procaine"}, "r": "A", "e": {"correcta": "Benzocaine is a local anesthetic classically associated with methemoglobinemia, especially with topical overuse or in infants, due to oxidation of hemoglobin iron.", "incorrectas": {"B": "Lidocaine is an amide anesthetic that is not classically linked to methemoglobinemia at typical toxic doses.", "C": "Bupivacaine toxicity is notorious for cardiotoxicity, not methemoglobinemia.", "D": "Procaine is an ester anesthetic more associated with allergic reactions via PABA metabolites than methemoglobinemia."}}}, {"id": "anking-neurology-special-senses-pharmacology-288", "fuente": "anking", "tema": 36, "anki": "1484768412769", "q": "Compared to long-acting benzodiazepines, short-acting benzodiazepines have a __ potential for addiction.", "o": {"A": "Higher", "B": "Lower", "C": "Equal", "D": "Absent"}, "r": "A", "e": {"correcta": "Short-acting benzodiazepines have a higher addiction potential because their rapid onset and offset produce more pronounced withdrawal and reinforcing effects.", "incorrectas": {"B": "Long-acting agents, not short-acting, have lower addiction potential due to gradual elimination.", "C": "Addiction potential is not equal; it clearly differs based on duration of action.", "D": "All benzodiazepines carry some addiction potential; it is not absent in short-acting agents."}}}, {"id": "anking-neurology-special-senses-pharmacology-289", "fuente": "anking", "tema": 36, "anki": "1484768416828", "q": "Benzodiazepines are primarily metabolized by which organ?", "o": {"A": "Liver", "B": "Kidney", "C": "Lung", "D": "Spleen"}, "r": "A", "e": {"correcta": "Benzodiazepines undergo hepatic metabolism; long-acting agents form active metabolites in the liver while short-acting ones do not.", "incorrectas": {"B": "The kidney primarily excretes metabolites rather than metabolizing benzodiazepines.", "C": "The lung is not a significant site of benzodiazepine metabolism.", "D": "The spleen plays no meaningful role in drug metabolism."}}}, {"id": "anking-neurology-special-senses-pharmacology-290", "fuente": "anking", "tema": 36, "anki": "1484768423971", "q": "Which class of benzodiazepines is typically metabolized by the liver into active metabolites?", "o": {"A": "Long-acting", "B": "Short-acting", "C": "Ultra-short-acting", "D": "Non-benzodiazepine hypnotics"}, "r": "A", "e": {"correcta": "Long-acting benzodiazepines are hepatically converted into active metabolites, prolonging their clinical effects.", "incorrectas": {"B": "Short-acting benzodiazepines generally lack clinically significant active metabolites.", "C": "Ultra-short-acting agents are eliminated too quickly to accumulate active metabolites.", "D": "Non-benzodiazepine hypnotics (Z-drugs) are a distinct drug class not defined by this metabolic pattern."}}}, {"id": "anking-neurology-special-senses-pharmacology-291", "fuente": "anking", "tema": 36, "anki": "1484768430296", "q": "Benzodiazepines exert their effects by binding to an allosteric site on which receptor?", "o": {"A": "GABAA receptor", "B": "NMDA receptor", "C": "GABAB receptor", "D": "Glycine receptor"}, "r": "A", "e": {"correcta": "Benzodiazepines bind an allosteric site on the GABAA receptor, distinct from the GABA binding site, enhancing chloride channel opening.", "incorrectas": {"B": "NMDA receptors are glutamate receptors targeted by drugs like ketamine, not benzodiazepines.", "C": "GABAB receptors are metabotropic and targeted by baclofen, not benzodiazepines.", "D": "Glycine receptors are inhibitory chloride channels but are not the benzodiazepine binding site."}}}, {"id": "anking-neurology-special-senses-pharmacology-292", "fuente": "anking", "tema": 36, "anki": "1484768435794", "q": "Benzodiazepines __ the action of GABAA receptors.", "o": {"A": "Enhance", "B": "Inhibit", "C": "Have no effect on", "D": "Reverse"}, "r": "A", "e": {"correcta": "Benzodiazepines enhance GABAA receptor activity by increasing the frequency of chloride channel opening in response to GABA.", "incorrectas": {"B": "Benzodiazepines potentiate rather than inhibit GABAA receptor function.", "C": "Benzodiazepines have a well-established potentiating effect on GABAA receptors.", "D": "Benzodiazepines do not reverse GABA's inhibitory action; they augment it."}}}, {"id": "anking-neurology-special-senses-pharmacology-293", "fuente": "anking", "tema": 36, "anki": "1484768461819", "q": "The GABAA receptor is a ligand-gated channel for which ion?", "o": {"A": "Chloride (Cl-)", "B": "Sodium (Na+)", "C": "Potassium (K+)", "D": "Calcium (Ca2+)"}, "r": "A", "e": {"correcta": "GABAA receptors are ligand-gated chloride channels; opening allows Cl- influx, hyperpolarizing the neuron.", "incorrectas": {"B": "Sodium channels are involved in depolarization (e.g., action potentials), not GABAA receptor function.", "C": "Potassium channels contribute to resting membrane potential but are not the GABAA receptor's conducted ion.", "D": "Calcium channels mediate neurotransmitter release, not the direct ionic conductance of GABAA receptors."}}}, {"id": "anking-neurology-special-senses-pharmacology-294", "fuente": "anking", "tema": 36, "anki": "1484768489461", "q": "Non-specific symptoms of alcohol withdrawal, such as anxiety, insomnia, and tremors, typically occur within what time frame after last drink?", "o": {"A": "3-36 hours", "B": "48-96 hours", "C": "1-2 hours", "D": "5-7 days"}, "r": "A", "e": {"correcta": "Mild/non-specific alcohol withdrawal symptoms (anxiety, insomnia, tremor) classically begin around 3-36 hours after the last drink.", "incorrectas": {"B": "48-96 hours is more characteristic of the delirium tremens window, not early non-specific symptoms.", "C": "1-2 hours is too early; withdrawal symptoms take longer to manifest as blood alcohol falls.", "D": "5-7 days is far beyond the typical withdrawal symptom timeline."}}}, {"id": "anking-neurology-special-senses-pharmacology-295", "fuente": "anking", "tema": 36, "anki": "1484768537325", "q": "Which route of benzodiazepine administration is useful for management of alcohol withdrawal, seizures, and anesthesia?", "o": {"A": "IV", "B": "Oral", "C": "Intramuscular only", "D": "Transdermal"}, "r": "A", "e": {"correcta": "IV benzodiazepines allow rapid onset needed for acute management of alcohol withdrawal, seizures, and induction/maintenance of anesthesia.", "incorrectas": {"B": "Oral administration has a slower onset, less suited for acute emergencies like status epilepticus.", "C": "Intramuscular administration has variable and slower absorption compared to IV in emergencies.", "D": "Transdermal delivery is not a standard route for benzodiazepines in these acute settings."}}}, {"id": "anking-neurology-special-senses-pharmacology-296", "fuente": "anking", "tema": 36, "anki": "1484768546903", "q": "Which type of generalized seizure is acutely treated with benzodiazepines (e.g., midazolam, lorazepam)?", "o": {"A": "Status epilepticus", "B": "Absence seizure", "C": "Myoclonic seizure", "D": "Simple partial seizure"}, "r": "A", "e": {"correcta": "Status epilepticus is a medical emergency acutely treated with IV benzodiazepines like lorazepam or midazolam to terminate prolonged seizure activity.", "incorrectas": {"B": "Absence seizures are typically managed with ethosuximide, not acute benzodiazepine treatment.", "C": "Myoclonic seizures are usually treated with valproate, not acute benzodiazepines as first-line.", "D": "Simple partial seizures are not the classic acute indication for benzodiazepine treatment (that is status epilepticus)."}}}, {"id": "anking-neurology-special-senses-pharmacology-297", "fuente": "anking", "tema": 36, "anki": "1484768551456", "q": "IV benzodiazepines can be used to produce muscle relaxation and amnesia in what clinical context?", "o": {"A": "General anesthesia", "B": "Local anesthesia", "C": "Regional nerve block", "D": "Epidural analgesia"}, "r": "A", "e": {"correcta": "IV benzodiazepines contribute to general anesthesia by providing muscle relaxation and amnesia as adjuncts to other anesthetic agents.", "incorrectas": {"B": "Local anesthesia involves agents like lidocaine acting on peripheral nerves, not systemic benzodiazepine effects.", "C": "Regional nerve blocks use local anesthetics injected near nerves, not benzodiazepines for amnesia.", "D": "Epidural analgesia typically uses local anesthetics/opioids, not benzodiazepines for muscle relaxation/amnesia."}}}, {"id": "anking-neurology-special-senses-pharmacology-298", "fuente": "anking", "tema": 36, "anki": "1484768555637", "q": "IV benzodiazepines like midazolam may be used to create what state for minor procedures such as colonoscopy or endoscopy?", "o": {"A": "Conscious sedation", "B": "General anesthesia", "C": "Spinal anesthesia", "D": "Deep coma"}, "r": "A", "e": {"correcta": "Midazolam is commonly used to produce conscious sedation, allowing patients to tolerate minor procedures while maintaining some responsiveness, often with adjunct gaseous anesthetics or narcotics.", "incorrectas": {"B": "General anesthesia involves full unconsciousness, which is not required or intended for these minor procedures.", "C": "Spinal anesthesia is a regional technique using injected anesthetics, unrelated to IV benzodiazepine sedation.", "D": "Deep coma is not the intended or safe target state for procedural sedation."}}}, {"id": "anking-neurology-special-senses-pharmacology-299", "fuente": "anking", "tema": 36, "anki": "1484768559674", "q": "Benzodiazepines may be used as a hypnotic to treat which condition, though they are not first-line due to physical dependence risk?", "o": {"A": "Insomnia", "B": "Narcolepsy", "C": "Restless legs syndrome", "D": "Sleep apnea"}, "r": "A", "e": {"correcta": "Benzodiazepines can treat insomnia by promoting sleep onset, but are not first-line therapy because of the risk of tolerance and physical dependence.", "incorrectas": {"B": "Narcolepsy is treated with stimulants like modafinil, not benzodiazepines as hypnotics.", "C": "Restless legs syndrome is managed with dopamine agonists or iron repletion, not benzodiazepine hypnotic use.", "D": "Sleep apnea requires treatments like CPAP; benzodiazepines can worsen respiratory depression in this condition."}}}, {"id": "anking-neurology-special-senses-pharmacology-300", "fuente": "anking", "tema": 36, "anki": "1484768563667", "q": "Which drug class may be used to treat parasomnias in children, such as sleepwalking and night terrors?", "o": {"A": "Benzodiazepines", "B": "Barbiturates", "C": "Antipsychotics", "D": "Stimulants"}, "r": "A", "e": {"correcta": "Benzodiazepines can reduce the frequency of parasomnias like sleepwalking and night terrors in children by suppressing slow-wave sleep stages.", "incorrectas": {"B": "Barbiturates are not standard treatment for pediatric parasomnias given their narrow therapeutic index and side effect profile.", "C": "Antipsychotics are not indicated for parasomnias in children.", "D": "Stimulants would not address parasomnias and could worsen sleep disturbances."}}}, {"id": "anking-neurology-special-senses-pharmacology-301", "fuente": "anking", "tema": 36, "anki": "1484768567591", "q": "Benzodiazepines may be used to treat spasticity caused by which category of disorders (e.g., MS, stroke, spinal cord trauma, tetanus)?", "o": {"A": "Upper motor neuron disorders", "B": "Lower motor neuron disorders", "C": "Neuromuscular junction disorders", "D": "Peripheral neuropathies"}, "r": "A", "e": {"correcta": "Benzodiazepines like diazepam help treat spasticity resulting from upper motor neuron (UMN) lesions such as MS, stroke, spinal cord trauma, and tetanus.", "incorrectas": {"B": "Lower motor neuron disorders typically cause flaccid paralysis, not the spasticity treated by benzodiazepines here.", "C": "Neuromuscular junction disorders (e.g., myasthenia gravis) involve different pathophysiology unrelated to UMN spasticity.", "D": "Peripheral neuropathies generally cause sensory/motor deficits without the UMN-type spasticity described."}}}, {"id": "anking-neurology-special-senses-pharmacology-302", "fuente": "anking", "tema": 36, "anki": "1484768571600", "q": "Benzodiazepines may be used to treat which disorder and panic disorder, though SSRIs/SNRIs are first-line?", "o": {"A": "Generalized anxiety disorder", "B": "Major depressive disorder", "C": "Bipolar disorder", "D": "Obsessive-compulsive disorder"}, "r": "A", "e": {"correcta": "Benzodiazepines can be used temporarily for generalized anxiety disorder and panic disorder while awaiting the delayed onset of SSRIs/SNRIs, which remain first-line.", "incorrectas": {"B": "Major depressive disorder is treated with antidepressants, not benzodiazepines as a primary approach.", "C": "Bipolar disorder requires mood stabilizers or antipsychotics, not benzodiazepines as core therapy.", "D": "OCD is treated with SSRIs at higher doses, and benzodiazepines are not a standard adjunct for OCD in this context."}}}, {"id": "anking-neurology-special-senses-pharmacology-303", "fuente": "anking", "tema": 36, "anki": "1484768583697", "q": "What pregnancy complication may be treated with benzodiazepines, though they are not first-line?", "o": {"A": "Eclampsia", "B": "Gestational diabetes", "C": "Placenta previa", "D": "Preterm labor"}, "r": "A", "e": {"correcta": "Benzodiazepines can be used (not first-line) for eclampsia, which is pre-eclampsia plus seizures; magnesium sulfate remains the first-line treatment.", "incorrectas": {"B": "Gestational diabetes is managed with diet, insulin, or metformin, not benzodiazepines.", "C": "Placenta previa is a structural/obstetric complication unrelated to benzodiazepine therapy.", "D": "Preterm labor is managed with tocolytics, not benzodiazepines."}}}, {"id": "anking-neurology-special-senses-pharmacology-304", "fuente": "anking", "tema": 36, "anki": "1484768590208", "q": "Benzodiazepines can cause which phenomenon by downregulating GABAA receptors?", "o": {"A": "Tolerance", "B": "Hypersensitivity", "C": "Idiosyncratic reaction", "D": "Anaphylaxis"}, "r": "A", "e": {"correcta": "Chronic benzodiazepine use downregulates GABAA receptors, leading to tolerance, which requires increasing doses to achieve the same effect.", "incorrectas": {"B": "Hypersensitivity would imply increased sensitivity, the opposite of receptor downregulation effects.", "C": "Idiosyncratic reactions are unpredictable individual responses, not the mechanism described here.", "D": "Anaphylaxis is an acute allergic reaction, unrelated to receptor downregulation and tolerance."}}}, {"id": "anking-ophthalmology-305", "fuente": "anking", "tema": 37, "anki": "1480550370725", "q": "The 2nd-order neuron of the hypothalamospinal (oculosympathetic) tract arises from the lateral horn of T1 and synapses on which structure?", "o": {"A": "Superior cervical ganglion", "B": "Ciliary ganglion", "C": "Pterygopalatine ganglion", "D": "Stellate (inferior cervical) ganglion"}, "r": "A", "e": {"correcta": "The 2nd-order (preganglionic) sympathetic neuron leaves the spinal cord at T1, ascends through the sympathetic chain, and synapses on the superior cervical ganglion, from which 3rd-order fibers travel to the eye and face.", "incorrectas": {"B": "The ciliary ganglion carries parasympathetic fibers to the eye (pupillary constriction), not sympathetic oculomotor fibers.", "C": "The pterygopalatine ganglion is parasympathetic, involved in lacrimation, not the sympathetic pathway to the eye.", "D": "The stellate ganglion is lower in the sympathetic chain and is more relevant to cardiac/upper limb sympathetics, not the classic 2nd-to-3rd order synapse in the oculosympathetic pathway."}}}, {"id": "anking-ophthalmology-306", "fuente": "anking", "tema": 37, "anki": "1480550373840", "q": "The 3rd-order neuron of the hypothalamospinal tract, arising from the superior cervical ganglion, carries which type of fibers to the eyelids, pupil, and facial skin?", "o": {"A": "Sympathetic fibers", "B": "Parasympathetic fibers", "C": "Special visceral afferent fibers", "D": "Somatic motor fibers"}, "r": "A", "e": {"correcta": "The 3rd-order neuron of the oculosympathetic pathway carries postganglionic sympathetic fibers from the superior cervical ganglion to the dilator pupillae, superior tarsal muscle, and facial sweat glands.", "incorrectas": {"B": "Parasympathetic fibers to the eye travel via CN III to the ciliary ganglion, not through the hypothalamospinal tract.", "C": "Special visceral afferents carry sensory information (e.g., taste), unrelated to this efferent motor pathway.", "D": "Somatic motor fibers innervate skeletal muscle directly via lower motor neurons, not smooth muscle/glands via ganglia."}}}, {"id": "anking-ophthalmology-307", "fuente": "anking", "tema": 37, "anki": "1480550376649", "q": "Which neural tract is responsible for sympathetic innervation of the face, and whose lesion produces Horner syndrome?", "o": {"A": "Hypothalamospinal tract", "B": "Medial longitudinal fasciculus", "C": "Spinothalamic tract", "D": "Corticobulbar tract"}, "r": "A", "e": {"correcta": "The hypothalamospinal tract (descending sympathetic/hypothalamic fibers) carries sympathetic input to the face; its interruption anywhere along its course causes Horner's syndrome (ptosis, miosis, anhidrosis).", "incorrectas": {"B": "The medial longitudinal fasciculus coordinates conjugate eye movements (vestibulo-ocular reflex), not sympathetic facial innervation.", "C": "The spinothalamic tract carries pain and temperature sensation, not autonomic output to the face.", "D": "The corticobulbar tract carries voluntary motor commands to brainstem motor nuclei, unrelated to sympathetic facial innervation."}}}, {"id": "anking-ophthalmology-308", "fuente": "anking", "tema": 37, "anki": "1480612362781", "q": "Which cranial nerve is unique in arising from the dorsal aspect of the midbrain?", "o": {"A": "Trochlear nerve (CN IV)", "B": "Oculomotor nerve (CN III)", "C": "Abducens nerve (CN VI)", "D": "Optic nerve (CN II)"}, "r": "A", "e": {"correcta": "CN IV (trochlear) is the only cranial nerve to exit from the dorsal surface of the brainstem, decussating before emerging just below the inferior colliculus.", "incorrectas": {"B": "CN III exits from the ventral midbrain, not dorsally.", "C": "CN VI exits from the ventral pontomedullary junction, not the dorsal midbrain.", "D": "CN II is not a true peripheral nerve but an extension of the CNS/diencephalon, and does not arise from the dorsal midbrain brainstem surface."}}}, {"id": "anking-ophthalmology-309", "fuente": "anking", "tema": 37, "anki": "1480876180506", "q": "In Horner syndrome, ptosis results from denervation of which muscle?", "o": {"A": "Superior tarsal muscle", "B": "Levator palpebrae superioris", "C": "Orbicularis oculi", "D": "Superior rectus muscle"}, "r": "A", "e": {"correcta": "The superior tarsal (Müller's) muscle is sympathetically innervated and provides additional lid elevation; its denervation in Horner syndrome causes a mild ptosis.", "incorrectas": {"B": "The levator palpebrae superioris is innervated by CN III (somatic), and its paralysis causes a more severe, complete ptosis, not the partial ptosis of Horner syndrome.", "C": "Orbicularis oculi is innervated by CN VII and functions in eyelid closure, not elevation; it is unaffected in Horner syndrome.", "D": "The superior rectus is an extraocular muscle controlling upward gaze, innervated by CN III, unrelated to eyelid position in Horner syndrome."}}}, {"id": "anking-ophthalmology-310", "fuente": "anking", "tema": 37, "anki": "1480876184706", "q": "Horner syndrome is classically associated with lesions of the spinal cord above which level?", "o": {"A": "T1", "B": "C3", "C": "T6", "D": "L1"}, "r": "A", "e": {"correcta": "The sympathetic outflow to the head and neck originates from the ciliospinal center at C8-T1/T2; lesions of the spinal cord above this level (e.g., Brown-Séquard, syringomyelia) can interrupt the hypothalamospinal tract and cause Horner syndrome.", "incorrectas": {"B": "C3 is not the classically cited boundary level; the key level relates to the ciliospinal center around C8-T1.", "C": "T6 is below the level of sympathetic outflow relevant to Horner syndrome and would not interrupt this specific pathway in the same way.", "D": "L1 is far below the cervicothoracic sympathetic outflow and is not associated with Horner syndrome."}}}, {"id": "anking-ophthalmology-311", "fuente": "anking", "tema": 37, "anki": "1480876192896", "q": "Horner syndrome's triad of ptosis, miosis, and anhidrosis results from denervation of which type of fibers to the face?", "o": {"A": "Sympathetic fibers", "B": "Parasympathetic fibers", "C": "Somatic sensory fibers", "D": "Special somatic afferent fibers"}, "r": "A", "e": {"correcta": "Horner syndrome results from interruption of sympathetic fibers anywhere along the hypothalamospinal tract, from the hypothalamus through the spinal cord, superior cervical ganglion, and along the internal carotid artery to the face and eye.", "incorrectas": {"B": "Parasympathetic denervation would cause mydriasis (dilated pupil) and other findings, not the miosis and ptosis seen in Horner syndrome.", "C": "Somatic sensory fibers convey touch/pain sensation and are not responsible for the autonomic findings of Horner syndrome.", "D": "Special somatic afferents relate to special senses like vision and hearing, unrelated to the autonomic triad of Horner syndrome."}}}, {"id": "anking-ophthalmology-312", "fuente": "anking", "tema": 37, "anki": "1480908781550", "q": "Primary vestibular afferent fibers synapse with secondary neurons in which nuclei?", "o": {"A": "Vestibular nuclei", "B": "Cochlear nuclei", "C": "Dorsal column nuclei", "D": "Inferior olivary nuclei"}, "r": "A", "e": {"correcta": "Primary vestibular afferents from the vestibular ganglion (CN VIII) synapse on the vestibular nuclear complex in the brainstem, which then relays information for balance and eye movement control.", "incorrectas": {"B": "Cochlear nuclei receive auditory, not vestibular, primary afferents.", "C": "Dorsal column nuclei (gracile/cuneate) relay proprioceptive and fine touch information from the spinal cord, unrelated to vestibular input.", "D": "Inferior olivary nuclei relay information to the cerebellum related to motor coordination, not primary vestibular sensory relay."}}}, {"id": "anking-ophthalmology-313", "fuente": "anking", "tema": 37, "anki": "1480908786228", "q": "Secondary vestibular fibers arising from the vestibular nuclei join which tract to supply the motor nuclei of CN III, IV, and VI for the vestibulo-ocular reflex?", "o": {"A": "Medial longitudinal fasciculus", "B": "Corticospinal tract", "C": "Spinothalamic tract", "D": "Vestibulospinal tract"}, "r": "A", "e": {"correcta": "The medial longitudinal fasciculus (MLF) connects the vestibular nuclei to the oculomotor (III), trochlear (IV), and abducens (VI) nuclei, coordinating conjugate eye movements during the vestibulo-ocular reflex.", "incorrectas": {"B": "The corticospinal tract carries voluntary motor commands to the spinal cord, not vestibular signals to ocular motor nuclei.", "C": "The spinothalamic tract carries pain and temperature sensation, unrelated to eye movement coordination.", "D": "The vestibulospinal tract projects to spinal motor neurons controlling postural/antigravity muscles, not to the cranial nerve nuclei governing eye movements."}}}, {"id": "anking-ophthalmology-314", "fuente": "anking", "tema": 37, "anki": "1480908796163", "q": "A lesion of the vestibular nuclei or nerve produces which characteristic finding via the vestibulo-ocular reflex?", "o": {"A": "Nystagmus", "B": "Internuclear ophthalmoplegia", "C": "Horner syndrome", "D": "Optic neuritis"}, "r": "A", "e": {"correcta": "Damage to the vestibular nuclei or nerve disrupts the normal balance of vestibular input, producing vestibular-evoked nystagmus along with dizziness, nausea, and imbalance.", "incorrectas": {"B": "Internuclear ophthalmoplegia results from a lesion of the MLF, not the vestibular nuclei/nerve themselves.", "C": "Horner syndrome results from sympathetic pathway lesions, unrelated to vestibular dysfunction.", "D": "Optic neuritis is inflammation of the optic nerve affecting vision, not a vestibular finding."}}}, {"id": "anking-ophthalmology-315", "fuente": "anking", "tema": 37, "anki": "1480908805768", "q": "In vestibular-evoked nystagmus, the slow deviation phase is directed in which direction relative to the lesion?", "o": {"A": "Toward the lesion", "B": "Away from the lesion", "C": "Upward regardless of lesion side", "D": "Downward regardless of lesion side"}, "r": "A", "e": {"correcta": "With a unilateral vestibular lesion, the intact contralateral vestibular nuclei become relatively unopposed, driving a slow deviation of the eyes toward the side of the lesion.", "incorrectas": {"B": "The slow phase moves toward, not away from, the lesion; the fast corrective phase is the one directed away from the lesion.", "C": "The direction of the slow phase is horizontal and lesion-side dependent, not consistently upward.", "D": "The direction of the slow phase is horizontal and lesion-side dependent, not consistently downward."}}}, {"id": "anking-ophthalmology-316", "fuente": "anking", "tema": 37, "anki": "1480908813955", "q": "In vestibular-evoked nystagmus, the fast corrective phase is directed in which direction relative to the lesion?", "o": {"A": "Away from the lesion", "B": "Toward the lesion", "C": "Purely vertical, independent of lesion side", "D": "Rotatory only, independent of lesion side"}, "r": "A", "e": {"correcta": "After the slow drift toward the lesion, a cortically mediated fast corrective phase rapidly moves the eyes away from the lesion side, defining the direction of the nystagmus by convention.", "incorrectas": {"B": "The slow phase, not the fast phase, moves toward the lesion.", "C": "The fast phase is typically horizontal in peripheral vestibular lesions, not purely vertical.", "D": "While rotatory components can occur, the classic fast phase described here is directionally defined as away from the lesion, not purely rotatory."}}}, {"id": "anking-ophthalmology-317", "fuente": "anking", "tema": 37, "anki": "1480995134421", "q": "A lesion of the abducens nucleus may result in complete, ipsilateral paralysis of which additional structure, beyond abducens/PPRF symptoms?", "o": {"A": "Facial muscles (CN VII)", "B": "Muscles of mastication (CN V)", "C": "Tongue muscles (CN XII)", "D": "Pharyngeal muscles (CN IX/X)"}, "r": "A", "e": {"correcta": "The facial nerve (CN VII) fibers loop around the abducens nucleus within the pons; a lesion of the abducens nucleus can therefore also damage these looping facial fibers, causing ipsilateral facial paralysis.", "incorrectas": {"B": "The muscles of mastication are innervated by CN V, which does not loop around the abducens nucleus.", "C": "Tongue muscles are innervated by CN XII, arising from the medulla, unrelated to the abducens nucleus in the pons.", "D": "Pharyngeal muscles are innervated by CN IX/X from the medulla, not related to the pontine abducens nucleus."}}}, {"id": "anking-ophthalmology-318", "fuente": "anking", "tema": 37, "anki": "1480995168622", "q": "MLF lesions classically seen in multiple sclerosis (causing internuclear ophthalmoplegia) are typically which distribution?", "o": {"A": "Bilateral", "B": "Unilateral", "C": "Exclusively right-sided", "D": "Exclusively left-sided"}, "r": "A", "e": {"correcta": "Multiple sclerosis characteristically causes bilateral MLF lesions (bilateral internuclear ophthalmoplegia), which is a classic clue distinguishing MS from other causes of unilateral INO such as stroke.", "incorrectas": {"B": "Unilateral INO is more typical of vascular (stroke) causes rather than the demyelinating plaques of MS.", "C": "There is no inherent right-sided predilection; MS-related INO is characteristically bilateral, not lateralized to one side.", "D": "There is no inherent left-sided predilection; MS-related INO is characteristically bilateral, not lateralized to one side."}}}, {"id": "anking-ophthalmology-319", "fuente": "anking", "tema": 37, "anki": "1480995174764", "q": "In internuclear ophthalmoplegia, the directional term (e.g., right or left INO) refers to which eye?", "o": {"A": "The paralyzed (impaired adduction) eye", "B": "The eye with impaired abduction", "C": "The eye with a dilated pupil", "D": "The eye with ptosis"}, "r": "A", "e": {"correcta": "The side of INO is named for the eye with impaired adduction (the affected medial rectus), e.g., a right INO means the right eye fails to adduct on attempted left lateral gaze.", "incorrectas": {"B": "Abduction of the contralateral eye is typically preserved or shows nystagmus, but the naming convention is based on the adduction deficit, not abduction.", "C": "Pupillary dilation is a feature of CN III lesions, not INO, which does not affect pupil size.", "D": "Ptosis is a feature of CN III lesions, not INO, which spares eyelid function."}}}, {"id": "anking-ophthalmology-320", "fuente": "anking", "tema": 37, "anki": "1480995198858", "q": "Internuclear ophthalmoplegia is distinguished from a CN III lesion by having normal function of which process?", "o": {"A": "Convergence", "B": "Pupillary constriction to light", "C": "Eyelid elevation", "D": "Accommodation"}, "r": "A", "e": {"correcta": "In INO, convergence is preserved because the medial rectus can still be activated via the convergence pathway (not dependent on the MLF), distinguishing it from a CN III lesion, which impairs convergence along with ptosis and mydriasis.", "incorrectas": {"B": "Pupillary constriction to light depends on CN III parasympathetics and is impaired in CN III lesions but not typically tested as the distinguishing convergence feature in INO.", "C": "Eyelid elevation (levator palpebrae) is impaired in CN III lesions causing ptosis, but this is not the distinguishing feature described for INO versus CN III lesion in this context.", "D": "Accommodation is a CN III-mediated parasympathetic function impaired in CN III lesions, but the classic distinguishing preserved feature highlighted for INO is convergence."}}}, {"id": "anking-ophthalmology-321", "fuente": "anking", "tema": 37, "anki": "1481126573614", "q": "The vestibular nuclei send axons to ipsilateral antigravity muscles via which tract to maintain upright, balanced posture?", "o": {"A": "Lateral vestibulospinal tract", "B": "Medial longitudinal fasciculus", "C": "Rubrospinal tract", "D": "Lateral corticospinal tract"}, "r": "A", "e": {"correcta": "The lateral vestibulospinal tract projects ipsilaterally from the vestibular nuclei to spinal motor neurons controlling extensor (antigravity) muscles, helping maintain upright posture and balance.", "incorrectas": {"B": "The medial longitudinal fasciculus coordinates eye movements via cranial nerve nuclei, not postural antigravity muscle control via the spinal cord.", "C": "The rubrospinal tract originates from the red nucleus and primarily facilitates flexor tone in the upper limbs, not vestibular-driven antigravity postural control.", "D": "The lateral corticospinal tract carries voluntary motor commands from the cortex, not vestibular postural reflex signals."}}}, {"id": "anking-ophthalmology-322", "fuente": "anking", "tema": 37, "anki": "1481244258605", "q": "Which part of the posterior eye is not covered by the retina, creating the physiologic blind spot?", "o": {"A": "Optic disc", "B": "Fovea centralis", "C": "Macula lutea", "D": "Ora serrata"}, "r": "A", "e": {"correcta": "The optic disc is the site where the optic nerve fibers and retinal vessels exit the eye; it lacks photoreceptors, producing the physiologic blind spot.", "incorrectas": {"B": "The fovea centralis is the region of sharpest vision, densely packed with cones, not the blind spot.", "C": "The macula lutea surrounds the fovea and is responsible for central, detailed vision, not the blind spot.", "D": "The ora serrata is the peripheral edge of the retina near the ciliary body, unrelated to the optic disc blind spot."}}}, {"id": "anking-gastrointestinal-anatomy-323", "fuente": "anking", "tema": 38, "anki": "1463078999188", "q": "What is the venous drainage pathway of the left ovary/testis?", "o": {"A": "Left gonadal vein -> left renal vein -> IVC", "B": "Left gonadal vein -> IVC directly", "C": "Left gonadal vein -> left renal artery -> IVC", "D": "Left gonadal vein -> hepatic portal vein -> IVC"}, "r": "A", "e": {"correcta": "The left gonadal vein drains at a 90-degree angle into the left renal vein, which then drains into the IVC. This longer, angled route predisposes to left-sided varicocele, especially with left renal vein compression (nutcracker syndrome) or renal mass.", "incorrectas": {"B": "This describes the right gonadal vein pathway, which drains directly into the IVC, not the left.", "C": "Veins do not drain into arteries; the renal artery carries blood away from the aorta to the kidney, not toward the IVC.", "D": "The gonadal veins are part of the systemic venous system and do not connect to the hepatic portal system."}}}, {"id": "anking-gastrointestinal-anatomy-324", "fuente": "anking", "tema": 38, "anki": "1463080196536", "q": "What is the venous drainage pathway of the right ovary/testis?", "o": {"A": "Right gonadal vein -> IVC directly", "B": "Right gonadal vein -> right renal vein -> IVC", "C": "Right gonadal vein -> hepatic vein -> IVC", "D": "Right gonadal vein -> azygos vein -> SVC"}, "r": "A", "e": {"correcta": "The right gonadal vein drains directly into the IVC at an oblique angle, allowing more laminar flow and lower venous pressure compared to the left side.", "incorrectas": {"B": "This is the pattern for the left gonadal vein, not the right.", "C": "The gonadal veins do not drain via the hepatic veins.", "D": "The gonadal veins drain into the IVC system, not the azygos-SVC system."}}}, {"id": "anking-gastrointestinal-anatomy-325", "fuente": "anking", "tema": 38, "anki": "1463080202688", "q": "What complication arises more often in the left testis than the right because of its venous drainage pattern?", "o": {"A": "Varicocele", "B": "Testicular torsion", "C": "Hydrocele", "D": "Epididymitis"}, "r": "A", "e": {"correcta": "The left spermatic vein enters the left renal vein at a 90-degree angle with a longer course to the IVC, producing less laminar flow and higher venous pressure, which predisposes to left-sided varicocele.", "incorrectas": {"B": "Testicular torsion is caused by inadequate fixation of the testis (bell-clapper deformity), not venous drainage asymmetry.", "C": "Hydrocele results from fluid accumulation within the tunica vaginalis, unrelated to venous drainage laterality.", "D": "Epididymitis is typically caused by infection (e.g., chlamydia, gonorrhea, E. coli), not venous anatomy."}}}, {"id": "anking-gastrointestinal-anatomy-326", "fuente": "anking", "tema": 38, "anki": "1463334174816", "q": "On which side of the body does varicocele most commonly occur?", "o": {"A": "Left", "B": "Right", "C": "Bilateral equally", "D": "Neither side has a predilection"}, "r": "A", "e": {"correcta": "Varicocele is far more common on the left due to the 90-degree entry of the left spermatic vein into the left renal vein, causing less laminar flow and higher venous pressure; it may also be associated with nutcracker syndrome.", "incorrectas": {"B": "The right spermatic vein drains directly into the IVC at an oblique angle with better flow, making right-sided varicocele much less common.", "C": "Varicocele shows a clear left-sided predominance rather than equal bilateral occurrence.", "D": "There is a well-documented left-sided predilection due to venous anatomy."}}}, {"id": "anking-gastrointestinal-anatomy-327", "fuente": "anking", "tema": 38, "anki": "1482014886764", "q": "What is the innermost layer of the gut wall?", "o": {"A": "Mucosa", "B": "Submucosa", "C": "Muscularis externa", "D": "Serosa"}, "r": "A", "e": {"correcta": "The mucosa is the innermost layer of the gut wall, lining the lumen and consisting of epithelium, lamina propria, and muscularis mucosae.", "incorrectas": {"B": "The submucosa lies external to the mucosa, not innermost.", "C": "The muscularis externa is located external to the submucosa, further from the lumen.", "D": "The serosa is the outermost layer of the gut wall (when intraperitoneal), not the innermost."}}}, {"id": "anking-gastrointestinal-anatomy-328", "fuente": "anking", "tema": 38, "anki": "1482021556058", "q": "Which layer of the gut wall lies external to the mucosa?", "o": {"A": "Submucosa", "B": "Muscularis externa", "C": "Serosa", "D": "Epithelium"}, "r": "A", "e": {"correcta": "The submucosa lies directly external to the mucosa and contains the submucosal (Meissner) nerve plexus along with blood vessels and lymphatics.", "incorrectas": {"B": "The muscularis externa lies external to the submucosa, one layer further out.", "C": "The serosa is the outermost layer, not immediately external to the mucosa.", "D": "Epithelium is part of the mucosa itself, not a separate layer external to it."}}}, {"id": "anking-gastrointestinal-anatomy-329", "fuente": "anking", "tema": 38, "anki": "1482021561377", "q": "Which layer of the gut wall lies external to the submucosa?", "o": {"A": "Muscularis externa", "B": "Mucosa", "C": "Serosa only", "D": "Muscularis mucosae"}, "r": "A", "e": {"correcta": "The muscularis externa lies external to the submucosa and is composed of inner circular and outer longitudinal smooth muscle layers responsible for peristalsis.", "incorrectas": {"B": "The mucosa is internal to the submucosa, not external to it.", "C": "The serosa is external to the muscularis externa, one layer further out than the submucosa's immediate neighbor.", "D": "The muscularis mucosae is a thin layer within the mucosa itself, not external to the submucosa."}}}, {"id": "anking-gastrointestinal-anatomy-330", "fuente": "anking", "tema": 38, "anki": "1482021567159", "q": "The muscularis externa of the gut wall consists of which two muscle layers, from inner to outer?", "o": {"A": "Circular (inner) and longitudinal (outer)", "B": "Longitudinal (inner) and circular (outer)", "C": "Oblique (inner) and circular (outer)", "D": "Circular (inner) and oblique (outer)"}, "r": "A", "e": {"correcta": "The muscularis externa consists of an inner circular muscle layer and an outer longitudinal muscle layer, which work together to produce peristalsis (the stomach additionally has an inner oblique layer).", "incorrectas": {"B": "This reverses the correct order; longitudinal muscle is outer, not inner.", "C": "An oblique layer is a third layer found only in the stomach, not the standard inner layer of the muscularis externa.", "D": "Oblique muscle is not the standard outer layer of the muscularis externa in most of the GI tract."}}}, {"id": "anking-gastrointestinal-anatomy-331", "fuente": "anking", "tema": 38, "anki": "1482021572867", "q": "Which nerve plexus lies between the circular and longitudinal muscle layers of the gut wall?", "o": {"A": "Myenteric (Auerbach) plexus", "B": "Submucosal (Meissner) plexus", "C": "Celiac plexus", "D": "Hypogastric plexus"}, "r": "A", "e": {"correcta": "The myenteric (Auerbach) plexus is located between the inner circular and outer longitudinal muscle layers of the muscularis externa and primarily controls GI motility.", "incorrectas": {"B": "The submucosal (Meissner) plexus lies in the submucosa, not between the muscle layers.", "C": "The celiac plexus is a prevertebral autonomic ganglion complex, not a wall layer plexus.", "D": "The hypogastric plexus is a pelvic autonomic plexus, not part of the gut wall's intrinsic nervous system."}}}, {"id": "anking-gastrointestinal-anatomy-332", "fuente": "anking", "tema": 38, "anki": "1482021579186", "q": "Which nerve plexus lies between the submucosa and inner circular muscle layer of the gut wall?", "o": {"A": "Submucosal (Meissner) plexus", "B": "Myenteric (Auerbach) plexus", "C": "Celiac plexus", "D": "Solar plexus"}, "r": "A", "e": {"correcta": "The submucosal (Meissner) plexus lies between the submucosa and the inner circular muscle layer and primarily regulates local blood flow, secretions, and absorption.", "incorrectas": {"B": "The myenteric (Auerbach) plexus lies between the two muscle layers, not between submucosa and inner circular muscle.", "C": "The celiac plexus is an extrinsic prevertebral plexus, not located within the gut wall.", "D": "The solar plexus is a lay term for the celiac plexus, an extrinsic structure, not an intramural plexus."}}}, {"id": "anking-gastrointestinal-anatomy-333", "fuente": "anking", "tema": 38, "anki": "1482021584289", "q": "What is the outermost layer of the gut wall when the segment is intraperitoneal?", "o": {"A": "Serosa", "B": "Adventitia", "C": "Muscularis externa", "D": "Submucosa"}, "r": "A", "e": {"correcta": "When a gut segment is intraperitoneal, its outermost layer is the serosa, a connective tissue layer covered by visceral peritoneum (mesothelium).", "incorrectas": {"B": "Adventitia is the outermost layer for retroperitoneal segments, which lack a peritoneal covering.", "C": "The muscularis externa is internal to the serosa, not the outermost layer.", "D": "The submucosa is deep to the mucosa and muscularis, far from the outermost position."}}}, {"id": "anking-gastrointestinal-anatomy-334", "fuente": "anking", "tema": 38, "anki": "1482021589803", "q": "What is the outermost layer of the gut wall when the segment is retroperitoneal?", "o": {"A": "Adventitia", "B": "Serosa", "C": "Muscularis externa", "D": "Mucosa"}, "r": "A", "e": {"correcta": "Retroperitoneal gut segments lack a peritoneal covering, so their outermost layer is the adventitia, a connective tissue layer that blends with surrounding structures.", "incorrectas": {"B": "Serosa is present only in intraperitoneal segments covered by visceral peritoneum.", "C": "The muscularis externa lies deep to the adventitia, not as the outermost layer.", "D": "The mucosa is the innermost layer, the opposite extreme from the outermost layer."}}}, {"id": "anking-gastrointestinal-anatomy-335", "fuente": "anking", "tema": 38, "anki": "1482021594676", "q": "Which gut wall layer contains Meissner's plexus?", "o": {"A": "Submucosa", "B": "Mucosa", "C": "Muscularis externa", "D": "Serosa"}, "r": "A", "e": {"correcta": "Meissner's plexus, also called the submucosal plexus, is located within the submucosa and regulates secretion, absorption, and local blood flow.", "incorrectas": {"B": "The mucosa does not house Meissner's plexus; it is a separate, more superficial layer.", "C": "The muscularis externa houses the myenteric (Auerbach) plexus, not Meissner's plexus.", "D": "The serosa is the outermost connective tissue layer and does not contain Meissner's plexus."}}}, {"id": "anking-gastrointestinal-anatomy-336", "fuente": "anking", "tema": 38, "anki": "1482021603417", "q": "Which gut wall layer contains Auerbach's plexus?", "o": {"A": "Muscularis externa", "B": "Submucosa", "C": "Mucosa", "D": "Serosa"}, "r": "A", "e": {"correcta": "Auerbach's plexus, also known as the myenteric plexus, lies within the muscularis externa between the circular and longitudinal muscle layers and primarily controls motility.", "incorrectas": {"B": "The submucosa contains Meissner's plexus, not Auerbach's plexus.", "C": "The mucosa does not contain either major intrinsic nerve plexus of the gut wall.", "D": "The serosa is a connective tissue covering and does not contain neural plexuses."}}}, {"id": "anking-gastrointestinal-anatomy-337", "fuente": "anking", "tema": 38, "anki": "1482021611944", "q": "Which division of the autonomic nervous system is usually excitatory on GI tract functions?", "o": {"A": "Parasympathetic nervous system", "B": "Sympathetic nervous system", "C": "Somatic nervous system", "D": "Enteric nervous system exclusively, independent of autonomic input"}, "r": "A", "e": {"correcta": "The parasympathetic nervous system is generally excitatory on GI tract motility and secretion, increasing peristalsis and glandular activity via vagal and pelvic splanchnic input.", "incorrectas": {"B": "The sympathetic nervous system is generally inhibitory on GI function, decreasing motility and secretion.", "C": "The somatic nervous system controls skeletal muscle (e.g., external anal sphincter), not the smooth muscle and glands of the GI tract wall.", "D": "While the enteric nervous system can act independently, the question asks about autonomic modulation, and it is the parasympathetic division that is classically excitatory."}}}, {"id": "anking-gastrointestinal-anatomy-338", "fuente": "anking", "tema": 38, "anki": "1482021615074", "q": "Which nerves carry parasympathetic input to the GI tract?", "o": {"A": "Vagus nerve and pelvic splanchnic nerves", "B": "Greater and lesser splanchnic nerves", "C": "Phrenic nerve and vagus nerve", "D": "Pudendal nerve and vagus nerve"}, "r": "A", "e": {"correcta": "Parasympathetic fibers reach the GI tract via the vagus nerve (foregut and midgut) and the pelvic splanchnic nerves (hindgut), stimulating motility and secretion.", "incorrectas": {"B": "The greater and lesser splanchnic nerves carry sympathetic (not parasympathetic) fibers to abdominal viscera.", "C": "The phrenic nerve innervates the diaphragm and pericardium, not the GI tract.", "D": "The pudendal nerve is a somatic nerve supplying perineal structures, not a parasympathetic GI nerve."}}}, {"id": "anking-gastrointestinal-anatomy-339", "fuente": "anking", "tema": 38, "anki": "1482021618596", "q": "What term describes reflexes in which both the afferent and efferent pathways are contained within the vagus nerve?", "o": {"A": "Vagovagal reflexes", "B": "Spinal reflexes", "C": "Enterogastric reflexes via sympathetic chain", "D": "Somatovisceral reflexes"}, "r": "A", "e": {"correcta": "Vagovagal reflexes are reflex arcs in which both the sensory (afferent) and motor (efferent) limbs travel within the vagus nerve, mediating responses such as receptive relaxation of the stomach.", "incorrectas": {"B": "Spinal reflexes involve pathways through the spinal cord, not solely the vagus nerve.", "C": "This distractor incorrectly attributes an enterogastric reflex to the sympathetic chain rather than the vagus nerve.", "D": "Somatovisceral reflexes involve somatic and visceral pathways together, not exclusively the vagus nerve."}}}, {"id": "anking-gastrointestinal-anatomy-340", "fuente": "anking", "tema": 38, "anki": "1482021659455", "q": "Which division of the autonomic nervous system is usually inhibitory on GI tract functions?", "o": {"A": "Sympathetic nervous system", "B": "Parasympathetic nervous system", "C": "Somatic nervous system", "D": "Central nervous system exclusively"}, "r": "A", "e": {"correcta": "The sympathetic nervous system is generally inhibitory on GI tract motility and secretion, decreasing peristalsis and glandular activity while promoting vasoconstriction of gut vasculature.", "incorrectas": {"B": "The parasympathetic nervous system is generally excitatory on GI function, the opposite effect described.", "C": "The somatic nervous system controls voluntary skeletal muscle, not autonomic regulation of GI smooth muscle and glands.", "D": "The CNS is not itself an autonomic division; the correct answer specifies the sympathetic division of the ANS."}}}, {"id": "anking-gastrointestinal-physiology-341", "fuente": "anking", "tema": 39, "anki": "1476669535017", "q": "In splenic macrophages, biliverdin is reduced to which compound?", "o": {"A": "Unconjugated bilirubin", "B": "Conjugated bilirubin", "C": "Urobilinogen", "D": "Stercobilin"}, "r": "A", "e": {"correcta": "Heme is broken down to biliverdin, which is then reduced by biliverdin reductase to unconjugated (indirect) bilirubin within splenic macrophages.", "incorrectas": {"B": "Conjugation of bilirubin with glucuronic acid occurs later in the liver, not in splenic macrophages.", "C": "Urobilinogen is formed by gut bacteria acting on conjugated bilirubin in the intestine, not by splenic macrophages.", "D": "Stercobilin is a further breakdown product of urobilinogen formed in the colon, not by splenic macrophages."}}}, {"id": "anking-gastrointestinal-physiology-342", "fuente": "anking", "tema": 39, "anki": "1476669538969", "q": "What type of bilirubin (conjugated or unconjugated) is formed in the splenic macrophages?", "o": {"A": "Conjugated (direct) bilirubin", "B": "Unconjugated (indirect) bilirubin", "C": "Urobilinogen", "D": "Biliverdin only, with no bilirubin formed"}, "r": "B", "e": {"correcta": "Splenic macrophages break down heme to biliverdin and then to unconjugated (indirect) bilirubin, which is subsequently transported to the liver for conjugation.", "incorrectas": {"A": "Conjugated bilirubin is produced in hepatocytes via UDP-glucuronosyltransferase, not in splenic macrophages.", "C": "Urobilinogen is a downstream intestinal bacterial product, not something splenic macrophages form.", "D": "Biliverdin is further reduced to bilirubin within the macrophage, so bilirubin is indeed formed there."}}}, {"id": "anking-gastrointestinal-physiology-343", "fuente": "anking", "tema": 39, "anki": "1476669544873", "q": "Unconjugated bilirubin travels in the blood bound to which protein?", "o": {"A": "Albumin", "B": "Transferrin", "C": "Ceruloplasmin", "D": "Haptoglobin"}, "r": "A", "e": {"correcta": "Unconjugated bilirubin is lipophilic and water-insoluble, so it must be carried in the blood bound to albumin en route to the liver.", "incorrectas": {"B": "Transferrin transports iron, not bilirubin.", "C": "Ceruloplasmin transports copper, not bilirubin.", "D": "Haptoglobin binds free hemoglobin released from lysed red cells, not bilirubin."}}}, {"id": "anking-gastrointestinal-physiology-344", "fuente": "anking", "tema": 39, "anki": "1476669549324", "q": "Unconjugated bilirubin is removed from the blood by which organ?", "o": {"A": "Liver", "B": "Spleen", "C": "Kidney", "D": "Pancreas"}, "r": "A", "e": {"correcta": "The liver takes up albumin-bound unconjugated bilirubin from the blood and conjugates it with glucuronic acid for excretion into bile.", "incorrectas": {"B": "The spleen is where bilirubin is initially produced from heme breakdown, not where it is cleared from blood.", "C": "The kidney excretes water-soluble conjugated bilirubin/urobilin in urine but does not clear unconjugated bilirubin from blood.", "D": "The pancreas has no role in bilirubin metabolism."}}}, {"id": "anking-gastrointestinal-physiology-345", "fuente": "anking", "tema": 39, "anki": "1476669559297", "q": "Conjugated (direct) bilirubin is excreted in bile and metabolized by bacterial flora, producing which compound?", "o": {"A": "Urobilinogen", "B": "Biliverdin", "C": "Stercobilin", "D": "Unconjugated bilirubin"}, "r": "A", "e": {"correcta": "Gut bacteria deconjugate and reduce conjugated bilirubin in the intestine to form urobilinogen, which can then follow several fates (fecal excretion as stercobilin, enterohepatic recirculation, or urinary excretion as urobilin).", "incorrectas": {"B": "Biliverdin is formed earlier from heme breakdown, prior to bilirubin conjugation.", "C": "Stercobilin is a further oxidation product of urobilinogen in the colon, occurring after urobilinogen is formed.", "D": "Unconjugated bilirubin is the precursor to conjugated bilirubin, formed before conjugation, not a product of bacterial metabolism of conjugated bilirubin."}}}, {"id": "anking-gastrointestinal-physiology-346", "fuente": "anking", "tema": 39, "anki": "1476669563594", "q": "Most (80%) of urobilinogen is excreted in feces as which compound, which gives stool its brown color?", "o": {"A": "Stercobilin", "B": "Urobilin", "C": "Biliverdin", "D": "Conjugated bilirubin"}, "r": "A", "e": {"correcta": "The majority of urobilinogen is oxidized in the colon to stercobilin, which is responsible for the brown color of normal stool.", "incorrectas": {"B": "Urobilin is the oxidation product excreted in urine (about 2% of urobilinogen), giving urine its yellow color, not stool its brown color.", "C": "Biliverdin is a green pigment formed early in heme catabolism, not the compound responsible for stool color.", "D": "Conjugated bilirubin is metabolized by bacteria to urobilinogen before further conversion to stercobilin; it is not itself the brown pigment."}}}, {"id": "anking-gastrointestinal-physiology-347", "fuente": "anking", "tema": 39, "anki": "1476669567633", "q": "Approximately 18% of urobilinogen is returned to the liver via which circulation?", "o": {"A": "Enterohepatic circulation", "B": "Portal circulation only (without hepatic uptake)", "C": "Systemic circulation", "D": "Lymphatic circulation"}, "r": "A", "e": {"correcta": "A portion of urobilinogen is reabsorbed from the intestine and recycled back to the liver through the enterohepatic circulation.", "incorrectas": {"B": "While the portal vein is involved, the specific named pathway of reabsorption and recycling back to the liver is termed enterohepatic circulation.", "C": "Systemic circulation refers to blood flow to the body generally, not the specific gut-liver recycling pathway.", "D": "Lymphatic circulation is not the route by which urobilinogen returns to the liver."}}}, {"id": "anking-gastrointestinal-physiology-348", "fuente": "anking", "tema": 39, "anki": "1476669572157", "q": "About 2% of urobilinogen is excreted in urine as which compound, which gives urine its yellow color?", "o": {"A": "Urobilin", "B": "Stercobilin", "C": "Biliverdin", "D": "Unconjugated bilirubin"}, "r": "A", "e": {"correcta": "A small fraction of urobilinogen is absorbed into the blood and filtered by the kidney, where it is oxidized to urobilin, giving urine its characteristic yellow color.", "incorrectas": {"B": "Stercobilin is the fecal oxidation product of urobilinogen, responsible for stool color, not urine color.", "C": "Biliverdin is an early heme breakdown product and is not excreted in urine to give it color.", "D": "Unconjugated bilirubin is water-insoluble and bound to albumin, so it is not filtered and excreted in urine."}}}, {"id": "anking-gastrointestinal-physiology-349", "fuente": "anking", "tema": 39, "anki": "1476669576211", "q": "Is unconjugated (indirect) bilirubin water soluble?", "o": {"A": "No, it is water-insoluble", "B": "Yes, it is highly water-soluble", "C": "Yes, but only after binding albumin", "D": "Only in the presence of bile salts"}, "r": "A", "e": {"correcta": "Unconjugated bilirubin is lipophilic and water-insoluble, requiring albumin binding for transport in blood; this insolubility is why it cannot be excreted directly in bile or urine and must first be conjugated.", "incorrectas": {"B": "Unconjugated bilirubin is not water-soluble; conjugation with glucuronic acid is required to make it water-soluble.", "C": "Albumin binding allows transport in blood but does not make the bilirubin molecule itself water-soluble.", "D": "Bile salts aid fat digestion and do not confer water solubility on unconjugated bilirubin."}}}, {"id": "anking-gastrointestinal-physiology-350", "fuente": "anking", "tema": 39, "anki": "1476669579159", "q": "Is conjugated (direct) bilirubin water soluble?", "o": {"A": "Yes, it is water-soluble", "B": "No, it is water-insoluble", "C": "Only when bound to albumin", "D": "Only after bacterial metabolism in the gut"}, "r": "A", "e": {"correcta": "Conjugation with glucuronic acid in the liver converts bilirubin into a water-soluble form, allowing it to be excreted into bile and, if elevated in blood, filtered by the kidney into urine.", "incorrectas": {"B": "It is unconjugated bilirubin that is water-insoluble; conjugation specifically renders bilirubin water-soluble.", "C": "Conjugated bilirubin does not require albumin binding for solubility, unlike its unconjugated counterpart.", "D": "Water solubility is conferred by hepatic conjugation, not by later bacterial metabolism in the gut."}}}, {"id": "anking-gastrointestinal-physiology-351", "fuente": "anking", "tema": 39, "anki": "1482021696583", "q": "Gastrin has which effect on gastric H+ secretion?", "o": {"A": "Increases gastric H+ secretion", "B": "Decreases gastric H+ secretion", "C": "Has no effect on gastric H+ secretion", "D": "Only inhibits H+ secretion during the cephalic phase"}, "r": "A", "e": {"correcta": "Gastrin stimulates parietal cells (directly and via histamine release from ECL cells) to increase gastric acid (H+) secretion.", "incorrectas": {"B": "Gastrin increases, rather than decreases, acid secretion; somatostatin and secretin are among the hormones that decrease it.", "C": "Gastrin has a well-established stimulatory effect on acid secretion, not a neutral one.", "D": "Gastrin's stimulatory effect on acid secretion occurs during the gastric phase, and it does not act as an inhibitor in the cephalic phase."}}}, {"id": "anking-gastrointestinal-physiology-352", "fuente": "anking", "tema": 39, "anki": "1482021707646", "q": "Gastrin has which effect on gastric motility?", "o": {"A": "Increases gastric motility", "B": "Decreases gastric motility", "C": "No effect on gastric motility", "D": "Increases motility only in the small intestine, not the stomach"}, "r": "A", "e": {"correcta": "Gastrin promotes gastric motility in addition to stimulating acid secretion and growth of gastric mucosa.", "incorrectas": {"B": "Gastrin increases, rather than decreases, gastric motility; hormones like secretin and GIP tend to decrease motility.", "C": "Gastrin has a recognized stimulatory effect on motility, not a null effect.", "D": "Gastrin's motility-promoting effect is on the stomach itself, which is one of its key actions."}}}, {"id": "anking-gastrointestinal-physiology-353", "fuente": "anking", "tema": 39, "anki": "1482021710999", "q": "Gastrin secretion is most stimulated by which of the following?", "o": {"A": "Stomach distention", "B": "Gastric acidification (low pH)", "C": "Secretin release", "D": "Fat in the duodenum"}, "r": "A", "e": {"correcta": "Distention of the stomach is a major and potent stimulus for gastrin release from G cells, along with vagal stimulation via GRP and luminal peptides/amino acids.", "incorrectas": {"B": "Acidification of the gastric lumen (low pH) actually inhibits, rather than stimulates, gastrin secretion via a negative feedback loop.", "C": "Secretin is released in response to duodenal acid and actually inhibits gastrin secretion, rather than stimulating it.", "D": "Fat in the duodenum stimulates CCK and GIP release and tends to inhibit, rather than stimulate, gastric emptying and gastrin secretion."}}}, {"id": "anking-gastrointestinal-physiology-354", "fuente": "anking", "tema": 39, "anki": "1482021723937", "q": "Gastrin secretion is stimulated by vagal stimulation via which neuropeptide?", "o": {"A": "Gastrin-releasing peptide (GRP, bombesin)", "B": "Vasoactive intestinal peptide (VIP)", "C": "Substance P", "D": "Somatostatin"}, "r": "A", "e": {"correcta": "Vagal efferents release gastrin-releasing peptide (GRP, also called bombesin) onto G cells, stimulating gastrin secretion, distinct from direct ACh-mediated pathways.", "incorrectas": {"B": "VIP is a relaxant neuropeptide involved in smooth muscle relaxation and secretion in other contexts, not the mediator of vagal gastrin stimulation.", "C": "Substance P is involved in pain transmission and some GI motility effects but is not the vagal mediator of gastrin release.", "D": "Somatostatin inhibits gastrin secretion; it is not a stimulatory vagal neurotransmitter."}}}, {"id": "anking-gastrointestinal-physiology-355", "fuente": "anking", "tema": 39, "anki": "1482021728193", "q": "Is the vagal stimulation of G cells (gastrin secretion) inhibited by atropine?", "o": {"A": "No, it is not inhibited by atropine", "B": "Yes, atropine completely blocks it", "C": "Yes, but only at high doses", "D": "Atropine enhances vagal stimulation of G cells"}, "r": "A", "e": {"correcta": "Atropine blocks muscarinic ACh receptors, but the vagus nerve stimulates G cells via release of gastrin-releasing peptide (GRP), a non-cholinergic pathway, so atropine does not block this stimulation.", "incorrectas": {"B": "Atropine blocks cholinergic muscarinic transmission but does not block the GRP-mediated pathway to G cells, so it does not fully inhibit gastrin release.", "C": "There is no dose-dependent atropine-sensitive component described for this GRP-mediated pathway; it remains atropine-resistant.", "D": "Atropine is a muscarinic antagonist and would not enhance any vagal signaling pathway."}}}, {"id": "anking-gastrointestinal-physiology-356", "fuente": "anking", "tema": 39, "anki": "1482021739745", "q": "Which nutrient class most stimulates gastrin secretion?", "o": {"A": "Protein (amino acids)", "B": "Carbohydrates", "C": "Fats", "D": "Fiber"}, "r": "A", "e": {"correcta": "Luminal protein digestion products (amino acids and small peptides) are potent stimulants of G cells to secrete gastrin.", "incorrectas": {"B": "Carbohydrates are not significant stimulants of gastrin secretion compared to protein.", "C": "Fat in the small intestine stimulates CCK and GIP release and actually slows gastric emptying rather than strongly stimulating gastrin.", "D": "Fiber has no significant direct role in stimulating gastrin secretion."}}}, {"id": "anking-gastrointestinal-physiology-357", "fuente": "anking", "tema": 39, "anki": "1482021753483", "q": "Gastrin secretion is affected in which way by somatostatin?", "o": {"A": "Inhibited", "B": "Stimulated", "C": "Unaffected", "D": "Stimulated only in the fasting state"}, "r": "A", "e": {"correcta": "Somatostatin, released from D cells, inhibits gastrin secretion as part of a negative feedback loop that limits acid secretion when the stomach is acidified.", "incorrectas": {"B": "Somatostatin is inhibitory to nearly all GI hormones, including gastrin, not stimulatory.", "C": "Somatostatin has a clear, well-documented inhibitory effect on gastrin secretion, not a neutral one.", "D": "Somatostatin's inhibitory action on gastrin is not restricted to the fasting state; it occurs particularly when luminal pH is low."}}}, {"id": "anking-gastrointestinal-physiology-358", "fuente": "anking", "tema": 39, "anki": "1482021756852", "q": "What is the minimum fragment necessary for biologic activity of gastrin?", "o": {"A": "C-terminal tetrapeptide", "B": "N-terminal tetrapeptide", "C": "Full-length gastrin-34 (big gastrin)", "D": "The signal peptide sequence"}, "r": "A", "e": {"correcta": "The C-terminal tetrapeptide of gastrin contains the minimal sequence required for full biologic activity, and this sequence is shared with cholecystokinin (CCK), explaining their overlapping actions.", "incorrectas": {"B": "It is the C-terminal, not N-terminal, tetrapeptide that carries the essential biologic activity of gastrin.", "C": "Full-length gastrin-34 is one of the larger circulating forms but is not the minimal fragment required for activity.", "D": "The signal peptide is cleaved during processing and is not related to the hormone's biologic activity."}}}, {"id": "anking-gastrointestinal-pharmacology-359", "fuente": "anking", "tema": 40, "anki": "1405722949047", "q": "Overuse of which antacid is associated with hyporeflexia, hypotension, and cardiac arrest?", "o": {"A": "Magnesium hydroxide", "B": "Aluminum hydroxide", "C": "Calcium carbonate", "D": "Sodium bicarbonate"}, "r": "A", "e": {"correcta": "Magnesium hydroxide overuse causes hypermagnesemia, which stabilizes voltage-gated calcium channels at the neuromuscular junction (causing hyporeflexia), decreases PTH and vascular calcium (causing hypotension), and impairs cardiac repolarization, leading to cardiac arrest.", "incorrectas": {"B": "Aluminum hydroxide classically causes constipation and hypophosphatemia, not the hypermagnesemia toxicity described.", "C": "Calcium carbonate overuse is associated with milk-alkali syndrome (hypercalcemia), not hyporeflexia and hypotension.", "D": "Sodium bicarbonate overuse causes metabolic alkalosis, not the neuromuscular/cardiac toxicity described."}}}, {"id": "anking-gastrointestinal-pharmacology-360", "fuente": "anking", "tema": 40, "anki": "1461596362186", "q": "Infection, medication, vestibular dysfunction, and chemoradiation are common causes of which symptom?", "o": {"A": "Vomiting", "B": "Constipation", "C": "Dysphagia", "D": "Abdominal pain"}, "r": "A", "e": {"correcta": "These are all classic triggers of nausea and vomiting, acting through different pathways (chemoreceptor trigger zone, vestibular system, and vagal afferents) that converge on the vomiting center.", "incorrectas": {"B": "Constipation is not a typical direct result of these triggers, which primarily activate emetic pathways.", "C": "Dysphagia refers to difficulty swallowing and is not the classic symptom linked to these triggers.", "D": "While some causes can produce abdominal pain, the classic shared endpoint of these triggers is vomiting via the emetic reflex."}}}, {"id": "anking-gastrointestinal-pharmacology-361", "fuente": "anking", "tema": 40, "anki": "1461597313002", "q": "The nucleus tractus solitarius projects neurons to other medullary nuclei to coordinate which response?", "o": {"A": "Vomiting", "B": "Respiratory rhythm generation", "C": "Blood pressure baroreflex only", "D": "Swallowing initiation"}, "r": "A", "e": {"correcta": "The nucleus tractus solitarius (NTS) integrates emetic signals and coordinates the vomiting response, including abdominal wall muscle contraction, diaphragm movement, and lower esophageal sphincter relaxation.", "incorrectas": {"B": "While the NTS has roles in autonomic regulation, the classic emetic reflex coordination described here is the vomiting response.", "C": "The NTS is involved in baroreflex processing, but that is not the response being described in this context.", "D": "Swallowing initiation involves different medullary circuits, not the vomiting reflex pathway described."}}}, {"id": "anking-gastrointestinal-pharmacology-362", "fuente": "anking", "tema": 40, "anki": "1461597435624", "q": "The GI tract directly communicates with the nucleus tractus solitarius via which cranial nerve?", "o": {"A": "Vagus nerve (CN X)", "B": "Glossopharyngeal nerve (CN IX)", "C": "Vestibulocochlear nerve (CN VIII)", "D": "Trigeminal nerve (CN V)"}, "r": "A", "e": {"correcta": "Vagal afferents (CN X) carry sensory information from the GI tract directly to the nucleus tractus solitarius, relaying signals related to nausea and vomiting.", "incorrectas": {"B": "CN IX contributes to some visceral sensation but is not the primary nerve linking the GI tract to the NTS in the vomiting pathway.", "C": "CN VIII connects the vestibular system, not the GI tract, to the NTS.", "D": "CN V is responsible for facial sensation and mastication, not GI-to-NTS communication."}}}, {"id": "anking-gastrointestinal-pharmacology-363", "fuente": "anking", "tema": 40, "anki": "1461597443435", "q": "GI irritation due to infection, chemotherapy, or distension causes release of which mucosal mediator?", "o": {"A": "Serotonin", "B": "Histamine", "C": "Dopamine", "D": "Substance P alone"}, "r": "A", "e": {"correcta": "Enterochromaffin cells in the irritated GI mucosa release serotonin, which then stimulates 5-HT3 receptors on vagal afferents to trigger the vomiting reflex.", "incorrectas": {"B": "Histamine is more associated with motion sickness and vestibular-mediated nausea, not direct mucosal irritation signaling.", "C": "Dopamine acts centrally at the chemoreceptor trigger zone rather than being the primary mucosal mediator released upon GI irritation.", "D": "Substance P is involved in the emetic pathway (via NK1 receptors) but is not the primary mucosal mediator released by GI irritation described here."}}}, {"id": "anking-gastrointestinal-pharmacology-364", "fuente": "anking", "tema": 40, "anki": "1461597499456", "q": "Serotonin released from irritated GI mucosa activates which receptor on vagal afferents to relay signals to the nucleus tractus solitarius?", "o": {"A": "5-HT3", "B": "5-HT1A", "C": "D2", "D": "M1 muscarinic"}, "r": "A", "e": {"correcta": "Serotonin acts on 5-HT3 receptors located on vagal afferent nerve terminals, which is why 5-HT3 antagonists like ondansetron are effective antiemetics for chemotherapy-induced nausea.", "incorrectas": {"B": "5-HT1A receptors are more relevant to central serotonergic signaling (e.g., anxiety, mood) rather than vagal afferent emetic signaling.", "C": "D2 receptors are involved in the chemoreceptor trigger zone pathway, not the vagal afferent serotonin pathway.", "D": "M1 muscarinic receptors mediate vestibular-induced nausea, not the serotonin-vagal afferent pathway."}}}, {"id": "anking-gastrointestinal-pharmacology-365", "fuente": "anking", "tema": 40, "anki": "1461597547266", "q": "The vestibular system communicates directly with the nucleus tractus solitarius via which cranial nerve?", "o": {"A": "Vestibulocochlear nerve (CN VIII)", "B": "Vagus nerve (CN X)", "C": "Facial nerve (CN VII)", "D": "Oculomotor nerve (CN III)"}, "r": "A", "e": {"correcta": "CN VIII (vestibulocochlear nerve) carries vestibular input directly to the nucleus tractus solitarius, mediating motion sickness and vertigo-associated nausea.", "incorrectas": {"B": "CN X carries GI visceral afferents to the NTS, not vestibular input.", "C": "CN VII controls facial movement and taste, not vestibular signaling to the NTS.", "D": "CN III controls eye movement and is not involved in vestibular communication with the NTS."}}}, {"id": "anking-gastrointestinal-pharmacology-366", "fuente": "anking", "tema": 40, "anki": "1461597592228", "q": "The vestibular system is primarily responsible for which sensation, along with motion sickness (vestibular nausea)?", "o": {"A": "Vertigo", "B": "Tinnitus", "C": "Diplopia", "D": "Ataxia only"}, "r": "A", "e": {"correcta": "The vestibular system maintains balance and spatial orientation; dysfunction or conflicting sensory input produces vertigo and motion sickness.", "incorrectas": {"B": "Tinnitus is a cochlear/auditory symptom, not primarily a vestibular balance symptom.", "C": "Diplopia (double vision) results from ocular motor dysfunction, not vestibular dysfunction.", "D": "Ataxia can result from cerebellar or vestibular pathology but is not the classic sensory symptom paired with motion sickness here; vertigo is."}}}, {"id": "anking-gastrointestinal-pharmacology-367", "fuente": "anking", "tema": 40, "anki": "1461597712293", "q": "The area postrema (chemoreceptor trigger zone) responds to which type of substances, such as chemotherapeutic agents?", "o": {"A": "Emetogenic substances", "B": "Anti-inflammatory substances", "C": "Anticoagulant substances", "D": "Antihypertensive substances"}, "r": "A", "e": {"correcta": "The area postrema lies outside the blood-brain barrier and detects emetogenic (vomit-inducing) substances in the blood and CSF, such as chemotherapeutic agents and toxins, triggering nausea and vomiting.", "incorrectas": {"B": "Anti-inflammatory agents are not the class of substances specifically detected by the area postrema in this context.", "C": "Anticoagulants are not sensed by the chemoreceptor trigger zone as a class.", "D": "Antihypertensives are not the substances classically detected by the area postrema for triggering emesis."}}}, {"id": "anking-gastrointestinal-pharmacology-368", "fuente": "anking", "tema": 40, "anki": "1461598594612", "q": "Ondansetron is used to treat nausea and vomiting induced by which two conditions?", "o": {"A": "Chemotherapy and post-operative states", "B": "Pregnancy and motion sickness", "C": "Migraine and vertigo", "D": "Gastroenteritis and peptic ulcer disease"}, "r": "A", "e": {"correcta": "Ondansetron, a 5-HT3 receptor antagonist, is a first-line agent for chemotherapy-induced and post-operative nausea and vomiting.", "incorrectas": {"B": "Ondansetron is sometimes used off-label in pregnancy, but the classic indications tested are chemotherapy- and post-operative-induced nausea/vomiting, and it is not a standard treatment for motion sickness.", "C": "Migraine and vertigo are treated with other agents (e.g., triptans, antihistamines/anticholinergics), not primarily ondansetron.", "D": "Gastroenteritis and peptic ulcer disease are not the classic FDA-labeled indications for ondansetron."}}}, {"id": "anking-gastrointestinal-pharmacology-369", "fuente": "anking", "tema": 40, "anki": "1461598623075", "q": "Which side effects can occur with ondansetron use, affecting the gut and the head respectively?", "o": {"A": "Constipation and headache/dizziness", "B": "Diarrhea and drowsiness", "C": "Bloating and tinnitus", "D": "Nausea and insomnia"}, "r": "A", "e": {"correcta": "Ondansetron commonly causes constipation (due to reduced GI motility from 5-HT3 blockade) and headache/dizziness as central side effects.", "incorrectas": {"B": "Diarrhea and drowsiness are not the classic ondansetron side effects; ondansetron tends to cause constipation, not diarrhea.", "C": "Bloating and tinnitus are not the well-recognized side effects of ondansetron.", "D": "Nausea and insomnia are not typical ondansetron side effects; ironically it is used to treat nausea, not cause it."}}}, {"id": "anking-gastrointestinal-pharmacology-370", "fuente": "anking", "tema": 40, "anki": "1461598652927", "q": "Ondansetron can prolong which cardiac interval and induce which arrhythmia?", "o": {"A": "QT interval / torsades de pointes", "B": "PR interval / atrial fibrillation", "C": "QRS interval / ventricular tachycardia", "D": "QT interval / Wolff-Parkinson-White syndrome"}, "r": "A", "e": {"correcta": "Ondansetron can prolong the QT interval, increasing the risk of torsades de pointes, so it should be used cautiously or avoided in patients with baseline QT prolongation.", "incorrectas": {"B": "PR interval prolongation and atrial fibrillation are not the classic arrhythmic risks associated with ondansetron.", "C": "QRS widening and ventricular tachycardia are not the specific risk described for ondansetron; QT prolongation and torsades are.", "D": "Wolff-Parkinson-White is a congenital conduction abnormality, not a drug-induced effect of ondansetron."}}}, {"id": "anking-gastrointestinal-pharmacology-371", "fuente": "anking", "tema": 40, "anki": "1461598684331", "q": "Ondansetron may cause a syndrome presenting with rigidity, tremor, hyperthermia, and confusion. What is this syndrome?", "o": {"A": "Serotonin syndrome", "B": "Neuroleptic malignant syndrome", "C": "Malignant hyperthermia", "D": "Anticholinergic toxicity"}, "r": "A", "e": {"correcta": "Ondansetron increases serotonergic activity via 5-HT3 blockade effects and, especially with concomitant serotonergic drugs, can precipitate serotonin syndrome, characterized by agitation, hyperactivity, and autonomic instability (the 3 A's) along with rigidity, tremor, and hyperthermia.", "incorrectas": {"B": "Neuroleptic malignant syndrome is caused by dopamine antagonists (e.g., antipsychotics, metoclopramide), not ondansetron.", "C": "Malignant hyperthermia is triggered by inhalational anesthetics and succinylcholine, not ondansetron.", "D": "Anticholinergic toxicity presents with dry skin, mydriasis, and delirium, not the described rigidity/hyperthermia/confusion picture from serotonergic excess."}}}, {"id": "anking-gastrointestinal-pharmacology-372", "fuente": "anking", "tema": 40, "anki": "1461599508630", "q": "The vestibular system contains which muscarinic receptor subtype?", "o": {"A": "M1", "B": "M2", "C": "M3", "D": "M4"}, "r": "A", "e": {"correcta": "The vestibular system expresses M1 muscarinic receptors, which is why M1 antagonists like scopolamine are effective in treating motion sickness.", "incorrectas": {"B": "M2 receptors are primarily found in cardiac tissue, mediating decreased heart rate, not vestibular signaling.", "C": "M3 receptors are found in smooth muscle and glands (e.g., bladder, GI tract, salivary glands), not primarily vestibular tissue.", "D": "M4 receptors are mainly expressed in the CNS (striatum) and are not the receptor associated with vestibular nausea."}}}, {"id": "anking-gastrointestinal-pharmacology-373", "fuente": "anking", "tema": 40, "anki": "1461599540100", "q": "Motion sickness (vestibular nausea) is treated with which two types of agents?", "o": {"A": "1st generation antihistamines (diphenhydramine, meclizine) and scopolamine", "B": "5-HT3 antagonists and D2 antagonists", "C": "Proton pump inhibitors and H2 blockers", "D": "NK1 antagonists and corticosteroids"}, "r": "A", "e": {"correcta": "Motion sickness is treated with H1 receptor blockers (1st generation antihistamines like diphenhydramine and meclizine) and M1 muscarinic receptor blockers (scopolamine), which target the vestibular pathway.", "incorrectas": {"B": "5-HT3 and D2 antagonists (e.g., ondansetron, metoclopramide) target chemotherapy-induced and GI-mediated nausea pathways, not the vestibular pathway specifically.", "C": "PPIs and H2 blockers treat acid-related conditions, not motion sickness.", "D": "NK1 antagonists (e.g., aprepitant) are used for chemotherapy-induced nausea, and corticosteroids are adjunctive antiemetics, not first-line motion sickness treatments."}}}, {"id": "anking-gastrointestinal-pharmacology-374", "fuente": "anking", "tema": 40, "anki": "1461600965249", "q": "Metoclopramide, a D2 antagonist, is contraindicated in patients with which condition?", "o": {"A": "Small bowel obstruction", "B": "Peptic ulcer disease", "C": "Gastroesophageal reflux disease", "D": "Chronic constipation"}, "r": "A", "e": {"correcta": "Metoclopramide is a prokinetic agent that increases GI motility, which is contraindicated in small bowel obstruction because it can worsen the obstruction and risk perforation; it is also contraindicated in Parkinson disease due to D2 receptor blockade.", "incorrectas": {"B": "Peptic ulcer disease is not a contraindication to metoclopramide; it is sometimes used to improve gastric emptying.", "C": "GERD is actually an indication for metoclopramide's prokinetic effects, not a contraindication.", "D": "Chronic constipation is not a contraindication; metoclopramide's prokinetic action could theoretically help motility, though it's not first-line."}}}, {"id": "anking-gastrointestinal-pharmacology-375", "fuente": "anking", "tema": 40, "anki": "1461601013250", "q": "Metoclopramide can cause which GI side effect as a result of its prokinetic effects?", "o": {"A": "Diarrhea", "B": "Constipation", "C": "GI bleeding", "D": "Malabsorption"}, "r": "A", "e": {"correcta": "Because metoclopramide increases GI motility (prokinetic effect) by antagonizing D2 receptors and enhancing acetylcholine release, it can cause diarrhea.", "incorrectas": {"B": "Constipation would be the opposite effect of a prokinetic agent; metoclopramide increases motility rather than slowing it.", "C": "GI bleeding is not a recognized prokinetic side effect of metoclopramide.", "D": "Malabsorption is not a typical consequence of increased GI motility from metoclopramide."}}}, {"id": "anking-gastrointestinal-pharmacology-376", "fuente": "anking", "tema": 40, "anki": "1461601301851", "q": "Side effects of metoclopramide affecting mood and alertness, resulting from central D2 blockade, include which two effects?", "o": {"A": "Drowsiness and depression", "B": "Insomnia and euphoria", "C": "Anxiety and mania", "D": "Hallucinations and agitation"}, "r": "A", "e": {"correcta": "Metoclopramide's central D2 receptor blockade can cause drowsiness and depression, along with extrapyramidal symptoms and risk of tardive dyskinesia with prolonged use.", "incorrectas": {"B": "Insomnia and euphoria are not typical effects of D2 blockade; D2 antagonism generally causes sedation, not euphoria or stimulation.", "C": "Anxiety and mania are not the classic central side effects associated with metoclopramide's D2 blockade.", "D": "Hallucinations and agitation are more consistent with dopamine excess or anticholinergic toxicity, not D2 blockade, which tends to cause sedation and flattened affect."}}}, {"id": "anking-immunosuppressants-377", "fuente": "anking", "tema": 41, "anki": "1461794652364", "q": "Interferon alpha may be used to treat which malignancy caused by HHV-8?", "o": {"A": "Kaposi sarcoma", "B": "Burkitt lymphoma", "C": "Nasopharyngeal carcinoma", "D": "Hepatocellular carcinoma"}, "r": "A", "e": {"correcta": "Interferon alpha has antiviral and antiproliferative activity and is used to treat Kaposi sarcoma, which is caused by HHV-8.", "incorrectas": {"B": "Burkitt lymphoma is associated with EBV and MYC translocation, not typically treated with interferon alpha for HHV-8-related disease.", "C": "Nasopharyngeal carcinoma is associated with EBV, not HHV-8.", "D": "Hepatocellular carcinoma is associated with HBV/HCV chronic infection, not HHV-8."}}}, {"id": "anking-immunosuppressants-378", "fuente": "anking", "tema": 41, "anki": "1461794663555", "q": "Interferon alpha may be used to treat which lesion caused by HPV?", "o": {"A": "Condyloma acuminata", "B": "Molluscum contagiosum", "C": "Seborrheic keratosis", "D": "Actinic keratosis"}, "r": "A", "e": {"correcta": "Condyloma acuminata (genital warts) are caused by HPV and can be treated with interferon alpha, in addition to other modalities like imiquimod or podophyllin.", "incorrectas": {"B": "Molluscum contagiosum is caused by a poxvirus, not HPV.", "C": "Seborrheic keratosis is a benign, non-viral proliferation of epidermal keratinocytes.", "D": "Actinic keratosis is a premalignant lesion from UV damage, unrelated to HPV."}}}, {"id": "anking-immunosuppressants-379", "fuente": "anking", "tema": 41, "anki": "1461794674850", "q": "Interferon alpha may be used to treat which type of carcinoma?", "o": {"A": "Renal cell carcinoma", "B": "Hepatocellular carcinoma", "C": "Squamous cell carcinoma", "D": "Papillary thyroid carcinoma"}, "r": "A", "e": {"correcta": "Interferon alpha has been used as an immunotherapy for renal cell carcinoma, leveraging its immunomodulatory and antiproliferative effects.", "incorrectas": {"B": "Hepatocellular carcinoma is not a standard indication for interferon alpha as antitumor therapy.", "C": "Squamous cell carcinoma is not treated with interferon alpha.", "D": "Papillary thyroid carcinoma is treated with surgery and radioactive iodine, not interferon alpha."}}}, {"id": "anking-immunosuppressants-380", "fuente": "anking", "tema": 41, "anki": "1461794689858", "q": "Which hepatitis drug commonly causes flu-like symptoms (headache, fever, malaise, myalgia) as a side effect, typically within 6 hours of administration?", "o": {"A": "Interferon alpha", "B": "Ribavirin", "C": "Sofosbuvir", "D": "Entecavir"}, "r": "A", "e": {"correcta": "Interferon alpha classically causes flu-like symptoms early in treatment, along with neutropenia in up to 30% of patients during the first week.", "incorrectas": {"B": "Ribavirin's classic side effect is dose-dependent hemolytic anemia, not flu-like symptoms.", "C": "Sofosbuvir is generally well tolerated and not known for flu-like reactions.", "D": "Entecavir is a nucleoside analog used for hepatitis B, not associated with flu-like symptoms."}}}, {"id": "anking-immunosuppressants-381", "fuente": "anking", "tema": 41, "anki": "1461794711294", "q": "Chronic interferon alpha therapy may result in which adverse effect, causing mood disorders (e.g., depression) and confusion?", "o": {"A": "Neurotoxicity", "B": "Hepatotoxicity", "C": "Nephrotoxicity", "D": "Cardiotoxicity"}, "r": "A", "e": {"correcta": "Chronic interferon alpha therapy can cause neurotoxicity, manifesting as depression, confusion, fatigue, tinnitus, retinopathy, and pneumonitis.", "incorrectas": {"B": "Hepatotoxicity would present with liver dysfunction, not mood/cognitive changes.", "C": "Nephrotoxicity would present with renal impairment, not psychiatric symptoms.", "D": "Cardiotoxicity would present with cardiac dysfunction, not confusion or depression."}}}, {"id": "anking-immunosuppressants-382", "fuente": "anking", "tema": 41, "anki": "1461794728973", "q": "Which hepatitis drug has myelosuppression as a possible side effect, requiring caution when combined with other myelosuppressive drugs like zidovudine?", "o": {"A": "Interferon alpha", "B": "Ribavirin", "C": "Simeprevir", "D": "Sofosbuvir"}, "r": "A", "e": {"correcta": "Interferon alpha can cause myelosuppression, so caution is needed when co-administering other myelosuppressive agents such as zidovudine.", "incorrectas": {"B": "Ribavirin's main hematologic toxicity is hemolytic anemia rather than myelosuppression per se.", "C": "Simeprevir is a protease inhibitor without a classic myelosuppressive profile.", "D": "Sofosbuvir is a polymerase inhibitor not known for myelosuppression."}}}, {"id": "anking-immunosuppressants-383", "fuente": "anking", "tema": 41, "anki": "1461794778292", "q": "Which type of interferon is associated with drug-induced lupus?", "o": {"A": "Interferon alpha", "B": "Interferon beta", "C": "Interferon gamma", "D": "Interferon lambda"}, "r": "A", "e": {"correcta": "Interferon alpha is associated with drug-induced lupus, an important adverse effect to recognize during therapy.", "incorrectas": {"B": "Interferon beta is used in multiple sclerosis and is not classically linked to drug-induced lupus.", "C": "Interferon gamma is used in chronic granulomatous disease and is not linked to drug-induced lupus.", "D": "Interferon lambda is not a classically described cause of drug-induced lupus in this context."}}}, {"id": "anking-immunosuppressants-384", "fuente": "anking", "tema": 41, "anki": "1461797595100", "q": "What was the traditional standard treatment regimen for hepatitis C?", "o": {"A": "Once weekly pegylated-interferon alpha with daily oral ribavirin", "B": "Daily oral sofosbuvir monotherapy", "C": "Once weekly pegylated-interferon alpha with daily lamivudine", "D": "Daily oral entecavir with ribavirin"}, "r": "A", "e": {"correcta": "The traditional standard of care for hepatitis C was once-weekly pegylated-interferon alpha combined with daily oral ribavirin, though this has been largely supplanted by direct-acting antivirals.", "incorrectas": {"B": "Sofosbuvir monotherapy is not the traditional standard; direct-acting antivirals are typically combined and are newer regimens.", "C": "Lamivudine is used for hepatitis B and HIV, not paired with interferon for hepatitis C.", "D": "Entecavir is a hepatitis B drug, not part of the traditional hepatitis C regimen."}}}, {"id": "anking-immunosuppressants-385", "fuente": "anking", "tema": 41, "anki": "1461797617523", "q": "Ribavirin is an analog of which nucleoside?", "o": {"A": "Guanosine", "B": "Adenosine", "C": "Cytidine", "D": "Thymidine"}, "r": "A", "e": {"correcta": "Ribavirin is a guanosine nucleoside analog that, once activated, inhibits viral RNA production.", "incorrectas": {"B": "Adenosine analogs describe other antivirals, not ribavirin's structural class.", "C": "Cytidine analogs (e.g., cytarabine) are a different drug class.", "D": "Thymidine analogs (e.g., zidovudine, stavudine) are structurally distinct from ribavirin."}}}, {"id": "anking-immunosuppressants-386", "fuente": "anking", "tema": 41, "anki": "1461797629482", "q": "What must happen to ribavirin by intracellular enzymes for it to reach its activated nucleotide form?", "o": {"A": "Phosphorylation three times", "B": "Deamination once", "C": "Glucuronidation twice", "D": "Acetylation once"}, "r": "A", "e": {"correcta": "Ribavirin requires triple phosphorylation by intracellular enzymes to become its active nucleotide form, which then inhibits RNA production.", "incorrectas": {"B": "Deamination is not the activation mechanism described for ribavirin.", "C": "Glucuronidation is a phase II metabolic pathway, not how ribavirin is activated.", "D": "Acetylation is not involved in ribavirin's activation to its active form."}}}, {"id": "anking-immunosuppressants-387", "fuente": "anking", "tema": 41, "anki": "1461797649771", "q": "What is a major side effect of ribavirin, occurring in 10-20% of patients?", "o": {"A": "Dose-dependent hemolytic anemia", "B": "Irreversible aplastic anemia", "C": "Thrombocytosis", "D": "Nephrogenic diabetes insipidus"}, "r": "A", "e": {"correcta": "Ribavirin classically causes dose-dependent hemolytic anemia in about 10-20% of patients.", "incorrectas": {"B": "Aplastic anemia is not the classic ribavirin toxicity; it is more associated with other myelosuppressive drugs.", "C": "Thrombocytosis (elevated platelets) is not a described ribavirin effect; it causes anemia, not platelet elevation.", "D": "Nephrogenic diabetes insipidus is caused by drugs like lithium, not ribavirin."}}}, {"id": "anking-immunosuppressants-388", "fuente": "anking", "tema": 41, "anki": "1461797660332", "q": "Ribavirin is contraindicated in which population due to which type of effect?", "o": {"A": "Pregnant women, due to teratogenic effects", "B": "Elderly patients, due to nephrotoxic effects", "C": "Diabetic patients, due to hyperglycemic effects", "D": "Asthmatic patients, due to bronchospastic effects"}, "r": "A", "e": {"correcta": "Ribavirin is teratogenic and contraindicated in pregnant women, as well as in individuals of childbearing potential not using contraception.", "incorrectas": {"B": "Ribavirin's key contraindication relates to teratogenicity, not nephrotoxicity in the elderly.", "C": "Hyperglycemia is not the described contraindication for ribavirin.", "D": "Bronchospasm in asthmatics is not the classic contraindication for ribavirin."}}}, {"id": "anking-immunosuppressants-389", "fuente": "anking", "tema": 41, "anki": "1461797674252", "q": "In addition to hepatitis C, what other virus is ribavirin classically used to treat?", "o": {"A": "Respiratory syncytial virus (RSV)", "B": "Influenza virus", "C": "Cytomegalovirus (CMV)", "D": "Varicella-zoster virus (VZV)"}, "r": "A", "e": {"correcta": "Ribavirin is classically used to treat RSV, though this use has largely been replaced by palivizumab, especially in children.", "incorrectas": {"B": "Influenza is treated with neuraminidase inhibitors like oseltamivir, not classically ribavirin.", "C": "CMV is treated with ganciclovir/valganciclovir, not ribavirin.", "D": "VZV is treated with acyclovir/valacyclovir, not ribavirin."}}}, {"id": "anking-immunosuppressants-390", "fuente": "anking", "tema": 41, "anki": "1461797710362", "q": "Sofosbuvir and simeprevir are not used as monotherapies for HCV, but rather as part of a regimen that classically includes which additional agent(s)?", "o": {"A": "Ribavirin with or without pegylated-interferon alpha", "B": "Zidovudine with lamivudine", "C": "Acyclovir with foscarnet", "D": "Entecavir with tenofovir"}, "r": "A", "e": {"correcta": "Sofosbuvir and simeprevir are used in HCV regimens combined with ribavirin, with or without pegylated-interferon alpha.", "incorrectas": {"B": "Zidovudine and lamivudine are antiretrovirals for HIV, unrelated to HCV regimens.", "C": "Acyclovir and foscarnet are used for herpesvirus infections, not HCV.", "D": "Entecavir and tenofovir are hepatitis B (and HIV, for tenofovir) agents, not part of HCV regimens with sofosbuvir/simeprevir."}}}, {"id": "anking-immunosuppressants-391", "fuente": "anking", "tema": 41, "anki": "1461797767925", "q": "Second generation NS3/NS4A protease inhibitors and NS5A inhibitors are under investigation to create HCV regimens that avoid the need for which administration?", "o": {"A": "Interferon/ribavirin", "B": "Corticosteroids", "C": "Intravenous immunoglobulin", "D": "Antiretroviral therapy"}, "r": "A", "e": {"correcta": "Newer direct-acting antivirals (NS3/NS4A and NS5A inhibitors) aim to create interferon/ribavirin-free regimens for HCV, reducing the toxicity burden of older therapy.", "incorrectas": {"B": "Corticosteroids are not part of standard HCV treatment regimens.", "C": "IVIG is not relevant to HCV antiviral regimens.", "D": "Antiretroviral therapy is for HIV, not the interferon/ribavirin combination being replaced in HCV treatment."}}}, {"id": "anking-immunosuppressants-392", "fuente": "anking", "tema": 41, "anki": "1462061251872", "q": "Glucocorticoids may have anti-inflammatory effects via inhibition of the release of which two mediators from mast cells and platelets?", "o": {"A": "Histamine and serotonin", "B": "Bradykinin and substance P", "C": "Prostaglandins and leukotrienes only", "D": "Complement C3a and C5a"}, "r": "A", "e": {"correcta": "Glucocorticoids inhibit the release of histamine and serotonin from mast cells and platelets, contributing to their anti-inflammatory effects.", "incorrectas": {"B": "Bradykinin and substance P are not the mediators specifically described as inhibited by glucocorticoids in this context.", "C": "While glucocorticoids do reduce prostaglandins/leukotrienes via phospholipase A2 inhibition, this option does not match the specific histamine/serotonin mechanism asked about.", "D": "Complement anaphylatoxins C3a/C5a are not the mediators referenced in this glucocorticoid mechanism."}}}, {"id": "anking-immunosuppressants-393", "fuente": "anking", "tema": 41, "anki": "1463442971546", "q": "Breast cancer with Her2/neu amplification is associated with a good response to which targeted therapy?", "o": {"A": "Trastuzumab (Herceptin)", "B": "Tamoxifen", "C": "Rituximab", "D": "Imatinib"}, "r": "A", "e": {"correcta": "Trastuzumab is a monoclonal antibody targeting the HER2/neu receptor and is highly effective in HER2-amplified breast cancers.", "incorrectas": {"B": "Tamoxifen targets the estrogen receptor and is used for ER-positive breast cancer, not specifically HER2-amplified disease.", "C": "Rituximab targets CD20 and is used for B-cell lymphomas, not HER2-positive breast cancer.", "D": "Imatinib targets BCR-ABL/c-KIT/PDGFR and is used in CML and GIST, not HER2-positive breast cancer."}}}, {"id": "anking-immunosuppressants-394", "fuente": "anking", "tema": 41, "anki": "1463881872804", "q": "Dexamethasone, hydrocortisone, and prednisone are all examples of which drug class?", "o": {"A": "Glucocorticoids", "B": "NSAIDs", "C": "Calcineurin inhibitors", "D": "mTOR inhibitors"}, "r": "A", "e": {"correcta": "Dexamethasone, hydrocortisone, and prednisone are all glucocorticoids, a class often recognizable by the '-sone' suffix.", "incorrectas": {"B": "NSAIDs (e.g., ibuprofen, naproxen) work via COX inhibition, unlike these steroid drugs.", "C": "Calcineurin inhibitors (e.g., cyclosporine, tacrolimus) are immunosuppressants acting on T cells, distinct from corticosteroids.", "D": "mTOR inhibitors (e.g., sirolimus) are a distinct class of immunosuppressants, not corticosteroids."}}}, {"id": "anking-cellular-immunology-395", "fuente": "anking", "tema": 42, "anki": "1486866351517", "q": "Which type of immunity is mediated by T cells and B cells?", "o": {"A": "Innate immunity", "B": "Adaptive immunity", "C": "Passive immunity acquired transplacentally only", "D": "Complement-mediated immunity"}, "r": "B", "e": {"correcta": "Adaptive (acquired) immunity is mediated by antigen-specific T lymphocytes and B lymphocytes, which generate highly specific responses and immunologic memory.", "incorrectas": {"A": "Innate immunity relies on nonspecific mechanisms (phagocytes, complement, barriers), not T or B cells.", "C": "Passive immunity refers to transfer of preformed antibodies, not a cell-mediated system, and is not limited to a single route.", "D": "Complement is part of the innate immune system, not the T/B cell adaptive system."}}}, {"id": "anking-cellular-immunology-396", "fuente": "anking", "tema": 42, "anki": "1486867490403", "q": "Which type of immunity includes circulating antibodies?", "o": {"A": "Innate immunity", "B": "Adaptive immunity", "C": "Cellular immunity only", "D": "Nonspecific humoral immunity"}, "r": "B", "e": {"correcta": "Circulating antibodies are produced by B cells/plasma cells as part of adaptive (humoral) immunity, providing antigen-specific protection.", "incorrectas": {"A": "Innate immunity does not use antibodies; it relies on preformed nonspecific defenses.", "C": "Cellular immunity refers to T cell-mediated responses, not antibody production.", "D": "Antibody-mediated immunity is highly specific, not nonspecific, so this term is inaccurate."}}}, {"id": "anking-cellular-immunology-397", "fuente": "anking", "tema": 42, "anki": "1486867495023", "q": "Which type of immunity includes macrophages and monocytes?", "o": {"A": "Adaptive immunity", "B": "Innate immunity", "C": "Humoral immunity", "D": "Memory immunity"}, "r": "B", "e": {"correcta": "Macrophages and monocytes are phagocytic cells of the innate immune system, providing rapid, nonspecific defense against pathogens.", "incorrectas": {"A": "Adaptive immunity is mediated by antigen-specific T and B lymphocytes, not phagocytes.", "C": "Humoral immunity refers to antibody-based adaptive responses, not phagocytic cells.", "D": "Memory immunity is a feature of adaptive immunity, not macrophages/monocytes."}}}, {"id": "anking-cellular-immunology-398", "fuente": "anking", "tema": 42, "anki": "1486867499358", "q": "Which type of immunity includes neutrophils and dendritic cells?", "o": {"A": "Adaptive immunity", "B": "Innate immunity", "C": "Humoral immunity", "D": "Passive immunity"}, "r": "B", "e": {"correcta": "Neutrophils and dendritic cells are components of the innate immune system; dendritic cells also bridge innate and adaptive immunity by presenting antigen.", "incorrectas": {"A": "Adaptive immunity involves T and B lymphocytes with antigen specificity, not neutrophils.", "C": "Humoral immunity refers to antibody production by B cells, not neutrophils/dendritic cells.", "D": "Passive immunity refers to transfer of preformed antibodies, unrelated to these cell types."}}}, {"id": "anking-cellular-immunology-399", "fuente": "anking", "tema": 42, "anki": "1486867503989", "q": "NK (natural killer) cells are classified as part of which arm of the immune system?", "o": {"A": "Adaptive immunity", "B": "Innate immunity", "C": "Humoral immunity exclusively", "D": "Passive immunity"}, "r": "B", "e": {"correcta": "Although NK cells arise from lymphoid precursors, they lack antigen-specific receptors and memory formation, so they are classified as part of innate immunity.", "incorrectas": {"A": "Adaptive immunity requires antigen-specific receptors (like T/B cells) and memory, which NK cells lack.", "C": "Humoral immunity refers to antibody-mediated responses, not NK cell cytotoxic activity.", "D": "Passive immunity involves transfer of preformed antibodies, not NK cell function."}}}, {"id": "anking-cellular-immunology-400", "fuente": "anking", "tema": 42, "anki": "1486867509134", "q": "The complement system is a component of which type of immunity?", "o": {"A": "Adaptive immunity", "B": "Innate immunity", "C": "Cell-mediated immunity", "D": "Memory-based immunity"}, "r": "B", "e": {"correcta": "The complement system consists of plasma proteins that act nonspecifically to opsonize pathogens, promote inflammation, and lyse cells, making it part of innate immunity.", "incorrectas": {"A": "Adaptive immunity is antigen-specific and mediated by lymphocytes, unlike complement.", "C": "Cell-mediated immunity refers to T cell responses, not the complement protein cascade.", "D": "Complement does not generate immunologic memory, a hallmark of adaptive immunity."}}}, {"id": "anking-cellular-immunology-401", "fuente": "anking", "tema": 42, "anki": "1486867513384", "q": "Innate immunity is best described as which type of immune response?", "o": {"A": "Highly specific", "B": "Non-specific", "C": "Antigen-specific with memory", "D": "Clonally selected"}, "r": "B", "e": {"correcta": "Innate immunity provides a broad, non-specific defense using pattern recognition of general microbial features rather than specific antigens.", "incorrectas": {"A": "High specificity is a hallmark of adaptive, not innate, immunity.", "C": "Antigen specificity and memory formation are features of adaptive immunity.", "D": "Clonal selection applies to lymphocytes in adaptive immunity, not innate immune cells."}}}, {"id": "anking-cellular-immunology-402", "fuente": "anking", "tema": 42, "anki": "1486867532110", "q": "Which type of immunity mounts a response within minutes to hours of pathogen exposure?", "o": {"A": "Adaptive immunity", "B": "Innate immunity", "C": "Memory-based secondary response", "D": "Antibody-mediated immunity"}, "r": "B", "e": {"correcta": "Innate immunity acts rapidly (minutes to hours) using preformed defenses like phagocytes, complement, and physical barriers.", "incorrectas": {"A": "Adaptive immunity takes days to develop because it requires clonal expansion of specific lymphocytes.", "C": "A memory-based secondary response is part of adaptive immunity and is faster on re-exposure, but still slower than the immediate innate response and not the first-line rapid mechanism described here.", "D": "Antibody-mediated immunity is a slower, adaptive process requiring B cell activation and antibody production."}}}, {"id": "anking-cellular-immunology-403", "fuente": "anking", "tema": 42, "anki": "1486867606359", "q": "Which type of immunity is characterized by limited diversity of its receptors/responses?", "o": {"A": "Adaptive immunity", "B": "Innate immunity", "C": "Immunoglobulin-based immunity", "D": "Somatically recombined immunity"}, "r": "B", "e": {"correcta": "Innate immunity uses a limited, germline-encoded set of pattern recognition receptors, giving it restricted diversity compared to adaptive immunity.", "incorrectas": {"A": "Adaptive immunity has extensive diversity due to somatic recombination of antigen receptor genes.", "C": "Immunoglobulin-based immunity refers to antibodies, which are highly diverse, unlike innate immunity.", "D": "Somatic recombination generates the vast diversity seen in adaptive, not innate, immune receptors."}}}, {"id": "anking-cellular-immunology-404", "fuente": "anking", "tema": 42, "anki": "1486867612235", "q": "Adaptive immunity is best described as which type of immune response?", "o": {"A": "Non-specific", "B": "Highly specific", "C": "Broadly reactive to pathogen-associated molecular patterns", "D": "Limited in diversity"}, "r": "B", "e": {"correcta": "Adaptive immunity generates antigen receptors through somatic recombination, producing a highly specific response tailored to particular antigens.", "incorrectas": {"A": "Non-specific responses characterize innate immunity, not adaptive immunity.", "C": "Recognition of pathogen-associated molecular patterns (PAMPs) is a feature of innate immune pattern recognition receptors.", "D": "Adaptive immunity has extensive, not limited, diversity due to receptor gene rearrangement."}}}, {"id": "anking-cellular-immunology-405", "fuente": "anking", "tema": 42, "anki": "1486867623104", "q": "Which type of immunity develops over long periods (days) after exposure?", "o": {"A": "Innate immunity", "B": "Adaptive immunity", "C": "Complement-mediated immunity", "D": "Barrier immunity"}, "r": "B", "e": {"correcta": "Adaptive immunity requires antigen presentation, lymphocyte activation, and clonal expansion, which takes days to develop, though subsequent memory responses are faster.", "incorrectas": {"A": "Innate immunity responds within minutes to hours, not over long periods.", "C": "Complement-mediated immunity is part of the innate system and acts rapidly.", "D": "Barrier immunity (skin, mucosa) is a constitutive innate defense present before exposure."}}}, {"id": "anking-cellular-immunology-406", "fuente": "anking", "tema": 42, "anki": "1486867628723", "q": "Which type of immunity has extensive diversity in its antigen receptors?", "o": {"A": "Innate immunity", "B": "Adaptive immunity", "C": "Complement system", "D": "Physical barrier defenses"}, "r": "B", "e": {"correcta": "Adaptive immunity achieves extensive receptor diversity through somatic recombination (V(D)J recombination) of T cell and B cell receptor genes.", "incorrectas": {"A": "Innate immunity has limited, germline-encoded receptor diversity.", "C": "The complement system consists of plasma proteins, not diverse antigen receptors.", "D": "Physical barriers provide nonspecific protection and do not involve diverse antigen receptors."}}}, {"id": "anking-cellular-immunology-407", "fuente": "anking", "tema": 42, "anki": "1486867633025", "q": "Physical barriers such as skin and mucous membranes are part of which type of immunity?", "o": {"A": "Adaptive immunity", "B": "Innate immunity", "C": "Humoral immunity", "D": "Cell-mediated immunity"}, "r": "B", "e": {"correcta": "Physical barriers like skin and mucous membranes are first-line, non-specific defenses that are part of innate immunity.", "incorrectas": {"A": "Adaptive immunity involves specific lymphocyte responses, not physical barriers.", "C": "Humoral immunity refers to antibody-mediated defense, not physical barriers.", "D": "Cell-mediated immunity refers to T cell responses, not structural barriers."}}}, {"id": "anking-cellular-immunology-408", "fuente": "anking", "tema": 42, "anki": "1486867644687", "q": "Physiologic barriers such as temperature and pH are part of which type of immunity?", "o": {"A": "Adaptive immunity", "B": "Innate immunity", "C": "Antibody-mediated immunity", "D": "Memory immunity"}, "r": "B", "e": {"correcta": "Physiologic barriers, such as body temperature and low pH (e.g., gastric acid), are non-specific innate defenses that inhibit pathogen survival.", "incorrectas": {"A": "Adaptive immunity relies on specific lymphocyte recognition, not physiologic conditions.", "C": "Antibody-mediated immunity involves specific immunoglobulins, not physiologic barriers.", "D": "Memory immunity is a feature of adaptive immunity involving memory lymphocytes."}}}, {"id": "anking-cellular-immunology-409", "fuente": "anking", "tema": 42, "anki": "1486867649389", "q": "Chemical barriers such as lysozyme and defensins are part of which type of immunity?", "o": {"A": "Adaptive immunity", "B": "Innate immunity", "C": "Cell-mediated immunity", "D": "Clonal immunity"}, "r": "B", "e": {"correcta": "Lysozyme and defensins are antimicrobial chemical barriers that act non-specifically as part of the innate immune system.", "incorrectas": {"A": "Adaptive immunity relies on lymphocyte specificity, not antimicrobial chemical secretions.", "C": "Cell-mediated immunity refers to T cell responses, not chemical antimicrobial substances.", "D": "Clonal immunity is not a standard immunologic term describing barrier defenses; clonal selection applies to adaptive lymphocytes."}}}, {"id": "anking-cellular-immunology-410", "fuente": "anking", "tema": 42, "anki": "1486867654077", "q": "Which immunoglobulin isotypes are co-expressed on the surface of mature, naive B cells?", "o": {"A": "IgG and IgA", "B": "IgM and IgD", "C": "IgE and IgG", "D": "IgA and IgM"}, "r": "B", "e": {"correcta": "Mature, naive B cells co-express surface IgM and IgD, which serve as the B cell receptor before class switching occurs upon antigen encounter.", "incorrectas": {"A": "IgG and IgA are isotypes produced after class switching in activated/memory B cells, not on naive B cells.", "C": "IgE is produced after class switching (often in allergic/parasitic responses), not expressed on naive B cells.", "D": "IgA is a class-switched isotype found in mucosal secretions, not co-expressed with IgM on naive B cells."}}}, {"id": "anking-lymphoid-structures-411", "fuente": "anking", "tema": 43, "anki": "1471466878440", "q": "Interstitial fluid can enter lymphatic vessels but cannot flow back out due to which structural feature?", "o": {"A": "One-way flap valves", "B": "Continuous tight junctions between endothelial cells", "C": "A thick basement membrane", "D": "Smooth muscle sphincters"}, "r": "A", "e": {"correcta": "Lymphatic capillaries have overlapping endothelial cells that act as one-way flap valves, allowing interstitial fluid to enter but preventing its retrograde flow out of the vessel.", "incorrectas": {"B": "Tight junctions would prevent fluid entry altogether, which is not how lymphatic capillaries function.", "C": "Lymphatic capillaries actually lack a continuous basement membrane, which is why they are so permeable to fluid entry.", "D": "Sphincters are not the mechanism responsible for unidirectional flow at the level of lymphatic capillaries."}}}, {"id": "anking-lymphoid-structures-412", "fuente": "anking", "tema": 43, "anki": "1481335224891", "q": "What is the medical term for enlarged lymph nodes?", "o": {"A": "Lymphadenopathy", "B": "Lymphangitis", "C": "Splenomegaly", "D": "Lymphedema"}, "r": "A", "e": {"correcta": "Lymphadenopathy (LAD) is the general term for enlargement of lymph nodes, which can result from infection, inflammation, or malignancy.", "incorrectas": {"B": "Lymphangitis refers to inflammation of lymphatic vessels, not enlargement of nodes.", "C": "Splenomegaly refers to enlargement of the spleen, a different organ.", "D": "Lymphedema refers to tissue swelling due to lymphatic fluid accumulation, not node enlargement."}}}, {"id": "anking-lymphoid-structures-413", "fuente": "anking", "tema": 43, "anki": "1481335233468", "q": "What type of lymphadenopathy is typically seen in lymph nodes draining a region of acute infection?", "o": {"A": "Painful", "B": "Painless", "C": "Rubbery", "D": "Matted"}, "r": "A", "e": {"correcta": "Acute infection causes acute lymphadenitis, in which rapid node enlargement stretches the capsule and produces pain and tenderness.", "incorrectas": {"B": "Painless lymphadenopathy is more characteristic of chronic inflammation or malignancy rather than acute infection.", "C": "A rubbery texture is classically described with lymphoma, not acute infectious lymphadenitis.", "D": "Matted (fixed, non-mobile) nodes suggest malignant infiltration, not acute infection."}}}, {"id": "anking-lymphoid-structures-414", "fuente": "anking", "tema": 43, "anki": "1481335242536", "q": "What type of lymphadenopathy is typically seen with chronic inflammation, metastatic carcinoma, or lymphoma?", "o": {"A": "Painless", "B": "Painful", "C": "Fluctuant", "D": "Erythematous"}, "r": "A", "e": {"correcta": "Chronic inflammation, metastatic carcinoma, and lymphoma cause slow, indolent node enlargement without acute capsular stretching, making the nodes typically painless.", "incorrectas": {"B": "Painful nodes are more typical of acute infectious processes rather than chronic or malignant causes.", "C": "Fluctuance suggests a fluid-filled abscess, not the firm nodes of chronic disease or malignancy.", "D": "Erythema over the node is a sign of acute superficial infection, not chronic disease or malignancy."}}}, {"id": "anking-lymphoid-structures-415", "fuente": "anking", "tema": 43, "anki": "1481335246915", "q": "Proliferation of the B cell compartment of lymph nodes (e.g., in rheumatoid arthritis or early HIV infection) causes what type of hyperplasia?", "o": {"A": "Follicular hyperplasia", "B": "Paracortical hyperplasia", "C": "Sinus histiocytosis", "D": "Medullary hyperplasia"}, "r": "A", "e": {"correcta": "B cells reside in the follicles of the lymph node cortex, so B cell proliferation produces follicular hyperplasia, as seen in rheumatoid arthritis and early HIV infection.", "incorrectas": {"B": "Paracortical hyperplasia results from T cell proliferation, not B cell proliferation.", "C": "Sinus histiocytosis reflects macrophage/histiocyte proliferation in the medullary sinuses, typically in nodes draining cancer.", "D": "Medullary hyperplasia is not the standard term used for lymph node reactive changes."}}}, {"id": "anking-lymphoid-structures-416", "fuente": "anking", "tema": 43, "anki": "1481335256235", "q": "Proliferation of the T cell compartment of lymph nodes (e.g., in viral infections such as EBV mononucleosis) causes what type of hyperplasia?", "o": {"A": "Paracortical hyperplasia", "B": "Follicular hyperplasia", "C": "Sinus histiocytosis", "D": "Cortical hyperplasia"}, "r": "A", "e": {"correcta": "T cells reside in the paracortex of the lymph node, so viral infections like EBV mononucleosis that expand the T cell population cause paracortical hyperplasia.", "incorrectas": {"B": "Follicular hyperplasia results from B cell proliferation in the follicles, not T cell expansion.", "C": "Sinus histiocytosis reflects histiocyte proliferation in nodes draining a tumor, not a viral T cell response.", "D": "Cortical hyperplasia is not the specific term used; the T cell region is termed the paracortex."}}}, {"id": "anking-lymphoid-structures-417", "fuente": "anking", "tema": 43, "anki": "1481335266202", "q": "Hyperplasia of sinus histiocytes is seen in lymph nodes draining a tissue that has what condition?", "o": {"A": "Cancer", "B": "Acute bacterial infection", "C": "Autoimmune disease", "D": "Viral infection"}, "r": "A", "e": {"correcta": "Sinus histiocytosis (expansion of macrophages in the medullary sinuses) is a reactive change seen in lymph nodes that drain a region containing cancer, as histiocytes respond to tumor antigens/debris.", "incorrectas": {"B": "Acute bacterial infection more classically produces paracortical or follicular hyperplasia with neutrophilic infiltration, not primarily sinus histiocytosis.", "C": "Autoimmune disease classically causes follicular hyperplasia from B cell activation, not sinus histiocytosis.", "D": "Viral infections classically cause paracortical hyperplasia due to T cell expansion, not sinus histiocytosis."}}}, {"id": "anking-lymphoid-structures-418", "fuente": "anking", "tema": 43, "anki": "1481335274780", "q": "What term describes neoplastic proliferations of lymphoid cells that form a mass, arising in a lymph node or extranodal tissue?", "o": {"A": "Lymphomas", "B": "Leukemias", "C": "Sarcomas", "D": "Lymphadenitis"}, "r": "A", "e": {"correcta": "Lymphomas are neoplastic proliferations of lymphoid cells that form a discrete mass, which may arise within a lymph node or in extranodal tissue.", "incorrectas": {"B": "Leukemias are neoplastic proliferations of hematopoietic cells that typically involve the bone marrow and blood diffusely rather than forming a discrete mass.", "C": "Sarcomas are malignancies of mesenchymal (connective tissue) origin, not lymphoid cells.", "D": "Lymphadenitis is inflammation of a lymph node, not a neoplastic process."}}}, {"id": "anking-lymphoid-structures-419", "fuente": "anking", "tema": 43, "anki": "1481335453994", "q": "Which region of the lymph node is immediately adjacent to the follicle?", "o": {"A": "Mantle zone", "B": "Paracortex", "C": "Medullary sinus", "D": "Subcapsular sinus"}, "r": "A", "e": {"correcta": "The mantle zone is the layer of small, resting B lymphocytes that surrounds the germinal center of a lymphoid follicle, making it immediately adjacent to the follicle.", "incorrectas": {"B": "The paracortex is the T cell region located deeper in the node, not immediately surrounding the follicle.", "C": "The medullary sinus is located in the medulla, the innermost part of the node, not adjacent to the follicle.", "D": "The subcapsular sinus lies just beneath the capsule, receiving afferent lymph, and is not specifically adjacent to the follicle."}}}, {"id": "anking-lymphoid-structures-420", "fuente": "anking", "tema": 43, "anki": "1482971264299", "q": "Which embryological germ layer gives rise to the spleen?", "o": {"A": "Mesoderm", "B": "Endoderm", "C": "Ectoderm", "D": "Neural crest"}, "r": "A", "e": {"correcta": "The spleen arises from mesenchymal cells within the dorsal mesentery of the stomach, making it a mesodermal derivative, and becomes a functional lymphatic organ by week 23 of gestation.", "incorrectas": {"B": "Endoderm gives rise to the gut lining and associated glandular organs (e.g., liver, pancreas), not the spleen.", "C": "Ectoderm gives rise to skin and neural tissue, not the spleen.", "D": "Neural crest gives rise to structures like peripheral neurons and melanocytes, not the spleen."}}}, {"id": "anking-lymphoid-structures-421", "fuente": "anking", "tema": 43, "anki": "1482971271910", "q": "The blood supply to the spleen (via the splenic artery from the celiac trunk) is derived from which embryonic gut region?", "o": {"A": "Foregut", "B": "Midgut", "C": "Hindgut", "D": "Mesonephros"}, "r": "A", "e": {"correcta": "The splenic artery arises from the celiac trunk, which supplies foregut structures, so the spleen's blood supply is a foregut derivative even though the spleen itself develops from mesoderm.", "incorrectas": {"B": "The midgut is supplied by the superior mesenteric artery, not the celiac trunk/splenic artery.", "C": "The hindgut is supplied by the inferior mesenteric artery, unrelated to the splenic artery.", "D": "The mesonephros is an embryonic kidney structure, not related to gut blood supply classification."}}}, {"id": "anking-lymphoid-structures-422", "fuente": "anking", "tema": 43, "anki": "1486945122632", "q": "Which primary lymphoid organ is the site of immune cell production, with IL-7 serving as a key survival signal for developing cells?", "o": {"A": "Bone marrow", "B": "Thymus", "C": "Spleen", "D": "Lymph node"}, "r": "A", "e": {"correcta": "Bone marrow is the primary site of immune cell production (hematopoiesis), and IL-7 acts as a critical survival signal; impaired IL-7 signaling causes defective T and B cell development, leading to severe combined immunodeficiency (SCID).", "incorrectas": {"B": "The thymus is where T cells mature and undergo selection, but it is not the primary site of overall immune cell production.", "C": "The spleen is a secondary lymphoid organ where mature immune cells respond to blood-borne antigens, not where they are produced.", "D": "Lymph nodes are secondary lymphoid organs involved in antigen presentation, not primary immune cell production."}}}, {"id": "anking-lymphoid-structures-423", "fuente": "anking", "tema": 43, "anki": "1486945125504", "q": "Which primary lymphoid organ is the site of B-cell maturation?", "o": {"A": "Bone marrow", "B": "Thymus", "C": "Spleen", "D": "Tonsils"}, "r": "A", "e": {"correcta": "B cells both originate and mature in the bone marrow, which is why it is classified as a primary lymphoid organ for B cell development.", "incorrectas": {"B": "The thymus is the site of T cell maturation, not B cell maturation.", "C": "The spleen is a secondary lymphoid organ where mature B cells encounter antigen, not where they mature.", "D": "Tonsils are secondary lymphoid tissue involved in mucosal immunity, not primary B cell maturation."}}}, {"id": "anking-lymphoid-structures-424", "fuente": "anking", "tema": 43, "anki": "1486945128758", "q": "Which primary lymphoid organ is the site of T-cell differentiation and maturation?", "o": {"A": "Thymus", "B": "Bone marrow", "C": "Spleen", "D": "Lymph node"}, "r": "A", "e": {"correcta": "T cell precursors originate in the bone marrow but migrate to the thymus, where they differentiate and mature through positive and negative selection.", "incorrectas": {"B": "Bone marrow is the site of T cell precursor origin and B cell maturation, not T cell differentiation itself.", "C": "The spleen is a secondary lymphoid organ where mature T cells respond to antigen, not where they mature.", "D": "Lymph nodes are secondary lymphoid organs, not sites of primary T cell maturation."}}}, {"id": "anking-lymphoid-structures-425", "fuente": "anking", "tema": 43, "anki": "1486945131833", "q": "Which class of lymphoid organs (e.g., spleen, lymph nodes, tonsils, Peyer patches) allows immune cells to react with antigen?", "o": {"A": "Secondary lymphoid organs", "B": "Primary lymphoid organs", "C": "Central lymphoid organs", "D": "Mucosal barrier organs"}, "r": "A", "e": {"correcta": "Secondary lymphoid organs, including the spleen, lymph nodes, tonsils, and Peyer patches, are the sites where mature immune cells encounter and react with antigen.", "incorrectas": {"B": "Primary lymphoid organs (bone marrow, thymus) are the sites of lymphocyte production and maturation, not antigen encounter.", "C": "\"Central lymphoid organs\" is essentially a synonym used for primary lymphoid organs, not the antigen-reactive secondary organs.", "D": "\"Mucosal barrier organs\" is not the standard classification term used for these antigen-encountering lymphoid structures."}}}, {"id": "anking-lymphoid-structures-426", "fuente": "anking", "tema": 43, "anki": "1486945137995", "q": "Antigens are brought into a lymph node via which type of lymphatic vessel?", "o": {"A": "Afferent lymphatics", "B": "Efferent lymphatics", "C": "Lymphatic trunks", "D": "Thoracic duct"}, "r": "A", "e": {"correcta": "Afferent lymphatics carry lymph containing antigen into the lymph node through the subcapsular sinus; a node has many afferent vessels but typically only one or a few efferent vessels.", "incorrectas": {"B": "Efferent lymphatics carry filtered lymph away from the node, not into it.", "C": "Lymphatic trunks are larger vessels that collect lymph from multiple regional nodes, not the vessels delivering antigen into an individual node.", "D": "The thoracic duct is the major lymphatic duct draining most of the body into the venous system, not the vessel delivering antigen into a specific node."}}}, {"id": "anking-lymphoid-structures-427", "fuente": "anking", "tema": 43, "anki": "1486945149721", "q": "The outer cortex of a lymph node contains aggregates of cells called what?", "o": {"A": "Follicles", "B": "Paracortex", "C": "Medullary cords", "D": "Sinusoids"}, "r": "A", "e": {"correcta": "The outer cortex of the lymph node contains follicles, which are aggregates of B cells (often with germinal centers during immune activation).", "incorrectas": {"B": "The paracortex is the deeper T cell zone of the node, not the follicular aggregates of the outer cortex.", "C": "Medullary cords are located in the medulla and contain plasma cells and macrophages, not the outer cortex follicles.", "D": "Sinusoids/sinuses are channels through which lymph flows, not cellular aggregates."}}}, {"id": "anking-molecular-biology-428", "fuente": "anking", "tema": 44, "anki": "1467682100570", "q": "Histones are particularly rich in which two amino acids that contribute to their positive charge and DNA binding ability?", "o": {"A": "Lysine and arginine", "B": "Glutamate and aspartate", "C": "Leucine and isoleucine", "D": "Serine and threonine"}, "r": "A", "e": {"correcta": "Histones are rich in the basic amino acids lysine and arginine, which give them a net positive charge allowing electrostatic interaction with the negatively charged phosphate backbone of DNA.", "incorrectas": {"B": "Glutamate and aspartate are acidic, negatively charged amino acids and would repel, not bind, DNA.", "C": "Leucine and isoleucine are nonpolar hydrophobic amino acids, not associated with DNA binding.", "D": "Serine and threonine are polar but uncharged and are not the amino acids that define histone basicity."}}}, {"id": "anking-molecular-biology-429", "fuente": "anking", "tema": 44, "anki": "1467682104886", "q": "Which histone class is not found as a pair within the nucleosome core but instead binds outside it?", "o": {"A": "H2A", "B": "H3", "C": "H1", "D": "H4"}, "r": "C", "e": {"correcta": "H1 is the linker histone that binds outside the nucleosome core to the linker DNA, stabilizing higher-order chromatin structure, unlike H2A, H2B, H3, and H4 which form the core histone octamer as pairs.", "incorrectas": {"A": "H2A is one of the four core histones that exists as a pair within the nucleosome.", "B": "H3 is also a core histone present as a pair in the nucleosome, not a linker histone.", "D": "H4 is likewise one of the paired core histones forming the nucleosome octamer."}}}, {"id": "anking-molecular-biology-430", "fuente": "anking", "tema": 44, "anki": "1467682112238", "q": "Which histone binds outside the nucleosome core and functions to condense nucleosomes together into higher-order chromatin?", "o": {"A": "H2B", "B": "H1", "C": "H3", "D": "H4"}, "r": "B", "e": {"correcta": "H1 binds to the nucleosome and to linker DNA outside the core particle, thereby stabilizing and condensing the chromatin fiber from the 10 nm to the 30 nm form.", "incorrectas": {"A": "H2B is a core histone incorporated into the nucleosome octamer, not a linker/condensing histone.", "C": "H3 is one of the four core histones within the nucleosome, not the condensing linker histone.", "D": "H4 is a core histone pair member, not the histone responsible for linking nucleosomes together."}}}, {"id": "anking-molecular-biology-431", "fuente": "anking", "tema": 44, "anki": "1467682119151", "q": "Which four histone classes are found as pairs (two copies each) within the nucleosome core?", "o": {"A": "H1, H2A, H3, H4", "B": "H2A, H2B, H3, H4", "C": "H1, H2B, H3, H4", "D": "H2A, H2B, H1, H4"}, "r": "B", "e": {"correcta": "The nucleosome core is an octamer composed of two copies each of H2A, H2B, H3, and H4, around which DNA wraps nearly twice.", "incorrectas": {"A": "This includes H1, the linker histone that is not part of the core octamer.", "C": "This also incorrectly includes H1 instead of H2A as a core histone.", "D": "This substitutes H1 for H3, but H1 is not a core nucleosome histone."}}}, {"id": "anking-molecular-biology-432", "fuente": "anking", "tema": 44, "anki": "1467682127205", "q": "What is the primary function of histone H1?", "o": {"A": "Forms the core octamer around which DNA wraps", "B": "Condenses and links nucleosomes together into higher-order chromatin", "C": "Catalyzes DNA replication during S phase", "D": "Methylates cytosine residues to mark parental DNA strands"}, "r": "B", "e": {"correcta": "H1 binds to the nucleosome and to linker DNA, stabilizing the chromatin fiber and condensing 10 nm chromatin into the more compact 30 nm form.", "incorrectas": {"A": "Forming the core octamer is the role of H2A, H2B, H3, and H4, not H1.", "C": "DNA replication is catalyzed by DNA polymerases, not histone H1.", "D": "DNA methylation for strand discrimination in mismatch repair is performed by methyltransferases, not H1."}}}, {"id": "anking-molecular-biology-433", "fuente": "anking", "tema": 44, "anki": "1467682132293", "q": "What is the name of the structural unit made up of a strand of DNA wrapped nearly twice around two copies each of histones H2A, H2B, H3, and H4?", "o": {"A": "Nucleolus", "B": "Nucleosome", "C": "Nucleoid", "D": "Centromere"}, "r": "B", "e": {"correcta": "The nucleosome is the basic repeating unit of chromatin, consisting of DNA wrapped around a histone octamer (two copies each of H2A, H2B, H3, and H4).", "incorrectas": {"A": "The nucleolus is a nuclear substructure involved in ribosome synthesis, unrelated to DNA packaging around histones.", "C": "The nucleoid is the region containing DNA in prokaryotic cells, which lack histones in this context.", "D": "The centromere is the chromosomal region involved in sister chromatid attachment during mitosis, not the DNA-histone packaging unit."}}}, {"id": "anking-molecular-biology-434", "fuente": "anking", "tema": 44, "anki": "1467682151814", "q": "During which phase of the cell cycle do DNA and histone synthesis occur?", "o": {"A": "G1 phase", "B": "S phase", "C": "G2 phase", "D": "M phase"}, "r": "B", "e": {"correcta": "DNA replication and the coordinated synthesis of new histones both occur during S (synthesis) phase of the cell cycle to package the newly replicated DNA.", "incorrectas": {"A": "G1 phase is a growth phase preceding DNA synthesis, not when replication occurs.", "C": "G2 phase occurs after DNA synthesis, as the cell prepares for mitosis.", "D": "M phase is when mitosis (chromosome segregation) occurs, after DNA and histones have already been synthesized."}}}, {"id": "anking-molecular-biology-435", "fuente": "anking", "tema": 44, "anki": "1467682160443", "q": "Which form of chromatin is highly condensed?", "o": {"A": "Euchromatin", "B": "Heterochromatin", "C": "Chromatid", "D": "Kinetochore"}, "r": "B", "e": {"correcta": "Heterochromatin is the highly condensed form of chromatin, which is transcriptionally inactive due to its tightly packed structure.", "incorrectas": {"A": "Euchromatin is the less condensed, transcriptionally active form of chromatin.", "C": "A chromatid refers to one of the two identical copies of a replicated chromosome, not a condensation state.", "D": "The kinetochore is a protein structure on the centromere involved in spindle attachment, not a chromatin condensation state."}}}, {"id": "anking-molecular-biology-436", "fuente": "anking", "tema": 44, "anki": "1467682164864", "q": "Which form of chromatin is less condensed?", "o": {"A": "Heterochromatin", "B": "Euchromatin", "C": "Satellite DNA", "D": "Telomere"}, "r": "B", "e": {"correcta": "Euchromatin is the less condensed, more loosely packed form of chromatin that allows access for transcription machinery.", "incorrectas": {"A": "Heterochromatin is the highly condensed form of chromatin, the opposite of the less condensed state.", "C": "Satellite DNA refers to repetitive noncoding DNA sequences, not a chromatin condensation state.", "D": "Telomeres are the protective end regions of chromosomes, not a description of chromatin condensation."}}}, {"id": "anking-molecular-biology-437", "fuente": "anking", "tema": 44, "anki": "1467682168594", "q": "Which form of chromatin appears darker on electron microscopy (EM)?", "o": {"A": "Euchromatin", "B": "Heterochromatin", "C": "Nucleoplasm", "D": "Mitochondrial matrix"}, "r": "B", "e": {"correcta": "Heterochromatin is densely packed and stains darker on EM due to its condensed structure, correlating with transcriptional inactivity.", "incorrectas": {"A": "Euchromatin is less dense and appears lighter on EM, not darker.", "C": "Nucleoplasm is the fluid matrix of the nucleus and is not a chromatin condensation state.", "D": "The mitochondrial matrix is an unrelated organelle compartment, not a nuclear chromatin form."}}}, {"id": "anking-molecular-biology-438", "fuente": "anking", "tema": 44, "anki": "1467682176839", "q": "Which form of chromatin appears lighter on electron microscopy (EM)?", "o": {"A": "Heterochromatin", "B": "Euchromatin", "C": "Nucleolar organizer region", "D": "Metaphase chromosome"}, "r": "B", "e": {"correcta": "Euchromatin is loosely packed and appears lighter on EM, consistent with its transcriptionally active, accessible state.", "incorrectas": {"A": "Heterochromatin is densely packed and appears darker on EM, not lighter.", "C": "The nucleolar organizer region is a chromosomal region encoding rRNA genes, not a general chromatin condensation description.", "D": "Metaphase chromosomes represent highly condensed chromatin (similar to heterochromatin), which appears dark, not light."}}}, {"id": "anking-molecular-biology-439", "fuente": "anking", "tema": 44, "anki": "1467682184880", "q": "Which form of chromatin is transcriptionally inactive and sterically inaccessible to transcription machinery?", "o": {"A": "Euchromatin", "B": "Heterochromatin", "C": "mRNA", "D": "Ribosomal RNA"}, "r": "B", "e": {"correcta": "Heterochromatin's dense packing sterically blocks access of transcription factors and RNA polymerase, rendering it transcriptionally silent.", "incorrectas": {"A": "Euchromatin is loosely packed and transcriptionally active, the opposite of this description.", "C": "mRNA is a product of transcription, not a chromatin state.", "D": "Ribosomal RNA is a type of RNA involved in translation, not a chromatin condensation state."}}}, {"id": "anking-molecular-biology-440", "fuente": "anking", "tema": 44, "anki": "1467682191339", "q": "Which form of chromatin is transcriptionally active and sterically accessible to transcription machinery?", "o": {"A": "Heterochromatin", "B": "Euchromatin", "C": "Barr body", "D": "Centromeric heterochromatin"}, "r": "B", "e": {"correcta": "Euchromatin is loosely packed, allowing transcription factors and RNA polymerase access to DNA, making it transcriptionally active.", "incorrectas": {"A": "Heterochromatin is densely packed and transcriptionally inactive, the opposite of this description.", "C": "A Barr body is an inactivated X chromosome existing as heterochromatin, not the accessible active form.", "D": "Centromeric heterochromatin is a densely packed, transcriptionally silent chromosomal region."}}}, {"id": "anking-molecular-biology-441", "fuente": "anking", "tema": 44, "anki": "1467682194916", "q": "Barr bodies (inactivated X chromosomes) exist in which form of chromatin?", "o": {"A": "Euchromatin", "B": "Heterochromatin", "C": "Nucleosome-free DNA", "D": "Naked single-stranded DNA"}, "r": "B", "e": {"correcta": "Barr bodies are inactive X chromosomes that are condensed into heterochromatin, which silences gene expression from that chromosome.", "incorrectas": {"A": "Euchromatin is the transcriptionally active, loosely packed form and would not represent an inactivated chromosome.", "C": "DNA in the nucleus, including inactivated X chromosomes, remains wrapped by nucleosomes; it is not nucleosome-free.", "D": "Barr bodies are double-stranded, highly condensed DNA-protein complexes, not naked single-stranded DNA."}}}, {"id": "anking-molecular-biology-442", "fuente": "anking", "tema": 44, "anki": "1467682203692", "q": "Which form of chromatin represents the highest order of packaging of the chromosome?", "o": {"A": "Euchromatin", "B": "Heterochromatin", "C": "The 10 nm fiber", "D": "The nucleosome core particle"}, "r": "B", "e": {"correcta": "Heterochromatin represents the most highly condensed, highest order of chromatin packaging, beyond the basic nucleosome and 30 nm fiber levels.", "incorrectas": {"A": "Euchromatin is a less condensed, lower order of chromatin packaging.", "C": "The 10 nm fiber (beads-on-a-string nucleosome array) is an early, less condensed level of packaging, not the highest order.", "D": "The nucleosome core particle is the most basic unit of DNA packaging, far below the highest order of condensation."}}}, {"id": "anking-molecular-biology-443", "fuente": "anking", "tema": 44, "anki": "1467682210281", "q": "In the absence of histone H1, the nucleosome exists as chromatin of approximately what diameter?", "o": {"A": "30 nm", "B": "10 nm", "C": "2 nm", "D": "100 nm"}, "r": "B", "e": {"correcta": "Without H1, nucleosomes exist as the loosely packed 10 nm 'beads-on-a-string' chromatin fiber, since H1 is required for further condensation.", "incorrectas": {"A": "30 nm chromatin requires H1 to condense the nucleosomes together, so it does not form in H1's absence.", "C": "2 nm corresponds to the diameter of the DNA double helix itself, not nucleosome-packaged chromatin.", "D": "100 nm is larger than either the 10 nm or 30 nm chromatin fiber diameters described for nucleosome packaging."}}}, {"id": "anking-molecular-biology-444", "fuente": "anking", "tema": 44, "anki": "1467682218464", "q": "In the presence of histone H1, the nucleosome condenses into chromatin of approximately what diameter?", "o": {"A": "10 nm", "B": "30 nm", "C": "2 nm", "D": "300 nm"}, "r": "B", "e": {"correcta": "With H1 bound to linker DNA, nucleosomes condense from the 10 nm fiber into the more compact 30 nm chromatin fiber.", "incorrectas": {"A": "10 nm chromatin is the less condensed state present before H1 binds and condenses the fiber.", "C": "2 nm corresponds to the width of the DNA double helix, not the H1-condensed chromatin fiber.", "D": "300 nm refers to a higher order chromatin loop structure beyond the 30 nm fiber, not the immediate effect of H1 binding."}}}, {"id": "anking-molecular-biology-445", "fuente": "anking", "tema": 44, "anki": "1467682225986", "q": "What process do mismatch repair enzymes use to distinguish the old (template) strand from the newly synthesized DNA strand in prokaryotes?", "o": {"A": "DNA methylation", "B": "Histone acetylation", "C": "DNA phosphorylation", "D": "Okazaki fragment ligation"}, "r": "A", "e": {"correcta": "In prokaryotes, the parental (template) strand is methylated at adenine and cytosine residues, allowing mismatch repair enzymes to distinguish it from the unmethylated newly synthesized strand.", "incorrectas": {"B": "Histone acetylation regulates chromatin condensation and gene expression in eukaryotes and is not relevant to prokaryotic strand discrimination, nor do prokaryotes package DNA with histones.", "C": "DNA phosphorylation is not a recognized mechanism used to distinguish parental from daughter DNA strands.", "D": "Okazaki fragment ligation is part of normal lagging-strand DNA synthesis, unrelated to distinguishing old versus new strands for mismatch repair."}}}, {"id": "anking-genetics-446", "fuente": "anking", "tema": 45, "anki": "1463526446923", "q": "What is the most common mechanism underlying chromosomal aneuploidy (e.g., trisomy 21)?", "o": {"A": "Meiotic nondisjunction", "B": "Robertsonian translocation", "C": "Mitotic nondisjunction (mosaicism)", "D": "Balanced reciprocal translocation"}, "r": "A", "e": {"correcta": "Meiotic nondisjunction (failure of homologous chromosomes or sister chromatids to separate during meiosis I or II) is the most common cause of aneuploidy such as trisomy 21, 18, and 13.", "incorrectas": {"B": "Robertsonian translocation is a less common cause of trisomy 21 (translocation Down syndrome), accounting for a small minority of cases.", "C": "Mitotic nondisjunction occurring after fertilization produces mosaicism, which is a much rarer cause of aneuploidy than meiotic nondisjunction.", "D": "A balanced reciprocal translocation does not change chromosome number and typically does not cause aneuploidy in the carrier."}}}, {"id": "anking-genetics-447", "fuente": "anking", "tema": 45, "anki": "1463944286727", "q": "On a neonatal quad screen, which pattern of AFP, estriol, hCG, and inhibin A is classically associated with trisomy 18 (Edward syndrome)?", "o": {"A": "AFP decreased, estriol decreased, hCG decreased, inhibin A normal or decreased", "B": "AFP increased, estriol decreased, hCG increased, inhibin A increased", "C": "AFP decreased, estriol decreased, hCG increased, inhibin A increased", "D": "AFP normal, estriol normal, hCG normal, inhibin A normal"}, "r": "A", "e": {"correcta": "Trisomy 18 classically shows decreased AFP, decreased estriol, decreased hCG, and normal or decreased inhibin A ('everything low' pattern), distinguishing it from trisomy 21.", "incorrectas": {"B": "This pattern (increased AFP/hCG/inhibin A with decreased estriol) does not match any classic trisomy screening profile.", "C": "Increased hCG and inhibin A with decreased AFP and estriol is the classic pattern for trisomy 21 (Down syndrome), not trisomy 18.", "D": "A completely normal quad screen would not be suggestive of any trisomy and does not describe Edward syndrome."}}}, {"id": "anking-genetics-448", "fuente": "anking", "tema": 45, "anki": "1463944294110", "q": "Which trisomy is characterized by increased levels of hCG on a maternal quad screen?", "o": {"A": "Trisomy 21 (Down syndrome)", "B": "Trisomy 18 (Edward syndrome)", "C": "Trisomy 13 (Patau syndrome)", "D": "Klinefelter syndrome (47,XXY)"}, "r": "A", "e": {"correcta": "Trisomy 21 (Down syndrome) is associated with increased hCG and inhibin A, along with decreased AFP and estriol.", "incorrectas": {"B": "Trisomy 18 is associated with decreased hCG, not increased.", "C": "Trisomy 13 is also associated with decreased hCG and decreased PAPP-A, not increased hCG.", "D": "Klinefelter syndrome is a sex chromosome aneuploidy that is not characterized by quad screen changes in the same way autosomal trisomies are."}}}, {"id": "anking-genetics-449", "fuente": "anking", "tema": 45, "anki": "1463944325300", "q": "Which trisomies are characterized by decreased levels of hCG on maternal screening?", "o": {"A": "Trisomy 18 (Edward syndrome) and trisomy 13 (Patau syndrome)", "B": "Trisomy 21 (Down syndrome) only", "C": "Trisomy 21 and trisomy 18 only", "D": "Klinefelter syndrome and Turner syndrome"}, "r": "A", "e": {"correcta": "Both trisomy 18 (Edward syndrome) and trisomy 13 (Patau syndrome) show decreased hCG; Patau syndrome additionally shows decreased PAPP-A.", "incorrectas": {"B": "Trisomy 21 is associated with increased, not decreased, hCG.", "C": "Trisomy 21 has increased hCG, so pairing it with trisomy 18 as both having decreased hCG is incorrect.", "D": "Sex chromosome aneuploidies like Klinefelter and Turner syndrome are not defined by this decreased hCG quad screen pattern."}}}, {"id": "anking-genetics-450", "fuente": "anking", "tema": 45, "anki": "1469146604758", "q": "What term describes the specific physical location of a gene on a chromosome?", "o": {"A": "Locus", "B": "Allele", "C": "Genotype", "D": "Karyotype"}, "r": "A", "e": {"correcta": "A locus is the specific, fixed position of a gene on a chromosome.", "incorrectas": {"B": "An allele is one of the alternative forms of a gene at a given locus, not the location itself.", "C": "Genotype refers to the genetic makeup of an organism at one or more loci, not the physical location.", "D": "Karyotype refers to the complete set of chromosomes of an individual, not a specific gene location."}}}, {"id": "anking-genetics-451", "fuente": "anking", "tema": 45, "anki": "1469146644218", "q": "What term describes different forms of a single gene that can occur at the same locus?", "o": {"A": "Alleles", "B": "Loci", "C": "Chromatids", "D": "Haplotypes"}, "r": "A", "e": {"correcta": "Alleles are the different variant forms of a single gene that can exist at a given locus.", "incorrectas": {"B": "Loci are the physical locations of genes, not the variant forms of a gene.", "C": "Chromatids are copies of a chromosome formed during DNA replication, unrelated to gene variants.", "D": "A haplotype is a group of alleles/genetic markers inherited together, not a single gene's alternative forms."}}}, {"id": "anking-genetics-452", "fuente": "anking", "tema": 45, "anki": "1469146651628", "q": "In a pedigree diagram, what does a square symbol represent?", "o": {"A": "A male individual", "B": "A female individual", "C": "An individual of unknown sex", "D": "A miscarriage or stillbirth"}, "r": "A", "e": {"correcta": "By pedigree convention, a square represents a male individual.", "incorrectas": {"B": "A female individual is represented by a circle, not a square.", "C": "Unknown sex is typically represented by a diamond, not a square.", "D": "A miscarriage or stillbirth is usually denoted by a small triangle, not a square."}}}, {"id": "anking-genetics-453", "fuente": "anking", "tema": 45, "anki": "1469146656814", "q": "In a pedigree diagram, what does a circle symbol represent?", "o": {"A": "A female individual", "B": "A male individual", "C": "A carrier of an X-linked trait", "D": "A deceased individual"}, "r": "A", "e": {"correcta": "By pedigree convention, a circle represents a female individual.", "incorrectas": {"B": "A male individual is represented by a square, not a circle.", "C": "A carrier is typically indicated by a dot or half-shading inside the symbol, not simply by the shape being a circle.", "D": "A deceased individual is indicated by a diagonal line through the symbol, not by the circle shape itself."}}}, {"id": "anking-genetics-454", "fuente": "anking", "tema": 45, "anki": "1469146662039", "q": "In a pedigree diagram, a shaded (filled-in) circle or square indicates what about that individual?", "o": {"A": "The individual is affected by the disease", "B": "The individual is an unaffected carrier", "C": "The individual is deceased", "D": "The individual's sex is unknown"}, "r": "A", "e": {"correcta": "A shaded (filled) symbol in a pedigree denotes an individual who is affected by (has) the disease/trait being tracked.", "incorrectas": {"B": "Unaffected carriers are typically shown with a dot or half-fill, not full shading.", "C": "A deceased individual is shown with a diagonal line through the symbol, not shading.", "D": "Unknown sex is represented by a diamond shape, not shading of a circle/square."}}}, {"id": "anking-genetics-455", "fuente": "anking", "tema": 45, "anki": "1469146690171", "q": "In a pedigree showing autosomal dominant inheritance, what is the typical pattern across generations?", "o": {"A": "The disease usually does not skip generations (vertical transmission)", "B": "The disease usually skips generations (horizontal transmission)", "C": "Only males are affected in each generation", "D": "The disease appears only in offspring of consanguineous unions"}, "r": "A", "e": {"correcta": "Autosomal dominant diseases typically show a vertical pattern of transmission, appearing in every generation without skipping, since only one copy of the mutant allele is needed for expression.", "incorrectas": {"B": "Skipping generations (horizontal pattern) is characteristic of autosomal recessive inheritance, not dominant.", "C": "Autosomal dominant conditions affect males and females equally; sex-limited patterns are not typical.", "D": "Consanguinity increasing risk is a feature of autosomal recessive disease, not dominant disease."}}}, {"id": "anking-genetics-456", "fuente": "anking", "tema": 45, "anki": "1469146700915", "q": "Autosomal dominant diseases are often due to defects in which category of genes?", "o": {"A": "Structural genes", "B": "Enzyme-encoding genes", "C": "Genes on the X chromosome", "D": "Mitochondrial genes"}, "r": "A", "e": {"correcta": "Autosomal dominant diseases commonly result from defects in structural proteins (e.g., collagen in Marfan syndrome or osteogenesis imperfecta), where a single abnormal copy disrupts the structure.", "incorrectas": {"B": "Enzyme deficiencies are more classically associated with autosomal recessive diseases, since a single normal enzyme copy is often sufficient.", "C": "X-linked genes are, by definition, not autosomal and follow a different inheritance pattern.", "D": "Mitochondrial gene defects follow maternal (mitochondrial) inheritance, not autosomal dominant inheritance."}}}, {"id": "anking-genetics-457", "fuente": "anking", "tema": 45, "anki": "1469146704776", "q": "Which inheritance pattern is often characterized by pleiotropy and variable expressivity, and may show incomplete penetrance?", "o": {"A": "Autosomal dominant", "B": "Autosomal recessive", "C": "X-linked recessive", "D": "Mitochondrial inheritance"}, "r": "A", "e": {"correcta": "Autosomal dominant diseases are often pleiotropic (one gene affects multiple systems) and variably expressive, and may show incomplete penetrance (not all who carry the allele express the disease).", "incorrectas": {"B": "Autosomal recessive diseases are typically more uniform in severity/expression and less noted for incomplete penetrance.", "C": "X-linked recessive diseases are defined by their X-linked transmission pattern rather than being classically known for pleiotropy/incomplete penetrance.", "D": "Mitochondrial inheritance is defined by maternal transmission and heteroplasmy, a distinct concept from pleiotropy/penetrance in autosomal dominant disease."}}}, {"id": "anking-genetics-458", "fuente": "anking", "tema": 45, "anki": "1469146716026", "q": "In a pedigree showing autosomal recessive inheritance, what is the typical pattern across generations?", "o": {"A": "The disease usually skips generations (horizontal pattern)", "B": "The disease usually does not skip generations (vertical pattern)", "C": "The disease is transmitted from father to son only", "D": "The disease affects every offspring of an affected parent"}, "r": "A", "e": {"correcta": "Autosomal recessive diseases usually show a horizontal pattern, appearing in siblings within a single generation while skipping the parents' generation, since both parents are typically unaffected carriers.", "incorrectas": {"B": "A pattern that does not skip generations (vertical) is characteristic of autosomal dominant inheritance, not recessive.", "C": "Father-to-son transmission specifically is not a hallmark of autosomal recessive inheritance; autosomal traits are not sex-linked.", "D": "Since both parents are usually heterozygous carriers rather than affected, not every offspring is affected—only about 1 in 4 on average."}}}, {"id": "anking-genetics-459", "fuente": "anking", "tema": 45, "anki": "1469146725917", "q": "Autosomal recessive diseases are often due to which type of deficiency?", "o": {"A": "Enzyme deficiencies", "B": "Structural protein deficiencies", "C": "Hormone receptor deficiencies", "D": "Ion channel deficiencies"}, "r": "A", "e": {"correcta": "Autosomal recessive diseases are often caused by enzyme deficiencies (e.g., inborn errors of metabolism), since a single functional enzyme copy is usually sufficient to prevent disease, and both alleles must be defective for expression.", "incorrectas": {"B": "Structural protein defects are more classically linked to autosomal dominant conditions.", "C": "Hormone receptor deficiencies are not the classic category associated with autosomal recessive inheritance.", "D": "Ion channel defects are seen in some genetic diseases but are not the hallmark category taught for autosomal recessive conditions."}}}, {"id": "anking-genetics-460", "fuente": "anking", "tema": 45, "anki": "1469146729264", "q": "There is an increased risk of autosomal recessive diseases in which type of family?", "o": {"A": "Consanguineous families", "B": "Families with advanced maternal age", "C": "Families with a history of chromosomal translocations", "D": "Families with X-linked disease carriers"}, "r": "A", "e": {"correcta": "Consanguineous (related) parents are more likely to share the same recessive allele, increasing the risk that their offspring will inherit two copies and be affected.", "incorrectas": {"B": "Advanced maternal age increases the risk of chromosomal nondisjunction (e.g., trisomies), not autosomal recessive single-gene disease risk.", "C": "A history of chromosomal translocations relates to structural chromosomal abnormalities, not single-gene recessive disease risk.", "D": "Being carriers of X-linked disease is unrelated to the risk of autosomal recessive disease, which involves different genes and chromosomes."}}}, {"id": "anking-genetics-461", "fuente": "anking", "tema": 45, "anki": "1469146736550", "q": "In a pedigree showing X-linked recessive inheritance, does the disease typically skip generations?", "o": {"A": "Yes, it usually skips generations", "B": "No, it usually does not skip generations", "C": "It always affects every generation equally in both sexes", "D": "It only appears in the first generation"}, "r": "A", "e": {"correcta": "X-linked recessive diseases usually skip generations, as they typically pass from an unaffected (carrier) grandmother through an unaffected carrier daughter to an affected grandson.", "incorrectas": {"B": "Not skipping generations (vertical transmission) is more typical of autosomal dominant inheritance.", "C": "X-linked recessive diseases affect males far more frequently than females, so it is not equal across sexes.", "D": "X-linked recessive diseases can persist and reappear across many generations, not just the first."}}}, {"id": "anking-genetics-462", "fuente": "anking", "tema": 45, "anki": "1469146744041", "q": "In X-linked recessive inheritance, which type of transmission is characteristically absent?", "o": {"A": "Male-to-male transmission", "B": "Mother-to-son transmission", "C": "Mother-to-daughter transmission", "D": "Father-to-daughter transmission"}, "r": "A", "e": {"correcta": "Because fathers pass their Y chromosome (not X) to sons, male-to-male transmission does not occur in X-linked recessive inheritance; this is a key distinguishing feature from autosomal inheritance.", "incorrectas": {"B": "Mother-to-son transmission is common in X-linked recessive disease, since sons receive their only X chromosome from their mother.", "C": "Mother-to-daughter transmission of a carrier X chromosome can occur and is not characteristically absent.", "D": "Father-to-daughter transmission of the X chromosome (making daughters obligate carriers) does occur in X-linked recessive inheritance."}}}, {"id": "anking-genetics-463", "fuente": "anking", "tema": 45, "anki": "1469146750767", "q": "X-linked recessive diseases are commonly more severe in which sex?", "o": {"A": "Males", "B": "Females", "C": "Equally severe in both sexes", "D": "Severity is unrelated to sex and depends only on age"}, "r": "A", "e": {"correcta": "Males are hemizygous for the X chromosome (only one copy), so a single recessive allele results in full disease expression, making X-linked recessive diseases commonly more frequent and more severe in males.", "incorrectas": {"B": "Females usually have a second, normal X chromosome that can compensate (via random X-inactivation), making them typically unaffected carriers or having milder disease.", "C": "Severity is not equal between sexes due to the hemizygosity of males for X-linked genes.", "D": "Sex, not age, is the primary determinant of severity difference in X-linked recessive disease due to hemizygosity."}}}, {"id": "anking-nutrition-464", "fuente": "anking", "tema": 46, "anki": "1462145843145", "q": "Besides cutaneous synthesis, what is the other external source of vitamin D (cholecalciferol) in the body?", "o": {"A": "Ingestion/diet", "B": "Bacterial synthesis in the colon", "C": "Renal conversion from cholesterol", "D": "Hepatic de novo synthesis"}, "r": "A", "e": {"correcta": "Vitamin D can be obtained exogenously through dietary intake (e.g., fortified dairy, fish), in addition to endogenous skin synthesis.", "incorrectas": {"B": "Gut bacteria do not synthesize vitamin D in humans.", "C": "The kidney hydroxylates vitamin D but does not create it from cholesterol; that occurs in skin.", "D": "The liver performs 25-hydroxylation of vitamin D but does not synthesize it de novo."}}}, {"id": "anking-nutrition-465", "fuente": "anking", "tema": 46, "anki": "1462145970044", "q": "Synthesis of vitamin D (cholecalciferol) from 7-dehydrocholesterol in the skin requires exposure to which factor?", "o": {"A": "UV light", "B": "Infrared radiation", "C": "Dietary calcium", "D": "Parathyroid hormone"}, "r": "A", "e": {"correcta": "UV light (UVB) converts 7-dehydrocholesterol in the skin to previtamin D3, which becomes cholecalciferol (vitamin D3).", "incorrectas": {"B": "Infrared radiation does not drive this photochemical conversion.", "C": "Dietary calcium is not required for the skin synthesis step.", "D": "PTH acts later to stimulate renal 1α-hydroxylase, not skin synthesis."}}}, {"id": "anking-nutrition-466", "fuente": "anking", "tema": 46, "anki": "1462146068480", "q": "How does serum Ca2+ concentration affect the activity of renal 1α-hydroxylase?", "o": {"A": "Decreased serum Ca2+ increases 1α-hydroxylase activity", "B": "Increased serum Ca2+ increases 1α-hydroxylase activity", "C": "Serum Ca2+ has no effect on 1α-hydroxylase", "D": "Decreased serum Ca2+ inhibits 1α-hydroxylase irreversibly"}, "r": "A", "e": {"correcta": "Low serum Ca2+ stimulates PTH release, which upregulates renal 1α-hydroxylase, increasing production of active vitamin D [1,25(OH)2D] to raise calcium absorption.", "incorrectas": {"B": "High calcium suppresses PTH and thus decreases, not increases, 1α-hydroxylase activity.", "C": "Serum calcium indirectly (via PTH) strongly regulates this enzyme.", "D": "The effect is a reversible physiologic regulation, not permanent inhibition."}}}, {"id": "anking-nutrition-467", "fuente": "anking", "tema": 46, "anki": "1462146092249", "q": "How do PTH levels affect the activity of renal 1α-hydroxylase?", "o": {"A": "Increased PTH increases 1α-hydroxylase activity", "B": "Increased PTH decreases 1α-hydroxylase activity", "C": "PTH has no effect on 1α-hydroxylase", "D": "PTH only affects intestinal calcium absorption, not the kidney enzyme"}, "r": "A", "e": {"correcta": "PTH directly stimulates renal 1α-hydroxylase, increasing conversion of 25-(OH)D to active 1,25-(OH)2D.", "incorrectas": {"B": "PTH is stimulatory, not inhibitory, to this enzyme.", "C": "PTH is one of the primary regulators of this enzyme.", "D": "PTH's action on intestinal calcium absorption is mediated indirectly through this renal enzyme's product."}}}, {"id": "anking-nutrition-468", "fuente": "anking", "tema": 46, "anki": "1462146106409", "q": "How does serum phosphate concentration affect the activity of renal 1α-hydroxylase?", "o": {"A": "Decreased serum phosphate increases 1α-hydroxylase activity", "B": "Increased serum phosphate increases 1α-hydroxylase activity", "C": "Serum phosphate has no effect on 1α-hydroxylase", "D": "Phosphate only regulates FGF23, not 1α-hydroxylase"}, "r": "A", "e": {"correcta": "Low serum phosphate stimulates 1α-hydroxylase activity, increasing active vitamin D production to help restore phosphate levels via intestinal and renal reabsorption.", "incorrectas": {"B": "High phosphate suppresses, rather than stimulates, this enzyme (partly via FGF23).", "C": "Phosphate is a known regulator of this enzyme.", "D": "While FGF23 does inhibit 1α-hydroxylase in response to phosphate, phosphate itself still influences the enzyme's activity."}}}, {"id": "anking-nutrition-469", "fuente": "anking", "tema": 46, "anki": "1462146169234", "q": "1,25-dihydroxycholecalciferol increases which type of Ca2+ absorption through synthesis of calbindin D-28K?", "o": {"A": "Intestinal absorption", "B": "Renal tubular absorption only", "C": "Salivary gland absorption", "D": "Pulmonary absorption"}, "r": "A", "e": {"correcta": "Active vitamin D induces calbindin D-28K in intestinal epithelial cells, which binds and facilitates transcellular calcium absorption from the gut.", "incorrectas": {"B": "Calbindin D-28K in this context refers to the intestinal isoform; renal reabsorption uses distinct mechanisms.", "C": "Salivary glands are not a site of vitamin D-mediated calcium absorption.", "D": "The lungs are not involved in dietary calcium absorption."}}}, {"id": "anking-nutrition-470", "fuente": "anking", "tema": 46, "anki": "1462146190722", "q": "In addition to calcium, what other ion's intestinal absorption is increased by 1,25-(OH)2 D3?", "o": {"A": "Phosphate (PO4 3-)", "B": "Potassium (K+)", "C": "Magnesium (Mg2+) exclusively", "D": "Chloride (Cl-)"}, "r": "A", "e": {"correcta": "1,25-(OH)2 D3 increases intestinal absorption of both calcium and phosphate, supporting bone mineralization.", "incorrectas": {"B": "Potassium absorption is not a primary target of vitamin D action.", "C": "Magnesium absorption is not the classic paired ion described with vitamin D action (phosphate is).", "D": "Chloride transport is not a major target of active vitamin D."}}}, {"id": "anking-nutrition-471", "fuente": "anking", "tema": 46, "anki": "1462146204556", "q": "Similar to its intestinal action, 1,25-dihydroxycholecalciferol increases which type of reabsorption of Ca2+ and phosphate?", "o": {"A": "Renal reabsorption", "B": "Hepatic reabsorption", "C": "Salivary reabsorption", "D": "Colonic secretion"}, "r": "A", "e": {"correcta": "Active vitamin D also acts on the kidney to increase reabsorption of calcium and phosphate from the renal tubules, paralleling its intestinal effect.", "incorrectas": {"B": "The liver is not a site of calcium/phosphate reabsorption.", "C": "Salivary glands do not reabsorb calcium/phosphate in this context.", "D": "This describes reabsorption, not colonic secretion."}}}, {"id": "anking-nutrition-472", "fuente": "anking", "tema": 46, "anki": "1462146232681", "q": "In bone, 1,25-(OH)2 D3 acts synergistically with PTH to stimulate which cellular activity and process?", "o": {"A": "Osteoclast activity and bone resorption", "B": "Osteoblast activity and bone formation only", "C": "Chondrocyte activity and cartilage formation", "D": "Osteocyte apoptosis"}, "r": "A", "e": {"correcta": "1,25-(OH)2 D3 and PTH act together to stimulate osteoclast activity and bone resorption, mobilizing calcium and phosphate from old bone to help mineralize new bone and maintain serum levels.", "incorrectas": {"B": "This process involves resorption via osteoclasts, not primarily new bone formation by osteoblasts.", "C": "Chondrocytes and cartilage formation are not the target of this PTH/vitamin D synergy.", "D": "Osteocyte apoptosis is not the described mechanism."}}}, {"id": "anking-nutrition-473", "fuente": "anking", "tema": 46, "anki": "1462146244155", "q": "What effect does 1,25-dihydroxycholecalciferol have on its own production?", "o": {"A": "Inhibits it (negative feedback)", "B": "Stimulates it (positive feedback)", "C": "Has no effect on its own production", "D": "Converts it into calcitriol-binding protein"}, "r": "A", "e": {"correcta": "Active vitamin D exerts negative feedback on 1α-hydroxylase, decreasing its own further synthesis once adequate levels are reached.", "incorrectas": {"B": "Positive feedback would lead to unregulated overproduction, which does not occur physiologically.", "C": "Vitamin D does regulate its own synthesis via feedback inhibition.", "D": "This does not describe a real regulatory mechanism for vitamin D."}}}, {"id": "anking-nutrition-474", "fuente": "anking", "tema": 46, "anki": "1462146277040", "q": "In children, vitamin D deficiency causes which condition?", "o": {"A": "Rickets", "B": "Osteomalacia", "C": "Osteoporosis", "D": "Osteopetrosis"}, "r": "A", "e": {"correcta": "Vitamin D deficiency in children causes rickets, characterized by growth failure and skeletal deformities because growing bones fail to mineralize properly.", "incorrectas": {"B": "Osteomalacia is the analogous condition seen in adults after growth plates have closed.", "C": "Osteoporosis is a disorder of decreased bone density typically related to aging or estrogen deficiency, not vitamin D deficiency in children.", "D": "Osteopetrosis is caused by defective osteoclast function, unrelated to vitamin D deficiency."}}}, {"id": "anking-nutrition-475", "fuente": "anking", "tema": 46, "anki": "1462146288515", "q": "In adults, vitamin D deficiency causes which condition?", "o": {"A": "Osteomalacia", "B": "Rickets", "C": "Paget disease of bone", "D": "Osteitis fibrosa cystica"}, "r": "A", "e": {"correcta": "In adults, vitamin D deficiency causes osteomalacia, characterized by bending and softening of weight-bearing bones due to poor mineralization.", "incorrectas": {"B": "Rickets is the pediatric form seen before growth plate closure.", "C": "Paget disease is a disorder of abnormal bone remodeling, unrelated to vitamin D deficiency.", "D": "Osteitis fibrosa cystica is caused by severe hyperparathyroidism, not vitamin D deficiency."}}}, {"id": "anking-nutrition-476", "fuente": "anking", "tema": 46, "anki": "1462146297915", "q": "Vitamin D resistance most commonly occurs due to which condition?", "o": {"A": "Chronic renal failure", "B": "Chronic liver failure", "C": "Primary hyperparathyroidism", "D": "Celiac disease"}, "r": "A", "e": {"correcta": "Chronic renal failure impairs renal 1α-hydroxylase activity, reducing conversion to active vitamin D and causing vitamin D resistance; congenital absence of 1α-hydroxylase is a rarer cause.", "incorrectas": {"B": "Liver failure impairs 25-hydroxylation but is a less common cause of clinically significant vitamin D resistance compared to renal failure.", "C": "Primary hyperparathyroidism increases active vitamin D production rather than causing resistance.", "D": "Celiac disease can cause malabsorption of vitamin D but is not the most common cause of vitamin D resistance."}}}, {"id": "anking-nutrition-477", "fuente": "anking", "tema": 46, "anki": "1472078831731", "q": "Which vitamin B1 (thiamine) deficiency syndrome may cause dilated cardiomyopathy?", "o": {"A": "Wet beriberi", "B": "Dry beriberi", "C": "Pellagra", "D": "Scurvy"}, "r": "A", "e": {"correcta": "Wet beriberi, caused by thiamine (vitamin B1) deficiency, involves high-output cardiac failure that can progress to dilated cardiomyopathy.", "incorrectas": {"B": "Dry beriberi causes peripheral neuropathy rather than cardiac disease.", "C": "Pellagra results from niacin (B3) deficiency and causes dermatitis, diarrhea, and dementia, not cardiomyopathy.", "D": "Scurvy is caused by vitamin C deficiency and causes connective tissue defects, not cardiomyopathy."}}}, {"id": "anking-nutrition-478", "fuente": "anking", "tema": 46, "anki": "1473995718828", "q": "Activated vitamin K acts as a cofactor for which enzyme?", "o": {"A": "γ-glutamyl carboxylase", "B": "Prothrombinase", "C": "Cyclooxygenase", "D": "Glutamate dehydrogenase"}, "r": "A", "e": {"correcta": "Activated vitamin K is a cofactor for γ-glutamyl carboxylase, which carboxylates glutamate residues on clotting factors, enabling their calcium-dependent activity.", "incorrectas": {"B": "Prothrombinase is a complex that activates prothrombin but is not the enzyme vitamin K serves as a cofactor for.", "C": "Cyclooxygenase is involved in prostaglandin synthesis, unrelated to vitamin K.", "D": "Glutamate dehydrogenase functions in amino acid metabolism, not clotting factor modification."}}}, {"id": "anking-nutrition-479", "fuente": "anking", "tema": 46, "anki": "1473995720927", "q": "Vitamin K is necessary for what modification of factors II, VII, IX, X, and proteins C and S?", "o": {"A": "Gamma carboxylation", "B": "Phosphorylation", "C": "Glycosylation", "D": "Hydroxylation"}, "r": "A", "e": {"correcta": "Vitamin K enables gamma carboxylation of glutamate residues on these clotting factors, creating a calcium-binding site necessary for their function.", "incorrectas": {"B": "Phosphorylation is not the vitamin K-dependent modification involved here.", "C": "Glycosylation is unrelated to vitamin K's role in coagulation factor activation.", "D": "Hydroxylation (as in collagen synthesis) requires vitamin C, not vitamin K."}}}, {"id": "anking-nutrition-480", "fuente": "anking", "tema": 46, "anki": "1473995736635", "q": "Which coagulation factors have decreased activity due to vitamin K deficiency?", "o": {"A": "Factors II, VII, IX, and X", "B": "Factors V, VIII, XI, and XII", "C": "Factors I, III, IV, and V", "D": "Factors VIII, IX, XI, and XII (intrinsic pathway only)"}, "r": "A", "e": {"correcta": "Vitamin K deficiency decreases activity of factors II, VII, IX, and X, since these require vitamin K-dependent gamma carboxylation for activity.", "incorrectas": {"B": "Factors V, VIII, XI, and XII are not vitamin K-dependent.", "C": "Factors I (fibrinogen), III (tissue factor), and IV (calcium) are not vitamin K-dependent clotting factors.", "D": "This list mixes non-vitamin K-dependent factors (VIII, XI, XII) and omits vitamin K-dependent ones like II and X."}}}, {"id": "anking-nutrition-481", "fuente": "anking", "tema": 46, "anki": "1473995740705", "q": "What proteins (besides clotting factors) have decreased activity due to vitamin K deficiency?", "o": {"A": "Protein C and protein S", "B": "Antithrombin III and plasminogen", "C": "Albumin and prealbumin", "D": "von Willebrand factor and fibrinogen"}, "r": "A", "e": {"correcta": "Protein C and protein S are vitamin K-dependent anticoagulant proteins and have decreased activity in vitamin K deficiency; protein S levels are also decreased during pregnancy.", "incorrectas": {"B": "Antithrombin III and plasminogen are not vitamin K-dependent proteins.", "C": "Albumin and prealbumin are liver-synthesized proteins unrelated to vitamin K-dependent carboxylation.", "D": "von Willebrand factor and fibrinogen are not vitamin K-dependent."}}}, {"id": "anking-cardiovascular-physiology-482", "fuente": "anking", "tema": 47, "anki": "1470836378217", "q": "In the steady state, how does the cardiac output of the left heart compare to the cardiac output of the right heart?", "o": {"A": "They are equal", "B": "Left heart output is roughly double right heart output", "C": "Right heart output is roughly double left heart output", "D": "Left heart output is about 20% higher due to bronchial circulation"}, "r": "A", "e": {"correcta": "In steady state, the pulmonary and systemic circulations form a closed loop in series, so the output of the left and right ventricles must be equal over time.", "incorrectas": {"B": "There is no normal physiologic state in which left heart output is double the right heart output; this would cause volume mismatch between circuits.", "C": "Right heart output being double left heart output would similarly cause an unsustainable volume imbalance.", "D": "Bronchial venous drainage causes only a tiny, physiologically negligible difference, not a 20% disparity, and is not the basis for equal cardiac outputs."}}}, {"id": "anking-cardiovascular-physiology-483", "fuente": "anking", "tema": 47, "anki": "1470839275182", "q": "What is the term for the rate at which blood is pumped out of either ventricle?", "o": {"A": "Cardiac output", "B": "Venous return", "C": "Stroke volume index", "D": "Ejection fraction"}, "r": "A", "e": {"correcta": "Cardiac output is defined as the rate of blood ejected from a ventricle per unit time (stroke volume x heart rate).", "incorrectas": {"B": "Venous return refers to the rate of blood flowing back into the atria, not blood pumped out of the ventricles.", "C": "Stroke volume index is stroke volume normalized to body surface area, not a rate of ventricular output.", "D": "Ejection fraction is the percentage of end-diastolic volume ejected per beat, not a flow rate."}}}, {"id": "anking-cardiovascular-physiology-484", "fuente": "anking", "tema": 47, "anki": "1470839277805", "q": "What is the term for the rate at which blood is returned to the atria?", "o": {"A": "Venous return", "B": "Cardiac output", "C": "Preload", "D": "Central venous pressure"}, "r": "A", "e": {"correcta": "Venous return is defined as the rate of blood flow returning to the right and left atria from the venous system.", "incorrectas": {"B": "Cardiac output describes blood pumped out of the ventricles, not blood returning to the atria.", "C": "Preload refers to ventricular wall tension/stretch at end-diastole, a related but distinct concept from the rate of venous return.", "D": "Central venous pressure is a pressure measurement in the great veins/right atrium, not a flow rate."}}}, {"id": "anking-cardiovascular-physiology-485", "fuente": "anking", "tema": 47, "anki": "1470839413539", "q": "Which equation is used to calculate the velocity of blood flow (v) given the flow rate (Q) and cross-sectional area (A)?", "o": {"A": "v = Q/A", "B": "v = Q x A", "C": "v = ΔP/R", "D": "v = A/Q"}, "r": "A", "e": {"correcta": "Velocity equals flow rate divided by cross-sectional area (v = Q/A), meaning velocity decreases as cross-sectional area increases for a given flow.", "incorrectas": {"B": "Multiplying Q by A gives an incorrect relationship; velocity is inversely, not directly, related to area.", "C": "Q = ΔP/R is the equation for flow rate based on pressure gradient and resistance, not for velocity.", "D": "A/Q is the inverse of the correct relationship and does not represent velocity."}}}, {"id": "anking-cardiovascular-physiology-486", "fuente": "anking", "tema": 47, "anki": "1470839420946", "q": "Velocity of blood flow (v) is related to the total cross-sectional area of the vessel in what way?", "o": {"A": "Inversely proportional", "B": "Directly proportional", "C": "Unrelated", "D": "Proportional to the square of the area"}, "r": "A", "e": {"correcta": "From v = Q/A, velocity is inversely proportional to cross-sectional area — as total cross-sectional area increases, velocity decreases for a constant flow rate.", "incorrectas": {"B": "Direct proportionality would mean velocity increases as area increases, which contradicts v = Q/A.", "C": "Velocity is mathematically dependent on area through the equation v = Q/A, so they are related, not unrelated.", "D": "The relationship is a simple inverse proportion, not an inverse-square or squared relationship."}}}, {"id": "anking-cardiovascular-physiology-487", "fuente": "anking", "tema": 47, "anki": "1470839425004", "q": "Which type of blood vessel has the lowest blood flow velocity?", "o": {"A": "Capillaries", "B": "Aorta", "C": "Arterioles", "D": "Venae cavae"}, "r": "A", "e": {"correcta": "Capillaries have the lowest flow velocity because their total cross-sectional area (summed across all parallel capillaries) is the largest of any vessel type, and velocity is inversely proportional to area.", "incorrectas": {"B": "The aorta has a small individual cross-sectional area and thus the highest flow velocity in the systemic circulation.", "C": "Arterioles have a smaller total cross-sectional area than capillaries, giving them a higher velocity than capillaries.", "D": "The venae cavae have less total cross-sectional area than the capillary bed, so their velocity is higher than that of capillaries."}}}, {"id": "anking-cardiovascular-physiology-488", "fuente": "anking", "tema": 47, "anki": "1470840588805", "q": "Which equation is used to calculate blood flow (Q) from the pressure gradient and resistance?", "o": {"A": "Q = ΔP/R", "B": "Q = ΔP x R", "C": "Q = v/A", "D": "Q = R/ΔP"}, "r": "A", "e": {"correcta": "Blood flow equals the pressure gradient divided by resistance (Q = ΔP/R), analogous to Ohm's law (I = V/R) in electrical circuits.", "incorrectas": {"B": "Multiplying pressure by resistance is the inverse of the correct relationship and does not describe flow.", "C": "Q = v/A relates velocity and area but is not the pressure-resistance flow equation (rearranged, Q = v x A).", "D": "R/ΔP is the reciprocal of the correct formula and would give the wrong relationship between flow, pressure, and resistance."}}}, {"id": "anking-cardiovascular-physiology-489", "fuente": "anking", "tema": 47, "anki": "1470841597433", "q": "Blood flow (Q) is related to vascular resistance (R) in what way, according to Q = ΔP/R?", "o": {"A": "Inversely proportional", "B": "Directly proportional", "C": "Independent of resistance", "D": "Proportional to the square root of resistance"}, "r": "A", "e": {"correcta": "Because Q = ΔP/R, flow is inversely proportional to resistance — as resistance increases, flow decreases for a constant pressure gradient.", "incorrectas": {"B": "Direct proportionality would mean flow increases as resistance increases, which is the opposite of the true relationship.", "C": "Resistance directly determines flow in the equation Q = ΔP/R, so flow is not independent of it.", "D": "The relationship is a simple inverse proportion, not a square-root dependence."}}}, {"id": "anking-cardiovascular-physiology-490", "fuente": "anking", "tema": 47, "anki": "1470841601855", "q": "The magnitude of blood flow (Q) is related to the pressure difference between two points in what way?", "o": {"A": "Directly proportional", "B": "Inversely proportional", "C": "Unrelated to pressure difference", "D": "Proportional to the inverse square of pressure"}, "r": "A", "e": {"correcta": "From Q = ΔP/R, flow is directly proportional to the pressure gradient — a larger pressure difference produces greater flow for a given resistance.", "incorrectas": {"B": "Inverse proportionality would mean flow decreases as pressure difference increases, which contradicts Q = ΔP/R.", "C": "Pressure difference (ΔP) is the numerator in the flow equation, so flow is clearly related to it.", "D": "The relationship is a simple direct proportion, not an inverse-square relationship."}}}, {"id": "anking-cardiovascular-physiology-491", "fuente": "anking", "tema": 47, "anki": "1470841606399", "q": "The direction of blood flow is determined by the direction of what, always flowing from high to low?", "o": {"A": "Pressure gradient", "B": "Resistance gradient", "C": "Velocity gradient", "D": "Viscosity gradient"}, "r": "A", "e": {"correcta": "Blood always flows down its pressure gradient, from areas of higher pressure to areas of lower pressure, regardless of vessel type.", "incorrectas": {"B": "Resistance influences the magnitude of flow but does not itself dictate the direction of flow.", "C": "Velocity is a consequence of flow and area, not the determinant of flow direction.", "D": "Viscosity affects resistance and thus flow magnitude, but it does not determine the direction of blood flow."}}}, {"id": "anking-cardiovascular-physiology-492", "fuente": "anking", "tema": 47, "anki": "1470841609507", "q": "What is the term for the total resistance of the entire systemic vasculature?", "o": {"A": "Total peripheral resistance (TPR)", "B": "Pulmonary vascular resistance (PVR)", "C": "Central venous resistance", "D": "Coronary vascular resistance"}, "r": "A", "e": {"correcta": "Total peripheral resistance (TPR), also called systemic vascular resistance (SVR), is the resistance of the entire systemic circulation as a whole.", "incorrectas": {"B": "Pulmonary vascular resistance refers to the resistance of the pulmonary circulation, not the systemic circulation.", "C": "Central venous resistance is not a standard physiologic term used to describe overall systemic vascular resistance.", "D": "Coronary vascular resistance describes resistance within the coronary circulation specifically, not the entire systemic vasculature."}}}, {"id": "anking-cardiovascular-physiology-493", "fuente": "anking", "tema": 47, "anki": "1470844049174", "q": "What type of resistance arrangement is illustrated by the sequence of vessels within a given organ (artery to arteriole to capillary to venule to vein)?", "o": {"A": "Series resistance", "B": "Parallel resistance", "C": "Laminar resistance", "D": "Turbulent resistance"}, "r": "A", "e": {"correcta": "Vessels arranged sequentially within an organ (artery -> arteriole -> capillary -> venule -> vein) are in series, so their individual resistances sum to give the total resistance.", "incorrectas": {"B": "Parallel resistance describes vessels branching side by side (like major arteries off the aorta), not the sequential arrangement within a single organ.", "C": "\"Laminar\" describes a smooth flow pattern, not a type of resistance arrangement.", "D": "\"Turbulent\" describes a disorderly flow pattern, not a resistance arrangement."}}}, {"id": "anking-cardiovascular-physiology-494", "fuente": "anking", "tema": 47, "anki": "1470849965601", "q": "Which type of blood vessel causes the greatest decrease in pressure within a vascular system arranged in series?", "o": {"A": "Arterioles", "B": "Capillaries", "C": "Large arteries", "D": "Veins"}, "r": "A", "e": {"correcta": "Arterioles have the highest resistance of any vessel type in series, so per Q = ΔP/R, they cause the largest pressure drop across the vascular tree.", "incorrectas": {"B": "Capillaries have high total surface area for exchange but lower individual resistance than arterioles, so the pressure drop across them is smaller.", "C": "Large arteries have low resistance and cause only a small pressure drop compared to arterioles.", "D": "Veins are low-resistance capacitance vessels and contribute minimally to the overall pressure drop."}}}, {"id": "anking-cardiovascular-physiology-495", "fuente": "anking", "tema": 47, "anki": "1470849997969", "q": "What type of resistance arrangement is illustrated by the major systemic arteries branching off the aorta?", "o": {"A": "Parallel resistance", "B": "Series resistance", "C": "Capacitive resistance", "D": "Laminar resistance"}, "r": "A", "e": {"correcta": "Major arteries branching from the aorta to supply different organs are arranged in parallel, so total resistance is calculated as the reciprocal sum of the individual resistances.", "incorrectas": {"B": "Series resistance describes vessels arranged sequentially, as within a single organ, not branching arteries supplying separate parallel circuits.", "C": "\"Capacitive resistance\" is not a standard term used in this context of vascular resistance arrangements.", "D": "\"Laminar\" refers to a smooth flow pattern, not an arrangement of resistances."}}}, {"id": "anking-cardiovascular-physiology-496", "fuente": "anking", "tema": 47, "anki": "1470850010829", "q": "When a blood vessel is added to a system in series, what happens to the total resistance?", "o": {"A": "It increases", "B": "It decreases", "C": "It stays the same", "D": "It first decreases, then increases"}, "r": "A", "e": {"correcta": "In a series arrangement, resistances add directly (R_total = R1 + R2 + ...), so adding another vessel always increases total resistance.", "incorrectas": {"B": "A decrease in total resistance occurs when a vessel is added in parallel, not in series.", "C": "Adding any additional resistor (vessel) to a series circuit always changes total resistance; it cannot remain unchanged.", "D": "There is no biphasic change; series resistance simply increases in a straightforward additive manner."}}}, {"id": "anking-cardiovascular-physiology-497", "fuente": "anking", "tema": 47, "anki": "1470850014562", "q": "When a blood vessel is added to a system in parallel, what happens to the total resistance?", "o": {"A": "It decreases", "B": "It increases", "C": "It stays the same", "D": "It becomes infinite"}, "r": "A", "e": {"correcta": "In a parallel arrangement, 1/R_total = 1/R1 + 1/R2 + ..., so adding another parallel pathway always decreases total resistance.", "incorrectas": {"B": "An increase in total resistance occurs when a vessel is added in series, not in parallel.", "C": "Adding another parallel pathway always provides an additional route for flow, which lowers total resistance rather than keeping it constant.", "D": "Adding a parallel vessel lowers, rather than raises, total resistance, and would never make it infinite."}}}, {"id": "anking-cardiovascular-physiology-498", "fuente": "anking", "tema": 47, "anki": "1470850018953", "q": "In which type of vessel arrangement is the total resistance less than the resistance of any individual vessel in the system?", "o": {"A": "Parallel", "B": "Series", "C": "Tandem", "D": "Sequential"}, "r": "A", "e": {"correcta": "In parallel arrangements, since 1/R_total = 1/R1 + 1/R2 + ..., the total resistance is always less than the resistance of any single branch, as seen in the systemic arterial branches.", "incorrectas": {"B": "In series arrangements, total resistance is the sum of individual resistances and is therefore greater than any single component's resistance.", "C": "\"Tandem\" is essentially synonymous with series arrangement, where resistances add rather than combine to produce a lower total.", "D": "\"Sequential\" arrangement also describes a series configuration, which increases rather than decreases total resistance."}}}, {"id": "anking-cardiovascular-physiology-499", "fuente": "anking", "tema": 47, "anki": "1470850036482", "q": "Ideally, blood flow in the cardiovascular system is described as what type of flow, meaning it is streamlined?", "o": {"A": "Laminar", "B": "Turbulent", "C": "Pulsatile", "D": "Retrograde"}, "r": "A", "e": {"correcta": "Laminar flow refers to smooth, streamlined blood flow with concentric layers moving parallel to the vessel wall, which is the ideal, low-energy-loss state of blood flow.", "incorrectas": {"B": "Turbulent flow is disorderly and chaotic, often produced by high velocity, vessel narrowing, or low viscosity, and is associated with audible bruits/murmurs — it is not the ideal state.", "C": "Pulsatile describes the rhythmic pressure/flow pattern driven by the cardiac cycle, not the smoothness or streamlining of flow.", "D": "Retrograde describes flow in the reverse of the normal direction (e.g., valve regurgitation), not a description of streamlined flow."}}}, {"id": "anking-cardiovascular-pharmacology-500", "fuente": "anking", "tema": 48, "anki": "1471995423922", "q": "Class I antiarrhythmic drugs exert their primary mechanism of action by blocking which ion channel?", "o": {"A": "Na+ channels", "B": "Ca2+ channels", "C": "K+ channels", "D": "Cl- channels"}, "r": "A", "e": {"correcta": "Class I antiarrhythmics are defined by their blockade of voltage-gated Na+ channels in cardiac myocytes, which slows phase 0 depolarization.", "incorrectas": {"B": "Ca2+ channel blockade is the mechanism of Class IV antiarrhythmics (e.g., verapamil, diltiazem), not Class I.", "C": "K+ channel blockade is the primary mechanism of Class III antiarrhythmics (e.g., amiodarone, sotalol).", "D": "Cl- channel blockade is not a recognized mechanism of any standard antiarrhythmic drug class."}}}, {"id": "anking-cardiovascular-pharmacology-501", "fuente": "anking", "tema": 48, "anki": "1471999854180", "q": "What effect do Class I antiarrhythmics have on the conduction velocity of the myocardial action potential?", "o": {"A": "Decreased conduction velocity", "B": "Increased conduction velocity", "C": "No change in conduction velocity", "D": "Conduction velocity becomes variable/unpredictable"}, "r": "A", "e": {"correcta": "By blocking Na+ channels, Class I antiarrhythmics slow the rate of phase 0 depolarization, which decreases conduction velocity through myocardial tissue.", "incorrectas": {"B": "Increased conduction velocity would require faster Na+ influx, the opposite of what Na+ channel blockade produces.", "C": "Conduction velocity is directly reduced because Na+ channel blockade slows the upstroke of the action potential.", "D": "The effect is consistent and predictable (a decrease), not variable."}}}, {"id": "anking-cardiovascular-pharmacology-502", "fuente": "anking", "tema": 48, "anki": "1471999865945", "q": "Class I antiarrhythmics preferentially bind to Na+ channels in which two conformational states?", "o": {"A": "Open or inactivated states", "B": "Resting or closed states", "C": "Only the resting state", "D": "Only the open state"}, "r": "A", "e": {"correcta": "Class I antiarrhythmics have the highest affinity for Na+ channels when they are in the open or inactivated states, which is why they preferentially affect rapidly depolarizing (diseased or tachycardic) tissue.", "incorrectas": {"B": "The resting/closed state has low affinity for these drugs; binding there would not explain their selective action on active tissue.", "C": "Binding only to the resting state would not produce use-dependent block, which is the hallmark of Class I drugs.", "D": "They bind to both open and inactivated states, not the open state alone."}}}, {"id": "anking-cardiovascular-pharmacology-503", "fuente": "anking", "tema": 48, "anki": "1471999885871", "q": "In rapidly depolarizing tissue (e.g., during tachycardia), Na+ channels spend the ____ amount of time in the open or inactivated states compared to normal tissue.", "o": {"A": "Most (greatest)", "B": "Least", "C": "Same amount of", "D": "Unpredictable amount of"}, "r": "A", "e": {"correcta": "Rapidly depolarizing tissue spends more time with Na+ channels open or inactivated, making it more susceptible to blockade by Class I antiarrhythmics (the basis of use-dependence).", "incorrectas": {"B": "Tissue depolarizing rapidly spends more, not less, time in these susceptible states.", "C": "Rapidly depolarizing tissue spends disproportionately more time in these states compared to normal tissue.", "D": "The relationship is predictable and directly tied to depolarization frequency."}}}, {"id": "anking-cardiovascular-pharmacology-504", "fuente": "anking", "tema": 48, "anki": "1471999893105", "q": "The property by which Class I antiarrhythmics selectively depress tissue that is frequently depolarized (such as tachyarrhythmic tissue) is known as what?", "o": {"A": "Use dependence", "B": "Reverse use dependence", "C": "Tachyphylaxis", "D": "Receptor downregulation"}, "r": "A", "e": {"correcta": "Use dependence describes the property whereby Class I antiarrhythmics bind more effectively to frequently opened/inactivated Na+ channels, giving them a greater effect on rapidly depolarizing (e.g., tachyarrhythmic) tissue.", "incorrectas": {"B": "Reverse use dependence describes drugs (typically some Class III agents) that have greater effect at slower heart rates, the opposite concept.", "C": "Tachyphylaxis refers to rapidly diminishing drug response with repeated dosing, unrelated to this channel-state-dependent binding.", "D": "Receptor downregulation refers to reduced receptor number/sensitivity with chronic agonist exposure, not a channel-blocking mechanism."}}}, {"id": "anking-cardiovascular-pharmacology-505", "fuente": "anking", "tema": 48, "anki": "1471999905712", "q": "What effect do Class I antiarrhythmics have on the action potentials of the SA and AV nodes?", "o": {"A": "No effect, since these nodes rely on Ca2+-dependent rather than Na+-dependent action potentials", "B": "They significantly slow SA and AV nodal conduction", "C": "They increase the rate of SA and AV nodal firing", "D": "They abolish SA and AV nodal automaticity"}, "r": "A", "e": {"correcta": "SA and AV nodal action potentials are generated primarily by slow Ca2+ channels rather than fast Na+ channels, so Class I antiarrhythmics (which target Na+ channels) have little to no effect on these tissues.", "incorrectas": {"B": "Significant slowing of nodal conduction is characteristic of Class II and IV drugs, not Class I.", "C": "Class I drugs do not increase nodal firing rate; they have essentially no direct effect on nodal tissue.", "D": "Class I drugs do not abolish nodal automaticity since they do not act on the Ca2+ channels that drive nodal depolarization."}}}, {"id": "anking-cardiovascular-pharmacology-506", "fuente": "anking", "tema": 48, "anki": "1471999913609", "q": "Class I antiarrhythmics have what effect on the QRS complex on ECG?", "o": {"A": "Widen the QRS complex", "B": "Narrow the QRS complex", "C": "No change in QRS width", "D": "Eliminate the QRS complex"}, "r": "A", "e": {"correcta": "By slowing Na+-channel-dependent conduction velocity through ventricular myocardium, Class I antiarrhythmics widen the QRS complex on ECG.", "incorrectas": {"B": "Narrowing would imply faster conduction, which contradicts the Na+ channel-blocking mechanism.", "C": "QRS width is directly affected because ventricular depolarization (QRS) depends on Na+ channel-mediated conduction.", "D": "These drugs slow but do not eliminate ventricular depolarization, so the QRS complex remains present, just widened."}}}, {"id": "anking-cardiovascular-pharmacology-507", "fuente": "anking", "tema": 48, "anki": "1471999991212", "q": "One important adverse effect of disopyramide is exacerbation of which condition, due to its negative inotropic effects?", "o": {"A": "Heart failure", "B": "Hyperthyroidism", "C": "Chronic kidney disease", "D": "Peptic ulcer disease"}, "r": "A", "e": {"correcta": "Disopyramide has pronounced negative inotropic (myocardial-depressant) effects, which can precipitate or worsen heart failure, making it relatively contraindicated in patients with reduced cardiac function.", "incorrectas": {"B": "Disopyramide is not known to worsen hyperthyroidism; it is not implicated in thyroid pathology.", "C": "Its major concerning adverse effect is cardiac (negative inotropy), not renal.", "D": "Disopyramide's anticholinergic effects can cause GI symptoms like constipation, but it is not classically linked to worsening peptic ulcer disease."}}}, {"id": "anking-cardiovascular-pharmacology-508", "fuente": "anking", "tema": 48, "anki": "1472000006974", "q": "Class IA antiarrhythmics have what relative binding affinity for the Na+ channel?", "o": {"A": "Intermediate", "B": "Very low/negligible", "C": "Extremely strong/irreversible", "D": "Variable and unrelated to channel state"}, "r": "A", "e": {"correcta": "Class IA drugs have an intermediate binding affinity for Na+ channels, producing moderate use-dependence and moderate slowing of phase 0 upstroke, positioning them between Class IB (low affinity) and Class IC (strong affinity).", "incorrectas": {"B": "A very low affinity describes Class IB agents, not Class IA.", "C": "An extremely strong affinity describes Class IC agents, not Class IA.", "D": "Binding affinity for these drugs is specifically tied to channel state (open/inactivated), not random or unrelated."}}}, {"id": "anking-cardiovascular-pharmacology-509", "fuente": "anking", "tema": 48, "anki": "1472000019446", "q": "In addition to Na+ channels, Class IA antiarrhythmics also block which other channel?", "o": {"A": "K+ channels", "B": "Ca2+ channels", "C": "Cl- channels", "D": "HCN (funny) channels"}, "r": "A", "e": {"correcta": "Class IA antiarrhythmics also block K+ channels, which prolongs phase 2 and 3 repolarization and lengthens the refractory period (and QT interval).", "incorrectas": {"B": "Ca2+ channel blockade is a property of Class IV agents, not an additional action of Class IA drugs.", "C": "Cl- channel blockade is not part of the Class IA mechanism.", "D": "HCN channel blockade (as with ivabradine) is unrelated to Class IA antiarrhythmic action."}}}, {"id": "anking-cardiovascular-pharmacology-510", "fuente": "anking", "tema": 48, "anki": "1472000027736", "q": "What effect do Class IA antiarrhythmics have on action potential duration?", "o": {"A": "Increased duration", "B": "Decreased duration", "C": "No change in duration", "D": "Biphasic effect (initially increased, then decreased)"}, "r": "A", "e": {"correcta": "Class IA drugs prolong action potential duration because their added K+ channel blockade extends phases 2 and 3 of repolarization.", "incorrectas": {"B": "Decreased action potential duration is characteristic of Class IB drugs, not Class IA.", "C": "Action potential duration is changed (increased), given the added K+ channel blocking effect of Class IA agents.", "D": "There is no established biphasic effect on action potential duration for Class IA drugs; the effect is a straightforward increase."}}}, {"id": "anking-cardiovascular-pharmacology-511", "fuente": "anking", "tema": 48, "anki": "1472000038292", "q": "What effect do Class IA antiarrhythmics have on the effective refractory period (ERP) in ventricular tissue?", "o": {"A": "Increased ERP", "B": "Decreased ERP", "C": "No change in ERP", "D": "ERP becomes unmeasurable"}, "r": "A", "e": {"correcta": "Because Class IA antiarrhythmics prolong the action potential duration via K+ channel blockade, they increase the effective refractory period of ventricular tissue.", "incorrectas": {"B": "A decreased ERP is a feature of Class IB drugs, which shorten action potential duration.", "C": "ERP is altered (increased) because of the added K+ channel blocking property unique to Class IA agents.", "D": "ERP remains a measurable clinical/electrophysiologic parameter; it is simply prolonged, not eliminated."}}}, {"id": "anking-cardiovascular-pharmacology-512", "fuente": "anking", "tema": 48, "anki": "1472000042817", "q": "Class IA antiarrhythmics are used to treat which type(s) of arrhythmia?", "o": {"A": "Both supraventricular and ventricular arrhythmias", "B": "Only supraventricular arrhythmias", "C": "Only ventricular arrhythmias", "D": "Only bradyarrhythmias"}, "r": "A", "e": {"correcta": "Class IA antiarrhythmics (e.g., quinidine, procainamide, disopyramide) have a broad spectrum of activity and are used for both supraventricular and ventricular arrhythmias, particularly re-entrant and ectopic types.", "incorrectas": {"B": "Restricting use to only supraventricular arrhythmias understates their efficacy, as they are also effective for ventricular arrhythmias.", "C": "Restricting use to only ventricular arrhythmias ignores their proven efficacy in supraventricular arrhythmias like SVT.", "D": "Class IA drugs are used for tachyarrhythmias, not bradyarrhythmias, which are treated with different approaches (e.g., atropine, pacing)."}}}, {"id": "anking-cardiovascular-pharmacology-513", "fuente": "anking", "tema": 48, "anki": "1472000056279", "q": "Which subclass of Class I antiarrhythmics may be used to treat Wolff-Parkinson-White (WPW) syndrome, a type of SVT?", "o": {"A": "Class IA", "B": "Class IB", "C": "Class IC", "D": "Class II"}, "r": "A", "e": {"correcta": "Class IA antiarrhythmics, especially procainamide, are used in the treatment of WPW-associated arrhythmias because of their efficacy against re-entrant supraventricular tachycardias.", "incorrectas": {"B": "Class IB drugs (e.g., lidocaine) are primarily used for ventricular arrhythmias, not WPW-related SVT.", "C": "Class IC drugs, while used in some SVTs, are not the classic answer for WPW; procainamide (Class IA) is the specifically noted agent.", "D": "Class II agents (beta-blockers) are not the specific class highlighted for WPW management in this context and can be risky in WPW with rapid conduction over the accessory pathway."}}}, {"id": "anking-cardiovascular-pharmacology-514", "fuente": "anking", "tema": 48, "anki": "1472000103258", "q": "Class IB antiarrhythmics have what relative binding affinity for the Na+ channel?", "o": {"A": "Low", "B": "Intermediate", "C": "Very strong", "D": "Highest of all antiarrhythmic classes"}, "r": "A", "e": {"correcta": "Class IB antiarrhythmics have a low binding affinity for Na+ channels, producing only modest slowing of the phase 0 upstroke, but they characteristically shorten the QT interval.", "incorrectas": {"B": "An intermediate affinity describes Class IA agents, not Class IB.", "C": "A very strong affinity describes Class IC agents, not Class IB.", "D": "Class IC agents have the strongest binding affinity among Class I subclasses, not Class IB."}}}, {"id": "anking-cardiovascular-pharmacology-515", "fuente": "anking", "tema": 48, "anki": "1472000114229", "q": "What effect do Class IB antiarrhythmics have on action potential duration?", "o": {"A": "Shortened duration", "B": "Increased duration", "C": "No change in duration", "D": "Duration becomes prolonged only in ischemic tissue"}, "r": "A", "e": {"correcta": "Class IB antiarrhythmics shorten action potential duration by shortening phases 2 and 3, which decreases the refractory period and characteristically shortens the QT interval.", "incorrectas": {"B": "Increased action potential duration is a feature of Class IA drugs (via K+ channel blockade), not Class IB.", "C": "Duration is changed (shortened) due to the effect on Na+ channel inactivated-state binding, which alters repolarization.", "D": "While Class IB drugs do have a preferential effect on depolarized/ischemic tissue, the shortening of action potential duration is a general property, not limited only to ischemic tissue."}}}, {"id": "anking-cardiovascular-pharmacology-516", "fuente": "anking", "tema": 48, "anki": "1472000134782", "q": "Which subclass of Class I antiarrhythmics may be used to treat digitalis (digoxin)-induced arrhythmias?", "o": {"A": "Class IB", "B": "Class IA", "C": "Class IC", "D": "Class III"}, "r": "A", "e": {"correcta": "Class IB antiarrhythmics (e.g., lidocaine) shorten the QT interval, which counteracts the QT-prolonging effect of digoxin toxicity, making them useful for digitalis-induced arrhythmias.", "incorrectas": {"B": "Class IA drugs prolong the QT interval, which would worsen rather than counteract digoxin-induced QT prolongation.", "C": "Class IC drugs are not specifically indicated for digitalis-induced arrhythmias; their strong Na+ channel blockade is used in other contexts (e.g., SVT without structural heart disease).", "D": "Class III drugs (e.g., amiodarone) generally prolong the QT interval and are not the therapy of choice for digitalis-induced arrhythmias."}}}, {"id": "anking-cardiovascular-pharmacology-517", "fuente": "anking", "tema": 48, "anki": "1472000170602", "q": "Class IC antiarrhythmics have what relative binding affinity for the Na+ channel?", "o": {"A": "Strong", "B": "Low", "C": "Intermediate", "D": "No appreciable affinity"}, "r": "A", "e": {"correcta": "Class IC antiarrhythmics have a strong binding affinity for Na+ channels, resulting in pronounced use-dependence and drastic slowing of the phase 0 upstroke.", "incorrectas": {"B": "A low affinity describes Class IB agents, not Class IC.", "C": "An intermediate affinity describes Class IA agents, not Class IC.", "D": "Class IC drugs are Na+ channel blockers by definition and have the strongest affinity among Class I subclasses, not negligible affinity."}}}, {"id": "anking-cardiovascular-anatomy-518", "fuente": "anking", "tema": 49, "anki": "1470839287077", "q": "Blood flows from the left atrium to the left ventricle through which valve?", "o": {"A": "Mitral (bicuspid) valve", "B": "Tricuspid valve", "C": "Pulmonic valve", "D": "Aortic valve"}, "r": "A", "e": {"correcta": "The mitral (bicuspid) valve separates the left atrium from the left ventricle and directs oxygenated blood flow between these chambers.", "incorrectas": {"B": "The tricuspid valve is on the right side of the heart, between the right atrium and right ventricle.", "C": "The pulmonic valve is between the right ventricle and pulmonary artery, not on the left side.", "D": "The aortic valve is between the left ventricle and the aorta, not between the atrium and ventricle."}}}, {"id": "anking-cardiovascular-anatomy-519", "fuente": "anking", "tema": 49, "anki": "1470839303346", "q": "Blood flows from which structure to the systemic arteries and tissues?", "o": {"A": "Aorta", "B": "Pulmonary vein", "C": "Vena cava", "D": "Right ventricle"}, "r": "A", "e": {"correcta": "The aorta is the great vessel that carries oxygenated blood from the left ventricle to the systemic arteries and tissues throughout the body.", "incorrectas": {"B": "The pulmonary vein carries oxygenated blood from the lungs to the left atrium, not to systemic tissues directly.", "C": "The vena cava carries deoxygenated blood from tissues back to the right atrium, the opposite direction.", "D": "The right ventricle pumps blood to the pulmonary artery, not to the systemic circulation."}}}, {"id": "anking-cardiovascular-anatomy-520", "fuente": "anking", "tema": 49, "anki": "1470839310425", "q": "Blood flows from the tissues to the systemic veins and ultimately to which structure before returning to the right atrium?", "o": {"A": "Vena cava", "B": "Aorta", "C": "Pulmonary artery", "D": "Coronary sinus"}, "r": "A", "e": {"correcta": "The vena cava (superior and inferior) collects deoxygenated blood from systemic veins and delivers it to the right atrium.", "incorrectas": {"B": "The aorta carries oxygenated blood away from the left ventricle, not toward the right atrium.", "C": "The pulmonary artery carries deoxygenated blood from the right ventricle to the lungs, not from systemic veins to the atrium.", "D": "The coronary sinus drains blood specifically from the cardiac veins, not the general systemic venous return."}}}, {"id": "anking-cardiovascular-anatomy-521", "fuente": "anking", "tema": 49, "anki": "1470839316273", "q": "Deoxygenated blood flows from the vena cava into which chamber of the heart?", "o": {"A": "Right atrium", "B": "Left atrium", "C": "Right ventricle", "D": "Left ventricle"}, "r": "A", "e": {"correcta": "The superior and inferior vena cavae empty deoxygenated blood directly into the right atrium.", "incorrectas": {"B": "The left atrium receives oxygenated blood from the pulmonary veins, not from the vena cava.", "C": "The right ventricle receives blood from the right atrium via the tricuspid valve, not directly from the vena cava.", "D": "The left ventricle receives oxygenated blood from the left atrium, not deoxygenated blood from the vena cava."}}}, {"id": "anking-cardiovascular-anatomy-522", "fuente": "anking", "tema": 49, "anki": "1470839322331", "q": "Blood flows from the right atrium to the right ventricle through which valve?", "o": {"A": "Tricuspid valve", "B": "Mitral valve", "C": "Pulmonic valve", "D": "Aortic valve"}, "r": "A", "e": {"correcta": "The tricuspid valve separates the right atrium from the right ventricle, allowing deoxygenated blood to pass between these chambers.", "incorrectas": {"B": "The mitral valve is on the left side of the heart, between the left atrium and left ventricle.", "C": "The pulmonic valve is located between the right ventricle and the pulmonary artery, not between the atrium and ventricle.", "D": "The aortic valve is between the left ventricle and aorta, unrelated to right-sided atrioventricular flow."}}}, {"id": "anking-cardiovascular-anatomy-523", "fuente": "anking", "tema": 49, "anki": "1470839328752", "q": "Blood flows from the right ventricle to the pulmonary artery through which valve?", "o": {"A": "Pulmonic valve", "B": "Tricuspid valve", "C": "Mitral valve", "D": "Aortic valve"}, "r": "A", "e": {"correcta": "The pulmonic (pulmonary) valve lies between the right ventricle and the pulmonary artery, allowing deoxygenated blood to be ejected toward the lungs.", "incorrectas": {"B": "The tricuspid valve is between the right atrium and right ventricle, not the outflow to the pulmonary artery.", "C": "The mitral valve is on the left side of the heart, between the left atrium and left ventricle.", "D": "The aortic valve is the outflow valve of the left ventricle into the aorta, not the pulmonary circuit."}}}, {"id": "anking-cardiovascular-anatomy-524", "fuente": "anking", "tema": 49, "anki": "1470839334989", "q": "Blood flows from the pulmonary artery to which structure for oxygenation?", "o": {"A": "Lungs", "B": "Left atrium", "C": "Aorta", "D": "Liver"}, "r": "A", "e": {"correcta": "The pulmonary artery carries deoxygenated blood from the right ventricle to the lungs, where gas exchange (oxygenation) occurs.", "incorrectas": {"B": "The left atrium receives oxygenated blood after gas exchange has already occurred in the lungs, via the pulmonary veins.", "C": "The aorta carries oxygenated blood from the left ventricle to the body, unrelated to the pulmonary circuit's oxygenation step.", "D": "The liver receives blood via the portal and hepatic circulation and is not involved in blood oxygenation."}}}, {"id": "anking-cardiovascular-anatomy-525", "fuente": "anking", "tema": 49, "anki": "1470839340859", "q": "Which type of blood vessel has extensive elastic tissue and smooth muscle?", "o": {"A": "Artery", "B": "Vein", "C": "Capillary", "D": "Venule"}, "r": "A", "e": {"correcta": "Arteries have thick walls with abundant elastic tissue and smooth muscle, allowing them to withstand and modulate high pressure pulsatile flow from the heart.", "incorrectas": {"B": "Veins have thinner walls with less elastic tissue and smooth muscle since they operate under low pressure.", "C": "Capillaries consist of only a single layer of endothelium and lack smooth muscle or elastic tissue, enabling exchange.", "D": "Venules are small, thin-walled vessels similar to veins and lack the extensive elastic and muscular layers of arteries."}}}, {"id": "anking-cardiovascular-anatomy-526", "fuente": "anking", "tema": 49, "anki": "1470839343366", "q": "Arteries are under what type of pressure?", "o": {"A": "High pressure", "B": "Low pressure", "C": "Negative pressure", "D": "Isobaric (constant) pressure"}, "r": "A", "e": {"correcta": "Arteries carry blood under high pressure generated by ventricular contraction, requiring thick, elastic, muscular walls.", "incorrectas": {"B": "Low pressure characterizes the venous system, which serves as a capacitance (blood reservoir) system, not arteries.", "C": "Negative pressure is not a normal physiological state of the arterial system.", "D": "Arterial pressure is pulsatile, fluctuating between systolic and diastolic values, not constant."}}}, {"id": "anking-cardiovascular-anatomy-527", "fuente": "anking", "tema": 49, "anki": "1470839346067", "q": "What is the term for the blood volume contained in the arteries?", "o": {"A": "Stressed volume", "B": "Unstressed volume", "C": "Central venous volume", "D": "Residual volume"}, "r": "A", "e": {"correcta": "Stressed volume refers to the blood volume in the arterial (high-pressure) system that generates wall tension and vascular pressure.", "incorrectas": {"B": "Unstressed volume refers to the blood volume in the veins, which does not generate significant pressure and acts as a reservoir.", "C": "Central venous volume relates to blood in the great veins near the heart, part of the low-pressure venous system, not arteries.", "D": "Residual volume is a respiratory physiology term referring to air remaining in the lungs after maximal exhalation, not a vascular volume term."}}}, {"id": "anking-cardiovascular-anatomy-528", "fuente": "anking", "tema": 49, "anki": "1470839348573", "q": "What are the smallest branches of arteries called?", "o": {"A": "Arterioles", "B": "Capillaries", "C": "Venules", "D": "Metarterioles"}, "r": "A", "e": {"correcta": "Arterioles are the smallest branches of the arterial tree and are the primary site of resistance regulation in the circulation.", "incorrectas": {"B": "Capillaries are downstream of arterioles and are single-cell-layer vessels for exchange, not arterial branches per se.", "C": "Venules are the smallest branches of the venous system, on the return side of circulation, not arterial branches.", "D": "Metarterioles are a less emphasized transitional vessel type but are not the standard answer for smallest arterial branch in USMLE physiology."}}}, {"id": "anking-cardiovascular-anatomy-529", "fuente": "anking", "tema": 49, "anki": "1470839353901", "q": "Arteriolar resistance is regulated primarily by which division of the nervous system?", "o": {"A": "Sympathetic nervous system", "B": "Parasympathetic nervous system", "C": "Somatic nervous system", "D": "Enteric nervous system"}, "r": "A", "e": {"correcta": "The sympathetic nervous system regulates arteriolar smooth muscle tone via adrenergic receptors, controlling vascular resistance and blood pressure.", "incorrectas": {"B": "The parasympathetic nervous system has minimal direct innervation of most peripheral arterioles and does not primarily regulate their resistance.", "C": "The somatic nervous system innervates skeletal muscle for voluntary movement, not vascular smooth muscle.", "D": "The enteric nervous system governs gastrointestinal motility and secretion, not systemic arteriolar resistance."}}}, {"id": "anking-cardiovascular-anatomy-530", "fuente": "anking", "tema": 49, "anki": "1470839358207", "q": "What type of receptor is found on the arterioles of skin, splanchnic, and renal circulation?", "o": {"A": "α1-adrenergic receptors", "B": "β1-adrenergic receptors", "C": "β2-adrenergic receptors", "D": "M3 muscarinic receptors"}, "r": "A", "e": {"correcta": "α1-adrenergic receptors predominate on arterioles of the skin, splanchnic, and renal circulations, mediating vasoconstriction in these vascular beds.", "incorrectas": {"B": "β1-adrenergic receptors are primarily located in the heart, increasing heart rate and contractility, not on these arterioles.", "C": "β2-adrenergic receptors predominate in skeletal muscle arterioles, causing vasodilation, not in skin/splanchnic/renal beds.", "D": "M3 muscarinic receptors mediate parasympathetic effects such as smooth muscle contraction in other organs and endothelium-dependent vasodilation, not the primary sympathetic control of these arterioles."}}}, {"id": "anking-cardiovascular-anatomy-531", "fuente": "anking", "tema": 49, "anki": "1470839374491", "q": "What types of receptors are found on the arterioles of skeletal muscle?", "o": {"A": "α1- and β2-adrenergic receptors", "B": "α1-adrenergic receptors only", "C": "β1-adrenergic receptors only", "D": "M2 muscarinic receptors"}, "r": "A", "e": {"correcta": "Skeletal muscle arterioles contain both α1-adrenergic receptors (vasoconstriction) and β2-adrenergic receptors (vasodilation), allowing dual regulation of blood flow depending on which is predominantly activated.", "incorrectas": {"B": "α1-adrenergic receptors alone characterize skin, splanchnic, and renal arterioles, not the dual receptor pattern of skeletal muscle.", "C": "β1-adrenergic receptors are mainly cardiac receptors affecting heart rate and contractility, not the primary receptors on skeletal muscle arterioles.", "D": "M2 muscarinic receptors are primarily found in the heart (mediating vagal slowing of heart rate), not on skeletal muscle arterioles."}}}, {"id": "anking-cardiovascular-anatomy-532", "fuente": "anking", "tema": 49, "anki": "1470839380176", "q": "When activated, α1-adrenergic receptors cause what effect on vascular smooth muscle?", "o": {"A": "Contraction", "B": "Relaxation", "C": "Hyperplasia", "D": "Apoptosis"}, "r": "A", "e": {"correcta": "α1-adrenergic receptor activation triggers a Gq-mediated increase in intracellular calcium, causing contraction (vasoconstriction) of vascular smooth muscle.", "incorrectas": {"B": "Relaxation is the effect produced by β2-adrenergic receptor activation, not α1 activation.", "C": "Hyperplasia refers to increased cell number and is not an acute functional effect of α1 receptor activation.", "D": "Apoptosis (programmed cell death) is not a direct or acute consequence of α1-adrenergic receptor stimulation."}}}, {"id": "anking-cardiovascular-anatomy-533", "fuente": "anking", "tema": 49, "anki": "1470839383062", "q": "When activated, β2-adrenergic receptors cause what effect on vascular smooth muscle?", "o": {"A": "Relaxation", "B": "Contraction", "C": "Hypertrophy", "D": "Increased permeability"}, "r": "A", "e": {"correcta": "β2-adrenergic receptor activation increases cAMP, leading to relaxation (vasodilation) of vascular smooth muscle, notably in skeletal muscle arterioles.", "incorrectas": {"B": "Contraction is the effect of α1-adrenergic receptor activation, the opposite of β2 receptor action.", "C": "Hypertrophy is a chronic structural change, not the acute functional effect of β2 receptor stimulation on smooth muscle tone.", "D": "Increased vascular permeability is more associated with inflammatory mediators (e.g., histamine) rather than β2-adrenergic signaling."}}}, {"id": "anking-cardiovascular-anatomy-534", "fuente": "anking", "tema": 49, "anki": "1470839385654", "q": "Which type of blood vessel has the largest total cross-sectional and surface area?", "o": {"A": "Capillaries", "B": "Arteries", "C": "Veins", "D": "Arterioles"}, "r": "A", "e": {"correcta": "Capillaries, despite their small individual diameter, are so numerous that collectively they have the largest total cross-sectional area and surface area of any vessel type, which slows blood velocity and favors exchange.", "incorrectas": {"B": "Arteries have a much smaller total cross-sectional area than capillaries despite carrying blood at higher velocity and pressure.", "C": "Veins have a larger total cross-sectional area than arteries but still less than the capillary bed.", "D": "Arterioles have a smaller total cross-sectional area than capillaries since there are far fewer of them."}}}, {"id": "anking-cardiovascular-anatomy-535", "fuente": "anking", "tema": 49, "anki": "1470839388021", "q": "Which type of blood vessel is the primary site of exchange of nutrients, water, and gases?", "o": {"A": "Capillaries", "B": "Arteries", "C": "Veins", "D": "Arterioles"}, "r": "A", "e": {"correcta": "Capillaries have thin, single-cell-layer walls and large total surface area, making them the ideal and primary site for exchange of nutrients, water, and gases between blood and tissue.", "incorrectas": {"B": "Arteries have thick muscular and elastic walls designed for conducting blood under pressure, not for exchange.", "C": "Veins have thin walls but function mainly as capacitance vessels for blood return, not as primary exchange sites.", "D": "Arterioles primarily regulate resistance and blood flow distribution rather than serving as the main exchange site."}}}, {"id": "anking-dermatology-536", "fuente": "anking", "tema": 50, "anki": "1488502261762", "q": "Which layer of the epidermis serves as the regenerative (stem cell) layer?", "o": {"A": "Stratum basalis", "B": "Stratum spinosum", "C": "Stratum granulosum", "D": "Stratum corneum"}, "r": "A", "e": {"correcta": "The stratum basalis is the deepest epidermal layer and contains the stem cells responsible for continuous keratinocyte renewal.", "incorrectas": {"B": "Stratum spinosum is the layer above the basal layer, notable for desmosomal connections, not stem cell activity.", "C": "Stratum granulosum contains keratohyalin granules involved in keratinization, not regeneration.", "D": "Stratum corneum is the outermost, anucleate, keratinized layer with no proliferative capacity."}}}, {"id": "anking-dermatology-537", "fuente": "anking", "tema": 50, "anki": "1488502267697", "q": "Which epidermal layer is characterized by prominent desmosomes connecting keratinocytes (giving a 'spiny' appearance)?", "o": {"A": "Stratum spinosum", "B": "Stratum basalis", "C": "Stratum lucidum", "D": "Stratum corneum"}, "r": "A", "e": {"correcta": "The stratum spinosum shows numerous desmosomes between keratinocytes, which appear as intercellular spines on histology.", "incorrectas": {"B": "Stratum basalis is the basal proliferative layer, not defined by prominent desmosomes.", "C": "Stratum lucidum is a thin clear layer found only in thick skin, composed of flattened eosinophilic cells.", "D": "Stratum corneum consists of anucleate, keratin-filled dead cells, not desmosome-rich keratinocytes."}}}, {"id": "anking-dermatology-538", "fuente": "anking", "tema": 50, "anki": "1488502276594", "q": "Which epidermal layer is characterized by keratohyalin granules within keratinocytes?", "o": {"A": "Stratum granulosum", "B": "Stratum basalis", "C": "Stratum spinosum", "D": "Stratum corneum"}, "r": "A", "e": {"correcta": "The stratum granulosum contains keratohyalin granules that participate in keratin filament aggregation during terminal differentiation.", "incorrectas": {"B": "Stratum basalis is the proliferative basal layer without keratohyalin granules.", "C": "Stratum spinosum is defined by desmosomal spines, not granules.", "D": "Stratum corneum is composed of dead, anucleate, keratin-filled cells without granules."}}}, {"id": "anking-dermatology-539", "fuente": "anking", "tema": 50, "anki": "1488502326517", "q": "Which epidermal layer consists of keratin-filled, anucleate cells?", "o": {"A": "Stratum corneum", "B": "Stratum basalis", "C": "Stratum granulosum", "D": "Stratum spinosum"}, "r": "A", "e": {"correcta": "The stratum corneum is the outermost epidermal layer, composed of flattened, anucleate corneocytes packed with keratin that form the skin's barrier.", "incorrectas": {"B": "Stratum basalis is the deepest layer with nucleated, proliferating cells.", "C": "Stratum granulosum contains nucleated keratinocytes with keratohyalin granules.", "D": "Stratum spinosum contains nucleated keratinocytes joined by desmosomes."}}}, {"id": "anking-dermatology-540", "fuente": "anking", "tema": 50, "anki": "1488502331191", "q": "Which skin layers contain nerve endings, blood vessels, lymphatics, and adnexal structures such as hair follicles and glands?", "o": {"A": "Dermis and hypodermis", "B": "Epidermis and stratum corneum", "C": "Stratum basalis and stratum spinosum", "D": "Stratum granulosum and stratum lucidum"}, "r": "A", "e": {"correcta": "The dermis and hypodermis (subcutaneous tissue) are vascularized, innervated layers housing hair follicles, sweat and sebaceous glands, unlike the avascular epidermis.", "incorrectas": {"B": "The epidermis and its outer stratum corneum are avascular and lack adnexal structures.", "C": "These are epidermal sublayers, avascular and without adnexal glands.", "D": "These are also epidermal sublayers, avascular and lacking nerves or adnexal structures."}}}, {"id": "anking-dermatology-541", "fuente": "anking", "tema": 50, "anki": "1488502337028", "q": "Which epithelial cell junction prevents paracellular movement of solutes between cells?", "o": {"A": "Tight junctions (zonula occludens)", "B": "Adherens junctions", "C": "Desmosomes", "D": "Gap junctions"}, "r": "A", "e": {"correcta": "Tight junctions (zonula occludens) seal the space between adjacent epithelial cells, blocking paracellular diffusion of solutes and maintaining apical-basal polarity.", "incorrectas": {"B": "Adherens junctions provide mechanical adhesion via actin filament linkage but do not seal paracellular pathways.", "C": "Desmosomes provide strong mechanical adhesion via intermediate filaments, not solute barrier function.", "D": "Gap junctions allow direct intercellular communication, not solute exclusion."}}}, {"id": "anking-dermatology-542", "fuente": "anking", "tema": 50, "anki": "1488502340989", "q": "What proteins compose tight junctions?", "o": {"A": "Claudins and occludins", "B": "Cadherins and catenins", "C": "Connexins and connexons", "D": "Integrins and laminins"}, "r": "A", "e": {"correcta": "Tight junctions are formed by transmembrane proteins claudins and occludins, which interlock to seal the intercellular space.", "incorrectas": {"B": "Cadherins and catenins form adherens junctions and desmosomes, not tight junctions.", "C": "Connexins/connexons form gap junction channels for intercellular communication.", "D": "Integrins bind basement membrane proteins in hemidesmosomes, not tight junctions."}}}, {"id": "anking-dermatology-543", "fuente": "anking", "tema": 50, "anki": "1488502345775", "q": "Which epithelial cell junction connects the actin cytoskeletons of adjacent cells?", "o": {"A": "Adherens junctions (zonula adherens)", "B": "Tight junctions", "C": "Desmosomes", "D": "Hemidesmosomes"}, "r": "A", "e": {"correcta": "Adherens junctions (zonula adherens) use cadherins to link the actin cytoskeletons of neighboring cells, forming a continuous adhesion belt just below tight junctions.", "incorrectas": {"B": "Tight junctions seal the paracellular space and do not link actin filaments between cells.", "C": "Desmosomes connect intermediate filaments (keratin), not actin.", "D": "Hemidesmosomes anchor cells to the basement membrane, not to each other, via integrins."}}}, {"id": "anking-dermatology-544", "fuente": "anking", "tema": 50, "anki": "1488502353724", "q": "Which epithelial cell junction connects the intermediate filaments of adjacent cells?", "o": {"A": "Desmosomes (macula adherens)", "B": "Adherens junctions", "C": "Tight junctions", "D": "Gap junctions"}, "r": "A", "e": {"correcta": "Desmosomes (macula adherens/spot desmosomes) use proteins like desmoglein, desmoplakin, and cytokeratin to connect intermediate filaments between adjacent cells, providing strong mechanical adhesion.", "incorrectas": {"B": "Adherens junctions link actin filaments, not intermediate filaments.", "C": "Tight junctions seal the paracellular space rather than linking cytoskeletal filaments.", "D": "Gap junctions form communication channels, not cytoskeletal linkages."}}}, {"id": "anking-dermatology-545", "fuente": "anking", "tema": 50, "anki": "1488502365775", "q": "What ion is required by cadherin proteins in epithelial cell junctions for their adhesive function?", "o": {"A": "Ca2+", "B": "Na+", "C": "K+", "D": "Mg2+"}, "r": "A", "e": {"correcta": "Cadherins are literally named for their \"Ca2+-dependent adhesion,\" requiring calcium ions to maintain their proper conformation for cell-cell binding.", "incorrectas": {"B": "Sodium ions are not required for cadherin-mediated adhesion.", "C": "Potassium ions are not involved in cadherin function.", "D": "Magnesium is not the ion associated with cadherin adhesion; that role belongs to calcium."}}}, {"id": "anking-dermatology-546", "fuente": "anking", "tema": 50, "anki": "1488502372834", "q": "Which epithelial cell junction permits electrical and chemical communication between adjacent cells?", "o": {"A": "Gap junctions", "B": "Tight junctions", "C": "Desmosomes", "D": "Hemidesmosomes"}, "r": "A", "e": {"correcta": "Gap junctions are composed of connexon channels that directly connect the cytoplasm of adjacent cells, allowing passage of ions and small molecules for electrical and chemical coupling.", "incorrectas": {"B": "Tight junctions block paracellular movement rather than allowing intercellular communication.", "C": "Desmosomes provide mechanical adhesion via intermediate filaments, not channels for communication.", "D": "Hemidesmosomes anchor cells to the basement membrane, not to each other."}}}, {"id": "anking-dermatology-547", "fuente": "anking", "tema": 50, "anki": "1488502376965", "q": "Gap junctions contain channel proteins called what, which allow communication between cells?", "o": {"A": "Connexons", "B": "Cadherins", "C": "Integrins", "D": "Claudins"}, "r": "A", "e": {"correcta": "Gap junctions are made of connexons (hexameric assemblies of connexin proteins) that form channels directly linking the cytoplasm of adjacent cells.", "incorrectas": {"B": "Cadherins mediate adhesion in adherens junctions and desmosomes, not intercellular channels.", "C": "Integrins anchor cells to the basement membrane in hemidesmosomes.", "D": "Claudins are components of tight junctions, which seal rather than connect cell cytoplasm."}}}, {"id": "anking-dermatology-548", "fuente": "anking", "tema": 50, "anki": "1488502381083", "q": "Which epithelial cell junction connects keratin in basal cells to the underlying basement membrane?", "o": {"A": "Hemidesmosomes", "B": "Desmosomes", "C": "Adherens junctions", "D": "Gap junctions"}, "r": "A", "e": {"correcta": "Hemidesmosomes anchor the intermediate (keratin) filaments of basal keratinocytes to the underlying basement membrane, providing structural stability.", "incorrectas": {"B": "Desmosomes connect intermediate filaments between adjacent cells, not cells to the basement membrane.", "C": "Adherens junctions connect actin filaments between neighboring cells, not to the basement membrane.", "D": "Gap junctions form communication channels between cells, unrelated to basement membrane attachment."}}}, {"id": "anking-dermatology-549", "fuente": "anking", "tema": 50, "anki": "1488502387243", "q": "What protein in hemidesmosomes binds to fibronectin, laminin, or collagen in the basement membrane (and is not calcium-dependent)?", "o": {"A": "Integrin", "B": "Cadherin", "C": "Connexin", "D": "Desmoglein"}, "r": "A", "e": {"correcta": "Integrins are transmembrane receptors in hemidesmosomes that bind basement membrane components (laminin, collagen, fibronectin) independent of calcium, unlike cadherins.", "incorrectas": {"B": "Cadherins mediate calcium-dependent adhesion in desmosomes and adherens junctions, not basement membrane binding.", "C": "Connexins form gap junction channels, unrelated to basement membrane attachment.", "D": "Desmoglein is a cadherin-family protein in desmosomes, calcium-dependent, connecting adjacent cells rather than binding the basement membrane."}}}, {"id": "anking-dermatology-550", "fuente": "anking", "tema": 50, "anki": "1488502394959", "q": "What dermatologic lesion is described as a flat, well-circumscribed color change in the skin measuring less than 1 cm?", "o": {"A": "Macule", "B": "Patch", "C": "Papule", "D": "Plaque"}, "r": "A", "e": {"correcta": "A macule is a flat, well-circumscribed lesion under 1 cm defined purely by a change in skin color, such as a freckle.", "incorrectas": {"B": "A patch is the same type of flat color-change lesion but larger than 1 cm.", "C": "A papule is elevated and solid, not flat.", "D": "A plaque is an elevated solid lesion larger than 1 cm, not a flat color change."}}}, {"id": "anking-dermatology-551", "fuente": "anking", "tema": 50, "anki": "1488502401419", "q": "What dermatologic lesion is a macule that is larger than 1 cm?", "o": {"A": "Patch", "B": "Macule", "C": "Papule", "D": "Nodule"}, "r": "A", "e": {"correcta": "A patch is defined as a flat, well-circumscribed area of color change greater than 1 cm, essentially a large macule, as seen in a congenital nevus (birthmark).", "incorrectas": {"B": "A macule is by definition smaller than 1 cm, so a larger lesion is no longer classified as a macule.", "C": "A papule is a raised, solid lesion, not a flat color change.", "D": "A nodule is a raised, solid, deeper lesion greater than 1 cm, not a flat macular lesion."}}}, {"id": "anking-dermatology-552", "fuente": "anking", "tema": 50, "anki": "1488502414992", "q": "What dermatologic lesion is an elevated, solid skin lesion measuring less than 1 cm?", "o": {"A": "Papule", "B": "Macule", "C": "Plaque", "D": "Nodule"}, "r": "A", "e": {"correcta": "A papule is a small (<1 cm), raised, solid lesion, exemplified by a mole (nevus) or acne lesion.", "incorrectas": {"B": "A macule is flat, not elevated, so it cannot be a raised solid lesion.", "C": "A plaque is the same type of raised solid lesion but larger than 1 cm.", "D": "A nodule is typically a larger and deeper solid lesion than a papule."}}}, {"id": "anking-dermatology-553", "fuente": "anking", "tema": 50, "anki": "1488502421602", "q": "What dermatologic lesion is a papule that is larger than 1 cm?", "o": {"A": "Plaque", "B": "Patch", "C": "Papule", "D": "Nodule"}, "r": "A", "e": {"correcta": "A plaque is an elevated, solid lesion greater than 1 cm, essentially a large papule, as seen in psoriasis.", "incorrectas": {"B": "A patch is a flat color-change lesion larger than 1 cm, not raised or solid.", "C": "A papule is by definition smaller than 1 cm, so a larger raised lesion is no longer termed a papule.", "D": "A nodule is typically a deeper, firmer lesion often extending into the dermis or subcutis, distinct from a superficial plaque."}}}, {"id": "anking-musculoskeletal-anatomy-physiology-554", "fuente": "anking", "tema": 51, "anki": "1479515855289", "q": "The ventral horn of the spinal cord contains two types of motor neurons: one that makes muscles contract and another that regulates muscle spindle sensitivity. What are these two types, respectively?", "o": {"A": "Alpha / gamma", "B": "Beta / delta", "C": "Ia / Ib", "D": "Upper / lower"}, "r": "A", "e": {"correcta": "Alpha motor neurons innervate extrafusal muscle fibers to produce contraction, while gamma motor neurons innervate intrafusal fibers of the muscle spindle to adjust its sensitivity to stretch.", "incorrectas": {"B": "Beta and delta are not the standard classification of somatic motor neurons in the ventral horn.", "C": "Ia and Ib refer to afferent (sensory) nerve fiber types from muscle spindles and Golgi tendon organs, not motor neurons.", "D": "Upper and lower motor neuron is a different classification based on location (cortex vs spinal cord), not function within the ventral horn."}}}, {"id": "anking-musculoskeletal-anatomy-physiology-555", "fuente": "anking", "tema": 51, "anki": "1479515860351", "q": "Which type of motor neuron directly makes skeletal muscle contract?", "o": {"A": "Alpha motor neurons", "B": "Gamma motor neurons", "C": "Preganglionic sympathetic neurons", "D": "Postganglionic parasympathetic neurons"}, "r": "A", "e": {"correcta": "Alpha motor neurons innervate extrafusal skeletal muscle fibers and are responsible for generating the force of contraction.", "incorrectas": {"B": "Gamma motor neurons innervate intrafusal fibers of the muscle spindle, adjusting sensitivity rather than causing contraction of the bulk of the muscle.", "C": "Preganglionic sympathetic neurons are part of the autonomic nervous system and do not innervate skeletal muscle.", "D": "Postganglionic parasympathetic neurons also belong to the autonomic nervous system, not somatic motor control of skeletal muscle."}}}, {"id": "anking-musculoskeletal-anatomy-physiology-556", "fuente": "anking", "tema": 51, "anki": "1479515868137", "q": "Which type of motor neuron increases the sensitivity of muscle spindles to stretch?", "o": {"A": "Gamma motor neurons", "B": "Alpha motor neurons", "C": "Ib afferent fibers", "D": "Renshaw cells"}, "r": "A", "e": {"correcta": "Gamma motor neurons innervate intrafusal muscle fibers, causing them to contract at their poles, which maintains tension in the spindle and keeps it sensitive to stretch even as the muscle shortens.", "incorrectas": {"B": "Alpha motor neurons innervate extrafusal fibers and cause overall muscle contraction, not spindle sensitivity adjustment.", "C": "Ib afferent fibers are sensory fibers from Golgi tendon organs, not motor neurons, and they signal tension rather than adjust spindle sensitivity.", "D": "Renshaw cells are inhibitory interneurons involved in recurrent inhibition, not spindle sensitivity regulation."}}}, {"id": "anking-musculoskeletal-anatomy-physiology-557", "fuente": "anking", "tema": 51, "anki": "1480386317587", "q": "How many neurons are required in the lateral corticospinal tract pathway for voluntary muscle movement?", "o": {"A": "Two (upper motor neuron and lower motor neuron)", "B": "One (a single continuous neuron)", "C": "Three (including an interneuron in the thalamus)", "D": "Four (including two interneurons in the spinal cord)"}, "r": "A", "e": {"correcta": "The lateral corticospinal tract pathway consists of an upper motor neuron originating in the primary motor cortex that synapses onto a lower motor neuron in the ventral horn, which then innervates the skeletal muscle.", "incorrectas": {"B": "A single continuous neuron does not span from cortex to muscle; a synapse must occur in the ventral horn.", "C": "There is no obligatory thalamic interneuron in this direct voluntary motor pathway.", "D": "Four neurons with two spinal interneurons is not the standard organization of this pathway."}}}, {"id": "anking-musculoskeletal-anatomy-physiology-558", "fuente": "anking", "tema": 51, "anki": "1480389629812", "q": "Where are the cell bodies of upper motor neurons primarily found?", "o": {"A": "Primary motor cortex (precentral gyrus)", "B": "Ventral horn of the spinal cord", "C": "Dorsal root ganglion", "D": "Cerebellar cortex"}, "r": "A", "e": {"correcta": "Upper motor neuron cell bodies are primarily located in the primary motor cortex (precentral gyrus), with additional contributions from the red nucleus, reticular formation, and lateral vestibular nuclei of the brainstem.", "incorrectas": {"B": "The ventral horn contains the cell bodies of lower motor neurons, not upper motor neurons.", "C": "The dorsal root ganglion contains cell bodies of sensory (afferent) neurons, not motor neurons.", "D": "The cerebellar cortex is involved in motor coordination but does not house the primary cell bodies of upper motor neurons."}}}, {"id": "anking-musculoskeletal-anatomy-physiology-559", "fuente": "anking", "tema": 51, "anki": "1480389638460", "q": "The axons of upper motor neurons destined for peripheral nerves travel in which tract?", "o": {"A": "Corticospinal tract", "B": "Corticobulbar tract", "C": "Spinothalamic tract", "D": "Dorsal column-medial lemniscus tract"}, "r": "A", "e": {"correcta": "Axons of upper motor neurons that synapse onto lower motor neurons supplying peripheral nerves (limb and trunk muscles) travel in the corticospinal tract.", "incorrectas": {"B": "The corticobulbar tract carries axons of upper motor neurons that innervate cranial nerve motor nuclei, not peripheral nerves.", "C": "The spinothalamic tract is an ascending sensory pathway carrying pain and temperature information, not a descending motor tract.", "D": "The dorsal column-medial lemniscus tract is an ascending sensory pathway for fine touch and proprioception, not a motor tract."}}}, {"id": "anking-musculoskeletal-anatomy-physiology-560", "fuente": "anking", "tema": 51, "anki": "1480389653921", "q": "Upper motor neurons synapse with the cell bodies of lower motor neurons in which part of the spinal cord?", "o": {"A": "Ventral (anterior) horn", "B": "Dorsal (posterior) horn", "C": "Lateral horn", "D": "Central canal region"}, "r": "A", "e": {"correcta": "The ventral (anterior) horn of the spinal cord contains the cell bodies of lower motor neurons, where upper motor neuron axons synapse to relay the motor command.", "incorrectas": {"B": "The dorsal horn processes incoming sensory information and does not contain lower motor neuron cell bodies.", "C": "The lateral horn contains preganglionic sympathetic neuron cell bodies, not lower motor neurons.", "D": "The region around the central canal is not where motor neuron synapses of this pathway occur."}}}, {"id": "anking-musculoskeletal-anatomy-physiology-561", "fuente": "anking", "tema": 51, "anki": "1480389657219", "q": "Lower motor neurons leave the spinal cord and synapse with skeletal muscle at which structure?", "o": {"A": "Neuromuscular junction", "B": "Golgi tendon organ", "C": "Muscle spindle capsule", "D": "Dorsal root ganglion"}, "r": "A", "e": {"correcta": "Lower motor neurons exit the spinal cord via the ventral root and synapse with skeletal muscle fibers at the neuromuscular junction, releasing acetylcholine to trigger contraction.", "incorrectas": {"B": "The Golgi tendon organ is a sensory receptor that detects muscle tension, not a site of motor neuron synapse.", "C": "The muscle spindle capsule houses intrafusal fibers and sensory endings for stretch detection, not the primary motor synapse for contraction.", "D": "The dorsal root ganglion contains sensory neuron cell bodies and is unrelated to the motor neuron-muscle synapse."}}}, {"id": "anking-musculoskeletal-anatomy-physiology-562", "fuente": "anking", "tema": 51, "anki": "1480389665227", "q": "Upper motor neurons initially descend in which position relative to the lower motor neurons they will eventually innervate (before decussation)?", "o": {"A": "Contralateral", "B": "Ipsilateral", "C": "Bilateral", "D": "Dorsal"}, "r": "A", "e": {"correcta": "Upper motor neuron axons in the corticospinal tract initially descend contralateral to the lower motor neurons they will innervate, then decussate at the pyramids (medulla) and continue ipsilaterally to their target.", "incorrectas": {"B": "The neurons are ipsilateral only after the pyramidal decussation, not during their initial descent.", "C": "The pathway is not bilateral; each corticospinal tract axon projects to one side after crossing.", "D": "Dorsal is not a laterality term relevant to this crossing pattern."}}}, {"id": "anking-musculoskeletal-anatomy-physiology-563", "fuente": "anking", "tema": 51, "anki": "1480389673051", "q": "Is the lateral corticospinal tract classified as an ascending or descending tract?", "o": {"A": "Descending", "B": "Ascending", "C": "Both ascending and descending", "D": "Neither; it is a commissural tract"}, "r": "A", "e": {"correcta": "The lateral corticospinal tract is a descending motor pathway that carries voluntary motor commands from the cortex down to lower motor neurons in the spinal cord.", "incorrectas": {"B": "Ascending tracts carry sensory information upward to the brain, which is not the function of the corticospinal tract.", "C": "The corticospinal tract functions strictly as a descending pathway, not both directions.", "D": "It is not a commissural tract, which would connect corresponding areas of the two cerebral hemispheres."}}}, {"id": "anking-musculoskeletal-anatomy-physiology-564", "fuente": "anking", "tema": 51, "anki": "1480389675385", "q": "The motor component of skeletal muscle reflexes (such as the muscle stretch reflex) is mediated by which type of motor neuron?", "o": {"A": "Lower motor neurons", "B": "Upper motor neurons", "C": "Postganglionic sympathetic neurons", "D": "Golgi tendon afferents"}, "r": "A", "e": {"correcta": "Reflex arcs are mediated at the spinal cord level by lower motor neurons, which receive sensory input directly (often monosynaptically) and generate the motor output without requiring cortical involvement.", "incorrectas": {"B": "Upper motor neurons provide descending modulation of reflexes but are not required for the basic reflex arc itself.", "C": "Postganglionic sympathetic neurons are part of the autonomic nervous system and are not involved in skeletal muscle stretch reflexes.", "D": "Golgi tendon afferents are sensory fibers, not motor neurons, and while involved in some reflexes they do not mediate the motor output."}}}, {"id": "anking-musculoskeletal-anatomy-physiology-565", "fuente": "anking", "tema": 51, "anki": "1480389677971", "q": "Which type of motor neuron provides descending control over spinal reflexes?", "o": {"A": "Upper motor neurons", "B": "Lower motor neurons", "C": "Gamma motor neurons only", "D": "Postganglionic sympathetic neurons"}, "r": "A", "e": {"correcta": "Upper motor neurons, originating in the cortex and brainstem, exert descending modulatory control over spinal reflex circuits, influencing their excitability.", "incorrectas": {"B": "Lower motor neurons execute the motor output of the reflex but do not provide descending control over it.", "C": "Gamma motor neurons regulate muscle spindle sensitivity but are not the primary source of descending reflex control described here.", "D": "Postganglionic sympathetic neurons are part of the autonomic nervous system and do not control somatic spinal reflexes."}}}, {"id": "anking-musculoskeletal-anatomy-physiology-566", "fuente": "anking", "tema": 51, "anki": "1480390831442", "q": "Alpha motor neurons innervate which type of muscle fiber?", "o": {"A": "Extrafusal muscle fibers", "B": "Intrafusal muscle fibers", "C": "Cardiac muscle fibers", "D": "Smooth muscle fibers"}, "r": "A", "e": {"correcta": "Alpha motor neurons innervate extrafusal muscle fibers, the main contractile fibers of skeletal muscle, generating tension that produces movement.", "incorrectas": {"B": "Intrafusal fibers are innervated by gamma motor neurons and form part of the muscle spindle sensory apparatus, not the main contractile mass.", "C": "Cardiac muscle is innervated by the autonomic nervous system, not by somatic alpha motor neurons.", "D": "Smooth muscle is likewise controlled by the autonomic nervous system, not by alpha motor neurons."}}}, {"id": "anking-musculoskeletal-anatomy-physiology-567", "fuente": "anking", "tema": 51, "anki": "1480391542068", "q": "Gamma motor neurons innervate which type of muscle fiber?", "o": {"A": "Intrafusal muscle fibers", "B": "Extrafusal muscle fibers", "C": "Golgi tendon organ fibers", "D": "Purkinje fibers"}, "r": "A", "e": {"correcta": "Gamma motor neurons innervate intrafusal muscle fibers within the muscle spindle, which detect the amount and rate of change in muscle length.", "incorrectas": {"B": "Extrafusal fibers, which generate the bulk contractile force of the muscle, are innervated by alpha motor neurons, not gamma.", "C": "The Golgi tendon organ is a sensory structure at the muscle-tendon junction and is not directly innervated by gamma motor neurons.", "D": "Purkinje fibers are specialized cardiac conduction fibers, unrelated to skeletal muscle innervation."}}}, {"id": "anking-musculoskeletal-anatomy-physiology-568", "fuente": "anking", "tema": 51, "anki": "1480391549216", "q": "In the muscle stretch reflex, stretch of the muscle increases afferent impulses conducted via which nerve fiber type?", "o": {"A": "Ia fibers", "B": "Ib fibers", "C": "II fibers only", "D": "C fibers"}, "r": "A", "e": {"correcta": "Muscle spindle stretch is sensed primarily by Ia afferent fibers, which rapidly conduct signals about muscle length and rate of stretch to the spinal cord.", "incorrectas": {"B": "Ib afferent fibers arise from Golgi tendon organs and signal muscle tension, not spindle stretch.", "C": "Group II fibers also arise from muscle spindles but signal static length rather than being the primary fiber type for the dynamic stretch reflex response described here.", "D": "C fibers are small, unmyelinated fibers that conduct slow pain and temperature sensations, not proprioceptive stretch signals."}}}, {"id": "anking-musculoskeletal-anatomy-physiology-569", "fuente": "anking", "tema": 51, "anki": "1480391558643", "q": "In the muscle stretch reflex, Ia afferent fibers directly stimulate which muscles, causing contraction?", "o": {"A": "Agonist muscles", "B": "Antagonist muscles", "C": "Synergist muscles only", "D": "Contralateral muscles"}, "r": "A", "e": {"correcta": "Ia afferent fibers form a monosynaptic connection with alpha motor neurons of the agonist muscle (e.g., the quadriceps in the knee-jerk reflex), causing it to contract in response to stretch.", "incorrectas": {"B": "Antagonist muscles are inhibited (via interneurons), not directly stimulated, by the Ia afferent input.", "C": "Synergist muscles are not the primary direct target described in this classic monosynaptic reflex arc.", "D": "The reflex is ipsilateral, not contralateral, so contralateral muscles are not directly stimulated."}}}, {"id": "anking-musculoskeletal-anatomy-physiology-570", "fuente": "anking", "tema": 51, "anki": "1480391566781", "q": "In the muscle stretch reflex, Ia afferent fibers inhibit which muscles through interneurons, causing relaxation?", "o": {"A": "Antagonist muscles", "B": "Agonist muscles", "C": "Ipsilateral flexors only", "D": "Muscles of the contralateral limb"}, "r": "A", "e": {"correcta": "Via inhibitory interneurons, Ia afferents cause reciprocal inhibition of the antagonist muscle (e.g., the hamstrings in the knee-jerk reflex), allowing the agonist to contract unopposed.", "incorrectas": {"B": "Agonist muscles are directly excited, not inhibited, by the Ia afferent pathway.", "C": "The inhibited muscle is specifically the antagonist to the stretched muscle, not simply defined as an ipsilateral flexor in general.", "D": "This reflex arc is confined to the ipsilateral limb; it does not inhibit muscles of the contralateral limb."}}}, {"id": "anking-musculoskeletal-anatomy-physiology-571", "fuente": "anking", "tema": 51, "anki": "1480391580026", "q": "In the inverse muscle stretch reflex (Golgi tendon reflex), increased muscle tension increases afferent impulses conducted via which nerve fiber type?", "o": {"A": "Ib fibers", "B": "Ia fibers", "C": "II fibers", "D": "A-delta fibers"}, "r": "A", "e": {"correcta": "The Golgi tendon organ, which senses muscle tension, sends afferent signals via Ib fibers; increased tension increases Ib firing, ultimately inhibiting the contracting muscle to protect against excessive force.", "incorrectas": {"B": "Ia fibers arise from muscle spindles and signal stretch/length, forming the afferent limb of the stretch reflex, not the tension-sensing inverse reflex.", "C": "Group II fibers also arise from muscle spindles and contribute to static length sensation, not tension sensing from tendons.", "D": "A-delta fibers conduct fast pain and temperature sensation, not proprioceptive tension signals."}}}, {"id": "anking-musculoskeletal-pharmacology-572", "fuente": "anking", "tema": 52, "anki": "1463675323435", "q": "Bisphosphonates have a chemical structure similar to which compound?", "o": {"A": "Pyrophosphate", "B": "Hydroxyapatite", "C": "Citrate", "D": "Phosphocreatine"}, "r": "A", "e": {"correcta": "Bisphosphonates are structural analogs of pyrophosphate, which allows them to bind avidly to bone mineral.", "incorrectas": {"B": "Hydroxyapatite is the bone mineral that bisphosphonates bind to, not the molecule they structurally resemble.", "C": "Citrate is not related to bisphosphonate structure.", "D": "Phosphocreatine is an energy storage molecule in muscle, unrelated to bisphosphonate structure."}}}, {"id": "anking-musculoskeletal-pharmacology-573", "fuente": "anking", "tema": 52, "anki": "1463675330277", "q": "Bisphosphonates bind to which component of bone, inhibiting osteoclast activity?", "o": {"A": "Collagen type I", "B": "Hydroxyapatite", "C": "Osteocalcin", "D": "Osteopontin"}, "r": "B", "e": {"correcta": "Bisphosphonates bind hydroxyapatite crystals in bone matrix, becoming incorporated and subsequently disrupting osteoclast function when released during resorption.", "incorrectas": {"A": "Collagen type I is the organic matrix protein of bone, not the binding target of bisphosphonates.", "C": "Osteocalcin is a matrix protein marker of osteoblast activity, not the bisphosphonate binding site.", "D": "Osteopontin is a bone matrix glycoprotein, not the site bisphosphonates bind."}}}, {"id": "anking-musculoskeletal-pharmacology-574", "fuente": "anking", "tema": 52, "anki": "1463675336561", "q": "When bound to bisphosphonate, which bone cells are unable to adhere to the bony surface, decreasing their activity?", "o": {"A": "Osteoblasts", "B": "Osteocytes", "C": "Osteoclasts", "D": "Chondrocytes"}, "r": "C", "e": {"correcta": "Bisphosphonate-coated bone surfaces impair osteoclast adhesion, reducing their bone-resorbing activity.", "incorrectas": {"A": "Osteoblasts form bone and are not directly impaired in adhesion by bisphosphonates.", "B": "Osteocytes are mature bone cells embedded in matrix, not the ones affected in adhesion.", "D": "Chondrocytes are cartilage cells, unrelated to bisphosphonate action on bone surfaces."}}}, {"id": "anking-musculoskeletal-pharmacology-575", "fuente": "anking", "tema": 52, "anki": "1463675342941", "q": "Bisphosphonates decrease the development and recruitment of precursors of which cell type?", "o": {"A": "Osteoblast", "B": "Osteoclast", "C": "Chondroblast", "D": "Fibroblast"}, "r": "B", "e": {"correcta": "Bisphosphonates reduce differentiation and recruitment of osteoclast precursors, limiting the pool of mature bone-resorbing cells.", "incorrectas": {"A": "Osteoblasts are bone-forming cells; bisphosphonates do not target their precursors.", "C": "Chondroblasts form cartilage, not the target of bisphosphonate action.", "D": "Fibroblasts are connective tissue cells unrelated to bisphosphonate mechanism."}}}, {"id": "anking-musculoskeletal-pharmacology-576", "fuente": "anking", "tema": 52, "anki": "1463675401764", "q": "In addition to decreasing osteoclast activity, bisphosphonates also induce which process in osteoclasts?", "o": {"A": "Apoptosis", "B": "Necrosis", "C": "Proliferation", "D": "Differentiation"}, "r": "A", "e": {"correcta": "Bisphosphonates promote osteoclast apoptosis, further reducing bone resorption beyond just inhibiting activity.", "incorrectas": {"B": "Necrosis is uncontrolled cell death, not the mechanism described for bisphosphonates.", "C": "Proliferation would increase osteoclast numbers, opposite to the drug's effect.", "D": "Differentiation into mature osteoclasts is decreased, not induced, by bisphosphonates."}}}, {"id": "anking-musculoskeletal-pharmacology-577", "fuente": "anking", "tema": 52, "anki": "1463675409153", "q": "Which two drugs are useful in the acute treatment of hypercalcemia of malignancy?", "o": {"A": "Bisphosphonates and calcitonin", "B": "Vitamin D and calcium gluconate", "C": "Thiazide diuretics and PTH", "D": "Loop diuretics alone and vitamin D"}, "r": "A", "e": {"correcta": "Bisphosphonates and calcitonin both lower serum calcium by inhibiting osteoclast-mediated bone resorption, making them useful in acute hypercalcemia of malignancy (often from PTHrP).", "incorrectas": {"B": "Vitamin D and calcium gluconate would raise, not lower, serum calcium.", "C": "Thiazides increase calcium reabsorption and worsen hypercalcemia; PTH raises calcium.", "D": "Loop diuretics do promote calciuresis but are typically paired with IV fluids/bisphosphonates, not vitamin D, which raises calcium."}}}, {"id": "anking-musculoskeletal-pharmacology-578", "fuente": "anking", "tema": 52, "anki": "1463675531294", "q": "As a result of decreased osteoclast activity, bisphosphonates may cause which electrolyte abnormality?", "o": {"A": "Hypercalcemia", "B": "Hypocalcemia", "C": "Hyperkalemia", "D": "Hypophosphatemia"}, "r": "B", "e": {"correcta": "By suppressing osteoclast-mediated bone resorption, bisphosphonates can lower serum calcium, causing hypocalcemia.", "incorrectas": {"A": "Hypercalcemia is the opposite effect; bisphosphonates are actually used to treat hypercalcemia.", "C": "Hyperkalemia is unrelated to bisphosphonate mechanism on bone.", "D": "Hypophosphatemia is not the primary described adverse effect of decreased osteoclast activity."}}}, {"id": "anking-musculoskeletal-pharmacology-579", "fuente": "anking", "tema": 52, "anki": "1463675577271", "q": "Chronic PTH exposure stimulates osteoblasts to express which ligand, which binds to which receptor on osteoclast surfaces to increase their activity?", "o": {"A": "RANKL / RANK", "B": "OPG / RANK", "C": "M-CSF / c-Fms", "D": "TNF-alpha / TNFR1"}, "r": "A", "e": {"correcta": "Chronic PTH exposure upregulates RANKL on osteoblasts, which binds RANK on osteoclast precursors/osteoclasts, promoting their differentiation and activity.", "incorrectas": {"B": "Osteoprotegerin (OPG) is a decoy receptor that inhibits RANKL, opposing bone resorption rather than promoting it.", "C": "M-CSF and c-Fms are involved in osteoclast precursor proliferation but are not the ligand-receptor pair described here for chronic PTH stimulation.", "D": "TNF-alpha/TNFR1 signaling is not the classic PTH-induced osteoclast activation pathway described in this context."}}}, {"id": "anking-musculoskeletal-pharmacology-580", "fuente": "anking", "tema": 52, "anki": "1463675593790", "q": "Which peptide hormone directly inhibits osteoclasts, causing decreased bone resorption?", "o": {"A": "Parathyroid hormone", "B": "Calcitonin", "C": "Vitamin D", "D": "Growth hormone"}, "r": "B", "e": {"correcta": "Calcitonin, secreted by thyroid parafollicular C cells, directly inhibits osteoclast activity, decreasing bone resorption (though it is less effective clinically than bisphosphonates).", "incorrectas": {"A": "Parathyroid hormone increases osteoclast activity (with chronic exposure) rather than inhibiting it.", "C": "Vitamin D promotes calcium absorption and, at high levels, can stimulate bone resorption rather than directly inhibiting osteoclasts.", "D": "Growth hormone affects bone growth via IGF-1 but does not directly inhibit osteoclasts."}}}, {"id": "anking-musculoskeletal-pharmacology-581", "fuente": "anking", "tema": 52, "anki": "1463675621016", "q": "Calcitonin promotes which renal handling of Ca2+?", "o": {"A": "Reabsorption", "B": "Excretion", "C": "Retention via aldosterone", "D": "No renal effect"}, "r": "B", "e": {"correcta": "Calcitonin promotes renal excretion of calcium, contributing to its calcium-lowering effect.", "incorrectas": {"A": "Reabsorption would raise serum calcium, the opposite of calcitonin's effect.", "C": "Aldosterone regulates sodium and potassium, not calcium, and is unrelated to calcitonin's mechanism.", "D": "Calcitonin does have a renal effect, promoting calciuresis."}}}, {"id": "anking-musculoskeletal-pharmacology-582", "fuente": "anking", "tema": 52, "anki": "1463675626990", "q": "What is a possible adverse metabolic effect of exogenous calcitonin administration?", "o": {"A": "Hyperkalemia", "B": "Hypocalcemia", "C": "Hypercalcemia", "D": "Hypernatremia"}, "r": "B", "e": {"correcta": "Exogenous calcitonin lowers serum calcium by inhibiting osteoclasts and promoting renal calcium excretion, which can lead to hypocalcemia.", "incorrectas": {"A": "Hyperkalemia is not a described effect of calcitonin.", "C": "Hypercalcemia is the opposite of calcitonin's calcium-lowering effect.", "D": "Hypernatremia is unrelated to calcitonin's mechanism of action."}}}, {"id": "anking-musculoskeletal-pharmacology-583", "fuente": "anking", "tema": 52, "anki": "1474580745605", "q": "Which leukotriene, along with 5-HETE, is a potent chemoattractant for inflammatory cells, particularly neutrophils?", "o": {"A": "Leukotriene B4", "B": "Leukotriene C4", "C": "Leukotriene D4", "D": "Leukotriene E4"}, "r": "A", "e": {"correcta": "Leukotriene B4 (LTB4), along with 5-HETE, is a potent chemoattractant that recruits neutrophils and other inflammatory cells to sites of inflammation.", "incorrectas": {"B": "Leukotriene C4 is primarily involved in bronchoconstriction and vascular permeability, not chemotaxis.", "C": "Leukotriene D4 is the most potent bronchoconstrictor, not a chemoattractant.", "D": "Leukotriene E4 contributes to bronchoconstriction and vascular permeability, not chemotaxis."}}}, {"id": "anking-musculoskeletal-pharmacology-584", "fuente": "anking", "tema": 52, "anki": "1474580751548", "q": "Which three leukotrienes increase airway vascular permeability, mucus production, and bronchoconstriction?", "o": {"A": "C4, D4, and E4", "B": "A4, B4, and C4", "C": "B4, D4, and E4", "D": "PGE2, PGF2-alpha, and TXA2"}, "r": "A", "e": {"correcta": "Leukotrienes C4, D4, and E4 (the cysteinyl leukotrienes) increase airway vascular permeability, mucus secretion, and bronchoconstriction, especially C4 and D4.", "incorrectas": {"B": "Leukotriene A4 is an unstable intermediate and B4 is a chemoattractant, not a bronchoconstrictor.", "C": "Leukotriene B4 is a chemoattractant, not one of the cysteinyl leukotrienes causing bronchoconstriction.", "D": "These are prostaglandins and thromboxane, not leukotrienes, and have different primary effects."}}}, {"id": "anking-musculoskeletal-pharmacology-585", "fuente": "anking", "tema": 52, "anki": "1474580768287", "q": "Which leukotriene is the most potent bronchoconstrictor?", "o": {"A": "Leukotriene B4", "B": "Leukotriene C4", "C": "Leukotriene D4", "D": "Leukotriene E4"}, "r": "C", "e": {"correcta": "Leukotriene D4 is the most potent bronchoconstrictor among the leukotrienes.", "incorrectas": {"A": "Leukotriene B4 is a chemoattractant for neutrophils, not primarily a bronchoconstrictor.", "B": "Leukotriene C4 causes bronchoconstriction but is less potent than D4.", "D": "Leukotriene E4 causes bronchoconstriction but is less potent than D4."}}}, {"id": "anking-musculoskeletal-pharmacology-586", "fuente": "anking", "tema": 52, "anki": "1474580773841", "q": "Leukotriene D4 exerts its bronchoconstrictive effects by binding to which receptor?", "o": {"A": "CysLT1", "B": "Thromboxane receptor (TP)", "C": "EP2 receptor", "D": "BLT1 receptor"}, "r": "A", "e": {"correcta": "Leukotriene D4 binds the CysLT1 receptor on airway smooth muscle, mediating bronchoconstriction; this receptor is the target of drugs like montelukast.", "incorrectas": {"B": "The thromboxane receptor (TP) mediates effects of thromboxane A2, not leukotriene D4.", "C": "The EP2 receptor is a prostaglandin E2 receptor, unrelated to leukotriene D4 signaling.", "D": "BLT1 is the receptor for leukotriene B4, not D4."}}}, {"id": "anking-musculoskeletal-pharmacology-587", "fuente": "anking", "tema": 52, "anki": "1483491954571", "q": "Which arachidonic acid pathway metabolite causes neutrophil chemotaxis?", "o": {"A": "LTB4", "B": "LTD4", "C": "PGE2", "D": "TXA2"}, "r": "A", "e": {"correcta": "LTB4 is a potent chemotactic agent for neutrophils, recruiting them to sites of inflammation.", "incorrectas": {"B": "LTD4 is the most potent bronchoconstrictor, not a chemoattractant.", "C": "PGE2 is involved in vasodilation, fever, and pain, not primarily neutrophil chemotaxis.", "D": "TXA2 promotes platelet aggregation and vasoconstriction, not neutrophil chemotaxis."}}}, {"id": "anking-musculoskeletal-pharmacology-588", "fuente": "anking", "tema": 52, "anki": "1483492000077", "q": "Leukotrienes are synthesized from arachidonic acid by which enzyme?", "o": {"A": "Cyclooxygenase (COX)", "B": "5-Lipoxygenase", "C": "Phospholipase A2", "D": "Prostacyclin synthase"}, "r": "B", "e": {"correcta": "5-Lipoxygenase converts arachidonic acid into leukotrienes, the alternative pathway to the cyclooxygenase pathway.", "incorrectas": {"A": "Cyclooxygenase converts arachidonic acid into prostaglandins and thromboxane, not leukotrienes.", "C": "Phospholipase A2 releases arachidonic acid from membrane phospholipids but does not produce leukotrienes directly.", "D": "Prostacyclin synthase converts prostaglandin intermediates into prostacyclin (PGI2), not leukotrienes."}}}, {"id": "anking-musculoskeletal-pharmacology-589", "fuente": "anking", "tema": 52, "anki": "1483492003622", "q": "PGI2, PGE1, PGE2, PGF2-alpha, and thromboxane A2 are synthesized from arachidonic acid by which enzyme(s)?", "o": {"A": "COX-1 and COX-2", "B": "5-Lipoxygenase", "C": "Phospholipase C", "D": "Lipoxin synthase"}, "r": "A", "e": {"correcta": "COX-1 and COX-2 (cyclooxygenases) convert arachidonic acid into prostaglandins (PGI2, PGE1, PGE2, PGF2-alpha) and thromboxane A2.", "incorrectas": {"B": "5-Lipoxygenase produces leukotrienes, not prostaglandins or thromboxane.", "C": "Phospholipase C is involved in phosphoinositide signaling, not arachidonic acid metabolism into prostaglandins.", "D": "Lipoxin synthase is not the enzyme responsible for producing these classic prostaglandins and thromboxane."}}}, {"id": "anking-respiratory-physiology-590", "fuente": "anking", "tema": 53, "anki": "1473289642149", "q": "Pulmonary blood flow is equal to which of the following?", "o": {"A": "Cardiac output of the right heart", "B": "Cardiac output of the left heart only", "C": "Total blood volume", "D": "Systemic vascular resistance"}, "r": "A", "e": {"correcta": "Pulmonary blood flow equals the cardiac output of the right heart, since all blood ejected by the right ventricle passes through the pulmonary circulation before reaching the left heart.", "incorrectas": {"B": "Left heart output equals right heart output at steady state, but pulmonary blood flow is specifically defined relative to the right heart, which pumps directly into the pulmonary circulation.", "C": "Total blood volume is a static measure of blood in the body, not a flow rate through the lungs.", "D": "Systemic vascular resistance relates to the systemic circulation, not pulmonary blood flow."}}}, {"id": "anking-respiratory-physiology-591", "fuente": "anking", "tema": 53, "anki": "1473289786175", "q": "In a standing person, pulmonary blood flow is lowest in which region of the lung?", "o": {"A": "Apex (top)", "B": "Base (bottom)", "C": "Middle (mid-lung zone)", "D": "It is uniform throughout the lung"}, "r": "A", "e": {"correcta": "Due to gravity, pulmonary blood flow is lowest at the apex of the lung in an upright person; this effect disappears when supine.", "incorrectas": {"B": "The base has the highest blood flow due to gravity, not the lowest.", "C": "The middle zone has intermediate flow, not the lowest.", "D": "Blood flow is not uniform in an upright person because of gravitational effects on perfusion."}}}, {"id": "anking-respiratory-physiology-592", "fuente": "anking", "tema": 53, "anki": "1473289801695", "q": "In a standing person, pulmonary blood flow is highest in which region of the lung?", "o": {"A": "Apex (top)", "B": "Base (bottom)", "C": "Middle (mid-lung zone)", "D": "It is uniform throughout the lung"}, "r": "B", "e": {"correcta": "Gravity causes the highest pulmonary blood flow at the base of the lung when standing; this gravitational gradient disappears in the supine position.", "incorrectas": {"A": "The apex has the lowest blood flow, not the highest, due to gravity in the upright position.", "C": "The middle zone has intermediate flow, not the highest.", "D": "Blood flow is not uniform because gravity creates a perfusion gradient from apex to base."}}}, {"id": "anking-respiratory-physiology-593", "fuente": "anking", "tema": 53, "anki": "1473289822632", "q": "What is the term for the volume of air that moves into the lung with each quiet (normal) inspiration?", "o": {"A": "Tidal volume", "B": "Inspiratory reserve volume", "C": "Vital capacity", "D": "Residual volume"}, "r": "A", "e": {"correcta": "Tidal volume is defined as the volume of air inspired or expired with each normal, quiet breath.", "incorrectas": {"B": "Inspiratory reserve volume is the additional air that can be inspired above tidal volume during forced inspiration.", "C": "Vital capacity is the sum of tidal volume, inspiratory reserve volume, and expiratory reserve volume.", "D": "Residual volume is the air remaining in the lungs after maximal forced expiration."}}}, {"id": "anking-respiratory-physiology-594", "fuente": "anking", "tema": 53, "anki": "1473293220506", "q": "What is the typical normal value for tidal volume?", "o": {"A": "500 mL", "B": "1200 mL", "C": "3000 mL", "D": "150 mL"}, "r": "A", "e": {"correcta": "The typical normal tidal volume during quiet breathing is approximately 500 mL.", "incorrectas": {"B": "1200 mL approximates the normal expiratory reserve volume and residual volume, not tidal volume.", "C": "3000 mL approximates the normal inspiratory reserve volume, not tidal volume.", "D": "150 mL approximates the normal anatomic dead space, not tidal volume."}}}, {"id": "anking-respiratory-physiology-595", "fuente": "anking", "tema": 53, "anki": "1473293242577", "q": "What is the term for the additional volume of air that can be inspired above tidal volume?", "o": {"A": "Inspiratory reserve volume", "B": "Expiratory reserve volume", "C": "Tidal volume", "D": "Functional residual capacity"}, "r": "A", "e": {"correcta": "Inspiratory reserve volume (normally about 3000 mL) is the extra air that can be forcibly inspired beyond a normal tidal breath.", "incorrectas": {"B": "Expiratory reserve volume refers to the extra air that can be expired below tidal volume, not inspired above it.", "C": "Tidal volume is the volume of a normal quiet breath, not the additional reserve above it.", "D": "Functional residual capacity is the volume remaining after normal expiration (ERV + RV), unrelated to inspiratory reserve."}}}, {"id": "anking-respiratory-physiology-596", "fuente": "anking", "tema": 53, "anki": "1473293251581", "q": "What is the term for the additional volume of air that can be expired below tidal volume?", "o": {"A": "Expiratory reserve volume", "B": "Inspiratory reserve volume", "C": "Residual volume", "D": "Vital capacity"}, "r": "A", "e": {"correcta": "Expiratory reserve volume (normally about 1200 mL) is the extra air that can be forcibly expired after a normal tidal expiration.", "incorrectas": {"B": "Inspiratory reserve volume is the additional air above tidal volume that can be inspired, not the air expired below it.", "C": "Residual volume is the air that remains in the lungs even after maximal forced expiration, distinct from ERV.", "D": "Vital capacity is the sum of tidal volume, IRV, and ERV, not the reserve volume itself."}}}, {"id": "anking-respiratory-physiology-597", "fuente": "anking", "tema": 53, "anki": "1473293260136", "q": "What is the term for the volume of air remaining in the lungs after maximal forced expiration?", "o": {"A": "Residual volume", "B": "Expiratory reserve volume", "C": "Functional residual capacity", "D": "Tidal volume"}, "r": "A", "e": {"correcta": "Residual volume (normally about 1200 mL) is the air left in the lungs after a maximal forced expiration; it cannot be measured by spirometry.", "incorrectas": {"B": "Expiratory reserve volume is the additional air that can be actively expired, not the volume left after maximal expiration.", "C": "Functional residual capacity includes residual volume plus expiratory reserve volume, but is not residual volume alone.", "D": "Tidal volume is the volume of a normal breath, unrelated to the air remaining after maximal expiration."}}}, {"id": "anking-respiratory-physiology-598", "fuente": "anking", "tema": 53, "anki": "1473293268513", "q": "Which lung volume cannot be measured directly by spirometry?", "o": {"A": "Residual volume", "B": "Tidal volume", "C": "Inspiratory reserve volume", "D": "Expiratory reserve volume"}, "r": "A", "e": {"correcta": "Residual volume cannot be measured by spirometry because it represents air that cannot be voluntarily expelled from the lungs; it requires methods like body plethysmography or gas dilution.", "incorrectas": {"B": "Tidal volume is directly measurable by spirometry as it involves normal breathing in and out.", "C": "Inspiratory reserve volume is measurable by spirometry since it is a volume that can be actively inspired.", "D": "Expiratory reserve volume is measurable by spirometry since it is a volume that can be actively expired."}}}, {"id": "anking-respiratory-physiology-599", "fuente": "anking", "tema": 53, "anki": "1473293272040", "q": "The sum of tidal volume plus inspiratory reserve volume is known as which of the following?", "o": {"A": "Inspiratory capacity", "B": "Vital capacity", "C": "Functional residual capacity", "D": "Total lung capacity"}, "r": "A", "e": {"correcta": "Inspiratory capacity is defined as tidal volume plus inspiratory reserve volume, representing the maximum air that can be inspired after a normal expiration.", "incorrectas": {"B": "Vital capacity includes tidal volume, IRV, and ERV, not just tidal volume plus IRV.", "C": "Functional residual capacity is the sum of expiratory reserve volume and residual volume, not tidal volume and IRV.", "D": "Total lung capacity is the sum of all four lung volumes, not just tidal volume and IRV."}}}, {"id": "anking-respiratory-physiology-600", "fuente": "anking", "tema": 53, "anki": "1473293278261", "q": "The sum of residual volume plus expiratory reserve volume is known as which of the following?", "o": {"A": "Functional residual capacity", "B": "Inspiratory capacity", "C": "Vital capacity", "D": "Total lung capacity"}, "r": "A", "e": {"correcta": "Functional residual capacity equals residual volume plus expiratory reserve volume, representing the volume of air in the lungs after a normal, passive expiration.", "incorrectas": {"B": "Inspiratory capacity is tidal volume plus inspiratory reserve volume, not related to residual volume.", "C": "Vital capacity is tidal volume plus IRV plus ERV, and excludes residual volume.", "D": "Total lung capacity includes all four volumes (TV, IRV, ERV, RV), not just RV and ERV."}}}, {"id": "anking-respiratory-physiology-601", "fuente": "anking", "tema": 53, "anki": "1473293285727", "q": "What is the term for the volume of gas remaining in the lungs after a normal (quiet) expiration?", "o": {"A": "Functional residual capacity", "B": "Residual volume", "C": "Vital capacity", "D": "Inspiratory capacity"}, "r": "A", "e": {"correcta": "Functional residual capacity (FRC) is the volume of air left in the lungs after a normal tidal expiration, and represents the equilibrium volume of the lungs (elastic recoil of lung balanced by chest wall).", "incorrectas": {"B": "Residual volume alone is the air left after maximal forced expiration, a smaller component of FRC.", "C": "Vital capacity is the maximum volume that can be exhaled after maximal inspiration, unrelated to the resting end-expiratory volume.", "D": "Inspiratory capacity is tidal volume plus IRV, representing maximal inspiration capability, not resting lung volume."}}}, {"id": "anking-respiratory-physiology-602", "fuente": "anking", "tema": 53, "anki": "1473293294683", "q": "The sum of tidal volume, inspiratory reserve volume, and expiratory reserve volume is known as which of the following?", "o": {"A": "Vital capacity", "B": "Total lung capacity", "C": "Functional residual capacity", "D": "Inspiratory capacity"}, "r": "A", "e": {"correcta": "Vital capacity is defined as the sum of tidal volume, inspiratory reserve volume, and expiratory reserve volume, representing the maximum volume that can be actively moved in and out of the lungs.", "incorrectas": {"B": "Total lung capacity also includes residual volume in addition to TV, IRV, and ERV.", "C": "Functional residual capacity is ERV plus residual volume, a different combination that excludes tidal volume and IRV.", "D": "Inspiratory capacity is only tidal volume plus IRV, excluding expiratory reserve volume."}}}, {"id": "anking-respiratory-physiology-603", "fuente": "anking", "tema": 53, "anki": "1473293303131", "q": "What is the term for the maximum volume of gas that can be expired after a maximal inspiration?", "o": {"A": "(Forced) vital capacity", "B": "Tidal volume", "C": "Functional residual capacity", "D": "Residual volume"}, "r": "A", "e": {"correcta": "(Forced) vital capacity is the maximum amount of air that can be forcibly exhaled after a maximal inspiration.", "incorrectas": {"B": "Tidal volume is the small amount of air moved during a normal quiet breath, far less than vital capacity.", "C": "Functional residual capacity is the resting lung volume after normal expiration, not related to maximal expiratory effort.", "D": "Residual volume is the air that remains in the lungs even after maximal expiration and cannot be exhaled."}}}, {"id": "anking-respiratory-physiology-604", "fuente": "anking", "tema": 53, "anki": "1473293310827", "q": "The sum of tidal volume, inspiratory reserve volume, expiratory reserve volume, and residual volume is known as which of the following?", "o": {"A": "Total lung capacity", "B": "Vital capacity", "C": "Functional residual capacity", "D": "Inspiratory capacity"}, "r": "A", "e": {"correcta": "Total lung capacity is the sum of all four lung volumes (TV, IRV, ERV, RV) and represents the total amount of air the lungs can hold after maximal inspiration.", "incorrectas": {"B": "Vital capacity excludes residual volume, so it is smaller than total lung capacity.", "C": "Functional residual capacity is only ERV plus RV, a subset of total lung capacity.", "D": "Inspiratory capacity is only TV plus IRV, a smaller subset of total lung capacity."}}}, {"id": "anking-respiratory-physiology-605", "fuente": "anking", "tema": 53, "anki": "1473293316303", "q": "What is the term for the volume of gas present in the lungs after a maximal inspiration?", "o": {"A": "Total lung capacity", "B": "Vital capacity", "C": "Inspiratory capacity", "D": "Functional residual capacity"}, "r": "A", "e": {"correcta": "Total lung capacity represents the volume of gas in the lungs at maximal inspiration, equal to the sum of all four lung volumes.", "incorrectas": {"B": "Vital capacity is the amount of air that can be exhaled after maximal inspiration, not the total volume present in the lungs at that point.", "C": "Inspiratory capacity is tidal volume plus IRV measured from the resting expiratory level, not the total volume at maximal inspiration.", "D": "Functional residual capacity is the lung volume after normal expiration, not after maximal inspiration."}}}, {"id": "anking-respiratory-physiology-606", "fuente": "anking", "tema": 53, "anki": "1473293322063", "q": "Which lung capacities cannot be measured directly by spirometry?", "o": {"A": "Functional residual capacity and total lung capacity", "B": "Vital capacity and inspiratory capacity", "C": "Tidal volume and inspiratory reserve volume", "D": "Expiratory reserve volume and vital capacity"}, "r": "A", "e": {"correcta": "Functional residual capacity and total lung capacity both include the residual volume, which cannot be exhaled and thus cannot be measured by spirometry; other methods like body plethysmography or gas dilution are required.", "incorrectas": {"B": "Vital capacity and inspiratory capacity do not include residual volume and can be measured directly by spirometry.", "C": "Tidal volume and inspiratory reserve volume are both measurable by spirometry since they involve air that can be actively moved.", "D": "Expiratory reserve volume and vital capacity are measurable by spirometry as they do not include the non-expirable residual volume."}}}, {"id": "anking-respiratory-physiology-607", "fuente": "anking", "tema": 53, "anki": "1473293337113", "q": "What is the typical normal value for anatomic dead space?", "o": {"A": "150 mL", "B": "500 mL", "C": "1200 mL", "D": "3000 mL"}, "r": "A", "e": {"correcta": "The typical normal anatomic dead space is approximately 150 mL, representing the volume of the conducting airways that does not participate in gas exchange.", "incorrectas": {"B": "500 mL is the typical normal tidal volume, not anatomic dead space.", "C": "1200 mL approximates normal expiratory reserve volume and residual volume, not dead space.", "D": "3000 mL approximates normal inspiratory reserve volume, not dead space."}}}, {"id": "anking-respiratory-anatomy-608", "fuente": "anking", "tema": 54, "anki": "1473286549070", "q": "The large airways containing the nose, pharynx, larynx, trachea, and bronchi belong to which functional zone of the lung?", "o": {"A": "Conducting zone", "B": "Respiratory zone", "C": "Transitional zone", "D": "Alveolar zone"}, "r": "A", "e": {"correcta": "The conducting zone comprises the large airways (nose, pharynx, larynx, trachea, bronchi) and serves to conduct air to the gas-exchanging portions of the lung; it does not participate in gas exchange itself.", "incorrectas": {"B": "The respiratory zone consists of respiratory bronchioles, alveolar ducts, and alveolar sacs, where gas exchange occurs, not the large airways listed.", "C": "\"Transitional zone\" is not a standard division of the respiratory tract.", "D": "\"Alveolar zone\" is not the standard term used; the gas-exchanging region is called the respiratory zone."}}}, {"id": "anking-respiratory-anatomy-609", "fuente": "anking", "tema": 54, "anki": "1473289435042", "q": "The small airways that consist of bronchioles further dividing into terminal bronchioles belong to which zone of the lung?", "o": {"A": "Conducting zone", "B": "Respiratory zone", "C": "Alveolar zone", "D": "Exchange zone"}, "r": "A", "e": {"correcta": "Bronchioles and terminal bronchioles are part of the conducting zone, which transports air but does not participate in gas exchange.", "incorrectas": {"B": "The respiratory zone begins at the respiratory bronchioles, distal to the terminal bronchioles, and is where gas exchange occurs.", "C": "\"Alveolar zone\" is not the standard anatomical term for this region.", "D": "\"Exchange zone\" is not the standard term; the correct term is the respiratory zone."}}}, {"id": "anking-respiratory-anatomy-610", "fuente": "anking", "tema": 54, "anki": "1473289442770", "q": "Which zone of the lung is responsible for warming, humidifying, and filtering inspired air?", "o": {"A": "Conducting zone", "B": "Respiratory zone", "C": "Cortical zone", "D": "Perfusion zone"}, "r": "A", "e": {"correcta": "The conducting zone (nose through terminal bronchioles) warms, humidifies, and filters air before it reaches the gas-exchange surfaces.", "incorrectas": {"B": "The respiratory zone is where gas exchange occurs; it does not primarily perform air conditioning functions.", "C": "\"Cortical zone\" is not a term used in respiratory anatomy.", "D": "\"Perfusion zone\" refers to blood flow distribution in the lung (West zones), not air conditioning."}}}, {"id": "anking-respiratory-anatomy-611", "fuente": "anking", "tema": 54, "anki": "1473289447013", "q": "Does the conducting zone of the lung participate in gas exchange?", "o": {"A": "No, it only conducts and conditions air", "B": "Yes, it is the primary site of gas exchange", "C": "Yes, but only during exercise", "D": "Yes, but only in the terminal bronchioles"}, "r": "A", "e": {"correcta": "The conducting zone has no alveoli and therefore does not participate in gas exchange; its role is to conduct, warm, humidify, and filter air.", "incorrectas": {"B": "Gas exchange occurs in the respiratory zone (respiratory bronchioles, alveolar ducts, and sacs), not the conducting zone.", "C": "Gas exchange does not occur in the conducting zone regardless of exercise state.", "D": "Terminal bronchioles are part of the conducting zone and lack alveoli, so no gas exchange occurs there."}}}, {"id": "anking-respiratory-anatomy-612", "fuente": "anking", "tema": 54, "anki": "1473289484281", "q": "Airway smooth muscle cells extend distally to which structure, becoming sparse beyond this point in the conducting zone?", "o": {"A": "Terminal bronchioles", "B": "Alveolar sacs", "C": "Trachea", "D": "Pharynx"}, "r": "A", "e": {"correcta": "Smooth muscle within the conducting zone extends down to the terminal bronchioles, becoming sparse beyond this level (though some persists in respiratory bronchioles).", "incorrectas": {"B": "Alveolar sacs are part of the respiratory zone and are the most distal structures, far past where conducting-zone smooth muscle is prominent.", "C": "The trachea is a proximal conducting airway with abundant smooth muscle, not the distal limit described.", "D": "The pharynx is a proximal upper airway structure, not related to the distal extent of airway smooth muscle."}}}, {"id": "anking-respiratory-anatomy-613", "fuente": "anking", "tema": 54, "anki": "1473289522726", "q": "What effect does sympathetic innervation have on the smooth muscle of the conducting airways?", "o": {"A": "Relaxation (bronchodilation)", "B": "Constriction (bronchoconstriction)", "C": "No effect", "D": "Increased mucus secretion only"}, "r": "A", "e": {"correcta": "Sympathetic stimulation (via beta-2 adrenergic receptors) causes relaxation of airway smooth muscle, leading to bronchodilation.", "incorrectas": {"B": "Bronchoconstriction is the effect of parasympathetic, not sympathetic, stimulation.", "C": "Sympathetic innervation does have a clear effect, causing bronchodilation.", "D": "Sympathetic stimulation does not primarily increase mucus secretion; its main airway effect is smooth muscle relaxation."}}}, {"id": "anking-respiratory-anatomy-614", "fuente": "anking", "tema": 54, "anki": "1473289526951", "q": "What effect does parasympathetic innervation have on the smooth muscle of the conducting airways?", "o": {"A": "Constriction (bronchoconstriction)", "B": "Relaxation (bronchodilation)", "C": "No effect", "D": "Decreased mucus secretion"}, "r": "A", "e": {"correcta": "Parasympathetic stimulation (via muscarinic receptors) causes contraction of airway smooth muscle, resulting in bronchoconstriction.", "incorrectas": {"B": "Bronchodilation is caused by sympathetic (beta-2 adrenergic), not parasympathetic, stimulation.", "C": "Parasympathetic innervation clearly produces bronchoconstriction, not a null effect.", "D": "Parasympathetic stimulation actually increases mucus secretion, not decreases it."}}}, {"id": "anking-respiratory-anatomy-615", "fuente": "anking", "tema": 54, "anki": "1473289531683", "q": "The respiratory bronchioles, alveolar ducts, and alveolar sacs together make up which zone of the lung?", "o": {"A": "Respiratory zone", "B": "Conducting zone", "C": "Transitional zone", "D": "Bronchial zone"}, "r": "A", "e": {"correcta": "The respiratory zone includes respiratory bronchioles, alveolar ducts, and alveolar sacs, and is the site of gas exchange.", "incorrectas": {"B": "The conducting zone consists of the nose through terminal bronchioles and does not include alveolar structures.", "C": "\"Transitional zone\" is not the standard term for this region.", "D": "\"Bronchial zone\" is not a standard anatomical division of the respiratory tract."}}}, {"id": "anking-respiratory-anatomy-616", "fuente": "anking", "tema": 54, "anki": "1473289537376", "q": "Does the respiratory zone of the lung participate in gas exchange?", "o": {"A": "Yes, it is the site of gas exchange", "B": "No, it only conducts air", "C": "No, it only humidifies air", "D": "Yes, but only during forced expiration"}, "r": "A", "e": {"correcta": "The respiratory zone contains alveoli and is where oxygen and carbon dioxide are exchanged between air and blood.", "incorrectas": {"B": "Conducting air without gas exchange describes the conducting zone, not the respiratory zone.", "C": "Humidification of air occurs primarily in the conducting zone, not the respiratory zone.", "D": "Gas exchange in the respiratory zone occurs continuously, not only during forced expiration."}}}, {"id": "anking-respiratory-anatomy-617", "fuente": "anking", "tema": 54, "anki": "1473289556073", "q": "Which part of the respiratory zone still contains some smooth muscle?", "o": {"A": "Respiratory bronchioles", "B": "Alveolar ducts", "C": "Alveolar sacs", "D": "Alveoli"}, "r": "A", "e": {"correcta": "Respiratory bronchioles, the most proximal part of the respiratory zone, retain some smooth muscle in their walls, unlike the more distal alveolar structures.", "incorrectas": {"B": "Alveolar ducts lack significant smooth muscle, having largely lost it distal to the respiratory bronchioles.", "C": "Alveolar sacs are composed of thin-walled alveoli without smooth muscle.", "D": "Alveoli are simple gas-exchange units without smooth muscle in their walls."}}}, {"id": "anking-respiratory-anatomy-618", "fuente": "anking", "tema": 54, "anki": "1473289582577", "q": "Where in the respiratory tract do cilia terminate?", "o": {"A": "Respiratory bronchioles", "B": "Alveolar ducts", "C": "Terminal bronchioles", "D": "Alveolar sacs"}, "r": "A", "e": {"correcta": "Ciliated epithelium extends through the conducting airways and terminates at the level of the respiratory bronchioles, where mucociliary clearance is no longer feasible.", "incorrectas": {"B": "Alveolar ducts are distal to the respiratory bronchioles and lack cilia, but this is not where cilia terminate—they end proximal to this point.", "C": "Terminal bronchioles are the last purely conducting airways, and cilia actually persist slightly further, ending in the respiratory bronchioles.", "D": "Alveolar sacs are the most distal structures and never have cilia; cilia end well before this level."}}}, {"id": "anking-respiratory-anatomy-619", "fuente": "anking", "tema": 54, "anki": "1473289590519", "q": "Do the alveolar ducts and alveolar sacs have cilia?", "o": {"A": "No, cilia terminate at the respiratory bronchioles", "B": "Yes, they are fully ciliated", "C": "Yes, but only the alveolar sacs are ciliated", "D": "Yes, but only the alveolar ducts are ciliated"}, "r": "A", "e": {"correcta": "Cilia terminate at the level of the respiratory bronchioles; the more distal alveolar ducts and sacs lack ciliated epithelium.", "incorrectas": {"B": "Alveolar ducts and sacs are lined by thin squamous epithelium (type I pneumocytes) without cilia.", "C": "Alveolar sacs, like alveolar ducts, lack cilia entirely.", "D": "Alveolar ducts, like alveolar sacs, lack cilia entirely."}}}, {"id": "anking-respiratory-anatomy-620", "fuente": "anking", "tema": 54, "anki": "1473300789890", "q": "Which muscle is the most important for inspiration?", "o": {"A": "Diaphragm", "B": "External intercostals", "C": "Sternocleidomastoid", "D": "Scalene muscles"}, "r": "A", "e": {"correcta": "The diaphragm is the primary muscle of inspiration, contracting to increase thoracic volume and generate negative intrathoracic pressure.", "incorrectas": {"B": "External intercostals assist inspiration by elevating the ribs but are secondary to the diaphragm.", "C": "The sternocleidomastoid is an accessory muscle of inspiration used during forced breathing, not the primary muscle.", "D": "The scalene muscles are accessory muscles that elevate the upper ribs during forced inspiration, not the main muscle of quiet inspiration."}}}, {"id": "anking-respiratory-anatomy-621", "fuente": "anking", "tema": 54, "anki": "1473303008746", "q": "When the diaphragm contracts during inspiration, in which direction are the abdominal contents pushed?", "o": {"A": "Downwards", "B": "Upwards", "C": "Laterally outward only", "D": "They remain unchanged"}, "r": "A", "e": {"correcta": "Diaphragmatic contraction flattens the dome of the diaphragm, pushing the abdominal contents downward while the ribs lift upward and outward, increasing thoracic volume.", "incorrectas": {"B": "Abdominal contents move downward, not upward, as the diaphragm flattens and descends.", "C": "The primary movement of abdominal contents is downward displacement, not purely lateral.", "D": "The abdominal contents are displaced downward due to diaphragmatic descent; they do not remain unchanged."}}}, {"id": "anking-respiratory-anatomy-622", "fuente": "anking", "tema": 54, "anki": "1473303024666", "q": "What muscles are normally used for expiration at rest?", "o": {"A": "None; resting expiration is passive", "B": "Internal intercostals and abdominal muscles", "C": "The diaphragm", "D": "Sternocleidomastoid and scalene muscles"}, "r": "A", "e": {"correcta": "At rest, expiration is a passive process driven by elastic recoil of the lungs and chest wall, requiring no active muscle contraction.", "incorrectas": {"B": "Internal intercostals and abdominal muscles are recruited for active/forced expiration, not normal resting expiration.", "C": "The diaphragm is the primary muscle of inspiration, not expiration.", "D": "Sternocleidomastoid and scalenes are accessory muscles of forced inspiration, not involved in resting expiration."}}}, {"id": "anking-respiratory-anatomy-623", "fuente": "anking", "tema": 54, "anki": "1473462191670", "q": "Which respiratory center, located in the reticular formation and containing inspiratory and expiratory centers, coordinates the basic rhythm of breathing?", "o": {"A": "Medullary respiratory center", "B": "Pontine respiratory center", "C": "Cortical respiratory center", "D": "Hypothalamic respiratory center"}, "r": "A", "e": {"correcta": "The medullary respiratory center, located in the reticular formation of the medulla, contains dorsal (inspiratory) and ventral (expiratory) respiratory groups that generate the basic rhythm of breathing.", "incorrectas": {"B": "The pontine respiratory center (pneumotaxic and apneustic centers) modulates the rhythm set by the medulla but is not itself the primary generator described.", "C": "There is no \"cortical respiratory center\"; the cortex allows voluntary control of breathing but is not the automatic rhythm generator.", "D": "The hypothalamus is not involved in generating the basic respiratory rhythm."}}}, {"id": "anking-respiratory-anatomy-624", "fuente": "anking", "tema": 54, "anki": "1473462194805", "q": "The dorsal and ventral respiratory groups are located in which part of the brainstem?", "o": {"A": "Medulla", "B": "Pons", "C": "Midbrain", "D": "Cerebellum"}, "r": "A", "e": {"correcta": "The dorsal and ventral respiratory groups, which generate the basic breathing rhythm, are located in the medulla oblongata.", "incorrectas": {"B": "The pons contains the pneumotaxic and apneustic centers, which modulate rhythm, but not the dorsal/ventral respiratory groups.", "C": "The midbrain is not a site of primary respiratory rhythm generation.", "D": "The cerebellum coordinates motor movements and balance, not respiratory rhythm generation."}}}, {"id": "anking-respiratory-anatomy-625", "fuente": "anking", "tema": 54, "anki": "1473462201615", "q": "The dorsal respiratory group receives sensory input from peripheral chemoreceptors via which two cranial nerves?", "o": {"A": "Glossopharyngeal (CN IX) and vagus (CN X)", "B": "Trigeminal (CN V) and facial (CN VII)", "C": "Vagus (CN X) and hypoglossal (CN XII)", "D": "Glossopharyngeal (CN IX) and accessory (CN XI)"}, "r": "A", "e": {"correcta": "Peripheral chemoreceptors in the carotid bodies signal via the glossopharyngeal nerve (CN IX), and those in the aortic bodies signal via the vagus nerve (CN X), both projecting to the dorsal respiratory group.", "incorrectas": {"B": "The trigeminal and facial nerves are involved in facial sensation/motor function and taste, not chemoreceptor input to the dorsal respiratory group.", "C": "The hypoglossal nerve controls tongue movement and is not involved in chemoreceptor signaling to the respiratory center.", "D": "The accessory nerve controls the sternocleidomastoid and trapezius muscles and is not involved in chemoreceptor signaling."}}}, {"id": "anking-respiratory-embryology-626", "fuente": "anking", "tema": 55, "anki": "1463944368984", "q": "Which lecithin:sphingomyelin (L/S) ratio, measured by amniocentesis, indicates a mature fetal lung?", "o": {"A": "L/S > 2", "B": "L/S < 1", "C": "L/S = 1", "D": "L/S between 1 and 1.5"}, "r": "A", "e": {"correcta": "An L/S ratio greater than 2 indicates sufficient surfactant production and pulmonary maturity, and this ratio can be measured via amniocentesis in the third trimester.", "incorrectas": {"B": "An L/S ratio below 1 (or below 1.5) suggests immature lungs and high risk of neonatal respiratory distress syndrome, not maturity.", "C": "A ratio of 1 reflects roughly equal amounts of lecithin and sphingomyelin, which is not indicative of lung maturity.", "D": "A ratio in the 1 to 1.5 range is considered borderline/uncertain surfactant status, not mature."}}}, {"id": "anking-respiratory-embryology-627", "fuente": "anking", "tema": 55, "anki": "1463944717248", "q": "Which two phospholipids are the most abundant components of pulmonary surfactant?", "o": {"A": "Lecithin (phosphatidylcholine) and sphingomyelin", "B": "Cholesterol and phosphatidylserine", "C": "Phosphatidylethanolamine and phosphatidylinositol", "D": "Sphingosine and ceramide"}, "r": "A", "e": {"correcta": "Surfactant is composed largely of lecithin (phosphatidylcholine) and sphingomyelin; the ratio of lecithin to sphingomyelin greater than 2 indicates a mature fetal lung.", "incorrectas": {"B": "Cholesterol and phosphatidylserine are not the principal phospholipids used to assess surfactant maturity.", "C": "Phosphatidylethanolamine and phosphatidylinositol are minor membrane phospholipids, not the key surfactant components measured clinically.", "D": "Sphingosine and ceramide are sphingolipid metabolites, not the primary surfactant phospholipids."}}}, {"id": "anking-respiratory-embryology-628", "fuente": "anking", "tema": 55, "anki": "1473289602247", "q": "The alveolar walls are lined by which two types of epithelial cells?", "o": {"A": "Type I and type II pneumocytes", "B": "Goblet cells and ciliated columnar cells", "C": "Club (Clara) cells and basal cells", "D": "Alveolar macrophages and mast cells"}, "r": "A", "e": {"correcta": "The alveolar epithelium is composed of type I pneumocytes (thin cells for gas exchange) and type II pneumocytes (surfactant-producing, regenerative cells).", "incorrectas": {"B": "Goblet cells and ciliated columnar cells line the conducting airways (bronchi/bronchioles), not the alveoli.", "C": "Club cells are found in the terminal bronchioles, and basal cells are progenitor cells of the airway epithelium, not the alveolar lining.", "D": "Alveolar macrophages are immune cells within the alveolar space, and mast cells are immune cells in connective tissue; neither lines the alveolar wall as epithelium."}}}, {"id": "anking-respiratory-embryology-629", "fuente": "anking", "tema": 55, "anki": "1473289619233", "q": "Which type of pneumocyte has the capacity to regenerate into both type I and type II pneumocytes?", "o": {"A": "Type II pneumocytes", "B": "Type I pneumocytes", "C": "Club cells", "D": "Alveolar macrophages"}, "r": "A", "e": {"correcta": "Type II pneumocytes serve as the progenitor cells of the alveolar epithelium, capable of proliferating and differentiating into both type I and type II pneumocytes after lung injury.", "incorrectas": {"B": "Type I pneumocytes are terminally differentiated, thin squamous cells specialized for gas exchange and lack regenerative capacity.", "C": "Club cells are progenitor cells of the bronchiolar epithelium, not the alveolar epithelium.", "D": "Alveolar macrophages are phagocytic immune cells, not epithelial progenitor cells."}}}, {"id": "anking-respiratory-embryology-630", "fuente": "anking", "tema": 55, "anki": "1473359937703", "q": "What substance, a mixture of phospholipids lining the alveoli, functions to reduce alveolar surface tension?", "o": {"A": "Surfactant", "B": "Mucus", "C": "Elastin", "D": "Collagen"}, "r": "A", "e": {"correcta": "Surfactant, produced by type II pneumocytes, is a phospholipid mixture (mainly lecithin) that reduces alveolar surface tension and prevents alveolar collapse.", "incorrectas": {"B": "Mucus is secreted by goblet cells in the airways to trap particles, not to reduce alveolar surface tension.", "C": "Elastin provides elastic recoil to lung tissue but does not reduce surface tension at the air-liquid interface.", "D": "Collagen provides structural support to the lung parenchyma but plays no role in reducing surface tension."}}}, {"id": "anking-respiratory-embryology-631", "fuente": "anking", "tema": 55, "anki": "1473359944505", "q": "Surfactant reduces alveolar surface tension by disrupting the intermolecular forces between molecules of what substance?", "o": {"A": "Liquid (water) lining the alveoli", "B": "Oxygen gas", "C": "Carbon dioxide gas", "D": "Surfactant itself"}, "r": "A", "e": {"correcta": "Surfactant interposes itself between water molecules lining the alveolar surface, disrupting the hydrogen bonding (intermolecular forces) that create surface tension, thereby easing alveolar expansion.", "incorrectas": {"B": "Oxygen gas does not form the intermolecular forces responsible for surface tension in the alveoli.", "C": "Carbon dioxide gas is not involved in the surface tension created by the liquid lining of the alveoli.", "D": "Surfactant acts upon the water molecules, not upon itself, to reduce surface tension."}}}, {"id": "anking-respiratory-embryology-632", "fuente": "anking", "tema": 55, "anki": "1473359947453", "q": "What is the term for the collapse of small alveoli that occurs in the absence of adequate surfactant?", "o": {"A": "Atelectasis", "B": "Pneumothorax", "C": "Emphysema", "D": "Bronchiectasis"}, "r": "A", "e": {"correcta": "Without surfactant to reduce surface tension, smaller alveoli (which have higher collapsing pressure by LaPlace's law) are prone to collapse, a condition termed atelectasis.", "incorrectas": {"B": "Pneumothorax refers to air in the pleural space causing lung collapse, not alveolar collapse due to surface tension.", "C": "Emphysema is destruction of alveolar walls with airspace enlargement, the opposite of alveolar collapse.", "D": "Bronchiectasis is irreversible dilation of the bronchi, unrelated to surfactant deficiency or alveolar collapse."}}}, {"id": "anking-respiratory-embryology-633", "fuente": "anking", "tema": 55, "anki": "1473359951494", "q": "Which lecithin is the most important component of pulmonary surfactant?", "o": {"A": "Dipalmitoyl phosphatidylcholine (DPPC)", "B": "Sphingomyelin", "C": "Phosphatidylserine", "D": "Phosphatidylinositol"}, "r": "A", "e": {"correcta": "Dipalmitoyl phosphatidylcholine (DPPC) is the principal and most functionally important lecithin in pulmonary surfactant, responsible for reducing alveolar surface tension.", "incorrectas": {"B": "Sphingomyelin is used as a reference lipid in the L/S ratio but is not the primary functional surfactant lecithin.", "C": "Phosphatidylserine is a minor membrane phospholipid, not a principal component of surfactant.", "D": "Phosphatidylinositol is a minor membrane phospholipid and signaling molecule, not the main surfactant lecithin."}}}, {"id": "anking-respiratory-embryology-634", "fuente": "anking", "tema": 55, "anki": "1473359954555", "q": "In fetal development, surfactant synthesis begins as early as which gestational week?", "o": {"A": "Week 20", "B": "Week 8", "C": "Week 28", "D": "Week 35"}, "r": "A", "e": {"correcta": "Surfactant synthesis begins as early as week 20 of gestation, coinciding with pneumocyte development during the canalicular period, though the surfactant is not yet functional at this stage.", "incorrectas": {"B": "Week 8 falls within the embryonic/pseudoglandular period, well before surfactant-producing pneumocytes develop.", "C": "Week 28 is later than the actual onset of surfactant synthesis, which begins at week 20.", "D": "Week 35 is when mature, functional levels of surfactant are achieved, not when synthesis first begins."}}}, {"id": "anking-respiratory-embryology-635", "fuente": "anking", "tema": 55, "anki": "1473359957928", "q": "Mature levels of pulmonary surfactant are typically not achieved until around which gestational week?", "o": {"A": "Week 35", "B": "Week 20", "C": "Week 24", "D": "Week 40"}, "r": "A", "e": {"correcta": "Although surfactant synthesis begins around week 20, mature and functionally adequate surfactant levels are not reached until approximately week 35 of gestation.", "incorrectas": {"B": "Week 20 marks the onset of surfactant synthesis, not the achievement of mature levels.", "C": "Week 24 is an early point at which surfactant production has begun but levels remain insufficient and uncertain.", "D": "Week 40 is full term; mature surfactant levels are achieved earlier, around week 35, not specifically at term."}}}, {"id": "anking-respiratory-embryology-636", "fuente": "anking", "tema": 55, "anki": "1473707435818", "q": "Neonatal respiratory distress syndrome (NRDS) is most strongly associated with which type of birth?", "o": {"A": "Premature birth", "B": "Post-term birth", "C": "Cesarean birth at term", "D": "Twin birth at term"}, "r": "A", "e": {"correcta": "NRDS is associated with premature birth because surfactant production doesn't begin until at least week 20-24 and adequate levels aren't reached until around week 35, leaving preterm infants surfactant-deficient.", "incorrectas": {"B": "Post-term birth occurs after 42 weeks, well past the point of surfactant maturity, so NRDS risk is not increased.", "C": "Cesarean delivery at term is not inherently linked to surfactant deficiency, as term infants have mature surfactant levels.", "D": "Twin birth at term does not by itself cause surfactant deficiency; prematurity is the key risk factor for NRDS."}}}, {"id": "anking-respiratory-embryology-637", "fuente": "anking", "tema": 55, "anki": "1473707500365", "q": "What lecithin:sphingomyelin (L/S) ratio is considered indicative of adequate surfactant production?", "o": {"A": "Greater than 2", "B": "Less than 1", "C": "Equal to 1", "D": "Less than 1.5"}, "r": "A", "e": {"correcta": "An L/S ratio greater than 2 reflects adequate surfactant production and fetal lung maturity.", "incorrectas": {"B": "An L/S ratio less than 1 reflects severe surfactant deficiency, not adequacy.", "C": "A ratio of 1 indicates roughly equal lecithin and sphingomyelin, insufficient to indicate mature surfactant production.", "D": "An L/S ratio less than 1.5 is predictive of neonatal respiratory distress syndrome, not adequate surfactant."}}}, {"id": "anking-respiratory-embryology-638", "fuente": "anking", "tema": 55, "anki": "1473707511363", "q": "What lecithin:sphingomyelin (L/S) ratio is predictive of neonatal respiratory distress syndrome (NRDS)?", "o": {"A": "Less than 1.5", "B": "Greater than 2", "C": "Greater than 3", "D": "Equal to 2"}, "r": "A", "e": {"correcta": "An L/S ratio less than 1.5 indicates insufficient surfactant production and is predictive of the development of NRDS in the newborn.", "incorrectas": {"B": "An L/S ratio greater than 2 indicates mature, adequate surfactant levels and low risk of NRDS.", "C": "A ratio greater than 3 would indicate even more mature surfactant status, not a risk for NRDS.", "D": "A ratio of exactly 2 is near the threshold of maturity and not the value predictive of NRDS."}}}, {"id": "anking-respiratory-embryology-639", "fuente": "anking", "tema": 55, "anki": "1473707553199", "q": "In neonatal respiratory distress syndrome, how does respiratory effort change after birth?", "o": {"A": "It increases", "B": "It decreases", "C": "It remains unchanged", "D": "It ceases entirely"}, "r": "A", "e": {"correcta": "In NRDS, respiratory effort increases because the infant must expend more energy to open collapsed alveoli (atelectasis) due to insufficient surfactant.", "incorrectas": {"B": "Respiratory effort does not decrease in NRDS; the collapsed alveoli require more, not less, effort to inflate.", "C": "Respiratory effort is markedly increased, not unchanged, as the infant compensates for poor lung compliance.", "D": "Respiratory effort does not cease; affected infants show increased work of breathing, potentially progressing to respiratory failure if untreated."}}}, {"id": "anking-respiratory-embryology-640", "fuente": "anking", "tema": 55, "anki": "1473707561353", "q": "Neonatal respiratory distress syndrome may present with which abnormal respiratory rate finding, along with use of accessory muscles and grunting?", "o": {"A": "Tachypnea", "B": "Bradypnea", "C": "Apnea", "D": "Normal respiratory rate"}, "r": "A", "e": {"correcta": "NRDS presents with tachypnea (increased respiratory rate) along with accessory muscle use and grunting; grunting helps generate positive end-expiratory pressure (PEEP) to keep alveoli open.", "incorrectas": {"B": "Bradypnea (decreased respiratory rate) is not characteristic of NRDS, which instead shows increased respiratory rate as a compensatory response.", "C": "Apnea (absence of breathing) is a possible late/severe complication but is not the typical presenting rate finding described here.", "D": "A normal respiratory rate would not be expected given the increased work of breathing and hypoxemia present in NRDS."}}}, {"id": "anking-respiratory-embryology-641", "fuente": "anking", "tema": 55, "anki": "1473707568629", "q": "Neonatal respiratory distress syndrome classically shows diffuse granularity of the lungs with what descriptive appearance on chest X-ray?", "o": {"A": "Ground-glass appearance", "B": "Honeycomb appearance", "C": "Water-bottle appearance", "D": "Cannonball appearance"}, "r": "A", "e": {"correcta": "NRDS classically presents on chest X-ray with a diffuse, finely granular \"ground-glass\" appearance due to widespread alveolar atelectasis.", "incorrectas": {"B": "A honeycomb appearance is characteristic of pulmonary fibrosis (e.g., usual interstitial pneumonia), not NRDS.", "C": "A water-bottle appearance on chest X-ray is classic for pericardial effusion, not NRDS.", "D": "A cannonball appearance describes multiple round metastatic lesions in the lungs, not NRDS."}}}, {"id": "anking-respiratory-embryology-642", "fuente": "anking", "tema": 55, "anki": "1473707579754", "q": "Which gastrointestinal pathology is associated with neonatal respiratory distress syndrome due to hypoxemia?", "o": {"A": "Necrotizing enterocolitis", "B": "Hirschsprung disease", "C": "Pyloric stenosis", "D": "Intussusception"}, "r": "A", "e": {"correcta": "Hypoxemia from NRDS can compromise intestinal perfusion, predisposing preterm infants to necrotizing enterocolitis, an ischemic and inflammatory bowel injury.", "incorrectas": {"B": "Hirschsprung disease is a congenital absence of ganglion cells causing bowel obstruction, unrelated to hypoxemia from NRDS.", "C": "Pyloric stenosis is caused by hypertrophy of the pyloric muscle, unrelated to hypoxemic injury from NRDS.", "D": "Intussusception is a mechanical telescoping of bowel segments, not a hypoxemia-related complication of NRDS."}}}, {"id": "anking-respiratory-embryology-643", "fuente": "anking", "tema": 55, "anki": "1473707603639", "q": "What treatment may be administered to the mother before birth to help prevent neonatal respiratory distress syndrome?", "o": {"A": "Maternal corticosteroids", "B": "Maternal antibiotics", "C": "Maternal insulin", "D": "Maternal anticoagulants"}, "r": "A", "e": {"correcta": "Antenatal maternal corticosteroids accelerate fetal lung maturation and surfactant production, reducing the risk of neonatal respiratory distress syndrome in preterm infants.", "incorrectas": {"B": "Maternal antibiotics are used to treat/prevent infection (e.g., in preterm labor with ruptured membranes) but do not promote fetal lung maturation.", "C": "Maternal insulin is used to manage maternal diabetes and does not accelerate fetal surfactant production.", "D": "Maternal anticoagulants are used for thromboembolic conditions and have no role in promoting fetal lung maturity."}}}, {"id": "anking-cellular-injury-644", "fuente": "anking", "tema": 56, "anki": "1475364142714", "q": "Systemic amyloidosis is a recognized cause of which renal disease presentation?", "o": {"A": "Nephrotic syndrome", "B": "Acute interstitial nephritis", "C": "Renal artery stenosis", "D": "Diabetes insipidus"}, "r": "A", "e": {"correcta": "Amyloid deposition in the glomerular basement membrane disrupts the filtration barrier, leading to massive proteinuria and nephrotic syndrome.", "incorrectas": {"B": "Interstitial nephritis is typically caused by drug hypersensitivity or infection, not amyloid deposition.", "C": "Renal artery stenosis is a vascular/atherosclerotic or fibromuscular dysplasia process, unrelated to amyloid.", "D": "Diabetes insipidus results from ADH deficiency or renal resistance to ADH, not glomerular amyloid deposition."}}}, {"id": "anking-cellular-injury-645", "fuente": "anking", "tema": 56, "anki": "1475364147786", "q": "In systemic amyloidosis, which organ is most commonly involved?", "o": {"A": "Kidney", "B": "Liver", "C": "Spleen", "D": "Heart"}, "r": "A", "e": {"correcta": "The kidney is the most frequently involved organ in systemic amyloidosis, with amyloid depositing in the glomeruli and causing nephrotic syndrome.", "incorrectas": {"B": "The liver can be involved in systemic amyloidosis but is not the most commonly affected organ.", "C": "The spleen may show amyloid deposition (e.g., sago spleen) but is less commonly involved than the kidney.", "D": "Cardiac amyloidosis occurs and can cause restrictive cardiomyopathy, but the kidney is affected more frequently overall."}}}, {"id": "anking-cellular-injury-646", "fuente": "anking", "tema": 56, "anki": "1481335888586", "q": "Deposition of free immunoglobulin light chains in tissue, as seen in multiple myeloma, produces which type of amyloidosis?", "o": {"A": "Primary (AL) amyloidosis", "B": "Secondary (AA) amyloidosis", "C": "Dialysis-related (Abeta2-microglobulin) amyloidosis", "D": "Senile systemic (transthyretin) amyloidosis"}, "r": "A", "e": {"correcta": "In multiple myeloma, plasma cells overproduce free light chains that circulate and deposit in tissues as amyloid light chain (AL), termed primary amyloidosis.", "incorrectas": {"B": "AA amyloidosis results from deposition of serum amyloid A protein during chronic inflammatory states, not light chains.", "C": "Dialysis-related amyloidosis is caused by accumulation of beta2-microglobulin in patients on long-term hemodialysis.", "D": "Senile systemic amyloidosis is caused by deposition of normal (wild-type) transthyretin, unrelated to plasma cell dyscrasias."}}}, {"id": "anking-cellular-injury-647", "fuente": "anking", "tema": 56, "anki": "1481857742032", "q": "Deposition of amyloid-beta around cerebral vessels in Alzheimer's disease causes which condition?", "o": {"A": "Amyloid (cerebral) angiopathy", "B": "Vasculitis", "C": "Atherosclerosis", "D": "Moyamoya disease"}, "r": "A", "e": {"correcta": "Amyloid-beta deposits in the walls of cerebral blood vessels in Alzheimer's disease, producing cerebral amyloid angiopathy, which weakens vessel walls.", "incorrectas": {"B": "Vasculitis is inflammation of vessel walls due to immune-mediated mechanisms, not amyloid deposition.", "C": "Atherosclerosis involves lipid-laden plaque formation in arterial intima, a distinct process from amyloid deposition.", "D": "Moyamoya disease is a progressive occlusive vasculopathy of the intracranial internal carotid arteries, unrelated to amyloid."}}}, {"id": "anking-cellular-injury-648", "fuente": "anking", "tema": 56, "anki": "1481857744999", "q": "Cerebral amyloid angiopathy most significantly increases the risk of which complication?", "o": {"A": "Intracranial hemorrhage", "B": "Ischemic stroke from large vessel occlusion", "C": "Subarachnoid hemorrhage from aneurysm rupture", "D": "Venous sinus thrombosis"}, "r": "A", "e": {"correcta": "Amyloid deposition weakens the walls of small cerebral vessels, predisposing to lobar intraparenchymal (intracranial) hemorrhage.", "incorrectas": {"B": "Large vessel occlusive ischemic stroke is typically due to atherosclerosis or embolism, not amyloid deposition in small vessels.", "C": "Subarachnoid hemorrhage from aneurysm rupture is usually due to berry aneurysms at the circle of Willis, not amyloid angiopathy.", "D": "Venous sinus thrombosis is related to hypercoagulable states or local infection, not amyloid deposition."}}}, {"id": "anking-cellular-injury-649", "fuente": "anking", "tema": 56, "anki": "1486590985316", "q": "Which yellow-brown \"wear and tear\" pigment accumulates with normal aging?", "o": {"A": "Lipofuscin", "B": "Hemosiderin", "C": "Melanin", "D": "Bilirubin"}, "r": "A", "e": {"correcta": "Lipofuscin is a yellow-brown pigment composed of oxidized, polymerized lipid and protein remnants that accumulates in cells with normal aging, malnutrition, and cachexia.", "incorrectas": {"B": "Hemosiderin is an iron-storage pigment that accumulates with iron overload or hemorrhage, not simply normal aging.", "C": "Melanin is a pigment produced by melanocytes for pigmentation and UV protection, not an aging \"wear and tear\" pigment.", "D": "Bilirubin is a bile pigment derived from heme breakdown, unrelated to cellular aging pigment accumulation."}}}, {"id": "anking-cellular-injury-650", "fuente": "anking", "tema": 56, "anki": "1486590994020", "q": "Lipofuscin pigment characteristically accumulates within which cellular compartment?", "o": {"A": "Lysosomes", "B": "Mitochondria", "C": "Endoplasmic reticulum", "D": "Nucleus"}, "r": "A", "e": {"correcta": "Lipofuscin accumulates in lysosomes because organellar membranes not cleared by autophagy are oxidized and polymerized there by lysosomal enzymes.", "incorrectas": {"B": "Mitochondria are the organelles being degraded via autophagy, not the site where lipofuscin accumulates.", "C": "The endoplasmic reticulum is not the site of lipofuscin deposition; it is involved in protein/lipid synthesis, not pigment storage.", "D": "The nucleus houses genetic material and is not a site of lipofuscin accumulation."}}}, {"id": "anking-cellular-injury-651", "fuente": "anking", "tema": 56, "anki": "1487458829921", "q": "Which cellular adaptation is defined by an increase in the number of cells in a tissue?", "o": {"A": "Hyperplasia", "B": "Hypertrophy", "C": "Metaplasia", "D": "Dysplasia"}, "r": "A", "e": {"correcta": "Hyperplasia is the controlled proliferation of cells leading to an increased number of cells in a tissue, which may be a risk factor for future malignancy in some contexts.", "incorrectas": {"B": "Hypertrophy is an increase in the size of individual cells, not their number.", "C": "Metaplasia is the replacement of one differentiated cell type by another, not an increase in cell number.", "D": "Dysplasia refers to disordered, atypical cellular growth that is considered a precancerous change, distinct from simple hyperplasia."}}}, {"id": "anking-cellular-injury-652", "fuente": "anking", "tema": 56, "anki": "1487460256729", "q": "Which cellular adaptation is defined by an increase in the size of individual cells?", "o": {"A": "Hypertrophy", "B": "Hyperplasia", "C": "Metaplasia", "D": "Atrophy"}, "r": "A", "e": {"correcta": "Hypertrophy refers to an increase in cell size due to increased production of cellular proteins and organelles, without an increase in cell number.", "incorrectas": {"B": "Hyperplasia is an increase in the number of cells, not their size.", "C": "Metaplasia is a change in cell type in response to stress, not a change in cell size.", "D": "Atrophy is a decrease in cell size or number, the opposite of hypertrophy."}}}, {"id": "anking-cellular-injury-653", "fuente": "anking", "tema": 56, "anki": "1487460262238", "q": "Gene activation, increased protein synthesis, and increased organelle production are hallmarks of which cellular adaptation?", "o": {"A": "Hypertrophy", "B": "Hyperplasia", "C": "Apoptosis", "D": "Autophagy"}, "r": "A", "e": {"correcta": "Hypertrophy involves activation of genes, increased protein synthesis, and production of additional organelles, resulting in an increase in cell size.", "incorrectas": {"B": "Hyperplasia involves increased cell division/number rather than intracellular protein and organelle synthesis within existing cells.", "C": "Apoptosis is programmed cell death, the opposite of the growth processes described.", "D": "Autophagy is a degradative process that consumes cellular components, not a process of building new organelles and protein."}}}, {"id": "anking-cellular-injury-654", "fuente": "anking", "tema": 56, "anki": "1487460265531", "q": "Controlled proliferation of stem cells and differentiated cells, increasing cell number in a tissue, describes which process?", "o": {"A": "Hyperplasia", "B": "Hypertrophy", "C": "Metaplasia", "D": "Necrosis"}, "r": "A", "e": {"correcta": "Hyperplasia is the controlled proliferation of stem and differentiated cells resulting in increased cell number; excessive stimulation can progress toward dysplasia and cancer.", "incorrectas": {"B": "Hypertrophy involves enlargement of existing cells, not proliferation of new cells.", "C": "Metaplasia is a switch from one differentiated cell type to another, not simple proliferation.", "D": "Necrosis is uncontrolled cell death due to injury, the opposite of controlled proliferation."}}}, {"id": "anking-cellular-injury-655", "fuente": "anking", "tema": 56, "anki": "1487460268378", "q": "Permanent tissues such as cardiac muscle, skeletal muscle, and nerve respond to increased demand through which adaptation(s)?", "o": {"A": "Hypertrophy only", "B": "Hyperplasia only", "C": "Both hypertrophy and hyperplasia", "D": "Metaplasia only"}, "r": "A", "e": {"correcta": "Permanent tissues like cardiac muscle, skeletal muscle, and neurons cannot regenerate new cells, so they can only enlarge existing cells (hypertrophy) in response to increased demand.", "incorrectas": {"B": "Hyperplasia requires the ability to produce new cells, which permanent tissues lack.", "C": "Hyperplasia is not possible in permanent tissues since they cannot make new cells.", "D": "Metaplasia refers to replacement by a different cell type, not the adaptive response of permanent tissues to increased workload."}}}, {"id": "anking-cellular-injury-656", "fuente": "anking", "tema": 56, "anki": "1487460276914", "q": "A decrease in tissue mass due to a reduction in cell size or number describes which cellular change?", "o": {"A": "Atrophy", "B": "Hypoplasia", "C": "Necrosis", "D": "Aplasia"}, "r": "A", "e": {"correcta": "Atrophy is a decrease in tissue mass from a reduction in cell size and/or number, caused by disuse, denervation, loss of blood supply, poor nutrition, aging, or mechanical pressure.", "incorrectas": {"B": "Hypoplasia refers to underdevelopment of an organ during development, not an acquired decrease in an already mature tissue.", "C": "Necrosis is uncontrolled cell death from acute injury, not the gradual, often reversible process of atrophy.", "D": "Aplasia is the complete failure of an organ or tissue to develop, not a reduction in an already-formed tissue."}}}, {"id": "anking-cellular-injury-657", "fuente": "anking", "tema": 56, "anki": "1487461041752", "q": "Atrophy occurring through a decrease in cell number is mediated by which process?", "o": {"A": "Apoptosis", "B": "Necrosis", "C": "Autophagy", "D": "Pyknosis alone"}, "r": "A", "e": {"correcta": "Atrophy via reduced cell number occurs through apoptosis, an ATP-dependent programmed cell death triggered by pro-death signals or loss of survival signals.", "incorrectas": {"B": "Necrosis is an uncontrolled, ATP-independent form of cell death caused by acute injury, not the mechanism of physiologic atrophy.", "C": "Autophagy contributes to atrophy via decreased cell size, not decreased cell number.", "D": "Pyknosis is a nuclear morphologic change seen in cell death, not itself the programmed death pathway causing atrophy."}}}, {"id": "anking-cellular-injury-658", "fuente": "anking", "tema": 56, "anki": "1487461046220", "q": "Atrophy via decreased cell size can occur through degradation of the cytoskeleton by which system?", "o": {"A": "Ubiquitin-proteasome system", "B": "Caspase cascade", "C": "Complement system", "D": "Autophagolysosomal fusion of mitochondria only"}, "r": "A", "e": {"correcta": "The ubiquitin-proteasome system tags misfolded, unwanted, or damaged cytoskeletal intermediate filaments with ubiquitin, targeting them for degradation by proteasomes, contributing to reduced cell size.", "incorrectas": {"B": "The caspase cascade executes apoptosis, not the routine turnover of cytoskeletal proteins in atrophy.", "C": "The complement system is part of innate immunity for pathogen defense, unrelated to intracellular protein degradation.", "D": "Mitochondrial autophagy is a separate mechanism (organelle turnover), not the ubiquitin-tagged cytoskeletal degradation described here."}}}, {"id": "anking-cellular-injury-659", "fuente": "anking", "tema": 56, "anki": "1487461053514", "q": "Atrophy via decreased cell size may also occur through degradation of cellular organelles by which process?", "o": {"A": "Autophagy", "B": "Ubiquitin-proteasome system", "C": "Phagocytosis by macrophages", "D": "Complement-mediated lysis"}, "r": "A", "e": {"correcta": "Autophagy, mediated by the Beclin-1 complex, generates autophagic vacuoles that consume organelles; these fuse with lysosomes for degradation, a response to cellular starvation via Akt/mTOR inhibition.", "incorrectas": {"B": "The ubiquitin-proteasome system degrades individual tagged proteins like cytoskeletal filaments, not whole organelles.", "C": "Phagocytosis by macrophages clears extracellular debris and dead cells, not intracellular organelles within a living cell.", "D": "Complement-mediated lysis targets pathogens or cells via membrane attack complex formation, unrelated to organelle turnover."}}}, {"id": "anking-cellular-injury-660", "fuente": "anking", "tema": 56, "anki": "1487461060183", "q": "Replacement of one differentiated cell type by another describes which process?", "o": {"A": "Metaplasia", "B": "Dysplasia", "C": "Hyperplasia", "D": "Anaplasia"}, "r": "A", "e": {"correcta": "Metaplasia is the replacement of one mature cell type by another, typically as an adaptive response to chronic stress.", "incorrectas": {"B": "Dysplasia is disordered, atypical growth within a cell type, not replacement by a different cell type.", "C": "Hyperplasia is an increase in the number of the same cell type, not a change in cell type.", "D": "Anaplasia refers to poorly differentiated, undifferentiated malignant cells, not an adaptive tissue change."}}}, {"id": "anking-cellular-injury-661", "fuente": "anking", "tema": 56, "anki": "1487461064842", "q": "Chronic exposure to an irritant such as gastric acid or cigarette smoke typically induces which cellular adaptation?", "o": {"A": "Metaplasia", "B": "Hypertrophy", "C": "Hyperplasia", "D": "Necrosis"}, "r": "A", "e": {"correcta": "Chronic irritant exposure induces metaplasia, allowing tissue to better withstand stress, such as squamous-to-columnar change in Barrett esophagus from acid reflux or columnar-to-squamous change in the bronchi from smoking.", "incorrectas": {"B": "Hypertrophy is enlargement of existing cells, not a change in cell type in response to chronic irritation.", "C": "Hyperplasia increases cell number of the same cell type, whereas irritant exposure classically causes a change in cell type (metaplasia).", "D": "Necrosis is acute uncontrolled cell death, not the adaptive, reversible change seen with chronic irritant exposure."}}}, {"id": "anking-inflammation-662", "fuente": "anking", "tema": 57, "anki": "1471541327679", "q": "What are the effects of histamine on arterioles and venules during acute inflammation?", "o": {"A": "Arteriolar dilation and venous constriction", "B": "Arteriolar constriction and venous dilation", "C": "Arteriolar and venous constriction", "D": "Arteriolar and venous dilation"}, "r": "A", "e": {"correcta": "Histamine causes arteriolar dilation and venous constriction. The net effect is increased capillary hydrostatic pressure, which increases filtration out of the capillaries and produces edema.", "incorrectas": {"B": "This is the opposite of histamine's actual effect; it does not constrict arterioles or dilate veins preferentially.", "C": "Histamine does not cause constriction of arterioles; it is a vasodilator at the arteriolar level.", "D": "Histamine does not cause venous dilation; it causes venous constriction, which raises capillary pressure."}}}, {"id": "anking-inflammation-663", "fuente": "anking", "tema": 57, "anki": "1471541598687", "q": "What are the effects of bradykinin on arterioles and venules?", "o": {"A": "Arteriolar and venous dilation", "B": "Arteriolar dilation and venous constriction", "C": "Arteriolar constriction and venous dilation", "D": "Arteriolar and venous constriction"}, "r": "B", "e": {"correcta": "Bradykinin, like histamine, causes arteriolar dilation and venous constriction, increasing capillary hydrostatic pressure and promoting edema formation.", "incorrectas": {"A": "Bradykinin does not dilate the venous side; it causes venous constriction instead.", "C": "Bradykinin causes arteriolar dilation, not constriction.", "D": "Bradykinin does not constrict arterioles; its arteriolar effect is vasodilation."}}}, {"id": "anking-inflammation-664", "fuente": "anking", "tema": 57, "anki": "1471806103006", "q": "How does the erythrocyte sedimentation rate (ESR) typically change in a patient with giant cell (temporal) arteritis?", "o": {"A": "Markedly increased (often >100 mm/hr)", "B": "Decreased below normal", "C": "Remains within normal limits", "D": "Mildly decreased due to anemia"}, "r": "A", "e": {"correcta": "Giant cell (temporal) arteritis is a granulomatous vasculitis associated with a markedly elevated ESR, often exceeding 100 mm/hr, reflecting the systemic inflammatory response.", "incorrectas": {"B": "ESR is not decreased in this inflammatory vasculitis; inflammation raises ESR.", "C": "ESR is essentially always significantly elevated in giant cell arteritis, not normal.", "D": "While anemia of chronic disease can occur, it does not lower the ESR; the ESR is characteristically very high."}}}, {"id": "anking-inflammation-665", "fuente": "anking", "tema": 57, "anki": "1471806180799", "q": "How does the ESR typically change in a patient with Takayasu arteritis?", "o": {"A": "Increased", "B": "Decreased", "C": "Unchanged", "D": "Undetectable"}, "r": "A", "e": {"correcta": "Takayasu arteritis is a large-vessel granulomatous vasculitis that produces a systemic inflammatory response, leading to an increased ESR.", "incorrectas": {"B": "Inflammatory vasculitides like Takayasu arteritis raise, not lower, the ESR.", "C": "ESR is characteristically elevated, not normal, in active Takayasu arteritis.", "D": "ESR is a quantifiable, elevated lab value in this disease, not undetectable."}}}, {"id": "anking-inflammation-666", "fuente": "anking", "tema": 57, "anki": "1479267358567", "q": "Which leukocyte is most involved in the acute inflammatory response?", "o": {"A": "Neutrophils", "B": "Lymphocytes", "C": "Plasma cells", "D": "Eosinophils"}, "r": "A", "e": {"correcta": "Neutrophils are the predominant leukocyte in acute inflammation, arriving first at the site of injury or infection to phagocytose pathogens and debris.", "incorrectas": {"B": "Lymphocytes predominate in chronic inflammation and adaptive immune responses, not the acute phase.", "C": "Plasma cells are terminally differentiated B cells involved in antibody production during chronic/adaptive responses, not acute inflammation.", "D": "Eosinophils are primarily involved in parasitic infections and allergic reactions, not the typical acute inflammatory response."}}}, {"id": "anking-inflammation-667", "fuente": "anking", "tema": 57, "anki": "1479267395454", "q": "What is the primary function of macrophages with respect to bacteria, cellular debris, and RBCs?", "o": {"A": "They phagocytose them", "B": "They opsonize them with antibody", "C": "They lyse them via complement activation", "D": "They sequester them within granulomas only"}, "r": "A", "e": {"correcta": "Macrophages phagocytose bacteria, cellular debris, and red blood cells as part of both innate immunity and tissue cleanup during and after inflammation.", "incorrectas": {"B": "Opsonization is typically performed by antibodies or complement proteins coating a target, not the direct action of the macrophage itself.", "C": "Complement-mediated lysis is a function of the membrane attack complex, not a direct macrophage mechanism for debris clearance.", "D": "Granuloma formation is a specific response to certain chronic infections, not the general mechanism macrophages use to clear debris and RBCs."}}}, {"id": "anking-inflammation-668", "fuente": "anking", "tema": 57, "anki": "1487639081947", "q": "Acute inflammation in tissue is characterized by edema and the presence of which cell type?", "o": {"A": "Neutrophils", "B": "Lymphocytes", "C": "Fibroblasts", "D": "Plasma cells"}, "r": "A", "e": {"correcta": "Acute inflammation is characterized histologically by edema and neutrophilic infiltration, whereas chronic inflammation is associated with lymphocytosis.", "incorrectas": {"B": "Lymphocytes are characteristic of chronic inflammation, not the acute phase.", "C": "Fibroblasts are involved in the proliferative/repair phase of healing, not acute inflammation.", "D": "Plasma cells reflect a chronic, antibody-producing immune response rather than acute inflammation."}}}, {"id": "anking-inflammation-669", "fuente": "anking", "tema": 57, "anki": "1487640050564", "q": "Toll-like receptor (TLR) activation results in upregulation of which nuclear transcription factor that activates immune response genes?", "o": {"A": "NF-κB", "B": "STAT3", "C": "AP-1 alone", "D": "HIF-1α"}, "r": "A", "e": {"correcta": "TLR signaling activates NF-κB, a nuclear transcription factor that upregulates genes encoding pro-inflammatory cytokines and other immune response mediators.", "incorrectas": {"B": "STAT3 is primarily activated downstream of cytokine receptors like IL-6, not the principal transcription factor induced by TLR signaling.", "C": "AP-1 can be co-activated in some inflammatory pathways but is not the classic transcription factor upregulated by TLR signaling; NF-κB is the hallmark.", "D": "HIF-1α is induced by hypoxia, not by TLR activation."}}}, {"id": "anking-inflammation-670", "fuente": "anking", "tema": 57, "anki": "1487640061733", "q": "Which enzyme converts arachidonic acid into prostaglandins?", "o": {"A": "Cyclooxygenase", "B": "5-lipoxygenase", "C": "Phospholipase A2", "D": "Thromboxane synthase"}, "r": "A", "e": {"correcta": "Cyclooxygenase (COX) converts arachidonic acid into prostaglandins and is also responsible for producing thromboxane A2.", "incorrectas": {"B": "5-lipoxygenase converts arachidonic acid into leukotrienes, not prostaglandins.", "C": "Phospholipase A2 acts upstream, releasing arachidonic acid from membrane phospholipids, rather than converting it into prostaglandins.", "D": "Thromboxane synthase acts further downstream of cyclooxygenase to specifically generate thromboxane A2, not the general prostaglandin conversion step."}}}, {"id": "anking-inflammation-671", "fuente": "anking", "tema": 57, "anki": "1487640068745", "q": "Which prostaglandins mediate vasodilation and increased vascular permeability?", "o": {"A": "PGE2, PGD2, and PGI2 (prostacyclin)", "B": "Thromboxane A2 and PGF2", "C": "Leukotrienes C4, D4, and E4", "D": "Leukotriene B4 alone"}, "r": "A", "e": {"correcta": "PGE2, PGD2, and PGI2 (prostacyclin) cause vasodilation at arterioles and increased vascular permeability at postcapillary venules, key features of acute inflammation.", "incorrectas": {"B": "Thromboxane A2 promotes vasoconstriction and platelet aggregation, the opposite effect of vasodilation.", "C": "Leukotrienes C4, D4, and E4 cause vasoconstriction and bronchospasm, not vasodilation.", "D": "Leukotriene B4 is chemotactic for neutrophils, not a mediator of vasodilation or permeability."}}}, {"id": "anking-inflammation-672", "fuente": "anking", "tema": 57, "anki": "1487640078840", "q": "Which prostaglandin is the principal mediator of pain and fever?", "o": {"A": "PGE2", "B": "PGD2", "C": "PGI2 (prostacyclin)", "D": "Thromboxane A2"}, "r": "A", "e": {"correcta": "PGE2 is the key prostaglandin mediator of pain and fever during the inflammatory response (mnemonic: \"fEEEEEver\").", "incorrectas": {"B": "PGD2 contributes to vasodilation and permeability but is not the principal mediator of pain and fever.", "C": "PGI2 (prostacyclin) mainly causes vasodilation and inhibits platelet aggregation, not the classic pain/fever mediator.", "D": "Thromboxane A2 promotes vasoconstriction and platelet aggregation, unrelated to pain and fever mediation."}}}, {"id": "anking-inflammation-673", "fuente": "anking", "tema": 57, "anki": "1487640101055", "q": "Which enzyme converts arachidonic acid into leukotrienes?", "o": {"A": "5-lipoxygenase", "B": "Cyclooxygenase", "C": "Phospholipase A2", "D": "Prostacyclin synthase"}, "r": "A", "e": {"correcta": "5-lipoxygenase converts arachidonic acid into leukotrienes, which mediate chemotaxis, bronchoconstriction, and vascular permeability changes.", "incorrectas": {"B": "Cyclooxygenase converts arachidonic acid into prostaglandins and thromboxane, not leukotrienes.", "C": "Phospholipase A2 releases arachidonic acid from membrane phospholipids upstream of the lipoxygenase and cyclooxygenase pathways.", "D": "Prostacyclin synthase acts downstream of cyclooxygenase to produce PGI2, unrelated to leukotriene synthesis."}}}, {"id": "anking-inflammation-674", "fuente": "anking", "tema": 57, "anki": "1487640104877", "q": "Which leukotriene is primarily responsible for attracting and activating neutrophils?", "o": {"A": "Leukotriene B4", "B": "Leukotriene C4", "C": "Leukotriene D4", "D": "Leukotriene E4"}, "r": "A", "e": {"correcta": "Leukotriene B4 is a potent chemoattractant that recruits and activates neutrophils at sites of inflammation.", "incorrectas": {"B": "Leukotriene C4 mediates vasoconstriction and bronchospasm rather than neutrophil chemotaxis.", "C": "Leukotriene D4 mediates vasoconstriction and bronchospasm rather than neutrophil chemotaxis.", "D": "Leukotriene E4 mediates vasoconstriction and bronchospasm rather than neutrophil chemotaxis."}}}, {"id": "anking-inflammation-675", "fuente": "anking", "tema": 57, "anki": "1487640108934", "q": "Which leukotrienes mediate vasoconstriction, bronchospasm, and increased vascular permeability?", "o": {"A": "Leukotrienes C4, D4, and E4", "B": "Leukotriene B4", "C": "PGE2 and PGD2", "D": "Thromboxane A2 alone"}, "r": "A", "e": {"correcta": "Leukotrienes C4, D4, and E4 cause contraction of endothelial and bronchial smooth muscle and pericytes, producing vasoconstriction, bronchospasm, and increased vascular permeability.", "incorrectas": {"B": "Leukotriene B4 functions mainly as a neutrophil chemoattractant, not as a mediator of vasoconstriction and bronchospasm.", "C": "PGE2 and PGD2 cause vasodilation, not vasoconstriction or bronchospasm.", "D": "Thromboxane A2 does cause vasoconstriction but is not responsible for bronchospasm in this classic grouping; the C4/D4/E4 leukotrienes are the mediators described."}}}, {"id": "anking-inflammation-676", "fuente": "anking", "tema": 57, "anki": "1487640116450", "q": "In general, prostaglandins cause which vascular effect?", "o": {"A": "Vasodilation", "B": "Vasoconstriction", "C": "No change in vascular tone", "D": "Selective venous dilation only"}, "r": "A", "e": {"correcta": "Prostaglandins generally cause vasodilation, which is a key contributor to the redness and warmth seen in acute inflammation.", "incorrectas": {"B": "Vasoconstriction is more characteristic of leukotrienes and thromboxane A2, not the general prostaglandin effect.", "C": "Prostaglandins actively alter vascular tone by causing dilation; they do not leave it unchanged.", "D": "Prostaglandins act on arterioles to cause dilation, not selectively on veins only."}}}, {"id": "anking-inflammation-677", "fuente": "anking", "tema": 57, "anki": "1487640120758", "q": "In general, prostaglandins have what effect on vascular permeability?", "o": {"A": "Increased vascular permeability", "B": "Decreased vascular permeability", "C": "No effect on vascular permeability", "D": "Permeability changes only in lymphatics"}, "r": "A", "e": {"correcta": "Prostaglandins generally increase vascular permeability, contributing to the edema characteristic of acute inflammation.", "incorrectas": {"B": "Prostaglandins do not reduce permeability; this would oppose their pro-inflammatory role.", "C": "Prostaglandins actively increase permeability rather than having no effect.", "D": "The permeability increase occurs at postcapillary venules in the systemic vasculature, not specifically in lymphatics."}}}, {"id": "anking-inflammation-678", "fuente": "anking", "tema": 57, "anki": "1487640124653", "q": "In general, leukotrienes cause which vascular effect?", "o": {"A": "Vasoconstriction", "B": "Vasodilation", "C": "No change in vascular tone", "D": "Selective arteriolar dilation only"}, "r": "A", "e": {"correcta": "Leukotrienes (particularly C4, D4, E4) generally cause vasoconstriction, along with bronchospasm and increased vascular permeability, contrasting with the vasodilatory effect of prostaglandins.", "incorrectas": {"B": "Vasodilation is characteristic of prostaglandins, not the general effect of leukotrienes.", "C": "Leukotrienes actively alter vascular tone by causing constriction; they do not leave it unchanged.", "D": "Leukotrienes cause constriction, not dilation, of vascular smooth muscle."}}}, {"id": "anking-renal-pathology-679", "fuente": "anking", "tema": 58, "anki": "1475287350418", "q": "In autosomal dominant polycystic kidney disease (ADPKD), the renal cysts are typically:", "o": {"A": "Unilateral", "B": "Bilateral", "C": "Confined to a single pole of one kidney", "D": "Limited to the renal pelvis only"}, "r": "B", "e": {"correcta": "ADPKD cysts develop in both kidneys (bilateral), progressively enlarging and destroying normal parenchyma.", "incorrectas": {"A": "Unilateral involvement is atypical; ADPKD is a bilateral, systemic genetic disease.", "C": "Cysts are diffusely distributed throughout the cortex and medulla of both kidneys, not localized to one pole.", "D": "Cysts arise from renal tubules, not the pelvis, which is a collecting/urine-drainage structure."}}}, {"id": "anking-renal-pathology-680", "fuente": "anking", "tema": 58, "anki": "1475287371253", "q": "Is polycystic kidney disease (ADPKD) an inherited/heritable condition?", "o": {"A": "Yes, it is heritable", "B": "No, it is always sporadic with no genetic basis", "C": "Only rarely, in less than 1% of cases", "D": "It results solely from environmental toxin exposure"}, "r": "A", "e": {"correcta": "ADPKD is caused by mutations in PKD1 or PKD2 genes and is inherited in an autosomal dominant pattern.", "incorrectas": {"B": "ADPKD has a well-defined genetic basis (PKD1/PKD2 mutations), though de novo mutations can occur.", "C": "The vast majority of cases are inherited, not rare sporadic events.", "D": "Environmental toxins are not the cause; this is a genetic disorder."}}}, {"id": "anking-renal-pathology-681", "fuente": "anking", "tema": 58, "anki": "1475287374579", "q": "Is polycystic kidney disease associated with enlargement of the kidneys?", "o": {"A": "Yes, kidneys become markedly enlarged", "B": "No, kidney size is unaffected", "C": "Kidneys typically shrink and atrophy", "D": "Only the left kidney enlarges"}, "r": "A", "e": {"correcta": "Innumerable cysts progressively expand the kidneys, causing massive bilateral enlargement, often palpable on exam.", "incorrectas": {"B": "Cyst formation and expansion significantly increase kidney size.", "C": "Atrophy is seen in chronic end-stage kidneys of other etiologies, not the classic enlarging picture of ADPKD.", "D": "Both kidneys are affected and enlarge, not just one side."}}}, {"id": "anking-renal-pathology-682", "fuente": "anking", "tema": 58, "anki": "1475287379499", "q": "Autosomal dominant polycystic kidney disease is characterized by cysts located in which two renal regions?", "o": {"A": "Cortex and medulla", "B": "Renal pelvis and ureter", "C": "Glomerulus only", "D": "Renal capsule and hilum"}, "r": "A", "e": {"correcta": "ADPKD cysts arise from tubular segments throughout the kidney, involving both the cortex and medulla.", "incorrectas": {"B": "The pelvis and ureter are urine-collecting structures, not the site of cyst formation in ADPKD.", "C": "Cysts arise from tubules, not glomeruli exclusively.", "D": "The capsule and hilum are not the primary sites of cystic change."}}}, {"id": "anking-renal-pathology-683", "fuente": "anking", "tema": 58, "anki": "1475287382270", "q": "Autosomal recessive polycystic kidney disease (ARPKD) is characterized by cystic dilation of which renal structure?", "o": {"A": "Collecting ducts", "B": "Renal artery", "C": "Glomerular capillaries", "D": "Bowman's capsule"}, "r": "A", "e": {"correcta": "ARPKD results from cystic dilation of the collecting ducts, typically presenting in infancy.", "incorrectas": {"B": "The renal artery is a vascular structure, not the site of cystic dilation in ARPKD.", "C": "Glomerular capillaries are not the classic site of cyst formation in ARPKD.", "D": "Bowman's capsule surrounds the glomerulus and is not the affected structure in ARPKD."}}}, {"id": "anking-renal-pathology-684", "fuente": "anking", "tema": 58, "anki": "1475287386660", "q": "Autosomal recessive PKD presents in infants as worsening renal failure and which additional finding?", "o": {"A": "Hypertension", "B": "Hyperglycemia", "C": "Hypocalcemia", "D": "Hyperthyroidism"}, "r": "A", "e": {"correcta": "Infants with ARPKD often present with worsening renal failure and hypertension due to renin release from cystic kidneys.", "incorrectas": {"B": "Hyperglycemia is not a characteristic feature of ARPKD.", "C": "Hypocalcemia is not a classic presenting feature of ARPKD.", "D": "Thyroid dysfunction is unrelated to ARPKD pathophysiology."}}}, {"id": "anking-renal-pathology-685", "fuente": "anking", "tema": 58, "anki": "1475287388509", "q": "Which form(s) of polycystic kidney disease are associated with hepatic cysts?", "o": {"A": "Only autosomal dominant PKD", "B": "Only autosomal recessive PKD", "C": "Both autosomal dominant and autosomal recessive PKD", "D": "Neither form is associated with hepatic cysts"}, "r": "C", "e": {"correcta": "Both ADPKD and ARPKD can be associated with hepatic cysts; these usually do not impair liver function but can cause pain if large.", "incorrectas": {"A": "ARPKD is also associated with hepatic cysts, so this is not exclusive to ADPKD.", "B": "ADPKD is also associated with hepatic cysts, so this is not exclusive to ARPKD.", "D": "Both forms are associated with hepatic cysts, not neither."}}}, {"id": "anking-renal-pathology-686", "fuente": "anking", "tema": 58, "anki": "1475287392656", "q": "Which congenital renal defect may cause portal hypertension in an infant?", "o": {"A": "Autosomal recessive PKD", "B": "Autosomal dominant PKD", "C": "Simple renal cyst", "D": "Renal agenesis"}, "r": "A", "e": {"correcta": "ARPKD is associated with congenital hepatic fibrosis, which can lead to portal hypertension in infants.", "incorrectas": {"B": "ADPKD typically presents in adulthood, not infancy, and is not classically linked to congenital hepatic fibrosis/portal hypertension in infants.", "C": "A simple renal cyst is a benign, isolated finding unrelated to liver fibrosis or portal hypertension.", "D": "Renal agenesis is absence of kidney development and is not linked to congenital hepatic fibrosis."}}}, {"id": "anking-renal-pathology-687", "fuente": "anking", "tema": 58, "anki": "1475287403610", "q": "Autosomal dominant PKD may present in young adults with which type of pain, along with urinary infection?", "o": {"A": "Flank pain", "B": "Suprapubic pain only", "C": "Chest pain", "D": "Periumbilical pain"}, "r": "A", "e": {"correcta": "Flank pain occurs due to dilation of the cysts and stretching of the renal capsule in ADPKD.", "incorrectas": {"B": "Suprapubic pain is more typical of bladder pathology, not cystic kidney enlargement.", "C": "Chest pain is not a classic renal symptom of ADPKD.", "D": "Periumbilical pain is not characteristic of renal capsule stretching from cysts."}}}, {"id": "anking-renal-pathology-688", "fuente": "anking", "tema": 58, "anki": "1475287417725", "q": "Autosomal dominant PKD may present in young adults as worsening renal failure and which urinary finding?", "o": {"A": "Hematuria", "B": "Glucosuria", "C": "Pyuria without infection", "D": "Ketonuria"}, "r": "A", "e": {"correcta": "As ADPKD cysts develop and enlarge over time, patients often develop hematuria along with progressive renal failure.", "incorrectas": {"B": "Glucosuria suggests diabetes or proximal tubule dysfunction, not the classic ADPKD presentation.", "C": "Sterile pyuria is not the classic urinary finding described for ADPKD progression.", "D": "Ketonuria reflects metabolic states like fasting or diabetic ketoacidosis, unrelated to ADPKD."}}}, {"id": "anking-renal-pathology-689", "fuente": "anking", "tema": 58, "anki": "1475287427443", "q": "What percentage of patients with autosomal dominant PKD experience progressive renal failure (reaching end-stage renal disease by age 70)?", "o": {"A": "50%", "B": "10%", "C": "90%", "D": "25%"}, "r": "A", "e": {"correcta": "Approximately 50% of ADPKD patients progress to end-stage renal disease by age 70.", "incorrectas": {"B": "10% underestimates the actual proportion who progress to ESRD.", "C": "90% overestimates the proportion; not nearly all patients progress to ESRD by that age.", "D": "25% underestimates the true proportion, which is closer to half of patients."}}}, {"id": "anking-renal-pathology-690", "fuente": "anking", "tema": 58, "anki": "1475287434487", "q": "Autosomal dominant PKD is associated with which vascular abnormality that is an important cause of death?", "o": {"A": "Berry aneurysm", "B": "Aortic dissection", "C": "Deep vein thrombosis", "D": "Coronary artery aneurysm"}, "r": "A", "e": {"correcta": "ADPKD is associated with berry (saccular) aneurysms of the circle of Willis, which can rupture causing subarachnoid hemorrhage and death.", "incorrectas": {"B": "Aortic dissection is not the classic vascular association taught with ADPKD.", "C": "DVT is not a hallmark vascular complication of ADPKD.", "D": "Coronary artery aneurysms are not a recognized association of ADPKD."}}}, {"id": "anking-renal-pathology-691", "fuente": "anking", "tema": 58, "anki": "1475287436376", "q": "In addition to renal cysts, both autosomal dominant and recessive PKD are associated with benign cysts in which organ?", "o": {"A": "Liver (hepatic cysts)", "B": "Spleen", "C": "Pancreas exclusively", "D": "Lungs"}, "r": "A", "e": {"correcta": "Both ADPKD and ARPKD are associated with benign hepatic cysts in addition to renal cysts.", "incorrectas": {"B": "Splenic cysts are not the classically taught association with PKD.", "C": "While pancreatic cysts can occur in ADPKD, hepatic cysts are the classic and more consistently tested association across both forms.", "D": "Pulmonary cysts are not a typical association of PKD."}}}, {"id": "anking-renal-pathology-692", "fuente": "anking", "tema": 58, "anki": "1475287438868", "q": "Which heart defect is associated with autosomal dominant PKD?", "o": {"A": "Mitral valve prolapse", "B": "Tetralogy of Fallot", "C": "Atrial septal defect", "D": "Bicuspid aortic valve"}, "r": "A", "e": {"correcta": "ADPKD is associated with mitral valve prolapse due to connective tissue abnormalities affecting valve structure.", "incorrectas": {"B": "Tetralogy of Fallot is a congenital cyanotic heart defect unrelated to ADPKD.", "C": "ASD is not the classic cardiac association taught with ADPKD.", "D": "Bicuspid aortic valve is associated with other conditions (e.g., Turner syndrome, coarctation), not classically ADPKD."}}}, {"id": "anking-renal-pathology-693", "fuente": "anking", "tema": 58, "anki": "1475287441317", "q": "When patients with autosomal dominant PKD develop hypertension or proteinuria, which medication class is used for treatment?", "o": {"A": "ACE inhibitors or ARBs", "B": "Thiazide diuretics as first-line", "C": "Beta-blockers exclusively", "D": "Calcium channel blockers exclusively"}, "r": "A", "e": {"correcta": "ACE inhibitors or ARBs are used to control hypertension and reduce proteinuria in ADPKD, providing renal protective effects.", "incorrectas": {"B": "Thiazides are not first-line therapy for ADPKD-associated hypertension with proteinuria.", "C": "Beta-blockers are not the preferred first-line agents for renoprotection in this setting.", "D": "Calcium channel blockers are not the first-line choice when proteinuria is present; ACEi/ARBs are preferred for renoprotection."}}}, {"id": "anking-renal-pathology-694", "fuente": "anking", "tema": 58, "anki": "1475287443246", "q": "Is Autosomal Dominant Tubulointerstitial Kidney Disease (formerly Medullary Cystic Kidney Disease) a heritable condition?", "o": {"A": "Yes, it is heritable", "B": "No, it is purely acquired", "C": "Only heritable in females", "D": "It is caused exclusively by infection"}, "r": "A", "e": {"correcta": "This disease is heritable, caused by autosomal dominant mutations in genes such as MUC1 (mucin-1) and UMOD (uromodulin), which normally protect the tubular epithelium.", "incorrectas": {"B": "It has a clear genetic basis (MUC1, UMOD mutations), not an acquired etiology.", "C": "Autosomal dominant inheritance affects both sexes equally; it is not sex-limited.", "D": "It is a genetic disease, not an infectious one."}}}, {"id": "anking-renal-pathology-695", "fuente": "anking", "tema": 58, "anki": "1475287445404", "q": "What is the mode of inheritance of (Autosomal Dominant Tubulointerstitial Kidney Disease, formerly medullary cystic kidney disease)?", "o": {"A": "Autosomal dominant", "B": "Autosomal recessive", "C": "X-linked recessive", "D": "Mitochondrial"}, "r": "A", "e": {"correcta": "The disease is autosomal dominant, caused by mutations in tubular protective proteins (mucin-1, uromodulin) affecting the thick ascending limb and distal convoluted tubule.", "incorrectas": {"B": "Autosomal recessive inheritance would require two mutated alleles, which is not the pattern seen here.", "C": "X-linked recessive inheritance predominantly affects males with a different transmission pattern, not seen in this disease.", "D": "Mitochondrial inheritance follows maternal transmission and is not the pattern of this disease."}}}, {"id": "anking-renal-pathology-696", "fuente": "anking", "tema": 58, "anki": "1475287447506", "q": "Autosomal Dominant Tubulointerstitial Kidney Disease (ADTKD) has the potential to present with cysts in which location?", "o": {"A": "Medullary collecting ducts", "B": "Renal cortex only", "C": "Glomerular tuft", "D": "Renal artery wall"}, "r": "A", "e": {"correcta": "ADTKD (formerly medullary cystic kidney disease) can present with cysts in the medullary collecting ducts, though most patients actually lack visible cysts, making the old name a misnomer.", "incorrectas": {"B": "Cortical cysts are more characteristic of ADPKD, not ADTKD.", "C": "Glomerular cysts are not the described feature of this disease.", "D": "Vascular wall involvement is not part of this tubulointerstitial disease process."}}}, {"id": "anking-renal-pharmacology-697", "fuente": "anking", "tema": 59, "anki": "1474684616177", "q": "In the kidney, renin is synthesized, stored, and released from which structure?", "o": {"A": "Juxtaglomerular apparatus", "B": "Macula densa alone", "C": "Proximal convoluted tubule", "D": "Renal medulla interstitium"}, "r": "A", "e": {"correcta": "The juxtaglomerular apparatus (specifically the granular/JG cells of the afferent arteriole) synthesizes, stores, and releases renin in response to decreased renal perfusion pressure, decreased NaCl delivery, and sympathetic stimulation.", "incorrectas": {"B": "The macula densa senses NaCl concentration and signals the JG cells but does not itself store or release renin.", "C": "The proximal convoluted tubule is responsible for bulk reabsorption, not renin secretion.", "D": "The renal medulla interstitium is involved in the countercurrent mechanism, not renin production."}}}, {"id": "anking-renal-pharmacology-698", "fuente": "anking", "tema": 59, "anki": "1474686171007", "q": "Renin catalyzes the conversion of which substrate to which product?", "o": {"A": "Angiotensinogen to angiotensin I", "B": "Angiotensin I to angiotensin II", "C": "Angiotensinogen to angiotensin II", "D": "Angiotensin II to aldosterone"}, "r": "A", "e": {"correcta": "Renin cleaves angiotensinogen (produced by the liver) to form angiotensin I, the first step of the renin-angiotensin-aldosterone system.", "incorrectas": {"B": "This conversion is catalyzed by ACE, not renin.", "C": "Renin does not directly produce angiotensin II; that requires ACE acting on angiotensin I.", "D": "Angiotensin II stimulates aldosterone release via receptor binding, not an enzymatic conversion by renin."}}}, {"id": "anking-renal-pharmacology-699", "fuente": "anking", "tema": 59, "anki": "1474686176874", "q": "Angiotensin-converting enzyme (ACE) is primarily located in the vascular endothelium of which organ?", "o": {"A": "Lungs", "B": "Kidneys", "C": "Liver", "D": "Heart"}, "r": "A", "e": {"correcta": "ACE is predominantly found on the vascular endothelium of the pulmonary capillaries, making the lungs the primary site of angiotensin I to angiotensin II conversion.", "incorrectas": {"B": "The kidney is the site of renin release and angiotensin II action but not the primary site of ACE activity.", "C": "The liver produces angiotensinogen, not ACE.", "D": "ACE activity in cardiac tissue exists but is not the primary site compared to the lungs."}}}, {"id": "anking-renal-pharmacology-700", "fuente": "anking", "tema": 59, "anki": "1474686182224", "q": "Which enzyme converts angiotensin I to angiotensin II, primarily in the lungs?", "o": {"A": "Angiotensin-converting enzyme (ACE)", "B": "Renin", "C": "Chymase", "D": "Neprilysin"}, "r": "A", "e": {"correcta": "ACE, located mainly on pulmonary vascular endothelium, converts angiotensin I into the active vasoconstrictor angiotensin II.", "incorrectas": {"B": "Renin acts upstream, converting angiotensinogen to angiotensin I.", "C": "Chymase is an alternative (non-ACE) pathway for angiotensin II generation but is not the primary enzyme referenced here.", "D": "Neprilysin degrades natriuretic peptides and bradykinin, unrelated to angiotensin I conversion."}}}, {"id": "anking-renal-pharmacology-701", "fuente": "anking", "tema": 59, "anki": "1474686187282", "q": "Angiotensin II is a potent mediator of which vascular effect?", "o": {"A": "Vasoconstriction", "B": "Vasodilation", "C": "Venodilation only", "D": "No significant vascular effect"}, "r": "A", "e": {"correcta": "Angiotensin II is one of the most potent endogenous vasoconstrictors, increasing systemic vascular resistance and blood pressure.", "incorrectas": {"B": "Angiotensin II causes vasoconstriction, the opposite of vasodilation.", "C": "Its constrictive effect is not limited to veins; it strongly affects arterioles as well.", "D": "Angiotensin II has significant and well-documented vascular effects."}}}, {"id": "anking-renal-pharmacology-702", "fuente": "anking", "tema": 59, "anki": "1474686197574", "q": "What is the effect of normal (physiologic) levels of angiotensin II on glomerular filtration rate (GFR)?", "o": {"A": "Increased GFR", "B": "Decreased GFR", "C": "No change in GFR", "D": "GFR becomes unmeasurable"}, "r": "A", "e": {"correcta": "At physiologic levels, angiotensin II preferentially constricts the efferent arteriole, which raises glomerular capillary pressure and increases GFR.", "incorrectas": {"B": "Decreased GFR is seen with very high levels of angiotensin II or with ACE inhibitor/ARB use, not normal levels.", "C": "Angiotensin II does change GFR by preferentially constricting the efferent arteriole.", "D": "This is not a physiologic outcome of angiotensin II activity."}}}, {"id": "anking-renal-pharmacology-703", "fuente": "anking", "tema": 59, "anki": "1474686203572", "q": "Angiotensin II normally constricts which arteriole of the kidney, helping to maintain GFR during decreased renal blood flow?", "o": {"A": "Efferent arteriole", "B": "Afferent arteriole", "C": "Interlobular artery", "D": "Vasa recta"}, "r": "A", "e": {"correcta": "Angiotensin II preferentially constricts the efferent arteriole, which increases glomerular hydrostatic pressure and preserves GFR during states of decreased renal perfusion such as hypotension or renal artery stenosis.", "incorrectas": {"B": "Afferent arteriole constriction would decrease, not preserve, GFR; angiotensin II preferentially spares/dilates the afferent side relative to efferent.", "C": "Interlobular arteries are conduit vessels and are not the primary site of angiotensin II-mediated resistance changes.", "D": "The vasa recta are involved in the medullary countercurrent exchange, not the GFR-preserving action of angiotensin II."}}}, {"id": "anking-renal-pharmacology-704", "fuente": "anking", "tema": 59, "anki": "1474686218949", "q": "Angiotensin II stimulates the release of which hormone from the adrenal cortex?", "o": {"A": "Aldosterone", "B": "Cortisol", "C": "Epinephrine", "D": "Dehydroepiandrosterone (DHEA)"}, "r": "A", "e": {"correcta": "Angiotensin II acts on the zona glomerulosa of the adrenal cortex to stimulate aldosterone secretion, which indirectly promotes sodium and water retention.", "incorrectas": {"B": "Cortisol release is primarily regulated by ACTH from the zona fasciculata, not angiotensin II.", "C": "Epinephrine is released from the adrenal medulla in response to sympathetic stimulation, not angiotensin II.", "D": "DHEA is produced by the zona reticularis and is regulated mainly by ACTH."}}}, {"id": "anking-renal-pharmacology-705", "fuente": "anking", "tema": 59, "anki": "1474686227756", "q": "What effect does angiotensin II indirectly have on serum potassium levels (via aldosterone)?", "o": {"A": "Decreased potassium", "B": "Increased potassium", "C": "No effect on potassium", "D": "Potassium levels become unpredictable"}, "r": "A", "e": {"correcta": "Aldosterone, stimulated by angiotensin II, increases renal potassium excretion in the collecting duct, indirectly lowering serum potassium.", "incorrectas": {"B": "Increased potassium (hyperkalemia) is seen when aldosterone is decreased, such as with ACE inhibitors, not with angiotensin II stimulation.", "C": "Angiotensin II, through aldosterone, has a clear lowering effect on serum potassium.", "D": "The effect is a predictable decrease in serum potassium due to increased renal excretion."}}}, {"id": "anking-renal-pharmacology-706", "fuente": "anking", "tema": 59, "anki": "1474686246072", "q": "What effect do ACE inhibitors have on circulating levels of angiotensin II?", "o": {"A": "Decreased angiotensin II", "B": "Increased angiotensin II", "C": "No change in angiotensin II", "D": "Angiotensin II is converted to angiotensin I"}, "r": "A", "e": {"correcta": "ACE inhibitors block the conversion of angiotensin I to angiotensin II, resulting in decreased angiotensin II levels.", "incorrectas": {"B": "Increased angiotensin II would occur with excess ACE activity or renin secretion, not ACE inhibition.", "C": "ACE inhibitors directly reduce angiotensin II production by blocking its formation.", "D": "ACE inhibitors block forward conversion; they do not cause reverse conversion of angiotensin II to angiotensin I."}}}, {"id": "anking-renal-pharmacology-707", "fuente": "anking", "tema": 59, "anki": "1474686254735", "q": "What effect do ACE inhibitors and ARBs have on glomerular filtration rate (GFR)?", "o": {"A": "Decreased GFR", "B": "Increased GFR", "C": "No effect on GFR", "D": "GFR increases only in diabetic patients"}, "r": "A", "e": {"correcta": "By blocking angiotensin II's preferential constriction of the efferent arteriole, ACE inhibitors and ARBs reduce glomerular capillary pressure and decrease GFR.", "incorrectas": {"B": "Increased GFR is the effect of angiotensin II itself, the opposite of ACE inhibitor/ARB action.", "C": "These drugs have a well-documented dose-dependent effect of lowering GFR, especially early in treatment.", "D": "While ACE inhibitors are renoprotective in diabetic nephropathy, the acute GFR-lowering effect occurs in all patients, not only diabetics."}}}, {"id": "anking-renal-pharmacology-708", "fuente": "anking", "tema": 59, "anki": "1474686269926", "q": "What effect do ACE inhibitors and ARBs have on aldosterone release from the adrenal cortex?", "o": {"A": "Decrease aldosterone release", "B": "Increase aldosterone release", "C": "No effect on aldosterone release", "D": "Convert aldosterone to cortisol"}, "r": "A", "e": {"correcta": "By reducing angiotensin II levels or blocking its receptor, ACE inhibitors and ARBs decrease the stimulus for aldosterone secretion from the adrenal cortex.", "incorrectas": {"B": "Increased aldosterone would occur with elevated angiotensin II, the opposite of these drugs' mechanism.", "C": "These drugs measurably reduce aldosterone secretion, which underlies their risk of causing hyperkalemia.", "D": "ACE inhibitors and ARBs do not chemically convert one hormone into another."}}}, {"id": "anking-renal-pharmacology-709", "fuente": "anking", "tema": 59, "anki": "1474686274500", "q": "ACE inhibitors can cause what change in serum creatinine within the first few days of starting treatment?", "o": {"A": "An elevation in creatinine", "B": "A drop in creatinine", "C": "No change in creatinine", "D": "Creatinine becomes undetectable"}, "r": "A", "e": {"correcta": "Due to the acute decrease in GFR from efferent arteriolar dilation, ACE inhibitors commonly cause a modest rise in serum creatinine when therapy is initiated.", "incorrectas": {"B": "A drop in creatinine would suggest improved GFR, which is not the expected initial effect of ACE inhibitors.", "C": "A mild creatinine rise (up to about 30%) is an expected and generally acceptable finding, not an absence of change.", "D": "Creatinine levels do not disappear; they typically rise modestly and then stabilize."}}}, {"id": "anking-renal-pharmacology-710", "fuente": "anking", "tema": 59, "anki": "1474686309779", "q": "What effect do ACE inhibitors have on levels of angiotensin I and renin?", "o": {"A": "Increased levels of both", "B": "Decreased levels of both", "C": "Increased angiotensin I, decreased renin", "D": "No change in either"}, "r": "A", "e": {"correcta": "Loss of negative feedback from angiotensin II (due to ACE blockade) leads to compensatory increases in renin secretion and, consequently, angiotensin I levels.", "incorrectas": {"B": "Decreased levels would occur if the RAAS were suppressed upstream, but ACE inhibition actually removes negative feedback, raising both.", "C": "Renin rises along with angiotensin I because renin drives angiotensin I production; they do not move in opposite directions here.", "D": "There is a well-documented compensatory rise in both renin and angiotensin I with ACE inhibitor therapy."}}}, {"id": "anking-renal-pharmacology-711", "fuente": "anking", "tema": 59, "anki": "1474686320085", "q": "What effect may ACE inhibitors have on serum potassium levels?", "o": {"A": "Increased potassium (hyperkalemia)", "B": "Decreased potassium (hypokalemia)", "C": "No effect on potassium", "D": "Potassium is converted to sodium"}, "r": "A", "e": {"correcta": "By decreasing aldosterone secretion, ACE inhibitors reduce renal potassium excretion, which can lead to hyperkalemia.", "incorrectas": {"B": "Hypokalemia would be expected with increased aldosterone activity (e.g., loop or thiazide diuretics), not ACE inhibition.", "C": "ACE inhibitors have a clinically significant and monitored effect of raising potassium.", "D": "Electrolytes are not interconverted; this option describes an impossible physiological process."}}}, {"id": "anking-renal-pharmacology-712", "fuente": "anking", "tema": 59, "anki": "1474686325582", "q": "ACE inhibitors are first-line agents in the treatment of which condition?", "o": {"A": "Heart failure", "B": "Hyperthyroidism", "C": "Acute asthma exacerbation", "D": "Peptic ulcer disease"}, "r": "A", "e": {"correcta": "ACE inhibitors are first-line therapy in heart failure because they decrease preload and afterload and reduce sympathetic tone, improving symptoms and survival.", "incorrectas": {"B": "Hyperthyroidism is treated with antithyroid drugs, beta-blockers, or radioactive iodine, not ACE inhibitors.", "C": "Acute asthma is treated with bronchodilators and corticosteroids; ACE inhibitors can even worsen cough, an unrelated issue.", "D": "Peptic ulcer disease is managed with acid suppression (PPIs, H2 blockers) and H. pylori eradication, not ACE inhibitors."}}}, {"id": "anking-renal-pharmacology-713", "fuente": "anking", "tema": 59, "anki": "1474686333322", "q": "Do ACE inhibitors reduce mortality in patients with heart failure and myocardial infarction?", "o": {"A": "Yes, they reduce mortality", "B": "No, they have no mortality benefit", "C": "They increase mortality in heart failure", "D": "They only improve symptoms without any survival benefit"}, "r": "A", "e": {"correcta": "Multiple landmark trials have shown ACE inhibitors reduce mortality in patients with heart failure and post-myocardial infarction, making them a cornerstone of guideline-directed therapy.", "incorrectas": {"B": "This contradicts strong clinical trial evidence demonstrating a clear survival benefit.", "C": "ACE inhibitors are associated with reduced, not increased, mortality in these populations.", "D": "ACE inhibitors provide a proven survival benefit in addition to symptomatic improvement."}}}, {"id": "anking-renal-pharmacology-714", "fuente": "anking", "tema": 59, "anki": "1474686349415", "q": "ACE inhibitors are a first-line agent in the treatment of which condition?", "o": {"A": "Primary hypertension", "B": "Hyperaldosteronism from an adrenal adenoma", "C": "Pheochromocytoma", "D": "Cushing syndrome"}, "r": "A", "e": {"correcta": "ACE inhibitors are recommended first-line agents for treating primary (essential) hypertension due to their efficacy and cardiovascular/renal protective effects.", "incorrectas": {"B": "Primary hyperaldosteronism from an adenoma is best treated surgically or with mineralocorticoid receptor antagonists like spironolactone.", "C": "Pheochromocytoma is treated with alpha-blockade (e.g., phenoxybenzamine) followed by beta-blockade, not ACE inhibitors as first-line.", "D": "Cushing syndrome requires treatment of the underlying cortisol excess (surgery, cortisol synthesis inhibitors), not ACE inhibitors."}}}, {"id": "anking-renal-embryology-715", "fuente": "anking", "tema": 60, "anki": "1475287234425", "q": "What is the most common congenital renal anomaly?", "o": {"A": "Horseshoe kidney", "B": "Renal agenesis", "C": "Polycystic kidney disease", "D": "Duplicated ureter"}, "r": "A", "e": {"correcta": "Horseshoe kidney, fusion of the lower (and rarely upper) poles of the kidneys, is the most common congenital renal anomaly, occurring in about 1 in 500 people.", "incorrectas": {"B": "Renal agenesis (unilateral or bilateral absence of a kidney) is much rarer than horseshoe kidney.", "C": "Polycystic kidney disease is a genetic cystic disorder, not the most common congenital anomaly.", "D": "Duplicated ureter is a ureteral anomaly, less common than horseshoe kidney."}}}, {"id": "anking-renal-embryology-716", "fuente": "anking", "tema": 60, "anki": "1475287241814", "q": "As horseshoe kidneys ascend from the pelvis during fetal development, they become trapped under which artery, causing them to remain low in the abdomen?", "o": {"A": "Superior mesenteric artery", "B": "Inferior mesenteric artery", "C": "Renal artery", "D": "Celiac artery"}, "r": "B", "e": {"correcta": "The horseshoe kidney's isthmus gets caught under the inferior mesenteric artery during ascent, preventing it from reaching its normal lumbar position.", "incorrectas": {"A": "The superior mesenteric artery is located above the level where the horseshoe kidney becomes trapped.", "C": "The renal arteries arise from the aorta at the level of the kidneys but do not cause the entrapment.", "D": "The celiac artery is well above the level of kidney ascent and is not involved in this entrapment."}}}, {"id": "anking-renal-embryology-717", "fuente": "anking", "tema": 60, "anki": "1475287246977", "q": "Is kidney function typically normal or abnormal in horseshoe kidney?", "o": {"A": "Normal", "B": "Severely reduced due to fused parenchyma", "C": "Absent, requiring dialysis", "D": "Function is present only in one of the fused kidneys"}, "r": "A", "e": {"correcta": "Despite the anatomic fusion, horseshoe kidneys generally function normally, though they carry increased risk of complications like obstruction, stones, and infection.", "incorrectas": {"B": "Fusion of the lower poles does not typically impair overall renal function significantly.", "C": "Horseshoe kidney does not cause renal failure or absent function by itself.", "D": "Both fused kidney masses generally retain functioning nephrons and contribute to filtration."}}}, {"id": "anking-renal-embryology-718", "fuente": "anking", "tema": 60, "anki": "1475287250177", "q": "Horseshoe kidney is associated with which complication due to ureteropelvic junction obstruction?", "o": {"A": "Hydronephrosis", "B": "Renal vein thrombosis", "C": "Nephrotic syndrome", "D": "Renal artery stenosis"}, "r": "A", "e": {"correcta": "The abnormal position and course of the ureters over the fused isthmus predisposes to ureteropelvic junction obstruction, leading to hydronephrosis.", "incorrectas": {"B": "Renal vein thrombosis is a vascular complication unrelated to ureteral obstruction in horseshoe kidney.", "C": "Nephrotic syndrome is a glomerular disease process, not a structural consequence of horseshoe kidney.", "D": "Renal artery stenosis involves the renal vasculature, not urinary outflow obstruction."}}}, {"id": "anking-renal-embryology-719", "fuente": "anking", "tema": 60, "anki": "1475287252831", "q": "Horseshoe kidney increases the risk of kidney infection and which other condition?", "o": {"A": "Kidney stones", "B": "Renal cell carcinoma", "C": "Minimal change disease", "D": "IgA nephropathy"}, "r": "A", "e": {"correcta": "Urinary stasis from abnormal drainage in horseshoe kidney predisposes to stone formation as well as infection.", "incorrectas": {"B": "Renal cell carcinoma is only rarely associated with horseshoe kidney, unlike the more common stone risk.", "C": "Minimal change disease is a primary glomerular disorder unrelated to horseshoe kidney anatomy.", "D": "IgA nephropathy is an immune-mediated glomerulonephritis, not a structural complication of horseshoe kidney."}}}, {"id": "anking-renal-embryology-720", "fuente": "anking", "tema": 60, "anki": "1475287255781", "q": "Which sex chromosome disorder is associated with horseshoe kidney?", "o": {"A": "Turner syndrome", "B": "Klinefelter syndrome", "C": "Triple X syndrome", "D": "XYY syndrome"}, "r": "A", "e": {"correcta": "Turner syndrome (45,XO) is classically associated with horseshoe kidney along with other anomalies like coarctation of the aorta and bicuspid aortic valve.", "incorrectas": {"B": "Klinefelter syndrome (47,XXY) is not classically associated with horseshoe kidney.", "C": "Triple X syndrome is generally not associated with renal anomalies.", "D": "XYY syndrome does not have a notable association with horseshoe kidney."}}}, {"id": "anking-renal-embryology-721", "fuente": "anking", "tema": 60, "anki": "1475287258523", "q": "Which congenital kidney disease is associated with chromosomal aneuploidies such as trisomy 13, 18, and 21?", "o": {"A": "Horseshoe kidney", "B": "Multicystic dysplastic kidney", "C": "Renal agenesis", "D": "Medullary sponge kidney"}, "r": "A", "e": {"correcta": "Horseshoe kidney is associated with aneuploidy syndromes, including trisomy 13 (Patau), trisomy 18 (Edwards), and trisomy 21 (Down syndrome).", "incorrectas": {"B": "Multicystic dysplastic kidney is not classically linked to these trisomies as a defining association.", "C": "Renal agenesis is not the classic anomaly linked with these trisomy syndromes in this context.", "D": "Medullary sponge kidney is typically a sporadic condition, not linked to chromosomal aneuploidy."}}}, {"id": "anking-renal-embryology-722", "fuente": "anking", "tema": 60, "anki": "1475287261393", "q": "Horseshoe kidney is rarely associated with an increased risk of which malignancy?", "o": {"A": "Renal cancer", "B": "Hepatocellular carcinoma", "C": "Bladder cancer", "D": "Adrenal carcinoma"}, "r": "A", "e": {"correcta": "Horseshoe kidney carries a rare but recognized increased risk of renal cancer, including Wilms tumor and renal cell carcinoma.", "incorrectas": {"B": "Hepatocellular carcinoma arises from the liver and has no established link to horseshoe kidney.", "C": "Bladder cancer is not the malignancy classically linked with horseshoe kidney.", "D": "Adrenal carcinoma is unrelated to the renal fusion anomaly of horseshoe kidney."}}}, {"id": "anking-renal-embryology-723", "fuente": "anking", "tema": 60, "anki": "1475287265217", "q": "Which congenital kidney disease involves unilateral or bilateral absence of kidney and ureter formation?", "o": {"A": "Renal agenesis", "B": "Horseshoe kidney", "C": "Polycystic kidney disease", "D": "Duplex collecting system"}, "r": "A", "e": {"correcta": "Renal agenesis results from failure of the ureteric bud to develop or interact with the metanephric mesenchyme, leading to absence of the kidney and ureter on one or both sides.", "incorrectas": {"B": "Horseshoe kidney involves fusion of two kidneys, not absence of kidney tissue.", "C": "Polycystic kidney disease involves cyst formation within existing kidneys, not agenesis.", "D": "Duplex collecting system is a ureteral duplication anomaly, not absence of the kidney."}}}, {"id": "anking-renal-embryology-724", "fuente": "anking", "tema": 60, "anki": "1475287273153", "q": "Renal agenesis is often diagnosed prenatally using which imaging modality?", "o": {"A": "Ultrasound", "B": "CT scan", "C": "MRI", "D": "Nuclear renal scan"}, "r": "A", "e": {"correcta": "Prenatal ultrasound is the standard modality used to detect renal agenesis, often revealing oligohydramnios as a clue along with absent kidney visualization.", "incorrectas": {"B": "CT scan involves ionizing radiation and is not used for routine prenatal screening.", "C": "MRI is not the standard first-line prenatal screening tool for this diagnosis.", "D": "Nuclear renal scans are used postnatally to assess function, not for prenatal screening."}}}, {"id": "anking-renal-embryology-725", "fuente": "anking", "tema": 60, "anki": "1475287276309", "q": "In unilateral renal agenesis, what happens to the remaining kidney?", "o": {"A": "It undergoes hypertrophy", "B": "It atrophies", "C": "It develops cysts", "D": "It remains unchanged in size"}, "r": "A", "e": {"correcta": "The solitary kidney compensates for the absent contralateral kidney by undergoing compensatory hypertrophy to maintain adequate filtration.", "incorrectas": {"B": "Atrophy would worsen renal function, which is the opposite of the compensatory response seen.", "C": "Cyst development is not the typical compensatory response of the remaining kidney.", "D": "The kidney enlarges rather than staying the same size to compensate for the missing kidney."}}}, {"id": "anking-renal-embryology-726", "fuente": "anking", "tema": 60, "anki": "1475287279212", "q": "Hyperfiltration of the remaining kidney in unilateral renal agenesis increases the risk of which long-term complication?", "o": {"A": "Renal failure", "B": "Renal artery aneurysm", "C": "Nephrolithiasis exclusively", "D": "Polycystic transformation"}, "r": "A", "e": {"correcta": "Chronic hyperfiltration in the compensating solitary kidney can lead to glomerular injury and progressive renal failure later in life.", "incorrectas": {"B": "Renal artery aneurysm is not a recognized consequence of compensatory hyperfiltration.", "C": "While stones can occur, hyperfiltration's classic long-term risk is progressive renal failure, not stones specifically.", "D": "Hyperfiltration does not cause polycystic transformation of the kidney."}}}, {"id": "anking-renal-embryology-727", "fuente": "anking", "tema": 60, "anki": "1475287283862", "q": "The primary abnormality underlying Potter sequence is which condition?", "o": {"A": "Oligohydramnios", "B": "Polyhydramnios", "C": "Placenta previa", "D": "Chorioamnionitis"}, "r": "A", "e": {"correcta": "Potter sequence begins with oligohydramnios (decreased amniotic fluid), commonly due to bilateral renal agenesis or other causes of decreased fetal urine output.", "incorrectas": {"B": "Polyhydramnios is excess amniotic fluid, the opposite of the finding in Potter sequence.", "C": "Placenta previa is an obstetric complication of placental position, not the cause of Potter sequence.", "D": "Chorioamnionitis is an infection of fetal membranes, unrelated to the oligohydramnios of Potter sequence."}}}, {"id": "anking-renal-embryology-728", "fuente": "anking", "tema": 60, "anki": "1475287286742", "q": "In Potter sequence, oligohydramnios most critically leads to which pulmonary finding, the most common cause of death?", "o": {"A": "Pulmonary hypoplasia", "B": "Pulmonary fibrosis", "C": "Pulmonary hypertension only", "D": "Pneumothorax"}, "r": "A", "e": {"correcta": "Oligohydramnios prevents normal alveolar distention by aspirated amniotic fluid, causing pulmonary hypoplasia, which is the most common cause of death in Potter sequence.", "incorrectas": {"B": "Pulmonary fibrosis is a chronic scarring process, not the acute developmental defect seen in Potter sequence.", "C": "Pulmonary hypertension may occur secondarily but is not the primary described defect from lack of alveolar distention.", "D": "Pneumothorax is an acute air leak, not the developmental hypoplasia caused by oligohydramnios."}}}, {"id": "anking-renal-embryology-729", "fuente": "anking", "tema": 60, "anki": "1475287289082", "q": "In Potter sequence, oligohydramnios causes what physical effect on the developing fetus?", "o": {"A": "Compression", "B": "Excessive amniotic distention", "C": "Hydrops fetalis", "D": "Increased fetal movement"}, "r": "A", "e": {"correcta": "Reduced amniotic fluid removes the normal cushioning effect, resulting in physical compression of the fetus by the uterine wall.", "incorrectas": {"B": "Excessive distention would occur with too much fluid (polyhydramnios), not too little.", "C": "Hydrops fetalis is fetal fluid overload/edema, a distinct condition unrelated to fetal compression from oligohydramnios.", "D": "Oligohydramnios typically restricts fetal movement rather than increasing it."}}}, {"id": "anking-renal-embryology-730", "fuente": "anking", "tema": 60, "anki": "1475287300322", "q": "In Potter sequence, compression of the developing fetus from oligohydramnios results in what type of abnormality?", "o": {"A": "Limb deformities", "B": "Cardiac septal defects", "C": "Neural tube defects", "D": "Cleft palate exclusively"}, "r": "A", "e": {"correcta": "Physical compression from lack of amniotic fluid cushioning leads to characteristic limb deformities in Potter sequence.", "incorrectas": {"B": "Cardiac septal defects arise from abnormal cardiac septation, not from mechanical fetal compression.", "C": "Neural tube defects result from failed neural tube closure early in gestation, unrelated to oligohydramnios compression.", "D": "Cleft palate results from failure of palatal shelf fusion, not compression deformities."}}}, {"id": "anking-renal-embryology-731", "fuente": "anking", "tema": 60, "anki": "1475287304702", "q": "Potter sequence may cause an abnormal positioning of the mandible known as what?", "o": {"A": "Retrognathia", "B": "Prognathism", "C": "Micrognathia isolated from sequence", "D": "Macroglossia"}, "r": "A", "e": {"correcta": "Facial compression in Potter sequence can produce retrognathia, a posteriorly positioned mandible, as part of the classic 'Potter facies.'", "incorrectas": {"B": "Prognathism describes a forward-jutting jaw, the opposite of the abnormality seen in Potter sequence.", "C": "While micrognathia can be part of Potter facies, the specific term for abnormal mandibular positioning described here is retrognathia.", "D": "Macroglossia refers to an enlarged tongue, not a jaw positioning abnormality."}}}, {"id": "anking-renal-embryology-732", "fuente": "anking", "tema": 60, "anki": "1475287310437", "q": "What is the most common cause of death in infants with Potter sequence?", "o": {"A": "Pulmonary hypoplasia", "B": "Renal failure", "C": "Sepsis", "D": "Cardiac arrhythmia"}, "r": "A", "e": {"correcta": "Pulmonary hypoplasia, resulting from oligohydramnios-induced lack of alveolar distention, is the most common cause of death in Potter sequence.", "incorrectas": {"B": "While renal agenesis underlies Potter sequence, it is the pulmonary complication that is typically fatal in infancy.", "C": "Sepsis is not the characteristic or most common cause of death in this condition.", "D": "Cardiac arrhythmia is not a classic feature or leading cause of death in Potter sequence."}}}, {"id": "anking-psychiatry-pharmacology-733", "fuente": "anking", "tema": 61, "anki": "1484950427352", "q": "A patient with opioid use disorder has completed detoxification and wants a medication to help maintain abstinence. Which mu-opioid receptor antagonist is used for this purpose?", "o": {"A": "Naltrexone", "B": "Methadone", "C": "Buprenorphine", "D": "Naloxone"}, "r": "A", "e": {"correcta": "Naltrexone is a long-acting mu-opioid receptor antagonist used after detoxification to help maintain abstinence by blocking the rewarding effects of opioids.", "incorrectas": {"B": "Methadone is a full mu-opioid agonist used for maintenance therapy, not an antagonist.", "C": "Buprenorphine is a partial mu-opioid agonist used for maintenance, not a pure antagonist for relapse prevention.", "D": "Naloxone is a short-acting antagonist used for acute opioid overdose reversal, not for long-term abstinence maintenance."}}}, {"id": "anking-psychiatry-pharmacology-734", "fuente": "anking", "tema": 61, "anki": "1484950433581", "q": "Which mu-opioid receptor antagonist can help reduce cravings for alcohol and nicotine?", "o": {"A": "Naltrexone", "B": "Disulfiram", "C": "Acamprosate", "D": "Varenicline"}, "r": "A", "e": {"correcta": "Naltrexone, a mu-opioid antagonist, reduces the rewarding/euphoric effects of alcohol and nicotine, helping decrease cravings and relapse.", "incorrectas": {"B": "Disulfiram causes an aversive reaction to alcohol via aldehyde dehydrogenase inhibition but does not act on opioid receptors or reduce cravings directly.", "C": "Acamprosate modulates glutamate/GABA activity to reduce alcohol cravings but is not a mu-opioid antagonist.", "D": "Varenicline is a nicotinic receptor partial agonist used for smoking cessation, not a mu-opioid antagonist."}}}, {"id": "anking-psychiatry-pharmacology-735", "fuente": "anking", "tema": 61, "anki": "1484950440235", "q": "Besides its use in addiction, naltrexone (a mu-opioid antagonist) can also help with which of the following?", "o": {"A": "Weight loss", "B": "Weight gain", "C": "Insomnia", "D": "Hypertension"}, "r": "A", "e": {"correcta": "Naltrexone, often combined with bupropion, is used clinically to promote weight loss by modulating hypothalamic reward and appetite pathways.", "incorrectas": {"B": "Naltrexone is not associated with weight gain; several psychiatric medications (e.g., SSRIs, antipsychotics) cause weight gain instead.", "C": "Naltrexone has no established role in treating insomnia.", "D": "Naltrexone is not used as an antihypertensive agent."}}}, {"id": "anking-psychiatry-pharmacology-736", "fuente": "anking", "tema": 61, "anki": "1485037158388", "q": "SSRIs exert their therapeutic effect primarily by inhibiting the presynaptic reuptake of which neurotransmitter?", "o": {"A": "Serotonin (5-HT)", "B": "Dopamine", "C": "Norepinephrine", "D": "GABA"}, "r": "A", "e": {"correcta": "Selective serotonin reuptake inhibitors (SSRIs) block the serotonin transporter (SERT), increasing synaptic serotonin (5-HT) availability.", "incorrectas": {"B": "Dopamine reuptake is primarily blocked by drugs like bupropion, not SSRIs.", "C": "Norepinephrine reuptake inhibition is the mechanism of SNRIs and TCAs, not SSRIs specifically.", "D": "GABA reuptake/enhancement is the mechanism of benzodiazepines and barbiturates, not SSRIs."}}}, {"id": "anking-psychiatry-pharmacology-737", "fuente": "anking", "tema": 61, "anki": "1485037163106", "q": "SNRIs inhibit the presynaptic reuptake of which two neurotransmitters?", "o": {"A": "Norepinephrine and serotonin", "B": "Dopamine and serotonin", "C": "Norepinephrine and dopamine", "D": "Serotonin and GABA"}, "r": "A", "e": {"correcta": "Serotonin-norepinephrine reuptake inhibitors (SNRIs) block reuptake of both norepinephrine and serotonin, increasing their synaptic concentrations.", "incorrectas": {"B": "Dopamine reuptake inhibition is not a primary mechanism of SNRIs; this profile is closer to bupropion.", "C": "SNRIs act on serotonin, not dopamine, alongside norepinephrine.", "D": "GABA is not a target of SNRIs; that mechanism belongs to benzodiazepines and barbiturates."}}}, {"id": "anking-psychiatry-pharmacology-738", "fuente": "anking", "tema": 61, "anki": "1485037167831", "q": "What is the first-line pharmacologic treatment for major depressive disorder?", "o": {"A": "SSRIs", "B": "Benzodiazepines", "C": "Monoamine oxidase inhibitors (MAOIs)", "D": "Antipsychotics"}, "r": "A", "e": {"correcta": "SSRIs are first-line for depression due to their favorable side-effect and safety profile compared to older antidepressants.", "incorrectas": {"B": "Benzodiazepines are used for anxiety and are not indicated as first-line depression treatment.", "C": "MAOIs are effective but reserved for treatment-resistant depression due to dietary restrictions and drug interactions.", "D": "Antipsychotics may be used as adjuncts in resistant depression but are not first-line monotherapy."}}}, {"id": "anking-psychiatry-pharmacology-739", "fuente": "anking", "tema": 61, "anki": "1485037176963", "q": "What are the first-line pharmacologic treatments for generalized anxiety disorder (GAD)?", "o": {"A": "SSRIs or SNRIs", "B": "Benzodiazepines", "C": "Antipsychotics", "D": "Beta-blockers"}, "r": "A", "e": {"correcta": "SSRIs and SNRIs are first-line for GAD due to efficacy with a better long-term safety profile than benzodiazepines.", "incorrectas": {"B": "Benzodiazepines are used for short-term or acute anxiety relief but are not first-line due to dependence risk.", "C": "Antipsychotics are not standard first-line agents for GAD.", "D": "Beta-blockers help with performance-related somatic symptoms but are not first-line for GAD."}}}, {"id": "anking-psychiatry-pharmacology-740", "fuente": "anking", "tema": 61, "anki": "1485037189108", "q": "What are the first-line pharmacologic treatments for post-traumatic stress disorder (PTSD)?", "o": {"A": "SSRIs or venlafaxine", "B": "Benzodiazepines", "C": "Prazosin alone", "D": "Antipsychotics"}, "r": "A", "e": {"correcta": "SSRIs and venlafaxine (an SNRI) are first-line pharmacologic agents for PTSD.", "incorrectas": {"B": "Benzodiazepines are generally avoided in PTSD due to limited efficacy and risk of dependence.", "C": "Prazosin is used adjunctively for PTSD-related nightmares, not as first-line monotherapy.", "D": "Antipsychotics are not first-line for PTSD."}}}, {"id": "anking-psychiatry-pharmacology-741", "fuente": "anking", "tema": 61, "anki": "1485037195286", "q": "What is the first-line pharmacologic treatment for obsessive-compulsive disorder (OCD)?", "o": {"A": "SSRIs", "B": "Benzodiazepines", "C": "Clomipramine as first-line", "D": "Antipsychotics"}, "r": "A", "e": {"correcta": "SSRIs are first-line for OCD; clomipramine (a TCA) is a second-line option due to its side effect profile.", "incorrectas": {"B": "Benzodiazepines are not effective as primary treatment for OCD's core symptoms.", "C": "Clomipramine is effective but reserved as second-line therapy, not first-line.", "D": "Antipsychotics may be used as augmentation in refractory OCD but are not first-line."}}}, {"id": "anking-psychiatry-pharmacology-742", "fuente": "anking", "tema": 61, "anki": "1485037202415", "q": "What is the first-line pharmacologic treatment for bulimia nervosa?", "o": {"A": "SSRIs", "B": "Bupropion", "C": "Benzodiazepines", "D": "Antipsychotics"}, "r": "A", "e": {"correcta": "SSRIs (particularly fluoxetine at higher doses) are first-line pharmacotherapy for bulimia nervosa.", "incorrectas": {"B": "Bupropion is actually contraindicated in bulimia nervosa due to increased seizure risk.", "C": "Benzodiazepines have no established role in treating bulimia nervosa.", "D": "Antipsychotics are not indicated as first-line treatment for bulimia nervosa."}}}, {"id": "anking-psychiatry-pharmacology-743", "fuente": "anking", "tema": 61, "anki": "1485037207685", "q": "What are the first-line pharmacologic treatments for social anxiety disorder?", "o": {"A": "SSRIs or venlafaxine", "B": "Benzodiazepines", "C": "Beta-blockers", "D": "Buspirone"}, "r": "A", "e": {"correcta": "SSRIs and venlafaxine (an SNRI) are first-line agents for social anxiety disorder.", "incorrectas": {"B": "Benzodiazepines can help acutely but are not first-line due to dependence concerns.", "C": "Beta-blockers are useful for performance-type social anxiety (situational), not generalized social anxiety disorder as first-line.", "D": "Buspirone is used for GAD, not as first-line for social anxiety disorder."}}}, {"id": "anking-psychiatry-pharmacology-744", "fuente": "anking", "tema": 61, "anki": "1485037215079", "q": "SSRIs are sometimes used off-label to treat which sexual dysfunction due to their side effect of delayed ejaculation?", "o": {"A": "Premature ejaculation", "B": "Erectile dysfunction", "C": "Anorgasmia", "D": "Hypoactive sexual desire disorder"}, "r": "A", "e": {"correcta": "Because SSRIs commonly cause delayed ejaculation as a side effect, they are used off-label to treat premature ejaculation.", "incorrectas": {"B": "SSRIs do not treat erectile dysfunction; they can actually contribute to sexual dysfunction.", "C": "Anorgasmia is itself a side effect caused by SSRIs, not a condition they treat.", "D": "SSRIs typically decrease libido and are not used to treat hypoactive sexual desire disorder."}}}, {"id": "anking-psychiatry-pharmacology-745", "fuente": "anking", "tema": 61, "anki": "1485037220962", "q": "SNRIs (e.g., duloxetine) can be used to treat which diabetes-related complication?", "o": {"A": "Diabetic neuropathy", "B": "Diabetic retinopathy", "C": "Diabetic nephropathy", "D": "Diabetic ketoacidosis"}, "r": "A", "e": {"correcta": "SNRIs such as duloxetine are approved to treat diabetic peripheral neuropathy by modulating pain pathways via serotonin and norepinephrine.", "incorrectas": {"B": "Diabetic retinopathy is managed with glycemic control and ophthalmologic treatments, not SNRIs.", "C": "Diabetic nephropathy is managed with ACE inhibitors/ARBs and glycemic control, not SNRIs.", "D": "Diabetic ketoacidosis is an acute metabolic emergency treated with insulin and fluids, unrelated to SNRIs."}}}, {"id": "anking-psychiatry-pharmacology-746", "fuente": "anking", "tema": 61, "anki": "1485037225784", "q": "SNRIs may be used to treat chronic pain, particularly which type of pain described as a burning sensation?", "o": {"A": "Neuropathic pain", "B": "Nociceptive pain", "C": "Visceral pain", "D": "Somatic pain"}, "r": "A", "e": {"correcta": "SNRIs are effective for neuropathic pain, which is often described as burning, due to their modulation of descending pain pathways.", "incorrectas": {"B": "Nociceptive pain arises from tissue damage and responds better to NSAIDs/opioids rather than being the classic SNRI-treated pain type.", "C": "Visceral pain originates from internal organs and is not the classic burning pain SNRIs target.", "D": "Somatic pain is localized musculoskeletal pain, not the burning neuropathic pain SNRIs are used for."}}}, {"id": "anking-psychiatry-pharmacology-747", "fuente": "anking", "tema": 61, "anki": "1485037235169", "q": "Approximately how long do SSRIs and SNRIs take to achieve their maximum therapeutic effect?", "o": {"A": "1-2 months", "B": "1-2 days", "C": "1-2 weeks", "D": "6-12 months"}, "r": "A", "e": {"correcta": "SSRIs and SNRIs typically require about 1-2 months of continuous use to reach maximal antidepressant/anxiolytic effect.", "incorrectas": {"B": "1-2 days is far too short; these medications do not produce full effect this quickly.", "C": "1-2 weeks may show initial improvement but is before maximal effect is reached.", "D": "6-12 months is longer than typically needed to reach maximum effect, though maintenance therapy may continue for that duration."}}}, {"id": "anking-psychiatry-pharmacology-748", "fuente": "anking", "tema": 61, "anki": "1485037244915", "q": "SSRIs can cause sexual dysfunction, including decreased libido and which of the following?", "o": {"A": "Anorgasmia", "B": "Premature ejaculation", "C": "Priapism", "D": "Gynecomastia"}, "r": "A", "e": {"correcta": "SSRIs commonly cause anorgasmia (difficulty achieving orgasm) along with decreased libido, affecting up to 50% of patients and contributing to nonadherence.", "incorrectas": {"B": "SSRIs cause delayed, not premature, ejaculation.", "C": "Priapism is classically associated with trazodone, not typical SSRIs.", "D": "Gynecomastia is more associated with antipsychotics (via hyperprolactinemia), not SSRIs."}}}, {"id": "anking-psychiatry-pharmacology-749", "fuente": "anking", "tema": 61, "anki": "1485037249011", "q": "Long-term SSRI use is commonly associated with which change in body weight?", "o": {"A": "Weight gain", "B": "Weight loss", "C": "No change in appetite", "D": "Severe cachexia"}, "r": "A", "e": {"correcta": "Chronic SSRI use is commonly associated with weight gain, an important consideration in long-term treatment adherence.", "incorrectas": {"B": "Weight loss is more typical of initial SSRI use (e.g., fluoxetine) or of stimulant medications, not the common long-term pattern.", "C": "Appetite changes do occur with SSRIs, most notably contributing to weight gain over time.", "D": "Cachexia is a severe wasting syndrome unrelated to typical SSRI side effects."}}}, {"id": "anking-psychiatry-pharmacology-750", "fuente": "anking", "tema": 61, "anki": "1485037314388", "q": "Sudden discontinuation of SSRIs or SNRIs can cause symptoms resembling which illness?", "o": {"A": "Flu-like symptoms", "B": "Anaphylaxis", "C": "Serotonin syndrome", "D": "Neuroleptic malignant syndrome"}, "r": "A", "e": {"correcta": "Abrupt discontinuation of SSRIs/SNRIs can cause a discontinuation syndrome with flu-like symptoms, dizziness, and irritability due to sudden loss of serotonergic/noradrenergic tone.", "incorrectas": {"B": "Anaphylaxis is an acute allergic reaction, unrelated to antidepressant discontinuation.", "C": "Serotonin syndrome results from excess serotonergic activity (e.g., drug combinations), not discontinuation.", "D": "Neuroleptic malignant syndrome is associated with antipsychotic use, not SSRI/SNRI discontinuation."}}}, {"id": "anking-psychology-751", "fuente": "anking", "tema": 62, "anki": "1484612578871", "q": "A patient develops a fear response to the sound of a dentist's drill after repeated painful procedures, even before the drill touches them. Which type of learning does this represent?", "o": {"A": "Classical conditioning", "B": "Operant conditioning", "C": "Habituation", "D": "Observational learning"}, "r": "A", "e": {"correcta": "Classical conditioning occurs when a natural (unconditioned) response becomes elicited by a previously neutral stimulus after repeated pairing with an unconditioned stimulus, as in Pavlov's dog (bell paired with food eliciting salivation).", "incorrectas": {"B": "Operant conditioning involves voluntary behaviors that are shaped by rewards or punishments, not an involuntary reflexive response to a paired stimulus.", "C": "Habituation is a decrease in response to a repeated, non-reinforced stimulus, not the acquisition of a new conditioned response.", "D": "Observational learning involves acquiring behavior by watching others, not through stimulus pairing."}}}, {"id": "anking-psychology-752", "fuente": "anking", "tema": 62, "anki": "1484617682911", "q": "Which type of conditioning usually deals with involuntary, reflexive responses?", "o": {"A": "Classical conditioning", "B": "Operant conditioning", "C": "Extinction learning", "D": "Latent learning"}, "r": "A", "e": {"correcta": "Classical conditioning pairs a neutral stimulus with an unconditioned stimulus to elicit an involuntary, reflexive response (e.g., salivation, fear responses).", "incorrectas": {"B": "Operant conditioning shapes voluntary behaviors through reinforcement or punishment, not involuntary reflexes.", "C": "Extinction is the loss of a learned response, not a type of conditioning dealing with reflexes.", "D": "Latent learning refers to learning that occurs without reinforcement and is not demonstrated until needed; it is unrelated to involuntary reflexes."}}}, {"id": "anking-psychology-753", "fuente": "anking", "tema": 62, "anki": "1484617708408", "q": "A rat presses a lever to receive a food pellet, and learns to press it more often over time. This describes which type of conditioning?", "o": {"A": "Operant conditioning", "B": "Classical conditioning", "C": "Habituation", "D": "Sensitization"}, "r": "A", "e": {"correcta": "Operant conditioning occurs when a voluntary action (lever pressing) is elicited or modified because it produces a reward or punishment (food pellet).", "incorrectas": {"B": "Classical conditioning involves pairing stimuli to produce an involuntary reflexive response, not a voluntary action driven by consequences.", "C": "Habituation is a decreased response to a repeated stimulus, not learning driven by reward.", "D": "Sensitization is an increased response to repeated stimulation, not behavior shaped by reward or punishment."}}}, {"id": "anking-psychology-754", "fuente": "anking", "tema": 62, "anki": "1484617710985", "q": "Which type of conditioning usually deals with voluntary responses?", "o": {"A": "Operant conditioning", "B": "Classical conditioning", "C": "Habituation", "D": "Imprinting"}, "r": "A", "e": {"correcta": "Operant conditioning shapes voluntary behaviors through the consequences (reinforcement or punishment) that follow them.", "incorrectas": {"B": "Classical conditioning deals with involuntary, reflexive responses elicited by paired stimuli.", "C": "Habituation is a decrease in an involuntary response to a repeated stimulus.", "D": "Imprinting is a critical-period developmental process in young animals, not a voluntary learned behavior."}}}, {"id": "anking-psychology-755", "fuente": "anking", "tema": 62, "anki": "1484617713237", "q": "A child receives a sticker every time she completes her homework, increasing the frequency of the behavior. Which operant conditioning technique does this represent?", "o": {"A": "Positive reinforcement", "B": "Negative reinforcement", "C": "Positive punishment", "D": "Negative punishment"}, "r": "A", "e": {"correcta": "Positive reinforcement involves adding a desirable stimulus (the sticker) following a behavior to increase the frequency of that behavior.", "incorrectas": {"B": "Negative reinforcement increases behavior by removing an aversive stimulus, not by adding a reward.", "C": "Positive punishment adds an aversive stimulus to decrease behavior, the opposite goal here.", "D": "Negative punishment removes a desired stimulus to decrease behavior, not increase it."}}}, {"id": "anking-psychology-756", "fuente": "anking", "tema": 62, "anki": "1484617722314", "q": "A driver fastens their seatbelt to stop an annoying chime from sounding, making them more likely to buckle up in the future. Which operant conditioning technique does this represent?", "o": {"A": "Negative reinforcement", "B": "Positive reinforcement", "C": "Positive punishment", "D": "Negative punishment"}, "r": "A", "e": {"correcta": "Negative reinforcement increases a behavior by removing an aversive stimulus (the chime) following that behavior.", "incorrectas": {"B": "Positive reinforcement increases behavior by adding a desirable stimulus, not by removing an aversive one.", "C": "Positive punishment adds an aversive stimulus to decrease behavior, the opposite effect described.", "D": "Negative punishment removes a desirable stimulus to decrease behavior, not increase it."}}}, {"id": "anking-psychology-757", "fuente": "anking", "tema": 62, "anki": "1484617729171", "q": "A child is repeatedly scolded whenever they interrupt a conversation, and gradually stops interrupting. Which operant conditioning technique does this represent?", "o": {"A": "Positive punishment", "B": "Negative punishment", "C": "Positive reinforcement", "D": "Negative reinforcement"}, "r": "A", "e": {"correcta": "Positive punishment involves the repeated addition of an aversive stimulus (scolding) following a behavior in order to decrease that behavior.", "incorrectas": {"B": "Negative punishment decreases behavior by removing a desired reward, not by adding an aversive stimulus.", "C": "Positive reinforcement adds a stimulus to increase behavior, not decrease it.", "D": "Negative reinforcement removes an aversive stimulus to increase behavior, not decrease it."}}}, {"id": "anking-psychology-758", "fuente": "anking", "tema": 62, "anki": "1484617758232", "q": "A teenager loses phone privileges after breaking curfew, and subsequently stops breaking curfew. Which operant conditioning technique does this represent?", "o": {"A": "Negative punishment", "B": "Positive punishment", "C": "Positive reinforcement", "D": "Negative reinforcement"}, "r": "A", "e": {"correcta": "Negative punishment involves removing a desired reward (phone privileges) following a behavior in order to decrease that behavior.", "incorrectas": {"B": "Positive punishment decreases behavior by adding an aversive stimulus, not removing a reward.", "C": "Positive reinforcement adds a stimulus to increase behavior, the opposite of what is described.", "D": "Negative reinforcement removes an aversive stimulus to increase behavior, not decrease it."}}}, {"id": "anking-psychology-759", "fuente": "anking", "tema": 62, "anki": "1484617765533", "q": "A behavior that was previously reinforced gradually disappears once reinforcement is discontinued. What is this phenomenon called?", "o": {"A": "Extinction", "B": "Habituation", "C": "Fixation", "D": "Displacement"}, "r": "A", "e": {"correcta": "Extinction is the idea that discontinuation of reinforcement (positive or negative) eventually eliminates a behavior; it can occur in both operant and classical conditioning.", "incorrectas": {"B": "Habituation is a decreased response to a repeated, non-reinforced stimulus rather than the loss of a reinforced behavior.", "C": "Fixation is an ego defense mechanism describing a partial arrest at a childish developmental level, unrelated to loss of reinforcement.", "D": "Displacement is an ego defense mechanism involving redirection of emotion to a neutral target, unrelated to extinction of behavior."}}}, {"id": "anking-psychology-760", "fuente": "anking", "tema": 62, "anki": "1484617849923", "q": "A patient begins treating her psychiatrist as though he were her critical father, projecting feelings from that relationship onto him. What is this phenomenon called?", "o": {"A": "Transference", "B": "Countertransference", "C": "Displacement", "D": "Projection"}, "r": "A", "e": {"correcta": "Transference occurs when a patient projects feelings about formative or other important persons in their life onto the physician, such as viewing the psychiatrist as a parent figure.", "incorrectas": {"B": "Countertransference is the reverse phenomenon, in which the doctor projects feelings about important persons onto the patient.", "C": "Displacement is an ego defense in which emotions are redirected onto a neutral third party, not specifically the projection of relationship-based feelings onto a caregiver in therapy.", "D": "Projection is a defense mechanism where one's own unacceptable feelings are attributed to another person, distinct from the therapeutic relationship dynamic of transference."}}}, {"id": "anking-psychology-761", "fuente": "anking", "tema": 62, "anki": "1484617866893", "q": "A physician finds himself becoming unusually protective of a patient because she reminds him of his younger sister. What is this phenomenon called?", "o": {"A": "Countertransference", "B": "Transference", "C": "Projection", "D": "Identification"}, "r": "A", "e": {"correcta": "Countertransference occurs when the doctor projects feelings about formative or other important persons onto the patient, such as the physician's reaction being colored by resemblance to his sister.", "incorrectas": {"B": "Transference is the reverse phenomenon, in which the patient projects feelings about important persons onto the physician.", "C": "Projection is a defense mechanism involving attributing one's own unacceptable feelings to another person, not the physician's emotional reaction rooted in a real relationship.", "D": "Identification is a defense mechanism where one models behavior after a person perceived as more powerful, distinct from countertransference."}}}, {"id": "anking-psychology-762", "fuente": "anking", "tema": 62, "anki": "1484617875332", "q": "What term describes the unconscious or conscious mental processes used to resolve conflict and prevent undesirable feelings such as anxiety or depression?", "o": {"A": "Ego defenses", "B": "Cognitive distortions", "C": "Transference reactions", "D": "Superego constraints"}, "r": "A", "e": {"correcta": "Ego defenses are unconscious or conscious mechanisms used to resolve psychological conflict and prevent undesirable feelings like anxiety or depression.", "incorrectas": {"B": "Cognitive distortions are irrational thought patterns seen in conditions like depression, not the broader category of conflict-resolving mental mechanisms.", "C": "Transference reactions refer specifically to projecting feelings about important persons onto a physician, a narrower and distinct concept.", "D": "Superego constraints refer to the internalized moral standards of the psyche, not the mechanisms used to manage conflict and distressing feelings."}}}, {"id": "anking-psychology-763", "fuente": "anking", "tema": 62, "anki": "1484617894077", "q": "An adolescent whose parents are going through a divorce begins engaging in promiscuous sexual behavior instead of verbalizing his distress. Which immature ego defense does this represent?", "o": {"A": "Acting out", "B": "Denial", "C": "Displacement", "D": "Dissociation"}, "r": "A", "e": {"correcta": "Acting out is the expression of unacceptable feelings and thoughts through actions, including attention-seeking or socially inappropriate behavior, as seen in this adolescent's response to family stress.", "incorrectas": {"B": "Denial involves refusing to accept an unpleasant reality, not expressing distress through behavior.", "C": "Displacement involves redirecting emotion toward a neutral person or object, not acting out through impulsive behavior.", "D": "Dissociation involves a drastic, temporary change in memory or consciousness to avoid emotional stress, not acting on impulses."}}}, {"id": "anking-psychology-764", "fuente": "anking", "tema": 62, "anki": "1484617900184", "q": "A patient with metastatic cancer schedules a full-time work commitment despite being warned about fatigue from chemotherapy. Which immature ego defense does this illustrate?", "o": {"A": "Denial", "B": "Acting out", "C": "Displacement", "D": "Fixation"}, "r": "A", "e": {"correcta": "Denial is avoiding awareness of a painful reality, such as a cancer patient ignoring warnings about fatigue and planning as though nothing is wrong.", "incorrectas": {"B": "Acting out involves expressing distress through impulsive or inappropriate actions, not simply refusing to acknowledge a diagnosis.", "C": "Displacement involves redirecting emotions toward a neutral target, not ignoring a medical reality.", "D": "Fixation involves remaining at an earlier developmental stage, not refusing to accept an unpleasant truth."}}}, {"id": "anking-psychology-765", "fuente": "anking", "tema": 62, "anki": "1484617907923", "q": "A teacher who is reprimanded by her principal goes home and unfairly criticizes her husband's cooking instead of confronting the principal. Which immature ego defense does this represent?", "o": {"A": "Displacement", "B": "Acting out", "C": "Denial", "D": "Idealization"}, "r": "A", "e": {"correcta": "Displacement is the redirection of emotions or impulses from their original source to a neutral person or object, as the teacher redirects her anger at the principal onto her husband.", "incorrectas": {"B": "Acting out involves expressing unacceptable feelings through impulsive behavior rather than redirecting emotion onto an unrelated person.", "C": "Denial involves refusing to accept an unpleasant reality, not redirecting emotion to another target.", "D": "Idealization involves viewing someone in an excessively positive light, unrelated to redirecting anger."}}}, {"id": "anking-psychology-766", "fuente": "anking", "tema": 62, "anki": "1484617930331", "q": "After being raped, a woman suddenly appears numb, detached, and has incomplete memory of the event when confronted with her abuser. Which immature ego defense does this represent?", "o": {"A": "Dissociation", "B": "Denial", "C": "Fixation", "D": "Displacement"}, "r": "A", "e": {"correcta": "Dissociation is a temporary, drastic change in personality, memory, consciousness, or motor behavior to avoid emotional stress, often with sudden onset after a traumatic triggering event and incomplete memory of the trauma.", "incorrectas": {"B": "Denial involves refusing to accept a painful reality but does not typically involve detachment and memory loss surrounding a traumatic event.", "C": "Fixation involves remaining at a childish developmental level, not a sudden detachment from reality after trauma.", "D": "Displacement involves redirecting emotion to a neutral target, not memory loss and detachment following trauma."}}}, {"id": "anking-psychology-767", "fuente": "anking", "tema": 62, "anki": "1484617937400", "q": "A surgeon throws a tantrum in the operating room when a case runs late. Which immature ego defense does this best illustrate?", "o": {"A": "Fixation", "B": "Regression", "C": "Displacement", "D": "Acting out"}, "r": "A", "e": {"correcta": "Fixation is partially remaining at a more childish level of development, illustrated by the surgeon's tantrum, a behavior more typical of early childhood.", "incorrectas": {"B": "Regression is an involuntary turning back to an earlier mode of dealing with the world under stress, which is distinct from fixation (a persistent partial arrest at an earlier stage) though related; per the source material fixation is the defense being tested here.", "C": "Displacement involves redirecting emotion onto a neutral person or object, not reverting to childish behavior itself.", "D": "Acting out involves expressing distress through impulsive or inappropriate actions generally, but the tantrum specifically illustrates a childish developmental level (fixation) as described in the source."}}}, {"id": "anking-psychology-768", "fuente": "anking", "tema": 62, "anki": "1484617942965", "q": "A patient boasts extensively about his physician's accomplishments while ignoring any of the physician's flaws. Which immature ego defense does this represent?", "o": {"A": "Idealization", "B": "Transference", "C": "Denial", "D": "Acting out"}, "r": "A", "e": {"correcta": "Idealization involves expressing extremely positive thoughts about oneself or others while ignoring negative aspects, as when the patient exaggerates his physician's virtues while disregarding flaws.", "incorrectas": {"B": "Transference involves projecting feelings about important persons onto the physician, not selectively emphasizing only positive traits.", "C": "Denial involves refusing to accept an unpleasant reality, not exaggerating positive qualities while ignoring negatives.", "D": "Acting out involves expressing distress through impulsive behavior, not a cognitive distortion of overly positive perception."}}}, {"id": "anking-healthcare-delivery-769", "fuente": "anking", "tema": 63, "anki": "1489891799832", "q": "Vaccination and health promotion programs (e.g., immunizations, smoking cessation counseling) are examples of which level of disease prevention?", "o": {"A": "Primary prevention", "B": "Secondary prevention", "C": "Tertiary prevention", "D": "Quaternary prevention"}, "r": "A", "e": {"correcta": "Primary prevention aims to prevent disease before it ever occurs, through measures like vaccination, health promotion, and risk factor reduction.", "incorrectas": {"B": "Secondary prevention involves screening to detect existing but asymptomatic disease early, not preventing disease onset.", "C": "Tertiary prevention reduces complications and disability from disease that has already caused long-term effects.", "D": "Quaternary prevention identifies patients at risk for unnecessary or harmful medical intervention, not preventing initial disease onset."}}}, {"id": "anking-healthcare-delivery-770", "fuente": "anking", "tema": 63, "anki": "1489891883933", "q": "Screening an individual or community for a disease (e.g., mammography, colonoscopy) represents which level of disease prevention?", "o": {"A": "Primary prevention", "B": "Secondary prevention", "C": "Tertiary prevention", "D": "Quaternary prevention"}, "r": "B", "e": {"correcta": "Secondary prevention involves screening to detect and manage disease that is already present but still asymptomatic, allowing earlier intervention.", "incorrectas": {"A": "Primary prevention acts before disease occurs at all, such as through vaccination.", "C": "Tertiary prevention addresses established, often symptomatic disease to limit further complications.", "D": "Quaternary prevention focuses on avoiding unnecessary or excessive medical care, not on early detection of disease."}}}, {"id": "anking-healthcare-delivery-771", "fuente": "anking", "tema": 63, "anki": "1489891925289", "q": "Chemotherapy for cancer, tight glucose/blood pressure control in diabetes, and physical therapy after a stroke are all examples of which type of disease prevention?", "o": {"A": "Primary prevention", "B": "Secondary prevention", "C": "Tertiary prevention", "D": "Quaternary prevention"}, "r": "C", "e": {"correcta": "Tertiary prevention involves treatment aimed at reducing complications and disability from disease that already has long-term effects, such as rehabilitation or disability limitation.", "incorrectas": {"A": "Primary prevention occurs before disease develops, unlike these interventions in patients with established disease.", "B": "Secondary prevention is about early detection of asymptomatic disease, not managing established complications.", "D": "Quaternary prevention is about avoiding unnecessary interventions, not treating existing disease complications."}}}, {"id": "anking-healthcare-delivery-772", "fuente": "anking", "tema": 63, "anki": "1489891980364", "q": "Electronic sharing of patient records to avoid duplicating recent laboratory and imaging studies is an example of which type of disease prevention?", "o": {"A": "Primary prevention", "B": "Secondary prevention", "C": "Tertiary prevention", "D": "Quaternary prevention"}, "r": "D", "e": {"correcta": "Quaternary prevention identifies patients at risk of unnecessary or excessive medical treatment and seeks to protect them from overmedicalization and iatrogenic harm.", "incorrectas": {"A": "Primary prevention is about preventing disease before it occurs, not avoiding unnecessary testing.", "B": "Secondary prevention involves screening for existing asymptomatic disease.", "C": "Tertiary prevention involves reducing complications of established disease."}}}, {"id": "anking-healthcare-delivery-773", "fuente": "anking", "tema": 63, "anki": "1489977208568", "q": "Which major medical insurance plan type generally has the cheapest monthly premiums and lowest copays/deductibles by restricting patients to a limited panel of providers and requiring PCP referrals?", "o": {"A": "Health maintenance organization (HMO)", "B": "Preferred provider organization (PPO)", "C": "Point of service (POS) plan", "D": "Exclusive provider organization (EPO)"}, "r": "A", "e": {"correcta": "HMO plans achieve the lowest premiums and out-of-pocket costs by confining patients to a limited provider panel, requiring PCP referrals for specialists, and denying payment for services that don't meet evidence-based guidelines.", "incorrectas": {"B": "PPO plans offer the most flexibility (in- and out-of-network) but at the cost of the highest premiums and deductibles.", "C": "POS plans allow some out-of-network care and thus have higher premiums than HMOs.", "D": "EPO plans also restrict to a network but do not require referrals, and are not characterized as the cheapest option."}}}, {"id": "anking-healthcare-delivery-774", "fuente": "anking", "tema": 63, "anki": "1489980815408", "q": "Can patients enrolled in a health maintenance organization (HMO) insurance plan see providers outside of their designated network (except in emergencies)?", "o": {"A": "Yes, with no additional cost", "B": "Yes, but at a higher out-of-pocket cost", "C": "No", "D": "Only with prior authorization from the insurer, at the same cost as in-network"}, "r": "C", "e": {"correcta": "HMO plans restrict patients to a limited panel of in-network providers and generally do not cover out-of-network care except in emergencies.", "incorrectas": {"A": "HMOs do not allow out-of-network care at all under normal circumstances, so there is no such option at no additional cost.", "B": "This describes POS or PPO plans, which do allow out-of-network visits at a higher cost, unlike HMOs.", "D": "HMOs do not generally permit out-of-network visits regardless of authorization, and would not match in-network cost even if allowed."}}}, {"id": "anking-healthcare-delivery-775", "fuente": "anking", "tema": 63, "anki": "1489980821094", "q": "Do patients with a health maintenance organization (HMO) insurance plan need a referral from their primary care provider (PCP) before seeing a specialist?", "o": {"A": "Yes", "B": "No", "C": "Only for out-of-network specialists", "D": "Only if the plan has a high deductible"}, "r": "A", "e": {"correcta": "HMO plans require patients to obtain a referral from their PCP before consulting a specialist, as part of controlling utilization of services.", "incorrectas": {"B": "This describes PPO or EPO plans, which do not require PCP referrals.", "C": "HMOs generally do not cover out-of-network specialists at all, referral or not.", "D": "The referral requirement is a feature of the HMO plan type itself, not dependent on deductible level."}}}, {"id": "anking-healthcare-delivery-776", "fuente": "anking", "tema": 63, "anki": "1489980825129", "q": "Which major medical insurance plan type is known for denying payment for services that do not meet established evidence-based guidelines?", "o": {"A": "Health maintenance organization (HMO)", "B": "Preferred provider organization (PPO)", "C": "Point of service (POS) plan", "D": "Exclusive provider organization (EPO)"}, "r": "A", "e": {"correcta": "HMO plans control costs in part by denying payment for services that don't meet established evidence-based guidelines, in addition to restricting provider panels and requiring referrals.", "incorrectas": {"B": "PPOs are known for flexibility and high costs, not strict evidence-based utilization review of this kind.", "C": "POS plans are a hybrid of HMO and PPO features but this strict denial policy is characteristic of HMOs.", "D": "EPOs restrict networks but this specific utilization-limiting feature is attributed to HMOs."}}}, {"id": "anking-healthcare-delivery-777", "fuente": "anking", "tema": 63, "anki": "1489980967266", "q": "Can patients with a point of service (POS) insurance plan see providers outside of their network?", "o": {"A": "No, never", "B": "Yes, but with higher out-of-pocket costs", "C": "Yes, at the same cost as in-network care", "D": "Only in emergencies"}, "r": "B", "e": {"correcta": "POS plans are similar to HMOs but, unlike HMOs, allow patients to see out-of-network providers, though at a higher out-of-pocket cost.", "incorrectas": {"A": "This describes HMO plans, not POS plans, which do allow out-of-network care.", "C": "Out-of-network care under a POS plan comes with higher costs, not equal cost to in-network care.", "D": "POS plans allow out-of-network care beyond just emergencies, unlike HMOs."}}}, {"id": "anking-healthcare-delivery-778", "fuente": "anking", "tema": 63, "anki": "1489980974618", "q": "Do patients with a point of service (POS) insurance plan require a PCP referral before seeing a specialist?", "o": {"A": "Yes", "B": "No", "C": "Only for out-of-network specialists", "D": "Only for pediatric specialists"}, "r": "A", "e": {"correcta": "POS plans, like HMOs, require patients to obtain a referral from their PCP before seeing a specialist.", "incorrectas": {"B": "This describes PPO or EPO plans, which do not require referrals.", "C": "The referral requirement in POS plans applies generally, not only to out-of-network specialists.", "D": "The referral requirement is not limited to pediatric specialists in POS plans."}}}, {"id": "anking-healthcare-delivery-779", "fuente": "anking", "tema": 63, "anki": "1489980980429", "q": "Compared to health maintenance organization (HMO) plans, point of service (POS) insurance plans generally have what kind of monthly premiums?", "o": {"A": "Less expensive", "B": "More expensive", "C": "Identical", "D": "Premiums are not applicable to POS plans"}, "r": "B", "e": {"correcta": "Because POS plans allow some out-of-network flexibility (unlike HMOs), they come with more expensive monthly premiums than HMO plans.", "incorrectas": {"A": "HMO plans, not POS plans, have the cheapest premiums due to their restrictive network requirements.", "C": "POS premiums are higher than HMO premiums, not the same, reflecting the added flexibility of POS plans.", "D": "POS plans do have monthly premiums, like all major insurance plan types."}}}, {"id": "anking-healthcare-delivery-780", "fuente": "anking", "tema": 63, "anki": "1489980984929", "q": "Which major medical insurance plan type has the most expensive monthly premiums and copays/deductibles, in exchange for the most flexible choice of in-network and out-of-network providers?", "o": {"A": "Health maintenance organization (HMO)", "B": "Preferred provider organization (PPO)", "C": "Exclusive provider organization (EPO)", "D": "Point of service (POS) plan"}, "r": "B", "e": {"correcta": "PPO plans offer the greatest flexibility, allowing both in-network and out-of-network care without referrals, but this comes at the cost of the highest premiums and deductibles.", "incorrectas": {"A": "HMO plans have the cheapest premiums due to restricted provider choice, the opposite of PPO.", "C": "EPO plans restrict patients to a network (like HMOs) and are not the most expensive or most flexible option.", "D": "POS plans allow some out-of-network care but are less flexible and generally cheaper than PPOs."}}}, {"id": "anking-healthcare-delivery-781", "fuente": "anking", "tema": 63, "anki": "1489980988754", "q": "Can patients with a preferred provider organization (PPO) insurance plan see providers outside of their network?", "o": {"A": "No", "B": "Yes, but only in emergencies", "C": "Yes, though with higher copays and deductibles", "D": "Yes, at the same cost as in-network providers"}, "r": "C", "e": {"correcta": "PPO plans allow patients to see providers outside their network, though all services carry higher copays and deductibles compared to in-network care.", "incorrectas": {"A": "This describes HMO plans; PPOs specifically allow out-of-network access.", "B": "PPOs allow out-of-network access generally, not just for emergencies, unlike HMOs.", "D": "Out-of-network care under a PPO plan costs more, not the same as in-network care."}}}, {"id": "anking-healthcare-delivery-782", "fuente": "anking", "tema": 63, "anki": "1489980995156", "q": "Do patients with a preferred provider organization (PPO) insurance plan need a referral from their PCP to see a specialist?", "o": {"A": "Yes", "B": "No", "C": "Only for out-of-network specialists", "D": "Only if under a capitation payment model"}, "r": "B", "e": {"correcta": "PPO plans do not require patients to obtain a referral from a primary care provider before consulting a specialist, reflecting their overall flexibility.", "incorrectas": {"A": "This requirement is characteristic of HMO and POS plans, not PPOs.", "C": "PPOs do not require referrals for either in-network or out-of-network specialists.", "D": "The referral requirement relates to the insurance plan type, not the payment model used to reimburse physicians."}}}, {"id": "anking-healthcare-delivery-783", "fuente": "anking", "tema": 63, "anki": "1489980999119", "q": "Which insurance plan type limits patients to a specific network of doctors, specialists, and hospitals, but does not require referrals for specialist visits?", "o": {"A": "Health maintenance organization (HMO)", "B": "Preferred provider organization (PPO)", "C": "Exclusive provider organization (EPO)", "D": "Point of service (POS) plan"}, "r": "C", "e": {"correcta": "An exclusive provider organization (EPO) combines the limited network feature of an HMO with the no-referral-needed feature of a PPO.", "incorrectas": {"A": "HMO plans restrict patients to a network but also require PCP referrals for specialists, unlike EPO.", "B": "PPO plans do not require referrals but also allow out-of-network care, unlike the network restriction of EPO.", "D": "POS plans restrict networks somewhat but do require PCP referrals, unlike EPO."}}}, {"id": "anking-healthcare-delivery-784", "fuente": "anking", "tema": 63, "anki": "1489981005316", "q": "Do patients with an exclusive provider organization (EPO) insurance plan require a PCP referral before seeing a specialist?", "o": {"A": "Yes", "B": "No", "C": "Only for out-of-network specialists", "D": "Only for surgical specialists"}, "r": "B", "e": {"correcta": "EPO plans do not require a referral from a primary care provider to see a specialist, combining network restriction (like an HMO) with referral-free access (like a PPO).", "incorrectas": {"A": "This requirement applies to HMO and POS plans, not EPO plans.", "C": "EPO plans generally do not cover out-of-network specialists at all, and no referral is required for in-network ones.", "D": "There is no distinction based on specialty type for referral requirements in EPO plans."}}}, {"id": "anking-healthcare-delivery-785", "fuente": "anking", "tema": 63, "anki": "1489981009210", "q": "Which healthcare payment model pays physicians a fixed, set amount per patient assigned to them over a given period, regardless of how much care that patient actually uses?", "o": {"A": "Capitation", "B": "Fee-for-service", "C": "Discounted fee-for-service", "D": "Pay-for-performance"}, "r": "A", "e": {"correcta": "Capitation pays providers a set amount per assigned patient per time period, independent of the volume or intensity of services the patient actually uses.", "incorrectas": {"B": "Fee-for-service pays providers based on each individual service rendered, the opposite of a fixed per-patient payment.", "C": "Discounted fee-for-service still pays per individual service, just at a pre-negotiated discounted rate, not a fixed per-patient amount.", "D": "Pay-for-performance ties reimbursement to quality or outcome metrics, not a fixed capitated payment per patient."}}}, {"id": "anking-healthcare-delivery-786", "fuente": "anking", "tema": 63, "anki": "1489981016891", "q": "Which healthcare payment model has patients (or insurers) pay for each individual service rendered, but at a pre-determined, discounted rate agreed upon by providers and payers (e.g., PPOs)?", "o": {"A": "Capitation", "B": "Discounted fee-for-service", "C": "Global budget", "D": "Bundled payment"}, "r": "B", "e": {"correcta": "Discounted fee-for-service involves payment for each individual service at a pre-determined discounted rate negotiated between providers and payers, as is common in PPO arrangements.", "incorrectas": {"A": "Capitation pays a fixed amount per patient regardless of services used, not per individual service.", "C": "A global budget allocates a fixed total budget to a healthcare system or facility rather than paying per discounted service.", "D": "Bundled payment reimburses a single fixed amount for an entire episode of care, not a discounted per-service rate."}}}, {"id": "anking-quality-safety-787", "fuente": "anking", "tema": 64, "anki": "1489981092201", "q": "Which type of medical error analysis is retrospective, performed after a failure has occurred, to identify underlying causes and prevent recurrence?", "o": {"A": "Root cause analysis", "B": "Failure mode and effects analysis", "C": "Six Sigma analysis", "D": "SWOT analysis"}, "r": "A", "e": {"correcta": "Root cause analysis is a retrospective, systems-based method used after an adverse event to identify all underlying problems (using records and participant interviews) that contributed to the error, in order to prevent it from recurring.", "incorrectas": {"B": "Failure mode and effects analysis is a proactive, forward-looking method used before failures occur, not a retrospective one.", "C": "Six Sigma is a general process-improvement methodology aimed at reducing variability and defects, not specifically a retrospective post-error analysis tool.", "D": "SWOT analysis is a strategic planning tool evaluating strengths, weaknesses, opportunities, and threats, not a medical error investigation method."}}}, {"id": "anking-quality-safety-788", "fuente": "anking", "tema": 64, "anki": "1489981095674", "q": "Which type of medical error analysis is a forward-looking, proactive approach used to anticipate and prevent failures before they occur?", "o": {"A": "Root cause analysis", "B": "Failure mode and effects analysis", "C": "Morbidity and mortality conference", "D": "Sentinel event review"}, "r": "B", "e": {"correcta": "Failure mode and effects analysis uses inductive reasoning to proactively identify all the ways a process might fail, allowing preventive measures to be implemented before an error actually occurs.", "incorrectas": {"A": "Root cause analysis is retrospective, applied after a failure has already occurred, not before.", "C": "A morbidity and mortality conference reviews cases retrospectively after an adverse outcome, not proactively.", "D": "Sentinel event review is a retrospective investigation triggered by an unexpected serious adverse outcome, not a preventive forward-looking tool."}}}, {"id": "anking-quality-safety-789", "fuente": "anking", "tema": 64, "anki": "1521934502037", "q": "What term describes injury to a patient resulting from failure to follow evidence-based best practice guidelines?", "o": {"A": "Preventable adverse event", "B": "Non-preventable adverse event", "C": "Near miss", "D": "Sentinel event"}, "r": "A", "e": {"correcta": "A preventable adverse event is harm to the patient caused by an act of commission or omission (such as failing to follow evidence-based guidelines) rather than by the underlying disease itself, meaning it could have been avoided.", "incorrectas": {"B": "A non-preventable adverse event is a complication that cannot be avoided given current medical knowledge, unrelated to guideline non-adherence.", "C": "A near miss is an error that is caught before it reaches or harms the patient, so no injury occurs.", "D": "A sentinel event is an unexpected occurrence causing death or serious injury requiring immediate investigation, a broader/different category than guideline non-adherence specifically."}}}, {"id": "anking-quality-safety-790", "fuente": "anking", "tema": 64, "anki": "1521934560789", "q": "What term describes an unexpected occurrence involving death or serious physical or psychological injury that requires immediate investigation?", "o": {"A": "Near miss", "B": "Sentinel event", "C": "Preventable adverse event", "D": "Non-preventable adverse event"}, "r": "B", "e": {"correcta": "A sentinel event is an unexpected occurrence involving death or serious physical or psychological injury (or risk thereof), which signals the need for immediate investigation and response.", "incorrectas": {"A": "A near miss is caught before causing any harm, so it does not involve death or serious injury.", "C": "A preventable adverse event refers broadly to harm from failure to follow best practices, not specifically an event demanding immediate investigation by definition.", "D": "A non-preventable adverse event is a complication unavoidable given current knowledge, not defined by requiring immediate investigation."}}}, {"id": "anking-quality-safety-791", "fuente": "anking", "tema": 64, "anki": "1521934590474", "q": "What term describes a complication that cannot be prevented given the current state of medical knowledge?", "o": {"A": "Preventable adverse event", "B": "Sentinel event", "C": "Non-preventable adverse event", "D": "Near miss"}, "r": "C", "e": {"correcta": "A non-preventable adverse event is a complication that occurs despite appropriate care, because it cannot be avoided given the current state of medical knowledge and practice.", "incorrectas": {"A": "A preventable adverse event results from failure to follow evidence-based guidelines and could have been avoided, unlike a non-preventable one.", "B": "A sentinel event is defined by its severity (death or serious injury) and need for investigation, not by whether it was avoidable.", "D": "A near miss is an error caught before it causes any harm, not a complication that actually occurred."}}}, {"id": "anking-quality-safety-792", "fuente": "anking", "tema": 64, "anki": "1521934618229", "q": "What term describes a medical error that is recognized and corrected before it causes harm to the patient?", "o": {"A": "Sentinel event", "B": "Near miss", "C": "Preventable adverse event", "D": "Idiosyncratic drug reaction"}, "r": "B", "e": {"correcta": "A near miss is a medical error that is caught before any harm occurs, such as a lethal medication dose being intercepted by a pharmacist prior to administration.", "incorrectas": {"A": "A sentinel event by definition involves actual death or serious injury, not an error that was caught in time.", "C": "A preventable adverse event involves actual harm to the patient, unlike a near miss where no harm occurs.", "D": "An idiosyncratic drug reaction is an unpredictable adverse drug effect due to genetic variation, unrelated to catching an error before harm."}}}, {"id": "anking-quality-safety-793", "fuente": "anking", "tema": 64, "anki": "1521934746044", "q": "Most adverse drug reactions fall into which category, being due to the known pharmacologic properties of the drug?", "o": {"A": "Idiosyncratic", "B": "Immunologic", "C": "Predictable", "D": "Exaggerated drug sensitivity"}, "r": "C", "e": {"correcta": "Most adverse drug reactions are predictable, arising from the known pharmacologic properties of the drug, such as an NSAID causing an upper GI hemorrhage.", "incorrectas": {"A": "Idiosyncratic reactions are unpredictable, occurring due to genetic differences or complex metabolic interactions, and are less common.", "B": "Immunologic reactions are unpredictable anamnestic immune responses, not the most common category of adverse drug reactions.", "D": "Exaggerated drug sensitivity refers to known pharmacologic effects occurring at unexpectedly low doses, a distinct and less common category."}}}, {"id": "anking-quality-safety-794", "fuente": "anking", "tema": 64, "anki": "1521934883002", "q": "What term describes an adverse drug reaction that occurs due to the known pharmacologic action of a drug but at a lower dose than expected?", "o": {"A": "Idiosyncratic drug reaction", "B": "Exaggerated drug sensitivity", "C": "Immunologic drug reaction", "D": "Predictable drug reaction"}, "r": "B", "e": {"correcta": "Exaggerated drug sensitivity occurs when a drug produces its known pharmacologic effect at a lower dose than expected, often due to altered metabolism or end-organ susceptibility, as with tinnitus after a single dose of aspirin.", "incorrectas": {"A": "An idiosyncratic drug reaction is unpredictable and due to genetic differences, not simply a known effect occurring at lower dose.", "C": "Immunologic drug reactions are unpredictable immune-mediated responses, not dose-related exaggerations of known pharmacologic effects.", "D": "Predictable drug reactions occur at expected doses due to known pharmacology, whereas exaggerated sensitivity occurs at lower-than-expected doses."}}}, {"id": "anking-quality-safety-795", "fuente": "anking", "tema": 64, "anki": "1521934935201", "q": "What term describes an unpredictable drug reaction due to genetic differences or complex metabolic interactions in certain patients?", "o": {"A": "Predictable drug reaction", "B": "Exaggerated drug sensitivity", "C": "Idiosyncratic drug reaction", "D": "Immunologic drug reaction"}, "r": "C", "e": {"correcta": "An idiosyncratic drug reaction is an unpredictable reaction due to genetic differences or complex metabolic interactions, such as oxidative hemolytic anemia from primaquine use in patients with G6PD deficiency.", "incorrectas": {"A": "Predictable drug reactions relate to known pharmacologic properties of the drug, not genetic variability.", "B": "Exaggerated drug sensitivity involves known pharmacologic effects at lower doses, not genetically-driven unpredictable reactions.", "D": "Immunologic drug reactions are driven by anamnestic immune responses rather than genetic metabolic differences."}}}, {"id": "anking-quality-safety-796", "fuente": "anking", "tema": 64, "anki": "1521934990415", "q": "Which category of drug reactions represents unpredictable anamnestic responses to medications?", "o": {"A": "Immunologic", "B": "Idiosyncratic", "C": "Predictable", "D": "Exaggerated drug sensitivity"}, "r": "A", "e": {"correcta": "Immunologic drug reactions are unpredictable anamnestic responses, meaning the immune system reacts in an enhanced fashion to an antigen it has previously encountered.", "incorrectas": {"B": "Idiosyncratic reactions arise from genetic or metabolic differences, not from an anamnestic immune response.", "C": "Predictable reactions are due to known pharmacologic properties of the drug, not immune memory responses.", "D": "Exaggerated drug sensitivity reflects known pharmacologic effects at low doses, not an immune-mediated anamnestic mechanism."}}}, {"id": "anking-quality-safety-797", "fuente": "anking", "tema": 64, "anki": "1524512451549", "q": "For effective discharge planning, which professional should be consulted to determine non-medical factors affecting a patient's ability to return home (e.g., transportation, safety, support systems)?", "o": {"A": "Social worker", "B": "Case manager physician", "C": "Hospital pharmacist", "D": "Physical therapist"}, "r": "A", "e": {"correcta": "A social worker should be consulted during discharge planning to assess non-medical factors such as transportation, home safety, and support systems that affect a patient's ability to safely return home.", "incorrectas": {"B": "A physician case manager typically focuses on coordinating medical care and treatment plans, not primarily on the psychosocial and logistical factors of discharge.", "C": "A hospital pharmacist focuses on medication reconciliation and safety, not on transportation or home support systems.", "D": "A physical therapist evaluates and addresses physical mobility and functional capacity, not broader social and logistical discharge factors."}}}, {"id": "anking-quality-safety-798", "fuente": "anking", "tema": 64, "anki": "1525463530778", "q": "What is the most effective structured strategy for decreasing adverse outcomes and preventing avoidable hospital readmissions?", "o": {"A": "A comprehensive discharge checklist", "B": "A single follow-up phone call after discharge", "C": "A mandatory extended hospital stay", "D": "An unstructured verbal handoff to the patient"}, "r": "A", "e": {"correcta": "A comprehensive discharge checklist is the most effective structured approach, covering medication purpose/dosing/adverse effects, follow-up appointments and tests, and emergency contact information at an appropriate literacy level.", "incorrectas": {"B": "A single follow-up phone call alone is not a comprehensive structured approach and lacks the systematic elements of a checklist.", "C": "Extending hospital stay is not the recommended strategy and can increase costs and complications without specifically preventing readmissions.", "D": "An unstructured verbal handoff lacks the systematic, literacy-appropriate documentation shown to be most effective at reducing adverse outcomes."}}}, {"id": "anking-quality-safety-799", "fuente": "anking", "tema": 64, "anki": "1576094418967", "q": "What term describes a medical outcome that should never occur, such as an incorrect surgical procedure or wrong-patient infant handoff?", "o": {"A": "Near miss", "B": "\"Never event\"", "C": "Non-preventable adverse event", "D": "Idiosyncratic drug reaction"}, "r": "B", "e": {"correcta": "A \"never event\" is a serious, largely preventable medical outcome that should never occur, such as performing the wrong surgical procedure, giving an infant to the wrong person, or a hospital-acquired pressure ulcer.", "incorrectas": {"A": "A near miss is an error caught before it causes harm, whereas a never event has actually occurred and caused harm.", "C": "A non-preventable adverse event is unavoidable given current knowledge, the opposite concept of a never event which should always be avoidable.", "D": "An idiosyncratic drug reaction is an unpredictable pharmacologic response, unrelated to the concept of a categorically unacceptable outcome."}}}, {"id": "anking-quality-safety-800", "fuente": "anking", "tema": 64, "anki": "1579214416936", "q": "What human factors design principle improves quality and safety by physically preventing an undesirable action from being performed?", "o": {"A": "Forcing function", "B": "Root cause analysis", "C": "Checklist", "D": "Sentinel event review"}, "r": "A", "e": {"correcta": "A forcing function is a human factors design element that physically prevents an undesirable action from occurring (e.g., an incompatible connector that cannot be misconnected), making it the most effective type of safety design.", "incorrectas": {"B": "Root cause analysis is a retrospective investigative method after an error occurs, not a physical design feature that prevents errors.", "C": "A checklist is a cognitive aid that reduces the chance of omission but does not physically prevent an action the way a forcing function does.", "D": "Sentinel event review is a retrospective investigation process, not a proactive design feature preventing errors."}}}, {"id": "anking-quality-safety-801", "fuente": "anking", "tema": 64, "anki": "1591133260645", "q": "Which model of error analysis focuses on systems and underlying conditions rather than blaming an individual's error, using the metaphor of aligned holes in slices allowing failure to occur?", "o": {"A": "Swiss cheese model", "B": "Domino model", "C": "Root cause analysis model", "D": "Failure mode and effects model"}, "r": "A", "e": {"correcta": "The Swiss cheese model is used in risk analysis and management, focusing on systemic weaknesses rather than individual error; each 'slice' represents a layer of defense with holes (weaknesses) of varying size and position that can align to allow an error to cause harm.", "incorrectas": {"B": "The domino model is a historical model of accident causation emphasizing a sequential chain of events, not the systems-based aligned-holes metaphor.", "C": "Root cause analysis is a retrospective investigative technique, not a conceptual model illustrating systemic layered defenses.", "D": "Failure mode and effects analysis is a proactive risk assessment method, not the layered-defense systems model described here."}}}, {"id": "anking-communication-skills-802", "fuente": "anking", "tema": 65, "anki": "1520708388467", "q": "A patient tells you they want to try an alternative or holistic medicine therapy that has no known safety concerns. What is the most appropriate physician response?", "o": {"A": "Allow it, after confirming there are no contraindications, drug interactions, or adverse effects", "B": "Refuse to allow it because it is not evidence-based medicine", "C": "Report the patient to an ethics committee for pursuing unproven therapy", "D": "Discharge the patient from your practice for noncompliance"}, "r": "A", "e": {"correcta": "Respect for patient autonomy means physicians should support a patient's informed choices, including safe complementary therapies, as long as the physician has verified there are no contraindications, medication interactions, or adverse effects, and understands the patient's reasons for wanting it.", "incorrectas": {"B": "Refusing outright disregards patient autonomy when the therapy is known to be safe and poses no medical risk.", "C": "Ethics committee referral is unnecessary and disproportionate for a safe, patient-driven choice.", "D": "Discharging the patient is inappropriate and punitive; it does not reflect respect for patient autonomy or shared decision-making."}}}, {"id": "anking-communication-skills-803", "fuente": "anking", "tema": 65, "anki": "1522110353417", "q": "A physician has a personal moral objection to performing a legal medical procedure a patient is requesting. Is the physician required to perform it themselves?", "o": {"A": "No, but they must refer the patient to another provider who will perform it", "B": "Yes, physicians must always perform any legal procedure a patient requests", "C": "No, and they have no further obligation to the patient", "D": "Yes, unless the patient signs a liability waiver"}, "r": "A", "e": {"correcta": "Physicians are not obligated to personally provide services that conflict with their sincere personal or religious beliefs, but they must still ensure the patient's access to care by referring them to another provider who will perform the requested procedure.", "incorrectas": {"B": "Physicians are not compelled to violate their own moral or religious beliefs to perform a procedure.", "C": "Abandoning the patient without referral fails the physician's continuing duty of care.", "D": "A liability waiver is irrelevant to the ethical obligation regarding conscientious objection and referral."}}}, {"id": "anking-communication-skills-804", "fuente": "anking", "tema": 65, "anki": "1522553863254", "q": "A proposed treatment carries some risk of harm to the patient. Can this be ethically consistent with the principle of nonmaleficence?", "o": {"A": "Yes, as long as the benefits outweigh the risks and the patient gives informed consent", "B": "No, nonmaleficence requires that a treatment carry zero risk of harm", "C": "No, any risk automatically violates nonmaleficence regardless of benefit", "D": "Yes, but only if the physician alone decides without patient input"}, "r": "A", "e": {"correcta": "Nonmaleficence does not require the complete absence of risk; it requires that potential benefits outweigh potential risks, with the patient making an informed decision to proceed, as is the case with most surgeries and medications.", "incorrectas": {"B": "Almost no effective medical intervention is entirely risk-free, so this standard is unworkable and not the actual ethical requirement.", "C": "This ignores the risk-benefit balancing that underlies nonmaleficence in real clinical practice.", "D": "Excluding the patient from the decision violates the principle of autonomy and informed consent."}}}, {"id": "anking-communication-skills-805", "fuente": "anking", "tema": 65, "anki": "1522887997773", "q": "What is the most effective way for a physician to begin a medical interview with a patient?", "o": {"A": "An open-ended question", "B": "A closed-ended yes/no question", "C": "A leading question that suggests the expected diagnosis", "D": "A detailed checklist of review-of-systems questions"}, "r": "A", "e": {"correcta": "Beginning with an open-ended question allows the patient to describe their condition in their own words without being led or directed by the physician, conveying genuine interest in the patient's experience and helping build rapport.", "incorrectas": {"B": "Closed-ended questions restrict the patient's response and are better used later to clarify specific details.", "C": "Leading questions bias the patient's response toward a preconceived answer and can distort the history.", "D": "Starting with a rigid checklist feels impersonal and does not allow the patient to express their primary concerns first."}}}, {"id": "anking-communication-skills-806", "fuente": "anking", "tema": 65, "anki": "1522981100788", "q": "When taking a sexual history from a patient, should the physician assume the patient's sexual orientation based on appearance or other cues?", "o": {"A": "No, the physician should ask directly and inquire about all types of sexual partners", "B": "Yes, assuming orientation saves time and is usually accurate", "C": "Yes, but only for patients who appear to be in a same-sex relationship", "D": "No, sexual orientation should never be discussed during a medical history"}, "r": "A", "e": {"correcta": "Physicians should never assume a patient's sexual orientation; instead they should ask open, nonjudgmental questions such as whether the patient's sexual partners have been women, men, or both, to obtain accurate and complete information.", "incorrectas": {"B": "Assumptions based on appearance or presentation are frequently wrong and can damage the patient-physician relationship.", "C": "Selectively assuming orientation for certain patients is both inaccurate and discriminatory.", "D": "Sexual history is a relevant and necessary part of a complete medical history, not a topic to avoid."}}}, {"id": "anking-communication-skills-807", "fuente": "anking", "tema": 65, "anki": "1523884717459", "q": "A child is at significant risk of harm from a life-threatening condition, but the parents refuse a life-saving treatment. Is the physician justified in seeking a court injunction to proceed with treatment?", "o": {"A": "Yes, the physician may seek a court injunction to protect the child from significant harm", "B": "No, parental authority over medical decisions for a minor is absolute", "C": "No, the physician must always respect the parents' refusal without exception", "D": "Yes, but only if the parents give verbal permission first"}, "r": "A", "e": {"correcta": "When a child faces significant risk of harm and parents refuse life-saving treatment, physicians are ethically and legally justified in seeking a court injunction (or involving child protective services) to override parental refusal and proceed with treatment in the child's best interest.", "incorrectas": {"B": "Parental authority is not absolute; it can be overridden when a child's welfare is seriously endangered.", "C": "Physicians have a duty to protect children from harm, which can supersede parental refusal in life-threatening situations.", "D": "Requiring parental permission defeats the purpose of the court injunction, which is specifically needed when parents refuse."}}}, {"id": "anking-communication-skills-808", "fuente": "anking", "tema": 65, "anki": "1526175155058", "q": "Is it ever considered ethically appropriate for a physician to date a current patient?", "o": {"A": "No, it is not appropriate while the patient-provider relationship exists", "B": "Yes, as long as both parties consent and no coercion is involved", "C": "Yes, if the treatment being provided is minor or non-serious", "D": "Yes, provided the relationship is disclosed to the medical board afterward"}, "r": "A", "e": {"correcta": "Dating a current patient is not considered ethically appropriate; the power imbalance inherent in the patient-physician relationship compromises the patient's ability to freely consent, and some argue even ending the relationship simply to pursue dating is itself an ethical violation.", "incorrectas": {"B": "Consent in this context is compromised by the inherent power imbalance between physician and patient.", "C": "The severity of the medical condition does not change the ethical prohibition against romantic involvement with a current patient.", "D": "Disclosure after the fact does not make the underlying romantic relationship with a current patient ethical."}}}, {"id": "anking-communication-skills-809", "fuente": "anking", "tema": 65, "anki": "1526175256676", "q": "Is it ever ethical for a psychiatrist to pursue a romantic relationship with a former psychiatric patient?", "o": {"A": "No, this is never considered ethical", "B": "Yes, once a specified waiting period (e.g., one year) has passed", "C": "Yes, as long as the patient initiates the relationship", "D": "Yes, if the treatment was brief and non-intensive"}, "r": "A", "e": {"correcta": "Romantic relationships between psychiatrists and former patients are never considered ethical because the power dynamic from the therapeutic relationship persists and makes such relationships inherently exploitative and dangerous, regardless of time elapsed.", "incorrectas": {"B": "No waiting period resolves the enduring power imbalance created by the psychiatric treatment relationship.", "C": "Who initiates the relationship does not eliminate the inherent power imbalance and potential for harm.", "D": "Even brief psychiatric treatment establishes a therapeutic power dynamic that makes later romantic involvement unethical."}}}, {"id": "anking-communication-skills-810", "fuente": "anking", "tema": 65, "anki": "1526310211870", "q": "Under what circumstance is it acceptable for a physician to provide medical treatment to a friend?", "o": {"A": "Only in emergency situations when no other physician is available", "B": "Whenever the friend specifically requests it", "C": "Only for minor, non-prescription-related complaints", "D": "Routinely, as long as proper documentation is kept"}, "r": "A", "e": {"correcta": "Treating friends and family is generally discouraged due to compromised objectivity and boundary issues, but it is considered acceptable in emergency situations when no other physician is available to provide care.", "incorrectas": {"B": "A friend's request alone does not justify treatment; personal relationships can impair objective clinical judgment.", "C": "Even minor complaints carry the same objectivity and boundary concerns that make treating friends problematic outside emergencies.", "D": "Routine treatment of friends is not endorsed regardless of documentation, due to the risk of compromised objectivity."}}}, {"id": "anking-virology-1131", "fuente": "anking", "tema": 20, "anki": "1394239337348", "q": "Which HPV-encoded protein binds and inactivates the retinoblastoma protein (p105-Rb), promoting unchecked progression through the cell cycle?", "o": {"A": "E6", "B": "E7", "C": "E1", "D": "L1"}, "r": "B", "e": {"correcta": "High-risk HPV E7 protein binds hypophosphorylated (active) Rb and displaces the E2F transcription factor, freeing E2F to drive the cell into S phase without normal checkpoint control, contributing to oncogenic transformation.", "incorrectas": {"A": "E6 is the other major high-risk HPV oncoprotein, but it acts by binding and promoting degradation of p53 (via ubiquitin ligase activity), not Rb.", "C": "E1 is a viral protein involved in HPV genome replication (helicase activity), not in inactivating tumor suppressor proteins like Rb.", "D": "L1 is the major capsid protein of HPV (the target of the HPV vaccines), a structural protein with no role in cell cycle deregulation."}}}, {"id": "anking-virology-1132", "fuente": "anking", "tema": 20, "anki": "1394239958498", "q": "Which two HPV genotypes are most commonly associated with high-risk (oncogenic) infection?", "o": {"A": "HPV6 and HPV11", "B": "HPV16 and HPV18", "C": "HPV1 and HPV2", "D": "HPV31 and HPV33"}, "r": "B", "e": {"correcta": "HPV16 and HPV18 are the most common high-risk genotypes, together accounting for the majority of HPV-associated cervical, anal, and oropharyngeal cancers due to their potent E6/E7 oncoproteins that degrade p53 and Rb, respectively.", "incorrectas": {"A": "HPV6 and HPV11 are classic low-risk genotypes that cause condyloma acuminata (genital warts) and laryngeal papillomatosis but have weak oncogenic potential.", "C": "HPV1 and HPV2 cause common cutaneous warts (verruca vulgaris) on skin such as the hands, not genital or cervical neoplasia.", "D": "HPV31 and HPV33 are also high-risk genotypes and contribute to cervical cancer, but they are less common than HPV16/18, which dominate as the most frequent high-risk types."}}}, {"id": "anking-virology-1133", "fuente": "anking", "tema": 20, "anki": "1394240219632", "q": "Which two HPV genotypes are most commonly associated with low-risk infection (genital warts)?", "o": {"A": "HPV16 and HPV18", "B": "HPV31 and HPV33", "C": "HPV6 and HPV11", "D": "HPV1 and HPV4"}, "r": "C", "e": {"correcta": "HPV6 and HPV11 are the classic low-risk genotypes responsible for condyloma acuminata (anogenital warts) and recurrent respiratory papillomatosis; they rarely integrate into the host genome and thus have low oncogenic potential.", "incorrectas": {"A": "HPV16 and HPV18 are the leading high-risk genotypes responsible for cervical, anal, and oropharyngeal carcinoma, not genital warts.", "B": "HPV31 and HPV33 are additional high-risk genotypes implicated in cervical intraepithelial neoplasia and carcinoma, not low-risk wart-forming strains.", "D": "HPV1 and HPV4 cause cutaneous verruca vulgaris (common warts on skin), not anogenital condylomas, which are caused by HPV6/11."}}}, {"id": "anking-neoplasia-1134", "fuente": "anking", "tema": 14, "anki": "1394240326453", "q": "A 45-year-old woman is diagnosed with cervical carcinoma. Persistent infection with which group of pathogens is the key risk factor for this cancer?", "o": {"A": "High-risk HPV types 16, 18, 31, 33", "B": "Herpes simplex virus type 2", "C": "Epstein-Barr virus", "D": "Human papillomavirus types 6 and 11"}, "r": "A", "e": {"correcta": "Persistent infection with high-risk HPV types (especially 16 and 18, which together account for over 70% of cases) is the key risk factor for cervical carcinoma; their E6 and E7 oncoproteins inactivate p53 and Rb, driving malignant transformation of cervical epithelium.", "incorrectas": {"B": "HSV-2 was historically implicated as a cervical cancer cofactor but is not the key causative risk factor; the dominant driver is persistent high-risk HPV infection.", "C": "EBV is associated with malignancies like Burkitt lymphoma and nasopharyngeal carcinoma, not cervical carcinoma.", "D": "HPV6 and 11 are low-risk types that cause genital warts but carry minimal oncogenic potential, in contrast to high-risk types 16/18/31/33."}}}, {"id": "anking-virology-1135", "fuente": "anking", "tema": 20, "anki": "1394240399533", "q": "What is the most common histologic subtype of cervical carcinoma?", "o": {"A": "Adenocarcinoma", "B": "Small cell carcinoma", "C": "Squamous cell carcinoma", "D": "Clear cell carcinoma"}, "r": "C", "e": {"correcta": "Squamous cell carcinoma accounts for approximately 80% of cervical carcinomas, arising from the transformation zone where HPV-driven dysplasia of squamous epithelium progresses through cervical intraepithelial neoplasia to invasive cancer.", "incorrectas": {"B": "Small cell carcinoma of the cervix is a rare, aggressive neuroendocrine subtype, representing only a small minority of cases, not the most common type.", "A": "Adenocarcinoma, arising from the endocervical glandular epithelium, is the second most common subtype (about 15% of cases) and is also HPV-related, but it is less frequent than squamous cell carcinoma.", "D": "Clear cell carcinoma is a rare cervical/vaginal cancer subtype classically associated with in utero diethylstilbestrol (DES) exposure, not the typical HPV-driven cervical cancer."}}}, {"id": "anking-virology-1136", "fuente": "anking", "tema": 20, "anki": "1394240523986", "q": "Which procedure is the gold-standard screening test for cervical carcinoma?", "o": {"A": "Colposcopy", "B": "HPV DNA testing alone", "C": "Pap smear", "D": "Endocervical curettage"}, "r": "C", "e": {"correcta": "The Pap smear, which cytologically evaluates exfoliated cervical cells for dysplastic changes, is the gold-standard screening test for cervical cancer and has dramatically reduced cervical cancer mortality through early detection of precancerous lesions.", "incorrectas": {"A": "Colposcopy is a diagnostic follow-up procedure used to directly visualize and biopsy the cervix after an abnormal Pap smear, not the primary screening test itself.", "B": "HPV DNA testing is often used adjunctively (co-testing) with the Pap smear, especially in older women, but the Pap smear remains the traditional gold-standard screening modality.", "D": "Endocervical curettage is a diagnostic sampling technique used when colposcopy findings are inadequate or the transformation zone is not fully visualized, not a screening test."}}}, {"id": "anking-virology-1137", "fuente": "anking", "tema": 20, "anki": "1394240978725", "q": "The quadrivalent HPV vaccine (Gardasil) provides protection against which four HPV genotypes?", "o": {"A": "HPV16, 18, 31, 33", "B": "HPV6, 11, 16, 18", "C": "HPV1, 2, 6, 11", "D": "HPV31, 33, 45, 52"}, "r": "B", "e": {"correcta": "The quadrivalent HPV vaccine covers HPV6 and 11 (the main low-risk types causing genital warts) and HPV16 and 18 (the main high-risk types causing cervical and other anogenital cancers), providing both cancer prevention and wart prevention.", "incorrectas": {"A": "HPV16, 18, 31, and 33 are all high-risk oncogenic types, but the quadrivalent vaccine specifically also covers the low-risk wart-causing types 6 and 11, not 31/33.", "C": "HPV1 and 2 cause cutaneous verruca vulgaris and are not targeted by the anogenital HPV vaccines, which focus on sexually transmitted genotypes.", "D": "HPV31, 33, 45, and 52 are additional high-risk types covered by the newer nonavalent (9-valent) vaccine, not the original quadrivalent formulation."}}}, {"id": "anking-virology-1138", "fuente": "anking", "tema": 20, "anki": "1394241705535", "q": "Which four HPV genotypes are most commonly implicated in cervical intraepithelial neoplasia (CIN) and cervical carcinoma?", "o": {"A": "HPV6, 11, 16, 18", "B": "HPV1, 2, 3, 4", "C": "HPV16, 18, 31, 33", "D": "HPV42, 43, 44, 45"}, "r": "C", "e": {"correcta": "HPV types 16, 18, 31, and 33 are the classic high-risk genotypes responsible for the majority of CIN and cervical carcinoma cases, due to potent E6/E7 oncoprotein activity that inactivates p53 and Rb tumor suppressors.", "incorrectas": {"A": "HPV6 and 11 are low-risk types causing genital warts, not the oncogenic drivers of CIN/cervical carcinoma; this combination mixes low- and high-risk types incorrectly.", "B": "HPV1-4 cause cutaneous verruca vulgaris (common skin warts), unrelated to cervical dysplasia or carcinoma.", "D": "HPV42-44 are low-risk genotypes with minimal oncogenic potential, not the principal drivers of cervical neoplasia."}}}, {"id": "anking-virology-1139", "fuente": "anking", "tema": 20, "anki": "1394242185928", "q": "What is the oncogenic risk classification of HPV types 42-44?", "o": {"A": "High risk", "B": "Intermediate risk", "C": "Low risk", "D": "No malignant potential ever reported"}, "r": "C", "e": {"correcta": "HPV types 42-44 are classified as low-risk genotypes; like HPV6/11, they are more commonly associated with benign genital warts and rarely integrate their genome into the host chromosome, resulting in minimal transformation potential.", "incorrectas": {"A": "High-risk classification applies to types like HPV16, 18, 31, and 33, which have strong oncoprotein activity against p53 and Rb; HPV42-44 lack this potent transforming capability.", "B": "There is no formal 'intermediate risk' category in standard HPV risk classification; genotypes are generally grouped as high-risk or low-risk based on oncogenic potential.", "D": "While low risk, this does not mean zero malignant potential has ever been reported for any low-risk HPV type in rare contexts; the accepted classification for HPV42-44 is 'low risk,' not a claim of absolute impossibility."}}}, {"id": "anking-virology-1140", "fuente": "anking", "tema": 20, "anki": "1394242887061", "q": "Low-risk HPV subtypes (especially HPV6 and 11) are most classically associated with which urogenital lesion?", "o": {"A": "Cervical squamous cell carcinoma", "B": "Condylomata (anogenital warts)", "C": "Vulvar intraepithelial neoplasia grade 3", "D": "Verruca vulgaris of the hands"}, "r": "B", "e": {"correcta": "Low-risk HPV subtypes, particularly HPV6 and 11, cause condyloma acuminatum (anogenital warts), which are exophytic, cauliflower-like lesions of the genital mucosa; these subtypes have low oncogenic potential compared to high-risk types.", "incorrectas": {"A": "Cervical squamous cell carcinoma is driven by high-risk HPV types (16, 18, 31, 33) with strong E6/E7 oncoprotein activity, not the low-risk types that cause warts.", "C": "High-grade vulvar intraepithelial neoplasia is typically associated with high-risk HPV infection and represents a precancerous lesion, distinct from the benign warts caused by low-risk types.", "D": "Verruca vulgaris (common warts on the hands) is caused by HPV types 1-4, which infect keratinocytes on non-genital skin, not the anogenital mucosa affected by HPV6/11."}}}, {"id": "anking-virology-1141", "fuente": "anking", "tema": 20, "anki": "1394242914870", "q": "A cervical biopsy from a patient with HPV infection shows squamous cells with perinuclear cytoplasmic clearing and a shrunken, raisin-like nucleus. What is this histologic finding called?", "o": {"A": "Owl's eye inclusions", "B": "Councilman bodies", "C": "Koilocytes", "D": "Reed-Sternberg cells"}, "r": "C", "e": {"correcta": "Koilocytes are HPV-infected squamous epithelial cells characterized by perinuclear cytoplasmic vacuolization (halo) and a wrinkled, raisin-like nucleus, representing a classic cytopathic effect used to diagnose HPV infection on Pap smear or biopsy.", "incorrectas": {"A": "Owl's eye inclusions describe the large intranuclear inclusion bodies seen in cytomegalovirus-infected cells, not HPV-infected keratinocytes.", "B": "Councilman bodies are eosinophilic apoptotic hepatocytes seen in viral hepatitis (e.g., yellow fever), unrelated to HPV cytopathology.", "D": "Reed-Sternberg cells are the large binucleated ('owl's eye') tumor cells diagnostic of classic Hodgkin lymphoma, not a feature of HPV-infected epithelium."}}}, {"id": "anking-virology-1142", "fuente": "anking", "tema": 20, "anki": "1394388455675", "q": "Which HPV subtypes are the classic cause of condylomata acuminata (anogenital warts)?", "o": {"A": "HPV16 and HPV18", "B": "HPV31 and HPV33", "C": "HPV6 and HPV11", "D": "HPV1 and HPV2"}, "r": "C", "e": {"correcta": "HPV6 and HPV11 are the low-risk genotypes responsible for the vast majority of condylomata acuminata, benign cauliflower-like papillomas of the anogenital mucosa; these types rarely cause malignant transformation.", "incorrectas": {"A": "HPV16 and 18 are high-risk oncogenic types associated with cervical, anal, and oropharyngeal carcinoma, not the benign warts of condyloma acuminatum.", "B": "HPV31 and 33 are also high-risk types contributing to cervical dysplasia and carcinoma, not the classic cause of genital warts.", "D": "HPV1 and 2 cause cutaneous verruca vulgaris (common warts on hands/skin), which are distinct in location and appearance from anogenital condylomas."}}}, {"id": "anking-virology-1143", "fuente": "anking", "tema": 20, "anki": "1394388562593", "q": "What is the most common risk factor for squamous cell carcinoma of the penis?", "o": {"A": "Chronic balanitis", "B": "Lack of circumcision", "C": "High-risk HPV (types 16, 18, 31, 33)", "D": "Chronic lichen sclerosus"}, "r": "C", "e": {"correcta": "High-risk HPV infection (particularly types 16, 18, 31, and 33) is the most common risk factor for penile squamous cell carcinoma, accounting for roughly two-thirds of cases, through the same E6/E7-mediated inactivation of p53 and Rb seen in cervical cancer.", "incorrectas": {"B": "Lack of circumcision (with poor hygiene and phimosis) is an important secondary risk factor that promotes smegma accumulation and chronic irritation, but it ranks second to high-risk HPV as the leading cause.", "A": "Chronic balanitis (inflammation of the glans) can be a contributing irritant factor but is not the most common or primary risk factor identified for penile carcinoma.", "D": "Lichen sclerosus is a chronic inflammatory dermatologic condition that can predispose to penile squamous cell carcinoma in some cases, but it is a less common risk factor than high-risk HPV infection."}}}, {"id": "anking-virology-1144", "fuente": "anking", "tema": 20, "anki": "1394388597280", "q": "Besides high-risk HPV infection, what is the second most significant risk factor for squamous cell carcinoma of the penis?", "o": {"A": "Cigarette smoking", "B": "Lack of circumcision and poor foreskin hygiene", "C": "HIV infection", "D": "Multiple sexual partners"}, "r": "B", "e": {"correcta": "Lack of circumcision, along with poorly maintained foreskin, promotes smegma accumulation and chronic inflammation of the glans, making it the second most significant risk factor for penile squamous cell carcinoma after high-risk HPV infection.", "incorrectas": {"A": "Cigarette smoking is a recognized risk factor for penile carcinoma due to carcinogen exposure, but it is not ranked as the second most significant factor behind HPV.", "C": "HIV infection increases susceptibility to persistent HPV infection and thus indirectly raises penile cancer risk, but it is not itself the classically cited second major risk factor.", "D": "Multiple sexual partners increase the risk of acquiring high-risk HPV, which is the primary risk factor, but this exposure factor is distinct from the anatomic/hygienic risk of an intact, poorly maintained foreskin."}}}, {"id": "anking-virology-1145", "fuente": "anking", "tema": 20, "anki": "1395340470032", "q": "Soft, flesh-colored, cauliflower-like papules on the skin resulting from HPV infection of keratinocytes are best described as which lesion?", "o": {"A": "Molluscum contagiosum", "B": "Verruca (warts)", "C": "Seborrheic keratosis", "D": "Actinic keratosis"}, "r": "B", "e": {"correcta": "Verrucae (warts) are soft, flesh-colored, cauliflower-like papules caused by HPV infection of keratinocytes, which induce epidermal hyperplasia; when they occur on the genitals, the same lesion is termed condyloma acuminatum.", "incorrectas": {"A": "Molluscum contagiosum presents as dome-shaped, umbilicated papules caused by a poxvirus, not HPV, and has a distinct central dimple rather than a cauliflower-like surface.", "C": "Seborrheic keratosis is a benign, 'stuck-on' pigmented epidermal growth common in older adults, unrelated to viral infection.", "D": "Actinic keratosis is a precancerous, scaly, erythematous lesion caused by chronic UV sun damage, not a viral wart caused by HPV."}}}, {"id": "anking-virology-1146", "fuente": "anking", "tema": 20, "anki": "1395340559909", "q": "Verruca vulgaris (common warts) results from HPV types 1-4 infecting which cell type?", "o": {"A": "Fibroblasts", "B": "Melanocytes", "C": "Keratinocytes", "D": "Langerhans cells"}, "r": "C", "e": {"correcta": "HPV types 1-4 infect keratinocytes of the epidermis, causing hyperproliferation and hyperkeratosis that manifest as verruca vulgaris (common warts), typically on the hands and other skin surfaces.", "incorrectas": {"A": "Fibroblasts are dermal connective tissue cells and are not the primary target of HPV infection, which is epidermal keratinocytes.", "B": "Melanocytes are pigment-producing cells in the basal epidermis; they are not infected by HPV and are not implicated in wart formation.", "D": "Langerhans cells are antigen-presenting dendritic cells of the epidermis involved in immune surveillance against HPV, not the cells that HPV productively infects to cause warts."}}}, {"id": "anking-molecular-biology-1147", "fuente": "anking", "tema": 44, "anki": "1401126448424", "q": "The tumor suppressor p53 arrests the cell cycle at which checkpoint in response to DNA damage?", "o": {"A": "G2 to M", "B": "M checkpoint (spindle assembly)", "C": "G1 to S", "D": "S phase entry from G0"}, "r": "C", "e": {"correcta": "p53 halts the cell cycle at the G1-to-S checkpoint by upregulating p21, which inhibits cyclin-CDK complexes, allowing time for DNA repair before replication; loss-of-function mutations in p53 (as induced by HPV E6) permit uncontrolled progression into S phase.", "incorrectas": {"A": "The G2-to-M checkpoint is regulated primarily by ATM/ATR-Chk1/2 signaling checking for completed and accurate DNA replication, not the principal checkpoint classically attributed to p53 action in this context.", "B": "The M checkpoint (spindle assembly checkpoint) ensures proper chromosome attachment to the mitotic spindle and is regulated by proteins like Mad2 and BubR1, not primarily by p53.", "D": "p53 acts at the G1/S checkpoint rather than controlling reentry from a quiescent G0 state into S phase directly."}}}, {"id": "anking-molecular-biology-1148", "fuente": "anking", "tema": 44, "anki": "1401126657216", "q": "Hypophosphorylated retinoblastoma protein (Rb) blocks progression through which cell cycle checkpoint?", "o": {"A": "G2 to M", "B": "G1 to S", "C": "Metaphase to anaphase", "D": "S to G2"}, "r": "B", "e": {"correcta": "Hypophosphorylated (active) Rb binds and sequesters the E2F transcription factor, preventing transcription of genes needed for S phase entry, thereby blocking the G1-to-S checkpoint; phosphorylation of Rb by cyclin D/CDK4/6 releases E2F and allows cell cycle progression.", "incorrectas": {"A": "The G2-to-M transition is governed by cyclin B/CDK1 (MPF) activity and DNA damage checkpoints, not by Rb's E2F-sequestering function.", "C": "The metaphase-to-anaphase transition is controlled by the spindle assembly checkpoint and securin/separase, unrelated to Rb-E2F regulation.", "D": "There is no classically described distinct 'S to G2' Rb-mediated checkpoint; Rb's principal regulatory role is at the G1/S restriction point."}}}, {"id": "anking-hematology-oncology-pathology-1149", "fuente": "anking", "tema": 6, "anki": "1401319326505", "q": "Hereditary spherocytosis, an autosomal dominant disorder causing spheroid erythrocytes and hemolytic anemia with increased MCHC, is most often due to a defect in which pair of cytoskeletal proteins?", "o": {"A": "Actin or myosin", "B": "Dystrophin or dystroglycan", "C": "Spectrin or ankyrin", "D": "Band 3 protein or glycophorin A"}, "r": "C", "e": {"correcta": "Hereditary spherocytosis most commonly results from mutations in spectrin or ankyrin, cytoskeletal proteins that normally anchor the red cell membrane to its underlying scaffold; their deficiency destabilizes the membrane, producing small, spherical, less deformable red cells that are prematurely destroyed by the spleen, causing extravascular hemolysis and elevated MCHC.", "incorrectas": {"A": "Actin and myosin are contractile cytoskeletal proteins central to muscle and general cell motility, not the classic red cell membrane proteins implicated in hereditary spherocytosis.", "B": "Dystrophin and dystroglycan defects cause muscular dystrophies (e.g., Duchenne), not red blood cell membrane instability or spherocytosis.", "D": "Band 3 protein can occasionally be involved in spherocytosis, but it is not the primary or 'classic' defect; the most emphasized proteins are spectrin and ankyrin, not glycophorin A, which is more relevant to blood group antigens."}}}, {"id": "anking-clinical-bacteriology-1150", "fuente": "anking", "tema": 21, "anki": "1402175838315", "q": "Which stain is best used to visualize intracytoplasmic inclusion bodies of Chlamydia trachomatis?", "o": {"A": "Ziehl-Neelsen (acid-fast) stain", "B": "Gram stain", "C": "Giemsa stain", "D": "India ink"}, "r": "C", "e": {"correcta": "Giemsa stain is used to visualize Chlamydia because it can detect the intracytoplasmic inclusion bodies formed by this obligate intracellular organism, which lacks a classic peptidoglycan cell wall detectable by Gram stain.", "incorrectas": {"A": "Ziehl-Neelsen (acid-fast) stain is used to visualize Mycobacterium species and Nocardia, which have mycolic acid-rich cell walls, not Chlamydia.", "B": "Gram stain is ineffective for Chlamydia because it lacks a typical peptidoglycan layer and does not take up Gram stain reliably, unlike most bacteria.", "D": "India ink is used to visualize the polysaccharide capsule of Cryptococcus neoformans, an unrelated fungal pathogen, not Chlamydia."}}}, {"id": "anking-clinical-bacteriology-1151", "fuente": "anking", "tema": 21, "anki": "1402176460130", "q": "Which stain is used to best visualize Borrelia species on peripheral blood smear?", "o": {"A": "Giemsa", "B": "Ziehl-Neelsen", "C": "Silver stain", "D": "Gram stain"}, "r": "A", "e": {"correcta": "Giemsa stain is used to visualize Borrelia species (e.g., B. burgdorferi, B. recurrentis) on peripheral blood smear because it stains spirochetes well enough to be seen by light microscopy, unlike thin, poorly Gram-staining spirochetes.", "incorrectas": {"B": "Ziehl-Neelsen (acid-fast) stain is specific for mycobacteria and some Nocardia species due to their mycolic acid cell walls, not spirochetes like Borrelia.", "C": "Silver stain (e.g., Warthin-Starry) can also visualize spirochetes such as Treponema and Bartonella, but the classically tested stain for Borrelia on blood smear is Giemsa.", "D": "Gram stain is not useful for Borrelia because spirochetes are too thin to be reliably visualized with standard Gram staining and light microscopy."}}}, {"id": "anking-clinical-bacteriology-1152", "fuente": "anking", "tema": 21, "anki": "1402176473561", "q": "Which stain is best used to visualize Rickettsiae?", "o": {"A": "Ziehl-Neelsen stain", "B": "Gram stain", "C": "Congo red stain", "D": "Giemsa stain"}, "r": "D", "e": {"correcta": "Giemsa stain is used to visualize Rickettsiae because these obligate intracellular organisms are too small and their cell walls too thin to be reliably seen with standard Gram staining.", "incorrectas": {"A": "Ziehl-Neelsen (acid-fast) stain is used for Mycobacterium and Nocardia, organisms with mycolic acid-rich walls, not Rickettsiae.", "B": "Gram stain is generally ineffective for Rickettsiae since they stain poorly due to their thin peptidoglycan layer and obligate intracellular lifestyle.", "C": "Congo red stain is used to detect amyloid deposits (showing apple-green birefringence under polarized light), an entirely different application unrelated to bacterial visualization."}}}, {"id": "anking-parasitology-1153", "fuente": "anking", "tema": 22, "anki": "1402176494851", "q": "Which stain is used to visualize Trypanosomes on peripheral blood smear?", "o": {"A": "Ziehl-Neelsen stain", "B": "Giemsa stain", "C": "Trichrome stain", "D": "PAS stain"}, "r": "B", "e": {"correcta": "Giemsa stain is the standard stain used to visualize Trypanosoma species on peripheral blood smear, allowing identification of the characteristic undulating flagellated trypomastigote forms.", "incorrectas": {"A": "Ziehl-Neelsen stain detects acid-fast organisms like Mycobacterium, and modified acid-fast stains are used for Cryptosporidium, not Trypanosoma.", "C": "Trichrome stain is used in stool microscopy to identify intestinal protozoa such as Entamoeba and Giardia, not blood-borne trypanosomes.", "D": "PAS (periodic acid-Schiff) stain highlights glycogen and mucopolysaccharides, useful for fungi and some storage diseases, not for visualizing blood parasites like Trypanosoma."}}}, {"id": "anking-parasitology-1154", "fuente": "anking", "tema": 22, "anki": "1402176519075", "q": "Which stain is used to visualize Plasmodium species on a peripheral blood smear?", "o": {"A": "Giemsa stain", "B": "India ink", "C": "Ziehl-Neelsen stain", "D": "Silver stain"}, "r": "A", "e": {"correcta": "Giemsa stain is the classic stain used to visualize Plasmodium species within red blood cells on peripheral blood smear, allowing identification of ring forms, schizonts, and gametocytes for species differentiation.", "incorrectas": {"B": "India ink is used to visualize the polysaccharide capsule of Cryptococcus neoformans on wet mount, not intraerythrocytic parasites like Plasmodium.", "C": "Ziehl-Neelsen stain is used for acid-fast organisms such as Mycobacterium, not for detecting malaria parasites in blood.", "D": "Silver stains (e.g., Warthin-Starry, GMS) are used for spirochetes and fungi like Pneumocystis, not for identifying Plasmodium in blood smears."}}}, {"id": "anking-parasitology-1155", "fuente": "anking", "tema": 22, "anki": "1402176691861", "q": "Which stain is used to visualize the polysaccharide capsule of Cryptococcus neoformans on a wet mount preparation?", "o": {"A": "Giemsa stain", "B": "Ziehl-Neelsen stain", "C": "India ink", "D": "Gram stain"}, "r": "C", "e": {"correcta": "India ink stain creates a dark background against which the thick polysaccharide capsule of Cryptococcus neoformans appears as a clear halo surrounding the yeast, allowing rapid visualization, especially in CSF samples; mucicarmine can also stain the capsule red on tissue sections.", "incorrectas": {"A": "Giemsa stain is used for organisms like Rickettsia, Borrelia, Trypanosoma, and Plasmodium, not for demonstrating the capsule of Cryptococcus.", "B": "Ziehl-Neelsen (acid-fast) stain identifies mycobacteria and Nocardia via mycolic acid content, unrelated to fungal capsule visualization.", "D": "Gram stain can show Cryptococcus as poorly staining budding yeast but does not highlight the capsule itself, which requires India ink or mucicarmine for clear visualization."}}}, {"id": "anking-clinical-bacteriology-1156", "fuente": "anking", "tema": 21, "anki": "1402796160322", "q": "Endemic (murine) typhus is caused by infection with which organism?", "o": {"A": "Rickettsia rickettsii", "B": "Rickettsia typhi", "C": "Rickettsia prowazekii", "D": "Orientia tsutsugamushi"}, "r": "B", "e": {"correcta": "Endemic (murine) typhus is caused by Rickettsia typhi, transmitted by the rat flea, and presents with fever, headache, and rash, generally milder than epidemic typhus.", "incorrectas": {"A": "Rickettsia rickettsii causes Rocky Mountain spotted fever, transmitted by the dog tick or wood tick, with a distinct rash pattern starting on wrists/ankles, not endemic typhus.", "C": "Rickettsia prowazekii causes epidemic typhus, transmitted by the human body louse, and is associated with more severe disease and outbreaks in crowded, unsanitary conditions.", "D": "Orientia tsutsugamushi causes scrub typhus, transmitted by chigger mites, a distinct rickettsial-like illness endemic to parts of Asia and the Pacific."}}}, {"id": "anking-clinical-bacteriology-1157", "fuente": "anking", "tema": 21, "anki": "1402797631619", "q": "What is the treatment of choice for infections caused by Rickettsia species?", "o": {"A": "Doxycycline", "B": "Vancomycin", "C": "Metronidazole", "D": "Fluconazole"}, "r": "A", "e": {"correcta": "Doxycycline is the treatment of choice for all Rickettsia species infections (including Rocky Mountain spotted fever, epidemic and endemic typhus), as tetracyclines effectively penetrate host cells to inhibit these obligate intracellular organisms' protein synthesis.", "incorrectas": {"B": "Vancomycin targets cell wall synthesis in gram-positive bacteria (including MRSA) and has no activity against obligate intracellular organisms like Rickettsia.", "C": "Metronidazole is used for anaerobic bacterial and protozoal infections (e.g., C. difficile, Giardia, Trichomonas), not for Rickettsial disease.", "D": "Fluconazole is an antifungal agent targeting ergosterol synthesis and has no role in treating bacterial Rickettsial infections."}}}, {"id": "anking-clinical-bacteriology-1158", "fuente": "anking", "tema": 21, "anki": "1402799666317", "q": "A patient develops a rickettsial-like febrile illness after exposure to aerosolized particles from tick feces or cattle placenta. What is this condition called?", "o": {"A": "Rocky Mountain spotted fever", "B": "Q fever", "C": "Epidemic typhus", "D": "Ehrlichiosis"}, "r": "B", "e": {"correcta": "Q fever, caused by Coxiella burnetii, is a rickettsial-like illness acquired via inhalation of aerosolized spores from tick feces, or from contact with birth products of infected cattle, sheep, or goats (e.g., placenta), rather than through a tick bite itself.", "incorrectas": {"A": "Rocky Mountain spotted fever is caused by Rickettsia rickettsii transmitted directly by tick bite (not aerosolized spores) and classically presents with a rash spreading from wrists/ankles centrally.", "C": "Epidemic typhus is caused by Rickettsia prowazekii transmitted by the human body louse, not by aerosolized tick feces or animal placental exposure.", "D": "Ehrlichiosis is caused by Ehrlichia chaffeensis, transmitted by the Lone Star tick bite, and does not involve the aerosolized transmission route characteristic of Q fever."}}}, {"id": "anking-clinical-bacteriology-1159", "fuente": "anking", "tema": 21, "anki": "1402799860948", "q": "A rickettsial-like disorder caused by Coxiella burnetii that classically presents as an atypical pneumonia is best described as which condition?", "o": {"A": "Rocky Mountain spotted fever", "B": "Ehrlichiosis", "C": "Q fever", "D": "Anaplasmosis"}, "r": "C", "e": {"correcta": "Q fever, caused by Coxiella burnetii, is a rickettsial-like illness that classically presents with atypical pneumonia (as well as hepatitis or endocarditis in some cases); unlike other rickettsial diseases, it typically lacks a rash and is not tick-bite transmitted but rather acquired via aerosol inhalation.", "incorrectas": {"A": "Rocky Mountain spotted fever, caused by Rickettsia rickettsii, presents with fever, headache, and a characteristic centripetal rash, not primarily as pneumonia.", "B": "Ehrlichiosis, caused by Ehrlichia chaffeensis, presents with fever, headache, and leukopenia after tick exposure, and is not classically characterized as an atypical pneumonia.", "D": "Anaplasmosis, caused by Anaplasma phagocytophilum, presents similarly to ehrlichiosis with fever and cytopenias following tick bite, not as a primary pneumonia syndrome."}}}, {"id": "anking-clinical-bacteriology-1160", "fuente": "anking", "tema": 21, "anki": "1402801458083", "q": "Which serotypes of Chlamydia trachomatis are most associated with neonatal conjunctivitis, acquired during passage through the birth canal?", "o": {"A": "A-C", "B": "D-K", "C": "L1-L3", "D": "Serotype B only"}, "r": "B", "e": {"correcta": "Chlamydia trachomatis serotypes D-K cause genitourinary infections (urethritis, cervicitis) and, when transmitted perinatally through the birth canal, neonatal conjunctivitis (and neonatal pneumonia), distinguishing them from other serotypes causing different clinical syndromes.", "incorrectas": {"A": "Serotypes A-C cause trachoma, a chronic conjunctival infection leading to blindness, typically transmitted through direct contact or fomites in endemic regions, not perinatal transmission causing neonatal conjunctivitis.", "C": "Serotypes L1-L3 cause lymphogranuloma venereum, a sexually transmitted infection involving lymph node involvement, distinct from neonatal conjunctivitis.", "D": "Serotype B alone is not the classically designated group; serotypes A-C together cause trachoma, while D-K are the ones responsible for neonatal conjunctivitis and genital infections."}}}, {"id": "anking-parasitology-1161", "fuente": "anking", "tema": 22, "anki": "1402961229963", "q": "Which opportunistic fungal infection is most classically seen in patients with diabetic ketoacidosis or leukemia, and can invade the cribriform plate to reach the brain?", "o": {"A": "Aspergillosis", "B": "Mucormycosis", "C": "Candidiasis", "D": "Cryptococcosis"}, "r": "B", "e": {"correcta": "Mucormycosis (caused by Mucor and Rhizopus species) is an opportunistic fungal infection classically occurring in ketoacidotic diabetics and leukemic/immunocompromised patients; the fungi proliferate within blood vessel walls in the presence of excess glucose and ketones, invade tissue, and can penetrate the cribriform plate to reach the brain, causing rhinocerebral disease.", "incorrectas": {"A": "Aspergillosis classically causes invasive disease in neutropenic patients with septate hyphae branching at acute (45-degree) angles, and is associated with allergic bronchopulmonary aspergillosis and aspergillomas, but is not the classic ketoacidosis-associated rhinocerebral infection.", "C": "Candidiasis is an opportunistic yeast infection common in immunosuppressed or catheterized patients causing thrush, esophagitis, or candidemia, but it is not specifically linked to diabetic ketoacidosis with cribriform plate invasion.", "D": "Cryptococcosis, caused by Cryptococcus neoformans, classically causes meningitis in AIDS patients and is identified by India ink staining, not the vessel-invasive rhinocerebral picture of mucormycosis."}}}, {"id": "anking-parasitology-1162", "fuente": "anking", "tema": 22, "anki": "1402961972079", "q": "Which opportunistic fungal infection classically presents with rhinocerebral involvement and frontal lobe abscesses in immunocompromised patients?", "o": {"A": "Histoplasmosis", "B": "Coccidioidomycosis", "C": "Blastomycosis", "D": "Mucormycosis"}, "r": "D", "e": {"correcta": "Mucormycosis characteristically presents with rhinocerebral disease, including frontal lobe abscesses, due to angioinvasive fungal hyphae (Mucor and Rhizopus species) spreading from the nasal sinuses through the cribriform plate into brain tissue, typically in diabetic ketoacidosis or immunocompromised patients.", "incorrectas": {"A": "Histoplasmosis, caused by Histoplasma capsulatum, is endemic to the Ohio/Mississippi River valleys and classically causes pulmonary disease with intracellular yeast forms in macrophages, not rhinocerebral abscesses.", "B": "Coccidioidomycosis is endemic to the southwestern US and causes pulmonary infection with spherules containing endospores, not rhinocerebral fungal invasion.", "C": "Blastomycosis, endemic to the central and eastern US, causes pulmonary and cutaneous disease with broad-based budding yeast, not the angioinvasive rhinocerebral picture of mucormycosis."}}}, {"id": "anking-parasitology-1163", "fuente": "anking", "tema": 22, "anki": "1402962164915", "q": "An immunocompromised patient presents with headache, facial pain, and a black necrotic eschar on the face with possible cranial nerve involvement. Which opportunistic fungal infection is most consistent with this presentation?", "o": {"A": "Aspergillosis", "B": "Candidiasis", "C": "Mucormycosis", "D": "Pneumocystis pneumonia"}, "r": "C", "e": {"correcta": "Mucormycosis presents with headache, facial pain, and a characteristic black necrotic eschar due to angioinvasion and tissue infarction by nonseptate hyphae, with possible cranial nerve involvement as the infection spreads from the sinuses toward the orbit and brain.", "incorrectas": {"A": "Aspergillosis can also be angioinvasive in immunocompromised hosts, but its classic hyphae are septate and branch at acute angles, and it is not the classic cause of a black facial eschar with cribriform plate spread described here.", "B": "Candidiasis typically causes mucocutaneous infections (thrush, esophagitis) or candidemia in immunocompromised patients, not a necrotic facial eschar with cranial nerve involvement.", "D": "Pneumocystis pneumonia causes a diffuse interstitial pneumonia in immunocompromised (especially HIV/AIDS) patients, presenting with dyspnea and hypoxia, not facial necrosis or cranial nerve deficits."}}}, {"id": "anking-parasitology-1164", "fuente": "anking", "tema": 22, "anki": "1402962307146", "q": "Which opportunistic fungal genus is characterized by nonseptate (aseptate) hyphae branching at wide angles?", "o": {"A": "Aspergillus", "B": "Candida", "C": "Mucor", "D": "Cryptococcus"}, "r": "C", "e": {"correcta": "Mucor (along with Rhizopus) is characterized histologically by broad, ribbon-like, nonseptate hyphae that branch at wide angles (approximately 90 degrees), a key feature distinguishing the Mucorales from other invasive fungi on tissue biopsy.", "incorrectas": {"A": "Aspergillus is characterized by septate hyphae that branch at acute (45-degree) angles, the opposite morphologic pattern from the nonseptate, wide-angle branching of Mucor.", "B": "Candida species appear as budding yeasts with pseudohyphae, not the nonseptate true hyphae with wide-angle branching seen in Mucor.", "D": "Cryptococcus neoformans is a budding yeast surrounded by a polysaccharide capsule, visualized with India ink, and does not form hyphae at all."}}}, {"id": "anking-virology-1165", "fuente": "anking", "tema": 20, "anki": "1403140169070", "q": "What is the most common etiologic agent of infectious mononucleosis, presenting with fever, hepatosplenomegaly, pharyngitis, and lymphadenopathy?", "o": {"A": "Cytomegalovirus", "B": "Epstein-Barr virus", "C": "Human herpesvirus 6", "D": "HIV (acute retroviral syndrome)"}, "r": "B", "e": {"correcta": "Epstein-Barr virus (EBV) is the most common cause of infectious mononucleosis, a syndrome characterized by fever, hepatosplenomegaly, pharyngitis, and lymphadenopathy, resulting from EBV infection and proliferation of infected B cells followed by a robust cytotoxic T cell (atypical lymphocyte) response.", "incorrectas": {"A": "Cytomegalovirus can cause a heterophile-negative mononucleosis-like syndrome, but it is a less common cause than EBV, which is the classic and most frequent etiology of infectious mononucleosis.", "C": "Human herpesvirus 6 classically causes roseola infantum in young children, not the mononucleosis syndrome most commonly attributed to EBV.", "D": "Acute HIV infection can present with a mononucleosis-like illness (fever, lymphadenopathy, pharyngitis), but it is not the most common cause of classic infectious mononucleosis, which is EBV."}}}, {"id": "anking-virology-1166", "fuente": "anking", "tema": 20, "anki": "1403140255270", "q": "A teenager presents with fever, hepatosplenomegaly, pharyngitis, and prominent posterior cervical lymphadenopathy after primary EBV infection. What is this clinical syndrome called?", "o": {"A": "Mononucleosis", "B": "Roseola infantum", "C": "Scarlet fever", "D": "Toxoplasmosis"}, "r": "A", "e": {"correcta": "Infectious mononucleosis is the classic clinical complication of primary EBV infection, presenting with fever, pharyngitis, hepatosplenomegaly, and lymphadenopathy that is especially prominent in the posterior cervical chain. It results from a vigorous cytotoxic T-cell response against EBV-infected B cells rather than direct viral cytopathic effect.", "incorrectas": {"B": "Roseola infantum is caused by HHV-6, presenting in infants with high fever followed by a diffuse rash after the fever breaks, not the fever-pharyngitis-lymphadenopathy triad of EBV mononucleosis.", "C": "Scarlet fever is caused by erythrogenic toxin-producing group A Streptococcus and presents with a sandpaper-like rash and strawberry tongue, a distinct bacterial illness unrelated to EBV.", "D": "Toxoplasmosis can occasionally mimic mononucleosis with lymphadenopathy, but it is caused by a protozoan parasite and lacks the characteristic heterophile antibody response and Downey cells seen in EBV infection."}}}, {"id": "anking-virology-1167", "fuente": "anking", "tema": 20, "anki": "1403140461354", "q": "Which EBV-associated illness is often nicknamed the \"kissing disease\" because it is commonly transmitted via saliva among teens and young adults?", "o": {"A": "Herpangina", "B": "Mononucleosis", "C": "Oral hairy leukoplakia", "D": "Herpetic gingivostomatitis"}, "r": "B", "e": {"correcta": "Mononucleosis is called the \"kissing disease\" because EBV is spread through saliva, making close oral contact between adolescents and young adults a common route of transmission, which fits the peak incidence in this age group.", "incorrectas": {"A": "Herpangina is caused by coxsackievirus A and presents with painful vesicular lesions on the posterior oropharynx, a different disease from EBV mononucleosis.", "C": "Oral hairy leukoplakia is an EBV-related lesion but occurs specifically in immunocompromised patients (e.g., HIV) as white, non-scrapable plaques on the tongue, not the systemic mononucleosis syndrome.", "D": "Herpetic gingivostomatitis is caused by HSV-1, typically in young children, and presents with painful oral vesicles and ulcers, distinct from EBV-driven mononucleosis."}}}, {"id": "anking-virology-1168", "fuente": "anking", "tema": 20, "anki": "1403140508210", "q": "In which cell type does EBV establish latency after primary infection?", "o": {"A": "Macrophages", "B": "Epithelial cells", "C": "B cells", "D": "T cells"}, "r": "C", "e": {"correcta": "EBV infects and establishes lifelong latency in B lymphocytes, using them as a reservoir from which reactivation can occur. This B-cell tropism also underlies EBV's association with B-cell malignancies such as Burkitt and Hodgkin lymphoma.", "incorrectas": {"A": "Macrophages are not the site of EBV latency; CMV, by contrast, establishes latency broadly in mononuclear cells including macrophages, monocytes, and T cells.", "B": "Epithelial cells support EBV lytic replication (contributing to viral shedding in saliva) but are not the site of long-term latency, which is specific to B cells.", "D": "T cells are not the reservoir for EBV latency; interestingly, the atypical lymphocytes seen on smear in mononucleosis are reactive cytotoxic T cells responding to infected B cells, not infected cells themselves."}}}, {"id": "anking-virology-1169", "fuente": "anking", "tema": 20, "anki": "1403140583915", "q": "Which receptor does EBV use to gain entry into B cells?", "o": {"A": "CD4", "B": "CD21 (CR2)", "C": "CD55 (DAF)", "D": "ACE2"}, "r": "B", "e": {"correcta": "EBV binds CD21 (also known as CR2, the complement receptor for C3d) on the surface of B lymphocytes to gain entry, which is why EBV infection and its complications are restricted to B cells. A helpful mnemonic is \"you must be 21 to drink at the Epstein-Barr.\"", "incorrectas": {"A": "CD4 is the receptor used by HIV (in conjunction with CCR5/CXCR4 coreceptors) to enter helper T cells, not the receptor EBV uses to enter B cells.", "C": "CD55 (decay-accelerating factor) is used by some enteroviruses (e.g., echoviruses) as a receptor, and is unrelated to EBV's B-cell tropism.", "D": "ACE2 is the receptor exploited by SARS-CoV-2 to enter respiratory epithelial cells, an entirely different virus-receptor pairing from EBV and CD21."}}}, {"id": "anking-virology-1170", "fuente": "anking", "tema": 20, "anki": "1403140620392", "q": "Which herpesvirus causes atypical reactive lymphocytes (Downey cells) to appear on a peripheral blood smear during acute infection?", "o": {"A": "HSV-1", "B": "VZV", "C": "EBV", "D": "HHV-8"}, "r": "C", "e": {"correcta": "EBV infection produces atypical lymphocytes, or Downey cells, on peripheral smear during acute mononucleosis. Importantly, these atypical cells are not the EBV-infected B cells themselves but reactive CD8+ cytotoxic T cells mounting an immune response against the infected B cells.", "incorrectas": {"A": "HSV-1 typically causes localized vesicular lesions (gingivostomatitis, herpes labialis) or encephalitis, but is not classically associated with atypical lymphocytosis on peripheral smear.", "B": "VZV causes varicella (chickenpox) and zoster (shingles) with characteristic vesicular skin lesions, not the atypical reactive lymphocyte picture seen in EBV mononucleosis.", "D": "HHV-8 is associated with Kaposi sarcoma and primary effusion lymphoma, particularly in immunocompromised or HIV-positive patients, but does not cause the Downey cell picture characteristic of EBV."}}}, {"id": "anking-virology-1171", "fuente": "anking", "tema": 20, "anki": "1403140678717", "q": "Which diagnostic test detects heterophile antibodies by causing agglutination of sheep or horse red blood cells to confirm EBV infection?", "o": {"A": "Direct Coombs test", "B": "Monospot test", "C": "PPD skin test", "D": "VDRL test"}, "r": "B", "e": {"correcta": "The Monospot test detects heterophile antibodies produced during EBV infection, which cross-react with and agglutinate sheep or horse red blood cells; a positive agglutination result supports the diagnosis of EBV-related mononucleosis.", "incorrectas": {"A": "The direct Coombs test detects antibodies or complement bound directly to a patient's own RBCs, used to diagnose autoimmune hemolytic anemia, not EBV infection.", "C": "The PPD (tuberculin) skin test evaluates delayed-type hypersensitivity to Mycobacterium tuberculosis antigens and has nothing to do with heterophile antibody detection.", "D": "The VDRL test detects non-treponemal antibodies (against cardiolipin) used for syphilis screening, an entirely different antigen-antibody system from EBV heterophile antibodies."}}}, {"id": "anking-virology-1172", "fuente": "anking", "tema": 20, "anki": "1403140742833", "q": "The Monospot test detects heterophile antibodies produced in the setting of which infection, causing agglutination of sheep or horse RBCs?", "o": {"A": "CMV", "B": "EBV", "C": "HSV-2", "D": "HHV-6"}, "r": "B", "e": {"correcta": "The Monospot test is specific for the heterophile antibodies generated during acute EBV infection; these antibodies are not directed against EBV antigens themselves but happen to cross-react with sheep or horse erythrocyte antigens, producing visible agglutination.", "incorrectas": {"A": "CMV can cause a mononucleosis-like illness clinically identical to EBV, but it does NOT generate heterophile antibodies, so the Monospot test is classically negative in CMV mononucleosis — a key distinguishing feature on boards.", "C": "HSV-2 causes genital herpes with painful vesicular/ulcerative lesions and is diagnosed via viral culture, PCR, or serology, not the heterophile antibody-based Monospot test.", "D": "HHV-6 causes roseola infantum in young children and is not associated with heterophile antibody production or a positive Monospot test."}}}, {"id": "anking-neoplasia-1173", "fuente": "anking", "tema": 14, "anki": "1403140899061", "q": "Which herpesvirus is most strongly associated with the development of Hodgkin lymphoma?", "o": {"A": "CMV", "B": "HHV-8", "C": "EBV", "D": "HSV-2"}, "r": "C", "e": {"correcta": "EBV is strongly linked to classic Hodgkin lymphoma, particularly the mixed-cellularity subtype, where viral genome and EBV latent proteins (such as EBNA and LMP-1) can be detected within the malignant Reed-Sternberg cells, driving their proliferation and survival.", "incorrectas": {"A": "CMV establishes latency in mononuclear cells and causes disease like retinitis and colitis in immunocompromised hosts, but it is not an oncogenic virus linked to Hodgkin lymphoma.", "B": "HHV-8 is the causative agent of Kaposi sarcoma and primary effusion lymphoma (a B-cell non-Hodgkin lymphoma), not classic Hodgkin lymphoma.", "D": "HSV-2 causes genital herpes and has no established role in lymphomagenesis; it is not one of the EBV-associated oncogenic mechanisms tested on boards."}}}, {"id": "anking-neoplasia-1174", "fuente": "anking", "tema": 14, "anki": "1403140915952", "q": "Endemic (African) Burkitt lymphoma, characterized by a c-myc translocation, is most strongly associated with which herpesvirus?", "o": {"A": "HHV-8", "B": "CMV", "C": "EBV", "D": "HSV-1"}, "r": "C", "e": {"correcta": "EBV is strongly associated with endemic (African) Burkitt lymphoma, which classically involves a t(8;14) translocation placing c-myc under control of the immunoglobulin heavy chain enhancer, driving uncontrolled B-cell proliferation; the \"starry sky\" appearance on histology reflects macrophages engulfing apoptotic tumor cells.", "incorrectas": {"A": "HHV-8 causes Kaposi sarcoma and primary effusion lymphoma, not Burkitt lymphoma, which is specifically tied to EBV and the c-myc translocation.", "B": "CMV is not an oncogenic herpesvirus associated with Burkitt lymphoma; its clinical relevance centers on congenital infection and disease in immunocompromised hosts.", "D": "HSV-1 causes oral/orolabial lesions and encephalitis but has no established role in Burkitt lymphoma pathogenesis, unlike EBV."}}}, {"id": "anking-neoplasia-1175", "fuente": "anking", "tema": 14, "anki": "1403140930710", "q": "Nasopharyngeal carcinoma, especially common in East Asian populations, is most strongly associated with which virus?", "o": {"A": "HPV", "B": "HHV-8", "C": "HBV", "D": "EBV"}, "r": "D", "e": {"correcta": "EBV is closely linked to nasopharyngeal carcinoma, which shows a markedly increased incidence in East Asian and certain African populations, reflecting a combination of viral, genetic, and environmental (e.g., dietary nitrosamine) factors.", "incorrectas": {"A": "HPV is oncogenic for cervical, anal, oropharyngeal, and penile squamous cell carcinomas via E6/E7 oncoproteins, but it is not the classic virus linked to nasopharyngeal carcinoma.", "B": "HHV-8 causes Kaposi sarcoma and primary effusion lymphoma, particularly in immunosuppressed patients, and is unrelated to nasopharyngeal carcinoma.", "C": "HBV is associated with hepatocellular carcinoma through chronic liver inflammation and integration into the host genome, not nasopharyngeal carcinoma."}}}, {"id": "anking-virology-1176", "fuente": "anking", "tema": 20, "anki": "1403140946098", "q": "A young adult presents with a mononucleosis-like illness (fever, pharyngitis, lymphadenopathy) but has a negative Monospot test. Which herpesvirus is the most likely cause?", "o": {"A": "CMV", "B": "HSV-1", "C": "VZV", "D": "HHV-6"}, "r": "A", "e": {"correcta": "CMV can cause a mononucleosis syndrome clinically similar to EBV but does not induce heterophile antibody production, so the Monospot test is negative; diagnosis instead relies on CMV-specific serology or PCR.", "incorrectas": {"B": "HSV-1 causes oral lesions and encephalitis rather than a mononucleosis-like systemic febrile illness, and is not typically implicated in Monospot-negative mononucleosis presentations.", "C": "VZV causes chickenpox and shingles with characteristic vesicular rashes, not a mononucleosis-like syndrome, making it an unlikely cause here.", "D": "HHV-6 classically causes roseola infantum in infants and young children, not a mononucleosis-like illness in young adults with a negative heterophile antibody test."}}}, {"id": "anking-virology-1177", "fuente": "anking", "tema": 20, "anki": "1403141234206", "q": "Which herpesvirus classically causes retinitis in immunocompromised patients (e.g., advanced HIV)?", "o": {"A": "HSV-2", "B": "VZV", "C": "CMV", "D": "EBV"}, "r": "C", "e": {"correcta": "CMV causes retinitis in severely immunocompromised patients, a mnemonic being \"sight-o-megalovirus.\" It presents with characteristic fluffy, granular retinal lesions and hemorrhages (\"cottage cheese and ketchup\" appearance) on funduscopic exam.", "incorrectas": {"A": "HSV-2 primarily causes genital ulcerative disease and neonatal herpes, and while HSV can rarely cause acute retinal necrosis, it is not the classic cause of retinitis in HIV/AIDS patients tested on boards.", "B": "VZV can cause herpes zoster ophthalmicus involving the eye via the nasociliary nerve, but this is a distinct clinical entity from the diffuse CMV retinitis of profound immunosuppression.", "D": "EBV is associated with mononucleosis and B-cell malignancies, not retinitis; its ocular associations are not a major testable feature."}}}, {"id": "anking-neoplasia-1178", "fuente": "anking", "tema": 14, "anki": "1403141269124", "q": "\"Owl's eye\" intranuclear inclusions in infected cells are a characteristic histologic finding of infection with which virus?", "o": {"A": "HSV-1", "B": "EBV", "C": "CMV", "D": "Adenovirus"}, "r": "C", "e": {"correcta": "CMV produces characteristic large cells with basophilic intranuclear inclusions surrounded by a clear halo, described as \"owl's eye\" inclusions, seen in infected tissues such as retina, GI mucosa, lung, and placenta. This is distinct from the owl's-eye binucleate Reed-Sternberg cells of Hodgkin lymphoma, which are associated with EBV.", "incorrectas": {"A": "HSV-1 produces multinucleated giant cells with Cowdry A intranuclear inclusions (as seen in Tzanck smear), a different histologic pattern from CMV's owl's eye inclusions.", "B": "EBV is associated with Reed-Sternberg cells in Hodgkin lymphoma, which have an owl's-eye binucleate appearance, but this is a distinct histologic entity from the viral cytopathic owl's eye inclusion bodies caused directly by CMV infection.", "D": "Adenovirus classically causes smudge cells in infected respiratory or conjunctival epithelium, not the owl's eye inclusions characteristic of CMV."}}}, {"id": "anking-virology-1179", "fuente": "anking", "tema": 20, "anki": "1403141305744", "q": "In contrast to EBV, which establishes latency only in B cells, CMV establishes latency in which broader group of cells?", "o": {"A": "Neurons", "B": "Mononuclear cells (T cells, B cells, macrophages)", "C": "Hepatocytes", "D": "Skeletal muscle cells"}, "r": "B", "e": {"correcta": "CMV establishes latency broadly across mononuclear cells, including T cells, B cells, and macrophages, in contrast to EBV, which is restricted to latency in B cells alone. This broader cellular tropism helps explain CMV's diverse disease manifestations across multiple organ systems in immunocompromised hosts.", "incorrectas": {"A": "Neurons are the site of latency for herpes simplex viruses (in sensory ganglia) and VZV (in dorsal root or trigeminal ganglia), not CMV.", "C": "Hepatocytes can be infected during acute CMV hepatitis but are not the reservoir for CMV latency; latency resides in mononuclear cell lineages.", "D": "Skeletal muscle cells are not a site of herpesvirus latency for any of the classic herpesviruses tested on boards."}}}, {"id": "anking-virology-1180", "fuente": "anking", "tema": 20, "anki": "1403149724209", "q": "Which EBV serologic antigen appears during active, productive (lytic) infection?", "o": {"A": "Epstein-Barr Nuclear Antigen (EBNA)", "B": "Viral Capsid Antigen (VCA)", "C": "Latent Membrane Protein (LMP)", "D": "Early Antigen (EA) only in latency"}, "r": "B", "e": {"correcta": "Viral capsid antigen (VCA) IgM and IgG antibodies rise during active, productive EBV infection and are used clinically to diagnose acute or recent EBV infection, since VCA is expressed as new viral particles are assembled during lytic replication.", "incorrectas": {"A": "EBNA (Epstein-Barr nuclear antigen) is expressed during latent infection, not active lytic replication, and antibodies to it typically appear later, marking past infection or chronic latency.", "C": "Latent membrane protein (LMP-1) is a latency-associated oncoprotein that promotes B-cell proliferation and survival, expressed during latency rather than active lytic infection.", "D": "Early antigen (EA) is actually associated with active lytic replication, similar to VCA, but the answer specifically asked for the classic marker of active/productive infection, which is VCA; EA is not restricted to or defined as a latency marker."}}}, {"id": "anking-neoplasia-1181", "fuente": "anking", "tema": 14, "anki": "1403149942402", "q": "Which EBV antigen is expressed during latent infection and is implicated in EBV-associated malignancies?", "o": {"A": "Viral Capsid Antigen (VCA)", "B": "Early Antigen (EA)", "C": "Epstein-Barr Nuclear Antigen (EBNA)", "D": "gp350"}, "r": "C", "e": {"correcta": "Epstein-Barr Nuclear Antigen (EBNA) is expressed during latent EBV infection and plays a role in maintaining the viral episome and driving B-cell immortalization, contributing to the pathogenesis of EBV-associated malignancies like Hodgkin and Burkitt lymphoma.", "incorrectas": {"A": "VCA is a marker of active, productive (lytic) EBV infection used to diagnose acute mononucleosis, not a latency-associated protein implicated in oncogenesis.", "B": "Early antigen (EA) is also expressed during active lytic replication and indicates recent or reactivated infection, rather than the latent state associated with malignant transformation.", "D": "gp350 is a viral envelope glycoprotein that mediates binding to the CD21 receptor on B cells during viral entry; it is not the classic serologic marker of latency used to diagnose EBV-driven lymphomas."}}}, {"id": "anking-neoplasia-1182", "fuente": "anking", "tema": 14, "anki": "1403149965943", "q": "Which EBV latent antigen contributes to the pathogenesis of EBV-associated Hodgkin and Burkitt lymphoma?", "o": {"A": "Viral Capsid Antigen (VCA)", "B": "Epstein-Barr Nuclear Antigen (EBNA)", "C": "Heterophile antibody", "D": "p24 antigen"}, "r": "B", "e": {"correcta": "EBNA is found in EBV-infected cells during latency and helps drive the immortalization and proliferation of B cells that underlies EBV's oncogenic potential in both Hodgkin lymphoma and Burkitt lymphoma.", "incorrectas": {"A": "VCA is a lytic-phase antigen used to diagnose acute mononucleosis, not a latency-associated protein tied to lymphomagenesis.", "C": "The heterophile antibody is a diagnostic serologic marker (detected by the Monospot test) generated during EBV infection, not a viral protein driving oncogenic transformation.", "D": "p24 is a structural capsid antigen of HIV used in HIV diagnostic testing, entirely unrelated to EBV antigens or lymphomagenesis."}}}, {"id": "anking-virology-1183", "fuente": "anking", "tema": 20, "anki": "1403292900993", "q": "Which herpesvirus causes retinitis in HIV patients that presents with cotton-wool spots (and can also cause esophagitis)?", "o": {"A": "HSV-1", "B": "VZV", "C": "CMV", "D": "HHV-8"}, "r": "C", "e": {"correcta": "CMV causes retinitis in advanced HIV/AIDS, presenting with cotton-wool spots, hemorrhages, and granular retinal lesions on funduscopic exam; CMV can also cause esophagitis (typically with large, shallow linear ulcers) in the same immunocompromised population.", "incorrectas": {"A": "HSV-1 can cause esophagitis with small, deep, punched-out ulcers, distinguishable from CMV's large linear ulcers, but is not the classic cause of cotton-wool spot retinitis in HIV patients.", "B": "VZV causes herpes zoster and, rarely, acute retinal necrosis, but this presents differently (rapidly progressive necrotizing retinitis) and is not the classic cotton-wool spot pattern of CMV retinitis.", "D": "HHV-8 causes Kaposi sarcoma, which can appear as violaceous skin or mucosal lesions in HIV patients, but does not cause retinitis or esophagitis."}}}, {"id": "anking-virology-1184", "fuente": "anking", "tema": 20, "anki": "1403293081180", "q": "CMV retinitis in HIV-positive patients classically occurs when the CD4+ count falls below what threshold?", "o": {"A": "< 500 cells/mm3", "B": "< 200 cells/mm3", "C": "< 100 cells/mm3", "D": "< 50 cells/mm3"}, "r": "D", "e": {"correcta": "CMV retinitis is a late, AIDS-defining opportunistic infection that classically occurs when the CD4+ T-cell count drops below 50 cells/mm3, reflecting severe cell-mediated immunodeficiency that allows reactivation of latent CMV.", "incorrectas": {"A": "A CD4+ count below 500 cells/mm3 is associated with earlier opportunistic risks such as oral candidiasis or reactivation TB, not the severe immunosuppression required for CMV retinitis.", "B": "Below 200 cells/mm3 marks the threshold for AIDS-defining illnesses like PCP pneumonia, but CMV retinitis specifically requires even deeper immunosuppression, generally below 50 cells/mm3.", "C": "A count below 100 cells/mm3 is associated with risks like toxoplasmosis encephalitis, but the classic CMV retinitis threshold taught on boards is lower, at less than 50 cells/mm3."}}}, {"id": "anking-virology-1185", "fuente": "anking", "tema": 20, "anki": "1403294217650", "q": "In an HIV-positive patient with a focal, solitary brain lesion (as opposed to the typically multiple ring-enhancing lesions of toxoplasmosis), which EBV-associated malignancy should be suspected?", "o": {"A": "Glioblastoma multiforme", "B": "Primary CNS (B-cell) lymphoma", "C": "Metastatic melanoma", "D": "Meningioma"}, "r": "B", "e": {"correcta": "Primary CNS lymphoma, a B-cell non-Hodgkin lymphoma strongly associated with EBV, often presents as a focal or solitary lesion in immunocompromised (especially HIV-positive) patients, which helps distinguish it from toxoplasmosis encephalitis, which more commonly produces multiple ring-enhancing lesions.", "incorrectas": {"A": "Glioblastoma multiforme is a primary glial tumor unrelated to EBV or HIV status, typically presenting with a butterfly-shaped, necrotic, ring-enhancing lesion crossing the corpus callosum, not the pattern used to distinguish it from toxoplasmosis in HIV patients.", "C": "Metastatic melanoma to the brain is not classically associated with EBV or specifically linked to the HIV-positive population in the way primary CNS lymphoma is.", "D": "Meningioma arises from arachnoid cap cells, is typically not EBV-associated, and is not part of the differential for focal brain lesions in HIV patients versus toxoplasmosis."}}}, {"id": "anking-gastrointestinal-pathology-1186", "fuente": "anking", "tema": 10, "anki": "1403295597194", "q": "In HIV-positive patients, HPV infection most commonly leads to which cancer, often occurring at the anus (in men who have sex with men) or the cervix?", "o": {"A": "Adenocarcinoma", "B": "Squamous cell carcinoma", "C": "Basal cell carcinoma", "D": "Kaposi sarcoma"}, "r": "B", "e": {"correcta": "HPV-driven squamous cell carcinoma is the most common HPV-associated cancer in HIV-positive patients (accounting for roughly 80% of such cancers), commonly arising at the anus in men who have sex with men or at the cervix in women, via HPV E6/E7 oncoprotein inactivation of p53 and Rb.", "incorrectas": {"A": "Adenocarcinoma arises from glandular epithelium and is not the characteristic HPV-driven cancer type; HPV-associated malignancies are predominantly squamous cell in nature.", "C": "Basal cell carcinoma is primarily driven by UV radiation exposure affecting basal keratinocytes, and is not part of the HPV oncogenic pathway.", "D": "Kaposi sarcoma is caused by HHV-8, not HPV, and presents as vascular, violaceous skin or mucosal lesions rather than squamous cell carcinoma."}}}, {"id": "anking-respiratory-pathology-1187", "fuente": "anking", "tema": 17, "anki": "1403296022011", "q": "Which herpesvirus is associated with interstitial pneumonia in HIV-positive patients, often accompanied by characteristic owl's eye inclusion bodies?", "o": {"A": "HSV-1", "B": "VZV", "C": "CMV", "D": "HHV-6"}, "r": "C", "e": {"correcta": "CMV causes interstitial pneumonia in immunocompromised patients, including those with advanced HIV, and infected cells show characteristic large owl's eye intranuclear inclusions on histology, reflecting active viral replication within the lung parenchyma.", "incorrectas": {"A": "HSV-1 can rarely cause pneumonia in severely immunocompromised hosts, but it is not the classic cause of interstitial pneumonia with owl's eye inclusions tested for HIV patients.", "B": "VZV can cause varicella pneumonia, particularly in adults or immunocompromised patients, but this presents differently and is not associated with owl's eye inclusion bodies.", "D": "HHV-6 causes roseola infantum and is not classically implicated in interstitial pneumonia or owl's eye inclusions in HIV-positive adults."}}}, {"id": "anking-clinical-bacteriology-1188", "fuente": "anking", "tema": 21, "anki": "1403297162366", "q": "Staphylococcus epidermidis, a common cause of prosthetic device and catheter infections, is normally found as flora at which body site?", "o": {"A": "Skin", "B": "Nasopharynx", "C": "Large intestine", "D": "Vagina"}, "r": "A", "e": {"correcta": "Staphylococcus epidermidis is a coagulase-negative staphylococcus that is normal skin flora, which explains its propensity to contaminate blood cultures and infect indwelling devices such as prosthetic joints, heart valves, and catheters via biofilm formation.", "incorrectas": {"B": "The nasopharynx is the classic carriage site for Staphylococcus aureus (as well as organisms like Neisseria meningitidis), not the primary niche for S. epidermidis.", "C": "The large intestine harbors organisms such as Bacteroides fragilis and E. coli as dominant flora, not S. epidermidis, which is a skin commensal.", "D": "The vagina's normal flora is dominated by Lactobacillus species, not S. epidermidis, which resides on the skin surface."}}}, {"id": "anking-clinical-bacteriology-1189", "fuente": "anking", "tema": 21, "anki": "1403301422588", "q": "Staphylococcus aureus food poisoning, caused by preformed enterotoxins, is classically linked to consumption of which food sources?", "o": {"A": "Reheated rice", "B": "Undercooked poultry", "C": "Meats, mayonnaise, and custard (cream-based foods)", "D": "Raw shellfish"}, "r": "C", "e": {"correcta": "S. aureus food poisoning results from ingestion of preformed heat-stable enterotoxins present in improperly refrigerated meats, mayonnaise, and cream/custard-based foods, causing rapid-onset (within hours) nausea and vomiting even though the bacteria itself may be killed by cooking.", "incorrectas": {"B": "Undercooked poultry is the classic food source associated with Salmonella and Campylobacter infections, which cause diarrheal illness with a longer incubation period, not the rapid preformed-toxin illness of S. aureus.", "A": "Reheated rice is classically associated with Bacillus cereus food poisoning, whose heat-stable emetic toxin causes a similarly rapid vomiting illness, but the specific food-source pairing tested for S. aureus is meats/mayonnaise/custard.", "D": "Raw shellfish is classically linked to Vibrio species (V. parahaemolyticus, V. vulnificus) causing gastroenteritis or wound infections, not S. aureus preformed toxin food poisoning."}}}, {"id": "anking-virology-1190", "fuente": "anking", "tema": 20, "anki": "1403393464088", "q": "A newborn presents with sensorineural hearing loss, seizures, petechial rash, and a \"blueberry muffin\" appearance. Which TORCH pathogen is most likely responsible?", "o": {"A": "Toxoplasma gondii", "B": "Rubella virus", "C": "CMV", "D": "Treponema pallidum"}, "r": "C", "e": {"correcta": "Congenital CMV infection is the most common congenital viral infection and classically presents with sensorineural hearing loss, seizures, periventricular calcifications, petechiae, and a \"blueberry muffin\" rash from extramedullary hematopoiesis in the skin.", "incorrectas": {"A": "Congenital toxoplasmosis presents with the classic triad of chorioretinitis, hydrocephalus, and diffuse intracranial calcifications, a distinct pattern from CMV's periventricular calcifications and hearing loss.", "B": "Congenital rubella syndrome classically causes cataracts, a patent ductus arteriosus (or other cardiac defects), and sensorineural deafness (the classic triad), a different constellation of calcification and rash than CMV.", "D": "Congenital syphilis presents with findings like saddle nose, saber shins, Hutchinson teeth, and interstitial keratitis, not the blueberry muffin rash and periventricular calcifications characteristic of CMV."}}}, {"id": "anking-virology-1191", "fuente": "anking", "tema": 20, "anki": "1403398772648", "q": "Condyloma acuminata (genital warts) are most commonly caused by which HPV serotypes?", "o": {"A": "HPV 16, 18", "B": "HPV 6, 11", "C": "HPV 31, 33", "D": "HPV 1, 2"}, "r": "B", "e": {"correcta": "HPV serotypes 6 and 11 are the low-risk strains responsible for condyloma acuminata (genital warts), causing benign proliferative squamous lesions without the high oncogenic potential of other HPV subtypes.", "incorrectas": {"A": "HPV 16 and 18 are the high-risk oncogenic serotypes responsible for cervical, anal, and oropharyngeal squamous cell carcinomas via E6/E7 oncoproteins, not genital warts.", "C": "HPV 31 and 33 are additional high-risk oncogenic serotypes associated with cervical dysplasia and carcinoma, not the benign wart-causing low-risk strains.", "D": "HPV 1 and 2 cause common cutaneous warts (verruca vulgaris) on the skin, such as on the hands, rather than genital condyloma acuminata."}}}, {"id": "anking-clinical-bacteriology-1192", "fuente": "anking", "tema": 21, "anki": "1403399191015", "q": "A sexually active patient presents with urethritis, cervicitis or prostatitis, and a white, creamy purulent discharge. Which organism is the most likely cause?", "o": {"A": "Chlamydia trachomatis", "B": "Neisseria gonorrhoeae", "C": "Trichomonas vaginalis", "D": "Gardnerella vaginalis"}, "r": "B", "e": {"correcta": "Neisseria gonorrhoeae is a gram-negative diplococcus that classically causes acute, purulent urethritis, cervicitis, or prostatitis with a thick, creamy discharge, reflecting the intense neutrophilic inflammatory response it provokes.", "incorrectas": {"A": "Chlamydia trachomatis (serotypes D-K) causes a similar sexually transmitted infection but tends to be subacute with more subtle or absent discharge, often going undiagnosed compared to the overt purulent discharge of gonorrhea.", "C": "Trichomonas vaginalis causes a frothy, greenish-yellow, malodorous vaginal discharge with vulvovaginal irritation (\"strawberry cervix\"), a different presentation from the purulent urethral discharge of gonorrhea.", "D": "Gardnerella vaginalis is associated with bacterial vaginosis, presenting with a thin, grayish, fishy-smelling discharge, not the purulent discharge and urethritis/cervicitis pattern of gonorrhea."}}}, {"id": "anking-clinical-bacteriology-1193", "fuente": "anking", "tema": 21, "anki": "1403399484734", "q": "What is the causative organism of syphilis?", "o": {"A": "Borrelia burgdorferi", "B": "Leptospira interrogans", "C": "Treponema pallidum", "D": "Chlamydia trachomatis"}, "r": "C", "e": {"correcta": "Syphilis is caused by Treponema pallidum, a spirochete that cannot be cultured on standard media and is instead visualized via dark-field microscopy; it progresses through primary (chancre), secondary (rash, condyloma lata), and tertiary (gummas, neurosyphilis, aortitis) stages if untreated.", "incorrectas": {"A": "Borrelia burgdorferi is the spirochete responsible for Lyme disease, transmitted by Ixodes ticks and presenting with erythema migrans, a distinct organism and disease from syphilis.", "B": "Leptospira interrogans causes leptospirosis, transmitted via contact with water contaminated by animal urine, presenting with fever, jaundice, and conjunctival suffusion, unrelated to syphilis.", "D": "Chlamydia trachomatis causes STIs such as urethritis, cervicitis, and lymphogranuloma venereum, but is an obligate intracellular bacterium distinct from the spirochete that causes syphilis."}}}, {"id": "anking-reproductive-system-pathology-1194", "fuente": "anking", "tema": 8, "anki": "1403402957857", "q": "Which organism frequently causes subacute pelvic inflammatory disease (PID) that often goes undiagnosed due to its milder presentation?", "o": {"A": "Neisseria gonorrhoeae", "B": "Chlamydia trachomatis serotypes D-K", "C": "Gardnerella vaginalis", "D": "Escherichia coli"}, "r": "B", "e": {"correcta": "Chlamydia trachomatis serotypes D-K cause a subacute, often clinically silent form of PID, which allows the infection to persist and progress undetected, increasing the risk of long-term complications like tubal scarring, infertility, and ectopic pregnancy.", "incorrectas": {"A": "Neisseria gonorrhoeae classically causes acute PID with prominent purulent discharge and pain, a more overt presentation than the subacute, often subtle disease caused by chlamydia.", "C": "Gardnerella vaginalis is associated with bacterial vaginosis, not PID; it is not a classic cause of ascending genital tract infection into the uterus and fallopian tubes.", "D": "Escherichia coli can occasionally be implicated in genitourinary infections but is not the classic sexually transmitted cause of subacute PID; that role belongs to Chlamydia trachomatis."}}}, {"id": "anking-reproductive-system-pathology-1195", "fuente": "anking", "tema": 8, "anki": "1403402982827", "q": "Which organism classically causes an acute presentation of pelvic inflammatory disease (PID)?", "o": {"A": "Chlamydia trachomatis", "B": "Neisseria gonorrhoeae", "C": "Mycoplasma genitalium", "D": "Ureaplasma urealyticum"}, "r": "B", "e": {"correcta": "Neisseria gonorrhoeae classically causes acute PID with sudden onset of pelvic pain, fever, and purulent cervical discharge, in contrast to the subacute, often silent presentation caused by Chlamydia trachomatis; both organisms can lead to scarring, infertility, and ectopic pregnancy.", "incorrectas": {"A": "Chlamydia trachomatis is the classic cause of subacute PID, which presents more insidiously and is frequently underdiagnosed compared to the acute presentation of gonorrhea.", "C": "Mycoplasma genitalium is an emerging cause of urethritis and cervicitis but is not the classic organism tested for acute PID on USMLE Step 1, which is gonorrhea.", "D": "Ureaplasma urealyticum is associated with nongonococcal urethritis and neonatal infections but is not the primary organism associated with acute PID in standard teaching."}}}, {"id": "anking-reproductive-system-pathology-1196", "fuente": "anking", "tema": 8, "anki": "1403404030220", "q": "A patient presents with purulent cervical discharge, pelvic pain, and adnexal tenderness caused by ascending infection with Chlamydia trachomatis or Neisseria gonorrhoeae. What is this condition called?", "o": {"A": "Endometriosis", "B": "Pelvic Inflammatory Disease (PID)", "C": "Tubo-ovarian torsion", "D": "Bacterial vaginosis"}, "r": "B", "e": {"correcta": "Pelvic inflammatory disease (also called salpingo-oophoritis) results from ascending infection of the upper female genital tract, most commonly by Neisseria gonorrhoeae (acute) or Chlamydia trachomatis (subacute), presenting with purulent cervical discharge, pelvic pain, and adnexal tenderness, and can progress to tubal scarring, infertility, or ectopic pregnancy.", "incorrectas": {"A": "Endometriosis involves ectopic endometrial tissue outside the uterus, causing cyclic pelvic pain and infertility, but it is not an infectious process caused by gonorrhea or chlamydia.", "C": "Tubo-ovarian torsion is a surgical emergency involving twisting of the ovary and fallopian tube on its vascular pedicle, causing acute severe pain, but is a mechanical event unrelated to bacterial infection.", "D": "Bacterial vaginosis is caused by an overgrowth of Gardnerella vaginalis and anaerobes with a thin, fishy-smelling discharge, but it is a vaginal (not ascending upper genital tract) infection and does not represent PID."}}}, {"id": "anking-clinical-bacteriology-1197", "fuente": "anking", "tema": 21, "anki": "1403404584966", "q": "A gram-negative organism causing nosocomial infections is associated with exposure to respiratory therapy equipment. Which organism is this?", "o": {"A": "Klebsiella pneumoniae", "B": "Pseudomonas aeruginosa", "C": "Acinetobacter baumannii", "D": "Serratia marcescens"}, "r": "B", "e": {"correcta": "Pseudomonas aeruginosa is a gram-negative rod notorious for nosocomial infections, with respiratory therapy equipment, burns, and water sources as classic risk factors (mnemonic: Pseudomonas \"air\"-uginosa for its association with air/ventilator equipment and burns).", "incorrectas": {"A": "Klebsiella pneumoniae is classically associated with aspiration pneumonia in alcoholics and healthcare-associated UTIs, presenting with thick, bloody \"currant jelly\" sputum, rather than respiratory equipment exposure specifically.", "C": "Acinetobacter baumannii is another important nosocomial gram-negative pathogen, often linked to ventilator-associated pneumonia in ICU settings, but the classic mnemonic and testable association with respiratory equipment/burns belongs to Pseudomonas.", "D": "Serratia marcescens can cause nosocomial infections and is notable for producing a red pigment, but it is not the organism classically linked to respiratory therapy equipment exposure in the way Pseudomonas is."}}}, {"id": "anking-virology-1198", "fuente": "anking", "tema": 20, "anki": "1403412017761", "q": "Which herpesvirus is a classic cause of infection in organ transplant recipients due to reactivation under immunosuppression?", "o": {"A": "EBV", "B": "HSV-2", "C": "CMV", "D": "HHV-7"}, "r": "C", "e": {"correcta": "CMV is a major pathogen in organ transplant recipients, where immunosuppressive therapy allows reactivation of latent virus (or transmission from a seropositive donor organ), leading to complications such as CMV pneumonitis, colitis, hepatitis, and retinitis.", "incorrectas": {"A": "EBV can reactivate in transplant recipients and is linked to post-transplant lymphoproliferative disorder, but the classic, most frequently tested herpesvirus complication of transplantation is CMV infection/disease.", "B": "HSV-2 typically causes genital lesions and can reactivate under immunosuppression, but it is not the classic organism associated with the broad systemic transplant complications (pneumonitis, retinitis, colitis) attributed to CMV.", "D": "HHV-7, like HHV-6, is associated with roseola-like illness and is not a classic, heavily tested pathogen in the transplant population compared to CMV."}}}, {"id": "anking-clinical-bacteriology-1199", "fuente": "anking", "tema": 21, "anki": "1403466367536", "q": "A patient develops watery diarrhea and colonic pseudomembranes after a course of ampicillin. Which process best explains this complication?", "o": {"A": "Direct mucosal toxicity of ampicillin", "B": "Overgrowth of Clostridioides difficile after disruption of normal flora", "C": "IgE-mediated hypersensitivity to ampicillin", "D": "Ampicillin-induced villous atrophy"}, "r": "B", "e": {"correcta": "Pseudomembranous colitis results from antibiotic-induced disruption of normal colonic flora (classically by ampicillin, clindamycin, or fluoroquinolones), permitting overgrowth of toxin-producing Clostridioides difficile, whose toxins A and B damage colonic mucosa and produce characteristic pseudomembranes.", "incorrectas": {"A": "Ampicillin itself is not directly cytotoxic to colonic mucosa; the pathology arises indirectly through elimination of protective flora that normally suppress C. difficile overgrowth.", "C": "An IgE-mediated hypersensitivity reaction to ampicillin would present as an allergic reaction (urticaria, anaphylaxis), not colitis with pseudomembrane formation, which is a toxin-mediated infectious process.", "D": "Villous atrophy is characteristic of celiac disease affecting the small intestine, an autoimmune process distinct from the toxin-mediated colonic mucosal damage seen in C. difficile colitis."}}}, {"id": "anking-antimicrobials-1200", "fuente": "anking", "tema": 4, "anki": "1403469569805", "q": "Which third-generation cephalosporin is commonly used to treat both meningitis and gonorrhea?", "o": {"A": "Cefazolin", "B": "Cefepime", "C": "Ceftriaxone", "D": "Cefaclor"}, "r": "C", "e": {"correcta": "Ceftriaxone is a third-generation cephalosporin with excellent CNS penetration and broad gram-negative coverage, making it a first-line agent for bacterial meningitis (including N. meningitidis and S. pneumoniae) as well as the standard single-dose treatment for gonorrhea caused by Neisseria gonorrhoeae.", "incorrectas": {"A": "Cefazolin is a first-generation cephalosporin used mainly for surgical prophylaxis and skin/soft tissue infections due to gram-positive cocci; it has poor CNS penetration and is not used for meningitis or gonorrhea.", "B": "Cefepime is a fourth-generation cephalosporin with broad gram-negative (including Pseudomonas) and gram-positive coverage, often used in febrile neutropenia or hospital-acquired infections, but it is not the classic first-line choice for gonorrhea.", "D": "Cefaclor is a second-generation oral cephalosporin used for respiratory and ear infections with modest gram-negative coverage; it lacks the CNS penetration and reliable anti-gonococcal activity of ceftriaxone."}}}, {"id": "anking-antimicrobials-1201", "fuente": "anking", "tema": 4, "anki": "1403557829724", "q": "Which of the following best describes the primary clinical use of tetracycline antibiotics?", "o": {"A": "First-line therapy for Borrelia burgdorferi, Mycoplasma pneumoniae, and intracellular organisms such as Rickettsia and Chlamydiae", "B": "First-line therapy for atypical mycobacterial infections and biofilm-associated prosthetic joint infections", "C": "First-line therapy for anaerobic infections below the diaphragm, such as diverticulitis and pelvic abscesses", "D": "First-line therapy for methicillin-resistant Staphylococcus aureus bacteremia"}, "r": "A", "e": {"correcta": "Tetracyclines (e.g., doxycycline, minocycline) are protein synthesis inhibitors that accumulate intracellularly, making them well suited to treat intracellular and atypical organisms: Borrelia burgdorferi (Lyme disease), Mycoplasma pneumoniae (atypical pneumonia), and obligate intracellular bacteria like Rickettsia and Chlamydiae. They are also used for acne due to their anti-inflammatory and antibacterial effects against Cutibacterium acnes.", "incorrectas": {"B": "Atypical mycobacteria and prosthetic joint biofilm infections are typically managed with macrolides, rifamycins, or combination regimens targeting slow-growing or biofilm-forming organisms, not the classic niche of tetracyclines.", "C": "Anaerobic infections below the diaphragm are classically covered by metronidazole or clindamycin (with clindamycin favored above the diaphragm); tetracyclines are not the first-line choice for these anaerobic infections.", "D": "MRSA bacteremia requires bactericidal agents like vancomycin or daptomycin; while doxycycline has some activity against skin MRSA, it is not standard therapy for bacteremia."}}}, {"id": "anking-antimicrobials-1202", "fuente": "anking", "tema": 4, "anki": "1403557897769", "q": "Which class of protein synthesis inhibiting antibiotics is particularly effective against intracellular organisms like Rickettsia and Chlamydiae due to their ability to accumulate intracellularly?", "o": {"A": "Aminoglycosides", "B": "Tetracyclines", "C": "Macrolides", "D": "Chloramphenicol"}, "r": "B", "e": {"correcta": "Tetracyclines are lipophilic and readily cross cell membranes, allowing them to concentrate within host cells where obligate and facultative intracellular pathogens like Rickettsia spp. and Chlamydiae spp. reside. This intracellular penetration, combined with 30S ribosomal subunit inhibition, makes them a mainstay for these infections.", "incorrectas": {"A": "Aminoglycosides bind the 30S subunit but require oxygen-dependent active transport into cells and have poor intracellular penetration, making them ineffective against obligate intracellular organisms.", "C": "Macrolides do have some intracellular activity and are used for atypical pneumonia, but they are not the classic drug of choice highlighted for Rickettsia and Chlamydiae the way tetracyclines are, and doxycycline is generally preferred first-line.", "D": "Chloramphenicol inhibits the 50S subunit and can treat Rickettsia in some settings, but it is not the primary or preferred class for this indication due to toxicity concerns like aplastic anemia."}}}, {"id": "anking-antimicrobials-1203", "fuente": "anking", "tema": 4, "anki": "1403561346128", "q": "A patient develops aspiration pneumonia with a lung abscess suspected to involve anaerobic oral flora. Which protein synthesis inhibitor is classically used to treat anaerobic infections above the diaphragm?", "o": {"A": "Metronidazole", "B": "Vancomycin", "C": "Clindamycin", "D": "Aztreonam"}, "r": "C", "e": {"correcta": "Clindamycin inhibits the 50S ribosomal subunit and has excellent activity against anaerobes found above the diaphragm, including oral flora and Bacteroides-like organisms, making it useful for aspiration pneumonia, lung abscesses, and oral/dental infections. It also covers Clostridium perfringens, though C. perfringens food poisoning itself is self-limited and does not require antibiotics.", "incorrectas": {"A": "Metronidazole is highly effective against anaerobes but is classically favored for anaerobic infections below the diaphragm (e.g., intra-abdominal and pelvic infections) and for protozoal infections, not the above-the-diaphragm anaerobic niche of clindamycin.", "B": "Vancomycin targets cell wall synthesis in gram-positive organisms including MRSA and C. difficile (oral form), but it is not a protein synthesis inhibitor and is not the classic choice for anaerobic aspiration pneumonia.", "D": "Aztreonam is a monobactam active only against aerobic gram-negative rods; it has no anaerobic or gram-positive coverage and would not treat this infection."}}}, {"id": "anking-antimicrobials-1204", "fuente": "anking", "tema": 4, "anki": "1403561490959", "q": "A patient treated with clindamycin for a dental abscess develops fever and watery diarrhea several days later. Which complication is most likely occurring?", "o": {"A": "Red man syndrome", "B": "Pseudomembranous colitis", "C": "Serotonin syndrome", "D": "Stevens-Johnson syndrome"}, "r": "B", "e": {"correcta": "Clindamycin disrupts normal colonic flora, allowing overgrowth of toxin-producing Clostridioides difficile, which causes pseudomembranous colitis presenting with fever, watery diarrhea, and characteristic yellow-white pseudomembranes on colonoscopy. This is one of the most classic antibiotic-drug associations tested on Step 1.", "incorrectas": {"A": "Red man syndrome is a rate-related infusion reaction to vancomycin causing flushing and pruritus due to mast cell degranulation, unrelated to clindamycin or C. difficile.", "C": "Serotonin syndrome results from excess serotonergic activity, typically from combining serotonergic drugs (e.g., SSRIs with MAOIs or linezolid), and presents with hyperthermia, clonus, and altered mental status, not diarrhea from flora disruption.", "D": "Stevens-Johnson syndrome is a severe mucocutaneous hypersensitivity reaction usually triggered by drugs like sulfonamides, anticonvulsants, or allopurinol, presenting with skin/mucosal sloughing, not fever and diarrhea from flora disruption."}}}, {"id": "anking-immune-responses-1205", "fuente": "anking", "tema": 11, "anki": "1404183158836", "q": "A patient with recurrent Neisseria meningitidis infections is found to have a complement deficiency. Deficiency of which complement component is most associated with increased susceptibility to Neisseria infections?", "o": {"A": "C3", "B": "C1 esterase inhibitor", "C": "C5b-C9 (membrane attack complex)", "D": "Factor H"}, "r": "C", "e": {"correcta": "Deficiencies in the terminal complement components C5b-C9, which form the membrane attack complex (MAC), predispose to recurrent Neisseria infections. Neisseria species have relatively thin outer membranes and are especially vulnerable to direct lysis by the MAC, so loss of this terminal pathway removes a key defense specifically against these organisms.", "incorrectas": {"A": "C3 deficiency causes severe, recurrent pyogenic infections with encapsulated organisms broadly (not specifically Neisseria) because C3 is central to both opsonization and the amplification loop of all complement pathways.", "B": "C1 esterase inhibitor deficiency causes hereditary angioedema due to unchecked bradykinin and complement activation, not increased infection risk.", "D": "Factor H deficiency leads to unregulated alternative pathway activation and conditions like atypical hemolytic uremic syndrome, not a specific predisposition to Neisseria infections."}}}, {"id": "anking-neurology-special-senses-anatomy-physiology-1206", "fuente": "anking", "tema": 35, "anki": "1405189748896", "q": "The spinal cord develops embryologically from which structure?", "o": {"A": "Notochord", "B": "Neural crest", "C": "Neural tube (neuroectoderm)", "D": "Surface ectoderm"}, "r": "C", "e": {"correcta": "The neural tube, derived from neuroectoderm, gives rise to the entire central nervous system, including the brain and spinal cord. Its lumen becomes the central canal of the spinal cord and the ventricular system of the brain.", "incorrectas": {"A": "The notochord induces formation of the neural plate/tube via the underlying mesoderm signaling but itself regresses to form the nucleus pulposus of the intervertebral discs, not the spinal cord.", "B": "The neural crest, arising from cells at the lateral margins of the neural tube, forms the peripheral nervous system (dorsal root ganglia, autonomic ganglia, Schwann cells) and other structures, but not the spinal cord itself.", "D": "Surface ectoderm forms the epidermis and associated structures like hair and nails, not any component of the central nervous system."}}}, {"id": "anking-virology-1207", "fuente": "anking", "tema": 20, "anki": "1405375421095", "q": "A cervical Pap smear reveals dysplastic changes concerning for progression to carcinoma in situ. Which HPV serotypes are most strongly associated with this process?", "o": {"A": "HPV 6 and 11", "B": "HPV 16 and 18", "C": "HPV 1 and 2", "D": "HPV 31 and 33"}, "r": "B", "e": {"correcta": "HPV 16 and 18 are the high-risk serotypes most strongly linked to cervical dysplasia and carcinoma in situ, progressing to invasive cervical cancer. Their E6 and E7 oncoproteins inactivate the tumor suppressors p53 and Rb, respectively, driving unchecked cellular proliferation.", "incorrectas": {"A": "HPV 6 and 11 are low-risk serotypes that cause genital and anal condylomata (warts) rather than malignant transformation; they lack the potent oncogenic E6/E7 activity of high-risk strains.", "C": "HPV 1 and 2 are associated with common cutaneous warts (verruca vulgaris), not genital mucosal disease or cervical cancer.", "D": "HPV 31 and 33 are also classified as high-risk oncogenic strains, but they are less prevalent and less strongly emphasized than HPV 16 and 18, which account for the majority of cervical cancer cases."}}}, {"id": "anking-toxicities-side-effects-1208", "fuente": "anking", "tema": 29, "anki": "1461601471464", "q": "A patient started on metoclopramide for gastroparesis develops fever, muscle rigidity, altered mental status, autonomic instability, and rhabdomyolysis. Which syndrome is this?", "o": {"A": "Serotonin syndrome", "B": "Malignant hyperthermia", "C": "Neuroleptic malignant syndrome", "D": "Acute dystonia"}, "r": "C", "e": {"correcta": "Metoclopramide is a D2 receptor antagonist, and like antipsychotics, it can precipitate neuroleptic malignant syndrome (NMS) through central dopamine blockade. NMS classically presents with the tetrad of fever, lead-pipe rigidity, altered mental status, and autonomic instability, with rhabdomyolysis from sustained muscle contraction.", "incorrectas": {"A": "Serotonin syndrome results from excess serotonergic activity (e.g., combining SSRIs, MAOIs, or triptans) and presents with hyperthermia, clonus, hyperreflexia, and GI symptoms; it is not caused by dopamine blockade.", "B": "Malignant hyperthermia is a genetic ryanodine receptor disorder triggered by inhalational anesthetics or succinylcholine, causing uncontrolled calcium release in skeletal muscle, unrelated to dopamine antagonism.", "D": "Acute dystonia is an early extrapyramidal reaction to dopamine blockade causing sudden sustained muscle contractions (e.g., torticollis, oculogyric crisis), but it lacks the fever, autonomic instability, and rhabdomyolysis characteristic of full NMS."}}}, {"id": "anking-gastrointestinal-pharmacology-1209", "fuente": "anking", "tema": 40, "anki": "1461601568244", "q": "A patient on chronic metoclopramide therapy develops galactorrhea, gynecomastia, and menstrual irregularities. Elevation of which hormone is responsible?", "o": {"A": "Growth hormone", "B": "Thyroid-stimulating hormone", "C": "Prolactin", "D": "Luteinizing hormone"}, "r": "C", "e": {"correcta": "Metoclopramide blocks D2 receptors on lactotrophs in the anterior pituitary. Because dopamine normally acts through Gi-coupled D2 receptors to tonically inhibit prolactin release, D2 blockade removes this inhibition and raises prolactin, causing galactorrhea, gynecomastia, impotence, and menstrual disorders.", "incorrectas": {"A": "Growth hormone secretion is regulated by GHRH and somatostatin, not dopamine/D2 receptors, so metoclopramide does not directly raise GH levels.", "B": "TSH is regulated by TRH from the hypothalamus and thyroid hormone feedback; dopamine blockade does not directly drive TSH elevation in this context.", "D": "LH is part of the hypothalamic-pituitary-gonadal axis regulated by GnRH, not by dopaminergic tone on lactotrophs, so it is not the hormone responsible for these symptoms."}}}, {"id": "anking-toxicities-side-effects-1210", "fuente": "anking", "tema": 29, "anki": "1461601584259", "q": "A patient with baseline prolonged QT interval is prescribed metoclopramide for gastroparesis. What cardiac risk should prompt caution or avoidance of this drug?", "o": {"A": "Atrial fibrillation", "B": "QT prolongation and torsades de pointes", "C": "Complete heart block", "D": "Wolff-Parkinson-White syndrome"}, "r": "B", "e": {"correcta": "Metoclopramide can prolong the QT interval, which increases the risk of torsades de pointes, a polymorphic ventricular tachycardia. Because patients with baseline QT prolongation are already predisposed to this life-threatening arrhythmia, metoclopramide should generally be avoided in this population.", "incorrectas": {"A": "Atrial fibrillation is not a recognized adverse effect of metoclopramide; the drug's cardiac liability is specifically related to ventricular repolarization (QT interval), not atrial rhythm.", "C": "Complete heart block involves failure of AV nodal conduction and is associated with drugs like beta-blockers, calcium channel blockers, or digoxin toxicity, not metoclopramide's QT effects.", "D": "WPW syndrome is a congenital accessory conduction pathway problem unrelated to drug-induced QT prolongation; metoclopramide's risk is specifically torsades from QT prolongation, not pre-excitation arrhythmias."}}}, {"id": "anking-gastrointestinal-pharmacology-1211", "fuente": "anking", "tema": 40, "anki": "1461601716224", "q": "A patient with nausea and vomiting due to direct GI mucosal irritation (e.g., from chemotherapy-induced gut injury) would benefit most from which class of antiemetic?", "o": {"A": "H1 receptor antagonists", "B": "M1 receptor antagonists", "C": "5-HT3 receptor antagonists", "D": "NK1 receptor antagonists"}, "r": "C", "e": {"correcta": "5-HT3 receptor antagonists like ondansetron block serotonin release from enterochromaffin cells in the GI tract that is triggered by mucosal irritation, and also block central 5-HT3 receptors in the chemoreceptor trigger zone and vagal afferents, making them the drug class of choice for nausea from GI irritation (e.g., chemotherapy, radiation, postoperative).", "incorrectas": {"A": "H1 receptor antagonists (diphenhydramine, meclizine) act on the vestibular system and are the treatment of choice for motion sickness, not GI mucosal irritation.", "B": "M1 receptor (muscarinic) antagonists like scopolamine also target the vestibular pathway for motion sickness, not the serotonin-mediated pathway activated by GI irritation.", "D": "NK1 receptor antagonists like aprepitant block substance P signaling and are most useful for emetogenic substances acting centrally (e.g., delayed chemotherapy-induced emesis), often used as an adjunct rather than the first-line choice for direct GI irritation."}}}, {"id": "anking-gastrointestinal-pharmacology-1212", "fuente": "anking", "tema": 40, "anki": "1461601928376", "q": "A patient experiencing nausea and vomiting from motion sickness during a cruise would benefit most from which class(es) of antiemetic?", "o": {"A": "D2 receptor antagonists and NK1 receptor antagonists", "B": "5-HT3 receptor antagonists alone", "C": "H1 and M1 receptor antagonists (e.g., diphenhydramine/meclizine and scopolamine)", "D": "Only corticosteroids such as dexamethasone"}, "r": "C", "e": {"correcta": "Motion sickness is mediated by the vestibular system signaling through the vestibular nuclei to the vomiting center via histaminergic (H1) and muscarinic (M1) pathways. H1 blockers such as diphenhydramine and meclizine, and M1 blockers such as scopolamine, are the antiemetics of choice for this specific etiology.", "incorrectas": {"A": "D2 and NK1 receptor antagonists (metoclopramide, aprepitant) target chemoreceptor trigger zone pathways activated by circulating toxins or chemotherapy, not the vestibular pathway responsible for motion sickness.", "B": "5-HT3 receptor antagonists target serotonin release from GI mucosal irritation and are first-line for chemotherapy- or radiation-induced emesis, not vestibular-mediated motion sickness.", "D": "Corticosteroids like dexamethasone are used as adjuncts in chemotherapy-induced nausea/vomiting regimens, not as primary therapy for motion sickness."}}}, {"id": "anking-gastrointestinal-pharmacology-1213", "fuente": "anking", "tema": 40, "anki": "1461601938999", "q": "A patient with nausea and vomiting from emetogenic substances circulating in the blood/CNS (e.g., chemotherapy agents acting on the chemoreceptor trigger zone) is best treated with which antiemetic class(es)?", "o": {"A": "H1 and M1 receptor antagonists", "B": "5-HT3 receptor antagonists exclusively", "C": "Anticholinergics only", "D": "D2 receptor antagonists and NK1 receptor antagonists (e.g., metoclopramide and aprepitant)"}, "r": "D", "e": {"correcta": "The chemoreceptor trigger zone, located in the area postrema outside the blood-brain barrier, detects circulating toxins and drugs and signals the vomiting center. D2 receptor antagonists (metoclopramide) and NK1 receptor antagonists (aprepitant) act directly on this zone and are the antiemetics of choice for emetogenic substances in the blood/CNS.", "incorrectas": {"A": "H1 and M1 receptor antagonists act on vestibular pathways and are preferred for motion sickness, not for centrally acting emetogenic substances detected by the chemoreceptor trigger zone.", "B": "5-HT3 receptor antagonists are most effective for nausea driven by GI mucosal irritation and serotonin release from enterochromaffin cells, though they do have some CTZ activity, they are not paired as the classic answer for this specific blood/CNS toxin pathway in this framework.", "C": "General anticholinergics primarily address vestibular-mediated nausea (motion sickness) via M1 blockade, not the chemoreceptor trigger zone pathway activated by circulating emetogenic substances."}}}, {"id": "anking-gastrointestinal-physiology-1214", "fuente": "anking", "tema": 39, "anki": "1461616559615", "q": "A patient on an H2 receptor blocker continues to have some gastric acid secretion. Through which mechanisms can H+ secretion persist despite H2 blockade?", "o": {"A": "Direct stimulation of parietal cells by vagal input and gastrin", "B": "Continued histamine binding to H1 receptors on parietal cells", "C": "Somatostatin-mediated stimulation of the proton pump", "D": "Secretin-mediated activation of ECL cells"}, "r": "A", "e": {"correcta": "Parietal cell H+ secretion is stimulated by three pathways: histamine (via H2 receptors), acetylcholine (via vagal/M3 stimulation), and gastrin (via CCK-B receptors), all converging to activate the H+/K+ ATPase. Blocking only the H2 receptor leaves the vagal (ACh) and gastrin pathways intact, allowing direct stimulation of parietal cells to still drive some acid secretion.", "incorrectas": {"B": "Parietal cells respond to histamine via H2 receptors, not H1 receptors; H1 receptors are not part of the gastric acid secretion pathway, so this is not a mechanism of persistent acid secretion.", "C": "Somatostatin is inhibitory to acid secretion (it suppresses gastrin and histamine release), so it would reduce rather than sustain proton pump activity.", "D": "Secretin acts mainly on pancreatic ductal cells and actually inhibits gastric acid secretion and gastrin release; it does not stimulate ECL cells or parietal cells to increase acid output."}}}, {"id": "anking-gastrointestinal-pharmacology-1215", "fuente": "anking", "tema": 40, "anki": "1461616566780", "q": "H2 receptor antagonists are most effective at reducing which type of gastric acid secretion, while having only modest effect on the other?", "o": {"A": "Most effective for meal-stimulated secretion; modest effect on nocturnal secretion", "B": "Most effective for nocturnal secretion; modest effect on meal-stimulated secretion", "C": "Equally effective for both nocturnal and meal-stimulated secretion", "D": "Ineffective for both nocturnal and meal-stimulated secretion"}, "r": "B", "e": {"correcta": "H2 blockers are particularly effective at suppressing basal and nocturnal acid secretion, which is largely histamine-driven, but they have only a modest effect on meal-stimulated secretion because eating triggers acid release through multiple redundant pathways (gastrin, acetylcholine, and histamine) that are not fully blocked by H2 antagonism alone.", "incorrectas": {"A": "This reverses the actual pharmacology; H2 blockers are weaker against meal-stimulated secretion (which involves gastrin and vagal input in addition to histamine) and stronger against the more histamine-dependent nocturnal secretion.", "C": "H2 blockers are not equally effective across both settings; their efficacy is disproportionately greater for nocturnal secretion, which is why they are often dosed at bedtime for conditions like nocturnal GERD symptoms.", "D": "H2 blockers do meaningfully reduce nocturnal acid secretion; they are not ineffective, they are simply less potent overall than proton pump inhibitors, especially regarding meal-stimulated acid."}}}, {"id": "anking-toxicities-side-effects-1216", "fuente": "anking", "tema": 29, "anki": "1461616743909", "q": "Cimetidine and ranitidine can both decrease renal excretion of which substance, an effect not typically seen with other H2 blockers?", "o": {"A": "Potassium", "B": "Creatinine", "C": "Uric acid", "D": "Phosphate"}, "r": "B", "e": {"correcta": "Cimetidine and ranitidine competitively inhibit renal tubular secretion of creatinine, which can raise serum creatinine and falsely suggest worsening renal function even though the actual glomerular filtration rate is unchanged. Other H2 blockers such as famotidine and nizatidine are relatively free of this effect.", "incorrectas": {"A": "Potassium handling is not the mechanism described for cimetidine/ranitidine; these drugs are not known for causing clinically significant hyperkalemia via renal tubular effects.", "C": "Uric acid excretion is affected by drugs like thiazide diuretics (decrease excretion) or probenecid (increase excretion), not classically by cimetidine or ranitidine.", "D": "Phosphate excretion is regulated primarily by parathyroid hormone and FGF23 at the proximal tubule, not by H2 receptor blockers."}}}, {"id": "anking-gastrointestinal-pharmacology-1217", "fuente": "anking", "tema": 40, "anki": "1461624946809", "q": "Which class of acid-suppressing drugs reduces both nocturnal and meal-stimulated gastric acid secretion, making it more effective overall than H2 receptor blockers?", "o": {"A": "Antacids", "B": "Proton pump inhibitors", "C": "Prostaglandin analogs", "D": "Muscarinic antagonists"}, "r": "B", "e": {"correcta": "Proton pump inhibitors irreversibly inhibit the H+/K+ ATPase, the final common step of acid secretion regardless of which pathway (histamine, gastrin, or acetylcholine) stimulated the parietal cell. Because they act downstream of all three stimulatory pathways, PPIs suppress both nocturnal and meal-stimulated acid secretion more completely than H2 blockers, which only interrupt one input.", "incorrectas": {"A": "Antacids work by chemically neutralizing acid already secreted into the stomach lumen; they do not inhibit the secretory pathways themselves and provide only short-lived symptomatic relief.", "C": "Prostaglandin analogs like misoprostol protect the gastric mucosa by increasing mucus and bicarbonate secretion and inhibiting acid secretion modestly, but they are not the class known for near-complete suppression of both nocturnal and meal-stimulated acid.", "D": "Muscarinic antagonists could theoretically reduce vagally-mediated acid secretion, but they are not used clinically for this purpose due to significant anticholinergic side effects and lack the potency of PPIs."}}}, {"id": "anking-gastrointestinal-pharmacology-1218", "fuente": "anking", "tema": 40, "anki": "1461624955031", "q": "A patient diagnosed with Zollinger-Ellison syndrome (a gastrin-secreting tumor causing recurrent peptic ulcers) should be started on which first-line medical therapy?", "o": {"A": "H2 receptor blockers", "B": "Antacids", "C": "Proton pump inhibitors", "D": "Sucralfate"}, "r": "C", "e": {"correcta": "Proton pump inhibitors are first-line therapy for Zollinger-Ellison syndrome because they block the final common pathway of acid secretion (the H+/K+ ATPase), providing the most potent and sustained acid suppression needed to counteract the massive gastrin-driven hyperacidity and promote ulcer healing.", "incorrectas": {"A": "H2 receptor blockers are less potent than PPIs and only partially block acid secretion, especially the gastrin-driven component that predominates in Zollinger-Ellison syndrome, making them inadequate as first-line therapy for this condition.", "B": "Antacids provide only transient neutralization of existing acid and cannot control the continuous, high-volume acid hypersecretion characteristic of a gastrinoma.", "D": "Sucralfate coats ulcers to promote local healing but does not address the underlying hypersecretion of acid driven by excess gastrin, so it is not first-line for this syndrome."}}}, {"id": "anking-antimicrobials-1219", "fuente": "anking", "tema": 4, "anki": "1461624973870", "q": "What is the first-line treatment regimen for a patient diagnosed with Helicobacter pylori infection?", "o": {"A": "Vancomycin plus metronidazole", "B": "Triple therapy with a PPI, clarithromycin, and amoxicillin (or metronidazole)", "C": "H2 blocker plus doxycycline alone", "D": "Metronidazole monotherapy"}, "r": "B", "e": {"correcta": "First-line therapy for H. pylori is triple therapy combining a proton pump inhibitor (to suppress acid and enhance antibiotic efficacy and healing) with clarithromycin and amoxicillin (or metronidazole in penicillin-allergic patients). This combination eradicates the organism and allows the ulcer to heal.", "incorrectas": {"A": "Vancomycin is not absorbed systemically when given orally and has no activity against H. pylori; it is not part of standard eradication regimens for this organism.", "C": "An H2 blocker with a single antibiotic provides inadequate acid suppression and monotherapy antibiotic coverage, leading to high treatment failure and resistance; PPI-based triple (or quadruple) therapy is required.", "D": "Metronidazole monotherapy is insufficient because H. pylori eradication requires combination therapy with acid suppression to prevent relapse and resistance; single-agent therapy has unacceptably high failure rates."}}}, {"id": "anking-toxicities-side-effects-1220", "fuente": "anking", "tema": 29, "anki": "1461624994016", "q": "Chronic use of proton pump inhibitors increases the risk of which enteric infection by 2-3 fold?", "o": {"A": "Clostridioides difficile infection", "B": "Salmonella gastroenteritis only", "C": "Giardia lamblia infection", "D": "Entamoeba histolytica infection"}, "r": "A", "e": {"correcta": "By suppressing gastric acid, PPIs reduce a key non-immune barrier that normally kills ingested pathogens, and this loss of acidity along with disruption of the normal gut microenvironment increases susceptibility to Clostridioides difficile colonization and infection by roughly 2-3 fold.", "incorrectas": {"B": "While reduced gastric acidity from any acid suppression can theoretically increase risk for various enteric pathogens including some Salmonella exposure, the specific and best-documented, heavily tested association with PPIs is C. difficile, not Salmonella specifically.", "C": "Giardia and other protozoal parasites are not the classic infection associated with PPI use in USMLE-style testing; the well-established, high-yield association is C. difficile.", "D": "Entamoeba histolytica is not the pathogen linked to PPI-associated increased infection risk; this distractor pairs a real parasite with the wrong drug association."}}}, {"id": "anking-toxicities-side-effects-1221", "fuente": "anking", "tema": 29, "anki": "1461625004593", "q": "In addition to increased risk of C. difficile infection, chronic proton pump inhibitor use is also associated with an increased risk of which condition?", "o": {"A": "Pneumonia", "B": "Peptic ulcer perforation", "C": "Acute pancreatitis", "D": "Esophageal varices"}, "r": "A", "e": {"correcta": "Reduced gastric acidity from PPIs allows bacterial overgrowth and colonization of the upper GI tract and oropharynx, which increases the risk of aspiration and community-acquired pneumonia, an association well documented in epidemiologic studies of long-term PPI users.", "incorrectas": {"B": "PPIs are used to treat and prevent peptic ulcers by suppressing acid, so they would not be expected to increase the risk of ulcer perforation; if anything, they reduce ulcer-related complications.", "C": "Acute pancreatitis is not a well-established adverse effect of PPI therapy; the recognized PPI-associated risks include C. difficile, pneumonia, fractures, and hypomagnesemia, not pancreatitis.", "D": "Esophageal varices result from portal hypertension in liver disease and are unrelated to gastric acid suppression by PPIs."}}}, {"id": "anking-toxicities-side-effects-1222", "fuente": "anking", "tema": 29, "anki": "1461625020267", "q": "A patient on long-term proton pump inhibitor therapy is counseled about several adverse effects. Which of the following is a recognized risk of chronic PPI use?", "o": {"A": "Increased risk of pneumonia", "B": "Decreased risk of hip fracture", "C": "Hypercalcemia", "D": "Hypermagnesemia"}, "r": "A", "e": {"correcta": "Chronic PPI use increases the risk of pneumonia, likely due to bacterial overgrowth in the acid-suppressed upper GI tract and subsequent microaspiration, in addition to increasing risk of C. difficile infection.", "incorrectas": {"B": "PPIs actually increase, not decrease, the risk of hip fracture because reduced gastric acidity impairs absorption of calcium, which requires an acidic environment for optimal solubility and uptake, weakening bone over time.", "C": "PPIs are associated with reduced calcium absorption and can contribute to hypocalcemia-related bone effects over time, not hypercalcemia.", "D": "Chronic PPI use is associated with hypomagnesemia (decreased absorption), not hypermagnesemia; this is the opposite of the actual electrolyte disturbance seen."}}}, {"id": "anking-gastrointestinal-physiology-1223", "fuente": "anking", "tema": 39, "anki": "1461625032072", "q": "Proton pump inhibitors decrease the absorption of which category of dietary minerals, since their uptake depends on an acidic gastric environment?", "o": {"A": "Monovalent cations such as Na+ and K+", "B": "Divalent cations such as Ca2+, Mg2+, and Fe2+", "C": "Halide anions such as Cl- and I-", "D": "Trace elements such as selenium and iodine"}, "r": "B", "e": {"correcta": "Divalent cations like calcium, magnesium, and iron require an acidic gastric environment to remain soluble and be optimally absorbed in the proximal small intestine. By raising gastric pH, PPIs impair the absorption of these divalent cations, contributing to risks like osteoporosis (from reduced calcium) and hypomagnesemia.", "incorrectas": {"A": "Sodium and potassium absorption occurs largely through active transport mechanisms in the intestines that are not primarily dependent on gastric acidity, so PPIs do not meaningfully impair their absorption.", "C": "Halide anion absorption is not the classic mineral absorption issue associated with acid suppression; the well-documented deficiency risks with PPIs involve divalent cations, not halides.", "D": "Trace elements like selenium and iodine absorption are not significantly pH-dependent in the way divalent cations are, and are not the minerals classically cited in PPI-related absorption problems."}}}, {"id": "anking-toxicities-side-effects-1224", "fuente": "anking", "tema": 29, "anki": "1461625057796", "q": "Reduced calcium absorption due to chronic proton pump inhibitor use increases the risk of which condition, prompting bone density monitoring and calcium supplementation?", "o": {"A": "Rickets", "B": "Osteoporosis with increased fracture risk", "C": "Osteopetrosis", "D": "Paget disease of bone"}, "r": "B", "e": {"correcta": "Chronic PPI-induced reduction in calcium absorption contributes to decreased bone mineral density over time, increasing the risk of osteoporosis and osteoporotic fractures, particularly hip fractures. This is why patients on long-term PPI therapy should have bone density monitored and consider calcium supplementation.", "incorrectas": {"A": "Rickets is a pediatric disorder of defective bone mineralization typically due to vitamin D deficiency, not a recognized consequence of adult PPI-induced calcium malabsorption.", "C": "Osteopetrosis is a genetic disorder of defective osteoclast function leading to abnormally dense but brittle bone, unrelated to PPI use or calcium absorption.", "D": "Paget disease of bone is a disorder of excessive, disorganized bone remodeling from osteoclast dysregulation, not related to acid suppression or calcium malabsorption."}}}, {"id": "anking-toxicities-side-effects-1225", "fuente": "anking", "tema": 29, "anki": "1461625078700", "q": "Decreased magnesium absorption from chronic proton pump inhibitor therapy may lead to which electrolyte abnormality?", "o": {"A": "Hypermagnesemia", "B": "Hypomagnesemia", "C": "Hyperkalemia", "D": "Hyponatremia"}, "r": "B", "e": {"correcta": "By decreasing gastric acidity, PPIs impair intestinal absorption of magnesium (a divalent cation requiring an acidic environment for uptake), which with prolonged use can result in clinically significant hypomagnesemia, sometimes requiring drug discontinuation.", "incorrectas": {"A": "Hypermagnesemia would result from excess magnesium intake or reduced renal excretion (e.g., renal failure with magnesium-containing antacid use), not from reduced absorption caused by PPIs.", "C": "Hyperkalemia is not a recognized consequence of PPI-induced malabsorption; potassium handling is regulated separately, mainly by aldosterone and renal mechanisms.", "D": "Hyponatremia is not linked to PPI-mediated divalent cation malabsorption; sodium balance is governed by different regulatory systems (e.g., ADH, aldosterone) unaffected by gastric acid suppression."}}}, {"id": "anking-gastrointestinal-pharmacology-1226", "fuente": "anking", "tema": 40, "anki": "1461632010388", "q": "Laxatives, as a drug class, primarily relieve constipation through which general mechanism, distinguishing them from prokinetic agents?", "o": {"A": "Direct stimulation of GI smooth muscle motility", "B": "Alteration of the consistency of feces", "C": "Blockade of opioid receptors in the gut", "D": "Inhibition of acetylcholinesterase in the enteric nervous system"}, "r": "B", "e": {"correcta": "Laxatives work broadly by changing the physical consistency of stool, whether by drawing water into the lumen (osmotic agents), softening stool with surfactants, or adding bulk, all of which promote easier passage. This is in contrast to prokinetic agents like metoclopramide or erythromycin, which act directly on GI motility receptors to stimulate peristalsis regardless of stool consistency.", "incorrectas": {"A": "Direct stimulation of GI motility is the mechanism of prokinetic agents (e.g., metoclopramide, erythromycin), which is explicitly distinguished from the mechanism of laxatives in this context.", "C": "Opioid receptor blockade in the gut describes drugs like methylnaltrexone, used specifically for opioid-induced constipation, not the general mechanism of the laxative class as a whole.", "D": "Acetylcholinesterase inhibition would increase cholinergic tone and motility (as with some prokinetic-like effects) but is not the general defining mechanism of laxatives, which act mainly via stool consistency changes."}}}, {"id": "anking-gastrointestinal-pharmacology-1227", "fuente": "anking", "tema": 40, "anki": "1461634577602", "q": "Which class of laxatives consists of non-absorbable substances that draw water into the intestinal lumen, causing distention and stimulating peristalsis?", "o": {"A": "Bulk-forming laxatives", "B": "Stool softeners", "C": "Osmotic laxatives", "D": "Stimulant laxatives"}, "r": "C", "e": {"correcta": "Osmotic laxatives are poorly absorbed solutes (such as magnesium salts, lactulose, and polyethylene glycol) that create an osmotic gradient pulling water into the intestinal lumen. This increased luminal water volume distends the bowel and stimulates peristalsis, promoting bowel movements.", "incorrectas": {"A": "Bulk-forming laxatives (e.g., psyllium, methylcellulose) are indigestible hydrophilic colloids that absorb water to add bulk to stool, which is a related but distinct mechanism from the osmotic water-drawing effect of non-absorbable solutes.", "B": "Stool softeners (e.g., docusate) are surfactants that allow water and lipids to penetrate and soften the stool, rather than creating an osmotic gradient to draw water into the lumen.", "D": "Stimulant laxatives directly irritate the intestinal mucosa or stimulate enteric nerves to increase motility, a different mechanism from the osmotic water-drawing action described here."}}}, {"id": "anking-gastrointestinal-pharmacology-1228", "fuente": "anking", "tema": 40, "anki": "1461634588075", "q": "Magnesium hydroxide and magnesium citrate belong to which class of laxatives?", "o": {"A": "Stimulant laxatives", "B": "Bulk-forming laxatives", "C": "Stool softeners", "D": "Osmotic laxatives"}, "r": "D", "e": {"correcta": "Magnesium hydroxide (milk of magnesia) and magnesium citrate are osmotic laxatives; the poorly absorbed magnesium salts create an osmotic gradient that draws water into the gut lumen, increasing stool volume and promoting peristalsis. Prolonged use can cause hypermagnesemia, particularly in patients with renal insufficiency who cannot excrete the excess magnesium.", "incorrectas": {"A": "Stimulant laxatives (e.g., senna, bisacodyl) work by directly irritating the bowel mucosa and enteric neurons to increase motility, a different mechanism than the osmotic effect of magnesium salts.", "B": "Bulk-forming laxatives like psyllium and methylcellulose are hydrophilic fiber compounds that add bulk and absorb water, distinct from the ionic osmotic mechanism of magnesium salts.", "C": "Stool softeners like docusate act as surfactants to allow water and lipid penetration into stool, which is a different mechanism from the osmotic gradient created by magnesium salts."}}}, {"id": "anking-gastrointestinal-pharmacology-1229", "fuente": "anking", "tema": 40, "anki": "1461634601250", "q": "Polyethylene glycol (PEG), a non-absorbable sugar-like compound often used as bowel prep before colonoscopy, acts through which laxative mechanism?", "o": {"A": "Stimulant", "B": "Bulk-forming", "C": "Surfactant/stool softening", "D": "Osmotic"}, "r": "D", "e": {"correcta": "Polyethylene glycol is a non-absorbable molecule that remains in the intestinal lumen and osmotically draws water into the bowel, producing a large volume of fluid that flushes the colon. This osmotic mechanism, especially when combined with electrolytes (Na, Cl, HCO3, K), makes PEG solutions ideal for rapid bowel cleansing before colonoscopy.", "incorrectas": {"A": "Stimulant laxatives act via direct irritation of the enteric nervous system and mucosa to enhance motility, which is a different mechanism from the osmotic water-drawing effect of PEG.", "B": "Bulk-forming laxatives rely on hydrophilic fiber that swells with water to increase stool bulk gradually, unlike the large-volume, rapid osmotic flushing effect used for bowel prep with PEG.", "C": "Surfactant stool softeners like docusate ease stool passage by facilitating water and lipid penetration into existing stool, a slower and gentler mechanism than the osmotic bowel-cleansing effect of PEG."}}}, {"id": "anking-gastrointestinal-pharmacology-1230", "fuente": "anking", "tema": 40, "anki": "1461634613345", "q": "Lactulose, a non-absorbable sugar used to treat constipation, acts through which laxative mechanism?", "o": {"A": "Stimulant", "B": "Bulk-forming", "C": "Osmotic", "D": "Surfactant"}, "r": "C", "e": {"correcta": "Lactulose is a non-absorbable disaccharide that remains in the gut lumen and is metabolized by colonic bacteria into osmotically active short-chain acids, drawing water into the lumen and softening/increasing stool volume. This same colonic bacterial metabolism, which acidifies the lumen and traps ammonia as ammonium, is also the basis for its use in hepatic encephalopathy.", "incorrectas": {"A": "Stimulant laxatives directly irritate the bowel wall or enteric neurons to enhance peristalsis, which is a distinct mechanism from the osmotic, bacterially-metabolized action of lactulose.", "B": "Bulk-forming laxatives rely on indigestible fiber that swells with water, whereas lactulose's laxative effect comes from bacterial fermentation products creating an osmotic gradient, not fiber bulk.", "D": "Surfactant laxatives (stool softeners) work by allowing water and lipids to penetrate stool directly, which differs mechanistically from lactulose's osmotic, fermentation-based action."}}}, {"id": "anking-gastrointestinal-pharmacology-1231", "fuente": "anking", "tema": 40, "anki": "1461634655914", "q": "What is the mechanism by which lactulose is used to treat hepatic encephalopathy in a patient with cirrhosis?", "o": {"A": "It directly chelates ammonia in the bloodstream, allowing renal excretion", "B": "It is metabolized into acidic metabolites that convert NH3 to NH4+, trapping it in the intestinal lumen for excretion", "C": "It inhibits hepatic ammonia production by blocking the urea cycle", "D": "It increases hepatic blood flow to enhance ammonia clearance by the liver"}, "r": "B", "e": {"correcta": "Colonic bacteria metabolize lactulose into lactic acid and acetic acid, acidifying the intestinal lumen. This acidic environment converts absorbable NH3 (ammonia) into non-absorbable NH4+ (ammonium), trapping it within the gut lumen so it is excreted in the stool rather than being absorbed into the portal circulation, thereby lowering blood ammonia levels in hepatic encephalopathy.", "incorrectas": {"A": "Lactulose does not directly bind or chelate ammonia already in the bloodstream; its effect occurs within the intestinal lumen by altering the chemical form of ammonia before it can be absorbed.", "C": "Lactulose does not act on the hepatic urea cycle at all; the liver's ammonia-processing machinery is not the target of this drug, which works entirely within the gut lumen.", "D": "Lactulose has no effect on hepatic blood flow; its therapeutic effect is purely local within the intestinal lumen via bacterial metabolism and ammonia trapping, not through altering liver perfusion."}}}, {"id": "anking-toxicities-side-effects-1232", "fuente": "anking", "tema": 29, "anki": "1461634673719", "q": "What are the two main adverse effects associated with osmotic laxative use?", "o": {"A": "Constipation and bloating", "B": "Diarrhea and dehydration", "C": "Hepatotoxicity and pancreatitis", "D": "Hypertension and tachycardia"}, "r": "B", "e": {"correcta": "Because osmotic laxatives work by drawing large amounts of water into the intestinal lumen, excessive or prolonged use can lead to diarrhea and, if fluid losses are not replaced, dehydration and associated electrolyte disturbances.", "incorrectas": {"A": "Constipation and bloating are the opposite of the expected effect of a laxative, and are not the recognized adverse effects of this drug class, which functions specifically to relieve constipation.", "C": "Hepatotoxicity and pancreatitis are not associated with osmotic laxatives, which act locally within the gut lumen and are not systemically absorbed to cause organ toxicity.", "D": "Hypertension and tachycardia are not typical adverse effects of osmotic laxatives; if anything, excessive fluid loss could contribute to volume depletion and hypotension rather than hypertension."}}}, {"id": "anking-gastrointestinal-pharmacology-1233", "fuente": "anking", "tema": 40, "anki": "1461634682247", "q": "Psyllium, an indigestible hydrophilic colloid that absorbs water to increase stool bulk, belongs to which class of laxatives?", "o": {"A": "Osmotic laxatives", "B": "Bulk-forming laxatives", "C": "Stool softeners", "D": "Stimulant laxatives"}, "r": "B", "e": {"correcta": "Psyllium is a bulk-forming laxative, an indigestible hydrophilic fiber that absorbs water within the gut lumen, increasing stool bulk and causing distension that stimulates peristalsis, similar in concept to increasing dietary fiber intake.", "incorrectas": {"A": "Osmotic laxatives (e.g., magnesium salts, lactulose, PEG) are non-absorbable solutes that create an osmotic gradient to draw water into the lumen, a chemically different mechanism than the fiber-based bulking action of psyllium.", "C": "Stool softeners like docusate are surfactants that allow water and lipid penetration into existing stool, rather than adding bulk through fiber as psyllium does.", "D": "Stimulant laxatives directly irritate the bowel wall or enteric nerves to promote motility, which is a different mechanism from the passive bulking and water absorption seen with psyllium."}}}, {"id": "anking-gastrointestinal-pharmacology-1234", "fuente": "anking", "tema": 40, "anki": "1461634691735", "q": "Stool softeners such as docusate work through which mechanism to relieve constipation?", "o": {"A": "Osmotically drawing water into the intestinal lumen", "B": "Directly stimulating enteric neurons to increase peristalsis", "C": "Acting as surfactants that facilitate penetration of stool by water and lipids", "D": "Adding indigestible fiber bulk to the stool"}, "r": "C", "e": {"correcta": "Stool softeners are surfactant agents that reduce the surface tension of stool, allowing water and lipids to penetrate and mix into the fecal mass. This softens the stool and makes it easier to pass without significantly increasing bowel motility or luminal water content through osmosis.", "incorrectas": {"A": "Osmotic laxatives (e.g., magnesium salts, lactulose, PEG) work by drawing water into the lumen via an osmotic gradient, a distinct mechanism from the surfactant action of stool softeners.", "B": "Direct stimulation of enteric neurons to increase peristalsis describes stimulant laxatives (e.g., senna, bisacodyl), not the surfactant mechanism of stool softeners.", "D": "Adding indigestible fiber bulk describes bulk-forming laxatives like psyllium, which work through a different physical mechanism than the surfactant action of stool softeners."}}}, {"id": "anking-gastrointestinal-pharmacology-1235", "fuente": "anking", "tema": 40, "anki": "1461634716202", "q": "Docusate is used medically for which purpose?", "o": {"A": "As a bulk-forming laxative", "B": "As a stool softener", "C": "As an osmotic laxative", "D": "As a stimulant laxative"}, "r": "B", "e": {"correcta": "Docusate is a surfactant agent that facilitates the penetration of stool by water and lipids, softening the stool to ease its passage without significantly increasing intestinal water content or directly stimulating motility. It is commonly used prophylactically to prevent straining, such as after surgery or childbirth.", "incorrectas": {"A": "Bulk-forming laxatives like psyllium and methylcellulose work by adding indigestible fiber that absorbs water and increases stool bulk, a different mechanism from docusate's surfactant action.", "C": "Osmotic laxatives such as magnesium salts, lactulose, and polyethylene glycol pull water into the lumen through an osmotic gradient, unlike docusate, which acts as a surfactant rather than an osmotic agent.", "D": "Stimulant laxatives (e.g., senna, bisacodyl) directly irritate the bowel or stimulate enteric nerves to increase peristalsis, which is mechanistically distinct from docusate's stool-softening surfactant effect."}}}, {"id": "anking-gastrointestinal-pharmacology-1236", "fuente": "anking", "tema": 40, "anki": "1461634726476", "q": "Senna and bisacodyl are laxatives of which class, which act via stimulation of the enteric nervous system and increased colonic secretions?", "o": {"A": "Osmotic agents", "B": "Bulk-forming agents", "C": "Cathartic (stimulant) agents", "D": "Stool softeners"}, "r": "C", "e": {"correcta": "Senna and bisacodyl are stimulant (cathartic) laxatives that directly stimulate enteric nerve endings in the colonic mucosa, increasing motility and net colonic fluid/electrolyte secretion, which produces a bowel movement within about 6-12 hours.", "incorrectas": {"A": "Osmotic laxatives (e.g., polyethylene glycol, lactulose, magnesium hydroxide) work by drawing water into the lumen through osmotic force, not by stimulating enteric neurons, distinguishing their mechanism from senna/bisacodyl.", "B": "Bulk-forming agents (e.g., psyllium, methylcellulose) increase stool bulk and water retention within the stool by absorbing water, promoting peristalsis mechanically rather than through direct enteric nerve stimulation.", "D": "Stool softeners (e.g., docusate) act as surfactants that allow water and lipids to penetrate the stool, softening it for easier passage, which is a distinct mechanism from the neurogenic stimulation caused by cathartics."}}}, {"id": "anking-gastrointestinal-pharmacology-1237", "fuente": "anking", "tema": 40, "anki": "1461634751424", "q": "Opioid agonists such as diphenoxylate and loperamide treat diarrhea by activating which receptor in the GI tract?", "o": {"A": "5-HT3 receptors", "B": "μ-opioid receptors", "C": "D2 dopamine receptors", "D": "M3 muscarinic receptors"}, "r": "B", "e": {"correcta": "Diphenoxylate and loperamide are opioid agonists that activate μ-opioid receptors on enteric neurons in the GI tract, which slows intestinal motility and increases transit time, allowing more water reabsorption and firmer stool.", "incorrectas": {"A": "5-HT3 receptor antagonism (e.g., ondansetron) is the mechanism behind antiemetics, not antidiarrheals; 5-HT3 receptors mediate nausea/vomiting signaling rather than colonic motility control by opioids.", "C": "D2 receptor antagonism underlies drugs like metoclopramide, which increase GI motility (prokinetic effect) rather than the antimotility, antidiarrheal effect produced by μ-opioid receptor activation.", "D": "Muscarinic M3 receptors mediate parasympathetic stimulation of GI smooth muscle contraction and secretion; antimuscarinics (not opioids) block this receptor to reduce GI motility, a different pathway from opioid antidiarrheals."}}}, {"id": "anking-gastrointestinal-pharmacology-1238", "fuente": "anking", "tema": 40, "anki": "1461634773558", "q": "Opioid agonists like loperamide increase colonic transit time primarily by increasing which type of colonic contraction?", "o": {"A": "Peristaltic contractions", "B": "Migrating motor complexes", "C": "Phasic segmentation contractions", "D": "Haustral relaxation"}, "r": "C", "e": {"correcta": "Opioid agonists increase colonic phasic segmentation contractions, which mix luminal contents back and forth in place rather than propelling them forward, slowing net transit and allowing more time for water absorption, thereby firming the stool.", "incorrectas": {"A": "Peristaltic contractions are coordinated, forward-propulsive waves that push stool distally; opioids actually suppress this pattern of motility rather than enhancing it, which is the opposite of segmentation.", "B": "Migrating motor complexes are the interdigestive, cyclical waves of motility that sweep the small intestine between meals; they are not the mechanism opioids use to slow colonic transit.", "D": "Haustral relaxation would allow contents to move along more freely; opioids do not work by relaxing haustra, but by promoting non-propulsive segmenting contractions that retain contents."}}}, {"id": "anking-gastrointestinal-pharmacology-1239", "fuente": "anking", "tema": 40, "anki": "1461634796049", "q": "A patient is more likely to become addicted to which anti-diarrheal μ-opioid agonist, and why?", "o": {"A": "Loperamide, because it crosses the blood-brain barrier", "B": "Diphenoxylate, because it crosses the blood-brain barrier", "C": "Loperamide, because it has high oral bioavailability", "D": "Diphenoxylate, because it is metabolized to morphine"}, "r": "B", "e": {"correcta": "Diphenoxylate crosses the blood-brain barrier at higher doses, giving it CNS opioid effects (including potential euphoria) and abuse potential, which is why it is formulated with atropine to discourage misuse.", "incorrectas": {"A": "Loperamide does not readily cross the blood-brain barrier at therapeutic doses (it is a P-glycoprotein substrate that gets pumped back out), so it produces minimal CNS/euphoric effects and has low abuse potential compared to diphenoxylate.", "C": "Oral bioavailability is not the property that determines abuse liability here; the key distinguishing pharmacokinetic feature is CNS penetration, which favors diphenoxylate, not loperamide.", "D": "Diphenoxylate is not metabolized to morphine; it is a meperidine analog that acts directly on μ-opioid receptors in the gut and, at high doses, in the CNS due to BBB penetration, not via conversion to morphine."}}}, {"id": "anking-gastrointestinal-pharmacology-1240", "fuente": "anking", "tema": 40, "anki": "1461634805663", "q": "Antidiarrheal agents are contraindicated in patients presenting with which findings?", "o": {"A": "Bloody diarrhea or fever", "B": "Mild watery diarrhea without fever", "C": "Chronic constipation-predominant IBS", "D": "Isolated abdominal bloating"}, "r": "A", "e": {"correcta": "Bloody diarrhea or fever suggests an invasive infectious process (e.g., Shigella, EHEC, Salmonella, C. difficile), and slowing GI motility with antidiarrheals can worsen the illness by prolonging pathogen/toxin contact with the mucosa and increasing risk of complications such as toxic megacolon or hemolytic uremic syndrome.", "incorrectas": {"B": "Mild watery diarrhea without systemic signs of invasive infection is exactly the setting where symptomatic antidiarrheal therapy is typically appropriate and safe, unlike bloody or febrile diarrhea.", "C": "Constipation-predominant IBS is not a scenario involving antidiarrheal use at all, and is not the classic contraindication being tested; the concern with antidiarrheals is specifically in acute invasive/inflammatory diarrheal illness.", "D": "Isolated bloating without diarrhea, blood, or fever does not represent a contraindication to antidiarrheal agents, since there is no evidence of an invasive infectious process that antimotility drugs could worsen."}}}, {"id": "anking-gastrointestinal-pharmacology-1241", "fuente": "anking", "tema": 40, "anki": "1461634814863", "q": "Which GI side effect is commonly caused by opioid agonists used as antidiarrheals?", "o": {"A": "Diarrhea", "B": "Constipation", "C": "GI perforation", "D": "Malabsorption"}, "r": "B", "e": {"correcta": "Opioid agonists slow GI motility and promote non-propulsive segmentation, which can lead to constipation as a side effect; patients on these agents should increase fluid and dietary fiber intake, with laxatives added if needed.", "incorrectas": {"A": "Diarrhea is the condition these agents are used to treat, not a side effect they cause; their pharmacologic action is antimotility, which produces the opposite effect (constipation).", "C": "GI perforation is not a typical or expected side effect of opioid antidiarrheal use; it would be a rare complication of an underlying untreated invasive infection, not a direct drug effect.", "D": "Malabsorption is not a recognized side effect of opioid agonist antidiarrheals; these drugs act on motility and secretion, not on nutrient absorption mechanisms."}}}, {"id": "anking-gastrointestinal-physiology-1242", "fuente": "anking", "tema": 39, "anki": "1461634826340", "q": "VIPoma and carcinoid tumor both classically cause which type of diarrhea?", "o": {"A": "Osmotic diarrhea", "B": "Secretory diarrhea", "C": "Malabsorptive (fatty) diarrhea", "D": "Inflammatory diarrhea"}, "r": "B", "e": {"correcta": "Secretory diarrhea is a watery diarrhea caused by active secretion of fluid into the stool; VIPoma produces vasoactive intestinal peptide (VIP) and carcinoid tumors produce serotonin, both of which drive intestinal epithelial cells to actively secrete electrolytes and water into the gut lumen.", "incorrectas": {"A": "Osmotic diarrhea results from unabsorbed osmotically active solutes (e.g., lactose in lactase deficiency) drawing water into the lumen, and typically improves with fasting, unlike the secretory diarrhea driven by VIP or serotonin which persists despite fasting.", "C": "Malabsorptive/fatty diarrhea (steatorrhea) results from impaired fat digestion or absorption, as seen in pancreatic insufficiency or celiac disease, a different mechanism from the hormone-driven active secretion seen with VIPoma and carcinoid tumors.", "D": "Inflammatory diarrhea results from mucosal damage and an inflammatory exudate, as in infectious colitis or IBD, and often includes blood/leukocytes in stool, which is not the mechanism behind VIPoma or carcinoid-associated diarrhea."}}}, {"id": "anking-gastrointestinal-pharmacology-1243", "fuente": "anking", "tema": 40, "anki": "1461706305811", "q": "Metoclopramide has clinically important drug interactions with digoxin and which other class of agents?", "o": {"A": "Diabetic (antidiabetic) agents", "B": "Anticoagulants", "C": "Antihypertensives", "D": "Statins"}, "r": "A", "e": {"correcta": "Metoclopramide is a prokinetic that speeds gastric emptying, which alters the rate and extent of absorption of orally administered drugs; it interacts with digoxin (by decreasing its absorption due to faster transit through the stomach) and with diabetic agents (by altering the timing of glucose absorption relative to insulin or oral hypoglycemic dosing).", "incorrectas": {"B": "Anticoagulants are not the classic drug interaction highlighted for metoclopramide; the clinically emphasized interactions involve digoxin and diabetic medications due to altered GI transit and absorption timing.", "C": "Antihypertensives are not the paired interaction category for metoclopramide in this context; metoclopramide's effect on gastric emptying specifically impacts absorption-sensitive drugs like digoxin and glycemic control agents.", "D": "Statins are not known for a clinically significant interaction with metoclopramide via altered gastric emptying; the relevant interacting drug classes are digoxin and antidiabetic agents."}}}, {"id": "anking-gastrointestinal-pharmacology-1244", "fuente": "anking", "tema": 40, "anki": "1461767111073", "q": "Which two anti-emetics carry a risk of causing torsades de pointes as a side effect, making them contraindicated with pre-existing QT prolongation?", "o": {"A": "Ondansetron and metoclopramide", "B": "Promethazine and diphenhydramine", "C": "Scopolamine and meclizine", "D": "Aprepitant and dronabinol"}, "r": "A", "e": {"correcta": "Both ondansetron and metoclopramide can prolong the QT interval, increasing the risk of torsades de pointes, which is why these drugs should be used cautiously or avoided in patients with a pre-existing prolonged QT interval or other risk factors for arrhythmia.", "incorrectas": {"B": "Promethazine and diphenhydramine are antihistamine-based antiemetics whose major concerning side effects are anticholinergic and sedative effects, not the classic QT-prolongation/torsades risk associated with ondansetron and metoclopramide.", "C": "Scopolamine and meclizine are used for motion sickness via anticholinergic/antihistaminic mechanisms; their notable adverse effects are dry mouth, sedation, and blurred vision, not torsades de pointes.", "D": "Aprepitant (NK1 antagonist) and dronabinol (cannabinoid) act through entirely different receptor mechanisms and are not associated with the QT-prolonging, torsadogenic risk seen with ondansetron and metoclopramide."}}}, {"id": "anking-antimicrobials-1245", "fuente": "anking", "tema": 4, "anki": "1461797701666", "q": "Which adverse effects are classically associated with sofosbuvir therapy for hepatitis C?", "o": {"A": "Photosensitivity and rash", "B": "Fatigue and nausea", "C": "Hemolytic anemia and cough", "D": "Peripheral neuropathy and pancreatitis"}, "r": "B", "e": {"correcta": "Sofosbuvir, a nucleotide analog NS5B polymerase inhibitor used in hepatitis C regimens, is associated with fatigue and nausea as common adverse effects, which are generally mild compared to older interferon-based regimens.", "incorrectas": {"A": "Photosensitivity and rash are the characteristic adverse effects of simeprevir (an NS3/4A protease inhibitor), a different hepatitis C agent, not sofosbuvir.", "C": "Hemolytic anemia and cough are classic adverse effects of ribavirin, another agent used in combination hepatitis C/some hepatitis regimens, distinct from sofosbuvir's fatigue/nausea profile.", "D": "Peripheral neuropathy and pancreatitis are more classically associated with older antiretroviral nucleoside analogs (e.g., didanosine, stavudine) rather than with sofosbuvir's typical side effect profile."}}}, {"id": "anking-toxicities-side-effects-1246", "fuente": "anking", "tema": 29, "anki": "1461797752804", "q": "Which adverse effects are characteristic of simeprevir, a protease inhibitor used in hepatitis C therapy?", "o": {"A": "Fatigue and nausea", "B": "Hemolytic anemia and cough", "C": "Photosensitivity and rash", "D": "Peripheral neuropathy and pancreatitis"}, "r": "C", "e": {"correcta": "Simeprevir, an NS3/4A protease inhibitor used to treat hepatitis C, is notably associated with photosensitivity and rash, so patients are counseled on sun protection while taking this medication.", "incorrectas": {"A": "Fatigue and nausea are the more typical adverse effects of sofosbuvir, a different hepatitis C agent (an NS5B polymerase inhibitor), not the hallmark effects of simeprevir.", "B": "Hemolytic anemia and cough are classically associated with ribavirin, used in combination antiviral regimens, and are not the characteristic side effects tied to simeprevir.", "D": "Peripheral neuropathy and pancreatitis are more associated with older nucleoside reverse transcriptase inhibitors used in HIV therapy, not with simeprevir's photosensitivity/rash profile."}}}, {"id": "anking-antimicrobials-1247", "fuente": "anking", "tema": 4, "anki": "1461797775253", "q": "Which two nucleos(t)ide reverse transcriptase inhibitors (NRTIs) are used to treat hepatitis B?", "o": {"A": "Zidovudine and abacavir", "B": "Lamivudine and tenofovir", "C": "Ribavirin and sofosbuvir", "D": "Emtricitabine and stavudine"}, "r": "B", "e": {"correcta": "Lamivudine and tenofovir are NRTIs that inhibit hepatitis B virus reverse transcriptase (HBV replicates via an RNA intermediate using reverse transcriptase), and are often combined with interferon alpha for chronic HBV treatment.", "incorrectas": {"A": "Zidovudine and abacavir are NRTIs used specifically in HIV antiretroviral regimens, not standard agents for hepatitis B treatment.", "C": "Ribavirin and sofosbuvir are antivirals used for hepatitis C (ribavirin as an adjunct, sofosbuvir as a direct-acting antiviral), not for hepatitis B.", "D": "Emtricitabine and stavudine are NRTIs primarily used in HIV treatment; while emtricitabine has some anti-HBV activity, the classic paired HBV NRTIs highlighted are lamivudine and tenofovir."}}}, {"id": "anking-antimicrobials-1248", "fuente": "anking", "tema": 4, "anki": "1461797786977", "q": "What has traditionally been the standard treatment regimen for chronic hepatitis B?", "o": {"A": "Ribavirin plus sofosbuvir", "B": "Interferon alpha plus lamivudine", "C": "Simeprevir plus tenofovir", "D": "Entecavir plus interferon gamma"}, "r": "B", "e": {"correcta": "The traditional standard treatment for hepatitis B has been interferon alpha combined with the NRTI lamivudine, which suppresses viral replication while boosting the host antiviral immune response; tenofovir may be substituted for lamivudine as an alternative NRTI.", "incorrectas": {"A": "Ribavirin plus sofosbuvir is a hepatitis C regimen (sofosbuvir targets HCV NS5B polymerase), not the traditional standard for hepatitis B.", "C": "Simeprevir is a hepatitis C protease inhibitor, not part of the classic hepatitis B regimen; the traditional HBV standard pairs interferon alpha with an NRTI like lamivudine.", "D": "Interferon gamma is not the interferon type used in hepatitis B treatment; interferon alpha is the one classically combined with lamivudine for chronic HBV therapy."}}}, {"id": "anking-endocrine-physiology-1249", "fuente": "anking", "tema": 23, "anki": "1461865801747", "q": "Newly synthesized cGMP, generated by guanylyl cyclase activity, exerts its physiologic effects by activating which enzyme?", "o": {"A": "Protein kinase A", "B": "Protein kinase C", "C": "Protein kinase G", "D": "Tyrosine kinase"}, "r": "C", "e": {"correcta": "cGMP produced by guanylyl cyclase (either the membrane-bound receptor form activated by ANP or the soluble cytosolic form activated by nitric oxide) activates protein kinase G (PKG), which then phosphorylates target proteins (such as those causing smooth muscle relaxation) to produce the downstream physiologic effects.", "incorrectas": {"A": "Protein kinase A is activated by cAMP downstream of Gs-coupled GPCR signaling, a distinct second-messenger pathway from the cGMP/guanylyl cyclase system.", "B": "Protein kinase C is activated by diacylglycerol (DAG) and calcium downstream of Gq-coupled receptors and phospholipase C activation, not by cGMP.", "D": "Tyrosine kinases are activated in receptor tyrosine kinase or receptor-associated tyrosine kinase pathways (e.g., insulin, growth hormone receptors), an entirely separate signaling mechanism from the guanylyl cyclase/cGMP/PKG cascade."}}}, {"id": "anking-endocrine-physiology-1250", "fuente": "anking", "tema": 23, "anki": "1461865838545", "q": "Which molecule signals through a cytosolic (soluble) guanylyl cyclase rather than a membrane receptor guanylyl cyclase?", "o": {"A": "Atrial natriuretic peptide", "B": "Nitric oxide", "C": "Insulin", "D": "Growth hormone"}, "r": "B", "e": {"correcta": "Nitric oxide diffuses freely across the cell membrane and activates soluble (cytosolic) guanylyl cyclase directly inside the target cell, converting GTP to cGMP, which then activates protein kinase G to produce effects like vascular smooth muscle relaxation.", "incorrectas": {"A": "Atrial natriuretic peptide binds a membrane-bound receptor guanylyl cyclase on the cell surface (not a cytosolic form), triggering intracellular cGMP production from the extracellular side, a distinct mechanism from NO's intracellular diffusion-based activation.", "C": "Insulin signals through a receptor tyrosine kinase (a dimeric receptor with intrinsic tyrosine kinase activity), an entirely separate signaling mechanism unrelated to guanylyl cyclase or cGMP.", "D": "Growth hormone signals through a receptor-associated tyrosine kinase (using JAK/STAT), which is unrelated to the guanylyl cyclase/cGMP pathway used by nitric oxide."}}}, {"id": "anking-endocrine-physiology-1251", "fuente": "anking", "tema": 23, "anki": "1461865849072", "q": "Once nitric oxide diffuses into smooth muscle cells and activates soluble guanylyl cyclase, this enzyme converts GTP into which second messenger?", "o": {"A": "cAMP", "B": "IP3", "C": "cGMP", "D": "DAG"}, "r": "C", "e": {"correcta": "Soluble guanylyl cyclase converts GTP into cGMP, which then activates protein kinase G to relax vascular smooth muscle; this is the same downstream cGMP/PKG mechanism used by ANP, though ANP acts via a membrane receptor guanylyl cyclase rather than a soluble cytosolic one.", "incorrectas": {"A": "cAMP is generated from ATP by adenylyl cyclase downstream of Gs or Gi-coupled GPCRs, a different second-messenger system from the guanylyl cyclase/cGMP pathway activated by nitric oxide.", "B": "IP3 is generated from PIP2 by phospholipase C downstream of Gq-coupled receptors, and it triggers calcium release from the endoplasmic reticulum, a distinct pathway from NO-mediated cGMP production.", "D": "DAG is the other product of PIP2 hydrolysis by phospholipase C (alongside IP3), activating protein kinase C in the Gq pathway, not part of the guanylyl cyclase/cGMP cascade triggered by nitric oxide."}}}, {"id": "anking-endocrine-physiology-1252", "fuente": "anking", "tema": 23, "anki": "1461865862798", "q": "How do atrial natriuretic peptide (ANP) and nitric oxide (NO) differ in how they activate guanylyl cyclase?", "o": {"A": "ANP binds a cytoplasmic guanylyl cyclase; NO binds a membrane receptor guanylyl cyclase", "B": "ANP binds a membrane receptor guanylyl cyclase; NO activates a cytoplasmic guanylyl cyclase", "C": "Both ANP and NO bind the same membrane receptor guanylyl cyclase", "D": "Both ANP and NO activate cytoplasmic guanylyl cyclase after diffusing into the cell"}, "r": "B", "e": {"correcta": "ANP is a peptide that binds an extracellular membrane-bound receptor guanylyl cyclase, activating the intracellular catalytic domain from the outside, whereas nitric oxide is a small, lipophilic gas that diffuses directly into the cell and activates a soluble (cytoplasmic) guanylyl cyclase from within.", "incorrectas": {"A": "This reverses the actual pairing: ANP works through a membrane-bound receptor form (since it cannot cross the membrane), while NO — being membrane-permeant — acts on the cytoplasmic form, not the other way around.", "C": "ANP and NO activate different guanylyl cyclase isoforms located in different cellular compartments (membrane-bound versus cytosolic), so they do not share the same receptor mechanism.", "D": "ANP is a peptide hormone that cannot diffuse across the lipid membrane, so it must act via a surface receptor guanylyl cyclase; only NO, due to its small lipophilic nature, diffuses into the cell to reach the cytoplasmic enzyme."}}}, {"id": "anking-endocrine-physiology-1253", "fuente": "anking", "tema": 23, "anki": "1461865864883", "q": "Protein kinase A and protein kinase C continue the signaling cascade by phosphorylating which two amino acid residues on target proteins?", "o": {"A": "Tyrosine and histidine", "B": "Serine and threonine", "C": "Cysteine and methionine", "D": "Lysine and arginine"}, "r": "B", "e": {"correcta": "Protein kinase A and protein kinase C are serine/threonine kinases that phosphorylate serine and threonine residues on target proteins to propagate their signaling cascades; other kinases such as Ca2+-calmodulin-dependent protein kinase (CaMK) and MAPKs likewise phosphorylate serine and threonine residues.", "incorrectas": {"A": "Tyrosine phosphorylation is the hallmark of receptor tyrosine kinases and receptor-associated tyrosine kinases (e.g., insulin receptor, JAK), a distinct class of kinases from the serine/threonine kinases PKA and PKC.", "C": "Cysteine and methionine are not residues targeted by kinase phosphorylation in these classical signaling cascades; phosphorylation occurs on residues bearing a hydroxyl group (serine, threonine, tyrosine), which cysteine and methionine lack.", "D": "Lysine and arginine are basic amino acids sometimes involved in other post-translational modifications (like methylation or ubiquitination) but are not the residues phosphorylated by PKA or PKC in signal transduction."}}}, {"id": "anking-endocrine-physiology-1254", "fuente": "anking", "tema": 23, "anki": "1461866207939", "q": "Which class of receptors has intrinsic tyrosine kinase activity built into the receptor molecule itself?", "o": {"A": "Receptor-associated tyrosine kinases", "B": "Receptor tyrosine kinases", "C": "Guanylyl cyclase receptors", "D": "Serine/threonine kinase receptors"}, "r": "B", "e": {"correcta": "Receptor tyrosine kinases (e.g., the insulin receptor and receptors for growth factors like NGF and IGF) contain their own intrinsic tyrosine kinase enzymatic activity within the receptor protein, so ligand binding directly triggers autophosphorylation without needing a separate associated kinase.", "incorrectas": {"A": "Receptor-associated tyrosine kinases (used by cytokine receptors and growth hormone receptors) lack intrinsic kinase activity in the receptor itself and instead rely on a separately encoded, non-covalently associated tyrosine kinase such as JAK.", "C": "Guanylyl cyclase receptors (e.g., the ANP receptor) have intrinsic enzymatic activity, but it is guanylyl cyclase activity producing cGMP, not tyrosine kinase activity.", "D": "Serine/threonine kinase receptors (e.g., TGF-beta receptor family) have intrinsic kinase activity, but they phosphorylate serine/threonine residues, not tyrosine, distinguishing them from receptor tyrosine kinases."}}}, {"id": "anking-endocrine-physiology-1255", "fuente": "anking", "tema": 23, "anki": "1461866913033", "q": "Which class of receptors lacks intrinsic kinase activity but instead associates non-covalently with a separate protein (such as JAK) that provides the kinase function?", "o": {"A": "Receptor tyrosine kinases", "B": "Guanylyl cyclase receptors", "C": "Receptor-associated tyrosine kinases", "D": "Nuclear hormone receptors"}, "r": "C", "e": {"correcta": "Receptor-associated tyrosine kinases (used by receptors such as those for growth hormone and many cytokines) do not have kinase activity built into the receptor itself; instead they rely on non-covalent association with separate tyrosine kinase proteins, most notably JAK, which becomes activated upon ligand-induced receptor dimerization.", "incorrectas": {"A": "Receptor tyrosine kinases have their tyrosine kinase activity built directly into the receptor molecule (e.g., insulin receptor), so they do not require a separately associated kinase protein like JAK.", "B": "Guanylyl cyclase receptors have intrinsic guanylyl cyclase enzymatic activity in the receptor itself (producing cGMP), not an associated tyrosine kinase mechanism.", "D": "Nuclear hormone receptors (for steroid/thyroid hormones) act as ligand-activated transcription factors in the cytoplasm or nucleus; they do not use kinase-based membrane signal transduction at all."}}}, {"id": "anking-endocrine-physiology-1256", "fuente": "anking", "tema": 23, "anki": "1461866925105", "q": "One type of receptor tyrosine kinase exists as a monomer that dimerizes and autophosphorylates upon ligand binding. Which of the following is a classic example that signals through this monomeric receptor tyrosine kinase mechanism?", "o": {"A": "Insulin", "B": "Growth hormone", "C": "Nerve growth factor (NGF)", "D": "Interferon alpha"}, "r": "C", "e": {"correcta": "Nerve growth factor (NGF) is a classic example of a ligand that binds a monomeric receptor tyrosine kinase; ligand binding induces dimerization of two monomeric receptors, which then trans-autophosphorylate each other to initiate downstream signaling.", "incorrectas": {"A": "Insulin binds a receptor tyrosine kinase that already exists as a covalently linked dimer (two alpha and two beta subunits) prior to ligand binding, rather than starting as separate monomers that dimerize upon binding like the NGF receptor.", "B": "Growth hormone signals through a receptor-associated tyrosine kinase (via JAK2), not a receptor tyrosine kinase with intrinsic kinase activity, so it does not fit the monomeric RTK dimerization mechanism described.", "D": "Interferon alpha signals through a receptor-associated tyrosine kinase pathway (JAK/STAT), lacking intrinsic tyrosine kinase activity in the receptor itself, unlike the monomeric receptor tyrosine kinase mechanism used by NGF."}}}, {"id": "anking-endocrine-physiology-1257", "fuente": "anking", "tema": 23, "anki": "1461866979051", "q": "One type of receptor tyrosine kinase exists as a preformed dimer that autophosphorylates upon ligand binding. Which hormone is the classic example that signals through this preformed dimeric receptor tyrosine kinase?", "o": {"A": "Nerve growth factor (NGF)", "B": "Insulin", "C": "Growth hormone", "D": "Erythropoietin"}, "r": "B", "e": {"correcta": "Insulin (along with insulin-like growth factors, IGF) binds a receptor tyrosine kinase that is already a covalently-linked dimer (composed of two alpha and two beta subunits) before ligand binding; hormone binding to the alpha subunits triggers autophosphorylation of the beta subunits' intracellular tyrosine kinase domains.", "incorrectas": {"A": "NGF is the classic example of a receptor tyrosine kinase that starts as separate monomers, which then dimerize upon ligand binding, in contrast to the insulin receptor, which is already dimeric before binding occurs.", "C": "Growth hormone acts through a receptor-associated tyrosine kinase (JAK2-dependent) mechanism, not an intrinsic receptor tyrosine kinase, so it does not fit the preformed dimer RTK category with insulin.", "D": "Erythropoietin also signals via a receptor-associated tyrosine kinase (JAK2), lacking intrinsic tyrosine kinase activity in the receptor, unlike the insulin receptor's built-in kinase domains."}}}, {"id": "anking-endocrine-physiology-1258", "fuente": "anking", "tema": 23, "anki": "1461866992917", "q": "Receptor-associated tyrosine kinases are non-covalently linked to which classic associated kinase protein?", "o": {"A": "MAPK", "B": "JAK", "C": "PKA", "D": "PI3K"}, "r": "B", "e": {"correcta": "Receptor-associated tyrosine kinases, such as those used by growth hormone, prolactin, and many cytokine receptors, lack their own intrinsic kinase domain and instead non-covalently associate with JAK (Janus kinase); ligand-induced receptor dimerization brings two JAK molecules together to trans-activate one another.", "incorrectas": {"A": "MAPK (mitogen-activated protein kinase) acts further downstream in many signaling cascades (including after receptor tyrosine kinase activation), but it is not the kinase that directly, non-covalently associates with the receptor itself in the JAK-type pathway.", "C": "PKA is activated by cAMP downstream of Gs-coupled GPCR signaling, an entirely separate signal transduction pathway from receptor-associated tyrosine kinase receptors.", "D": "PI3K is an important downstream signaling enzyme activated in several pathways (including insulin signaling), but it is not the kinase directly associated with the receptor in the classic receptor-associated tyrosine kinase/JAK mechanism."}}}, {"id": "anking-endocrine-physiology-1259", "fuente": "anking", "tema": 23, "anki": "1461867008556", "q": "In the JAK-dependent, receptor-associated tyrosine kinase pathway, activated JAK phosphorylates which downstream targets that then translocate to the nucleus to drive new mRNA and protein synthesis?", "o": {"A": "STATs", "B": "SMADs", "C": "CREB", "D": "NF-kB"}, "r": "A", "e": {"correcta": "Activated JAK phosphorylates STAT (signal transducer and activator of transcription) proteins, which then dimerize and translocate into the nucleus to act as transcription factors, driving new mRNA transcription and protein synthesis in response to hormones like growth hormone and cytokines.", "incorrectas": {"B": "SMAD proteins are the downstream transcription factors activated by the serine/threonine kinase receptor pathway (e.g., TGF-beta signaling), not by the JAK-associated receptor tyrosine kinase pathway.", "C": "CREB is a transcription factor activated downstream of the cAMP/PKA pathway, phosphorylated by PKA rather than by JAK, representing a distinct signaling cascade.", "D": "NF-kB is a transcription factor typically activated downstream of pathways like TNF/Toll-like receptor signaling and IkB degradation, not the direct target of JAK phosphorylation in the growth hormone/cytokine receptor pathway."}}}, {"id": "anking-endocrine-physiology-1260", "fuente": "anking", "tema": 23, "anki": "1461867010914", "q": "Growth hormone exerts its signaling effects through which type of cell surface receptor?", "o": {"A": "Receptor tyrosine kinase", "B": "Guanylyl cyclase receptor", "C": "Receptor-associated tyrosine kinase", "D": "Nuclear steroid receptor"}, "r": "C", "e": {"correcta": "Growth hormone signals through a receptor-associated tyrosine kinase, specifically activating JAK2, which phosphorylates STAT proteins that translocate to the nucleus to alter gene transcription; the growth hormone receptor itself lacks intrinsic catalytic kinase activity.", "incorrectas": {"A": "Receptor tyrosine kinases (like the insulin receptor) have intrinsic tyrosine kinase activity built into the receptor itself, which is different from growth hormone's mechanism of relying on a separately associated JAK kinase.", "B": "Guanylyl cyclase receptors (used by ANP) produce cGMP as a second messenger, an entirely different catalytic mechanism from the JAK/STAT pathway used by growth hormone.", "D": "Nuclear steroid receptors are used by lipophilic hormones like cortisol and estrogen that diffuse into the cell to bind intracellular receptors, a fundamentally different mechanism from growth hormone's cell-surface receptor-associated tyrosine kinase signaling."}}}, {"id": "anking-endocrine-physiology-1261", "fuente": "anking", "tema": 23, "anki": "1461867085192", "q": "How do the receptors for steroid and thyroid hormones differ from those used by peptide hormones?", "o": {"A": "Peptide hormones bind extracellular (cell surface) receptors, while steroid/thyroid hormones bind intracellular receptors", "B": "Steroid/thyroid hormones bind extracellular receptors, while peptide hormones bind intracellular receptors", "C": "Both bind extracellular receptors but use different second messengers", "D": "Both bind intracellular receptors but differ in dimerization"}, "r": "A", "e": {"correcta": "Peptide hormones are hydrophilic and cannot cross the plasma membrane, so they bind extracellular (cell-surface) receptors that trigger intracellular second-messenger cascades, whereas steroid and thyroid hormones are lipophilic, diffuse across the membrane, and bind cytosolic or nuclear receptors directly to act as transcription factors.", "incorrectas": {"B": "This reverses the true relationship: steroid and thyroid hormones are lipid-soluble and can cross the membrane to bind intracellular (cytosolic/nuclear) receptors, while peptide hormones, being hydrophilic, must act on cell-surface receptors instead.", "C": "Peptide hormones use extracellular receptors and intracellular second messengers, but steroid/thyroid hormones do not act via extracellular receptors at all — they bind intracellular receptors and directly regulate gene transcription without a conventional second-messenger cascade.", "D": "Only steroid/thyroid hormones bind intracellular receptors; peptide hormones act on extracellular, cell-surface receptors, so the premise that both use intracellular receptors is incorrect."}}}, {"id": "anking-endocrine-physiology-1262", "fuente": "anking", "tema": 23, "anki": "1461867860665", "q": "Relative to peptide hormones, how does the time course of steroid hormone action typically compare?", "o": {"A": "Steroid hormones act within seconds, faster than peptide hormones", "B": "Steroid hormones act slowly over hours, while peptide hormones act quickly within minutes", "C": "Both act within minutes with no meaningful difference", "D": "Steroid hormones act faster than peptide hormones because they use second messengers"}, "r": "B", "e": {"correcta": "Steroid hormones act slowly, over a time course of hours, because their mechanism requires diffusion into the cell, receptor binding, dimerization, gene transcription, and new protein synthesis, whereas peptide hormones act rapidly (within minutes) via cell-surface receptors and pre-existing second-messenger systems that modify existing proteins.", "incorrectas": {"A": "Steroid hormones are notably slow-acting due to their transcription-dependent mechanism; it is peptide hormones, not steroids, that act rapidly (within minutes) via second-messenger cascades on existing proteins.", "C": "There is a well-recognized and clinically important difference in onset: peptide hormones act within minutes, while steroid hormones require hours because they must alter gene expression and synthesize new proteins.", "D": "Steroid hormones do not use classic second-messenger systems and are actually slower, not faster, than peptide hormones, since their genomic mechanism of action inherently takes longer than direct second-messenger signaling."}}}, {"id": "anking-endocrine-physiology-1263", "fuente": "anking", "tema": 23, "anki": "1461867864150", "q": "After a steroid hormone binds its receptor in the cytoplasm or nucleus, what does the hormone-receptor complex do next to affect gene transcription?", "o": {"A": "It phosphorylates cytoplasmic kinases", "B": "It dimerizes", "C": "It is degraded by the proteasome immediately", "D": "It binds a G protein"}, "r": "B", "e": {"correcta": "Once a steroid hormone binds its intracellular receptor, the hormone-receptor complex dimerizes (typically forming a homodimer), which is necessary for the complex to translocate to (or remain in) the nucleus and bind hormone response elements on DNA to regulate gene transcription.", "incorrectas": {"A": "Steroid hormone receptors act as transcription factors, not kinases, and do not phosphorylate cytoplasmic kinases as part of their mechanism; this contrasts with membrane receptor pathways that do rely on kinase cascades.", "C": "The hormone-receptor complex is not immediately degraded; rather it dimerizes and goes on to actively regulate transcription, with degradation occurring later as part of normal receptor turnover, not as the immediate next step after binding.", "D": "Steroid hormone receptors are intracellular/nuclear receptors that act directly as transcription factors; they do not couple to G proteins, which is a mechanism used by membrane-bound GPCRs for peptide/catecholamine hormones instead."}}}, {"id": "anking-endocrine-physiology-1264", "fuente": "anking", "tema": 23, "anki": "1461867900413", "q": "What is the ultimate downstream effect produced by steroid hormone-receptor complexes after they bind DNA?", "o": {"A": "Immediate opening of ion channels", "B": "Activation of second-messenger cascades", "C": "Synthesis of new proteins", "D": "Direct enzymatic modification of existing membrane receptors"}, "r": "C", "e": {"correcta": "Steroid hormone-receptor complexes act as transcription factors that bind hormone response elements on DNA, altering gene expression and ultimately leading to the synthesis of new proteins, which mediate the physiologic effects of the hormone; this is why steroid hormone action is comparatively slow (hours).", "incorrectas": {"A": "Direct opening of ion channels is a mechanism associated with ligand-gated ion channel receptors (e.g., nicotinic ACh receptors), not with the transcription-factor mechanism used by steroid hormone receptors.", "B": "Second-messenger cascades (like cAMP or IP3 generation) are characteristic of cell-surface peptide hormone receptors, not steroid hormone receptors, which act directly on gene transcription rather than through second messengers.", "D": "Steroid hormones do not directly modify existing membrane receptors enzymatically; their mechanism is genomic, altering transcription and translation to produce new proteins rather than acting post-translationally on pre-existing receptors."}}}, {"id": "anking-endocrine-physiology-1265", "fuente": "anking", "tema": 23, "anki": "1461871709857", "q": "The family of hormones derived from proopiomelanocortin (POMC) processing includes melanocyte-stimulating hormone, gamma- and beta-lipotropin, and beta-endorphin, along with which other hormone?", "o": {"A": "TSH", "B": "ACTH", "C": "Prolactin", "D": "FSH"}, "r": "B", "e": {"correcta": "ACTH, along with melanocyte-stimulating hormone (MSH), gamma- and beta-lipotropin, and beta-endorphin, are all cleavage products of the common precursor protein proopiomelanocortin (POMC), which explains the shared structural motifs among these seemingly unrelated hormones/peptides.", "incorrectas": {"A": "TSH is a distinct anterior pituitary glycoprotein hormone (sharing an alpha subunit with LH, FSH, and hCG) that is not derived from POMC processing, unlike ACTH and its related peptides.", "C": "Prolactin is a separate anterior pituitary hormone structurally related to growth hormone and human placental lactogen, not part of the POMC-derived family that includes ACTH, MSH, lipotropins, and beta-endorphin.", "D": "FSH, like TSH and LH, is a glycoprotein hormone sharing a common alpha subunit, and is unrelated to the POMC precursor pathway that produces ACTH, MSH, lipotropins, and beta-endorphin."}}}, {"id": "anking-endocrine-anatomy-1266", "fuente": "anking", "tema": 25, "anki": "1461871735495", "q": "Alpha-MSH and beta-MSH are produced in which lobe of the pituitary gland, a structure that is largely rudimentary in adult humans?", "o": {"A": "Anterior lobe", "B": "Posterior lobe", "C": "Intermediate lobe", "D": "Tuberal region"}, "r": "C", "e": {"correcta": "Alpha-MSH and beta-MSH are produced in the intermediate lobe of the pituitary, a thin layer of tissue situated between the anterior and posterior lobes that is prominent in fetal life but becomes largely vestigial/rudimentary in adult humans.", "incorrectas": {"A": "The anterior lobe (adenohypophysis) produces the major pituitary hormones like ACTH, GH, TSH, FSH, LH, and prolactin, but MSH production is specifically attributed to the intermediate lobe, a distinct structure between the anterior and posterior lobes.", "B": "The posterior lobe (neurohypophysis) stores and releases oxytocin and ADH, which are synthesized in the hypothalamus, and is not the source of MSH production.", "D": "The tuberal region of the pituitary/hypothalamic stalk is not classically identified as the site of MSH synthesis; that role belongs specifically to the intermediate lobe."}}}, {"id": "anking-endocrine-physiology-1267", "fuente": "anking", "tema": 23, "anki": "1461871803920", "q": "Which hormone is considered the single most important factor for normal growth to adult size?", "o": {"A": "Insulin-like growth factor 1 alone", "B": "Growth hormone", "C": "Thyroid hormone", "D": "Cortisol"}, "r": "B", "e": {"correcta": "Growth hormone (GH) is the single most important hormone for achieving normal growth to adult size, acting both directly and by stimulating hepatic and peripheral production of IGF-1, which mediates many of its growth-promoting effects on bone and soft tissue.", "incorrectas": {"A": "IGF-1 is a critical downstream mediator of many of GH's growth effects, but it is GH itself that is considered the primary driver, with IGF-1 acting as an important effector rather than being the single most important hormone on its own.", "C": "Thyroid hormone is necessary for normal growth and skeletal maturation (its deficiency causes growth failure), but it is a permissive/supportive factor rather than being the single most important hormone for overall growth to adult size, a role attributed to GH.", "D": "Cortisol, especially in excess, actually impairs growth (as seen in Cushing syndrome with growth retardation in children); it is not considered a primary growth-promoting hormone like GH."}}}, {"id": "anking-endocrine-physiology-1268", "fuente": "anking", "tema": 23, "anki": "1461875768373", "q": "Growth hormone is a single-chain polypeptide structurally homologous to human placental lactogen and which other hormone?", "o": {"A": "Prolactin", "B": "Thyroid-stimulating hormone", "C": "Insulin", "D": "Follicle-stimulating hormone"}, "r": "A", "e": {"correcta": "Growth hormone is structurally homologous to prolactin and human placental lactogen; all three are single-chain polypeptide hormones believed to have arisen from a common ancestral gene, which explains their overlapping structural features and some shared receptor-signaling characteristics.", "incorrectas": {"B": "TSH is a glycoprotein hormone made of alpha and beta subunits (sharing its alpha subunit with LH, FSH, and hCG), structurally distinct from the single-chain polypeptide family that includes GH, prolactin, and placental lactogen.", "C": "Insulin is a distinct polypeptide hormone with a different structure (two chains linked by disulfide bonds) and signals through a receptor tyrosine kinase, and it is not part of the GH/prolactin/placental lactogen homologous family.", "D": "FSH, like TSH, is a glycoprotein hormone with a shared alpha subunit structure, unrelated to the single-chain polypeptide homology shared by growth hormone, prolactin, and human placental lactogen."}}}, {"id": "anking-endocrine-physiology-1269", "fuente": "anking", "tema": 23, "anki": "1461875806897", "q": "Growth hormone is released from the anterior pituitary in what secretion pattern?", "o": {"A": "Continuous, steady-state secretion", "B": "Pulsatile secretion, with bursts occurring approximately every 2 hours", "C": "A single large surge at puberty only", "D": "Only in response to hypoglycemia"}, "r": "B", "e": {"correcta": "Growth hormone is secreted in a pulsatile pattern, with discrete bursts of release occurring approximately every 2 hours throughout the day, reflecting the episodic pattern of hypothalamic GHRH stimulation and somatostatin inhibition.", "incorrectas": {"A": "GH secretion is not continuous or steady; it is characteristically pulsatile, which is why isolated random GH levels are not clinically useful for diagnosis and provocative or suppression testing is needed instead.", "C": "While GH secretion does increase during puberty as part of the growth spurt, it is not limited to a single surge at that time; pulsatile secretion occurs throughout life, with peak amplitude during adolescence.", "D": "Hypoglycemia is one of several stimuli that can trigger GH release (used clinically in GH stimulation testing), but GH secretion is not restricted only to hypoglycemic episodes — it occurs in a regular pulsatile pattern under normal physiologic conditions."}}}, {"id": "anking-endocrine-physiology-1270", "fuente": "anking", "tema": 23, "anki": "1461875813135", "q": "The largest secretory burst of growth hormone during the day typically occurs within an hour of which event?", "o": {"A": "Waking up in the morning", "B": "A high-protein meal", "C": "Falling asleep", "D": "Peak daytime cortisol secretion"}, "r": "C", "e": {"correcta": "The largest pulsatile burst of growth hormone secretion occurs within about an hour of falling asleep, coinciding with the onset of slow-wave (deep) sleep, which is why adequate sleep is important for normal growth, particularly in children and adolescents.", "incorrectas": {"A": "Waking up is not associated with the largest GH secretory burst; the major surge is tied to sleep onset (specifically slow-wave sleep), not the transition out of sleep.", "B": "While exercise and certain nutritional stimuli can modestly increase GH secretion, the single largest physiologic burst of GH release is linked to falling asleep, not to meals.", "D": "Cortisol secretion follows its own distinct circadian rhythm (peaking in the early morning), which is different from and not the trigger for the sleep-onset-associated GH secretory burst."}}}, {"id": "anking-endocrine-physiology-1271", "fuente": "anking", "tema": 23, "anki": "1461875836893", "q": "At puberty, an enormous secretory burst of growth hormone occurs, driven by rising sex steroid levels. Which life stage is this pubertal GH surge classically associated with?", "o": {"A": "Menopause", "B": "Puberty", "C": "Early infancy", "D": "Mid-adulthood"}, "r": "B", "e": {"correcta": "At puberty, rising estrogen (in females) or testosterone (in males, largely via aromatization to estrogen) markedly increases the frequency and amplitude of GH secretory pulses from somatotrophs. This estrogen-driven GH surge underlies the pubertal growth spurt, the rapid increase in height velocity seen in early-to-mid puberty.", "incorrectas": {"A": "Menopause is characterized by declining estrogen and rising gonadotropins (FSH/LH), not a GH secretory burst; GH pulsatility actually tends to decline with aging.", "C": "Early infancy has relatively high GH levels but the classic enormous secretory burst tied to sex steroid rise is a pubertal phenomenon, not an infantile one.", "D": "Mid-adulthood is associated with declining GH pulse amplitude (somatopause), the opposite of the pubertal surge described."}}}, {"id": "anking-endocrine-physiology-1272", "fuente": "anking", "tema": 23, "anki": "1461875856182", "q": "What is the effect of hypoglycemia and starvation on growth hormone secretion?", "o": {"A": "No change", "B": "Increased", "C": "Decreased", "D": "Biphasic: initial increase then suppression"}, "r": "B", "e": {"correcta": "Hypoglycemia and starvation stimulate GH secretion as part of the counter-regulatory response to low glucose availability. GH raises blood glucose by decreasing peripheral glucose uptake and promoting lipolysis, providing alternative fuel and sparing glucose for the brain during fasting states.", "incorrectas": {"A": "GH secretion is not static during metabolic stress; hypoglycemia is actually one of the most potent physiologic stimuli for GH release, used clinically in the insulin tolerance test to assess GH reserve.", "C": "Decreased GH secretion occurs with hyperglycemia and obesity, the opposite metabolic state from hypoglycemia/starvation.", "D": "There is no biphasic suppression pattern; GH secretion remains elevated as long as the hypoglycemic/fasting stimulus persists, since it functions to counteract low glucose."}}}, {"id": "anking-endocrine-physiology-1273", "fuente": "anking", "tema": 23, "anki": "1461875931305", "q": "Growth hormone secretion shows a characteristic pattern tied to sleep. During which sleep stage(s) is GH secretion increased?", "o": {"A": "REM sleep", "B": "Stage I sleep only", "C": "Stage III and IV (slow-wave) sleep", "D": "GH is unaffected by sleep stage"}, "r": "C", "e": {"correcta": "GH secretion peaks during slow-wave sleep (stages III and IV), which is why the largest daily GH pulse typically occurs shortly after sleep onset. This is clinically relevant because sleep deprivation or disorders that reduce slow-wave sleep can blunt nocturnal GH release and, in children, impair growth.", "incorrectas": {"A": "REM sleep is associated with muscle atonia and vivid dreaming but is not the sleep stage linked to the major nocturnal GH pulse.", "B": "Stage I sleep is the lightest stage of transition into sleep and is not associated with the GH secretory burst; the burst requires deeper slow-wave sleep.", "D": "GH secretion is strongly sleep-stage dependent, with slow-wave sleep being the key trigger for the largest pulsatile release of the day."}}}, {"id": "anking-endocrine-physiology-1274", "fuente": "anking", "tema": 23, "anki": "1461875941713", "q": "What is the effect of obesity, pregnancy, and hyperglycemia on growth hormone secretion?", "o": {"A": "Increased", "B": "No effect", "C": "Decreased", "D": "Increased only in pregnancy"}, "r": "C", "e": {"correcta": "Obesity, pregnancy, and hyperglycemia all suppress GH secretion. Elevated glucose and increased circulating free fatty acids/IGF-like signals provide negative feedback on somatotrophs and stimulate hypothalamic somatostatin release, reducing pulsatile GH output.", "incorrectas": {"A": "Increased GH secretion is seen with opposing stimuli such as hypoglycemia, fasting, exercise, and stress, not with obesity, pregnancy, or hyperglycemia.", "B": "These states do have a clear physiologic effect on GH; they are not neutral, but rather potent inhibitory influences on the somatotroph axis.", "D": "Pregnancy itself does not selectively raise pituitary GH; in fact placental GH variants rise while pituitary GH secretion is suppressed similarly to the other listed states."}}}, {"id": "anking-endocrine-physiology-1275", "fuente": "anking", "tema": 23, "anki": "1461875953752", "q": "What is the effect of exercise and stress on growth hormone secretion?", "o": {"A": "Decreased", "B": "No change", "C": "Increased", "D": "Suppressed acutely, then increased after 24 hours"}, "r": "C", "e": {"correcta": "Exercise and stress both increase GH secretion, consistent with GH's role as a counter-regulatory, catabolic-state hormone that mobilizes energy substrates (via lipolysis and decreased peripheral glucose uptake) when the body faces increased metabolic demand.", "incorrectas": {"A": "Decreased GH secretion occurs in the opposite physiologic context, such as hyperglycemia, obesity, or high somatostatin/IGF-1 tone, not during exercise or stress.", "B": "Exercise and stress are well-established potent stimuli of pulsatile GH release, so there is a clear, reproducible increase rather than no change.", "D": "The GH rise with exercise/stress is relatively prompt (within the exercise bout or acute stress response), not delayed by 24 hours."}}}, {"id": "anking-endocrine-physiology-1276", "fuente": "anking", "tema": 23, "anki": "1461875965165", "q": "What is the effect of somatostatin on growth hormone secretion from the anterior pituitary?", "o": {"A": "Increased, via cAMP", "B": "No direct effect", "C": "Decreased", "D": "Increased, via IP3/Ca2+"}, "r": "C", "e": {"correcta": "Somatostatin (also called growth hormone release-inhibiting hormone, or SRIF) is released from the hypothalamus and binds Gi-coupled receptors on somatotrophs, decreasing cAMP and thereby inhibiting GH synthesis and secretion. It is the counterbalance to GHRH in regulating pulsatile GH release.", "incorrectas": {"B": "Somatostatin has a well-defined direct inhibitory action on somatotrophs; it is not merely a bystander hormone but an active suppressor of GH release.", "A": "Increased GH via cAMP describes the action of GHRH (a stimulatory hormone acting through Gs/cAMP), which is the opposite of somatostatin's inhibitory Gi-mediated effect.", "D": "Increased secretion via IP3/Ca2+ also describes a stimulatory pathway (part of GHRH signaling), not the inhibitory somatostatin pathway."}}}, {"id": "anking-endocrine-physiology-1277", "fuente": "anking", "tema": 23, "anki": "1461875973910", "q": "The synthesis of growth hormone by somatotrophs is stimulated by which hypothalamic hormone?", "o": {"A": "Thyrotropin-releasing hormone (TRH)", "B": "Somatostatin", "C": "Growth-hormone releasing hormone (GHRH)", "D": "Dopamine"}, "r": "C", "e": {"correcta": "GHRH is released from hypothalamic neurons into the hypophyseal portal system and binds Gs-coupled receptors on somatotrophs, increasing cAMP and stimulating both GH synthesis and secretion. It is the primary positive driver of the GH axis.", "incorrectas": {"A": "TRH stimulates TSH and prolactin release from the anterior pituitary, not GH; it is not a physiologic regulator of the somatotroph axis.", "B": "Somatostatin is the release-inhibiting hormone for GH, exerting the opposite (inhibitory) effect of GHRH.", "D": "Dopamine primarily inhibits prolactin secretion from lactotrophs; it is not the stimulatory hormone for GH synthesis."}}}, {"id": "anking-endocrine-physiology-1278", "fuente": "anking", "tema": 23, "anki": "1461875983115", "q": "The synthesis of growth hormone is inhibited by which hypothalamic hormone (also known as somatotropin release-inhibiting factor, SRIF)?", "o": {"A": "GHRH", "B": "Somatostatin", "C": "Prolactin", "D": "IGF-1"}, "r": "B", "e": {"correcta": "Somatostatin, also called somatotropin release-inhibiting factor (SRIF), is secreted by the hypothalamus and inhibits both the synthesis and secretion of GH from somatotrophs. It acts as the primary brake on the GH axis, opposing GHRH.", "incorrectas": {"A": "GHRH stimulates rather than inhibits GH synthesis; it is the counterpart hormone that promotes somatotroph activity.", "C": "Prolactin is a separate anterior pituitary hormone secreted by lactotrophs; it is not the hypothalamic inhibitor of GH synthesis.", "D": "IGF-1 does provide negative feedback on GH secretion, but it does so peripherally (and by stimulating hypothalamic somatostatin) rather than being the hypothalamic release-inhibiting hormone itself, which is somatostatin."}}}, {"id": "anking-endocrine-physiology-1279", "fuente": "anking", "tema": 23, "anki": "1461876028006", "q": "Through which second messenger system(s) does GHRH act on somatotrophs to stimulate growth hormone release?", "o": {"A": "IP3/Ca2+ only", "B": "cGMP only", "C": "Both cAMP (primarily) and IP3/Ca2+", "D": "Tyrosine kinase activity"}, "r": "C", "e": {"correcta": "GHRH binds a Gs-protein coupled receptor on somatotrophs, primarily activating adenylate cyclase to raise intracellular cAMP, with a secondary contribution from the IP3/Ca2+ pathway. Together these signals promote GH gene transcription and secretory vesicle release.", "incorrectas": {"A": "IP3/Ca2+ alone is only a secondary contributor to GHRH signaling; the dominant pathway is cAMP-mediated, so this option is incomplete.", "B": "cGMP is not the second messenger used by GHRH receptor signaling; it is more relevant to pathways like nitric oxide/natriuretic peptide signaling.", "D": "Tyrosine kinase activity describes receptors like the IGF-1 or insulin receptor, not the G-protein coupled GHRH receptor on somatotrophs."}}}, {"id": "anking-endocrine-physiology-1280", "fuente": "anking", "tema": 23, "anki": "1461876075319", "q": "How does GHRH affect its own secretion from the hypothalamus?", "o": {"A": "Increases it via a positive feedback loop", "B": "Has no effect on its own secretion", "C": "Decreases it via ultrashort-loop negative feedback", "D": "Increases it indirectly through IGF-1"}, "r": "C", "e": {"correcta": "GHRH exerts an ultrashort-loop negative feedback on its own hypothalamic secretion, meaning the hormone inhibits release of more of itself independent of downstream pituitary or peripheral hormones. This is one of several feedback tiers (short-loop, ultrashort-loop) that finely tune GH axis pulsatility.", "incorrectas": {"A": "A positive feedback loop would cause unchecked amplification of GHRH release, which is not how the hypothalamic-pituitary axis is regulated; feedback here is inhibitory.", "B": "GHRH does have a demonstrated effect on its own secretion (ultrashort-loop inhibition), so 'no effect' is inaccurate.", "D": "IGF-1 mediates long-loop negative feedback on GH and GHRH/somatostatin release, but the ultrashort-loop effect described is GHRH acting directly on itself, independent of IGF-1."}}}, {"id": "anking-endocrine-physiology-1281", "fuente": "anking", "tema": 23, "anki": "1461876115915", "q": "When growth hormone acts on target tissue, it stimulates production of a class of mediators produced predominantly by the liver. What are these mediators called?", "o": {"A": "Somatomedins (IGFs)", "B": "Thyroid hormones", "C": "Glucocorticoids", "D": "Catecholamines"}, "r": "A", "e": {"correcta": "GH stimulates the liver (and, to a lesser extent, other tissues) to produce somatomedins, chiefly insulin-like growth factors (IGFs), which mediate most of GH's growth-promoting effects on bone, cartilage, and muscle. This indirect, IGF-mediated action is the main mechanism behind GH-induced linear growth.", "incorrectas": {"B": "Thyroid hormones (T3/T4) are produced by the thyroid gland under TSH control and are unrelated to the GH-stimulated hepatic mediators described here.", "C": "Glucocorticoids are produced by the adrenal cortex under ACTH control, not by the liver in response to GH.", "D": "Catecholamines are produced by the adrenal medulla and sympathetic neurons, not generated by the liver as a downstream effector of GH."}}}, {"id": "anking-endocrine-physiology-1282", "fuente": "anking", "tema": 23, "anki": "1461877961265", "q": "The insulin-like growth factor (IGF) receptor has what type of intrinsic enzymatic activity, similar to the insulin receptor?", "o": {"A": "Serine/threonine kinase", "B": "Guanylate cyclase", "C": "Tyrosine kinase", "D": "Phospholipase C"}, "r": "C", "e": {"correcta": "The IGF-1 receptor is structurally and functionally homologous to the insulin receptor, both being receptor tyrosine kinases. Ligand binding triggers autophosphorylation of tyrosine residues, activating downstream signaling cascades (e.g., RAS/MAPK and PI3K/AKT) that promote cell growth, proliferation, and metabolic effects.", "incorrectas": {"A": "Serine/threonine kinase receptors are characteristic of the TGF-beta superfamily (e.g., activin, BMP receptors), not the IGF/insulin receptor family.", "B": "Guanylate cyclase activity is found in receptors for atrial natriuretic peptide, not IGF or insulin receptors.", "D": "Phospholipase C activation is typically downstream of Gq-coupled GPCRs, not the mechanism by which the IGF receptor itself signals; the IGF receptor's intrinsic activity is tyrosine kinase."}}}, {"id": "anking-endocrine-physiology-1283", "fuente": "anking", "tema": 23, "anki": "1461877968926", "q": "One direct (non-IGF-mediated) action of growth hormone on peripheral tissue is decreased glucose uptake into cells. What effect does this have on blood glucose concentration?", "o": {"A": "Decreased blood glucose", "B": "Increased blood glucose", "C": "No change in blood glucose", "D": "Blood glucose becomes unmeasurable due to hemolysis"}, "r": "B", "e": {"correcta": "GH directly antagonizes insulin action, decreasing glucose uptake into peripheral cells (a diabetogenic effect), which raises blood glucose concentration. This insulin-resistance effect mimics diabetes mellitus and explains why excess GH (as in acromegaly) can cause secondary hyperglycemia or overt diabetes.", "incorrectas": {"A": "Decreased blood glucose would be the expected effect of increased glucose uptake or insulin action, which is the opposite of GH's diabetogenic, insulin-antagonistic effect.", "C": "GH has a well-documented direct effect on glucose homeostasis; it is not glucose-neutral, since chronic GH excess produces measurable hyperglycemia and glucose intolerance.", "D": "This is a nonsensical distractor; GH's effect on glucose is a genuine physiologic/metabolic action, not an artifact of sample handling."}}}, {"id": "anking-endocrine-physiology-1284", "fuente": "anking", "tema": 23, "anki": "1461877995639", "q": "What direct action does growth hormone have on lipolysis in adipose tissue?", "o": {"A": "Decreased", "B": "Increased", "C": "No effect", "D": "Increased only in the presence of insulin"}, "r": "B", "e": {"correcta": "GH directly stimulates lipolysis in adipose tissue, increasing release of free fatty acids into the circulation. This provides an alternative energy substrate to spare glucose and protein, consistent with GH's overall role as a catabolic, fuel-mobilizing hormone during fasting, stress, or exercise.", "incorrectas": {"A": "Decreased lipolysis would be an anti-catabolic, fat-storing effect, which contradicts GH's known role in promoting fat breakdown and mobilization of free fatty acids.", "C": "GH has a clear, direct stimulatory effect on lipolysis; describing it as having no effect ignores a core physiologic action used to differentiate GH from purely anabolic hormones like insulin.", "D": "GH's lipolytic effect does not require concurrent insulin; in fact, GH's actions on lipid and glucose metabolism generally oppose insulin's actions rather than depending on it."}}}, {"id": "anking-endocrine-physiology-1285", "fuente": "anking", "tema": 23, "anki": "1461878001216", "q": "How does growth hormone affect protein synthesis and lean body mass?", "o": {"A": "Decreased", "B": "No change", "C": "Increased", "D": "Increased only during childhood, absent in adults"}, "r": "C", "e": {"correcta": "GH increases protein synthesis and promotes an anabolic, nitrogen-retaining state, leading to increased lean body mass and organ growth. This effect, largely mediated through IGF-1, is why GH deficiency in adults leads to decreased lean mass and why GH is used clinically to promote growth and anabolism.", "incorrectas": {"A": "Decreased protein synthesis would be a catabolic effect, contrary to GH's well-established anabolic action on skeletal muscle and organ tissue.", "B": "GH has a clear, measurable anabolic effect on protein synthesis and lean mass; describing it as unchanged ignores this core physiologic function.", "D": "While the effect is most dramatic during growth (childhood/adolescence), adult GH deficiency also demonstrably reduces lean body mass, showing the anabolic effect persists into adulthood, just less dramatically for linear growth."}}}, {"id": "anking-endocrine-physiology-1286", "fuente": "anking", "tema": 23, "anki": "1461878021280", "q": "What direct action does growth hormone have on hepatic production of insulin-like growth factor (IGF)?", "o": {"A": "Decreased", "B": "Increased", "C": "No effect", "D": "Biphasic: acute suppression followed by delayed increase"}, "r": "B", "e": {"correcta": "GH directly increases hepatic (and local tissue) production of IGF-1, which then mediates most of GH's growth-promoting effects, including increased lean body mass, organ size, and linear growth. This GH-to-IGF-1 axis is the central mechanism by which pituitary GH translates into peripheral anabolic and growth effects.", "incorrectas": {"A": "Decreased IGF production would undermine GH's growth-promoting role; GH's defining action on the liver is to stimulate, not suppress, IGF-1 synthesis.", "C": "GH has a well-characterized stimulatory effect on hepatic IGF-1 production; describing this as absent contradicts the core GH-IGF axis physiology.", "D": "There is no clinically significant biphasic suppression-then-increase pattern; GH's stimulatory effect on IGF-1 production is a straightforward, sustained increase."}}}, {"id": "anking-endocrine-physiology-1287", "fuente": "anking", "tema": 23, "anki": "1461878037901", "q": "Growth hormone/IGF-1 alters cartilage metabolism, chiefly by stimulating chondrocytes in growth plates, to increase which type of growth?", "o": {"A": "Appositional (width) growth only", "B": "Linear growth", "C": "Epiphyseal closure", "D": "Cartilage calcification exclusively"}, "r": "B", "e": {"correcta": "GH/IGF-1 increases protein synthesis in chondrocytes at the epiphyseal growth plates, driving linear (longitudinal) bone growth. Notably, unlike estrogen, IGF-1 does not accelerate epiphyseal closure, which is why unopposed GH excess (before closure) can cause gigantism rather than premature cessation of growth.", "incorrectas": {"A": "While bone can grow in width via periosteal appositional growth, the classic GH/IGF-1 action highlighted for chondrocytes at growth plates is longitudinal (linear) growth, not width.", "C": "Epiphyseal closure is actually a process accelerated by estrogen, not IGF-1; IGF-1 is specifically noted to lack this closure-promoting effect, distinguishing it from sex steroids.", "D": "Cartilage calcification is part of endochondral ossification generally, but the specific highlighted GH/IGF-1 effect is on chondrocyte proliferation/protein synthesis driving linear growth, not calcification per se."}}}, {"id": "anking-endocrine-pharmacology-1288", "fuente": "anking", "tema": 24, "anki": "1461878157516", "q": "Conditions with excess growth hormone (e.g., acromegaly) may be treated with analogues of which hormone, such as octreotide, to inhibit GH secretion?", "o": {"A": "Growth-hormone releasing hormone (GHRH)", "B": "Dopamine", "C": "Somatostatin", "D": "Thyrotropin-releasing hormone (TRH)"}, "r": "C", "e": {"correcta": "Somatostatin analogues such as octreotide mimic the natural inhibitory action of somatostatin on somatotrophs, suppressing GH secretion. This makes octreotide a mainstay medical therapy for acromegaly, especially in patients who are not surgical candidates or have residual disease after pituitary surgery.", "incorrectas": {"A": "GHRH analogues would stimulate rather than suppress GH release, the opposite of the desired therapeutic effect in GH-excess states.", "B": "Dopamine agonists (e.g., cabergoline, bromocriptine) are used in acromegaly as an adjunct in some cases, but the classic somatostatin-mimicking drug described here is octreotide, which acts via somatostatin receptors, not dopamine receptors.", "D": "TRH analogues would be irrelevant to GH suppression; TRH's main physiologic role is stimulating TSH and prolactin release, not modulating the somatotroph axis."}}}, {"id": "anking-endocrine-physiology-1289", "fuente": "anking", "tema": 23, "anki": "1461878460770", "q": "The most important of the somatomedins, which mediates most GH-driven growth effects, goes by what name?", "o": {"A": "Somatomedin C (IGF-1)", "B": "Somatomedin B (IGF-2)", "C": "Somatostatin", "D": "Growth hormone-binding protein"}, "r": "A", "e": {"correcta": "Somatomedin C, also known as IGF-1, is the principal somatomedin mediating GH's peripheral growth-promoting effects, including linear bone growth, increased lean body mass, and organ growth. Serum IGF-1 levels are used clinically as an integrated marker of GH activity because IGF-1 is more stable than pulsatile GH itself.", "incorrectas": {"B": "IGF-2 plays a more prominent role in fetal growth and is not the primary postnatal mediator of GH action referred to as the most important somatomedin.", "C": "Somatostatin is the inhibitory hypothalamic hormone that suppresses GH release; it is not a somatomedin and does not mediate GH's growth-promoting peripheral effects.", "D": "Growth hormone-binding protein transports GH in the circulation but does not itself mediate the growth-promoting signaling that somatomedins (IGFs) provide."}}}, {"id": "anking-endocrine-physiology-1290", "fuente": "anking", "tema": 23, "anki": "1461880415237", "q": "Prolactin is the major hormone responsible for milk production and, together with estrogen, contributes to which additional process?", "o": {"A": "Uterine contraction during labor", "B": "Breast development", "C": "Cervical ripening", "D": "Ovarian follicle maturation"}, "r": "B", "e": {"correcta": "Prolactin drives lactogenesis (milk production) and, acting together with estrogen, supports breast development during pregnancy, preparing the mammary glands structurally for lactation. This dual role distinguishes prolactin's function in both glandular growth and functional milk synthesis.", "incorrectas": {"A": "Uterine contraction during labor is primarily driven by oxytocin, not prolactin, which is instead focused on mammary gland development and milk synthesis.", "C": "Cervical ripening is mediated by prostaglandins and mechanical/hormonal changes near term, not by prolactin's actions on the breast.", "D": "Ovarian follicle maturation is driven by FSH and LH; prolactin actually tends to suppress the reproductive axis (via GnRH inhibition) rather than promote follicle maturation."}}}, {"id": "anking-endocrine-physiology-1291", "fuente": "anking", "tema": 23, "anki": "1461880431253", "q": "Prolactin is structurally homologous to which other anterior pituitary hormone?", "o": {"A": "Thyroid-stimulating hormone (TSH)", "B": "Growth hormone", "C": "Adrenocorticotropic hormone (ACTH)", "D": "Luteinizing hormone (LH)"}, "r": "B", "e": {"correcta": "Prolactin and growth hormone are structurally homologous single-chain polypeptide hormones, reflecting their shared evolutionary origin from a common ancestral gene. This homology also explains overlapping receptor signaling features, including activation of the JAK-STAT pathway by both hormone receptors.", "incorrectas": {"A": "TSH is a glycoprotein hormone composed of alpha and beta subunits (sharing its alpha subunit with LH, FSH, and hCG), structurally distinct from the single-chain prolactin/GH family.", "C": "ACTH is derived from proteolytic cleavage of the POMC precursor and is structurally unrelated to the prolactin/GH polypeptide family.", "D": "LH is also a glycoprotein hormone in the same subunit family as TSH and FSH, structurally distinct from prolactin, which belongs to the GH-homologous family instead."}}}, {"id": "anking-endocrine-physiology-1292", "fuente": "anking", "tema": 23, "anki": "1461880437675", "q": "Prolactin is synthesized by which anterior pituitary cell type, comprising roughly 15% of anterior pituitary tissue?", "o": {"A": "Somatotrophs", "B": "Corticotrophs", "C": "Lactotrophs", "D": "Gonadotrophs"}, "r": "C", "e": {"correcta": "Prolactin is produced by lactotrophs, which make up about 15% of anterior pituitary cells (a proportion that increases substantially during pregnancy). This is distinct from GH, which is produced by the more abundant somatotrophs, the most common anterior pituitary cell type.", "incorrectas": {"A": "Somatotrophs synthesize growth hormone, not prolactin; they represent the largest population of anterior pituitary cells, unlike the smaller lactotroph population.", "B": "Corticotrophs produce ACTH via POMC processing and are unrelated to prolactin synthesis.", "D": "Gonadotrophs produce FSH and LH, playing a role in the reproductive axis, but they are not the cell type responsible for prolactin synthesis."}}}, {"id": "anking-endocrine-physiology-1293", "fuente": "anking", "tema": 23, "anki": "1461880484814", "q": "Prolactin secretion from the anterior pituitary is stimulated by which hypothalamic hormone?", "o": {"A": "Dopamine", "B": "Somatostatin", "C": "Thyrotropin-releasing hormone (TRH)", "D": "GHRH"}, "r": "C", "e": {"correcta": "TRH, in addition to its main role stimulating TSH release, also stimulates prolactin secretion from lactotrophs. This explains why primary hypothyroidism (with elevated TRH due to loss of negative feedback) can cause hyperprolactinemia and galactorrhea.", "incorrectas": {"A": "Dopamine is the principal inhibitor of prolactin secretion (tonic inhibitory tone from the hypothalamus), the opposite of a stimulatory hormone like TRH.", "B": "Somatostatin primarily inhibits GH (and to a lesser extent TSH) secretion; it is not the major stimulatory hormone for prolactin release.", "D": "GHRH stimulates GH release from somatotrophs, a distinct axis from the TRH-driven stimulation of prolactin from lactotrophs."}}}, {"id": "anking-endocrine-physiology-1294", "fuente": "anking", "tema": 23, "anki": "1461880499776", "q": "What effect does prolactin have on its own secretion from the anterior pituitary?", "o": {"A": "Increased, via positive feedback", "B": "Decreased", "C": "No effect", "D": "Increased, via suppression of dopamine"}, "r": "B", "e": {"correcta": "Prolactin decreases its own secretion through a short-loop negative feedback mechanism: it stimulates hypothalamic dopamine release, and dopamine in turn tonically inhibits lactotrophs. This keeps circulating prolactin levels regulated in the non-lactating state.", "incorrectas": {"A": "A positive feedback loop would cause unchecked prolactin rise, which does not match the physiologic self-limiting regulation seen with prolactin.", "C": "Prolactin does have a clear regulatory effect on its own secretion via the dopamine feedback loop; describing it as neutral misses this key regulatory mechanism.", "D": "Prolactin actually stimulates (not suppresses) dopamine secretion as part of its negative feedback loop; suppressing dopamine would disinhibit lactotrophs and increase, not decrease, prolactin, which is the opposite of what occurs."}}}, {"id": "anking-endocrine-physiology-1295", "fuente": "anking", "tema": 23, "anki": "1461880512032", "q": "Which hormone stimulates milk production in the breast by inducing synthesis of milk components such as casein and lactose?", "o": {"A": "Oxytocin", "B": "Estrogen", "C": "Prolactin", "D": "Human placental lactogen"}, "r": "C", "e": {"correcta": "Prolactin acts directly on mammary alveolar epithelial cells to induce synthesis of milk components, including casein (a milk protein) and lactose, driving lactogenesis. This is prolactin's signature physiologic function, distinguishing it from oxytocin, which governs milk ejection rather than production.", "incorrectas": {"A": "Oxytocin causes myoepithelial cell contraction leading to milk ejection (the let-down reflex), but it does not induce synthesis of milk components like casein and lactose.", "B": "Estrogen supports breast ductal development and works with prolactin during pregnancy, but it actually inhibits milk secretion during pregnancy and is not the direct driver of casein/lactose synthesis.", "D": "Human placental lactogen supports maternal metabolic adaptation during pregnancy and has some prolactin-like activity, but the primary hormone responsible for inducing milk component synthesis postpartum is prolactin."}}}, {"id": "anking-endocrine-physiology-1296", "fuente": "anking", "tema": 23, "anki": "1461880545687", "q": "Which hormone stimulates breast development, acting in a supportive role together with estrogen?", "o": {"A": "Progesterone", "B": "Prolactin", "C": "Follicle-stimulating hormone (FSH)", "D": "Testosterone"}, "r": "B", "e": {"correcta": "Prolactin works together with estrogen to promote breast development, particularly the growth and differentiation of glandular (alveolar) tissue in preparation for lactation. This complements estrogen's role in ductal proliferation.", "incorrectas": {"A": "Progesterone contributes to lobuloalveolar development during pregnancy as well, but the hormone specifically paired with estrogen in this classic description of supportive breast development is prolactin.", "C": "FSH acts on the ovary to promote follicular development and is not directly involved in mammary gland development.", "D": "Testosterone is an androgen that does not promote breast development; in fact, androgens generally oppose breast tissue growth."}}}, {"id": "anking-endocrine-physiology-1297", "fuente": "anking", "tema": 23, "anki": "1461880555092", "q": "What effect does elevated prolactin have on ovulation and spermatogenesis?", "o": {"A": "Increased / stimulation", "B": "No effect", "C": "Decreased / inhibition", "D": "Increased ovulation but decreased spermatogenesis"}, "r": "C", "e": {"correcta": "Prolactin inhibits ovulation and spermatogenesis by suppressing hypothalamic GnRH release, which reduces LH/FSH secretion. This is why hyperprolactinemia (e.g., from a prolactinoma) commonly presents with amenorrhea and infertility in women or decreased libido and infertility in men.", "incorrectas": {"A": "Increased/stimulation is the opposite of prolactin's actual effect; prolactin suppresses, rather than promotes, the reproductive axis via GnRH inhibition.", "B": "Prolactin has a well-documented suppressive effect on reproductive function through GnRH inhibition, so 'no effect' does not reflect the known physiology.", "D": "Prolactin inhibits both ovulation and spermatogenesis by the same underlying mechanism (GnRH suppression), not selectively one while enhancing the other."}}}, {"id": "anking-endocrine-physiology-1298", "fuente": "anking", "tema": 23, "anki": "1461880625384", "q": "Destruction of the hypothalamus or interruption of the hypothalamic-hypophyseal tract (e.g., from infiltrative lesions like sarcoidosis) results in prolactin excess by causing loss of which regulatory input?", "o": {"A": "Tonic inhibition by dopamine", "B": "Tonic stimulation by TRH", "C": "Negative feedback by IGF-1", "D": "Stimulation by GHRH"}, "r": "A", "e": {"correcta": "Dopamine normally travels down the hypothalamic-hypophyseal (tuberoinfundibular) tract to tonically inhibit lactotrophs. Disruption of this tract (by tumors, infiltrative disease such as sarcoidosis or histiocytosis X, or pituitary stalk compression) removes dopamine's inhibitory tone, causing a 'stalk effect' with resultant hyperprolactinemia even without a prolactin-secreting tumor.", "incorrectas": {"B": "Loss of TRH stimulation would tend to lower, not raise, prolactin, since TRH is a stimulatory (not inhibitory) input to lactotrophs; the excess seen here results from losing an inhibitory signal, dopamine.", "C": "IGF-1 feedback primarily regulates the GH axis (via hypothalamic somatostatin), not the prolactin axis, so it is not the mechanism behind stalk-effect hyperprolactinemia.", "D": "GHRH stimulates GH release from somatotrophs and is unrelated to the mechanism causing prolactin excess after hypothalamic-pituitary stalk disruption."}}}, {"id": "anking-endocrine-physiology-1299", "fuente": "anking", "tema": 23, "anki": "1461880672430", "q": "In patients with excess prolactin (hyperprolactinemia), what happens to libido?", "o": {"A": "Increased", "B": "Decreased", "C": "Unchanged", "D": "Increased in men, decreased in women"}, "r": "B", "e": {"correcta": "Hyperprolactinemia decreases libido in both sexes, largely as a downstream consequence of prolactin-induced suppression of GnRH and the resulting fall in sex steroid production (estrogen in women, testosterone in men). This contributes to the clinical picture of hypogonadism seen with prolactinomas.", "incorrectas": {"A": "Increased libido would be inconsistent with the hypogonadal state that hyperprolactinemia produces through GnRH suppression; the actual clinical effect is a decrease.", "C": "Libido is not unaffected; decreased libido is a well-recognized clinical feature of hyperprolactinemia in both men and women due to secondary hypogonadism.", "D": "The effect of hyperprolactinemia on libido is not sex-discordant; it decreases libido in both men and women through the same GnRH-suppression mechanism."}}}, {"id": "anking-endocrine-pharmacology-1300", "fuente": "anking", "tema": 24, "anki": "1461880683894", "q": "A patient with hyperprolactinemia causing galactorrhea and amenorrhea is started on medical therapy. Which class of drug is first-line treatment?", "o": {"A": "Somatostatin analogs", "B": "Dopamine agonists", "C": "GnRH agonists", "D": "Selective estrogen receptor modulators"}, "r": "B", "e": {"correcta": "Dopamine normally acts on D2 receptors on lactotrophs to tonically inhibit prolactin secretion. Dopamine agonists such as bromocriptine and cabergoline mimic this inhibitory tone, shrinking prolactinomas and normalizing prolactin levels, making them first-line therapy for prolactin excess.", "incorrectas": {"A": "Somatostatin analogs (e.g., octreotide) suppress GH and are used in acromegaly or GH-secreting tumors, not prolactinomas, since somatostatin has only a minor inhibitory effect on prolactin compared to dopamine.", "C": "GnRH agonists downregulate the hypothalamic-pituitary-gonadal axis and are used in conditions like precocious puberty or prostate cancer, not to directly suppress prolactin secretion from lactotrophs.", "D": "SERMs modulate estrogen receptor activity peripherally and are used in breast cancer or osteoporosis; they do not act on the dopaminergic inhibition of lactotrophs and are not used for prolactin excess."}}}, {"id": "anking-endocrine-anatomy-1301", "fuente": "anking", "tema": 25, "anki": "1461884723914", "q": "ADH and oxytocin are synthesized in the hypothalamus and transported down the axon to the posterior pituitary packaged in secretory granules together with which carrier proteins?", "o": {"A": "Chromogranins", "B": "Neurophysins", "C": "Thyroglobulin", "D": "Transcortin"}, "r": "B", "e": {"correcta": "ADH and oxytocin are each synthesized as larger prohormones that are cleaved to yield the active hormone plus a neurophysin carrier protein (neurophysin I for oxytocin, neurophysin II for ADH). These neurophysins bind their respective hormones within secretory granules during axonal transport down the hypothalamo-hypophyseal tract to the posterior pituitary for storage and release.", "incorrectas": {"A": "Chromogranins are acidic proteins co-stored with catecholamines in adrenal medullary chromaffin granules and other neuroendocrine secretory vesicles, not the specific carriers packaged with ADH and oxytocin.", "C": "Thyroglobulin is a large glycoprotein synthesized by thyroid follicular cells that serves as the scaffold for thyroid hormone synthesis, unrelated to posterior pituitary hormone transport.", "D": "Transcortin (corticosteroid-binding globulin) is a plasma protein that binds cortisol in the bloodstream for transport, not a granule carrier protein for hypothalamic neurohormones."}}}, {"id": "anking-renal-physiology-1302", "fuente": "anking", "tema": 12, "anki": "1461884779583", "q": "Which physiologic change is the most important stimulus for increased ADH secretion under normal conditions?", "o": {"A": "Decreased plasma volume", "B": "Increased plasma osmolarity", "C": "Decreased blood pressure", "D": "Increased serum sodium-independent of osmolarity"}, "r": "B", "e": {"correcta": "Osmoreceptors in the anterior hypothalamus (organum vasculosum) are exquisitely sensitive to small changes in plasma osmolarity, and increased osmolarity is the most important and sensitive physiologic stimulus for ADH secretion, triggering water retention to dilute the plasma back toward normal.", "incorrectas": {"A": "Decreased plasma volume does stimulate ADH via baroreceptors, but it is a less sensitive stimulus that requires a larger percentage change (roughly 10-15%) to trigger a response, compared to the much smaller osmolarity changes (about 1%) that activate osmoreceptors.", "C": "Decreased blood pressure activates baroreceptor-mediated ADH release similarly to volume depletion, but this pathway is less sensitive than the osmoreceptor pathway and is usually a secondary, more powerful override rather than the primary day-to-day stimulus.", "D": "Serum sodium changes act on ADH secretion specifically through their effect on plasma osmolarity sensed by osmoreceptors; sodium in isolation without altering osmolarity is not the direct stimulus."}}}, {"id": "anking-renal-physiology-1303", "fuente": "anking", "tema": 12, "anki": "1461884800688", "q": "Which structures detect increases in plasma osmolarity and signal the posterior pituitary to increase ADH secretion?", "o": {"A": "Carotid body chemoreceptors", "B": "Juxtaglomerular cells", "C": "Osmoreceptors in the anterior hypothalamus", "D": "Baroreceptors in the carotid sinus"}, "r": "C", "e": {"correcta": "Osmoreceptors located in the anterior hypothalamus (near the organum vasculosum of the lamina terminalis) continuously monitor plasma osmolarity. When osmolarity rises, these cells shrink and signal the hypothalamic neurons that synthesize ADH, increasing its secretion from the posterior pituitary to promote water reabsorption.", "incorrectas": {"A": "Carotid body chemoreceptors primarily sense arterial PO2, PCO2, and pH to regulate respiratory drive, not plasma osmolarity or ADH release.", "B": "Juxtaglomerular cells in the renal afferent arteriole sense decreased renal perfusion pressure and secrete renin, a distinct pathway from osmolarity sensing for ADH.", "D": "Baroreceptors in the carotid sinus and aortic arch sense blood pressure/volume changes and can stimulate ADH release, but this is the volume-based pathway, not the osmolarity-sensing pathway described here."}}}, {"id": "anking-renal-physiology-1304", "fuente": "anking", "tema": 12, "anki": "1461884807843", "q": "In a patient with significant hypovolemia, what happens to plasma volume status and its effect on ADH secretion?", "o": {"A": "Volume expansion, which suppresses ADH", "B": "Volume contraction, which strongly stimulates ADH secretion", "C": "No change in ADH, since volume does not affect secretion", "D": "Volume contraction, which only weakly affects ADH via minor pathways"}, "r": "B", "e": {"correcta": "Hypovolemia (volume contraction) is sensed by baroreceptors, with information relayed via the vagus and glossopharyngeal nerves to the hypothalamus. This is a potent, though less sensitive, stimulus for ADH secretion compared to osmolarity, and it can override osmotic feedback to preserve intravascular volume even at the expense of causing hyponatremia.", "incorrectas": {"A": "Volume expansion (not contraction) suppresses ADH via decreased baroreceptor firing and stretch-mediated atrial natriuretic peptide release, the opposite of what occurs in hypovolemia.", "C": "Volume status is, alongside osmolarity, one of the two principal physiologic regulators of ADH secretion; baroreceptor-mediated volume sensing has a well-established and powerful effect on ADH release.", "D": "Far from being a weak or minor pathway, baroreceptor-mediated volume sensing is potent enough to override osmotic regulation entirely in severe hypovolemia, driving ADH secretion even when plasma osmolarity is low."}}}, {"id": "anking-renal-physiology-1305", "fuente": "anking", "tema": 12, "anki": "1461884819979", "q": "Which receptors detect a decrease in plasma volume and relay signals that increase ADH secretion?", "o": {"A": "Baroreceptors", "B": "Osmoreceptors", "C": "Chemoreceptors", "D": "Stretch receptors in the bladder"}, "r": "A", "e": {"correcta": "Baroreceptors located in the carotid sinus, aortic arch, and cardiac atria detect reduced stretch/pressure when plasma volume falls. Reduced baroreceptor firing is relayed via the vagus nerve to the hypothalamus, stimulating ADH release to promote water retention and restore volume.", "incorrectas": {"B": "Osmoreceptors in the anterior hypothalamus detect changes in plasma osmolarity, not volume, and represent a separate, more sensitive stimulus for ADH secretion.", "C": "Chemoreceptors (e.g., carotid and aortic bodies) primarily respond to changes in blood gases (PO2, PCO2, pH) to regulate ventilation, not plasma volume.", "D": "Bladder stretch receptors are involved in the micturition reflex signaling bladder fullness, unrelated to systemic volume sensing or ADH regulation."}}}, {"id": "anking-renal-physiology-1306", "fuente": "anking", "tema": 12, "anki": "1461884838662", "q": "A patient presents with both low effective circulating volume and low plasma osmolarity. What happens to ADH secretion in this scenario?", "o": {"A": "ADH secretion is suppressed because low osmolarity dominates", "B": "ADH secretion increases because volume depletion overrides the osmolarity signal", "C": "ADH secretion remains unchanged since the two signals cancel out", "D": "ADH secretion is suppressed because both signals favor water excretion"}, "r": "B", "e": {"correcta": "When volume and osmolarity signals conflict, volume status takes priority: severe hypovolemia triggers ADH secretion via baroreceptors even though low osmolarity would normally suppress it. This explains why patients with severe volume depletion can develop hyponatremia, as the body prioritizes restoring perfusion over correcting osmolarity.", "incorrectas": {"A": "Low osmolarity alone would suppress ADH, but this ignores the more clinically dominant hypovolemic stimulus, which overrides the osmotic signal in this scenario.", "C": "The two signals do not simply cancel; instead there is a hierarchy where volume depletion is prioritized and dominates the net effect on ADH secretion.", "D": "This is incorrect because although low osmolarity favors water excretion, hypovolemia produces the opposite, dominant effect of ADH release and water retention."}}}, {"id": "anking-renal-physiology-1307", "fuente": "anking", "tema": 12, "anki": "1461884846394", "q": "In a patient with both high effective circulating volume and high plasma osmolarity, what happens to ADH secretion?", "o": {"A": "ADH increases because high osmolarity dominates", "B": "ADH secretion is variable and unpredictable", "C": "ADH is not secreted (or secretion decreases) because volume status dominates", "D": "ADH increases proportionally to both stimuli additively"}, "r": "C", "e": {"correcta": "Just as volume depletion overrides low osmolarity to stimulate ADH, volume expansion overrides high osmolarity to suppress ADH secretion (or blunt the expected increase). Volume status consistently takes precedence over osmolarity in determining the net ADH response when the two signals conflict.", "incorrectas": {"A": "While high osmolarity alone would stimulate ADH via hypothalamic osmoreceptors, this signal is overridden by the dominant volume-expansion signal in this scenario.", "B": "The physiologic response is not unpredictable; volume status reliably dominates over osmolarity, producing decreased ADH secretion despite elevated osmolarity.", "D": "The two signals do not add together; rather, one (volume) dominates the other (osmolarity) when they point in opposite directions."}}}, {"id": "anking-renal-physiology-1308", "fuente": "anking", "tema": 12, "anki": "1461884855032", "q": "Which of the following non-osmotic, non-volume stimuli increases ADH secretion?", "o": {"A": "Atrial natriuretic peptide", "B": "Alcohol ingestion", "C": "Nausea", "D": "Alpha-adrenergic agonists"}, "r": "C", "e": {"correcta": "Nausea is one of the most potent non-osmotic stimuli for ADH release, along with pain, hypoglycemia, and opiates. These stressors act through central pathways independent of plasma osmolarity or volume, which is clinically relevant because antiemetics or pain control can indirectly affect ADH-driven water retention.", "incorrectas": {"A": "Atrial natriuretic peptide is released in response to atrial stretch from volume expansion and acts to decrease ADH secretion, the opposite effect of nausea.", "B": "Alcohol is a classic inhibitor of ADH secretion, which is why alcohol consumption causes increased diuresis and can contribute to dehydration.", "D": "Alpha-adrenergic agonists decrease ADH secretion, contrasting with nausea, pain, hypoglycemia, and opiates, which are stimulatory."}}}, {"id": "anking-renal-physiology-1309", "fuente": "anking", "tema": 12, "anki": "1461884861116", "q": "Which of the following decreases ADH secretion?", "o": {"A": "Opiate use", "B": "Hypoglycemia", "C": "Alpha-adrenergic agonists", "D": "Severe pain"}, "r": "C", "e": {"correcta": "Alpha-adrenergic agonists, along with alcohol and atrial natriuretic peptide, decrease ADH secretion. This is clinically relevant because sympathomimetic and alcohol use can promote diuresis by suppressing this hormone, in contrast to stress-related stimuli that increase it.", "incorrectas": {"A": "Opiates are a classic stimulus that increases ADH secretion, part of the group including pain, nausea, and hypoglycemia, opposite to the effect of alpha-agonists.", "B": "Hypoglycemia is a stress stimulus that increases ADH secretion as part of the counter-regulatory and stress hormone response, not a suppressor.", "D": "Severe pain increases ADH secretion through central stress pathways, the opposite effect compared to alpha-adrenergic agonists."}}}, {"id": "anking-renal-physiology-1310", "fuente": "anking", "tema": 12, "anki": "1461884921465", "q": "ADH increases water permeability of the principal cells in the late distal tubule and collecting duct primarily by increasing insertion of which channel via which second messenger?", "o": {"A": "AQP2 channels via increased cAMP", "B": "ENaC channels via increased IP3", "C": "AQP1 channels via increased cGMP", "D": "ROMK channels via increased cAMP"}, "r": "A", "e": {"correcta": "ADH binds V2 receptors (Gs-coupled) on the basolateral membrane of principal cells, activating adenylate cyclase to increase intracellular cAMP. This triggers a signaling cascade that inserts preformed aquaporin-2 (AQP2) channels into the apical membrane, dramatically increasing water permeability and reabsorption in the late distal tubule and collecting duct.", "incorrectas": {"B": "ENaC channels mediate sodium reabsorption in the principal cells and are regulated primarily by aldosterone, not by ADH-driven IP3 signaling; ADH's key water channel effect is on AQP2, not ENaC.", "C": "AQP1 channels are constitutively expressed water channels found in the proximal tubule and descending thin limb, not the ADH-regulated segment; they are not regulated by cGMP or by ADH.", "D": "ROMK channels mediate potassium secretion in the distal nephron and are not the ADH-responsive water channel; ADH's key second messenger is cAMP, but it acts on AQP2, not ROMK."}}}, {"id": "anking-cardiovascular-physiology-1311", "fuente": "anking", "tema": 47, "anki": "1461884927872", "q": "Beyond its water-conserving action on the kidney, ADH (vasopressin) has which additional physiologic effect at high concentrations?", "o": {"A": "Relaxation of vascular smooth muscle to lower blood pressure", "B": "Contraction of vascular smooth muscle to raise blood pressure", "C": "Direct positive inotropic effect on cardiac myocytes", "D": "Inhibition of the renin-angiotensin-aldosterone system"}, "r": "B", "e": {"correcta": "At high concentrations, ADH acts on V1 receptors on vascular smooth muscle to cause vasoconstriction, raising systemic blood pressure. This pressor effect is why vasopressin is used clinically in vasodilatory (septic) shock to support blood pressure independent of its renal water-retaining effects.", "incorrectas": {"A": "ADH causes vasoconstriction, not vasodilation, via V1 receptor activation on vascular smooth muscle; this is opposite to its actual pressor effect.", "C": "ADH does not have a well-described direct positive inotropic effect on cardiac myocytes; its cardiovascular effect is primarily through V1-receptor-mediated vasoconstriction of smooth muscle.", "D": "ADH does not inhibit the renin-angiotensin-aldosterone system; in fact, low blood volume that stimulates ADH release also typically stimulates renin release via similar baroreceptor-sensed mechanisms."}}}, {"id": "anking-cardiovascular-physiology-1312", "fuente": "anking", "tema": 47, "anki": "1461885010270", "q": "Which receptor mediates the blood-pressure-raising, vasoconstrictive effect of antidiuretic hormone?", "o": {"A": "V2 receptors", "B": "V1 receptors", "C": "Oxytocin receptors", "D": "Beta-1 adrenergic receptors"}, "r": "B", "e": {"correcta": "ADH acts on V1 receptors, which are Gq-coupled receptors on vascular smooth muscle, activating phospholipase C and increasing intracellular calcium to cause vasoconstriction and raise blood pressure. This is distinct from its renal water-conserving action.", "incorrectas": {"A": "V2 receptors are Gs-coupled receptors located on renal principal cells that mediate the water reabsorption effect of ADH via cAMP and AQP2 insertion, not the vasopressor effect.", "C": "Oxytocin receptors mediate uterine and myoepithelial contraction in response to oxytocin, a structurally related but functionally distinct posterior pituitary hormone, not the vasopressor action of ADH.", "D": "Beta-1 adrenergic receptors mediate catecholamine effects on heart rate and contractility and are unrelated to the ADH signaling pathway for vasoconstriction."}}}, {"id": "anking-reproductive-system-physiology-1313", "fuente": "anking", "tema": 32, "anki": "1461979320393", "q": "What is the major physiologic stimulus for oxytocin secretion during lactation?", "o": {"A": "Suckling of the breast", "B": "Uterine distension", "C": "Cervical dilation", "D": "Rising serum prolactin levels"}, "r": "A", "e": {"correcta": "Suckling stimulates sensory nerve endings in the nipple, sending afferent signals to the hypothalamus that trigger oxytocin release from the posterior pituitary, which then acts on myoepithelial cells to cause milk ejection. Though it is the major stimulus, suckling is not strictly required, since conditioned stimuli (sight, sound, or smell of an infant) can also trigger release.", "incorrectas": {"B": "Uterine distension is not a described stimulus for oxytocin during lactation; rather, cervical dilation during labor is the relevant reproductive stimulus for oxytocin release in that separate context.", "C": "Cervical dilation stimulates oxytocin release during labor via the Ferguson reflex, but this is a distinct mechanism from the suckling reflex responsible for lactational oxytocin release.", "D": "Prolactin and oxytocin are co-released during suckling but act on different tissues (milk production versus milk ejection); rising prolactin itself is not the trigger for oxytocin secretion."}}}, {"id": "anking-reproductive-system-physiology-1314", "fuente": "anking", "tema": 32, "anki": "1461979329468", "q": "In addition to direct suckling, oxytocin secretion in a nursing mother can be triggered by which type of stimulus?", "o": {"A": "Conditioned responses like the sight, sound, or smell of her infant", "B": "Increased plasma osmolarity", "C": "Decreased plasma volume", "D": "Rising maternal cortisol levels"}, "r": "A", "e": {"correcta": "Oxytocin release can be conditioned through classical association, such that a mother may experience milk let-down simply from hearing her infant cry or seeing/smelling the baby, even before physical suckling occurs. This illustrates the neuroendocrine reflex's connection to higher cortical and limbic processing, not just peripheral sensory input from the nipple.", "incorrectas": {"B": "Increased plasma osmolarity is the classic stimulus for ADH secretion via hypothalamic osmoreceptors, not the pathway responsible for conditioned oxytocin release related to nursing cues.", "C": "Decreased plasma volume stimulates ADH secretion via baroreceptors; this volume-sensing pathway is unrelated to the sensory/conditioned stimuli that trigger oxytocin in nursing mothers.", "D": "Cortisol is part of the stress response and hypothalamic-pituitary-adrenal axis, not linked to the conditioned sensory triggers (sight, sound, smell of infant) that provoke oxytocin release."}}}, {"id": "anking-reproductive-system-physiology-1315", "fuente": "anking", "tema": 32, "anki": "1461979376290", "q": "During labor, mechanical stimulation of which structure triggers oxytocin secretion via the Ferguson reflex?", "o": {"A": "Fundus of the uterus", "B": "Cervix (dilation)", "C": "Vaginal introitus", "D": "Fallopian tube"}, "r": "B", "e": {"correcta": "Cervical dilation during labor (and also during orgasm) activates stretch receptors that send afferent signals to the hypothalamus, triggering oxytocin secretion from the posterior pituitary. Released oxytocin then acts on the uterine myometrium in a positive feedback loop, intensifying contractions to further dilate the cervix and progress labor.", "incorrectas": {"A": "The uterine fundus is the site where oxytocin ultimately acts to produce contractions, but it is cervical dilation, not fundal stretch per se, that classically triggers the neuroendocrine reflex for oxytocin release.", "C": "The vaginal introitus is not the described trigger point for the Ferguson reflex; the reflex is specifically tied to cervical dilation sensed by cervical mechanoreceptors.", "D": "The fallopian tube is not involved in sensing the mechanical stimulus that triggers oxytocin release during labor or orgasm."}}}, {"id": "anking-reproductive-system-anatomy-1316", "fuente": "anking", "tema": 34, "anki": "1461979481956", "q": "Oxytocin triggers milk ejection by causing contraction of which cell type surrounding the mammary alveoli and ducts?", "o": {"A": "Luminal (ductal) epithelial cells", "B": "Myoepithelial cells", "C": "Adipocytes of the breast stroma", "D": "Fibroblasts of the interlobular septa"}, "r": "B", "e": {"correcta": "Myoepithelial cells are specialized contractile cells surrounding the mammary alveoli and ducts that express oxytocin receptors. When oxytocin binds these receptors, the myoepithelial cells contract, squeezing stored milk out of the alveoli and into the ducts for ejection during breastfeeding.", "incorrectas": {"A": "Luminal epithelial cells line the ducts and alveoli and are responsible for milk production and secretion, but they lack the contractile apparatus that myoepithelial cells have to physically expel milk.", "C": "Adipocytes make up the fatty stroma of the breast and provide structural support and energy storage, but they have no role in the contractile milk-ejection reflex.", "D": "Fibroblasts produce connective tissue components of the breast stroma and are not contractile cells responsive to oxytocin for milk ejection."}}}, {"id": "anking-reproductive-system-physiology-1317", "fuente": "anking", "tema": 32, "anki": "1461979495589", "q": "Oxytocin's action during labor produces powerful rhythmic contractions of which tissue?", "o": {"A": "Uterine smooth muscle", "B": "Cervical striated muscle", "C": "Vaginal smooth muscle only", "D": "Fallopian tube smooth muscle only"}, "r": "A", "e": {"correcta": "Oxytocin binds Gq-coupled receptors on uterine smooth muscle (myometrium), increasing intracellular calcium and producing powerful, rhythmic contractions essential for labor progression. As parturition approaches, oxytocin receptor density in the uterus is markedly up-regulated by rising estrogen levels, sensitizing the myometrium to oxytocin's effects.", "incorrectas": {"B": "The cervix is composed predominantly of connective tissue and smooth muscle, not striated muscle, and it does not undergo the rhythmic oxytocin-driven contractions that the uterine body does; it instead dilates passively in response to those contractions.", "C": "Vaginal smooth muscle is not the primary target for the powerful rhythmic contractions of labor; the myometrium of the uterine corpus is the key oxytocin-responsive tissue.", "D": "While the fallopian tube does have some oxytocin receptor expression relevant to sperm/ovum transport, it is not the site of the powerful rhythmic contractions described during labor, which occur in the uterine body."}}}, {"id": "anking-endocrine-physiology-1318", "fuente": "anking", "tema": 23, "anki": "1461979698536", "q": "Which thyroid hormone, T3 or T4, has greater biologic activity at the target tissue receptor?", "o": {"A": "T4", "B": "Reverse T3", "C": "T3", "D": "Both have equal activity"}, "r": "C", "e": {"correcta": "T3 (triiodothyronine) binds the nuclear thyroid hormone receptor with roughly 10-fold higher affinity than T4 and is the more biologically active form. Most circulating T4 is converted to T3 peripherally by 5'-deiodinase in target tissues, making T4 essentially a prohormone for the more potent T3.", "incorrectas": {"B": "Reverse T3 (rT3) is an inactive metabolite formed by alternative deiodination of T4, particularly during illness or starvation, and does not bind the thyroid hormone receptor with meaningful activity.", "A": "T4 is the predominant hormone secreted by the thyroid by mass and has a longer half-life, but it has much lower receptor affinity/activity than T3 and must be converted peripherally to exert its main effects.", "D": "T3 and T4 do not have equal potency; T3 is substantially more active at the nuclear receptor, which is why peripheral conversion of T4 to T3 is physiologically important."}}}, {"id": "anking-endocrine-physiology-1319", "fuente": "anking", "tema": 23, "anki": "1461984633531", "q": "Which thyroid hormone constitutes the majority of what is directly secreted by the thyroid gland?", "o": {"A": "T3", "B": "T4", "C": "Reverse T3", "D": "Thyroglobulin"}, "r": "B", "e": {"correcta": "T4 (thyroxine) is the predominant hormone secreted directly by the thyroid gland, due to the coupling reaction of two DIT molecules being faster and favored over the MIT+DIT coupling that forms T3. The majority of circulating T3 is generated later by peripheral deiodination of T4 in tissues like liver and kidney.", "incorrectas": {"A": "T3 is the more biologically potent hormone, but it is secreted in much smaller quantities directly by the thyroid; most T3 in the body arises from peripheral conversion of T4, not direct thyroidal secretion.", "C": "Reverse T3 is an inactive deiodination product formed from T4 in peripheral tissues (especially during illness), not a hormone secreted in significant quantities by the thyroid gland itself.", "D": "Thyroglobulin is the glycoprotein scaffold within the follicular colloid used for thyroid hormone synthesis and storage; it is not itself released into the circulation as a functional secreted hormone."}}}, {"id": "anking-endocrine-anatomy-1320", "fuente": "anking", "tema": 25, "anki": "1461984643617", "q": "Thyroid hormones are synthesized within which cells of the thyroid gland?", "o": {"A": "Parafollicular (C) cells", "B": "Follicular epithelial cells", "C": "Colloid macrophages", "D": "Hürthle cells exclusively"}, "r": "B", "e": {"correcta": "Follicular epithelial cells line the thyroid follicles and are responsible for iodine trapping, thyroglobulin synthesis, iodination, and ultimately the production and release of T3 and T4. These cells surround the colloid-filled follicular lumen, where iodinated thyroglobulin is stored until stimulated for hormone release.", "incorrectas": {"A": "Parafollicular (C) cells are a separate population within the thyroid that secrete calcitonin, involved in calcium homeostasis, not thyroid hormone synthesis.", "C": "Colloid within the follicular lumen contains stored iodinated thyroglobulin, but there are no resident macrophages responsible for hormone synthesis there; synthesis and iodination occur via the follicular epithelial cells and the colloid interface.", "D": "Hürthle cells are enlarged, oxyphilic (mitochondria-rich) follicular epithelial cells seen in certain pathologic states like Hashimoto thyroiditis or Hürthle cell neoplasms, not a distinct normal cell type responsible for thyroid hormone synthesis."}}}, {"id": "anking-endocrine-physiology-1321", "fuente": "anking", "tema": 23, "anki": "1461984695705", "q": "The glycoprotein thyroglobulin, which serves as the scaffold for thyroid hormone synthesis, is rich in which amino acid that gets iodinated?", "o": {"A": "Phenylalanine", "B": "Tyrosine", "C": "Tryptophan", "D": "Histidine"}, "r": "B", "e": {"correcta": "Thyroglobulin contains numerous tyrosine residues that serve as the substrate for iodination by thyroid peroxidase, forming monoiodotyrosine (MIT) and diiodotyrosine (DIT). These iodinated tyrosines are then coupled to form T3 and T4, making tyrosine essential to thyroid hormone synthesis.", "incorrectas": {"A": "Phenylalanine is structurally related to tyrosine (its metabolic precursor) but is not the residue on thyroglobulin that undergoes iodination in thyroid hormone synthesis.", "C": "Tryptophan is an aromatic amino acid used in serotonin and niacin synthesis, unrelated to thyroid hormone formation on thyroglobulin.", "D": "Histidine is an amino acid important in buffering and enzyme active sites (e.g., hemoglobin), but it is not the iodination site involved in thyroid hormone synthesis."}}}, {"id": "anking-endocrine-anatomy-1322", "fuente": "anking", "tema": 25, "anki": "1461984713642", "q": "Thyroglobulin, used in thyroid hormone synthesis, is synthesized in which two organelles of the follicular epithelial cell?", "o": {"A": "Mitochondria and lysosomes", "B": "RER and Golgi apparatus", "C": "Smooth ER and peroxisomes", "D": "Nucleus and rough ER only"}, "r": "B", "e": {"correcta": "Thyroglobulin, as a secreted glycoprotein, is synthesized in the rough endoplasmic reticulum (RER), then undergoes glycosylation and packaging in the Golgi apparatus before being secreted into the follicular lumen where iodination occurs. This follows the classic secretory pathway used by cells producing large exported proteins.", "incorrectas": {"A": "Mitochondria generate ATP and are involved in oxidative phosphorylation, while lysosomes later degrade internalized iodinated thyroglobulin to release hormone; neither organelle is where thyroglobulin protein synthesis and glycosylation occur.", "C": "Smooth ER is involved in lipid synthesis and detoxification, and peroxisomes handle fatty acid oxidation, neither playing a role in thyroglobulin's synthetic pathway.", "D": "While the RER is correctly involved, thyroglobulin is a secreted glycoprotein and must pass through the Golgi apparatus for further processing, not remain associated solely with the nucleus and RER."}}}, {"id": "anking-renal-physiology-1323", "fuente": "anking", "tema": 12, "anki": "1461984729677", "q": "Iodine enters the follicular epithelial cell of the thyroid via which transport mechanism?", "o": {"A": "Facilitated diffusion", "B": "Na+-I- cotransport (the iodide pump)", "C": "Simple diffusion across the basolateral membrane", "D": "Na+/K+-ATPase-mediated primary active transport"}, "r": "B", "e": {"correcta": "Iodide enters follicular epithelial cells via the sodium-iodide symporter (NIS), a secondary active transport mechanism that uses the inward sodium gradient (maintained by the Na+/K+-ATPase) to co-transport iodide against its concentration gradient into the cell. This is often called the 'iodine pump' or 'iodide trap.'", "incorrectas": {"A": "Facilitated diffusion moves solutes down their concentration gradient without energy input, but iodide is actively concentrated against its gradient into the thyroid cell, requiring a cotransport mechanism, not passive facilitated diffusion.", "C": "Simple diffusion would not allow the thyroid to concentrate iodide many-fold higher than plasma levels, which is precisely what the active Na+-I- cotransporter accomplishes.", "D": "The Na+/K+-ATPase is a primary active transporter that maintains the sodium gradient used by the iodide symporter, but it is not itself the transporter that moves iodide into the cell; that role belongs to the secondary active Na+-I- cotransporter."}}}, {"id": "anking-renal-physiology-1324", "fuente": "anking", "tema": 12, "anki": "1461984744498", "q": "When circulating iodine levels are low, what happens to the activity of the thyroid's Na+-I- cotransporter?", "o": {"A": "Activity decreases to conserve residual iodine", "B": "Activity increases to enhance iodine trapping", "C": "The transporter is completely internalized and non-functional", "D": "Activity is unaffected by iodine levels"}, "r": "B", "e": {"correcta": "Low iodine levels upregulate activity of the Na+-I- symporter (increased TSH-driven expression and function) to enhance iodide trapping and maximize hormone synthesis capacity when substrate is scarce, a negative feedback adaptation. Conversely, iodine excess downregulates this transporter's activity.", "incorrectas": {"A": "Decreasing transporter activity would worsen iodine scarcity and impair thyroid hormone synthesis further; the actual physiologic response is the opposite, an upregulation to compensate for limited iodine.", "C": "Complete internalization/non-function would be maladaptive in iodine deficiency; instead the thyroid increases NIS activity and expression to better trap the limited available iodide.", "D": "The transporter's activity is very much regulated by iodine and TSH levels as part of a negative feedback loop, not fixed regardless of iodine status."}}}, {"id": "anking-renal-physiology-1325", "fuente": "anking", "tema": 12, "anki": "1461984762666", "q": "Thiocyanate and perchlorate impair thyroid hormone synthesis by competitively inhibiting which transporter?", "o": {"A": "Pendrin (apical Cl-/I- exchanger)", "B": "Na+-I- cotransporter (NIS)", "C": "Thyroid peroxidase", "D": "Monocarboxylate transporter 8 (T3 transporter)"}, "r": "B", "e": {"correcta": "Thiocyanate and perchlorate are anions similar in size/charge to iodide and act as competitive inhibitors of the sodium-iodide symporter (NIS), blocking iodide uptake into follicular cells and thereby impairing thyroid hormone synthesis. This principle underlies the perchlorate discharge test used to evaluate organification defects.", "incorrectas": {"A": "Pendrin transports iodide from the follicular cell cytoplasm into the colloid at the apical membrane (a later step), which is a different transporter from the basolateral NIS that thiocyanate and perchlorate inhibit.", "C": "Thyroid peroxidase catalyzes oxidation, organification, and coupling reactions later in synthesis; it is inhibited by drugs like methimazole and PTU, not by thiocyanate or perchlorate, which act on iodide uptake instead.", "D": "MCT8 is a transporter responsible for T3 uptake into target cells (mutations cause Allan-Herndon-Dudley syndrome), unrelated to the iodide-uptake inhibition caused by thiocyanate and perchlorate."}}}, {"id": "anking-endocrine-physiology-1326", "fuente": "anking", "tema": 23, "anki": "1461985089349", "q": "Glucocorticoids, beta-blockers, and PTU all share which mechanism relevant to thyroid hormone metabolism?", "o": {"A": "Inhibition of the Na+-I- cotransporter", "B": "Inhibition of 5'-deiodinase, blocking peripheral T4-to-T3 conversion", "C": "Inhibition of thyroid peroxidase-mediated organification", "D": "Stimulation of TSH receptor signaling"}, "r": "B", "e": {"correcta": "Glucocorticoids, beta-blockers, and propylthiouracil (PTU) all inhibit 5'-deiodinase, the peripheral enzyme responsible for converting the less active T4 into the more potent T3. This is clinically useful in severe hyperthyroidism/thyroid storm, where these drugs reduce the amount of active hormone reaching target tissues even without blocking new hormone synthesis.", "incorrectas": {"A": "Thiocyanate and perchlorate, not glucocorticoids/beta-blockers/PTU, inhibit the Na+-I- cotransporter; that mechanism is distinct from the peripheral deiodinase inhibition described here.", "C": "PTU does inhibit thyroid peroxidase (as does methimazole), but glucocorticoids and beta-blockers do not act on thyroid peroxidase; the shared mechanism among all three drugs is 5'-deiodinase inhibition, not organification blockade.", "D": "None of these agents stimulate TSH receptor signaling; in fact, their overall clinical effect in hyperthyroidism management is to reduce active thyroid hormone levels or effects, not stimulate receptor activity."}}}, {"id": "anking-endocrine-pharmacology-1327", "fuente": "anking", "tema": 24, "anki": "1461985157595", "q": "Methimazole and PTU both act as antithyroid drugs by inhibiting which enzyme?", "o": {"A": "5'-deiodinase", "B": "Thyroperoxidase", "C": "Adenylate cyclase", "D": "Na+-I- symporter"}, "r": "B", "e": {"correcta": "Both methimazole and PTU inhibit thyroperoxidase, the enzyme responsible for oxidation of iodide, organification onto tyrosine residues, and coupling of MIT/DIT to form T3 and T4. Blocking this enzyme reduces new thyroid hormone synthesis, making both drugs effective treatments for hyperthyroidism, though PTU additionally inhibits peripheral 5'-deiodinase, giving it an extra mechanism useful in thyroid storm.", "incorrectas": {"A": "5'-deiodinase converts peripheral T4 to T3; PTU (but not methimazole) inhibits this enzyme as an additional mechanism, but the enzyme shared and primarily targeted by both drugs is thyroperoxidase, not 5'-deiodinase.", "C": "Adenylate cyclase is part of the TSH receptor signaling cascade (Gs-cAMP pathway) that stimulates thyroid cell activity, not the enzyme inhibited by methimazole or PTU.", "D": "The Na+-I- symporter mediates iodide uptake into follicular cells and is inhibited by competitive anions like thiocyanate/perchlorate, a different mechanism from the thyroperoxidase inhibition produced by methimazole and PTU."}}}, {"id": "anking-endocrine-anatomy-1328", "fuente": "anking", "tema": 25, "anki": "1461985501857", "q": "After iodinated thyroglobulin is synthesized, where is it stored until the thyroid is stimulated to secrete thyroid hormones?", "o": {"A": "In secretory granules within the follicular cell cytoplasm", "B": "In the follicular lumen as colloid", "C": "Bound to thyroxine-binding globulin in plasma", "D": "In the parafollicular cell cytoplasm"}, "r": "B", "e": {"correcta": "Iodinated thyroglobulin is stored extracellularly within the follicular lumen as colloid, a unique feature of thyroid hormone storage compared to most endocrine glands that store hormone intracellularly in secretory granules. This allows the thyroid to maintain a substantial reserve of preformed hormone (weeks' worth) bound within thyroglobulin until TSH stimulation triggers endocytosis and hydrolysis.", "incorrectas": {"A": "Most peptide hormones are stored in intracellular secretory granules, but thyroid hormone is unusual in being stored extracellularly as colloid within the follicular lumen, not in cytoplasmic granules.", "C": "Thyroxine-binding globulin binds circulating T4 in the bloodstream after secretion, transporting it to target tissues; it is not the storage form of hormone within the thyroid gland itself.", "D": "Parafollicular (C) cells produce calcitonin and are anatomically and functionally distinct from the follicular cells and colloid-containing lumen involved in thyroid hormone storage."}}}, {"id": "anking-endocrine-physiology-1329", "fuente": "anking", "tema": 23, "anki": "1461985522739", "q": "Why is significantly more T4 than T3 produced by the thyroid gland, despite T3 being the more active hormone?", "o": {"A": "T4 has a much longer half-life allowing greater accumulation", "B": "The coupling reaction forming T4 (DIT + DIT) proceeds much faster than the reaction forming T3", "C": "T3 is rapidly degraded within the follicular lumen before secretion", "D": "TSH selectively stimulates T4 synthesis over T3 synthesis"}, "r": "B", "e": {"correcta": "T4 is formed by coupling two DIT molecules, while T3 forms from coupling MIT and DIT; the DIT+DIT coupling reaction catalyzed by thyroid peroxidase proceeds much more efficiently and rapidly, resulting in far greater production of T4. Despite this quantitative predominance, T3 remains the more biologically active hormone once formed via peripheral conversion of T4.", "incorrectas": {"A": "T4 does have a longer half-life in circulation than T3, which affects steady-state plasma levels, but this is a separate pharmacokinetic point from why more T4 is synthesized in the first place, which is due to the coupling kinetics.", "C": "There is no described mechanism of selective T3 degradation within the follicular lumen driving the T4:T3 production ratio; the actual explanation is the faster T4-forming coupling reaction.", "D": "TSH stimulates overall thyroid hormone synthesis and secretion without a described mechanism for selectively favoring T4 synthesis at the coupling-reaction level; the T4 predominance arises from the intrinsic chemistry of the coupling reactions."}}}, {"id": "anking-endocrine-physiology-1330", "fuente": "anking", "tema": 23, "anki": "1461985542858", "q": "Thyroid peroxidase catalyzes which sequence of reactions during thyroid hormone synthesis?", "o": {"A": "Endocytosis, hydrolysis, and secretion", "B": "Iodide uptake, storage, and recycling", "C": "Oxidation of iodide, organification onto tyrosine, and coupling of MIT/DIT", "D": "Glycosylation, folding, and export of thyroglobulin"}, "r": "C", "e": {"correcta": "Thyroid peroxidase (TPO) catalyzes three sequential reactions: oxidation of iodide (I-) to iodine (I2/reactive iodine species), organification of this iodine onto tyrosine residues of thyroglobulin to form MIT and DIT, and coupling of these iodotyrosines to form T3 and T4. This single enzyme is therefore central to nearly the entire biosynthetic pathway and is a key drug target (methimazole, PTU) in hyperthyroidism treatment.", "incorrectas": {"A": "Endocytosis and hydrolysis of iodinated thyroglobulin occur later, when TSH stimulates hormone release, and are mediated by different cellular machinery (endocytic vesicles and lysosomal proteases), not by thyroid peroxidase.", "B": "Iodide uptake into the follicular cell is mediated by the Na+-I- symporter (NIS), a completely separate transporter from thyroid peroxidase, which acts later at the apical membrane/colloid interface.", "D": "Glycosylation and folding of thyroglobulin occur in the RER and Golgi as part of protein synthesis, a process distinct from the peroxidase-catalyzed iodination and coupling reactions that occur afterward in the follicular lumen."}}}, {"id": "anking-endocrine-physiology-1331", "fuente": "anking", "tema": 23, "anki": "1461985573952", "q": "When the thyroid gland is stimulated by TSH to release hormone, what is the first step that occurs to the stored iodinated thyroglobulin in the colloid?", "o": {"A": "Direct diffusion of T4 and T3 out of the colloid", "B": "Endocytosis into the follicular epithelial cell", "C": "Extracellular proteolysis within the follicular lumen", "D": "Conversion to reverse T3"}, "r": "B", "e": {"correcta": "TSH stimulation triggers endocytosis of colloid droplets (containing iodinated thyroglobulin) from the follicular lumen back into the follicular epithelial cell. Once internalized, these droplets fuse with lysosomes, allowing proteolytic enzymes to cleave the thyroglobulin and release free T4, T3, MIT, and DIT.", "incorrectas": {"A": "T4 and T3 are bound within the thyroglobulin protein structure in colloid and cannot simply diffuse out; they must first be proteolytically cleaved from thyroglobulin after endocytosis.", "C": "Proteolysis of thyroglobulin occurs intracellularly within lysosomes after endocytosis, not extracellularly within the follicular lumen.", "D": "Conversion to reverse T3 is a peripheral deiodination pathway occurring in target tissues under certain conditions (e.g., illness), unrelated to the initial step of hormone release from the thyroid follicle."}}}, {"id": "anking-endocrine-physiology-1332", "fuente": "anking", "tema": 23, "anki": "1461985599113", "q": "After iodinated thyroglobulin is endocytosed into the follicular epithelial cell, which enzymes release T4, T3, MIT, and DIT from the protein backbone?", "o": {"A": "Thyroid peroxidase", "B": "Lysosomal proteases", "C": "5'-deiodinase", "D": "Carbonic anhydrase"}, "r": "B", "e": {"correcta": "Following endocytosis, colloid droplets fuse with lysosomes, where lysosomal proteases hydrolyze the peptide bonds holding T4, T3, MIT, and DIT within the thyroglobulin structure, liberating the free hormones and iodotyrosines for release or recycling.", "incorrectas": {"A": "Thyroid peroxidase functions earlier in synthesis, catalyzing oxidation, organification, and coupling reactions in the follicular lumen, not the intracellular proteolytic release of hormone from thyroglobulin.", "C": "5'-deiodinase acts peripherally (and to some extent intrathyroidally) to convert T4 to T3 or to deiodinate MIT/DIT for recycling, but it does not cleave the peptide bonds of thyroglobulin itself.", "D": "Carbonic anhydrase is involved in acid-base handling and bicarbonate generation in tissues like the kidney and red blood cells, unrelated to thyroglobulin proteolysis."}}}, {"id": "anking-endocrine-physiology-1333", "fuente": "anking", "tema": 23, "anki": "1461985625347", "q": "After being cleaved from thyroglobulin within the follicular cell, T4 and T3 exit the cell to enter which compartment?", "o": {"A": "The follicular lumen colloid", "B": "The systemic circulation", "C": "The lysosomal compartment for storage", "D": "The Golgi apparatus for re-glycosylation"}, "r": "B", "e": {"correcta": "Once liberated from thyroglobulin by lysosomal proteolysis, T4 and T3 are secreted across the basolateral membrane of the follicular cell into the bloodstream, entering the systemic circulation where most become bound to carrier proteins like thyroxine-binding globulin for transport to target tissues.", "incorrectas": {"A": "The follicular lumen colloid is where iodinated thyroglobulin was stored prior to stimulation; after hormone is cleaved intracellularly, it moves toward the bloodstream, not back into the lumen.", "C": "The lysosomal compartment is where proteolysis occurs to release T4 and T3 from thyroglobulin, but the hormones do not remain stored there; they are secreted into the circulation.", "D": "The Golgi apparatus functions earlier in thyroglobulin's synthetic and secretory pathway (before iodination), not after the hormone has already been cleaved and is being released into the blood."}}}, {"id": "anking-endocrine-physiology-1334", "fuente": "anking", "tema": 23, "anki": "1461985675479", "q": "The MIT and DIT that are not coupled into T3/T4 are deiodinated, generating tyrosine and iodide that are then used for what purpose?", "o": {"A": "Excreted unchanged in bile", "B": "Recycled within the thyroid for further hormone synthesis", "C": "Converted directly into calcitonin", "D": "Transported to the adrenal cortex for steroidogenesis"}, "r": "B", "e": {"correcta": "Intrathyroidal deiodinase removes iodine from uncoupled MIT and DIT, regenerating free tyrosine and iodide within the follicular cell. Both products are recycled: tyrosine can be incorporated into new thyroglobulin, and iodide re-enters the iodination pathway, making thyroid hormone synthesis highly efficient at conserving iodine.", "incorrectas": {"A": "Tyrosine and iodide generated from MIT/DIT deiodination are not excreted in bile; they are efficiently recycled within the thyroid gland to conserve resources for further hormone synthesis.", "C": "Calcitonin is produced by parafollicular (C) cells from a distinct peptide precursor and has no relationship to the tyrosine/iodide recycling pathway of follicular cells.", "D": "Adrenal steroidogenesis uses cholesterol as its precursor and occurs in an entirely separate gland; recycled thyroid tyrosine and iodide remain within the thyroid for hormone synthesis, not transported to the adrenal cortex."}}}, {"id": "anking-endocrine-physiology-1335", "fuente": "anking", "tema": 23, "anki": "1461985737790", "q": "A patient has a congenital deficiency of peripheral deiodinase enzymes, impairing recycling of iodide from deiodinated thyroid hormone. This condition functionally mimics a deficiency of which dietary mineral?", "o": {"A": "Iodine", "B": "Selenium", "C": "Iron", "D": "Zinc"}, "r": "A", "e": {"correcta": "Deiodinases remove iodine atoms from T4 and T3 as they are degraded peripherally, and normally this iodide is recycled back into the thyroid for new hormone synthesis. If deiodinase is deficient, this recycling fails and iodide is progressively lost from the body, functionally reproducing a state of dietary iodine deficiency with reduced thyroid hormone synthesis despite normal intake.", "incorrectas": {"B": "Selenium is actually a cofactor required for deiodinase enzyme activity (deiodinases are selenoproteins), so a selenium deficiency would also impair deiodination, but the question describes an inability to recycle iodine, which directly mimics iodine deficiency rather than selenium deficiency itself.", "C": "Iron deficiency impairs thyroid peroxidase function (an iron-containing enzyme) rather than iodide recycling, and would present as a distinct mechanism of hypothyroidism unrelated to deiodinase activity.", "D": "Zinc deficiency is not linked to thyroid hormone deiodination or iodide recycling; zinc deficiency more classically affects taste, wound healing, and immune function."}}}, {"id": "anking-endocrine-physiology-1336", "fuente": "anking", "tema": 23, "anki": "1461985749010", "q": "In the bloodstream, the majority of circulating T3 and T4 is bound to which protein?", "o": {"A": "Albumin", "B": "Thyroxine-binding globulin (TBG)", "C": "Transthyretin", "D": "Corticosteroid-binding globulin"}, "r": "B", "e": {"correcta": "TBG is the primary carrier protein for thyroid hormone, binding the vast majority of circulating T3 and T4. Since only the free (unbound) fraction is biologically active, TBG serves as a large reservoir that buffers plasma hormone levels, releasing free hormone as needed to maintain a stable pool of active thyroid hormone.", "incorrectas": {"A": "Albumin binds a small fraction of circulating thyroid hormone with relatively low affinity, but it is not the primary or highest-affinity carrier — that role belongs to TBG.", "C": "Transthyretin (also called thyroxine-binding prealbumin) does bind thyroid hormone, particularly T4, but it carries a much smaller proportion of the circulating pool compared to TBG.", "D": "Corticosteroid-binding globulin (transcortin) is the carrier protein for cortisol, not thyroid hormone, so it plays no role in T3/T4 transport."}}}, {"id": "anking-endocrine-physiology-1337", "fuente": "anking", "tema": 23, "anki": "1461985920242", "q": "A patient with hepatic failure has decreased hepatic synthesis of thyroxine-binding globulin (TBG). What is the expected effect on a T3 resin uptake test?", "o": {"A": "Resin uptake is decreased", "B": "Resin uptake is increased", "C": "Resin uptake is unchanged", "D": "The test becomes uninterpretable"}, "r": "B", "e": {"correcta": "In hepatic failure, TBG synthesis falls, leaving fewer binding sites available on serum proteins. When radiolabeled T3 is added in the resin uptake test, less of it is captured by the reduced pool of TBG, so more labeled T3 remains free to bind the added resin, increasing resin uptake.", "incorrectas": {"A": "Decreased resin uptake occurs in states of increased TBG (such as pregnancy or estrogen therapy), where more binding sites compete with the resin for labeled T3 — the opposite of what happens with reduced TBG in liver failure.", "C": "The T3 resin uptake test is specifically designed to reflect the number of available TBG binding sites, so any significant change in TBG levels, as in hepatic failure, does change the result rather than leaving it unchanged.", "D": "The test remains interpretable in hepatic failure; it simply shows an increased uptake pattern consistent with reduced TBG, which is a classic teaching point rather than a technical failure of the assay."}}}, {"id": "anking-endocrine-physiology-1338", "fuente": "anking", "tema": 23, "anki": "1461985996999", "q": "During pregnancy, estrogen-driven increases in thyroxine-binding globulin (TBG) have what effect on a T3 resin uptake test?", "o": {"A": "Resin uptake is increased", "B": "Resin uptake is unchanged", "C": "Resin uptake is decreased", "D": "Resin uptake becomes undetectable"}, "r": "C", "e": {"correcta": "Pregnancy increases hepatic production of TBG due to elevated estrogen, expanding the number of available binding sites in serum. This means more of the added radiolabeled T3 is captured by TBG rather than free to bind the resin, so resin uptake decreases even though total thyroid hormone levels rise to maintain a normal free hormone level.", "incorrectas": {"A": "Increased resin uptake is seen when TBG is reduced, such as in hepatic failure or nephrotic syndrome, which is the opposite scenario from the TBG excess of pregnancy.", "B": "Resin uptake is not unchanged in pregnancy; the marked rise in TBG measurably shifts the balance of labeled T3 toward the binding protein and away from the resin, producing a clear decrease in the test result.", "D": "Resin uptake is decreased, not eliminated — free thyroid hormone status remains clinically euthyroid in pregnancy because compensatory increases in total hormone synthesis maintain normal free T4/T3 levels."}}}, {"id": "anking-endocrine-physiology-1339", "fuente": "anking", "tema": 23, "anki": "1461986072634", "q": "Which thyroid hormone binds the nuclear thyroid hormone receptor with greater affinity?", "o": {"A": "T4 (thyroxine)", "B": "Reverse T3 (rT3)", "C": "T3 (triiodothyronine)", "D": "Diiodotyrosine (DIT)"}, "r": "C", "e": {"correcta": "T3 binds the nuclear thyroid hormone receptor with much higher affinity than T4, making it the biologically active form that drives gene transcription at target tissues. Most circulating T4 must be peripherally converted to T3 by deiodinases to exert its full effect.", "incorrectas": {"A": "T4 is the predominant hormone secreted by the thyroid but functions largely as a circulating prohormone, binding the nuclear receptor with lower affinity than T3 until it is converted peripherally.", "B": "Reverse T3 is a biologically inactive metabolite formed by alternative deiodination of T4 and does not meaningfully activate the nuclear thyroid hormone receptor; it is produced in states like starvation or illness to reduce metabolic rate.", "D": "Diiodotyrosine is an intermediate formed during thyroid hormone synthesis within the thyroglobulin molecule, not a circulating hormone that binds nuclear receptors."}}}, {"id": "anking-endocrine-physiology-1340", "fuente": "anking", "tema": 23, "anki": "1461986082711", "q": "During starvation, activity of the enzyme 5'-deiodinase in skeletal muscle is inhibited, but what happens to its activity in the brain?", "o": {"A": "It is also inhibited, mirroring skeletal muscle", "B": "It remains active (not inhibited)", "C": "It is upregulated far beyond baseline", "D": "It is converted to reverse T3 synthase"}, "r": "B", "e": {"correcta": "During starvation, 5'-deiodinase activity is suppressed in peripheral tissues like skeletal muscle to conserve energy by lowering T3 production and metabolic rate, but this enzyme remains active in the brain. This tissue-selective sparing maintains adequate local T3 levels in the brain even during caloric deprivation, protecting critical central nervous system function when the body is otherwise down-regulating metabolism.", "incorrectas": {"A": "If brain deiodinase activity were also inhibited like in skeletal muscle, brain T3 levels would fall along with the rest of the body's metabolic rate, which would be maladaptive since the brain requires a steady fuel and hormone supply even during starvation.", "C": "Deiodinase activity in the brain is preserved at a level sufficient to maintain local T3, not pathologically upregulated beyond normal, which would be an unnecessary and unsupported response to caloric restriction.", "D": "5'-deiodinase converts T4 to the active T3 (removing an outer-ring iodine); it does not get converted into a separate 'reverse T3 synthase' enzyme — reverse T3 is instead produced by a different deiodinase (type III) acting on the inner ring of T4."}}}, {"id": "anking-endocrine-physiology-1341", "fuente": "anking", "tema": 23, "anki": "1462032410674", "q": "Thyrotropin-releasing hormone (TRH) is secreted by which hypothalamic nucleus?", "o": {"A": "Arcuate nucleus", "B": "Paraventricular nucleus", "C": "Supraoptic nucleus", "D": "Suprachiasmatic nucleus"}, "r": "B", "e": {"correcta": "TRH is synthesized and released by parvocellular neurons of the paraventricular nucleus of the hypothalamus. It travels through the hypothalamo-hypophyseal portal system to stimulate thyrotrophs in the anterior pituitary to secrete TSH.", "incorrectas": {"A": "The arcuate nucleus is primarily associated with regulation of appetite (via neurons producing NPY/AgRP and POMC) and GnRH/dopamine secretion, not TRH.", "C": "The supraoptic nucleus, along with the paraventricular nucleus, produces ADH and oxytocin for release from the posterior pituitary, but it is not the source of TRH.", "D": "The suprachiasmatic nucleus is the master circadian pacemaker of the hypothalamus, regulating sleep-wake cycles via input from the retina, and has no direct role in TRH secretion."}}}, {"id": "anking-endocrine-physiology-1342", "fuente": "anking", "tema": 23, "anki": "1462037970480", "q": "An increase in hypothalamic thyrotropin-releasing hormone (TRH) stimulates secretion of which two anterior pituitary hormones?", "o": {"A": "Growth hormone and ACTH", "B": "LH and FSH", "C": "Prolactin and thyroid-stimulating hormone", "D": "ACTH and prolactin"}, "r": "C", "e": {"correcta": "TRH acts on thyrotrophs of the anterior pituitary to stimulate TSH release, but it also has a secondary action on lactotrophs, stimulating prolactin secretion. This is why primary hypothyroidism (with elevated TRH) can sometimes cause mild hyperprolactinemia and galactorrhea.", "incorrectas": {"A": "Growth hormone is regulated primarily by GHRH and somatostatin, and ACTH is regulated by CRH — neither is a direct target of TRH stimulation.", "B": "LH and FSH secretion from gonadotrophs is controlled by GnRH pulsatility, not by TRH, so this pairing does not reflect TRH's actual pituitary targets.", "D": "ACTH is released in response to CRH, not TRH; while prolactin is correctly linked to TRH, pairing it with ACTH rather than TSH misrepresents the classic TRH-responsive hormone pair."}}}, {"id": "anking-endocrine-physiology-1343", "fuente": "anking", "tema": 23, "anki": "1462037991238", "q": "Secretion of thyroid-stimulating hormone (TSH) from the anterior pituitary is decreased in response to rising levels of which substance?", "o": {"A": "Free T3/T4", "B": "TSH receptor antibodies", "C": "Iodide", "D": "Thyroglobulin"}, "r": "A", "e": {"correcta": "Free T3 and T4 exert negative feedback on the anterior pituitary (and hypothalamus), suppressing TSH secretion. Notably, the pituitary itself expresses deiodinase enzymes that convert free T4 to the more potent T3 locally, making pituitary thyrotrophs highly sensitive to circulating T4 levels for feedback purposes.", "incorrectas": {"B": "TSH receptor antibodies, as seen in Graves disease, activate rather than suppress the TSH receptor on thyroid follicular cells; they do not directly act on the pituitary to reduce TSH secretion (though the resulting excess thyroid hormone does suppress TSH via feedback).", "C": "Iodide affects thyroid hormone synthesis directly within the thyroid gland (e.g., the Wolff-Chaikoff effect) rather than acting as the primary negative feedback signal on pituitary TSH secretion.", "D": "Thyroglobulin is the intrathyroidal glycoprotein scaffold for thyroid hormone synthesis and storage; it does not circulate to the pituitary to regulate TSH secretion."}}}, {"id": "anking-endocrine-physiology-1344", "fuente": "anking", "tema": 23, "anki": "1462038045403", "q": "By what mechanism does free T3 decrease TSH secretion from the anterior pituitary?", "o": {"A": "Directly inhibiting TSH gene transcription independent of TRH", "B": "Down-regulating TRH receptors on thyrotrophs", "C": "Increasing somatostatin release from the hypothalamus", "D": "Stimulating dopamine release to inhibit thyrotrophs"}, "r": "B", "e": {"correcta": "Free T3 down-regulates TRH receptor expression on the thyrotrophs of the anterior pituitary, reducing their sensitivity to stimulation by hypothalamic TRH. With fewer functional TRH receptors, the same amount of TRH produces less TSH release, providing negative feedback control of the thyroid axis.", "incorrectas": {"A": "While T3 does ultimately reduce TSH output, the classic mechanism taught is receptor down-regulation reducing responsiveness to TRH, not a TRH-independent direct transcriptional block described in this context.", "C": "Somatostatin primarily inhibits growth hormone and TSH release through a separate hypothalamic pathway, but it is not the mechanism by which free T3 itself suppresses TSH secretion.", "D": "Dopamine tonically inhibits prolactin secretion from lactotrophs; it is not the pathway responsible for T3-mediated suppression of TSH from thyrotrophs."}}}, {"id": "anking-endocrine-physiology-1345", "fuente": "anking", "tema": 23, "anki": "1462038123541", "q": "TSH exerts its actions on the thyroid follicular cell primarily through which second messenger system?", "o": {"A": "IP3/DAG/calcium", "B": "cAMP", "C": "cGMP", "D": "Tyrosine kinase/JAK-STAT"}, "r": "B", "e": {"correcta": "TSH binds a Gs-coupled receptor on thyroid follicular cells, activating adenylate cyclase to raise intracellular cAMP. This cAMP signal drives essentially every step of thyroid hormone synthesis and secretion, as well as the trophic (growth-promoting) effects of TSH on the gland.", "incorrectas": {"A": "The IP3/DAG/calcium pathway is used by Gq-coupled receptors such as those for GnRH, TRH, and alpha-1 adrenergic receptors, not the TSH receptor, which is Gs-coupled.", "C": "cGMP is the second messenger for pathways like atrial natriuretic peptide and nitric oxide signaling, and is not involved in TSH receptor signal transduction.", "D": "Tyrosine kinase/JAK-STAT signaling is used by cytokine and growth factor receptors (e.g., GH, prolactin, erythropoietin receptors), not by the G-protein-coupled TSH receptor."}}}, {"id": "anking-endocrine-physiology-1346", "fuente": "anking", "tema": 23, "anki": "1462038128069", "q": "TSH stimulates thyroid follicular cells to increase which two processes related to thyroid hormone?", "o": {"A": "Synthesis and secretion", "B": "Deiodination and excretion", "C": "Storage and calcification", "D": "Apoptosis and regeneration"}, "r": "A", "e": {"correcta": "TSH acts through cAMP signaling to stimulate essentially every step of the thyroid hormone biosynthetic pathway, from iodide uptake and organification to thyroglobulin proteolysis, thereby increasing both the synthesis of new thyroid hormone and its secretion into the circulation.", "incorrectas": {"B": "Deiodination of T4 to T3 occurs mainly in peripheral tissues (liver, kidney, muscle) rather than being a primary TSH-driven action on the thyroid gland itself, and TSH does not promote hormone excretion.", "C": "TSH promotes active hormone synthesis and release, not simply passive storage, and calcification is not a physiologic action of TSH on follicular cells.", "D": "TSH is a trophic, growth-promoting hormone that supports follicular cell survival and proliferation; it does not primarily induce apoptosis of thyroid cells."}}}, {"id": "anking-endocrine-physiology-1347", "fuente": "anking", "tema": 23, "anki": "1462038150878", "q": "Chronic elevation of TSH exerts a trophic effect on the thyroid gland, leading to which structural change?", "o": {"A": "Follicular atrophy", "B": "Fibrosis and calcification", "C": "Hypertrophy/hyperplasia (goiter)", "D": "Squamous metaplasia"}, "r": "C", "e": {"correcta": "TSH is trophic to thyroid follicular cells, and chronically elevated TSH (as in iodine deficiency or Hashimoto thyroiditis) drives hypertrophy and hyperplasia of the gland, producing a goiter. TSH receptor antibodies in Graves disease produce a similar trophic, goiter-inducing effect by directly activating the same receptor.", "incorrectas": {"A": "Atrophy would be expected with loss of trophic stimulation (e.g., pituitary failure with low TSH), which is the opposite of what chronic TSH elevation produces.", "B": "Fibrosis and calcification are more characteristic of long-standing autoimmune destruction (e.g., burnt-out Hashimoto thyroiditis) rather than the direct proliferative trophic action of TSH itself.", "D": "Squamous metaplasia is not a recognized effect of TSH stimulation on thyroid follicular epithelium; the classic response to chronic TSH drive is glandular enlargement, not a change in epithelial cell type."}}}, {"id": "anking-endocrine-physiology-1348", "fuente": "anking", "tema": 23, "anki": "1462038188179", "q": "Besides TSH itself, the TSH receptor on thyroid follicular cells can be pathologically activated by which substance, characteristic of Graves disease?", "o": {"A": "Thyroglobulin autoantibodies", "B": "Thyroid peroxidase antibodies", "C": "Thyrotropin receptor antibodies (TRAb)", "D": "Anti-nuclear antibodies"}, "r": "C", "e": {"correcta": "In Graves disease, thyroid-stimulating immunoglobulins (a type of TRAb) bind and activate the TSH receptor independent of pituitary control, driving continuous unregulated synthesis and secretion of thyroid hormone and causing hyperthyroidism along with goiter.", "incorrectas": {"A": "Thyroglobulin antibodies target the storage protein for thyroid hormone precursors and are seen in autoimmune thyroiditis, but they do not activate the TSH receptor to stimulate hormone secretion.", "B": "Thyroid peroxidase (anti-TPO) antibodies are associated with Hashimoto thyroiditis and contribute to follicular cell destruction; they do not act as TSH receptor agonists.", "D": "Anti-nuclear antibodies are markers of systemic autoimmune diseases like lupus and are not implicated in TSH receptor activation in Graves disease."}}}, {"id": "anking-endocrine-physiology-1349", "fuente": "anking", "tema": 23, "anki": "1462038201806", "q": "Thyrotropin receptor antibodies (TRAb) belong to which immunoglobulin class?", "o": {"A": "IgA", "B": "IgE", "C": "IgM", "D": "IgG"}, "r": "D", "e": {"correcta": "TRAb, including the thyroid-stimulating immunoglobulins responsible for Graves disease, are IgG antibodies. As IgG, they can cross the placenta, which explains why neonatal Graves disease/neonatal hyperthyroidism can occur when a pregnant woman with high TRAb titers transmits these antibodies to the fetus.", "incorrectas": {"B": "IgE is the antibody class involved in type I hypersensitivity reactions such as allergies and anaphylaxis, not autoimmune receptor-stimulating antibodies like TRAb.", "C": "IgM is the first antibody produced in an acute immune response and is too large to cross the placenta; TRAb's ability to cause transplacental neonatal Graves disease is explained by it being IgG, not IgM.", "A": "IgA is the predominant antibody in mucosal secretions and breast milk, and is not the immunoglobulin class implicated in TSH receptor autoimmunity."}}}, {"id": "anking-endocrine-physiology-1350", "fuente": "anking", "tema": 23, "anki": "1462038209306", "q": "When thyroid-stimulating immunoglobulins bind TSH receptors on thyroid follicular cells, what is the resulting effect?", "o": {"A": "They block T3/T4 secretion", "B": "They stimulate secretion of T3 and T4", "C": "They induce follicular cell apoptosis", "D": "They have no functional effect on hormone secretion"}, "r": "B", "e": {"correcta": "Thyroid-stimulating immunoglobulins mimic the action of TSH by binding and activating the TSH receptor, which triggers the cAMP signaling cascade and drives increased synthesis and secretion of T3 and T4. This autoimmune receptor activation is the pathophysiologic basis of hyperthyroidism in Graves disease.", "incorrectas": {"A": "These antibodies are stimulatory, not blocking; a distinct (much rarer) class of TSH receptor-blocking antibodies exists and can cause hypothyroidism, but the classic thyroid-stimulating immunoglobulins of Graves disease increase hormone output.", "C": "The trophic, receptor-activating effect of these antibodies promotes follicular cell growth and hyperplasia (contributing to goiter), not apoptosis.", "D": "These antibodies have a clear and potent functional effect, unregulated activation of thyroid hormone synthesis and secretion, which is the entire basis of the clinical hyperthyroid state seen in Graves disease."}}}, {"id": "anking-endocrine-pathology-1351", "fuente": "anking", "tema": 5, "anki": "1462038253501", "q": "High titers of thyrotropin receptor antibodies (TRAb) are classically associated with which thyroid disorder?", "o": {"A": "Hashimoto thyroiditis", "B": "Subacute (de Quervain) thyroiditis", "C": "Graves disease", "D": "Toxic multinodular goiter"}, "r": "C", "e": {"correcta": "Graves disease is an autoimmune hyperthyroid condition driven by TRAb (thyroid-stimulating immunoglobulins) that activate the TSH receptor, causing diffuse goiter, hyperthyroidism, and extrathyroidal manifestations such as ophthalmopathy and pretibial myxedema. Elevated TRAb titers are used diagnostically to confirm Graves disease.", "incorrectas": {"A": "Hashimoto thyroiditis is primarily mediated by anti-thyroid peroxidase and anti-thyroglobulin antibodies causing lymphocytic destruction of the gland and hypothyroidism, not TSH receptor-stimulating antibodies.", "B": "Subacute (de Quervain) thyroiditis is typically triggered by a preceding viral infection, causing a painful, granulomatous thyroiditis with transient hyperthyroidism from follicular disruption, not TRAb-mediated receptor activation.", "D": "Toxic multinodular goiter results from autonomously functioning thyroid nodules that secrete hormone independent of TSH regulation, rather than from circulating TSH receptor-activating antibodies."}}}, {"id": "anking-endocrine-pathology-1352", "fuente": "anking", "tema": 5, "anki": "1462038265112", "q": "What is the expected TSH level in a patient with Graves disease?", "o": {"A": "Increased", "B": "Normal", "C": "Decreased", "D": "Undetectable and unmeasurable by any assay"}, "r": "C", "e": {"correcta": "In Graves disease, TRAb directly stimulate the thyroid gland to overproduce T3 and T4 independent of pituitary control. The resulting high circulating levels of free thyroid hormone suppress TSH secretion via negative feedback on the anterior pituitary, so TSH is characteristically low despite an overactive thyroid.", "incorrectas": {"B": "TSH is not normal in Graves disease; the elevated free thyroid hormone levels produce clear suppression of TSH via feedback inhibition, which is a key diagnostic finding distinguishing primary hyperthyroidism from a TSH-secreting pituitary tumor.", "A": "Increased TSH would suggest a secondary (pituitary) cause of hyperthyroidism, such as a TSH-secreting adenoma, rather than the primary thyroid autoimmune process of Graves disease.", "D": "TSH remains measurable, just at a suppressed (low) level, using standard ultrasensitive TSH assays; it does not become undetectable by all assay methods."}}}, {"id": "anking-endocrine-physiology-1353", "fuente": "anking", "tema": 23, "anki": "1462038296160", "q": "What effect does an increase in thyroxine-binding globulin (TBG) levels have on total thyroid hormone secretion?", "o": {"A": "Decreases secretion", "B": "Increases secretion", "C": "Has no effect on secretion", "D": "Halts secretion entirely"}, "r": "B", "e": {"correcta": "When TBG rises, more circulating hormone becomes protein-bound, transiently lowering the free hormone fraction. This drop in free hormone reduces negative feedback on the pituitary, causing a compensatory rise in TSH that stimulates the thyroid to increase total hormone secretion until a new equilibrium is reached where free hormone levels return to normal, even though total hormone levels are now higher.", "incorrectas": {"A": "Decreased secretion would be expected only if free hormone levels remained persistently elevated and suppressed TSH; instead, increased TBG initially lowers free hormone, which stimulates rather than suppresses further secretion.", "C": "TBG changes do affect secretion, since the feedback loop responds specifically to free hormone levels, and any perturbation in binding capacity triggers a compensatory adjustment in thyroid output.", "D": "Secretion is not halted; rather, it increases as a physiologic compensation to restore normal free hormone concentration in the face of an expanded binding protein pool."}}}, {"id": "anking-endocrine-physiology-1354", "fuente": "anking", "tema": 23, "anki": "1462038317147", "q": "Excessive iodide (I-) intake acutely has what effect on thyroid hormone secretion?", "o": {"A": "Increases secretion via enhanced organification", "B": "Decreases secretion (Wolff-Chaikoff effect)", "C": "Has no measurable effect", "D": "Causes irreversible destruction of follicular cells"}, "r": "B", "e": {"correcta": "A large acute iodide load transiently inhibits thyroid peroxidase-mediated organification and hormone synthesis, a protective autoregulatory response known as the Wolff-Chaikoff effect. This temporarily decreases thyroid hormone secretion, preventing hormone overproduction that could otherwise result from the iodide excess.", "incorrectas": {"A": "While moderate iodide is a necessary substrate for hormone synthesis, an excessive acute load paradoxically inhibits rather than enhances organification and hormone output, the opposite of what this option describes.", "C": "Excess iodide clearly produces a measurable effect, the Wolff-Chaikoff effect, which is a well-described autoregulatory suppression of thyroid hormone synthesis used clinically (e.g., potassium iodide before thyroidectomy in Graves disease).", "D": "The Wolff-Chaikoff effect is typically a transient, self-limited (usually days-long) suppression of thyroid function, not permanent destruction of the gland's follicular cells."}}}, {"id": "anking-endocrine-physiology-1355", "fuente": "anking", "tema": 23, "anki": "1462038359619", "q": "Iodide (I-) deficiency has what effect on thyroid hormone secretion?", "o": {"A": "Increases secretion", "B": "No effect on secretion", "C": "Decreases secretion", "D": "Causes secretion to become erratic and unpredictable"}, "r": "C", "e": {"correcta": "Iodide is an essential substrate for thyroid hormone synthesis (needed for iodination of tyrosine residues on thyroglobulin). Without adequate iodide, the thyroid cannot produce sufficient T3 and T4, resulting in decreased hormone secretion, low free hormone levels, and compensatory TSH elevation that can produce a goiter.", "incorrectas": {"A": "Secretion cannot increase without adequate iodide substrate, since iodination of tyrosine residues is an obligatory step in thyroid hormone synthesis.", "B": "Iodide deficiency has a very clear, well-documented effect on thyroid function, historically the most common cause of endemic goiter and hypothyroidism worldwide before iodized salt programs.", "D": "The response to iodide deficiency is a predictable, sustained decrease in hormone synthesis and compensatory TSH-driven glandular hyperplasia, not an erratic or unpredictable pattern."}}}, {"id": "anking-endocrine-physiology-1356", "fuente": "anking", "tema": 23, "anki": "1462038368730", "q": "Obesity is associated with which change in peripheral conversion of T4 to T3?", "o": {"A": "Decreased conversion, with increased reverse T3", "B": "No change in conversion", "C": "Increased conversion, with decreased reverse T3", "D": "Complete cessation of peripheral conversion"}, "r": "C", "e": {"correcta": "Obesity is associated with increased peripheral deiodinase activity converting T4 to the more active T3, which increases the amount of active hormone available to tissues while decreasing the formation of the inactive metabolite reverse T3 (rT3). This contrasts with states like starvation, which favor decreased T3 production and increased rT3 to conserve energy.", "incorrectas": {"A": "Decreased T4-to-T3 conversion with increased reverse T3 is the pattern seen in starvation or severe illness (sick euthyroid syndrome), which is the opposite metabolic adaptation compared to obesity.", "B": "Obesity is specifically associated with a measurable shift toward increased T3 generation, not an absence of change in deiodinase activity.", "D": "Peripheral conversion is enhanced, not stopped, in obesity; complete cessation of deiodination would produce severe hypothyroid-like effects at the tissue level, which is not the physiologic picture in obesity."}}}, {"id": "anking-endocrine-physiology-1357", "fuente": "anking", "tema": 23, "anki": "1462038445101", "q": "After being converted to its active form inside a target cell, T3 enters which cellular compartment to bind its receptor?", "o": {"A": "Mitochondria", "B": "Nucleus", "C": "Cytoplasmic ribosomes", "D": "Golgi apparatus"}, "r": "B", "e": {"correcta": "T3 diffuses into the nucleus, where it binds a nuclear thyroid hormone receptor. This receptor functions as a ligand-activated transcription factor, and the T3-receptor complex binds thyroid-response elements on DNA to regulate gene transcription, distinguishing thyroid hormone action from cell-surface receptor signaling used by peptide hormones.", "incorrectas": {"A": "While thyroid hormone does have some described mitochondrial effects on metabolism, its principal, classically tested mechanism of action is via the nuclear receptor regulating gene transcription, not a primary mitochondrial receptor interaction.", "C": "Ribosomes are the site of protein translation but do not contain the thyroid hormone receptor; the receptor-DNA interaction that initiates the hormone's genomic effects occurs in the nucleus before any new mRNA reaches ribosomes.", "D": "The Golgi apparatus is involved in protein modification and trafficking, not thyroid hormone receptor binding, which is a nuclear event."}}}, {"id": "anking-endocrine-physiology-1358", "fuente": "anking", "tema": 23, "anki": "1462038493029", "q": "After the T3-nuclear receptor complex binds a thyroid-response element on DNA, what is the immediate downstream effect?", "o": {"A": "Inhibition of RNA polymerase II", "B": "Stimulation of DNA transcription", "C": "Direct activation of cytoplasmic kinases", "D": "Degradation of the DNA-receptor complex"}, "r": "B", "e": {"correcta": "The T3-receptor complex acts as a transcription factor, and upon binding thyroid-response elements, it stimulates transcription of target genes into mRNA. This drives synthesis of new proteins (such as Na+/K+-ATPase and structural proteins) responsible for the wide-ranging metabolic and developmental effects of thyroid hormone.", "incorrectas": {"A": "The T3-receptor complex generally promotes rather than inhibits transcription at its target genes; inhibition of RNA polymerase II activity is not the mechanism by which thyroid hormone exerts its genomic effects.", "C": "Thyroid hormone's classic genomic action operates through direct nuclear gene transcription rather than through activation of cytoplasmic kinase cascades, which is characteristic of membrane receptor signaling (e.g., insulin or growth factor receptors) instead.", "D": "The T3-receptor-DNA complex functions as an active transcriptional unit; it is not immediately targeted for degradation, as its whole purpose is to persist and drive gene expression."}}}, {"id": "anking-endocrine-physiology-1359", "fuente": "anking", "tema": 23, "anki": "1462038533263", "q": "Thyroid hormone increases oxygen consumption and basal metabolic rate in most tissues, but this effect is notably absent in which tissues?", "o": {"A": "Liver, kidney, and muscle", "B": "Brain, gonads, and spleen", "C": "Heart and lungs", "D": "Skin and adipose tissue"}, "r": "B", "e": {"correcta": "Thyroid hormone increases oxygen consumption and heat production in most metabolically active tissues by upregulating Na+/K+-ATPase activity, but the brain, gonads, and spleen are notable exceptions that do not show this thermogenic increase in oxygen consumption in response to thyroid hormone.", "incorrectas": {"A": "Liver, kidney, and muscle are classic examples of tissues where thyroid hormone does increase oxygen consumption and metabolic rate, making this option the opposite of the tested exception list.", "C": "The heart and lungs show increased activity (heart rate, contractility, ventilation) under thyroid hormone influence, which reflects increased rather than absent metabolic stimulation.", "D": "Skin and adipose tissue are also generally responsive to thyroid hormone's metabolic effects, unlike the brain, gonads, and spleen, which are specifically excluded from the oxygen consumption increase."}}}, {"id": "anking-endocrine-physiology-1360", "fuente": "anking", "tema": 23, "anki": "1462038554234", "q": "By what mechanism does thyroid hormone increase cellular oxygen consumption?", "o": {"A": "Increased synthesis and activity of Na+-K+-ATPase", "B": "Increased mitochondrial biogenesis exclusively", "C": "Direct inhibition of the electron transport chain", "D": "Upregulation of anaerobic glycolysis enzymes only"}, "r": "A", "e": {"correcta": "Thyroid hormone increases the synthesis and activity of the Na+-K+-ATPase pump in cell membranes. Because this pump uses primary active transport that consumes ATP, increased pump activity raises ATP demand and thus oxygen consumption, while the energy expended is released as heat, contributing to thyroid hormone's calorigenic effect.", "incorrectas": {"B": "While thyroid hormone does have effects on mitochondrial number and function, the specific and classically tested mechanism linking it to increased oxygen consumption is upregulation of the Na+-K+-ATPase pump, not mitochondrial biogenesis alone.", "C": "Thyroid hormone increases, rather than inhibits, oxidative metabolism and electron transport chain activity as part of its overall stimulation of cellular respiration.", "D": "Thyroid hormone promotes aerobic oxidative metabolism and oxygen consumption; it does not selectively upregulate anaerobic glycolysis, which would not explain increased oxygen use."}}}, {"id": "anking-endocrine-physiology-1361", "fuente": "anking", "tema": 23, "anki": "1462038586217", "q": "Thyroid hormone increases absorption of which nutrient from the GI tract to help meet the metabolic demands of increased oxygen consumption?", "o": {"A": "Glucose", "B": "Amino acids exclusively", "C": "Calcium", "D": "Long-chain fatty acids"}, "r": "A", "e": {"correcta": "Thyroid hormone increases intestinal absorption of glucose, supplying the additional substrate needed to fuel the elevated oxidative metabolism and ATP demand (largely from increased Na+-K+-ATPase activity) that thyroid hormone induces throughout the body.", "incorrectas": {"B": "Although thyroid hormone broadly increases metabolic turnover including protein metabolism, the specific GI absorptive effect classically tested is increased glucose absorption, not a selective increase limited to amino acids.", "C": "Calcium absorption and metabolism are primarily regulated by vitamin D, PTH, and calcitonin; thyroid hormone's key metabolic support in this context is directed at increasing glucose availability, not calcium.", "D": "Fatty acid absorption is not the specific nutrient effect associated with thyroid hormone's role in meeting increased oxygen consumption demands; glucose is the classic answer."}}}, {"id": "anking-endocrine-physiology-1362", "fuente": "anking", "tema": 23, "anki": "1462038610838", "q": "Although thyroid hormone increases both protein synthesis and protein degradation, what is its net overall effect on protein metabolism?", "o": {"A": "Net anabolic, causing increased muscle mass", "B": "Net catabolic, causing decreased muscle mass", "C": "No net effect on protein balance", "D": "Selective anabolism restricted to cardiac muscle"}, "r": "B", "e": {"correcta": "Even though thyroid hormone stimulates both synthesis and breakdown of protein, degradation predominates overall, producing a net catabolic effect. This explains the muscle wasting and weakness seen clinically in hyperthyroid states, despite increased protein synthetic activity occurring simultaneously.", "incorrectas": {"A": "Excess thyroid hormone is catabolic overall and is associated with muscle wasting (proximal myopathy) rather than anabolic muscle building, which distinguishes its net effect from anabolic hormones like testosterone or growth hormone.", "C": "There is a clear net effect, not a balance; the tested teaching point specifically emphasizes that degradation exceeds synthesis, tipping the balance toward net protein loss.", "D": "The catabolic effect of thyroid hormone on protein metabolism is systemic, affecting skeletal muscle broadly, rather than being selectively confined to cardiac muscle."}}}, {"id": "anking-endocrine-physiology-1363", "fuente": "anking", "tema": 23, "anki": "1462038624500", "q": "What is the overall effect of thyroid hormone on cardiovascular and respiratory system activity?", "o": {"A": "Decreased activity, with bradycardia and hypoventilation", "B": "Increased activity, with higher cardiac output and ventilation rate", "C": "No significant effect on either system", "D": "Selective increase in respiratory rate only, with no cardiac effect"}, "r": "B", "e": {"correcta": "Thyroid hormone increases overall cardiovascular and respiratory activity, raising cardiac output (via increased heart rate and contractility) and increasing ventilation rate to meet the heightened tissue oxygen demand generated by thyroid hormone's calorigenic effects.", "incorrectas": {"A": "Decreased cardiovascular and respiratory activity with bradycardia is a feature of hypothyroidism, the opposite hormonal state, not of normal or excess thyroid hormone action.", "C": "Thyroid hormone has robust, well-documented effects on both systems; hyperthyroid patients classically present with tachycardia, palpitations, and increased respiratory rate, showing this is far from a null effect.", "D": "Thyroid hormone increases both cardiac and respiratory activity together, as both systems must work harder to support the elevated tissue oxygen consumption it induces; it does not spare the cardiovascular system."}}}, {"id": "anking-endocrine-physiology-1364", "fuente": "anking", "tema": 23, "anki": "1462038633475", "q": "Thyroid hormone increases cardiac output partly by inducing upregulation of which cardiac receptor?", "o": {"A": "α1-adrenergic receptor", "B": "M2 muscarinic receptor", "C": "β1-adrenergic receptor", "D": "Angiotensin II type 1 receptor"}, "r": "C", "e": {"correcta": "Thyroid hormone upregulates β1-adrenergic receptor expression in the heart, amplifying the sensitivity of cardiac tissue to sympathetic stimulation. This mediates increased heart rate, contractility, stroke volume, and cardiac output, and explains why β-blockers are used to control the adrenergic symptoms of thyroid storm.", "incorrectas": {"A": "α1-adrenergic receptors are more associated with vascular smooth muscle vasoconstriction rather than the primary cardiac chronotropic and inotropic effects driven by thyroid hormone's β1 upregulation.", "B": "M2 muscarinic receptors mediate parasympathetic (vagal) slowing of heart rate; thyroid hormone's cardiovascular effects work through enhancing sympathetic β1 signaling, not muscarinic receptors.", "D": "Angiotensin II type 1 receptors mediate blood pressure regulation through the renin-angiotensin system, not the thyroid hormone-driven upregulation of adrenergic sensitivity in the heart."}}}, {"id": "anking-endocrine-physiology-1365", "fuente": "anking", "tema": 23, "anki": "1462038652698", "q": "The thyroid hormone-induced increase in cardiac output results from a combination of increased heart rate and increased what other parameter?", "o": {"A": "Total peripheral resistance", "B": "Stroke volume (contractility)", "C": "Central venous pressure", "D": "Pulmonary vascular resistance"}, "r": "B", "e": {"correcta": "Thyroid hormone increases cardiac output through two complementary mechanisms: an increased heart rate (chronotropy) and an increased stroke volume driven by enhanced myocardial contractility (inotropy), both amplified by β1-adrenergic receptor upregulation in the heart.", "incorrectas": {"A": "Thyroid hormone actually tends to decrease total peripheral resistance (via vasodilation to dissipate the extra heat generated), which helps maintain blood pressure despite the marked rise in cardiac output, rather than contributing to that rise itself.", "C": "Central venous pressure is not the parameter classically paired with heart rate in explaining thyroid hormone's effect on cardiac output; stroke volume/contractility is the standard teaching point.", "D": "Pulmonary vascular resistance is not a primary driver of the systemic cardiac output increase attributed to thyroid hormone; the relevant contractile parameter is stroke volume in the systemic circulation."}}}, {"id": "anking-endocrine-physiology-1366", "fuente": "anking", "tema": 23, "anki": "1462038682267", "q": "Thyroid hormone works synergistically with growth hormone and somatomedins to promote which skeletal process, necessary for attaining normal adult height?", "o": {"A": "Bone resorption exclusively", "B": "Bone formation", "C": "Cartilage calcification without growth", "D": "Osteoclast differentiation only"}, "r": "B", "e": {"correcta": "Thyroid hormone acts synergistically with growth hormone and IGF-1 (somatomedins) to promote bone formation, and adequate thyroid hormone is required to achieve normal adult stature. Congenital hypothyroidism (cretinism) causes marked growth failure and skeletal maturation delay if untreated.", "incorrectas": {"A": "While bone remodeling involves both formation and resorption, the synergistic growth-promoting action highlighted with GH/somatomedins is specifically new bone formation supporting linear growth, not resorption alone.", "C": "The synergy with GH and somatomedins is specifically about active bone formation and growth, not simply calcification of cartilage without an accompanying growth process.", "D": "Osteoclast differentiation pertains to bone resorption, which is not the aspect of skeletal biology emphasized in the growth-promoting synergy between thyroid hormone and growth hormone/somatomedins."}}}, {"id": "anking-endocrine-physiology-1367", "fuente": "anking", "tema": 23, "anki": "1462038696517", "q": "Thyroid hormone stimulates which skeletal process, resulting from ossification and fusion of the growth plates?", "o": {"A": "Bone maturation", "B": "Bone marrow hyperplasia", "C": "Osteoporosis in children", "D": "Chondrocyte proliferation without ossification"}, "r": "A", "e": {"correcta": "Thyroid hormone stimulates bone maturation by promoting ossification and eventual fusion of the epiphyseal growth plates. A lack of thyroid hormone (as in congenital hypothyroidism) delays bone maturation, producing a bone age that lags behind chronologic age, a classic finding used to detect hypothyroidism in children.", "incorrectas": {"B": "Bone marrow hyperplasia refers to increased hematopoietic cellularity within marrow, not the skeletal maturation and growth plate fusion process attributed to thyroid hormone.", "C": "Thyroid hormone deficiency, not excess, is associated with delayed bone maturation; osteoporosis in children is not the described effect of normal thyroid hormone action on the growth plate.", "D": "Thyroid hormone promotes progression to ossification (calcified, mature bone) rather than simply causing unchecked chondrocyte proliferation without eventual mineralization and plate fusion."}}}, {"id": "anking-endocrine-physiology-1368", "fuente": "anking", "tema": 23, "anki": "1462038822137", "q": "Thyroid hormone shares many physiologic actions with which branch of the autonomic nervous system, largely through its upregulation of β1-adrenergic receptors?", "o": {"A": "Parasympathetic nervous system", "B": "Enteric nervous system", "C": "Sympathetic nervous system", "D": "Somatic motor nervous system"}, "r": "C", "e": {"correcta": "By upregulating β1-adrenergic receptors in tissues like the heart, thyroid hormone amplifies the effects of sympathetic stimulation, producing sympathomimetic-like features such as tachycardia, increased contractility, tremor, and heat intolerance that closely resemble sympathetic nervous system activation.", "incorrectas": {"A": "The parasympathetic nervous system generally produces opposing effects (e.g., bradycardia via vagal M2 receptor activity), which is the opposite pattern of what thyroid hormone's β1 upregulation produces.", "B": "The enteric nervous system governs intrinsic GI motility and secretion independent of adrenergic receptor upregulation, and is not the system whose actions thyroid hormone is described as mimicking here.", "D": "The somatic motor nervous system controls voluntary skeletal muscle contraction via neuromuscular junctions, which is unrelated to the adrenergic receptor-mediated resemblance between thyroid hormone action and the sympathetic nervous system."}}}, {"id": "anking-endocrine-pathology-1369", "fuente": "anking", "tema": 5, "anki": "1462038910568", "q": "In a patient with clinical hyperthyroidism, an elevated (rather than suppressed) TSH level should raise suspicion for which type of underlying cause?", "o": {"A": "Primary thyroid disease such as a toxic nodule", "B": "A disorder in the hypothalamus or anterior pituitary causing excess TRH or TSH secretion", "C": "Subclinical thyroiditis", "D": "Peripheral thyroid hormone resistance limited to target tissues"}, "r": "B", "e": {"correcta": "Normally, hyperthyroidism from primary thyroid overactivity suppresses TSH via negative feedback. An elevated TSH in the setting of hyperthyroidism instead points to a central (secondary) cause, such as a TSH-secreting pituitary adenoma or excessive hypothalamic TRH drive, where the pituitary or hypothalamus itself is the source of the abnormal stimulation rather than responding appropriately to high hormone levels.", "incorrectas": {"A": "Primary thyroid disease, such as a toxic adenoma or Graves disease, produces hyperthyroidism through autonomous thyroid hormone overproduction, which suppresses (not elevates) TSH through intact negative feedback.", "C": "Subclinical thyroiditis typically presents with variable TSH depending on phase of illness, but is not the classic explanation taught for elevated TSH coexisting with clinical hyperthyroidism; the central pituitary/hypothalamic cause is the key teaching point.", "D": "Generalized thyroid hormone resistance syndromes can show elevated TSH with high thyroid hormone levels, but this represents defective receptor signaling throughout the body (including the pituitary), which is a distinct and much rarer explanation than the hypothalamic/pituitary oversecretion scenario being tested here."}}}, {"id": "anking-endocrine-pharmacology-1370", "fuente": "anking", "tema": 24, "anki": "1462038986297", "q": "A patient with hyperthyroidism is started on a thionamide drug that inhibits both thyroid peroxidase and peripheral deiodinase. Which drug is this?", "o": {"A": "Methimazole", "B": "Propylthiouracil (PTU)", "C": "Potassium iodide", "D": "Levothyroxine"}, "r": "B", "e": {"correcta": "PTU blocks thyroid peroxidase (preventing iodide oxidation and organification, and coupling of iodotyrosines) and also inhibits peripheral 5'-deiodinase, which converts T4 to the more active T3. This dual mechanism makes it especially useful in thyroid storm. Surgical thyroidectomy is another definitive treatment option for hyperthyroidism.", "incorrectas": {"A": "Methimazole also inhibits thyroid peroxidase and is actually preferred over PTU for long-term management (less hepatotoxicity), but unlike PTU it does not inhibit peripheral deiodinase, so it lacks the added benefit of blocking T4-to-T3 conversion.", "C": "Potassium iodide (Wolff-Chaikoff effect) transiently inhibits thyroid hormone release and synthesis at high doses, typically used short-term before surgery, but it does not act by inhibiting thyroid peroxidase or deiodinase enzymatically.", "D": "Levothyroxine is synthetic T4 used to treat hypothyroidism, the opposite condition; it is a hormone replacement, not an antithyroid drug."}}}, {"id": "anking-endocrine-pathology-1371", "fuente": "anking", "tema": 5, "anki": "1462039003966", "q": "A goiter (enlarged thyroid gland) can be seen in which of the following thyroid function states?", "o": {"A": "Hyperthyroidism only", "B": "Hypothyroidism only", "C": "Both hyperthyroidism and hypothyroidism", "D": "Neither, goiter only occurs with euthyroid nodules"}, "r": "C", "e": {"correcta": "Goiter simply reflects thyroid gland enlargement and can occur in both hyperthyroid states (e.g., Graves disease, where TSH-receptor stimulating antibodies drive follicular hyperplasia) and hypothyroid states (e.g., Hashimoto thyroiditis or iodine deficiency, where chronically elevated TSH drives glandular hypertrophy/hyperplasia). The functional status of the thyroid must be assessed separately with TSH/T4 levels.", "incorrectas": {"A": "Restricting goiter to hyperthyroidism ignores that hypothyroid conditions like Hashimoto thyroiditis and iodine deficiency also commonly cause glandular enlargement via TSH-driven hyperplasia.", "B": "Restricting goiter to hypothyroidism ignores that Graves disease and toxic multinodular goiter are hyperthyroid conditions that also produce a diffusely or nodularly enlarged gland.", "D": "Goiter is not limited to euthyroid nodules; it is a nonspecific finding of gland enlargement that can accompany hyperthyroid, hypothyroid, or euthyroid states depending on the underlying cause."}}}, {"id": "anking-endocrine-pathology-1372", "fuente": "anking", "tema": 5, "anki": "1462039023178", "q": "In iodine-replete countries, what is the most common cause of hypothyroidism?", "o": {"A": "Autoimmune (Hashimoto) thyroiditis", "B": "Iodine deficiency", "C": "Subacute (de Quervain) thyroiditis", "D": "Pituitary adenoma causing secondary hypothyroidism"}, "r": "A", "e": {"correcta": "Hashimoto thyroiditis is an autoimmune process featuring antithyroid peroxidase and antithyroglobulin antibodies with lymphocytic infiltration of the thyroid, leading to progressive gland destruction and hypothyroidism; it is the leading cause of hypothyroidism where iodine intake is adequate.", "incorrectas": {"B": "Iodine deficiency is the most common cause of hypothyroidism worldwide but specifically in iodine-deficient regions, not in iodine-replete countries where Hashimoto thyroiditis predominates.", "C": "Subacute (de Quervain) thyroiditis is typically postviral, presents with a painful tender thyroid, and usually causes a transient thyrotoxic phase followed by transient hypothyroidism, not the chronic primary hypothyroidism most commonly seen.", "D": "Pituitary adenoma causing decreased TSH secretion (secondary/central hypothyroidism) is a much less common cause than primary autoimmune thyroid failure."}}}, {"id": "anking-endocrine-physiology-1373", "fuente": "anking", "tema": 23, "anki": "1462039030033", "q": "In hypothyroidism due to thyroiditis or iodine deficiency, what happens to TSH levels, and why?", "o": {"A": "TSH decreases due to reduced hypothalamic TRH output", "B": "TSH increases due to loss of negative feedback from low free T3/T4", "C": "TSH remains normal because the defect is purely glandular", "D": "TSH increases because TRH receptors become desensitized"}, "r": "B", "e": {"correcta": "When the thyroid gland itself fails to produce adequate T3/T4 (primary hypothyroidism from thyroiditis or iodine deficiency), the normal negative feedback of thyroid hormone on the hypothalamus and anterior pituitary is lost, so TRH and TSH secretion increase in a compensatory attempt to drive more hormone production.", "incorrectas": {"A": "A decrease in TRH would only occur if the defect were at the hypothalamic level (tertiary hypothyroidism), not in primary gland failure, where feedback loss actually raises TRH and TSH.", "C": "TSH does not stay normal in primary hypothyroidism; the hallmark lab finding is an elevated TSH with low free T4, which is precisely how primary thyroid failure is diagnosed.", "D": "TRH receptor desensitization is not the mechanism; the rise in TSH results from the physiologic negative feedback loop being disrupted by low circulating thyroid hormone, not receptor downregulation."}}}, {"id": "anking-endocrine-physiology-1374", "fuente": "anking", "tema": 23, "anki": "1462039045912", "q": "In which scenario would TSH levels be decreased in a patient with hypothyroidism?", "o": {"A": "When hypothyroidism is caused by Hashimoto thyroiditis", "B": "When the defect lies in the hypothalamus or anterior pituitary (insufficient TRH or TSH secretion)", "C": "When hypothyroidism is caused by iodine deficiency", "D": "When there is peripheral resistance to thyroid hormone"}, "r": "B", "e": {"correcta": "Central (secondary or tertiary) hypothyroidism results from inadequate TRH or TSH secretion by the hypothalamus or anterior pituitary, respectively. In these cases the thyroid gland itself is normal but understimulated, so TSH is low or inappropriately normal despite low T4, unlike in primary gland failure.", "incorrectas": {"A": "Hashimoto thyroiditis destroys the thyroid gland itself, so it causes primary hypothyroidism with elevated (not decreased) TSH due to loss of negative feedback.", "C": "Iodine deficiency impairs hormone synthesis at the level of the gland, again causing primary hypothyroidism with a compensatory rise in TSH, not a decrease.", "D": "Peripheral resistance to thyroid hormone typically presents with elevated or normal TSH and elevated thyroid hormone levels because tissues fail to respond appropriately, which is a different mechanism than decreased pituitary/hypothalamic output."}}}, {"id": "anking-endocrine-pharmacology-1375", "fuente": "anking", "tema": 24, "anki": "1462039119063", "q": "Hypothyroidism is most appropriately treated with which of the following?", "o": {"A": "Propylthiouracil", "B": "Thyroid hormone replacement therapy (e.g., levothyroxine, liothyronine)", "C": "Radioactive iodine ablation", "D": "Beta-blockers"}, "r": "B", "e": {"correcta": "Hypothyroidism is treated by replacing deficient hormone with synthetic levothyroxine (T4) or liothyronine (T3), restoring circulating thyroid hormone levels and normalizing TSH via feedback.", "incorrectas": {"A": "Propylthiouracil is an antithyroid drug used to reduce hormone synthesis in hyperthyroidism; giving it to a hypothyroid patient would worsen the deficiency.", "C": "Radioactive iodine ablation destroys thyroid tissue and is a treatment for hyperthyroidism (e.g., Graves disease), not an appropriate therapy for a gland that is already underactive.", "D": "Beta-blockers manage adrenergic symptoms (tachycardia, tremor) in hyperthyroidism/thyroid storm; they do not address the hormone deficiency of hypothyroidism."}}}, {"id": "anking-endocrine-anatomy-1376", "fuente": "anking", "tema": 25, "anki": "1462043410108", "q": "The adrenal medulla secretes which two catecholamines?", "o": {"A": "Dopamine and serotonin", "B": "Cortisol and aldosterone", "C": "Norepinephrine and epinephrine", "D": "Androgens and estrogens"}, "r": "C", "e": {"correcta": "The adrenal medulla is composed of chromaffin cells derived from neural crest that synthesize and secrete the catecholamines norepinephrine and epinephrine into the bloodstream, mediating the sympathetic 'fight-or-flight' response, especially epinephrine which requires cortisol-induced PNMT for its final synthesis step.", "incorrectas": {"A": "Dopamine is a catecholamine precursor synthesized in the pathway but is not the principal secretory product of the adrenal medulla, and serotonin is not produced by chromaffin cells at all.", "B": "Cortisol and aldosterone are steroid hormones produced by the adrenal cortex (zona fasciculata and zona glomerulosa, respectively), not the medulla, which secretes catecholamines instead.", "D": "Androgens (like DHEA) are produced by the zona reticularis of the adrenal cortex, not the medulla, which is unrelated to steroidogenesis."}}}, {"id": "anking-endocrine-anatomy-1377", "fuente": "anking", "tema": 25, "anki": "1462043412770", "q": "The adrenal cortex, which makes up approximately 80% of the glandular tissue, occupies which zone of the adrenal gland?", "o": {"A": "The innermost zone", "B": "The outer zone", "C": "A scattered zone within the medulla", "D": "The capsule only"}, "r": "B", "e": {"correcta": "The adrenal cortex forms the outer portion of the adrenal gland, surrounding the centrally located medulla, and accounts for roughly 80% of the gland's total mass. It is subdivided into three concentric zones (glomerulosa, fasciculata, reticularis) that each synthesize distinct classes of steroid hormones.", "incorrectas": {"A": "The innermost region of the adrenal gland is the medulla, which produces catecholamines, not the steroid-producing cortex.", "C": "The cortex is not scattered within the medulla; it forms a distinct, organized outer layer surrounding the medulla, not an intermixed or scattered arrangement.", "D": "The capsule is a thin connective tissue covering external to the cortex, not the cortex itself, which lies beneath the capsule and comprises the bulk of the gland."}}}, {"id": "anking-endocrine-anatomy-1378", "fuente": "anking", "tema": 25, "anki": "1462049653810", "q": "Which zone of the adrenal cortex is the middle and widest layer, situated between the zona glomerulosa and zona reticularis?", "o": {"A": "Zona reticularis", "B": "Zona glomerulosa", "C": "Zona fasciculata", "D": "Zona medullaris"}, "r": "C", "e": {"correcta": "The zona fasciculata is the middle and widest of the three adrenal cortical layers, situated between the outer zona glomerulosa and the inner zona reticularis. It is primarily responsible for glucocorticoid (cortisol) synthesis under ACTH stimulation.", "incorrectas": {"A": "The zona reticularis is the innermost cortical layer, adjacent to the medulla, and mainly produces adrenal androgens, not the widest middle layer.", "B": "The zona glomerulosa is the outermost cortical layer, responsible for mineralocorticoid (aldosterone) production, not the middle widest zone.", "D": "There is no 'zona medullaris'; the medulla is a separate structure entirely distinct from the three cortical zones."}}}, {"id": "anking-endocrine-physiology-1379", "fuente": "anking", "tema": 23, "anki": "1462049746964", "q": "What is the rate-limiting enzyme in the biosynthesis of all adrenocortical steroid hormones?", "o": {"A": "21β-hydroxylase", "B": "Aldosterone synthase", "C": "Cholesterol desmolase", "D": "17α-hydroxylase"}, "r": "C", "e": {"correcta": "Cholesterol desmolase (side-chain cleavage enzyme, CYP11A1) catalyzes the conversion of cholesterol to pregnenolone, the first and rate-limiting step common to all steroid hormone synthesis pathways. A complete deficiency is lethal in utero because it also abolishes placental progesterone synthesis needed to maintain pregnancy.", "incorrectas": {"A": "21β-hydroxylase acts downstream, converting progesterone to deoxycorticosterone and 17-hydroxyprogesterone to 11-deoxycortisol; its deficiency causes congenital adrenal hyperplasia but it is not the initial rate-limiting enzyme.", "B": "Aldosterone synthase is the terminal, zona glomerulosa-specific enzyme that converts corticosterone to aldosterone; it acts far downstream of the rate-limiting step.", "D": "17α-hydroxylase converts pregnenolone/progesterone toward cortisol and androgen precursors in the zona fasciculata/reticularis but is not the shared rate-limiting enzyme for the entire steroidogenic pathway."}}}, {"id": "anking-endocrine-physiology-1380", "fuente": "anking", "tema": 23, "anki": "1462049756266", "q": "Which of the following is the major glucocorticoid produced by the human adrenal cortex?", "o": {"A": "Aldosterone", "B": "Corticosterone", "C": "Cortisol (hydrocortisone)", "D": "Dehydroepiandrosterone (DHEA)"}, "r": "C", "e": {"correcta": "Cortisol, also called hydrocortisone, is the principal glucocorticoid secreted by the zona fasciculata of the adrenal cortex, regulating glucose metabolism, immune suppression, and stress responses under control of the hypothalamic-pituitary-adrenal axis (CRH-ACTH-cortisol).", "incorrectas": {"A": "Aldosterone is the major mineralocorticoid, produced by the zona glomerulosa and regulating sodium/potassium and volume homeostasis, not the primary glucocorticoid.", "B": "Corticosterone does have some glucocorticoid activity and is an important intermediate/hormone in rodents, but in humans cortisol is quantitatively and functionally the dominant glucocorticoid.", "D": "DHEA is a weak adrenal androgen produced by the zona reticularis, serving as a precursor for peripheral sex steroid synthesis, not a glucocorticoid."}}}, {"id": "anking-endocrine-physiology-1381", "fuente": "anking", "tema": 23, "anki": "1462049766892", "q": "Which hormone is the major mineralocorticoid produced by the human adrenal cortex?", "o": {"A": "Cortisol", "B": "Aldosterone", "C": "Corticosterone", "D": "Testosterone"}, "r": "B", "e": {"correcta": "Aldosterone is the principal mineralocorticoid, synthesized in the zona glomerulosa via the unique enzyme aldosterone synthase. It acts on the distal nephron to increase sodium reabsorption and potassium/hydrogen secretion, playing a key role in blood pressure and volume regulation via the renin-angiotensin-aldosterone system.", "incorrectas": {"A": "Cortisol is the major glucocorticoid, and although it has some mineralocorticoid activity at high concentrations, it is not the primary mineralocorticoid under normal physiologic conditions.", "C": "Corticosterone is an intermediate with mixed weak glucocorticoid/mineralocorticoid activity, but it is not the major mineralocorticoid in humans, unlike in rodents.", "D": "Testosterone is an androgen involved in male sexual development, unrelated to mineralocorticoid function."}}}, {"id": "anking-endocrine-physiology-1382", "fuente": "anking", "tema": 23, "anki": "1462050054661", "q": "If the mineralocorticoid synthesis pathway is blocked below the level of 11-deoxycorticosterone (DOC) — such as with 11β-hydroxylase or aldosterone synthase deficiency — can mineralocorticoids still be produced?", "o": {"A": "No, synthesis is completely blocked", "B": "Yes, because DOC and corticosterone both retain mineralocorticoid activity", "C": "Yes, but only via conversion of cortisol to aldosterone", "D": "No, because 21β-hydroxylase is also required and absent"}, "r": "B", "e": {"correcta": "DOC (11-deoxycorticosterone) and corticosterone, the precursors that accumulate proximal to a block at 11β-hydroxylase or aldosterone synthase, both possess intrinsic mineralocorticoid activity. So even without terminal conversion to aldosterone, some mineralocorticoid effect persists, which is why these enzyme deficiencies present with hypertension rather than salt-wasting.", "incorrectas": {"A": "Synthesis is not completely blocked because the accumulated precursors (DOC, corticosterone) themselves have mineralocorticoid activity, distinguishing this scenario from a block earlier in the pathway.", "C": "Cortisol is not converted to aldosterone; the mineralocorticoid effect instead comes from the accumulated intermediate precursors proximal to the enzymatic block.", "D": "21β-hydroxylase acts upstream (converting progesterone to DOC), so a block at 11β-hydroxylase or aldosterone synthase occurs downstream of it and does not require an additional 21β-hydroxylase deficiency to explain the finding."}}}, {"id": "anking-endocrine-physiology-1383", "fuente": "anking", "tema": 23, "anki": "1462050131597", "q": "If the mineralocorticoid synthesis pathway is blocked above the level of 11-deoxycorticosterone (DOC), as in 21β-hydroxylase deficiency, can mineralocorticoids still be produced?", "o": {"A": "Yes, corticosterone still retains full mineralocorticoid activity", "B": "No, because there is no precursor beyond the block with mineralocorticoid activity", "C": "Yes, via an alternate zona reticularis pathway", "D": "No, because ACTH secretion is suppressed"}, "r": "B", "e": {"correcta": "21β-hydroxylase deficiency blocks the pathway before DOC is formed, so none of the downstream intermediates with mineralocorticoid activity (DOC, corticosterone, aldosterone) can be synthesized. This is why classic 21-hydroxylase deficiency (a cause of congenital adrenal hyperplasia) leads to salt-wasting due to aldosterone deficiency.", "incorrectas": {"A": "Corticosterone cannot be formed at all if the block is above the level of DOC, since 21β-hydroxylase is required to generate DOC (and subsequently corticosterone) from progesterone in the first place.", "C": "The zona reticularis primarily produces androgens, not mineralocorticoids, and does not provide an alternate route to bypass a 21β-hydroxylase block in the glomerulosa pathway.", "D": "The clinical problem is enzymatic blockade preventing hormone synthesis, not suppressed ACTH; in fact, cortisol deficiency from the same block causes compensatory ACTH elevation and adrenal hyperplasia."}}}, {"id": "anking-endocrine-physiology-1384", "fuente": "anking", "tema": 23, "anki": "1462050321344", "q": "In the absence of 17α-hydroxylase, can glucocorticoids still be produced?", "o": {"A": "No, glucocorticoid synthesis is completely abolished", "B": "Yes, the zona fasciculata can still produce corticosterone, which has glucocorticoid activity", "C": "Yes, through unopposed androgen conversion", "D": "No, because cortisol is the only glucocorticoid and requires this enzyme"}, "r": "B", "e": {"correcta": "17α-hydroxylase deficiency blocks cortisol and androgen synthesis specifically, but the zona fasciculata can still produce corticosterone via the mineralocorticoid-shared pathway, and corticosterone possesses meaningful glucocorticoid (as well as mineralocorticoid) activity, preventing complete glucocorticoid deficiency.", "incorrectas": {"A": "Glucocorticoid synthesis is not completely abolished because corticosterone, which does not require 17α-hydroxylase, still provides glucocorticoid activity in this deficiency.", "C": "Androgen conversion actually requires 17α-hydroxylase (and 17,20-lyase) as well, so this pathway is also blocked, not enhanced or providing an alternate glucocorticoid source.", "D": "Cortisol is the major but not the only glucocorticoid; corticosterone can substitute with weaker but present glucocorticoid activity when 17α-hydroxylase is absent."}}}, {"id": "anking-endocrine-physiology-1385", "fuente": "anking", "tema": 23, "anki": "1462050384019", "q": "Can glucocorticoids still be produced if there is a deficiency of cholesterol desmolase, 21β-hydroxylase, 11β-hydroxylase, or 3β-hydroxysteroid dehydrogenase?", "o": {"A": "Yes, corticosterone compensates in all these cases", "B": "No, deficiency of any of these enzymes blocks synthesis of both corticosterone and cortisol", "C": "Yes, but only cortisol synthesis is affected, not corticosterone", "D": "No, but only because ACTH secretion fails"}, "r": "B", "e": {"correcta": "Cholesterol desmolase, 3β-hydroxysteroid dehydrogenase, 21β-hydroxylase, and 11β-hydroxylase all act at steps shared by both the corticosterone and cortisol synthesis pathways (upstream of or at the point where the pathways diverge from 17α-hydroxylase). A deficiency in any of these blocks both pathways entirely, unlike a 17α-hydroxylase deficiency where corticosterone synthesis is spared. This is why these deficiencies are life-threatening without hormone replacement.", "incorrectas": {"A": "Corticosterone synthesis itself requires these same shared enzymes, so it cannot compensate; corticosterone only rescues glucocorticoid activity when the block is specifically at 17α-hydroxylase, not at these shared enzymatic steps.", "C": "Both corticosterone and cortisol synthesis depend on these enzymes, so both pathways—not just cortisol—are blocked when any of them is deficient.", "D": "The mechanism is direct enzymatic blockade of steroid synthesis, not a primary failure of ACTH secretion; in fact, cortisol deficiency triggers compensatory ACTH elevation, which is insufficient to overcome the enzymatic block."}}}, {"id": "anking-endocrine-physiology-1386", "fuente": "anking", "tema": 23, "anki": "1462050503572", "q": "Which enzyme is unique to the zona glomerulosa, making it essential specifically for the mineralocorticoid synthesis pathway?", "o": {"A": "17α-hydroxylase", "B": "Cholesterol desmolase", "C": "Aldosterone synthase", "D": "3β-hydroxysteroid dehydrogenase"}, "r": "C", "e": {"correcta": "Aldosterone synthase (CYP11B2) is expressed only in the zona glomerulosa and catalyzes the final steps converting corticosterone to aldosterone, making it the enzyme that defines and restricts mineralocorticoid production to this specific cortical zone.", "incorrectas": {"A": "17α-hydroxylase is expressed in the zona fasciculata and reticularis (not glomerulosa), directing precursors toward cortisol and androgen synthesis rather than aldosterone.", "B": "Cholesterol desmolase is present in all three cortical zones as the shared, rate-limiting first step of steroidogenesis, not unique to the glomerulosa.", "D": "3β-hydroxysteroid dehydrogenase is also present across multiple zones and steroidogenic pathways, not restricted to the zona glomerulosa or aldosterone synthesis alone."}}}, {"id": "anking-endocrine-physiology-1387", "fuente": "anking", "tema": 23, "anki": "1462050515698", "q": "Which enzymes are unique to the zona fasciculata/reticularis, driving the glucocorticoid and androgen synthesis pathways?", "o": {"A": "Aldosterone synthase and 21β-hydroxylase", "B": "17α-hydroxylase and 17,20-lyase", "C": "Cholesterol desmolase and 3β-hydroxysteroid dehydrogenase", "D": "11β-hydroxylase and 21β-hydroxylase"}, "r": "B", "e": {"correcta": "17α-hydroxylase and 17,20-lyase are expressed specifically in the zona fasciculata and zona reticularis (not the glomerulosa), diverting steroid precursors toward cortisol and adrenal androgen (DHEA, androstenedione) synthesis rather than the mineralocorticoid pathway.", "incorrectas": {"A": "Aldosterone synthase is unique to the zona glomerulosa for mineralocorticoid production, the opposite pathway from what is being asked about here; 21β-hydroxylase is present in multiple zones, not unique to fasciculata/reticularis.", "C": "Cholesterol desmolase and 3β-hydroxysteroid dehydrogenase are shared, early-pathway enzymes expressed across all three cortical zones, not specific to fasciculata/reticularis.", "D": "11β-hydroxylase and 21β-hydroxylase are involved in both the corticosterone/aldosterone and cortisol pathways and are not restricted to the fasciculata/reticularis-specific androgen/glucocorticoid branch."}}}, {"id": "anking-endocrine-physiology-1388", "fuente": "anking", "tema": 23, "anki": "1462050538129", "q": "The mineralocorticoids and glucocorticoids (progesterone, deoxycorticosterone, aldosterone, and cortisol) belong to which class of steroids based on carbon number?", "o": {"A": "18-carbon steroids", "B": "19-carbon steroids", "C": "21-carbon steroids", "D": "27-carbon steroids"}, "r": "C", "e": {"correcta": "Mineralocorticoids and glucocorticoids are 21-carbon steroids, retaining the full pregnane-derived carbon skeleton (progesterone, deoxycorticosterone, aldosterone, cortisol), distinguishing them from the shorter carbon-chain sex steroids formed after further enzymatic cleavage.", "incorrectas": {"A": "18-carbon steroids refer to estrogens (e.g., estradiol), which have lost additional carbons via aromatization, not the corticosteroids in question.", "B": "19-carbon steroids refer to androgens (e.g., testosterone, androstenedione), formed after 17,20-lyase removes a two-carbon unit, not the 21-carbon corticosteroids.", "D": "27-carbon steroids describes cholesterol itself, the parent precursor molecule, before side-chain cleavage by cholesterol desmolase produces the 21-carbon pregnenolone-derived hormones."}}}, {"id": "anking-endocrine-physiology-1389", "fuente": "anking", "tema": 23, "anki": "1462051340374", "q": "Cortisol secretion follows which characteristic pattern?", "o": {"A": "Continuous and constant throughout the day", "B": "Pulsatile and diurnal (circadian)", "C": "Strictly seasonal, varying by month", "D": "Triggered only by acute stress, otherwise absent"}, "r": "B", "e": {"correcta": "Cortisol is secreted in a pulsatile manner that also follows a diurnal (circadian) rhythm, driven by the corresponding oscillating pattern of hypothalamic CRH and pituitary ACTH secretion. This diurnal pattern can be disrupted by coma, blindness, or constant light/dark exposure, and aldosterone secretion follows a similar rhythmic pattern.", "incorrectas": {"A": "Cortisol secretion is not constant; it fluctuates in discrete pulses superimposed on a circadian rhythm, peaking before waking and troughing in the evening.", "C": "The rhythm operates on a roughly 24-hour (diurnal) cycle tied to the sleep-wake cycle, not a monthly or seasonal pattern.", "D": "While cortisol secretion increases acutely with stress, baseline secretion is ongoing and rhythmic even without stress; it is not solely stress-dependent."}}}, {"id": "anking-endocrine-physiology-1390", "fuente": "anking", "tema": 23, "anki": "1462053097810", "q": "In a person with a typical morning-wake, night-sleep schedule, cortisol levels are highest just before which event and lowest at which time?", "o": {"A": "Highest before sleep onset, lowest at midday", "B": "Highest before awakening, lowest in the evening", "C": "Highest at midday, lowest before awakening", "D": "Highest in the evening, lowest before awakening"}, "r": "B", "e": {"correcta": "Cortisol follows a circadian rhythm driven by the hypothalamic-pituitary-adrenal axis, peaking in the early morning just before awakening to help mobilize energy stores for the day, and reaching its nadir in the evening, consistent with reduced CRH/ACTH drive at that time.", "incorrectas": {"A": "Cortisol is not highest before sleep onset; that is closer to its lowest point in the evening, opposite to the actual diurnal peak that occurs before waking.", "C": "Cortisol is not highest at midday; levels are already declining from their early-morning peak by midday, and the nadir occurs in the evening, not before awakening.", "D": "This reverses the true pattern; cortisol is lowest, not highest, in the evening, and highest before waking rather than at that time."}}}, {"id": "anking-endocrine-anatomy-1391", "fuente": "anking", "tema": 25, "anki": "1462053126605", "q": "Corticotropin-releasing hormone (CRH) is secreted by neurons of which hypothalamic nucleus?", "o": {"A": "Supraoptic nucleus", "B": "Arcuate nucleus", "C": "Paraventricular nucleus", "D": "Suprachiasmatic nucleus"}, "r": "C", "e": {"correcta": "CRH is secreted by parvocellular neurons of the paraventricular nucleus (PVN) of the hypothalamus and travels via the hypothalamic-hypophyseal portal blood system to stimulate corticotrophs in the anterior pituitary to release ACTH.", "incorrectas": {"A": "The supraoptic nucleus, along with the PVN's magnocellular neurons, primarily produces ADH (vasopressin) and oxytocin destined for the posterior pituitary, not CRH for the anterior pituitary axis.", "B": "The arcuate nucleus is best known for secreting GHRH and dopamine (which inhibits prolactin), not CRH.", "D": "The suprachiasmatic nucleus is the master circadian pacemaker that helps set the timing of hormone rhythms (including cortisol's diurnal pattern) but does not itself secrete CRH."}}}, {"id": "anking-endocrine-physiology-1392", "fuente": "anking", "tema": 23, "anki": "1462053144091", "q": "Through which second messenger does CRH act on corticotrophs in the anterior pituitary to stimulate ACTH secretion?", "o": {"A": "IP3/DAG", "B": "cGMP", "C": "cAMP", "D": "Tyrosine kinase activity"}, "r": "C", "e": {"correcta": "CRH binds a Gs-protein-coupled receptor on corticotrophs, activating adenylate cyclase to raise intracellular cAMP, which stimulates POMC gene transcription and ACTH secretion. This fits the mnemonic 'FLAT ChAMP' for hormones signaling through cAMP (FSH, LH, ACTH, TSH, CRH, hCG, ADH [V2], MSH, PTH, calcitonin).", "incorrectas": {"B": "cGMP is the second messenger for ANP, BNP, and nitric oxide signaling, not for CRH acting on corticotrophs.", "A": "IP3/DAG (Gq-coupled, calcium-based signaling) mediates hormones like GnRH, TRH, and oxytocin, but CRH signals through the Gs/cAMP pathway instead.", "D": "Tyrosine kinase receptor signaling is used by insulin, growth factors, and some cytokines, not by CRH, which uses a Gs-protein-coupled receptor and cAMP."}}}, {"id": "anking-endocrine-physiology-1393", "fuente": "anking", "tema": 23, "anki": "1462053147855", "q": "CRH binds corticotrophs in the anterior pituitary, prompting them to synthesize which precursor protein and secrete which hormone?", "o": {"A": "Synthesize prolactin and secrete oxytocin", "B": "Synthesize POMC and secrete ACTH", "C": "Synthesize TRH and secrete TSH", "D": "Synthesize proopiomelanocortin and secrete GH"}, "r": "B", "e": {"correcta": "CRH stimulates corticotrophs to synthesize proopiomelanocortin (POMC), a large precursor protein that is cleaved into ACTH (and also melanocyte-stimulating hormone and beta-endorphin). The secreted ACTH then travels to the adrenal cortex to stimulate cortisol synthesis.", "incorrectas": {"A": "Prolactin and oxytocin are unrelated hormones from different cell types/glands (lactotrophs and hypothalamic magnocellular neurons/posterior pituitary), not products of the CRH-corticotroph axis.", "C": "TRH acts on thyrotrophs to stimulate TSH release; this is a separate hypothalamic-pituitary axis from the CRH-ACTH-cortisol pathway.", "D": "While POMC is correctly identified as the precursor, its cleavage product secreted by corticotrophs is ACTH, not growth hormone, which is produced by a distinct cell line (somatotrophs) under GHRH control."}}}, {"id": "anking-endocrine-physiology-1394", "fuente": "anking", "tema": 23, "anki": "1462053171660", "q": "ACTH acts on which zone(s) of the adrenal cortex to increase steroid hormone synthesis?", "o": {"A": "Only the zona glomerulosa", "B": "Only the zona fasciculata", "C": "All three zones, though predominantly the zona fasciculata", "D": "Only the zona reticularis"}, "r": "C", "e": {"correcta": "ACTH receptors are present on all three zones of the adrenal cortex, so ACTH stimulates steroidogenesis broadly across the gland, but its predominant trophic and secretory effect is on the zona fasciculata (cortisol production), with lesser direct effects on glomerulosa and reticularis output compared to other regulators (e.g., renin-angiotensin for glomerulosa).", "incorrectas": {"A": "Restricting ACTH's action to the zona glomerulosa is incorrect; aldosterone secretion from the glomerulosa is primarily regulated by the renin-angiotensin system and potassium, with ACTH playing only a minor/permissive role, while ACTH's dominant effect is elsewhere.", "B": "While the zona fasciculata is indeed the primary target, ACTH receptors and trophic effects extend to the zona glomerulosa and reticularis as well, so 'only' the fasciculata is too narrow.", "D": "Restricting the action to the zona reticularis ignores ACTH's predominant and most clinically significant effect on cortisol synthesis in the zona fasciculata."}}}, {"id": "anking-endocrine-physiology-1395", "fuente": "anking", "tema": 23, "anki": "1462053248848", "q": "ACTH increases adrenocortical steroid hormone synthesis primarily by stimulating which enzyme?", "o": {"A": "Aldosterone synthase", "B": "17α-hydroxylase", "C": "Cholesterol desmolase", "D": "21β-hydroxylase"}, "r": "C", "e": {"correcta": "ACTH upregulates cholesterol desmolase (side-chain cleavage enzyme), which converts cholesterol to pregnenolone. Because this is the rate-limiting step of all adrenal steroidogenesis, stimulating it is the key mechanism by which ACTH increases overall hormone output across the cortex.", "incorrectas": {"A": "Aldosterone synthase is specific to the zona glomerulosa's terminal aldosterone synthesis step and is regulated mainly by angiotensin II and potassium, not the primary target of ACTH's stimulatory action.", "B": "17α-hydroxylase directs precursors toward cortisol and androgens in the fasciculata/reticularis, but it is not the rate-limiting enzyme ACTH principally upregulates to drive overall steroidogenesis.", "D": "21β-hydroxylase acts further downstream in both the mineralocorticoid and glucocorticoid pathways, but the primary rate-limiting step ACTH targets is the initial cholesterol-to-pregnenolone conversion."}}}, {"id": "anking-endocrine-physiology-1396", "fuente": "anking", "tema": 23, "anki": "1462053270810", "q": "What long-term effect does ACTH have on its own receptors in the adrenal cortex?", "o": {"A": "Down-regulation, decreasing adrenal sensitivity", "B": "Up-regulation, increasing adrenal sensitivity", "C": "No change in receptor number, only acute signaling changes", "D": "Receptor internalization with permanent loss of responsiveness"}, "r": "B", "e": {"correcta": "With sustained exposure, ACTH up-regulates its own receptors on adrenocortical cells, increasing the gland's sensitivity to subsequent ACTH stimulation. This trophic effect also underlies the adrenal hypertrophy/hyperplasia seen with chronically elevated ACTH.", "incorrectas": {"A": "Down-regulation with decreased sensitivity is the opposite of what actually occurs with chronic ACTH exposure; the adrenal cortex instead becomes more responsive over time.", "C": "ACTH does produce a durable long-term change in receptor expression (up-regulation), not merely transient acute signaling effects without receptor-level change.", "D": "Chronic ACTH exposure does not cause permanent loss of responsiveness; rather it enhances long-term sensitivity via receptor up-regulation and gland hypertrophy."}}}, {"id": "anking-endocrine-physiology-1397", "fuente": "anking", "tema": 23, "anki": "1462053298193", "q": "Chronically elevated ACTH levels produce what structural change in the adrenal cortex?", "o": {"A": "Atrophy of all three zones", "B": "Hypertrophy/hyperplasia of the adrenal cortex", "C": "Selective fibrosis of the zona glomerulosa", "D": "Calcification of the medulla"}, "r": "B", "e": {"correcta": "ACTH is trophic to the adrenal cortex; sustained elevation (e.g., from an ACTH-secreting pituitary adenoma, ectopic ACTH production, or chronic stress states) drives hypertrophy and hyperplasia of cortical cells, enlarging the gland, as seen classically in ACTH-dependent Cushing syndrome.", "incorrectas": {"A": "Atrophy occurs with chronic exogenous glucocorticoid use that suppresses endogenous ACTH, the opposite scenario from chronically elevated ACTH, which instead causes gland growth.", "C": "Fibrosis is not the characteristic response to elevated ACTH; the gland undergoes proliferative hypertrophy/hyperplasia rather than scarring, and this is not zone-selective in the way described.", "D": "Calcification of the medulla is not a recognized consequence of chronic ACTH stimulation; ACTH acts on the cortex, not the medulla, and its trophic effect there is proliferative, not degenerative/calcific."}}}, {"id": "anking-endocrine-physiology-1398", "fuente": "anking", "tema": 23, "anki": "1462053314382", "q": "Through which second messenger does ACTH exert its actions on the adrenal cortex?", "o": {"A": "cAMP", "B": "IP3/DAG", "C": "cGMP", "D": "JAK/STAT"}, "r": "A", "e": {"correcta": "ACTH binds the melanocortin 2 receptor (MC2R), a Gs-protein-coupled receptor on adrenocortical cells, activating adenylate cyclase and raising cAMP, which in turn activates protein kinase A to stimulate cholesterol desmolase and downstream steroidogenic enzymes. This fits the 'FLAT ChAMP' mnemonic of cAMP-signaling hormones.", "incorrectas": {"B": "IP3/DAG signaling (Gq-coupled) is used by hormones like GnRH, TRH, and angiotensin II (AT1 receptor), not by ACTH acting on the adrenal cortex.", "C": "cGMP mediates natriuretic peptide and nitric oxide signaling, unrelated to the ACTH-MC2R-adenylate cyclase pathway.", "D": "JAK/STAT signaling is used by cytokine and growth hormone/prolactin receptors, not by the Gs-coupled ACTH receptor."}}}, {"id": "anking-endocrine-physiology-1399", "fuente": "anking", "tema": 23, "anki": "1462053317785", "q": "How does cortisol regulate CRH secretion from the hypothalamus?", "o": {"A": "It has no effect on CRH secretion", "B": "It inhibits CRH secretion, both directly and indirectly", "C": "It stimulates CRH secretion via positive feedback", "D": "It inhibits CRH only indirectly via the adrenal medulla"}, "r": "B", "e": {"correcta": "Cortisol exerts negative feedback on the hypothalamus, inhibiting CRH secretion both directly on the paraventricular nucleus and indirectly by acting on hippocampal neurons that synapse onto and modulate hypothalamic CRH neurons, completing the classic HPA axis feedback loop.", "incorrectas": {"A": "Cortisol clearly modulates CRH secretion through negative feedback; claiming no effect ignores the fundamental regulatory loop of the HPA axis.", "C": "Cortisol provides negative, not positive, feedback; positive feedback would create an unchecked, runaway cortisol response rather than the tightly controlled homeostatic system that actually exists.", "D": "The indirect inhibitory pathway involves hippocampal neurons acting on the hypothalamus, not the adrenal medulla, which is unrelated to CRH regulation."}}}, {"id": "anking-endocrine-physiology-1400", "fuente": "anking", "tema": 23, "anki": "1462053331431", "q": "How does cortisol regulate ACTH secretion from the anterior pituitary?", "o": {"A": "Stimulates secretion directly", "B": "Inhibits secretion directly", "C": "Has no direct effect, acts only via the hypothalamus", "D": "Inhibits secretion only during stress"}, "r": "B", "e": {"correcta": "Cortisol acts directly on anterior pituitary corticotrophs to inhibit ACTH secretion, forming a short negative-feedback loop in addition to its longer-loop inhibitory effect on hypothalamic CRH, together keeping circulating cortisol within a controlled range.", "incorrectas": {"A": "Cortisol suppresses, rather than stimulates, ACTH secretion; stimulation would produce unchecked positive feedback rather than the homeostatic negative feedback that characterizes the HPA axis.", "C": "Cortisol has a well-established direct inhibitory effect on the pituitary corticotroph itself, in addition to its indirect hypothalamic effects, so it is not limited to an indirect route.", "D": "This direct inhibitory feedback on the pituitary operates continuously as part of normal physiologic regulation, not only during acute stress states."}}}, {"id": "anking-endocrine-physiology-1401", "fuente": "anking", "tema": 23, "anki": "1462053341905", "q": "Chronically elevated cortisol (glucocorticoid excess) leads to decreased levels of which two upstream hormones via negative feedback?", "o": {"A": "TRH and TSH", "B": "GnRH and LH", "C": "CRH and ACTH", "D": "GHRH and growth hormone"}, "r": "C", "e": {"correcta": "Excess circulating cortisol suppresses hypothalamic CRH and pituitary ACTH secretion through negative feedback on both levels of the HPA axis. This is the physiologic basis for adrenal atrophy seen with chronic exogenous steroid use, since the native ACTH drive to the adrenal cortex is suppressed.", "incorrectas": {"A": "TRH and TSH are part of the hypothalamic-pituitary-thyroid axis, regulated by thyroid hormone feedback, not directly suppressed as the primary feedback target of cortisol excess.", "B": "GnRH and LH belong to the reproductive axis; while cortisol excess can have some suppressive crosstalk effects on reproductive hormones, the primary, direct negative feedback loop of cortisol is on CRH and ACTH.", "D": "GHRH and growth hormone are part of a separate somatotropic axis; cortisol's principal negative feedback target is the HPA axis (CRH/ACTH), not the GH axis."}}}, {"id": "anking-endocrine-pathology-1402", "fuente": "anking", "tema": 5, "anki": "1462053424992", "q": "In a normal (non-Cushingoid) patient, what is the expected result of a low-dose dexamethasone suppression test?", "o": {"A": "Low-dose dexamethasone fails to suppress cortisol secretion", "B": "Low-dose dexamethasone inhibits ACTH secretion and consequently cortisol secretion", "C": "Low-dose dexamethasone paradoxically increases ACTH secretion", "D": "The test has no effect regardless of dose in normal individuals"}, "r": "B", "e": {"correcta": "In a normal individual, the intact negative feedback loop means even a low dose of the potent synthetic glucocorticoid dexamethasone suppresses hypothalamic CRH and pituitary ACTH secretion, which in turn lowers endogenous cortisol production, confirming a normally functioning HPA axis.", "incorrectas": {"A": "Failure of low-dose suppression is the abnormal finding seen in Cushing syndrome (whether pituitary, adrenal, or ectopic), not in a normal patient with an intact feedback loop.", "C": "Dexamethasone acts to inhibit, not paradoxically increase, ACTH secretion via negative feedback in normal physiology; a paradoxical increase would be an atypical/abnormal response.", "D": "A normal patient does respond to even low-dose dexamethasone with suppression of cortisol; claiming no effect regardless of dose is incorrect and would actually suggest pathology (like an autonomous cortisol-secreting process)."}}}, {"id": "anking-endocrine-pathology-1403", "fuente": "anking", "tema": 5, "anki": "1462053437992", "q": "A patient with Cushing syndrome due to an ACTH-secreting pituitary adenoma undergoes a dexamethasone suppression test. What result is expected?", "o": {"A": "Neither low nor high dose suppresses cortisol secretion", "B": "Low dose suppresses cortisol, but high dose does not", "C": "Low dose does not suppress cortisol secretion, but high dose does", "D": "Both low and high dose suppress cortisol normally"}, "r": "C", "e": {"correcta": "A pituitary corticotroph adenoma has reduced, but not absent, sensitivity to negative feedback: low-dose dexamethasone fails to suppress ACTH/cortisol, but a high enough dose can still override the tumor's relatively preserved (though blunted) feedback responsiveness, suppressing cortisol. This pattern helps localize Cushing disease to the pituitary rather than an adrenal or ectopic source.", "incorrectas": {"A": "Failure to suppress at both low and high doses is characteristic of an ectopic ACTH-secreting tumor or an autonomous adrenal tumor, which typically show completely absent feedback responsiveness, unlike the pituitary adenoma which retains some sensitivity at higher doses.", "B": "This describes the normal-patient pattern (suppression even at low dose), the opposite of what happens with a pituitary adenoma, which requires a higher dose to achieve suppression.", "D": "A pituitary corticotroph adenoma does not suppress normally at low dose; only the higher dose overcomes its partially preserved but blunted feedback sensitivity."}}}, {"id": "anking-endocrine-pathology-1404", "fuente": "anking", "tema": 5, "anki": "1462053455853", "q": "A patient with Cushing syndrome caused by a cortisol-secreting adrenal cortical tumor undergoes a dexamethasone suppression test. What result is expected?", "o": {"A": "Low dose suppresses cortisol, but high dose does not", "B": "Both low and high dose suppress cortisol secretion", "C": "Neither low nor high dose dexamethasone suppresses cortisol secretion", "D": "Only high-dose dexamethasone suppresses cortisol secretion"}, "r": "C", "e": {"correcta": "An autonomous adrenal cortical tumor secretes cortisol independently of pituitary ACTH regulation, so it is entirely unresponsive to negative feedback from exogenous glucocorticoid—neither low- nor high-dose dexamethasone suppresses cortisol secretion, and ACTH itself is typically already suppressed by the tumor's autonomous cortisol output.", "incorrectas": {"A": "This pattern (suppression at low dose) describes a normal HPA axis response, not the autonomous, feedback-independent secretion characteristic of an adrenal tumor.", "B": "Suppression at both doses would indicate an intact, feedback-responsive HPA axis, which is not the case with an autonomously functioning adrenal tumor that operates independently of ACTH regulation.", "D": "Even high-dose dexamethasone fails to suppress cortisol in this scenario, unlike a pituitary adenoma (which can be suppressed by a high enough dose); the adrenal tumor is entirely autonomous and unresponsive to feedback at any dose."}}}, {"id": "anking-endocrine-physiology-1405", "fuente": "anking", "tema": 23, "anki": "1462053479653", "q": "What is the effect of somatostatin and opioids on ACTH secretion from the anterior pituitary?", "o": {"A": "Increased", "B": "No effect", "C": "Decreased", "D": "Biphasic (initial increase then decrease)"}, "r": "C", "e": {"correcta": "Somatostatin and opioids inhibit corticotroph function and suppress ACTH secretion, similar to their inhibitory effects on other anterior pituitary axes (e.g., somatostatin suppresses GH and TSH). This is part of the broader inhibitory tone these substances exert on hypothalamic-pituitary hormone release.", "incorrectas": {"A": "An increase would be expected from CRH, stress, or hypoglycemia, which stimulate ACTH release, not from somatostatin or opioids, which are inhibitory signals.", "B": "Somatostatin and opioids are not neutral bystanders in pituitary regulation; they actively suppress hormone secretion at multiple axes, including corticotropes producing ACTH.", "D": "There is no described biphasic pattern for somatostatin/opioid effects on ACTH; the consistent physiologic effect is a straightforward decrease in secretion."}}}, {"id": "anking-endocrine-physiology-1406", "fuente": "anking", "tema": 23, "anki": "1462061124035", "q": "Glucocorticoids increase which process in skeletal muscle, providing amino acids to the liver for gluconeogenesis?", "o": {"A": "Protein catabolism (proteolysis)", "B": "Glycogen synthesis", "C": "Glucose uptake via GLUT4", "D": "Lipoprotein lipase activity"}, "r": "A", "e": {"correcta": "Glucocorticoids promote muscle protein breakdown (proteolysis) while simultaneously inhibiting protein synthesis, releasing amino acids that travel to the liver to serve as substrates for gluconeogenesis. This catabolic muscle-wasting effect contributes to the proximal muscle weakness seen in Cushing syndrome.", "incorrectas": {"B": "Glycogen synthesis in muscle is not the process glucocorticoids upregulate to fuel gluconeogenesis; glucocorticoids actually promote hepatic glycogen storage while breaking down muscle protein, not glycogen, for fuel.", "C": "Glucocorticoids decrease, not increase, GLUT4-mediated glucose uptake in peripheral tissues, contributing to their diabetogenic, insulin-antagonizing effect rather than supplying gluconeogenic substrate.", "D": "Lipoprotein lipase activity relates to triglyceride clearance from circulation, not to the amino acid supply used for gluconeogenesis from muscle breakdown."}}}, {"id": "anking-endocrine-physiology-1407", "fuente": "anking", "tema": 23, "anki": "1462061140097", "q": "What effect do glucocorticoids have on peripheral glucose utilization and adipose tissue insulin sensitivity?", "o": {"A": "Increase glucose utilization and increase insulin sensitivity", "B": "Decrease glucose utilization and decrease insulin sensitivity", "C": "Increase glucose utilization and decrease insulin sensitivity", "D": "No change in either parameter"}, "r": "B", "e": {"correcta": "Glucocorticoids decrease peripheral tissue glucose utilization and decrease insulin sensitivity of adipose tissue, contributing to their diabetogenic effect. This combination raises blood glucose by reducing peripheral glucose disposal while the liver simultaneously increases gluconeogenesis.", "incorrectas": {"A": "This is the opposite of the actual effect; glucocorticoids are catabolic, anti-insulin hormones that raise blood glucose rather than enhance its cellular uptake and utilization.", "C": "While the insulin sensitivity portion is correct, glucocorticoids decrease rather than increase peripheral glucose utilization, both effects working in the same hyperglycemic direction.", "D": "Glucocorticoids have well-established, clinically significant effects on glucose metabolism (steroid-induced hyperglycemia/diabetes), not a neutral effect on these parameters."}}}, {"id": "anking-endocrine-physiology-1408", "fuente": "anking", "tema": 23, "anki": "1462061153036", "q": "How do glucocorticoids affect insulin resistance, and by what mechanism?", "o": {"A": "Decrease insulin resistance by increasing adipose insulin sensitivity", "B": "Increase insulin resistance by decreasing adipose tissue insulin sensitivity", "C": "No effect on insulin resistance", "D": "Increase insulin resistance by directly destroying pancreatic beta cells"}, "r": "B", "e": {"correcta": "Glucocorticoids increase insulin resistance by decreasing the sensitivity of adipose tissue to insulin, part of their overall diabetogenic, hyperglycemic action. This is why exogenous steroid use or endogenous excess (Cushing syndrome) commonly precipitates or worsens hyperglycemia and steroid-induced diabetes.", "incorrectas": {"A": "This is the reverse of the true relationship; glucocorticoids impair rather than improve adipose tissue's response to insulin, worsening glucose control.", "C": "Glucocorticoid excess is a well-recognized cause of secondary insulin resistance and hyperglycemia, making a claim of no effect incorrect.", "D": "Glucocorticoids act by antagonizing insulin's peripheral effects and promoting gluconeogenesis, not by cytotoxic destruction of pancreatic beta cells, which is more characteristic of autoimmune processes in type 1 diabetes."}}}, {"id": "anking-endocrine-physiology-1409", "fuente": "anking", "tema": 23, "anki": "1462061159065", "q": "Glucocorticoids increase peripheral lipolysis, which supplies the liver with more of which substrate for gluconeogenesis?", "o": {"A": "Free fatty acids", "B": "Glycerol", "C": "Alanine", "D": "Lactate"}, "r": "B", "e": {"correcta": "Glucocorticoid-induced peripheral lipolysis breaks down triglycerides into glycerol and free fatty acids; the glycerol backbone is a direct gluconeogenic substrate that the liver converts to glucose. This is one of several ways glucocorticoids raise blood glucose alongside proteolysis-derived amino acids.", "incorrectas": {"A": "Free fatty acids released by lipolysis are primarily used for hepatic ketogenesis and as an alternative fuel source for peripheral tissues, but they are not themselves converted into glucose via gluconeogenesis.", "C": "Alanine is an important gluconeogenic substrate, but it comes from muscle protein catabolism (via the glucose-alanine cycle), not from lipolysis of adipose tissue.", "D": "Lactate is a gluconeogenic substrate generated by anaerobic glycolysis in muscle and red blood cells (Cori cycle), not a product of adipose tissue lipolysis."}}}, {"id": "anking-endocrine-physiology-1410", "fuente": "anking", "tema": 23, "anki": "1462061181462", "q": "In hypocortisolism, decreased levels of which hepatic process lead to hypoglycemia?", "o": {"A": "Glycogenolysis", "B": "Glycolysis", "C": "Gluconeogenesis", "D": "Lipogenesis"}, "r": "C", "e": {"correcta": "Cortisol normally stimulates hepatic gluconeogenesis; in states of hypocortisolism (e.g., Addison disease), reduced gluconeogenesis leads to inadequate glucose production and consequent hypoglycemia. The reverse (hypercortisolism) increases gluconeogenesis and contributes to hyperglycemia.", "incorrectas": {"A": "Glycogenolysis is primarily regulated by glucagon and epinephrine acutely, not the chronic permissive gluconeogenic action of cortisol that is emphasized in adrenal insufficiency.", "B": "Glycolysis is the breakdown of glucose for energy, the opposite direction of glucose production; a decrease in glycolysis would not directly explain hypoglycemia from cortisol deficiency.", "D": "Lipogenesis is fat synthesis and is not the pathway cortisol drives to maintain blood glucose; cortisol's key glucose-related action is stimulating gluconeogenesis, not lipogenesis."}}}, {"id": "anking-endocrine-physiology-1411", "fuente": "anking", "tema": 23, "anki": "1462061261772", "q": "What effect do glucocorticoids have on blood neutrophil count, and by what mechanism?", "o": {"A": "Decreased neutrophils due to increased apoptosis", "B": "Increased neutrophils (neutrophilia) due to decreased WBC adhesion", "C": "No change in neutrophil count", "D": "Increased neutrophils due to increased bone marrow production only"}, "r": "B", "e": {"correcta": "Glucocorticoids cause neutrophilia by decreasing neutrophil adhesion to vascular endothelium, which demarginates neutrophils from the vessel wall into the circulating pool and reduces their migration into tissue. This explains why steroid use raises the WBC count even though it is immunosuppressive, since neutrophil function and mobilization into infected tissue are actually impaired.", "incorrectas": {"A": "Glucocorticoids increase, not decrease, circulating neutrophil counts; apoptosis induction by glucocorticoids is a mechanism more relevant to lymphocytes and eosinophils, not the mechanism behind neutrophilia.", "C": "Glucocorticoid-induced neutrophilia is a well-documented and clinically useful finding (e.g., distinguishing steroid effect from infection on a CBC), so no change is incorrect.", "D": "The primary mechanism is redistribution (demargination) of the existing neutrophil pool from vessel walls into circulation, not new bone marrow production, which is a slower process."}}}, {"id": "anking-endocrine-physiology-1412", "fuente": "anking", "tema": 23, "anki": "1462061271080", "q": "What effect do glucocorticoids have on circulating eosinophil counts?", "o": {"A": "Increase", "B": "Decrease", "C": "No effect", "D": "Initial decrease followed by rebound increase"}, "r": "B", "e": {"correcta": "Glucocorticoids decrease circulating eosinophils (as well as basophils and lymphocytes) by sequestering them in tissue and promoting apoptosis, in contrast to their effect on neutrophils, which they increase via demargination. This differential white cell effect is a classic feature tested alongside glucocorticoid-induced neutrophilia.", "incorrectas": {"A": "An increase describes the effect on neutrophils, not eosinophils; glucocorticoids move in opposite directions for these two cell types, which is a key distinction to remember.", "C": "Glucocorticoids reliably lower eosinophil counts, a mechanism therapeutically exploited in treating eosinophilic conditions like severe asthma or eosinophilic esophagitis.", "D": "There is no described rebound increase phase; the sustained effect of glucocorticoids on eosinophils is a straightforward decrease."}}}, {"id": "anking-endocrine-physiology-1413", "fuente": "anking", "tema": 23, "anki": "1462061287878", "q": "By what mechanism do glucocorticoids suppress the immune response, allowing their pharmacologic use in preventing transplant rejection?", "o": {"A": "By inhibiting production of IL-2 and subsequent T-cell proliferation", "B": "By directly lysing mature B lymphocytes", "C": "By blocking MHC class I expression on all nucleated cells", "D": "By inhibiting complement fixation on antibody-coated cells"}, "r": "A", "e": {"correcta": "Glucocorticoids suppress the immune response largely by inhibiting IL-2 gene transcription in T cells, which blocks the autocrine/paracrine signal needed for T-cell proliferation and clonal expansion. This is why pharmacologic-dose glucocorticoids are used clinically to prevent rejection of transplanted organs and to treat autoimmune and inflammatory conditions.", "incorrectas": {"B": "Glucocorticoids can induce apoptosis in some lymphocyte populations, but their principal immunosuppressive mechanism relevant to transplant rejection is blocking IL-2-driven T-cell proliferation, not direct B-cell lysis (which is more characteristic of drugs like rituximab).", "C": "Glucocorticoids do not act by suppressing MHC class I expression; this mechanism is more associated with certain viral immune evasion strategies or specific tumor behaviors, not standard corticosteroid immunosuppression.", "D": "Complement-mediated cytotoxicity is a humoral immune effector mechanism; glucocorticoid immunosuppression is centered on cellular immunity via IL-2 and T-cell proliferation, not complement fixation."}}}, {"id": "anking-endocrine-physiology-1414", "fuente": "anking", "tema": 23, "anki": "1462061322698", "q": "Glucocorticoids are essential in maintaining vascular responsiveness to catecholamines via upregulation of which receptor on arterioles?", "o": {"A": "β2 receptors", "B": "α1 receptors", "C": "M3 muscarinic receptors", "D": "AT1 angiotensin receptors"}, "r": "B", "e": {"correcta": "Cortisol upregulates α1 adrenergic receptors on arteriolar smooth muscle, maintaining the vasoconstrictive responsiveness of blood vessels to circulating catecholamines like norepinephrine and epinephrine. This permissive effect is why cortisol deficiency (as in adrenal insufficiency) leads to impaired vasoconstriction and hypotension.", "incorrectas": {"A": "β2 receptors mediate vasodilation and bronchodilation in response to catecholamines; upregulating them would oppose, not support, vascular tone maintenance, so this is not the receptor cortisol permissively upregulates for vasoconstriction.", "C": "M3 muscarinic receptors respond to acetylcholine, not catecholamines, and mediate parasympathetic effects like vasodilation via endothelial nitric oxide, unrelated to cortisol's permissive vascular action.", "D": "AT1 receptors are the target of angiotensin II in the renin-angiotensin-aldosterone system; while both pathways contribute to vascular tone, the specific receptor cortisol upregulates for catecholamine responsiveness is α1, not AT1."}}}, {"id": "anking-endocrine-physiology-1415", "fuente": "anking", "tema": 23, "anki": "1462061338886", "q": "What is the effect of hypocortisolism (e.g., Addison disease) on blood pressure, and why does this occur?", "o": {"A": "Increased blood pressure due to increased aldosterone", "B": "Decreased blood pressure due to decreased α1 receptor expression and vasoconstriction", "C": "No significant change in blood pressure", "D": "Increased blood pressure due to catecholamine excess"}, "r": "B", "e": {"correcta": "In hypocortisolism, decreased cortisol leads to decreased expression of vascular α1 receptors, reducing the vasculature's responsiveness to catecholamines and causing decreased vasoconstriction and hypotension. This permissive vascular effect of cortisol is a key reason patients with adrenal insufficiency can present with hypotension, sometimes progressing to adrenal crisis with vascular collapse.", "incorrectas": {"A": "In primary adrenal insufficiency (Addison disease), aldosterone is typically also decreased (not increased) since the entire adrenal cortex is affected, contributing further to hypotension via salt wasting rather than counteracting it.", "C": "Hypotension is a clinically significant and expected finding in adrenal insufficiency, not an absent or negligible effect, and can be life-threatening in acute adrenal crisis.", "D": "Cortisol deficiency does not cause catecholamine excess; rather it blunts the vascular response to whatever catecholamines are present, so the net effect is hypotension, not hypertension from excess catecholamines."}}}, {"id": "anking-endocrine-physiology-1416", "fuente": "anking", "tema": 23, "anki": "1462061434545", "q": "Glucocorticoid excess decreases fibroblast activity, contributing to which clinical finding?", "o": {"A": "Hypertrophic scarring", "B": "Striae (stretch marks)", "C": "Keloid formation", "D": "Increased wound tensile strength"}, "r": "B", "e": {"correcta": "Glucocorticoids decrease fibroblast activity and collagen synthesis, weakening the dermis and connective tissue, which manifests clinically as striae (purple stretch marks), thin skin, easy bruising, and poor wound healing seen in Cushing syndrome.", "incorrectas": {"A": "Hypertrophic scarring results from excessive collagen deposition during wound healing, the opposite of the decreased collagen synthesis caused by glucocorticoid excess.", "C": "Keloids also arise from exaggerated fibroblastic collagen production extending beyond the wound margin, which is inconsistent with the collagen-suppressing effect of glucocorticoids.", "D": "Glucocorticoids impair wound healing and reduce tensile strength of healing tissue due to decreased fibroblast and collagen activity, which is why steroid use is a recognized risk factor for wound dehiscence."}}}, {"id": "anking-endocrine-physiology-1417", "fuente": "anking", "tema": 23, "anki": "1462061444174", "q": "What effect does cortisol have on glomerular filtration rate (GFR)?", "o": {"A": "Decreased GFR", "B": "Increased GFR", "C": "No effect on GFR", "D": "Variable effect depending on time of day"}, "r": "B", "e": {"correcta": "Cortisol increases glomerular filtration rate, an effect thought to relate to its permissive actions on renal blood flow and vascular tone. This is a less commonly tested but recognized physiologic action of cortisol on the kidney.", "incorrectas": {"A": "A decrease in GFR would be more consistent with conditions of renal hypoperfusion or vasoconstriction of the afferent arteriole, not the known effect of cortisol, which increases GFR.", "C": "Cortisol does have a measurable physiologic effect on renal function, increasing GFR, so a claim of no effect is inaccurate.", "D": "There is no established circadian variability specifically attributed to cortisol's GFR effect in the standard physiology teaching; the effect is simply an increase in GFR."}}}, {"id": "anking-endocrine-physiology-1418", "fuente": "anking", "tema": 23, "anki": "1462061449471", "q": "Cortisol affects sleep architecture by decreasing which sleep stage while increasing total awake time?", "o": {"A": "Stage 3/4 (slow-wave) sleep", "B": "REM sleep", "C": "Stage 1 sleep", "D": "Stage 2 sleep"}, "r": "B", "e": {"correcta": "Cortisol decreases REM sleep and increases awake time, consistent with its role as a stress hormone that promotes arousal and alertness. This effect helps explain sleep disturbances seen with cortisol excess, such as in Cushing syndrome or during periods of high stress.", "incorrectas": {"A": "Slow-wave sleep is more classically linked to growth hormone secretion (which peaks during this stage) rather than being the specific stage that cortisol is described as suppressing.", "C": "Stage 1 sleep is a light transitional sleep stage and is not the stage specifically identified as being decreased by cortisol in this physiologic relationship.", "D": "Stage 2 sleep, characterized by sleep spindles and K-complexes, is not the sleep stage classically described as being reduced by cortisol; the specific effect taught is on REM sleep."}}}, {"id": "anking-endocrine-physiology-1419", "fuente": "anking", "tema": 23, "anki": "1462061455299", "q": "Cortisol travels in the blood primarily bound to which transport protein?", "o": {"A": "Albumin exclusively", "B": "Corticosteroid-binding globulin (CBG, transcortin)", "C": "Thyroxine-binding globulin (TBG)", "D": "Sex hormone-binding globulin (SHBG)"}, "r": "B", "e": {"correcta": "Cortisol circulates in the blood mostly bound to corticosteroid-binding globulin (CBG, also called transcortin), a liver-produced carrier protein with high affinity for cortisol, with a smaller fraction bound to albumin and only a small free fraction being biologically active. This protein-binding buffers cortisol levels and prolongs its half-life.", "incorrectas": {"A": "Albumin does bind a portion of circulating cortisol as a lower-affinity, higher-capacity carrier, but the primary, specific, high-affinity binding protein for cortisol is CBG, not albumin alone.", "C": "Thyroxine-binding globulin is the specific carrier protein for thyroid hormones (T4 and T3), not for cortisol, though both are hepatically synthesized binding globulins.", "D": "Sex hormone-binding globulin transports testosterone and estradiol in the blood, not cortisol, which has its own dedicated carrier, CBG."}}}, {"id": "anking-endocrine-physiology-1420", "fuente": "anking", "tema": 23, "anki": "1462061471530", "q": "At high concentrations, cortisol can cross-react with and bind which receptor, producing mineralocorticoid-like effects?", "o": {"A": "Glucocorticoid receptor only", "B": "Mineralocorticoid (aldosterone) receptor", "C": "Androgen receptor", "D": "Estrogen receptor"}, "r": "B", "e": {"correcta": "Cortisol has high affinity for the mineralocorticoid receptor and, at high concentrations, can bind and activate it, producing aldosterone-like effects such as sodium retention and potassium wasting. Normally this is prevented because the renal enzyme 11β-hydroxysteroid dehydrogenase type 2 converts cortisol to inactive cortisone in mineralocorticoid target tissues, but when this enzyme is overwhelmed or deficient, cortisol exerts unopposed mineralocorticoid activity (as seen in apparent mineralocorticoid excess or with very high cortisol states like ectopic ACTH syndrome).", "incorrectas": {"A": "Cortisol's action through its own glucocorticoid receptor is its primary, expected function; the notable and testable point here is its additional, more unusual cross-reactivity with the mineralocorticoid receptor at high levels.", "C": "The androgen receptor binds testosterone and dihydrotestosterone; cortisol does not exert clinically significant cross-reactivity at this receptor, unlike its known cross-talk with the mineralocorticoid receptor.", "D": "The estrogen receptor is not a target of cortisol cross-reactivity; the clinically relevant crossover described for high-concentration cortisol is specifically with the mineralocorticoid receptor."}}}, {"id": "anking-endocrine-physiology-1421", "fuente": "anking", "tema": 23, "anki": "1462061881729", "q": "In adrenogenital syndrome (congenital adrenal hyperplasia), overproduction of adrenal androgens results in increased urinary levels of which metabolites?", "o": {"A": "Vanillylmandelic acid (VMA)", "B": "17-ketosteroids", "C": "Metanephrines", "D": "5-HIAA"}, "r": "B", "e": {"correcta": "Excess adrenal androgen production in congenital adrenal hyperplasia (adrenogenital syndrome) increases urinary excretion of 17-ketosteroids, which are breakdown products of androgens (and some other adrenal steroids). Measuring urinary 17-ketosteroids historically helped assess adrenal androgen output in these patients.", "incorrectas": {"A": "Vanillylmandelic acid is a breakdown product of catecholamines (epinephrine/norepinephrine), used to screen for pheochromocytoma, not a marker of adrenal androgen excess.", "C": "Metanephrines are also catecholamine metabolites used in pheochromocytoma workup, unrelated to the androgen overproduction seen in congenital adrenal hyperplasia.", "D": "5-HIAA is the metabolite of serotonin, elevated in carcinoid syndrome, and has no relationship to adrenal androgen excess or congenital adrenal hyperplasia."}}}, {"id": "anking-endocrine-pathology-1422", "fuente": "anking", "tema": 5, "anki": "1462066580065", "q": "Which classes of adrenal steroid hormones are decreased in primary adrenal insufficiency (Addison disease)?", "o": {"A": "Glucocorticoids only", "B": "Mineralocorticoids only", "C": "All three classes: glucocorticoids, mineralocorticoids, and androgens", "D": "Glucocorticoids and androgens only, sparing mineralocorticoids"}, "r": "C", "e": {"correcta": "Addison disease results from destruction or dysfunction of the entire adrenal cortex, so all three classes of adrenal steroids—glucocorticoids (cortisol), mineralocorticoids (aldosterone), and androgens—are decreased. This distinguishes it from secondary/tertiary adrenal insufficiency, where the pituitary/hypothalamic defect spares aldosterone production since that is largely regulated by the renin-angiotensin system rather than ACTH.", "incorrectas": {"A": "Glucocorticoid deficiency alone would not account for the hyperkalemia, hyponatremia, and hypotension seen in Addison disease, which also require concurrent mineralocorticoid deficiency.", "B": "Isolated mineralocorticoid deficiency does not explain the hypoglycemia and stress intolerance seen in Addison disease, which require concurrent glucocorticoid deficiency as well.", "D": "This pattern (sparing mineralocorticoids) actually describes secondary adrenal insufficiency, not primary Addison disease, where the entire cortex including the zona glomerulosa (aldosterone-producing layer) is affected."}}}, {"id": "anking-endocrine-pathology-1423", "fuente": "anking", "tema": 5, "anki": "1462066592419", "q": "What happens to ACTH levels in Addison disease, and why?", "o": {"A": "Decreased, because the pituitary is destroyed along with the adrenal gland", "B": "Increased, because low cortisol removes negative feedback on the pituitary/hypothalamus", "C": "Normal, because ACTH is independent of cortisol feedback", "D": "Decreased, because ACTH is co-secreted with cortisol from the adrenal cortex"}, "r": "B", "e": {"correcta": "In Addison disease (primary adrenal insufficiency), the adrenal cortex itself fails, so cortisol levels fall; this removes the normal negative feedback cortisol exerts on the hypothalamus and pituitary, causing compensatory elevation of CRH and ACTH. The elevated ACTH (which shares a precursor, POMC, with melanocyte-stimulating hormone) also explains the hyperpigmentation seen in Addison disease.", "incorrectas": {"A": "The pituitary is intact in primary adrenal insufficiency; the defect is in the adrenal gland itself, so the pituitary actually responds appropriately by increasing ACTH output in an attempt to stimulate the failing adrenal cortex.", "C": "ACTH secretion is tightly regulated by cortisol negative feedback via the hypothalamic-pituitary-adrenal axis; it is not independent of cortisol levels.", "D": "ACTH is produced by the anterior pituitary, not by the adrenal cortex, so it is not co-secreted with cortisol; instead it is the upstream signal that stimulates cortisol production from the adrenal gland."}}}, {"id": "anking-endocrine-pathology-1424", "fuente": "anking", "tema": 5, "anki": "1462066599407", "q": "What effect does Addison disease have on blood glucose levels?", "o": {"A": "Hyperglycemia", "B": "Hypoglycemia", "C": "No change in glucose homeostasis", "D": "Alternating hyper- and hypoglycemia"}, "r": "B", "e": {"correcta": "Addison disease causes hypoglycemia because the deficient cortisol fails to stimulate adequate hepatic gluconeogenesis and normally opposes insulin action; without this glucose-raising influence, blood sugar tends to fall. Patients may also present with nausea, weight loss, weakness, and hypotension as part of the broader clinical picture of adrenal insufficiency.", "incorrectas": {"A": "Hyperglycemia is the expected finding in cortisol excess states (Cushing syndrome), the opposite scenario from adrenal insufficiency, where cortisol's glucose-raising, insulin-antagonizing effects are lost.", "C": "Cortisol plays a significant permissive role in glucose homeostasis (via gluconeogenesis and insulin antagonism), so its deficiency has a clinically meaningful hypoglycemic effect, not a neutral one.", "D": "Addison disease produces a sustained tendency toward hypoglycemia rather than an alternating or labile glucose pattern."}}}, {"id": "anking-endocrine-pathology-1425", "fuente": "anking", "tema": 5, "anki": "1462066630531", "q": "Which electrolyte abnormality is a clinical feature of Addison disease, and why does it occur?", "o": {"A": "Hypokalemia due to increased aldosterone", "B": "Hyperkalemia due to decreased aldosterone levels", "C": "Hypercalcemia due to decreased PTH", "D": "Hyponatremia due to increased ADH secretion only"}, "r": "B", "e": {"correcta": "Addison disease causes hyperkalemia because decreased aldosterone impairs the normal renal exchange of sodium reabsorption for potassium and hydrogen ion secretion in the collecting duct, leading to potassium retention. This aldosterone deficiency also causes sodium wasting (hyponatremia) and volume depletion (hypotension), forming the classic biochemical triad of primary adrenal insufficiency along with hyperkalemia.", "incorrectas": {"A": "Hypokalemia with increased aldosterone describes hyperaldosteronism (e.g., Conn syndrome), essentially the opposite hormonal and electrolyte picture from Addison disease.", "C": "Calcium and PTH regulation are not primarily governed by the adrenal cortex; hypercalcemia is not a characteristic feature of Addison disease, which instead centers on sodium and potassium derangements from aldosterone loss.", "D": "While hyponatremia does occur in Addison disease, it results predominantly from aldosterone deficiency (impaired sodium reabsorption) rather than from an isolated ADH-driven mechanism."}}}, {"id": "anking-endocrine-pathology-1426", "fuente": "anking", "tema": 5, "anki": "1462066673891", "q": "What is the appropriate treatment for Addison disease (primary adrenocortical insufficiency)?", "o": {"A": "Glucocorticoid replacement only", "B": "Mineralocorticoid replacement only", "C": "Replacement of both glucocorticoids and mineralocorticoids", "D": "ACTH analog therapy alone"}, "r": "C", "e": {"correcta": "Because primary adrenal insufficiency involves loss of the entire adrenal cortex, treatment requires replacement of both glucocorticoids (e.g., hydrocortisone) and mineralocorticoids (e.g., fludrocortisone) to correct both the cortisol and aldosterone deficits and their associated metabolic and electrolyte abnormalities.", "incorrectas": {"A": "Glucocorticoid replacement alone would correct hypoglycemia and stress-response deficits but would leave the mineralocorticoid deficiency untreated, so hyperkalemia, hyponatremia, and hypotension from aldosterone loss would persist.", "B": "Mineralocorticoid replacement alone would address the electrolyte and volume derangements but would leave the patient without adequate cortisol for stress response and glucose homeostasis, risking adrenal crisis.", "D": "Giving ACTH would be ineffective in primary adrenal insufficiency because the problem lies in the adrenal gland's inability to respond to ACTH (the gland itself is destroyed), not in insufficient pituitary stimulation."}}}, {"id": "anking-endocrine-pathology-1427", "fuente": "anking", "tema": 5, "anki": "1462066714314", "q": "In secondary adrenocortical insufficiency, which classes of adrenal steroid hormones are decreased?", "o": {"A": "Mineralocorticoids and androgens, sparing glucocorticoids", "B": "Only mineralocorticoids", "C": "Glucocorticoids +/- androgens, with aldosterone relatively spared", "D": "All three classes equally, identical to Addison disease"}, "r": "C", "e": {"correcta": "Secondary adrenocortical insufficiency results from decreased pituitary ACTH secretion, which primarily drives cortisol (and to some extent androgen) production from the adrenal cortex. Aldosterone secretion is largely governed by the renin-angiotensin system and requires only low, tonic levels of ACTH, so it remains relatively normal, sparing patients from the hyperkalemia, metabolic acidosis, and hypotension seen in Addison disease.", "incorrectas": {"A": "This describes the opposite pattern; in secondary insufficiency it is glucocorticoids (and possibly androgens) that fall due to lost ACTH drive, while mineralocorticoids are spared, not the reverse.", "B": "Isolated mineralocorticoid deficiency is not the pattern seen; aldosterone is actually preserved in secondary adrenal insufficiency since it does not critically depend on ACTH.", "D": "Secondary adrenocortical insufficiency is specifically distinguished from Addison disease by sparing of aldosterone; equating the two patterns misses this key clinical distinction (e.g., absence of hyperkalemia in secondary disease)."}}}, {"id": "anking-endocrine-pathology-1428", "fuente": "anking", "tema": 5, "anki": "1462066758910", "q": "What is the level of ACTH in secondary adrenocortical insufficiency, and why?", "o": {"A": "Increased, due to loss of negative feedback from low cortisol", "B": "Decreased, because the disease results from decreased pituitary ACTH secretion", "C": "Normal, because the defect is purely at the level of the adrenal cortex", "D": "Increased, due to an ACTH-secreting pituitary tumor"}, "r": "B", "e": {"correcta": "Secondary adrenocortical insufficiency is caused by a pituitary or hypothalamic defect leading to decreased ACTH secretion, which in turn causes decreased adrenal cortisol production. This is a critical distinguishing feature from Addison disease (primary insufficiency), where ACTH is elevated, and it explains why secondary insufficiency does not cause hyperpigmentation, since ACTH/MSH-related skin darkening requires elevated ACTH.", "incorrectas": {"A": "An ACTH rise from loss of cortisol feedback would occur if the adrenal gland itself were failing (primary insufficiency); in secondary insufficiency, the primary defect is insufficient ACTH production itself, not a compensatory rise.", "C": "The defect in secondary insufficiency is at the level of the pituitary (or hypothalamus), not the adrenal cortex; the adrenal gland is intrinsically capable of producing cortisol but lacks adequate ACTH stimulation.", "D": "An ACTH-secreting pituitary tumor causing elevated ACTH describes Cushing disease, a state of hormone excess, which is essentially the opposite clinical scenario from secondary adrenal insufficiency."}}}, {"id": "anking-endocrine-pathology-1429", "fuente": "anking", "tema": 5, "anki": "1462066777580", "q": "How do blood glucose levels change in secondary adrenocortical insufficiency, and why?", "o": {"A": "Hyperglycemia, due to elevated ACTH", "B": "Hypoglycemia, due to decreased cortisol levels", "C": "No change, since aldosterone is unaffected", "D": "Hypoglycemia, due to elevated insulin secretion"}, "r": "B", "e": {"correcta": "In secondary adrenocortical insufficiency, decreased ACTH leads to decreased cortisol production; since cortisol normally supports gluconeogenesis and antagonizes insulin, its deficiency results in hypoglycemia, similar to the glucose effect seen in Addison disease even though the underlying cause and aldosterone status differ.", "incorrectas": {"A": "ACTH itself is decreased (not elevated) in secondary insufficiency, and even where ACTH is elevated (as in Addison disease), the resulting cortisol deficiency causes hypoglycemia, not hyperglycemia.", "C": "While aldosterone is indeed largely unaffected in secondary insufficiency, this does not mean glucose is unaffected; cortisol deficiency independently causes hypoglycemia regardless of aldosterone status.", "D": "Cortisol deficiency does not work by increasing insulin secretion; rather, loss of cortisol's normal insulin-antagonizing, gluconeogenic actions is what drives the hypoglycemia."}}}, {"id": "anking-endocrine-pathology-1430", "fuente": "anking", "tema": 5, "anki": "1462066785696", "q": "Does secondary adrenocortical insufficiency present with hyperpigmentation? Why or why not?", "o": {"A": "Yes, because low cortisol directly darkens the skin", "B": "No, because ACTH levels are low, so there is no increased melanocyte-stimulating hormone (MSH) co-production", "C": "Yes, to the same degree as Addison disease", "D": "No, because aldosterone directly suppresses melanocyte activity"}, "r": "B", "e": {"correcta": "Hyperpigmentation in adrenal insufficiency results from elevated ACTH, which is cleaved from the same POMC precursor as melanocyte-stimulating hormone, so high ACTH also raises MSH-like activity and darkens the skin. In secondary insufficiency, ACTH is low (not elevated) because the defect is at the pituitary level, so this MSH-driven hyperpigmentation does not occur, unlike in Addison disease.", "incorrectas": {"A": "Cortisol itself has no direct pigmentation effect; the hyperpigmentation seen in some forms of adrenal insufficiency is mediated indirectly through elevated ACTH/POMC-derived peptides, not cortisol.", "C": "Secondary insufficiency is specifically characterized by the absence of hyperpigmentation because ACTH is low, in clear contrast to Addison disease, where hyperpigmentation is a classic and prominent finding due to high ACTH.", "D": "Aldosterone has no role in skin pigmentation; the mechanism linking adrenal insufficiency to hyperpigmentation runs through elevated ACTH and its shared precursor with MSH, not through mineralocorticoid activity."}}}, {"id": "anking-endocrine-pathology-1431", "fuente": "anking", "tema": 5, "anki": "1462066794043", "q": "Why does secondary adrenocortical insufficiency typically NOT present with hyperkalemia, metabolic acidosis, or hypotension?", "o": {"A": "Because ACTH levels remain elevated and compensate", "B": "Because aldosterone levels are normal in this condition", "C": "Because cortisol levels are actually normal in secondary insufficiency", "D": "Because the renin-angiotensin system is inactivated"}, "r": "B", "e": {"correcta": "Aldosterone secretion depends mainly on the renin-angiotensin-aldosterone system and requires only low, tonic ACTH levels to be maintained, so in secondary adrenocortical insufficiency (a pituitary/hypothalamic problem causing decreased ACTH), aldosterone production remains largely normal. This spares patients the hyperkalemia, metabolic acidosis, and hypotension that occur in Addison disease, where the entire adrenal cortex including aldosterone-producing tissue is destroyed.", "incorrectas": {"A": "ACTH is actually decreased, not elevated, in secondary adrenocortical insufficiency; the sparing of aldosterone-related electrolyte problems occurs because aldosterone does not require high ACTH levels to be produced, not because of ACTH compensation.", "C": "Cortisol is in fact decreased in secondary insufficiency (that is the definition of the disease); the electrolyte findings are spared because of preserved aldosterone, not because cortisol is unaffected.", "D": "The renin-angiotensin system remains active and functional in secondary adrenal insufficiency; it is precisely this intact system (independent of ACTH) that keeps aldosterone production normal and prevents the electrolyte disturbances."}}}, {"id": "anking-endocrine-pathology-1432", "fuente": "anking", "tema": 5, "anki": "1462066866385", "q": "Which classes of steroid hormones are increased in Cushing syndrome/disease?", "o": {"A": "Mineralocorticoids only", "B": "Glucocorticoids (cortisol) +/- androgens", "C": "Androgens only, with normal cortisol", "D": "All three classes equally, including marked aldosterone excess"}, "r": "B", "e": {"correcta": "Cushing syndrome/disease is characterized by excess glucocorticoid (cortisol) production, and depending on the underlying cause (e.g., ACTH-secreting tumor driving the whole cortex), adrenal androgens may also be elevated, contributing to signs like hirsutism or virilization. Mineralocorticoid levels are not the primary hormone elevated in this condition, distinguishing it from primary hyperaldosteronism.", "incorrectas": {"A": "Isolated mineralocorticoid excess describes primary hyperaldosteronism (Conn syndrome), which presents with hypertension and hypokalemia rather than the classic cortisol-excess features (central obesity, striae, hyperglycemia) of Cushing syndrome.", "C": "Cortisol excess is the defining hormonal abnormality in Cushing syndrome; androgens may be elevated as well, but cortisol itself is markedly increased, not normal.", "D": "Aldosterone is not typically the predominantly elevated hormone in Cushing syndrome; the central hormonal abnormality is cortisol excess, with androgens variably elevated depending on etiology."}}}, {"id": "anking-endocrine-pathology-1433", "fuente": "anking", "tema": 5, "anki": "1462066906674", "q": "What is the level of ACTH in Cushing disease, and why?", "o": {"A": "Decreased, due to negative feedback from high cortisol", "B": "Increased, because the disease is caused by an ACTH-secreting pituitary tumor", "C": "Normal, because Cushing disease is ACTH-independent", "D": "Increased, due to an adrenal cortisol-secreting adenoma"}, "r": "B", "e": {"correcta": "Cushing disease specifically refers to Cushing syndrome caused by an ACTH-secreting pituitary adenoma, so ACTH levels are elevated and drive excess cortisol secretion from otherwise normal adrenal glands (bilateral adrenal hyperplasia results from the ACTH stimulation). This is distinct from ACTH-independent causes of Cushing syndrome, such as a primary adrenal adenoma or exogenous steroid use, where ACTH is suppressed.", "incorrectas": {"A": "Although high cortisol would normally exert negative feedback to lower ACTH, in Cushing disease, the pituitary tumor autonomously secretes ACTH and is relatively resistant to this feedback, keeping ACTH elevated despite high cortisol.", "C": "Cushing disease is by definition ACTH-dependent, since it is caused by an ACTH-producing pituitary tumor; ACTH-independent causes would be labeled differently (e.g., adrenal Cushing syndrome).", "D": "An adrenal cortisol-secreting adenoma is a primary adrenal cause of Cushing syndrome and would suppress ACTH via negative feedback, the opposite of the elevated ACTH seen in Cushing disease, which originates from the pituitary."}}}, {"id": "anking-endocrine-pathology-1434", "fuente": "anking", "tema": 5, "anki": "1462066956421", "q": "Which clinical feature in women with Cushing syndrome/disease results from increased adrenal androgen levels?", "o": {"A": "Osteoporosis", "B": "Virilization", "C": "Moon facies", "D": "Purple abdominal striae"}, "r": "B", "e": {"correcta": "Excess adrenal androgens in Cushing syndrome/disease can cause virilization in women, including features like hirsutism, deepening of the voice, and menstrual irregularities, reflecting the androgenic component of the hormonal excess alongside the glucocorticoid effects.", "incorrectas": {"A": "Osteoporosis in Cushing syndrome results from glucocorticoid excess directly inhibiting osteoblast activity and promoting bone resorption, not from the androgen component of the disease.", "C": "Moon facies (rounded facial appearance) is a classic feature of cortisol-driven central fat redistribution, not a result of androgen excess specifically.", "D": "Purple striae result from glucocorticoid-mediated decreased fibroblast activity and collagen breakdown in the skin, a cortisol effect rather than an androgen-driven feature."}}}, {"id": "anking-endocrine-pathology-1435", "fuente": "anking", "tema": 5, "anki": "1462066978901", "q": "What is the expected result of a high-dose dexamethasone suppression test in a patient with Cushing disease (pituitary ACTH-secreting adenoma)?", "o": {"A": "Cortisol response would NOT be suppressed at any dexamethasone dose", "B": "Cortisol response WOULD BE suppressed by high-dose dexamethasone", "C": "ACTH would rise paradoxically regardless of dose", "D": "Cortisol would be suppressed equally by both low and high doses"}, "r": "B", "e": {"correcta": "In Cushing disease, the pituitary corticotroph adenoma retains partial responsiveness to negative feedback, so while low-dose dexamethasone fails to suppress cortisol, high-dose dexamethasone is typically able to suppress cortisol secretion. This distinguishes Cushing disease from ectopic ACTH-secreting tumors or primary adrenal Cushing syndrome, where high-dose dexamethasone typically fails to suppress cortisol.", "incorrectas": {"A": "Failure of cortisol to suppress even at high-dose dexamethasone is more characteristic of an ectopic ACTH-secreting tumor or an autonomous adrenal cause, not classic pituitary Cushing disease, which does show suppression at the high dose.", "C": "A paradoxical rise in ACTH regardless of dose is not the expected pattern in Cushing disease; the pituitary adenoma still retains some feedback sensitivity, which is exploited diagnostically at the high dose.", "D": "Low-dose dexamethasone fails to suppress cortisol in Cushing disease (this is actually part of what confirms the diagnosis); only the high dose achieves suppression, so equal suppression at both doses is incorrect."}}}, {"id": "anking-endocrine-pharmacology-1436", "fuente": "anking", "tema": 24, "anki": "1462066985374", "q": "Which medications are used as pharmacologic treatment for Cushing syndrome by blocking steroid hormone biosynthesis?", "o": {"A": "Spironolactone and eplerenone", "B": "Ketoconazole and metyrapone", "C": "Hydrocortisone and fludrocortisone", "D": "Cabergoline and pasireotide"}, "r": "B", "e": {"correcta": "Ketoconazole and metyrapone are used to treat Cushing syndrome by directly inhibiting enzymes in the steroidogenesis pathway, thereby blocking cortisol biosynthesis at the adrenal level. These agents are especially useful for rapid biochemical control of severe hypercortisolism, such as before definitive surgery or in inoperable cases.", "incorrectas": {"A": "Spironolactone and eplerenone are mineralocorticoid receptor antagonists used mainly in hyperaldosteronism (Conn syndrome) and heart failure, not to block cortisol synthesis in Cushing syndrome.", "C": "Hydrocortisone and fludrocortisone are replacement therapies used in adrenal insufficiency (the opposite condition of cortisol deficiency), not treatments for cortisol excess.", "D": "Cabergoline and pasireotide are dopamine agonist/somatostatin analog therapies sometimes used for Cushing disease by acting on the pituitary tumor to reduce ACTH secretion, which is a different mechanism from directly blocking adrenal steroidogenic enzymes like ketoconazole and metyrapone do."}}}, {"id": "anking-endocrine-pathology-1437", "fuente": "anking", "tema": 5, "anki": "1462067017399", "q": "What is the definitive treatment for Cushing disease (ACTH-secreting pituitary adenoma)?", "o": {"A": "Lifelong ketoconazole therapy", "B": "Bilateral adrenalectomy as first-line therapy", "C": "Removal of the ACTH-secreting tumor", "D": "High-dose glucocorticoid replacement"}, "r": "C", "e": {"correcta": "The definitive treatment for Cushing disease is surgical removal of the ACTH-secreting pituitary tumor (typically via transsphenoidal resection), which eliminates the source of excess ACTH and subsequently normalizes cortisol production by the adrenal glands.", "incorrectas": {"A": "Ketoconazole can be used for temporary medical control of hypercortisolism (e.g., preoperatively) but is not the definitive treatment; the underlying tumor still needs to be addressed surgically for cure.", "B": "Bilateral adrenalectomy removes the adrenal glands themselves but leaves the pituitary tumor in place, which can lead to Nelson syndrome (an enlarging, ACTH-hypersecreting pituitary tumor after loss of adrenal feedback); it is not the first-line treatment for Cushing disease.", "D": "Giving more glucocorticoids would worsen, not treat, the hypercortisolism of Cushing disease; this is the opposite of the appropriate management for hormone excess."}}}, {"id": "anking-endocrine-pathology-1438", "fuente": "anking", "tema": 5, "anki": "1462067036959", "q": "Conn syndrome presents with hypertension, hypokalemia, and metabolic alkalosis due to which hormonal abnormality?", "o": {"A": "Increased aldosterone levels", "B": "Increased cortisol levels", "C": "Increased renin levels", "D": "Decreased ACTH levels"}, "r": "A", "e": {"correcta": "Conn syndrome is caused by primary hyperaldosteronism, typically from an aldosterone-producing adrenal adenoma, leading to increased sodium and water reabsorption (causing hypertension), potassium wasting (hypokalemia), and increased hydrogen ion secretion (metabolic alkalosis). Because the increased extracellular fluid volume raises renal perfusion pressure, renin secretion is actually suppressed (low renin), which is a key diagnostic clue distinguishing primary from secondary hyperaldosteronism; these electrolyte imbalances may also cause paresthesias and muscle weakness.", "incorrectas": {"B": "While cortisol excess (Cushing syndrome) can occasionally cause some mineralocorticoid-like effects at very high levels, the classic and defining hormonal abnormality of Conn syndrome is autonomous aldosterone excess, not cortisol excess.", "C": "Renin levels are actually decreased, not increased, in Conn syndrome (primary hyperaldosteronism), because the elevated aldosterone and expanded volume suppress renin release; an elevated renin would instead suggest secondary hyperaldosteronism.", "D": "ACTH is not the driver of aldosterone excess in Conn syndrome; aldosterone secretion here is autonomous from the adrenal adenoma and largely independent of ACTH, which primarily governs cortisol and androgen synthesis."}}}, {"id": "anking-endocrine-physiology-1439", "fuente": "anking", "tema": 23, "anki": "1462067070469", "q": "Which classes of adrenal steroid hormones are decreased in 21-hydroxylase deficiency (a cause of congenital adrenal hyperplasia)?", "o": {"A": "Androgens and mineralocorticoids only", "B": "Glucocorticoids and mineralocorticoids", "C": "Glucocorticoids and androgens", "D": "None; all steroid classes are increased"}, "r": "B", "e": {"correcta": "21-hydroxylase deficiency blocks the conversion of steroid precursors into both cortisol and aldosterone pathways, resulting in decreased glucocorticoids and mineralocorticoids. The accumulated precursors are shunted into the androgen synthesis pathway, causing increased androgen production, which leads to virilization and, in severe cases, salt-wasting crises from the mineralocorticoid deficiency.", "incorrectas": {"A": "Androgens are actually increased, not decreased, in 21-hydroxylase deficiency, because the enzymatic block shunts precursor steroids toward the androgen pathway rather than reducing androgen production.", "C": "Glucocorticoids are indeed decreased, but androgens are increased (not decreased) in this condition, since the blocked pathway diverts precursors toward androgen synthesis.", "D": "This is the reverse of the true pattern; glucocorticoids and mineralocorticoids are decreased due to the enzymatic block, while only androgens are increased from precursor shunting."}}}, {"id": "anking-endocrine-physiology-1440", "fuente": "anking", "tema": 23, "anki": "1462067091584", "q": "Deficiency of which enzyme is the most common cause of congenital adrenal hyperplasia?", "o": {"A": "17α-hydroxylase", "B": "21β-hydroxylase", "C": "11β-hydroxylase", "D": "3β-hydroxysteroid dehydrogenase"}, "r": "B", "e": {"correcta": "21β-hydroxylase converts progesterone to 11-deoxycorticosterone and 17-hydroxyprogesterone to 11-deoxycortisol, steps required for both mineralocorticoid and glucocorticoid synthesis. Its deficiency is the most common cause of congenital adrenal hyperplasia and blocks cortisol and aldosterone production while shunting precursors into the androgen pathway, producing an adrenogenital syndrome.", "incorrectas": {"A": "17α-hydroxylase deficiency is a much rarer cause of CAH, and it decreases sex hormones and cortisol while increasing mineralocorticoids, the opposite hormonal pattern from 21β-hydroxylase deficiency.", "C": "11β-hydroxylase deficiency is a less common cause of CAH that causes virilization with hypertension (due to accumulation of 11-deoxycorticosterone), but it is not the most common cause.", "D": "3β-hydroxysteroid dehydrogenase deficiency is a rare cause of CAH that impairs synthesis of all three classes of adrenal steroids, but it is not the classic most-common form tested on boards."}}}, {"id": "anking-endocrine-physiology-1441", "fuente": "anking", "tema": 23, "anki": "1462067106848", "q": "In 21β-hydroxylase deficiency, what happens to ACTH levels and why?", "o": {"A": "Decreased, due to increased negative feedback from mineralocorticoids", "B": "Unchanged, because ACTH is independent of cortisol", "C": "Increased, due to decreased negative feedback from cortisol", "D": "Decreased, due to direct enzyme inhibition of the pituitary"}, "r": "C", "e": {"correcta": "Because 21β-hydroxylase deficiency blocks cortisol synthesis, there is less negative feedback on the hypothalamic-pituitary axis, so ACTH rises. This chronic ACTH stimulation drives adrenocortical hyperplasia, the hallmark of the disease, while also pushing precursors toward androgen synthesis.", "incorrectas": {"A": "Mineralocorticoids like aldosterone do not provide meaningful negative feedback on ACTH secretion; it is cortisol (glucocorticoid) that normally suppresses the hypothalamic-pituitary-adrenal axis.", "B": "ACTH secretion is tightly regulated by cortisol feedback via the hypothalamic-pituitary-adrenal axis, so it is very much dependent on cortisol levels, not independent of them.", "D": "21β-hydroxylase acts within the adrenal cortex on steroid precursors; it has no direct action on the pituitary gland, so the ACTH rise is due to loss of feedback inhibition, not direct enzyme inhibition of the pituitary."}}}, {"id": "anking-endocrine-physiology-1442", "fuente": "anking", "tema": 23, "anki": "1462067121558", "q": "A female infant with 21β-hydroxylase deficiency presents with clitoral enlargement and early pubic/axillary hair. These findings result from excess of which hormone class?", "o": {"A": "Mineralocorticoids", "B": "Glucocorticoids", "C": "Androgens", "D": "Estrogens"}, "r": "C", "e": {"correcta": "Because 21β-hydroxylase deficiency blocks the cortisol and aldosterone pathways, accumulated precursors are shunted into androgen synthesis. The resulting androgen excess causes masculinization in females, including clitoromegaly and early pubic/axillary hair, alongside the separate features of glucocorticoid and mineralocorticoid deficiency.", "incorrectas": {"A": "Mineralocorticoids are actually decreased (not increased) in classic 21β-hydroxylase deficiency, contributing to salt-wasting, not to masculinization.", "B": "Glucocorticoids (cortisol) are decreased in this enzyme deficiency, which is why patients also have signs of adrenal insufficiency; glucocorticoid excess would cause a Cushingoid picture, not virilization.", "D": "Estrogen excess would cause feminizing changes, not masculinization; the pathway shunting in 21β-hydroxylase deficiency directs precursors toward androgens, not estrogens."}}}, {"id": "anking-endocrine-physiology-1443", "fuente": "anking", "tema": 23, "anki": "1462067165000", "q": "In 21β-hydroxylase deficiency, urinary excretion of which substance is increased, reflecting excess adrenal androgen production?", "o": {"A": "Vanillylmandelic acid", "B": "17-ketosteroids", "C": "5-hydroxyindoleacetic acid", "D": "Metanephrines"}, "r": "B", "e": {"correcta": "17-ketosteroids are urinary metabolites of adrenal (and gonadal) androgens such as DHEA and androstenedione. Because 21β-hydroxylase deficiency shunts steroid precursors into the androgen pathway, urinary 17-ketosteroid excretion is characteristically elevated, serving as a diagnostic clue.", "incorrectas": {"A": "Vanillylmandelic acid (VMA) is a breakdown product of catecholamines (epinephrine/norepinephrine) used to screen for pheochromocytoma, unrelated to adrenal androgen production.", "C": "5-hydroxyindoleacetic acid (5-HIAA) is a serotonin metabolite used to diagnose carcinoid syndrome, not a marker of adrenal steroidogenesis.", "D": "Metanephrines are also catecholamine metabolites used in pheochromocytoma workup, reflecting adrenal medullary (not adrenal cortex androgen) hormone excess."}}}, {"id": "anking-endocrine-pharmacology-1444", "fuente": "anking", "tema": 24, "anki": "1462067175456", "q": "What is the appropriate treatment for classic 21β-hydroxylase deficiency (congenital adrenal hyperplasia)?", "o": {"A": "Mineralocorticoid replacement alone", "B": "Androgen receptor blockade alone", "C": "Replacement of both glucocorticoids and mineralocorticoids", "D": "ACTH analog therapy to stimulate residual enzyme activity"}, "r": "C", "e": {"correcta": "Since 21β-hydroxylase deficiency causes both cortisol and aldosterone deficiency, treatment requires replacing both glucocorticoids and mineralocorticoids. Glucocorticoid replacement also suppresses the excess ACTH drive, which in turn reduces the shunting of precursors into androgen overproduction.", "incorrectas": {"A": "Mineralocorticoid replacement alone would address salt-wasting but would leave cortisol deficiency untreated and would not suppress the elevated ACTH driving androgen excess.", "B": "Androgen receptor blockade does not address the underlying cortisol and aldosterone deficiencies that cause the acute, life-threatening manifestations of the disease (adrenal crisis, salt-wasting).", "D": "Giving more ACTH would be counterproductive, since ACTH excess is what drives the adrenal hyperplasia and androgen overproduction in this condition; the enzyme block itself cannot be overcome by more ACTH stimulation."}}}, {"id": "anking-endocrine-physiology-1445", "fuente": "anking", "tema": 23, "anki": "1462067182134", "q": "17α-hydroxylase deficiency causes decreased production of which two classes of steroid hormones?", "o": {"A": "Mineralocorticoids and glucocorticoids", "B": "Glucocorticoids and androgens", "C": "Androgens and mineralocorticoids", "D": "Glucocorticoids and estrogens only"}, "r": "B", "e": {"correcta": "17α-hydroxylase is required to convert pregnenolone/progesterone into precursors of cortisol and androgens. Its deficiency blocks glucocorticoid and androgen synthesis, shunting steroid precursors into the mineralocorticoid pathway and causing mineralocorticoid excess instead.", "incorrectas": {"A": "Mineralocorticoids are actually increased, not decreased, in 17α-hydroxylase deficiency because precursors are shunted into that pathway when the 17α-hydroxylation step is blocked.", "C": "Mineralocorticoids are elevated rather than decreased in this deficiency; only glucocorticoids and androgens are reduced.", "D": "Estrogens are downstream of androgens, but the classic teaching describes glucocorticoids and androgens broadly as deficient, and mineralocorticoids as the pathway that is instead overproduced."}}}, {"id": "anking-endocrine-physiology-1446", "fuente": "anking", "tema": 23, "anki": "1462067204039", "q": "A phenotypic female with 17α-hydroxylase deficiency fails to develop pubic and axillary hair at puberty. This is due to decreased levels of which hormone class?", "o": {"A": "Mineralocorticoids", "B": "Glucocorticoids", "C": "Estrogens", "D": "Androgens"}, "r": "D", "e": {"correcta": "Pubic and axillary hair growth in females is driven by adrenal and ovarian androgens. Because 17α-hydroxylase deficiency blocks androgen synthesis, affected females lack this androgen-dependent hair development, alongside other signs of glucocorticoid deficiency and mineralocorticoid excess.", "incorrectas": {"A": "Mineralocorticoids are actually increased in 17α-hydroxylase deficiency (causing hypertension and hypokalemia), and they do not govern pubic/axillary hair development.", "B": "Glucocorticoid deficiency in this condition contributes to signs like hypoglycemia tendency but does not explain the lack of sexual hair, which is androgen-dependent.", "C": "Estrogens support breast development and other feminizing changes, but pubic and axillary hair growth specifically depends on androgens, not estrogens."}}}, {"id": "anking-endocrine-physiology-1447", "fuente": "anking", "tema": 23, "anki": "1462067218581", "q": "In 17α-hydroxylase deficiency, aldosterone levels are typically which of the following, despite mineralocorticoid excess symptoms?", "o": {"A": "Markedly increased", "B": "Decreased", "C": "Unchanged from normal", "D": "Increased only during stress"}, "r": "B", "e": {"correcta": "In 17α-hydroxylase deficiency, excess 11-deoxycorticosterone (DOC) and corticosterone act as mineralocorticoids, causing hypertension. This hypertension suppresses renin, which lowers angiotensin II, and consequently aldosterone itself is decreased even though the patient has clinical mineralocorticoid excess from DOC.", "incorrectas": {"A": "Aldosterone is paradoxically low, not increased, because the mineralocorticoid excess is driven by DOC and corticosterone, whose hypertensive effect suppresses renin-angiotensin-aldosterone activity.", "C": "Aldosterone is specifically decreased due to renin suppression from the DOC-mediated hypertension, not simply unchanged.", "D": "The suppression of renin and aldosterone is a sustained physiologic consequence of chronic mineralocorticoid excess, not an intermittent, stress-limited phenomenon."}}}, {"id": "anking-endocrine-physiology-1448", "fuente": "anking", "tema": 23, "anki": "1462067231521", "q": "Which adrenal enzyme deficiency causes shunting of steroid precursors toward the aldosterone (mineralocorticoid) synthesis pathway?", "o": {"A": "21β-hydroxylase deficiency", "B": "11β-hydroxylase deficiency", "C": "17α-hydroxylase deficiency", "D": "Aromatase deficiency"}, "r": "C", "e": {"correcta": "17α-hydroxylase deficiency blocks conversion of precursors toward cortisol and androgens, forcing excess pregnenolone and progesterone down the mineralocorticoid pathway. This produces increased 11-deoxycorticosterone and corticosterone, causing hypertension and hypokalemia despite low aldosterone itself.", "incorrectas": {"A": "21β-hydroxylase deficiency shunts precursors toward the androgen pathway (causing virilization), the opposite direction of shunting compared to 17α-hydroxylase deficiency.", "B": "11β-hydroxylase deficiency causes accumulation of 11-deoxycorticosterone and virilization with hypertension, but the classic \"shunt toward mineralocorticoid pathway\" enzyme discussed in this context is 17α-hydroxylase deficiency.", "D": "Aromatase deficiency impairs conversion of androgens to estrogens and is not a cause of congenital adrenal hyperplasia or mineralocorticoid pathway shunting."}}}, {"id": "anking-endocrine-physiology-1449", "fuente": "anking", "tema": 23, "anki": "1462067240205", "q": "Which adrenal enzyme deficiency results in shunting of steroid precursors toward the androgen synthesis pathway?", "o": {"A": "17α-hydroxylase deficiency", "B": "21β-hydroxylase deficiency", "C": "Aromatase deficiency", "D": "5α-reductase deficiency"}, "r": "B", "e": {"correcta": "21β-hydroxylase deficiency blocks conversion of 17-hydroxyprogesterone and progesterone into cortisol and aldosterone precursors, so excess substrate is diverted into androgen synthesis. This causes virilization in females and precocious puberty features, alongside signs of glucocorticoid and mineralocorticoid deficiency.", "incorrectas": {"A": "17α-hydroxylase deficiency shunts precursors toward the mineralocorticoid pathway (increasing DOC and corticosterone), the opposite of androgen pathway shunting.", "C": "Aromatase deficiency prevents conversion of androgens to estrogens, which actually leads to androgen accumulation for a different reason, but it is not a cause of congenital adrenal hyperplasia via cortisol pathway shunting.", "D": "5α-reductase deficiency impairs conversion of testosterone to the more potent dihydrotestosterone peripherally; it does not involve shunting within the adrenal steroidogenesis pathway."}}}, {"id": "anking-endocrine-anatomy-1450", "fuente": "anking", "tema": 25, "anki": "1462120796565", "q": "The endocrine cells of the pancreas, comprising only 1-2% of pancreatic mass, are organized into which structures?", "o": {"A": "Islets of Langerhans", "B": "Crypts of Lieberkühn", "C": "Peyer's patches", "D": "Zona glomerulosa nodules"}, "r": "A", "e": {"correcta": "The islets of Langerhans are clusters of endocrine cells scattered throughout the pancreas that make up only 1-2% of total pancreatic mass, with the remainder being exocrine acinar tissue. These islets contain alpha, beta, delta, and other cell types that secrete glucagon, insulin, somatostatin, and other peptides directly into the bloodstream.", "incorrectas": {"B": "Crypts of Lieberkühn are intestinal glands found in the small and large intestine mucosa, unrelated to pancreatic endocrine tissue.", "C": "Peyer's patches are lymphoid follicles found in the ileum that are part of gut-associated lymphoid tissue, not endocrine pancreatic structures.", "D": "The zona glomerulosa is a layer of the adrenal cortex that produces aldosterone; it has no relation to pancreatic endocrine architecture."}}}, {"id": "anking-endocrine-anatomy-1451", "fuente": "anking", "tema": 25, "anki": "1462121476788", "q": "Besides alpha, beta, and delta cells, the remaining cells of the islets of Langerhans mainly secrete which substance?", "o": {"A": "Gastrin", "B": "Vasoactive intestinal peptide", "C": "Pancreatic polypeptide", "D": "Secretin"}, "r": "C", "e": {"correcta": "A minor population of islet cells (PP cells, or F cells) secretes pancreatic polypeptide along with other minor peptides. Pancreatic polypeptide helps regulate pancreatic exocrine and endocrine secretion, though it is a much smaller contributor than the major alpha, beta, and delta cell hormones.", "incorrectas": {"A": "Gastrin is secreted by G cells located primarily in the gastric antrum and duodenum, not by pancreatic islet cells.", "B": "Vasoactive intestinal peptide is produced by neurons and some diffuse endocrine cells in the GI tract, and while some islet cells can express related peptides, it is not the classic \"remaining\" islet cell secretion described here.", "D": "Secretin is secreted by S cells in the duodenal mucosa in response to acidic chyme, and is unrelated to the minor islet cell population."}}}, {"id": "anking-endocrine-anatomy-1452", "fuente": "anking", "tema": 25, "anki": "1462121485588", "q": "What structures link beta-cells to each other, alpha-cells to each other, and beta-cells to alpha-cells within the islets of Langerhans, enabling rapid intercellular communication?", "o": {"A": "Tight junctions", "B": "Desmosomes", "C": "Gap junctions", "D": "Hemidesmosomes"}, "r": "C", "e": {"correcta": "Gap junctions are channels that allow direct ionic and small-molecule communication between adjacent cells. Within the islets of Langerhans, gap junctions connect beta-to-beta, alpha-to-alpha, and beta-to-alpha cells, allowing coordinated, rapid signaling that helps synchronize hormone release across the islet.", "incorrectas": {"A": "Tight junctions seal the intercellular space to control paracellular permeability (as seen between epithelial cells) but do not allow direct cytoplasmic communication between cells the way gap junctions do.", "B": "Desmosomes are adhesive junctions that provide mechanical strength between cells (e.g., in skin and cardiac tissue) but do not permit direct chemical or electrical communication.", "D": "Hemidesmosomes anchor epithelial cells to the underlying basement membrane; they are not intercellular junctions and do not mediate cell-to-cell communication."}}}, {"id": "anking-endocrine-anatomy-1453", "fuente": "anking", "tema": 25, "anki": "1462121501158", "q": "The portal blood supply within the islets of Langerhans allows insulin-rich venous blood from which cells to bathe the alpha and delta cells, promoting paracrine communication?", "o": {"A": "Delta cells", "B": "PP (pancreatic polypeptide) cells", "C": "Alpha cells", "D": "Beta cells"}, "r": "D", "e": {"correcta": "Blood flows first through the beta-cell-rich core of the islet before draining outward, meaning insulin-laden venous blood from beta cells bathes the surrounding alpha and delta cells. This portal-like microcirculation allows insulin to locally suppress glucagon secretion from alpha cells, an example of intra-islet paracrine regulation.", "incorrectas": {"A": "Delta cells, which secrete somatostatin, are themselves downstream recipients of beta-cell-derived blood flow in this arrangement rather than the source cells whose secretions bathe the others.", "B": "PP cells are a minor islet population not described as the central source of blood flow that bathes the other islet cell types.", "C": "Alpha cells are positioned at the periphery of the islet and receive blood from the beta-cell core; they are not the source of the blood supply in this described flow pattern."}}}, {"id": "anking-endocrine-anatomy-1454", "fuente": "anking", "tema": 25, "anki": "1462121565140", "q": "Where are the somatostatin-secreting delta cells located within the islets of Langerhans?", "o": {"A": "Confined to the outermost periphery of the islet", "B": "Interspersed between alpha and beta cells", "C": "Clustered exclusively in the islet core", "D": "Located only in islets near the pancreatic tail"}, "r": "B", "e": {"correcta": "Delta cells are scattered between the alpha (peripheral) and beta (central) cells within the islet architecture. This central positioning allows somatostatin, their secreted hormone, to exert local paracrine inhibitory effects on both insulin and glucagon secretion from neighboring cells.", "incorrectas": {"A": "Alpha cells, not delta cells, are classically described as occupying the outer rim of the islet, with beta cells forming the central core.", "C": "Beta cells make up the central core of the islet; delta cells are interspersed between the alpha and beta cell populations rather than confined to the core themselves.", "D": "Islet cell arrangement (alpha peripheral, beta central, delta interspersed) is a general feature of pancreatic islets throughout the gland, not a phenomenon restricted to the tail."}}}, {"id": "anking-endocrine-physiology-1455", "fuente": "anking", "tema": 23, "anki": "1462122564570", "q": "The gene directing insulin synthesis is located on which chromosome?", "o": {"A": "Chromosome 6", "B": "Chromosome 11", "C": "Chromosome 17", "D": "Chromosome 21"}, "r": "B", "e": {"correcta": "The insulin gene (INS) is located on chromosome 11, and mutations or regulatory changes at this locus can affect insulin production and have been studied in relation to diabetes risk. This gene encodes preproinsulin, which undergoes sequential processing to yield mature insulin.", "incorrectas": {"A": "Chromosome 6 houses the HLA gene complex, relevant to autoimmune conditions like type 1 diabetes susceptibility, but not the insulin structural gene itself.", "C": "Chromosome 17 contains genes such as BRCA1 and TP53 among others, but it is not the location of the insulin gene.", "D": "Chromosome 21 is notable for trisomy 21 (Down syndrome) and genes like APP, but it does not carry the insulin gene."}}}, {"id": "anking-endocrine-physiology-1456", "fuente": "anking", "tema": 23, "anki": "1462122572408", "q": "Ribosomal translation of insulin mRNA in the rough endoplasmic reticulum initially produces which precursor molecule, containing a signal peptide, the A and B chains, and a connecting peptide?", "o": {"A": "Proinsulin", "B": "Preproinsulin", "C": "Mature insulin", "D": "C-peptide alone"}, "r": "B", "e": {"correcta": "Preproinsulin is the initial translation product synthesized on ribosomes in the rough endoplasmic reticulum. It contains a signal peptide that directs it into the ER lumen, along with the A chain, B chain, and connecting (C) peptide; cleavage of the signal peptide in the ER yields proinsulin.", "incorrectas": {"A": "Proinsulin is formed after the signal peptide is cleaved from preproinsulin in the ER; it is the next step in processing, not the initial ribosomal product described here.", "C": "Mature insulin (the A and B chains linked by disulfide bonds, without C-peptide) is produced only after further proteolytic cleavage in secretory granules, well after the initial translation step.", "D": "C-peptide alone is only one piece cleaved out of proinsulin during granule packaging; it is not the full initial translation product, which includes the signal peptide and both insulin chains as well."}}}, {"id": "anking-endocrine-physiology-1457", "fuente": "anking", "tema": 23, "anki": "1462122640848", "q": "After being formed in the rough endoplasmic reticulum, proinsulin is packaged into secretory granules within which organelle?", "o": {"A": "Mitochondria", "B": "Golgi apparatus", "C": "Lysosome", "D": "Peroxisome"}, "r": "B", "e": {"correcta": "Following synthesis and initial folding in the rough ER, proinsulin is transported to the Golgi apparatus, where it is packaged into secretory granules. Within these granules, proteolytic enzymes subsequently cleave proinsulin into insulin and C-peptide before storage and eventual exocytosis.", "incorrectas": {"A": "Mitochondria are the site of oxidative phosphorylation and ATP production (important for the later insulin secretion trigger) but are not involved in packaging proinsulin into secretory granules.", "C": "Lysosomes contain degradative enzymes for breaking down cellular debris and macromolecules; they are not part of the normal secretory pathway for proinsulin packaging.", "D": "Peroxisomes are involved in fatty acid oxidation and reactive oxygen species detoxification, not in the secretory packaging of proinsulin."}}}, {"id": "anking-endocrine-physiology-1458", "fuente": "anking", "tema": 23, "anki": "1462122652771", "q": "During packaging into secretory granules, proteases cleave which peptide from proinsulin to yield mature insulin?", "o": {"A": "Signal peptide", "B": "Connecting peptide", "C": "A chain", "D": "B chain"}, "r": "B", "e": {"correcta": "Within the secretory granules, specific proteases cleave the connecting peptide (C-peptide) out of proinsulin. This cleavage leaves the A and B chains linked by disulfide bonds as mature, biologically active insulin, while C-peptide is co-secreted in equimolar amounts.", "incorrectas": {"A": "The signal peptide is cleaved much earlier, in the rough endoplasmic reticulum, converting preproinsulin to proinsulin; it is not the peptide removed during granule packaging to form mature insulin.", "C": "The A chain is a structural component that remains as part of the mature insulin molecule after processing; it is not cleaved away.", "D": "The B chain, like the A chain, is retained as part of mature insulin (linked to the A chain by disulfide bonds) and is not the segment removed during proteolytic processing."}}}, {"id": "anking-endocrine-physiology-1459", "fuente": "anking", "tema": 23, "anki": "1462122670792", "q": "Insulin is packaged into secretory granules of the Golgi apparatus alongside which co-secreted peptide?", "o": {"A": "Proinsulin", "B": "Signal peptide", "C": "C peptide", "D": "Amylin only, with no other peptide"}, "r": "C", "e": {"correcta": "As proinsulin is cleaved within secretory granules, insulin and C-peptide are generated together and stored side by side. Because they are released in equimolar amounts upon exocytosis, C-peptide serves as a useful clinical marker of endogenous insulin secretion.", "incorrectas": {"A": "Proinsulin is the precursor molecule that gets cleaved to form insulin and C-peptide; once mature insulin is formed, proinsulin is no longer the co-packaged partner (though trace amounts may be co-secreted, it is not the intended answer here).", "B": "The signal peptide is removed early in processing (in the ER) and is degraded, not stored or co-secreted with mature insulin in granules.", "D": "While amylin (islet amyloid polypeptide) is also co-secreted with insulin from beta cells, the specific peptide classically taught as being packaged with insulin from proinsulin cleavage is C-peptide."}}}, {"id": "anking-endocrine-physiology-1460", "fuente": "anking", "tema": 23, "anki": "1462122681020", "q": "When a pancreatic beta cell is stimulated to release insulin, in what ratio are insulin and C-peptide released?", "o": {"A": "Insulin in a 2:1 excess over C-peptide", "B": "C-peptide in a 2:1 excess over insulin", "C": "Equimolar amounts", "D": "A variable ratio depending on glucose concentration"}, "r": "C", "e": {"correcta": "Because insulin and C-peptide are cleaved from the same proinsulin precursor and stored together in secretory granules, exocytosis releases them in equimolar quantities. This 1:1 relationship is clinically useful, since C-peptide is excreted largely unchanged in urine and can be measured to assess endogenous beta-cell function even in patients on exogenous insulin.", "incorrectas": {"A": "Insulin is not released in excess over C-peptide; both are cleaved from the same proinsulin molecule and are released in a strict 1:1 (equimolar) ratio, not a 2:1 ratio.", "B": "C-peptide is not released in excess over insulin; the cleavage of one proinsulin molecule yields exactly one insulin molecule and one C-peptide molecule.", "D": "The equimolar relationship between insulin and C-peptide release is a fixed consequence of their shared biosynthetic origin and does not vary with glucose concentration, which affects the total amount secreted but not the ratio."}}}, {"id": "anking-endocrine-physiology-1461", "fuente": "anking", "tema": 23, "anki": "1462122701249", "q": "Which peptide, co-packaged and co-secreted with insulin, can be measured to monitor endogenous beta-cell function in patients receiving exogenous insulin therapy?", "o": {"A": "Glucagon", "B": "Amylin", "C": "C peptide (connecting peptide)", "D": "Somatostatin"}, "r": "C", "e": {"correcta": "C-peptide is cleaved from proinsulin along with insulin and is secreted in equimolar amounts, then excreted largely unchanged in the urine. Because exogenous insulin preparations do not contain C-peptide, measuring urine or serum C-peptide levels distinguishes endogenous insulin production from exogenous insulin administration.", "incorrectas": {"A": "Glucagon is secreted by alpha cells and raises blood glucose; it is not co-packaged with insulin in beta cells and is not used as a marker of endogenous insulin secretion.", "B": "Amylin is co-secreted with insulin from beta cells and can reflect beta-cell activity, but the classic clinical marker used to distinguish endogenous insulin secretion from exogenous insulin injection is C-peptide.", "D": "Somatostatin is secreted by delta cells and inhibits insulin and glucagon release; it is not a marker of beta-cell insulin production."}}}, {"id": "anking-endocrine-pathology-1462", "fuente": "anking", "tema": 5, "anki": "1462122709023", "q": "A patient with a suspected insulinoma has elevated insulin along with elevated C-peptide. What is the most likely explanation for concurrently elevated levels of both insulin and C-peptide?", "o": {"A": "Exogenous insulin injection", "B": "Insulinoma or sulfonylurea use", "C": "Type 1 diabetes mellitus", "D": "Insulin receptor antibody-mediated resistance"}, "r": "B", "e": {"correcta": "Both insulinoma (an insulin-secreting beta cell tumor) and sulfonylurea drugs stimulate endogenous insulin secretion from beta cells, which co-releases C-peptide in equimolar amounts. This produces elevated levels of both insulin and C-peptide, distinguishing these causes from exogenous insulin administration.", "incorrectas": {"A": "Exogenous insulin injections raise insulin levels but do not contain C-peptide, so C-peptide levels would be normal or suppressed (due to feedback suppression of endogenous secretion), not elevated.", "C": "Type 1 diabetes mellitus is characterized by beta-cell destruction and loss of endogenous insulin production, so both insulin and C-peptide levels would typically be low, not elevated.", "D": "Insulin receptor antibody-mediated resistance would be expected to raise insulin levels as a compensatory response to reduced receptor signaling, but this is not the classic explanation paired with elevated C-peptide in this context; endogenous beta-cell hyperstimulation (insulinoma/sulfonylureas) is the standard answer."}}}, {"id": "anking-endocrine-physiology-1463", "fuente": "anking", "tema": 23, "anki": "1462122859168", "q": "A patient has elevated serum insulin but normal or decreased C-peptide levels. What is the most likely cause?", "o": {"A": "Insulinoma", "B": "Sulfonylurea overdose", "C": "Exogenous insulin use", "D": "Glucagonoma"}, "r": "C", "e": {"correcta": "Exogenous insulin injections raise measured insulin levels directly without contributing any C-peptide, since manufactured insulin lacks the connecting peptide. Additionally, elevated exogenous insulin suppresses endogenous beta-cell secretion via negative feedback, further lowering or normalizing C-peptide.", "incorrectas": {"A": "Insulinoma stimulates endogenous beta-cell secretion, releasing insulin and C-peptide together in equimolar amounts, so both would be elevated rather than showing a discordant pattern.", "B": "Sulfonylurea overdose stimulates endogenous insulin release from beta cells (by closing K+ channels), so it would also elevate both insulin and C-peptide together, not just insulin alone.", "D": "Glucagonoma involves excess glucagon secretion from alpha cell tumors and is associated with hyperglycemia, not classically with an insulin/C-peptide discordance pattern."}}}, {"id": "anking-endocrine-physiology-1464", "fuente": "anking", "tema": 23, "anki": "1462123239655", "q": "What is the major physiological regulator of insulin release from pancreatic beta cells?", "o": {"A": "Serum calcium", "B": "Glucose", "C": "Serum sodium", "D": "Cortisol"}, "r": "B", "e": {"correcta": "Glucose is the primary and most important stimulus for insulin secretion; as blood glucose rises, beta cells take up glucose, metabolize it, and trigger insulin release. This rate of release is proportional to glucose concentration up to roughly 300 mg/dL, beyond which the response plateaus.", "incorrectas": {"A": "While intracellular calcium influx is a critical downstream step that triggers exocytosis of insulin granules, serum calcium itself is not the major physiological regulator that initiates the beta-cell response to nutrient status.", "C": "Serum sodium levels are not a significant regulator of beta-cell insulin secretion; sodium homeostasis is primarily managed by renal and mineralocorticoid mechanisms.", "D": "Cortisol is a counter-regulatory hormone that tends to raise blood glucose and can modestly influence insulin secretion indirectly, but it is not the major direct regulator of insulin release; glucose itself holds that role."}}}, {"id": "anking-endocrine-physiology-1465", "fuente": "anking", "tema": 23, "anki": "1462127745460", "q": "Glucose enters the pancreatic beta cell from the blood via which transporter, characterized by low affinity and high capacity facilitated diffusion?", "o": {"A": "GLUT1", "B": "GLUT2", "C": "GLUT4", "D": "SGLT1"}, "r": "B", "e": {"correcta": "GLUT2 is a low-affinity, high-capacity facilitated glucose transporter expressed on pancreatic beta cells (as well as the liver and kidney). Its low affinity allows glucose entry into the beta cell to scale proportionally with blood glucose concentration, making it well suited for glucose sensing that triggers insulin secretion.", "incorrectas": {"A": "GLUT1 is a ubiquitously expressed, high-affinity glucose transporter (notably important in red blood cells and the blood-brain barrier) that maintains basal glucose uptake regardless of concentration, unlike the glucose-sensing role of GLUT2 in beta cells.", "C": "GLUT4 is the insulin-responsive glucose transporter found in skeletal muscle and adipose tissue, mediating glucose uptake in response to insulin rather than glucose sensing within the beta cell itself.", "D": "SGLT1 is a sodium-glucose cotransporter located in the intestine (and SGLT2 in the kidney) that uses secondary active transport, not facilitated diffusion, and is unrelated to beta-cell glucose sensing."}}}, {"id": "anking-endocrine-physiology-1466", "fuente": "anking", "tema": 23, "anki": "1462127781248", "q": "In the pancreatic beta cell, metabolism of glucose generates which molecule that causes closure of specific K+ channels and subsequent membrane depolarization?", "o": {"A": "NADH", "B": "ATP", "C": "Acetyl-CoA", "D": "Pyruvate"}, "r": "B", "e": {"correcta": "Glucose metabolism through glycolysis and oxidative phosphorylation raises intracellular ATP levels in the beta cell. The rising ATP-to-ADP ratio closes ATP-sensitive K+ channels, which depolarizes the cell membrane, opens voltage-gated Ca2+ channels, and ultimately triggers insulin granule exocytosis.", "incorrectas": {"A": "NADH is generated during glycolysis and the citric acid cycle and feeds into the electron transport chain to help generate ATP, but it is ATP itself, not NADH, that directly closes the K+ channels in this signaling cascade.", "C": "Acetyl-CoA is an intermediate that enters the citric acid cycle to help generate the reducing equivalents used for ATP production, but it does not directly act on the K+ channels.", "D": "Pyruvate is the end product of glycolysis that is further metabolized (via the citric acid cycle) to ultimately yield ATP, but pyruvate itself is not the direct trigger for K+ channel closure."}}}, {"id": "anking-endocrine-physiology-1467", "fuente": "anking", "tema": 23, "anki": "1462127869624", "q": "In the pancreatic beta cell, an increase in intracellular Ca2+ following membrane depolarization directly triggers which process, releasing insulin-containing granules?", "o": {"A": "Autophagy", "B": "Exocytosis", "C": "Pinocytosis", "D": "Apoptosis"}, "r": "B", "e": {"correcta": "Membrane depolarization from K+ channel closure opens voltage-gated Ca2+ channels, and the resulting rise in intracellular Ca2+ triggers exocytosis of insulin-containing secretory granules (which also contain C-peptide) into the bloodstream. This calcium-triggered exocytosis is the final common step of glucose-stimulated insulin secretion.", "incorrectas": {"A": "Autophagy is an intracellular degradative process for recycling damaged organelles and proteins; it is not the mechanism by which insulin granules are released from beta cells.", "C": "Pinocytosis is a form of endocytosis where cells take up extracellular fluid, essentially the opposite direction of vesicle trafficking compared to exocytotic hormone release.", "D": "Apoptosis is programmed cell death and is unrelated to the normal calcium-triggered secretory response that releases insulin granules."}}}, {"id": "anking-endocrine-pharmacology-1468", "fuente": "anking", "tema": 24, "anki": "1462127903018", "q": "Which class of drugs increases insulin secretion by closing ATP-sensitive K+ channels in pancreatic beta cells?", "o": {"A": "Biguanides", "B": "Thiazolidinediones", "C": "Sulfonylureas (e.g., tolbutamide, glyburide)", "D": "GLP-1 receptor agonists"}, "r": "C", "e": {"correcta": "Sulfonylureas such as tolbutamide and glyburide bind directly to the sulfonylurea receptor associated with ATP-sensitive K+ channels on beta cells, forcing channel closure independent of glucose metabolism. This mimics the natural ATP-mediated depolarization signal, triggering calcium influx and insulin exocytosis, making them effective but risk-prone for hypoglycemia.", "incorrectas": {"A": "Biguanides (e.g., metformin) work primarily by decreasing hepatic gluconeogenesis and increasing peripheral insulin sensitivity; they do not act on beta-cell K+ channels or directly stimulate insulin secretion.", "B": "Thiazolidinediones improve insulin sensitivity in peripheral tissues by activating PPAR-gamma receptors, and do not act on pancreatic K+ channels to stimulate insulin release.", "D": "GLP-1 receptor agonists enhance glucose-dependent insulin secretion through a cAMP-mediated pathway activated by GLP-1 receptor binding, a distinct mechanism from direct K+ channel closure used by sulfonylureas."}}}, {"id": "anking-gastrointestinal-physiology-1469", "fuente": "anking", "tema": 39, "anki": "1462127929691", "q": "Why is an oral glucose load a more powerful stimulant of insulin secretion than an equivalent intravenous glucose infusion?", "o": {"A": "Oral glucose is absorbed faster into the bloodstream than IV glucose", "B": "Oral glucose stimulates secretion of GIP and GLP-1 from the gut", "C": "Oral glucose bypasses first-pass hepatic metabolism", "D": "Oral glucose directly activates beta-cell GLUT2 transporters more efficiently"}, "r": "B", "e": {"correcta": "Oral glucose intake stimulates intestinal K cells and L cells to release the incretin hormones GIP and GLP-1, respectively. These incretins act on pancreatic beta cells to amplify glucose-stimulated insulin secretion, producing a greater insulin response than IV glucose, which bypasses the gut and does not trigger this incretin effect.", "incorrectas": {"A": "IV glucose actually raises blood glucose levels more rapidly and directly than oral glucose (which must be digested and absorbed), so absorption speed is not the reason oral glucose produces a greater insulin response.", "C": "First-pass hepatic metabolism affects drug and nutrient processing via the portal circulation, but this is not the mechanism responsible for the enhanced insulin response to oral glucose; the incretin effect from gut hormones is the accepted explanation.", "D": "GLUT2 transport of glucose into beta cells is a downstream, glucose-concentration-dependent process that occurs regardless of the route of glucose administration; the enhanced oral response comes from additional incretin hormone signaling, not more efficient GLUT2 activity."}}}, {"id": "anking-endocrine-pharmacology-1470", "fuente": "anking", "tema": 24, "anki": "1462127967528", "q": "By what mechanism do sulfonylurea drugs such as tolbutamide and glyburide increase insulin secretion?", "o": {"A": "By increasing beta-cell sensitivity to GLP-1", "B": "By closing ATP-dependent K+ channels, causing depolarization and insulin release", "C": "By inhibiting insulin degradation in the liver", "D": "By blocking glucagon receptors on beta cells"}, "r": "B", "e": {"correcta": "Sulfonylureas bind the sulfonylurea receptor (SUR1) subunit of the ATP-sensitive K+ channel on beta cells, causing the channel to close regardless of the cell's actual metabolic (ATP) state. This forced closure depolarizes the membrane, opens voltage-gated calcium channels, and triggers exocytosis of insulin-containing granules.", "incorrectas": {"A": "Sulfonylureas act directly on the K+ channel of the beta cell and do not work by enhancing GLP-1 receptor sensitivity, which is the mechanism of a different drug class (GLP-1 receptor agonists and DPP-4 inhibitors).", "C": "Sulfonylureas increase insulin secretion at the source (the beta cell) rather than by altering hepatic insulin clearance or degradation.", "D": "Sulfonylureas have no described action on glucagon receptors; their mechanism is specific to ATP-sensitive K+ channel closure in beta cells."}}}, {"id": "anking-endocrine-physiology-1471", "fuente": "anking", "tema": 23, "anki": "1462127985068", "q": "What effect does glucagon have on insulin secretion from pancreatic beta cells?", "o": {"A": "Decreases it", "B": "Increases it", "C": "No effect", "D": "Biphasic: initial decrease followed by suppression"}, "r": "B", "e": {"correcta": "Glucagon acts on beta cells via a cAMP-mediated pathway to enhance insulin secretion, providing a counter-regulatory feedback loop that helps balance glucose homeostasis. This is part of the broader paracrine cross-talk within the islet, where alpha-cell and beta-cell products influence each other's secretion.", "incorrectas": {"A": "Glucagon does not decrease insulin secretion; that inhibitory role is instead played by somatostatin, which is secreted by neighboring delta cells.", "C": "Glucagon has a clear stimulatory effect on beta cells through cAMP signaling, so it is incorrect to say it has no effect on insulin secretion.", "D": "There is no biphasic decrease-then-suppression pattern described for glucagon's effect on insulin secretion; the established effect is a straightforward increase."}}}, {"id": "anking-endocrine-physiology-1472", "fuente": "anking", "tema": 23, "anki": "1462128017601", "q": "What effect does somatostatin, secreted by pancreatic delta cells, have on insulin secretion?", "o": {"A": "Increases it", "B": "Decreases it", "C": "No significant effect", "D": "Converts insulin to its inactive precursor"}, "r": "B", "e": {"correcta": "Somatostatin acts as a paracrine inhibitor within the islet, suppressing the pathway that glucagon otherwise stimulates and thereby decreasing insulin secretion from beta cells. This inhibitory tone helps dampen and fine-tune overall islet hormone output.", "incorrectas": {"A": "Increasing insulin secretion is the effect of glucagon, not somatostatin; somatostatin instead opposes and inhibits that stimulatory pathway.", "C": "Somatostatin has a well-documented inhibitory paracrine effect on both insulin and glucagon secretion, so it is incorrect to describe it as having no significant effect.", "D": "Somatostatin does not chemically convert insulin to an inactive precursor; it acts upstream by inhibiting the beta cell's secretory signaling pathway, not by modifying the insulin molecule itself."}}}, {"id": "anking-endocrine-physiology-1473", "fuente": "anking", "tema": 23, "anki": "1462128028823", "q": "The insulin receptor is a tetrameric structure composed of which subunits?", "o": {"A": "Four identical alpha subunits", "B": "Two alpha and two beta subunits", "C": "Four identical beta subunits", "D": "One alpha and three beta subunits"}, "r": "B", "e": {"correcta": "The insulin receptor is a disulfide-linked tetramer composed of two extracellular alpha subunits, which bind insulin, and two transmembrane beta subunits, which contain intrinsic tyrosine kinase activity. Insulin binding to the alpha subunits activates the beta subunits' kinase domains, initiating downstream signaling cascades.", "incorrectas": {"A": "The receptor is not composed of four identical alpha subunits; it contains two alpha subunits (which bind insulin) paired with two distinct beta subunits (which transduce the signal).", "C": "The receptor is not composed of four identical beta subunits; the beta subunits function together with two alpha subunits, not as a homogeneous tetramer of beta subunits alone.", "D": "The correct stoichiometry is two alpha and two beta subunits, not one alpha and three beta subunits; the tetramer is symmetric with equal numbers of each subunit type."}}}, {"id": "anking-endocrine-physiology-1474", "fuente": "anking", "tema": 23, "anki": "1462128036872", "q": "Which subunits of the insulin receptor are connected by a disulfide bond and lie entirely within the extracellular domain?", "o": {"A": "Beta subunits", "B": "Alpha subunits", "C": "Gamma subunits", "D": "Delta subunits"}, "r": "B", "e": {"correcta": "The two alpha subunits of the insulin receptor are located entirely extracellularly and are linked to each other (and to the beta subunits) by disulfide bonds. These alpha subunits form the insulin-binding site, and ligand binding induces a conformational change transmitted to the transmembrane beta subunits.", "incorrectas": {"A": "The beta subunits span the membrane and contain the intracellular tyrosine kinase domain; they are not the subunits confined to the extracellular space, unlike the alpha subunits.", "C": "The insulin receptor tetramer is composed of alpha and beta subunits only; there is no gamma subunit in its structure.", "D": "There is no delta subunit in the insulin receptor; its structure consists solely of two alpha and two beta subunits linked by disulfide bonds."}}}, {"id": "anking-endocrine-physiology-1475", "fuente": "anking", "tema": 23, "anki": "1462128089182", "q": "Which subunit of the insulin receptor is a transmembrane protein connected to the extracellular alpha subunit by a disulfide bond?", "o": {"A": "α subunit", "B": "β subunit", "C": "GLUT4 transporter", "D": "IRS-1 adaptor protein"}, "r": "B", "e": {"correcta": "The insulin receptor is a heterotetramer of two extracellular α subunits (which bind insulin) and two transmembrane β subunits, linked by disulfide bonds. The β subunits span the membrane and contain the intracellular tyrosine kinase domain that transmits the signal into the cell.", "incorrectas": {"A": "The α subunit is entirely extracellular and serves as the insulin-binding site; it does not span the membrane and has no catalytic activity of its own.", "C": "GLUT4 is the insulin-responsive glucose transporter that translocates to the membrane after insulin signaling, but it is a separate protein from the receptor itself, not one of its subunits.", "D": "IRS-1 (insulin receptor substrate-1) is a cytoplasmic docking protein phosphorylated by the activated receptor; it is a downstream signaling molecule, not a structural subunit of the receptor."}}}, {"id": "anking-endocrine-physiology-1476", "fuente": "anking", "tema": 23, "anki": "1462128108324", "q": "The β subunits of the insulin receptor possess which intrinsic enzymatic activity?", "o": {"A": "Guanylate cyclase activity", "B": "Serine/threonine kinase activity", "C": "Tyrosine kinase activity", "D": "Phospholipase C activity"}, "r": "C", "e": {"correcta": "The insulin receptor is a receptor tyrosine kinase: its β subunits have intrinsic tyrosine kinase activity that phosphorylates tyrosine residues on itself and on downstream substrates, initiating the insulin signaling cascade.", "incorrectas": {"A": "Guanylate cyclase activity (as in the ANP receptor) generates cGMP as a second messenger; this is a distinct receptor class unrelated to the insulin receptor's mechanism.", "B": "Serine/threonine kinases (e.g., in TGF-β receptor signaling) phosphorylate different residues; the insulin receptor specifically phosphorylates tyrosines, not serines or threonines, at this initial step.", "D": "Phospholipase C activity generates IP3 and DAG downstream of Gq-coupled receptors; the insulin receptor itself lacks this activity and instead directly phosphorylates tyrosines."}}}, {"id": "anking-endocrine-physiology-1477", "fuente": "anking", "tema": 23, "anki": "1462128120927", "q": "When insulin binds its receptor, which enzyme becomes activated and autophosphorylates the receptor's β-subunits, subsequently phosphorylating intracellular proteins?", "o": {"A": "Adenylate cyclase", "B": "Tyrosine kinase", "C": "Protein kinase A", "D": "Phosphodiesterase"}, "r": "B", "e": {"correcta": "Insulin binding to the α subunits triggers a conformational change that activates the intrinsic tyrosine kinase domain of the β subunits. This kinase autophosphorylates the receptor itself and then phosphorylates intracellular substrates like IRS proteins, propagating the signal.", "incorrectas": {"A": "Adenylate cyclase generates cAMP downstream of Gs-coupled GPCRs (such as glucagon's receptor); the insulin receptor does not signal through cAMP generation as its primary mechanism.", "C": "Protein kinase A is activated by cAMP in glucagon and catecholamine signaling pathways, not by direct receptor autophosphorylation as occurs with the insulin receptor's tyrosine kinase.", "D": "Phosphodiesterase degrades cyclic nucleotides like cAMP and cGMP; it is not involved in the initial insulin receptor activation step described here."}}}, {"id": "anking-endocrine-physiology-1478", "fuente": "anking", "tema": 23, "anki": "1462128134720", "q": "After the insulin receptor phosphorylates intracellular proteins, what happens to the receptor itself?", "o": {"A": "It remains permanently on the cell surface", "B": "It is cleaved and released into the bloodstream", "C": "It is internalized via endocytosis and then degraded, stored, or recycled", "D": "It dimerizes irreversibly with GLUT4"}, "r": "C", "e": {"correcta": "Following activation and phosphorylation of downstream substrates, the insulin receptor complex is internalized by endocytosis. Once inside the cell, it may be degraded in lysosomes, stored, or recycled back to the plasma membrane, which helps regulate the duration and magnitude of insulin signaling.", "incorrectas": {"A": "Receptors do not remain permanently on the surface after activation; internalization is a key mechanism for terminating and modulating the signal, and contributes to receptor downregulation with chronic stimulation.", "B": "The receptor is not cleaved and released into circulation; it stays associated with the cell membrane/endosomal system throughout the internalization process.", "D": "GLUT4 translocation to the membrane is a downstream consequence of insulin signaling, but the insulin receptor does not irreversibly dimerize with GLUT4 as part of its post-signaling fate."}}}, {"id": "anking-endocrine-physiology-1479", "fuente": "anking", "tema": 23, "anki": "1462128153992", "q": "Chronic elevation of insulin levels, such as occurs in obesity, has what effect on insulin receptors in target tissues?", "o": {"A": "Upregulation, increasing insulin sensitivity", "B": "No change in receptor number", "C": "Down-regulation, potentially contributing to insulin resistance", "D": "Conversion of receptors to a high-affinity state"}, "r": "C", "e": {"correcta": "Insulin causes down-regulation of its own receptors on target tissues. In states of chronic hyperinsulinemia, such as obesity, this reduction in receptor number/sensitivity contributes to insulin resistance, a hallmark of type 2 diabetes.", "incorrectas": {"A": "Upregulation would increase sensitivity to insulin, which is the opposite of what is observed; chronically elevated insulin instead causes the receptor number to decrease.", "B": "Receptor number is not static; it is dynamically regulated by ligand exposure, and sustained high insulin levels specifically reduce receptor density.", "D": "Down-regulation involves fewer receptors and/or reduced signaling efficiency, not a shift of the same number of receptors into a higher-affinity conformation."}}}, {"id": "anking-endocrine-physiology-1480", "fuente": "anking", "tema": 23, "anki": "1462128168760", "q": "How does the number of insulin receptors change in starvation compared to obesity?", "o": {"A": "Increased in both starvation and obesity", "B": "Decreased in both starvation and obesity", "C": "Decreased in starvation, increased in obesity", "D": "Increased in starvation, decreased in obesity"}, "r": "D", "e": {"correcta": "Insulin receptor number is inversely related to circulating insulin levels: it is increased in starvation (low insulin) and decreased in obesity (chronically high insulin), reflecting receptor down-regulation by its own ligand. This is why waist circumference/waist-to-hip ratio, as a marker of visceral fat, helps predict insulin resistance.", "incorrectas": {"A": "Receptor number does not move in the same direction in both states; starvation and obesity represent opposite extremes of insulin exposure and produce opposite receptor responses.", "B": "A uniform decrease in both conditions ignores the adaptive upregulation seen in starvation, when low insulin levels allow more receptors to be expressed on target tissues.", "C": "This reverses the actual relationship: starvation (low insulin) is associated with increased receptor number, while obesity (high insulin) is associated with decreased receptor number, not the other way around."}}}, {"id": "anking-endocrine-physiology-1481", "fuente": "anking", "tema": 23, "anki": "1462128178981", "q": "Which three tissues are the primary targets of insulin action?", "o": {"A": "Brain, kidney, and pancreas", "B": "Liver, muscle, and adipose tissue", "C": "Lung, heart, and skin", "D": "Bone, intestine, and thyroid"}, "r": "B", "e": {"correcta": "Insulin's principal target organs are the liver, skeletal muscle, and adipose tissue. In these tissues, insulin promotes glucose uptake and storage (as glycogen or triglycerides) and inhibits catabolic processes like gluconeogenesis, glycogenolysis, and lipolysis.", "incorrectas": {"A": "The brain notably has largely insulin-independent glucose uptake (via GLUT1/GLUT3) and is not considered a primary insulin target tissue; the kidney and pancreas are also not classified among insulin's main target organs.", "C": "Lung, heart, and skin are not the classic insulin-responsive tissues; glucose uptake in these organs is largely insulin-independent or not central to insulin's major metabolic actions.", "D": "Bone, intestine, and thyroid are not the primary sites of insulin action; insulin's major metabolic effects on glucose, fat, and protein metabolism are concentrated in liver, muscle, and adipose tissue."}}}, {"id": "anking-endocrine-physiology-1482", "fuente": "anking", "tema": 23, "anki": "1462128231420", "q": "Insulin lowers blood glucose in part by decreasing which hepatic process, mediated by increased fructose-2,6-bisphosphate?", "o": {"A": "Glycogenolysis", "B": "Glycolysis", "C": "Gluconeogenesis", "D": "Ketogenesis"}, "r": "C", "e": {"correcta": "Insulin increases fructose-2,6-bisphosphate, which activates phosphofructokinase-1 (favoring glycolysis) and inhibits fructose-1,6-bisphosphatase, thereby suppressing gluconeogenesis. This decrease in hepatic glucose production is a key mechanism by which insulin lowers blood glucose; in insulin resistance, this brake is lost, leading to increased hepatic glucose output.", "incorrectas": {"A": "Glycogenolysis (glycogen breakdown) is inhibited by insulin as well, but the specific mechanism involving increased fructose-2,6-bisphosphate acts on the gluconeogenesis/glycolysis switch point, not directly on glycogen phosphorylase.", "B": "Glycolysis is actually stimulated, not decreased, by increased fructose-2,6-bisphosphate, since this metabolite activates PFK-1; insulin promotes glycolysis while suppressing the opposing pathway of gluconeogenesis.", "D": "Ketogenesis is suppressed by insulin through decreased fatty acid delivery to the liver, but this occurs via effects on lipolysis and malonyl-CoA/CPT1, not through the fructose-2,6-bisphosphate-mediated control of gluconeogenesis described here."}}}, {"id": "anking-endocrine-physiology-1483", "fuente": "anking", "tema": 23, "anki": "1462128243453", "q": "In adipose tissue, insulin stimulates fat deposition while inhibiting which catabolic process?", "o": {"A": "Lipolysis", "B": "Fatty acid synthesis", "C": "Glucose uptake", "D": "Triglyceride synthesis"}, "r": "A", "e": {"correcta": "Insulin promotes triglyceride synthesis and storage in adipocytes while simultaneously inhibiting lipolysis (breakdown of stored triglycerides into free fatty acids and glycerol), largely by suppressing hormone-sensitive lipase activity. In insulin resistance, this brake on lipolysis is lost, contributing to elevated triglycerides and low HDL.", "incorrectas": {"B": "Fatty acid synthesis is actually stimulated, not inhibited, by insulin, as it promotes lipogenesis and triglyceride storage rather than opposing it.", "C": "Glucose uptake into adipocytes (via GLUT4) is stimulated by insulin, providing substrate for triglyceride synthesis, rather than being an inhibited process.", "D": "Triglyceride synthesis is stimulated, not inhibited, by insulin; the question is asking about the catabolic process insulin suppresses, which is lipolysis, not the anabolic process it promotes."}}}, {"id": "anking-endocrine-physiology-1484", "fuente": "anking", "tema": 23, "anki": "1462128264089", "q": "Insulin inhibits hepatic formation of which compound by decreasing fatty acid degradation and thus limiting available acetyl-CoA substrate?", "o": {"A": "Glycogen", "B": "Ketoacids", "C": "Cholesterol", "D": "Urea"}, "r": "B", "e": {"correcta": "Insulin decreases lipolysis and fatty acid oxidation in the liver, reducing the acetyl-CoA pool that would otherwise be shunted into ketoacid (ketone body) synthesis. This is why adequate insulin prevents ketogenesis, and its absence (as in type 1 diabetes) permits unchecked ketoacid formation leading to diabetic ketoacidosis.", "incorrectas": {"A": "Glycogen formation is actually promoted, not inhibited, by insulin, which stimulates glycogen synthase activity; this is the opposite effect from what is being asked about ketoacid suppression.", "C": "Cholesterol synthesis is not the process being limited by decreased acetyl-CoA availability in this context; the classic insulin effect highlighted here is suppression of ketogenesis, not cholesterol metabolism.", "D": "Urea production relates to amino acid catabolism and ammonia disposal, not to the acetyl-CoA-dependent ketoacid formation pathway that insulin suppresses via reduced fatty acid degradation."}}}, {"id": "anking-endocrine-physiology-1485", "fuente": "anking", "tema": 23, "anki": "1462128347237", "q": "Insulin increases cellular uptake of potassium by increasing the activity of which transporter?", "o": {"A": "Na+-K+-ATPase", "B": "Na+/glucose cotransporter (SGLT)", "C": "Na+/H+ exchanger", "D": "Ca2+-ATPase"}, "r": "A", "e": {"correcta": "Insulin increases the activity of the Na+-K+-ATPase pump on cell membranes, driving potassium into cells (along with sodium extrusion). This is the basis for using insulin (with glucose) clinically to treat hyperkalemia by shifting potassium intracellularly.", "incorrectas": {"B": "SGLT transporters mediate secondary active transport of glucose coupled to sodium in tissues like the renal tubule and gut, and are not the mechanism by which insulin shifts potassium into cells.", "C": "The Na+/H+ exchanger regulates intracellular pH and sodium levels but is not the primary transporter insulin upregulates to drive potassium into cells.", "D": "Ca2+-ATPase pumps calcium out of the cytosol and is unrelated to insulin's potassium-shifting effect, which specifically involves stimulation of the Na+-K+-ATPase."}}}, {"id": "anking-endocrine-physiology-1486", "fuente": "anking", "tema": 23, "anki": "1462128367235", "q": "What is the effect of insulin on blood potassium (K+) and amino acid concentrations?", "o": {"A": "Both increase due to decreased cellular uptake", "B": "Both decrease due to increased cellular uptake", "C": "K+ increases while amino acids decrease", "D": "K+ decreases while amino acids increase"}, "r": "B", "e": {"correcta": "Insulin increases cellular uptake of both potassium (via stimulation of Na+-K+-ATPase) and amino acids (into tissues like muscle), which lowers their concentrations in the blood. This dual effect is exploited clinically, for example when insulin/glucose is given to acutely treat hyperkalemia.", "incorrectas": {"A": "Insulin increases, not decreases, cellular uptake of both K+ and amino acids; the resulting blood concentrations fall rather than rise.", "C": "Both K+ and amino acids move in the same direction (decreasing) under insulin's influence, since insulin promotes uptake of both into cells rather than affecting them in opposite directions.", "D": "This describes an inverse relationship between K+ and amino acids that does not occur; insulin decreases blood levels of both by driving them into cells simultaneously."}}}, {"id": "anking-endocrine-physiology-1487", "fuente": "anking", "tema": 23, "anki": "1462128398864", "q": "Regarding placental transfer, which of the following correctly describes whether glucose and insulin cross the placenta?", "o": {"A": "Neither glucose nor insulin crosses the placenta", "B": "Both glucose and insulin cross the placenta", "C": "Glucose crosses the placenta; insulin does not", "D": "Insulin crosses the placenta; glucose does not"}, "r": "C", "e": {"correcta": "Glucose readily crosses the placenta via facilitated diffusion (GLUT transporters) to supply the fetus, whereas maternal insulin does not cross the placenta. This is why maternal hyperglycemia (e.g., in gestational diabetes) drives fetal hyperinsulinemia, as the fetal pancreas must produce its own insulin in response to the glucose load.", "incorrectas": {"A": "Glucose does cross the placenta; if it did not, the fetus would have no maternal glucose supply, which is essential for fetal energy needs and growth.", "B": "Insulin is too large and is specifically excluded from placental transfer; only glucose crosses, which is why fetal hyperglycemia from maternal diabetes must be managed by the fetus's own insulin secretion.", "D": "This reverses the actual relationship: it is glucose that crosses the placenta, while insulin does not, explaining why fetal insulin levels reflect fetal (not maternal) insulin secretion."}}}, {"id": "anking-endocrine-pathology-1488", "fuente": "anking", "tema": 5, "anki": "1462128405138", "q": "In a patient with diabetes mellitus, blood concentrations of amino acids and fatty acids are typically what, due to decreased insulin activity?", "o": {"A": "Decreased", "B": "Increased", "C": "Unchanged", "D": "Amino acids increased, fatty acids decreased"}, "r": "B", "e": {"correcta": "In diabetes mellitus, insufficient insulin action fails to suppress protein catabolism and lipolysis, so blood levels of amino acids and fatty acids rise. This reflects the loss of insulin's normal anabolic, anti-catabolic actions on muscle and adipose tissue.", "incorrectas": {"A": "A decrease would be expected if insulin action were excessive (as in exogenous insulin overdose), not in the setting of insulin deficiency or resistance seen in diabetes, where catabolism is unchecked.", "C": "Levels are not unchanged; the marked reduction in insulin signaling in diabetes actively drives increased breakdown of protein and fat stores, raising circulating substrate levels.", "D": "Both amino acids and fatty acids rise together in diabetes because both protein catabolism and lipolysis are increased by the same underlying insulin deficiency, not in opposite directions."}}}, {"id": "anking-endocrine-pathology-1489", "fuente": "anking", "tema": 5, "anki": "1462128449086", "q": "What is the primary cause of metabolic acidosis in a patient with diabetes mellitus?", "o": {"A": "Increased production of ketoacids", "B": "Renal bicarbonate wasting", "C": "Lactic acid accumulation from tissue hypoperfusion", "D": "Excess dietary acid intake"}, "r": "A", "e": {"correcta": "In diabetes, insulin deficiency permits unchecked lipolysis and hepatic fatty acid oxidation, generating excess acetyl-CoA that is converted into ketoacids (beta-hydroxybutyrate and acetoacetate). Accumulation of these ketoacids produces an anion-gap metabolic acidosis, which may trigger compensatory hyperventilation (Kussmaul breathing).", "incorrectas": {"B": "Renal bicarbonate wasting is a feature of renal tubular acidosis, not the primary mechanism of diabetic ketoacidosis, which is driven by overproduction of acid (ketoacids) rather than loss of buffering capacity.", "C": "Lactic acidosis can occur in severe diabetic complications with poor perfusion, but the classic and primary cause of metabolic acidosis in diabetes is ketoacid overproduction from unrestrained lipolysis and ketogenesis.", "D": "Excess dietary acid intake is not a recognized mechanism of diabetic metabolic acidosis; the acidosis arises from endogenous ketoacid production driven by insulin deficiency."}}}, {"id": "anking-endocrine-pathology-1490", "fuente": "anking", "tema": 5, "anki": "1462128459898", "q": "What is the expected blood potassium concentration in a patient with diabetes mellitus, and why?", "o": {"A": "Decreased, due to increased renal excretion", "B": "Normal, because insulin does not affect potassium", "C": "Increased (hyperkalemia), due to decreased K+ uptake into cells", "D": "Decreased, due to increased K+ uptake into cells"}, "r": "C", "e": {"correcta": "Because insulin normally drives potassium into cells via the Na+-K+-ATPase, insulin deficiency in diabetes mellitus impairs this cellular uptake, resulting in hyperkalemia. Note that total body potassium may actually be depleted (due to osmotic diuresis), but the serum concentration is often elevated because potassium shifts out of cells.", "incorrectas": {"A": "While osmotic diuresis in diabetes can cause total body potassium depletion over time, the immediate effect on serum potassium from lack of insulin is a rise (hyperkalemia), not a fall from renal losses alone.", "B": "Insulin has a well-established, clinically important effect on potassium distribution via stimulation of the Na+-K+-ATPase; ignoring this effect is inaccurate and is the basis for insulin's use in treating hyperkalemia.", "D": "Decreased K+ uptake into cells (not increased) is what occurs with insulin deficiency, and this causes serum potassium to rise rather than fall."}}}, {"id": "anking-endocrine-physiology-1491", "fuente": "anking", "tema": 23, "anki": "1462130433532", "q": "Which pancreatic hormone belongs to the same peptide family as the GI hormones secretin and GIP?", "o": {"A": "Insulin", "B": "Somatostatin", "C": "Glucagon", "D": "Pancreatic polypeptide"}, "r": "C", "e": {"correcta": "Glucagon is a member of the secretin/glucagon peptide hormone superfamily, which also includes secretin, GIP (glucose-dependent insulinotropic peptide), VIP, and GLP-1. These hormones share structural homology and act through G protein-coupled receptors linked to cAMP signaling.", "incorrectas": {"A": "Insulin belongs to a distinct family related structurally to insulin-like growth factors (IGF-1 and IGF-2), and signals through a receptor tyrosine kinase rather than a cAMP-linked GPCR, unlike the secretin/glucagon family.", "B": "Somatostatin is a small cyclic peptide with its own distinct receptor family (somatostatin receptors, SSTRs) and is not classified within the secretin/glucagon peptide family.", "D": "Pancreatic polypeptide belongs to the neuropeptide Y (NPY) family along with peptide YY, a separate structural and functional grouping from the secretin/glucagon family that includes glucagon, secretin, and GIP."}}}, {"id": "anking-endocrine-physiology-1492", "fuente": "anking", "tema": 23, "anki": "1462131701878", "q": "Besides the liver, on which other tissue does glucagon act to increase blood glucose and mobilize energy stores?", "o": {"A": "Skeletal muscle", "B": "Adipose tissue", "C": "Pancreatic beta cells", "D": "Renal tubular cells"}, "r": "B", "e": {"correcta": "Glucagon acts primarily on the liver (promoting gluconeogenesis and glycogenolysis while decreasing glycolysis) and secondarily on adipose tissue, where it increases adipose triglyceride lipase activity, releasing non-esterified fatty acids, and reduces malonyl-CoA, permitting fatty acid oxidation.", "incorrectas": {"A": "Skeletal muscle lacks significant glucagon receptor expression and is not a primary target of glucagon action; muscle glycogenolysis is instead regulated mainly by epinephrine and local factors, not circulating glucagon.", "C": "Glucagon acts on pancreatic alpha cells (its cell of origin) in an autocrine/paracrine sense and can influence beta cells indirectly, but this is not the classic target tissue relationship described for glucagon's metabolic actions.", "D": "Renal tubular cells are not a primary target of glucagon's metabolic actions; glucagon's key peripheral effects are on hepatic and adipose metabolism, not renal glucose handling."}}}, {"id": "anking-endocrine-physiology-1493", "fuente": "anking", "tema": 23, "anki": "1462131726115", "q": "What is the major physiologic stimulus for glucagon secretion?", "o": {"A": "Hyperglycemia", "B": "Hypoglycemia", "C": "Elevated plasma amino acids alone", "D": "Increased somatostatin"}, "r": "B", "e": {"correcta": "Hypoglycemia is the major stimulus for glucagon secretion from pancreatic alpha cells. Low blood glucose triggers glucagon release, which then acts on the liver to raise blood glucose through glycogenolysis and gluconeogenesis, restoring euglycemia.", "incorrectas": {"A": "Hyperglycemia actually suppresses glucagon secretion, since glucagon's role is to counteract low blood sugar, not high blood sugar; hyperglycemia instead stimulates insulin release.", "C": "While amino acids can stimulate glucagon secretion (important to prevent hypoglycemia after a protein-only meal), this is not the major or primary physiologic stimulus compared to hypoglycemia.", "D": "Somatostatin inhibits, rather than increases, glucagon secretion; it would not serve as a stimulus for glucagon release."}}}, {"id": "anking-endocrine-physiology-1494", "fuente": "anking", "tema": 23, "anki": "1462131783153", "q": "What effect does insulin have on glucagon secretion from pancreatic alpha cells?", "o": {"A": "Increased secretion", "B": "No effect", "C": "Decreased secretion", "D": "Biphasic secretion, initially increased then decreased"}, "r": "C", "e": {"correcta": "Insulin, acting in a paracrine fashion within the pancreatic islets, decreases glucagon secretion from neighboring alpha cells. Glucagon secretion is also decreased by hyperglycemia and by somatostatin, reflecting the integrated regulation of the islet to prevent excessive glucose-raising signals when glucose is already adequate.", "incorrectas": {"A": "An increase would be counterproductive physiologically, since insulin and glucagon have opposing actions on blood glucose; insulin suppresses, rather than promotes, glucagon release.", "B": "Insulin has a clear inhibitory paracrine effect on alpha cells within the islet; claiming no effect ignores this important local regulatory relationship between beta and alpha cells.", "D": "There is no established biphasic pattern where insulin first increases then decreases glucagon secretion; the well-documented effect is a straightforward inhibition."}}}, {"id": "anking-endocrine-physiology-1495", "fuente": "anking", "tema": 23, "anki": "1462131799037", "q": "Through which second messenger does glucagon primarily exert its actions on liver and adipose tissue?", "o": {"A": "IP3/DAG", "B": "cGMP", "C": "cAMP", "D": "Calcium-calmodulin"}, "r": "C", "e": {"correcta": "Glucagon binds a Gs-coupled receptor on hepatocytes and adipocytes, activating adenylate cyclase to generate cAMP. This second messenger activates protein kinase A, which phosphorylates key enzymes to promote glycogenolysis, gluconeogenesis, and lipolysis.", "incorrectas": {"A": "IP3/DAG signaling is characteristic of Gq-coupled receptors (e.g., alpha-1 adrenergic receptors), not the glucagon receptor, which couples to Gs and cAMP instead.", "B": "cGMP is the second messenger for receptors like the ANP receptor (guanylate cyclase) and is not involved in glucagon's mechanism of action on liver and adipose tissue.", "D": "Calcium-calmodulin signaling is prominent in Gq-linked pathways and various calcium-dependent processes, but it is not the primary mediator of glucagon's actions, which rely on the Gs/cAMP/PKA cascade."}}}, {"id": "anking-endocrine-physiology-1496", "fuente": "anking", "tema": 23, "anki": "1462131802276", "q": "Glucagon raises blood glucose in part by increasing which hepatic process, while simultaneously inhibiting glycogen synthesis?", "o": {"A": "Glycogenolysis", "B": "Fatty acid synthesis", "C": "Protein synthesis", "D": "Ketogenesis"}, "r": "A", "e": {"correcta": "Glucagon activates hepatic glycogen phosphorylase, increasing glycogenolysis (breakdown of stored glycogen into glucose), while simultaneously inhibiting glycogen synthase, blocking new glycogen formation from glucose. Together, these actions rapidly mobilize glucose stores to raise blood glucose during fasting or hypoglycemia.", "incorrectas": {"B": "Fatty acid synthesis is inhibited, not increased, by glucagon, which instead favors fatty acid oxidation and ketogenesis rather than lipogenesis, consistent with its overall catabolic, fasting-state role.", "C": "Protein synthesis is not the process being described in this glycogen-related mechanism; glucagon's action here specifically concerns glucose storage and release via glycogen metabolism.", "D": "While glucagon does promote ketogenesis as part of its broader catabolic actions, the specific process paired with inhibited glycogen synthesis in this question is glycogenolysis, not ketogenesis."}}}, {"id": "anking-endocrine-physiology-1497", "fuente": "anking", "tema": 23, "anki": "1462131823875", "q": "Glucagon increases blood glucose concentration by increasing gluconeogenesis, mediated through what change in fructose-2,6-bisphosphate levels?", "o": {"A": "Increased production of fructose-2,6-bisphosphate", "B": "No change in fructose-2,6-bisphosphate", "C": "Decreased production of fructose-2,6-bisphosphate", "D": "Increased degradation of fructose-1,6-bisphosphate only"}, "r": "C", "e": {"correcta": "Glucagon decreases hepatic fructose-2,6-bisphosphate levels, which relieves inhibition of fructose-1,6-bisphosphatase and reduces activation of phosphofructokinase-1. This shifts the metabolic balance toward gluconeogenesis and away from glycolysis, raising blood glucose, the opposite of insulin's effect on this regulatory metabolite.", "incorrectas": {"A": "Increased fructose-2,6-bisphosphate is the effect of insulin, which promotes glycolysis and suppresses gluconeogenesis; glucagon acts in the opposite direction, decreasing this metabolite.", "B": "Fructose-2,6-bisphosphate levels do change significantly with glucagon signaling; this metabolite is a key regulatory point specifically targeted by the glucagon-driven PKA cascade (via phosphorylation of PFK-2/FBPase-2).", "D": "The mechanism centers on decreased fructose-2,6-bisphosphate synthesis (via inhibition of PFK-2) rather than isolated changes in fructose-1,6-bisphosphate degradation alone."}}}, {"id": "anking-endocrine-physiology-1498", "fuente": "anking", "tema": 23, "anki": "1462131831506", "q": "Glucagon causes what combination of changes in fatty acid metabolism that shunts substrates toward gluconeogenesis?", "o": {"A": "Increased fatty acid synthesis and decreased lipolysis", "B": "Decreased fatty acid synthesis and increased lipolysis", "C": "No change in either fatty acid synthesis or lipolysis", "D": "Increased fatty acid synthesis and increased lipolysis"}, "r": "B", "e": {"correcta": "Glucagon decreases fatty acid synthesis (by lowering malonyl-CoA, which normally inhibits fat oxidation) and increases lipolysis (breakdown of stored triglycerides). This combination frees up glycerol and reduces competing lipogenic substrate use, effectively shunting carbon substrates and priority toward hepatic gluconeogenesis.", "incorrectas": {"A": "This describes the opposite, anabolic pattern seen with insulin (which increases fat synthesis and decreases lipolysis), not the catabolic, glucose-raising actions of glucagon.", "C": "Glucagon has clear, opposing effects on both processes; asserting no change ignores its well-established catabolic actions on adipose tissue during fasting or hypoglycemia.", "D": "Fatty acid synthesis and lipolysis are being pushed in opposite directions by glucagon (synthesis down, lipolysis up), not increased together, which would be metabolically contradictory (simultaneously building up and breaking down fat)."}}}, {"id": "anking-endocrine-physiology-1499", "fuente": "anking", "tema": 23, "anki": "1462131849821", "q": "What is the effect of glucagon on blood fatty acid and ketoacid concentrations?", "o": {"A": "Decreased, due to decreased lipolysis", "B": "Increased, due to increased lipolysis", "C": "No change in either", "D": "Fatty acids increased, ketoacids decreased"}, "r": "B", "e": {"correcta": "Glucagon increases lipolysis in adipose tissue, releasing free fatty acids into the blood. These fatty acids are then oxidized in the liver, generating acetyl-CoA that can be converted into ketoacids, so both fatty acid and ketoacid concentrations rise under glucagon's influence, particularly during prolonged fasting or insulin deficiency.", "incorrectas": {"A": "A decrease would be the expected effect of insulin, which inhibits lipolysis; glucagon does the opposite, stimulating lipolysis and thus raising, not lowering, fatty acid and ketoacid levels.", "C": "Glucagon has a clear stimulatory effect on lipolysis and subsequent ketogenesis, particularly relevant during fasting states, so asserting no change misses this key catabolic action.", "D": "Both fatty acids and ketoacids rise together because ketoacids are generated directly from the fatty acids mobilized by increased lipolysis; they do not move in opposite directions."}}}, {"id": "anking-endocrine-physiology-1500", "fuente": "anking", "tema": 23, "anki": "1462131857829", "q": "What effect does glucagon have on urea production, and by what mechanism?", "o": {"A": "Decreased, due to decreased amino acid catabolism", "B": "No effect on urea production", "C": "Increased, secondary to increased gluconeogenesis from amino acids", "D": "Increased, due to direct stimulation of the urea cycle independent of amino acid metabolism"}, "r": "C", "e": {"correcta": "Glucagon increases urea production as a secondary consequence of increased gluconeogenesis: amino acids are catabolized and used as gluconeogenic substrate, and the amino groups released from this process are incorporated into urea for disposal, raising urea synthesis.", "incorrectas": {"A": "Amino acid catabolism is actually increased, not decreased, under glucagon's influence, as amino acids are mobilized to fuel gluconeogenesis, which in turn increases urea production as a byproduct.", "B": "Glucagon does have a notable indirect effect on urea production through its stimulation of gluconeogenesis from amino acids, which is the basis for the increased urea seen with high glucagon states.", "D": "The rise in urea is not from direct stimulation of urea cycle enzymes independent of amino acid supply; it results specifically from the increased amino acid flux into gluconeogenesis providing more nitrogen substrate for urea synthesis."}}}, {"id": "anking-endocrine-physiology-1501", "fuente": "anking", "tema": 23, "anki": "1462131869971", "q": "Which of the following nutrients stimulates the release of somatostatin from pancreatic delta cells?", "o": {"A": "Glucose only", "B": "Amino acids only", "C": "Fatty acids only", "D": "Glucose, amino acids, and fatty acids"}, "r": "D", "e": {"correcta": "All three major macronutrient-derived substrates, glucose, amino acids, and fatty acids, stimulate somatostatin release from pancreatic delta cells after a meal. This broad nutrient sensitivity allows somatostatin to act as a general brake on islet hormone secretion (inhibiting both insulin and glucagon) once fuel substrates are abundant.", "incorrectas": {"A": "Glucose alone is an incomplete answer since amino acids and fatty acids also independently stimulate somatostatin secretion, reflecting delta cells' broad nutrient-sensing role.", "B": "Amino acids alone is incomplete because glucose and fatty acids are equally capable of triggering somatostatin release from pancreatic delta cells after nutrient intake.", "C": "Fatty acids alone is incomplete, as glucose and amino acids also serve as effective stimuli for somatostatin secretion, making this only one of three relevant stimulants."}}}, {"id": "anking-gastrointestinal-physiology-1502", "fuente": "anking", "tema": 39, "anki": "1462131874456", "q": "What effect does insulin have on somatostatin secretion from pancreatic delta cells?", "o": {"A": "Increased secretion", "B": "Decreased secretion", "C": "No effect", "D": "Insulin stimulates somatostatin only in the fasting state"}, "r": "B", "e": {"correcta": "Insulin decreases somatostatin secretion, reflecting complex paracrine cross-talk within the pancreatic islet among beta, alpha, and delta cells. This reciprocal regulation helps fine-tune the overall balance of islet hormone output in response to nutrient status.", "incorrectas": {"A": "An increase would be inconsistent with the inhibitory paracrine relationship that has been established between insulin and somatostatin secretion within the islet.", "C": "Insulin does have a demonstrable inhibitory paracrine effect on delta cell somatostatin secretion; claiming no effect overlooks this intra-islet regulatory interaction.", "D": "This inhibitory relationship is not restricted specifically to the fasting state; it reflects a general paracrine effect of insulin secretion on neighboring delta cells whenever insulin is released."}}}, {"id": "anking-gastrointestinal-physiology-1503", "fuente": "anking", "tema": 39, "anki": "1462131878424", "q": "What effect does somatostatin have on insulin and glucagon secretion from the pancreatic islets?", "o": {"A": "Increases both", "B": "Decreases both", "C": "Increases insulin, decreases glucagon", "D": "Has no significant effect on either"}, "r": "B", "e": {"correcta": "Somatostatin acts as a broad paracrine inhibitor within the pancreatic islet, decreasing secretion of both insulin from beta cells and glucagon from alpha cells. It also inhibits gastrin secretion in the GI tract, consistent with its general role in suppressing multiple endocrine and exocrine secretory processes.", "incorrectas": {"A": "Somatostatin is inhibitory, not stimulatory, toward islet hormone secretion; it suppresses both insulin and glucagon rather than increasing either.", "C": "Somatostatin decreases both insulin and glucagon secretion in parallel rather than having opposite effects on the two hormones.", "D": "Somatostatin has well-documented, clinically significant inhibitory effects on both insulin and glucagon secretion, which is why somatostatin analogs (e.g., octreotide) are used to treat conditions of hormone excess, such as insulinomas and glucagonomas."}}}, {"id": "anking-endocrine-physiology-1504", "fuente": "anking", "tema": 23, "anki": "1462131885732", "q": "Approximately what percentage of total plasma calcium is bound to plasma proteins (mainly albumin)?", "o": {"A": "10-15%", "B": "40%", "C": "60%", "D": "45-50%"}, "r": "B", "e": {"correcta": "About 40% of total plasma calcium is bound to plasma proteins, primarily albumin. This protein-bound fraction is biologically inactive and not filtered by the glomerulus, which is clinically important since low albumin states can lower total calcium measurements without affecting the physiologically active ionized fraction.", "incorrectas": {"A": "10-15% corresponds to the fraction of calcium complexed to anions such as phosphate, sulfate, and citrate, not the protein-bound fraction.", "C": "60% represents the ultrafilterable fraction of calcium (the sum of the ionized and anion-complexed forms), not the protein-bound portion specifically.", "D": "45-50% corresponds to the ionized (free) calcium fraction, which is the biologically active form, not the fraction bound to plasma proteins."}}}, {"id": "anking-endocrine-physiology-1505", "fuente": "anking", "tema": 23, "anki": "1462133613898", "q": "Approximately what percentage of total plasma calcium is ultrafilterable (i.e., not bound to plasma protein)?", "o": {"A": "40%", "B": "60%", "C": "10-15%", "D": "90%"}, "r": "B", "e": {"correcta": "About 60% of total plasma calcium is ultrafilterable, meaning it is small enough to pass through the glomerular filtration barrier. This ultrafilterable fraction is the sum of the ionized (free) calcium and the calcium complexed to anions like phosphate and citrate.", "incorrectas": {"A": "40% corresponds to the protein-bound fraction of calcium, which is not ultrafilterable since it is attached to large plasma proteins like albumin that cannot cross the glomerular filter.", "C": "10-15% refers specifically to the fraction of calcium complexed to anions, which is only part of, not the entirety of, the ultrafilterable fraction (which also includes ionized calcium).", "D": "90% overstates the ultrafilterable fraction; a substantial portion (about 40%) of plasma calcium remains protein-bound and is excluded from filtration."}}}, {"id": "anking-endocrine-physiology-1506", "fuente": "anking", "tema": 23, "anki": "1462133631167", "q": "What percentage of total plasma calcium exists in the biologically active, ionized (free Ca2+) form?", "o": {"A": "40%", "B": "10-15%", "C": "45-50%", "D": "100%"}, "r": "C", "e": {"correcta": "About 45-50% of total plasma calcium exists as free, ionized Ca2+, which is the only form that is biologically active, participating in processes like neuromuscular signaling, coagulation, and hormone secretion. This is why ionized calcium, rather than total calcium, is the more accurate clinical measure of physiologically relevant calcium status.", "incorrectas": {"A": "40% corresponds to the protein-bound fraction, which is biologically inactive since it is not free to interact with calcium-sensing mechanisms or participate in cellular signaling.", "B": "10-15% is the fraction of calcium complexed to anions such as phosphate and citrate, a smaller, non-ionized component distinct from the free ionized fraction.", "D": "100% is incorrect because a substantial portion of plasma calcium is either protein-bound or complexed to anions, and only about half exists in the free, biologically active ionized form."}}}, {"id": "anking-endocrine-physiology-1507", "fuente": "anking", "tema": 23, "anki": "1462133649729", "q": "What percentage of total plasma calcium is complexed to anions such as phosphate, sulfate, and citrate?", "o": {"A": "45-50%", "B": "40%", "C": "10-15%", "D": "60%"}, "r": "C", "e": {"correcta": "About 10-15% of total plasma calcium is complexed to anions such as phosphate, sulfate, and citrate. This small anion-bound fraction, together with the ionized fraction, makes up the ultrafilterable portion of plasma calcium (about 60% total).", "incorrectas": {"A": "45-50% is the ionized (free) fraction of calcium, the biologically active form, which is distinct from and larger than the small anion-complexed fraction.", "B": "40% represents the fraction of calcium bound to plasma proteins like albumin, a separate, non-ultrafilterable pool distinct from the anion-complexed calcium.", "D": "60% is the total ultrafilterable fraction, which includes both the ionized calcium and the anion-complexed calcium combined, not the anion-complexed portion alone."}}}, {"id": "anking-endocrine-physiology-1508", "fuente": "anking", "tema": 23, "anki": "1462133657540", "q": "Which fraction of total plasma calcium is the only biologically active form?", "o": {"A": "Calcium bound to albumin", "B": "Calcium complexed with phosphate/citrate/sulfate", "C": "Free, ionized Ca2+", "D": "Calcium bound to calbindin"}, "r": "C", "e": {"correcta": "Only the free, ionized fraction of plasma Ca2+ (about 50% of total) is biologically active and available to participate in neuromuscular signaling, coagulation, and enzyme function. The remaining calcium is either protein-bound (mainly to albumin) or complexed with anions, and neither of these forms can interact with cellular targets.", "incorrectas": {"A": "Roughly 40% of plasma calcium is bound to albumin, but this bound fraction is biologically inert; it serves as a buffer/reservoir and changes with albumin concentration, not as the active signaling form.", "B": "About 10% of plasma calcium is complexed with anions such as phosphate, citrate, and sulfate; like albumin-bound calcium, this fraction is not free to interact with receptors or channels and is therefore inactive.", "D": "Calbindin is an intracellular vitamin D-dependent calcium-binding protein found in intestinal enterocytes and renal tubular cells that facilitates transcellular Ca2+ transport; it is not a plasma calcium fraction."}}}, {"id": "anking-endocrine-physiology-1509", "fuente": "anking", "tema": 23, "anki": "1462133663173", "q": "A patient presents with hyperreflexia, spontaneous muscle twitching, cramping, and perioral tingling/numbness. Which calcium disturbance best explains this presentation?", "o": {"A": "Hypercalcemia", "B": "Hypocalcemia", "C": "Hypermagnesemia", "D": "Hypophosphatemia"}, "r": "B", "e": {"correcta": "Hypocalcemia lowers the threshold for neuronal and muscular depolarization, producing a hyperexcitable state manifested as hyperreflexia, tetany-like twitching, cramping, and paresthesias (classically perioral and in the extremities). This is an early clue to hypoparathyroidism.", "incorrectas": {"A": "Hypercalcemia produces the opposite picture: it raises the depolarization threshold, causing hyporeflexia, muscle weakness, constipation, and lethargy rather than hyperexcitability.", "C": "Hypermagnesemia also decreases neuromuscular excitability, causing hyporeflexia and lethargy (and at high levels, respiratory depression); it does not cause the hyperexcitable tetany picture described here.", "D": "Hypophosphatemia typically causes muscle weakness, bone pain, and rhabdomyolysis in severe cases, but it is not the classic cause of the hyperreflexia/tetany syndrome described, which is specific to low ionized calcium."}}}, {"id": "anking-endocrine-physiology-1510", "fuente": "anking", "tema": 23, "anki": "1462133704288", "q": "What is the underlying electrophysiologic mechanism by which hypocalcemia produces tingling, numbness, twitching, and cramping?", "o": {"A": "Decreased extracellular Ca2+ makes the threshold potential more negative, so the membrane potential is closer to threshold", "B": "Decreased extracellular Ca2+ hyperpolarizes the resting membrane potential", "C": "Decreased extracellular Ca2+ increases sodium channel inactivation", "D": "Decreased extracellular Ca2+ increases potassium conductance at rest"}, "r": "A", "e": {"correcta": "Extracellular Ca2+ normally stabilizes voltage-gated Na+ channels, keeping the threshold potential relatively less negative (harder to reach). When Ca2+ falls, the threshold potential becomes more negative, moving it closer to the resting membrane potential, so smaller depolarizing stimuli trigger action potentials — producing the hyperexcitability seen as perioral tingling, numbness, and muscle twitching/cramping, an early sign of hypoparathyroidism.", "incorrectas": {"B": "Hypocalcemia does not hyperpolarize the resting membrane potential; the resting potential is largely unchanged, while it is the threshold that shifts closer to it, narrowing the gap needed for firing.", "C": "Low Ca2+ actually makes it easier for Na+ channels to open (destabilizes the channel's voltage sensor), rather than increasing their inactivation, which would reduce excitability, the opposite of what is observed.", "D": "Increased resting potassium conductance would hyperpolarize the cell and reduce excitability; the hyperexcitability of hypocalcemia is explained by the threshold shift on sodium channels, not a change in potassium conductance."}}}, {"id": "anking-endocrine-physiology-1511", "fuente": "anking", "tema": 23, "anki": "1462133718268", "q": "A patient presents with constipation, polyuria, polydipsia, lethargy, and hyporeflexia. Which calcium disturbance is most consistent with this picture?", "o": {"A": "Hypocalcemia", "B": "Hypercalcemia", "C": "Hypokalemia", "D": "Hyponatremia"}, "r": "B", "e": {"correcta": "Hypercalcemia raises the threshold potential, reducing neuromuscular excitability and producing \"stones, bones, groans, and psychiatric overtones\": nephrogenic diabetes insipidus-like polyuria/polydipsia (impaired ADH responsiveness), GI hypomotility causing constipation, lethargy, and hyporeflexia.", "incorrectas": {"A": "Hypocalcemia causes the opposite, hyperexcitable picture (hyperreflexia, tingling, cramping, tetany), not the hyporeflexic, lethargic, constipated presentation described here.", "C": "Hypokalemia can cause muscle weakness and ileus-like constipation but is not associated with polyuria/polydipsia in the same mechanism and does not classically produce this exact symptom cluster.", "D": "Hyponatremia typically presents with neurologic symptoms related to cerebral edema (confusion, seizures) rather than this specific combination of GI, renal, and neuromuscular findings tied to serum calcium."}}}, {"id": "anking-renal-physiology-1512", "fuente": "anking", "tema": 12, "anki": "1462133746777", "q": "What happens to the concentration of free ionized Ca2+ during acidemia?", "o": {"A": "It decreases", "B": "It increases", "C": "It stays the same but total calcium falls", "D": "It oscillates without a net change"}, "r": "B", "e": {"correcta": "In acidemia, excess H+ competes with Ca2+ for binding sites on plasma albumin. As more H+ binds albumin, fewer sites remain available for Ca2+, so more calcium is displaced into the free, ionized form — producing a relative increase in ionized Ca2+ (functional hypercalcemia) even if total calcium is unchanged.", "incorrectas": {"A": "A decrease in ionized Ca2+ is what occurs with alkalemia, not acidemia; in alkalosis, less H+ occupies albumin's binding sites, leaving more sites open for Ca2+ to bind and lowering the free fraction.", "C": "Acidemia does not necessarily change total plasma calcium; the effect is on the distribution between bound and free calcium, with the ionized fraction rising due to competitive displacement by H+.", "D": "The pH-dependent effect on ionized calcium is a predictable, directional shift (not an oscillation): acidemia consistently increases and alkalemia consistently decreases the ionized fraction via competition for albumin binding sites."}}}, {"id": "anking-renal-physiology-1513", "fuente": "anking", "tema": 12, "anki": "1462133757332", "q": "What happens to the concentration of free ionized Ca2+ during alkalemia?", "o": {"A": "It increases", "B": "It decreases", "C": "It remains unchanged", "D": "It increases only if phosphate also rises"}, "r": "B", "e": {"correcta": "In alkalemia, there is less free H+ available to bind albumin, so more of albumin's negatively charged binding sites are left open for Ca2+. This increased albumin binding pulls Ca2+ out of the free, ionized pool, effectively lowering ionized Ca2+ and producing symptomatic hypocalcemia (e.g., perioral tingling with hyperventilation-induced respiratory alkalosis).", "incorrectas": {"A": "An increase in ionized Ca2+ occurs with acidemia, the opposite acid-base disturbance, where H+ competes with Ca2+ for albumin binding sites and displaces more calcium into the free form.", "C": "Ionized calcium does change with alkalemia because albumin binding capacity for Ca2+ is directly affected by competing H+ ion concentration; the relationship is a well-established acid-base effect, not a null one.", "D": "This effect on ionized calcium is independent of phosphate levels; it is driven purely by the change in H+ concentration altering competitive binding to albumin, not by concurrent phosphate changes."}}}, {"id": "anking-endocrine-physiology-1514", "fuente": "anking", "tema": 23, "anki": "1462133770989", "q": "Which three organ systems are primarily responsible for maintaining calcium homeostasis in the body?", "o": {"A": "Liver, kidney, and intestine", "B": "Bone, kidney, and intestine", "C": "Bone, liver, and pancreas", "D": "Kidney, pancreas, and intestine"}, "r": "B", "e": {"correcta": "Calcium homeostasis is coordinated among bone (the major calcium reservoir, which can release or store calcium), the intestine (site of dietary Ca2+ absorption, regulated by vitamin D), and the kidney (which filters and reabsorbs Ca2+ and excretes the excess in urine). Net intestinal absorption must balance urinary excretion for the body to remain in calcium balance.", "incorrectas": {"A": "The liver plays an important role in vitamin D metabolism (25-hydroxylation) but is not one of the three primary organs directly exchanging calcium with the extracellular fluid; that role belongs to bone, kidney, and intestine.", "C": "The pancreas has no significant direct role in calcium homeostasis; while the liver assists indirectly via vitamin D activation, neither organ substitutes for the kidney's excretory role in the calcium balance system.", "D": "The pancreas is not a calcium-regulating organ; the core homeostatic triad is bone, kidney, and intestine, working together under PTH, vitamin D, and calcitonin regulation."}}}, {"id": "anking-endocrine-physiology-1515", "fuente": "anking", "tema": 23, "anki": "1462133789803", "q": "Which three hormones are the primary regulators of calcium homeostasis?", "o": {"A": "Cortisol, aldosterone, and vitamin D", "B": "Parathyroid hormone, calcitonin, and vitamin D (1,25-dihydroxycholecalciferol)", "C": "Parathyroid hormone, insulin, and calcitonin", "D": "Growth hormone, parathyroid hormone, and vitamin D"}, "r": "B", "e": {"correcta": "PTH (from chief cells of the parathyroid glands) raises serum calcium by acting on bone, kidney, and indirectly the intestine; calcitonin (from parafollicular C cells of the thyroid) opposes PTH by lowering serum calcium; and activated vitamin D (1,25-dihydroxycholecalciferol) increases intestinal calcium absorption. Together these three hormones tightly regulate serum Ca2+.", "incorrectas": {"A": "Cortisol and aldosterone are adrenal steroid hormones involved in glucose/stress metabolism and sodium/potassium balance respectively; neither is a primary regulator of the minute-to-minute calcium homeostasis system.", "C": "Insulin regulates glucose and potassium uptake into cells but has no direct role in calcium homeostasis; the third key hormone in calcium regulation is vitamin D, not insulin.", "D": "Growth hormone influences bone growth over time via IGF-1 but is not part of the acute calcium-regulating hormonal triad; that role belongs to PTH, calcitonin, and vitamin D."}}}, {"id": "anking-endocrine-physiology-1516", "fuente": "anking", "tema": 23, "anki": "1462133797766", "q": "Which demographic group is classically in a positive calcium balance?", "o": {"A": "Postmenopausal women", "B": "Growing children", "C": "Pregnant women", "D": "Elderly men with osteoporosis"}, "r": "B", "e": {"correcta": "Growing children are in positive calcium balance because intestinal Ca2+ absorption exceeds urinary excretion; the surplus calcium is deposited into growing bone as the skeleton lengthens and mineralizes, supporting net bone accretion.", "incorrectas": {"A": "Postmenopausal women tend toward negative calcium balance due to estrogen deficiency, which increases osteoclastic bone resorption and net bone loss, the opposite of the positive balance seen in growing children.", "C": "Pregnant and lactating women are in negative calcium balance, since fetal/mammary calcium demands exceed intestinal absorption, forcing mobilization of calcium from maternal bone stores.", "D": "Elderly individuals with osteoporosis are generally in negative calcium balance, with bone resorption outpacing formation, contrasting with the net calcium accretion seen during childhood growth."}}}, {"id": "anking-endocrine-physiology-1517", "fuente": "anking", "tema": 23, "anki": "1462133805523", "q": "Which demographic group is classically in a negative calcium balance?", "o": {"A": "Growing children", "B": "Young adult men", "C": "Women during pregnancy or lactation", "D": "Postmenopausal women on estrogen replacement"}, "r": "C", "e": {"correcta": "Women during pregnancy or lactation are in negative calcium balance because intestinal Ca2+ absorption is insufficient to meet the demands of fetal skeletal development or milk production; the deficit is made up by mobilizing calcium from maternal bone, which can transiently reduce maternal bone density.", "incorrectas": {"A": "Growing children are in positive, not negative, calcium balance — their intestinal absorption exceeds excretion, and the surplus is deposited into the growing skeleton rather than depleted from it.", "B": "Healthy young adult men are generally in neutral calcium balance, with intestinal absorption matching urinary excretion, since they are neither building new skeleton rapidly nor supplying calcium to a fetus or breast milk.", "D": "Estrogen replacement in postmenopausal women helps maintain bone density by limiting resorption, tending toward a more neutral balance rather than the frank negative balance driven by fetal/lactational calcium demands."}}}, {"id": "anking-endocrine-anatomy-1518", "fuente": "anking", "tema": 25, "anki": "1462135442737", "q": "Parathyroid hormone is synthesized and secreted by which cell type of the parathyroid gland?", "o": {"A": "Parafollicular (C) cells", "B": "Oxyphil cells", "C": "Chief cells", "D": "Follicular cells"}, "r": "C", "e": {"correcta": "Chief cells are the predominant secretory cells of the parathyroid glands and are responsible for synthesizing and releasing PTH in response to changes in serum ionized calcium sensed via the calcium-sensing receptor on their surface.", "incorrectas": {"A": "Parafollicular (C) cells reside in the thyroid gland, not the parathyroid, and secrete calcitonin, which lowers serum calcium — a distinct cell type and hormone from PTH-secreting chief cells.", "B": "Oxyphil cells are also found in the parathyroid gland but their function is not well defined and they are not the primary source of PTH; their number increases with age, but chief cells remain the dominant hormone-secreting cell.", "D": "Follicular cells are found in the thyroid gland, where they produce thyroid hormones (T3/T4), and have no role in parathyroid hormone secretion."}}}, {"id": "anking-endocrine-physiology-1519", "fuente": "anking", "tema": 23, "anki": "1462137178939", "q": "Secretion of parathyroid hormone is primarily regulated by plasma concentration of which substance?", "o": {"A": "Phosphate", "B": "Magnesium", "C": "Calcium", "D": "Vitamin D"}, "r": "C", "e": {"correcta": "PTH secretion from parathyroid chief cells is regulated principally by the plasma concentration of ionized Ca2+, sensed via calcium-sensing receptors (CaSR) on the chief cell membrane. A fall in serum Ca2+ reduces receptor activation and stimulates PTH release, while a rise suppresses it, forming a classic negative feedback loop.", "incorrectas": {"B": "Severe hypomagnesemia can actually impair PTH secretion (and cause PTH resistance), but magnesium is not the primary physiologic regulator of moment-to-moment PTH release; that role belongs to calcium.", "A": "Serum phosphate does influence PTH secretion, largely indirectly by complexing with calcium and lowering ionized Ca2+, but calcium remains the dominant, direct regulator sensed by the parathyroid CaSR.", "D": "Vitamin D (1,25-(OH)2D3) exerts negative feedback on PTH gene transcription over a longer time frame, but it is not the acute, minute-to-minute regulator of PTH secretion — that role is served by plasma Ca2+."}}}, {"id": "anking-endocrine-physiology-1520", "fuente": "anking", "tema": 23, "anki": "1462137205163", "q": "Extracellular calcium regulates PTH secretion by binding to which type of receptor on the parathyroid cell membrane?", "o": {"A": "Receptor tyrosine kinase", "B": "Ca2+-sensing receptor (CaSR)", "C": "Ligand-gated calcium channel", "D": "Nuclear vitamin D receptor"}, "r": "B", "e": {"correcta": "The Ca2+-sensing receptor (CaSR) is a G protein-coupled receptor on the parathyroid chief cell membrane that detects extracellular ionized calcium. Decreased Ca2+ binding to CaSR relieves inhibition and increases PTH secretion, whereas increased Ca2+ binding suppresses PTH release — the fundamental feedback loop controlling calcium homeostasis.", "incorrectas": {"A": "Receptor tyrosine kinases mediate growth factor signaling (e.g., insulin, IGF-1) through intrinsic kinase activity, not calcium sensing; CaSR is a GPCR, structurally and functionally distinct from RTKs.", "C": "Ligand-gated calcium channels allow ion flux across the membrane in response to a ligand (e.g., in neurons or muscle), but they do not mediate the calcium-sensing feedback that controls PTH gene transcription and secretion.", "D": "The vitamin D receptor is a nuclear/intracellular receptor that binds 1,25-(OH)2D3 to regulate gene transcription (including suppressing PTH gene expression), but it is not the surface receptor that senses extracellular calcium directly."}}}, {"id": "anking-endocrine-pathology-1521", "fuente": "anking", "tema": 5, "anki": "1462137262732", "q": "Chronic hypocalcemia (e.g., from chronic kidney disease) leads to which parathyroid condition, characterized by increased PTH synthesis/storage and gland hyperplasia?", "o": {"A": "Primary hyperparathyroidism", "B": "Secondary hyperparathyroidism", "C": "Pseudohypoparathyroidism", "D": "Tertiary hyperparathyroidism"}, "r": "B", "e": {"correcta": "Secondary hyperparathyroidism arises when a chronic stimulus such as persistent hypocalcemia (commonly from chronic kidney disease or vitamin D deficiency) drives sustained PTH secretion, leading to increased synthesis/storage of PTH and compensatory hyperplasia of all four parathyroid glands, in an appropriate physiologic attempt to restore calcium levels.", "incorrectas": {"A": "Primary hyperparathyroidism results from an intrinsic parathyroid gland abnormality (usually an adenoma) autonomously overproducing PTH, causing hypercalcemia — the opposite calcium direction from the hypocalcemia-driven secondary form.", "C": "Pseudohypoparathyroidism is a condition of end-organ (renal) resistance to PTH due to a Gs-alpha protein defect, producing hypocalcemia despite elevated PTH levels, but it is not the gland hyperplasia response to chronic hypocalcemia described here.", "D": "Tertiary hyperparathyroidism develops when long-standing secondary hyperparathyroidism (usually in dialysis patients) causes the parathyroid glands to become autonomous, secreting excess PTH even after the underlying cause is corrected — a later-stage complication, not the initial chronic-hypocalcemia response."}}}, {"id": "anking-renal-physiology-1522", "fuente": "anking", "tema": 12, "anki": "1462137316417", "q": "What effect does an increase in serum phosphate (PO4^3-) have on PTH secretion?", "o": {"A": "Decreases PTH secretion", "B": "Increases PTH secretion", "C": "No effect on PTH secretion", "D": "Suppresses PTH secretion only if calcium is also elevated"}, "r": "B", "e": {"correcta": "Increased serum phosphate stimulates PTH secretion, partly because phosphate complexes with ionized calcium, lowering free Ca2+ and removing the inhibitory signal at the calcium-sensing receptor. In turn, increased PTH promotes phosphate excretion in the urine, forming a feedback loop that helps normalize serum phosphate.", "incorrectas": {"A": "A decrease in PTH secretion would be expected with hypophosphatemia or hypercalcemia, not with rising phosphate, which instead stimulates PTH release via calcium complexing and direct effects on chief cells.", "C": "Phosphate does have a real physiologic effect on PTH secretion; ignoring this relationship would miss the feedback mechanism by which the parathyroid gland compensates for phosphate retention (e.g., in chronic kidney disease).", "D": "The phosphate-PTH relationship does not require concurrent hypercalcemia; elevated phosphate stimulates PTH secretion independently, largely through calcium complexing and direct chief cell effects, regardless of baseline calcium status."}}}, {"id": "anking-renal-physiology-1523", "fuente": "anking", "tema": 12, "anki": "1462137345946", "q": "The net physiologic actions of PTH produce which combination of serum electrolyte changes?", "o": {"A": "Increased serum Ca2+ and increased serum phosphate", "B": "Decreased serum Ca2+ and decreased serum phosphate", "C": "Increased serum Ca2+ and decreased serum phosphate", "D": "Decreased serum Ca2+ and increased serum phosphate"}, "r": "C", "e": {"correcta": "PTH coordinately raises serum calcium (via bone resorption, renal Ca2+ reabsorption, and stimulation of active vitamin D that increases intestinal absorption) while lowering serum phosphate (via decreased renal phosphate reabsorption in the proximal tubule, causing phosphaturia). This dual effect prevents the released bone phosphate from re-complexing with the newly liberated calcium.", "incorrectas": {"A": "PTH does not raise phosphate; in fact it actively promotes renal phosphate wasting, which is essential to keep the released calcium from precipitating with phosphate as calcium phosphate salts.", "B": "Decreased calcium is the opposite of PTH's primary purpose, which is to defend against hypocalcemia by raising serum Ca2+ through bone, kidney, and (indirectly) intestinal actions.", "D": "This describes the pattern of hypoparathyroidism (low PTH activity), not the action of PTH itself, which raises calcium while lowering, not raising, phosphate."}}}, {"id": "anking-renal-physiology-1524", "fuente": "anking", "tema": 12, "anki": "1462137433796", "q": "PTH exerts its effects on bone and kidney predominantly through which intracellular second messenger?", "o": {"A": "IP3/DAG", "B": "cAMP", "C": "cGMP", "D": "Calcium-calmodulin only"}, "r": "B", "e": {"correcta": "PTH binds a Gs protein-coupled receptor (PTH1R) on target cells in bone and kidney, activating adenylate cyclase to generate cAMP as its principal second messenger, which then activates protein kinase A to mediate downstream effects such as renal phosphate excretion and osteoblast-mediated signaling to osteoclasts.", "incorrectas": {"A": "The IP3/DAG pathway is used by Gq-coupled receptors (e.g., alpha-1 adrenergic, angiotensin II AT1) to mobilize intracellular calcium and activate PKC; PTH signaling is primarily Gs/cAMP-mediated, not Gq-mediated.", "C": "cGMP is the second messenger for receptors coupled to guanylate cyclase (e.g., ANP, nitric oxide signaling), an entirely separate pathway from the Gs/adenylate cyclase/cAMP cascade that PTH uses.", "D": "While intracellular calcium-calmodulin signaling can be a downstream consequence of some GPCR pathways, PTH's principal and defining second messenger, especially as measured clinically via urinary cAMP, is cAMP, not a calmodulin-only pathway."}}}, {"id": "anking-renal-physiology-1525", "fuente": "anking", "tema": 12, "anki": "1462137441428", "q": "In bone tissue, PTH receptors are located on which cell type, while the other major bone cell type lacks these receptors?", "o": {"A": "Osteoclasts", "B": "Osteocytes", "C": "Osteoblasts", "D": "Chondrocytes"}, "r": "C", "e": {"correcta": "PTH receptors (PTH1R) are expressed on osteoblasts, not osteoclasts. This means PTH acts directly on osteoblasts, which in turn release paracrine signals (such as RANKL) that indirectly activate osteoclasts to increase bone resorption — an important indirect mechanism tested frequently on exams.", "incorrectas": {"A": "Osteoclasts, the bone-resorbing cells, actually lack PTH receptors; they are stimulated indirectly through osteoblast-derived cytokines rather than by PTH binding them directly.", "B": "Osteocytes are mature, terminally differentiated osteoblasts embedded in bone matrix that sense mechanical strain; they are not the primary direct PTH target cell described in this classic bone-kidney-PTH physiology.", "D": "Chondrocytes are cartilage cells involved in endochondral ossification during growth, not the direct target of PTH signaling in mature bone remodeling, which centers on the osteoblast-osteoclast relationship."}}}, {"id": "anking-renal-physiology-1526", "fuente": "anking", "tema": 12, "anki": "1462137452070", "q": "What is the initial, transient effect of PTH on bone, mediated by direct action on osteoblasts?", "o": {"A": "Increased bone resorption", "B": "Increased bone formation", "C": "Increased chondrocyte proliferation", "D": "Decreased osteoblast number"}, "r": "B", "e": {"correcta": "PTH initially and transiently stimulates bone formation through direct anabolic effects on osteoblasts. This is the physiologic basis for intermittent (pulsatile) administration of synthetic PTH (teriparatide) as an osteoporosis treatment, since brief PTH exposure favors bone-building over bone-resorbing signaling.", "incorrectas": {"A": "Increased bone resorption is the long-term, sustained effect of continuous PTH exposure, mediated indirectly through osteoclast activation via osteoblast-derived cytokines — the opposite of the acute anabolic effect described here.", "C": "Chondrocyte proliferation relates to endochondral bone growth at the growth plate and is not the mechanism by which PTH acutely stimulates osteoblasts to increase bone formation.", "D": "PTH's transient action increases osteoblast activity/formation rather than decreasing osteoblast number; a decrease in osteoblasts would be inconsistent with the anabolic, bone-forming effect being tested."}}}, {"id": "anking-renal-physiology-1527", "fuente": "anking", "tema": 12, "anki": "1462137465195", "q": "What is the long-term (sustained) effect of PTH on bone, and by what mechanism does it occur?", "o": {"A": "Bone formation via direct action on osteoclasts", "B": "Bone resorption via indirect action on osteoclasts", "C": "Bone resorption via direct action on osteoclasts", "D": "Bone formation via indirect action on osteoblasts"}, "r": "B", "e": {"correcta": "With sustained (continuous) exposure, PTH's dominant long-term effect is bone resorption, mediated indirectly through osteoclasts — PTH binds osteoblasts (which express the receptor), and osteoblasts then release cytokines (e.g., RANKL) that increase osteoclast number and activity to break down bone and release Ca2+ and phosphate.", "incorrectas": {"A": "Osteoclasts do not express PTH receptors at all, so PTH cannot act directly on them; furthermore, the long-term effect of sustained PTH is resorption, not formation.", "C": "PTH's action on osteoclasts is indirect, not direct, because osteoclasts lack PTH receptors; the signal must be relayed through osteoblasts via paracrine cytokines.", "D": "Formation is the acute/transient effect of osteoblast stimulation, not the sustained, long-term effect; with prolonged PTH exposure, the net effect shifts toward resorption via the osteoblast-to-osteoclast signaling axis."}}}, {"id": "anking-renal-physiology-1528", "fuente": "anking", "tema": 12, "anki": "1462137479145", "q": "PTH's indirect stimulation of osteoclasts is mediated by cytokines released from which cell type?", "o": {"A": "Osteoclasts themselves (autocrine)", "B": "Chondrocytes", "C": "Osteoblasts", "D": "Renal tubular epithelial cells"}, "r": "C", "e": {"correcta": "Because osteoclasts lack PTH receptors, PTH must act on osteoblasts, which then release paracrine cytokines (notably RANKL, which binds RANK on osteoclast precursors) that increase both the number and activity of osteoclasts, ultimately driving bone resorption.", "incorrectas": {"A": "Osteoclasts do not autonomously respond to PTH via autocrine cytokine release; they depend entirely on paracrine signals originating from osteoblasts, since they lack the PTH receptor themselves.", "B": "Chondrocytes are cartilage cells involved in longitudinal bone growth, not the intermediary cell type in the PTH-osteoblast-osteoclast resorption signaling pathway.", "D": "Renal tubular cells are the site of PTH's direct actions on calcium/phosphate reabsorption and vitamin D activation, but they are unrelated to the bone-specific cytokine signaling that links PTH to osteoclast activation."}}}, {"id": "anking-renal-physiology-1529", "fuente": "anking", "tema": 12, "anki": "1462137495190", "q": "Resorption of the organic (collagenous) matrix of bone by PTH-stimulated osteoclasts is reflected by increased urinary excretion of which compound?", "o": {"A": "Hydroxyproline", "B": "Creatinine", "C": "Uric acid", "D": "Cystine"}, "r": "A", "e": {"correcta": "Hydroxyproline is a modified amino acid unique to collagen. When osteoclasts break down the collagenous organic matrix of bone during PTH-stimulated resorption, hydroxyproline is released and excreted in the urine, making urinary hydroxyproline a marker of bone turnover/resorption.", "incorrectas": {"B": "Creatinine is a byproduct of muscle creatine metabolism used to estimate glomerular filtration rate; it has no relationship to bone matrix breakdown or collagen turnover.", "C": "Uric acid is the end product of purine metabolism, relevant to gout, not a marker of bone collagen resorption.", "D": "Cystine is an amino acid whose excess urinary excretion causes cystinuria and kidney stones, unrelated to collagen breakdown in bone remodeling."}}}, {"id": "anking-renal-physiology-1530", "fuente": "anking", "tema": 12, "anki": "1462137524818", "q": "If PTH acted on bone alone (without its renal actions), would ionized plasma Ca2+ actually increase?", "o": {"A": "Yes, because bone resorption alone is sufficient to raise ionized Ca2+", "B": "No, because the released calcium would complex with the released phosphate without PTH's phosphaturic renal action", "C": "Yes, because osteoclasts directly release only calcium, not phosphate", "D": "No, because bone resorption releases only phosphate, not calcium"}, "r": "B", "e": {"correcta": "Bone resorption releases both calcium and phosphate from the mineral matrix in fixed proportions. Without PTH's renal phosphaturic action (decreased phosphate reabsorption in the proximal tubule), the released phosphate would remain in circulation and re-complex with the released calcium, preventing any net rise in free ionized Ca2+. PTH's renal actions are therefore essential to actually raise ionized calcium.", "incorrectas": {"A": "Bone resorption alone is not sufficient because it releases phosphate along with calcium; without renal phosphate excretion, the two ions would recombine, negating any net increase in free ionized calcium.", "C": "Osteoclastic bone resorption releases both calcium and phosphate together (since bone mineral is hydroxyapatite, a calcium-phosphate salt), not calcium alone.", "D": "Bone resorption releases both minerals from hydroxyapatite, not phosphate exclusively; the key issue is that without renal phosphate excretion, the co-released phosphate binds the calcium back up."}}}, {"id": "anking-renal-physiology-1531", "fuente": "anking", "tema": 12, "anki": "1462137593301", "q": "The cAMP generated by PTH action on the renal proximal tubule can be measured clinically after being excreted in which fluid?", "o": {"A": "Cerebrospinal fluid", "B": "Urine (urinary cAMP)", "C": "Bile", "D": "Synovial fluid"}, "r": "B", "e": {"correcta": "When PTH binds its receptor on proximal tubule cells, it activates adenylate cyclase and generates intracellular cAMP as a second messenger; a portion of this cAMP is excreted into the urine, so urinary cAMP can serve as a clinical marker of PTH bioactivity at the renal tubule (useful in distinguishing PTH-related disorders).", "incorrectas": {"A": "Cerebrospinal fluid is not a site where PTH-generated cAMP is measured; PTH does not act on the central nervous system in this signaling pathway.", "C": "Bile is produced by hepatocytes for lipid digestion and has no role in the PTH-cAMP renal signaling pathway measured clinically.", "D": "Synovial fluid lubricates joints and is unrelated to renal tubular cAMP generation from PTH receptor activation."}}}, {"id": "anking-renal-physiology-1532", "fuente": "anking", "tema": 12, "anki": "1462137618041", "q": "PTH stimulates which renal enzyme that converts 25-hydroxycholecalciferol to the active form of vitamin D?", "o": {"A": "25-hydroxylase", "B": "1α-hydroxylase", "C": "24-hydroxylase", "D": "7-dehydrocholesterol reductase"}, "r": "B", "e": {"correcta": "PTH stimulates renal 1α-hydroxylase (in the proximal tubule), which converts 25-hydroxycholecalciferol (the hepatic product) into 1,25-dihydroxycholecalciferol, the biologically active form of vitamin D. Active vitamin D then increases intestinal calcium (and phosphate) absorption, working alongside PTH's other actions to raise serum calcium.", "incorrectas": {"A": "25-hydroxylase acts in the liver to convert vitamin D (cholecalciferol) into 25-hydroxycholecalciferol, the first activation step, but this occurs in the liver and is not the PTH-stimulated renal enzyme in question.", "C": "24-hydroxylase produces inactive metabolites of vitamin D (e.g., 24,25-dihydroxycholecalciferol) as part of a degradation/inactivation pathway, essentially the opposite function of the activating 1α-hydroxylase.", "D": "7-dehydrocholesterol reductase is involved in cholesterol/vitamin D precursor synthesis in the skin (converting 7-dehydrocholesterol to cholecalciferol with UV light), not in the renal activation step stimulated by PTH."}}}, {"id": "anking-renal-physiology-1533", "fuente": "anking", "tema": 12, "anki": "1462137679566", "q": "By what mechanism does PTH increase intestinal calcium absorption?", "o": {"A": "Directly, by binding PTH receptors on intestinal enterocytes", "B": "Indirectly, by stimulating renal production of 1,25-(OH)2D3", "C": "Directly, by increasing calbindin transcription in enterocytes without vitamin D", "D": "Indirectly, by increasing serum phosphate which enhances calcium uptake"}, "r": "B", "e": {"correcta": "PTH does not act directly on the intestine; instead, it indirectly increases intestinal Ca2+ absorption by stimulating 1α-hydroxylase in the renal proximal tubule, boosting production of active 1,25-dihydroxyvitamin D3, which then acts on enterocytes to upregulate calcium transport proteins (like calbindin) and increase absorption.", "incorrectas": {"A": "Intestinal enterocytes do not express significant PTH receptors that mediate calcium absorption; PTH's influence on the gut is entirely indirect, working through activated vitamin D as the intermediary.", "C": "Calbindin transcription in enterocytes is induced by vitamin D binding its nuclear receptor, not directly by PTH; PTH's role is upstream, stimulating vitamin D activation in the kidney.", "D": "Increased serum phosphate does not enhance intestinal calcium absorption; if anything, phosphate can complex with calcium. The mechanism by which PTH boosts calcium absorption is through vitamin D activation, not phosphate elevation."}}}, {"id": "anking-endocrine-pathology-1534", "fuente": "anking", "tema": 5, "anki": "1462137714771", "q": "What is the most common cause of primary hyperparathyroidism?", "o": {"A": "Parathyroid carcinoma", "B": "Chronic kidney disease", "C": "Parathyroid adenoma", "D": "Vitamin D deficiency"}, "r": "C", "e": {"correcta": "A single parathyroid adenoma is the most common cause of primary hyperparathyroidism, accounting for the majority of cases. The adenoma autonomously secretes excess PTH independent of normal calcium feedback, leading to hypercalcemia, hypophosphatemia, and elevated PTH.", "incorrectas": {"B": "Chronic kidney disease causes secondary (and eventually tertiary) hyperparathyroidism by inducing chronic hypocalcemia/hyperphosphatemia that drives compensatory PTH hypersecretion, but it is not the cause of primary hyperparathyroidism, which is an intrinsic gland disorder.", "A": "Parathyroid carcinoma is a rare cause of primary hyperparathyroidism, typically presenting with markedly elevated calcium and a palpable neck mass, but adenoma is far more common than carcinoma as the underlying etiology.", "D": "Vitamin D deficiency leads to hypocalcemia, which stimulates secondary hyperparathyroidism (an appropriate physiologic response), the opposite scenario from primary hyperparathyroidism's autonomous gland overactivity."}}}, {"id": "anking-endocrine-pathology-1535", "fuente": "anking", "tema": 5, "anki": "1462140487757", "q": "A patient has hypercalcemia, hypophosphatemia, and elevated circulating PTH. Which condition best fits this laboratory profile?", "o": {"A": "Secondary hyperparathyroidism", "B": "Hypoparathyroidism", "C": "Primary hyperparathyroidism", "D": "Pseudohypoparathyroidism"}, "r": "C", "e": {"correcta": "Primary hyperparathyroidism is characterized by autonomous PTH oversecretion (usually from an adenoma), producing hypercalcemia (from increased bone resorption, renal reabsorption, and vitamin D-mediated intestinal absorption) together with hypophosphatemia (from PTH's phosphaturic effect on the renal proximal tubule) — the classic triad tested here.", "incorrectas": {"A": "Secondary hyperparathyroidism also shows elevated PTH, but it develops in response to hypocalcemia or hyperphosphatemia (e.g., in CKD), so serum calcium is typically low or normal, not elevated as in this case.", "B": "Hypoparathyroidism presents with low PTH, low serum calcium, and high serum phosphate, the inverse pattern of the hypercalcemia/hypophosphatemia/high-PTH profile described.", "D": "Pseudohypoparathyroidism involves renal resistance to PTH due to a Gs-alpha defect, causing hypocalcemia and hyperphosphatemia despite elevated PTH — again the opposite electrolyte pattern from primary hyperparathyroidism."}}}, {"id": "anking-renal-physiology-1536", "fuente": "anking", "tema": 12, "anki": "1462140496889", "q": "In primary hyperparathyroidism, what happens to urinary calcium excretion, and why?", "o": {"A": "It decreases, due to increased renal Ca2+ reabsorption overriding the filtered load", "B": "It increases, due to the high filtered load of calcium overwhelming reabsorptive capacity", "C": "It remains unchanged because PTH only affects phosphate handling", "D": "It decreases, because PTH suppresses glomerular filtration of calcium"}, "r": "B", "e": {"correcta": "Although PTH increases tubular calcium reabsorption, in primary hyperparathyroidism the resulting hypercalcemia raises the filtered load of calcium so much that it exceeds the kidney's reabsorptive capacity, leading to net hypercalciuria — a key contributor to the kidney stone risk seen in this disorder.", "incorrectas": {"A": "While PTH does increase fractional reabsorption of calcium per nephron, this is outweighed by the markedly increased filtered load from severe hypercalcemia, so the net effect is increased, not decreased, urinary calcium excretion.", "C": "PTH clearly affects both phosphate and calcium renal handling; it increases calcium reabsorption per se, but the massive filtered load from hypercalcemia still results in net hypercalciuria, so calcium excretion is not unchanged.", "D": "PTH does not suppress glomerular filtration of calcium; the elevated filtered load actually results directly from the elevated plasma calcium concentration being filtered at the glomerulus at a normal or near-normal GFR."}}}, {"id": "anking-endocrine-pathology-1537", "fuente": "anking", "tema": 5, "anki": "1462140513830", "q": "Increased urinary calcium excretion, such as occurs in primary hyperparathyroidism, predisposes to which complication?", "o": {"A": "Uric acid kidney stones", "B": "Struvite kidney stones", "C": "Calcium-oxalate kidney stones", "D": "Cystine kidney stones"}, "r": "C", "e": {"correcta": "Hypercalciuria from primary hyperparathyroidism increases the risk of calcium-oxalate (and calcium-phosphate) kidney stones, one of the classic \"stones\" manifestations of the disease, as excess filtered calcium in the urine precipitates with oxalate to form calculi.", "incorrectas": {"A": "Uric acid stones form in conditions of high purine turnover or persistently acidic urine (e.g., gout, tumor lysis syndrome), not as a direct consequence of hypercalciuria from hyperparathyroidism.", "B": "Struvite stones (magnesium ammonium phosphate) form in the setting of urease-producing bacterial infections (e.g., Proteus), unrelated to the hypercalciuria of hyperparathyroidism.", "D": "Cystine stones result from a genetic defect in renal amino acid transport (cystinuria), a completely separate metabolic disorder from hypercalciuria-induced calcium-oxalate stone formation."}}}, {"id": "anking-renal-physiology-1538", "fuente": "anking", "tema": 12, "anki": "1462140522357", "q": "In primary hyperparathyroidism, what happens to urinary excretion of phosphate, calcium, and cAMP?", "o": {"A": "All three decrease", "B": "Phosphate and cAMP increase, calcium decreases", "C": "All three increase", "D": "All three remain normal"}, "r": "C", "e": {"correcta": "In primary hyperparathyroidism, excess PTH increases urinary phosphate excretion (via decreased proximal tubule reabsorption) and urinary cAMP (the second messenger generated by PTH receptor activation), while urinary calcium also increases because the filtered calcium load from hypercalcemia exceeds tubular reabsorptive capacity — all three rise together.", "incorrectas": {"A": "A decrease in all three would suggest hypoparathyroidism (low PTH activity), the opposite of the excess PTH signaling and hypercalcemia driving these increases in primary hyperparathyroidism.", "B": "Calcium excretion also increases (not decreases) in primary hyperparathyroidism, because the massively elevated filtered calcium load overwhelms PTH's reabsorptive effect at the tubule.", "D": "These urinary markers are all significantly abnormal in primary hyperparathyroidism, reflecting both excess PTH receptor signaling (cAMP, phosphate) and the hypercalcemia-driven filtered load (calcium); none remain normal."}}}, {"id": "anking-endocrine-pathology-1539", "fuente": "anking", "tema": 5, "anki": "1462140530307", "q": "Which parathyroid disorder is classically described using the mnemonic \"stones, bones, groans, and psychiatric overtones\"?", "o": {"A": "Secondary hyperparathyroidism", "B": "Hypoparathyroidism", "C": "Primary hyperparathyroidism", "D": "Familial hypocalciuric hypercalcemia"}, "r": "C", "e": {"correcta": "Primary hyperparathyroidism is remembered by \"stones, bones, groans, and psychiatric overtones\": kidney stones from hypercalciuria, bone pain/fractures from increased resorption, abdominal groans (constipation, peptic ulcers, pancreatitis), and psychiatric symptoms like depression or anxiety, all resulting from the chronic hypercalcemia of excess PTH.", "incorrectas": {"A": "Secondary hyperparathyroidism presents with signs of the underlying cause (e.g., CKD) and usually low-to-normal calcium, not the hypercalcemia-driven \"stones, bones, groans\" syndrome specific to primary disease.", "B": "Hypoparathyroidism causes hypocalcemia with tetany, hyperreflexia, and paresthesias, essentially the opposite clinical picture from the hypercalcemic mnemonic describing primary hyperparathyroidism.", "D": "Familial hypocalciuric hypercalcemia causes mild, usually asymptomatic hypercalcemia due to a CaSR mutation with low urinary calcium excretion, and does not produce the symptomatic mnemonic triad/tetrad seen in primary hyperparathyroidism."}}}, {"id": "anking-endocrine-pathology-1540", "fuente": "anking", "tema": 5, "anki": "1462140537123", "q": "What is the definitive treatment for symptomatic primary hyperparathyroidism due to a parathyroid adenoma?", "o": {"A": "Cinacalcet (calcimimetic) alone", "B": "Bisphosphonate therapy", "C": "Parathyroidectomy", "D": "Vitamin D supplementation"}, "r": "C", "e": {"correcta": "Surgical removal of the abnormal gland(s), parathyroidectomy, is the definitive and curative treatment for primary hyperparathyroidism, since it eliminates the source of autonomous PTH oversecretion (typically an adenoma).", "incorrectas": {"A": "Cinacalcet, a calcimimetic that activates the calcium-sensing receptor to reduce PTH secretion, is used medically in patients who are poor surgical candidates or have secondary/tertiary hyperparathyroidism, but it is not the definitive cure that surgery provides.", "B": "Bisphosphonates can help manage the resulting hypercalcemia by inhibiting osteoclastic bone resorption, but they do not address the underlying autonomous PTH-secreting adenoma and are not the definitive treatment.", "D": "Vitamin D supplementation would be inappropriate and potentially harmful in primary hyperparathyroidism, since the patient already has hypercalcemia; vitamin D is used to treat hypoparathyroidism-related hypocalcemia, not hyperparathyroidism."}}}, {"id": "anking-endocrine-pathology-1541", "fuente": "anking", "tema": 5, "anki": "1462140542758", "q": "In secondary hyperparathyroidism, elevated PTH levels occur as a compensatory response to which underlying abnormality?", "o": {"A": "Parathyroid adenoma", "B": "Hypocalcemia (or hyperphosphatemia)", "C": "Vitamin D excess", "D": "Autoimmune destruction of chief cells"}, "r": "B", "e": {"correcta": "Secondary hyperparathyroidism is an appropriate physiologic response of otherwise normal parathyroid glands to chronic hypocalcemia or hyperphosphatemia, most commonly from chronic kidney disease (impaired 1α-hydroxylation and phosphate retention) or vitamin D deficiency, driving compensatory PTH hypersecretion in an attempt to normalize calcium.", "incorrectas": {"A": "A parathyroid adenoma causing autonomous PTH secretion defines primary hyperparathyroidism, an intrinsic gland disorder, not the appropriate compensatory response to a systemic calcium/phosphate abnormality seen in secondary disease.", "C": "Vitamin D excess would raise, not lower, serum calcium, which would suppress rather than stimulate PTH secretion — the opposite trigger from the hypocalcemia that drives secondary hyperparathyroidism.", "D": "Autoimmune destruction of parathyroid chief cells would cause hypoparathyroidism (low PTH), not the elevated PTH levels that define secondary hyperparathyroidism."}}}, {"id": "anking-endocrine-pathology-1542", "fuente": "anking", "tema": 5, "anki": "1462140559401", "q": "Hypoparathyroidism is characterized by which pair of serum electrolyte abnormalities?", "o": {"A": "Hypercalcemia and hypophosphatemia", "B": "Hypocalcemia and hyperphosphatemia", "C": "Hypercalcemia and hyperphosphatemia", "D": "Hypocalcemia and hypophosphatemia"}, "r": "B", "e": {"correcta": "Hypoparathyroidism results from deficient PTH activity, leading to decreased serum calcium (hypocalcemia, from reduced bone resorption, renal reabsorption, and vitamin D activation) together with increased serum phosphate (hyperphosphatemia, from decreased renal phosphate excretion, since PTH's phosphaturic effect is lost). Treatment involves oral calcium and vitamin D supplementation.", "incorrectas": {"A": "Hypercalcemia with hypophosphatemia describes primary hyperparathyroidism (excess PTH activity), the opposite hormonal and electrolyte state from hypoparathyroidism.", "C": "Hypercalcemia would not occur in hypoparathyroidism, since without adequate PTH, bone resorption and renal calcium reabsorption are both reduced, driving calcium down rather than up.", "D": "Hypophosphatemia is inconsistent with hypoparathyroidism; loss of PTH's phosphaturic action causes phosphate retention (hyperphosphatemia), not phosphate wasting."}}}, {"id": "anking-endocrine-pathology-1543", "fuente": "anking", "tema": 5, "anki": "1462140587560", "q": "A patient has hypocalcemia and hyperphosphatemia. Administration of exogenous PTH fails to correct the lab abnormalities. Which condition, associated with short stature, short 4th/5th metacarpals, and end-organ resistance to PTH, is most likely present?", "o": {"A": "Primary hyperparathyroidism", "B": "Hypoparathyroidism", "C": "Pseudohypoparathyroidism type 1a", "D": "Familial hypocalciuric hypercalcemia"}, "r": "C", "e": {"correcta": "Pseudohypoparathyroidism type 1a (Albright hereditary osteodystrophy) results from an inactivating mutation in the Gs-alpha protein coupled to the PTH receptor, so the kidney and bone cannot respond to PTH despite normal or elevated hormone levels. The result is end-organ resistance producing hypocalcemia and hyperphosphatemia that does not improve with exogenous PTH administration, along with short stature, obesity, and shortened 4th/5th metacarpals.", "incorrectas": {"A": "Primary hyperparathyroidism is caused by autonomous PTH secretion (usually a parathyroid adenoma) and produces hypercalcemia with hypophosphatemia, the opposite biochemical pattern seen here.", "B": "Hypoparathyroidism results from deficient PTH secretion; unlike pseudohypoparathyroidism, administering exogenous PTH would correct the hypocalcemia and hyperphosphatemia because the renal and bone receptors are intact and responsive.", "D": "Familial hypocalciuric hypercalcemia is caused by an inactivating mutation in the calcium-sensing receptor, leading to hypercalcemia (not hypocalcemia) with low urinary calcium excretion, a distinct biochemical profile."}}}, {"id": "anking-endocrine-pathology-1544", "fuente": "anking", "tema": 5, "anki": "1462140593524", "q": "How do serum PTH levels differ between hypoparathyroidism and pseudohypoparathyroidism?", "o": {"A": "PTH is decreased in both conditions", "B": "PTH is elevated in hypoparathyroidism and decreased in pseudohypoparathyroidism", "C": "PTH is decreased in hypoparathyroidism and elevated in pseudohypoparathyroidism", "D": "PTH is elevated in both conditions"}, "r": "C", "e": {"correcta": "In hypoparathyroidism the parathyroid glands fail to produce PTH, so levels are low. In pseudohypoparathyroidism the glands are normal and appropriately increase PTH secretion in response to the resulting hypocalcemia, but target tissues (kidney, bone) are resistant to its action due to a Gs-alpha signaling defect, so PTH is elevated despite persistent hypocalcemia.", "incorrectas": {"A": "PTH is not decreased in both; pseudohypoparathyroidism features compensatory hypersecretion of PTH because the gland itself is functioning normally and is being stimulated by low calcium.", "B": "This reverses the actual pattern: hypoparathyroidism is characterized by low PTH from gland failure, not elevation.", "D": "PTH is not elevated in both; hypoparathyroidism specifically reflects a primary deficiency of hormone production, not resistance to a normally secreted hormone."}}}, {"id": "anking-endocrine-pathology-1545", "fuente": "anking", "tema": 5, "anki": "1462140675966", "q": "A patient with humoral hypercalcemia of malignancy due to a PTHrP-secreting squamous cell lung cancer is treated with a drug that inhibits osteoclast-mediated bone resorption. Which class of drug is this?", "o": {"A": "Loop diuretics", "B": "Calcitonin", "C": "Bisphosphonates (e.g., zoledronate, pamidronate)", "D": "Cinacalcet"}, "r": "C", "e": {"correcta": "Bisphosphonates such as zoledronate and pamidronate bind hydroxyapatite in bone and are ingested by osteoclasts, inducing osteoclast apoptosis and inhibiting bone resorption. This lowers serum calcium and is a mainstay treatment for humoral hypercalcemia of malignancy, where tumor-secreted PTHrP drives excessive osteoclastic bone breakdown. Older agents like etidronate are less potent and largely fallen out of favor compared to newer bisphosphonates.", "incorrectas": {"A": "Loop diuretics (e.g., furosemide) promote renal calcium excretion by inhibiting reabsorption in the thick ascending limb and can be used adjunctively for severe hypercalcemia, but they do not inhibit bone resorption, which is the primary pathologic process in malignancy-associated hypercalcemia.", "B": "Calcitonin lowers calcium quickly by inhibiting osteoclasts and increasing renal calcium excretion, but its effect is short-lived due to tachyphylaxis, making it useful for acute management rather than the mainstay bisphosphonate therapy described here.", "D": "Cinacalcet is a calcimimetic that activates the calcium-sensing receptor on parathyroid cells to suppress PTH secretion; it is used in primary/secondary hyperparathyroidism, not as a direct inhibitor of osteoclastic bone resorption in malignancy-related hypercalcemia."}}}, {"id": "anking-endocrine-pathology-1546", "fuente": "anking", "tema": 5, "anki": "1462140694887", "q": "What is the pattern of inheritance of familial hypocalciuric hypercalcemia (FHH)?", "o": {"A": "X-linked recessive", "B": "Autosomal recessive", "C": "Autosomal dominant", "D": "Mitochondrial"}, "r": "C", "e": {"correcta": "FHH is inherited in an autosomal dominant pattern due to an inactivating mutation in the calcium-sensing receptor (CaSR) on parathyroid chief cells and renal tubular cells. This raises the calcium set point for PTH suppression and increases renal calcium reabsorption, producing mild hypercalcemia with low urinary calcium (hence 'hypocalciuric'), typically asymptomatic and not requiring treatment.", "incorrectas": {"B": "Autosomal recessive inheritance would require two mutated alleles for disease expression; FHH manifests with a single mutant CaSR allele, consistent with a dominant pattern.", "A": "X-linked recessive conditions are inherited via mutations on the X chromosome and predominantly affect males; FHH is caused by an autosomal gene (CASR gene) and affects both sexes equally.", "D": "Mitochondrial inheritance follows maternal transmission of mutated mitochondrial DNA; FHH results from a nuclear gene mutation transmitted in a classic autosomal dominant Mendelian pattern."}}}, {"id": "anking-renal-pathology-1547", "fuente": "anking", "tema": 58, "anki": "1462140768683", "q": "What happens to serum phosphate levels in chronic renal failure, and why?", "o": {"A": "Phosphate decreases due to increased renal excretion", "B": "Phosphate increases due to decreased glomerular filtration", "C": "Phosphate remains normal due to compensatory PTH suppression", "D": "Phosphate decreases due to increased intestinal absorption of calcium"}, "r": "B", "e": {"correcta": "As glomerular filtration rate declines in chronic renal failure, the kidney filters and excretes less phosphate, causing it to accumulate in the serum (hyperphosphatemia). This retained phosphate goes on to complex with ionized calcium, contributing to hypocalcemia and secondary hyperparathyroidism.", "incorrectas": {"A": "Renal excretion of phosphate actually decreases, not increases, as GFR falls, since fewer nephrons are available to filter and clear phosphate from the blood.", "C": "Phosphate does not stay normal; despite a compensatory rise in PTH (which normally promotes phosphaturia), the severely reduced GFR overwhelms this compensation and phosphate still accumulates.", "D": "Decreased renal function does not increase intestinal calcium absorption; in fact, reduced renal 1,25-dihydroxyvitamin D production in CKD decreases intestinal calcium absorption, compounding hypocalcemia rather than affecting phosphate directly."}}}, {"id": "anking-renal-pathology-1548", "fuente": "anking", "tema": 58, "anki": "1462140786768", "q": "In chronic renal failure, elevated serum phosphate complexes with calcium, leading to a decrease in which form of calcium?", "o": {"A": "Protein-bound calcium", "B": "Free, ionized Ca2+", "C": "Total serum calcium-phosphate product only", "D": "Intracellular calcium stores"}, "r": "B", "e": {"correcta": "Excess serum phosphate in chronic renal failure precipitates with calcium to form calcium-phosphate complexes, directly lowering the free, ionized Ca2+ fraction, which is the physiologically active form that parathyroid chief cells sense. This drop in ionized calcium is a key driver of the compensatory secondary hyperparathyroidism seen in CKD.", "incorrectas": {"A": "Protein-bound calcium (bound mainly to albumin) is a separate pool from ionized calcium and is not the fraction directly consumed by complexing with excess phosphate.", "C": "The calcium-phosphate product describes the mathematical relationship used to assess risk of vascular/soft tissue calcification, but the direct physiologic consequence tested here is the fall in ionized calcium sensed by the parathyroid gland.", "D": "Intracellular calcium stores (e.g., in the endoplasmic reticulum) are regulated separately from extracellular ionized calcium and are not what is depleted by extracellular calcium-phosphate complex formation."}}}, {"id": "anking-renal-pathology-1549", "fuente": "anking", "tema": 58, "anki": "1462140791464", "q": "In chronic renal failure, decreased renal production of which active hormone contributes to decreased ionized Ca2+ by reducing intestinal calcium absorption?", "o": {"A": "25-hydroxycholecalciferol", "B": "1,25-dihydroxycholecalciferol (active vitamin D)", "C": "Calcitonin", "D": "Parathyroid hormone-related peptide"}, "r": "B", "e": {"correcta": "The kidney performs the final 1-alpha-hydroxylation step converting 25-hydroxyvitamin D into 1,25-dihydroxycholecalciferol (calcitriol), the active form of vitamin D. In chronic renal failure, damaged renal tissue cannot perform this conversion, so intestinal calcium absorption falls, worsening hypocalcemia and driving secondary hyperparathyroidism.", "incorrectas": {"A": "25-hydroxycholecalciferol is the storage form produced by the liver and is relatively unaffected by renal disease; it must still undergo renal 1-alpha-hydroxylation to become biologically active, which is the step that fails in CKD.", "C": "Calcitonin is produced by thyroid parafollicular cells, not the kidney, and acts to lower calcium by inhibiting osteoclasts; it is not part of the vitamin D activation pathway affected in renal failure.", "D": "PTHrP is a paraneoplastic peptide mimicking PTH action, unrelated to renal vitamin D metabolism or the pathophysiology of secondary hyperparathyroidism in CKD."}}}, {"id": "anking-renal-pathology-1550", "fuente": "anking", "tema": 58, "anki": "1462140817380", "q": "The decreased ionized Ca2+ characteristic of chronic renal failure leads to which compensatory condition, marked by elevated PTH levels?", "o": {"A": "Primary hyperparathyroidism", "B": "Secondary hyperparathyroidism", "C": "Pseudohypoparathyroidism", "D": "Tertiary hypoparathyroidism"}, "r": "B", "e": {"correcta": "Chronic renal failure causes hyperphosphatemia and decreased active vitamin D production, both of which lower ionized calcium. The parathyroid glands respond appropriately by increasing PTH secretion in an attempt to restore calcium homeostasis, a state termed secondary hyperparathyroidism because the parathyroid pathology is secondary to an extrinsic stimulus (renal disease), not an intrinsic gland abnormality.", "incorrectas": {"A": "Primary hyperparathyroidism arises from an intrinsic parathyroid abnormality (typically an adenoma) causing autonomous PTH secretion and hypercalcemia, the opposite of the hypocalcemia-driven compensatory state seen in renal failure.", "C": "Pseudohypoparathyroidism is a distinct genetic condition involving end-organ resistance to PTH due to a Gs-alpha defect, not a compensatory response to renal disease.", "D": "There is no entity called tertiary hypoparathyroidism; the analogous complication of prolonged secondary hyperparathyroidism is tertiary hyperparathyroidism, where the glands become autonomous and cause hypercalcemia, not hypoparathyroidism."}}}, {"id": "anking-endocrine-physiology-1551", "fuente": "anking", "tema": 23, "anki": "1462143900723", "q": "What is the major physiologic stimulus for calcitonin secretion by thyroid parafollicular (C) cells?", "o": {"A": "Hypocalcemia", "B": "Hyperphosphatemia", "C": "Hypercalcemia", "D": "Elevated PTH levels"}, "r": "C", "e": {"correcta": "Calcitonin is secreted by parafollicular C cells of the thyroid in response to hypercalcemia, acting to lower serum calcium primarily by inhibiting osteoclastic bone resorption. This is the opposite trigger of PTH, which is released in response to decreased calcium, though calcitonin plays only a minor role in day-to-day calcium homeostasis compared to PTH and vitamin D.", "incorrectas": {"A": "Hypocalcemia is the stimulus for PTH secretion from the parathyroid glands, not calcitonin; calcitonin release is triggered by the opposite condition, elevated calcium.", "B": "Hyperphosphatemia is not the primary trigger for calcitonin release; phosphate levels are regulated mainly through PTH-mediated renal phosphate excretion and FGF23, not calcitonin secretion.", "D": "PTH levels do not directly stimulate calcitonin secretion; the two hormones are produced by different glands (parathyroid vs. thyroid C cells) and respond independently to serum calcium in opposite directions."}}}, {"id": "anking-endocrine-physiology-1552", "fuente": "anking", "tema": 23, "anki": "1462143914867", "q": "What is the major mechanism by which calcitonin lowers plasma calcium concentration?", "o": {"A": "Stimulating renal calcium reabsorption", "B": "Increasing intestinal calcium absorption", "C": "Inhibiting osteoclast-mediated bone resorption", "D": "Suppressing PTH secretion directly"}, "r": "C", "e": {"correcta": "Calcitonin's main action is to inhibit osteoclast activity, thereby decreasing bone resorption and the release of calcium and phosphate into the blood. This lowers plasma calcium concentration, making calcitonin useful therapeutically in acute hypercalcemia, though its effect is limited by rapid tachyphylaxis.", "incorrectas": {"A": "Calcitonin actually promotes renal calcium excretion rather than reabsorption, contributing to lower serum calcium, the opposite of what PTH does at the renal tubule.", "B": "Calcitonin does not act on intestinal calcium absorption; that process is primarily regulated by active vitamin D (calcitriol), which increases gut calcium uptake.", "D": "Calcitonin does not act directly on the parathyroid gland to suppress PTH; the two hormones function through independent target-organ mechanisms (bone, kidney) rather than one directly inhibiting the other's secretion."}}}, {"id": "anking-endocrine-physiology-1553", "fuente": "anking", "tema": 23, "anki": "1462143926547", "q": "Calcitonin may be used therapeutically to treat which calcium imbalance?", "o": {"A": "Hypocalcemia", "B": "Hypercalcemia", "C": "Hypophosphatemia", "D": "Hyperphosphatemia"}, "r": "B", "e": {"correcta": "Because calcitonin inhibits osteoclastic bone resorption and promotes renal calcium excretion, it lowers serum calcium and can be used as a rapid-acting treatment for hypercalcemia, particularly in acute settings, although its effect diminishes with prolonged use due to tachyphylaxis.", "incorrectas": {"A": "Hypocalcemia would be worsened, not treated, by calcitonin, since calcitonin further lowers calcium; hypocalcemia is instead treated with calcium and active vitamin D supplementation, or PTH analogs when appropriate.", "C": "Hypophosphatemia is not treated with calcitonin; phosphate imbalances are managed with phosphate repletion or restriction and are not calcitonin's primary target.", "D": "Hyperphosphatemia (as seen in chronic kidney disease) is managed with phosphate binders and dietary restriction, not calcitonin, which primarily targets calcium rather than phosphate homeostasis."}}}, {"id": "anking-neurology-special-senses-pathology-1554", "fuente": "anking", "tema": 9, "anki": "1462204521643", "q": "A pituitary adenoma is best described as which type of lesion?", "o": {"A": "A malignant tumor of anterior pituitary cells with frequent metastasis", "B": "A benign tumor of anterior pituitary cells", "C": "A benign tumor of the posterior pituitary", "D": "A malignant germ cell tumor of the sella turcica"}, "r": "B", "e": {"correcta": "Pituitary adenomas are benign neoplasms arising from the hormone-producing cells of the anterior pituitary (adenohypophysis). They are the most common cause of sellar masses in adults and can be functional (hormone-secreting) or nonfunctional (silent), producing symptoms via hormone excess and/or mass effect.", "incorrectas": {"A": "Pituitary adenomas are benign, not malignant, and essentially never metastasize; even large, locally invasive adenomas remain histologically benign lesions confined to local structures.", "C": "The posterior pituitary (neurohypophysis) is composed of neural tissue storing ADH and oxytocin and does not give rise to adenomas; pituitary adenomas arise specifically from the anterior pituitary's secretory cells.", "D": "Germ cell tumors of the sellar/suprasellar region are a distinct, much rarer entity typically seen in children (e.g., germinomas), unrelated to the common benign adenohypophyseal adenoma."}}}, {"id": "anking-neurology-special-senses-pathology-1555", "fuente": "anking", "tema": 9, "anki": "1462206100432", "q": "Pituitary adenomas that do not secrete an excess hormone and are clinically silent except for mass effect are classified as which type?", "o": {"A": "Functional adenomas", "B": "Nonfunctional adenomas", "C": "Ectopic adenomas", "D": "Mixed secretory adenomas"}, "r": "B", "e": {"correcta": "Nonfunctional (silent) pituitary adenomas do not produce clinically significant hormone excess, so they typically present later, once they are large enough to cause mass effect symptoms such as headache, visual field defects, or hypopituitarism from compression of normal pituitary tissue.", "incorrectas": {"A": "Functional adenomas actively secrete a pituitary hormone (e.g., prolactin, GH, ACTH), producing a distinct hyperfunction syndrome (e.g., hyperprolactinemia), which contrasts with the silent nonfunctional tumors.", "C": "Ectopic adenomas is not a recognized classification for pituitary tumors; pituitary adenomas are categorized by their secretory activity (functional vs. nonfunctional), not by anatomic ectopia.", "D": "While some adenomas can co-secrete more than one hormone, 'mixed secretory' is not the standard term used to distinguish nonfunctional tumors, which by definition lack significant hormone secretion altogether."}}}, {"id": "anking-neurology-special-senses-pathology-1556", "fuente": "anking", "tema": 9, "anki": "1462206107219", "q": "Nonfunctional pituitary adenomas most often present with symptoms due to which mechanism?", "o": {"A": "Autoimmune destruction of pituitary tissue", "B": "Hormone hypersecretion", "C": "Mass effect from tumor growth", "D": "Infarction of the gland"}, "r": "C", "e": {"correcta": "Because nonfunctional adenomas do not secrete hormones in excess, they remain clinically silent until they grow large enough to compress surrounding structures, causing symptoms from mass effect, such as headache, bitemporal hemianopsia (optic chiasm compression), or hypopituitarism from compression of normal gland tissue.", "incorrectas": {"A": "Autoimmune destruction describes conditions like lymphocytic hypophysitis, a separate and much rarer cause of pituitary dysfunction, not the mechanism behind nonfunctional adenoma symptoms.", "B": "Hormone hypersecretion is the defining feature of functional adenomas, not nonfunctional ones, which by definition lack significant hormone output.", "D": "Infarction of the pituitary gland describes Sheehan syndrome (postpartum hemorrhage-related) or pituitary apoplexy, distinct clinical entities rather than the typical presentation of a slow-growing nonfunctional adenoma."}}}, {"id": "anking-neurology-special-senses-pathology-1557", "fuente": "anking", "tema": 9, "anki": "1462206153513", "q": "A pituitary adenoma may cause deficiency of multiple anterior pituitary hormones. What is this clinical presentation called?", "o": {"A": "Hyperpituitarism", "B": "Hypopituitarism", "C": "Diabetes insipidus", "D": "SIADH"}, "r": "B", "e": {"correcta": "As a pituitary adenoma enlarges, it can compress the surrounding normal anterior pituitary tissue, impairing secretion of multiple hormones (e.g., TSH, ACTH, gonadotropins, GH) and producing hypopituitarism, in addition to any hormone the tumor itself may be secreting.", "incorrectas": {"A": "Hyperpituitarism refers to excess hormone secretion, which is the opposite process; it describes the effect of a functional adenoma's own hormone output, not the compression-related loss of function in surrounding normal tissue.", "C": "Diabetes insipidus results from deficient ADH (posterior pituitary/hypothalamic) function, not from compression of anterior pituitary hormone-secreting cells by an adenoma.", "D": "SIADH involves excess ADH secretion causing hyponatremia and is unrelated to anterior pituitary compression by an adenoma; it is more classically associated with ectopic ADH production or CNS/pulmonary pathology."}}}, {"id": "anking-neurology-special-senses-pathology-1558", "fuente": "anking", "tema": 9, "anki": "1462206162910", "q": "Which nonspecific symptom is commonly caused by the mass effect of a pituitary adenoma?", "o": {"A": "Headache", "B": "Diarrhea", "C": "Peripheral edema", "D": "Tinnitus"}, "r": "A", "e": {"correcta": "Headache is a common, nonspecific symptom of pituitary adenomas resulting from mass effect, as the enlarging tumor stretches the dura and surrounding structures within and around the sella turcica. It often accompanies more specific findings like visual field deficits or hormone-related symptoms.", "incorrectas": {"B": "Diarrhea is not a typical feature of pituitary mass effect; it is unrelated to sellar compression and would suggest a different underlying process (e.g., GI or specific hormone-secreting tumors like VIPoma).", "C": "Peripheral edema is not a classic symptom of pituitary adenoma mass effect; it is more commonly associated with conditions like heart failure, renal disease, or venous insufficiency.", "D": "Tinnitus is typically associated with otologic or vestibular pathology (e.g., acoustic neuroma, Meniere disease), not with pituitary adenomas, which more classically cause headache and visual disturbances from chiasmal compression."}}}, {"id": "anking-neurology-special-senses-pathology-1559", "fuente": "anking", "tema": 9, "anki": "1462206168906", "q": "What is the most common type of functional (hormone-secreting) pituitary adenoma?", "o": {"A": "Corticotroph (ACTH-secreting) adenoma", "B": "Somatotroph (GH-secreting) adenoma", "C": "Lactotroph (prolactin-secreting) adenoma", "D": "Gonadotroph (FSH/LH-secreting) adenoma"}, "r": "C", "e": {"correcta": "Prolactinomas (lactotroph adenomas) are the most common type of functional pituitary adenoma. They cause hyperprolactinemia, which in women presents with galactorrhea, amenorrhea, and infertility, and in men presents more subtly with decreased libido and infertility, often leading to later diagnosis at a more advanced, mass-effect stage.", "incorrectas": {"A": "Corticotroph adenomas secrete ACTH and cause Cushing disease, but they are less common than prolactinomas as a cause of functional pituitary adenoma.", "B": "Somatotroph adenomas secrete growth hormone and cause acromegaly (or gigantism in children), but they occur less frequently than prolactin-secreting adenomas.", "D": "Gonadotroph (FSH/LH-secreting) adenomas are actually quite rare and often clinically silent or associated with nonspecific symptoms, making them far less common than prolactinomas."}}}, {"id": "anking-neurology-special-senses-pathology-1560", "fuente": "anking", "tema": 9, "anki": "1462206185551", "q": "In men, a prolactin-secreting pituitary adenoma classically presents with headache, infertility, and which additional symptom, without galactorrhea?", "o": {"A": "Gynecomastia only", "B": "Decreased libido", "C": "Hyperpigmentation", "D": "Polyuria"}, "r": "B", "e": {"correcta": "Excess prolactin suppresses GnRH release from the hypothalamus, reducing LH/FSH and downstream testosterone production, which manifests in men as decreased libido and infertility, along with headache from mass effect. Unlike women, men do not typically develop galactorrhea, so they often present later with larger, more locally invasive tumors.", "incorrectas": {"A": "While gynecomastia can occur with hypogonadism, it is not the classic distinguishing symptom emphasized for male prolactinoma presentation; decreased libido from GnRH suppression is the hallmark feature alongside headache and infertility.", "C": "Hyperpigmentation is associated with elevated ACTH/MSH-related peptides (e.g., in Addison disease or Nelson syndrome), not with prolactin excess.", "D": "Polyuria suggests a posterior pituitary/ADH problem such as diabetes insipidus, unrelated to the anterior pituitary prolactin excess seen in prolactinoma."}}}, {"id": "anking-endocrine-pathology-1561", "fuente": "anking", "tema": 5, "anki": "1462206280174", "q": "Acromegaly is characterized by enlargement of which structure, producing deep furrows and a deepened voice?", "o": {"A": "Thyroid gland", "B": "Tongue", "C": "Larynx cartilage alone", "D": "Parotid glands"}, "r": "B", "e": {"correcta": "Excess growth hormone in acromegaly causes soft tissue overgrowth, producing macroglossia (an enlarged tongue with deep furrows) along with a deepened voice from thickening of the vocal cords and soft tissues of the airway. These soft tissue changes, together with skeletal overgrowth, are classic clinical clues to GH excess in adults.", "incorrectas": {"A": "Thyroid enlargement (goiter) is not a typical feature of acromegaly; it is more associated with thyroid-specific pathology like Graves disease or Hashimoto thyroiditis.", "C": "While laryngeal soft tissue does thicken contributing to voice change, isolated cartilage growth is not the described mechanism; the overall soft tissue and macroglossia changes are more characteristic of the exam finding.", "D": "Parotid gland enlargement is not a hallmark of acromegaly; it is more classically associated with conditions like bulimia, alcohol use, or Sjögren syndrome."}}}, {"id": "anking-endocrine-pathology-1562", "fuente": "anking", "tema": 5, "anki": "1462206290247", "q": "Acromegaly causes enlargement of bones in which locations?", "o": {"A": "Vertebral bodies only", "B": "Hands, feet, and jaw", "C": "Long bone epiphyses only", "D": "Skull base only"}, "r": "B", "e": {"correcta": "In adults, growth plates have already fused, so excess GH and IGF-1 in acromegaly cause periosteal bone growth and soft tissue expansion rather than linear growth, leading to characteristic enlargement of the hands, feet, and jaw (mandibular prognathism), along with frontal bossing and widened spaces between teeth.", "incorrectas": {"A": "Vertebral body changes can occur but are not the classic, most emphasized skeletal finding; the hands, feet, and jaw enlargement are the hallmark exam findings in acromegaly.", "C": "Because growth plates are already closed in adults with acromegaly, bones grow in width via periosteal apposition rather than at the epiphyses, distinguishing acromegaly from gigantism (which occurs before growth plate closure).", "D": "While the skull can be affected (frontal bossing), isolated skull base enlargement is not the primary or most classic description of acromegaly's skeletal manifestations."}}}, {"id": "anking-endocrine-pathology-1563", "fuente": "anking", "tema": 5, "anki": "1462206315422", "q": "In acromegaly, growth hormone excess may cause enlargement of which category of structures, leading to organ dysfunction?", "o": {"A": "Visceral organs", "B": "Lymph nodes only", "C": "Peripheral nerves only", "D": "Skeletal muscle only"}, "r": "A", "e": {"correcta": "Chronic GH/IGF-1 excess in acromegaly promotes organomegaly of visceral organs, including the heart (cardiomegaly), liver, and kidneys, which can progressively impair their function. Cardiac involvement is particularly important, as it contributes significantly to morbidity and mortality in these patients.", "incorrectas": {"B": "Lymphadenopathy is not a characteristic feature of acromegaly; visceral organomegaly (particularly cardiomegaly) is the more clinically significant and tested consequence of GH excess.", "C": "While some peripheral nerve entrapment (e.g., carpal tunnel syndrome from soft tissue swelling) can occur in acromegaly, generalized peripheral nerve enlargement is not the described mechanism of organ dysfunction.", "D": "Skeletal muscle is not classically described as undergoing dysfunction-causing enlargement in acromegaly; the emphasis is on visceral organ growth, especially cardiac hypertrophy leading to heart failure."}}}, {"id": "anking-endocrine-pathology-1564", "fuente": "anking", "tema": 5, "anki": "1462206324429", "q": "Acromegaly can cause impaired tolerance of which substance, potentially presenting as secondary diabetes mellitus?", "o": {"A": "Sodium", "B": "Glucose", "C": "Potassium", "D": "Calcium"}, "r": "B", "e": {"correcta": "Growth hormone excess antagonizes insulin action in peripheral tissues, producing insulin resistance and impaired glucose tolerance. Over time this can manifest as overt secondary diabetes mellitus, making glucose intolerance an important metabolic complication to screen for in patients with acromegaly.", "incorrectas": {"A": "Sodium handling is not the primary metabolic disturbance in acromegaly; GH's main metabolic antagonism is directed at insulin's effects on glucose metabolism.", "C": "Potassium regulation is not classically disrupted by GH excess in acromegaly; this is more relevant to mineralocorticoid or renal tubular disorders.", "D": "While calcium metabolism can be indirectly affected by GH-driven phosphate retention, the primary and classically tested metabolic derangement in acromegaly is impaired glucose tolerance from insulin resistance."}}}, {"id": "anking-endocrine-pathology-1565", "fuente": "anking", "tema": 5, "anki": "1462206340681", "q": "Acromegaly is associated with resistance to which hormone, contributing to secondary diabetes mellitus?", "o": {"A": "Glucagon", "B": "Cortisol", "C": "Insulin", "D": "Thyroid hormone"}, "r": "C", "e": {"correcta": "Growth hormone directly antagonizes insulin signaling in peripheral tissues, producing insulin resistance. This chronic resistance can progress to overt secondary diabetes mellitus in patients with long-standing acromegaly, making glucose monitoring an important part of their management.", "incorrectas": {"A": "Glucagon resistance is not a described feature of acromegaly; GH's counter-regulatory effect is specifically directed against insulin action, not glucagon signaling.", "B": "Cortisol resistance is characteristic of a separate condition and not part of the acromegaly mechanism; GH excess does not classically induce cortisol resistance.", "D": "Thyroid hormone resistance is a distinct, rare genetic condition unrelated to GH excess; acromegaly's metabolic hallmark is insulin resistance, not thyroid hormone resistance."}}}, {"id": "anking-endocrine-pathology-1566", "fuente": "anking", "tema": 5, "anki": "1462206379039", "q": "What is the most common cause of death in patients with acromegaly?", "o": {"A": "Colorectal cancer", "B": "Heart failure", "C": "Pituitary apoplexy", "D": "Renal failure"}, "r": "B", "e": {"correcta": "Chronic GH/IGF-1 excess drives cardiac hypertrophy and cardiomyopathy, which progresses to heart failure, the leading cause of death in acromegaly. Cardiovascular complications, including hypertension and arrhythmias, are major contributors to the increased mortality seen in untreated or poorly controlled disease.", "incorrectas": {"A": "Acromegaly does carry an increased risk of colorectal polyps and cancer, warranting earlier screening colonoscopy, but this is not the leading cause of death compared to cardiovascular complications.", "C": "Pituitary apoplexy is an acute hemorrhagic or ischemic event within a pituitary adenoma; while a possible complication of any large adenoma, it is not the most common cause of death in acromegaly overall.", "D": "Renal failure is not the primary described cause of mortality in acromegaly; cardiac disease, driven by GH-induced myocardial hypertrophy, is the leading cause of death."}}}, {"id": "anking-endocrine-pathology-1567", "fuente": "anking", "tema": 5, "anki": "1462206421793", "q": "A growth hormone cell adenoma may be diagnosed by finding elevated serum levels of GH and which other biomarker?", "o": {"A": "IGF-1", "B": "PTHrP", "C": "TSH", "D": "ACTH"}, "r": "A", "e": {"correcta": "IGF-1 (insulin-like growth factor 1), produced by the liver in response to GH stimulation, reflects average GH secretion over time and is a key diagnostic marker for GH-secreting pituitary adenomas, since GH itself is secreted in pulses and a single random level can be misleading. Elevated GH and/or IGF-1 together support the diagnosis of acromegaly.", "incorrectas": {"B": "PTHrP is associated with humoral hypercalcemia of malignancy (e.g., squamous cell lung cancer), unrelated to growth hormone-secreting pituitary tumors.", "C": "TSH would be elevated in a TSH-secreting adenoma, a rare and distinct type of functional pituitary tumor, not the GH-secreting adenoma causing acromegaly.", "D": "ACTH is the hormone elevated in corticotroph adenomas causing Cushing disease, a different functional adenoma subtype than the somatotroph (GH-secreting) adenoma described here."}}}, {"id": "anking-endocrine-pathology-1568", "fuente": "anking", "tema": 5, "anki": "1462206436898", "q": "A growth hormone cell adenoma may be diagnosed by demonstrating a failure of GH to do what after an oral glucose load?", "o": {"A": "Rise", "B": "Suppress", "C": "Fluctuate normally", "D": "Correlate with insulin levels"}, "r": "B", "e": {"correcta": "Normally, an oral glucose load suppresses GH secretion through negative feedback. In a GH-secreting pituitary adenoma, this suppression fails to occur because the tumor autonomously secretes GH independent of normal regulatory signals, and this lack of suppression on an oral glucose tolerance test is a key confirmatory diagnostic test for acromegaly.", "incorrectas": {"A": "GH does not rise further with glucose administration in normal physiology or in acromegaly testing; the diagnostic abnormality is failure of the expected suppression, not a paradoxical rise being the tested feature.", "C": "The test specifically evaluates for loss of the normal suppressive response, not general fluctuation; a 'normal' fluctuating pattern would argue against autonomous GH secretion.", "D": "The oral glucose tolerance test for acromegaly assesses GH's own suppression, not its correlation with insulin; insulin levels are not the parameter used to confirm the diagnosis in this test."}}}, {"id": "anking-endocrine-pathology-1569", "fuente": "anking", "tema": 5, "anki": "1462206451792", "q": "Which class of drug, exemplified by octreotide, can be used to treat a growth hormone-secreting pituitary adenoma by suppressing GH release?", "o": {"A": "Dopamine agonists", "B": "Somatostatin analogs", "C": "GnRH agonists", "D": "Aldosterone antagonists"}, "r": "B", "e": {"correcta": "Somatostatin analogs such as octreotide mimic endogenous somatostatin, which physiologically inhibits GH release from the anterior pituitary. They are used medically to treat GH-secreting adenomas (acromegaly) when surgical resection is not curative or feasible, reducing GH and IGF-1 levels.", "incorrectas": {"A": "Dopamine agonists (e.g., cabergoline, bromocriptine) are the first-line medical therapy for prolactin-secreting adenomas, not GH-secreting adenomas, since dopamine normally inhibits prolactin, not GH.", "C": "GnRH agonists are used to suppress gonadotropin/sex steroid secretion (e.g., in prostate cancer or endometriosis treatment), not to manage GH-secreting pituitary tumors.", "D": "Aldosterone antagonists (e.g., spironolactone) act on the mineralocorticoid receptor in the kidney and are unrelated to pituitary hormone regulation or acromegaly treatment."}}}, {"id": "anking-neurology-special-senses-pathology-1570", "fuente": "anking", "tema": 9, "anki": "1462206535243", "q": "Compared to prolactin- and GH-secreting adenomas, how commonly do TSH-, LH-, and FSH-secreting pituitary adenomas occur?", "o": {"A": "They are the most common functional adenomas", "B": "They occur with equal frequency to prolactinomas", "C": "They are rare", "D": "They occur only in children"}, "r": "C", "e": {"correcta": "TSH-secreting, LH-secreting, and FSH-secreting pituitary adenomas do occur but are rare compared to the far more common prolactin- and GH-secreting adenomas. Because they are uncommon and often produce subtle or nonspecific symptoms, they may be discovered incidentally or present primarily due to mass effect.", "incorrectas": {"A": "Prolactinomas, not TSH/LH/FSH-secreting adenomas, are the most common type of functional pituitary adenoma, making this option incorrect.", "B": "These gonadotropin- and thyrotropin-secreting adenomas are notably less common than prolactinomas, not equally frequent.", "D": "These adenoma subtypes are not restricted to children; they can occur in adults as well, though they remain uncommon overall regardless of age group."}}}, {"id": "anking-endocrine-pathology-1571", "fuente": "anking", "tema": 5, "anki": "1462206536742", "q": "Hypopituitarism is best defined as which of the following?", "o": {"A": "Excess secretion of anterior pituitary hormones", "B": "Insufficient production of anterior pituitary hormones", "C": "Excess ADH secretion from the posterior pituitary", "D": "Autoimmune destruction of the adrenal cortex"}, "r": "B", "e": {"correcta": "Hypopituitarism refers to insufficient production of one or more anterior pituitary hormones (e.g., ACTH, TSH, GH, gonadotropins, prolactin), which can result from tumors, ischemic injury (e.g., Sheehan syndrome), or other causes destroying or compressing pituitary tissue.", "incorrectas": {"A": "Excess anterior pituitary hormone secretion describes hyperpituitarism (e.g., from a functional adenoma), the opposite process from the hormone deficiency defining hypopituitarism.", "C": "Excess ADH secretion describes SIADH, a posterior pituitary/hypothalamic phenomenon unrelated to anterior pituitary hormone deficiency.", "D": "Autoimmune destruction of the adrenal cortex describes primary adrenal insufficiency (Addison disease), a distinct condition originating in the adrenal gland itself, not the pituitary."}}}, {"id": "anking-endocrine-pathology-1572", "fuente": "anking", "tema": 5, "anki": "1462207413343", "q": "Symptoms of hypopituitarism typically arise only after what percentage of pituitary parenchyma has been lost?", "o": {"A": "25%", "B": "50%", "C": "75%", "D": "90%"}, "r": "C", "e": {"correcta": "The anterior pituitary has substantial functional reserve, so clinically apparent hypopituitarism generally does not manifest until more than 75% of the gland's parenchyma has been destroyed or compressed. This explains why early or partial pituitary injury can remain asymptomatic despite ongoing damage.", "incorrectas": {"A": "A 25% loss of pituitary tissue is well within the gland's functional reserve and would not be expected to produce clinical hypopituitarism.", "B": "At 50% loss, the remaining pituitary tissue can typically still maintain adequate hormone secretion, so symptomatic disease has not yet developed at this threshold.", "D": "While 90% loss would certainly cause hypopituitarism, the classically cited threshold at which symptoms begin to appear is greater than 75%, not specifically 90%."}}}, {"id": "anking-neurology-special-senses-pathology-1573", "fuente": "anking", "tema": 9, "anki": "1462207418792", "q": "In adults, hypopituitarism due to compression of normal pituitary tissue by mass effect is most commonly caused by which lesion?", "o": {"A": "Craniopharyngioma", "B": "Pituitary adenoma", "C": "Meningioma of the sella", "D": "Rathke cleft cyst"}, "r": "B", "e": {"correcta": "In adults, pituitary adenomas are the most common cause of hypopituitarism from mass effect, as an enlarging tumor compresses and destroys surrounding normal anterior pituitary tissue, reducing secretion of multiple hormones even if the adenoma itself is nonfunctional or secretes only one hormone type.", "incorrectas": {"A": "Craniopharyngioma is the classic cause of hypopituitarism in children (arising from Rathke pouch remnants near the sella), not the most common cause in adults, where pituitary adenomas predominate.", "C": "Meningiomas can occur near the sella and cause compressive symptoms, but they are a much less common cause of hypopituitarism compared to pituitary adenomas.", "D": "Rathke cleft cysts are benign, often incidentally found sellar lesions that can occasionally cause mass effect, but they are a far less common cause of hypopituitarism than pituitary adenomas in adults."}}}, {"id": "anking-neurology-special-senses-pathology-1574", "fuente": "anking", "tema": 9, "anki": "1462207429862", "q": "In children, hypopituitarism due to mass effect is classically caused by which tumor, derived from remnants of Rathke pouch?", "o": {"A": "Pituitary adenoma", "B": "Medulloblastoma", "C": "Craniopharyngioma", "D": "Pilocytic astrocytoma"}, "r": "C", "e": {"correcta": "Craniopharyngioma is a benign, often cystic suprasellar tumor arising from remnants of Rathke pouch (the embryologic precursor of the anterior pituitary). It is the most common cause of hypopituitarism in children and can also cause visual disturbances and, classically, calcifications visible on imaging.", "incorrectas": {"A": "Pituitary adenomas are the classic cause of hypopituitarism from mass effect in adults, but craniopharyngioma is the more characteristic cause in the pediatric population.", "B": "Medulloblastoma is a malignant cerebellar tumor common in children, but it arises in the posterior fossa and is not associated with pituitary hormone compression as craniopharyngioma is.", "D": "Pilocytic astrocytoma is a common pediatric brain tumor, often cerebellar or involving the optic pathway/hypothalamus, but it is not the classic sellar-region tumor causing hypopituitarism the way craniopharyngioma is."}}}, {"id": "anking-endocrine-pathology-1575", "fuente": "anking", "tema": 5, "anki": "1462207474576", "q": "During pregnancy, the pituitary gland approximately doubles in size, but what happens to its blood supply, predisposing to ischemic injury?", "o": {"A": "Blood supply doubles proportionally", "B": "Blood supply does not increase significantly", "C": "Blood supply is redirected entirely to the posterior pituitary", "D": "Blood supply triples to meet demand"}, "r": "B", "e": {"correcta": "During pregnancy the anterior pituitary enlarges (mainly due to lactotroph hyperplasia) to roughly double its normal size, but its vascular supply does not increase proportionally. This mismatch leaves the gland vulnerable to ischemic injury if blood pressure drops significantly, such as during postpartum hemorrhage, setting the stage for Sheehan syndrome.", "incorrectas": {"A": "The blood supply specifically fails to increase in proportion to the gland's growth; if it matched the increased tissue mass, the gland would not be at increased risk of ischemic infarction.", "C": "There is no redirection of blood supply to the posterior pituitary during pregnancy; the vulnerability described applies to the enlarged anterior pituitary, which is relatively underperfused relative to its size.", "D": "Blood supply does not triple; the core physiologic mismatch is that vascular supply remains essentially unchanged despite the gland nearly doubling in size, creating a relative ischemia risk."}}}, {"id": "anking-endocrine-pathology-1576", "fuente": "anking", "tema": 5, "anki": "1462207540805", "q": "Sheehan syndrome, an infarction of the enlarged pregnancy pituitary gland, is most often precipitated by which event?", "o": {"A": "Preeclampsia", "B": "Postpartum bleeding", "C": "Gestational diabetes", "D": "Chorioamnionitis"}, "r": "B", "e": {"correcta": "Because the pregnant pituitary gland is enlarged but not correspondingly better perfused, significant postpartum hemorrhage can cause hypotension severe enough to infarct the gland, resulting in Sheehan syndrome. This typically presents with failure to lactate, loss of pubic/axillary hair, and other signs of panhypopituitarism after a complicated delivery with significant blood loss.", "incorrectas": {"A": "Preeclampsia is a hypertensive disorder of pregnancy and, while it has its own maternal complications, it is not the classic precipitant of pituitary infarction described in Sheehan syndrome, which is tied to hypotension from blood loss.", "C": "Gestational diabetes is a glucose metabolism disorder of pregnancy unrelated to the vascular/ischemic mechanism causing pituitary infarction in Sheehan syndrome.", "D": "Chorioamnionitis is an infection of the fetal membranes and is not the mechanism linked to pituitary ischemia; the key precipitant is hypotension from significant postpartum hemorrhage."}}}, {"id": "anking-endocrine-pathology-1577", "fuente": "anking", "tema": 5, "anki": "1462207566120", "q": "Which combination of findings is classic for Sheehan syndrome?", "o": {"A": "Galactorrhea and hirsutism", "B": "Poor lactation, loss of pubic hair, and fatigue", "C": "Hypertension and weight gain", "D": "Polyuria and polydipsia"}, "r": "B", "e": {"correcta": "Sheehan syndrome results from postpartum pituitary infarction causing panhypopituitarism. Classic findings include poor or absent lactation (from prolactin deficiency), loss of pubic and axillary hair (from gonadotropin deficiency), fatigue (from ACTH/TSH deficiency), and often absent menstruation and cold intolerance.", "incorrectas": {"A": "Galactorrhea would result from prolactin excess, whereas Sheehan syndrome causes prolactin deficiency, leading to poor lactation, the opposite of this finding; hirsutism is also not a feature of this hypopituitary state.", "C": "Hypertension and weight gain are not characteristic of Sheehan syndrome; the deficiency of pituitary trophic hormones more typically leads to fatigue, hypotension, and features of secondary hypothyroidism/adrenal insufficiency rather than hypertension.", "D": "Polyuria and polydipsia suggest diabetes insipidus, a posterior pituitary/ADH-related problem; Sheehan syndrome primarily affects the anterior pituitary, causing deficiencies in prolactin, gonadotropins, ACTH, and TSH rather than ADH."}}}, {"id": "anking-endocrine-pathology-1578", "fuente": "anking", "tema": 5, "anki": "1462207601161", "q": "Hypopituitarism may be caused by which syndrome, which can result from trauma or a congenital defect of the sella turcica?", "o": {"A": "Sheehan syndrome", "B": "Empty sella syndrome", "C": "Cushing syndrome", "D": "Kallmann syndrome"}, "r": "B", "e": {"correcta": "Empty sella syndrome results when the sella turcica is not completely filled by pituitary tissue, often due to herniation of arachnoid and CSF into the sella (from a congenital diaphragma sellae defect or trauma), causing the gland to become flattened against the floor of the sella and predisposing to hypopituitarism.", "incorrectas": {"A": "Sheehan syndrome is postpartum pituitary infarction/necrosis due to hypotension during delivery, a distinct mechanism from the anatomic herniation seen in empty sella syndrome.", "C": "Cushing syndrome refers to hypercortisolism from any cause (exogenous steroids, pituitary adenoma, adrenal tumor) and is not related to sellar anatomic defects causing hypopituitarism.", "D": "Kallmann syndrome is a congenital GnRH deficiency due to failure of GnRH neuron migration, presenting with anosmia and hypogonadotropic hypogonadism, not a structural sellar abnormality."}}}, {"id": "anking-endocrine-pathology-1579", "fuente": "anking", "tema": 5, "anki": "1462207614080", "q": "In empty sella syndrome, atrophy, compression, and ultimately destruction occur in which structure?", "o": {"A": "Hypothalamus", "B": "Optic chiasm", "C": "Pituitary gland", "D": "Pineal gland"}, "r": "C", "e": {"correcta": "Empty sella syndrome occurs when herniation of the arachnoid and CSF into the sella turcica compresses and flattens the pituitary gland against the sellar floor, leading to progressive atrophy and potentially hypopituitarism, even though imaging may suggest an 'empty' sella.", "incorrectas": {"B": "The optic chiasm sits above the sella and can be affected by mass lesions expanding upward, but empty sella syndrome specifically compresses the pituitary gland itself, not the chiasm.", "A": "The hypothalamus lies superior to the pituitary stalk; it is not the structure directly compressed by CSF herniation into the sella turcica.", "D": "The pineal gland is located in the posterior brain near the third ventricle, anatomically unrelated to the sella turcica and pituitary fossa."}}}, {"id": "anking-endocrine-pathology-1580", "fuente": "anking", "tema": 5, "anki": "1462207714541", "q": "Empty sella syndrome is characterized by what finding on pituitary imaging?", "o": {"A": "Pituitary calcification", "B": "Apparent absence of the pituitary gland", "C": "Pituitary macroadenoma", "D": "Diffuse pituitary hemorrhage"}, "r": "B", "e": {"correcta": "On imaging, empty sella syndrome shows the sella turcica filled with CSF rather than visible pituitary tissue, giving the appearance that the gland is absent, even though a thin rim of flattened, functioning (or nonfunctioning) pituitary tissue is usually still present along the sellar floor.", "incorrectas": {"A": "Pituitary calcification is more characteristic of lesions like craniopharyngioma, not the CSF-filled sella seen in empty sella syndrome.", "C": "A macroadenoma would appear as an enlarging mass expanding the sella, the opposite imaging appearance of the CSF-filled, seemingly empty sella.", "D": "Pituitary hemorrhage (pituitary apoplexy) presents acutely with sudden hemorrhagic enlargement of the gland, not a CSF-filled, apparently empty sella."}}}, {"id": "anking-endocrine-pathology-1581", "fuente": "anking", "tema": 5, "anki": "1462207723111", "q": "Empty sella syndrome most commonly affects which demographic?", "o": {"A": "Thin elderly men", "B": "Obese women", "C": "Young athletic men", "D": "Prepubertal children"}, "r": "B", "e": {"correcta": "Empty sella syndrome classically occurs in obese women, thought to relate to increased intracranial pressure or a patulous diaphragma sellae that allows CSF and arachnoid to herniate into the sellar space over time, compressing the pituitary gland.", "incorrectas": {"A": "Thin elderly men are not the classically described demographic; the association is specifically with obesity and female sex, likely tied to intracranial pressure dynamics.", "C": "Young athletic men do not represent the typical population; empty sella syndrome is not linked to athleticism or male sex.", "D": "Prepubertal children are not the typical population affected; this condition is described predominantly in adult obese women."}}}, {"id": "anking-endocrine-pathology-1582", "fuente": "anking", "tema": 5, "anki": "1462207725659", "q": "What is the mainstay of treatment for hypopituitarism?", "o": {"A": "Hormone replacement therapy", "B": "Pituitary irradiation", "C": "Transsphenoidal decompression", "D": "Dopamine agonist therapy"}, "r": "A", "e": {"correcta": "Hypopituitarism is treated by replacing the specific hormones that are deficient, such as corticosteroids (for ACTH deficiency), levothyroxine (for TSH deficiency), sex steroids (for LH/FSH deficiency), and human growth hormone (for GH deficiency), tailored to which pituitary axes are affected.", "incorrectas": {"B": "Pituitary irradiation is a treatment option for certain functioning or residual pituitary tumors, not a standard therapy for restoring hormone deficiency in hypopituitarism itself.", "C": "Transsphenoidal surgery is used to remove pituitary adenomas or decompress the sella, but it does not address the hormonal deficiencies of hypopituitarism, which still require replacement therapy.", "D": "Dopamine agonists (e.g., cabergoline) are used to treat prolactinomas by suppressing excess prolactin, the opposite therapeutic goal from replacing deficient hormones in hypopituitarism."}}}, {"id": "anking-endocrine-pathology-1583", "fuente": "anking", "tema": 5, "anki": "1462209855035", "q": "Which type of diabetes insipidus has etiologies including pituitary tumor, autoimmune destruction, trauma, surgery, and ischemic encephalopathy affecting ADH production?", "o": {"A": "Nephrogenic diabetes insipidus", "B": "Central diabetes insipidus", "C": "Primary polydipsia", "D": "Gestational diabetes insipidus"}, "r": "B", "e": {"correcta": "Central diabetes insipidus results from impaired synthesis or release of ADH from the hypothalamus/posterior pituitary, caused by suprasellar tumors, autoimmune destruction of ADH-producing neurons, head trauma or neurosurgery damaging the pituitary stalk, and ischemic or infiltrative processes (sarcoidosis, Langerhans cell histiocytosis, hemochromatosis) that disrupt the neurohypophysis.", "incorrectas": {"A": "Nephrogenic diabetes insipidus arises from renal collecting duct unresponsiveness to ADH (e.g., lithium toxicity, hypercalcemia, genetic AQP2/V2 receptor mutations), not from problems with ADH production itself.", "C": "Primary polydipsia is due to excessive water intake causing physiologic ADH suppression, not to structural or autoimmune damage to ADH-producing centers.", "D": "Gestational diabetes insipidus is caused by placental vasopressinase degrading circulating ADH during pregnancy, a distinct mechanism from central pituitary/hypothalamic damage."}}}, {"id": "anking-endocrine-pathology-1584", "fuente": "anking", "tema": 5, "anki": "1462209898939", "q": "Both central and nephrogenic diabetes insipidus are characterized by a urine specific gravity below what value?", "o": {"A": "1.010", "B": "1.006", "C": "1.020", "D": "1.030"}, "r": "B", "e": {"correcta": "In diabetes insipidus, whether central (lack of ADH) or nephrogenic (renal resistance to ADH), the kidneys cannot concentrate urine, producing dilute urine with specific gravity less than 1.006, reflecting the massive excretion of free water.", "incorrectas": {"A": "A specific gravity around 1.010 is roughly isosthenuric (similar to plasma) and would not reflect the markedly dilute urine characteristic of uncontrolled diabetes insipidus.", "C": "A specific gravity of 1.020 reflects appropriately concentrated urine, which occurs when ADH is present and functioning, the opposite of what is seen in diabetes insipidus.", "D": "A specific gravity of 1.030 indicates highly concentrated urine, seen in states of volume depletion with intact ADH response, not in diabetes insipidus."}}}, {"id": "anking-endocrine-pathology-1585", "fuente": "anking", "tema": 5, "anki": "1462210021520", "q": "Both central and nephrogenic diabetes insipidus are characterized by what change in urine osmolality?", "o": {"A": "Markedly elevated urine osmolality", "B": "Low urine osmolality", "C": "Urine osmolality equal to serum osmolality", "D": "Urine osmolality that fluctuates unpredictably"}, "r": "B", "e": {"correcta": "Because ADH is either absent (central DI) or ineffective at the renal collecting duct (nephrogenic DI), water cannot be reabsorbed, resulting in inappropriately dilute urine with low osmolality despite a concentrated, hyperosmolar serum.", "incorrectas": {"A": "Markedly elevated urine osmolality would indicate effective ADH action concentrating the urine, which is precisely what fails to occur in diabetes insipidus.", "C": "Urine osmolality equal to serum (isosthenuria) suggests a fixed inability to either concentrate or dilute urine, distinct from the profoundly low urine osmolality typical of DI.", "D": "Unpredictable fluctuation is not the classic pattern; DI consistently produces low, dilute urine osmolality regardless of serum osmolality."}}}, {"id": "anking-endocrine-pathology-1586", "fuente": "anking", "tema": 5, "anki": "1462210030535", "q": "Due to a decreased ability to retain water, both central and nephrogenic diabetes insipidus are characterized by a serum osmolality above what threshold?", "o": {"A": "250 mOsm/kg", "B": "270 mOsm/kg", "C": "290 mOsm/kg", "D": "310 mOsm/kg"}, "r": "C", "e": {"correcta": "Because diabetes insipidus impairs renal water reabsorption, free water is lost in excess, concentrating the blood and raising serum osmolality above 290 mOsm/kg, which in turn stimulates thirst and polydipsia if the patient has access to water.", "incorrectas": {"A": "250 mOsm/kg is below the normal range and would suggest water excess or hyponatremia (e.g., SIADH), the opposite of the hyperosmolar state seen in diabetes insipidus.", "B": "270 mOsm/kg is still within or below the normal physiologic range and does not reflect the hyperosmolar state driven by excessive free water loss in DI.", "D": "310 mOsm/kg would represent an even more extreme derangement; the classic threshold cited for diabetes insipidus's serum hyperosmolality is greater than 290 mOsm/kg."}}}, {"id": "anking-endocrine-pathology-1587", "fuente": "anking", "tema": 5, "anki": "1462210050114", "q": "Because the lack of effective ADH activity causes excess water excretion, both central and nephrogenic diabetes insipidus lead to what change in blood volume?", "o": {"A": "Hyperosmotic volume expansion", "B": "Hyperosmotic volume contraction", "C": "Isotonic volume expansion", "D": "Hypoosmotic volume contraction"}, "r": "B", "e": {"correcta": "Since ADH deficiency or resistance prevents water reabsorption, patients lose free water in excess of solute, producing a hyperosmotic (concentrated) blood with contracted intravascular volume, unless fluid intake compensates for ongoing losses.", "incorrectas": {"A": "Volume expansion would require excess retention of water or sodium, the opposite process of the free water loss that defines diabetes insipidus.", "C": "Isotonic volume expansion implies proportional gain of water and sodium without a change in osmolality, inconsistent with the hyperosmolar contraction seen in DI.", "D": "Hypoosmotic volume contraction (as in adrenal insufficiency with sodium loss) reflects a different derangement; DI causes contraction with hyperosmolality, not hypoosmolality, because free water (not sodium) is preferentially lost."}}}, {"id": "anking-endocrine-pathology-1588", "fuente": "anking", "tema": 5, "anki": "1462210111594", "q": "Central diabetes insipidus is characterized by what level of circulating ADH?", "o": {"A": "Low ADH levels", "B": "Normal ADH levels", "C": "Elevated ADH levels", "D": "ADH levels that vary with time of day"}, "r": "A", "e": {"correcta": "Central diabetes insipidus arises from destruction or dysfunction of the hypothalamic neurons or posterior pituitary that produce and release ADH, so circulating ADH levels are low, leading to an inability to concentrate urine despite an appropriate osmotic stimulus.", "incorrectas": {"B": "Normal ADH levels would not explain the clinical syndrome of polyuria and dilute urine seen in central DI, since the defect is a lack of ADH production, not receptor unresponsiveness.", "C": "Elevated ADH levels are seen in nephrogenic diabetes insipidus (as a compensatory response to renal resistance) and in SIADH, not in central DI where the hormone itself is deficient.", "D": "Diurnal fluctuation is not the defining feature; the hallmark of central DI is a persistently low ADH level due to impaired production or secretion."}}}, {"id": "anking-endocrine-pathology-1589", "fuente": "anking", "tema": 5, "anki": "1462210119948", "q": "Nephrogenic diabetes insipidus is characterized by what level of circulating ADH?", "o": {"A": "Low ADH levels", "B": "Absent ADH levels", "C": "Normal or elevated ADH levels", "D": "Progressively declining ADH levels"}, "r": "C", "e": {"correcta": "In nephrogenic diabetes insipidus, the hypothalamus and posterior pituitary produce ADH normally (or even in excess, as a compensatory response to persistent hyperosmolality), but the renal collecting ducts fail to respond appropriately, due to causes such as lithium toxicity, hypercalcemia, or mutations in the V2 receptor or aquaporin-2 channel.", "incorrectas": {"A": "Low ADH levels are the hallmark of central diabetes insipidus, which results from deficient hormone production rather than renal resistance.", "B": "Absent ADH would also point toward central DI (particularly severe cases); nephrogenic DI specifically features intact or increased ADH secretion with renal unresponsiveness.", "D": "Progressive decline in ADH describes a pattern of worsening central hormone deficiency, not the renal-level resistance mechanism that defines nephrogenic DI."}}}, {"id": "anking-endocrine-pharmacology-1590", "fuente": "anking", "tema": 24, "anki": "1462210128881", "q": "In addition to hydration, treatment of central diabetes insipidus includes which ADH analog?", "o": {"A": "Demeclocycline", "B": "Tolvaptan", "C": "Desmopressin", "D": "Conivaptan"}, "r": "C", "e": {"correcta": "Desmopressin (DDAVP) is a synthetic ADH analog selective for the V2 receptor that restores water reabsorption in the renal collecting ducts, correcting the polyuria of central diabetes insipidus where endogenous ADH is deficient.", "incorrectas": {"A": "Demeclocycline is a tetracycline that induces nephrogenic diabetes insipidus by antagonizing ADH action at the kidney, used to treat SIADH, the opposite therapeutic goal from replacing ADH in central DI.", "B": "Tolvaptan is an oral V2 receptor antagonist used to treat hyponatremia from SIADH by blocking ADH's effect, not to replace ADH as is needed in central DI.", "D": "Conivaptan is a combined V1a/V2 receptor antagonist used for euvolemic or hypervolemic hyponatremia (e.g., SIADH), again blocking rather than replacing ADH activity."}}}, {"id": "anking-endocrine-pharmacology-1591", "fuente": "anking", "tema": 24, "anki": "1462210181914", "q": "Besides hydration, treatment of nephrogenic diabetes insipidus includes which thiazide diuretic?", "o": {"A": "Furosemide", "B": "Spironolactone", "C": "Acetazolamide", "D": "Hydrochlorothiazide (HCTZ)"}, "r": "D", "e": {"correcta": "Paradoxically, thiazide diuretics like HCTZ help nephrogenic diabetes insipidus by causing mild volume depletion, which increases proximal tubule sodium and water reabsorption and thereby decreases delivery of fluid to the collecting duct, reducing urine output; indomethacin and amiloride may also be used as adjuncts.", "incorrectas": {"A": "Furosemide is a loop diuretic that inhibits the Na-K-2Cl cotransporter in the thick ascending limb, impairing the countercurrent mechanism and worsening the kidney's diluting/concentrating capacity rather than helping nephrogenic DI.", "B": "Spironolactone is a potassium-sparing aldosterone antagonist used for conditions like hyperaldosteronism or heart failure, not a standard treatment for nephrogenic DI.", "C": "Acetazolamide is a carbonic anhydrase inhibitor used for conditions like glaucoma or altitude sickness, unrelated to the volume-contraction mechanism thiazides use to treat nephrogenic DI."}}}, {"id": "anking-endocrine-pathology-1592", "fuente": "anking", "tema": 5, "anki": "1462210183851", "q": "Diagnosis of diabetes insipidus is aided by which diagnostic test?", "o": {"A": "Water deprivation test", "B": "Dexamethasone suppression test", "C": "Oral glucose tolerance test", "D": "TRH stimulation test"}, "r": "A", "e": {"correcta": "The water deprivation test assesses the kidney's ability to concentrate urine when water intake is withheld; failure to appropriately increase urine osmolality supports a diagnosis of diabetes insipidus, and subsequent administration of desmopressin helps distinguish central (osmolality rises) from nephrogenic (osmolality remains low) DI.", "incorrectas": {"B": "The dexamethasone suppression test evaluates cortisol suppression and is used to diagnose Cushing syndrome, not disorders of water balance like diabetes insipidus.", "C": "The oral glucose tolerance test assesses glucose handling for diagnosing diabetes mellitus or gestational diabetes, an entirely different disease process from diabetes insipidus.", "D": "The TRH stimulation test evaluates the hypothalamic-pituitary-thyroid axis and is used in thyroid or pituitary function testing, not for diagnosing diabetes insipidus."}}}, {"id": "anking-endocrine-pathology-1593", "fuente": "anking", "tema": 5, "anki": "1462210190761", "q": "In diabetes insipidus, the water deprivation test fails to produce what expected change in urine osmolality?", "o": {"A": "A decrease in urine osmolality", "B": "An increase in urine osmolality", "C": "No change at all in serum sodium", "D": "A decrease in serum osmolality"}, "r": "B", "e": {"correcta": "Normally, water deprivation triggers ADH release, causing urine osmolality to rise as the kidney concentrates urine to conserve water; in diabetes insipidus, this expected rise fails to occur because ADH is either deficient (central) or ineffective (nephrogenic), and only administration of an ADH analog restores concentration in the central form.", "incorrectas": {"A": "A decrease in urine osmolality would not be the expected normal response to water deprivation in the first place, so this option describes the wrong baseline expectation being tested.", "C": "Serum sodium is expected to rise, not stay unchanged, during water deprivation in DI as free water is progressively lost; the key diagnostic failure being tested is the urine osmolality response, not serum sodium stability.", "D": "Serum osmolality is expected to increase (not decrease) during water deprivation in DI, since ongoing free water loss without adequate reabsorption concentrates the blood."}}}, {"id": "anking-endocrine-pathology-1594", "fuente": "anking", "tema": 5, "anki": "1462210209207", "q": "SIADH may be caused by which lung malignancy, which serves as a source of ectopic ADH production?", "o": {"A": "Squamous cell carcinoma", "B": "Adenocarcinoma", "C": "Small cell lung carcinoma", "D": "Large cell carcinoma"}, "r": "C", "e": {"correcta": "Small cell lung carcinoma is a neuroendocrine tumor with paraneoplastic potential, capable of ectopically synthesizing and secreting ADH independent of hypothalamic osmotic or volume regulation, producing SIADH with excess free water retention and hyponatremia.", "incorrectas": {"A": "Squamous cell carcinoma of the lung is more classically associated with ectopic PTHrP secretion causing hypercalcemia, not ectopic ADH production.", "B": "Adenocarcinoma is the most common lung cancer subtype overall but is not the classic paraneoplastic source of ectopic ADH; that association belongs to small cell carcinoma.", "D": "Large cell carcinoma is a poorly differentiated non-small cell lung cancer without the characteristic neuroendocrine ADH-secreting paraneoplastic association seen with small cell carcinoma."}}}, {"id": "anking-endocrine-pathology-1595", "fuente": "anking", "tema": 5, "anki": "1462210245186", "q": "Disease of which organ system is most commonly associated with SIADH?", "o": {"A": "Gastrointestinal", "B": "Pulmonary", "C": "Renal", "D": "Musculoskeletal"}, "r": "B", "e": {"correcta": "Pulmonary disease is the most common association with SIADH, classically through ectopic ADH secretion from small cell lung carcinoma, but also from pneumonia, tuberculosis, and other lung pathology that can trigger nonosmotic ADH release.", "incorrectas": {"A": "Gastrointestinal disease is not the classic organ system linked to SIADH; while various malignancies can rarely cause ectopic hormone secretion, the strongest and most tested association is pulmonary.", "C": "Renal disease is more classically linked to disorders of sodium and water handling like nephrogenic diabetes insipidus rather than to SIADH, which is primarily driven by excess ADH from central or ectopic pulmonary sources.", "D": "Musculoskeletal disease has no established classic association with SIADH; this option does not fit the paraneoplastic and pulmonary mechanisms typically tested."}}}, {"id": "anking-endocrine-pathology-1596", "fuente": "anking", "tema": 5, "anki": "1462210256039", "q": "SIADH is characterized by increased renal handling of free water in which direction?", "o": {"A": "Increased excretion", "B": "Increased retention", "C": "No net change", "D": "Increased filtration without reabsorption"}, "r": "B", "e": {"correcta": "SIADH involves inappropriately elevated ADH activity at the renal collecting duct, promoting excessive aquaporin-2-mediated water reabsorption and thus increased retention of free water, which dilutes serum sodium and produces hyponatremia despite normal or expanded volume status.", "incorrectas": {"A": "Increased excretion of free water is the opposite of what occurs in SIADH; excess ADH activity causes the kidney to retain, not excrete, water.", "C": "No net change would not explain the hyponatremia and low serum osmolality characteristic of SIADH, which results directly from excess water retention.", "D": "Filtration without reabsorption describes a state of water loss, contrary to the pathophysiology of SIADH, in which reabsorption of water is specifically increased."}}}, {"id": "anking-endocrine-pathology-1597", "fuente": "anking", "tema": 5, "anki": "1462210267018", "q": "SIADH is characterized by what relationship between urine osmolality and serum osmolality?", "o": {"A": "Urine osmolality equal to serum osmolality", "B": "Urine osmolality greater than serum osmolality", "C": "Urine osmolality less than serum osmolality", "D": "Urine osmolality that cannot be measured reliably"}, "r": "B", "e": {"correcta": "In SIADH, excess ADH causes the kidney to concentrate urine inappropriately relative to the diluted serum, so urine osmolality remains greater than serum osmolality even though serum osmolality is low, reflecting the kidney's failure to appropriately excrete free water despite hypoosmolar serum.", "incorrectas": {"A": "Equal osmolalities (isosthenuria) would suggest a fixed inability to concentrate or dilute urine, not the inappropriately concentrated urine relative to dilute serum seen in SIADH.", "C": "Urine osmolality less than serum osmolality would indicate appropriate dilution in response to low serum osmolality, which is the expected normal physiologic response, not the pathologic pattern of SIADH.", "D": "Urine osmolality is a standard, reliably measurable lab value and is central to diagnosing SIADH; this option does not reflect the actual pathophysiology being tested."}}}, {"id": "anking-endocrine-pathology-1598", "fuente": "anking", "tema": 5, "anki": "1462210280338", "q": "SIADH is characterized by which volume and sodium status, despite continued urinary sodium excretion?", "o": {"A": "Hypervolemic hypernatremia", "B": "Hypovolemic hyponatremia", "C": "Euvolemic hyponatremia", "D": "Euvolemic hypernatremia"}, "r": "C", "e": {"correcta": "In SIADH, water retention mildly expands intravascular volume, which suppresses aldosterone and promotes continued renal sodium excretion (aldosterone escape), so the net result is a clinically euvolemic state with dilutional hyponatremia rather than overt volume overload.", "incorrectas": {"A": "Hypervolemic hypernatremia is not characteristic of SIADH; the mild volume expansion from water retention is compensated by natriuresis, and sodium is low (not high) due to dilution.", "B": "Hypovolemic hyponatremia describes states of true volume depletion with secondary ADH release (e.g., diarrhea, diuretic use), not SIADH, in which the patient is euvolemic rather than volume-depleted.", "D": "Euvolemic hypernatremia would suggest a defect in water retention causing high sodium concentration, the opposite of SIADH's dilutional hyponatremia from excess ADH-driven water retention."}}}, {"id": "anking-endocrine-pathology-1599", "fuente": "anking", "tema": 5, "anki": "1462210406620", "q": "In SIADH, serum sodium must be corrected slowly to prevent which complication?", "o": {"A": "Cerebral edema", "B": "Osmotic demyelination syndrome", "C": "Rhabdomyolysis", "D": "Acute tubular necrosis"}, "r": "B", "e": {"correcta": "Rapid correction of chronic hyponatremia causes water to shift out of brain cells that have adapted to the low-osmolality state, leading to osmotic demyelination syndrome (formerly central pontine myelinolysis), which can cause irreversible neurologic deficits including quadriplegia and locked-in syndrome; sodium correction should therefore proceed gradually.", "incorrectas": {"A": "Cerebral edema is the risk of correcting hyponatremia too slowly or of the hyponatremia itself worsening acutely, causing water to shift into brain cells, the opposite direction of fluid shift from rapid overcorrection.", "C": "Rhabdomyolysis is muscle breakdown typically from crush injury, prolonged immobilization, or certain drugs, unrelated to the osmotic shifts from correcting sodium too quickly.", "D": "Acute tubular necrosis is a form of intrinsic kidney injury from ischemia or nephrotoxins, not a recognized consequence of rapid sodium correction in SIADH."}}}, {"id": "anking-endocrine-pharmacology-1600", "fuente": "anking", "tema": 24, "anki": "1462210416123", "q": "In addition to water restriction, treatment of SIADH includes which tetracycline-class drug?", "o": {"A": "Doxycycline", "B": "Minocycline", "C": "Demeclocycline", "D": "Tigecycline"}, "r": "C", "e": {"correcta": "Demeclocycline is a tetracycline derivative that induces nephrogenic diabetes insipidus by antagonizing ADH's effect on the renal collecting duct, making it useful to treat SIADH when water restriction is insufficient; IV hypertonic saline and vasopressin receptor antagonists like conivaptan or tolvaptan are other treatment options.", "incorrectas": {"A": "Doxycycline is a commonly used tetracycline for infections (e.g., Lyme disease, chlamydia) but does not have the ADH-antagonist property used therapeutically in SIADH.", "B": "Minocycline is another tetracycline antibiotic notable for CNS penetration and use in acne, not for antagonizing ADH activity in the kidney.", "D": "Tigecycline is a glycylcycline antibiotic used for broad-spectrum coverage of resistant infections, unrelated to the ADH-antagonizing renal effect that makes demeclocycline useful in SIADH."}}}, {"id": "anking-endocrine-anatomy-1601", "fuente": "anking", "tema": 25, "anki": "1462211176329", "q": "During embryonic development, the thyroid forms at the base of the tongue and migrates to the anterior neck via which structure?", "o": {"A": "Thyroglossal duct", "B": "Branchial cleft", "C": "Pharyngeal pouch remnant", "D": "Ultimobranchial body"}, "r": "A", "e": {"correcta": "The thyroid diverticulum arises from the floor of the primitive pharynx (derived from the first pharyngeal arch region) around 3-4 weeks of gestation and migrates caudally through the thyroglossal duct to reach its final position in the anterior neck below the larynx.", "incorrectas": {"B": "Branchial (pharyngeal) clefts give rise to external structures like the external auditory meatus, not the migratory pathway of the thyroid gland.", "C": "Pharyngeal pouches give rise to structures such as the tonsils, thymus, and parathyroid glands, but the thyroid's specific route of descent is the thyroglossal duct, not a persisting pouch remnant.", "D": "The ultimobranchial body, derived from the fourth/fifth pharyngeal pouches, contributes the parafollicular (C) cells to the thyroid, but it is not the ductal structure along which the thyroid gland itself migrates."}}}, {"id": "anking-endocrine-anatomy-1602", "fuente": "anking", "tema": 25, "anki": "1462211180559", "q": "Which structure at the base of the tongue is the normal remnant of the thyroglossal duct?", "o": {"A": "Vallate papillae", "B": "Foramen cecum", "C": "Lingual tonsil", "D": "Sulcus terminalis"}, "r": "B", "e": {"correcta": "The foramen cecum marks the original site of the thyroid primordium at the junction of the anterior two-thirds and posterior one-third of the tongue, representing the normal residual opening of the thyroglossal duct after the thyroid completes its caudal migration.", "incorrectas": {"A": "Vallate papillae are large mushroom-shaped papillae arranged just anterior to the sulcus terminalis, involved in taste, not related to the thyroglossal duct's course.", "C": "The lingual tonsil is lymphoid tissue at the base of the tongue, part of Waldeyer's ring, unrelated to thyroid gland embryology or the thyroglossal duct.", "D": "The sulcus terminalis is a V-shaped groove separating the anterior and posterior tongue, a landmark near the foramen cecum but not itself the thyroglossal duct remnant."}}}, {"id": "anking-endocrine-anatomy-1603", "fuente": "anking", "tema": 25, "anki": "1462211182904", "q": "A partially involuted thyroglossal duct may present as what structure on the thyroid gland?", "o": {"A": "Pyramidal lobe", "B": "Isthmus duplication", "C": "Ectopic parathyroid tissue", "D": "Thyroid diverticulum cyst at the hyoid"}, "r": "A", "e": {"correcta": "When the thyroglossal duct does not fully involute, a small cone-shaped pyramidal lobe of thyroid tissue can persist extending upward from the isthmus, usually toward the left of midline, as a normal anatomic variant reflecting incomplete regression of the duct.", "incorrectas": {"B": "Isthmus duplication is not a recognized anomaly associated with the thyroglossal duct; the classic residual finding is a pyramidal lobe, not a duplicated isthmus.", "C": "Ectopic parathyroid tissue results from aberrant migration of the parathyroid glands (derived from pharyngeal pouches), an entirely separate embryologic process from thyroglossal duct involution.", "D": "A thyroglossal duct cyst can occur anywhere along the duct's course (often near the hyoid bone) as a distinct cystic anomaly, but the specific residual thyroid tissue described here is the pyramidal lobe, not a cyst."}}}, {"id": "anking-endocrine-anatomy-1604", "fuente": "anking", "tema": 25, "anki": "1462211192914", "q": "What is the most common site for ectopic thyroid tissue?", "o": {"A": "The mediastinum", "B": "The tongue", "C": "The esophagus", "D": "The thymus"}, "r": "B", "e": {"correcta": "Because the thyroid originates at the foramen cecum at the tongue base and must migrate caudally along the thyroglossal duct, failure of descent most commonly leaves ectopic thyroid tissue lodged in the tongue, producing a lingual thyroid, which can be the patient's only functioning thyroid tissue.", "incorrectas": {"A": "Mediastinal ectopic thyroid tissue (substernal goiter) can occur from excessive descent but is far less common than the lingual thyroid caused by incomplete cranial-to-caudal migration.", "C": "The esophagus is not a typical site for ectopic thyroid tissue, as it lies outside the normal path traced by the thyroglossal duct during descent.", "D": "The thymus derives from the third pharyngeal pouch and migrates to the mediastinum separately from the thyroid; it is not a typical site of ectopic thyroid tissue."}}}, {"id": "anking-endocrine-pathology-1605", "fuente": "anking", "tema": 5, "anki": "1462218872220", "q": "By what mechanism does hyperthyroidism increase the basal metabolic rate?", "o": {"A": "Increased synthesis of Na+-K+ ATPase pumps", "B": "Increased mitochondrial biogenesis in adipocytes only", "C": "Decreased thyroid hormone receptor expression", "D": "Increased glycogen storage in the liver"}, "r": "A", "e": {"correcta": "Thyroid hormone increases the transcription of Na+-K+ ATPase pumps across many tissues, which consumes substantial ATP to maintain ion gradients, thereby raising oxygen consumption and heat production and elevating the basal metabolic rate, a key mechanism behind the hypermetabolic features of hyperthyroidism.", "incorrectas": {"B": "While thyroid hormone does promote mitochondrial biogenesis broadly, the specific and classically tested mechanism for increased BMR is upregulation of Na+-K+ ATPase pumps across multiple tissues, not an adipocyte-restricted effect.", "C": "Hyperthyroidism is associated with increased, not decreased, sensitivity and receptor-mediated signaling of thyroid hormone in target tissues; decreased receptor expression would blunt rather than enhance metabolic effects.", "D": "Increased glycogen storage would represent an anabolic, energy-conserving process, whereas hyperthyroidism actually promotes glycogenolysis and a catabolic state consistent with elevated metabolic demand."}}}, {"id": "anking-endocrine-pathology-1606", "fuente": "anking", "tema": 5, "anki": "1462219763138", "q": "By what mechanism does hyperthyroidism increase sympathetic nervous system activity?", "o": {"A": "Increased circulating catecholamine synthesis", "B": "Increased expression of β1-adrenergic receptors", "C": "Decreased catecholamine reuptake at nerve terminals", "D": "Direct stimulation of the adrenal medulla by thyroid hormone"}, "r": "B", "e": {"correcta": "Thyroid hormone upregulates the expression of β1-adrenergic receptors in tissues such as the heart, sensitizing them to normal circulating catecholamine levels and producing the tachycardia, tremor, and increased cardiac output characteristic of hyperthyroidism, without necessarily increasing actual catecholamine levels.", "incorrectas": {"A": "Catecholamine synthesis itself is not typically increased in hyperthyroidism; rather, tissue sensitivity to existing catecholamine levels is enhanced through receptor upregulation.", "C": "Catecholamine reuptake inhibition is not the mechanism at play in hyperthyroidism; the effect is receptor-level sensitization (increased β1 receptor density), not altered neurotransmitter clearance.", "D": "Thyroid hormone does not directly stimulate the adrenal medulla to release catecholamines; instead, it amplifies peripheral tissue responsiveness to normal sympathetic tone via increased adrenergic receptor expression."}}}, {"id": "anking-endocrine-pathology-1607", "fuente": "anking", "tema": 5, "anki": "1462219774801", "q": "Which thyroid imbalance presents with decreased heat production (cold intolerance) and decreased sweating?", "o": {"A": "Hyperthyroidism", "B": "Hypothyroidism", "C": "Subclinical hyperthyroidism", "D": "Euthyroid sick syndrome"}, "r": "B", "e": {"correcta": "Hypothyroidism decreases Na+-K+ ATPase activity and overall cellular metabolism, lowering the basal metabolic rate and reducing calorigenesis, which manifests clinically as cold intolerance and decreased sweating due to diminished heat generation.", "incorrectas": {"A": "Hyperthyroidism causes the opposite picture: increased Na+-K+ ATPase activity raises BMR and heat production, leading to heat intolerance and increased sweating rather than cold intolerance.", "C": "Subclinical hyperthyroidism refers to a mild biochemical elevation in thyroid hormone activity without overt symptoms, and would trend toward heat intolerance if symptomatic, not cold intolerance.", "D": "Euthyroid sick syndrome reflects abnormal thyroid function tests in the setting of systemic nonthyroidal illness without a true intrinsic thyroid hormone deficiency causing cold intolerance."}}}, {"id": "anking-endocrine-pathology-1608", "fuente": "anking", "tema": 5, "anki": "1462219782959", "q": "Which thyroid imbalance presents with increased heat production (heat intolerance) and increased sweating?", "o": {"A": "Hypothyroidism", "B": "Hyperthyroidism", "C": "Central hypothyroidism", "D": "Sick euthyroid syndrome"}, "r": "B", "e": {"correcta": "Hyperthyroidism increases synthesis of Na+-K+ ATPase pumps, raising the basal metabolic rate and calorigenesis, which produces excess heat generation manifesting as heat intolerance and increased sweating (diaphoresis).", "incorrectas": {"A": "Hypothyroidism produces the opposite clinical picture, with decreased BMR leading to cold intolerance and decreased sweating rather than heat intolerance.", "C": "Central hypothyroidism, caused by deficient TSH from the pituitary, still results in low thyroid hormone levels and the associated hypometabolic features, not the hypermetabolic heat intolerance of hyperthyroidism.", "D": "Sick euthyroid syndrome involves abnormal thyroid function tests during systemic illness without a true hyperthyroid state driving increased heat production."}}}, {"id": "anking-endocrine-pathology-1609", "fuente": "anking", "tema": 5, "anki": "1462219790083", "q": "Which thyroid imbalance presents with weight loss and increased appetite?", "o": {"A": "Hypothyroidism", "B": "Hyperthyroidism", "C": "Hashimoto thyroiditis in its late fibrotic stage", "D": "Myxedema"}, "r": "B", "e": {"correcta": "Hyperthyroidism raises the basal metabolic rate and accelerates catabolism of fat and protein stores; despite a compensatory increase in appetite and food intake, the elevated metabolic demand outpaces caloric intake, resulting in net weight loss.", "incorrectas": {"A": "Hypothyroidism slows metabolism and is classically associated with weight gain and decreased appetite, the opposite pattern from hyperthyroidism.", "C": "Hashimoto thyroiditis in its late fibrotic stage results in hypothyroidism (as the gland is progressively destroyed), which produces weight gain and decreased appetite, not weight loss with increased appetite.", "D": "Myxedema refers to the severe hypothyroid state with dermal mucopolysaccharide deposition, associated with weight gain and hypometabolism, not the weight loss and hyperphagia of hyperthyroidism."}}}, {"id": "anking-endocrine-pathology-1610", "fuente": "anking", "tema": 5, "anki": "1462219795034", "q": "Which thyroid imbalance presents with weight gain and decreased appetite?", "o": {"A": "Hyperthyroidism", "B": "Hypothyroidism", "C": "Graves disease", "D": "Toxic multinodular goiter"}, "r": "B", "e": {"correcta": "Hypothyroidism decreases the basal metabolic rate, slowing caloric expenditure, while appetite is also reduced; the net effect of lower energy needs combined with continued (even if diminished) intake is weight gain, a classic feature distinguishing it from hyperthyroid states.", "incorrectas": {"A": "Hyperthyroidism increases metabolic rate and typically increases appetite, but because caloric expenditure outpaces intake, it causes weight loss rather than weight gain.", "C": "Graves disease is the most common cause of hyperthyroidism, driven by TSH receptor-stimulating autoantibodies, and thus presents with weight loss and increased appetite, not weight gain.", "D": "Toxic multinodular goiter causes autonomous thyroid hormone overproduction, resulting in a hyperthyroid clinical picture with weight loss, not the weight gain seen in hypothyroidism."}}}, {"id": "anking-endocrine-pathology-1611", "fuente": "anking", "tema": 5, "anki": "1462219844221", "q": "Which thyroid imbalance presents with hyperdefecation or diarrhea due to increased GI motility?", "o": {"A": "Hypothyroidism", "B": "Hyperthyroidism", "C": "Subclinical hypothyroidism", "D": "Riedel thyroiditis"}, "r": "B", "e": {"correcta": "Hyperthyroidism increases sympathetic tone and overall metabolic activity throughout the gut, accelerating intestinal transit and producing increased bowel frequency or frank diarrhea (hyperdefecation), one of the classic gastrointestinal manifestations of thyrotoxicosis.", "incorrectas": {"A": "Hypothyroidism slows metabolism and reduces GI motility, classically producing constipation rather than diarrhea.", "C": "Subclinical hypothyroidism involves mildly elevated TSH with normal thyroid hormone levels and, if anything, would trend toward reduced GI motility rather than hyperdefecation.", "D": "Riedel thyroiditis is a rare fibrosing thyroiditis that typically causes hypothyroidism and a hard, fixed goiter, associated with decreased (not increased) GI motility."}}}, {"id": "anking-endocrine-pathology-1612", "fuente": "anking", "tema": 5, "anki": "1462219845577", "q": "Which thyroid imbalance presents with constipation due to decreased GI motility?", "o": {"A": "Hyperthyroidism", "B": "Graves disease", "C": "Hypothyroidism", "D": "Thyroid storm"}, "r": "C", "e": {"correcta": "Hypothyroidism slows overall metabolic activity, including gastrointestinal smooth muscle motility, which leads to decreased peristalsis and constipation, a common and classic symptom of an underactive thyroid.", "incorrectas": {"A": "Hyperthyroidism accelerates GI motility due to a hypermetabolic, sympathetically driven state, producing hyperdefecation or diarrhea rather than constipation.", "B": "Graves disease is an autoimmune cause of hyperthyroidism and thus produces increased GI motility and diarrhea-type symptoms, not constipation.", "D": "Thyroid storm is a life-threatening exacerbation of severe hyperthyroidism, which would be expected to cause increased, not decreased, gastrointestinal motility."}}}, {"id": "anking-endocrine-pathology-1613", "fuente": "anking", "tema": 5, "anki": "1462219856267", "q": "A patient presents with delayed relaxation phase of deep tendon reflexes ('hung up' reflexes). Which thyroid disorder is most consistent with this finding?", "o": {"A": "Hyperthyroidism", "B": "Hypothyroidism", "C": "Primary hyperparathyroidism", "D": "Pheochromocytoma"}, "r": "B", "e": {"correcta": "Hypothyroidism slows the relaxation phase of deep tendon reflexes, producing the classic 'hung up' or delayed-relaxing reflex, because reduced thyroid hormone slows myocyte calcium reuptake and overall muscle contraction-relaxation kinetics.", "incorrectas": {"A": "Hyperthyroidism causes brisk, hyperactive reflexes due to increased catecholamine sensitivity and metabolic rate, the opposite of the delayed-relaxation pattern described here.", "C": "Primary hyperparathyroidism causes hypercalcemia, which classically produces hyporeflexia or muscle weakness rather than the specific slow-relaxing reflex phenomenon seen in hypothyroidism.", "D": "Pheochromocytoma causes catecholamine excess with tachycardia, hypertension, and diaphoresis, not the characteristic delayed reflex relaxation associated with low thyroid hormone."}}}, {"id": "anking-endocrine-pathology-1614", "fuente": "anking", "tema": 5, "anki": "1462219859743", "q": "Which thyroid disorder classically presents with brisk (hyperactive) deep tendon reflexes?", "o": {"A": "Hypothyroidism", "B": "Adrenal insufficiency", "C": "Hyperthyroidism", "D": "Hypoparathyroidism"}, "r": "C", "e": {"correcta": "Excess thyroid hormone increases the number and sensitivity of beta-adrenergic receptors and overall metabolic rate, producing brisk, hyperactive deep tendon reflexes as part of the hyperadrenergic state of hyperthyroidism.", "incorrectas": {"A": "Hypothyroidism produces the opposite finding: delayed-relaxation ('hung up') reflexes due to slowed muscle contraction-relaxation kinetics from low thyroid hormone.", "B": "Adrenal insufficiency (e.g., Addison disease) presents with fatigue, hypotension, and hyperpigmentation, not a characteristic hyperreflexia pattern tied to thyroid status.", "D": "Hypoparathyroidism causes hypocalcemia, which produces neuromuscular irritability (e.g., Chvostek and Trousseau signs) rather than the brisk reflexes characteristic of thyrotoxicosis."}}}, {"id": "anking-endocrine-pathology-1615", "fuente": "anking", "tema": 5, "anki": "1462219862784", "q": "A patient with a history of Graves disease presents with new-onset tachycardia, palpitations, and atrial fibrillation. This cardiac presentation is most characteristic of which condition?", "o": {"A": "Hypothyroidism", "B": "Hyperthyroidism", "C": "Primary hyperaldosteronism", "D": "Cushing syndrome"}, "r": "B", "e": {"correcta": "Hyperthyroidism increases the number and sensitivity of cardiac beta-adrenergic receptors, producing tachycardia, palpitations, and arrhythmias including atrial fibrillation; excess thyroid hormone directly increases heart rate and contractility.", "incorrectas": {"A": "Hypothyroidism causes bradycardia and decreased cardiac output rather than tachyarrhythmias, reflecting the generalized hypometabolic state from insufficient thyroid hormone.", "C": "Primary hyperaldosteronism causes hypertension and hypokalemia from excess mineralocorticoid activity, not the beta-adrenergic-driven tachyarrhythmias seen with thyroid hormone excess.", "D": "Cushing syndrome causes hypertension, central obesity, and hyperglycemia from cortisol excess, but is not classically associated with the tachyarrhythmias driven by increased beta-adrenergic receptor expression seen in hyperthyroidism."}}}, {"id": "anking-endocrine-pathology-1616", "fuente": "anking", "tema": 5, "anki": "1462219876107", "q": "A patient presents with bradycardia and dyspnea on exertion. Which thyroid disorder best explains this presentation?", "o": {"A": "Hyperthyroidism", "B": "Hypothyroidism", "C": "Subclinical hyperthyroidism", "D": "Toxic adenoma"}, "r": "B", "e": {"correcta": "Hypothyroidism slows the basal metabolic rate and reduces cardiac chronotropy and contractility, leading to bradycardia and reduced cardiac output that manifests as dyspnea on exertion; pericardial effusion can also contribute to exertional dyspnea in severe cases.", "incorrectas": {"A": "Hyperthyroidism increases metabolic demand and cardiac output, producing tachycardia rather than bradycardia, the opposite hemodynamic profile from what is described.", "C": "Subclinical hyperthyroidism (low TSH with normal T3/T4) would still tend toward mild tachycardia or arrhythmia risk rather than bradycardia.", "D": "Toxic adenoma is an autonomously functioning thyroid nodule causing hyperthyroidism, which produces tachycardia and hypermetabolic symptoms, not bradycardia."}}}, {"id": "anking-endocrine-pathology-1617", "fuente": "anking", "tema": 5, "anki": "1462219879343", "q": "A patient presents with proximal muscle weakness but a normal serum creatine kinase level. Which thyroid disorder is most likely responsible?", "o": {"A": "Hashimoto thyroiditis (late stage)", "B": "Hyperthyroidism", "C": "Subacute thyroiditis", "D": "Congenital hypothyroidism"}, "r": "B", "e": {"correcta": "Hyperthyroidism can cause thyrotoxic myopathy, a proximal muscle weakness resulting from accelerated protein catabolism and muscle breakdown, but classically with a normal creatine kinase, distinguishing it from other myopathies with elevated CK.", "incorrectas": {"A": "Late-stage Hashimoto thyroiditis leads to hypothyroidism, which causes a myopathy typically associated with an elevated CK (seen in up to 90% of cases), not a normal one.", "C": "Subacute (de Quervain) thyroiditis classically presents with a painful, tender thyroid and transient thyrotoxicosis followed by hypothyroidism, not the specific normal-CK myopathy pattern of chronic hyperthyroidism.", "D": "Congenital hypothyroidism (cretinism) presents in infancy with developmental delay and characteristic facies, not with an adult-onset myopathy with normal CK."}}}, {"id": "anking-endocrine-pathology-1618", "fuente": "anking", "tema": 5, "anki": "1462219894892", "q": "A patient presents with proximal muscle weakness, myalgias, and an elevated serum creatine kinase. Which thyroid disorder is most likely responsible?", "o": {"A": "Hyperthyroidism", "B": "Hypothyroidism", "C": "Graves disease", "D": "Toxic multinodular goiter"}, "r": "B", "e": {"correcta": "Hypothyroidism causes a myopathy with weakness, cramps, and myalgias, and serum CK is elevated in up to 90% of cases due to decreased clearance and altered muscle membrane integrity from thyroid hormone deficiency.", "incorrectas": {"A": "Hyperthyroidism causes thyrotoxic myopathy, which presents with proximal weakness but characteristically a normal CK, the opposite lab finding described here.", "C": "Graves disease is a cause of hyperthyroidism (via TSH receptor-stimulating antibodies) and would produce the normal-CK myopathy pattern, not an elevated CK.", "D": "Toxic multinodular goiter causes hyperthyroidism from autonomously functioning nodules, which is again associated with thyrotoxic myopathy and a normal CK rather than an elevated one."}}}, {"id": "anking-endocrine-pathology-1619", "fuente": "anking", "tema": 5, "anki": "1462219903584", "q": "Hyperthyroidism is classically associated with which cholesterol abnormality, and what is the underlying mechanism?", "o": {"A": "Hypercholesterolemia due to decreased LDL receptor expression", "B": "Hypocholesterolemia due to increased LDL receptor expression", "C": "Hypertriglyceridemia due to decreased lipoprotein lipase activity", "D": "Hypocholesterolemia due to decreased hepatic cholesterol synthesis"}, "r": "B", "e": {"correcta": "Thyroid hormone upregulates hepatic LDL receptor expression, increasing clearance of circulating LDL cholesterol from the blood; this produces the hypocholesterolemia characteristically seen in hyperthyroidism.", "incorrectas": {"A": "This describes the mechanism in hypothyroidism, where decreased LDL receptor expression leads to reduced LDL clearance and hypercholesterolemia, the opposite of what occurs in hyperthyroidism.", "C": "Hyperthyroidism is not primarily characterized by hypertriglyceridemia from lipoprotein lipase dysfunction; the classic lipid finding is hypocholesterolemia via enhanced LDL receptor-mediated clearance.", "D": "The mechanism is increased LDL receptor-mediated clearance of cholesterol from the blood, not a primary decrease in hepatic cholesterol synthesis."}}}, {"id": "anking-endocrine-pathology-1620", "fuente": "anking", "tema": 5, "anki": "1462219909563", "q": "Hypothyroidism is classically associated with which cholesterol abnormality, and what is the underlying mechanism?", "o": {"A": "Hypocholesterolemia due to increased LDL receptor expression", "B": "Hypertriglyceridemia due to increased lipoprotein lipase activity", "C": "Hypercholesterolemia due to decreased LDL receptor expression", "D": "Hypercholesterolemia due to increased hepatic cholesterol synthesis"}, "r": "C", "e": {"correcta": "Low thyroid hormone levels reduce hepatic LDL receptor expression, impairing clearance of LDL cholesterol from the circulation and resulting in hypercholesterolemia, a common finding in hypothyroid patients.", "incorrectas": {"A": "This describes hyperthyroidism, in which increased LDL receptor expression enhances cholesterol clearance and causes hypocholesterolemia, the opposite of the hypothyroid lipid profile.", "B": "Hypothyroidism is not primarily defined by increased lipoprotein lipase activity; in fact, reduced lipoprotein lipase activity can contribute to lipid abnormalities, but the hallmark mechanism tested is decreased LDL receptor expression.", "D": "The mechanism is decreased clearance of LDL cholesterol due to fewer LDL receptors, not an increase in hepatic cholesterol synthesis."}}}, {"id": "anking-endocrine-pathology-1621", "fuente": "anking", "tema": 5, "anki": "1462219919701", "q": "Hyperthyroidism is associated with which glucose abnormality, and by what mechanism?", "o": {"A": "Hypoglycemia due to increased peripheral glucose uptake", "B": "Hyperglycemia due to increased gluconeogenesis and glycogenolysis", "C": "Hypoglycemia due to decreased glycogenolysis", "D": "Hyperglycemia due to decreased insulin receptor sensitivity alone"}, "r": "B", "e": {"correcta": "Excess thyroid hormone accelerates hepatic gluconeogenesis and glycogenolysis, increasing hepatic glucose output and contributing to the mild hyperglycemia and glucose intolerance sometimes seen in hyperthyroid patients.", "incorrectas": {"A": "Hyperthyroidism does not typically cause hypoglycemia; increased peripheral glucose uptake is not the dominant mechanism, whereas increased hepatic glucose production drives hyperglycemia instead.", "C": "Hyperthyroidism increases, rather than decreases, glycogenolysis, contributing to higher rather than lower blood glucose.", "D": "While hyperthyroidism can be associated with some insulin resistance, the classically tested mechanism is increased hepatic gluconeogenesis and glycogenolysis driving glucose output, not solely decreased insulin receptor sensitivity."}}}, {"id": "anking-endocrine-pathology-1622", "fuente": "anking", "tema": 5, "anki": "1462219925082", "q": "Graves disease is an example of which type of hypersensitivity reaction?", "o": {"A": "Type I (IgE-mediated)", "B": "Type III (immune complex-mediated)", "C": "Type II (antibody-mediated)", "D": "Type IV (T cell-mediated)"}, "r": "C", "e": {"correcta": "Graves disease is a Type II hypersensitivity reaction in which autoantibodies (thyroid-stimulating immunoglobulins) bind and activate the TSH receptor on thyroid follicular cells, mimicking TSH and driving unregulated thyroid hormone synthesis and release.", "incorrectas": {"A": "Type I hypersensitivity involves IgE-mediated mast cell degranulation in immediate allergic reactions, not autoantibody-mediated receptor stimulation as seen in Graves disease.", "B": "Type III hypersensitivity involves immune complex deposition causing tissue damage (e.g., serum sickness, lupus nephritis), which is distinct from the direct receptor-stimulating antibody mechanism in Graves disease.", "D": "Type IV hypersensitivity is T cell-mediated (delayed-type), as in contact dermatitis or granulomatous disease, whereas Graves disease is driven by a circulating stimulating autoantibody, a Type II mechanism."}}}, {"id": "anking-endocrine-pathology-1623", "fuente": "anking", "tema": 5, "anki": "1462219932103", "q": "Graves disease most commonly develops in which demographic group, often precipitated by a period of physiologic stress?", "o": {"A": "Elderly men, precipitated by surgery", "B": "Women of childbearing age, often during stress such as childbirth", "C": "Adolescent males, often during puberty", "D": "Postmenopausal women, often during iodine supplementation"}, "r": "B", "e": {"correcta": "Graves disease most commonly affects women of childbearing age and often presents or flares during periods of physiologic stress such as childbirth (postpartum), reflecting the autoimmune nature of the disease and its interplay with immune modulation around pregnancy.", "incorrectas": {"A": "Graves disease is far more common in women than men and is not classically triggered by surgery; postoperative stress can precipitate thyroid storm in an already hyperthyroid patient but is not the typical precipitant described for new-onset Graves disease.", "C": "Graves disease is not classically an adolescent male disease; it predominates in women, particularly during reproductive age.", "D": "Iodine supplementation can precipitate hyperthyroidism (Jod-Basedow phenomenon) in patients with underlying nodular thyroid disease, but the classic demographic and stress trigger for Graves disease is a woman of childbearing age around events like childbirth."}}}, {"id": "anking-endocrine-pathology-1624", "fuente": "anking", "tema": 5, "anki": "1462219938805", "q": "What type of goiter is characteristically seen in Graves disease?", "o": {"A": "Nodular goiter", "B": "Diffuse goiter", "C": "Substernal goiter", "D": "Fibrotic (Riedel) goiter"}, "r": "B", "e": {"correcta": "Graves disease produces a diffuse, symmetric enlargement of the thyroid gland because TSH receptor-stimulating antibodies uniformly stimulate follicular cell hypertrophy and hyperplasia throughout the entire gland, rather than in isolated nodules.", "incorrectas": {"A": "A nodular goiter, as in toxic multinodular goiter, arises from discrete autonomously functioning nodules rather than the diffuse, uniform stimulation of the whole gland characteristic of Graves disease.", "C": "A substernal goiter refers to extension of an enlarged thyroid into the mediastinum, a structural/anatomic descriptor unrelated to the diffuse autoimmune process specific to Graves disease.", "D": "Riedel (fibrosing) thyroiditis produces a hard, fixed, fibrotic thyroid mass, an entirely different pathologic process from the diffuse hyperplastic goiter of Graves disease."}}}, {"id": "anking-endocrine-pathology-1625", "fuente": "anking", "tema": 5, "anki": "1462220165879", "q": "A patient with untreated Graves disease develops severe agitation, high fever, and tachyarrhythmia after undergoing emergency surgery. Which life-threatening endocrine emergency does this represent?", "o": {"A": "Myxedema coma", "B": "Adrenal crisis", "C": "Thyroid storm", "D": "Pheochromocytoma crisis"}, "r": "C", "e": {"correcta": "Thyroid storm is a severe, life-threatening exacerbation of hyperthyroidism precipitated by acute stress (infection, trauma, surgery) in a patient with preexisting hyperthyroid disease such as Graves disease or toxic multinodular goiter; the acute stress triggers a massive catecholamine surge that drives the florid symptoms.", "incorrectas": {"A": "Myxedema coma is the severe decompensated form of hypothyroidism, presenting with hypothermia, bradycardia, and altered mental status, the opposite physiologic direction from the hyperadrenergic thyroid storm.", "B": "Adrenal crisis results from acute cortisol deficiency, presenting with hypotension, shock, and hyponatremia/hyperkalemia, not the hyperthermic tachyarrhythmic picture driven by thyroid hormone excess.", "D": "A pheochromocytoma crisis involves paroxysmal catecholamine release from an adrenal medullary tumor causing episodic hypertension, headache, and palpitations, but is not linked to preexisting hyperthyroidism as thyroid storm is."}}}, {"id": "anking-endocrine-pathology-1626", "fuente": "anking", "tema": 5, "anki": "1462220175783", "q": "In thyroid storm, agitation, delirium, fever, diarrhea, and coma may occur. Which cardiac finding is the most common cause of death in this condition?", "o": {"A": "Tachyarrhythmia", "B": "Complete heart block", "C": "Cardiac tamponade", "D": "Bradyarrhythmia"}, "r": "A", "e": {"correcta": "Thyroid storm produces a massive catecholamine surge and hypermetabolic state that leads to severe tachyarrhythmias (including atrial fibrillation and other rhythm disturbances), which is the most common cause of death in this condition.", "incorrectas": {"B": "Complete heart block is a bradyarrhythmia typically related to conduction system disease or drug toxicity, not the hyperadrenergic tachyarrhythmic process driving mortality in thyroid storm.", "C": "Cardiac tamponade results from pericardial fluid accumulation compressing the heart, a mechanical process unrelated to the hypermetabolic, catecholamine-driven pathophysiology of thyroid storm.", "D": "Bradyarrhythmia would be expected in hypothyroid states (e.g., myxedema coma), not in the hyperadrenergic, tachycardic state of thyroid storm."}}}, {"id": "anking-endocrine-pathology-1627", "fuente": "anking", "tema": 5, "anki": "1462220180615", "q": "In thyroid storm, which serum marker may be elevated due to increased bone turnover?", "o": {"A": "Parathyroid hormone", "B": "Alkaline phosphatase", "C": "Vitamin D", "D": "Osteocalcin only, with normal alkaline phosphatase"}, "r": "B", "e": {"correcta": "Thyroid hormone excess accelerates bone remodeling and turnover, which can elevate serum alkaline phosphatase (along with liver function tests) in thyroid storm, reflecting the hypermetabolic effect of thyroid hormone on bone as well as liver.", "incorrectas": {"A": "Parathyroid hormone is regulated independently by serum calcium and is not the marker classically elevated due to increased bone turnover in thyroid storm; thyroid hormone itself, not PTH, drives the increased turnover here.", "C": "Vitamin D levels are not characteristically altered by the hypermetabolic bone turnover of thyroid storm; the classic marker tested is alkaline phosphatase.", "D": "While osteocalcin can also rise with bone turnover, alkaline phosphatase is the classic, commonly tested elevated marker in this setting, not an isolated osteocalcin rise with normal alkaline phosphatase."}}}, {"id": "anking-endocrine-pathology-1628", "fuente": "anking", "tema": 5, "anki": "1462220216737", "q": "An enlarged thyroid gland containing multiple discrete nodules is best described as which entity?", "o": {"A": "Diffuse goiter", "B": "Multinodular goiter", "C": "Papillary thyroid carcinoma", "D": "Riedel thyroiditis"}, "r": "B", "e": {"correcta": "A multinodular goiter is an enlarged thyroid gland containing multiple nodules, often arising from relative iodine deficiency and long-standing TSH stimulation causing repeated cycles of hyperplasia and involution; it is usually nontoxic (euthyroid) but can become toxic if nodules develop autonomous function.", "incorrectas": {"A": "A diffuse goiter refers to uniform enlargement without discrete nodules, as classically seen in Graves disease, which is a distinct pattern from the multiple discrete nodules of multinodular goiter.", "C": "Papillary thyroid carcinoma is a malignant neoplasm with characteristic nuclear features (Orphan Annie eyes, psammoma bodies), not simply a description of a benign, multiply-nodular enlarged gland.", "D": "Riedel thyroiditis is a rare fibrosing process that replaces thyroid tissue with dense fibrous tissue, producing a hard, fixed gland, distinct from the nodular hyperplastic pattern of multinodular goiter."}}}, {"id": "anking-endocrine-pathology-1629", "fuente": "anking", "tema": 5, "anki": "1462220231068", "q": "A multinodular goiter is termed 'toxic' when which of the following occurs?", "o": {"A": "The nodules become malignant", "B": "Hyperfunctioning follicular cells within the nodules work independently of TSH, increasing T3/T4 release", "C": "The gland becomes fibrotic and calcified", "D": "TSH levels rise markedly due to pituitary hyperplasia"}, "r": "B", "e": {"correcta": "A toxic multinodular goiter arises when hyperfunctioning follicular cells within some of the nodules acquire autonomous, TSH-independent activity, leading to excess, unregulated release of T3 and T4 and clinical hyperthyroidism, in contrast to the euthyroid state of a typical nontoxic multinodular goiter.", "incorrectas": {"A": "Malignant transformation is a separate concern in nodular thyroid disease but is not what defines a goiter as 'toxic'; toxicity refers specifically to autonomous hormone hypersecretion, not malignancy.", "C": "Fibrosis and calcification are histologic changes that can be seen in longstanding nodular goiters but do not define toxicity, which is a functional (hormonal) designation, not a structural one.", "D": "In toxic multinodular goiter, TSH is suppressed (low), not elevated, because autonomous hormone production creates negative feedback inhibition of the pituitary, the opposite of pituitary TSH hypersecretion."}}}, {"id": "anking-endocrine-pathology-1630", "fuente": "anking", "tema": 5, "anki": "1462220276669", "q": "Toxic multinodular goiter is most often caused by activating mutations in which gene/receptor (accounting for roughly 60% of cases)?", "o": {"A": "RET proto-oncogene", "B": "TSH receptor", "C": "RAS", "D": "BRAF"}, "r": "B", "e": {"correcta": "Approximately 60% of toxic multinodular goiter cases arise from activating (gain-of-function) mutations in the TSH receptor gene, causing constitutive, TSH-independent stimulation of follicular cells and excess thyroid hormone production.", "incorrectas": {"A": "RET proto-oncogene mutations are classically associated with medullary thyroid carcinoma and MEN2 syndromes, not the functional hyperthyroidism of toxic multinodular goiter.", "C": "RAS mutations can be found in some follicular thyroid neoplasms but are not the predominant mutation responsible for the autonomous hyperfunction in toxic multinodular goiter.", "D": "BRAF mutations (e.g., V600E) are characteristic of papillary thyroid carcinoma, a malignant process distinct from the benign, hyperfunctioning nodules of toxic multinodular goiter."}}}, {"id": "anking-endocrine-pathology-1631", "fuente": "anking", "tema": 5, "anki": "1462220327470", "q": "Hypothyroidism presenting in neonates and infants, causing impaired growth and neurodevelopment, is known by which term?", "o": {"A": "Myxedema", "B": "Cretinism", "C": "Hashitoxicosis", "D": "Graves ophthalmopathy"}, "r": "B", "e": {"correcta": "Cretinism refers to hypothyroidism occurring in neonates and infants, and if untreated leads to severe impairment of physical growth and neurologic/cognitive development because thyroid hormone is essential for normal brain maturation during this critical period.", "incorrectas": {"A": "Myxedema refers to the non-pitting edema from glycosaminoglycan accumulation in the skin seen in adult hypothyroidism, not the specific term for congenital/infantile hypothyroidism.", "C": "Hashitoxicosis refers to the transient hyperthyroid phase sometimes seen early in Hashimoto thyroiditis due to follicular disruption, unrelated to the term for infantile hypothyroidism.", "D": "Graves ophthalmopathy is the autoimmune eye disease (exophthalmos, periorbital edema) associated with Graves disease, a hyperthyroid condition, not the term for infantile hypothyroidism."}}}, {"id": "anking-endocrine-pathology-1632", "fuente": "anking", "tema": 5, "anki": "1462223715564", "q": "A pot-bellied, pale, puffy-faced infant with a protruding umbilicus, protuberant tongue, and poor brain development most likely has which condition?", "o": {"A": "Down syndrome", "B": "Cretinism", "C": "Congenital adrenal hyperplasia", "D": "Beckwith-Wiedemann syndrome"}, "r": "B", "e": {"correcta": "This constellation of findings — pot-belly, pallor, puffy face, umbilical hernia, macroglossia, and impaired neurodevelopment — is the classic description of cretinism, the clinical picture of congenital hypothyroidism, reflecting thyroid hormone's essential role in growth and CNS maturation.", "incorrectas": {"A": "Down syndrome has its own characteristic facial features (epicanthal folds, flat facies, single palmar crease) and cardiac defects, distinct from the puffy, myxedematous facies and umbilical hernia of cretinism, although the two conditions can coexist.", "C": "Congenital adrenal hyperplasia presents with ambiguous genitalia, salt-wasting, or virilization depending on the enzyme deficiency, not the puffy, hypothyroid facies described here.", "D": "Beckwith-Wiedemann syndrome features macrosomia, macroglossia, and omphalocele, but is a growth-dysregulation syndrome unrelated to thyroid hormone deficiency and does not include poor brain development as a core feature in the same way cretinism does."}}}, {"id": "anking-endocrine-pathology-1633", "fuente": "anking", "tema": 5, "anki": "1462223763124", "q": "A congenital defect in thyroid hormone production leading to cretinism is termed which of the following?", "o": {"A": "Thyroid dysgenesis", "B": "Dyshormonogenetic goiter", "C": "Subacute thyroiditis", "D": "Riedel thyroiditis"}, "r": "B", "e": {"correcta": "Dyshormonogenetic goiter refers to a congenital defect in the enzymatic machinery of thyroid hormone synthesis, leading to inadequate hormone production despite a structurally present (often enlarged, from compensatory TSH-driven hyperplasia) thyroid gland, and can cause cretinism.", "incorrectas": {"A": "Thyroid dysgenesis refers to abnormal development of the thyroid gland itself (e.g., ectopic or absent gland tissue) rather than a defect in the hormone-synthesizing enzymes; it is actually the most common overall cause of cretinism in the U.S., but is a distinct entity from dyshormonogenetic goiter.", "C": "Subacute (de Quervain) thyroiditis is an acquired, typically post-viral inflammatory condition in older children/adults, not a congenital enzymatic defect causing cretinism.", "D": "Riedel thyroiditis is a rare fibrosing disease of the thyroid in adults, unrelated to congenital hormone synthesis defects."}}}, {"id": "anking-endocrine-pathology-1634", "fuente": "anking", "tema": 5, "anki": "1462223772224", "q": "Dyshormonogenetic goiter most commonly results from a deficiency of which enzyme involved in thyroid hormone synthesis?", "o": {"A": "5'-deiodinase", "B": "Thyroid peroxidase", "C": "Thyroglobulin synthase", "D": "Sodium-iodide symporter only"}, "r": "B", "e": {"correcta": "Thyroid peroxidase deficiency is the most common cause of dyshormonogenetic goiter; this enzyme is required for oxidation and organification of iodide as well as coupling of iodotyrosines to form T3/T4, so its absence severely impairs hormone synthesis despite compensatory gland hyperplasia.", "incorrectas": {"A": "5'-deiodinase converts T4 to the more active T3 peripherally, but a defect here is not the most common cause of dyshormonogenetic goiter, which is predominantly due to peroxidase deficiency.", "C": "There is no major enzyme called 'thyroglobulin synthase' driving dyshormonogenetic goiter in the classic teaching; thyroglobulin itself can be mutated, but thyroid peroxidase deficiency is the classically tested most common cause.", "D": "Isolated sodium-iodide symporter defects can impair iodide trapping and cause dyshormonogenesis, but they are less common than thyroid peroxidase deficiency as the cause of dyshormonogenetic goiter."}}}, {"id": "anking-endocrine-pathology-1635", "fuente": "anking", "tema": 5, "anki": "1462223781267", "q": "What is the most common cause of cretinism (congenital hypothyroidism) in the United States?", "o": {"A": "Maternal iodine deficiency", "B": "Dyshormonogenetic goiter", "C": "Thyroid dysgenesis", "D": "Maternal Hashimoto thyroiditis with antibody transfer"}, "r": "C", "e": {"correcta": "Thyroid dysgenesis (abnormal thyroid gland development, including ectopic or hypoplastic gland tissue) is the most common cause of cretinism in the United States, where iodine sufficiency is generally not a limiting factor.", "incorrectas": {"A": "Maternal iodine deficiency is a major cause of congenital hypothyroidism worldwide (especially in iodine-deficient regions), but it is not the most common cause in the iodine-sufficient United States.", "B": "Dyshormonogenetic goiter, often due to thyroid peroxidase deficiency, is an important but less common cause of cretinism compared to thyroid dysgenesis.", "D": "Antibody-mediated maternal hypothyroidism (transfer of TSH receptor-blocking antibodies) is a recognized but less common cause of congenital hypothyroidism compared to thyroid dysgenesis."}}}, {"id": "anking-endocrine-pathology-1636", "fuente": "anking", "tema": 5, "anki": "1462223802155", "q": "In hypothyroidism, myxedema (glycosaminoglycan deposition) commonly affects which two structures, producing a deep voice and an enlarged tongue respectively?", "o": {"A": "Vocal cords and parotid gland", "B": "Larynx and tongue", "C": "Epiglottis and salivary glands", "D": "Trachea and lips"}, "r": "B", "e": {"correcta": "Myxedema in hypothyroidism results from accumulation of glycosaminoglycans and hyaluronic acid in tissues; when this occurs in the larynx it produces a deep, husky voice, and when it occurs in the tongue it causes macroglossia (tongue enlargement), both classic findings of severe hypothyroidism.", "incorrectas": {"A": "The vocal cords and parotid gland are not the classic sites cited for the deep voice and tongue enlargement of myxedema; the larynx broadly (not isolated vocal cord swelling) and tongue are the structures specifically implicated.", "C": "The epiglottis and salivary glands are not the classically described sites of myxedematous deposition responsible for voice change and macroglossia in hypothyroidism.", "D": "The trachea and lips are not the tissues classically cited for producing the deep voice and enlarged tongue seen in myxedema."}}}, {"id": "anking-endocrine-pathology-1637", "fuente": "anking", "tema": 5, "anki": "1462223809215", "q": "Dry, cool skin and coarse, brittle hair are most characteristic of which thyroid disorder?", "o": {"A": "Hyperthyroidism", "B": "Hypothyroidism", "C": "Subacute thyroiditis", "D": "Thyroid storm"}, "r": "B", "e": {"correcta": "Hypothyroidism reduces blood flow to dermal vessels and slows overall metabolism, resulting in dry, cool skin and coarse, brittle hair, reflecting the generalized hypometabolic state and decreased cutaneous perfusion.", "incorrectas": {"A": "Hyperthyroidism causes warm, moist skin and fine hair due to increased dermal blood flow and heat production from the hypermetabolic state, the opposite of the dry, cool skin described here.", "C": "Subacute thyroiditis is defined by a painful, tender thyroid gland during a transient inflammatory process, not by the chronic dermatologic changes of established hypothyroidism.", "D": "Thyroid storm is an acute hyperthyroid crisis presenting with fever, tachycardia, and warm/diaphoretic skin, not the dry, cool skin of hypothyroidism."}}}, {"id": "anking-endocrine-pathology-1638", "fuente": "anking", "tema": 5, "anki": "1462223812155", "q": "Warm, moist skin and fine hair are most characteristic of which thyroid disorder?", "o": {"A": "Hypothyroidism", "B": "Hashimoto thyroiditis (late stage)", "C": "Hyperthyroidism", "D": "Myxedema coma"}, "r": "C", "e": {"correcta": "Hyperthyroidism increases blood flow to dermal vessels and raises basal metabolic rate, producing warm, moist skin and fine hair, reflecting the hypermetabolic and vasodilated state caused by excess thyroid hormone.", "incorrectas": {"A": "Hypothyroidism causes decreased dermal blood flow, producing dry, cool skin and coarse hair, the opposite of the warm, moist skin and fine hair described here.", "B": "Late-stage Hashimoto thyroiditis results in hypothyroidism, which produces dry, cool skin, not the warm, moist skin characteristic of thyroid hormone excess.", "D": "Myxedema coma is severe, decompensated hypothyroidism with hypothermia and dry skin, the opposite clinical picture from the warm, moist skin of hyperthyroidism."}}}, {"id": "anking-endocrine-pathology-1639", "fuente": "anking", "tema": 5, "anki": "1462223814642", "q": "Hashimoto thyroiditis is associated with which HLA haplotypes?", "o": {"A": "HLA-B27 and HLA-B8", "B": "HLA-DR3 and HLA-DR5", "C": "HLA-DR2 and HLA-DR4", "D": "HLA-A3 and HLA-DQ2"}, "r": "B", "e": {"correcta": "Hashimoto thyroiditis has a well-established association with HLA-DR3 and HLA-DR5, consistent with its autoimmune pathogenesis in which genetically susceptible individuals develop cytotoxic T cell- and antibody-mediated destruction of thyroid follicular cells.", "incorrectas": {"A": "HLA-B27 is classically associated with the seronegative spondyloarthropathies (ankylosing spondylitis, reactive arthritis), not Hashimoto thyroiditis.", "C": "HLA-DR2 and HLA-DR4 are associated with other autoimmune conditions (e.g., DR4 with rheumatoid arthritis and type 1 diabetes, DR2 with MS and Goodpasture syndrome), not the classic Hashimoto association.", "D": "HLA-DQ2 is associated with celiac disease, and HLA-A3 with hemochromatosis; neither is the classic haplotype pairing linked to Hashimoto thyroiditis."}}}, {"id": "anking-endocrine-pathology-1640", "fuente": "anking", "tema": 5, "anki": "1462223819821", "q": "In regions with adequate iodine intake, what is the most common cause of hypothyroidism?", "o": {"A": "Iodine deficiency", "B": "Subacute granulomatous (de Quervain) thyroiditis", "C": "Hashimoto thyroiditis", "D": "Wolff-Chaikoff effect"}, "r": "C", "e": {"correcta": "Hashimoto thyroiditis, an autoimmune process involving cytotoxic T cell-mediated destruction of thyroid follicular cells and circulating anti-thyroid peroxidase/anti-thyroglobulin antibodies, is the most common cause of hypothyroidism in iodine-sufficient regions such as the United States.", "incorrectas": {"A": "Iodine deficiency remains the most common cause of hypothyroidism worldwide, particularly in regions like Southeast Asia and Africa, but not in iodine-replete areas where Hashimoto predominates.", "B": "Subacute granulomatous thyroiditis is typically a self-limited, post-viral condition causing transient thyroid dysfunction (often with a painful gland), not the leading chronic cause of hypothyroidism in iodine-sufficient populations.", "D": "The Wolff-Chaikoff effect is a transient autoregulatory reduction in thyroid hormone synthesis following an acute iodine load; while it can cause transient hypothyroidism, it is not the most common overall cause in iodine-sufficient regions."}}}, {"id": "anking-endocrine-pathology-1641", "fuente": "anking", "tema": 5, "anki": "1462223846795", "q": "Early in its course, Hashimoto thyroiditis may transiently present with which thyroid functional state, before ultimately progressing to hypothyroidism?", "o": {"A": "Euthyroidism", "B": "Hyperthyroidism due to thyrotoxicosis from follicular rupture", "C": "Isolated central hypothyroidism", "D": "Subclinical hypothyroidism only"}, "r": "B", "e": {"correcta": "Early Hashimoto thyroiditis can present with transient hyperthyroidism ('hashitoxicosis') as autoimmune destruction ruptures thyroid follicles and releases preformed stored hormone into circulation, before follicular reserve is depleted and the disease progresses to the chronic hypothyroid state (low T4, elevated TSH).", "incorrectas": {"A": "While a euthyroid phase can occur at some point, the classically tested early transient state specifically driven by follicular rupture is hyperthyroidism (thyrotoxicosis), not simple euthyroidism.", "C": "Hashimoto thyroiditis is a primary thyroid gland process (peripheral), not a pituitary/hypothalamic disorder, so it does not cause central hypothyroidism.", "D": "Subclinical hypothyroidism (elevated TSH with normal T4) can occur later in the disease course as gland reserve declines, but it is not the described transient early presentation caused by follicular rupture and hormone release."}}}, {"id": "anking-endocrine-pathology-1642", "fuente": "anking", "tema": 5, "anki": "1462223891730", "q": "Histologically, Hashimoto thyroiditis is characterized by chronic inflammatory infiltrate with which additional finding, reflecting active B cell involvement?", "o": {"A": "Granulomas with multinucleated giant cells", "B": "Well-developed germinal centers", "C": "Psammoma bodies", "D": "Amyloid deposition"}, "r": "B", "e": {"correcta": "Hashimoto thyroiditis shows chronic lymphocytic inflammation with well-developed germinal centers, reflecting the autoimmune process in which T cells attack thyroid follicular cells and activate B cells, which organize into germinal centers and produce anti-thyroid antibodies.", "incorrectas": {"A": "Granulomas with giant cells are the hallmark of subacute granulomatous (de Quervain) thyroiditis, a distinct, typically post-viral and self-limited condition, not Hashimoto thyroiditis.", "C": "Psammoma bodies are calcified, laminated structures characteristic of papillary thyroid carcinoma (and other tumors like meningioma, serous ovarian carcinoma), not the inflammatory histology of Hashimoto thyroiditis.", "D": "Amyloid deposition in the thyroid is characteristic of medullary thyroid carcinoma (amyloid derived from calcitonin), not the lymphocytic and germinal center-rich histology of Hashimoto thyroiditis."}}}, {"id": "anking-endocrine-pathology-1643", "fuente": "anking", "tema": 5, "anki": "1462223900918", "q": "Histologically, Hashimoto thyroiditis may show eosinophilic, metaplastic cells lining atrophic thyroid follicles. What are these cells called?", "o": {"A": "Reed-Sternberg cells", "B": "Hurthle cells", "C": "Langhans giant cells", "D": "Anitschkow cells"}, "r": "B", "e": {"correcta": "Hurthle cells are eosinophilic, granular metaplastic follicular epithelial cells (with abundant mitochondria) that line thyroid follicles in Hashimoto thyroiditis, reflecting a chronic injury/regenerative response of the follicular epithelium to ongoing autoimmune attack.", "incorrectas": {"A": "Reed-Sternberg cells are the characteristic binucleated 'owl-eye' cells of classic Hodgkin lymphoma, unrelated to thyroid epithelial metaplasia in Hashimoto thyroiditis.", "C": "Langhans giant cells are multinucleated cells seen in granulomatous inflammation (e.g., tuberculosis, subacute granulomatous thyroiditis), not the eosinophilic metaplastic epithelial cells of Hashimoto thyroiditis.", "D": "Anitschkow cells ('caterpillar cells') are activated macrophages seen in Aschoff bodies in rheumatic heart disease, unrelated to thyroid histology."}}}, {"id": "anking-endocrine-pathology-1644", "fuente": "anking", "tema": 5, "anki": "1462223916411", "q": "Patients with Hashimoto thyroiditis have an increased risk of developing which malignancy, which may present as an enlarging thyroid late in the disease course?", "o": {"A": "Papillary thyroid carcinoma", "B": "Medullary thyroid carcinoma", "C": "B-cell (marginal zone) lymphoma", "D": "Anaplastic thyroid carcinoma"}, "r": "C", "e": {"correcta": "Chronic autoimmune inflammation and B cell activation in Hashimoto thyroiditis increase the long-term risk of primary thyroid B-cell (marginal zone/MALT-type) lymphoma, which can present as a rapidly enlarging thyroid gland late in the disease course.", "incorrectas": {"A": "Papillary thyroid carcinoma is the most common thyroid cancer overall and can have some epidemiologic association with autoimmune thyroid disease, but the specific, classically tested malignancy linked to chronic Hashimoto inflammation is B-cell lymphoma, not papillary carcinoma.", "B": "Medullary thyroid carcinoma arises from parafollicular C cells and is associated with MEN2 syndromes and RET mutations, not with the chronic lymphocytic inflammation of Hashimoto thyroiditis.", "D": "Anaplastic thyroid carcinoma is an aggressive, undifferentiated tumor typically arising in older patients, often from dedifferentiation of preexisting differentiated thyroid cancer, not specifically linked to Hashimoto-associated lymphoid proliferation."}}}, {"id": "anking-endocrine-pathology-1645", "fuente": "anking", "tema": 5, "anki": "1462223924118", "q": "On physical exam, is the thyroid gland in Hashimoto thyroiditis typically tender or nontender?", "o": {"A": "Tender and warm", "B": "Nontender and mildly enlarged", "C": "Tender with overlying erythema", "D": "Nontender but markedly enlarged and rock-hard"}, "r": "B", "e": {"correcta": "Hashimoto thyroiditis classically presents with a nontender, mildly enlarged (and sometimes firm/rubbery) thyroid gland, distinguishing it from the painful thyroiditis seen in subacute (de Quervain) thyroiditis.", "incorrectas": {"A": "A tender, warm thyroid is not typical of Hashimoto thyroiditis; tenderness is much more characteristic of subacute granulomatous (de Quervain) thyroiditis.", "C": "Tenderness with overlying erythema would suggest acute suppurative thyroiditis (typically bacterial), not the nontender autoimmune process of Hashimoto thyroiditis.", "D": "While the gland can be mildly enlarged, it is not classically described as rock-hard; a hard, fixed gland is more characteristic of Riedel thyroiditis or invasive thyroid carcinoma, not Hashimoto thyroiditis."}}}, {"id": "anking-endocrine-pathology-1646", "fuente": "anking", "tema": 5, "anki": "1462223933107", "q": "Subacute granulomatous (de Quervain) thyroiditis is a self-limited condition that most often follows which trigger?", "o": {"A": "Bacterial infection", "B": "Viral infection", "C": "Iodine contrast administration", "D": "Radiation exposure"}, "r": "B", "e": {"correcta": "Subacute granulomatous (de Quervain) thyroiditis is a self-limited inflammatory condition that classically follows a viral upper respiratory infection, producing granulomatous inflammation and transient thyroid dysfunction that resolves over weeks to months.", "incorrectas": {"A": "Bacterial infection causing thyroid involvement would more typically produce acute suppurative thyroiditis with abscess formation, a distinct and rarer entity from the granulomatous, viral-associated de Quervain thyroiditis.", "C": "Iodine contrast administration can precipitate hyperthyroidism in susceptible patients (Jod-Basedow phenomenon) but is not the classic trigger for the granulomatous inflammatory process of de Quervain thyroiditis.", "D": "Radiation exposure is associated with increased risk of thyroid neoplasia (e.g., papillary carcinoma) over time, not with triggering the acute granulomatous inflammatory response of de Quervain thyroiditis."}}}, {"id": "anking-endocrine-pathology-1647", "fuente": "anking", "tema": 5, "anki": "1462223953253", "q": "On physical exam, is the thyroid gland in subacute granulomatous (de Quervain) thyroiditis typically tender or nontender?", "o": {"A": "Nontender and mildly enlarged", "B": "Very tender", "C": "Nontender but rock-hard and fixed", "D": "Tender only in children, nontender in adults"}, "r": "B", "e": {"correcta": "Subacute granulomatous (de Quervain) thyroiditis classically presents with a very tender thyroid gland, often with pain radiating to the jaw or ears, along with elevated inflammatory markers (ESR/CRP), distinguishing it from the painless thyroid enlargement of Hashimoto thyroiditis.", "incorrectas": {"A": "A nontender, mildly enlarged gland is characteristic of Hashimoto thyroiditis, not de Quervain thyroiditis, which is specifically known for marked tenderness.", "C": "A nontender, rock-hard, fixed gland is characteristic of Riedel thyroiditis, a fibrosing process distinct from the tender, self-limited granulomatous inflammation of de Quervain thyroiditis.", "D": "Tenderness in de Quervain thyroiditis is not restricted to children; it is a classic finding across affected patients regardless of age, typically young to middle-aged adults following a viral illness."}}}, {"id": "anking-endocrine-pathology-1648", "fuente": "anking", "tema": 5, "anki": "1462223990721", "q": "A patient develops a painful, tender thyroid gland after a recent viral upper respiratory infection. Thyroid function testing early in the course shows a transient thyrotoxic phase. Which phase of thyroid function typically follows this initial hyperthyroid period in subacute granulomatous (de Quervain) thyroiditis?", "o": {"A": "A transient hypothyroid phase", "B": "Permanent hyperthyroidism", "C": "Immediate return to euthyroid state without any hypothyroid phase", "D": "Progression directly to myxedema coma"}, "r": "A", "e": {"correcta": "De Quervain thyroiditis classically follows a triphasic course: an initial hyperthyroid phase from follicular disruption releasing preformed T3/T4, followed by a transient hypothyroid phase as hormone stores are depleted, and finally return to euthyroidism in the majority of patients. Thyroid symptoms are usually mild, and the hypothyroid phase becomes permanent in only about 15% of cases.", "incorrectas": {"B": "Permanent hyperthyroidism is not the typical pattern; the hyperthyroid phase is transient and due to passive leakage of preformed hormone from a damaged gland rather than ongoing overproduction, so it resolves rather than persisting.", "C": "The disease does not skip straight back to euthyroid; hormone stores become depleted after the initial leak, producing a distinct transient hypothyroid phase before most patients recover.", "D": "Myxedema coma is a severe, life-threatening decompensated hypothyroid state seen with profound long-standing hypothyroidism, not the expected outcome of the typically mild and self-limited hypothyroid phase of de Quervain thyroiditis."}}}, {"id": "anking-endocrine-pathology-1649", "fuente": "anking", "tema": 5, "anki": "1462224001342", "q": "Histologic examination of the thyroid in a patient with subacute (de Quervain) thyroiditis is most likely to reveal which finding?", "o": {"A": "Granulomatous inflammation with multinucleated giant cells", "B": "Dense fibrosis replacing normal parenchyma", "C": "Lymphocytic infiltrate with germinal centers", "D": "Papillary fronds with psammoma bodies"}, "r": "A", "e": {"correcta": "Subacute granulomatous thyroiditis is initially marked by a neutrophilic infiltrate with microabscess formation, which is later replaced by a granulomatous reaction with macrophages and multinucleated giant cells surrounding disrupted follicles, giving the disease its name.", "incorrectas": {"B": "Dense fibrosis with an inflammatory infiltrate replacing thyroid parenchyma is the hallmark of Riedel thyroiditis, not de Quervain thyroiditis, and reflects an IgG4-related fibrosing process rather than granulomatous inflammation.", "C": "A lymphocytic infiltrate with germinal center formation is characteristic of Hashimoto thyroiditis, an autoimmune process distinct from the postviral granulomatous reaction seen in de Quervain thyroiditis.", "D": "Papillary fronds with psammoma bodies are a histologic feature of papillary thyroid carcinoma, a neoplastic process unrelated to the inflammatory changes of subacute thyroiditis."}}}, {"id": "anking-endocrine-pathology-1650", "fuente": "anking", "tema": 5, "anki": "1462224038691", "q": "In Riedel thyroiditis, the normal thyroid parenchyma is progressively replaced by which type of tissue along with an inflammatory infiltrate?", "o": {"A": "Granulomatous tissue with giant cells", "B": "Fibrous tissue", "C": "Amyloid deposits", "D": "Adipose tissue"}, "r": "B", "e": {"correcta": "Riedel thyroiditis is characterized by dense fibrous tissue replacing the thyroid gland along with an inflammatory infiltrate, producing a hard, 'woody' thyroid that can extend into and fix adjacent neck structures such as strap muscles and the trachea.", "incorrectas": {"A": "Granulomatous tissue with giant cells is the hallmark of subacute (de Quervain) thyroiditis, not Riedel thyroiditis, and reflects a different pathogenic process centered on a postviral inflammatory reaction rather than progressive fibrosis.", "C": "Amyloid deposition within the thyroid is seen in medullary thyroid carcinoma, where calcitonin is deposited as amyloid stroma, not in Riedel thyroiditis.", "D": "Adipose replacement is not a described feature of any major thyroid pathology; Riedel thyroiditis specifically involves fibrous, not fatty, replacement of the gland."}}}, {"id": "anking-endocrine-pathology-1651", "fuente": "anking", "tema": 5, "anki": "1462224119900", "q": "Riedel thyroiditis most commonly affects which patient demographic?", "o": {"A": "Elderly men over 70", "B": "Neonates", "C": "Middle-aged women (30-50 years old)", "D": "Adolescent males"}, "r": "C", "e": {"correcta": "Riedel thyroiditis classically presents in middle-aged women between 30 and 50 years old with a hard, fixed thyroid mass. This demographic overlap with anaplastic thyroid carcinoma (which occurs in elderly patients) is an important distinguishing clinical clue between the two conditions.", "incorrectas": {"A": "Elderly patients, particularly elderly women, are the demographic classically affected by anaplastic thyroid carcinoma, which can mimic Riedel thyroiditis clinically but occurs in an older population.", "B": "Neonates are not a described population for Riedel thyroiditis, which is a disease of adulthood, typically arising in the fourth and fifth decades of life.", "D": "Adolescent males are not the typical demographic for any major thyroid disease covered here; Riedel thyroiditis shows a clear predilection for middle-aged women."}}}, {"id": "anking-endocrine-pathology-1652", "fuente": "anking", "tema": 5, "anki": "1462224134179", "q": "Riedel thyroiditis is considered part of a systemic fibrosing disease spectrum mediated by which immunoglobulin subclass, which also causes autoimmune pancreatitis and retroperitoneal fibrosis?", "o": {"A": "IgA", "B": "IgE", "C": "IgM", "D": "IgG4"}, "r": "D", "e": {"correcta": "Riedel thyroiditis is now recognized as a manifestation of IgG4-related systemic disease, a fibroinflammatory condition in which IgG4-bearing plasma cells infiltrate and cause fibrosis in multiple organs, including the thyroid, pancreas (autoimmune pancreatitis), retroperitoneum (retroperitoneal fibrosis), and aorta (noninfectious aortitis).", "incorrectas": {"A": "IgA is the predominant antibody in mucosal immunity and is not the immunoglobulin implicated in the fibrosing systemic disease that includes Riedel thyroiditis.", "B": "IgE mediates type I hypersensitivity reactions such as allergies and anaphylaxis, a mechanism unrelated to the chronic fibrosing plasma cell infiltration seen in IgG4-related disease.", "C": "IgM is the first antibody produced in a primary immune response and is involved in complement activation, not in the chronic fibrotic process characteristic of IgG4-related disease."}}}, {"id": "anking-endocrine-pathology-1653", "fuente": "anking", "tema": 5, "anki": "1462224141565", "q": "When a thyroid nodule is discovered, which outcome is statistically more likely?", "o": {"A": "The nodule is malignant", "B": "The nodule is benign", "C": "The nodule represents metastatic disease", "D": "The nodule is equally likely to be benign or malignant"}, "r": "B", "e": {"correcta": "The large majority of thyroid nodules discovered clinically or incidentally are benign, most commonly representing colloid nodules or follicular adenomas, which is why initial workup (TSH, ultrasound characteristics, and selective FNA) focuses on risk-stratifying rather than assuming malignancy.", "incorrectas": {"A": "While malignancy must always be excluded because of its clinical importance, thyroid nodules are statistically much more likely to be benign than malignant, so this option overstates the risk.", "C": "Metastatic disease to the thyroid is rare compared with primary thyroid nodules, which are overwhelmingly benign proliferative or colloid changes rather than secondary tumors from other organs.", "D": "The likelihood is not equal; the probability is skewed heavily toward benign findings, which is why FNA cytology is used to identify the minority of nodules that harbor malignancy."}}}, {"id": "anking-endocrine-pathology-1654", "fuente": "anking", "tema": 5, "anki": "1462228482324", "q": "Which imaging study is used to functionally characterize a thyroid nodule based on its uptake activity?", "o": {"A": "Technetium-99m sestamibi scan", "B": "131I radioactive iodine uptake study", "C": "Contrast-enhanced CT of the neck", "D": "Doppler ultrasound"}, "r": "B", "e": {"correcta": "Radioactive iodine (131I) uptake scanning is used to classify a thyroid nodule as 'hot' (increased uptake) or 'cold' (decreased uptake), reflecting its functional activity relative to surrounding thyroid tissue and guiding further workup.", "incorrectas": {"A": "Technetium-99m sestamibi scanning is primarily used to localize hyperfunctioning parathyroid tissue in parathyroid adenoma workup, not to characterize thyroid nodule function.", "C": "Contrast-enhanced CT can show anatomic detail and local invasion but does not assess the functional iodine-trapping activity of a nodule the way radioiodine uptake scanning does.", "D": "Doppler ultrasound assesses nodule size, vascularity, and suspicious structural features (e.g., microcalcifications, irregular margins) but does not measure iodine uptake or functional status."}}}, {"id": "anking-endocrine-pathology-1655", "fuente": "anking", "tema": 5, "anki": "1462228497868", "q": "A thyroid nodule demonstrating increased uptake of 131I on radioactive scanning is classified as which type of nodule, commonly seen in Graves disease or toxic nodular goiter?", "o": {"A": "Cold nodule", "B": "Hot nodule", "C": "Cystic nodule", "D": "Calcified nodule"}, "r": "B", "e": {"correcta": "A 'hot' nodule shows increased radioactive iodine uptake because it is autonomously producing thyroid hormone at a higher rate than surrounding tissue, as seen in toxic nodular goiter or diffusely in Graves disease. Hot nodules are rarely malignant and generally do not require biopsy.", "incorrectas": {"A": "A 'cold' nodule is the opposite finding, showing decreased 131I uptake, and carries a higher relative risk of malignancy, warranting biopsy rather than being reassuring like a hot nodule.", "C": "Cystic change refers to a structural, fluid-filled appearance on ultrasound and is not defined by radioiodine uptake activity; a cystic nodule could be either hot or cold on functional imaging.", "D": "Calcification, particularly microcalcification, is a structural ultrasound feature suggestive of papillary carcinoma, not a term used to describe radioiodine uptake status."}}}, {"id": "anking-endocrine-pathology-1656", "fuente": "anking", "tema": 5, "anki": "1462228511124", "q": "A thyroid nodule with decreased uptake of 131I on radioactive iodine scanning is classified as which type, and warrants further evaluation?", "o": {"A": "Hot nodule", "B": "Warm nodule", "C": "Cold nodule", "D": "Isofunctioning nodule"}, "r": "C", "e": {"correcta": "A 'cold' nodule shows decreased radioactive iodine uptake, indicating the tissue is not actively trapping iodine as well as surrounding normal thyroid parenchyma; this finding is concerning because it is associated with adenoma or carcinoma and requires further evaluation with fine needle aspiration.", "incorrectas": {"A": "A hot nodule shows increased, not decreased, iodine uptake and reflects autonomous hyperfunction, which is a reassuring finding rarely associated with malignancy, opposite to the cold nodule scenario.", "B": "Warm nodule is not a standard clinical classification used in thyroid scanning terminology; nodules are categorized functionally as hot or cold relative to surrounding tissue.", "D": "Isofunctioning is not a term used in thyroid scintigraphy classification; the relevant distinction is between increased (hot) and decreased (cold) uptake compared to normal parenchyma."}}}, {"id": "anking-endocrine-pathology-1657", "fuente": "anking", "tema": 5, "anki": "1462228521890", "q": "A 'cold' thyroid nodule on radioactive iodine uptake scanning is most indicative of which underlying process, warranting further biopsy?", "o": {"A": "Graves disease", "B": "Toxic multinodular goiter", "C": "Adenoma or carcinoma", "D": "Subacute thyroiditis"}, "r": "C", "e": {"correcta": "A cold nodule fails to concentrate radioiodine as well as surrounding thyroid tissue, and this reduced functional activity is characteristic of both benign follicular adenomas and malignant carcinomas, meaning further evaluation with fine needle aspiration biopsy is required to distinguish between them.", "incorrectas": {"A": "Graves disease produces diffusely increased radioiodine uptake throughout the gland (a diffusely 'hot' thyroid) due to TSH receptor-stimulating antibodies, not a focal cold nodule.", "B": "Toxic multinodular goiter is characterized by multiple hyperfunctioning ('hot') nodules with autonomous hormone production and increased uptake, the opposite of the cold nodule pattern.", "D": "Subacute thyroiditis classically causes decreased uptake throughout the entire gland during the transient hyperthyroid phase due to low TSH and follicular disruption, rather than a discrete cold nodule requiring biopsy for malignancy."}}}, {"id": "anking-endocrine-pathology-1658", "fuente": "anking", "tema": 5, "anki": "1462228531057", "q": "Which biopsy technique is used to sample a suspicious thyroid nodule, chosen specifically because the thyroid gland is highly vascularized?", "o": {"A": "Core needle biopsy", "B": "Excisional biopsy", "C": "Fine needle aspiration (FNA)", "D": "Punch biopsy"}, "r": "C", "e": {"correcta": "Fine needle aspiration uses a small-gauge needle to sample cells from a thyroid nodule with minimal trauma, which is important because the thyroid is highly vascularized and larger-bore sampling techniques would carry a higher risk of bleeding complications.", "incorrectas": {"A": "Core needle biopsy uses a larger needle to obtain a tissue core rather than just cells, increasing the risk of bleeding in a highly vascular organ like the thyroid, which is why FNA is preferred.", "B": "Excisional biopsy, meaning surgical removal of the nodule or lobe, is a more invasive definitive procedure typically reserved for cases where FNA is indeterminate or malignancy is confirmed, not the standard initial diagnostic step.", "D": "Punch biopsy is a technique used for sampling skin lesions and is not applicable to internal, highly vascular organs such as the thyroid gland."}}}, {"id": "anking-endocrine-pathology-1659", "fuente": "anking", "tema": 5, "anki": "1462228546625", "q": "A benign, solitary growth arising within the thyroid gland is best classified as which entity?", "o": {"A": "Thyroid carcinoma", "B": "Thyroid adenoma", "C": "Multinodular goiter", "D": "Thyroglossal duct cyst"}, "r": "B", "e": {"correcta": "A thyroid adenoma is defined as a benign, solitary neoplastic growth of the thyroid gland, most commonly of follicular origin, and is distinguished from malignant carcinoma by the absence of capsular or vascular invasion.", "incorrectas": {"A": "Thyroid carcinoma refers to malignant thyroid neoplasms that, unlike adenoma, demonstrate invasive growth through the tumor capsule and/or vasculature and have metastatic potential.", "C": "Multinodular goiter involves diffuse, typically multiple nodular enlargement of the thyroid gland due to variable follicular hyperplasia and involution, rather than a single discrete benign neoplasm.", "D": "A thyroglossal duct cyst is a congenital midline neck mass arising from persistence of the thyroglossal duct during embryologic descent of the thyroid, an entirely different developmental abnormality rather than a neoplastic growth."}}}, {"id": "anking-endocrine-pathology-1660", "fuente": "anking", "tema": 5, "anki": "1462228554222", "q": "Although most thyroid adenomas are nonfunctional ('cold'), autonomous thyroid hormone production by a 'hot' or toxic adenoma can rarely cause which clinical condition?", "o": {"A": "Hyperthyroidism", "B": "Hypothyroidism", "C": "Hypoparathyroidism", "D": "Adrenal insufficiency"}, "r": "A", "e": {"correcta": "While the majority of thyroid adenomas do not secrete hormone and appear 'cold' on scintigraphy, a small subset autonomously produce excess thyroid hormone independent of TSH regulation, appearing as 'hot' or toxic adenomas and producing clinical hyperthyroidism.", "incorrectas": {"B": "Hypothyroidism would result from decreased, not increased, thyroid hormone production; a functioning ('hot') adenoma by definition is overproducing hormone, driving the opposite clinical picture.", "C": "Hypoparathyroidism involves insufficient parathyroid hormone and disordered calcium regulation, an entirely separate gland and axis from thyroid hormone overproduction by a toxic adenoma.", "D": "Adrenal insufficiency reflects deficient cortisol and/or aldosterone production from the adrenal cortex and has no direct relationship to autonomous thyroid hormone secretion by a thyroid adenoma."}}}, {"id": "anking-endocrine-pathology-1661", "fuente": "anking", "tema": 5, "anki": "1462228578176", "q": "What is the most common histologic type of thyroid adenoma?", "o": {"A": "Papillary adenoma", "B": "Hürthle cell adenoma", "C": "Follicular adenoma", "D": "Medullary adenoma"}, "r": "C", "e": {"correcta": "Follicular adenoma is the most common type of thyroid adenoma, composed of well-differentiated follicular cells forming a benign encapsulated growth that is usually nonfunctional but occasionally secretes thyroid hormone.", "incorrectas": {"A": "Papillary adenoma is not a recognized common entity; papillary architecture in the thyroid is instead strongly associated with papillary carcinoma, a malignant rather than benign process.", "B": "Hürthle cell adenoma is a less common oxyphilic cell variant of follicular neoplasm, distinguished by abundant eosinophilic, mitochondria-rich cytoplasm, but it is not the most common type of thyroid adenoma overall.", "D": "Medullary adenoma is not a standard classification; medullary thyroid tumors arising from parafollicular C cells are classified as medullary carcinoma, which is malignant, not benign."}}}, {"id": "anking-endocrine-pathology-1662", "fuente": "anking", "tema": 5, "anki": "1462228594968", "q": "What is the key histologic feature that distinguishes follicular carcinoma from follicular adenoma of the thyroid?", "o": {"A": "Presence of Orphan Annie eye nuclei", "B": "Follicular adenoma lacks capsular and vascular invasion, which is present in carcinoma", "C": "Follicular adenoma contains psammoma bodies", "D": "Follicular carcinoma lacks a fibrous capsule entirely"}, "r": "B", "e": {"correcta": "Both follicular adenoma and follicular carcinoma are encapsulated tumors composed of follicles, but the defining distinction is invasive behavior: adenoma shows an intact capsule with no capsular or vascular invasion, while carcinoma demonstrates invasion through the capsule and/or into blood vessels, which is why this distinction can only be made on full histologic examination, not cytology alone.", "incorrectas": {"A": "Orphan Annie eye nuclei (clear, empty-appearing nuclei) are a classic feature of papillary thyroid carcinoma, not a distinguishing feature between follicular adenoma and follicular carcinoma.", "C": "Psammoma bodies (laminated calcified structures) are associated with papillary carcinoma, not follicular adenoma, and are not part of the adenoma-versus-carcinoma distinction in follicular neoplasms.", "D": "Follicular carcinoma still forms within a fibrous capsule, similar to adenoma; the critical difference is that carcinoma breaches or invades through that capsule, rather than lacking a capsule altogether."}}}, {"id": "anking-endocrine-pathology-1663", "fuente": "anking", "tema": 5, "anki": "1462228629278", "q": "A benign tumor of thyroid follicles is typically surrounded by which structure that helps distinguish it from invasive carcinoma?", "o": {"A": "Calcified psammoma bodies", "B": "A fibrous capsule", "C": "A layer of squamous epithelium", "D": "Lymphoid follicles with germinal centers"}, "r": "B", "e": {"correcta": "Thyroid follicular adenoma is a benign tumor composed of follicles enclosed by a distinct, dense fibrous capsule that separates the tumor from surrounding normal thyroid tissue; the adenoma is usually nonfunctional but may rarely secrete thyroid hormone. The integrity of this capsule (no invasion) is what differentiates it from follicular carcinoma.", "incorrectas": {"A": "Psammoma bodies are calcified, laminated structures seen in papillary carcinoma, not a structural feature that encapsulates follicular adenomas.", "C": "Squamous epithelium is not a component of the thyroid follicular architecture or its capsule; the thyroid is lined by follicular (cuboidal to low columnar) epithelium, and the capsule itself is fibrous connective tissue, not epithelial.", "D": "Lymphoid follicles with germinal centers are characteristic of the diffuse lymphocytic infiltration seen in Hashimoto thyroiditis, not a structural feature surrounding a follicular adenoma."}}}, {"id": "anking-endocrine-pathology-1664", "fuente": "anking", "tema": 5, "anki": "1462228661599", "q": "What is the most common histologic type of thyroid carcinoma, accounting for approximately 80% of cases?", "o": {"A": "Follicular carcinoma", "B": "Medullary carcinoma", "C": "Anaplastic carcinoma", "D": "Papillary carcinoma"}, "r": "D", "e": {"correcta": "Papillary carcinoma is the most common thyroid malignancy, accounting for roughly 80% of cases. It is characterized by papillary structures, Orphan Annie eye nuclei, and nuclear grooves/inclusions, and generally carries an excellent prognosis, often spreading via cervical lymph nodes.", "incorrectas": {"A": "Follicular carcinoma is the second most common thyroid cancer, distinguished by capsular/vascular invasion and hematogenous rather than lymphatic spread, but it is far less common than papillary carcinoma.", "B": "Medullary carcinoma arises from parafollicular C cells, secretes calcitonin, and is associated with MEN 2A/2B and RET mutations, but it represents a smaller minority of thyroid cancers compared to papillary carcinoma.", "C": "Anaplastic carcinoma is a rare, highly aggressive undifferentiated tumor typically seen in elderly patients with a poor prognosis, and accounts for only a small fraction of thyroid cancers, far less than papillary carcinoma."}}}, {"id": "anking-endocrine-pathology-1665", "fuente": "anking", "tema": 5, "anki": "1462228675825", "q": "Which two gene mutations are most associated with an increased risk of papillary thyroid carcinoma?", "o": {"A": "RAS and PTEN", "B": "RET and BRAF", "C": "APC and TP53", "D": "MEN1 and RET"}, "r": "B", "e": {"correcta": "Papillary thyroid carcinoma is associated with activating mutations or rearrangements in RET and BRAF, both of which activate the MAPK signaling pathway and promote unregulated cell growth, making them the two mutations most linked to increased papillary carcinoma risk.", "incorrectas": {"A": "RAS mutations are classically associated with follicular thyroid carcinoma, not papillary carcinoma, and PTEN mutations are more associated with Cowden syndrome-related thyroid disease, not the typical papillary carcinoma mutation profile.", "C": "APC and TP53 mutations are more classically associated with colorectal cancer progression (APC in familial adenomatous polyposis, TP53 as a general tumor suppressor loss) rather than being the signature mutations of papillary thyroid carcinoma.", "D": "MEN1 mutations cause multiple endocrine neoplasia type 1 (parathyroid, pituitary, pancreatic tumors), not papillary thyroid carcinoma; RET is correctly associated with papillary carcinoma but pairing it with MEN1 here is incorrect since MEN1 is unrelated to papillary carcinoma risk."}}}, {"id": "anking-endocrine-pathology-1666", "fuente": "anking", "tema": 5, "anki": "1462228925054", "q": "In addition to 'Orphan Annie eye' nuclei, which nuclear feature is characteristic of papillary thyroid carcinoma?", "o": {"A": "Prominent nucleoli with coarse chromatin", "B": "Intranuclear grooves and inclusions", "C": "Binucleation with mitotic figures", "D": "Pyknotic, condensed nuclei"}, "r": "B", "e": {"correcta": "Papillary thyroid carcinoma cells characteristically show intranuclear grooves (linear indentations of the nuclear membrane) and cytoplasmic pseudoinclusions in addition to the clear, empty-appearing 'Orphan Annie eye' nuclei, together forming the classic cytologic triad used to diagnose this tumor on FNA or histology.", "incorrectas": {"A": "Prominent nucleoli with coarse chromatin are nonspecific findings seen in many malignancies but are not the specific distinguishing nuclear feature described for papillary carcinoma, which is defined by grooves, inclusions, and clearing.", "C": "Binucleation with numerous mitotic figures is more suggestive of an aggressive, high-grade or anaplastic process rather than the relatively bland, low-mitotic-rate nuclear appearance typical of papillary carcinoma.", "D": "Pyknotic, condensed nuclei are a feature of cell death (apoptosis or necrosis), not the open, clear chromatin pattern with grooves and inclusions that defines papillary carcinoma nuclei."}}}, {"id": "anking-endocrine-pathology-1667", "fuente": "anking", "tema": 5, "anki": "1462228980582", "q": "Papillary thyroid carcinoma most often spreads via lymphatic invasion to which nodal basin?", "o": {"A": "Axillary nodes", "B": "Cervical nodes", "C": "Inguinal nodes", "D": "Mediastinal nodes only"}, "r": "B", "e": {"correcta": "Papillary thyroid carcinoma characteristically spreads through lymphatic channels to the cervical lymph nodes, which is consistent with its typical route of local lymphatic invasion rather than hematogenous dissemination, and despite nodal involvement, prognosis generally remains excellent.", "incorrectas": {"A": "Axillary nodes drain the breast and upper extremity and are not the characteristic lymphatic drainage basin for thyroid malignancies, which drain instead to cervical nodal chains.", "C": "Inguinal nodes drain the lower extremities, external genitalia, and anal canal, structures anatomically unrelated to thyroid lymphatic drainage.", "D": "While some spread to mediastinal nodes can occur with more extensive disease, the classic and most emphasized nodal spread for papillary carcinoma is to the cervical nodes, not the mediastinum exclusively."}}}, {"id": "anking-endocrine-pathology-1668", "fuente": "anking", "tema": 5, "anki": "1462228988545", "q": "What is the general prognosis for a patient diagnosed with papillary thyroid carcinoma?", "o": {"A": "Poor, with rapid progression to death", "B": "Excellent", "C": "Guarded, similar to anaplastic carcinoma", "D": "Variable and unpredictable, with no established prognostic pattern"}, "r": "B", "e": {"correcta": "Papillary thyroid carcinoma, despite being the most common thyroid cancer and frequently spreading to cervical lymph nodes, carries an excellent overall prognosis, with very high long-term survival rates following surgical resection and, when indicated, radioactive iodine ablation.", "incorrectas": {"A": "A poor prognosis with rapid progression is characteristic of anaplastic thyroid carcinoma, an aggressive undifferentiated tumor, not papillary carcinoma, which is typically indolent and slow-growing.", "C": "Anaplastic carcinoma has a genuinely guarded, poor prognosis due to its aggressive local invasion and resistance to treatment; papillary carcinoma is markedly different, behaving indolently with excellent outcomes.", "D": "Papillary carcinoma actually has a well-established and predictable favorable prognosis; describing its course as unpredictable does not reflect the consistent excellent outcomes seen clinically."}}}, {"id": "anking-endocrine-pathology-1669", "fuente": "anking", "tema": 5, "anki": "1462228992508", "q": "Thyroid follicular carcinoma is defined by a malignant proliferation of follicles surrounded by a fibrous capsule with which additional finding that distinguishes it from adenoma?", "o": {"A": "Presence of psammoma bodies within the follicles", "B": "Invasion through the capsule and/or vasculature", "C": "Complete absence of any capsule", "D": "Diffuse lymphocytic infiltration of the stroma"}, "r": "B", "e": {"correcta": "Follicular carcinoma is a malignant tumor of follicular cells that, like adenoma, is surrounded by a fibrous capsule, but unlike adenoma it shows invasion through that capsule and/or into blood vessels, which is the defining criterion separating it from benign follicular adenoma.", "incorrectas": {"A": "Psammoma bodies are a feature of papillary carcinoma, reflecting calcified debris within psammomatous structures, and are not part of the defining criteria for follicular carcinoma.", "C": "Follicular carcinoma still develops within a capsule similar to adenoma; the tumor does not lack a capsule altogether, it invades through the capsule that is present.", "D": "Diffuse lymphocytic infiltration of the stroma describes autoimmune processes such as Hashimoto thyroiditis, not the defining invasive feature that separates follicular carcinoma from adenoma."}}}, {"id": "anking-endocrine-pathology-1670", "fuente": "anking", "tema": 5, "anki": "1462229017040", "q": "Why can fine needle aspiration (FNA) not reliably distinguish thyroid follicular adenoma from follicular carcinoma?", "o": {"A": "Both tumors have identical molecular mutations detectable only by immunohistochemistry", "B": "The fibrous capsule and its integrity cannot be visualized with FNA", "C": "FNA cannot sample follicular cells at all", "D": "Follicular neoplasms do not exfoliate cells adequately for cytology"}, "r": "B", "e": {"correcta": "The distinction between follicular adenoma and follicular carcinoma rests entirely on architectural findings, namely capsular and/or vascular invasion, which requires assessment of the tumor's relationship to its surrounding capsule on a full histologic section. FNA only provides isolated cells or small clusters without preserving this architecture, so it cannot determine whether invasion is present, and definitive diagnosis requires surgical excision and histologic examination.", "incorrectas": {"A": "While molecular markers like RAS mutations are associated with follicular carcinoma, they are not routinely diagnostic or specific enough on their own to reliably separate adenoma from carcinoma on FNA; the practical clinical limitation described is architectural, not primarily molecular.", "C": "FNA does sample follicular cells effectively and is useful for identifying follicular neoplasms as a category; the limitation is not in obtaining cells but in assessing capsular invasion.", "D": "Follicular neoplasms do exfoliate adequately for cytologic sampling via FNA; the problem is specifically that cytology preserves individual cells or clusters, not the intact capsule architecture needed to assess invasion."}}}, {"id": "anking-endocrine-pathology-1671", "fuente": "anking", "tema": 5, "anki": "1462229032182", "q": "Thyroid follicular carcinoma is most strongly associated with which gene mutation?", "o": {"A": "BRAF", "B": "RET", "C": "RAS", "D": "TP53"}, "r": "C", "e": {"correcta": "Follicular thyroid carcinoma is associated with RAS oncogene mutations, which drive constitutive activation of downstream growth signaling pathways contributing to follicular cell proliferation and malignant transformation.", "incorrectas": {"A": "BRAF mutations are strongly associated with papillary thyroid carcinoma, driving MAPK pathway activation in that tumor type, rather than being the characteristic mutation of follicular carcinoma.", "B": "RET mutations/rearrangements are associated with papillary carcinoma (RET/PTC rearrangements) and with medullary carcinoma in the context of MEN 2A/2B, not with follicular carcinoma.", "D": "TP53 mutations are more classically associated with anaplastic (undifferentiated) thyroid carcinoma, often representing a later dedifferentiation event, rather than being the signature mutation of follicular carcinoma."}}}, {"id": "anking-endocrine-pathology-1672", "fuente": "anking", "tema": 5, "anki": "1462229039299", "q": "Unlike most carcinomas, which typically spread via lymphatics, thyroid follicular carcinoma most commonly metastasizes by which route?", "o": {"A": "Lymphatic spread to cervical nodes", "B": "Direct local invasion only", "C": "Hematogenous spread", "D": "Transcoelomic seeding"}, "r": "C", "e": {"correcta": "Follicular thyroid carcinoma is a notable exception to the general rule that carcinomas spread via lymphatics, instead favoring hematogenous dissemination, commonly to bone and lung, which is an important distinguishing feature from papillary carcinoma's lymphatic spread pattern.", "incorrectas": {"A": "Lymphatic spread to cervical nodes is the classic metastatic route for papillary thyroid carcinoma, not follicular carcinoma, which is specifically noted as an exception that spreads hematogenously instead.", "B": "While local invasion can occur, the hallmark and clinically emphasized metastatic pathway for follicular carcinoma is hematogenous spread to distant sites, not simply direct local extension.", "D": "Transcoelomic seeding, spread across a body cavity such as the peritoneum, is a mechanism associated with intra-abdominal malignancies like ovarian cancer, not thyroid carcinoma."}}}, {"id": "anking-endocrine-pathology-1673", "fuente": "anking", "tema": 5, "anki": "1462229061096", "q": "Medullary thyroid carcinoma arises from parafollicular C cells and characteristically secretes which hormone?", "o": {"A": "Thyroglobulin", "B": "Parathyroid hormone", "C": "Calcitonin", "D": "Thyroid-stimulating hormone"}, "r": "C", "e": {"correcta": "Medullary thyroid carcinoma originates from the parafollicular C cells of the thyroid, which normally secrete calcitonin, a hormone that lowers serum calcium; this tumor continues to secrete calcitonin, making it a useful tumor marker for diagnosis and surveillance.", "incorrectas": {"A": "Thyroglobulin is produced by follicular cells and serves as the protein scaffold for thyroid hormone synthesis and storage; it is used as a tumor marker for papillary and follicular carcinoma, not medullary carcinoma.", "B": "Parathyroid hormone is produced by the parathyroid glands, a distinct anatomic structure from the thyroid's parafollicular C cells, and regulates calcium via different mechanisms than calcitonin.", "D": "Thyroid-stimulating hormone is produced by the anterior pituitary and regulates follicular cell hormone production; it is not secreted by the parafollicular C cells or by medullary carcinoma."}}}, {"id": "anking-endocrine-pathology-1674", "fuente": "anking", "tema": 5, "anki": "1462229067351", "q": "High levels of calcitonin secreted by a medullary thyroid carcinoma may lead to which electrolyte abnormality?", "o": {"A": "Hypercalcemia", "B": "Hypocalcemia", "C": "Hyperkalemia", "D": "Hypernatremia"}, "r": "B", "e": {"correcta": "Calcitonin acts to lower serum calcium by inhibiting osteoclastic bone resorption and promoting renal calcium excretion, so excessive calcitonin secretion from a medullary thyroid carcinoma can drive serum calcium levels down, producing hypocalcemia.", "incorrectas": {"A": "Hypercalcemia would be the expected result of a hormone that raises calcium, such as excess parathyroid hormone, which is the opposite physiologic effect of calcitonin.", "C": "Hyperkalemia refers to elevated potassium and is not a direct physiologic consequence of calcitonin, which specifically regulates calcium homeostasis, not potassium.", "D": "Hypernatremia refers to elevated sodium and reflects water balance disturbances, unrelated to calcitonin's specific role in lowering serum calcium."}}}, {"id": "anking-endocrine-pathology-1675", "fuente": "anking", "tema": 5, "anki": "1462229198876", "q": "Thyroid medullary carcinoma is associated with which two multiple endocrine neoplasia (MEN) syndromes, both linked to RET mutations?", "o": {"A": "MEN 1 and MEN 2A", "B": "MEN 2A and MEN 2B", "C": "MEN 1 only", "D": "MEN 2B and MEN 1"}, "r": "B", "e": {"correcta": "Medullary thyroid carcinoma is a component tumor of both MEN 2A (medullary carcinoma, pheochromocytoma, primary hyperparathyroidism) and MEN 2B (medullary carcinoma, pheochromocytoma, mucosal neuromas, marfanoid habitus), both of which arise from germline RET proto-oncogene mutations.", "incorrectas": {"A": "MEN 1 involves parathyroid, pituitary, and pancreatic tumors due to MEN1 gene mutations, not RET mutations, and does not classically feature medullary thyroid carcinoma the way MEN 2A and 2B do.", "C": "MEN 1 alone is incorrect because medullary thyroid carcinoma is not a hallmark feature of MEN 1, which instead centers on parathyroid, pituitary, and pancreatic neoplasms via a different gene (MEN1, encoding menin).", "D": "Pairing MEN 2B correctly with medullary carcinoma but incorrectly including MEN 1 is wrong, since MEN 1 is caused by a different gene and does not classically include medullary thyroid carcinoma; the correct pairing is MEN 2A and MEN 2B."}}}, {"id": "anking-endocrine-pathology-1676", "fuente": "anking", "tema": 5, "anki": "1462229233459", "q": "An elderly patient presents with a rapidly enlarging, undifferentiated malignant thyroid tumor showing large pleomorphic, osteoclast-like multinucleate giant cells and biphasic spindle cells. Which thyroid carcinoma subtype is this?", "o": {"A": "Papillary carcinoma", "B": "Follicular carcinoma", "C": "Anaplastic carcinoma", "D": "Medullary carcinoma"}, "r": "C", "e": {"correcta": "Anaplastic thyroid carcinoma is an undifferentiated, highly aggressive malignant tumor characterized histologically by large pleomorphic cells, osteoclast-like multinucleate giant cells, and biphasic spindle cell populations. It typically affects elderly patients and behaves very aggressively, often invading local structures.", "incorrectas": {"A": "Papillary carcinoma shows well-differentiated papillary architecture with distinctive nuclear features (Orphan Annie eyes, grooves, inclusions), not the undifferentiated pleomorphic giant cell morphology described here.", "B": "Follicular carcinoma is a well-differentiated tumor forming follicular structures within an invaded capsule, in contrast to the completely undifferentiated, pleomorphic appearance of anaplastic carcinoma.", "D": "Medullary carcinoma arises from C cells, often shows amyloid stroma from calcitonin deposition, and has a distinct cytologic appearance rather than the undifferentiated pleomorphic giant cell pattern of anaplastic carcinoma."}}}, {"id": "anking-endocrine-pathology-1677", "fuente": "anking", "tema": 5, "anki": "1462229246757", "q": "Anaplastic thyroid carcinoma is most commonly seen in which patient demographic, distinguishing it clinically from Riedel thyroiditis?", "o": {"A": "Young men", "B": "Elderly women", "C": "Adolescent girls", "D": "Middle-aged men"}, "r": "B", "e": {"correcta": "Anaplastic thyroid carcinoma classically occurs in elderly women, which is an important distinguishing feature from Riedel thyroiditis, a fibrosing thyroid condition that instead affects middle-aged women (30-50 years old); both can present with a hard, invasive-feeling thyroid mass, making age an important discriminator.", "incorrectas": {"A": "Young men are not the typical demographic for anaplastic carcinoma, which is an aggressive tumor primarily seen in an older population, and more specifically skews toward women.", "C": "Adolescent girls are not associated with anaplastic thyroid carcinoma; this is a disease of older adulthood, occurring almost exclusively in elderly patients.", "D": "Middle-aged men are not the classic demographic for anaplastic carcinoma; the disease occurs in elderly patients with a female predominance, and it is Riedel thyroiditis (not anaplastic carcinoma) that is associated with a middle-aged demographic, specifically women."}}}, {"id": "anking-endocrine-pathology-1678", "fuente": "anking", "tema": 5, "anki": "1462229255450", "q": "Anaplastic thyroid carcinoma often invades local neck structures, leading to which set of symptoms?", "o": {"A": "Diarrhea and flushing", "B": "Dysphagia and respiratory compromise", "C": "Hoarseness only, with no other symptoms", "D": "Isolated painless neck swelling with no compressive symptoms"}, "r": "B", "e": {"correcta": "Anaplastic thyroid carcinoma is highly aggressive and infiltrates adjacent structures in the neck, including the esophagus and trachea, producing dysphagia (difficulty swallowing) and respiratory compromise from airway compression, reflecting its rapid, invasive local growth pattern.", "incorrectas": {"A": "Diarrhea and flushing are classic symptoms of carcinoid syndrome from a serotonin-secreting neuroendocrine tumor, not a feature of local invasion by anaplastic thyroid carcinoma.", "C": "While hoarseness can occur from recurrent laryngeal nerve involvement, anaplastic carcinoma's aggressive local invasion produces a broader constellation of compressive symptoms, including dysphagia and respiratory compromise, not hoarseness in isolation.", "D": "Anaplastic carcinoma is notable precisely because it does cause compressive, invasive symptoms due to rapid local extension, unlike a painless, non-invasive nodule, making this option inconsistent with its aggressive behavior."}}}, {"id": "anking-endocrine-pathology-1679", "fuente": "anking", "tema": 5, "anki": "1462229270613", "q": "What is the typical prognosis for a patient diagnosed with anaplastic thyroid carcinoma?", "o": {"A": "Excellent, similar to papillary carcinoma", "B": "Good, with long-term survival expected in most patients", "C": "Poor", "D": "Variable, but generally favorable with surgery alone"}, "r": "C", "e": {"correcta": "Anaplastic thyroid carcinoma has a poor prognosis due to its undifferentiated, highly aggressive nature, rapid local invasion into neck structures, and tendency to be diagnosed at an advanced, often unresectable stage, in sharp contrast to the excellent prognosis of papillary carcinoma.", "incorrectas": {"A": "An excellent prognosis is characteristic of papillary carcinoma, the most differentiated and indolent thyroid cancer, which stands in stark contrast to the undifferentiated, aggressive behavior of anaplastic carcinoma.", "B": "Good long-term survival is not expected with anaplastic carcinoma; most patients face a rapidly progressive course with survival typically measured in months due to the tumor's aggressive local and systemic behavior.", "D": "Surgery alone is rarely curative in anaplastic carcinoma because of its propensity for extensive local invasion at diagnosis, and prognosis remains poor despite multimodal therapy, not merely variable but favorable."}}}, {"id": "anking-endocrine-pathology-1680", "fuente": "anking", "tema": 5, "anki": "1462229286041", "q": "What is the most common cause of primary hyperparathyroidism?", "o": {"A": "Parathyroid carcinoma", "B": "Sporadic four-gland parathyroid hyperplasia", "C": "Parathyroid adenoma", "D": "Chronic kidney disease"}, "r": "C", "e": {"correcta": "Parathyroid adenoma accounts for greater than 80% of cases of primary hyperparathyroidism, arising from a single benign, autonomously functioning parathyroid gland that oversecretes PTH independent of normal calcium feedback regulation.", "incorrectas": {"A": "Parathyroid carcinoma is a rare cause of primary hyperparathyroidism, representing a small minority of cases, far less common than the benign adenoma that dominates the etiology.", "B": "Sporadic hyperplasia of all four parathyroid glands is a recognized but less common cause of primary hyperparathyroidism compared to a solitary adenoma, and is more often associated with MEN syndromes when it occurs.", "D": "Chronic kidney disease causes secondary (and eventually tertiary) hyperparathyroidism due to phosphate retention and decreased vitamin D activation, which is a distinct pathophysiologic category from primary hyperparathyroidism caused by an intrinsic parathyroid gland abnormality."}}}, {"id": "anking-endocrine-pathology-1681", "fuente": "anking", "tema": 5, "anki": "1462232001565", "q": "In primary hyperparathyroidism, what is the expected serum calcium level?", "o": {"A": "Decreased, due to increased renal calcium excretion", "B": "Normal, because PTH tightly regulates calcium within range", "C": "Increased, due to increased PTH", "D": "Decreased, due to increased calcitonin"}, "r": "C", "e": {"correcta": "In primary hyperparathyroidism, autonomous PTH oversecretion (usually from an adenoma) increases serum calcium by stimulating bone resorption, enhancing renal calcium reabsorption, and increasing intestinal calcium absorption via activated vitamin D, resulting in hypercalcemia.", "incorrectas": {"A": "PTH actually increases renal calcium reabsorption (while increasing phosphate excretion), so decreased calcium due to renal wasting is inconsistent with the known action of excess PTH in this condition.", "B": "Calcium is not maintained in the normal range in primary hyperparathyroidism; the defining feature of the disease is autonomous PTH secretion that overrides normal feedback control, driving calcium above normal.", "D": "Calcitonin lowers calcium and is not the operative hormone in primary hyperparathyroidism; the pathology is driven by excess PTH, not increased calcitonin, and calcitonin levels are not the mechanism described in this condition."}}}, {"id": "anking-endocrine-pathology-1682", "fuente": "anking", "tema": 5, "anki": "1462232007760", "q": "As a result of hypercalcemia, patients with primary hyperparathyroidism are at increased risk of developing which type of kidney stone?", "o": {"A": "Uric acid stones", "B": "Struvite (magnesium ammonium phosphate) stones", "C": "Cystine stones", "D": "Calcium oxalate kidney stones"}, "r": "D", "e": {"correcta": "The hypercalcemia of primary hyperparathyroidism increases the filtered calcium load presented to the kidney; despite increased renal tubular calcium reabsorption driven by PTH, the excess calcium in the urine cannot be fully reabsorbed, leading to hypercalciuria and precipitation of calcium oxalate stones, the most common stone type in this condition.", "incorrectas": {"A": "Uric acid stones form in settings of low urine pH and hyperuricosuria, such as gout or high-purine states, and are not the classic stone type driven by the hypercalcemia of hyperparathyroidism.", "B": "Struvite stones form in the setting of chronic urinary tract infections with urease-producing organisms (e.g., Proteus), a mechanism unrelated to the calcium excess seen in primary hyperparathyroidism.", "C": "Cystine stones result from an inherited defect in renal tubular reabsorption of cystine (cystinuria), a distinct metabolic condition unrelated to the calcium handling abnormality of hyperparathyroidism."}}}, {"id": "anking-endocrine-pathology-1683", "fuente": "anking", "tema": 5, "anki": "1462232033989", "q": "A patient with primary hyperparathyroidism develops chronic hypercalcemia leading to calcium deposition within the renal tubules. What is this condition called?", "o": {"A": "Nephrolithiasis", "B": "Nephrocalcinosis", "C": "Papillary necrosis", "D": "Acute tubular necrosis"}, "r": "B", "e": {"correcta": "Nephrocalcinosis is metastatic calcification of the renal tubules caused by chronic hypercalcemia, as seen in primary hyperparathyroidism. Histology shows calcium deposits within the tubular epithelium, and this process can progress to renal insufficiency and polyuria (from impaired concentrating ability).", "incorrectas": {"A": "Nephrolithiasis refers to discrete kidney stones (often calcium oxalate or phosphate) forming in the collecting system, which can also occur with hypercalciuria in hyperparathyroidism, but it is a distinct process from diffuse tubular calcium deposition.", "C": "Papillary necrosis is ischemic necrosis of the renal papillae, classically associated with analgesic abuse, sickle cell disease, diabetes, and obstruction, not with hypercalcemia-induced calcification.", "D": "Acute tubular necrosis is caused by ischemia or nephrotoxins damaging tubular epithelial cells, presenting with granular casts, and is unrelated to calcium deposition from hyperparathyroidism."}}}, {"id": "anking-endocrine-pathology-1684", "fuente": "anking", "tema": 5, "anki": "1462232060525", "q": "Which CNS/psychiatric manifestation is classically associated with primary hyperparathyroidism, captured in the mnemonic 'psychiatric overtones'?", "o": {"A": "Mania", "B": "Depression", "C": "Visual hallucinations", "D": "Catatonia"}, "r": "B", "e": {"correcta": "Primary hyperparathyroidism causes hypercalcemia, which can produce CNS disturbances including depression, lethargy, and seizures, summarized by the mnemonic 'stones, bones, groans, and psychiatric overtones.' Elevated calcium alters neuronal excitability, contributing to mood and cognitive changes.", "incorrectas": {"A": "Mania is not part of the classic hypercalcemia symptom complex; the psychiatric overtones of hyperparathyroidism are more typically depression, anxiety, and cognitive slowing rather than elevated mood or activity.", "C": "Visual hallucinations are not a hallmark feature of hypercalcemia from hyperparathyroidism; this presentation is more suggestive of delirium from other causes (e.g., Lewy body disease, substance withdrawal).", "D": "Catatonia is not the classic psychiatric finding taught for hyperparathyroidism; the recognized triad emphasizes depression and, in severe cases, seizures or altered mental status, not catatonic features."}}}, {"id": "anking-gastrointestinal-pathology-1685", "fuente": "anking", "tema": 10, "anki": "1462232069152", "q": "Hypercalcemia from primary hyperparathyroidism can trigger premature activation of pancreatic zymogens, resulting in which complication?", "o": {"A": "Chronic pancreatitis", "B": "Pancreatic pseudocyst", "C": "Pancreatic adenocarcinoma", "D": "Acute pancreatitis"}, "r": "D", "e": {"correcta": "Elevated serum calcium can activate trypsinogen and other pancreatic enzymes prematurely within the pancreas, causing autodigestion and acute pancreatitis. Hypercalcemia is a recognized, though less common, cause of acute pancreatitis alongside gallstones and alcohol.", "incorrectas": {"A": "Chronic pancreatitis results from repeated bouts of inflammation leading to fibrosis and calcifications, most often from long-term alcohol use, not typically framed as the acute consequence of hypercalcemia-induced enzyme activation.", "B": "Pancreatic pseudocysts are a complication that can follow an episode of acute pancreatitis (a collection of fluid walled off by granulation tissue) but are not the direct effect of calcium-mediated enzyme activation itself.", "C": "Pancreatic adenocarcinoma is a malignant neoplasm unrelated to acute calcium-induced enzyme activation; hypercalcemia causes acute inflammatory injury, not neoplastic transformation."}}}, {"id": "anking-endocrine-pathology-1686", "fuente": "anking", "tema": 5, "anki": "1462232077763", "q": "A patient with primary hyperparathyroidism and hypercalcemia is more likely to present with which GI symptom?", "o": {"A": "Diarrhea", "B": "Constipation", "C": "Malabsorption", "D": "Bloody stools"}, "r": "B", "e": {"correcta": "Hypercalcemia decreases smooth muscle contractility and neuronal excitability in the GI tract, leading to constipation, along with nausea and abdominal pain ('groans'), as part of the classic hyperparathyroidism mnemonic 'stones, bones, groans, and psychiatric overtones.'", "incorrectas": {"A": "Diarrhea is not a typical feature of hypercalcemia; elevated calcium tends to slow GI motility rather than accelerate it, making constipation the expected finding instead.", "C": "Malabsorption syndromes (e.g., celiac disease, pancreatic insufficiency) present with steatorrhea and nutrient deficiencies, a different mechanism than the smooth-muscle hypomotility caused by hypercalcemia.", "D": "Bloody stools suggest mucosal injury, infection, or malignancy, not the smooth muscle relaxation effect of hypercalcemia, which manifests as constipation rather than bleeding."}}}, {"id": "anking-endocrine-pathology-1687", "fuente": "anking", "tema": 5, "anki": "1462232133452", "q": "In primary hyperparathyroidism, which serum marker is elevated due to increased osteoblastic activity in response to PTH-driven bone turnover?", "o": {"A": "Creatine kinase", "B": "Amylase", "C": "Lactate dehydrogenase", "D": "Alkaline phosphatase"}, "r": "D", "e": {"correcta": "Elevated PTH increases osteoclastic bone resorption, but this is coupled with a compensatory increase in osteoblast activity attempting to rebuild bone, which raises serum alkaline phosphatase (ALP), a marker of osteoblast activity and bone turnover.", "incorrectas": {"A": "Creatine kinase is a marker of muscle injury (skeletal or cardiac), not bone turnover, and is not characteristically elevated in hyperparathyroidism.", "B": "Amylase can be elevated if hypercalcemia triggers acute pancreatitis, but it is not the marker directly reflecting the increased osteoblast activity described in bone remodeling.", "C": "Lactate dehydrogenase is a nonspecific marker of cellular injury or turnover (e.g., hemolysis, tumor lysis) and is not the specific bone-turnover marker associated with hyperparathyroidism."}}}, {"id": "anking-endocrine-pathology-1688", "fuente": "anking", "tema": 5, "anki": "1462232142704", "q": "What is the expected serum calcium level in a patient with primary hyperparathyroidism?", "o": {"A": "Decreased", "B": "Increased", "C": "Normal", "D": "Variable, depending on vitamin D status"}, "r": "B", "e": {"correcta": "Primary hyperparathyroidism is caused by autonomous overproduction of PTH (often from a parathyroid adenoma), which increases bone resorption, renal calcium reabsorption, and intestinal calcium absorption (via activated vitamin D), producing hypercalcemia as the hallmark biochemical finding.", "incorrectas": {"A": "Decreased calcium is seen in hypoparathyroidism or secondary hyperparathyroidism (where low calcium is the stimulus for PTH release), the opposite pattern from primary hyperparathyroidism where high PTH drives calcium up.", "C": "hypercalcemia results directly from the excess PTH acting on bone, kidney, and gut to raise serum calcium; a normal level would be inconsistent with the primary defect of unregulated PTH secretion.", "D": "the calcium elevation in primary hyperparathyroidism is a consistent, defining feature caused directly by excess PTH, not something that fluctuates based on vitamin D independent of the primary glandular defect."}}}, {"id": "anking-endocrine-pathology-1689", "fuente": "anking", "tema": 5, "anki": "1462232161465", "q": "What is the expected serum phosphate level in a patient with primary hyperparathyroidism?", "o": {"A": "Increased", "B": "Decreased", "C": "Normal", "D": "Undetectable"}, "r": "B", "e": {"correcta": "PTH promotes phosphate excretion by inhibiting its reabsorption in the renal proximal tubule, so excess PTH in primary hyperparathyroidism causes hypophosphatemia alongside the hypercalcemia, since increased PTH secretion is the primary defect driving both changes.", "incorrectas": {"A": "Increased phosphate is seen in secondary hyperparathyroidism due to chronic renal failure, where impaired renal excretion causes phosphate to build up, the opposite mechanism from primary hyperparathyroidism.", "C": "phosphate is not normal because excess PTH actively promotes phosphaturia (renal phosphate wasting), producing a measurable decrease rather than no change.", "D": "Phosphate is decreased, not undetectable; PTH increases urinary phosphate losses but does not eliminate phosphate from the serum entirely."}}}, {"id": "anking-endocrine-pathology-1690", "fuente": "anking", "tema": 5, "anki": "1462232179503", "q": "What is the expected serum calcium level in secondary hyperparathyroidism?", "o": {"A": "Increased", "B": "Decreased", "C": "Normal", "D": "Variable, unrelated to PTH"}, "r": "B", "e": {"correcta": "In secondary hyperparathyroidism, low serum calcium (often from chronic renal failure, vitamin D deficiency, or malabsorption) is the primary defect that stimulates compensatory PTH secretion, so hypocalcemia is the driving abnormality rather than a consequence of high PTH.", "incorrectas": {"A": "Increased calcium is characteristic of primary hyperparathyroidism, where excess PTH raises calcium; in secondary hyperparathyroidism the direction of the defect is reversed, calcium is low and PTH rises to compensate.", "C": "Calcium is not normal in secondary hyperparathyroidism; it is precisely the low calcium level that provides the stimulus for the parathyroid glands to increase PTH output.", "D": "the calcium abnormality (hypocalcemia) is directly and causally related to PTH secretion, serving as the stimulus for the compensatory rise in PTH, not an unrelated, variable finding."}}}, {"id": "anking-renal-pathology-1691", "fuente": "anking", "tema": 58, "anki": "1462232204692", "q": "What is the most common underlying cause of secondary hyperparathyroidism?", "o": {"A": "Vitamin D toxicity", "B": "Chronic renal failure", "C": "Parathyroid adenoma", "D": "Multiple endocrine neoplasia type 1"}, "r": "B", "e": {"correcta": "Chronic renal failure is the most common cause of secondary hyperparathyroidism: failing kidneys cannot excrete phosphate, so phosphate accumulates and binds free ionized calcium, lowering serum calcium and chronically stimulating PTH secretion from otherwise normal parathyroid glands.", "incorrectas": {"A": "Vitamin D toxicity causes hypercalcemia, which would suppress rather than stimulate PTH secretion, the opposite of the hypocalcemia-driven mechanism behind secondary hyperparathyroidism.", "C": "A parathyroid adenoma is the most common cause of primary hyperparathyroidism, where the gland itself is the intrinsic abnormality, not a compensatory response to a systemic calcium/phosphate disturbance.", "D": "Multiple endocrine neoplasia type 1 predisposes to parathyroid, pituitary, and pancreatic tumors causing primary hyperparathyroidism, not the compensatory secondary form triggered by renal failure."}}}, {"id": "anking-renal-pathology-1692", "fuente": "anking", "tema": 58, "anki": "1462232219341", "q": "In chronic renal failure, how does the kidney trigger secondary hyperparathyroidism?", "o": {"A": "Increased calcitriol production raises calcium absorption, suppressing PTH release", "B": "Decreased phosphate excretion raises phosphate, which binds free calcium and lowers serum calcium, stimulating PTH release", "C": "Loss of erythropoietin directly stimulates parathyroid hyperplasia", "D": "Increased renal calcium reabsorption raises serum calcium, triggering PTH release"}, "r": "B", "e": {"correcta": "Failing kidneys excrete less phosphate, so serum phosphate rises; the excess phosphate binds free ionized calcium, lowering serum calcium. This hypocalcemia is sensed by the parathyroid glands, which respond by secreting more PTH in a compensatory (secondary) fashion.", "incorrectas": {"A": "Renal failure actually decreases calcitriol (active vitamin D) production because the kidney is needed for 1-alpha-hydroxylation, further worsening hypocalcemia rather than raising calcium or suppressing PTH.", "C": "Loss of erythropoietin causes anemia of chronic kidney disease but has no direct role in stimulating parathyroid hyperplasia; the parathyroid response is driven by the calcium-phosphate disturbance, not erythropoietin deficiency.", "D": "Renal failure impairs, rather than increases, calcium handling; the pathway to secondary hyperparathyroidism is via hyperphosphatemia lowering calcium, not via increased calcium reabsorption raising it."}}}, {"id": "anking-renal-pathology-1693", "fuente": "anking", "tema": 58, "anki": "1462232225257", "q": "Chronic renal disease can lead to a secondary hyperparathyroidism-driven bone disease characterized by increased bone resorption from elevated PTH. What is this condition called?", "o": {"A": "Osteomalacia", "B": "Paget disease of bone", "C": "Osteitis fibrosa cystica (primary)", "D": "Renal osteodystrophy"}, "r": "D", "e": {"correcta": "Renal osteodystrophy is the constellation of bone lesions seen in chronic kidney disease, driven by secondary hyperparathyroidism, hypocalcemia, hyperphosphatemia, and impaired renal hydroxylation of vitamin D, resulting in increased osteoclastic bone resorption and skeletal lesions similar to osteitis fibrosa cystica.", "incorrectas": {"A": "Osteomalacia refers to defective bone mineralization from vitamin D deficiency or resistance, presenting with soft, weak bones, but it is a distinct entity from the PTH-driven bone resorption of renal osteodystrophy, though vitamin D deficiency contributes to both.", "B": "Paget disease of bone is a disorder of excessive, disorganized bone remodeling due to increased osteoclastic and osteoblastic activity, unrelated to renal failure or secondary hyperparathyroidism.", "C": "Osteitis fibrosa cystica classically refers to the bone lesions of primary hyperparathyroidism (from a parathyroid adenoma), whereas the analogous process from chronic kidney disease is specifically termed renal osteodystrophy."}}}, {"id": "anking-endocrine-pathology-1694", "fuente": "anking", "tema": 5, "anki": "1462232232348", "q": "After a prolonged period of secondary hyperparathyroidism from chronic renal disease, the parathyroid glands can become autonomous, secreting PTH independent of calcium regulation. What is this condition called?", "o": {"A": "Primary hyperparathyroidism", "B": "Tertiary hyperparathyroidism", "C": "Pseudohyperparathyroidism", "D": "Familial hypocalciuric hypercalcemia"}, "r": "B", "e": {"correcta": "Tertiary hyperparathyroidism arises after long-standing secondary hyperparathyroidism (typically from chronic renal disease), in which the chronically stimulated parathyroid glands undergo hyperplasia and become autonomous, secreting excess PTH independent of the original calcium stimulus, resulting in elevated PTH, phosphate, and calcium levels.", "incorrectas": {"A": "Primary hyperparathyroidism arises de novo from an intrinsic parathyroid abnormality (usually adenoma), not as the end result of years of compensatory secondary hyperparathyroidism from renal disease.", "C": "Pseudohyperparathyroidism is not a standard clinical entity in this context; the condition resulting from prolonged secondary hyperparathyroidism becoming autonomous is specifically termed tertiary hyperparathyroidism.", "D": "Familial hypocalciuric hypercalcemia is a genetic disorder of the calcium-sensing receptor causing mild hypercalcemia with low urinary calcium, unrelated to the renal-disease-driven progression from secondary to tertiary hyperparathyroidism."}}}, {"id": "anking-endocrine-pathology-1695", "fuente": "anking", "tema": 5, "anki": "1462232288770", "q": "Pseudohypoparathyroidism type 1a (Albright hereditary osteodystrophy) is characterized by shortened stature and shortening of which digits?", "o": {"A": "2nd and 3rd digits", "B": "1st and 2nd digits", "C": "4th and 5th digits", "D": "3rd and 4th digits"}, "r": "C", "e": {"correcta": "Albright hereditary osteodystrophy classically presents with shortened stature, obesity, developmental delay, and characteristically short 4th and 5th metacarpals/digits, along with end-organ (renal) resistance to PTH causing hypocalcemia despite elevated PTH levels.", "incorrectas": {"A": "Shortening of the 2nd and 3rd digits is not the classic pattern described in Albright hereditary osteodystrophy; the disorder specifically involves the 4th and 5th digits/metacarpals.", "B": "The 1st and 2nd digits are not the digits affected in this syndrome; the skeletal finding taught for Step 1 is shortening of the 4th and 5th digits.", "D": "The 3rd and 4th digits are not the classic pairing; the mnemonic and clinical finding specifically point to the 4th and 5th digits being shortened."}}}, {"id": "anking-endocrine-pathology-1696", "fuente": "anking", "tema": 5, "anki": "1462232307555", "q": "What is the inheritance pattern of pseudohypoparathyroidism type 1a (Albright hereditary osteodystrophy)?", "o": {"A": "X-linked recessive", "B": "Autosomal recessive", "C": "Autosomal dominant", "D": "Mitochondrial"}, "r": "C", "e": {"correcta": "Pseudohypoparathyroidism type 1a follows autosomal dominant inheritance, resulting from a mutation in the GNAS1 gene encoding the Gs alpha-subunit; due to genomic imprinting, the clinical syndrome with end-organ PTH resistance manifests only when the defective allele is inherited from the mother.", "incorrectas": {"A": "X-linked recessive inheritance would predominantly affect males and follow a different pedigree pattern; pseudohypoparathyroidism type 1a is autosomal, involving GNAS1 on chromosome 20, not the X chromosome.", "B": "Autosomal recessive inheritance would require two defective alleles for expression; this disorder is dominant, with a single mutated maternal allele sufficient to cause the phenotype due to imprinting at the renal locus.", "D": "Mitochondrial inheritance follows strict maternal transmission to all offspring via mitochondrial DNA, a different mechanism than the autosomal dominant, imprinted GNAS1 mutation responsible for this condition."}}}, {"id": "anking-endocrine-pathology-1697", "fuente": "anking", "tema": 5, "anki": "1462308715423", "q": "Which condition presents with the physical features of Albright hereditary osteodystrophy (short stature, short 4th/5th digits) but WITHOUT end-organ PTH resistance or calcium/phosphate abnormalities?", "o": {"A": "Pseudopseudohypoparathyroidism", "B": "Pseudohypoparathyroidism type 1a", "C": "Primary hypoparathyroidism", "D": "DiGeorge syndrome"}, "r": "A", "e": {"correcta": "Pseudopseudohypoparathyroidism occurs when the defective Gs alpha-subunit (GNAS1) gene is inherited from the father rather than the mother. Because the paternal allele is imprinted (silenced) in the kidney, renal PTH signaling remains normal, so patients have the Albright phenotype (short stature, short 4th/5th digits) but normal calcium, phosphate, and PTH levels.", "incorrectas": {"B": "Pseudohypoparathyroidism type 1a occurs when the mutant maternal allele is inherited, causing actual renal PTH resistance with hypocalcemia and elevated PTH, in contrast to pseudopseudohypoparathyroidism which has normal labs.", "C": "Primary hypoparathyroidism results from insufficient PTH production (e.g., after thyroid surgery or autoimmune destruction), causing hypocalcemia with low PTH, a completely different mechanism from the imprinting-based paternal transmission seen here.", "D": "DiGeorge syndrome causes hypoparathyroidism due to failure of the third and fourth pharyngeal pouches to develop, leading to absent parathyroid glands, unrelated to the GNAS1 imprinting defect of pseudopseudohypoparathyroidism."}}}, {"id": "anking-endocrine-pathology-1698", "fuente": "anking", "tema": 5, "anki": "1462308845977", "q": "Pseudohypoparathyroidism type 1a occurs due to inheritance of a defective GNAS1 allele from which parent, given that renal tissue only expresses the maternal allele due to imprinting?", "o": {"A": "Father", "B": "Either parent equally", "C": "Grandmother (skipped generation)", "D": "Mother"}, "r": "D", "e": {"correcta": "Because of genomic imprinting, the kidney only expresses the maternal copy of the GNAS1 gene. If the defective allele is inherited from the mother, the kidney lacks a functional Gs alpha-subunit, producing true end-organ PTH resistance with hypocalcemia, hyperphosphatemia, and elevated PTH — pseudohypoparathyroidism type 1a.", "incorrectas": {"A": "If the defective allele comes from the father, the kidney's silenced paternal allele means the (normal) maternal allele is still expressed there, so renal PTH responsiveness is preserved and labs remain normal, this is pseudopseudohypoparathyroidism, not type 1a.", "B": "Inheritance is not equivalent from either parent because of imprinting, the renal phenotype depends specifically on which parental allele is affected, making the maternal origin critical for causing renal resistance.", "C": "there is no mechanism of a 'skipped generation' effect here; genomic imprinting depends on the sex of the immediate parent transmitting the allele, not the grandparent of origin."}}}, {"id": "anking-endocrine-pathology-1699", "fuente": "anking", "tema": 5, "anki": "1462308907642", "q": "Pseudopseudohypoparathyroidism occurs when a defective Gs alpha-subunit (GNAS1) allele is inherited from which parent?", "o": {"A": "Mother", "B": "Both parents", "C": "Father", "D": "Neither, it is a de novo mutation"}, "r": "C", "e": {"correcta": "In pseudopseudohypoparathyroidism, the defective GNAS1 allele comes from the father. Because renal tissue only expresses the maternal allele (paternal allele is imprinted/silenced there), the kidney's PTH responsiveness stays normal, producing normal calcium, phosphate, and PTH despite the Albright-like skeletal phenotype.", "incorrectas": {"A": "If the defective allele is maternal, the kidney (which relies on the maternal allele) loses functional Gs alpha-subunit activity, producing true renal PTH resistance with abnormal labs, that scenario is pseudohypoparathyroidism type 1a, not the pseudo-pseudo form.", "B": "The distinguishing feature of these related syndromes is precisely which single parent transmitted the mutant allele, not biallelic inheritance from both parents.", "D": "This is an inherited, imprinted condition tied to parental origin of the mutation, not a spontaneous de novo mutation without a parental transmission pattern."}}}, {"id": "anking-endocrine-pathology-1700", "fuente": "anking", "tema": 5, "anki": "1462326105448", "q": "Which type of diabetes mellitus is characterized primarily by an absolute insulin deficiency due to autoimmune beta-cell destruction?", "o": {"A": "Type 1 diabetes mellitus", "B": "Type 2 diabetes mellitus", "C": "Maturity-onset diabetes of the young", "D": "Gestational diabetes"}, "r": "A", "e": {"correcta": "Type 1 diabetes mellitus results from autoimmune (type IV hypersensitivity) destruction of pancreatic beta cells, leading to an absolute deficiency of insulin production. This differs fundamentally from type 2 diabetes, where insulin is initially present but tissues are resistant to its effects.", "incorrectas": {"B": "Type 2 diabetes mellitus is characterized by insulin resistance with variable (often initially elevated) insulin levels, not an absolute deficiency from autoimmune beta-cell destruction as in type 1.", "C": "Maturity-onset diabetes of the young (MODY) is caused by monogenic defects impairing insulin secretion, typically presenting in young, non-obese patients without the autoimmune beta-cell destruction seen in type 1 diabetes.", "D": "Gestational diabetes arises from pregnancy-related insulin resistance (placental hormones antagonizing insulin action), not from autoimmune destruction of beta cells."}}}, {"id": "anking-endocrine-pathology-1701", "fuente": "anking", "tema": 5, "anki": "1462326951145", "q": "Which type of diabetes mellitus is primarily characterized by peripheral insulin resistance rather than an absolute deficiency of insulin?", "o": {"A": "Type 1 diabetes mellitus", "B": "Diabetes insipidus", "C": "Latent autoimmune diabetes of adults", "D": "Type 2 diabetes mellitus"}, "r": "D", "e": {"correcta": "Type 2 diabetes mellitus is driven mainly by insulin resistance in peripheral tissues (often related to obesity and downregulation of insulin receptors), with insulin levels initially normal or elevated as the pancreas compensates, before beta-cell exhaustion may eventually reduce insulin output.", "incorrectas": {"A": "Type 1 diabetes mellitus involves absolute insulin deficiency from autoimmune destruction of beta cells, not peripheral resistance to insulin's action.", "B": "Diabetes insipidus is a disorder of insufficient ADH action (central or nephrogenic) causing dilute polyuria, entirely unrelated to insulin or glucose metabolism despite the similar name.", "C": "Latent autoimmune diabetes of adults is a slowly progressive autoimmune form of diabetes resembling type 1 (with beta-cell destruction) that presents in adulthood, distinct from the insulin-resistance mechanism of classic type 2 diabetes."}}}, {"id": "anking-endocrine-pathology-1702", "fuente": "anking", "tema": 5, "anki": "1462326990404", "q": "Type 1 diabetes mellitus results from beta-cell destruction mediated by which type of hypersensitivity reaction?", "o": {"A": "Type I (IgE-mediated)", "B": "Type II (antibody-mediated cytotoxicity)", "C": "Type III (immune complex)", "D": "Type IV (T-cell mediated)"}, "r": "D", "e": {"correcta": "Type 1 diabetes mellitus is a type IV (delayed, T-cell mediated) hypersensitivity reaction, in which autoreactive CD4+ and CD8+ T cells infiltrate the pancreatic islets and destroy insulin-producing beta cells, producing the characteristic leukocytic infiltrate (insulitis) seen on histology.", "incorrectas": {"A": "Type I hypersensitivity is IgE-mediated, occurring within minutes of allergen exposure (e.g., anaphylaxis, atopic conditions), a mechanism unrelated to the chronic T-cell mediated beta-cell destruction of type 1 diabetes.", "B": "Type II hypersensitivity involves antibodies directly targeting cell-surface or matrix antigens causing cytotoxicity (e.g., Goodpasture syndrome), distinct from the cell-mediated (not primarily antibody-driven) beta-cell destruction in type 1 diabetes.", "C": "Type III hypersensitivity involves immune complex deposition activating complement (e.g., lupus nephritis, serum sickness), a different mechanism than the direct T-cell attack on beta cells in type 1 diabetes."}}}, {"id": "anking-endocrine-pathology-1703", "fuente": "anking", "tema": 5, "anki": "1462326996658", "q": "Type 1 diabetes mellitus, which manifests with features of insulin deficiency, is most commonly diagnosed in which age group?", "o": {"A": "Less than 30 years old", "B": "40 to 60 years old", "C": "Greater than 60 years old", "D": "Only in neonates"}, "r": "A", "e": {"correcta": "Type 1 diabetes typically manifests in childhood or adolescence, generally before age 30, presenting with signs of absolute insulin deficiency such as weight loss, polyuria, and polydipsia, often precipitated acutely by an infection or other stressor unmasking the autoimmune beta-cell loss.", "incorrectas": {"B": "Onset in the 40-60 age range is more typical of type 2 diabetes, which usually presents in middle-aged, often obese adults due to insulin resistance rather than autoimmune beta-cell destruction.", "C": "Onset after age 60 is atypical for type 1 diabetes; while late-onset autoimmune diabetes can occur, the classic teaching for type 1 diabetes is presentation in childhood/young adulthood.", "D": "While congenital and neonatal diabetes syndromes exist, they are rare monogenic conditions distinct from typical type 1 diabetes, which classically presents in childhood through young adulthood, not exclusively in neonates."}}}, {"id": "anking-endocrine-pathology-1704", "fuente": "anking", "tema": 5, "anki": "1462327011039", "q": "Type 2 diabetes mellitus most commonly presents in which age group?", "o": {"A": "Less than 20 years old", "B": "20 to 30 years old", "C": "Greater than 40 years old", "D": "Exclusively in adolescents"}, "r": "C", "e": {"correcta": "Type 2 diabetes classically presents after age 40, often in middle-aged, obese individuals, as chronic insulin resistance and progressive beta-cell dysfunction develop over years, though rising obesity rates have increasingly caused earlier-onset cases in younger patients.", "incorrectas": {"A": "Presentation before age 20 is much more characteristic of type 1 diabetes, driven by autoimmune beta-cell destruction, rather than the insulin-resistance pattern of classic type 2 diabetes.", "B": "Onset in the 20-30 age range is atypical for classic type 2 diabetes; this age group is more commonly associated with type 1 diabetes or monogenic forms like MODY.", "D": "Type 2 diabetes is not exclusive to adolescents; despite rising pediatric obesity increasing incidence in youth, the disease classically and most commonly presents after age 40."}}}, {"id": "anking-endocrine-pathology-1705", "fuente": "anking", "tema": 5, "anki": "1462327016536", "q": "Compared with type 2 diabetes, type 1 diabetes mellitus has which relative degree of genetic predisposition, as shown by twin concordance studies?", "o": {"A": "Relatively strong (90% concordance in identical twins)", "B": "No genetic component (0% concordance)", "C": "Relatively weak (50% concordance in identical twins)", "D": "Complete genetic determinism (100% concordance)"}, "r": "C", "e": {"correcta": "Type 1 diabetes shows only about 50% concordance in identical twins, indicating a relatively weak genetic predisposition compared to type 2 diabetes; environmental triggers (e.g., viral infections) combined with HLA-DR3/DR4 susceptibility genes contribute to autoimmune beta-cell destruction.", "incorrectas": {"A": "90% twin concordance describes type 2 diabetes, which has a much stronger genetic component than type 1 diabetes, reflecting the polygenic and lifestyle-driven nature of insulin resistance.", "B": "Type 1 diabetes does have a genetic component (evidenced by HLA associations and the 50% twin concordance), so zero genetic contribution is incorrect.", "D": "100% concordance would imply purely genetic determinism with no environmental contribution, which is not the case for type 1 diabetes since even identical twins can be discordant, highlighting a significant environmental/immunologic role."}}}, {"id": "anking-endocrine-pathology-1706", "fuente": "anking", "tema": 5, "anki": "1462327023070", "q": "Compared with type 1 diabetes, type 2 diabetes mellitus has which relative degree of genetic predisposition, based on twin studies?", "o": {"A": "Relatively strong (90% concordance)", "B": "Relatively weak (50% concordance)", "C": "No heritable component", "D": "Weaker than type 1 diabetes"}, "r": "A", "e": {"correcta": "Type 2 diabetes shows approximately 90% concordance in identical twins, reflecting a strong polygenic predisposition combined with lifestyle factors like obesity and sedentary behavior, in contrast to the weaker (about 50%) concordance seen in type 1 diabetes.", "incorrectas": {"B": "50% twin concordance is characteristic of type 1 diabetes, which has a comparatively weaker genetic component than type 2 diabetes.", "C": "Type 2 diabetes clearly has a strong heritable component, as demonstrated by its high twin concordance rate and its tendency to cluster in families.", "D": "Type 2 diabetes actually shows a stronger, not weaker, genetic predisposition than type 1 diabetes, based on the higher twin concordance rate observed."}}}, {"id": "anking-endocrine-pathology-1707", "fuente": "anking", "tema": 5, "anki": "1462327031605", "q": "Histologic examination of the pancreas in type 1 diabetes mellitus classically shows islets with which finding?", "o": {"A": "Amyloid deposits", "B": "Fibrosis with calcification", "C": "Fatty replacement of acinar tissue", "D": "Leukocytic infiltrate (insulitis)"}, "r": "D", "e": {"correcta": "Type 1 diabetes shows leukocytic infiltration of the pancreatic islets (insulitis), reflecting the autoimmune, T-cell mediated destruction of beta cells that defines the disease's type IV hypersensitivity pathogenesis.", "incorrectas": {"A": "Amyloid deposits within the islets are the classic histologic finding in type 2 diabetes, resulting from deposition of islet amyloid polypeptide (amylin) co-secreted with insulin, not from autoimmune inflammation.", "B": "Fibrosis with calcification is more characteristic of chronic pancreatitis affecting the exocrine pancreas, not the immune-mediated islet destruction seen in type 1 diabetes.", "C": "Fatty replacement of acinar tissue can be seen in conditions like cystic fibrosis or obesity-related pancreatic changes, not as the defining islet finding in type 1 diabetes."}}}, {"id": "anking-endocrine-pathology-1708", "fuente": "anking", "tema": 5, "anki": "1462327043159", "q": "Histologic examination of the pancreas in type 2 diabetes mellitus classically shows islets with which finding?", "o": {"A": "Leukocytic infiltrate", "B": "Granulomatous inflammation", "C": "Amyloid deposits", "D": "Islet cell hyperplasia only, no deposits"}, "r": "C", "e": {"correcta": "Type 2 diabetes is associated with amyloid deposition within the pancreatic islets, formed from islet amyloid polypeptide (amylin), which is co-secreted with insulin; chronic hypersecretion of insulin in the setting of insulin resistance contributes to this amyloid accumulation over time.", "incorrectas": {"A": "A leukocytic infiltrate (insulitis) is the histologic hallmark of type 1 diabetes, reflecting autoimmune T-cell mediated beta-cell destruction, not the amyloid deposition seen in type 2 diabetes.", "B": "Granulomatous inflammation is not a feature of either type of diabetes; it is more typical of conditions like tuberculosis, sarcoidosis, or certain fungal infections.", "D": "Islet cell hyperplasia without deposits does not describe the classic pathologic finding in type 2 diabetes, which specifically involves visible amyloid deposits within the islets on histology."}}}, {"id": "anking-endocrine-pathology-1709", "fuente": "anking", "tema": 5, "anki": "1462327053167", "q": "In a patient with type 2 diabetes mellitus, how does serum insulin level typically change over the course of the disease?", "o": {"A": "Always decreased from disease onset", "B": "Always increased throughout the disease course", "C": "Variable — initially increased, but may decrease later due to beta-cell exhaustion", "D": "Absent from the start, similar to type 1 diabetes"}, "r": "C", "e": {"correcta": "In type 2 diabetes, insulin levels are initially elevated as beta cells compensate for peripheral insulin resistance; however, over time, chronic overstimulation can lead to beta-cell exhaustion and a decline in insulin secretion, making the insulin level variable depending on disease stage.", "incorrectas": {"A": "Insulin is not decreased from the outset in type 2 diabetes; early in the disease, compensatory hyperinsulinemia is typical as the pancreas attempts to overcome insulin resistance.", "B": "Insulin levels do not remain elevated indefinitely; with disease progression, beta-cell exhaustion can cause insulin secretion to decline, making a constantly elevated level inaccurate.", "D": "An absolute absence of insulin from disease onset describes type 1 diabetes (due to autoimmune beta-cell destruction), not the gradual, resistance-driven course of type 2 diabetes where insulin starts elevated."}}}, {"id": "anking-endocrine-pathology-1710", "fuente": "anking", "tema": 5, "anki": "1462327061414", "q": "Type 1 diabetes mellitus shows the strongest HLA associations with which alleles?", "o": {"A": "HLA-B27", "B": "HLA-DR2 only", "C": "HLA-DR3 and HLA-DR4", "D": "HLA-A3"}, "r": "C", "e": {"correcta": "Type 1 diabetes is strongly associated with HLA-DR3 and HLA-DR4, class II MHC alleles that influence antigen presentation to T cells and contribute to the autoimmune destruction of pancreatic beta cells characteristic of the disease.", "incorrectas": {"A": "HLA-B27 is classically associated with the seronegative spondyloarthropathies (e.g., ankylosing spondylitis, reactive arthritis), not with type 1 diabetes.", "B": "HLA-DR2 is associated with conditions such as narcolepsy and Goodpasture syndrome, not with the primary genetic risk alleles for type 1 diabetes, which are DR3 and DR4.", "D": "HLA-A3 is associated with hereditary hemochromatosis, an iron overload disorder unrelated to the autoimmune beta-cell destruction of type 1 diabetes."}}}, {"id": "anking-endocrine-pathology-1711", "fuente": "anking", "tema": 5, "anki": "1462327073683", "q": "Why do patients with type 1 diabetes mellitus present with weight loss and decreased muscle mass?", "o": {"A": "Increased lipolysis and proteolysis occur due to unopposed glucagon from lack of insulin", "B": "Excess insulin promotes fat and protein synthesis uncontrollably", "C": "Chronic malabsorption from autoimmune enteropathy", "D": "Increased cortisol secretion causes catabolism independent of insulin status"}, "r": "A", "e": {"correcta": "In type 1 diabetes, the absolute lack of insulin removes its normal inhibitory effect on glucagon and its anabolic actions, leading to unopposed glucagon-driven lipolysis and proteolysis. This breakdown of fat and muscle for energy produces the characteristic weight loss and decreased muscle mass despite often normal or increased caloric intake.", "incorrectas": {"B": "Insulin is deficient, not in excess, in type 1 diabetes; without insulin's anabolic signaling, fat and protein synthesis are impaired rather than promoted, contributing to catabolism instead of build-up.", "C": "Autoimmune enteropathy causing malabsorption is not the mechanism behind weight loss in type 1 diabetes; the wasting is due to unopposed catabolic hormone action from insulin deficiency, not nutrient malabsorption.", "D": "While stress hormones can contribute to hyperglycemia, the primary driver of the wasting syndrome in type 1 diabetes is the loss of insulin's anabolic/anti-catabolic effects, unmasking glucagon's lipolytic and proteolytic actions, not an independent cortisol effect."}}}, {"id": "anking-endocrine-physiology-1712", "fuente": "anking", "tema": 23, "anki": "1462327089156", "q": "Why do patients with diabetes mellitus present with polyuria and polydipsia?", "o": {"A": "Excess glucose filtered into the urine creates an osmotic effect that pulls water with it", "B": "ADH secretion is chronically suppressed by hyperglycemia", "C": "Renal tubules develop resistance to aldosterone", "D": "Hyperglycemia directly damages the glomerular basement membrane, causing proteinuria-driven fluid loss"}, "r": "A", "e": {"correcta": "When serum glucose exceeds the renal reabsorptive threshold, excess glucose is filtered into the urine, creating an osmotic diuresis that pulls water along with it, producing polyuria. The resulting fluid loss and increased serum osmolality then stimulate thirst, causing compensatory polydipsia.", "incorrectas": {"B": "ADH secretion is not suppressed by hyperglycemia; in fact, the resulting dehydration and rising osmolality would normally stimulate ADH release, but the osmotic diuresis from glucosuria overwhelms the kidney's ability to concentrate urine despite ADH.", "C": "Aldosterone resistance affecting sodium and potassium handling is not the mechanism behind diabetic polyuria; the driving force is osmotic diuresis from glucose in the tubular fluid, not a mineralocorticoid receptor problem.", "D": "While chronic hyperglycemia does eventually damage the glomerular basement membrane (diabetic nephropathy), this is a long-term complication and not the acute mechanism causing polyuria and polydipsia, which is due to glucosuria-induced osmotic diuresis."}}}, {"id": "anking-endocrine-pathology-1713", "fuente": "anking", "tema": 5, "anki": "1462327127564", "q": "What is the most common type of diabetes mellitus?", "o": {"A": "Type 1 diabetes mellitus", "B": "Maturity-onset diabetes of the young", "C": "Type 2 diabetes mellitus", "D": "Diabetes secondary to pancreatitis"}, "r": "C", "e": {"correcta": "Type 2 diabetes mellitus accounts for the vast majority of diabetes cases, driven primarily by insulin resistance related to obesity, sedentary lifestyle, and genetic predisposition, making it far more prevalent than the autoimmune type 1 form.", "incorrectas": {"A": "Type 1 diabetes, caused by autoimmune beta-cell destruction, represents a much smaller proportion of diabetes cases overall compared to the insulin-resistance-driven type 2 form.", "B": "Maturity-onset diabetes of the young is a rare group of monogenic diabetes syndromes, representing only a small fraction of diabetes cases compared to the much more common type 2 diabetes.", "D": "Diabetes secondary to pancreatitis (or other pancreatic damage) is an uncommon secondary cause of diabetes, far less prevalent than the common insulin-resistance pathophysiology of type 2 diabetes."}}}, {"id": "anking-endocrine-pathology-1714", "fuente": "anking", "tema": 5, "anki": "1462327133002", "q": "Which demographic is most commonly associated with the development of type 2 diabetes mellitus?", "o": {"A": "Young, thin patients", "B": "Elderly patients with low BMI", "C": "Children with a history of viral infections", "D": "Middle-aged, obese patients"}, "r": "D", "e": {"correcta": "Type 2 diabetes classically develops in middle-aged, obese patients, since excess adiposity contributes directly to peripheral insulin resistance, which is the central pathophysiologic driver of this form of diabetes.", "incorrectas": {"A": "Young, thin patients presenting with diabetes are more suggestive of type 1 diabetes or a monogenic form like MODY, not the obesity-driven insulin resistance typical of type 2 diabetes.", "B": "Low BMI is atypical for type 2 diabetes; obesity is a central risk factor because excess adipose tissue contributes to insulin receptor downregulation and resistance.", "C": "A preceding viral infection triggering autoimmune beta-cell destruction is more characteristic of the proposed mechanism for type 1 diabetes, not the metabolic syndrome-related pathophysiology of type 2 diabetes."}}}, {"id": "anking-endocrine-pathology-1715", "fuente": "anking", "tema": 5, "anki": "1462327139204", "q": "In obese patients, what mechanism underlies the insulin resistance that leads to type 2 diabetes mellitus?", "o": {"A": "Obesity causes downregulation of insulin receptors on target tissues", "B": "Obesity triggers autoimmune destruction of pancreatic beta cells", "C": "Obesity increases renal clearance of insulin, lowering circulating levels", "D": "Obesity causes a mutation in the insulin gene itself"}, "r": "A", "e": {"correcta": "Obesity causes downregulation of insulin receptors on peripheral tissues (such as muscle and adipose tissue), reducing their sensitivity to circulating insulin. This receptor-level resistance requires the pancreas to secrete more insulin to achieve the same glucose-lowering effect, eventually contributing to type 2 diabetes.", "incorrectas": {"B": "Autoimmune destruction of beta cells is the mechanism behind type 1 diabetes, not the insulin-resistance-driven pathophysiology linking obesity to type 2 diabetes.", "C": "Increased renal clearance of insulin is not the mechanism connecting obesity to insulin resistance; the core problem is reduced receptor sensitivity at target tissues, not accelerated insulin removal.", "D": "Type 2 diabetes is not caused by a mutation in the insulin gene itself; the insulin molecule is structurally normal, but tissues become resistant to its action due to receptor downregulation and post-receptor signaling defects."}}}, {"id": "anking-endocrine-pharmacology-1716", "fuente": "anking", "tema": 24, "anki": "1462327150620", "q": "Chronic use of which class of drugs can precipitate 'steroid diabetes'?", "o": {"A": "Glucocorticoids", "B": "Thiazide diuretics", "C": "Beta-blockers", "D": "ACE inhibitors"}, "r": "A", "e": {"correcta": "Glucocorticoids promote gluconeogenesis, decrease peripheral glucose uptake, and antagonize insulin's action on target tissues, so chronic glucocorticoid therapy can induce insulin resistance and hyperglycemia, a condition known as steroid diabetes.", "incorrectas": {"B": "Thiazide diuretics can worsen glucose tolerance as a side effect, but this is not the classic 'steroid diabetes' phenomenon, which specifically refers to glucocorticoid-induced hyperglycemia.", "C": "Beta-blockers can mask hypoglycemic symptoms and have modest effects on glucose metabolism, but they are not the class of drugs associated with the well-known steroid-induced diabetes syndrome.", "D": "ACE inhibitors are not associated with causing diabetes; they are renoprotective in diabetic patients and do not induce the insulin resistance seen with chronic glucocorticoid use."}}}, {"id": "anking-endocrine-physiology-1717", "fuente": "anking", "tema": 23, "anki": "1462327161497", "q": "Which laboratory test is used to diagnose and monitor diabetes mellitus by reflecting average blood glucose over the prior 2-3 months?", "o": {"A": "Fasting C-peptide", "B": "Random urine glucose", "C": "HbA1c", "D": "Serum fructosamine"}, "r": "C", "e": {"correcta": "HbA1c is the glycated form of hemoglobin, formed when glucose non-enzymatically binds hemoglobin within red blood cells. Since red blood cells live approximately 2-3 months, HbA1c provides a reliable estimate of average blood glucose control over that period and is used both diagnostically and to monitor long-term glycemic control.", "incorrectas": {"A": "Fasting C-peptide reflects endogenous insulin production (useful for distinguishing endogenous from exogenous insulin or assessing beta-cell reserve), but it does not reflect average glucose levels over time the way HbA1c does.", "B": "Random urine glucose only indicates whether the current blood glucose exceeds the renal threshold at that moment; it does not provide any information about average glycemic control over weeks to months.", "D": "Serum fructosamine reflects glycated serum proteins (mainly albumin) and estimates average glucose over a much shorter period (about 2-3 weeks, reflecting albumin's shorter half-life), not the 2-3 month window provided by HbA1c."}}}, {"id": "anking-endocrine-pathology-1718", "fuente": "anking", "tema": 5, "anki": "1462327170017", "q": "What HbA1c value meets the diagnostic threshold for diabetes mellitus?", "o": {"A": "≥5.7%", "B": "≥6.5%", "C": "≥7.0%", "D": "≥8.0%"}, "r": "B", "e": {"correcta": "An HbA1c ≥6.5% reflects average glycemic control over the preceding 2-3 months (the lifespan of an erythrocyte) and is one of the accepted diagnostic criteria for diabetes mellitus, alongside fasting glucose ≥126 mg/dL and 2-hour OGTT ≥200 mg/dL.", "incorrectas": {"A": "5.7-6.4% is the range defining prediabetes (impaired glucose tolerance), a state of increased risk that has not yet crossed the threshold for a diabetes diagnosis.", "C": "7.0% is not a formal diagnostic cutoff; it is often used clinically as a treatment target for glycemic control in patients already diagnosed with diabetes, not for diagnosis itself.", "D": "8.0% is well above the diagnostic threshold and would represent poorly controlled diabetes in an already-diagnosed patient, not the minimum value used to establish the diagnosis."}}}, {"id": "anking-endocrine-pathology-1719", "fuente": "anking", "tema": 5, "anki": "1462327178225", "q": "A fasting plasma glucose above what value (after fasting >8 hours) meets criteria for a diagnosis of diabetes mellitus?", "o": {"A": "≥100 mg/dL", "B": "≥110 mg/dL", "C": "≥126 mg/dL", "D": "≥140 mg/dL"}, "r": "C", "e": {"correcta": "A fasting plasma glucose ≥126 mg/dL after at least 8 hours without caloric intake is one of the standard diagnostic criteria for diabetes mellitus, reflecting sustained impairment of insulin-mediated glucose disposal during the fasting state.", "incorrectas": {"A": "A fasting glucose of 100-125 mg/dL defines impaired fasting glucose (prediabetes), a risk state that precedes but does not itself satisfy the diagnostic threshold for diabetes.", "B": "110 mg/dL falls within the prediabetes range and is not a recognized diagnostic cutoff for either prediabetes or diabetes under current criteria.", "D": "140 mg/dL is actually the diagnostic cutoff used for the 2-hour oral glucose tolerance test in some contexts for impaired glucose tolerance, not the fasting glucose cutoff for diabetes."}}}, {"id": "anking-endocrine-pathology-1720", "fuente": "anking", "tema": 5, "anki": "1462327189114", "q": "During a 2-hour oral glucose tolerance test (75 g glucose load), what plasma glucose level at 2 hours is diagnostic of diabetes mellitus?", "o": {"A": "≥140 mg/dL", "B": "≥180 mg/dL", "C": "≥200 mg/dL", "D": "≥250 mg/dL"}, "r": "C", "e": {"correcta": "A 2-hour plasma glucose ≥200 mg/dL after ingesting 75 g of glucose in water indicates an inability to appropriately clear a glucose load, consistent with diabetes mellitus, and is one of the three standard diagnostic criteria along with fasting glucose and HbA1c.", "incorrectas": {"A": "140-199 mg/dL at 2 hours defines impaired glucose tolerance (prediabetes), not overt diabetes; the patient shows some difficulty handling the glucose load but not to a diagnostic degree.", "B": "180 mg/dL is not a formal OGTT diagnostic threshold for diabetes, though it is a commonly used glucose threshold in other contexts, such as the renal threshold for glucosuria.", "D": "250 mg/dL is well above the diagnostic cutoff and would be seen in more severe hyperglycemia, but is not the minimum value that defines the diagnostic threshold."}}}, {"id": "anking-endocrine-pathology-1721", "fuente": "anking", "tema": 5, "anki": "1462327203603", "q": "What is the normal range for blood glucose levels?", "o": {"A": "40-70 mg/dL", "B": "70-120 mg/dL", "C": "120-180 mg/dL", "D": "180-250 mg/dL"}, "r": "B", "e": {"correcta": "Normal blood glucose is maintained in the range of 70-120 mg/dL (roughly 4-6 mM) through the coordinated actions of insulin, glucagon, and counterregulatory hormones, keeping glucose available for tissues like the brain while avoiding the toxic effects of hyperglycemia.", "incorrectas": {"A": "40-70 mg/dL is below the normal range and would represent hypoglycemia, which can trigger counterregulatory hormone release (glucagon, epinephrine, cortisol, growth hormone) and neuroglycopenic symptoms.", "C": "120-180 mg/dL exceeds the normal fasting/random range and reflects hyperglycemia, such as postprandial glucose excursions or poorly controlled diabetes.", "D": "180-250 mg/dL is markedly elevated and corresponds to significant hyperglycemia, well above the renal threshold for glucosuria and typical of uncontrolled diabetes."}}}, {"id": "anking-endocrine-pathology-1722", "fuente": "anking", "tema": 5, "anki": "1462327211125", "q": "Which acute, life-threatening complication is most feared in patients with type 1 diabetes mellitus?", "o": {"A": "Hyperosmolar hyperglycemic state", "B": "Diabetic ketoacidosis", "C": "Lactic acidosis", "D": "Hypoglycemic coma"}, "r": "B", "e": {"correcta": "Diabetic ketoacidosis (DKA) is the classic acute emergency of type 1 diabetes, arising from near-total insulin deficiency that unleashes unopposed lipolysis and hepatic ketogenesis, producing hyperglycemia, ketonemia, and a high anion gap metabolic acidosis.", "incorrectas": {"A": "Hyperosmolar hyperglycemic state is the analogous life-threatening emergency of type 2 diabetes, where residual insulin secretion suppresses ketogenesis but is insufficient to prevent severe hyperglycemia and osmotic diuresis.", "C": "Lactic acidosis is not a hallmark complication of type 1 diabetes itself; it is more classically associated with metformin accumulation (used in type 2 diabetes) or tissue hypoperfusion states.", "D": "Hypoglycemic coma is a risk of insulin therapy (iatrogenic) rather than an intrinsic complication of the underlying type 1 diabetic pathophysiology in the way DKA is."}}}, {"id": "anking-endocrine-pathology-1723", "fuente": "anking", "tema": 5, "anki": "1462327224889", "q": "Diabetic ketoacidosis is classically precipitated by which type of trigger, such as an infection?", "o": {"A": "Excess insulin administration", "B": "Stress", "C": "Prolonged fasting alone", "D": "Excessive fluid intake"}, "r": "B", "e": {"correcta": "Physiologic stress (e.g., infection, surgery, myocardial infarction) raises counterregulatory hormones, especially epinephrine, which stimulates glucagon release; the resulting surge in glucagon exacerbates lipolysis and hepatic ketogenesis, precipitating DKA in an insulin-deficient patient.", "incorrectas": {"A": "Excess insulin would suppress lipolysis and ketogenesis, driving glucose down toward hypoglycemia rather than precipitating the hyperglycemic, ketotic state of DKA.", "C": "Prolonged fasting alone can produce mild ketosis (starvation ketosis) but does not typically generate the severe ketoacidosis and marked hyperglycemia seen in DKA, which requires profound insulin deficiency plus counterregulatory excess.", "D": "Excessive fluid intake would not drive the hormonal cascade of lipolysis and ketogenesis; if anything, DKA causes fluid loss via osmotic diuresis, not fluid excess as a trigger."}}}, {"id": "anking-endocrine-pathology-1724", "fuente": "anking", "tema": 5, "anki": "1462327309654", "q": "Which two ketone bodies are chiefly responsible for the ketoacidosis seen in a type 1 diabetic patient in DKA?", "o": {"A": "Acetone and lactate", "B": "Beta-hydroxybutyrate and acetoacetate", "C": "Pyruvate and acetoacetate", "D": "Acetone and beta-hydroxybutyrate"}, "r": "B", "e": {"correcta": "Unopposed lipolysis in insulin deficiency releases free fatty acids that undergo hepatic beta-oxidation and ketogenesis, producing beta-hydroxybutyrate (the more prevalent species) and acetoacetate, both of which are acidic and drive the anion gap metabolic acidosis of DKA.", "incorrectas": {"A": "Acetone is indeed a ketone body (formed by spontaneous decarboxylation of acetoacetate) but it is a neutral, volatile compound responsible for the fruity breath odor, not a major acid contributor; lactate is not a ketone body at all.", "C": "Pyruvate is a glycolytic intermediate, not a ketone body, and does not accumulate as part of the ketogenic pathway in DKA.", "D": "Acetone is a minor, non-acidic ketone byproduct rather than one of the two principal acidic ketone bodies driving the acidosis; beta-hydroxybutyrate and acetoacetate are the correct pairing."}}}, {"id": "anking-renal-pathology-1725", "fuente": "anking", "tema": 58, "anki": "1462327341080", "q": "What is the expected serum (extracellular) potassium level in a patient presenting with diabetic ketoacidosis?", "o": {"A": "Decreased", "B": "Normal", "C": "Increased", "D": "Undetectable"}, "r": "C", "e": {"correcta": "Serum potassium is typically increased (or normal-high) in DKA because insulin deficiency prevents potassium from being driven into cells, and the K+-H+ exchanger pushes potassium out of cells as the body buffers the metabolic acidosis, even though total body potassium is actually depleted.", "incorrectas": {"B": "A normal serum potassium can sometimes be seen but does not reflect the typical pathophysiology; the acidosis and insulin deficiency classically shift potassium extracellularly, raising the measured serum level despite total body depletion.", "A": "A decreased serum potassium is not the expected initial presentation; it is what can develop only after insulin therapy begins and drives potassium back into cells, unmasking the true total-body deficit.", "D": "Potassium becoming undetectable does not occur in DKA; the danger is actually a falsely reassuring high or normal serum level masking significant total body potassium depletion."}}}, {"id": "anking-renal-pathology-1726", "fuente": "anking", "tema": 58, "anki": "1462327346466", "q": "What happens to intracellular potassium levels in a patient with diabetic ketoacidosis?", "o": {"A": "Increased", "B": "Decreased", "C": "Unchanged", "D": "Cannot be determined"}, "r": "B", "e": {"correcta": "Intracellular potassium is decreased in DKA because insulin, which normally stimulates the Na+/K+-ATPase to drive potassium into cells, is deficient; without this uptake, total body potassium becomes depleted intracellularly even as serum levels appear elevated.", "incorrectas": {"A": "Intracellular potassium is not increased in DKA; the lack of insulin impairs cellular uptake of potassium, producing the opposite effect of intracellular depletion.", "C": "Intracellular potassium is not unchanged; the profound insulin deficiency in DKA specifically disrupts normal potassium handling, shifting the ion out of cells and lowering intracellular stores.", "D": "The direction of the change is well established pathophysiologically (decreased) and is a key reason IV potassium repletion is part of DKA management despite normal or high serum levels at presentation."}}}, {"id": "anking-renal-pathology-1727", "fuente": "anking", "tema": 58, "anki": "1462327363797", "q": "A patient with diabetic ketoacidosis is expected to have which acid-base disturbance?", "o": {"A": "Non-anion gap metabolic acidosis", "B": "Respiratory alkalosis", "C": "High anion gap metabolic acidosis", "D": "Metabolic alkalosis"}, "r": "C", "e": {"correcta": "DKA produces a high anion gap metabolic acidosis because the accumulating ketoacids (beta-hydroxybutyrate and acetoacetate) are unmeasured anions that consume bicarbonate buffer while widening the anion gap, distinguishing it from acidoses caused by bicarbonate loss.", "incorrectas": {"A": "A non-anion gap (hyperchloremic) metabolic acidosis results from bicarbonate loss or renal tubular dysfunction with chloride retention, not from an accumulation of unmeasured ketoacid anions as in DKA.", "B": "Respiratory alkalosis results from hyperventilation lowering CO2; in DKA, the compensatory Kussmaul respirations are a response to the metabolic acidosis, not a primary respiratory alkalosis.", "D": "Metabolic alkalosis involves a rise in serum bicarbonate/pH, the opposite derangement from the acid buildup and bicarbonate consumption that characterizes DKA."}}}, {"id": "anking-endocrine-pathology-1728", "fuente": "anking", "tema": 5, "anki": "1462327370877", "q": "A patient in diabetic ketoacidosis is expected to present with which glucose abnormality?", "o": {"A": "Hypoglycemia (<70 mg/dL)", "B": "Normoglycemia", "C": "Hyperglycemia (usually >300 mg/dL)", "D": "Glucose levels are unaffected"}, "r": "C", "e": {"correcta": "DKA presents with marked hyperglycemia, usually >300 mg/dL, because profound insulin deficiency prevents cellular glucose uptake while unopposed counterregulatory hormones (glucagon, catecholamines) drive gluconeogenesis and glycogenolysis, flooding the bloodstream with glucose.", "incorrectas": {"A": "Hypoglycemia is not characteristic of DKA; it would suggest excessive insulin administration or another process entirely, not the insulin-deficient hyperglycemic state of DKA.", "B": "Normoglycemia is inconsistent with the pathophysiology of DKA, though rare euglycemic DKA variants exist (e.g., with SGLT2 inhibitor use), the classic and expected presentation is marked hyperglycemia.", "D": "Glucose regulation is profoundly disrupted in DKA; the absence of insulin action is central to both the hyperglycemia and the ketogenesis that define the syndrome."}}}, {"id": "anking-clinical-bacteriology-1729", "fuente": "anking", "tema": 21, "anki": "1462327377004", "q": "Which fungal infection is a feared complication in patients with diabetic ketoacidosis?", "o": {"A": "Aspergillosis", "B": "Candidiasis", "C": "Mucormycosis", "D": "Cryptococcosis"}, "r": "C", "e": {"correcta": "Mucormycosis, most often caused by Rhizopus species, thrives in the acidic, hyperglycemic, iron-rich environment of DKA and classically causes rhinocerebral disease with black necrotic eschar, given the organism's angioinvasive growth into blood vessels and tissue.", "incorrectas": {"A": "Aspergillosis classically affects immunocompromised or neutropenic patients and those with chronic lung cavities (aspergilloma), and is not the fungal infection specifically associated with the acidotic, hyperglycemic milieu of DKA.", "B": "Candidiasis is common in diabetics generally (e.g., mucocutaneous or vaginal candidiasis due to hyperglycemia favoring fungal growth), but it is not the specific angioinvasive, life-threatening infection classically linked to DKA.", "D": "Cryptococcosis is associated with impaired cell-mediated immunity (e.g., HIV/AIDS) and causes meningitis, but it is not the organism classically triggered by the acidotic environment of DKA."}}}, {"id": "anking-endocrine-pathology-1730", "fuente": "anking", "tema": 5, "anki": "1462327382493", "q": "After correcting volume status, what is the mainstay treatment for diabetic ketoacidosis?", "o": {"A": "IV fluids, insulin, and potassium repletion", "B": "Oral hypoglycemics and sodium bicarbonate", "C": "IV glucagon and calcium gluconate", "D": "IV fluids and glucocorticoids"}, "r": "A", "e": {"correcta": "DKA management centers on IV fluids to correct volume depletion, IV insulin to shut off lipolysis and ketogenesis and drive glucose (and potassium) into cells, and potassium repletion to replace the depleted intracellular stores that will be unmasked as insulin therapy shifts potassium back into cells.", "incorrectas": {"B": "Oral hypoglycemics are not appropriate in an acute insulin-deficient emergency requiring immediate IV insulin, and bicarbonate is not routinely given because it can worsen paradoxical CNS acidosis and is reserved for severe cases.", "C": "Glucagon would raise blood glucose further and worsen the crisis, since DKA is a state of relative glucagon excess already; calcium gluconate is used for cardiac membrane stabilization in hyperkalemia, not as first-line DKA therapy.", "D": "Glucocorticoids are not part of standard DKA treatment; they can even worsen hyperglycemia by promoting gluconeogenesis and insulin resistance."}}}, {"id": "anking-endocrine-pathology-1731", "fuente": "anking", "tema": 5, "anki": "1462327389480", "q": "Which severe acute complication is most feared in patients with type 2 diabetes mellitus?", "o": {"A": "Diabetic ketoacidosis", "B": "Hyperosmolar hyperglycemic state", "C": "Lactic acidosis", "D": "Somogyi effect"}, "r": "B", "e": {"correcta": "Hyperosmolar hyperglycemic state (HHS) is the classic acute emergency of type 2 diabetes; severe hyperglycemia causes an osmotic diuresis leading to profound dehydration, hyperosmolarity, and potentially coma, occurring without significant ketosis because residual endogenous insulin suppresses lipolysis.", "incorrectas": {"A": "DKA is the parallel emergency but is classically associated with type 1 diabetes, where near-total insulin deficiency permits unchecked lipolysis and ketogenesis; residual insulin in type 2 diabetes usually prevents this.", "C": "Lactic acidosis is more classically linked to metformin toxicity or tissue hypoperfusion states, not a defining acute complication intrinsic to type 2 diabetes pathophysiology itself.", "D": "The Somogyi effect refers to rebound morning hyperglycemia following nocturnal hypoglycemia in insulin-treated patients, a dosing phenomenon rather than a life-threatening systemic emergency like HHS."}}}, {"id": "anking-endocrine-pathology-1732", "fuente": "anking", "tema": 5, "anki": "1462327432810", "q": "Which patient population is most classically associated with developing hyperosmolar hyperglycemic state?", "o": {"A": "Young type 1 diabetics who miss insulin doses", "B": "Elderly type 2 diabetics with limited ability to drink water", "C": "Pregnant patients with gestational diabetes", "D": "Children with new-onset type 1 diabetes"}, "r": "B", "e": {"correcta": "HHS classically occurs in elderly type 2 diabetics, particularly those with limited access to water (e.g., due to immobility, dementia, or living alone), since impaired thirst response and inability to replace osmotic fluid losses allow severe dehydration and extreme hyperglycemia to develop over days.", "incorrectas": {"A": "Young type 1 diabetics missing insulin doses are the classic setup for DKA, not HHS, since their near-total insulin deficiency permits ketogenesis, which is largely absent in HHS.", "C": "Gestational diabetes is not the population associated with HHS; HHS is a complication of long-standing type 2 diabetes, typically in older adults with comorbidities limiting fluid intake.", "D": "Children with new-onset type 1 diabetes typically present with DKA as the initial manifestation of their disease, not the insidious hyperosmolar picture of HHS seen in older type 2 diabetics."}}}, {"id": "anking-endocrine-pathology-1733", "fuente": "anking", "tema": 5, "anki": "1462327441833", "q": "Hyperosmolar hyperglycemic state classically presents with glucose levels exceeding what threshold, along with a serum osmolarity >320 mOsm/kg?", "o": {"A": "300 mg/dL", "B": "400 mg/dL", "C": "600 mg/dL", "D": "1000 mg/dL"}, "r": "C", "e": {"correcta": "HHS typically presents with glucose levels exceeding 600 mg/dL, far higher than the threshold seen in DKA (usually >300 mg/dL), because the gradual, prolonged osmotic diuresis over days allows glucose to climb to extreme levels alongside a markedly elevated serum osmolarity (>320 mOsm/kg).", "incorrectas": {"A": "300 mg/dL is closer to the glucose threshold classically cited for DKA, not the far higher glucose level (>600 mg/dL) that characterizes the more insidious, prolonged hyperglycemia of HHS.", "B": "400 mg/dL, while markedly elevated, is still below the level typically required to produce the profound hyperosmolarity that defines HHS.", "D": "1000 mg/dL is higher than the typical threshold cited for HHS diagnosis; while extreme hyperglycemia can occur, the classically taught cutoff is >600 mg/dL."}}}, {"id": "anking-endocrine-pathology-1734", "fuente": "anking", "tema": 5, "anki": "1462327461738", "q": "Why does hyperosmolar hyperglycemic state typically NOT present with significant ketoacidosis, unlike DKA?", "o": {"A": "Because glucagon levels are suppressed", "B": "Because ketone production is inhibited by the presence of residual insulin", "C": "Because renal clearance of ketones is enhanced", "D": "Because these patients lack functional adipose tissue"}, "r": "B", "e": {"correcta": "In type 2 diabetes, the pancreas still secretes some endogenous insulin, and even low levels are sufficient to suppress lipolysis and hepatic ketogenesis, so patients develop extreme hyperglycemia and dehydration without significant ketone production, distinguishing HHS from the ketosis-prone DKA of type 1 diabetes.", "incorrectas": {"A": "Glucagon is not the key differentiator; the essential distinction is the presence of some residual insulin in type 2 diabetes, which is enough to block ketogenesis even amid severe hyperglycemia.", "C": "Enhanced renal ketone clearance is not the mechanism preventing ketoacidosis in HHS; the difference lies in insulin sufficiency to suppress ketone production at the source (the liver), not in clearance.", "D": "Patients with HHS have normal adipose tissue; the reason lipolysis and ketogenesis are suppressed is the presence of some insulin, not an absence of fat stores to mobilize."}}}, {"id": "anking-endocrine-pathology-1735", "fuente": "anking", "tema": 5, "anki": "1462327473707", "q": "What is the primary treatment approach for hyperosmolar hyperglycemic state?", "o": {"A": "Sodium bicarbonate infusion", "B": "Oral metformin initiation", "C": "Intense IV fluids and insulin therapy", "D": "Emergent hemodialysis"}, "r": "C", "e": {"correcta": "HHS is treated with aggressive IV fluid resuscitation to correct the severe dehydration from osmotic diuresis, combined with insulin therapy to lower serum glucose and halt the ongoing osmotic fluid losses, mirroring the fluids-first approach used in DKA.", "incorrectas": {"A": "Sodium bicarbonate is not indicated because HHS does not typically involve significant metabolic acidosis (unlike DKA), so there is no acid-base derangement to correct with bicarbonate.", "B": "Oral metformin is inappropriate in an acute hyperosmolar emergency requiring rapid IV correction of volume and glucose; oral agents have no role in this acute crisis.", "D": "Hemodialysis is not a first-line treatment for HHS; the mainstay is fluid and insulin therapy, with dialysis reserved for other specific indications like severe renal failure or refractory electrolyte abnormalities."}}}, {"id": "anking-endocrine-pathology-1736", "fuente": "anking", "tema": 5, "anki": "1462327481691", "q": "Chronic hyperglycemia in diabetes mellitus leads to which biochemical process affecting vascular basement membranes?", "o": {"A": "Amyloid deposition", "B": "Non-enzymatic glycosylation", "C": "Complement-mediated injury", "D": "Fibrinoid necrosis"}, "r": "B", "e": {"correcta": "Persistently elevated glucose covalently and non-enzymatically attaches to proteins in vascular basement membranes (non-enzymatic glycosylation), leading to membrane thickening and dysfunction that underlies many chronic microvascular and macrovascular complications of diabetes.", "incorrectas": {"A": "Amyloid deposition refers to extracellular accumulation of misfolded protein fibrils (e.g., islet amyloid polypeptide in type 2 diabetes pancreatic islets), a distinct process from the glucose-protein modification driving basement membrane changes.", "C": "Complement-mediated injury involves immune-mediated tissue damage via complement activation, which is not the mechanism responsible for diabetic vascular basement membrane thickening.", "D": "Fibrinoid necrosis describes vessel wall damage seen in conditions like malignant hypertension or vasculitis, characterized by deposition of fibrin-like material, distinct from the chronic glycosylation process of diabetes."}}}, {"id": "anking-endocrine-pathology-1737", "fuente": "anking", "tema": 5, "anki": "1462327558597", "q": "What is the leading cause of death in patients with diabetes mellitus?", "o": {"A": "Diabetic ketoacidosis", "B": "Chronic renal failure", "C": "Myocardial infarction", "D": "Sepsis from foot ulcers"}, "r": "C", "e": {"correcta": "Myocardial infarction is the leading cause of death in diabetics, driven by accelerated atherosclerosis of large vessels resulting from chronic non-enzymatic glycosylation of vascular proteins, which promotes endothelial dysfunction and plaque formation.", "incorrectas": {"A": "DKA is an important acute emergency but, with modern management, is not the leading overall cause of mortality in diabetic patients compared to the cumulative cardiovascular burden of chronic disease.", "B": "Chronic renal failure is a major diabetic complication (diabetic nephropathy) and contributes to morbidity and mortality, but cardiovascular disease, particularly MI, remains the single leading cause of death.", "D": "Sepsis from foot ulcers is a serious complication related to diabetic neuropathy and vascular disease, but it is not the statistically leading cause of death compared to myocardial infarction."}}}, {"id": "anking-dermatology-1738", "fuente": "anking", "tema": 50, "anki": "1462327570500", "q": "Non-enzymatic glycosylation of medium and large-sized vessels in diabetic patients most classically leads to which complication, a leading cause of nontraumatic amputation?", "o": {"A": "Peripheral vascular occlusive disease", "B": "Deep vein thrombosis", "C": "Raynaud phenomenon", "D": "Buerger disease"}, "r": "A", "e": {"correcta": "Glycosylation-driven accelerated atherosclerosis in medium and large vessels produces peripheral vascular occlusive disease, causing critical limb ischemia, poor wound healing, and ulceration that make it the leading cause of nontraumatic lower-extremity amputation in diabetic patients.", "incorrectas": {"B": "Deep vein thrombosis is a venous thromboembolic process related to stasis, hypercoagulability, and vessel wall injury (Virchow triad), not the arterial occlusive disease driven by glycosylation-accelerated atherosclerosis.", "C": "Raynaud phenomenon is a vasospastic disorder of digital arteries typically triggered by cold or stress, often associated with connective tissue diseases, not the chronic atherosclerotic process seen in diabetes.", "D": "Buerger disease (thromboangiitis obliterans) is a segmental vasculitis strongly linked to heavy tobacco use in young men, distinct from the diffuse atherosclerotic vascular disease caused by diabetic glycosylation."}}}, {"id": "anking-renal-pathology-1739", "fuente": "anking", "tema": 58, "anki": "1462327588618", "q": "Non-enzymatic glycosylation of small renal vessels in diabetic patients classically produces which pathologic finding, including Kimmelstiel-Wilson nodules?", "o": {"A": "Minimal change disease", "B": "Nodular glomerulosclerosis", "C": "Crescentic glomerulonephritis", "D": "Membranous nephropathy"}, "r": "B", "e": {"correcta": "Chronic hyperglycemia causes non-enzymatic glycosylation and hyalinization of the glomerular basement membrane and mesangium, producing nodular glomerulosclerosis with pathognomonic Kimmelstiel-Wilson nodules, a major cause of chronic renal failure in diabetics.", "incorrectas": {"A": "Minimal change disease shows effacement of podocyte foot processes on electron microscopy with a normal-appearing glomerulus on light microscopy, typically idiopathic or associated with lymphoma, not a diabetic glycosylation process.", "C": "Crescentic glomerulonephritis is characterized by cellular crescents from severe glomerular injury, seen in rapidly progressive glomerulonephritis syndromes, not the nodular sclerotic pattern of diabetic nephropathy.", "D": "Membranous nephropathy shows subepithelial immune complex deposits with a 'spike and dome' pattern on the basement membrane, a distinct immune-mediated process unrelated to diabetic glycosylation."}}}, {"id": "anking-renal-pathology-1740", "fuente": "anking", "tema": 58, "anki": "1462327605465", "q": "Non-enzymatic glycosylation of small renal vessels in diabetic patients can cause which vascular lesion, contributing to chronic renal failure?", "o": {"A": "Fibromuscular dysplasia", "B": "Hyaline arteriolosclerosis", "C": "Hyperplastic arteriolosclerosis", "D": "Polyarteritis nodosa"}, "r": "B", "e": {"correcta": "Diabetic glycosylation of arteriolar walls produces hyaline arteriolosclerosis, characterized histologically by homogeneous pink hyaline material within the vessel wall that narrows the lumen, contributing to renal ischemia and chronic renal failure.", "incorrectas": {"A": "Fibromuscular dysplasia is a non-atherosclerotic, non-inflammatory arterial disease causing a 'string of beads' appearance, most classically affecting the renal arteries of young women, unrelated to diabetic glycosylation.", "C": "Hyperplastic arteriolosclerosis shows an 'onion-skin' concentric thickening of arteriolar walls and is classically associated with malignant hypertension, not the hyaline pattern of diabetic small-vessel disease.", "D": "Polyarteritis nodosa is a systemic necrotizing vasculitis of medium-sized arteries often associated with hepatitis B, a distinct inflammatory process rather than the metabolic hyalinization seen in diabetes."}}}, {"id": "anking-endocrine-pathology-1741", "fuente": "anking", "tema": 5, "anki": "1462327641370", "q": "Non-enzymatic glycosylation of hemoglobin produces which clinically useful marker of long-term glycemic control?", "o": {"A": "C-peptide", "B": "HbA1c", "C": "Fructosamine only", "D": "Carboxyhemoglobin"}, "r": "B", "e": {"correcta": "Glucose non-enzymatically and irreversibly binds hemoglobin over the lifespan of the red blood cell, forming HbA1c, which serves as a marker of average glycemic control over the preceding 2-3 months and is used both diagnostically and for monitoring treatment.", "incorrectas": {"A": "C-peptide is a byproduct of proinsulin cleavage that reflects endogenous insulin secretion, useful for distinguishing exogenous insulin use or diagnosing insulinoma, not a product of hemoglobin glycosylation.", "C": "Fructosamine is also a glycated protein marker (glycated serum proteins/albumin) reflecting shorter-term (2-3 week) glycemic control, but it is not the glycosylated hemoglobin product referred to here.", "D": "Carboxyhemoglobin results from hemoglobin binding carbon monoxide, a completely different chemical interaction unrelated to glucose or glycemic control."}}}, {"id": "anking-endocrine-pathology-1742", "fuente": "anking", "tema": 5, "anki": "1462327732727", "q": "A tumor arising from pancreatic alpha cells is called what?", "o": {"A": "Insulinoma", "B": "Somatostatinoma", "C": "Glucagonoma", "D": "VIPoma"}, "r": "C", "e": {"correcta": "Glucagonoma arises from pancreatic alpha cells and secretes excess glucagon, producing hyperglycemia (diabetes), necrolytic migratory erythema, weight loss, and a hypercoagulable state predisposing to DVT.", "incorrectas": {"A": "Insulinoma arises from pancreatic beta cells and secretes excess insulin, causing hypoglycemia rather than the hyperglycemia and catabolic features seen with glucagonoma.", "B": "Somatostatinoma arises from pancreatic delta cells and broadly inhibits multiple GI hormones (secretin, CCK, gastrin, insulin, glucagon), producing a distinct syndrome of diabetes, gallstones, and steatorrhea, not the alpha-cell tumor described.", "D": "VIPoma secretes vasoactive intestinal peptide and arises from non-alpha, non-beta pancreatic islet cells (or neural crest-derived cells), causing the WDHA syndrome (watery diarrhea, hypokalemia, achlorhydria), not from alpha cells."}}}, {"id": "anking-endocrine-pathology-1743", "fuente": "anking", "tema": 5, "anki": "1462327744491", "q": "A patient presents with necrolytic migratory erythema, new-onset diabetes, deep vein thrombosis, weight loss, and depression. Which hormone-secreting pancreatic tumor best explains this presentation?", "o": {"A": "Insulinoma", "B": "VIPoma", "C": "Gastrinoma", "D": "Glucagonoma"}, "r": "D", "e": {"correcta": "Glucagonoma, a tumor of pancreatic alpha cells, produces this classic constellation because glucagon excess promotes catabolism (weight loss), hyperglycemia (diabetes), a hypercoagulable state (DVT), and necrolytic migratory erythema from hypoaminoacidemia and zinc/essential fatty acid deficiency.", "incorrectas": {"A": "Insulinoma causes hypoglycemia with neuroglycopenic symptoms (Whipple triad), the opposite metabolic direction from the diabetes and catabolic wasting seen with glucagon excess.", "B": "VIPoma causes the WDHA syndrome of watery diarrhea, hypokalemia, and achlorhydria, a presentation dominated by secretory diarrhea rather than the skin, diabetic, and thrombotic findings described.", "C": "Gastrinoma (Zollinger-Ellison syndrome) causes recurrent peptic ulcers and diarrhea from gastric acid hypersecretion, not the dermatologic rash, diabetes, and DVT triad characteristic of glucagonoma."}}}, {"id": "anking-endocrine-pharmacology-1744", "fuente": "anking", "tema": 24, "anki": "1462327755265", "q": "Besides surgical resection, which medical therapy is used to treat glucagonoma?", "o": {"A": "Metformin", "B": "Octreotide (a somatostatin analog)", "C": "Insulin infusion", "D": "Proton pump inhibitors"}, "r": "B", "e": {"correcta": "Octreotide, a somatostatin analog, is used to treat glucagonoma because somatostatin broadly inhibits pancreatic and GI hormone secretion, suppressing glucagon release and thereby controlling the hyperglycemia, catabolic wasting, and skin manifestations of the tumor when surgery is not curative or feasible.", "incorrectas": {"A": "Metformin is an oral hypoglycemic used in type 2 diabetes management by decreasing hepatic gluconeogenesis, but it does not address the underlying hormone-secreting tumor driving glucagonoma's hyperglycemia.", "C": "Insulin infusion could help control the hyperglycemia symptomatically but does not target the tumor itself or reduce glucagon secretion the way a somatostatin analog does.", "D": "Proton pump inhibitors are used for acid-hypersecretory conditions like Zollinger-Ellison syndrome (gastrinoma), not for glucagonoma, which is not driven by excess gastric acid."}}}, {"id": "anking-endocrine-pathology-1745", "fuente": "anking", "tema": 5, "anki": "1462327759863", "q": "A tumor arising from pancreatic beta cells is called what?", "o": {"A": "Insulinoma", "B": "Glucagonoma", "C": "Gastrinoma", "D": "Somatostatinoma"}, "r": "A", "e": {"correcta": "Insulinoma is a tumor of pancreatic beta cells that autonomously secretes excess insulin, causing episodic hypoglycemia with elevated insulin and C-peptide levels, distinguishing it from exogenous insulin administration.", "incorrectas": {"B": "Glucagonoma arises from alpha cells and secretes glucagon, producing hyperglycemia and catabolic features, the opposite metabolic picture from the hypoglycemia caused by insulinoma.", "C": "Gastrinoma arises from gastrin-secreting cells (often in the pancreas or duodenum) and causes Zollinger-Ellison syndrome with recurrent peptic ulcers, unrelated to beta-cell insulin secretion.", "D": "Somatostatinoma arises from delta cells and broadly inhibits hormone secretion, producing diabetes, gallstones, and steatorrhea, a distinct entity from the beta-cell-derived insulinoma."}}}, {"id": "anking-endocrine-pathology-1746", "fuente": "anking", "tema": 5, "anki": "1462327792664", "q": "A symptomatic patient with insulinoma is expected to have which combination of blood glucose and C-peptide levels?", "o": {"A": "High glucose, low C-peptide", "B": "Low glucose, low C-peptide", "C": "Low glucose, high C-peptide", "D": "High glucose, high C-peptide"}, "r": "C", "e": {"correcta": "Insulinoma causes autonomous insulin secretion, driving blood glucose low while insulin and C-peptide (co-secreted in equimolar amounts from proinsulin cleavage) are elevated, a pattern that helps confirm endogenous insulin hypersecretion as the cause of hypoglycemia.", "incorrectas": {"A": "High glucose with low C-peptide does not fit insulinoma physiology at all; it would be more consistent with insulin deficiency states, not autonomous endogenous insulin oversecretion.", "B": "Low glucose with low C-peptide is the pattern seen with exogenous (surreptitious) insulin injection, since injected insulin suppresses endogenous insulin/C-peptide production, distinguishing it from insulinoma.", "D": "High glucose with high C-peptide would suggest insulin resistance (as in type 2 diabetes) with compensatory endogenous insulin secretion, not the hypoglycemia caused by an insulin-secreting tumor."}}}, {"id": "anking-endocrine-pathology-1747", "fuente": "anking", "tema": 5, "anki": "1462327808151", "q": "Approximately 10% of insulinoma cases occur in association with which hereditary syndrome?", "o": {"A": "MEN 1", "B": "MEN 2A", "C": "MEN 2B", "D": "Von Hippel-Lindau disease"}, "r": "A", "e": {"correcta": "About 10% of insulinomas occur as part of MEN 1 syndrome (parathyroid, pituitary, and pancreatic tumors), which arises from mutations in the MEN1 tumor suppressor gene and predisposes to multiple endocrine neoplasms, including pancreatic islet cell tumors like insulinoma and gastrinoma.", "incorrectas": {"B": "MEN 2A involves medullary thyroid carcinoma, pheochromocytoma, and parathyroid hyperplasia, driven by RET proto-oncogene mutations, and does not classically feature pancreatic islet cell tumors like insulinoma.", "C": "MEN 2B involves medullary thyroid carcinoma, pheochromocytoma, and mucosal neuromas/marfanoid habitus, also due to RET mutations, and similarly does not include pancreatic insulinomas as a component.", "D": "Von Hippel-Lindau disease is associated with hemangioblastomas, renal cell carcinoma, and pheochromocytoma due to VHL gene mutations, not the pancreatic endocrine tumors characteristic of MEN 1."}}}, {"id": "anking-endocrine-pathology-1748", "fuente": "anking", "tema": 5, "anki": "1462327814144", "q": "A tumor arising from pancreatic delta cells is called what?", "o": {"A": "Insulinoma", "B": "Somatostatinoma", "C": "VIPoma", "D": "Glucagonoma"}, "r": "B", "e": {"correcta": "Somatostatinoma arises from pancreatic delta cells, which normally secrete somatostatin to inhibit multiple GI and pancreatic hormones; excess somatostatin from the tumor decreases secretin, CCK, glucagon, insulin, and gastrin secretion, producing diabetes, gallstones, and steatorrhea.", "incorrectas": {"A": "Insulinoma arises from beta cells and causes hypoglycemia from insulin excess, the opposite functional cell type and clinical picture from the broadly inhibitory somatostatinoma.", "C": "VIPoma secretes vasoactive intestinal peptide, causing the WDHA syndrome of watery diarrhea and hypokalemia, and arises from a different cell population than the somatostatin-secreting delta cells.", "D": "Glucagonoma arises from alpha cells and causes hyperglycemia with necrolytic migratory erythema, a distinct tumor type from the delta-cell-derived somatostatinoma."}}}, {"id": "anking-endocrine-pathology-1749", "fuente": "anking", "tema": 5, "anki": "1462327827158", "q": "Somatostatinoma may present clinically with diabetes due to which mechanism?", "o": {"A": "Direct destruction of beta cells", "B": "Inhibition of insulin secretion", "C": "Excess cortisol production", "D": "Autoimmune insulin receptor blockade"}, "r": "B", "e": {"correcta": "Somatostatin potently inhibits insulin secretion from pancreatic beta cells (along with glucagon, gastrin, secretin, and CCK), so a somatostatin-secreting tumor suppresses endogenous insulin release, resulting in hyperglycemia and diabetes.", "incorrectas": {"A": "Somatostatinoma does not physically destroy beta cells; the hyperglycemia results from functional hormonal suppression of insulin secretion by excess somatostatin, not autoimmune or cytotoxic beta cell destruction as in type 1 diabetes.", "C": "Excess cortisol production describes Cushing syndrome, which can cause secondary diabetes through insulin resistance and increased gluconeogenesis, a different mechanism unrelated to somatostatin's inhibitory hormonal effects.", "D": "Autoimmune insulin receptor blockade describes a rare form of severe insulin resistance (type B insulin resistance), a distinct immune-mediated mechanism unrelated to the hormonal suppression caused by somatostatinoma."}}}, {"id": "anking-gastrointestinal-physiology-1750", "fuente": "anking", "tema": 39, "anki": "1462327847781", "q": "Which diagnostic test may be used to help confirm a diagnosis of Zollinger-Ellison syndrome?", "o": {"A": "Secretin stimulation test", "B": "Water deprivation test", "C": "Dexamethasone suppression test", "D": "TRH stimulation test"}, "r": "A", "e": {"correcta": "The secretin stimulation test exploits the paradoxical response of gastrinoma cells to secretin: whereas secretin normally inhibits gastrin release from healthy antral G cells, it paradoxically stimulates gastrin release from ectopic gastrinoma cells, so a rise in gastrin after secretin administration supports the diagnosis of Zollinger-Ellison syndrome.", "incorrectas": {"B": "The water deprivation test is used to evaluate diabetes insipidus by assessing the kidney's ability to concentrate urine in response to fluid restriction and ADH, unrelated to gastrin physiology or ZES.", "C": "The dexamethasone suppression test is used to evaluate for Cushing syndrome by assessing cortisol suppression, an entirely different hormonal axis from the gastrin-secretin interaction tested in ZES.", "D": "The TRH stimulation test evaluates thyrotroph and, historically, pituitary function (e.g., in acromegaly or hypothyroidism workups), not the gastrin response used to diagnose gastrinoma."}}}, {"id": "anking-gastrointestinal-physiology-1751", "fuente": "anking", "tema": 39, "anki": "1462327862046", "q": "In a patient with Zollinger-Ellison syndrome, what happens to gastrin levels after administration of secretin during the secretin stimulation test?", "o": {"A": "Gastrin falls to normal levels", "B": "Gastrin remains elevated (paradoxical rise)", "C": "Gastrin becomes undetectable", "D": "Gastrin oscillates unpredictably"}, "r": "B", "e": {"correcta": "In Zollinger-Ellison syndrome, gastrin levels remain elevated or paradoxically rise further after secretin administration, because ectopic gastrinoma cells express receptors that respond to secretin with increased gastrin release, unlike normal antral G cells which are suppressed by secretin.", "incorrectas": {"A": "A fall to normal levels would be the expected response in a healthy individual, where secretin normally suppresses gastric G-cell gastrin secretion; this normal suppression is precisely what is lost in ZES.", "C": "Gastrin does not become undetectable; the hallmark of the test is a paradoxical rise or persistence of elevated gastrin, not its disappearance.", "D": "The response in ZES is a reproducible, characteristic paradoxical increase rather than unpredictable oscillation, which is what makes the test diagnostically useful."}}}, {"id": "anking-endocrine-pathology-1752", "fuente": "anking", "tema": 5, "anki": "1462327872883", "q": "Zollinger-Ellison syndrome is caused by a gastrin-secreting tumor arising from where?", "o": {"A": "Pancreas or duodenum", "B": "Adrenal medulla", "C": "Anterior pituitary", "D": "Parathyroid gland"}, "r": "A", "e": {"correcta": "Zollinger-Ellison syndrome results from a gastrinoma, most commonly located in the pancreas or duodenum (the 'gastrinoma triangle'), which autonomously secretes gastrin and drives excessive gastric acid production, leading to recurrent and refractory peptic ulcers; it may also be associated with MEN 1.", "incorrectas": {"B": "The adrenal medulla is the site of pheochromocytoma, which secretes catecholamines causing episodic hypertension, not the gastrin-secreting tumor responsible for Zollinger-Ellison syndrome.", "C": "The anterior pituitary can harbor tumors secreting prolactin, GH, or ACTH among others, but it is not the origin of the gastrin-secreting tumors that define Zollinger-Ellison syndrome.", "D": "The parathyroid gland is the source of PTH-secreting adenomas seen in primary hyperparathyroidism, a component of MEN 1, but it is not the site of origin for gastrinomas themselves."}}}, {"id": "anking-gastrointestinal-pathology-1753", "fuente": "anking", "tema": 10, "anki": "1462327899426", "q": "A 55-year-old man undergoes resection of a small bowel mass. Biopsy shows nests of cells with prominent rosettes. What is the most common malignancy of the small intestine?", "o": {"A": "Adenocarcinoma", "B": "Carcinoid tumor (neuroendocrine cell origin)", "C": "Gastrointestinal stromal tumor", "D": "Lymphoma"}, "r": "B", "e": {"correcta": "Carcinoid tumors, arising from neuroendocrine cells of the gut, are the most common malignancy of the small intestine. Histologically they show nests of uniform cells often forming rosette-like structures, and they can secrete serotonin and other vasoactive peptides.", "incorrectas": {"A": "Adenocarcinoma is the most common malignancy of the large intestine (colon), not the small bowel, where it is comparatively rare.", "C": "Gastrointestinal stromal tumors arise from the interstitial cells of Cajal and are most common in the stomach; they do not form neuroendocrine rosettes and are not the leading small bowel malignancy.", "D": "Lymphoma can occur in the small intestine (e.g., associated with celiac disease) but is far less common than carcinoid tumor as a cause of small bowel malignancy."}}}, {"id": "anking-endocrine-pathology-1754", "fuente": "anking", "tema": 5, "anki": "1462327929517", "q": "Carcinoid syndrome (flushing, diarrhea, wheezing) typically only manifests once the carcinoid tumor metastasizes to which organ?", "o": {"A": "Lung", "B": "Liver", "C": "Spleen", "D": "Kidney"}, "r": "B", "e": {"correcta": "Carcinoid tumors confined to the GI tract have their serotonin secretion metabolized by the liver via first-pass metabolism, preventing systemic symptoms. Once the tumor metastasizes to the liver, serotonin bypasses hepatic degradation and is released directly into systemic circulation, producing carcinoid syndrome.", "incorrectas": {"A": "The lung does not perform first-pass metabolism of GI-derived serotonin; primary bronchial carcinoids can actually cause carcinoid syndrome without liver metastasis because they release serotonin directly into systemic circulation, bypassing the portal system.", "C": "The spleen has no role in metabolizing serotonin or in the first-pass clearance relevant to carcinoid syndrome pathophysiology.", "D": "The kidney does not perform the first-pass metabolism relevant here; it is the liver's degradation of serotonin (via monoamine oxidase) that normally prevents systemic symptoms."}}}, {"id": "anking-endocrine-pathology-1755", "fuente": "anking", "tema": 5, "anki": "1462327941682", "q": "A patient with metastatic carcinoid tumor presents with episodic bronchospasm and recurrent watery diarrhea. Which additional finding is classically part of this triad (carcinoid syndrome)?", "o": {"A": "Cutaneous flushing", "B": "Peripheral edema", "C": "Jaundice", "D": "Hyperpigmentation"}, "r": "A", "e": {"correcta": "Carcinoid syndrome classically presents with the triad of flushing, diarrhea, and wheezing/bronchospasm (mnemonic 'Be FDR'), resulting from systemic release of serotonin and other vasoactive substances (histamine, bradykinin) from the tumor.", "incorrectas": {"B": "Peripheral edema is not a classic component of carcinoid syndrome; right-sided heart failure from carcinoid heart disease may eventually cause edema, but it is not part of the core triad.", "C": "Jaundice is not a typical feature of carcinoid syndrome unless there is extensive hepatic replacement by metastases, but it is not one of the hallmark triad symptoms.", "D": "Hyperpigmentation is a feature of primary adrenal insufficiency (Addison disease) due to elevated ACTH/MSH, not of carcinoid syndrome."}}}, {"id": "anking-cardiovascular-pathology-1756", "fuente": "anking", "tema": 15, "anki": "1462327945336", "q": "Carcinoid heart disease from chronic serotonin exposure classically causes right-sided valvular fibrosis leading to regurgitation of which valve?", "o": {"A": "Mitral valve", "B": "Aortic valve", "C": "Tricuspid valve", "D": "Pulmonary valve"}, "r": "C", "e": {"correcta": "Carcinoid heart disease causes fibrous plaque deposition on the endocardium of right-sided heart valves due to prolonged serotonin exposure, leading to tricuspid regurgitation and pulmonic valve stenosis. The right side is affected because it is the first to receive the high concentrations of serotonin-laden venous blood before pulmonary metabolism can degrade it.", "incorrectas": {"A": "The mitral valve is on the left side of the heart and is generally spared in carcinoid heart disease, since pulmonary metabolism of serotonin (via MAO) protects the left heart from the high circulating levels seen on the right.", "B": "The aortic valve is also a left-sided structure and is typically unaffected for the same reason the mitral valve is spared: serotonin is inactivated in the lungs before reaching the left heart.", "D": "The pulmonary valve is affected in carcinoid heart disease, but the lesion there is characteristically stenosis rather than regurgitation, whereas the tricuspid valve develops regurgitation."}}}, {"id": "anking-cardiovascular-pathology-1757", "fuente": "anking", "tema": 15, "anki": "1462327957226", "q": "In a patient with carcinoid heart disease, why are left-sided cardiac valvular lesions typically absent?", "o": {"A": "The left heart lacks serotonin receptors", "B": "Serotonin is converted to 5-HIAA by pulmonary MAO before reaching the left heart", "C": "The left heart has a thicker endocardium resistant to fibrosis", "D": "Serotonin is degraded by hepatic first-pass metabolism before reaching the left heart"}, "r": "B", "e": {"correcta": "Blood carrying serotonin from the right heart passes through the pulmonary circulation, where monoamine oxidase (MAO) in the lungs converts serotonin (5-HT) to its inactive metabolite 5-HIAA. This detoxification protects the left-sided valves from the fibrogenic effects of serotonin that damage the right-sided valves.", "incorrectas": {"A": "Serotonin receptor distribution is not the limiting factor; both sides of the heart have serotonin receptors, but only the right side is exposed to high concentrations of active serotonin before pulmonary clearance.", "C": "There is no described difference in endocardial thickness or intrinsic fibrosis resistance between the right and left heart; the protection is due to serotonin inactivation in the lungs, not structural differences.", "D": "Hepatic first-pass metabolism explains why non-metastatic carcinoid tumors do not cause systemic symptoms at all, but once serotonin is in systemic (right heart) circulation, it is the pulmonary MAO metabolism, not hepatic metabolism, that protects the left heart."}}}, {"id": "anking-gastrointestinal-pathology-1758", "fuente": "anking", "tema": 10, "anki": "1462327963475", "q": "A pancreatic islet cell tumor arising from non-α, non-β, non-δ cells secretes a hormone causing watery diarrhea, hypokalemia, and achlorhydria (WDHA syndrome). What is this tumor called?", "o": {"A": "Glucagonoma", "B": "Somatostatinoma", "C": "Gastrinoma", "D": "VIPoma"}, "r": "D", "e": {"correcta": "A VIPoma is a pancreatic islet cell tumor that secretes vasoactive intestinal peptide (VIP), causing watery diarrhea, hypokalemia, and achlorhydria — collectively known as WDHA syndrome. VIP stimulates intestinal chloride and fluid secretion while inhibiting gastric acid production.", "incorrectas": {"A": "Glucagonoma arises from pancreatic α-cells and secretes glucagon, causing hyperglycemia, necrolytic migratory erythema, and weight loss, not the WDHA triad.", "B": "Somatostatinoma arises from δ-cells and causes diabetes, cholelithiasis, and steatorrhea due to inhibition of insulin, cholecystokinin, and pancreatic enzyme secretion, distinct from VIPoma's presentation.", "C": "Gastrinoma secretes gastrin and causes Zollinger-Ellison syndrome with recurrent peptic ulcers and increased (not decreased) gastric acid, the opposite of the achlorhydria seen in VIPoma."}}}, {"id": "anking-gastrointestinal-pathology-1759", "fuente": "anking", "tema": 10, "anki": "1462327969304", "q": "A patient with a VIPoma presents with large-volume watery diarrhea. Which additional laboratory/clinical findings are classically seen, completing the 'WDHA' syndrome?", "o": {"A": "Hyperkalemia and increased gastric acid", "B": "Hypokalemia and achlorhydria", "C": "Hyperkalemia and achlorhydria", "D": "Hypokalemia and increased gastric acid"}, "r": "B", "e": {"correcta": "VIPoma classically causes WDHA syndrome: Watery Diarrhea, Hypokalemia (from massive stool potassium losses), and Achlorhydria (VIP inhibits gastric acid secretion). The severe secretory diarrhea drives both the electrolyte loss and the inhibited acid production.", "incorrectas": {"A": "Hyperkalemia does not occur; the massive diarrhea causes potassium loss (hypokalemia), and VIP suppresses rather than increases gastric acid secretion.", "C": "Hyperkalemia is incorrect for the same reason as above — the secretory diarrhea depletes potassium, causing hypokalemia rather than hyperkalemia, even though achlorhydria is correctly matched.", "D": "Gastric acid is decreased (achlorhydria), not increased, because VIP inhibits parietal cell acid secretion; this distinguishes VIPoma from gastrin-secreting tumors, which increase acid."}}}, {"id": "anking-endocrine-pathology-1760", "fuente": "anking", "tema": 5, "anki": "1462377691686", "q": "Cushing syndrome is fundamentally defined by a chronic elevation of which hormone?", "o": {"A": "Aldosterone", "B": "Cortisol", "C": "ACTH", "D": "Growth hormone"}, "r": "B", "e": {"correcta": "Cushing syndrome refers broadly to any condition resulting in chronically elevated serum cortisol, regardless of the underlying cause (exogenous steroids, pituitary adenoma, adrenal tumor, or ectopic ACTH). It is the excess cortisol itself that produces the clinical features (central obesity, hyperglycemia, hypertension, immunosuppression, and skin changes).", "incorrectas": {"A": "Aldosterone excess defines hyperaldosteronism (Conn syndrome), which presents with hypertension and hypokalemia but not the classic cortisol-driven features of Cushing syndrome such as central obesity, striae, and hyperglycemia.", "C": "ACTH is elevated only in ACTH-dependent causes of Cushing syndrome (pituitary adenoma or ectopic secretion); it is suppressed in ACTH-independent causes like exogenous steroids or adrenal tumors, so ACTH elevation is not the defining feature of the syndrome itself.", "D": "Growth hormone excess causes acromegaly (or gigantism in children), a distinct endocrine disorder with different manifestations such as coarsened facial features and organomegaly, unrelated to cortisol excess."}}}, {"id": "anking-endocrine-pathology-1761", "fuente": "anking", "tema": 5, "anki": "1462380546437", "q": "The term 'Cushing disease' refers specifically to which cause of hypercortisolism?", "o": {"A": "Adrenal adenoma secreting cortisol", "B": "Exogenous glucocorticoid administration", "C": "ACTH-secreting pituitary adenoma", "D": "Ectopic ACTH secretion from small cell lung cancer"}, "r": "C", "e": {"correcta": "Cushing disease is a specific subtype of Cushing syndrome caused by an ACTH-secreting pituitary adenoma, which drives bilateral adrenal hyperplasia and cortisol overproduction. The term 'disease' is reserved for this pituitary-driven etiology, distinguishing it from the broader term 'syndrome,' which encompasses all causes of hypercortisolism.", "incorrectas": {"A": "A cortisol-secreting adrenal adenoma causes ACTH-independent Cushing syndrome, not Cushing disease; ACTH would be suppressed in this scenario due to negative feedback on the pituitary.", "B": "Exogenous glucocorticoid use is the most common cause of Cushing syndrome overall but is specifically termed iatrogenic Cushing syndrome, not Cushing disease, and also suppresses endogenous ACTH.", "D": "Ectopic ACTH secretion (e.g., from small cell lung carcinoma) causes ACTH-dependent Cushing syndrome but is classified separately from Cushing disease, which is reserved specifically for pituitary-origin ACTH excess."}}}, {"id": "anking-endocrine-pathology-1762", "fuente": "anking", "tema": 5, "anki": "1462380557261", "q": "What is the most common overall cause of Cushing syndrome?", "o": {"A": "Ectopic ACTH secretion", "B": "Adrenal adenoma", "C": "Exogenous glucocorticoids", "D": "Cushing disease (pituitary adenoma)"}, "r": "C", "e": {"correcta": "Exogenous (iatrogenic) glucocorticoid administration, such as prednisone used for autoimmune or inflammatory conditions, is the most common cause of Cushing syndrome overall. This is an important distinction from endogenous causes, since the treatment is simply tapering the medication rather than surgery.", "incorrectas": {"B": "Adrenal adenoma is an endogenous cause of Cushing syndrome but is far less common than exogenous steroid use as an overall cause.", "D": "Cushing disease (an ACTH-secreting pituitary adenoma) is the most common endogenous cause of Cushing syndrome, but exogenous steroids outnumber all endogenous causes combined.", "A": "Ectopic ACTH secretion, most often from small cell lung carcinoma, is a relatively rare cause of Cushing syndrome compared to the ubiquity of therapeutic glucocorticoid use."}}}, {"id": "anking-endocrine-pathology-1763", "fuente": "anking", "tema": 5, "anki": "1462380573238", "q": "Among endogenous causes only, what is the most common cause of Cushing syndrome?", "o": {"A": "Ectopic ACTH secretion from small cell lung cancer", "B": "Cushing disease (ACTH-secreting pituitary adenoma)", "C": "Primary adrenal adenoma", "D": "Bilateral adrenal hyperplasia (non-ACTH driven)"}, "r": "B", "e": {"correcta": "When exogenous steroid use is excluded, Cushing disease — a pituitary adenoma secreting ACTH — is the most common endogenous cause of Cushing syndrome. The excess ACTH drives bilateral adrenal hyperplasia and cortisol overproduction.", "incorrectas": {"A": "Ectopic ACTH secretion (classically from small cell lung carcinoma) is an important but less common endogenous cause compared to a pituitary corticotroph adenoma.", "C": "Primary adrenal adenoma is an ACTH-independent cause of Cushing syndrome, and it occurs less frequently than pituitary-driven Cushing disease.", "D": "Bilateral adrenal hyperplasia not driven by pituitary ACTH is a rare cause of Cushing syndrome and is much less common than an ACTH-secreting pituitary adenoma."}}}, {"id": "anking-endocrine-pathology-1764", "fuente": "anking", "tema": 5, "anki": "1462380580332", "q": "A patient with Cushing syndrome develops proximal muscle weakness with disproportionately thin limbs alongside central obesity. What is the mechanism underlying the thin extremities?", "o": {"A": "Decreased protein synthesis and increased lipolysis/proteolysis in peripheral tissue", "B": "Selective fat redistribution without muscle involvement", "C": "Increased peripheral insulin sensitivity", "D": "Decreased cortisol receptor density in muscle"}, "r": "A", "e": {"correcta": "Excess cortisol promotes catabolism of peripheral muscle and fat (proteolysis and lipolysis) while simultaneously promoting central fat deposition, producing the classic 'thin extremities with truncal obesity' appearance along with proximal muscle weakness from muscle wasting.", "incorrectas": {"B": "Fat redistribution alone does not explain the muscle weakness; cortisol actively catabolizes skeletal muscle protein, contributing directly to the thin, weak extremities, not just fat shifting.", "C": "Cortisol excess actually causes insulin resistance and hyperglycemia (steroid diabetes), not increased peripheral insulin sensitivity.", "D": "Decreased cortisol receptor density is not the mechanism; rather it is cortisol's direct catabolic action via its receptors that drives muscle protein breakdown."}}}, {"id": "anking-endocrine-pathology-1765", "fuente": "anking", "tema": 5, "anki": "1462380649800", "q": "Patients with Cushing syndrome are prone to infections due to immune suppression. What is the mechanism of this cortisol-mediated immunosuppression?", "o": {"A": "Increased IL-2 and histamine release", "B": "Inhibition of phospholipase A2, IL-2, and histamine", "C": "Upregulation of B-cell proliferation", "D": "Increased neutrophil chemotaxis"}, "r": "B", "e": {"correcta": "Cortisol suppresses the immune response by inhibiting phospholipase A2 (reducing arachidonic acid-derived inflammatory mediators), decreasing IL-2 production (impairing T-cell proliferation), and decreasing histamine release, collectively blunting inflammatory and immune responses and predisposing to infection.", "incorrectas": {"A": "Cortisol decreases, not increases, IL-2 and histamine release; this is precisely why hypercortisolism causes immunosuppression rather than heightened immune activity.", "C": "Cortisol does not upregulate B-cell proliferation; excess glucocorticoids generally suppress lymphocyte function and can cause lymphopenia.", "D": "Cortisol actually causes neutrophilia by demargination and decreased neutrophil adhesion, but it impairs neutrophil function and chemotaxis rather than enhancing it, contributing to increased infection risk despite higher circulating neutrophil counts."}}}, {"id": "anking-endocrine-pathology-1766", "fuente": "anking", "tema": 5, "anki": "1462380658695", "q": "Which laboratory test is used as a positive screening result supporting a diagnosis of Cushing syndrome?", "o": {"A": "Decreased 24-hour urine free cortisol", "B": "Increased 24-hour urine free cortisol", "C": "Decreased plasma renin activity", "D": "Increased serum potassium"}, "r": "B", "e": {"correcta": "An elevated 24-hour urine free cortisol level reflects excess cortisol production over a full day and is one of the standard initial screening tests for Cushing syndrome, along with the low-dose dexamethasone suppression test and late-night salivary cortisol.", "incorrectas": {"A": "Decreased urine free cortisol would be inconsistent with hypercortisolism; Cushing syndrome screening relies on demonstrating an increase in cortisol production, not a decrease.", "C": "Plasma renin activity is relevant to the workup of hyperaldosteronism, not Cushing syndrome, and is not part of the standard screening panel for hypercortisolism.", "D": "Cushing syndrome classically causes hypokalemia (due to cortisol's mineralocorticoid-like activity at high concentrations), not hyperkalemia, so increased potassium is not an expected or diagnostic finding."}}}, {"id": "anking-endocrine-pathology-1767", "fuente": "anking", "tema": 5, "anki": "1462380664504", "q": "Besides 24-hour urinary free cortisol, which timed cortisol measurement is used as a screening test for Cushing syndrome because normal diurnal suppression is lost?", "o": {"A": "Morning plasma ACTH", "B": "Midnight salivary cortisol", "C": "Random serum cortisol", "D": "Fasting morning glucose"}, "r": "B", "e": {"correcta": "Cortisol normally follows a diurnal rhythm, peaking in the morning and reaching its nadir at midnight. In Cushing syndrome, this normal suppression is lost, so an elevated midnight salivary cortisol is a sensitive screening test for autonomous cortisol overproduction.", "incorrectas": {"A": "Morning plasma ACTH helps distinguish ACTH-dependent from ACTH-independent causes once Cushing syndrome is confirmed, but it is not itself a first-line screening test for the presence of hypercortisolism.", "C": "A single random serum cortisol level is unreliable for screening because cortisol normally fluctuates throughout the day, making a specifically timed midnight sample more useful.", "D": "Fasting morning glucose may be elevated in Cushing syndrome due to cortisol's hyperglycemic effects, but it is nonspecific and not one of the standard diagnostic screening tests for hypercortisolism."}}}, {"id": "anking-endocrine-pathology-1768", "fuente": "anking", "tema": 5, "anki": "1462380676531", "q": "In the overnight low-dose (1 mg) dexamethasone suppression test, what result supports a diagnosis of Cushing syndrome?", "o": {"A": "Cortisol suppression below normal", "B": "Normal suppression of cortisol", "C": "Failure to suppress cortisol", "D": "Paradoxical rise in ACTH only"}, "r": "C", "e": {"correcta": "In a healthy individual, low-dose dexamethasone suppresses ACTH and thus cortisol via negative feedback on the pituitary. In Cushing syndrome, cortisol production is autonomous (from a tumor or exogenous source) and fails to suppress despite the exogenous glucocorticoid, confirming the diagnosis.", "incorrectas": {"A": "Cortisol suppression below normal describes the expected, healthy response and would argue against Cushing syndrome, not support it.", "B": "Normal suppression of cortisol indicates an intact hypothalamic-pituitary-adrenal feedback axis and would rule out Cushing syndrome rather than confirm it.", "D": "The low-dose test evaluates cortisol suppression, not an isolated ACTH rise; a paradoxical ACTH rise is not the described diagnostic criterion for this particular screening test."}}}, {"id": "anking-endocrine-pathology-1769", "fuente": "anking", "tema": 5, "anki": "1462380707702", "q": "In a patient with Cushing syndrome caused by long-term exogenous corticosteroid use, what is the expected state of the adrenal glands?", "o": {"A": "Hyperplasia of both adrenal glands", "B": "Atrophy of both adrenal glands", "C": "Hyperplasia of one gland with atrophy of the other", "D": "Normal-appearing adrenal glands"}, "r": "B", "e": {"correcta": "Exogenous glucocorticoids suppress hypothalamic CRH and pituitary ACTH via negative feedback. Because both adrenal glands depend on ACTH stimulation to maintain their cortical mass, chronic ACTH suppression leads to bilateral adrenal atrophy.", "incorrectas": {"A": "Bilateral adrenal hyperplasia occurs when ACTH is elevated (as in Cushing disease or ectopic ACTH secretion), which is the opposite of what happens with exogenous steroids, where ACTH is suppressed.", "C": "Unilateral hyperplasia with contralateral atrophy is the pattern seen with a unilateral cortisol-secreting adrenal adenoma or carcinoma, not with exogenous steroid administration, which affects both glands equally via ACTH suppression.", "D": "The adrenal glands do not remain normal; chronic loss of ACTH trophic support causes measurable atrophy of both glands over time."}}}, {"id": "anking-endocrine-pathology-1770", "fuente": "anking", "tema": 5, "anki": "1462380756236", "q": "A patient with Cushing syndrome due to a primary adrenal adenoma has suppressed ACTH. What is the expected state of the adrenal glands?", "o": {"A": "Bilateral hyperplasia", "B": "Bilateral atrophy", "C": "Atrophy of the uninvolved gland with hyperplasia of the involved gland", "D": "Hyperplasia of the uninvolved gland with atrophy of the involved gland"}, "r": "C", "e": {"correcta": "A cortisol-secreting adrenal adenoma (or carcinoma/hyperplasia) autonomously overproduces cortisol, suppressing ACTH via negative feedback. The involved gland itself is hyperplastic/enlarged due to the tumor, while the contralateral, ACTH-deprived gland atrophies from lack of trophic stimulation, and can even cause a pseudohyperaldosteronism picture.", "incorrectas": {"A": "Bilateral hyperplasia occurs with ACTH-dependent causes (Cushing disease or ectopic ACTH), where elevated ACTH stimulates both glands, not with an autonomous adrenal tumor that suppresses ACTH.", "B": "Bilateral atrophy occurs with exogenous steroid administration, which suppresses ACTH to both normal adrenal glands equally; here, one gland harbors the tumor itself and is not atrophied.", "D": "This describes the reverse of the actual pattern — the tumor-bearing gland is enlarged/hyperplastic due to the neoplasm, while the uninvolved gland atrophies from ACTH suppression."}}}, {"id": "anking-endocrine-pathology-1771", "fuente": "anking", "tema": 5, "anki": "1462380757677", "q": "In Cushing disease (an ACTH-secreting pituitary adenoma), what is the expected state of the adrenal glands?", "o": {"A": "Atrophy of both adrenal glands", "B": "Hyperplasia of both adrenal glands", "C": "Hyperplasia of only the gland ipsilateral to the adenoma", "D": "No change in adrenal gland size"}, "r": "B", "e": {"correcta": "In Cushing disease, the pituitary adenoma continuously secretes ACTH, which stimulates both adrenal glands symmetrically, producing bilateral adrenal hyperplasia and increased cortisol output.", "incorrectas": {"A": "Bilateral atrophy occurs when ACTH is suppressed, such as with exogenous steroid use, which is the opposite of the ACTH excess driving Cushing disease.", "C": "The adrenal glands have no direct anatomic laterality relationship to a pituitary tumor; ACTH acts systemically via the bloodstream to stimulate both adrenal glands equally, not selectively on one side.", "D": "The adrenal glands do change size — chronic ACTH excess causes measurable bilateral hyperplasia rather than remaining unchanged."}}}, {"id": "anking-respiratory-pathology-1772", "fuente": "anking", "tema": 17, "anki": "1462380769945", "q": "A 68-year-old smoker with a central lung mass develops Cushing syndrome from paraneoplastic ectopic ACTH secretion. What is the expected state of the adrenal glands?", "o": {"A": "Bilateral atrophy", "B": "Bilateral hyperplasia", "C": "Unilateral hyperplasia with contralateral atrophy", "D": "Adrenal glands remain unaffected"}, "r": "B", "e": {"correcta": "Ectopic ACTH secretion, classically from small cell lung carcinoma or bronchial carcinoids, stimulates both adrenal glands via circulating ACTH just as pituitary-derived ACTH would, resulting in bilateral adrenal hyperplasia.", "incorrectas": {"A": "Bilateral atrophy occurs with ACTH suppression (exogenous steroids), not with the ACTH excess seen in ectopic ACTH secretion.", "C": "A unilateral hyperplasia/atrophy pattern is seen with a primary adrenal tumor that autonomously secretes cortisol and suppresses ACTH; ectopic ACTH instead raises ACTH systemically and affects both glands.", "D": "The adrenal glands are directly affected — chronically elevated circulating ACTH drives measurable bilateral hyperplasia, not an unchanged gland state."}}}, {"id": "anking-respiratory-pathology-1773", "fuente": "anking", "tema": 17, "anki": "1462380781251", "q": "What is the most common tumor responsible for ectopic ACTH secretion causing Cushing syndrome?", "o": {"A": "Bronchial carcinoid tumor", "B": "Small cell lung carcinoma", "C": "Medullary thyroid carcinoma", "D": "Pancreatic neuroendocrine tumor"}, "r": "B", "e": {"correcta": "Small cell lung carcinoma is the most common cause of ectopic ACTH secretion, a paraneoplastic phenomenon that produces ACTH-dependent Cushing syndrome with bilateral adrenal hyperplasia, independent of pituitary regulation.", "incorrectas": {"A": "Bronchial carcinoid tumors can also secrete ectopic ACTH and are a recognized cause, but they are less common than small cell lung carcinoma as the culprit.", "C": "Medullary thyroid carcinoma is associated with ectopic ACTH secretion in some cases (and with calcitonin secretion always), but it is a much rarer cause than small cell lung cancer.", "D": "Pancreatic neuroendocrine tumors can rarely secrete ectopic ACTH, but this is far less common than the classic association with small cell lung carcinoma."}}}, {"id": "anking-endocrine-pathology-1774", "fuente": "anking", "tema": 5, "anki": "1462380786286", "q": "A patient is diagnosed with Cushing syndrome, and laboratory testing reveals a suppressed ACTH level. Which two conditions comprise the primary differential diagnosis?", "o": {"A": "Cushing disease and ectopic ACTH secretion", "B": "Exogenous glucocorticoids and adrenal adenoma/carcinoma/hyperplasia", "C": "Pituitary adenoma and small cell lung cancer", "D": "Primary hyperaldosteronism and pheochromocytoma"}, "r": "B", "e": {"correcta": "A low ACTH in the setting of hypercortisolism indicates an ACTH-independent process: either exogenous glucocorticoid administration (suppressing the HPA axis) or an autonomous adrenal source (adenoma, carcinoma, or nodular hyperplasia) that produces cortisol without needing ACTH stimulation, itself suppressing pituitary ACTH via feedback.", "incorrectas": {"A": "Cushing disease and ectopic ACTH secretion are both ACTH-dependent causes and would present with elevated, not suppressed, ACTH levels.", "C": "A pituitary adenoma (Cushing disease) and small cell lung cancer (ectopic ACTH) both drive ACTH elevation, making them the differential for high-ACTH Cushing syndrome, not the suppressed-ACTH scenario asked about here.", "D": "Primary hyperaldosteronism and pheochromocytoma are distinct adrenal conditions related to aldosterone and catecholamine excess respectively, not part of the Cushing syndrome ACTH differential."}}}, {"id": "anking-endocrine-pathology-1775", "fuente": "anking", "tema": 5, "anki": "1462380873616", "q": "A patient with Cushing syndrome has an elevated ACTH level. Which two conditions form the primary differential diagnosis for this ACTH-dependent presentation?", "o": {"A": "Exogenous glucocorticoids and adrenal adenoma", "B": "Cushing disease and ectopic ACTH secretion", "C": "Adrenal carcinoma and adrenal hyperplasia", "D": "Primary hyperaldosteronism and CAH"}, "r": "B", "e": {"correcta": "Elevated ACTH in Cushing syndrome indicates an ACTH-dependent cause: either Cushing disease (an ACTH-secreting pituitary adenoma) or ectopic ACTH secretion (classically from small cell lung carcinoma). Distinguishing between these two requires further testing such as the high-dose dexamethasone suppression test or CRH stimulation test.", "incorrectas": {"A": "Exogenous glucocorticoids and adrenal adenoma both suppress ACTH via negative feedback (ACTH-independent causes), which contradicts the elevated ACTH described in this scenario.", "C": "Adrenal carcinoma and adrenal hyperplasia (when primary/autonomous) are ACTH-independent causes of Cushing syndrome and would show suppressed, not elevated, ACTH.", "D": "Primary hyperaldosteronism and congenital adrenal hyperplasia are separate endocrine disorders not part of the ACTH-dependent Cushing syndrome differential."}}}, {"id": "anking-endocrine-pathology-1776", "fuente": "anking", "tema": 5, "anki": "1462380876557", "q": "In a patient with ACTH-dependent Cushing syndrome, adequate cortisol suppression occurs following a high-dose (8 mg) dexamethasone suppression test. What is the most likely underlying cause?", "o": {"A": "Ectopic ACTH secretion", "B": "Adrenal adenoma", "C": "Cushing disease", "D": "Exogenous glucocorticoid use"}, "r": "C", "e": {"correcta": "Pituitary corticotroph adenomas in Cushing disease retain some responsiveness to negative feedback, though at a higher threshold than normal. A high dose of dexamethasone is sufficient to suppress ACTH and subsequently cortisol, supporting a pituitary origin.", "incorrectas": {"A": "Ectopic ACTH-secreting tumors (e.g., small cell lung carcinoma) are typically completely unresponsive to negative feedback, even at high-dose dexamethasone, so suppression argues against this diagnosis.", "B": "An adrenal adenoma is an ACTH-independent cause and would already show a suppressed ACTH at baseline, making it inconsistent with the ACTH-dependent scenario described in this question.", "D": "Exogenous glucocorticoid use is also an ACTH-independent cause with baseline ACTH suppression, not a condition being evaluated by the high-dose dexamethasone test in ACTH-dependent Cushing syndrome."}}}, {"id": "anking-endocrine-pathology-1777", "fuente": "anking", "tema": 5, "anki": "1462380908389", "q": "In a patient with ACTH-dependent Cushing syndrome, cortisol fails to suppress following a high-dose (8 mg) dexamethasone suppression test. What is the most likely cause?", "o": {"A": "Cushing disease", "B": "Ectopic ACTH secretion", "C": "Adrenal adenoma", "D": "Exogenous glucocorticoid use"}, "r": "B", "e": {"correcta": "Ectopic ACTH-secreting tumors, such as small cell lung carcinoma, are autonomous and lack the corticotroph-like feedback receptors present in pituitary adenomas, so they fail to respond even to high-dose dexamethasone, distinguishing them from Cushing disease.", "incorrectas": {"A": "Cushing disease pituitary adenomas typically retain partial feedback sensitivity and do suppress with high-dose dexamethasone, which is the opposite of the lack of suppression described here.", "C": "Adrenal adenoma is an ACTH-independent cause with baseline suppressed ACTH, not a diagnosis under consideration in this ACTH-dependent scenario being tested with high-dose dexamethasone.", "D": "Exogenous glucocorticoid use is ACTH-independent and would present with low baseline ACTH, not the ACTH-dependent picture being evaluated by this test."}}}, {"id": "anking-endocrine-pathology-1778", "fuente": "anking", "tema": 5, "anki": "1462380929386", "q": "In a patient with ACTH-dependent Cushing syndrome, ACTH secretion increases following a CRH stimulation test. What is the most likely cause?", "o": {"A": "Ectopic ACTH secretion", "B": "Cushing disease", "C": "Adrenal carcinoma", "D": "Exogenous glucocorticoid use"}, "r": "B", "e": {"correcta": "Pituitary corticotroph adenomas in Cushing disease retain CRH receptors and respond to exogenous CRH administration with a further rise in ACTH, unlike ectopic sources which do not have this responsiveness, helping localize the source to the pituitary.", "incorrectas": {"A": "Ectopic ACTH-secreting tumors generally lack functional CRH receptors and therefore do not increase ACTH secretion in response to CRH stimulation, which is why this response points away from an ectopic source.", "C": "Adrenal carcinoma is an ACTH-independent cause with suppressed ACTH at baseline and is not evaluated using the CRH stimulation test, which is used to differentiate ACTH-dependent causes.", "D": "Exogenous glucocorticoid use suppresses ACTH via negative feedback and is an ACTH-independent cause, not relevant to the CRH stimulation test used for ACTH-dependent Cushing syndrome."}}}, {"id": "anking-endocrine-pathology-1779", "fuente": "anking", "tema": 5, "anki": "1462380934501", "q": "In a patient with ACTH-dependent Cushing syndrome, ACTH secretion does NOT increase following a CRH stimulation test. What is the most likely underlying cause?", "o": {"A": "Cushing disease", "B": "Ectopic ACTH secretion", "C": "Adrenal adenoma", "D": "Exogenous glucocorticoid use"}, "r": "B", "e": {"correcta": "Ectopic ACTH-secreting tumors, such as small cell lung carcinoma, do not respond to CRH stimulation because they lack the normal CRH receptor-mediated regulation present in pituitary corticotrophs, so ACTH fails to rise, helping distinguish it from Cushing disease.", "incorrectas": {"A": "Cushing disease pituitary adenomas typically show an increase in ACTH after CRH stimulation because they retain CRH responsiveness, the opposite of the lack of response described here.", "C": "Adrenal adenoma is an ACTH-independent cause with baseline suppressed ACTH and is not the diagnosis being distinguished by the CRH stimulation test, which applies to ACTH-dependent causes.", "D": "Exogenous glucocorticoid use is ACTH-independent, presenting with suppressed baseline ACTH, and is not relevant to this test used to differentiate ACTH-dependent etiologies."}}}, {"id": "anking-endocrine-pathology-1780", "fuente": "anking", "tema": 5, "anki": "1462380947005", "q": "Which two diagnostic tests are used to differentiate Cushing disease from ectopic (paraneoplastic) ACTH secretion in a patient with ACTH-dependent Cushing syndrome?", "o": {"A": "Low-dose dexamethasone suppression test and 24-hour urine cortisol", "B": "High-dose dexamethasone suppression test and CRH stimulation test", "C": "Plasma renin activity and aldosterone-to-renin ratio", "D": "Midnight salivary cortisol and fasting glucose"}, "r": "B", "e": {"correcta": "The high-dose dexamethasone suppression test and the CRH stimulation test both exploit residual feedback responsiveness in pituitary corticotroph adenomas (Cushing disease), which suppress/respond appropriately, whereas ectopic ACTH-secreting tumors are autonomous and fail to respond to either test.", "incorrectas": {"A": "The low-dose dexamethasone test and 24-hour urine cortisol are used to screen for and confirm the presence of Cushing syndrome in general, not to distinguish between its ACTH-dependent causes.", "C": "Plasma renin activity and aldosterone-to-renin ratio are used in the workup of hyperaldosteronism, an entirely separate condition from Cushing syndrome.", "D": "Midnight salivary cortisol and fasting glucose are useful screening tools for hypercortisolism generally but do not distinguish pituitary from ectopic ACTH sources."}}}, {"id": "anking-endocrine-pathology-1781", "fuente": "anking", "tema": 5, "anki": "1462381626652", "q": "What is the most common cause of primary hyperaldosteronism?", "o": {"A": "Aldosterone-secreting adrenal adenoma (Conn syndrome)", "B": "Adrenal carcinoma", "C": "Bilateral adrenal hyperplasia", "D": "Renal artery stenosis"}, "r": "C", "e": {"correcta": "Recent evidence indicates that bilateral idiopathic adrenal hyperplasia, rather than a solitary aldosterone-secreting adenoma (Conn syndrome), is now recognized as the most common cause of primary hyperaldosteronism, both presenting with hypertension and hypokalemia from autonomous aldosterone excess.", "incorrectas": {"A": "An aldosterone-secreting adenoma (Conn syndrome) is a classic and important cause of primary hyperaldosteronism, but current data show it is actually less common than bilateral adrenal hyperplasia.", "B": "Adrenal carcinoma can rarely secrete aldosterone but is a much less common cause of primary hyperaldosteronism than either hyperplasia or adenoma.", "D": "Renal artery stenosis causes secondary hyperaldosteronism by activating the renin-angiotensin system due to decreased renal perfusion, which is a distinct category from primary (adrenal-autonomous) hyperaldosteronism."}}}, {"id": "anking-endocrine-physiology-1782", "fuente": "anking", "tema": 23, "anki": "1462383708003", "q": "Congenital adrenal hyperplasia results from a deficiency in one of the enzymes required for cortisol synthesis, producing what change in adrenal gland size?", "o": {"A": "Adrenal hyperplasia", "B": "Adrenal atrophy", "C": "No change in gland size", "D": "Unilateral adrenal atrophy"}, "r": "A", "e": {"correcta": "In congenital adrenal hyperplasia, an enzyme deficiency (most commonly 21-hydroxylase) impairs cortisol synthesis. The resulting drop in cortisol removes negative feedback on the pituitary, causing increased ACTH secretion, which chronically stimulates and enlarges the adrenal cortex, producing bilateral adrenal hyperplasia.", "incorrectas": {"B": "Adrenal atrophy would occur with excess negative feedback (as with exogenous steroids suppressing ACTH), which is the opposite of what happens here — the low cortisol removes feedback inhibition and increases ACTH drive to the adrenal glands.", "C": "The adrenal glands are not unaffected; chronically elevated ACTH from loss of cortisol feedback produces measurable, often marked, hyperplasia.", "D": "The enzyme deficiency is a systemic biochemical defect affecting both adrenal glands equally, not a unilateral process, so unilateral atrophy does not fit the pathophysiology."}}}, {"id": "anking-endocrine-physiology-1783", "fuente": "anking", "tema": 23, "anki": "1462383833553", "q": "In congenital adrenal hyperplasia, decreased synthesis of which hormone leads to a compensatory increase in ACTH via loss of negative feedback?", "o": {"A": "Aldosterone", "B": "Cortisol", "C": "DHEA", "D": "Testosterone"}, "r": "B", "e": {"correcta": "The enzyme defects in congenital adrenal hyperplasia impair cortisol synthesis. Because cortisol normally provides negative feedback on the hypothalamus and pituitary, decreased cortisol removes this inhibition, causing increased CRH and ACTH secretion, which in turn drives adrenal hyperplasia and shunts precursors toward androgen synthesis.", "incorrectas": {"A": "Aldosterone deficiency (seen in 21-hydroxylase deficiency) contributes to the salt-wasting phenotype but is not the hormone whose loss directly triggers the ACTH feedback loop; that role belongs to cortisol.", "C": "DHEA is an adrenal androgen precursor that is often increased (not decreased) in congenital adrenal hyperplasia due to shunting of steroid precursors, rather than being the hormone driving the ACTH feedback response.", "D": "Testosterone (and other androgens) is typically increased due to precursor shunting in congenital adrenal hyperplasia, not decreased, and it is not the hormone responsible for regulating pituitary ACTH feedback."}}}, {"id": "anking-endocrine-physiology-1784", "fuente": "anking", "tema": 23, "anki": "1462383836128", "q": "Congenital adrenal hyperplasia, due to an inherited enzyme deficiency, characteristically affects which adrenal gland(s)?", "o": {"A": "The left gland only", "B": "The right gland only", "C": "Both adrenal glands", "D": "Neither gland; it is extra-adrenal"}, "r": "C", "e": {"correcta": "Because congenital adrenal hyperplasia results from an inherited, systemic enzyme deficiency present in all adrenal cortical tissue, both adrenal glands are affected equally and become hyperplastic under chronic ACTH stimulation.", "incorrectas": {"A": "Unilateral (left-only) involvement would suggest a localized tumor process rather than a global enzymatic defect, which is inconsistent with the systemic, genetically determined nature of congenital adrenal hyperplasia.", "B": "Similarly, right-only involvement is not consistent with a systemic enzymatic defect; both glands share the same genetic and metabolic machinery, so both are affected.", "D": "The adrenal cortex itself is the site of the enzymatic defect and resultant hyperplasia; the condition is not extra-adrenal."}}}, {"id": "anking-endocrine-physiology-1785", "fuente": "anking", "tema": 23, "anki": "1462383838903", "q": "In congenital adrenal hyperplasia with severe cortisol deficiency, life-threatening hypotension can occur due to decreased expression of which receptor?", "o": {"A": "Beta-1 adrenergic receptor", "B": "Alpha-1 adrenergic receptor", "C": "Angiotensin II receptor", "D": "Mineralocorticoid receptor"}, "r": "B", "e": {"correcta": "Cortisol is required to maintain normal vascular alpha-1 adrenergic receptor expression and responsiveness on blood vessels (a permissive effect). Severe cortisol deficiency in congenital adrenal hyperplasia decreases alpha-1 receptor expression, impairing vasoconstriction and leading to life-threatening hypotension, especially during physiologic stress.", "incorrectas": {"A": "Beta-1 adrenergic receptors are primarily involved in increasing heart rate and contractility rather than the peripheral vasoconstriction whose loss is implicated in cortisol-deficient hypotension.", "C": "Angiotensin II receptors are part of the renin-angiotensin-aldosterone system regulating volume and vasoconstriction, but the specific permissive cortisol effect described here relates to alpha-1 adrenergic receptors on vascular smooth muscle.", "D": "Mineralocorticoid receptor function relates to aldosterone's effects on sodium and potassium handling in the kidney, which contributes to volume status in salt-wasting CAH, but is distinct from the alpha-1 receptor mechanism underlying cortisol-deficient vascular hypotension."}}}, {"id": "anking-endocrine-physiology-1786", "fuente": "anking", "tema": 23, "anki": "1462383841425", "q": "A deficiency of which steroidogenic enzyme causes congenital adrenal hyperplasia with salt-wasting and hyponatremia due to lack of aldosterone?", "o": {"A": "17α-hydroxylase deficiency", "B": "11β-hydroxylase deficiency", "C": "21β-hydroxylase deficiency", "D": "3β-hydroxysteroid dehydrogenase deficiency"}, "r": "C", "e": {"correcta": "21β-hydroxylase deficiency is the most common cause of congenital adrenal hyperplasia (about 90% of cases) and impairs synthesis of both cortisol and aldosterone, leading to salt wasting, hyponatremia, hyperkalemia, and hypotension, along with androgen excess from shunted precursors.", "incorrectas": {"A": "17α-hydroxylase deficiency impairs cortisol and sex hormone synthesis but increases mineralocorticoid precursors, causing hypertension and hypokalemia rather than salt-wasting hyponatremia.", "B": "11β-hydroxylase deficiency also causes increased mineralocorticoid precursor (11-deoxycorticosterone) accumulation, leading to hypertension, not the salt-wasting picture seen with 21-hydroxylase deficiency.", "D": "3β-hydroxysteroid dehydrogenase deficiency is a rare cause of CAH that can cause salt wasting, but it is distinguished by minimal virilization or even undervirilization in males, and it is not the classic enzyme associated with this specific salt-wasting presentation, which is 21-hydroxylase deficiency."}}}, {"id": "anking-endocrine-physiology-1787", "fuente": "anking", "tema": 23, "anki": "1462383852650", "q": "A female infant with 11β-hydroxylase deficiency presents with signs of excess androgen exposure. Which clinical feature results directly from this androgen elevation?", "o": {"A": "Hypotension", "B": "Virilization", "C": "Hyponatremia", "D": "Hypoglycemia"}, "r": "B", "e": {"correcta": "11β-hydroxylase deficiency causes accumulation of steroid precursors that are shunted toward androgen synthesis, resulting in virilization (ambiguous genitalia, clitoromegaly) in affected female infants, in addition to accumulation of 11-deoxycorticosterone, a weak mineralocorticoid.", "incorrectas": {"A": "11β-hydroxylase deficiency actually causes hypertension (not hypotension), because the accumulated 11-deoxycorticosterone has mineralocorticoid activity that promotes sodium retention and volume expansion.", "C": "Hyponatremia would be expected with salt-wasting forms of CAH (like 21-hydroxylase deficiency), but 11β-hydroxylase deficiency instead causes sodium retention and hypertension due to the mineralocorticoid-active precursor buildup.", "D": "Hypoglycemia is not a characteristic feature driven by androgen excess in 11β-hydroxylase deficiency; the clinically relevant findings are virilization from androgens and hypertension from the mineralocorticoid precursor."}}}, {"id": "anking-endocrine-pathology-1788", "fuente": "anking", "tema": 5, "anki": "1462389760356", "q": "Which condition is defined as the inability of the adrenal glands to generate sufficient glucocorticoids, with or without mineralocorticoid deficiency?", "o": {"A": "Cushing syndrome", "B": "Adrenal insufficiency", "C": "Conn syndrome", "D": "Pheochromocytoma"}, "r": "B", "e": {"correcta": "Adrenal insufficiency is the state in which the adrenal cortex fails to produce adequate cortisol (and often aldosterone), leading to hypotension, hyponatremia, hyperkalemia, and hypoglycemia. It can be primary (adrenal gland destruction), secondary (pituitary ACTH deficiency), or tertiary (hypothalamic CRH deficiency).", "incorrectas": {"A": "Cushing syndrome is the opposite process, caused by excess glucocorticoid (cortisol) exposure, whether from exogenous steroids or endogenous overproduction, producing hyperglycemia, weight gain, and immunosuppression rather than insufficiency.", "C": "Conn syndrome is primary hyperaldosteronism from an aldosterone-secreting adrenal adenoma, causing hypertension, hypokalemia, and metabolic alkalosis—an excess state, not a deficiency of adrenal hormones.", "D": "Pheochromocytoma is a catecholamine-secreting tumor of the adrenal medulla (chromaffin cells), not the cortex, and causes episodic hypertension rather than a deficiency of cortical hormones."}}}, {"id": "anking-endocrine-pathology-1789", "fuente": "anking", "tema": 5, "anki": "1462390250682", "q": "A patient with primary adrenal insufficiency undergoes a metyrapone stimulation test. Metyrapone blocks conversion of 11-deoxycortisol to cortisol, which should normally raise both ACTH and 11-deoxycortisol via loss of cortisol feedback. What are the expected ACTH and 11-deoxycortisol results in this patient?", "o": {"A": "Increased ACTH, increased 11-deoxycortisol", "B": "Decreased ACTH, decreased 11-deoxycortisol", "C": "Increased ACTH, decreased 11-deoxycortisol", "D": "Decreased ACTH, increased 11-deoxycortisol"}, "r": "C", "e": {"correcta": "In primary adrenal insufficiency, the adrenal cortex itself is destroyed and cannot synthesize steroid precursors regardless of stimulation. Metyrapone blocks 11-beta-hydroxylase, dropping cortisol and triggering an appropriate rise in ACTH via loss of negative feedback (since the pituitary is intact), but the diseased adrenal cannot produce 11-deoxycortisol in response, so it remains low.", "incorrectas": {"A": "Increased ACTH with increased 11-deoxycortisol is the NORMAL response, indicating an intact hypothalamic-pituitary-adrenal axis with a functioning adrenal cortex capable of producing precursor in response to ACTH drive—not what is seen when the adrenal gland itself is destroyed.", "B": "Decreased ACTH with decreased 11-deoxycortisol describes secondary/tertiary adrenal insufficiency, where the pituitary or hypothalamus fails to increase ACTH output, so the adrenal (though structurally intact) never receives the stimulus to make precursor.", "D": "Decreased ACTH with increased 11-deoxycortisol does not fit any physiologic pattern in this test, since a healthy pituitary should increase ACTH in response to metyrapone-induced cortisol loss, and precursor synthesis depends on that ACTH drive."}}}, {"id": "anking-endocrine-pathology-1790", "fuente": "anking", "tema": 5, "anki": "1462390264931", "q": "A patient with secondary/tertiary adrenal insufficiency undergoes metyrapone stimulation testing. What are the expected ACTH and 11-deoxycortisol levels?", "o": {"A": "Increased ACTH, increased 11-deoxycortisol", "B": "Decreased ACTH, decreased 11-deoxycortisol", "C": "Increased ACTH, decreased 11-deoxycortisol", "D": "Decreased ACTH, increased 11-deoxycortisol"}, "r": "B", "e": {"correcta": "In secondary or tertiary adrenal insufficiency, the defect lies in the pituitary (decreased ACTH) or hypothalamus (decreased CRH), so even though the adrenal cortex is structurally intact, it never receives an adequate stimulus. After metyrapone blocks cortisol synthesis, the pituitary fails to mount a compensatory ACTH rise, so 11-deoxycortisol also stays low.", "incorrectas": {"A": "Increased ACTH with increased 11-deoxycortisol is the normal response of an intact HPA axis, which is precisely what is deficient in secondary/tertiary disease—the pituitary/hypothalamus cannot generate the ACTH surge needed to drive precursor production.", "C": "Increased ACTH with decreased 11-deoxycortisol is the primary adrenal insufficiency pattern, where the pituitary can still respond appropriately (high ACTH) but the destroyed adrenal cortex cannot generate precursor—the opposite defect from secondary/tertiary disease.", "D": "Decreased ACTH with increased 11-deoxycortisol is physiologically inconsistent, since 11-deoxycortisol production in this test is driven by ACTH stimulation; without a rise in ACTH there is no mechanism to raise 11-deoxycortisol."}}}, {"id": "anking-endocrine-pathology-1791", "fuente": "anking", "tema": 5, "anki": "1462390426081", "q": "Which syndrome, characterized by bilateral adrenal hemorrhage in the setting of fulminant meningococcemia, is a classic cause of acute primary adrenal insufficiency?", "o": {"A": "Sheehan syndrome", "B": "Nelson syndrome", "C": "Waterhouse-Friderichsen syndrome", "D": "Conn syndrome"}, "r": "C", "e": {"correcta": "Waterhouse-Friderichsen syndrome is acute hemorrhagic destruction of both adrenal glands, classically triggered by overwhelming Neisseria meningitidis septicemia with DIC, leading to sudden loss of cortisol and mineralocorticoid production and adrenal crisis.", "incorrectas": {"A": "Sheehan syndrome is postpartum pituitary infarction due to hypotension/hemorrhage during delivery, causing panhypopituitarism (a secondary/central cause of hormone deficiency), not direct adrenal gland hemorrhage from sepsis.", "B": "Nelson syndrome refers to an ACTH-secreting pituitary adenoma that develops after bilateral adrenalectomy (e.g., for Cushing disease), causing hyperpigmentation and mass effect—a pituitary tumor complication, not an acute adrenal hemorrhage syndrome.", "D": "Conn syndrome is primary hyperaldosteronism from an aldosterone-producing adrenal adenoma, causing hypertension and hypokalemia, the opposite clinical picture of the acute hormone deficiency seen in Waterhouse-Friderichsen syndrome."}}}, {"id": "anking-endocrine-pathology-1792", "fuente": "anking", "tema": 5, "anki": "1462390449708", "q": "Waterhouse-Friderichsen syndrome classically follows disseminated intravascular coagulation in young children infected with which organism?", "o": {"A": "Streptococcus pneumoniae", "B": "Haemophilus influenzae", "C": "Neisseria meningitidis", "D": "Staphylococcus aureus"}, "r": "C", "e": {"correcta": "Neisseria meningitidis septicemia can trigger DIC with bilateral adrenal hemorrhage (Waterhouse-Friderichsen syndrome), and the resulting loss of cortisol exacerbates septic hypotension, often leading rapidly to death if not recognized and treated with stress-dose steroids and antibiotics.", "incorrectas": {"B": "Haemophilus influenzae classically causes epiglottitis and, in unvaccinated children, meningitis, but it is not the organism classically linked to Waterhouse-Friderichsen syndrome—that association is specific to meningococcemia.", "A": "Streptococcus pneumoniae is a common cause of meningitis and sepsis in children but is not the classic trigger organism for Waterhouse-Friderichsen syndrome, which is specifically tied to meningococcal septicemia and its characteristic petechial/purpuric rash with DIC.", "D": "Staphylococcus aureus can cause severe sepsis and toxic shock syndrome, but the classic textbook association with adrenal hemorrhage and Waterhouse-Friderichsen syndrome is Neisseria meningitidis, not S. aureus."}}}, {"id": "anking-endocrine-pathology-1793", "fuente": "anking", "tema": 5, "anki": "1462390476322", "q": "Chronic primary adrenal insufficiency due to adrenal atrophy or destruction by disease is also known by what eponym?", "o": {"A": "Cushing disease", "B": "Addison disease", "C": "Conn disease", "D": "Graves disease"}, "r": "B", "e": {"correcta": "Addison disease is the eponym for chronic primary adrenal insufficiency, in which the adrenal cortex is progressively destroyed or atrophies, leading to deficient cortisol and often aldosterone production with compensatory elevation of ACTH.", "incorrectas": {"A": "Cushing disease specifically refers to an ACTH-secreting pituitary adenoma causing hypercortisolism, a distinct entity of hormone excess from a central source, not adrenal destruction and hormone deficiency.", "C": "Conn disease (syndrome) describes autonomous aldosterone overproduction from an adrenal adenoma, producing hypertension and hypokalemia—an excess state opposite to the deficiency seen in Addison disease.", "D": "Graves disease is an autoimmune cause of hyperthyroidism due to TSH-receptor stimulating antibodies, unrelated to the adrenal cortex or adrenal insufficiency."}}}, {"id": "anking-endocrine-pathology-1794", "fuente": "anking", "tema": 5, "anki": "1462390501771", "q": "In the Western world, what is the most common cause of Addison disease?", "o": {"A": "Tuberculosis", "B": "Metastatic carcinoma", "C": "Autoimmune destruction", "D": "Adrenal hemorrhage"}, "r": "C", "e": {"correcta": "Autoimmune destruction of the adrenal cortex (autoimmune adrenalitis) is the leading cause of Addison disease in developed countries, often occurring as part of autoimmune polyendocrine syndromes, and results in lymphocytic infiltration and progressive cortical atrophy.", "incorrectas": {"A": "Tuberculosis is the most common cause of Addison disease in the developing world, where caseating granulomas destroy the adrenal cortex, but it is a less frequent cause in Western countries where autoimmune disease predominates.", "B": "Metastatic carcinoma (especially from lung cancer) can infiltrate and destroy the adrenal glands bilaterally, but this is a less common cause overall compared to autoimmune destruction in the West.", "D": "Adrenal hemorrhage, as in Waterhouse-Friderichsen syndrome or anticoagulant use, causes acute rather than chronic adrenal insufficiency and is not the leading cause of classic Addison disease."}}}, {"id": "anking-endocrine-pathology-1795", "fuente": "anking", "tema": 5, "anki": "1462390507327", "q": "In the developing world, what is the most common cause of Addison disease?", "o": {"A": "Autoimmune destruction", "B": "Tuberculosis", "C": "Metastatic carcinoma", "D": "Adrenoleukodystrophy"}, "r": "B", "e": {"correcta": "Tuberculosis remains the most common cause of Addison disease in developing regions with high TB prevalence, where mycobacterial infection spreads hematogenously to the adrenal glands and causes caseating granulomatous destruction of the cortex.", "incorrectas": {"A": "Autoimmune destruction is the predominant cause in the Western/developed world, where TB is far less prevalent, reflecting differing epidemiology of adrenal insufficiency etiologies between regions.", "C": "Metastatic carcinoma, particularly from the lung, can destroy adrenal tissue bilaterally but is not the leading cause of Addison disease in the developing world, where infectious causes dominate.", "D": "Adrenoleukodystrophy is an X-linked peroxisomal disorder causing very-long-chain fatty acid accumulation, adrenal insufficiency, and neurologic demyelination, but it is a rare genetic cause, not the leading global cause of Addison disease."}}}, {"id": "anking-endocrine-pathology-1796", "fuente": "anking", "tema": 5, "anki": "1462390512342", "q": "A common cause of Addison disease is metastatic carcinoma, particularly originating from which primary site?", "o": {"A": "Breast", "B": "Colon", "C": "Lungs", "D": "Prostate"}, "r": "C", "e": {"correcta": "Lung cancer is a classic primary tumor that metastasizes to the adrenal glands, and when bilateral adrenal involvement is extensive enough to destroy more than 90% of cortical tissue, it can precipitate Addison disease (primary adrenal insufficiency).", "incorrectas": {"A": "Breast cancer can metastasize widely, including to bone and liver, but it is not the classic primary site emphasized in association with adrenal metastases causing Addison disease—lung cancer holds that distinction due to its frequent adrenal spread.", "B": "Colon cancer typically metastasizes to the liver via portal circulation first, and while distant spread can occur, it is not the prototypical cancer linked to adrenal metastasis and Addison disease.", "D": "Prostate cancer characteristically metastasizes to bone (osteoblastic lesions), not preferentially to the adrenal glands, making it a less classic association with Addison disease compared to lung cancer."}}}, {"id": "anking-endocrine-pathology-1797", "fuente": "anking", "tema": 5, "anki": "1462390524548", "q": "A patient with Addison disease presents with low blood pressure. This clinical feature is primarily due to a deficiency of which hormone(s)?", "o": {"A": "Thyroid hormone", "B": "Cortisol", "C": "Insulin", "D": "Growth hormone"}, "r": "B", "e": {"correcta": "Cortisol deficiency in Addison disease reduces vascular responsiveness to catecholamines and contributes to hypotension; combined with mineralocorticoid (aldosterone) deficiency causing volume depletion, patients develop significant hypotension, along with hypoglycemia, vomiting, and diarrhea.", "incorrectas": {"A": "Thyroid hormone deficiency (hypothyroidism) causes bradycardia, cold intolerance, and fatigue, but it is not the hormone deficiency responsible for the hypotension characteristic of Addison disease.", "C": "Insulin deficiency, as in type 1 diabetes, causes hyperglycemia and ketoacidosis rather than hypotension, and is unrelated to the adrenal cortical failure seen in Addison disease.", "D": "Growth hormone deficiency causes growth failure in children and subtle metabolic changes in adults, but it does not produce the hypotension that defines the adrenal crisis picture of Addison disease."}}}, {"id": "anking-endocrine-pathology-1798", "fuente": "anking", "tema": 5, "anki": "1462390533401", "q": "A patient with Addison disease presents with hyponatremia, hypovolemia, and hyperkalemia. These findings are primarily due to deficiency of which class of hormones?", "o": {"A": "Glucocorticoids", "B": "Mineralocorticoids", "C": "Sex steroids", "D": "Catecholamines"}, "r": "B", "e": {"correcta": "Mineralocorticoids (aldosterone) normally promote renal sodium reabsorption and potassium/hydrogen excretion in the collecting duct; their deficiency in primary adrenal insufficiency leads to sodium wasting (hyponatremia), volume depletion (hypovolemia), and potassium retention (hyperkalemia).", "incorrectas": {"A": "Glucocorticoid deficiency contributes to hypotension, hypoglycemia, and impaired stress response, but the specific electrolyte pattern of hyponatremia/hyperkalemia is driven by loss of aldosterone's renal tubular effects, not cortisol.", "C": "Sex steroid deficiency (e.g., adrenal androgens) can cause decreased libido or loss of axillary/pubic hair in women, but does not cause the electrolyte disturbances seen in this presentation.", "D": "Catecholamines (epinephrine/norepinephrine) are produced by the adrenal medulla, not the cortex, and are unaffected in Addison disease, which is a cortical disorder; their deficiency would not explain these electrolyte findings."}}}, {"id": "anking-endocrine-pathology-1799", "fuente": "anking", "tema": 5, "anki": "1462390604502", "q": "Why does secondary adrenal insufficiency, unlike primary adrenal insufficiency, NOT present with skin and mucosal hyperpigmentation?", "o": {"A": "Because cortisol levels are normal", "B": "Because ACTH levels are decreased", "C": "Because aldosterone is elevated", "D": "Because the adrenal cortex is hyperplastic"}, "r": "B", "e": {"correcta": "Hyperpigmentation in primary adrenal insufficiency results from markedly elevated ACTH (and its co-secreted peptide POMC-derived MSH) stimulating melanocytes. In secondary adrenal insufficiency, the defect is at the pituitary level, so ACTH is low rather than compensatorily elevated, and hyperpigmentation does not occur.", "incorrectas": {"A": "Cortisol levels are actually low in secondary adrenal insufficiency, just as in primary disease; the distinguishing factor for pigmentation is not cortisol level itself but whether ACTH is elevated or reduced.", "C": "Aldosterone is not the driver of skin pigmentation in adrenal insufficiency; pigmentation results from ACTH/MSH stimulation of melanocytes, and aldosterone is actually preserved (not elevated) in secondary disease since the renin-angiotensin system remains intact.", "D": "The adrenal cortex in secondary adrenal insufficiency is understimulated and may atrophy from lack of ACTH trophic support, rather than becoming hyperplastic; hyperplasia is not the mechanism relevant to pigmentation differences."}}}, {"id": "anking-endocrine-pathology-1800", "fuente": "anking", "tema": 5, "anki": "1462390609512", "q": "Why does secondary adrenal insufficiency typically NOT present with hyperkalemia, unlike primary adrenal insufficiency?", "o": {"A": "Because ACTH is elevated", "B": "Because glucocorticoid levels are normal", "C": "Because aldosterone synthesis is preserved", "D": "Because renal potassium excretion is enhanced by cortisol"}, "r": "C", "e": {"correcta": "Aldosterone secretion is primarily regulated by the renin-angiotensin system and serum potassium, not by ACTH/pituitary function. In secondary adrenal insufficiency, only cortisol production falls (due to loss of ACTH drive), while the zona glomerulosa and its aldosterone output remain largely intact, so potassium homeostasis is preserved and hyperkalemia does not occur.", "incorrectas": {"A": "ACTH is actually decreased, not elevated, in secondary adrenal insufficiency, since the defect originates in the pituitary itself and there is no compensatory rise as seen in primary disease.", "B": "Glucocorticoid levels are low, not normal, in secondary adrenal insufficiency; the key point is that the aldosterone axis (renin-angiotensin) is unaffected, which is why hyperkalemia does not develop despite low cortisol.", "D": "Cortisol does not primarily regulate renal potassium excretion; that is aldosterone's role via the mineralocorticoid receptor in the collecting duct, and this pathway is preserved because it depends on renin-angiotensin, not ACTH."}}}, {"id": "anking-endocrine-anatomy-1801", "fuente": "anking", "tema": 25, "anki": "1462391919306", "q": "The adrenal medulla secretes which two catecholamines?", "o": {"A": "Dopamine and serotonin", "B": "Cortisol and aldosterone", "C": "Norepinephrine and epinephrine", "D": "Epinephrine and dopamine"}, "r": "C", "e": {"correcta": "The adrenal medulla is composed of neural crest-derived chromaffin cells that synthesize and secrete the catecholamines norepinephrine and epinephrine into the bloodstream in response to sympathetic (preganglionic) stimulation, mediating the systemic fight-or-flight response.", "incorrectas": {"A": "Dopamine is a catecholamine precursor synthesized en route to norepinephrine/epinephrine, and serotonin is unrelated to adrenal medullary function; neither is the primary secretory product released from the adrenal medulla into circulation.", "B": "Cortisol and aldosterone are steroid hormones produced by the adrenal cortex (zona fasciculata and zona glomerulosa, respectively), an entirely separate embryologic and functional compartment from the medulla.", "D": "While dopamine is a biosynthetic intermediate in catecholamine synthesis, it is not one of the two major hormones secreted by the adrenal medulla into the bloodstream; epinephrine and norepinephrine are the defining secretory products."}}}, {"id": "anking-endocrine-pathology-1802", "fuente": "anking", "tema": 5, "anki": "1462391926278", "q": "A pheochromocytoma arises from a neoplastic proliferation of which cell type?", "o": {"A": "Zona glomerulosa cells", "B": "Chromaffin cells", "C": "Follicular cells", "D": "Neuroendocrine C cells"}, "r": "B", "e": {"correcta": "Pheochromocytoma is a tumor of chromaffin cells, the neural crest-derived catecholamine-secreting cells of the adrenal medulla, leading to excess and often episodic secretion of epinephrine and norepinephrine.", "incorrectas": {"A": "Zona glomerulosa cells are cortical cells that produce aldosterone; a tumor of these cells causes primary hyperaldosteronism (Conn syndrome), not the catecholamine excess seen in pheochromocytoma.", "C": "Follicular cells are thyroid epithelial cells responsible for producing thyroid hormone (T3/T4); they are unrelated to the adrenal medulla or catecholamine secretion.", "D": "Neuroendocrine C cells (parafollicular cells) of the thyroid secrete calcitonin and give rise to medullary thyroid carcinoma, a distinct tumor from pheochromocytoma despite both being neural crest-derived."}}}, {"id": "anking-endocrine-pathology-1803", "fuente": "anking", "tema": 5, "anki": "1462391936207", "q": "On gross pathologic examination, a pheochromocytoma classically appears as a tumor of what color?", "o": {"A": "Yellow", "B": "White", "C": "Brown", "D": "Black"}, "r": "C", "e": {"correcta": "Pheochromocytomas classically appear brown grossly, reflecting their chromaffin cell origin (chromaffin cells stain brown with chromate salts). A thin yellow rim of residual, compressed adrenal cortex, colored by its cholesterol content, may be seen surrounding the tumor.", "incorrectas": {"A": "Yellow coloration is characteristic of the normal adrenal cortex due to its high cholesterol/lipid content (used for steroidogenesis), not of the medullary chromaffin tumor itself, which is brown.", "B": "A white, glistening appearance is not typical of pheochromocytoma; this tumor's chromaffin reaction gives it a characteristically brown gross appearance.", "D": "Black discoloration is not a classic gross feature of pheochromocytoma; it is more associated with hemorrhagic or necrotic changes in other tumor types, not the typical brown chromaffin appearance."}}}, {"id": "anking-endocrine-pathology-1804", "fuente": "anking", "tema": 5, "anki": "1462391951908", "q": "Patients with pheochromocytoma typically experience their hypertensive symptoms in what pattern?", "o": {"A": "Continuously, without variation", "B": "Only at night", "C": "Episodically, in discrete spells", "D": "Only after meals"}, "r": "C", "e": {"correcta": "Pheochromocytomas release catecholamines in bursts rather than continuously, so patients experience episodic (paroxysmal) symptoms—headache, palpitations, diaphoresis, and hypertensive spells—separated by relatively symptom-free intervals, rather than sustained continuous hypertension.", "incorrectas": {"A": "Continuous, unvarying symptoms are not the classic presentation; the hallmark of pheochromocytoma is paroxysmal (episodic) catecholamine surges rather than a steady, unchanging hypertensive state.", "B": "Episodes are not specifically confined to nighttime; attacks can be triggered by various stimuli (stress, exertion, certain foods, abdominal palpation, or anesthesia induction) at any time of day, not solely nocturnally.", "D": "While certain triggers like tyramine-containing foods or abdominal pressure can provoke episodes, symptoms are not restricted to occurring only after meals—the defining feature is episodic, not meal-specific, timing."}}}, {"id": "anking-endocrine-pathology-1805", "fuente": "anking", "tema": 5, "anki": "1462392039342", "q": "What is the definitive treatment for a pheochromocytoma?", "o": {"A": "Lifelong alpha-blocker therapy", "B": "Radioactive iodine ablation", "C": "Surgical excision", "D": "Chemotherapy"}, "r": "C", "e": {"correcta": "Surgical excision (adrenalectomy) is the definitive treatment for pheochromocytoma. Critically, patients must first receive an irreversible alpha-blocker (phenoxybenzamine) followed by a beta-blocker preoperatively to prevent a catecholamine-driven hypertensive crisis during tumor manipulation.", "incorrectas": {"A": "Alpha-blockers like phenoxybenzamine are essential preoperative preparation to control catecholamine surges and prevent intraoperative hypertensive crisis, but they are a bridge to surgery, not a lifelong cure for the tumor itself.", "B": "Radioactive iodine ablation is used to treat thyroid conditions (hyperthyroidism, thyroid cancer) because thyroid follicular cells take up iodine; pheochromocytoma cells do not concentrate iodine and this modality is not the treatment for this adrenal medullary tumor.", "D": "Chemotherapy is reserved for malignant, metastatic, or unresectable pheochromocytoma cases, but it is not the primary or definitive treatment for the typical, resectable tumor—surgery remains first-line."}}}, {"id": "anking-endocrine-pathology-1806", "fuente": "anking", "tema": 5, "anki": "1462392082389", "q": "Pheochromocytoma is classically associated with which mnemonic rule describing its epidemiologic and pathologic features?", "o": {"A": "Rule of 2s", "B": "Rule of 9s", "C": "Rule of 10s", "D": "Rule of 3s"}, "r": "C", "e": {"correcta": "The 'rule of 10s' for pheochromocytoma classically states that approximately 10% are bilateral, 10% are extra-adrenal (paraganglioma), 10% are malignant, and 10% occur in children, although with modern genetic testing (e.g., MEN2, VHL, NF1) these percentages are now recognized as underestimates for familial/extra-adrenal cases.", "incorrectas": {"A": "The 'rule of 2s' is a classic mnemonic for Meckel diverticulum (2% of population, within 2 feet of the ileocecal valve, 2 inches long, presents by age 2), an unrelated gastrointestinal congenital anomaly.", "B": "The 'rule of 9s' is used to estimate total body surface area involved in burns, dividing the body into sections that are multiples of 9%, and has no relation to pheochromocytoma.", "D": "There is no classic 'rule of 3s' associated with pheochromocytoma in First Aid or standard USMLE teaching; the well-known mnemonic for this tumor is specifically the rule of 10s."}}}, {"id": "anking-endocrine-pathology-1807", "fuente": "anking", "tema": 5, "anki": "1462392092430", "q": "A pheochromocytoma arising outside the adrenal medulla is classically located in the wall of which organ, presenting with episodic symptoms triggered by a specific activity?", "o": {"A": "Stomach, triggered by eating", "B": "Bladder, triggered by urination", "C": "Rectum, triggered by defecation", "D": "Uterus, triggered by menstruation"}, "r": "B", "e": {"correcta": "Extra-adrenal pheochromocytomas (paragangliomas) can arise from chromaffin-like paraganglion cells in the bladder wall, and because catecholamine release is provoked by bladder wall stretch and contraction, patients classically experience hypertensive episodes, palpitations, or headache specifically during or immediately after urination (micturition syncope-like episodes).", "incorrectas": {"A": "The stomach is not a classic extra-adrenal site for pheochromocytoma/paraganglioma, and eating is not the characteristic trigger described for this tumor's episodic catecholamine release.", "C": "The rectum is not the classically cited extra-adrenal location for pheochromocytoma; the bladder is specifically highlighted because of its distinctive link to micturition-triggered symptoms.", "D": "The uterus is not a recognized site for extra-adrenal pheochromocytoma, and menstruation is not a described trigger for catecholamine release in this tumor."}}}, {"id": "anking-endocrine-physiology-1808", "fuente": "anking", "tema": 23, "anki": "1462808824667", "q": "Surgical removal of a lingual thyroid can result in which condition, if it represents the only functional thyroid tissue present?", "o": {"A": "Hyperthyroidism", "B": "Hypothyroidism", "C": "Thyroid storm", "D": "Graves disease"}, "r": "B", "e": {"correcta": "A lingual thyroid results from failure of the thyroid diverticulum to fully descend from the base of the tongue (foramen cecum) into the neck during development. In some patients, this ectopic tissue is the only functioning thyroid present, so its surgical removal without adequate hormone replacement causes hypothyroidism.", "incorrectas": {"A": "Hyperthyroidism would result from excess thyroid hormone production, the opposite of what happens when the only source of thyroid tissue is surgically removed and hormone production ceases.", "C": "Thyroid storm is a life-threatening exacerbation of hyperthyroidism, usually precipitated by stress or infection in a patient with underlying thyrotoxicosis, not a consequence of removing thyroid tissue.", "D": "Graves disease is an autoimmune cause of hyperthyroidism from TSH-receptor stimulating antibodies; it is unrelated to the embryologic consequence of losing one's only thyroid tissue via surgery."}}}, {"id": "anking-endocrine-anatomy-1809", "fuente": "anking", "tema": 25, "anki": "1462808874657", "q": "A persistent cervical sinus results in a branchial cleft cyst, which characteristically presents in which location of the neck?", "o": {"A": "Midline", "B": "Lateral neck", "C": "Suprasternal", "D": "Posterior triangle only"}, "r": "B", "e": {"correcta": "A branchial cleft cyst results from failure of obliteration of the cervical sinus (formed by the second branchial arch overgrowing the second through fourth clefts), and it characteristically presents as a smooth, fluctuant mass in the lateral neck, typically along the anterior border of the sternocleidomastoid muscle.", "incorrectas": {"A": "A midline neck mass is characteristic of a thyroglossal duct cyst, which arises from persistence of the thyroglossal duct along the descent path of the thyroid gland—a distinct embryologic remnant from the branchial apparatus.", "C": "A suprasternal location is not the classic site for a branchial cleft cyst; this location is not a standard teaching point for either branchial or thyroglossal duct anomalies.", "D": "While branchial cleft cysts occur laterally, they are not restricted specifically to the posterior triangle; they classically occur along the anterior border of the sternocleidomastoid, which is not confined to the posterior triangle."}}}, {"id": "anking-reproductive-system-embryology-1810", "fuente": "anking", "tema": 33, "anki": "1462808901843", "q": "Thyroid follicular tissue arises embryologically from which germ layer?", "o": {"A": "Ectoderm", "B": "Mesoderm", "C": "Endoderm", "D": "Neural crest"}, "r": "C", "e": {"correcta": "The thyroid gland develops from an endodermal outpouching called the thyroid diverticulum, which arises from the floor of the primitive pharynx and descends along the thyroglossal duct into the neck, ultimately forming the follicular cells that produce thyroid hormone.", "incorrectas": {"A": "Ectoderm gives rise to structures like the epidermis, CNS, and PNS, but the thyroid diverticulum arises from the pharyngeal floor, which is endodermal in origin, not ectodermal.", "B": "Mesoderm forms structures such as the adrenal cortex, muscle, and connective tissue, but thyroid follicular tissue derives from endoderm of the primitive pharynx, not mesoderm.", "D": "Neural crest, a derivative of ectoderm, gives rise to structures like the adrenal medulla and many peripheral nervous system components, but not the thyroid follicular cells, which are endodermal."}}}, {"id": "anking-reproductive-system-embryology-1811", "fuente": "anking", "tema": 33, "anki": "1462808976733", "q": "According to current First Aid teaching, parafollicular (C) cells of the thyroid, which secrete calcitonin, arise from which germ layer?", "o": {"A": "Mesoderm", "B": "Ectoderm", "C": "Neural crest exclusively", "D": "Endoderm"}, "r": "D", "e": {"correcta": "Although the embryologic origin of parafollicular (C) cells has historically been debated (with older teaching attributing them to neural crest via the ultimobranchial body), current First Aid errata clarify that these calcitonin-secreting cells are classified as endoderm-derived, similar to the rest of the thyroid gland.", "incorrectas": {"A": "Mesoderm gives rise to structures such as the adrenal cortex, kidneys, and connective tissue; it is not the germ layer attributed to parafollicular cells in current First Aid teaching.", "B": "Ectoderm forms the epidermis and nervous system; while neural crest (an ectodermal derivative) was the traditional attribution for C cells, updated teaching reclassifies them as endodermal.", "C": "Neural crest was the older, traditional teaching for the origin of C cells (via the ultimobranchial body), but per FA2018 errata, current First Aid editions specify an endodermal origin instead."}}}, {"id": "anking-reproductive-system-embryology-1812", "fuente": "anking", "tema": 33, "anki": "1462809000922", "q": "The adrenal cortex arises embryologically from which germ layer?", "o": {"A": "Neural crest", "B": "Mesoderm", "C": "Endoderm", "D": "Surface ectoderm"}, "r": "B", "e": {"correcta": "The adrenal cortex, which produces steroid hormones (mineralocorticoids, glucocorticoids, and androgens), is derived from mesoderm, consistent with its steroidogenic function shared with other mesodermally derived gonadal steroid-producing tissues.", "incorrectas": {"A": "Neural crest gives rise to the adrenal medulla (chromaffin cells), which is functionally and embryologically distinct from the cortex, producing catecholamines rather than steroid hormones.", "C": "Endoderm forms structures like the thyroid follicular cells and gut epithelium, but not the adrenal cortex, which has a mesodermal origin reflecting its steroidogenic lineage.", "D": "Surface ectoderm gives rise to structures like the epidermis and lens of the eye, unrelated to the mesodermally derived adrenal cortex."}}}, {"id": "anking-reproductive-system-embryology-1813", "fuente": "anking", "tema": 33, "anki": "1462809037538", "q": "The adrenal medulla arises embryologically from which structure?", "o": {"A": "Mesoderm", "B": "Endoderm", "C": "Neural crest", "D": "Surface ectoderm"}, "r": "C", "e": {"correcta": "The adrenal medulla is derived from neural crest cells, the same migratory ectodermal population that gives rise to sympathetic ganglia and other components of the peripheral nervous system, consistent with the medulla functioning essentially as a specialized sympathetic ganglion that secretes catecholamines directly into the blood.", "incorrectas": {"A": "Mesoderm gives rise to the adjacent adrenal cortex, which is embryologically and functionally distinct from the medulla, producing steroid hormones rather than catecholamines.", "B": "Endoderm forms structures such as the thyroid and gut lining, not the adrenal medulla, which arises from neural crest as part of the peripheral autonomic nervous system lineage.", "D": "Surface ectoderm gives rise to skin and sensory placodes, not the adrenal medulla; the medulla arises specifically from the neural crest subset of ectodermal derivatives."}}}, {"id": "anking-endocrine-anatomy-1814", "fuente": "anking", "tema": 25, "anki": "1462809038273", "q": "Which anterior pituitary hormones stain basophilic on histological preparation?", "o": {"A": "GH, prolactin", "B": "FSH, LH, ACTH, TSH", "C": "Only ACTH and TSH", "D": "GH, ACTH, TSH"}, "r": "B", "e": {"correcta": "The basophilic cells of the anterior pituitary secrete FSH, LH, ACTH, and TSH (mnemonic 'B-FLAT': Basophils = FSH, LH, ACTH, TSH). These glycoprotein and peptide hormones stain with basic dyes due to their carbohydrate/protein composition, distinguishing them from the acidophilic hormone-producing cells.", "incorrectas": {"A": "GH and prolactin are the acidophilic hormones of the anterior pituitary (mnemonic 'A-PiG'), staining with acidic dyes rather than basic dyes, placing them in the opposite histologic category from the basophils.", "C": "While ACTH and TSH are indeed basophilic, this option omits FSH and LH, which are also basophilic hormones; the complete basophilic group includes all four: FSH, LH, ACTH, and TSH.", "D": "GH is an acidophilic hormone, not basophilic, so grouping it with ACTH and TSH under the basophilic category is incorrect; GH belongs with prolactin in the acidophilic group."}}}, {"id": "anking-endocrine-anatomy-1815", "fuente": "anking", "tema": 25, "anki": "1462809195840", "q": "Which anterior pituitary hormones stain acidophilic on histological preparation?", "o": {"A": "FSH, LH", "B": "ACTH, TSH", "C": "GH, prolactin", "D": "FSH, LH, ACTH, TSH"}, "r": "C", "e": {"correcta": "GH and prolactin are the acidophilic hormones of the anterior pituitary (mnemonic 'A-PiG': Acidophils = Prolactin, GH), staining with acidic dyes (eosin) due to their protein structure, distinguishing them from the basophilic glycoprotein/peptide hormone-secreting cells.", "incorrectas": {"A": "FSH and LH are gonadotropins that belong to the basophilic cell group (along with ACTH and TSH), not the acidophilic group, which contains only GH and prolactin.", "B": "ACTH and TSH are part of the basophilic hormone group (mnemonic 'B-FLAT'), staining with basic dyes, the opposite category from the acidophilic GH and prolactin.", "D": "This lists all four basophilic hormones (FSH, LH, ACTH, TSH), none of which are acidophilic; the acidophilic category specifically comprises only GH and prolactin."}}}, {"id": "anking-endocrine-physiology-1816", "fuente": "anking", "tema": 23, "anki": "1462809232452", "q": "Insulin increases GLUT4 transporter expression on the surface of adipose and skeletal muscle tissue primarily via which intracellular signaling pathway?", "o": {"A": "cAMP/PKA pathway", "B": "JAK-STAT pathway", "C": "PI3 kinase pathway", "D": "cGMP/PKG pathway"}, "r": "C", "e": {"correcta": "Binding of insulin to its receptor tyrosine kinase activates insulin receptor substrate (IRS) proteins, which recruit and activate PI3 kinase (PI3K). This pathway triggers translocation of GLUT4-containing vesicles to the plasma membrane in muscle and adipose tissue, increasing glucose uptake in these insulin-dependent tissues.", "incorrectas": {"A": "The cAMP/PKA pathway is classically activated by Gs-coupled receptors (e.g., glucagon, epinephrine at beta receptors) and mediates catabolic effects like glycogenolysis and lipolysis, essentially opposing insulin's anabolic actions rather than mediating GLUT4 translocation.", "B": "JAK-STAT signaling is used by cytokine and growth hormone receptors (e.g., GH, prolactin, erythropoietin) to directly activate transcription factors, not the mechanism by which insulin promotes GLUT4 membrane translocation.", "D": "The cGMP/PKG pathway is activated by receptors like ANP or nitric oxide-guanylate cyclase signaling (e.g., vascular smooth muscle relaxation), and is unrelated to insulin's action on GLUT4 trafficking."}}}, {"id": "anking-endocrine-physiology-1817", "fuente": "anking", "tema": 23, "anki": "1462809460228", "q": "Overall, the metabolic effects of insulin are best characterized as which of the following?", "o": {"A": "Catabolic", "B": "Anabolic", "C": "Neutral, no net metabolic effect", "D": "Purely glycogenolytic"}, "r": "B", "e": {"correcta": "Insulin is the primary anabolic hormone of the body, promoting glucose uptake and storage as glycogen, fatty acid synthesis and storage as triglycerides, and protein synthesis, while inhibiting catabolic processes like gluconeogenesis, glycogenolysis, and lipolysis.", "incorrectas": {"A": "Catabolic describes the action of counter-regulatory hormones like glucagon, cortisol, and epinephrine, which break down glycogen, fat, and protein stores to raise blood glucose—effects opposite to those of insulin.", "C": "Insulin has clear, well-defined net anabolic effects on metabolism (building up glycogen, fat, and protein stores); it does not have a neutral or absent metabolic effect.", "D": "Glycogenolysis (glycogen breakdown) is actually inhibited by insulin, not promoted; insulin instead stimulates glycogenesis (glycogen synthesis), which is an anabolic, not catabolic, process."}}}, {"id": "anking-endocrine-physiology-1818", "fuente": "anking", "tema": 23, "anki": "1462809498251", "q": "Which insulin-independent glucose transporter is found in the brain, placenta, cornea, and red blood cells?", "o": {"A": "GLUT1", "B": "GLUT2", "C": "GLUT3", "D": "GLUT4"}, "r": "A", "e": {"correcta": "GLUT1 is an insulin-independent glucose transporter widely expressed in tissues that require constant basal glucose uptake regardless of insulin status, including the brain (particularly the blood-brain barrier), placenta, RBCs, and cornea, ensuring these tissues are never glucose-starved even during fasting.", "incorrectas": {"B": "GLUT2 is a bidirectional, low-affinity/high-capacity insulin-independent transporter found in beta-islet cells, liver, kidney, and small intestine, functioning as a glucose sensor and facilitating rapid glucose equilibration, distinct from the tissue distribution of GLUT1.", "C": "GLUT3 is an insulin-independent transporter found predominantly in neurons and the placenta, with high affinity for glucose, but it is not classically described as present in RBCs or the cornea like GLUT1.", "D": "GLUT4 is the insulin-DEPENDENT transporter found in adipose tissue and skeletal/cardiac muscle, translocating to the membrane in response to insulin signaling—functionally and tissue-wise distinct from the constitutively active GLUT1."}}}, {"id": "anking-endocrine-physiology-1819", "fuente": "anking", "tema": 23, "anki": "1462809621604", "q": "Which bidirectional, insulin-independent glucose transporter with low affinity and high capacity is found in pancreatic beta-islet cells, liver, kidney, and small intestine?", "o": {"A": "GLUT1", "B": "GLUT2", "C": "GLUT4", "D": "GLUT5"}, "r": "B", "e": {"correcta": "GLUT2 is a low-affinity, high-capacity, bidirectional transporter present in pancreatic beta cells, hepatocytes, renal tubular cells, and enterocytes, allowing glucose flux proportional to blood glucose concentration—critical for beta cells to sense glucose levels and appropriately regulate insulin secretion.", "incorrectas": {"A": "GLUT1 is a high-affinity, insulin-independent transporter found in the brain, RBCs, placenta, and cornea, ensuring constant basal glucose uptake, but it is not the bidirectional low-affinity/high-capacity transporter described in beta cells, liver, and kidney.", "C": "GLUT4 is the insulin-DEPENDENT transporter in adipose and muscle tissue, requiring insulin signaling for membrane translocation, unlike the constitutively active, insulin-independent GLUT2.", "D": "GLUT5 is an insulin-independent fructose transporter found in spermatocytes and the GI tract, functionally and structurally distinct from the bidirectional glucose transporter GLUT2 described here."}}}, {"id": "anking-endocrine-physiology-1820", "fuente": "anking", "tema": 23, "anki": "1462809626737", "q": "Which insulin-independent glucose transporter is found exclusively in the brain and placenta?", "o": {"A": "GLUT1", "B": "GLUT2", "C": "GLUT3", "D": "GLUT4"}, "r": "C", "e": {"correcta": "GLUT3 is a high-affinity, insulin-independent glucose transporter localized specifically to neurons of the brain and to the placenta, ensuring the brain maintains adequate glucose uptake and priority access to circulating glucose independent of insulin status.", "incorrectas": {"A": "GLUT1 is also insulin-independent and present in the brain, but it has a broader distribution including RBCs, placenta, and cornea, unlike GLUT3, which is restricted to brain and placenta specifically.", "B": "GLUT2 is found in beta-islet cells, liver, kidney, and small intestine as a bidirectional low-affinity transporter, an entirely different tissue distribution and function from the brain/placenta-restricted GLUT3.", "D": "GLUT4 is the insulin-DEPENDENT transporter in adipose tissue and muscle, requiring insulin-stimulated translocation, in contrast to the insulin-independent, constitutively active GLUT3."}}}, {"id": "anking-endocrine-physiology-1821", "fuente": "anking", "tema": 23, "anki": "1462809630887", "q": "Which insulin-independent glucose transporter, found in spermatocytes and the GI tract, is primarily responsible for fructose transport?", "o": {"A": "GLUT2", "B": "GLUT3", "C": "GLUT4", "D": "GLUT5"}, "r": "D", "e": {"correcta": "GLUT5 is an insulin-independent transporter primarily responsible for facilitating fructose uptake, and it is expressed in spermatocytes/sperm and in the gastrointestinal tract (enterocytes), where it absorbs dietary fructose.", "incorrectas": {"A": "GLUT2 also has some role in intestinal and hepatic glucose/fructose handling as a bidirectional transporter, but the transporter specifically highlighted for fructose transport in spermatocytes and GI tract is GLUT5, not GLUT2.", "B": "GLUT3 is a high-affinity glucose transporter restricted to the brain and placenta; it is not associated with fructose transport in spermatocytes or the GI tract.", "C": "GLUT4 is the insulin-dependent glucose transporter in muscle and adipose tissue; it is unrelated to fructose transport and not expressed in spermatocytes or gut epithelium in this context."}}}, {"id": "anking-endocrine-physiology-1822", "fuente": "anking", "tema": 23, "anki": "1462809734046", "q": "Overall, the metabolic effects of glucagon are best characterized as which of the following?", "o": {"A": "Anabolic", "B": "Catabolic", "C": "Neutral, no net metabolic effect", "D": "Purely lipogenic"}, "r": "B", "e": {"correcta": "Glucagon is a catabolic, counter-regulatory hormone released from pancreatic alpha cells during fasting or hypoglycemia. It promotes glycogenolysis, gluconeogenesis, ketogenesis, and lipolysis to raise blood glucose and mobilize fuel stores, acting in direct opposition to the anabolic effects of insulin.", "incorrectas": {"A": "Anabolic describes insulin's actions (building glycogen, fat, and protein stores); glucagon instead breaks down these stores to liberate glucose and fatty acids, making it a catabolic rather than anabolic hormone.", "C": "Glucagon has clear, well-defined net catabolic effects (stimulating glycogen breakdown and gluconeogenesis); it does not have a neutral or absent metabolic effect on the body.", "D": "Lipogenesis (fat synthesis) is actually inhibited by glucagon, which instead promotes lipolysis (fat breakdown) to generate free fatty acids and glycerol as fuel sources during fasting states."}}}, {"id": "anking-endocrine-physiology-1823", "fuente": "anking", "tema": 23, "anki": "1462809735089", "q": "A patient sustains blunt chest wall trauma. What is the expected effect on serum prolactin levels?", "o": {"A": "Decreased", "B": "No change", "C": "Increased", "D": "Transiently decreased then normalized"}, "r": "C", "e": {"correcta": "Chest wall trauma, surgery, or herpes zoster affecting the chest wall stimulates the intercostal nerves, activating the same neural reflex pathway used by nipple/breast stimulation, which signals the hypothalamus to reduce dopamine (prolactin inhibitory factor) tone and raise prolactin secretion. This is why breast/chest wall irritation of any cause can produce mild hyperprolactinemia.", "incorrectas": {"A": "Prolactin is not decreased by chest wall trauma; dopamine (the tonic inhibitor of prolactin) would have to increase to lower prolactin, which is not what nerve stimulation from trauma produces.", "B": "There is a real physiologic effect: intercostal nerve stimulation from chest trauma reproduces the nipple-stimulation reflex arc, so prolactin does change rather than staying the same.", "D": "The effect is not transient and self-correcting; as long as the irritating stimulus (trauma, surgical incision, or shingles) persists, the reflex-driven increase in prolactin can persist as well."}}}, {"id": "anking-endocrine-physiology-1824", "fuente": "anking", "tema": 23, "anki": "1462809895863", "q": "A patient with chronic renal failure is found to have elevated serum prolactin. What is the primary mechanism?", "o": {"A": "Increased pituitary prolactin synthesis from uremic stimulation of lactotrophs", "B": "Decreased renal elimination of prolactin", "C": "Loss of dopamine receptors on lactotrophs", "D": "Increased hypothalamic dopamine release"}, "r": "B", "e": {"correcta": "Prolactin is cleared in part by the kidneys, so in renal failure its metabolic clearance is reduced, allowing it to accumulate in the serum even without a change in pituitary secretion rate. This is a classic cause of secondary hyperprolactinemia distinct from a prolactin-secreting adenoma.", "incorrectas": {"A": "Renal failure does not directly stimulate lactotroph synthesis of prolactin; the elevation is due to reduced clearance, not increased production.", "C": "Renal failure does not cause loss of dopamine receptors on lactotrophs; dopamine receptor antagonism (e.g., by antipsychotics) is a separate cause of hyperprolactinemia.", "D": "Increased hypothalamic dopamine release would inhibit, not raise, prolactin secretion, since dopamine is the tonic inhibitory factor for prolactin — the opposite of what is seen in renal failure."}}}, {"id": "anking-gastrointestinal-physiology-1825", "fuente": "anking", "tema": 39, "anki": "1462809930377", "q": "What is the effect of ghrelin, secreted mainly by the stomach fundus, on appetite?", "o": {"A": "Decreased appetite via hypothalamic satiety centers", "B": "Increased appetite", "C": "No direct effect on appetite, only on gastric motility", "D": "Increased appetite only in the fed state"}, "r": "B", "e": {"correcta": "Ghrelin is an orexigenic (appetite-stimulating) hormone released from the stomach, primarily before meals, that signals the arcuate nucleus of the hypothalamus to increase hunger. It also stimulates growth hormone release from the anterior pituitary, linking energy state to growth signaling.", "incorrectas": {"A": "Decreased appetite via satiety signaling describes leptin, which acts in the opposite direction from ghrelin and rises with adiposity rather than fasting.", "C": "Ghrelin does have direct central effects on appetite through hypothalamic neurons (activating NPY/AgRP neurons); it is not limited to peripheral GI motility effects.", "D": "Ghrelin levels actually rise before meals (fasting state) and fall after eating, so its appetite-stimulating effect is most prominent in the fasted, not fed, state."}}}, {"id": "anking-gastrointestinal-physiology-1826", "fuente": "anking", "tema": 39, "anki": "1462810025802", "q": "In a patient experiencing sleep deprivation, what happens to ghrelin secretion?", "o": {"A": "Decreased", "B": "Unchanged", "C": "Increased", "D": "Suppressed to undetectable levels"}, "r": "C", "e": {"correcta": "Sleep deprivation increases ghrelin secretion (along with decreasing leptin), shifting the appetite balance toward hunger and contributing to increased caloric intake and weight gain associated with chronic poor sleep. This hormonal shift is one proposed mechanism linking insufficient sleep to obesity risk.", "incorrectas": {"A": "Ghrelin does not decrease with sleep deprivation; a decrease would reduce hunger drive, which is the opposite of the well-documented appetite increase seen with poor sleep.", "B": "The relationship is not neutral: sleep deprivation reliably alters appetite-regulating hormones, raising ghrelin and lowering leptin, rather than leaving levels unchanged.", "D": "Ghrelin is not suppressed by sleep deprivation; suppression would be inconsistent with the increased hunger and food-seeking behavior observed in sleep-deprived individuals."}}}, {"id": "anking-gastrointestinal-physiology-1827", "fuente": "anking", "tema": 39, "anki": "1462810051900", "q": "Leptin, secreted by adipose tissue in proportion to fat mass, has what effect on appetite?", "o": {"A": "Increased appetite to maintain fat stores", "B": "No effect on appetite, only on reproductive hormone axis", "C": "Decreased appetite", "D": "Increased appetite during starvation only"}, "r": "C", "e": {"correcta": "Leptin acts on the arcuate nucleus of the hypothalamus to suppress appetite and increase energy expenditure, serving as a signal of adequate energy stores. Because leptin is produced by adipocytes proportional to fat mass, higher fat stores normally increase leptin and reduce hunger, providing negative feedback on caloric intake.", "incorrectas": {"A": "Leptin does the opposite of stimulating appetite; it signals satiety and sufficiency of energy stores, decreasing the drive to eat, which is why leptin deficiency (or resistance, as in obesity) is associated with excess hunger.", "B": "While leptin does have permissive effects on the hypothalamic-pituitary-gonadal axis (low leptin can suppress GnRH, as in very low body fat), its primary and most tested role is in appetite suppression, not exclusively reproductive signaling.", "D": "Leptin levels fall during starvation (low fat mass), which removes its appetite-suppressing signal and permits increased hunger — leptin itself is not acting to increase appetite in this state."}}}, {"id": "anking-gastrointestinal-physiology-1828", "fuente": "anking", "tema": 39, "anki": "1462810098191", "q": "In a patient experiencing sleep deprivation, what happens to leptin secretion?", "o": {"A": "Increased", "B": "Decreased", "C": "Unchanged", "D": "Initially decreased, then rebounds above baseline"}, "r": "B", "e": {"correcta": "Sleep deprivation decreases leptin secretion, removing its appetite-suppressing signal. Combined with the concurrent rise in ghrelin, this produces a net increase in hunger and caloric intake, which is one mechanism linking chronic sleep restriction to weight gain.", "incorrectas": {"A": "An increase in leptin would promote satiety and reduce hunger, which contradicts the well-established increased appetite seen with sleep deprivation.", "C": "Leptin levels are not unchanged with sleep deprivation; they measurably decrease alongside a rise in ghrelin, shifting the hunger-satiety balance toward hunger.", "D": "There is no described rebound above baseline; the physiologic finding is a sustained decrease in leptin with ongoing sleep deprivation, not a transient dip followed by overshoot."}}}, {"id": "anking-endocrine-physiology-1829", "fuente": "anking", "tema": 23, "anki": "1462810116955", "q": "Endocannabinoids acting on hypothalamic CB1 receptors have what effect on appetite, classically producing \"the munchies\"?", "o": {"A": "Decreased appetite", "B": "No significant effect on appetite", "C": "Increased appetite", "D": "Decreased appetite only in fasting states"}, "r": "C", "e": {"correcta": "Endocannabinoids stimulate appetite by acting on CB1 receptors in the hypothalamus, increasing food intake and reward-related eating behavior — the physiologic basis for the well-known increase in hunger (\"the munchies\") seen with cannabis use, which activates the same receptors.", "incorrectas": {"A": "A decreased appetite effect describes drugs that antagonize CB1 receptors (such as the withdrawn anti-obesity drug rimonabant), which is the opposite of the orexigenic effect of endogenous endocannabinoid signaling.", "B": "Endocannabinoids have a clear, clinically recognized orexigenic effect; this is why CB1 agonism is used therapeutically to stimulate appetite in conditions like cancer cachexia and HIV wasting.", "D": "The appetite-stimulating effect of endocannabinoids is not restricted to fasting states; it is a general hypothalamic effect that increases hunger and food-seeking behavior regardless of feeding status."}}}, {"id": "anking-endocrine-physiology-1830", "fuente": "anking", "tema": 23, "anki": "1462810148953", "q": "A neonate with ambiguous genitalia and salt-wasting crisis is found to have congenital adrenal hyperplasia with markedly increased plasma renin activity. Which enzyme deficiency is most consistent with this finding?", "o": {"A": "17α-hydroxylase deficiency", "B": "11β-hydroxylase deficiency", "C": "21-hydroxylase deficiency", "D": "Aromatase deficiency"}, "r": "C", "e": {"correcta": "21-hydroxylase deficiency blocks conversion of progesterone and 17-hydroxyprogesterone into mineralocorticoid and glucocorticoid precursors, causing decreased aldosterone and cortisol. The resulting volume depletion and hyponatremia strongly activate the renin-angiotensin system, producing markedly increased plasma renin activity along with salt-wasting and virilization from shunted androgen synthesis.", "incorrectas": {"A": "17α-hydroxylase deficiency causes increased mineralocorticoids (via excess 11-deoxycorticosterone), leading to hypertension and hypokalemia with suppressed, not increased, renin activity.", "B": "11β-hydroxylase deficiency causes accumulation of 11-deoxycorticosterone, a weak mineralocorticoid, which causes volume expansion, hypertension, and low renin activity — the opposite of the salt-wasting, high-renin picture in 21-hydroxylase deficiency.", "D": "Aromatase deficiency impairs conversion of androgens to estrogens and presents with virilization of a female fetus and maternal virilization during pregnancy, but it does not primarily disrupt mineralocorticoid synthesis or renin activity."}}}, {"id": "anking-endocrine-physiology-1831", "fuente": "anking", "tema": 23, "anki": "1462810342552", "q": "A patient with congenital adrenal hyperplasia has hypertension and low plasma renin activity due to accumulation of a mineralocorticoid precursor. Which enzyme is deficient?", "o": {"A": "21-hydroxylase", "B": "3β-hydroxysteroid dehydrogenase", "C": "17α-hydroxylase", "D": "11β-hydroxylase"}, "r": "D", "e": {"correcta": "11β-hydroxylase deficiency causes accumulation of 11-deoxycorticosterone (11-DOC), a precursor with intrinsic mineralocorticoid activity. This drives volume expansion and hypertension, which suppresses renin release, giving the classic combination of low renin activity with hypertension, distinguishing it from the salt-wasting, high-renin picture of 21-hydroxylase deficiency.", "incorrectas": {"A": "21-hydroxylase deficiency causes decreased aldosterone (and cortisol) with resultant salt-wasting, volume depletion, and compensatory increased renin activity — the opposite pattern from 11β-hydroxylase deficiency.", "B": "3β-hydroxysteroid dehydrogenase deficiency impairs synthesis of essentially all classes of adrenal steroids (mineralocorticoids, glucocorticoids, and androgens), typically causing salt-wasting rather than the hypertensive, low-renin picture.", "C": "17α-hydroxylase deficiency does cause hypertension and low renin from excess 11-DOC as well, but it is distinguished from 11β-hydroxylase deficiency by absent sex steroid production, causing sexual infantilism/ambiguous genitalia rather than virilization."}}}, {"id": "anking-metabolism-1832", "fuente": "anking", "tema": 13, "anki": "1462810386376", "q": "Considering its effects on gluconeogenesis, lipolysis, and proteolysis, cortisol's overall metabolic action is best characterized as which of the following?", "o": {"A": "Anabolic", "B": "Catabolic", "C": "Purely anti-inflammatory with no metabolic effect", "D": "Anabolic in muscle, catabolic only in adipose tissue"}, "r": "B", "e": {"correcta": "Cortisol is overall catabolic: it increases hepatic gluconeogenesis, stimulates lipolysis in adipose tissue to mobilize free fatty acids, and promotes proteolysis in muscle to supply amino acid substrates for gluconeogenesis. This combination raises blood glucose during stress at the expense of breaking down stored fat and protein.", "incorrectas": {"A": "An anabolic hormone would promote synthesis and storage of glycogen, fat, and protein; cortisol does the opposite, breaking down these stores to raise blood glucose during stress.", "C": "Cortisol's anti-inflammatory and immunosuppressive properties are well known, but it also has prominent, clinically important metabolic (catabolic) effects on glucose, lipid, and protein metabolism that are heavily tested.", "D": "Cortisol's catabolic action is not restricted to adipose tissue; it also promotes muscle proteolysis and hepatic gluconeogenesis, making its overall systemic effect catabolic rather than tissue-selective anabolism."}}}, {"id": "anking-endocrine-physiology-1833", "fuente": "anking", "tema": 23, "anki": "1462810615371", "q": "PTH binds to which cell type to trigger RANK-L secretion, which then binds RANK on osteoclasts to increase bone resorption?", "o": {"A": "Osteocytes", "B": "Chondrocytes", "C": "Osteoclast precursors directly", "D": "Osteoblasts"}, "r": "D", "e": {"correcta": "PTH receptors are located on osteoblasts, not osteoclasts. When PTH binds osteoblasts, it induces them to express RANK-L (and M-CSF), which then binds RANK on osteoclast precursors, promoting their differentiation and activity, thereby increasing bone resorption and releasing calcium into the blood.", "incorrectas": {"A": "Osteocytes are mature bone cells embedded in the matrix that primarily sense mechanical strain and regulate phosphate via FGF23/sclerostin signaling; they are not the primary target of PTH in the RANK-L pathway described here.", "B": "Chondrocytes are cartilage-forming cells involved in endochondral ossification and growth plate biology, not the cell type through which PTH stimulates osteoclastic bone resorption.", "C": "Osteoclasts (and their precursors) do not have PTH receptors; they respond indirectly to PTH via RANK-L presented by osteoblasts, which is the key concept tested by this pathway."}}}, {"id": "anking-endocrine-physiology-1834", "fuente": "anking", "tema": 23, "anki": "1462810965063", "q": "Which two hormones act together to increase linear bone growth, with growth hormone driving proliferation and thyroid hormone driving maturation/growth of the epiphyseal plate?", "o": {"A": "Growth hormone and cortisol", "B": "Insulin and thyroid hormone", "C": "Growth hormone and thyroid hormone", "D": "IGF-1 and PTH"}, "r": "C", "e": {"correcta": "Growth hormone (via IGF-1) stimulates chondrocyte proliferation at the epiphyseal growth plate, while thyroid hormone is required for the maturation and ossification steps of bone growth. Both hormones are necessary for normal linear growth, and deficiency of either (e.g., congenital hypothyroidism or GH deficiency) impairs a child's growth.", "incorrectas": {"A": "Cortisol is catabolic and, especially in excess (e.g., Cushing syndrome or chronic steroid use), impairs linear growth in children by inhibiting collagen synthesis and growth plate activity rather than promoting bone growth.", "B": "Insulin supports fetal growth and has some anabolic effects, but it is not one of the two classic hormones (GH and thyroid hormone) highlighted as driving postnatal bone growth at the growth plate.", "D": "IGF-1 is the mediator of growth hormone's effects, so pairing it with PTH does not represent the two independent classic hormonal axes (GH and thyroid hormone) responsible for bone growth; PTH's main role is calcium homeostasis, not growth-plate maturation."}}}, {"id": "anking-metabolism-1835", "fuente": "anking", "tema": 13, "anki": "1462811101121", "q": "With effects including increased glycogenolysis, gluconeogenesis, and lipolysis, the overall metabolic effect of thyroid hormone is best described as which of the following?", "o": {"A": "Anabolic", "B": "Catabolic", "C": "Neutral, only affecting basal metabolic rate without substrate effects", "D": "Anabolic in the liver, catabolic in muscle only"}, "r": "B", "e": {"correcta": "Thyroid hormone increases the basal metabolic rate and has overall catabolic effects: it stimulates glycogenolysis and gluconeogenesis to raise blood glucose, and promotes lipolysis to mobilize fatty acids for oxidation, supporting increased oxygen consumption and heat production (calorigenic effect).", "incorrectas": {"A": "An anabolic characterization would imply net synthesis and storage of glycogen and fat; thyroid hormone instead promotes their breakdown to fuel the increased metabolic rate it induces.", "C": "Thyroid hormone's calorigenic effect is tightly linked to its substrate-mobilizing actions (glycogenolysis, gluconeogenesis, lipolysis) that supply the fuel for increased oxygen consumption — the two are not separable as suggested.", "D": "Thyroid hormone's catabolic effects are not confined to muscle; it also promotes gluconeogenesis and glycogenolysis in the liver and lipolysis in adipose tissue, making its overall systemic effect catabolic across tissues."}}}, {"id": "anking-endocrine-physiology-1836", "fuente": "anking", "tema": 23, "anki": "1462811217109", "q": "A hormone panel is being reviewed for second-messenger signaling. Which of the following hormones signals primarily through cAMP as its second messenger?", "o": {"A": "GnRH", "B": "Oxytocin", "C": "ACTH", "D": "Angiotensin II"}, "r": "C", "e": {"correcta": "ACTH is one of the classic Gs-coupled, cAMP-signaling hormones (mnemonic FLAT ChAMP's CHuGG: FSH, LH, ACTH, TSH, CRH, hCG, ADH at V2, MSH, PTH, Calcitonin, Histamine at H2, Glucagon, GHRH). Binding activates adenylyl cyclase, raising intracellular cAMP, which activates protein kinase A to mediate cortisol synthesis in the adrenal cortex.", "incorrectas": {"B": "Oxytocin signals through the IP3/Gq pathway (mnemonic GOAT HAG: GnRH, Oxytocin, ADH at V1, TRH, Histamine at H1, Angiotensin II, Gastrin), leading to increased intracellular calcium rather than cAMP.", "A": "GnRH also uses the IP3/Gq pathway, not cAMP, stimulating gonadotroph calcium signaling to release FSH and LH — it is grouped with oxytocin and angiotensin II in the IP3 category, not the cAMP category.", "D": "Angiotensin II acts via AT1 receptors coupled to Gq and the IP3 pathway to cause vasoconstriction and aldosterone release, placing it in the IP3 second-messenger group rather than the cAMP group."}}}, {"id": "anking-endocrine-physiology-1837", "fuente": "anking", "tema": 23, "anki": "1462811651513", "q": "Which group of molecules signals through cGMP as their second messenger via guanylyl cyclase receptors?", "o": {"A": "ANP, BNP, and nitric oxide", "B": "TSH, ACTH, and glucagon", "C": "GnRH, oxytocin, and gastrin", "D": "Insulin, GH, and prolactin"}, "r": "A", "e": {"correcta": "ANP and BNP act through membrane-bound guanylyl cyclase receptors, while nitric oxide activates soluble (cytosolic) guanylyl cyclase; both pathways raise intracellular cGMP, which activates protein kinase G. These are the classic cGMP-signaling molecules, functionally linked as vasodilators/natriuretic factors that promote smooth muscle relaxation and vasodilation.", "incorrectas": {"B": "TSH, ACTH, and glucagon are classic Gs-coupled hormones that signal via adenylyl cyclase and cAMP, not the guanylyl cyclase/cGMP pathway used by the natriuretic peptides and nitric oxide.", "C": "GnRH, oxytocin, and gastrin signal through Gq-coupled receptors activating phospholipase C and the IP3/calcium pathway, a distinct second-messenger system from cGMP.", "D": "Insulin, GH, and prolactin signal through receptor tyrosine kinase or JAK/STAT-associated pathways, not through cyclic nucleotide second messengers like cGMP."}}}, {"id": "anking-endocrine-physiology-1838", "fuente": "anking", "tema": 23, "anki": "1462811666951", "q": "Which of the following hormones signals through IP3/Gq (mnemonic GOAT HAG) as its second-messenger pathway?", "o": {"A": "TSH", "B": "GHRH", "C": "Gastrin", "D": "Calcitonin"}, "r": "C", "e": {"correcta": "Gastrin is part of the GOAT HAG group (GnRH, Oxytocin, ADH at V1, TRH, Histamine at H1, Angiotensin II, Gastrin) that signals through Gq-coupled receptors, activating phospholipase C to generate IP3 and DAG, which raises intracellular calcium and activates protein kinase C.", "incorrectas": {"A": "TSH is part of the cAMP-signaling group (FLAT ChAMP's CHuGG), acting through Gs-coupled receptors and adenylyl cyclase rather than the Gq/IP3 pathway.", "B": "GHRH also belongs to the cAMP-signaling group, stimulating somatotroph GH release via a Gs/adenylyl cyclase/cAMP mechanism, not IP3.", "D": "Calcitonin is likewise a cAMP-signaling hormone (part of FLAT ChAMP's CHuGG), acting on Gs-coupled receptors in osteoclasts to inhibit bone resorption, distinct from the IP3 pathway."}}}, {"id": "anking-endocrine-physiology-1839", "fuente": "anking", "tema": 23, "anki": "1462811678102", "q": "Which two classic anterior pituitary hormones signal through receptor-associated (JAK2-linked) tyrosine kinase receptors rather than cAMP, IP3, or steroid nuclear receptors?", "o": {"A": "FSH and LH", "B": "ACTH and TSH", "C": "Prolactin and growth hormone", "D": "Oxytocin and ADH"}, "r": "C", "e": {"correcta": "Prolactin and growth hormone both signal through receptors lacking intrinsic kinase activity that instead associate with JAK2, a cytoplasmic tyrosine kinase, activating the JAK/STAT pathway. This same receptor class is shared by cytokines (e.g., IL-2, IL-6) and hematopoietic growth factors (erythropoietin, thrombopoietin, G-CSF), reflecting a common evolutionary signaling strategy for growth and immune regulation.", "incorrectas": {"A": "FSH and LH are glycoprotein hormones that signal through Gs-coupled receptors and the cAMP pathway, not through JAK2-associated tyrosine kinase receptors.", "B": "ACTH and TSH are also classic Gs-coupled, cAMP-signaling hormones (part of FLAT ChAMP's CHuGG), distinct from the tyrosine kinase-associated receptors used by prolactin and GH.", "D": "Oxytocin and ADH (via V1 receptors) signal through the Gq/IP3/calcium pathway; ADH acting at V2 receptors uses cAMP — neither uses the JAK2-tyrosine kinase mechanism."}}}, {"id": "anking-reproductive-system-physiology-1840", "fuente": "anking", "tema": 32, "anki": "1462811683463", "q": "A woman has decreased sex hormone-binding globulin (SHBG), for example due to obesity or PCOS. What clinical finding results from the accompanying rise in free testosterone?", "o": {"A": "Gynecomastia", "B": "Hirsutism", "C": "Amenorrhea from estrogen excess", "D": "Galactorrhea"}, "r": "B", "e": {"correcta": "SHBG preferentially binds androgens over estrogens, so when SHBG levels fall, a larger fraction of circulating testosterone remains free (biologically active). This increase in free testosterone in women produces androgenic effects such as hirsutism (excess terminal hair growth in a male pattern), a common finding in conditions like PCOS where SHBG is often reduced due to insulin resistance.", "incorrectas": {"A": "Gynecomastia results from increased free estrogen relative to androgen action in men, typically from increased SHBG (which binds androgens more tightly, raising free estrogen) — the opposite scenario from decreased SHBG causing hirsutism in women.", "C": "Amenorrhea from estrogen excess is not the expected consequence of decreased SHBG in women; decreased SHBG raises free androgen (not estrogen) activity, driving virilizing changes like hirsutism rather than estrogen-mediated menstrual changes.", "D": "Galactorrhea is driven by hyperprolactinemia, not by changes in SHBG or free testosterone; it is not the classic finding associated with low SHBG in women."}}}, {"id": "anking-reproductive-system-physiology-1841", "fuente": "anking", "tema": 32, "anki": "1462811818195", "q": "A man is found to have increased sex hormone-binding globulin (SHBG), for example due to liver disease or aging. What clinical finding results from the accompanying fall in free testosterone?", "o": {"A": "Hirsutism", "B": "Precocious puberty", "C": "Gynecomastia", "D": "Virilization"}, "r": "C", "e": {"correcta": "SHBG binds androgens more avidly than estrogens, so when SHBG rises, a greater proportion of circulating testosterone becomes bound and inactive, decreasing free testosterone while relatively sparing free estrogen. This shifts the androgen-to-estrogen balance toward estrogen effect in men, producing gynecomastia, commonly seen in conditions like cirrhosis where SHBG is elevated.", "incorrectas": {"A": "Hirsutism is a manifestation of androgen excess in women, typically from decreased (not increased) SHBG raising free testosterone; it is not the expected finding in a man with elevated SHBG and reduced free testosterone.", "B": "Precocious puberty relates to early activation of the hypothalamic-pituitary-gonadal axis, unrelated to the SHBG-mediated shift in free hormone availability described here.", "D": "Virilization refers to the development of male secondary sexual characteristics due to androgen excess, the opposite of what occurs when increased SHBG lowers free testosterone and promotes relatively greater estrogen effect."}}}, {"id": "anking-endocrine-pathology-1842", "fuente": "anking", "tema": 5, "anki": "1462811819671", "q": "A patient with adrenal insufficiency reports strong cravings for salty and sugary foods. What is the underlying mechanism?", "o": {"A": "Decreased levels of glucocorticoids and/or mineralocorticoids", "B": "Excess ACTH causing direct hypothalamic appetite stimulation", "C": "Hyperkalemia-induced taste changes", "D": "Compensatory hyperglycemia from unopposed catecholamines"}, "r": "A", "e": {"correcta": "In adrenal insufficiency, decreased cortisol impairs normal glucose homeostasis (contributing to hypoglycemia and sugar craving), while decreased aldosterone causes renal sodium wasting and volume depletion, which drives salt craving as the body attempts to restore sodium balance. This combination of sugar and salt cravings is a classic symptom of primary adrenal insufficiency (Addison disease).", "incorrectas": {"B": "While ACTH is elevated in primary adrenal insufficiency (due to loss of cortisol negative feedback) and contributes to hyperpigmentation, it is not the direct mechanism proposed for salt and sugar cravings, which instead stem from the downstream hormone deficiencies themselves.", "C": "Hyperkalemia does occur in aldosterone deficiency, but it does not act through a taste-alteration mechanism to produce cravings; the cravings are better explained by the physiologic drive to correct sodium and glucose deficits.", "D": "Adrenal insufficiency is characterized by hypoglycemia (from cortisol deficiency), not hyperglycemia, and catecholamine excess is not the mechanism behind the salt and sugar craving symptom."}}}, {"id": "anking-endocrine-pathology-1843", "fuente": "anking", "tema": 5, "anki": "1462812278781", "q": "A patient with primary adrenal insufficiency (Addison disease) develops hyperpigmentation. Which two areas are classically most affected?", "o": {"A": "Palms and soles only", "B": "Nail beds and hair", "C": "Skin and mucous membranes", "D": "Sclera and conjunctiva"}, "r": "C", "e": {"correcta": "In primary adrenal insufficiency, loss of cortisol negative feedback causes markedly increased ACTH, which is derived from the same POMC precursor as melanocyte-stimulating hormone (MSH). Elevated POMC-derived peptides stimulate melanocytes, producing diffuse hyperpigmentation most notable in the skin (especially sun-exposed areas, skin folds, and scars) and mucous membranes (such as the gums and buccal mucosa).", "incorrectas": {"A": "Palms and soles are not singled out as the classic distribution; hyperpigmentation in Addison disease is more diffuse, notably involving mucous membranes and skin creases/sun-exposed areas, not restricted to palms and soles.", "B": "Nail bed and hair changes are not the characteristic finding of ACTH-driven hyperpigmentation in Addison disease; the classic finding is generalized skin darkening plus mucosal pigmentation.", "D": "Scleral or conjunctival pigmentation is not the classic distribution taught for Addison disease; the disease's pathognomonic finding is bronze-colored skin plus oral/mucosal pigmentation."}}}, {"id": "anking-endocrine-pathology-1844", "fuente": "anking", "tema": 5, "anki": "1462812673994", "q": "An 18-month-old presents with an abdominal mass. Which tumor is the most common neoplasm of the adrenal medulla in children?", "o": {"A": "Pheochromocytoma", "B": "Adrenocortical carcinoma", "C": "Wilms tumor", "D": "Neuroblastoma"}, "r": "D", "e": {"correcta": "Neuroblastoma is the most common adrenal medullary tumor of childhood, arising from neural crest-derived sympathetic precursor cells, with a median age of diagnosis around 18 months. It classically presents as an abdominal mass that can cross the midline and secretes catecholamine metabolites (HVA, VMA), unlike pheochromocytoma which is rare in this age group.", "incorrectas": {"A": "Pheochromocytoma is a catecholamine-secreting tumor of chromaffin cells but is much less common than neuroblastoma in children and typically presents later, with episodic hypertension, palpitations, and diaphoresis rather than as an infant abdominal mass.", "B": "Adrenocortical carcinoma arises from the adrenal cortex, not the medulla, and typically presents with hormone excess syndromes (e.g., Cushing syndrome, virilization) rather than as the classic medullary tumor of infancy.", "C": "Wilms tumor is a renal (not adrenal) tumor arising from nephrogenic blastema, presenting as an abdominal mass in young children, but it is a distinct entity from neuroblastoma and does not arise from the adrenal medulla."}}}, {"id": "anking-endocrine-pathology-1845", "fuente": "anking", "tema": 5, "anki": "1462818125916", "q": "A young child with neuroblastoma develops rapid, chaotic eye movements and myoclonic jerks, described as \"dancing eyes, dancing feet.\" What is this paraneoplastic syndrome called?", "o": {"A": "Lambert-Eaton myasthenic syndrome", "B": "Opsoclonus-myoclonus syndrome", "C": "Horner syndrome", "D": "Cerebellar ataxia-telangiectasia"}, "r": "B", "e": {"correcta": "Opsoclonus-myoclonus syndrome is a paraneoplastic phenomenon associated with neuroblastoma, thought to be immune-mediated (antibodies cross-reacting with neuronal tissue), presenting with rapid multidirectional eye movements (opsoclonus) and myoclonic jerks, giving rise to the memorable description \"dancing eyes, dancing feet.\"", "incorrectas": {"A": "Lambert-Eaton myasthenic syndrome is a paraneoplastic disorder of neuromuscular transmission (antibodies against presynaptic voltage-gated calcium channels) classically associated with small cell lung cancer, not neuroblastoma, and presents with proximal muscle weakness rather than opsoclonus-myoclonus.", "C": "Horner syndrome (ptosis, miosis, anhidrosis) can occur with neuroblastoma due to involvement of the cervical sympathetic chain, but it is a distinct clinical finding from the opsoclonus-myoclonus paraneoplastic syndrome described here.", "D": "Ataxia-telangiectasia is an inherited DNA repair disorder causing cerebellar ataxia and telangiectasias, unrelated to neuroblastoma or the paraneoplastic opsoclonus-myoclonus phenomenon."}}}, {"id": "anking-endocrine-pathology-1846", "fuente": "anking", "tema": 5, "anki": "1462818414312", "q": "Which two serum markers are characteristically elevated in neuroblastoma?", "o": {"A": "Alpha-fetoprotein and beta-hCG", "B": "CA-125 and CEA", "C": "Bombesin and neuron-specific enolase", "D": "Chromogranin A and calcitonin"}, "r": "C", "e": {"correcta": "Neuroblastoma, arising from primitive neural crest cells, characteristically elevates bombesin (a neuropeptide) and neuron-specific enolase (NSE), a glycolytic enzyme found in neurons and neuroendocrine cells, both reflecting the tumor's neural origin and helping support the diagnosis alongside imaging and catecholamine metabolites.", "incorrectas": {"A": "Alpha-fetoprotein and beta-hCG are markers used for germ cell tumors (e.g., yolk sac tumor, choriocarcinoma), not the classic markers associated with neuroblastoma.", "B": "CA-125 and CEA are tumor markers associated with ovarian cancer and colorectal/other adenocarcinomas respectively, not with neuroblastoma.", "D": "Chromogranin A is a general neuroendocrine marker and calcitonin is specific to medullary thyroid carcinoma (C cells); neither is the specific pairing of markers classically taught for neuroblastoma (bombesin and NSE)."}}}, {"id": "anking-endocrine-pathology-1847", "fuente": "anking", "tema": 5, "anki": "1462818499640", "q": "Urine testing in a child with suspected neuroblastoma is most likely to show increased levels of which catecholamine metabolites?", "o": {"A": "Metanephrine and normetanephrine only", "B": "5-HIAA and serotonin", "C": "Homovanillic acid (HVA) and vanillylmandelic acid (VMA)", "D": "Dopamine and epinephrine (unmetabolized)"}, "r": "C", "e": {"correcta": "Neuroblastoma cells synthesize and metabolize catecholamines, leading to increased urinary excretion of their breakdown products, HVA (a dopamine metabolite) and VMA (a norepinephrine/epinephrine metabolite). Measuring these urinary metabolites is a key diagnostic test, analogous to how metanephrines are used for pheochromocytoma.", "incorrectas": {"A": "Metanephrine and normetanephrine are the classic urinary/plasma metabolites measured for pheochromocytoma, not the specific pairing (HVA and VMA) taught for neuroblastoma, although both tumors are catecholamine-related.", "B": "5-HIAA is the metabolite of serotonin used to diagnose carcinoid syndrome, not neuroblastoma; serotonin and 5-HIAA are unrelated to the catecholamine pathway tested in neuroblastoma.", "D": "Catecholamines themselves are rapidly metabolized and are not the primary diagnostic urine test; it is their breakdown products (HVA, VMA), not unmetabolized dopamine and epinephrine, that are measured."}}}, {"id": "anking-endocrine-pathology-1848", "fuente": "anking", "tema": 5, "anki": "1462818528144", "q": "A thyroid adenoma, thyroid cancer, or thyroid cyst is most likely to produce which type of goiter on physical exam?", "o": {"A": "Diffuse goiter", "B": "Nodular goiter", "C": "Substernal goiter without palpable enlargement", "D": "Colloid goiter"}, "r": "B", "e": {"correcta": "Focal thyroid lesions such as adenomas, carcinomas, and cysts present as discrete, palpable nodules within the gland, producing a nodular goiter pattern (which can be uninodular or, when multiple nodules coexist as in toxic multinodular goiter, multinodular). This contrasts with diffuse processes that enlarge the entire gland uniformly.", "incorrectas": {"A": "A diffuse goiter reflects uniform enlargement of the entire thyroid gland, as seen in Graves disease or simple/colloid goiter from iodine deficiency, rather than the discrete focal lesions produced by adenomas, cancers, or cysts.", "C": "A substernal goiter refers to downward extension of an enlarged thyroid into the mediastinum, which is a description of location, not the nodular character produced by adenomas, cancer, or cysts.", "D": "Colloid goiter describes diffuse enlargement due to colloid accumulation, typically from iodine deficiency or compensatory TSH stimulation, not the discrete nodular lesions produced by adenomas, cancer, or cysts."}}}, {"id": "anking-renal-pathology-1849", "fuente": "anking", "tema": 58, "anki": "1462818806593", "q": "A patient has mild, asymptomatic hypercalcemia with hypocalciuria and a normal-to-mildly-elevated PTH level. Genetic testing reveals a defective calcium-sensing receptor (CaSR). What is the diagnosis?", "o": {"A": "Primary hyperparathyroidism", "B": "Familial hypocalciuric hypercalcemia", "C": "Vitamin D toxicity", "D": "Multiple myeloma-associated hypercalcemia"}, "r": "B", "e": {"correcta": "Familial hypocalciuric hypercalcemia is caused by an inactivating mutation in the calcium-sensing receptor (CaSR), which raises the calcium set-point in the parathyroid glands and renal tubules. This produces mild hypercalcemia with inappropriately normal-to-high PTH and, importantly, hypocalciuria (rather than the hypercalciuria expected with hypercalcemia), because the kidneys also perceive calcium levels as lower than they truly are and reabsorb it.", "incorrectas": {"A": "Primary hyperparathyroidism also causes hypercalcemia with elevated PTH, but it typically causes hypercalciuria (increased urinary calcium excretion) rather than the hypocalciuria that distinguishes FHH, since the CaSR defect is what specifically causes excess renal calcium reabsorption in FHH.", "C": "Vitamin D toxicity causes hypercalcemia through increased intestinal calcium absorption, with suppressed (not normal/elevated) PTH due to negative feedback, and it does not involve a CaSR mutation or the classic hypocalciuria of FHH.", "D": "Multiple myeloma causes hypercalcemia via osteoclast-activating factors and bone destruction with appropriately suppressed PTH, a very different mechanism from the CaSR-mediated benign familial condition described here."}}}, {"id": "anking-endocrine-pathology-1850", "fuente": "anking", "tema": 5, "anki": "1462819175860", "q": "What is the most common cause of hypoparathyroidism in adults?", "o": {"A": "Autoimmune destruction", "B": "DiGeorge syndrome", "C": "Surgical excision (e.g., inadvertent removal during thyroidectomy)", "D": "Metastatic infiltration of the parathyroid glands"}, "r": "C", "e": {"correcta": "The most common cause of hypoparathyroidism is inadvertent surgical damage or removal of the parathyroid glands, most often during thyroid surgery, given their close anatomic proximity. This leads to acute hypocalcemia (tetany, perioral numbness, Chvostek/Trousseau signs) due to loss of PTH's calcium-raising actions on bone, kidney, and vitamin D activation.", "incorrectas": {"A": "Autoimmune destruction of the parathyroid glands is a recognized cause of hypoparathyroidism (sometimes as part of autoimmune polyendocrine syndrome type 1), but it is less common overall than surgical injury/removal.", "B": "DiGeorge syndrome causes congenital hypoparathyroidism due to failure of the third and fourth pharyngeal pouches to develop (along with thymic aplasia and cardiac defects), but this congenital cause is far less common than acquired surgical hypoparathyroidism in the general population.", "D": "Metastatic infiltration of the parathyroid glands is a rare cause of hypoparathyroidism and is not among the commonly tested or clinically frequent etiologies compared to surgical excision."}}}, {"id": "anking-neurology-special-senses-pathology-1851", "fuente": "anking", "tema": 9, "anki": "1462832275222", "q": "A patient requires surgical removal of a pituitary adenoma. Which surgical approach is typically used?", "o": {"A": "Craniotomy with frontal lobe retraction", "B": "Transsphenoidal resection", "C": "Transorbital approach", "D": "Stereotactic radiosurgery only, without resection"}, "r": "B", "e": {"correcta": "Pituitary adenomas are most commonly removed via transsphenoidal resection, in which the surgeon accesses the sella turcica through the nasal cavity and sphenoid sinus. This minimally invasive route avoids open craniotomy and takes advantage of the pituitary gland's midline location just above the sphenoid sinus.", "incorrectas": {"A": "Craniotomy with brain retraction is a more invasive approach reserved for tumors not amenable to transsphenoidal access (e.g., large tumors with significant lateral or suprasellar extension), not the standard first-line approach for typical pituitary adenomas.", "C": "A transorbital approach is not the standard route for pituitary surgery; the pituitary's anatomic relationship to the sphenoid sinus makes the transsphenoidal route the natural and preferred corridor.", "D": "Stereotactic radiosurgery is a nonsurgical treatment option sometimes used for residual or recurrent tumors, or when surgery is contraindicated, but it is not the standard primary surgical approach and does not involve resection at all."}}}, {"id": "anking-endocrine-pathology-1852", "fuente": "anking", "tema": 5, "anki": "1462832847050", "q": "A child with proportional short stature is found to have elevated growth hormone but low IGF-1 levels. What is the diagnosis?", "o": {"A": "Growth hormone deficiency", "B": "Laron syndrome", "C": "Achondroplasia", "D": "Panhypopituitarism"}, "r": "B", "e": {"correcta": "Laron syndrome (Laron dwarfism) results from a defective growth hormone receptor, so despite elevated GH levels, the liver cannot respond to generate IGF-1, leading to low IGF-1 and proportional short stature. This is a classic example of hormone resistance rather than hormone deficiency.", "incorrectas": {"A": "Growth hormone deficiency would present with low GH and consequently low IGF-1, the opposite pattern from Laron syndrome, where GH is elevated due to loss of negative feedback from IGF-1.", "C": "Achondroplasia is caused by an activating FGFR3 mutation impairing endochondral ossification, producing disproportionate dwarfism (short limbs, normal trunk), unlike the proportional dwarfism and GH receptor defect seen in Laron syndrome.", "D": "Panhypopituitarism involves deficiency of multiple anterior pituitary hormones (including GH itself), so GH levels would be low, not elevated, distinguishing it from Laron syndrome's peripheral GH resistance."}}}, {"id": "anking-endocrine-pathology-1853", "fuente": "anking", "tema": 5, "anki": "1462832850088", "q": "A child presents with short stature, small head circumference, a saddle nose, prominent forehead, small genitalia, and delayed skeletal maturation, with proportional body segments. Which condition is most consistent with this presentation?", "o": {"A": "Achondroplasia", "B": "Laron syndrome", "C": "Turner syndrome", "D": "Constitutional growth delay"}, "r": "B", "e": {"correcta": "Laron syndrome results from a growth hormone receptor defect causing GH resistance, producing proportional dwarfism with characteristic facial features (saddle nose, prominent forehead), small genitalia, and delayed bone maturation, all while growth hormone levels remain elevated (with low IGF-1) due to loss of negative feedback.", "incorrectas": {"A": "Achondroplasia produces disproportionate dwarfism, with shortened limbs relative to a normal-sized trunk and head, due to an FGFR3 gain-of-function mutation impairing cartilage growth — a distinctly different body habitus from the proportional dwarfism of Laron syndrome.", "C": "Turner syndrome (45,X) presents with short stature, webbed neck, and streak gonads in phenotypic females, but it is a chromosomal disorder, not a growth hormone receptor defect, and does not typically present with the specific facies described here.", "D": "Constitutional growth delay is a normal variant in which children are temporarily short with delayed bone age but eventually reach a normal adult height, without the distinctive facial features, small genitalia, or GH receptor defect characteristic of Laron syndrome."}}}, {"id": "anking-endocrine-pathology-1854", "fuente": "anking", "tema": 5, "anki": "1462833348246", "q": "A patient develops sudden severe headache, visual field impairment, and features of hypopituitarism. What is this presentation, classically caused by hemorrhage or infarction of a pituitary adenoma, called?", "o": {"A": "Cavernous sinus thrombosis", "B": "Sheehan syndrome", "C": "Pituitary apoplexy", "D": "Empty sella syndrome"}, "r": "C", "e": {"correcta": "Pituitary apoplexy is an endocrine emergency resulting from sudden hemorrhage or infarction, typically within a preexisting pituitary adenoma, causing acute expansion of the sella contents. This produces sudden severe headache, compression of the optic chiasm (classically bitemporal hemianopsia or diplopia from cavernous sinus involvement), and acute hypopituitarism requiring urgent glucocorticoid replacement and often surgical decompression.", "incorrectas": {"A": "Cavernous sinus thrombosis presents with cranial nerve palsies (III, IV, V1/V2, VI), proptosis, and chemosis from venous congestion, typically related to infection, rather than hemorrhagic infarction of a pituitary tumor with hypopituitarism.", "B": "Sheehan syndrome is postpartum pituitary infarction resulting from severe obstetric hemorrhage and hypotension, presenting with hypopituitarism (notably failure to lactate), but it is a specific peripartum entity distinct from apoplexy occurring within a pre-existing adenoma.", "D": "Empty sella syndrome refers to herniation of the subarachnoid space into the sella turcica, flattening the pituitary gland, which is often an incidental finding and does not typically present with the acute headache and visual symptoms of apoplexy."}}}, {"id": "anking-endocrine-pathology-1855", "fuente": "anking", "tema": 5, "anki": "1462833395284", "q": "Carcinoid syndrome, caused by serotonin-secreting neuroendocrine tumors, is classically associated with which epidemiologic pattern?", "o": {"A": "The \"rule of 2s\"", "B": "The \"rule of 9s\"", "C": "The \"rule of 1/3s\"", "D": "The \"rule of 10s\""}, "r": "C", "e": {"correcta": "Carcinoid tumors follow the classic \"rule of 1/3s\": roughly one-third are multiple, one-third metastasize, one-third are associated with a second malignancy, one-third present with carcinoid syndrome, and about one-third occur outside the GI tract, reflecting the variable behavior and distribution of these neuroendocrine tumors.", "incorrectas": {"A": "The \"rule of 2s\" is the classic mnemonic for Meckel diverticulum (2% of population, within 2 feet of the ileocecal valve, 2 inches long, presents by age 2, etc.), not carcinoid tumors.", "B": "The \"rule of 9s\" is used to estimate total body surface area involved in burns, an entirely unrelated clinical tool with no connection to carcinoid tumor epidemiology.", "D": "There is no classic \"rule of 10s\" taught for carcinoid syndrome; this is sometimes confused with the classic \"10% tumor\" teaching historically applied to pheochromocytoma, which is a different tumor entirely."}}}, {"id": "anking-genetics-1856", "fuente": "anking", "tema": 45, "anki": "1462833649683", "q": "What is the pattern of inheritance for all of the multiple endocrine neoplasia (MEN) syndromes?", "o": {"A": "Autosomal recessive", "B": "Autosomal dominant", "C": "X-linked recessive", "D": "Mitochondrial"}, "r": "B", "e": {"correcta": "All MEN syndromes (MEN1, MEN2A, and MEN2B) are inherited in an autosomal dominant pattern. MEN1 results from mutations in the MEN1 tumor suppressor gene (menin), while MEN2A and MEN2B result from gain-of-function mutations in the RET proto-oncogene, but all share the same dominant inheritance pattern, meaning an affected parent has a 50% chance of passing the mutation to each child.", "incorrectas": {"A": "Autosomal recessive inheritance would require two mutated alleles for disease expression, but MEN syndromes are caused by single mutant alleles being sufficient to cause disease (dominant), often via haploinsufficiency (MEN1) or constitutive receptor activation (RET in MEN2).", "C": "X-linked recessive inheritance would predominantly affect males and involve genes on the X chromosome; the MEN1 and RET genes are both autosomal, and the pattern of inheritance for MEN syndromes is not sex-linked.", "D": "Mitochondrial inheritance follows maternal transmission and affects genes in mitochondrial DNA; MEN syndromes are caused by nuclear gene mutations (MEN1, RET) with straightforward autosomal dominant transmission, not maternal-only inheritance."}}}, {"id": "anking-endocrine-pathology-1857", "fuente": "anking", "tema": 5, "anki": "1462834082547", "q": "Which three organs are classically involved in multiple endocrine neoplasia type 1 (MEN1), remembered as the \"3 P's\"?", "o": {"A": "Pituitary, parathyroid, and pheochromocytoma", "B": "Pancreas, parathyroid, and pheochromocytoma", "C": "Pituitary, pancreas, and parathyroid", "D": "Parathyroid, pancreas, and papillary thyroid carcinoma"}, "r": "C", "e": {"correcta": "MEN1 (caused by mutation in the MEN1 tumor suppressor gene, menin) classically involves the \"3 P's\": pituitary adenomas (often prolactinoma), pancreatic endocrine tumors (e.g., gastrinoma causing Zollinger-Ellison syndrome, insulinoma), and parathyroid hyperplasia/adenomas causing primary hyperparathyroidism, which is typically the most common and earliest manifestation.", "incorrectas": {"A": "Pheochromocytoma is a feature of MEN2A and MEN2B (arising from adrenal medullary chromaffin cells due to RET mutations), not MEN1, which does not typically feature pheochromocytoma.", "B": "This combination substitutes pheochromocytoma for pituitary involvement, but pheochromocytoma belongs to the MEN2 syndromes, while pituitary adenoma (not pheochromocytoma) is the correct third component of the MEN1 triad.", "D": "Papillary thyroid carcinoma is not part of the MEN1 or MEN2 syndromes (MEN2 involves medullary thyroid carcinoma, not papillary), and pituitary adenoma, not thyroid carcinoma, is the third classic component of MEN1."}}}, {"id": "anking-endocrine-pathology-1858", "fuente": "anking", "tema": 5, "anki": "1462834233055", "q": "Parathyroid adenomas (leading to hyperparathyroidism) are a classic component of which multiple endocrine neoplasia syndrome?", "o": {"A": "MEN 1", "B": "MEN 2A", "C": "MEN 2B", "D": "Von Hippel-Lindau syndrome"}, "r": "A", "e": {"correcta": "MEN 1 (due to mutation of the MEN1 tumor suppressor gene, menin) classically presents with the '3 Ps': Pituitary adenomas, Parathyroid adenomas/hyperplasia (causing hypercalcemia), and Pancreatic endocrine tumors (e.g., gastrinoma, insulinoma). Parathyroid involvement is the most common manifestation, occurring in nearly all patients.", "incorrectas": {"B": "MEN 2A also involves parathyroid disease, but classically parathyroid hyperplasia rather than adenoma, plus medullary thyroid carcinoma and pheochromocytoma; it results from a RET proto-oncogene mutation, not menin.", "C": "MEN 2B does not typically involve parathyroid disease at all; it features medullary thyroid carcinoma, pheochromocytoma, and mucosal neuromas/marfanoid habitus, also due to RET mutations.", "D": "Von Hippel-Lindau syndrome involves hemangioblastomas, renal cell carcinoma, and pheochromocytoma due to VHL gene mutation, not parathyroid tumors."}}}, {"id": "anking-endocrine-pathology-1859", "fuente": "anking", "tema": 5, "anki": "1462834349642", "q": "Which three tumor types/organs are classically affected in MEN 2A?", "o": {"A": "Pituitary adenoma, parathyroid adenoma, pancreatic islet cell tumor", "B": "Parathyroid, medullary thyroid carcinoma, and pheochromocytoma", "C": "Medullary thyroid carcinoma, pheochromocytoma, and mucosal neuromas", "D": "Optic gliomas, pheochromocytoma, and renal cell carcinoma"}, "r": "B", "e": {"correcta": "MEN 2A, caused by a germline gain-of-function mutation in the RET proto-oncogene, is characterized by parathyroid hyperplasia/adenoma, medullary thyroid carcinoma (from parafollicular C cells), and pheochromocytoma. All patients with MEN 2A require prophylactic thyroidectomy given the near-100% penetrance of medullary thyroid carcinoma.", "incorrectas": {"A": "Pituitary adenoma and pancreatic islet cell tumors, along with parathyroid adenoma, describe MEN 1's '3 Ps', not MEN 2A, which does not involve the pituitary or pancreas.", "C": "Medullary thyroid carcinoma, pheochromocytoma, and mucosal neuromas (with marfanoid habitus, but no parathyroid disease) describe MEN 2B, which is also RET-driven but clinically distinct and generally more aggressive.", "D": "Optic gliomas, pheochromocytoma, and renal cell carcinoma are not a recognized MEN triad; pheochromocytoma with renal cell carcinoma and hemangioblastomas instead suggests von Hippel-Lindau disease."}}}, {"id": "anking-endocrine-pathology-1860", "fuente": "anking", "tema": 5, "anki": "1462834690894", "q": "Parathyroid hyperplasia (rather than a solitary adenoma) is characteristically seen alongside medullary thyroid carcinoma and pheochromocytoma in which MEN syndrome?", "o": {"A": "MEN 1", "B": "MEN 2A", "C": "MEN 2B", "D": "Neurofibromatosis type 1"}, "r": "B", "e": {"correcta": "MEN 2A features parathyroid hyperplasia (as opposed to the adenoma more typical of MEN 1), medullary thyroid carcinoma, and pheochromocytoma, all driven by activating RET proto-oncogene mutations that promote unchecked cellular proliferation in neural-crest-derived tissues.", "incorrectas": {"A": "MEN 1 is caused by mutation of the menin tumor suppressor gene and involves parathyroid, pituitary, and pancreatic tumors, not medullary thyroid carcinoma or pheochromocytoma.", "C": "MEN 2B shares the RET mutation and pheochromocytoma/medullary thyroid carcinoma findings, but does not include parathyroid disease; instead it features mucosal neuromas and a marfanoid body habitus.", "D": "Neurofibromatosis type 1 is caused by NF1 gene mutations and presents with neurofibromas, café-au-lait spots, and Lisch nodules, not with parathyroid, thyroid, or adrenal medullary tumors."}}}, {"id": "anking-endocrine-pathology-1861", "fuente": "anking", "tema": 5, "anki": "1462834732857", "q": "Which three findings comprise the classic triad of MEN 2B?", "o": {"A": "Parathyroid hyperplasia, medullary thyroid carcinoma, pheochromocytoma", "B": "Pituitary adenoma, parathyroid adenoma, pancreatic tumor", "C": "Thyroid medullary carcinoma, pheochromocytoma, mucosal neuromas", "D": "Renal cell carcinoma, pheochromocytoma, hemangioblastoma"}, "r": "C", "e": {"correcta": "MEN 2B, like MEN 2A, arises from RET proto-oncogene mutations and features medullary thyroid carcinoma and pheochromocytoma, but is distinguished by mucosal neuromas (oral/intestinal ganglioneuromatosis) and a marfanoid habitus, with no parathyroid involvement.", "incorrectas": {"A": "Parathyroid hyperplasia together with medullary thyroid carcinoma and pheochromocytoma describes MEN 2A, not MEN 2B, which characteristically lacks parathyroid disease.", "B": "Pituitary adenoma, parathyroid adenoma, and pancreatic tumor make up the '3 Ps' of MEN 1, an entirely separate syndrome caused by menin mutation rather than RET.", "D": "Renal cell carcinoma, pheochromocytoma, and hemangioblastoma are features of von Hippel-Lindau disease, unrelated to the RET-driven MEN 2 syndromes."}}}, {"id": "anking-endocrine-pathology-1862", "fuente": "anking", "tema": 5, "anki": "1462834769845", "q": "In MEN 2B, oral and intestinal ganglioneuromatosis corresponds to which characteristic finding?", "o": {"A": "Parathyroid hyperplasia", "B": "Mucosal neuromas", "C": "Medullary thyroid carcinoma", "D": "Pheochromocytoma"}, "r": "B", "e": {"correcta": "Mucosal neuromas are benign proliferations of nerve tissue seen on the lips, tongue, and GI mucosa in MEN 2B, producing the ganglioneuromatosis pattern; along with a marfanoid habitus, they distinguish MEN 2B from MEN 2A, which lacks these findings.", "incorrectas": {"A": "Parathyroid hyperplasia is a feature of MEN 2A, not MEN 2B; MEN 2B does not involve parathyroid pathology.", "C": "Medullary thyroid carcinoma is shared between MEN 2A and 2B, but it arises from parafollicular C cells, not mucosal nerve tissue, so it does not explain ganglioneuromatosis.", "D": "Pheochromocytoma is also shared between MEN 2A and 2B and arises from adrenal medullary chromaffin cells, distinct from the mucosal neuromas described here."}}}, {"id": "anking-endocrine-pathology-1863", "fuente": "anking", "tema": 5, "anki": "1462834810746", "q": "MEN 2A is caused by mutations in which gene, which encodes a receptor tyrosine kinase expressed in neural-crest-derived cells?", "o": {"A": "MEN1 (menin)", "B": "RET", "C": "VHL", "D": "NF1 (neurofibromin)"}, "r": "B", "e": {"correcta": "MEN 2A (and 2B) result from germline gain-of-function mutations in RET, a proto-oncogene encoding a receptor tyrosine kinase normally expressed in cells derived from the neural crest, such as thyroid C cells and adrenal medullary chromaffin cells; constitutive activation drives the characteristic tumors.", "incorrectas": {"A": "MEN1 encodes menin, a tumor suppressor whose loss-of-function mutation causes MEN 1, not MEN 2A; menin is not a receptor tyrosine kinase.", "C": "VHL encodes a tumor suppressor protein involved in regulating hypoxia-inducible factor; its loss-of-function mutation causes von Hippel-Lindau disease, unrelated to MEN 2A.", "D": "NF1 encodes neurofibromin, a Ras-GAP tumor suppressor whose mutation causes neurofibromatosis type 1, a distinct condition from the MEN syndromes."}}}, {"id": "anking-endocrine-pharmacology-1864", "fuente": "anking", "tema": 24, "anki": "1462849353569", "q": "Because sulfonylureas and meglitinides stimulate insulin release independent of ambient glucose levels, which adverse effect is a significant risk?", "o": {"A": "Hypoglycemia", "B": "Lactic acidosis", "C": "Hyperkalemia", "D": "Pancreatitis"}, "r": "A", "e": {"correcta": "Sulfonylureas and meglitinides close ATP-sensitive K+ channels on pancreatic beta cells, causing depolarization and insulin release that bypasses the normal glucose-dependent regulation. Because insulin is secreted regardless of current glucose levels, patients are at significant risk of hypoglycemia, especially with missed meals or renal impairment (for sulfonylureas).", "incorrectas": {"B": "Lactic acidosis is the classic serious adverse effect of metformin, which inhibits hepatic gluconeogenesis and thereby impairs lactate clearance; it is not a typical concern with sulfonylureas or meglitinides.", "C": "Hyperkalemia is not a recognized adverse effect of these insulin secretagogues; their action is on pancreatic beta-cell K+ channels, not renal potassium handling.", "D": "Pancreatitis is not a characteristic side effect of sulfonylureas or meglitinides; it is more associated with other diabetes drug classes (e.g., GLP-1 agonists/DPP-4 inhibitors have a reported, though controversial, pancreatitis risk)."}}}, {"id": "anking-endocrine-pharmacology-1865", "fuente": "anking", "tema": 24, "anki": "1462849360434", "q": "Which change in body weight is a recognized side effect of sulfonylureas and meglitinides?", "o": {"A": "Significant weight loss", "B": "Weight gain", "C": "No effect on weight", "D": "Cachexia"}, "r": "B", "e": {"correcta": "By stimulating insulin release independent of glucose levels, sulfonylureas and meglitinides promote anabolic, fat-storing effects of insulin, leading to weight gain as a common side effect—an important consideration in overweight type 2 diabetics.", "incorrectas": {"A": "Weight loss is instead associated with agents like GLP-1 agonists and SGLT2 inhibitors, which affect satiety and glucose excretion respectively, not with sulfonylureas or meglitinides.", "C": "Weight is not neutral with these drugs; the surge in glucose-independent insulin secretion promotes fat and glycogen storage, producing measurable weight gain in most patients.", "D": "Cachexia (wasting) is the opposite of the expected effect and is not associated with insulin secretagogues, which instead promote anabolism."}}}, {"id": "anking-endocrine-pharmacology-1866", "fuente": "anking", "tema": 24, "anki": "1462849374890", "q": "Sulfonylureas and meglitinides are effective only in patients with which condition, since they require some residual endogenous insulin secretory capacity?", "o": {"A": "Type 1 diabetes mellitus", "B": "Type 2 diabetes mellitus", "C": "Gestational diabetes with absolute insulin deficiency", "D": "Diabetes insipidus"}, "r": "B", "e": {"correcta": "Sulfonylureas and meglitinides work by stimulating existing pancreatic beta cells to release insulin, so they are only useful in type 2 diabetes mellitus, where patients retain some functional beta-cell mass; they are ineffective when beta cells are largely destroyed.", "incorrectas": {"A": "Type 1 diabetes mellitus involves autoimmune destruction of beta cells leaving little to no endogenous insulin to stimulate, making these agents ineffective; exogenous insulin is required instead.", "C": "Gestational diabetes with absolute insulin deficiency implies minimal functional beta-cell reserve, similar to type 1 diabetes, and would not respond to drugs that rely on stimulating existing beta cells.", "D": "Diabetes insipidus is a disorder of vasopressin/ADH deficiency or resistance affecting free water reabsorption, entirely unrelated to insulin secretion or glucose metabolism."}}}, {"id": "anking-endocrine-pharmacology-1867", "fuente": "anking", "tema": 24, "anki": "1462849382382", "q": "Patients on sulfonylureas have an increased risk of hypoglycemia in the setting of which organ dysfunction, since these drugs rely on it for elimination?", "o": {"A": "Hepatic failure", "B": "Renal failure", "C": "Pulmonary failure", "D": "Adrenal insufficiency"}, "r": "B", "e": {"correcta": "Sulfonylureas are eliminated entirely by renal excretion, with no hepatic metabolism or inactivation. In renal failure, the drug accumulates and has a prolonged half-life, causing more sustained insulin release and a substantially increased risk of hypoglycemia.", "incorrectas": {"A": "Hepatic failure is not the primary concern for sulfonylurea clearance since these drugs are not significantly metabolized or inactivated by the liver; renal excretion is the dominant elimination pathway.", "C": "Pulmonary failure does not affect sulfonylurea pharmacokinetics, as these drugs are not cleared via the respiratory system.", "D": "Adrenal insufficiency affects cortisol and aldosterone production, not drug elimination, and does not explain the accumulation of sulfonylureas leading to hypoglycemia."}}}, {"id": "anking-endocrine-pharmacology-1868", "fuente": "anking", "tema": 24, "anki": "1462849387815", "q": "Exenatide and liraglutide belong to which class of diabetes medications?", "o": {"A": "Sulfonylureas", "B": "DPP-4 inhibitors", "C": "GLP-1 agonists", "D": "Thiazolidinediones"}, "r": "C", "e": {"correcta": "Exenatide and liraglutide are GLP-1 receptor agonists (incretin mimetics) that increase glucose-dependent insulin secretion, decrease glucagon, and slow gastric emptying to promote satiety, mimicking the action of endogenous glucagon-like peptide-1.", "incorrectas": {"A": "Sulfonylureas (e.g., glipizide, glyburide) stimulate insulin release by closing beta-cell K+ channels independent of glucose levels, a mechanistically distinct and older drug class from GLP-1 agonists.", "B": "DPP-4 inhibitors (e.g., sitagliptin) work by blocking the enzyme that degrades endogenous GLP-1, raising its levels indirectly, rather than being GLP-1 receptor agonists themselves like exenatide and liraglutide.", "D": "Thiazolidinediones (e.g., pioglitazone) act on PPAR-gamma receptors to increase insulin sensitivity in peripheral tissue, a completely different mechanism from incretin-based therapies."}}}, {"id": "anking-endocrine-pharmacology-1869", "fuente": "anking", "tema": 24, "anki": "1462849394748", "q": "GLP-1 analogs promote satiety and glycemic control in part by increasing secretion of which hormone?", "o": {"A": "Glucagon", "B": "Insulin", "C": "Somatostatin", "D": "Cortisol"}, "r": "B", "e": {"correcta": "GLP-1 analogs bind GLP-1 receptors on pancreatic beta cells to increase glucose-dependent insulin release, meaning insulin secretion only rises when glucose is elevated—this glucose dependence is why GLP-1 agonists carry minimal hypoglycemia risk compared to sulfonylureas.", "incorrectas": {"A": "Glucagon secretion is actually decreased, not increased, by GLP-1 analogs, contributing to lower hepatic glucose output alongside increased insulin.", "C": "Somatostatin is not the hormone classically described as increased by GLP-1 analogs in this context; the key incretin effect is on insulin and glucagon, not somatostatin.", "D": "Cortisol is a glucocorticoid regulated by the HPA axis and is unrelated to the incretin pathway targeted by GLP-1 analogs."}}}, {"id": "anking-endocrine-pharmacology-1870", "fuente": "anking", "tema": 24, "anki": "1462849402751", "q": "In addition to increasing insulin release, GLP-1 analogs decrease secretion of which hormone, contributing to lower hepatic glucose output?", "o": {"A": "Glucagon", "B": "Growth hormone", "C": "Somatostatin", "D": "Aldosterone"}, "r": "A", "e": {"correcta": "GLP-1 analogs suppress glucagon secretion from pancreatic alpha cells, which reduces hepatic gluconeogenesis and glycogenolysis, complementing the increased glucose-dependent insulin release to lower blood glucose and slow gastric emptying.", "incorrectas": {"B": "Growth hormone secretion is regulated by the hypothalamic-pituitary axis (GHRH/somatostatin) and is not a target of GLP-1 receptor signaling in glucose homeostasis.", "C": "Somatostatin itself inhibits both insulin and glucagon release, but it is not the hormone described as being suppressed by GLP-1 analogs in this glucose-lowering mechanism.", "D": "Aldosterone regulates sodium and potassium balance via the renin-angiotensin-aldosterone system and has no role in the incretin-mediated glucose control described here."}}}, {"id": "anking-endocrine-pharmacology-1871", "fuente": "anking", "tema": 24, "anki": "1462849421840", "q": "Linagliptin, saxagliptin, and sitagliptin belong to which drug class?", "o": {"A": "GLP-1 agonists", "B": "Sulfonylureas", "C": "DPP-4 inhibitors", "D": "Biguanides"}, "r": "C", "e": {"correcta": "Linagliptin, saxagliptin, and sitagliptin are DPP-4 (dipeptidyl peptidase-4) inhibitors, which block the enzyme responsible for degrading endogenous incretins like GLP-1, thereby prolonging their glucose-lowering, insulinotropic effects.", "incorrectas": {"A": "GLP-1 agonists (e.g., exenatide, liraglutide) directly activate the GLP-1 receptor rather than inhibiting the enzyme that degrades endogenous GLP-1, distinguishing them from DPP-4 inhibitors.", "B": "Sulfonylureas (e.g., glipizide, glyburide) act directly on pancreatic beta-cell K+ channels to stimulate insulin release, an entirely different mechanism from incretin-based DPP-4 inhibition.", "D": "Biguanides (metformin is the prototype) work by decreasing hepatic gluconeogenesis and increasing peripheral insulin sensitivity, unrelated to DPP-4 enzyme inhibition."}}}, {"id": "anking-endocrine-pharmacology-1872", "fuente": "anking", "tema": 24, "anki": "1462849428163", "q": "DPP-4 inhibitors lower blood glucose primarily by increasing levels of which endogenously secreted hormone?", "o": {"A": "Insulin", "B": "GLP-1", "C": "Somatostatin", "D": "Amylin"}, "r": "B", "e": {"correcta": "DPP-4 inhibitors block the enzyme dipeptidyl peptidase-4, which normally rapidly degrades endogenous GLP-1 (and GIP). By preventing this breakdown, DPP-4 inhibitors raise circulating GLP-1 levels, prolonging its glucose-dependent insulinotropic and glucagon-suppressing effects.", "incorrectas": {"A": "Insulin itself is not directly increased by DPP-4 inhibitors; rather, insulin secretion rises indirectly and only in a glucose-dependent manner as a downstream effect of elevated GLP-1.", "C": "Somatostatin is not the target hormone of DPP-4 inhibition; DPP-4 specifically cleaves incretins like GLP-1, not somatostatin.", "D": "Amylin is co-secreted with insulin and slows gastric emptying, but it is not the hormone whose levels are raised by DPP-4 inhibition; that is GLP-1."}}}, {"id": "anking-endocrine-pharmacology-1873", "fuente": "anking", "tema": 24, "anki": "1462849434995", "q": "Both GLP-1 agonists and DPP-4 inhibitors lower blood glucose in part by decreasing secretion of which pancreatic hormone?", "o": {"A": "Insulin", "B": "Somatostatin", "C": "Glucagon", "D": "Pancreatic polypeptide"}, "r": "C", "e": {"correcta": "Both GLP-1 agonists and DPP-4 inhibitors act through the incretin pathway to suppress glucagon secretion from pancreatic alpha cells, which reduces hepatic glucose output and complements their glucose-dependent stimulation of insulin release.", "incorrectas": {"A": "Insulin secretion is increased, not decreased, by these drug classes; the decreased hormone in this glucose-lowering mechanism is glucagon.", "B": "Somatostatin is not the hormone specifically described as decreased by these incretin-based therapies; the relevant suppressed hormone is glucagon.", "D": "Pancreatic polypeptide regulates pancreatic exocrine secretion and appetite but is not part of the described mechanism of GLP-1 agonists or DPP-4 inhibitors."}}}, {"id": "anking-endocrine-pharmacology-1874", "fuente": "anking", "tema": 24, "anki": "1462849442061", "q": "GLP-1 agonists and DPP-4 inhibitors increase satiety in part through a decrease in which physiologic process?", "o": {"A": "Gastric emptying", "B": "Renal glucose reabsorption", "C": "Hepatic glycogenolysis", "D": "Intestinal glucose absorption"}, "r": "A", "e": {"correcta": "By activating GLP-1 receptor signaling (directly via agonists, or indirectly by preserving endogenous GLP-1 via DPP-4 inhibition), these drugs slow gastric emptying, which prolongs the feeling of fullness and contributes to increased satiety and modest weight benefits.", "incorrectas": {"B": "Renal glucose reabsorption is the target of SGLT2 inhibitors (e.g., canagliflozin), which block glucose reabsorption in the proximal tubule, not a mechanism of GLP-1 agonists or DPP-4 inhibitors.", "C": "Hepatic glycogenolysis is not the primary satiety mechanism described; glucagon suppression by these drugs does reduce hepatic glucose output, but satiety specifically relates to delayed gastric emptying.", "D": "Intestinal glucose absorption is targeted by drugs like acarbose (alpha-glucosidase inhibitors), a different drug class unrelated to the incretin-based mechanism here."}}}, {"id": "anking-toxicities-side-effects-1875", "fuente": "anking", "tema": 29, "anki": "1462849448833", "q": "DPP-4 inhibitors carry an increased risk of which type of infection?", "o": {"A": "Genital fungal infection", "B": "Upper respiratory tract infection", "C": "Clostridioides difficile colitis", "D": "Osteomyelitis"}, "r": "B", "e": {"correcta": "DPP-4 inhibitors are associated with an increased risk of upper respiratory tract infections, such as nasopharyngitis, and may also modestly increase urinary tract infection risk; the mechanism is not fully understood but is a recognized class side effect on exams.", "incorrectas": {"A": "Genital fungal (mycotic) infections are a well-known side effect of SGLT2 inhibitors due to increased urinary glucose excretion promoting fungal overgrowth, not a typical effect of DPP-4 inhibitors.", "C": "Clostridioides difficile colitis is classically linked to antibiotic use disrupting normal gut flora, not to DPP-4 inhibitor therapy.", "D": "Osteomyelitis is a bone infection unrelated to DPP-4 inhibitor pharmacology; it is not a recognized class side effect of these drugs."}}}, {"id": "anking-endocrine-pharmacology-1876", "fuente": "anking", "tema": 24, "anki": "1462849475077", "q": "Do GLP-1 agonists and DPP-4 inhibitors carry a significant risk of causing hypoglycemia as monotherapy?", "o": {"A": "Yes, because they bypass normal glucose-dependent insulin regulation", "B": "No, because their insulinotropic effect is glucose-dependent", "C": "Yes, but only in patients with renal failure", "D": "No, because they suppress insulin secretion entirely"}, "r": "B", "e": {"correcta": "Unlike sulfonylureas and meglitinides, GLP-1 agonists and DPP-4 inhibitors stimulate insulin release only when glucose levels are elevated (glucose-dependent insulinotropic effect), so they do not cause the same degree of unregulated insulin secretion and therefore carry minimal risk of hypoglycemia as monotherapy.", "incorrectas": {"A": "This describes sulfonylureas and meglitinides, which do bypass glucose-dependent regulation of insulin release and thus do carry significant hypoglycemia risk, unlike GLP-1 agonists/DPP-4 inhibitors.", "C": "Renal failure affects the pharmacokinetics of some diabetes drugs (like sulfonylureas), but it is not the reason GLP-1 agonists/DPP-4 inhibitors have low hypoglycemia risk; the reason is their glucose-dependent mechanism.", "D": "These drugs do not suppress insulin secretion; they enhance it in a glucose-dependent manner, which is precisely why they avoid causing hypoglycemia."}}}, {"id": "anking-endocrine-pharmacology-1877", "fuente": "anking", "tema": 24, "anki": "1462849488980", "q": "GLP-1 agonists and DPP-4 inhibitors are effective only in which type of diabetes, since they depend on some residual functional beta-cell mass?", "o": {"A": "Type 1 diabetes mellitus", "B": "Type 2 diabetes mellitus", "C": "Maturity-onset diabetes of the young with complete beta-cell loss", "D": "Diabetes insipidus"}, "r": "B", "e": {"correcta": "GLP-1 agonists and DPP-4 inhibitors work by potentiating glucose-dependent insulin secretion from existing pancreatic beta cells, so they require some functional beta-cell reserve and are effective only in type 2 diabetes mellitus, not in states of near-complete beta-cell destruction.", "incorrectas": {"A": "Type 1 diabetes mellitus involves autoimmune beta-cell destruction leaving minimal insulin-secreting capacity to potentiate, making these incretin-based drugs ineffective as primary therapy.", "C": "A condition with complete beta-cell loss would behave like type 1 diabetes for treatment purposes—no functional beta cells means no substrate for incretin-based drugs to act upon.", "D": "Diabetes insipidus involves vasopressin/ADH dysfunction and free water handling, entirely unrelated to insulin secretion, beta-cell function, or incretin pharmacology."}}}, {"id": "anking-endocrine-pharmacology-1878", "fuente": "anking", "tema": 24, "anki": "1462913162803", "q": "Metformin lowers blood glucose primarily by decreasing which hepatic process?", "o": {"A": "Glycogenolysis", "B": "Gluconeogenesis", "C": "Lipogenesis", "D": "Ketogenesis"}, "r": "B", "e": {"correcta": "Metformin activates AMP-activated protein kinase (AMPK) in hepatocytes, which decreases hepatic gluconeogenesis, the primary mechanism by which it lowers blood glucose; it also modestly increases peripheral insulin sensitivity without stimulating insulin secretion, so it does not cause hypoglycemia.", "incorrectas": {"A": "Glycogenolysis (glycogen breakdown) is not the primary hepatic pathway targeted by metformin; its main action is on gluconeogenesis, the synthesis of new glucose.", "C": "Lipogenesis is fat synthesis and is not the mechanism by which metformin reduces blood glucose; metformin's principal action is on glucose production pathways.", "D": "Ketogenesis is the production of ketone bodies during states of low insulin/fasting and is not directly targeted by metformin's glucose-lowering mechanism."}}}, {"id": "anking-endocrine-pharmacology-1879", "fuente": "anking", "tema": 24, "anki": "1462913228518", "q": "Metformin improves glycemic control in part by increasing which parameter in peripheral tissues?", "o": {"A": "Insulin sensitivity", "B": "Insulin secretion", "C": "Glucagon secretion", "D": "Renal glucose reabsorption"}, "r": "A", "e": {"correcta": "Metformin increases insulin sensitivity in peripheral tissues, enhancing glucose uptake (e.g., via GLUT4) without increasing insulin secretion itself; because it does not provoke additional insulin release, it does not bypass glucose-dependent regulation and carries essentially no risk of hypoglycemia as monotherapy.", "incorrectas": {"B": "Metformin does not increase insulin secretion from pancreatic beta cells; its glucose-lowering effects come from decreased hepatic gluconeogenesis and increased peripheral insulin sensitivity, not insulinotropic action.", "C": "Glucagon secretion is not increased by metformin; if anything, improved glycemic control indirectly reduces the stimulus for glucagon release, but this is not metformin's direct mechanism.", "D": "Renal glucose reabsorption is the target of SGLT2 inhibitors, a different drug class; metformin's mechanism does not involve the kidney's handling of glucose."}}}, {"id": "anking-toxicities-side-effects-1880", "fuente": "anking", "tema": 29, "anki": "1462913238244", "q": "What is the most serious adverse effect associated with metformin therapy?", "o": {"A": "Hypoglycemia", "B": "Lactic acidosis", "C": "Pancreatitis", "D": "Peripheral edema"}, "r": "B", "e": {"correcta": "Metformin's most serious adverse effect is lactic acidosis. By inhibiting hepatic gluconeogenesis, metformin also impairs the pathway that normally clears lactate (since lactate is a gluconeogenic substrate), causing lactate to accumulate in serum. This risk is heightened in hypoxic tissues, which have already shifted to anaerobic glycolysis and generate more lactate.", "incorrectas": {"A": "Hypoglycemia is not a significant risk with metformin monotherapy because it does not stimulate insulin secretion; it works by decreasing hepatic glucose production and improving peripheral insulin sensitivity.", "C": "Pancreatitis is more classically associated with incretin-based therapies (GLP-1 agonists/DPP-4 inhibitors), not metformin, and is not metformin's defining serious adverse effect.", "D": "Peripheral edema is a recognized side effect of thiazolidinediones due to fluid retention, not a typical adverse effect of metformin."}}}, {"id": "anking-toxicities-side-effects-1881", "fuente": "anking", "tema": 29, "anki": "1462913246058", "q": "Patients with which condition are at increased risk of metformin-induced lactic acidosis due to drug accumulation?", "o": {"A": "Hepatic insufficiency", "B": "Renal insufficiency", "C": "Adrenal insufficiency", "D": "Thyroid insufficiency"}, "r": "B", "e": {"correcta": "Metformin is not metabolized and is cleared purely by renal excretion. In renal insufficiency, metformin accumulates in the body, dramatically increasing the risk of lactic acidosis; metformin is generally avoided when creatinine is significantly elevated (or with reduced eGFR) for this reason.", "incorrectas": {"A": "Hepatic insufficiency is actually a separate risk factor for lactic acidosis (because the liver is also important for lactate clearance), but the classic teaching point about metformin accumulation specifically concerns renal excretion, not hepatic metabolism, since metformin isn't hepatically metabolized.", "C": "Adrenal insufficiency affects cortisol and aldosterone production and does not influence metformin clearance or lactic acidosis risk through drug accumulation.", "D": "Thyroid insufficiency (hypothyroidism) does not affect metformin's renal excretion pathway and is not a recognized risk factor for metformin-induced lactic acidosis."}}}, {"id": "anking-endocrine-pharmacology-1882", "fuente": "anking", "tema": 24, "anki": "1462913267342", "q": "What effect does metformin have on body weight?", "o": {"A": "Significant weight gain", "B": "Modest weight reduction", "C": "No effect on weight", "D": "Severe cachexia"}, "r": "B", "e": {"correcta": "Metformin is associated with modest weight reduction or at least weight neutrality, making it particularly favorable for overweight type 2 diabetic patients, in contrast to insulin secretagogues (sulfonylureas, meglitinides) and thiazolidinediones, which tend to cause weight gain.", "incorrectas": {"A": "Weight gain is instead characteristic of sulfonylureas, meglitinides, and thiazolidinediones, which promote anabolic insulin effects or adipocyte differentiation, not metformin.", "C": "Metformin is not simply weight-neutral; it is specifically associated with modest weight loss, which is one of its clinically favorable attributes.", "D": "Severe cachexia is not an expected or reported effect of metformin; the observed change is a mild, generally beneficial reduction in weight."}}}, {"id": "anking-endocrine-pharmacology-1883", "fuente": "anking", "tema": 24, "anki": "1462913285372", "q": "Pioglitazone and rosiglitazone belong to which drug class, also called glitazones?", "o": {"A": "Biguanides", "B": "Sulfonylureas", "C": "Thiazolidinediones", "D": "Meglitinides"}, "r": "C", "e": {"correcta": "Pioglitazone and rosiglitazone are thiazolidinediones (glitazones), which act as PPAR-gamma agonists in adipose and other peripheral tissues, increasing insulin sensitivity through effects on gene transcription related to glucose and lipid metabolism.", "incorrectas": {"A": "Biguanides refers to metformin, which decreases hepatic gluconeogenesis and increases peripheral insulin sensitivity through AMPK activation, a mechanistically distinct drug class from thiazolidinediones.", "B": "Sulfonylureas (e.g., glipizide, glyburide) stimulate insulin secretion by closing beta-cell K+ channels, unrelated to the PPAR-gamma mechanism of thiazolidinediones.", "D": "Meglitinides (e.g., repaglinide, nateglinide) also stimulate insulin secretion via K+ channel closure, similar to sulfonylureas but shorter-acting, and are distinct from thiazolidinediones."}}}, {"id": "anking-endocrine-pharmacology-1884", "fuente": "anking", "tema": 24, "anki": "1462913300610", "q": "Thiazolidinediones lower blood glucose primarily by increasing which parameter, especially in adipose tissue?", "o": {"A": "Insulin secretion", "B": "Insulin sensitivity", "C": "Renal glucose excretion", "D": "Intestinal carbohydrate absorption"}, "r": "B", "e": {"correcta": "Thiazolidinediones increase insulin sensitivity, particularly in adipose tissue, enhancing glucose uptake into fat cells and effectively redirecting excess circulating glucose there; this occurs via PPAR-gamma receptor activation and downstream gene transcription changes rather than via stimulating insulin release.", "incorrectas": {"A": "Insulin secretion is not increased by thiazolidinediones; they work by sensitizing tissues to existing insulin, which is also why they do not cause hypoglycemia as monotherapy.", "C": "Renal glucose excretion is the mechanism of SGLT2 inhibitors, not thiazolidinediones, which act at the level of peripheral tissue insulin sensitivity instead.", "D": "Intestinal carbohydrate absorption is targeted by alpha-glucosidase inhibitors (e.g., acarbose), an unrelated mechanism to PPAR-gamma-mediated insulin sensitization."}}}, {"id": "anking-endocrine-pharmacology-1885", "fuente": "anking", "tema": 24, "anki": "1462913323101", "q": "Activation of PPAR-gamma by thiazolidinediones upregulates which adipokine that increases insulin sensitivity and fatty acid oxidation?", "o": {"A": "Leptin", "B": "Resistin", "C": "Adiponectin", "D": "TNF-alpha"}, "r": "C", "e": {"correcta": "Thiazolidinediones activate PPAR-gamma, which upregulates adiponectin, an adipokine that enhances insulin sensitivity and promotes fatty acid oxidation. Adiponectin levels are typically low in obesity and type 2 diabetes, and thiazolidinediones help correct this deficiency.", "incorrectas": {"A": "Leptin is an adipokine that regulates satiety and energy balance via hypothalamic signaling, but it is not the specific adipokine described as upregulated by PPAR-gamma activation in this mechanism.", "B": "Resistin is an adipokine that has been associated with insulin resistance (opposing the effect described), not with the insulin-sensitizing action of thiazolidinediones.", "D": "TNF-alpha is a pro-inflammatory cytokine linked to insulin resistance in obesity; thiazolidinediones do not act by upregulating TNF-alpha, which would worsen rather than improve insulin sensitivity."}}}, {"id": "anking-endocrine-pharmacology-1886", "fuente": "anking", "tema": 24, "anki": "1462913355567", "q": "What effect do thiazolidinediones have on the differentiation and number of adipocytes?", "o": {"A": "Decreased", "B": "No effect", "C": "Increased", "D": "Complete apoptosis of adipocytes"}, "r": "C", "e": {"correcta": "Thiazolidinediones, via PPAR-gamma activation (a key transcription factor in adipogenesis), increase the differentiation and number of adipocytes, particularly favoring subcutaneous over visceral fat, which helps redistribute and store excess glucose/lipids more safely.", "incorrectas": {"A": "A decrease in adipocyte differentiation would be the opposite of what PPAR-gamma agonism produces; thiazolidinediones actually promote adipogenesis, not adipocyte loss.", "B": "There is a measurable effect on adipocytes; PPAR-gamma is a master regulator of adipocyte differentiation, so thiazolidinediones do not leave this parameter unaffected.", "D": "Thiazolidinediones do not cause adipocyte apoptosis; rather, they promote adipocyte formation and function, which is central to their insulin-sensitizing mechanism."}}}, {"id": "anking-endocrine-pharmacology-1887", "fuente": "anking", "tema": 24, "anki": "1462913390177", "q": "What effect do thiazolidinediones have on triglyceride storage and fatty acid oxidation in adipose tissue?", "o": {"A": "Decreased, raising serum triglycerides", "B": "Increased, decreasing serum triglycerides", "C": "No significant effect", "D": "Increased triglyceride storage but decreased fatty acid oxidation"}, "r": "B", "e": {"correcta": "Thiazolidinediones increase both triglyceride storage in adipocytes and fatty acid oxidation, which together lower circulating serum triglyceride levels—part of their favorable, PPAR-gamma-mediated effect on lipid metabolism alongside improved insulin sensitivity.", "incorrectas": {"A": "A decrease in these processes would raise, not lower, serum triglycerides, which is the opposite of the actual effect of thiazolidinediones on lipid handling.", "C": "Thiazolidinediones have a well-documented effect on lipid metabolism through PPAR-gamma activation; it is not accurate to say there is no significant effect.", "D": "Thiazolidinediones increase both processes together (storage and oxidation), not one at the expense of the other; increased fatty acid oxidation accompanies increased storage capacity in adipocytes."}}}, {"id": "anking-endocrine-pharmacology-1888", "fuente": "anking", "tema": 24, "anki": "1462913407963", "q": "Which glucose transporter is upregulated in peripheral tissue by thiazolidinediones, enhancing glucose uptake?", "o": {"A": "GLUT1", "B": "GLUT2", "C": "GLUT4", "D": "GLUT5"}, "r": "C", "e": {"correcta": "Thiazolidinediones upregulate GLUT4, the insulin-responsive glucose transporter found in skeletal muscle and adipose tissue, increasing glucose uptake into these peripheral tissues and thereby improving insulin sensitivity and lowering blood glucose.", "incorrectas": {"A": "GLUT1 is a ubiquitously expressed, insulin-independent glucose transporter (important in red blood cells and the blood-brain barrier), not the insulin-responsive transporter upregulated by thiazolidinediones.", "B": "GLUT2 is found in pancreatic beta cells, hepatocytes, and renal tubule cells and functions as a glucose sensor/low-affinity transporter, not the peripheral tissue transporter targeted here.", "D": "GLUT5 is primarily a fructose transporter located in the small intestine, unrelated to the insulin-sensitizing, glucose-uptake mechanism of thiazolidinediones."}}}, {"id": "anking-pharmacokinetics-pharmacodynamics-1889", "fuente": "anking", "tema": 31, "anki": "1462913437726", "q": "Why do thiazolidinediones act slowly to reduce blood glucose levels?", "o": {"A": "They require hepatic bioactivation before becoming effective", "B": "They act at the level of gene transcription", "C": "They must first be filtered and reabsorbed by the kidney", "D": "They require binding to plasma proteins before activation"}, "r": "B", "e": {"correcta": "Thiazolidinediones act as PPAR-gamma agonists that alter gene transcription, changing the expression of proteins involved in glucose and lipid metabolism (e.g., GLUT4, adiponectin). Because transcriptional and translational changes take time to manifest, the clinical glucose-lowering effect is slow, often taking weeks to become fully apparent.", "incorrectas": {"A": "Thiazolidinediones do not require hepatic bioactivation to become pharmacologically active at their nuclear receptor target; their delayed onset relates to the transcriptional mechanism, not prodrug conversion.", "C": "Renal filtration and reabsorption are not relevant to the onset of action of thiazolidinediones, which act intracellularly on nuclear PPAR-gamma receptors, not through renal handling.", "D": "Plasma protein binding affects drug distribution and free fraction, but it is not the reason for the slow onset of thiazolidinediones; the delay comes from their transcriptional mechanism of action."}}}, {"id": "anking-toxicities-side-effects-1890", "fuente": "anking", "tema": 29, "anki": "1462913454503", "q": "Thiazolidinedione-induced fluid retention commonly manifests as which finding in the extremities?", "o": {"A": "Peripheral edema", "B": "Digital clubbing", "C": "Raynaud phenomenon", "D": "Livedo reticularis"}, "r": "A", "e": {"correcta": "Thiazolidinediones cause fluid retention, commonly presenting as peripheral edema in the extremities. This fluid retention is clinically significant because it can worsen or precipitate heart failure, making thiazolidinediones relatively contraindicated in patients with advanced heart disease.", "incorrectas": {"B": "Digital clubbing is associated with chronic hypoxic conditions (e.g., lung disease, cyanotic heart disease) and is not related to thiazolidinedione-induced fluid retention.", "C": "Raynaud phenomenon is vasospasm of digital arteries triggered by cold or stress, unrelated to the fluid-retaining mechanism of thiazolidinediones.", "D": "Livedo reticularis is a mottled skin discoloration pattern related to vascular abnormalities (e.g., cholesterol emboli, vasculitis), not a recognized manifestation of thiazolidinedione fluid retention."}}}, {"id": "anking-toxicities-side-effects-1891", "fuente": "anking", "tema": 29, "anki": "1462913462613", "q": "Thiazolidinedione-induced fluid retention can exacerbate which underlying condition, representing a relative contraindication?", "o": {"A": "Chronic kidney disease", "B": "Heart failure", "C": "Peripheral arterial disease", "D": "Chronic obstructive pulmonary disease"}, "r": "B", "e": {"correcta": "Thiazolidinediones cause fluid retention through effects on renal sodium handling, which can precipitate or worsen heart failure; consequently, they are contraindicated in patients with later-stage heart disease, particularly those with reduced cardiac reserve.", "incorrectas": {"A": "Chronic kidney disease is a concern with drugs cleared renally (like metformin, raising lactic acidosis risk), but it is not the specific condition classically exacerbated by thiazolidinedione-related fluid retention.", "C": "Peripheral arterial disease relates to atherosclerotic narrowing of limb arteries and is not directly worsened by the fluid retention mechanism of thiazolidinediones.", "D": "Chronic obstructive pulmonary disease is a respiratory condition unrelated to the fluid overload and cardiac strain caused by thiazolidinedione-induced sodium and water retention."}}}, {"id": "anking-toxicities-side-effects-1892", "fuente": "anking", "tema": 29, "anki": "1462913505933", "q": "Thiazolidinediones increase the risk of which skeletal adverse effect?", "o": {"A": "Osteonecrosis of the jaw", "B": "Atypical extremity fractures", "C": "Vertebral compression fractures only", "D": "Osteomyelitis"}, "r": "B", "e": {"correcta": "Thiazolidinediones decrease bone mineral density, likely by shifting mesenchymal stem cell differentiation toward adipocytes rather than osteoblasts via PPAR-gamma activation, which increases the risk of atypical extremity fractures, particularly in postmenopausal women.", "incorrectas": {"A": "Osteonecrosis of the jaw is classically associated with bisphosphonate or denosumab therapy, not with thiazolidinediones, which have a distinct bone-density-lowering mechanism affecting peripheral bone.", "C": "The fracture risk with thiazolidinediones is not limited to vertebral compression fractures; it is characteristically described as an increase in atypical fractures of the extremities (e.g., distal upper and lower limbs).", "D": "Osteomyelitis is a bone infection, an entirely different process from the decreased bone mineral density and fracture risk caused by thiazolidinediones."}}}, {"id": "anking-endocrine-pharmacology-1893", "fuente": "anking", "tema": 24, "anki": "1462913533718", "q": "A patient with type 2 diabetes started on a new oral hypoglycemic agent presents 8 months later with a low-trauma wrist fracture. Which class of diabetic medication is most associated with increased fracture risk?", "o": {"A": "Sulfonylureas", "B": "Thiazolidinediones (glitazones)", "C": "Metformin", "D": "DPP-4 inhibitors"}, "r": "B", "e": {"correcta": "Thiazolidinediones (e.g. pioglitazone, rosiglitazone) activate PPAR-gamma, which shifts mesenchymal stem cell differentiation away from osteoblasts and toward adipocytes, reducing bone formation and increasing fracture risk, particularly in postmenopausal women.", "incorrectas": {"A": "Sulfonylureas stimulate insulin release by closing beta-cell K+ATP channels; their main risks are hypoglycemia and weight gain, not bone loss.", "C": "Metformin works by decreasing hepatic gluconeogenesis and is actually considered bone-neutral to mildly bone-protective, not associated with fractures.", "D": "DPP-4 inhibitors (e.g. sitagliptin) prolong endogenous incretin activity and are generally well tolerated with no established link to fracture risk."}}}, {"id": "anking-endocrine-pharmacology-1894", "fuente": "anking", "tema": 24, "anki": "1462913541311", "q": "A patient taking pioglitazone for type 2 diabetes develops progressive dyspnea and peripheral edema. Which mechanism explains this thiazolidinedione side effect?", "o": {"A": "Direct cardiotoxicity from mitochondrial injury", "B": "Increased fluid retention", "C": "Negative inotropic effect on cardiac myocytes", "D": "Precipitation of arrhythmia via QT prolongation"}, "r": "B", "e": {"correcta": "Thiazolidinediones increase renal sodium and water reabsorption (via PPAR-gamma effects on the collecting duct), causing fluid retention that can precipitate or worsen heart failure; this is why they are contraindicated in patients with NYHA class III-IV heart failure.", "incorrectas": {"A": "Thiazolidinediones are not known for direct mitochondrial cardiotoxicity; their cardiac risk is specifically tied to volume overload from fluid retention.", "C": "There is no established direct negative inotropic effect of glitazones on myocardium; the heart failure risk is a consequence of increased preload from fluid retention, not impaired contractility.", "D": "Glitazones are not associated with QT prolongation or arrhythmia; their cardiovascular adverse effect profile centers on edema and heart failure exacerbation."}}}, {"id": "anking-endocrine-pharmacology-1895", "fuente": "anking", "tema": 24, "anki": "1462913584874", "q": "Pramlintide, an amylin analog used as adjunct diabetes therapy, has what effect on gastric emptying?", "o": {"A": "No significant effect", "B": "Increased", "C": "Decreased", "D": "Biphasic, first increased then decreased"}, "r": "C", "e": {"correcta": "Amylin (and its analog pramlintide) slows gastric emptying, which blunts the rapid rise in postprandial blood glucose by delaying nutrient delivery to the small intestine for absorption.", "incorrectas": {"A": "Pramlintide does have a clinically significant effect on gastric motility; slowed emptying is one of its three main glucose-lowering mechanisms along with suppressing glucagon and promoting satiety.", "B": "Increased gastric emptying would worsen postprandial hyperglycemia by delivering glucose to the gut faster, the opposite of amylin's therapeutic effect.", "D": "There is no biphasic gastric emptying pattern described for amylin analogs; the effect is a sustained slowing of emptying."}}}, {"id": "anking-endocrine-pharmacology-1896", "fuente": "anking", "tema": 24, "anki": "1462913605177", "q": "Pramlintide lowers postprandial blood glucose in part by suppressing secretion of which pancreatic hormone?", "o": {"A": "Insulin", "B": "Somatostatin", "C": "Glucagon", "D": "Pancreatic polypeptide"}, "r": "C", "e": {"correcta": "Amylin, co-secreted with insulin from pancreatic beta cells, normally suppresses glucagon release from alpha cells after a meal; pramlintide mimics this action, decreasing glucagon-driven hepatic glucose output and reducing postprandial glucose spikes.", "incorrectas": {"A": "Pramlintide does not suppress insulin; rather it is used as an adjunct to insulin therapy since patients with diabetes lack sufficient endogenous amylin (co-secreted with insulin).", "B": "Somatostatin is a separate paracrine inhibitor of both insulin and glucagon secreted by pancreatic delta cells; it is not the target of amylin's action.", "D": "Pancreatic polypeptide, secreted by PP cells, regulates pancreatic secretory activity and is not the hormone suppressed by amylin/pramlintide in glucose control."}}}, {"id": "anking-endocrine-pharmacology-1897", "fuente": "anking", "tema": 24, "anki": "1462913613399", "q": "Pramlintide is unique among non-insulin diabetes therapies in that it can be used in which population(s)?", "o": {"A": "T2DM only", "B": "T1DM and T2DM", "C": "T1DM only, as monotherapy without insulin", "D": "Gestational diabetes only"}, "r": "B", "e": {"correcta": "Unlike oral hypoglycemics that require residual beta-cell function and are limited to T2DM, pramlintide is an injectable amylin analog usable in both T1DM and T2DM because it addresses the unopposed glucagon secretion seen in type 1 diabetes (due to loss of amylin co-secretion with insulin), in addition to its effects in T2DM.", "incorrectas": {"A": "This describes most oral hypoglycemic agents (e.g. metformin, sulfonylureas), which require functioning beta cells and therefore do not work in T1DM; pramlintide is different because it is used as an adjunct to insulin in both diabetes types.", "C": "Pramlintide is always used as an adjunct to mealtime insulin, not as monotherapy replacing insulin, since patients with T1DM still require exogenous insulin for glycemic control.", "D": "Pramlintide is not specifically indicated for gestational diabetes; its approved use is as adjunct therapy in T1DM and T2DM patients on mealtime insulin."}}}, {"id": "anking-endocrine-pharmacology-1898", "fuente": "anking", "tema": 24, "anki": "1462913625624", "q": "Pramlintide is administered as an adjunct to mealtime insulin primarily to control which aspect of glycemic control?", "o": {"A": "Fasting morning glucose", "B": "Postprandial glucose spike", "C": "Nocturnal hypoglycemia prevention", "D": "HbA1c independent of meals"}, "r": "B", "e": {"correcta": "By slowing gastric emptying and suppressing glucagon secretion, pramlintide blunts the sharp rise in blood glucose that occurs immediately after meals, making it useful for controlling postprandial hyperglycemia that mealtime insulin alone may not fully address.", "incorrectas": {"A": "Fasting glucose is primarily managed by basal (long-acting) insulin, not by pramlintide, which is dosed with meals to target the postprandial rise.", "C": "Pramlintide actually increases hypoglycemia risk (especially with mistimed insulin dosing) rather than being used to prevent nocturnal hypoglycemia.", "D": "While reducing postprandial spikes may lower overall HbA1c, the drug's specific mechanism and dosing timing (with meals) targets the postprandial glucose excursion, not glucose control independent of meals."}}}, {"id": "anking-endocrine-pharmacology-1899", "fuente": "anking", "tema": 24, "anki": "1462913640957", "q": "A patient on pramlintide and mealtime insulin injects her insulin significantly earlier than her meal and later develops symptoms of confusion and diaphoresis. What is the most likely complication?", "o": {"A": "Diabetic ketoacidosis", "B": "Hypoglycemia", "C": "Lactic acidosis", "D": "Hyperosmolar hyperglycemic state"}, "r": "B", "e": {"correcta": "Because pramlintide works through an insulin-independent mechanism (chiefly suppressing glucagon) and is combined with exogenous insulin, mistimed prandial insulin relative to food intake creates a significant risk of hypoglycemia, presenting with adrenergic and neuroglycopenic symptoms like diaphoresis and confusion.", "incorrectas": {"A": "DKA results from severe insulin deficiency with unchecked lipolysis and ketogenesis, the opposite clinical scenario from excess/mistimed insulin relative to glucose intake seen here.", "C": "Lactic acidosis is classically associated with metformin accumulation (e.g. in renal failure), not with pramlintide or insulin dosing errors.", "D": "Hyperosmolar hyperglycemic state occurs with severe hyperglycemia and dehydration in type 2 diabetes, not from mistimed insulin causing low glucose."}}}, {"id": "anking-toxicities-side-effects-1900", "fuente": "anking", "tema": 29, "anki": "1462913649966", "q": "Which adverse effect is most commonly reported by patients starting pramlintide therapy?", "o": {"A": "Peripheral edema", "B": "GI upset (nausea, vomiting, anorexia)", "C": "Lactic acidosis", "D": "Genital mycotic infection"}, "r": "B", "e": {"correcta": "GI symptoms, particularly nausea, are the most common adverse effects of pramlintide, related to its physiologic actions of slowing gastric emptying and promoting satiety; these effects often improve with dose titration.", "incorrectas": {"A": "Peripheral edema and fluid retention are characteristic side effects of thiazolidinediones, not amylin analogs like pramlintide.", "C": "Lactic acidosis is a rare but serious risk associated with metformin accumulation, unrelated to amylin analog pharmacology.", "D": "Genital mycotic infections (yeast infections) are a known side effect of SGLT2 inhibitors due to glucosuria, not of pramlintide."}}}, {"id": "anking-endocrine-pharmacology-1901", "fuente": "anking", "tema": 24, "anki": "1462913659830", "q": "What is the correct route and timing of administration for pramlintide?", "o": {"A": "Oral tablet with breakfast only", "B": "Subcutaneous injection prior to meals", "C": "Intravenous infusion during meals", "D": "Subcutaneous injection once daily at bedtime"}, "r": "B", "e": {"correcta": "Pramlintide is a peptide hormone analog and would be degraded if taken orally, so it is given by subcutaneous injection, typically immediately before major meals to blunt the postprandial glucose rise, similar to how amylin is normally co-secreted with insulin at meals.", "incorrectas": {"A": "As a peptide, pramlintide cannot be given orally because it would be digested by GI proteases before absorption; it must be injected.", "C": "Pramlintide is not given intravenously; it is self-administered subcutaneously by the patient, similar to prandial insulin.", "D": "Dosing at bedtime would not address postprandial glucose spikes, which is the drug's specific therapeutic target; it must be given before meals, and typically with more than one meal per day."}}}, {"id": "anking-endocrine-pharmacology-1902", "fuente": "anking", "tema": 24, "anki": "1462913664323", "q": "Acarbose and miglitol used in type 2 diabetes management belong to which drug class?", "o": {"A": "Sulfonylureas", "B": "Alpha-glucosidase inhibitors", "C": "Biguanides", "D": "Meglitinides"}, "r": "B", "e": {"correcta": "Acarbose and miglitol are alpha-glucosidase inhibitors that act at the intestinal brush border to slow carbohydrate digestion and absorption, thereby reducing postprandial glucose excursions.", "incorrectas": {"A": "Sulfonylureas (e.g. glyburide, glipizide) close K+ATP channels on pancreatic beta cells to stimulate insulin release, a completely different mechanism from inhibiting carbohydrate digestion.", "C": "Biguanides (metformin) decrease hepatic gluconeogenesis and increase peripheral insulin sensitivity; they do not act on intestinal brush-border enzymes.", "D": "Meglitinides (e.g. repaglinide) also stimulate insulin secretion via K+ATP channel closure, similar to sulfonylureas but with shorter action, not by inhibiting digestive enzymes."}}}, {"id": "anking-endocrine-pharmacology-1903", "fuente": "anking", "tema": 24, "anki": "1462913681590", "q": "Alpha-glucosidase inhibitors like acarbose reduce the conversion of which dietary molecules into an absorbable form?", "o": {"A": "Triglycerides into free fatty acids", "B": "Disaccharides into monosaccharides", "C": "Polypeptides into amino acids", "D": "Amylose into disaccharides"}, "r": "B", "e": {"correcta": "Alpha-glucosidase inhibitors block the brush-border enzymes that hydrolyze disaccharides (e.g. sucrose, maltose) into absorbable monosaccharides (glucose, fructose), delaying carbohydrate absorption and blunting postprandial glucose rise.", "incorrectas": {"A": "Fat digestion involves pancreatic lipase acting on triglycerides, an entirely separate digestive pathway not affected by alpha-glucosidase inhibitors.", "C": "Protein digestion into amino acids depends on proteases (pepsin, trypsin, chymotrypsin), not brush-border alpha-glucosidases.", "D": "The conversion of starch (amylose) into disaccharides is carried out by amylases (salivary and pancreatic), an earlier digestive step upstream of the brush-border alpha-glucosidase step that acarbose targets."}}}, {"id": "anking-gastrointestinal-physiology-1904", "fuente": "anking", "tema": 39, "anki": "1462913702538", "q": "Acarbose and miglitol exert their anti-diabetic effect by acting at which anatomical location?", "o": {"A": "Renal proximal tubule", "B": "Pancreatic beta cells", "C": "Intestinal brush border", "D": "Hepatocyte glucose-6-phosphatase"}, "r": "C", "e": {"correcta": "Alpha-glucosidase inhibitors act locally at the intestinal brush border, where they reduce the activity of alpha-glucosidase enzymes, delaying carbohydrate hydrolysis and glucose absorption without being significantly systemically absorbed themselves.", "incorrectas": {"A": "The renal proximal tubule is the site of action of SGLT2 inhibitors, which block glucose reabsorption there, not the site targeted by alpha-glucosidase inhibitors.", "B": "Pancreatic beta cells are the target of insulin secretagogues like sulfonylureas and meglitinides, not alpha-glucosidase inhibitors, which act purely at the level of intestinal digestion.", "D": "Hepatic glucose-6-phosphatase is involved in glycogenolysis/gluconeogenesis output and is not a target of acarbose or miglitol, which act peripherally in the gut lumen."}}}, {"id": "anking-endocrine-pharmacology-1905", "fuente": "anking", "tema": 24, "anki": "1462913711724", "q": "Alpha-glucosidase inhibitors are primarily used to target which component of glycemic control in diabetes?", "o": {"A": "Fasting glucose levels", "B": "Postprandial glucose spike", "C": "Basal insulin requirement", "D": "Nocturnal hypoglycemia"}, "r": "B", "e": {"correcta": "By slowing carbohydrate breakdown and absorption at the intestinal brush border, alpha-glucosidase inhibitors specifically blunt the postprandial glucose spike; they are taken with meals at regular intervals throughout the day to achieve this effect.", "incorrectas": {"A": "Fasting glucose is more influenced by hepatic glucose output and basal insulin, not by drugs acting on carbohydrate digestion which only matters when food is being consumed.", "C": "Alpha-glucosidase inhibitors do not affect basal insulin needs; they have no direct action on insulin secretion or sensitivity.", "D": "These drugs are not associated with preventing nocturnal hypoglycemia; in fact if hypoglycemia occurs while on these agents, oral disaccharides won't work quickly (glucose tablets are needed) because sucrose digestion is impaired."}}}, {"id": "anking-endocrine-pharmacology-1906", "fuente": "anking", "tema": 24, "anki": "1462913747084", "q": "Canagliflozin, dapagliflozin, and empagliflozin all belong to which class of antidiabetic drugs?", "o": {"A": "GLP-1 receptor agonists", "B": "SGLT2 inhibitors", "C": "DPP-4 inhibitors", "D": "Alpha-glucosidase inhibitors"}, "r": "B", "e": {"correcta": "These three agents are SGLT2 (sodium-glucose cotransporter 2) inhibitors, which block glucose reabsorption in the proximal renal tubule, causing glucosuria and lowering blood glucose independent of insulin.", "incorrectas": {"A": "GLP-1 receptor agonists (e.g. exenatide, liraglutide) enhance glucose-dependent insulin secretion and slow gastric emptying, a different mechanism and different drug names than the gliflozins listed.", "C": "DPP-4 inhibitors (e.g. sitagliptin, saxagliptin, linagliptin) prevent degradation of endogenous incretins, unrelated to renal glucose transport, which is the SGLT2 mechanism.", "D": "Alpha-glucosidase inhibitors (acarbose, miglitol) act at the intestinal brush border, an entirely different site and mechanism from the renal-acting gliflozins."}}}, {"id": "anking-endocrine-pharmacology-1907", "fuente": "anking", "tema": 24, "anki": "1462913773816", "q": "A patient started on canagliflozin for type 2 diabetes has a urinalysis showing an unexpected finding related to the drug's mechanism. What is this finding?", "o": {"A": "Ketonuria", "B": "Proteinuria", "C": "Glucosuria", "D": "Hematuria"}, "r": "C", "e": {"correcta": "SGLT2 inhibitors block glucose reabsorption in the proximal tubule, causing intentional glucosuria as their mechanism of lowering serum glucose; this expected glucosuria also explains their associated risk of genital and urinary infections.", "incorrectas": {"B": "Proteinuria is not a direct expected effect of SGLT2 inhibition; these drugs may actually have some renoprotective effects in diabetic nephropathy by reducing intraglomerular pressure.", "A": "Ketonuria can occur as a rare adverse effect (euglycemic diabetic ketoacidosis) with SGLT2 inhibitors, but it is not the expected/mechanistic urinary finding — glucosuria is the direct, intended pharmacologic effect.", "D": "Hematuria is not an expected or characteristic finding associated with SGLT2 inhibitor use; it is not part of their mechanism of action."}}}, {"id": "anking-renal-physiology-1908", "fuente": "anking", "tema": 12, "anki": "1462913780255", "q": "SGLT2 inhibitors block glucose reabsorption at which segment of the nephron?", "o": {"A": "Thick ascending limb of the loop of Henle", "B": "Distal convoluted tubule", "C": "Proximal tubule", "D": "Collecting duct"}, "r": "C", "e": {"correcta": "SGLT2 is the major sodium-glucose cotransporter responsible for the majority of glucose reabsorption, located in the early proximal convoluted tubule; inhibiting it causes glucose (along with sodium) to remain in the tubular fluid and be excreted in urine.", "incorrectas": {"A": "The thick ascending limb reabsorbs sodium, potassium, and chloride via the Na-K-2Cl cotransporter (target of loop diuretics), not glucose via SGLT2.", "B": "The distal convoluted tubule reabsorbs sodium and chloride via the Na-Cl cotransporter (target of thiazide diuretics), not glucose.", "D": "The collecting duct is where aldosterone and ADH act on sodium and water reabsorption, respectively; it is not a site of significant glucose reabsorption."}}}, {"id": "anking-toxicities-side-effects-1909", "fuente": "anking", "tema": 29, "anki": "1462913801840", "q": "A woman on canagliflozin presents with dysuria and urinary frequency. Which adverse effect of SGLT2 inhibitors explains this presentation?", "o": {"A": "Increased risk of urinary tract infection", "B": "Direct bladder irritation from the drug", "C": "Drug-induced neurogenic bladder", "D": "Interstitial nephritis"}, "r": "A", "e": {"correcta": "By increasing urinary glucose concentration, SGLT2 inhibitors create a favorable environment for bacterial growth, raising the risk of urinary tract infections in patients taking these drugs.", "incorrectas": {"B": "SGLT2 inhibitors do not cause direct chemical irritation of the bladder wall; the increased infection risk is due to the glucose-rich urine promoting microbial growth, not a direct irritant effect.", "C": "Neurogenic bladder involves impaired nerve control of bladder function (e.g. from diabetic autonomic neuropathy) and is not a described mechanism of SGLT2 inhibitor toxicity.", "D": "Interstitial nephritis is typically a hypersensitivity reaction associated with drugs like NSAIDs or certain antibiotics, not an established mechanism for SGLT2 inhibitor-related genitourinary symptoms."}}}, {"id": "anking-toxicities-side-effects-1910", "fuente": "anking", "tema": 29, "anki": "1462913811151", "q": "A woman taking an SGLT2 inhibitor for diabetes develops vulvovaginal itching and discharge. What is the most likely cause?", "o": {"A": "Bacterial vaginosis from altered vaginal flora pH", "B": "Vaginal candidiasis (yeast infection)", "C": "Trichomonas vaginalis infection", "D": "Contact dermatitis from drug excretion in urine"}, "r": "B", "e": {"correcta": "The glucosuria caused by SGLT2 inhibitors provides a nutrient-rich environment that promotes fungal overgrowth, making genital mycotic infections (vulvovaginal candidiasis in women, balanitis in men) one of the most common adverse effects of this drug class.", "incorrectas": {"A": "Bacterial vaginosis is related to disruption of normal lactobacilli-dominant flora and is not the characteristic infection linked to SGLT2 inhibitor-induced glucosuria; a yeast infection is the classic association.", "C": "Trichomonas is a sexually transmitted protozoal infection unrelated to glucosuria and not a recognized SGLT2 inhibitor side effect.", "D": "There is no described mechanism of direct contact dermatitis from the drug being excreted in urine; the vulvovaginal symptoms arise from fungal overgrowth due to glucose-rich urine, not a chemical skin reaction."}}}, {"id": "anking-toxicities-side-effects-1911", "fuente": "anking", "tema": 29, "anki": "1462913833610", "q": "An elderly patient on empagliflozin reports dizziness upon standing. Which mechanism best explains this SGLT2 inhibitor adverse effect?", "o": {"A": "Direct vasodilation of arterioles", "B": "Orthostatic hypotension due to osmotic diuresis", "C": "Bradycardia from autonomic dysfunction", "D": "Hyponatremia-induced cerebral edema"}, "r": "B", "e": {"correcta": "SGLT2 inhibitors cause osmotic diuresis by increasing urinary glucose (and accompanying water) loss, which can lead to volume depletion and dehydration, manifesting clinically as orthostatic hypotension, especially in elderly or volume-sensitive patients.", "incorrectas": {"A": "SGLT2 inhibitors do not have a direct vasodilatory effect on arterioles; the hypotension arises from intravascular volume depletion via osmotic diuresis, not vascular tone changes.", "C": "There is no established mechanism by which SGLT2 inhibitors cause bradycardia or autonomic dysfunction; the orthostatic symptoms are volume-related, not related to heart rate control.", "D": "SGLT2 inhibitors do not typically cause hyponatremia or cerebral edema; the diuresis is osmotic in nature and if anything can concentrate serum sodium slightly, not dilute it."}}}, {"id": "anking-renal-pharmacology-1912", "fuente": "anking", "tema": 59, "anki": "1462913839886", "q": "SGLT2 inhibitors are contraindicated or require dose adjustment in patients with which condition?", "o": {"A": "Hepatic insufficiency", "B": "Renal insufficiency", "C": "Adrenal insufficiency", "D": "Thyroid dysfunction"}, "r": "B", "e": {"correcta": "Because SGLT2 inhibitors depend on adequate glomerular filtration to deliver glucose to the proximal tubule for their effect, and because they can worsen volume depletion, they are contraindicated or require caution in patients with significant renal insufficiency, where their efficacy also declines.", "incorrectas": {"A": "Hepatic insufficiency is not the primary organ dysfunction of concern for SGLT2 inhibitors; their mechanism and major precautions are centered on renal function and volume status.", "C": "Adrenal insufficiency is not a specific contraindication for SGLT2 inhibitors; this class's key caution relates to renal function, not adrenal hormone status.", "D": "Thyroid dysfunction has no established interaction with SGLT2 inhibitor mechanism or dosing; the drug class's key limiting factor is kidney function."}}}, {"id": "anking-reproductive-system-embryology-1913", "fuente": "anking", "tema": 33, "anki": "1462932114470", "q": "The germ cells of the female gonad that undergo meiosis to eventually form the ovum are called what?", "o": {"A": "Spermatogonia", "B": "Oogonia", "C": "Primordial germ cells only (pre-meiotic)", "D": "Polar bodies"}, "r": "B", "e": {"correcta": "Oogonia are the diploid germ cells of the female gonad that proliferate by mitosis and then enter meiosis; once surrounded by granulosa cells and stroma, these meiotically arrested cells are termed primary oocytes.", "incorrectas": {"A": "Spermatogonia are the analogous male germ cells found in the seminiferous tubules of the testis, not the female gonad.", "C": "Primordial germ cells are the earliest precursor cells that migrate to the gonadal ridge before differentiating into oogonia; the term oogonia specifically refers to the female germ cells once established in the ovary.", "D": "Polar bodies are the small, non-functional byproducts extruded during the unequal divisions of meiosis in oocyte maturation, not the germ cells themselves."}}}, {"id": "anking-reproductive-system-physiology-1914", "fuente": "anking", "tema": 32, "anki": "1462932142648", "q": "Which ovarian cell type is primarily responsible for synthesizing progesterone?", "o": {"A": "Granulosa cells", "B": "Theca cells", "C": "Oocytes", "D": "Corpus albicans stromal cells"}, "r": "B", "e": {"correcta": "Theca cells, stimulated by LH, synthesize progesterone and androgens (androstenedione) from cholesterol; the androgens are then transferred to granulosa cells, which aromatize them into estrogen under FSH stimulation.", "incorrectas": {"A": "Granulosa cells primarily convert theca-derived androgens into estrogen via aromatase and, after ovulation, contribute to corpus luteum progesterone production, but the theca cells are the classic site of primary progesterone synthesis in the two-cell model.", "C": "Oocytes are the gametes themselves and do not have significant steroidogenic capacity; hormone synthesis is carried out by the surrounding somatic (theca and granulosa) cells.", "D": "The corpus albicans is the involuted, fibrotic remnant of the corpus luteum after it regresses and is hormonally inactive, not a site of progesterone synthesis."}}}, {"id": "anking-reproductive-system-physiology-1915", "fuente": "anking", "tema": 32, "anki": "1462932191528", "q": "The combined activity of theca cells and granulosa cells in the ovarian follicle produces which hormone via the two-cell, two-gonadotropin model?", "o": {"A": "Progesterone alone", "B": "Testosterone", "C": "Estradiol (estrogen)", "D": "Inhibin B"}, "r": "C", "e": {"correcta": "In the two-cell model, LH stimulates theca cells to produce androstenedione, which diffuses to granulosa cells where FSH-induced aromatase converts it into estradiol, making estrogen production a cooperative product of both cell types.", "incorrectas": {"A": "Progesterone is produced predominantly by theca cells (and later by the corpus luteum), not as the joint product of theca and granulosa cell cooperation described in the two-cell model, which specifically explains estrogen synthesis.", "B": "Testosterone/androstenedione is the intermediate product made by theca cells alone; granulosa cells then convert it to estrogen rather than testosterone being the final joint product.", "D": "Inhibin B is produced by granulosa cells to provide negative feedback on FSH, but it is not the hormone produced through theca-granulosa cooperation in the classic two-cell model."}}}, {"id": "anking-reproductive-system-embryology-1916", "fuente": "anking", "tema": 33, "anki": "1462932197787", "q": "Which two testicular hormones are essential for determining male internal and external genital differentiation during embryogenesis?", "o": {"A": "Testosterone and estrogen", "B": "Anti-müllerian hormone and testosterone", "C": "LH and FSH", "D": "Inhibin and activin"}, "r": "B", "e": {"correcta": "The fetal testes secrete anti-müllerian hormone (from Sertoli cells), which causes regression of the müllerian ducts, and testosterone (from Leydig cells), which stimulates the wolffian ducts to differentiate into male internal genitalia; together these hormones are decisive for the male phenotype.", "incorrectas": {"A": "Estrogen is not a determining hormone for the male phenotype in this context; the two decisive testicular hormones are anti-müllerian hormone and testosterone, not estrogen.", "C": "LH and FSH are pituitary gonadotropins that stimulate Leydig and Sertoli cell function respectively, but they are not themselves the testicular hormones that directly drive genital differentiation.", "D": "Inhibin and activin regulate FSH secretion via feedback but are not the hormones responsible for directing wolffian duct differentiation or müllerian duct regression."}}}, {"id": "anking-reproductive-system-embryology-1917", "fuente": "anking", "tema": 33, "anki": "1462932210004", "q": "Sertoli cells secrete anti-müllerian hormone while Leydig cells secrete testosterone in the developing male fetus, both required for male phenotype development. What do gonadal males' testes secrete to trigger differentiation of male internal genitalia?", "o": {"A": "Anti-müllerian hormone and testosterone", "B": "Estrogen and progesterone", "C": "DHEA-S only", "D": "Inhibin only"}, "r": "A", "e": {"correcta": "The fetal testes secrete both anti-müllerian hormone, which suppresses the müllerian (paramesonephric) ducts, and testosterone, which stimulates the wolffian (mesonephric) ducts to differentiate into the epididymis, vas deferens, and seminal vesicles — together establishing the male internal genital phenotype.", "incorrectas": {"B": "Estrogen and progesterone are ovarian/placental hormones relevant to female reproductive physiology, not the testicular hormones driving male internal genitalia development.", "C": "DHEA-S is largely an adrenal androgen precursor and is not the primary hormone responsible for wolffian duct differentiation; that role belongs to testosterone secreted by Leydig cells.", "D": "Inhibin from Sertoli cells regulates FSH feedback but does not drive wolffian duct differentiation; anti-müllerian hormone (not inhibin) is the Sertoli cell product responsible for müllerian duct regression."}}}, {"id": "anking-reproductive-system-embryology-1918", "fuente": "anking", "tema": 33, "anki": "1462932310717", "q": "In the absence of which hormone do the wolffian ducts fail to differentiate into male internal genitalia, as occurs in gonadal females?", "o": {"A": "Anti-müllerian hormone", "B": "Estradiol", "C": "Testosterone", "D": "LH"}, "r": "C", "e": {"correcta": "Testosterone secreted by fetal Leydig cells is required to stimulate the wolffian (mesonephric) ducts to differentiate into the epididymis, vas deferens, and seminal vesicles. In gonadal females, who lack testes and thus lack testosterone, the wolffian ducts regress by default rather than differentiating.", "incorrectas": {"A": "Anti-müllerian hormone acts on the müllerian ducts, causing their regression, not on the wolffian ducts; its absence would cause persistence of müllerian structures, not failure of wolffian duct differentiation.", "B": "Estradiol is not the hormone responsible for wolffian duct stimulation; the female pathway occurs by default from the absence of testosterone and anti-müllerian hormone, not from an active estrogen effect on the ducts.", "D": "LH stimulates Leydig cells to produce testosterone, but it is testosterone itself acting locally on the wolffian duct mesenchyme that drives differentiation; LH is upstream of the actual effector hormone."}}}, {"id": "anking-reproductive-system-embryology-1919", "fuente": "anking", "tema": 33, "anki": "1462932318824", "q": "In gonadal females who lack testes and therefore lack fetal testicular hormone secretion, why do the müllerian ducts persist and develop into female internal genitalia?", "o": {"A": "Absence of testosterone", "B": "Absence of anti-müllerian hormone", "C": "Presence of maternal estrogen", "D": "Absence of GnRH"}, "r": "B", "e": {"correcta": "Anti-müllerian hormone, normally secreted by fetal Sertoli cells, actively suppresses the müllerian ducts in males; in its absence (as in gonadal females, who lack testes), the müllerian ducts are not suppressed and default to developing into the fallopian tubes, uterus, and upper vagina.", "incorrectas": {"A": "Absence of testosterone explains why the wolffian ducts regress (they require testosterone to persist and differentiate), not why the müllerian ducts survive — that depends specifically on the absence of anti-müllerian hormone.", "C": "Female internal genital development follows a default pathway that does not require maternal or fetal estrogen; müllerian duct persistence is due to the absence of anti-müllerian hormone, not the presence of estrogen.", "D": "GnRH regulates gonadotropin secretion later in reproductive life and puberty; it is not the factor responsible for müllerian duct fate during early fetal sexual differentiation."}}}, {"id": "anking-reproductive-system-physiology-1920", "fuente": "anking", "tema": 32, "anki": "1462933184944", "q": "After the onset of puberty, pulsatile GnRH secretion from the hypothalamus drives parallel pulsatile secretion of which anterior pituitary hormones?", "o": {"A": "ACTH and TSH", "B": "FSH and LH", "C": "Prolactin and GH", "D": "Oxytocin and ADH"}, "r": "B", "e": {"correcta": "Pulsatile GnRH release stimulates the gonadotroph cells of the anterior pituitary to secrete FSH and LH in a corresponding pulsatile pattern; these gonadotropins then drive gonadal sex steroid production, which underlies the physical changes of puberty.", "incorrectas": {"A": "ACTH and TSH are regulated by CRH and TRH respectively, hypothalamic hormones distinct from GnRH and unrelated to the pubertal gonadotropin axis.", "C": "Prolactin is regulated primarily by dopamine (inhibitory) and GH by GHRH/somatostatin; neither is directly driven by pulsatile GnRH secretion.", "D": "Oxytocin and ADH are synthesized in the hypothalamus but released from the posterior pituitary, and are unrelated to the GnRH-gonadotropin axis."}}}, {"id": "anking-reproductive-system-physiology-1921", "fuente": "anking", "tema": 32, "anki": "1462933218218", "q": "At the onset of puberty, increasing pulsatile GnRH secretion has what effect on its own receptor expression in the anterior pituitary?", "o": {"A": "Down-regulates the receptor, decreasing sensitivity", "B": "Up-regulates the receptor, increasing sensitivity", "C": "Has no effect on receptor expression", "D": "Causes receptor internalization and desensitization"}, "r": "B", "e": {"correcta": "During puberty, pulsatile (rather than continuous) GnRH secretion up-regulates its own receptor on gonadotroph cells, increasing pituitary sensitivity to GnRH and amplifying FSH/LH secretion — a self-priming effect that helps drive pubertal maturation.", "incorrectas": {"A": "Down-regulation of the GnRH receptor occurs with continuous (non-pulsatile) GnRH exposure, such as with GnRH agonist therapy used to suppress the axis, not with the normal pulsatile pattern seen in puberty.", "C": "GnRH does have a well-described self-priming effect on its receptor; pulsatile secretion is not neutral but actively increases receptor expression and sensitivity.", "D": "Receptor internalization/desensitization is the mechanism exploited therapeutically by continuous GnRH agonist administration (e.g. leuprolide) to suppress gonadotropins, not the physiologic pubertal pattern of pulsatile stimulation."}}}, {"id": "anking-reproductive-system-physiology-1922", "fuente": "anking", "tema": 32, "anki": "1462981484465", "q": "Hypothalamic regulation of spermatogenesis and testosterone secretion is mediated through which hormone?", "o": {"A": "Inhibin B", "B": "GnRH", "C": "Prolactin", "D": "Activin"}, "r": "B", "e": {"correcta": "GnRH, released in a pulsatile fashion from the hypothalamus, stimulates the anterior pituitary to secrete LH and FSH; LH acts on Leydig cells to produce testosterone, while FSH acts on Sertoli cells to support spermatogenesis, making GnRH the apex regulator of this axis.", "incorrectas": {"A": "Inhibin B is produced by Sertoli cells and provides negative feedback specifically on FSH secretion; it is a downstream regulator, not the hypothalamic hormone initiating the axis.", "C": "Prolactin, when elevated pathologically, can suppress GnRH and thus the reproductive axis, but it is not itself the hypothalamic hormone that drives spermatogenesis and testosterone production.", "D": "Activin stimulates FSH secretion at the pituitary level (opposing inhibin), but it is not the primary hypothalamic hormone controlling the overall axis; that role belongs to GnRH."}}}, {"id": "anking-reproductive-system-anatomy-1923", "fuente": "anking", "tema": 34, "anki": "1462981781486", "q": "GnRH is primarily secreted by which hypothalamic nuclei?", "o": {"A": "Suprachiasmatic nucleus", "B": "Preoptic nuclei (also arcuate nuclei)", "C": "Paraventricular nucleus", "D": "Ventromedial nucleus"}, "r": "B", "e": {"correcta": "GnRH neurons originate primarily in the preoptic area (and arcuate nucleus) of the hypothalamus and secrete GnRH into the hypothalamic-hypophyseal portal system; these neurons migrate from the olfactory placode during development, guided by anosmin-1, which is why Kallmann syndrome (anosmin-1 mutation) causes both anosmia and hypogonadotropic hypogonadism.", "incorrectas": {"A": "The suprachiasmatic nucleus is the master circadian clock, regulating sleep-wake cycles via light input from the retina, not GnRH secretion.", "C": "The paraventricular nucleus mainly produces oxytocin, ADH, and CRH, not GnRH.", "D": "The ventromedial nucleus is classically associated with satiety regulation, not GnRH secretion."}}}, {"id": "anking-reproductive-system-physiology-1924", "fuente": "anking", "tema": 32, "anki": "1462981797259", "q": "Pulsatile secretion of hypothalamic GnRH stimulates the anterior pituitary to release which two hormones?", "o": {"A": "TSH and prolactin", "B": "ACTH and GH", "C": "FSH and LH", "D": "Oxytocin and vasopressin"}, "r": "C", "e": {"correcta": "Pulsatile GnRH stimulates gonadotroph cells to secrete both FSH and LH; notably, this pulsatility is essential — continuous, non-pulsatile GnRH exposure paradoxically inhibits FSH/LH secretion by down-regulating GnRH receptors, a principle exploited by GnRH agonist drugs used to suppress the reproductive axis.", "incorrectas": {"A": "TSH is regulated by TRH and prolactin mainly by dopamine (inhibitory tone); neither is under GnRH control.", "B": "ACTH is regulated by CRH and GH by GHRH/somatostatin, entirely separate hypothalamic-pituitary axes from the GnRH-gonadotropin system.", "D": "Oxytocin and vasopressin (ADH) are synthesized in hypothalamic nuclei but released from the posterior pituitary, unrelated to the anterior pituitary gonadotropin response to GnRH."}}}, {"id": "anking-reproductive-system-physiology-1925", "fuente": "anking", "tema": 32, "anki": "1462981887544", "q": "What effect does rising testosterone have on hypothalamic GnRH secretion via negative feedback?", "o": {"A": "Increased secretion", "B": "Decreased secretion", "C": "No effect on GnRH, only on LH directly", "D": "Biphasic: initially increased, then decreased"}, "r": "B", "e": {"correcta": "Testosterone exerts negative feedback on the hypothalamus, decreasing GnRH pulse secretion (and also acts directly on the pituitary to reduce LH release), which is the physiologic basis for the hypothalamic-pituitary-gonadal axis's homeostatic regulation of testosterone levels.", "incorrectas": {"A": "Rising testosterone does not stimulate further GnRH release; that would create unchecked positive feedback rather than the homeostatic negative feedback loop that actually governs the axis.", "C": "Testosterone feedback acts at both the hypothalamic level (suppressing GnRH) and the pituitary level (suppressing LH sensitivity/secretion), not exclusively at the pituitary.", "D": "There is no biphasic feedback pattern for testosterone on GnRH in normal male physiology; the relationship is a straightforward negative feedback loop."}}}, {"id": "anking-reproductive-system-physiology-1926", "fuente": "anking", "tema": 32, "anki": "1462981954788", "q": "Which androgen is primarily responsible for libido in men?", "o": {"A": "Dihydrotestosterone (DHT)", "B": "Testosterone", "C": "Androstenedione", "D": "Estradiol"}, "r": "B", "e": {"correcta": "Testosterone, the principal circulating androgen secreted by Leydig cells, is responsible for libido, along with muscle mass, spermatogenesis support, and deepening of the voice, making it functionally distinct from its more potent derivative DHT, which governs external genitalia development.", "incorrectas": {"A": "DHT, formed from testosterone via 5-alpha-reductase, is more potent at the androgen receptor but is specifically responsible for differentiation of external male genitalia and male pattern hair distribution, not libido.", "C": "Androstenedione is a weaker adrenal/gonadal androgen precursor that can be converted to testosterone or estrone; it is not the primary driver of male libido.", "D": "Estradiol in men (derived from aromatization of testosterone) contributes to bone health and epiphyseal closure, not primarily to libido, which is testosterone-driven."}}}, {"id": "anking-reproductive-system-embryology-1927", "fuente": "anking", "tema": 33, "anki": "1462981959318", "q": "Differentiation of the external male genitalia (penis and scrotum) during fetal development depends primarily on which androgen?", "o": {"A": "Testosterone", "B": "Dihydrotestosterone (DHT)", "C": "Androstenedione", "D": "Estrone"}, "r": "B", "e": {"correcta": "Testosterone is converted locally by 5-alpha-reductase into DHT, which is the more potent androgen responsible for virilization of the external genitalia (penis, scrotum, prostate); this explains why 5-alpha-reductase deficiency results in ambiguous or female-appearing external genitalia despite normal testes and testosterone levels.", "incorrectas": {"A": "Testosterone itself drives internal genital differentiation (wolffian duct derivatives — epididymis, vas deferens, seminal vesicles) and must be converted to DHT for external genitalia virilization, illustrated clinically by 5-alpha-reductase deficiency where testosterone is normal but external genitalia fail to virilize.", "C": "Androstenedione is a weaker precursor androgen, not the potent hormone driving external genital differentiation; that role belongs specifically to DHT.", "D": "Estrone is a weak estrogen and plays no role in male external genitalia development, which depends on androgen (DHT) signaling."}}}, {"id": "anking-reproductive-system-physiology-1928", "fuente": "anking", "tema": 32, "anki": "1462981965951", "q": "Which androgen is responsible for differentiation of the prostate during male fetal development?", "o": {"A": "Testosterone", "B": "Dihydrotestosterone (DHT)", "C": "Androstenedione", "D": "Estradiol"}, "r": "B", "e": {"correcta": "DHT, formed from testosterone by 5-alpha-reductase in target tissues, drives differentiation of the male external genitalia and prostate in utero. Testosterone alone drives the internal genitalia (epididymis, vas deferens, seminal vesicles) from the Wolffian ducts, but the prostate specifically requires DHT.", "incorrectas": {"A": "Testosterone is responsible for differentiation of the Wolffian duct structures (epididymis, vas deferens, seminal vesicles, ejaculatory ducts), not the prostate or external genitalia, which require conversion to DHT.", "C": "Androstenedione is a weaker adrenal/gonadal androgen precursor that can be converted to testosterone or estrone, but it is not the active hormone driving prostatic differentiation.", "D": "Estradiol is the primary estrogen and plays no role in prostate differentiation; it is instead involved in feedback regulation of the hypothalamic-pituitary-gonadal axis and, in males, contributes to epiphyseal closure."}}}, {"id": "anking-reproductive-system-physiology-1929", "fuente": "anking", "tema": 32, "anki": "1462981972669", "q": "Which androgen is most directly associated with prostate growth throughout adult life, and is targeted by 5-alpha-reductase inhibitors in benign prostatic hyperplasia?", "o": {"A": "Androstenedione", "B": "Testosterone", "C": "Dihydrotestosterone (DHT)", "D": "Estrone"}, "r": "C", "e": {"correcta": "DHT is the potent androgen that continues to stimulate prostatic epithelial and stromal growth throughout life, and its overproduction contributes to benign prostatic hyperplasia. Drugs like finasteride block 5-alpha-reductase, the enzyme that converts testosterone to DHT, to shrink the prostate.", "incorrectas": {"A": "Androstenedione is a weak precursor androgen produced by the adrenal cortex and gonads that must be converted to testosterone or estrogen to exert significant effects; it is not the main driver of prostate growth.", "B": "Testosterone is the precursor to DHT and does stimulate some prostatic tissue, but it is the locally converted DHT (via 5-alpha-reductase) that has the dominant trophic effect on the prostate.", "D": "Estrone is a weak estrogen formed from androstenedione via aromatase; it is not primarily responsible for prostate growth, though relative excess with aging has been implicated in BPH pathogenesis as a secondary factor."}}}, {"id": "anking-reproductive-system-physiology-1930", "fuente": "anking", "tema": 32, "anki": "1462981980045", "q": "Which androgen is primarily responsible for the male-pattern hair distribution and androgenetic alopecia (balding)?", "o": {"A": "Testosterone", "B": "Androstenedione", "C": "Estradiol", "D": "Dihydrotestosterone (DHT)"}, "r": "D", "e": {"correcta": "DHT acts on hair follicles in the scalp and body to produce the male pattern of terminal hair growth and, paradoxically, to miniaturize scalp follicles in genetically susceptible men, causing androgenetic alopecia. This is why 5-alpha-reductase inhibitors (finasteride) are used to treat male pattern baldness.", "incorrectas": {"A": "Testosterone is the precursor that must be locally converted to DHT by 5-alpha-reductase within hair follicles to produce these effects; testosterone itself is less potent at the androgen receptor in these tissues.", "B": "Androstenedione is a weak intermediate androgen that contributes little directly to hair pattern effects compared with the more potent DHT.", "C": "Estradiol is an estrogen, not an androgen, and does not drive male-pattern hair growth or balding; if anything, estrogens are associated with hair retention rather than androgenic alopecia."}}}, {"id": "anking-reproductive-system-physiology-1931", "fuente": "anking", "tema": 32, "anki": "1462981986014", "q": "Which androgen is chiefly responsible for stimulating sebaceous gland activity (contributing to acne)?", "o": {"A": "Dihydrotestosterone (DHT)", "B": "Testosterone", "C": "Androstenedione", "D": "Progesterone"}, "r": "A", "e": {"correcta": "DHT is the most potent androgen at the androgen receptor and strongly stimulates sebaceous gland activity, which is why increased androgen states (like puberty or PCOS) are associated with acne. Local conversion of testosterone to DHT by 5-alpha-reductase in the skin is key to this effect.", "incorrectas": {"B": "Testosterone does contribute to sebaceous gland stimulation, but its effect is markedly weaker than DHT because DHT binds the androgen receptor with much higher affinity and cannot be converted back to testosterone.", "C": "Androstenedione is a weak precursor androgen with minimal direct receptor activity; its effects on sebaceous glands are indirect, via conversion to more potent androgens.", "D": "Progesterone is a progestin, not an androgen, and does not meaningfully stimulate sebaceous gland activity; it is more relevant to endometrial and myometrial physiology."}}}, {"id": "anking-reproductive-system-physiology-1932", "fuente": "anking", "tema": 32, "anki": "1462982024044", "q": "In males, circulating androgens are peripherally converted into which class of hormone by the enzyme cytochrome P-450 aromatase?", "o": {"A": "Glucocorticoids", "B": "Estrogens", "C": "Mineralocorticoids", "D": "Progestins"}, "r": "B", "e": {"correcta": "Aromatase (CYP19) converts androgens such as testosterone and androstenedione into estrogens (estradiol and estrone, respectively). In males, this peripheral aromatization is a normal physiologic source of circulating estrogen, important for bone maturation and epiphyseal closure.", "incorrectas": {"A": "Glucocorticoids like cortisol are synthesized from cholesterol in the adrenal zona fasciculata via a distinct steroidogenic pathway (11-beta and 17-alpha hydroxylases), not via aromatization of androgens.", "C": "Mineralocorticoids like aldosterone arise from the adrenal zona glomerulosa through a pathway that does not involve aromatase; aromatase acts specifically on androgens to yield estrogens.", "D": "Progestins like progesterone are precursors upstream of androgens in steroidogenesis, formed from pregnenolone, and are not the products of aromatase activity on androgens."}}}, {"id": "anking-reproductive-system-physiology-1933", "fuente": "anking", "tema": 32, "anki": "1462982032546", "q": "In males, aromatization of androgens to estrogen occurs primarily in which two tissues?", "o": {"A": "Liver and kidney", "B": "Adrenal cortex and skin", "C": "Adipose tissue and the testis", "D": "Skeletal muscle and bone"}, "r": "C", "e": {"correcta": "In males, adipose tissue and the testis (specifically Sertoli cells, which express aromatase in response to FSH) are the primary sites of peripheral androgen-to-estrogen conversion. This is clinically relevant because increased adiposity (as in obesity) raises aromatase activity and estrogen levels, which can suppress the hypothalamic-pituitary-gonadal axis.", "incorrectas": {"A": "The liver metabolizes and conjugates steroid hormones for excretion and the kidney excretes their metabolites, but neither is a major site of aromatase-mediated estrogen synthesis in males.", "B": "The adrenal cortex synthesizes androgen precursors (like DHEA) but has relatively low aromatase activity; skin has only minor aromatase activity compared to fat and testis.", "D": "Skeletal muscle and bone are targets of estrogen action (e.g., epiphyseal closure) rather than major sites of aromatase-driven estrogen production."}}}, {"id": "anking-reproductive-system-physiology-1934", "fuente": "anking", "tema": 32, "anki": "1462982063732", "q": "Which enzyme is the key catalyst converting androgens (testosterone and androstenedione) into estrogens?", "o": {"A": "5-alpha-reductase", "B": "Aromatase", "C": "17-beta-hydroxysteroid dehydrogenase", "D": "3-beta-hydroxysteroid dehydrogenase"}, "r": "B", "e": {"correcta": "Aromatase (cytochrome P-450 aromatase, CYP19) catalyzes the aromatization of the A-ring of androgens, converting testosterone to estradiol and androstenedione to estrone. It is expressed in the ovarian granulosa cells, testis, adipose tissue, and placenta.", "incorrectas": {"A": "5-alpha-reductase converts testosterone to the more potent androgen DHT; it does not produce estrogens and works in the opposite direction of increasing androgenic potency.", "C": "17-beta-hydroxysteroid dehydrogenase interconverts weaker and more potent forms of androgens and estrogens (e.g., androstenedione to testosterone, estrone to estradiol), but it is not the enzyme responsible for the aromatization step itself.", "D": "3-beta-hydroxysteroid dehydrogenase converts pregnenolone to progesterone and DHEA to androstenedione earlier in the steroidogenic pathway, upstream of the aromatization step."}}}, {"id": "anking-reproductive-system-physiology-1935", "fuente": "anking", "tema": 32, "anki": "1462982091710", "q": "Ranking androgens by potency at the androgen receptor from most to least potent, which order is correct?", "o": {"A": "Testosterone > DHT > androstenedione", "B": "Androstenedione > testosterone > DHT", "C": "DHT > testosterone > androstenedione", "D": "DHT > androstenedione > testosterone"}, "r": "C", "e": {"correcta": "DHT is the most potent androgen because it binds the androgen receptor with the highest affinity and dissociates more slowly, followed by testosterone, with androstenedione (a weak precursor androgen) being the least potent of the three.", "incorrectas": {"A": "This reverses DHT and testosterone; DHT is actually more potent than testosterone at the androgen receptor due to its higher binding affinity, not the other way around.", "B": "This places androstenedione, the weakest of the three androgens, at the top, which is incorrect; androstenedione must be converted to testosterone (or estrone) to exert significant hormonal effects.", "D": "This correctly ranks DHT first but incorrectly places the weak precursor androstenedione above testosterone, when testosterone is substantially more potent than androstenedione."}}}, {"id": "anking-reproductive-system-anatomy-1936", "fuente": "anking", "tema": 34, "anki": "1462984351263", "q": "The middle layer of the ovary, containing a mixture of cell types including connective tissue, vessels, and nerves, is called the?", "o": {"A": "Cortex", "B": "Medulla", "C": "Hilum", "D": "Germinal epithelium"}, "r": "B", "e": {"correcta": "The ovarian medulla is the middle layer, sandwiched between the outer cortex (which contains the follicles) and the inner hilum. It is composed of a heterogeneous mixture of loose connective tissue, blood vessels, lymphatics, and nerve fibers that support the ovary.", "incorrectas": {"A": "The cortex is the outer, follicle-containing layer of the ovary, distinct from the vascular and connective-tissue-rich medulla in the middle.", "C": "The hilum is the innermost point of attachment where vessels and lymphatics enter/exit the ovary, not the middle layer with mixed cell types.", "D": "The germinal epithelium is the single layer of surface mesothelial cells covering the ovary, unrelated to the internal medullary layer."}}}, {"id": "anking-reproductive-system-anatomy-1937", "fuente": "anking", "tema": 34, "anki": "1462984357903", "q": "The inner layer of the ovary, through which blood vessels and lymphatics pass, is called the?", "o": {"A": "Cortex", "B": "Medulla", "C": "Hilum", "D": "Tunica albuginea"}, "r": "C", "e": {"correcta": "The hilum is the innermost part of the ovary and serves as the point of entry and exit for the ovarian blood vessels, lymphatics, and nerves, analogous to the hilum of other organs like the kidney or lung.", "incorrectas": {"A": "The cortex is the outer layer housing the oocyte-containing follicles, structurally and functionally distinct from the vascular hilum.", "B": "The medulla is the middle layer with mixed connective tissue and vessels, positioned between the cortex and the hilum rather than being the innermost structure itself.", "D": "The tunica albuginea is a fibrous connective tissue layer beneath the ovarian surface epithelium, not the site of vascular entry and exit."}}}, {"id": "anking-reproductive-system-physiology-1938", "fuente": "anking", "tema": 32, "anki": "1462984377331", "q": "The functional unit of the ovaries, comprising a single germ cell surrounded by endocrine (granulosa and theca) cells, is called the?", "o": {"A": "Corpus luteum", "B": "Graafian follicle", "C": "Ovarian follicle", "D": "Corpus albicans"}, "r": "C", "e": {"correcta": "The ovarian follicle is the basic functional unit of the ovary, consisting of a single oocyte surrounded by supportive endocrine cells (granulosa cells, and later theca cells) that nourish the oocyte and produce sex steroid hormones under gonadotropin control.", "incorrectas": {"A": "The corpus luteum is a specific, transient endocrine structure formed from the residual follicle after ovulation, not the general functional unit present throughout follicular development.", "B": "The graafian follicle is a late, mature stage of follicular development (just before ovulation), representing one specific stage of the more general ovarian follicle.", "D": "The corpus albicans is the fibrous scar that remains after the corpus luteum degenerates when fertilization does not occur, representing an involuted endpoint rather than the functional unit."}}}, {"id": "anking-reproductive-system-physiology-1939", "fuente": "anking", "tema": 32, "anki": "1462984451980", "q": "Primary oocytes remain arrested in which phase of the cell cycle from fetal life until ovulation?", "o": {"A": "Metaphase II of meiosis II", "B": "Prophase I of meiosis I", "C": "Metaphase I of meiosis I", "D": "Anaphase II of meiosis II"}, "r": "B", "e": {"correcta": "Primary oocytes complete DNA replication and enter meiosis I during fetal development but arrest in prophase I (specifically the diplotene stage), remaining suspended there for years to decades until the LH surge triggers resumption of meiosis just before ovulation.", "incorrectas": {"A": "Metaphase II arrest occurs later, after the primary oocyte completes meiosis I and becomes a secondary oocyte; this arrest happens at ovulation, not before it.", "C": "Metaphase I is not a stable long-term arrest point in oogenesis; the prolonged arrest specifically occurs in prophase I, and once resumed, meiosis I proceeds relatively quickly to completion.", "D": "Anaphase II is a late stage of the second meiotic division, which only occurs after fertilization triggers completion of meiosis II; it is not where oocytes are held in prolonged arrest."}}}, {"id": "anking-reproductive-system-physiology-1940", "fuente": "anking", "tema": 32, "anki": "1462984486053", "q": "Secondary oocytes are arrested in which phase of the cell cycle until fertilization occurs?", "o": {"A": "Prophase I of meiosis I", "B": "Anaphase I of meiosis I", "C": "Metaphase II of meiosis II", "D": "Telophase II of meiosis II"}, "r": "C", "e": {"correcta": "After completing meiosis I at ovulation, the secondary oocyte begins meiosis II but arrests again in metaphase II, and remains there unless fertilization occurs, at which point the sperm entry triggers completion of meiosis II and extrusion of the second polar body.", "incorrectas": {"A": "Prophase I arrest describes the primary oocyte's long-standing arrest before ovulation, not the secondary oocyte, which has already completed meiosis I by the time it is released.", "B": "Anaphase I is a transient stage during the completion of meiosis I around the time of the LH surge, not a stable arrest point for the secondary oocyte.", "D": "Telophase II would represent completion of meiosis II, which only happens after fertilization; the secondary oocyte is arrested before this point, at metaphase II."}}}, {"id": "anking-reproductive-system-physiology-1941", "fuente": "anking", "tema": 32, "anki": "1462984508078", "q": "Primary oocytes are held in prophase I of meiosis I for years until which event triggers resumption of meiosis?", "o": {"A": "Fertilization", "B": "Menarche", "C": "Ovulation", "D": "Implantation"}, "r": "C", "e": {"correcta": "The mid-cycle LH surge triggers resumption of meiosis I in the dominant follicle just before ovulation, allowing the primary oocyte to complete meiosis I and become a secondary oocyte (which then arrests again in metaphase II) that is released at ovulation.", "incorrectas": {"A": "Fertilization triggers completion of the second meiotic arrest (metaphase II), not the first; it acts on the already-ovulated secondary oocyte, not the prophase I-arrested primary oocyte.", "B": "Menarche marks the onset of the first menstrual cycle and cyclic hormonal activity, but it does not itself trigger the resumption of meiosis in any single oocyte; that happens with each cycle's LH surge.", "D": "Implantation is a much later event in early pregnancy involving the blastocyst embedding in the endometrium, unrelated to the meiotic arrest and resumption of the oocyte."}}}, {"id": "anking-reproductive-system-physiology-1942", "fuente": "anking", "tema": 32, "anki": "1462984522924", "q": "Secondary oocytes remain arrested in metaphase II of meiosis II until which event occurs?", "o": {"A": "Ovulation", "B": "The LH surge", "C": "Fertilization", "D": "Menstruation"}, "r": "C", "e": {"correcta": "Fertilization is the trigger that allows the secondary oocyte to complete meiosis II, resulting in extrusion of the second polar body and formation of a mature ovum (now technically a zygote once fused with the sperm pronucleus). Without fertilization, the oocyte degenerates while still arrested in metaphase II.", "incorrectas": {"A": "Ovulation is the event that releases the secondary oocyte (already arrested in metaphase II) from the ovary; it does not itself resolve the metaphase II arrest.", "B": "The LH surge triggers resumption of meiosis I in the primary oocyte and precedes ovulation, but it is not what resolves the subsequent metaphase II arrest in the secondary oocyte.", "D": "Menstruation is the sloughing of the endometrium that occurs when fertilization/implantation does not happen; it is unrelated to the mechanism that releases the oocyte from metaphase II arrest."}}}, {"id": "anking-reproductive-system-physiology-1943", "fuente": "anking", "tema": 32, "anki": "1462984530226", "q": "The first, long stage of ovarian follicle development (lasting roughly 13-50 years) involves development of which follicle type from a primordial follicle?", "o": {"A": "Graafian follicle", "B": "Secondary follicle", "C": "Primary follicle", "D": "Corpus luteum"}, "r": "C", "e": {"correcta": "The first, slow stage of folliculogenesis is the gonadotropin-independent development of a primordial follicle into a primary follicle, a process that can take anywhere from puberty until the follicle is eventually recruited, spanning up to decades for any given follicle.", "incorrectas": {"A": "The graafian follicle represents the final, mature stage of follicle development that occurs rapidly (over about 48 hours) just before ovulation, not the initial slow stage described here.", "B": "The secondary follicle is an intermediate stage that follows the primary follicle stage, developing as part of the second, comparatively shorter (70-85 day) phase of maturation.", "D": "The corpus luteum forms only after ovulation from the ruptured follicle remnants; it has nothing to do with the initial slow transition from primordial to primary follicle."}}}, {"id": "anking-reproductive-system-physiology-1944", "fuente": "anking", "tema": 32, "anki": "1462984565173", "q": "The second stage of ovarian follicle development, lasting about 70-85 days, culminates in formation of which follicle type from a primary/secondary follicle?", "o": {"A": "Primordial follicle", "B": "Graafian follicle", "C": "Corpus albicans", "D": "Primary follicle"}, "r": "B", "e": {"correcta": "The second stage of folliculogenesis takes roughly 70-85 days and involves gonadotropin-dependent growth of the primary/secondary follicle into the mature graafian (preovulatory) follicle, characterized by a fluid-filled antrum and a fully developed cumulus-oocyte complex.", "incorrectas": {"A": "The primordial follicle is the earliest, most immature follicular stage, present from before birth, and represents the starting point of folliculogenesis rather than its second-stage endpoint.", "C": "The corpus albicans is the fibrous scar remnant that forms after the corpus luteum regresses when pregnancy does not occur; it is a much later structure unrelated to this maturation stage.", "D": "The primary follicle is the product of the first (long) stage of folliculogenesis, serving as the starting material for this second stage rather than its result."}}}, {"id": "anking-reproductive-system-physiology-1945", "fuente": "anking", "tema": 32, "anki": "1462984581013", "q": "In the third, rapid stage of ovarian follicle development (lasting about 48 hours), a dominant graafian follicle ruptures and releases its oocyte into the peritoneal cavity via which process?", "o": {"A": "Luteinization", "B": "Atresia", "C": "Ovulation", "D": "Implantation"}, "r": "C", "e": {"correcta": "Ovulation is the rapid final stage of follicular development in which the dominant graafian follicle, under the influence of the LH surge, ruptures its wall and releases the oocyte-cumulus complex into the peritoneal cavity to be captured by the fallopian tube fimbriae.", "incorrectas": {"A": "Luteinization is the process by which the ruptured follicle's granulosa and theca cells transform into the corpus luteum after ovulation has already occurred, not the rupture event itself.", "B": "Atresia is the degeneration process that the vast majority of follicles undergo without ever ovulating; it is the opposite fate from the dominant follicle that proceeds to ovulation.", "D": "Implantation refers to the blastocyst embedding into the endometrium, a much later event in a successful pregnancy, unrelated to the mechanics of follicular rupture."}}}, {"id": "anking-reproductive-system-physiology-1946", "fuente": "anking", "tema": 32, "anki": "1462984615221", "q": "If fertilization occurs, the residual granulosa and theca cells of the ruptured ovarian follicle form which structure, which continues to secrete steroid hormones?", "o": {"A": "Corpus albicans", "B": "Corpus luteum", "C": "Graafian follicle", "D": "Primordial follicle"}, "r": "B", "e": {"correcta": "The corpus luteum forms from the residual granulosa lutein and theca lutein cells of the ruptured follicle after ovulation. If fertilization and implantation occur, human chorionic gonadotropin (hCG) from the developing trophoblast rescues the corpus luteum, allowing it to keep secreting progesterone and estrogen to sustain early pregnancy until placental steroidogenesis takes over.", "incorrectas": {"A": "The corpus albicans is a fibrous scar that the corpus luteum degenerates into when fertilization does NOT occur and hCG support is absent, the opposite scenario from the one described.", "C": "The graafian follicle is the pre-ovulatory structure that existed before rupture; once it releases its oocyte, it no longer exists as a graafian follicle but transforms into the corpus luteum.", "D": "The primordial follicle is the earliest, dormant follicular stage present from before birth, unrelated to the post-ovulatory structure formed after fertilization."}}}, {"id": "anking-reproductive-system-physiology-1947", "fuente": "anking", "tema": 32, "anki": "1462984636271", "q": "If fertilization does not occur, the corpus luteum degenerates and is replaced by which structure?", "o": {"A": "Graafian follicle", "B": "Primary follicle", "C": "Corpus albicans", "D": "Theca lutein cyst"}, "r": "C", "e": {"correcta": "Without fertilization, there is no hCG to rescue the corpus luteum, so it involutes and is replaced by the corpus albicans, an avascular fibrous scar composed mostly of collagen. This regression is accompanied by falling progesterone and estrogen, which precipitates menstruation.", "incorrectas": {"A": "The graafian follicle is the pre-ovulatory follicle stage that existed prior to ovulation and corpus luteum formation; it is not what the corpus luteum turns into afterward.", "B": "The primary follicle is an early developmental stage of folliculogenesis occurring long before ovulation, unrelated to the post-luteal regression process.", "D": "A theca lutein cyst is a pathologic ovarian cyst associated with excessive hCG stimulation (e.g., molar pregnancy), not the normal physiologic fate of a non-fertilized corpus luteum."}}}, {"id": "anking-reproductive-system-physiology-1948", "fuente": "anking", "tema": 32, "anki": "1462986711789", "q": "In the ovaries, cholesterol desmolase activity (converting cholesterol to pregnenolone) in theca cells is primarily stimulated by which hormone, paralleling its role in the testes?", "o": {"A": "FSH", "B": "LH", "C": "GnRH", "D": "hCG"}, "r": "B", "e": {"correcta": "LH stimulates theca cells to upregulate cholesterol desmolase (the rate-limiting enzyme converting cholesterol to pregnenolone) and subsequent steroidogenic enzymes, paralleling how LH stimulates Leydig cells in the testes to produce testosterone via the same enzyme.", "incorrectas": {"A": "FSH acts primarily on granulosa cells to stimulate aromatase expression (converting androgens to estrogens) rather than on theca cells to drive cholesterol desmolase activity.", "C": "GnRH acts upstream at the level of the anterior pituitary to stimulate LH and FSH release; it does not directly act on ovarian theca cells to regulate steroidogenic enzymes.", "D": "hCG can substitute for LH at the LH receptor (as in pregnancy, supporting the corpus luteum), but it is not the physiologic hormone referenced in the normal ovarian cycle paralleling testicular Leydig cell stimulation."}}}, {"id": "anking-reproductive-system-physiology-1949", "fuente": "anking", "tema": 32, "anki": "1462986731912", "q": "In the ovaries, which cell type synthesizes and secretes progesterone from pregnenolone via 3-beta-hydroxysteroid dehydrogenase?", "o": {"A": "Granulosa cells", "B": "Theca cells", "C": "Oocytes", "D": "Corpus albicans cells"}, "r": "B", "e": {"correcta": "Theca cells, stimulated by LH, convert cholesterol to pregnenolone and then use 3-beta-hydroxysteroid dehydrogenase to form progesterone, and further steps convert this to androstenedione, which then diffuses to neighboring granulosa cells for aromatization to estrogen.", "incorrectas": {"A": "Granulosa cells lack significant 17-alpha-hydroxylase activity and instead specialize in taking up androgens (from theca cells) and converting them to estrogens via aromatase, stimulated by FSH.", "C": "Oocytes are the germ cells themselves and do not carry out steroidogenic enzyme reactions; steroid hormone synthesis is performed by the surrounding somatic (theca and granulosa) cells.", "D": "The corpus albicans is an inert fibrous scar with no active steroidogenic capacity, representing the degenerated remnant of a corpus luteum that is no longer functionally producing hormones."}}}, {"id": "anking-reproductive-system-physiology-1950", "fuente": "anking", "tema": 32, "anki": "1462986779904", "q": "In addition to progesterone, theca cells also synthesize which androgen, which then diffuses to nearby granulosa cells for further processing?", "o": {"A": "Testosterone", "B": "Dihydrotestosterone (DHT)", "C": "Androstenedione", "D": "Estradiol"}, "r": "C", "e": {"correcta": "LH-stimulated theca cells synthesize androstenedione from progesterone-derived precursors. Because theca cells lack aromatase, androstenedione diffuses across the basement membrane into neighboring granulosa cells, which express FSH-induced aromatase to convert it into estrone and estradiol (the two-cell, two-gonadotropin model).", "incorrectas": {"A": "Testosterone is produced within granulosa cells from androstenedione (via 17-beta-hydroxysteroid dehydrogenase), not synthesized directly by theca cells as the diffusible intermediate.", "B": "DHT is not a normal product of ovarian steroidogenesis in this pathway; it requires 5-alpha-reductase activity, which is not the enzyme driving the theca-to-granulosa cell cooperation in estrogen synthesis.", "D": "Estradiol is the final estrogenic product formed in granulosa cells via aromatization of androgens; theca cells themselves cannot produce estradiol because they lack aromatase."}}}, {"id": "anking-reproductive-system-physiology-1951", "fuente": "anking", "tema": 32, "anki": "1462986796333", "q": "In which ovarian cell type is androstenedione converted to testosterone via 17-beta-hydroxysteroid dehydrogenase, before further conversion to estradiol?", "o": {"A": "Theca cells", "B": "Granulosa cells", "C": "Corpus albicans cells", "D": "Oocytes"}, "r": "B", "e": {"correcta": "Granulosa cells, under FSH stimulation, take up androstenedione diffusing from theca cells and convert it to testosterone via 17-beta-hydroxysteroid dehydrogenase, then aromatize both androstenedione and testosterone into estrone and estradiol, respectively, completing the two-cell model of ovarian estrogen synthesis.", "incorrectas": {"A": "Theca cells are the site of androstenedione production (from cholesterol via LH stimulation) but lack the aromatase and full enzymatic machinery to convert it further into estrogens themselves.", "C": "The corpus albicans is a degenerated, hormonally inactive scar and does not perform any steroidogenic enzymatic conversions.", "D": "Oocytes are the germ cells and do not carry out steroidogenic enzymatic reactions; hormone synthesis is the job of the surrounding somatic granulosa and theca cells."}}}, {"id": "anking-reproductive-system-physiology-1952", "fuente": "anking", "tema": 32, "anki": "1462986851805", "q": "In the ovaries, aromatase activity in granulosa cells is primarily stimulated by which hormone?", "o": {"A": "LH", "B": "GnRH", "C": "FSH", "D": "Prolactin"}, "r": "C", "e": {"correcta": "FSH binds receptors on granulosa cells and upregulates aromatase expression, enabling conversion of theca-derived androgens (androstenedione, testosterone) into estrogens (estrone, estradiol). This is the granulosa cell arm of the two-cell, two-gonadotropin model of ovarian steroidogenesis.", "incorrectas": {"A": "LH acts primarily on theca cells to stimulate cholesterol desmolase and androgen production, not on granulosa cell aromatase; granulosa cells only acquire LH receptors later, near ovulation and luteinization.", "B": "GnRH acts at the level of the anterior pituitary to control LH and FSH secretion; it does not directly stimulate aromatase within the ovary.", "D": "Prolactin's main physiologic role is stimulating milk production in the mammary gland; it is not the driver of granulosa cell aromatase activity and, in excess, actually suppresses GnRH/gonadotropin secretion."}}}, {"id": "anking-reproductive-system-physiology-1953", "fuente": "anking", "tema": 32, "anki": "1462986895220", "q": "Hypothalamic control over oogenesis and ovarian progesterone/estradiol secretion is mediated through which hormone?", "o": {"A": "Inhibin", "B": "Activin", "C": "GnRH", "D": "hCG"}, "r": "C", "e": {"correcta": "Gonadotropin-releasing hormone (GnRH), secreted in a pulsatile fashion from the hypothalamus, stimulates the anterior pituitary to release LH and FSH, which in turn drive follicular development, oogenesis, and ovarian steroid hormone (estrogen and progesterone) production.", "incorrectas": {"A": "Inhibin is secreted by granulosa cells and acts to suppress FSH release from the pituitary in a negative feedback loop; it is a downstream ovarian product, not the hypothalamic controller.", "B": "Activin is also produced by granulosa cells and stimulates FSH secretion, acting as a paracrine/endocrine modulator rather than the primary hypothalamic signal driving the axis.", "D": "hCG is produced by the placental syncytiotrophoblast during pregnancy to rescue the corpus luteum; it is not part of normal hypothalamic regulation of the menstrual cycle."}}}, {"id": "anking-reproductive-system-physiology-1954", "fuente": "anking", "tema": 32, "anki": "1462987312318", "q": "Ovarian granulosa cells may produce which hormone that inhibits FSH secretion from the anterior pituitary, analogous to its role in the testes?", "o": {"A": "Activin", "B": "Inhibin", "C": "Estradiol", "D": "Progesterone"}, "r": "B", "e": {"correcta": "Inhibin, produced by granulosa cells (and by Sertoli cells in the testes), selectively suppresses FSH secretion from the anterior pituitary via negative feedback. After menopause, follicular depletion leads to loss of inhibin production, which is a key reason FSH levels rise so markedly.", "incorrectas": {"A": "Activin has the opposite effect of inhibin: it stimulates FSH secretion from the anterior pituitary rather than suppressing it, despite being produced by the same granulosa cells.", "C": "Estradiol exerts complex feedback on the axis (negative feedback most of the cycle, but positive feedback triggering the LH surge at mid-cycle), but it is not the same hormone class as inhibin and does not act the same way on FSH specifically.", "D": "Progesterone mainly feeds back to suppress GnRH pulse frequency (thus indirectly affecting both LH and FSH) and prepares the endometrium, but it is not the specific granulosa-derived hormone responsible for selective FSH suppression."}}}, {"id": "anking-reproductive-system-physiology-1955", "fuente": "anking", "tema": 32, "anki": "1462987450650", "q": "Ovarian granulosa cells may also produce which hormone that stimulates FSH secretion from the anterior pituitary?", "o": {"A": "Inhibin", "B": "Progesterone", "C": "Activin", "D": "Testosterone"}, "r": "C", "e": {"correcta": "Activin, secreted by granulosa cells, stimulates FSH release from the anterior pituitary, complementing the paracrine actions of activin within the ovary that enhance granulosa cell proliferation and aromatase activity; it acts opposite to inhibin in its effect on the pituitary.", "incorrectas": {"A": "Inhibin, also produced by granulosa cells, has the opposite effect of suppressing FSH secretion, making it functionally antagonistic to activin at the pituitary level.", "B": "Progesterone's main endocrine feedback is on GnRH pulsatility (slowing pulse frequency), and it is produced mainly by theca and luteal cells rather than being the specific FSH-stimulating factor from granulosa cells.", "D": "Testosterone is an androgen produced in small amounts by granulosa cells (converted from androstenedione) as an intermediate toward estradiol synthesis, not a direct stimulator of pituitary FSH secretion."}}}, {"id": "anking-reproductive-system-physiology-1956", "fuente": "anking", "tema": 32, "anki": "1462988649843", "q": "Which female sex steroid is chiefly responsible for the development of the fallopian tubes, uterus, cervix, and upper vagina from the Mullerian ducts?", "o": {"A": "Progesterone", "B": "Testosterone", "C": "Inhibin", "D": "Estrogen"}, "r": "D", "e": {"correcta": "Estrogen supports the growth and differentiation of the Mullerian (paramesonephric) duct derivatives into the fallopian tubes, uterus, cervix, and upper vagina, in the absence of anti-Mullerian hormone and androgens (which would otherwise suppress and virilize these structures, respectively).", "incorrectas": {"A": "Progesterone acts primarily on tissues that are already differentiated (e.g., converting proliferative endometrium to secretory endometrium) rather than driving the initial embryologic development of the genital tract structures.", "B": "Testosterone (and its potent metabolite DHT) drives development of male genital structures (Wolffian ducts and external genitalia); its absence, rather than presence, permits female genital tract development.", "C": "Inhibin's primary role is suppressing FSH secretion from the anterior pituitary; it does not drive the differentiation of the female genital tract structures."}}}, {"id": "anking-reproductive-system-physiology-1957", "fuente": "anking", "tema": 32, "anki": "1462989727742", "q": "Which female sex steroid is primarily responsible for stimulating breast development at puberty?", "o": {"A": "Progesterone", "B": "Estrogen", "C": "Prolactin", "D": "Oxytocin"}, "r": "B", "e": {"correcta": "Estrogen drives ductal proliferation and growth of the breast's connective and fatty tissue at puberty, producing the characteristic breast development (thelarche) seen in girls. Progesterone later contributes to lobuloalveolar development but estrogen is the primary driver of overall breast growth.", "incorrectas": {"A": "Progesterone primarily promotes maturation of the lobular and alveolar glandular components of the breast (important for lactation preparation) rather than the initial ductal growth and overall size increase seen at puberty.", "C": "Prolactin stimulates milk production from already-developed mammary glandular tissue postpartum, rather than driving the pubertal growth of the breast itself.", "D": "Oxytocin causes myoepithelial cell contraction leading to milk ejection (letdown) during lactation; it plays no role in pubertal breast tissue growth."}}}, {"id": "anking-reproductive-system-physiology-1958", "fuente": "anking", "tema": 32, "anki": "1462989733104", "q": "Which female sex steroid is responsible for growth of the ovarian follicle and proliferation of the endometrium during the follicular phase?", "o": {"A": "Progesterone", "B": "Inhibin", "C": "Estrogen", "D": "LH"}, "r": "C", "e": {"correcta": "Estrogen, produced by the growing follicle's granulosa cells, drives further follicular growth in an autocrine/paracrine fashion and stimulates proliferation of the endometrial glands and stroma, giving the follicular phase of the endometrial cycle its name: the proliferative phase.", "incorrectas": {"A": "Progesterone is produced predominantly after ovulation by the corpus luteum, and its role is to convert the estrogen-primed proliferative endometrium into a secretory, glandular endometrium suitable for implantation, not to drive proliferation.", "B": "Inhibin's role is to suppress FSH secretion from the pituitary; it does not directly stimulate endometrial or follicular growth.", "D": "LH is the gonadotropin that stimulates theca cell androgen production and later triggers ovulation and luteinization, but the actual proliferative endometrial effect is mediated by the resulting estrogen, not LH itself."}}}, {"id": "anking-reproductive-system-physiology-1959", "fuente": "anking", "tema": 32, "anki": "1462989736246", "q": "Immediately prior to delivery, which female sex steroid increases myometrial (uterine) contractility and excitability by upregulating gap junctions and oxytocin receptors?", "o": {"A": "Progesterone", "B": "Relaxin", "C": "Estrogen", "D": "hCG"}, "r": "C", "e": {"correcta": "Near term, rising estrogen upregulates gap junctions between myometrial cells (allowing coordinated, synchronized contractions) and increases oxytocin receptor expression, which mediates calcium influx through ligand-activated channels, together heightening uterine excitability and readiness for labor.", "incorrectas": {"A": "Progesterone has the opposite effect: it maintains uterine quiescence throughout most of pregnancy by decreasing myometrial contractility and excitability, and its withdrawal (functional or otherwise) near term contributes to the onset of labor.", "B": "Relaxin primarily softens the cervix and relaxes the pelvic ligaments/pubic symphysis in preparation for delivery, rather than directly increasing myometrial contractile excitability via gap junctions.", "D": "hCG's major role is maintaining the corpus luteum in early pregnancy; by term its levels have long since declined, and it is not the hormone responsible for the late-pregnancy myometrial excitability changes."}}}, {"id": "anking-reproductive-system-physiology-1960", "fuente": "anking", "tema": 32, "anki": "1462989739466", "q": "Which female sex steroid is chiefly responsible for the typical female pattern of fat distribution (hips, thighs, breasts)?", "o": {"A": "Progesterone", "B": "Testosterone", "C": "Inhibin", "D": "Estrogen"}, "r": "D", "e": {"correcta": "Estrogen promotes deposition of subcutaneous fat in a gynecoid distribution (hips, thighs, buttocks, breasts), contributing to the secondary sexual characteristics that distinguish female from male body habitus, the latter influenced more by androgens toward central/visceral fat and muscle mass.", "incorrectas": {"A": "Progesterone's actions are centered on endometrial secretory transformation and maintaining pregnancy, and it is not the principal hormone driving the classic female fat distribution pattern.", "B": "Testosterone and other androgens instead favor a more central/android pattern of fat distribution and increased muscle mass, the opposite of the effect being described.", "C": "Inhibin functions in feedback suppression of FSH secretion and has no meaningful role in body fat distribution."}}}, {"id": "anking-reproductive-system-physiology-1961", "fuente": "anking", "tema": 32, "anki": "1462989742904", "q": "Estrogen exerts what effect on LH, estrogen, and progesterone receptor expression in target tissues?", "o": {"A": "Down-regulation of these receptors", "B": "No significant effect on receptor expression", "C": "Up-regulation of these receptors", "D": "Selective down-regulation of only progesterone receptors"}, "r": "C", "e": {"correcta": "Estrogen up-regulates the expression of LH receptors, estrogen receptors, and progesterone receptors in target tissues (such as the ovarian follicle and endometrium). This receptor up-regulation amplifies the tissue's responsiveness to these hormones, contributing to processes like follicular maturation, the LH surge response, and endometrial preparation for progesterone action after ovulation.", "incorrectas": {"A": "Down-regulation is the opposite of estrogen's actual effect; estrogen enhances rather than diminishes target tissue sensitivity to these hormones by increasing receptor numbers.", "B": "Estrogen does have a significant and well-described effect (up-regulation) on these receptors; describing it as having no effect ignores its key role in amplifying hormonal responsiveness during the cycle.", "D": "Estrogen's up-regulating effect is not limited to or selective for progesterone receptors alone; it also up-regulates LH receptors and its own (estrogen) receptors."}}}, {"id": "anking-reproductive-system-physiology-1962", "fuente": "anking", "tema": 32, "anki": "1462989745991", "q": "What is the effect of estrogen on prolactin secretion from the anterior pituitary?", "o": {"A": "Decreased secretion", "B": "No effect", "C": "Increased secretion", "D": "Biphasic effect depending on cycle day"}, "r": "C", "e": {"correcta": "Estrogen increases prolactin secretion from lactotrophs and promotes breast tissue growth in preparation for lactation, which is why prolactin levels rise progressively throughout pregnancy. Despite this, estrogen (along with progesterone) simultaneously blocks prolactin's action directly on breast tissue, preventing actual milk letdown until after delivery when estrogen and progesterone levels fall.", "incorrectas": {"A": "Estrogen does not decrease prolactin secretion; in fact it stimulates lactotroph proliferation and prolactin release, which is why prolactin rises across gestation even though lactation itself is suppressed.", "B": "Estrogen clearly affects prolactin — it is a known stimulus for lactotroph hyperplasia and increased prolactin output, distinguishing it from hormones with no pituitary effect.", "D": "The relationship is not biphasic; estrogen consistently increases prolactin secretion, while its inhibitory effect is on prolactin's peripheral action at the breast, not on its secretion from the pituitary."}}}, {"id": "anking-reproductive-system-physiology-1963", "fuente": "anking", "tema": 32, "anki": "1462989749371", "q": "Which form of estrogen is the predominant one produced by the ovary in a nonpregnant woman?", "o": {"A": "Estrone", "B": "Estriol", "C": "17β-estradiol", "D": "Ethinyl estradiol"}, "r": "C", "e": {"correcta": "17β-estradiol is the main estrogen secreted by the ovary (specifically the granulosa cells via aromatization of androgens) and is the most potent naturally occurring estrogen in reproductive-age women.", "incorrectas": {"A": "Estrone is the estrogen predominantly produced by peripheral aromatization of androstenedione in adipose tissue, not the main ovarian product; it becomes the dominant circulating estrogen after menopause.", "B": "Estriol is the estrogen primarily produced by the placenta during pregnancy from fetal adrenal precursors, not by the ovary in a nonpregnant state.", "D": "Ethinyl estradiol is a synthetic estrogen used in oral contraceptives; it is not a naturally produced ovarian hormone."}}}, {"id": "anking-reproductive-system-physiology-1964", "fuente": "anking", "tema": 32, "anki": "1462989752426", "q": "Which form of estrogen is characteristically produced by the placenta during pregnancy?", "o": {"A": "17β-estradiol", "B": "Estrone", "C": "Estriol", "D": "Estradiol valerate"}, "r": "C", "e": {"correcta": "Estriol is the major estrogen produced by the placenta during pregnancy, synthesized from DHEA-sulfate provided by the fetal adrenal gland and converted by placental aromatase; its levels rise markedly and are used clinically as a marker of fetoplacental well-being.", "incorrectas": {"A": "17β-estradiol is the dominant estrogen of the nonpregnant ovarian cycle, produced mainly by granulosa cells, whereas estriol is the placental hallmark hormone of pregnancy.", "B": "Estrone is derived largely from peripheral aromatization of androgens in adipose tissue and is the main postmenopausal estrogen, not the characteristic placental product of pregnancy.", "D": "Estradiol valerate is a synthetic esterified form of estradiol used in hormone therapy, not a naturally occurring placental hormone."}}}, {"id": "anking-reproductive-system-physiology-1965", "fuente": "anking", "tema": 32, "anki": "1462989755828", "q": "Which form of estrogen is produced primarily in adipose tissue and becomes the main source of estrogen after menopause?", "o": {"A": "17β-estradiol", "B": "Estriol", "C": "Estrone", "D": "Progesterone"}, "r": "C", "e": {"correcta": "Estrone is generated in peripheral adipose tissue by aromatization of adrenal and ovarian androgens (mainly androstenedione). After menopause, when ovarian estradiol production ceases, estrone from adipose aromatization becomes the predominant circulating estrogen, which is also why obesity is linked to higher estrogen exposure postmenopausally.", "incorrectas": {"A": "17β-estradiol is the most potent estrogen and the main product of the cycling ovary, but its production falls sharply after menopause as ovarian follicles are depleted.", "B": "Estriol is produced almost exclusively by the placenta during pregnancy and is essentially absent in the nonpregnant state, including after menopause.", "D": "Progesterone is a distinct steroid class (a progestin, not an estrogen) made by the corpus luteum and placenta; it is not the adipose-derived estrogen referenced here."}}}, {"id": "anking-reproductive-system-physiology-1966", "fuente": "anking", "tema": 32, "anki": "1462989759896", "q": "Which ranking correctly orders the naturally occurring estrogens from most to least potent?", "o": {"A": "Estrone > 17β-estradiol > estriol", "B": "Estriol > estrone > 17β-estradiol", "C": "17β-estradiol > estrone > estriol", "D": "Estriol > 17β-estradiol > estrone"}, "r": "C", "e": {"correcta": "17β-estradiol is the most potent natural estrogen, followed by estrone, with estriol being the weakest of the three; this potency order reflects their differing affinity and efficacy at the estrogen receptor despite estriol reaching the highest absolute levels in pregnancy.", "incorrectas": {"A": "This reverses the top two — estradiol, not estrone, is the most potent estrogen; estrone is an intermediate-potency metabolite produced mainly by peripheral aromatization.", "B": "This places the weakest estrogen (estriol) first, which is incorrect; estriol's very low receptor affinity is why massive placental output is needed to have physiologic effect.", "D": "This also incorrectly ranks estriol above estradiol; estriol is the weakest of the three despite being produced in the largest quantities during pregnancy."}}}, {"id": "anking-reproductive-system-physiology-1967", "fuente": "anking", "tema": 32, "anki": "1462989763064", "q": "Where are estrogen receptors located within the target cell prior to hormone binding?", "o": {"A": "Cell membrane, as a G protein-coupled receptor", "B": "Cytoplasm, translocating to the nucleus once bound by estrogen", "C": "Mitochondrial membrane", "D": "Endoplasmic reticulum, remaining there after binding"}, "r": "B", "e": {"correcta": "Estrogen receptors are intracellular (cytoplasmic/nuclear) steroid hormone receptors; because estrogen is lipophilic it diffuses across the plasma membrane and binds its receptor in the cytoplasm, and the hormone-receptor complex then translocates into the nucleus to act as a transcription factor regulating gene expression.", "incorrectas": {"A": "Estrogen receptors are not membrane-bound GPCRs; that mechanism applies to peptide hormones and catecholamines, not to lipophilic steroid hormones like estrogen, which require intracellular receptors.", "C": "Estrogen receptors are not located on the mitochondrial membrane; while some evidence exists for mitochondrial effects of estrogen, the classic and testable receptor location is cytoplasmic/nuclear.", "D": "The receptor does not remain fixed in the endoplasmic reticulum after binding; the hallmark of steroid receptor signaling is translocation of the ligand-receptor complex to the nucleus to alter gene transcription."}}}, {"id": "anking-reproductive-system-physiology-1968", "fuente": "anking", "tema": 32, "anki": "1462989766626", "q": "What effect does estrogen have on hepatic production of sex hormone-binding globulin (SHBG)?", "o": {"A": "Decreased SHBG synthesis", "B": "Increased SHBG synthesis", "C": "No change in SHBG levels", "D": "Decreased SHBG binding affinity without change in level"}, "r": "B", "e": {"correcta": "Estrogen increases hepatic synthesis of SHBG. Because SHBG binds androgens with higher affinity than estrogens, raising SHBG lowers free testosterone more than free estrogen, which shifts the androgen-to-estrogen balance further toward estrogen effects — a self-amplifying loop relevant to conditions like pregnancy and OCP use.", "incorrectas": {"A": "Estrogen increases, not decreases, SHBG production; this is actually exploited therapeutically in conditions of androgen excess (e.g., PCOS), where estrogen-containing OCPs raise SHBG to lower free testosterone.", "C": "SHBG levels are not static under estrogen influence — estrogen is a well-recognized stimulus of hepatic SHBG gene transcription, and levels rise measurably with estrogen exposure such as pregnancy or OCP use.", "D": "The estrogen effect is on the quantity of SHBG produced by the liver, not on the binding affinity of the SHBG molecule itself for its ligands."}}}, {"id": "anking-reproductive-system-physiology-1969", "fuente": "anking", "tema": 32, "anki": "1462989771729", "q": "What is the effect of estrogen on serum HDL cholesterol levels?", "o": {"A": "Decreased HDL", "B": "Increased HDL", "C": "No effect on HDL", "D": "Increased HDL only in postmenopausal women"}, "r": "B", "e": {"correcta": "Estrogen raises HDL cholesterol levels, contributing to a more favorable lipid profile in premenopausal women; this is part of why estrogen is generally considered cardioprotective prior to menopause and why lipid profiles often worsen after estrogen decline at menopause.", "incorrectas": {"A": "Estrogen does not lower HDL; it raises it, while simultaneously lowering LDL, together producing a lipid profile favorable for cardiovascular health.", "C": "Estrogen has a clear, well-documented effect of raising HDL via hepatic effects on lipoprotein metabolism, so \"no effect\" understates its known physiologic action.", "D": "The HDL-raising effect of estrogen is not restricted to postmenopausal women; it operates physiologically throughout reproductive life whenever estrogen levels are elevated (e.g., also relevant to exogenous estrogen therapy)."}}}, {"id": "anking-reproductive-system-physiology-1970", "fuente": "anking", "tema": 32, "anki": "1462989774805", "q": "What is the effect of estrogen on serum LDL cholesterol levels?", "o": {"A": "Increased LDL", "B": "No effect on LDL", "C": "Decreased LDL", "D": "Increased LDL only with exogenous estrogen"}, "r": "C", "e": {"correcta": "Estrogen decreases LDL cholesterol, complementing its HDL-raising effect to produce an overall cardioprotective lipid profile in premenopausal women; this combined effect is one reason cardiovascular risk rises after the estrogen decline of menopause.", "incorrectas": {"A": "Estrogen lowers LDL rather than raising it; increased LDL would work against the favorable lipid shift that estrogen is known to produce.", "B": "Estrogen has a well-established LDL-lowering effect via upregulation of hepatic LDL receptors, so stating no effect misses this key physiologic action.", "D": "This effect is not unique to exogenous estrogen — endogenous ovarian estrogen also lowers LDL throughout the reproductive years, which is part of the physiologic protection against atherosclerosis before menopause."}}}, {"id": "anking-reproductive-system-physiology-1971", "fuente": "anking", "tema": 32, "anki": "1462989777976", "q": "Which female sex steroid is primarily responsible for the maintenance of pregnancy?", "o": {"A": "Estrogen", "B": "Progesterone", "C": "hCG", "D": "Prolactin"}, "r": "B", "e": {"correcta": "Progesterone maintains pregnancy by keeping the myometrium quiescent, supporting the decidua, and preventing uterine contractions that would otherwise expel the fetus; it is produced first by the corpus luteum and later by the placenta as pregnancy progresses.", "incorrectas": {"A": "Estrogen supports many pregnancy-related changes (breast growth, uteroplacental blood flow) but progesterone is specifically the hormone that keeps the uterus quiescent and maintains the pregnancy itself.", "C": "hCG's main role is to rescue and maintain the corpus luteum early in pregnancy (so it continues making progesterone), but hCG itself is not the effector hormone maintaining uterine quiescence.", "D": "Prolactin promotes lactogenesis in preparation for breastfeeding but does not maintain pregnancy or uterine quiescence; its major action is on the breast, not the myometrium."}}}, {"id": "anking-reproductive-system-physiology-1972", "fuente": "anking", "tema": 32, "anki": "1462989781672", "q": "Which female sex steroid stimulates secretory activity of the endometrial glands?", "o": {"A": "Estrogen", "B": "FSH", "C": "Progesterone", "D": "LH"}, "r": "C", "e": {"correcta": "Progesterone, secreted by the corpus luteum after ovulation, converts the proliferative endometrium into a secretory endometrium by stimulating glandular tortuosity and secretion of glycogen-rich fluid, preparing the lining for possible implantation.", "incorrectas": {"A": "Estrogen drives the earlier proliferative phase, causing endometrial glandular and stromal proliferation, but it is progesterone that induces the subsequent secretory changes.", "B": "FSH acts on the ovary to stimulate follicular growth and is not a direct effector of endometrial gland secretion.", "D": "LH triggers ovulation and supports the corpus luteum, but its endometrial effects are mediated indirectly through the progesterone it induces the corpus luteum to produce, not through a direct glandular action."}}}, {"id": "anking-reproductive-system-physiology-1973", "fuente": "anking", "tema": 32, "anki": "1462989784984", "q": "Which female sex steroid promotes the development of endometrial spiral arteries?", "o": {"A": "Estrogen", "B": "Progesterone", "C": "hCG", "D": "Inhibin"}, "r": "B", "e": {"correcta": "Progesterone promotes coiling and development of the spiral arteries within the secretory endometrium, providing the vascular support needed for potential implantation; loss of progesterone at the end of a nonconceptive cycle causes spiral artery vasoconstriction and subsequent menstruation.", "incorrectas": {"A": "Estrogen drives glandular and stromal proliferation in the earlier proliferative phase, but spiral artery development specifically is a progesterone-dependent secretory-phase change.", "C": "hCG functions to maintain the corpus luteum's progesterone output in early pregnancy but is not itself the direct mediator of spiral artery development in the endometrium.", "D": "Inhibin acts on the pituitary to suppress FSH secretion and has no direct role in endometrial spiral artery development."}}}, {"id": "anking-reproductive-system-physiology-1974", "fuente": "anking", "tema": 32, "anki": "1462989788369", "q": "Which female sex steroid decreases myometrial contractility and excitability?", "o": {"A": "Estrogen", "B": "Oxytocin", "C": "Progesterone", "D": "Prostaglandin F2α"}, "r": "C", "e": {"correcta": "Progesterone reduces myometrial excitability and contractility by hyperpolarizing smooth muscle cells and decreasing gap junction formation, keeping the uterus quiescent during pregnancy; a fall in progesterone (or a rise in the estrogen:progesterone ratio) is thought to help trigger labor.", "incorrectas": {"A": "Estrogen actually increases myometrial excitability by promoting gap junction formation and oxytocin receptor expression, the opposite of progesterone's quiescent effect.", "B": "Oxytocin is a potent stimulator of myometrial contraction, acting at term to promote labor, which is the opposite effect described here.", "D": "Prostaglandin F2α stimulates uterine contractions and is involved in labor initiation and dysmenorrhea, not in decreasing myometrial excitability."}}}, {"id": "anking-reproductive-system-physiology-1975", "fuente": "anking", "tema": 32, "anki": "1462989794214", "q": "Which female sex steroid produces thick cervical mucus that inhibits sperm entry into the uterus?", "o": {"A": "Estrogen", "B": "Progesterone", "C": "LH", "D": "FSH"}, "r": "B", "e": {"correcta": "Progesterone, dominant during the luteal phase and in pregnancy, thickens cervical mucus into a viscous plug that blocks sperm (and pathogen) passage into the uterine cavity, functioning as a natural contraceptive-like barrier once ovulation has passed or during gestation.", "incorrectas": {"A": "Estrogen produces thin, watery, elastic ('fern-pattern') cervical mucus around ovulation that facilitates rather than inhibits sperm penetration — the opposite effect of progesterone.", "C": "LH triggers ovulation via its mid-cycle surge but does not directly govern cervical mucus consistency; that is a downstream effect of the ovarian steroids it induces.", "D": "FSH stimulates follicular development in the ovary and does not have a direct action on cervical mucus characteristics."}}}, {"id": "anking-reproductive-system-physiology-1976", "fuente": "anking", "tema": 32, "anki": "1462989801399", "q": "Which female sex steroid produces thin, watery cervical mucus that facilitates sperm entry into the uterus around ovulation?", "o": {"A": "Progesterone", "B": "Estrogen", "C": "Testosterone", "D": "Inhibin"}, "r": "B", "e": {"correcta": "Estrogen, which peaks just before ovulation, thins the cervical mucus and increases its water content and elasticity (spinnbarkeit), creating a favorable environment for sperm migration into the uterus during the fertile window.", "incorrectas": {"A": "Progesterone has the opposite effect, thickening cervical mucus after ovulation to create a barrier against sperm and pathogens, consistent with its role in the luteal phase and pregnancy.", "C": "Testosterone is an androgen involved in male reproductive physiology and is not the driver of cyclical cervical mucus changes in the female reproductive tract.", "D": "Inhibin suppresses FSH secretion from the pituitary and has no direct role in determining cervical mucus consistency."}}}, {"id": "anking-reproductive-system-physiology-1977", "fuente": "anking", "tema": 32, "anki": "1462989809462", "q": "Which female sex steroid is responsible for the rise in basal body temperature seen after ovulation?", "o": {"A": "Estrogen", "B": "Progesterone", "C": "FSH", "D": "Inhibin B"}, "r": "B", "e": {"correcta": "Progesterone acts on the hypothalamic thermoregulatory center to raise the basal body temperature set point after ovulation, producing the characteristic post-ovulatory temperature rise (typically about 0.5°F) that is used clinically to help confirm that ovulation has occurred.", "incorrectas": {"A": "Estrogen dominates the follicular phase before ovulation and does not produce the thermogenic effect; the temperature shift specifically tracks the post-ovulatory rise in progesterone.", "C": "FSH stimulates follicular development but has no direct thermoregulatory action on the hypothalamus.", "D": "Inhibin B is secreted by granulosa cells to provide negative feedback on FSH but does not affect basal body temperature."}}}, {"id": "anking-reproductive-system-physiology-1978", "fuente": "anking", "tema": 32, "anki": "1462989816760", "q": "Which female sex steroid causes uterine smooth muscle (myometrial) relaxation?", "o": {"A": "Estrogen", "B": "Oxytocin", "C": "Progesterone", "D": "Prostaglandin E2"}, "r": "C", "e": {"correcta": "Progesterone relaxes uterine smooth muscle by reducing excitability and gap junction communication between myometrial cells, helping the uterus remain quiescent and tolerate a growing pregnancy without contracting prematurely.", "incorrectas": {"A": "Estrogen promotes myometrial excitability and gap junction formation, increasing rather than decreasing contractile potential — the opposite of progesterone's relaxing effect.", "B": "Oxytocin is a potent uterotonic that stimulates contraction, particularly at term, and is used clinically to induce or augment labor.", "D": "Prostaglandin E2 promotes uterine contraction and cervical ripening, and is used clinically for labor induction, contrary to a relaxing effect."}}}, {"id": "anking-reproductive-system-physiology-1979", "fuente": "anking", "tema": 32, "anki": "1462989824446", "q": "What effect does progesterone have on estrogen receptor expression in target tissues?", "o": {"A": "Upregulation of estrogen receptors", "B": "Downregulation of estrogen receptors", "C": "No effect on estrogen receptor number", "D": "Conversion of estrogen receptors to progesterone receptors"}, "r": "B", "e": {"correcta": "Progesterone downregulates estrogen receptor expression in target tissues such as the endometrium, which limits continued estrogenic stimulation and helps transition the tissue from the proliferative to the secretory state; this negative cross-talk is part of how progesterone opposes unchecked estrogen action.", "incorrectas": {"A": "Progesterone does not upregulate estrogen receptors; estrogen itself upregulates its own receptors as well as progesterone receptors during the proliferative phase, while progesterone has the opposite, downregulating effect.", "C": "Progesterone does have a measurable effect on estrogen receptor density — its downregulation of ER is a key mechanism by which it limits estrogen's proliferative action on the endometrium.", "D": "Progesterone does not convert one receptor type into another; it acts through its own progesterone receptor to reduce transcription/expression of the estrogen receptor gene."}}}, {"id": "anking-reproductive-system-physiology-1980", "fuente": "anking", "tema": 32, "anki": "1462989830272", "q": "Which female sex steroid protects against endometrial hyperplasia by opposing unchecked estrogen stimulation?", "o": {"A": "Estrogen", "B": "Testosterone", "C": "Progesterone", "D": "FSH"}, "r": "C", "e": {"correcta": "Progesterone opposes estrogen's proliferative drive on the endometrium by downregulating estrogen receptors and promoting differentiation into a secretory state, thereby protecting against endometrial hyperplasia; this is why unopposed estrogen (e.g., in anovulatory cycles, PCOS, or obesity) raises the risk of endometrial hyperplasia and cancer.", "incorrectas": {"A": "Estrogen is precisely the hormone that drives endometrial proliferation and, when unopposed by progesterone, causes hyperplasia — it is the risk factor, not the protective hormone.", "B": "Testosterone is an androgen without a direct protective role against endometrial hyperplasia; its clinical relevance to the endometrium is indirect (e.g., via peripheral conversion to estrogen).", "D": "FSH stimulates ovarian follicular development but does not act directly on the endometrium to prevent hyperplasia; its relevant downstream effect is mediated through the ovarian hormones it induces."}}}, {"id": "anking-reproductive-system-physiology-1981", "fuente": "anking", "tema": 32, "anki": "1462989835971", "q": "Approximately how many-fold do circulating estradiol and estrone levels increase during pregnancy?", "o": {"A": "5-fold", "B": "50-fold", "C": "200-fold", "D": "1000-fold"}, "r": "B", "e": {"correcta": "During pregnancy, estradiol and estrone rise approximately 50-fold above nonpregnant levels, driven by increasing placental steroidogenesis as gestation progresses, supporting uterine growth, uteroplacental blood flow, and breast development.", "incorrectas": {"A": "A 5-fold rise substantially underestimates the actual increase; placental estrogen production causes a much larger surge than this over the course of pregnancy.", "C": "A 200-fold increase overstates the rise seen for estradiol and estrone; that magnitude is not the figure associated with these two estrogens in pregnancy.", "D": "A 1000-fold increase describes the rise seen in estriol specifically (reflecting its role as a marker of fetal well-being via fetal adrenal precursor conversion), not estradiol or estrone."}}}, {"id": "anking-reproductive-system-physiology-1982", "fuente": "anking", "tema": 32, "anki": "1462989841151", "q": "Approximately how many-fold does estriol increase during pregnancy, making it a useful indicator of fetal well-being?", "o": {"A": "50-fold", "B": "100-fold", "C": "1000-fold", "D": "10-fold"}, "r": "C", "e": {"correcta": "Estriol rises approximately 1000-fold during pregnancy because it depends on DHEA-sulfate produced by the fetal adrenal gland and 16-hydroxylation by the fetal liver before placental aromatization, making maternal estriol levels a marker of fetal (and placental) functional status.", "incorrectas": {"A": "A 50-fold rise describes the increase seen in estradiol and estrone during pregnancy, not the much larger rise characteristic of estriol.", "B": "A 100-fold increase understates the actual magnitude of estriol's rise in pregnancy, which is roughly an order of magnitude greater.", "D": "A 10-fold increase is far too small; estriol's dramatic rise (about 1000-fold) is specifically what makes it clinically useful as a marker reflecting fetal contribution to placental steroidogenesis."}}}, {"id": "anking-reproductive-system-physiology-1983", "fuente": "anking", "tema": 32, "anki": "1462989855687", "q": "Variability in the overall length of the menstrual cycle is mainly attributed to variation in the duration of which phase?", "o": {"A": "Luteal phase", "B": "Follicular phase", "C": "Menstrual phase", "D": "Ovulatory phase"}, "r": "B", "e": {"correcta": "The follicular phase has a variable duration (ranging widely between individuals and cycles) because it depends on how long it takes a dominant follicle to mature, which is why total cycle length differs from woman to woman; the luteal phase, in contrast, is fixed at about 14 days due to the fixed lifespan of the corpus luteum.", "incorrectas": {"A": "The luteal phase is remarkably constant at about 14 days because it reflects the intrinsic lifespan of the corpus luteum, which is why it is not the source of cycle-length variability.", "C": "The menstrual (bleeding) phase is a brief part of the early follicular phase and is not the recognized determinant of overall cycle-length variability.", "D": "Ovulation is a discrete event (not an extended phase) triggered by the LH surge, and its timing is a consequence of follicular phase length rather than an independent source of variability."}}}, {"id": "anking-reproductive-system-physiology-1984", "fuente": "anking", "tema": 32, "anki": "1462992500901", "q": "By convention, what event marks day 0 (day 1) of the menstrual cycle?", "o": {"A": "Ovulation", "B": "The LH surge", "C": "Onset of menses", "D": "Fertilization"}, "r": "C", "e": {"correcta": "Day 1 of the menstrual cycle is defined as the first day of menstrual bleeding (onset of menses), providing a standardized, clinically observable reference point from which the follicular phase, ovulation, and luteal phase are timed.", "incorrectas": {"A": "Ovulation is a variable event that typically occurs around day 14 (dependent on follicular phase length), not the fixed starting reference point of the cycle.", "B": "The LH surge precedes ovulation by about 24-36 hours and is a mid-cycle event, not the conventional marker for cycle day 0.", "D": "Fertilization is not a universal or reliably timed event for every cycle and is not used as the standardized reference point for cycle dating."}}}, {"id": "anking-reproductive-system-physiology-1985", "fuente": "anking", "tema": 32, "anki": "1462992514871", "q": "The first phase of the menstrual cycle, lasting from approximately day 0 to day 14 and characterized histologically by straight endometrial glands with abundant mitotic figures, is called what?", "o": {"A": "Secretory (luteal) phase", "B": "Follicular (proliferative) phase", "C": "Ischemic phase", "D": "Menstrual phase only"}, "r": "B", "e": {"correcta": "The follicular (proliferative) phase spans roughly days 0-14 and is driven by rising estrogen from the developing dominant follicle, which stimulates endometrial glandular and stromal proliferation; histologically, days 4-7 after menses show straight, short glands with a compact stroma and numerous mitoses reflecting active cell division.", "incorrectas": {"A": "The secretory (luteal) phase occurs after ovulation under progesterone influence and shows coiled, tortuous glands with glycogen-rich secretions and reduced mitotic activity — the opposite histologic picture from the proliferative phase.", "C": "The ischemic phase refers to the brief premenstrual period of spiral artery vasoconstriction as progesterone withdraws, immediately preceding menstruation, not the early estrogen-driven phase.", "D": "The menstrual (bleeding) phase is only the first few days within the follicular phase, not synonymous with the entire proliferative phase that lasts through day 14."}}}, {"id": "anking-reproductive-system-physiology-1986", "fuente": "anking", "tema": 32, "anki": "1462992530707", "q": "During the follicular phase, a graafian follicle develops into which structure, while neighboring follicles undergo atresia?", "o": {"A": "Corpus luteum", "B": "Corpus albicans", "C": "Dominant follicle", "D": "Primordial follicle"}, "r": "C", "e": {"correcta": "One graafian follicle is selected to become the dominant follicle, which continues to grow and mature under FSH/LH influence and produces estrogen, while the other developing follicles in that cohort undergo atresia due to relatively lower FSH sensitivity as estrogen and inhibin suppress FSH.", "incorrectas": {"A": "The corpus luteum forms after ovulation from the ruptured follicle's remnants (granulosa and theca lutein cells), which is a later step than the dominant follicle stage described.", "B": "The corpus albicans is the fibrotic remnant left after the corpus luteum degenerates if pregnancy does not occur, representing a much later stage than dominant follicle selection.", "D": "The primordial follicle is the earliest, resting stage of a follicle, present from before birth and requiring a long maturation process to eventually reach the graafian/dominant stage, not a downstream product of the graafian follicle."}}}, {"id": "anking-reproductive-system-physiology-1987", "fuente": "anking", "tema": 32, "anki": "1462992616794", "q": "During most of the follicular phase, rising estradiol has what effect on FSH and LH secretion from the pituitary?", "o": {"A": "Stimulates their secretion", "B": "Inhibits their secretion", "C": "Has no effect on gonadotropins", "D": "Selectively inhibits only FSH, not LH"}, "r": "B", "e": {"correcta": "During the early-to-mid follicular phase, estradiol from the developing follicle exerts negative feedback on the hypothalamic-pituitary axis, inhibiting FSH and LH secretion; this keeps gonadotropin levels controlled until estradiol reaches a sufficiently high, sustained level to flip the feedback to positive just before ovulation.", "incorrectas": {"A": "Stimulation of FSH/LH by estradiol occurs only later, at high sustained estrogen levels near the end of the follicular phase (producing the LH surge) — during most of the follicular phase the effect is inhibitory.", "C": "Estradiol clearly modulates gonadotropin secretion through classic feedback loops; describing no effect ignores the well-established negative feedback active for most of this phase.", "D": "Estradiol's negative feedback during this period suppresses both FSH and LH together, not FSH selectively; inhibin, not estradiol, is the hormone that provides more selective FSH suppression."}}}, {"id": "anking-reproductive-system-physiology-1988", "fuente": "anking", "tema": 32, "anki": "1462992655373", "q": "During the follicular phase of the menstrual cycle, circulating progesterone levels are typically at what level?", "o": {"A": "High", "B": "Low", "C": "Peaking mid-phase", "D": "Equal to luteal phase levels"}, "r": "B", "e": {"correcta": "Progesterone remains low throughout the follicular phase because there is no corpus luteum yet to produce it in significant quantity; progesterone rises sharply only after ovulation once the corpus luteum forms, defining the subsequent luteal phase.", "incorrectas": {"A": "Progesterone is not high during the follicular phase; a high level is characteristic of the luteal phase after corpus luteum formation.", "C": "There is no mid-follicular progesterone peak; the dominant hormonal event of this phase is the rise in estradiol, with progesterone staying low until after ovulation.", "D": "Follicular-phase progesterone is markedly lower than luteal-phase progesterone, not equal, reflecting the absence of a functioning corpus luteum before ovulation."}}}, {"id": "anking-reproductive-system-physiology-1989", "fuente": "anking", "tema": 32, "anki": "1462992751502", "q": "In the middle of the menstrual cycle, sustained high estradiol levels have what effect on FSH and LH secretion, producing the LH surge?", "o": {"A": "Inhibits their secretion", "B": "Stimulates their secretion", "C": "Has no effect", "D": "Only suppresses FSH via inhibin-like action"}, "r": "B", "e": {"correcta": "When estradiol reaches a high enough level and is sustained for roughly 48 hours, the feedback on the hypothalamic-pituitary axis flips from negative to positive, stimulating a surge in GnRH pulsatility and pituitary LH (and to a lesser extent FSH) release — the LH surge that triggers ovulation about 24-36 hours later.", "incorrectas": {"A": "Inhibition describes estradiol's action earlier in the follicular phase; at mid-cycle with high, sustained estradiol the feedback switches to stimulatory, producing the surge rather than continued suppression.", "C": "Estradiol clearly has an effect at this point in the cycle — the mid-cycle positive feedback loop it creates is the entire mechanism driving the LH surge and subsequent ovulation.", "D": "Inhibin (from granulosa cells), not estradiol, selectively suppresses FSH; the mid-cycle estradiol surge instead stimulates both gonadotropins via positive feedback, culminating in the LH surge."}}}, {"id": "anking-reproductive-system-physiology-1990", "fuente": "anking", "tema": 32, "anki": "1462992809651", "q": "At the time of ovulation, cervical mucus undergoes what change in quantity and character?", "o": {"A": "Decreases in quantity and becomes thicker", "B": "Increases in quantity and becomes more watery/penetrable", "C": "Remains unchanged in both quantity and consistency", "D": "Increases in quantity but becomes thicker"}, "r": "B", "e": {"correcta": "At ovulation, the peak estrogen level increases the volume of cervical mucus and makes it thin, watery, and elastic (spinnbarkeit), creating an optimal channel for sperm to traverse the cervix during the fertile window.", "incorrectas": {"A": "A decrease in quantity with thickening describes the luteal-phase, progesterone-dominated pattern that impedes sperm entry, which is the opposite of the periovulatory change.", "C": "Cervical mucus undergoes a marked, clinically observable change around ovulation (used in fertility awareness methods), so \"unchanged\" does not reflect the actual physiology.", "D": "An increase in quantity occurs, but the mucus becomes thinner/more watery, not thicker, under estrogen's periovulatory influence."}}}, {"id": "anking-reproductive-system-physiology-1991", "fuente": "anking", "tema": 32, "anki": "1462992912807", "q": "How do estradiol levels change immediately after ovulation and then again during the luteal phase?", "o": {"A": "They increase after ovulation, then decrease during the luteal phase", "B": "They decrease just after ovulation, then increase again during the luteal phase", "C": "They remain constant throughout both periods", "D": "They decrease after ovulation and continue to decrease through the luteal phase"}, "r": "B", "e": {"correcta": "Estradiol drops transiently just after ovulation as the dominant follicle ruptures and its estrogen-producing granulosa cells transform, but then rises again as the newly formed corpus luteum begins producing both estradiol and progesterone during the luteal phase.", "incorrectas": {"A": "This reverses the actual pattern — estradiol does not rise right after ovulation, it dips first, and it is progesterone (alongside a secondary estradiol rise) that characterizes the luteal phase, not an estradiol decline.", "C": "Estradiol is not constant across this window; there is a clear transient dip followed by a corpus-luteum-driven rise, both of which are physiologically and clinically significant.", "D": "Estradiol does not continue falling throughout the luteal phase; after its initial post-ovulatory dip it rises again due to corpus luteum steroidogenesis, only falling again near the end of the luteal phase if pregnancy does not occur."}}}, {"id": "anking-reproductive-system-physiology-1992", "fuente": "anking", "tema": 32, "anki": "1462992935387", "q": "Ovarian follicular growth is fastest during which week of the follicular phase?", "o": {"A": "1st week", "B": "2nd week", "C": "3rd week", "D": "4th week"}, "r": "B", "e": {"correcta": "Follicular growth accelerates most rapidly during the second week of the follicular phase, as the selected dominant follicle undergoes rapid growth and increasing estradiol production in the run-up to ovulation, which typically occurs around day 14.", "incorrectas": {"A": "The first week involves initial recruitment and early growth of a cohort of follicles, but growth accelerates further in the second week as the dominant follicle is selected and matures rapidly.", "C": "There is no third week of the follicular phase in a typical 28-day cycle, since ovulation (ending the follicular phase) occurs around day 14, at the end of the second week.", "D": "A fourth week would fall within the luteal phase in a standard cycle, well after the follicular phase and its peak growth period have ended."}}}, {"id": "anking-reproductive-system-physiology-1993", "fuente": "anking", "tema": 32, "anki": "1462992958189", "q": "During the luteal phase of the menstrual cycle, which structure develops from the ruptured follicle to dominate hormone production?", "o": {"A": "Corpus albicans", "B": "Graafian follicle", "C": "Corpus luteum", "D": "Primary follicle"}, "r": "C", "e": {"correcta": "After ovulation, the ruptured follicle's granulosa and theca cells luteinize under LH influence to form the corpus luteum, which becomes the dominant endocrine structure of the luteal phase, secreting both progesterone and estradiol (with progesterone predominating).", "incorrectas": {"A": "The corpus albicans is the later, involuted fibrous scar that the corpus luteum degenerates into if pregnancy does not occur — it develops after, not during, the functional luteal phase.", "B": "The graafian follicle is the mature preovulatory follicle; it no longer exists as such once ovulation has occurred and the follicle has released its oocyte and transformed into the corpus luteum.", "D": "A primary follicle is an early developmental stage occurring long before ovulation, not the structure that forms in the luteal phase after the follicle has ruptured."}}}, {"id": "anking-reproductive-system-physiology-1994", "fuente": "anking", "tema": 32, "anki": "1462992976162", "q": "The corpus luteum synthesizes which two steroid hormones, with the latter predominating in quantity?", "o": {"A": "Testosterone and estradiol (testosterone > estradiol)", "B": "Estradiol and progesterone (progesterone > estradiol)", "C": "Cortisol and progesterone (cortisol > progesterone)", "D": "Estriol and estrone (estrone > estriol)"}, "r": "B", "e": {"correcta": "The corpus luteum, formed from luteinized granulosa and theca cells after ovulation, secretes both estradiol and progesterone, with progesterone produced in greater quantity than estradiol; this progesterone dominance defines the secretory changes of the luteal phase and supports early pregnancy if fertilization occurs.", "incorrectas": {"A": "The corpus luteum is not a source of significant testosterone production; its major secretory products are the female steroids estradiol and progesterone, not androgens.", "C": "Cortisol is an adrenal (not ovarian) steroid and is not among the hormones characteristically produced by the corpus luteum.", "D": "Estriol and estrone are not the corpus luteum's characteristic products; estriol is chiefly a placental hormone of pregnancy, and estrone is mainly derived from peripheral adipose aromatization, not corpus luteum secretion."}}}, {"id": "anking-reproductive-system-physiology-1995", "fuente": "anking", "tema": 32, "anki": "1462993011096", "q": "During the luteal phase, basal body temperature increases due to which hormone acting on the hypothalamic temperature set-point?", "o": {"A": "Estrogen", "B": "LH", "C": "Progesterone", "D": "FSH"}, "r": "C", "e": {"correcta": "Progesterone, secreted in large amounts by the corpus luteum during the luteal phase, raises the hypothalamic thermoregulatory set point, producing the sustained basal body temperature increase (about 0.5°F) that persists until progesterone falls at the end of the cycle (or continues to rise further in pregnancy).", "incorrectas": {"A": "Estrogen dominates the follicular phase before the temperature shift and does not produce the thermogenic effect on the hypothalamus that characterizes the luteal phase.", "B": "LH triggers ovulation via its mid-cycle surge but is not the hormone responsible for the sustained temperature elevation seen afterward; that effect is mediated by progesterone from the corpus luteum LH helped form.", "D": "FSH governs follicular recruitment and growth in the ovary and has no direct thermoregulatory action on the hypothalamus."}}}, {"id": "anking-reproductive-system-physiology-1996", "fuente": "anking", "tema": 32, "anki": "1462993025484", "q": "During the luteal phase, cervical mucus becomes what compared to the periovulatory period?", "o": {"A": "Thinner and more watery, more penetrable by sperm", "B": "Thicker and less watery, less penetrable by sperm", "C": "Unchanged from the ovulatory pattern", "D": "Absent entirely"}, "r": "B", "e": {"correcta": "Under the influence of luteal-phase progesterone, cervical mucus becomes thick, tacky, and scant, forming a barrier that is far less penetrable by sperm compared with the thin, watery, estrogen-dominated mucus present at ovulation — this same principle underlies progestin-only contraceptive mechanisms.", "incorrectas": {"A": "A thin, watery, sperm-penetrable mucus describes the periovulatory estrogen-dominated state, which is the opposite of what progesterone produces in the luteal phase.", "C": "Cervical mucus does change substantially between the periovulatory and luteal phases — it is a hallmark, clinically used sign of the shift from an estrogen-dominant to a progesterone-dominant hormonal milieu.", "D": "Mucus does not disappear during the luteal phase; it becomes scantier and thicker, but it remains present as a protective, less penetrable barrier."}}}, {"id": "anking-reproductive-system-physiology-1997", "fuente": "anking", "tema": 32, "anki": "1462993044137", "q": "If fertilization does not occur, the corpus luteum regresses. What happens to estradiol and progesterone levels as a result?", "o": {"A": "They increase abruptly", "B": "They decrease abruptly", "C": "They remain unchanged", "D": "They plateau at luteal-phase levels"}, "r": "B", "e": {"correcta": "Without hCG support from a pregnancy, the corpus luteum has a fixed lifespan of about 14 days and undergoes involution, causing estradiol and progesterone to fall abruptly. This hormone withdrawal removes support for the secretory endometrium, triggering vasoconstriction of spiral arteries, ischemia, and menstruation.", "incorrectas": {"A": "An abrupt increase would occur only if the corpus luteum were rescued by hCG from an implanting embryo, which is the opposite of what happens when fertilization fails.", "C": "Hormone levels do not remain unchanged; the corpus luteum is a transient structure that degenerates by around day 14 post-ovulation absent hCG rescue, causing steroid levels to fall, not stabilize.", "D": "There is no plateau; the whole point of luteolysis is that estradiol and progesterone drop sharply, which is the signal that initiates menstrual sloughing of the endometrium."}}}, {"id": "anking-reproductive-system-physiology-1998", "fuente": "anking", "tema": 32, "anki": "1462993056311", "q": "A woman has abnormally low progesterone levels in the luteal phase. What effect does this have on her fertility?", "o": {"A": "Increased fertility due to enhanced endometrial receptivity", "B": "No effect on fertility", "C": "Decreased fertility due to poor endometrial receptivity", "D": "Increased fertility due to suppressed ovulation"}, "r": "C", "e": {"correcta": "Endometrial receptivity to a fertilized egg depends on maintaining a low estrogen-to-progesterone ratio, so adequate progesterone is required to prepare a secretory endometrium capable of supporting implantation. Low progesterone shifts this ratio unfavorably and decreases fertility by impairing implantation.", "incorrectas": {"A": "Low progesterone does not enhance receptivity; it actually raises the estrogen:progesterone ratio, which is the opposite of the low ratio needed for optimal implantation, so this decreases rather than increases fertility.", "B": "Progesterone is essential for converting the proliferative endometrium into a secretory, implantation-ready endometrium, so a deficiency has a clear negative effect on fertility rather than none.", "D": "Progesterone deficiency does not suppress ovulation; if anything, low progesterone reduces negative feedback on LH/FSH. The fertility problem here is with implantation, not ovulation."}}}, {"id": "anking-reproductive-system-physiology-1999", "fuente": "anking", "tema": 32, "anki": "1462993061053", "q": "What effect does progesterone secreted by the corpus luteum have on LH and FSH secretion from the anterior pituitary?", "o": {"A": "It increases LH and FSH via positive feedback", "B": "It decreases LH and FSH via negative feedback", "C": "It has no effect on gonadotropin secretion", "D": "It selectively increases FSH only"}, "r": "B", "e": {"correcta": "Progesterone acts on the hypothalamus and anterior pituitary to suppress GnRH pulsatility and gonadotropin release, providing negative feedback that decreases LH and FSH secretion during the luteal phase. This suppression prevents new follicular development and ovulation while the corpus luteum is active.", "incorrectas": {"A": "Positive feedback on LH is characteristic of the high, sustained estrogen surge just before ovulation, not of progesterone, which instead exerts negative feedback during the luteal phase.", "C": "Progesterone clearly affects gonadotropin secretion; it is central to preventing another LH surge and additional follicle recruitment while a corpus luteum is functioning.", "D": "Progesterone's negative feedback affects both LH and FSH together (via GnRH suppression), not FSH alone, and the direction is inhibitory, not stimulatory."}}}, {"id": "anking-reproductive-system-pathology-2000", "fuente": "anking", "tema": 8, "anki": "1462993203139", "q": "Patients with abnormal uterine bleeding classically present with variations of what kind of underlying menstrual cycle, along with symptoms of anemia?", "o": {"A": "An anovulatory cycle only", "B": "A normal menstrual cycle", "C": "A cycle with luteal phase defect only", "D": "An artificially induced cycle from hormonal contraception"}, "r": "B", "e": {"correcta": "Abnormal uterine bleeding often occurs as variations (in frequency, duration, or volume) of an otherwise normal underlying menstrual cycle rather than requiring a distinct pathologic cycle type, and heavy or prolonged bleeding commonly leads to iron-deficiency anemia symptoms such as fatigue and pallor.", "incorrectas": {"A": "Anovulatory cycles are one specific cause of abnormal bleeding (common in adolescence or perimenopause) but are not the general description of the presentation; abnormal bleeding is framed as a variation of a normal cycle, not exclusively anovulatory cycles.", "C": "Luteal phase defect is a specific and less commonly emphasized etiology, not the general concept being tested, which is that abnormal bleeding represents variations of a normal cycle.", "D": "Abnormal uterine bleeding is defined independent of hormonal contraception use; it refers to deviations from a naturally occurring normal cycle, not to bleeding patterns induced by exogenous hormones."}}}, {"id": "anking-reproductive-system-pathology-2001", "fuente": "anking", "tema": 8, "anki": "1462993233054", "q": "A patient has abnormal uterine bleeding due to ovulatory dysfunction. What is the general category of first-line medical treatment?", "o": {"A": "Hormone therapy (e.g., OCPs, oral progestins, or levonorgestrel IUD)", "B": "Surgical hysterectomy", "C": "Endometrial ablation", "D": "Antifibrinolytic agents alone"}, "r": "A", "e": {"correcta": "Ovulatory dysfunction disrupts the normal cyclic hormonal support of the endometrium, so first-line treatment is hormone therapy, such as combined oral contraceptives, oral progestin therapy, or a levonorgestrel-releasing IUD, which stabilizes the endometrium and regulates bleeding.", "incorrectas": {"B": "Hysterectomy is a definitive surgical option reserved for refractory cases or when fertility is not desired, not the first-line approach for ovulatory dysfunction-related bleeding.", "C": "Endometrial ablation is a second-line procedural option for women who have failed or cannot tolerate medical therapy and do not desire future fertility, not the initial treatment.", "D": "Antifibrinolytics (like tranexamic acid) can help reduce bleeding volume but do not address the underlying ovulatory dysfunction the way hormone therapy does, and are not considered first-line for this etiology."}}}, {"id": "anking-reproductive-system-physiology-2002", "fuente": "anking", "tema": 32, "anki": "1462993235591", "q": "During the first trimester of pregnancy, what structure is the primary source of steroid hormones (estrogen and progesterone)?", "o": {"A": "The placenta", "B": "The corpus luteum", "C": "The maternal adrenal cortex", "D": "The fetal adrenal gland"}, "r": "B", "e": {"correcta": "In early pregnancy, hCG from the syncytiotrophoblast rescues and maintains the corpus luteum, which continues to produce estrogen and progesterone to support the endometrium until the placenta can take over steroidogenesis.", "incorrectas": {"A": "The placenta becomes the dominant source of steroid hormones only in the second and third trimesters, once it is developed enough to independently synthesize estrogen and progesterone from precursors.", "C": "The maternal adrenal cortex is not the primary source of pregnancy steroid hormones in early pregnancy; hormone production in the first trimester depends on the corpus luteum, which is maintained by hCG.", "D": "The fetal adrenal gland contributes precursor steroids (like DHEA-S) later in pregnancy for placental estrogen synthesis, but it is not the first-trimester source of steroid hormones."}}}, {"id": "anking-reproductive-system-physiology-2003", "fuente": "anking", "tema": 32, "anki": "1462995794856", "q": "In mid-to-late pregnancy (second and third trimesters), which structure becomes the primary source of steroid hormones?", "o": {"A": "The corpus luteum", "B": "The placenta", "C": "The maternal ovary", "D": "The fetal pituitary"}, "r": "B", "e": {"correcta": "By the second trimester, the placenta has developed sufficient steroidogenic capacity to take over as the dominant source of estrogen and progesterone, using maternal and fetal precursors, allowing the corpus luteum to regress without loss of hormonal support.", "incorrectas": {"A": "The corpus luteum is the dominant source only in the first trimester; it regresses ('luteal-placental shift') once the placenta becomes capable of independent steroid production.", "C": "The maternal ovary (outside the corpus luteum) is not a significant source of pregnancy hormones; ovarian follicular activity is suppressed during pregnancy due to high estrogen and progesterone feedback.", "D": "The fetal pituitary does not produce steroid sex hormones; it is the placenta (using fetal adrenal and maternal precursors) that synthesizes estrogen and progesterone in later pregnancy."}}}, {"id": "anking-reproductive-system-physiology-2004", "fuente": "anking", "tema": 32, "anki": "1462995810306", "q": "How do estrogen and progesterone levels change over the course of a normal pregnancy?", "o": {"A": "They decrease steadily after the first trimester", "B": "They increase steadily throughout pregnancy", "C": "They remain constant from conception to delivery", "D": "They spike briefly at implantation then fall"}, "r": "B", "e": {"correcta": "Pregnancy is characterized by a steady, progressive rise in estrogen and progesterone levels, which maintain the endometrium, suppress further ovarian follicular development (preventing additional ovulation), and stimulate breast development in preparation for lactation.", "incorrectas": {"A": "Levels do not decrease after the first trimester; instead, the luteal-placental shift ensures continued and increasing hormone production as the placenta takes over steroidogenesis.", "C": "Hormone levels are not static; they rise progressively as the placenta grows and its steroidogenic capacity increases across gestation, rather than plateauing at a constant level.", "D": "There is no early spike-and-fall pattern; rather, after fertilization, levels are sustained by the corpus luteum and then rise continuously as the placenta takes over hormone production."}}}, {"id": "anking-reproductive-system-physiology-2005", "fuente": "anking", "tema": 32, "anki": "1462995824386", "q": "Within how many days of ovulation must fertilization occur for pregnancy to be possible?", "o": {"A": "Three days", "B": "One day", "C": "Five days", "D": "Seven days"}, "r": "B", "e": {"correcta": "The secondary oocyte remains viable for fertilization for only about 24 hours after ovulation, so sperm must reach and fertilize the egg within roughly one day of its release for conception to occur.", "incorrectas": {"A": "Three days overestimates oocyte viability; while sperm can survive in the female reproductive tract for several days, the egg itself is only fertilizable for about one day after ovulation.", "C": "Five days is far longer than the oocyte's actual fertilizable window; this duration is closer to how long sperm can survive in the reproductive tract awaiting ovulation, not how long the egg lasts after release.", "D": "Seven days substantially overstates oocyte viability post-ovulation; the fertile window relative to ovulation for the egg itself is roughly a single day."}}}, {"id": "anking-reproductive-system-anatomy-2006", "fuente": "anking", "tema": 34, "anki": "1462995830556", "q": "Fertilization of the ovum most commonly occurs in which part of the fallopian tube (uterine tube/oviduct/salpinx)?", "o": {"A": "The isthmus", "B": "The infundibulum", "C": "The ampulla", "D": "The interstitial (intramural) segment"}, "r": "C", "e": {"correcta": "The ampulla is the widest and longest segment of the fallopian tube, located near its upper end, and is the classic site where the sperm meets and fertilizes the released oocyte before the zygote travels toward the uterus.", "incorrectas": {"A": "The isthmus is the narrow segment closer to the uterus that primarily serves as a conduit toward the uterine cavity; it is not the typical site where fertilization occurs.", "B": "The infundibulum is the funnel-shaped distal end with fimbriae that captures the ovulated oocyte from the ovary, but fertilization itself occurs slightly further along, in the ampulla.", "D": "The interstitial (intramural) segment passes through the uterine wall itself and is the narrowest part of the tube; it is not where fertilization takes place."}}}, {"id": "anking-reproductive-system-physiology-2007", "fuente": "anking", "tema": 32, "anki": "1462995840692", "q": "Approximately how many days after ovulation does implantation of the blastocyst into the uterine wall occur?", "o": {"A": "Three days", "B": "Six days", "C": "Ten days", "D": "Fourteen days"}, "r": "B", "e": {"correcta": "Implantation typically occurs about six days after ovulation/fertilization, once the blastocyst has traveled through the fallopian tube and reached the uterine cavity (mnemonic: the blastocyst 'sticks' on day six).", "incorrectas": {"A": "Three days is too early; this timeframe corresponds more to the period during which the early embryo is still traveling through the fallopian tube toward the uterus, not yet implanting.", "C": "Ten days overshoots the typical implantation window; by this point implantation has usually already occurred, and hCG production is already underway.", "D": "Fourteen days corresponds roughly to the time of the next expected menstrual period and is too late for implantation, which must occur earlier for hCG to rescue the corpus luteum in time."}}}, {"id": "anking-reproductive-system-physiology-2008", "fuente": "anking", "tema": 32, "anki": "1462995851227", "q": "Endometrial receptivity to a fertilized ovum is critically dependent on what estrogen-to-progesterone ratio?", "o": {"A": "A high estrogen:progesterone ratio", "B": "An equal estrogen:progesterone ratio", "C": "A low estrogen:progesterone ratio", "D": "A ratio that fluctuates rapidly"}, "r": "C", "e": {"correcta": "A low estrogen-to-progesterone ratio (i.e., progesterone-dominant state) is required to convert the endometrium into a receptive, secretory tissue capable of supporting implantation, which is why decreased progesterone secretion directly reduces fertility.", "incorrectas": {"A": "A high estrogen:progesterone ratio favors endometrial proliferation rather than the secretory transformation needed for implantation, and is more characteristic of the follicular phase or approaching parturition, not peak receptivity.", "B": "An equal ratio is not the physiologic target; receptivity specifically requires progesterone to predominate over estrogen, shifting the ratio low rather than balanced.", "D": "Rapid fluctuation is not the mechanism; receptivity depends on sustained progesterone dominance (a stable low ratio) during the luteal/secretory phase, not oscillation."}}}, {"id": "anking-reproductive-system-physiology-2009", "fuente": "anking", "tema": 32, "anki": "1462995889625", "q": "How soon after conception is hCG typically detectable in maternal blood versus on a home urine pregnancy test?", "o": {"A": "Immediately in blood; 1 week in urine", "B": "1 week in blood; 2 weeks in urine", "C": "2 weeks in blood; 1 week in urine", "D": "3 weeks in both blood and urine"}, "r": "B", "e": {"correcta": "hCG produced by the syncytiotrophoblast becomes detectable in maternal serum about one week after conception (around the time of implantation), while urine levels rise high enough for a home test to detect it about two weeks after conception, roughly coinciding with the missed menstrual period.", "incorrectas": {"A": "hCG is not detectable immediately in blood; it takes about a week for levels from the newly implanted trophoblast to rise into the detectable range, and urine detection lags further behind serum detection.", "C": "This reverses the actual timeline; blood detection precedes urine detection because serum hCG concentrations rise before urine concentrations reach the threshold used by home tests.", "D": "Three weeks for both is too late for blood detection and does not reflect the earlier serum rise; blood tests are more sensitive and detect hCG about a week before home urine tests can."}}}, {"id": "anking-reproductive-system-physiology-2010", "fuente": "anking", "tema": 32, "anki": "1462995922829", "q": "How is the gestational age of a fetus calculated?", "o": {"A": "From the estimated date of conception", "B": "From the date of implantation", "C": "From the date of the last menstrual period", "D": "From the date of the first fetal heartbeat detected"}, "r": "C", "e": {"correcta": "Gestational age is conventionally calculated from the first day of the last menstrual period (LMP), giving the standard 40-week pregnancy timeline used clinically for dating and due-date estimation, even though ovulation and conception occur roughly two weeks later.", "incorrectas": {"A": "Dating from the estimated date of conception instead yields embryonic age, which runs about two weeks shorter than gestational age (a 38-week timeline), not the clinically standard gestational age measure.", "B": "Implantation occurs about six days after fertilization/ovulation, well after the LMP, and is not the reference point used for standard gestational dating.", "D": "The first detectable fetal heartbeat is a developmental milestone (around 6 weeks gestational age by ultrasound) but is not the reference point from which gestational age itself is calculated."}}}, {"id": "anking-reproductive-system-physiology-2011", "fuente": "anking", "tema": 32, "anki": "1462995934823", "q": "What term describes fetal age calculated from the date of conception (gestational age minus 2 weeks), corresponding to a roughly 38-week pregnancy?", "o": {"A": "Gestational age", "B": "Embryonic (conceptional) age", "C": "Menstrual age", "D": "Postnatal age"}, "r": "B", "e": {"correcta": "Embryonic (or conceptional) age is calculated from the actual date of conception/fertilization, which occurs about two weeks after the last menstrual period, so it runs two weeks shorter than gestational age, yielding an approximately 38-week timeline instead of 40 weeks.", "incorrectas": {"A": "Gestational age is dated from the last menstrual period, not from conception, and is therefore about two weeks longer (40 weeks) than embryonic age for the same pregnancy.", "C": "Menstrual age is essentially synonymous with gestational age (dated from LMP), the opposite of what is being described here, which is dating from conception.", "D": "Postnatal age refers to time elapsed since birth, which is an entirely different concept from prenatal dating conventions like gestational or embryonic age."}}}, {"id": "anking-reproductive-system-physiology-2012", "fuente": "anking", "tema": 32, "anki": "1462996133513", "q": "Which hormone is the dominant hormone produced during the first trimester of pregnancy?", "o": {"A": "Human placental lactogen", "B": "Estriol", "C": "Human chorionic gonadotropin (hCG)", "D": "Progesterone from the placenta"}, "r": "C", "e": {"correcta": "hCG, secreted by the syncytiotrophoblast beginning shortly after implantation, is the dominant and defining hormone of the first trimester; it rescues the corpus luteum, maintaining estrogen and progesterone production until the placenta can take over.", "incorrectas": {"B": "Estriol is a placental estrogen that becomes clinically relevant later in pregnancy (used in maternal serum screening), reflecting fetal adrenal and placental activity, not the dominant first-trimester hormone.", "A": "Human placental lactogen rises throughout pregnancy and plays a larger metabolic role as pregnancy progresses, but it is not the dominant hormone characterizing the first trimester; that role belongs to hCG.", "D": "Placental progesterone production only becomes dominant in the second and third trimesters after the luteal-placental shift; in the first trimester the corpus luteum (driven by hCG) is the main progesterone source."}}}, {"id": "anking-reproductive-system-physiology-2013", "fuente": "anking", "tema": 32, "anki": "1462996151862", "q": "During the second and third trimesters, the placenta produces progesterone using which substrate obtained from the mother?", "o": {"A": "Maternal cholesterol", "B": "Maternal DHEA-S", "C": "Maternal cortisol", "D": "Maternal testosterone"}, "r": "A", "e": {"correcta": "The placenta lacks certain enzymes needed to synthesize cholesterol de novo, so it relies on maternal cholesterol as the precursor substrate to produce progesterone throughout the second and third trimesters, unlike estrogen synthesis which depends on fetal adrenal-derived DHEA-S.", "incorrectas": {"B": "DHEA-S (largely from the fetal adrenal gland/zona reticularis) is the precursor used by the placenta for estrogen (estriol) synthesis, not for progesterone production, which uses maternal cholesterol instead.", "C": "Maternal cortisol is not the substrate for placental progesterone synthesis; cortisol is instead relevant to the estrogen:progesterone ratio shift and myometrial sensitivity as parturition approaches.", "D": "Testosterone is not the precursor used in this pathway; the placenta converts maternal cholesterol directly into progesterone via steroidogenic enzymes, bypassing androgen intermediates for this hormone."}}}, {"id": "anking-reproductive-system-physiology-2014", "fuente": "anking", "tema": 32, "anki": "1462996238719", "q": "Which hormone, produced throughout pregnancy by the syncytiotrophoblast, has actions similar to growth hormone and prolactin?", "o": {"A": "Human chorionic gonadotropin", "B": "Inhibin", "C": "Estriol", "D": "Human placental lactogen (HPL)"}, "r": "D", "e": {"correcta": "Human placental lactogen is secreted by the syncytiotrophoblast throughout pregnancy and has metabolic effects similar to growth hormone (promoting maternal lipolysis and insulin resistance to shunt glucose to the fetus) and to prolactin (supporting breast development for lactation).", "incorrectas": {"A": "hCG is also made by the syncytiotrophoblast but its role is to maintain the corpus luteum and support early steroidogenesis; it does not share the growth hormone/prolactin-like metabolic actions of HPL.", "B": "Inhibin (produced by the corpus luteum and placenta) primarily inhibits FSH secretion; it does not have growth hormone- or prolactin-like activity.", "C": "Estriol is an estrogen produced from fetal precursors and reflects fetoplacental function, but it does not exert growth hormone- or prolactin-like effects like HPL does."}}}, {"id": "anking-reproductive-system-physiology-2015", "fuente": "anking", "tema": 32, "anki": "1462996257748", "q": "As parturition (labor) nears, the estrogen/progesterone ratio increases due to rising cortisol. What effect does this have on the uterus?", "o": {"A": "It makes the uterus less sensitive to contractile stimuli", "B": "It has no effect on uterine sensitivity", "C": "It makes the uterus more sensitive to contractile stimuli", "D": "It causes permanent uterine quiescence"}, "r": "C", "e": {"correcta": "As term approaches, rising fetal cortisol increases placental estrogen production relative to progesterone, and this rising estrogen:progesterone ratio increases myometrial expression of oxytocin receptors and gap junctions, making the uterus more sensitive and responsive to contractile stimuli such as oxytocin and prostaglandins, promoting labor onset.", "incorrectas": {"A": "Decreased sensitivity would be expected if progesterone (which maintains uterine quiescence) predominated; but near term the ratio shifts toward estrogen dominance, which increases rather than decreases contractile responsiveness.", "B": "The ratio shift is not inconsequential; it is a key physiologic mechanism preparing the myometrium for labor by upregulating receptors that mediate contraction.", "D": "The uterus does not become permanently quiescent as term approaches; quite the opposite, it becomes primed for increasingly coordinated contractions leading to parturition."}}}, {"id": "anking-reproductive-system-physiology-2016", "fuente": "anking", "tema": 32, "anki": "1462996285814", "q": "Which hormone remains elevated following parturition to support breastfeeding?", "o": {"A": "Progesterone", "B": "Estrogen", "C": "Human placental lactogen", "D": "Prolactin"}, "r": "D", "e": {"correcta": "Prolactin remains elevated after delivery and, with suckling-induced stimulation, drives ongoing milk production; the sharp drop in placental estrogen and progesterone after delivery removes the inhibitory block on prolactin's action at the breast, allowing lactation to proceed.", "incorrectas": {"A": "Progesterone actually falls sharply after delivery of the placenta; its withdrawal is exactly what permits prolactin to finally act on the breast and initiate milk production.", "B": "Estrogen levels also drop abruptly postpartum along with progesterone, removing the hormones that had been suppressing prolactin receptor expression on breast tissue during pregnancy.", "C": "Human placental lactogen is produced by the placenta and its levels fall after delivery once the placenta is expelled, unlike prolactin, which is pituitary-derived and remains elevated for lactation."}}}, {"id": "anking-reproductive-system-physiology-2017", "fuente": "anking", "tema": 32, "anki": "1462996297369", "q": "Prolactin levels rise throughout pregnancy, yet lactation does not occur until after delivery. What explains this?", "o": {"A": "Prolactin receptors are not yet expressed on breast tissue during pregnancy", "B": "Oxytocin blocks prolactin release during pregnancy", "C": "Estrogen and progesterone downregulate prolactin receptors on the breast during pregnancy", "D": "hCG competitively inhibits prolactin receptors during pregnancy"}, "r": "C", "e": {"correcta": "During pregnancy, high circulating estrogen and progesterone downregulate prolactin receptors on breast tissue, blocking prolactin's lactogenic effect despite rising prolactin levels; after delivery, the abrupt fall in estrogen and progesterone removes this inhibition, unmasking prolactin's action and allowing milk production to begin.", "incorrectas": {"A": "Prolactin receptors are present on breast tissue during pregnancy (contributing to breast development), but their functional lactogenic effect is suppressed by high estrogen and progesterone, not by complete absence of receptors.", "B": "Oxytocin is responsible for milk ejection (letdown), not for regulating prolactin's ability to stimulate milk synthesis; it is not the hormone responsible for suppressing lactation during pregnancy.", "D": "hCG's primary role is maintaining the corpus luteum and early steroidogenesis; it does not act as a competitive inhibitor at prolactin receptors, unlike estrogen and progesterone which directly suppress the receptor's function."}}}, {"id": "anking-reproductive-system-physiology-2018", "fuente": "anking", "tema": 32, "anki": "1462996327469", "q": "As long as breastfeeding (lactation) continues, which reproductive process is suppressed due to prolactin's inhibitory effects on GnRH, FSH, and LH?", "o": {"A": "Endometrial proliferation", "B": "Cervical mucus production", "C": "Ovulation", "D": "Uterine involution"}, "r": "C", "e": {"correcta": "Elevated prolactin during lactation suppresses hypothalamic GnRH pulsatility, thereby decreasing pituitary FSH and LH secretion; without adequate LH surges, ovulation is suppressed, which is the physiologic basis of lactational amenorrhea as a (imperfect) natural contraceptive method.", "incorrectas": {"A": "Endometrial proliferation is downstream of estrogen exposure; while suppressed gonadotropins reduce ovarian estrogen production indirectly, the direct process being suppressed by prolactin's action on the hypothalamic-pituitary axis is ovulation itself.", "B": "Cervical mucus changes are driven by the estrogen and progesterone status of the cycle, not a direct target of prolactin's suppression of GnRH/FSH/LH.", "D": "Uterine involution (the postpartum shrinking of the uterus) is a separate, largely mechanical/hormonal recovery process and is not what is being suppressed by prolactin's effects on the hypothalamic-pituitary-gonadal axis."}}}, {"id": "anking-reproductive-system-embryology-2019", "fuente": "anking", "tema": 33, "anki": "1463075650855", "q": "In the development of a female fetus, which duct degenerates and which duct develops into the internal genitalia?", "o": {"A": "Paramesonephric duct degenerates; mesonephric duct develops", "B": "Mesonephric (wolffian) duct degenerates; paramesonephric (müllerian) duct develops", "C": "Both ducts degenerate equally", "D": "Both ducts persist and develop"}, "r": "B", "e": {"correcta": "In females, the absence of anti-müllerian hormone (normally produced by Sertoli cells in males) allows the paramesonephric (müllerian) duct to persist and develop into the fallopian tubes, uterus, and upper vagina, while the mesonephric (wolffian) duct regresses due to lack of testosterone support.", "incorrectas": {"A": "This reverses the actual pattern seen in females; in males, testosterone maintains the wolffian duct while AMH causes müllerian duct regression, the opposite of the fate of each duct in female development.", "C": "The ducts do not degenerate equally; one duct system (wolffian) regresses while the other (müllerian) develops, driven by differential hormone exposure rather than both disappearing.", "D": "Both ducts do not persist in typical female development; the default (absent Sertoli-derived AMH and testicular testosterone) pathway causes wolffian regression alongside müllerian development, not preservation of both systems."}}}, {"id": "anking-reproductive-system-embryology-2020", "fuente": "anking", "tema": 33, "anki": "1463078577289", "q": "Anti-müllerian hormone, secreted by Sertoli cells, is also referred to by what other name?", "o": {"A": "Inhibin B", "B": "Müllerian inhibitory factor", "C": "Sex hormone-binding globulin", "D": "Androgen-binding protein"}, "r": "B", "e": {"correcta": "Anti-müllerian hormone (AMH) is synonymously called müllerian inhibitory factor (MIF), reflecting its function: it is secreted by fetal Sertoli cells and causes regression of the paramesonephric (müllerian) ducts in genotypic males, allowing normal male internal genital development.", "incorrectas": {"A": "Inhibin B is also produced by Sertoli cells, but it functions to suppress FSH secretion via negative feedback on the pituitary; it is a distinct molecule from AMH/MIF and does not cause müllerian duct regression.", "C": "Sex hormone-binding globulin is a transport protein for sex steroids in the blood, unrelated to the developmental process of müllerian duct regression.", "D": "Androgen-binding protein, also secreted by Sertoli cells, concentrates testosterone within the seminiferous tubules for spermatogenesis; it is a different Sertoli cell product from AMH/MIF and has no role in müllerian duct regression."}}}, {"id": "anking-reproductive-system-embryology-2021", "fuente": "anking", "tema": 33, "anki": "1463078581596", "q": "If a genotypically XY fetus lacks Sertoli cells or has deficient müllerian inhibitory factor during development, what is the resulting internal and external genitalia?", "o": {"A": "Female internal genitalia only; female external genitalia", "B": "Both male and female internal genitalia; male external genitalia", "C": "Male internal genitalia only; ambiguous external genitalia", "D": "Both male and female internal genitalia; female external genitalia"}, "r": "B", "e": {"correcta": "Without Sertoli cells (or their AMH/MIF product), the müllerian ducts fail to regress and develop alongside the wolffian ducts (which persist due to testosterone from Leydig cells), producing both male and female internal duct derivatives; because testes still produce testosterone/DHT, external genitalia remain virilized (male).", "incorrectas": {"A": "Female internal genitalia alone would require absence of both AMH and testosterone (as in complete gonadal failure); here, testosterone-producing Leydig cells persist, so wolffian derivatives still form alongside the unregressed müllerian structures, and external genitalia remain male.", "C": "External genitalia are not ambiguous in this scenario; because testosterone/DHT exposure is intact (only AMH/Sertoli function is lost), external genitalia differentiate in the male direction, while internally both duct systems persist.", "D": "External genitalia would only be female if androgen action were absent (e.g., 5-alpha reductase deficiency or androgen insensitivity); since only Sertoli/AMH function is missing here, testosterone still virilizes the external genitalia toward male."}}}, {"id": "anking-reproductive-system-embryology-2022", "fuente": "anking", "tema": 33, "anki": "1463078620627", "q": "The indifferent gonad begins development adjacent to which fetal structure, the precursor of part of the developing kidney?", "o": {"A": "The metanephros", "B": "The mesonephros", "C": "The pronephros", "D": "The cloaca"}, "r": "B", "e": {"correcta": "The indifferent gonad develops in close proximity to the mesonephros, the intermediate (and transiently functional) fetal kidney structure, reflecting the shared embryologic origin of the urinary and genital systems from the intermediate mesoderm.", "incorrectas": {"A": "The metanephros is the definitive kidney precursor that gives rise to the adult kidney (via the ureteric bud and metanephric mesenchyme), but the indifferent gonad specifically develops next to the mesonephros, not the metanephros.", "C": "The pronephros is the earliest, vestigial and nonfunctional kidney precursor that regresses very early in development; the gonad's developmental association is with the mesonephros, the later intermediate stage.", "D": "The cloaca is the common terminal chamber that later divides into the urogenital sinus and rectum; it is not the structure adjacent to which the indifferent gonad develops."}}}, {"id": "anking-reproductive-system-embryology-2023", "fuente": "anking", "tema": 33, "anki": "1463078634375", "q": "Which embryologic duct develops into the fallopian tubes, uterus, and upper portion of the vagina (internal female genitalia)?", "o": {"A": "Mesonephric (wolffian) duct", "B": "Urogenital sinus", "C": "Paramesonephric (müllerian) duct", "D": "Gubernaculum"}, "r": "C", "e": {"correcta": "The paramesonephric (müllerian) duct, in the absence of anti-müllerian hormone, persists and differentiates into the fallopian tubes, uterus, and upper vagina, forming the internal female genital tract; its vestigial male remnant is the appendix testis.", "incorrectas": {"A": "The mesonephric (wolffian) duct develops into male internal structures (epididymis, vas deferens, seminal vesicles) when testosterone is present; in females it regresses, leaving only a vestigial remnant (Gartner duct), rather than forming the uterus or tubes.", "B": "The urogenital sinus gives rise to the lower portion of the vagina (and the bladder/urethra), not the fallopian tubes, uterus, or upper vagina, which come from the müllerian duct.", "D": "The gubernaculum is a ligamentous structure involved in gonadal descent (forming the ovarian ligament and round ligament of the uterus in females), not the origin of the tubes, uterus, or vagina."}}}, {"id": "anking-reproductive-system-embryology-2024", "fuente": "anking", "tema": 33, "anki": "1463078682536", "q": "Which embryologic duct develops into the seminal vesicles, epididymis, ejaculatory duct, and ductus deferens (male internal genitalia, except the prostate)?", "o": {"A": "Paramesonephric (müllerian) duct", "B": "Urogenital sinus", "C": "Mesonephric (wolffian) duct", "D": "Genital tubercle"}, "r": "C", "e": {"correcta": "Under the influence of testosterone from fetal Leydig cells, the mesonephric (wolffian) duct differentiates into the epididymis, vas deferens (ductus deferens), seminal vesicles, and ejaculatory duct; in females, this duct regresses, leaving only a vestigial remnant called the Gartner duct.", "incorrectas": {"A": "The paramesonephric (müllerian) duct regresses in males due to anti-müllerian hormone from Sertoli cells; it does not give rise to these male internal structures, which instead derive from the wolffian duct.", "B": "The urogenital sinus gives rise to the prostate and bulbourethral glands (and bladder/urethra), not the epididymis, vas deferens, or seminal vesicles, which are wolffian duct derivatives.", "D": "The genital tubercle gives rise to external genital structures (glans penis/clitoris), not the internal ductal structures being described here."}}}, {"id": "anking-reproductive-system-pathology-2025", "fuente": "anking", "tema": 8, "anki": "1463078721869", "q": "Which uterine anomaly, resulting from incomplete resorption of the uterovaginal septum, is the most common congenital uterine malformation?", "o": {"A": "Bicornuate uterus", "B": "Uterus didelphys", "C": "Unicornuate uterus", "D": "Septate uterus"}, "r": "D", "e": {"correcta": "A septate uterus arises from incomplete resorption of the midline septum that forms after the paired müllerian ducts fuse, leaving a fibrous or muscular septum dividing the uterine cavity; it is the most common müllerian duct anomaly and is associated with the highest rate of pregnancy complications among these anomalies.", "incorrectas": {"A": "A bicornuate uterus results from incomplete fusion of the müllerian ducts themselves (not failed septal resorption), producing a heart-shaped uterus with two horns, which is a distinct anomaly from septate uterus.", "B": "Uterus didelphys results from complete failure of müllerian duct fusion, producing entirely duplicated uterine horns, cervices, and often vaginas, a different and less common mechanism than incomplete septal resorption.", "C": "A unicornuate uterus results from incomplete development (or complete failure of development) of one müllerian duct, not from a septum failing to resorb after normal fusion."}}}, {"id": "anking-reproductive-system-pathology-2026", "fuente": "anking", "tema": 8, "anki": "1463078730041", "q": "What is the treatment for a symptomatic septate uterus?", "o": {"A": "Hysterectomy", "B": "Septoplasty", "C": "Cervical cerclage", "D": "Progestin therapy"}, "r": "B", "e": {"correcta": "Septoplasty, the surgical resection of the fibrous/muscular septum (typically via hysteroscopy), is the standard treatment for a septate uterus, particularly in patients experiencing recurrent pregnancy loss or infertility, and it can restore a normal uterine cavity to improve reproductive outcomes.", "incorrectas": {"A": "Hysterectomy is a drastic and fertility-ending procedure that is not indicated for a septate uterus, which is a correctable anatomic variant, not a condition requiring removal of the uterus.", "C": "Cervical cerclage is used to treat cervical insufficiency (a weak cervix prone to painless dilation), a different condition from an intrauterine septum, and does not address the septum itself.", "D": "Progestin therapy does not correct the anatomic defect of a uterine septum; medical hormone therapy is not the treatment for this structural anomaly, which requires surgical correction."}}}, {"id": "anking-reproductive-system-pathology-2027", "fuente": "anking", "tema": 8, "anki": "1463078734022", "q": "What effect does a septate uterus have on fertility?", "o": {"A": "No effect on fertility", "B": "Increased fertility", "C": "Decreased fertility", "D": "Fertility is unaffected but labor is prolonged"}, "r": "C", "e": {"correcta": "A septate uterus decreases fertility and is associated with the highest rate of pregnancy loss among müllerian anomalies, because the septum is poorly vascularized fibrous/muscular tissue that provides an inadequate implantation site and increases the risk of miscarriage and malpresentation.", "incorrectas": {"A": "A septate uterus is not fertility-neutral; it is specifically noted for impairing implantation and increasing miscarriage risk more than other müllerian anomalies, which is why septoplasty is often recommended.", "B": "There is no mechanism by which a septum would enhance fertility; its poor vascularity and disruption of normal cavity shape work against successful implantation and pregnancy maintenance.", "D": "While obstetric complications (like malpresentation) can occur, the key clinically tested effect of septate uterus is on fertility/miscarriage risk, not specifically on labor duration."}}}, {"id": "anking-reproductive-system-pathology-2028", "fuente": "anking", "tema": 8, "anki": "1463078784640", "q": "Is pregnancy possible in a patient with uterus didelphys (complete failure of müllerian duct fusion)?", "o": {"A": "No, uterus didelphys is incompatible with pregnancy", "B": "Yes, pregnancy is possible", "C": "Only with in vitro fertilization", "D": "Only after surgical unification of the two uterine horns"}, "r": "B", "e": {"correcta": "Uterus didelphys results from complete failure of müllerian duct fusion, producing two separate uterine horns, cervices, and often vaginas, but each horn typically has a functional endometrial cavity, so natural pregnancy is possible, although patients have increased risk of preterm labor and malpresentation.", "incorrectas": {"A": "Pregnancy is not incompatible with uterus didelphys; unlike more severe müllerian agenesis, the duplicated uterine horns are generally each capable of supporting a pregnancy, albeit with higher obstetric risk.", "C": "Natural conception and pregnancy are possible in uterus didelphys without requiring assisted reproductive technology; IVF is not a prerequisite for this anomaly.", "D": "Surgical unification is not required for pregnancy to occur; women with uterus didelphys can and do conceive and carry pregnancies without surgical correction of the duplicated uterine horns."}}}, {"id": "anking-reproductive-system-pathology-2029", "fuente": "anking", "tema": 8, "anki": "1463078929014", "q": "Which congenital penile abnormality, hypospadias or epispadias, is more common?", "o": {"A": "Epispadias", "B": "They occur with equal frequency", "C": "Hypospadias", "D": "Neither occurs congenitally; both are acquired"}, "r": "C", "e": {"correcta": "Hypospadias, in which the urethral meatus opens on the ventral surface of the penis due to failure of the urethral folds to fuse, is more common than epispadias and is often associated with failure of the genital tubercle to properly form the urethra.", "incorrectas": {"A": "Epispadias, where the urethral meatus opens on the dorsal surface of the penis due to abnormal positioning of the genital tubercle, is less common than hypospadias and is classically associated with bladder exstrophy.", "B": "The two conditions do not occur with equal frequency; hypospadias is substantially more common in clinical practice than epispadias.", "D": "Both hypospadias and epispadias are congenital, arising from defects in embryologic urethral or genital tubercle development, not acquired conditions."}}}, {"id": "anking-reproductive-system-embryology-2030", "fuente": "anking", "tema": 33, "anki": "1463078958759", "q": "What is the male remnant of the processus vaginalis after normal descent of the testis?", "o": {"A": "Gubernaculum testis", "B": "Tunica vaginalis", "C": "Appendix testis", "D": "Cremasteric fascia"}, "r": "B", "e": {"correcta": "The processus vaginalis, an outpouching of peritoneum that guides testicular descent through the inguinal canal, normally obliterates except for its distal portion, which persists as the tunica vaginalis, the serous covering surrounding the testis; incomplete obliteration can leave a patent tract predisposing to hydrocele (small opening) or indirect inguinal hernia (large opening).", "incorrectas": {"A": "The gubernaculum is a separate fibrous cord that guides the testis toward the scrotum during descent; it is not derived from the processus vaginalis and becomes the scrotal ligament, not the tunica vaginalis.", "C": "The appendix testis is a müllerian duct remnant (vestige of the paramesonephric duct) attached to the testis, unrelated to the processus vaginalis or its obliteration.", "D": "The cremasteric fascia derives from the internal oblique muscle layer that the testis passes through during descent, not from the processus vaginalis itself."}}}, {"id": "anking-reproductive-system-embryology-2031", "fuente": "anking", "tema": 33, "anki": "1463078965308", "q": "What is the female remnant of the processus vaginalis?", "o": {"A": "The canal of Nuck", "B": "The round ligament of the uterus", "C": "There is no remnant; it normally obliterates completely", "D": "The suspensory ligament of the ovary"}, "r": "C", "e": {"correcta": "In females, the processus vaginalis (called the canal of Nuck when persistent) normally regresses completely and leaves no significant remnant structure, unlike in males where its distal portion persists as the tunica vaginalis; rare failure of complete obliteration in females can result in a canal of Nuck cyst or predispose to an indirect inguinal hernia.", "incorrectas": {"A": "The canal of Nuck refers to an abnormally persistent processus vaginalis in females (a pathologic finding), not the expected normal outcome, which is complete obliteration without a named remnant structure.", "B": "The round ligament of the uterus is derived from the gubernaculum, not from the processus vaginalis, and follows a similar path through the inguinal canal but is an embryologically distinct structure.", "D": "The suspensory ligament of the ovary carries the ovarian vessels and is unrelated to the processus vaginalis; it is a peritoneal fold overlying the gonadal vessels, not a remnant of this structure."}}}, {"id": "anking-reproductive-system-embryology-2032", "fuente": "anking", "tema": 33, "anki": "1463078977459", "q": "The gubernaculum is a fibrous cord that guides testicular descent in the male fetus. What is the adult male remnant of the gubernaculum?", "o": {"A": "Round ligament of the uterus", "B": "Scrotal ligament (anchors testis within scrotum)", "C": "Processus vaginalis", "D": "Median umbilical ligament"}, "r": "B", "e": {"correcta": "In males, the gubernaculum persists as the scrotal ligament, which anchors the testis to the inferior scrotum after descent. Defective anchoring predisposes to a 'bell-clapper deformity,' in which the testis hangs freely within the tunica vaginalis and can rotate on the spermatic cord, causing testicular torsion.", "incorrectas": {"A": "The round ligament of the uterus is the female homologue of the gubernaculum (the portion distal to the ovary), not the male remnant; it runs from the uterus through the inguinal canal to the labia majora.", "C": "The processus vaginalis is a peritoneal outpouching that precedes and accompanies testicular descent, giving rise to the tunica vaginalis; it is a separate embryologic structure from the gubernaculum itself, and its persistent patency causes indirect inguinal hernias or hydroceles.", "D": "The median umbilical ligament is the remnant of the urachus, an allantoic structure connecting the bladder to the umbilicus, unrelated to gonadal descent."}}}, {"id": "anking-reproductive-system-embryology-2033", "fuente": "anking", "tema": 33, "anki": "1463078997361", "q": "In the female, the gubernaculum does not need to guide descent into a scrotum but still persists as two ligamentous structures. What are they?", "o": {"A": "Broad ligament and mesovarium", "B": "Suspensory ligament of the ovary and cardinal ligament", "C": "Ovarian ligament and round ligament of the uterus", "D": "Infundibulopelvic ligament and uterosacral ligament"}, "r": "C", "e": {"correcta": "Because the ovary does not descend into a scrotum, the gubernaculum in females remains as two separate segments: the ovarian ligament (connecting the ovary to the uterus) and the round ligament of the uterus (running from the uterus through the inguinal canal to the labia majora), corresponding to the proximal and distal portions of the original gubernacular cord, respectively.", "incorrectas": {"A": "The broad ligament and mesovarium are peritoneal folds that support the uterus, tubes, and ovaries; they derive from peritoneal reflections, not from the gubernaculum.", "B": "The suspensory ligament of the ovary carries the ovarian vessels and is a peritoneal fold, and the cardinal ligament supports the cervix and upper vagina via the uterine vessels; neither is a gubernacular remnant.", "D": "The infundibulopelvic ligament is another name for the suspensory ligament of the ovary, and the uterosacral ligament anchors the cervix to the sacrum; both are distinct peritoneal/connective structures unrelated to the gubernaculum."}}}, {"id": "anking-reproductive-system-anatomy-2034", "fuente": "anking", "tema": 34, "anki": "1463080274404", "q": "A patient has a squamous cell carcinoma of the vulva. To which lymph node group does this tumor most likely spread first?", "o": {"A": "External iliac nodes", "B": "Para-aortic nodes", "C": "Internal iliac nodes", "D": "Superficial inguinal nodes"}, "r": "D", "e": {"correcta": "The vulva, scrotum, distal anus (below the pectinate line), and distal (lower third) of the vagina share embryologic origin from external structures and drain to the superficial inguinal lymph nodes, following the same pattern as the skin of the lower limb and perineum.", "incorrectas": {"A": "The external iliac nodes drain pelvic structures derived from the urogenital sinus above the pelvic floor, such as the body of the uterus, cervix, and superior bladder, not external genital skin.", "B": "The para-aortic nodes drain retroperitoneal structures that arise from midline gonadal tissue, including the ovaries, testes, and kidneys, which migrate with their embryonic blood supply rather than draining to inguinal nodes.", "C": "The internal iliac nodes drain deeper pelvic viscera such as the prostate, cervix, corpus cavernosum, and proximal vagina, which are not part of the external perineal/vulvar drainage territory."}}}, {"id": "anking-reproductive-system-anatomy-2035", "fuente": "anking", "tema": 34, "anki": "1463080276822", "q": "A tumor in the body of the uterus is being staged by lymphatic spread. Which lymph node group receives drainage from the body of the uterus, cervix, and superior bladder?", "o": {"A": "Superficial inguinal nodes", "B": "Para-aortic nodes", "C": "External iliac nodes", "D": "Internal iliac nodes"}, "r": "C", "e": {"correcta": "The body of the uterus, cervix, and superior bladder drain to the external iliac nodes, reflecting their location within the pelvis along structures derived from the urogenital sinus and paramesonephric system, distinct from the perineal external genitalia drainage pattern.", "incorrectas": {"A": "The superficial inguinal nodes drain external genital and perineal skin structures such as the vulva, scrotum, distal vagina, and distal anus, not the uterine corpus or bladder dome.", "B": "The para-aortic nodes drain the ovaries and testes, which retain their embryonic gonadal lymphatic drainage along the aorta since they originate near the kidneys and descend with their own vasculature.", "D": "The internal iliac nodes drain the prostate, cervix (lower/deeper portion in some schemes), corpus cavernosum, and proximal vagina; this is a distractor because it is easily confused with the cervix listed in the question but the specific structures named (uterine body and superior bladder) drain to external iliac nodes."}}}, {"id": "anking-reproductive-system-anatomy-2036", "fuente": "anking", "tema": 34, "anki": "1463081009048", "q": "After ejaculation, detumescence of the penis occurs. Which neurotransmitter is released by the sympathetic nervous system to mediate this process?", "o": {"A": "Acetylcholine", "B": "Nitric oxide", "C": "Vasoactive intestinal peptide", "D": "Norepinephrine"}, "r": "D", "e": {"correcta": "Sympathetic postganglionic fibers release norepinephrine, which acts on alpha-1 receptors in the trabecular smooth muscle of the corpora cavernosa to increase intracellular calcium, causing contraction of the smooth muscle and constriction of the helicine arterioles. This reduces arterial inflow and allows venous drainage of the erectile tissue, producing detumescence.", "incorrectas": {"B": "Nitric oxide is the key mediator of erection, not detumescence; it activates guanylate cyclase to increase cGMP, which relaxes trabecular smooth muscle and dilates the helicine arteries to fill the corpora cavernosa with blood.", "C": "Vasoactive intestinal peptide, along with acetylcholine, contributes to the parasympathetic-mediated erectile response by promoting smooth muscle relaxation and vasodilation, the opposite effect of what causes detumescence.", "A": "Acetylcholine is released by parasympathetic fibers and promotes erection indirectly by stimulating endothelial nitric oxide release, making it part of the pro-erectile pathway rather than the detumescence pathway."}}}, {"id": "anking-reproductive-system-physiology-2037", "fuente": "anking", "tema": 32, "anki": "1463081027332", "q": "A 24-year-old woman presents with acute right lower quadrant pain on day 14 of her menstrual cycle. Ultrasound reveals no adnexal mass and normal ovaries. Which of the following best explains her presentation?", "o": {"A": "Ectopic pregnancy", "B": "Mittelschmerz", "C": "Ovarian torsion", "D": "Endometriosis"}, "r": "B", "e": {"correcta": "Mittelschmerz is transient, mid-cycle ovulatory pain classically occurring around day 10-14 of the cycle, coinciding with ovulation. It results from peritoneal irritation caused by follicular swelling and rupture along with fallopian tube contraction, and it can mimic appendicitis when it occurs on the right side.", "incorrectas": {"A": "Ectopic pregnancy typically presents with pain and vaginal bleeding in a patient with a positive pregnancy test, often several weeks after a missed period, not classically timed precisely to mid-cycle ovulation with a normal ultrasound.", "C": "Ovarian torsion typically presents with sudden, severe unilateral pain and would show an enlarged, edematous ovary or abnormal Doppler flow on ultrasound, which is inconsistent with the normal ovarian imaging described.", "D": "Endometriosis classically causes cyclic pelvic pain related to menstruation (dysmenorrhea, dyspareunia, infertility) rather than an isolated mid-cycle event tied specifically to ovulation, and often shows implants or endometriomas on imaging."}}}, {"id": "anking-reproductive-system-physiology-2038", "fuente": "anking", "tema": 32, "anki": "1463081222466", "q": "A newborn is assessed at 1 minute and 5 minutes after delivery using a standardized 10-point scale of vital signs to determine the need for resuscitation. What is this assessment tool called?", "o": {"A": "Ballard score", "B": "Apgar score", "C": "Glasgow Coma Scale", "D": "Silverman-Andersen score"}, "r": "B", "e": {"correcta": "The Apgar score is a rapid clinical assessment of a newborn's condition performed at 1 and 5 minutes after birth, scoring five parameters (appearance/color, pulse, grimace/reflex irritability, activity/muscle tone, and respiration) from 0 to 2 each, for a maximum of 10 points, to guide the need for resuscitative measures.", "incorrectas": {"A": "The Ballard score is used to estimate gestational age based on physical and neuromuscular maturity findings, not to assess immediate postnatal vital status.", "C": "The Glasgow Coma Scale assesses level of consciousness in patients (eye opening, verbal response, motor response) after neurologic injury, and is not designed for or applied to newborns in the delivery room.", "D": "The Silverman-Andersen score assesses the degree of respiratory distress in neonates based on chest wall movement and retractions, a narrower tool focused only on breathing, unlike the broader five-category Apgar score."}}}, {"id": "anking-reproductive-system-physiology-2039", "fuente": "anking", "tema": 32, "anki": "1463081611935", "q": "On the Apgar score, an infant with a pink body but blue extremities receives a score of 1 for the appearance component. What score and appearance would indicate the best possible finding for this component?", "o": {"A": "Score of 2: fully pink", "B": "Score of 2: pale or blue", "C": "Score of 0: extremities blue only", "D": "Score of 1: fully pink"}, "r": "A", "e": {"correcta": "For the appearance (color) component of the Apgar score, a score of 2 corresponds to a fully pink infant, reflecting good oxygenation and perfusion throughout the body. A score of 1 is given for acrocyanosis (pink body, blue extremities), and a score of 0 is given when the infant is pale or entirely blue (central cyanosis), indicating poor perfusion or oxygenation.", "incorrectas": {"B": "Pale or blue coloration throughout the body corresponds to the lowest score of 0, not the best score of 2, since it signals inadequate oxygenation or circulation.", "C": "Blue extremities alone (with a pink trunk) is acrocyanosis, which is a normal transitional finding scored as 1, not 0; a score of 0 requires the infant to be pale or entirely blue.", "D": "A fully pink appearance is correctly the best finding, but it is scored as 2, not 1; scoring it as 1 misassigns points within this component of the scale."}}}, {"id": "anking-reproductive-system-physiology-2040", "fuente": "anking", "tema": 32, "anki": "1463081757542", "q": "On the Apgar score, a heart rate of 130 bpm in a newborn corresponds to which score for the pulse component?", "o": {"A": "Score of 0", "B": "Score of 1", "C": "Score of 2", "D": "This component is not scored on the Apgar exam"}, "r": "C", "e": {"correcta": "For the pulse component of the Apgar score, a heart rate of 100 bpm or greater receives the maximum score of 2, reflecting adequate cardiac output and perfusion. Since 130 bpm exceeds this threshold, it earns a score of 2.", "incorrectas": {"A": "A score of 0 for the pulse component is reserved for an absent pulse (no heartbeat detectable), which would be a medical emergency requiring immediate resuscitation, not the case with a heart rate of 130 bpm.", "B": "A score of 1 is given for a pulse less than 100 bpm, indicating relative bradycardia in the newborn; 130 bpm is well above this cutoff and therefore does not receive a score of 1.", "D": "Pulse (heart rate) is one of the five standard components of the Apgar score, alongside appearance, grimace, activity, and respiration, so it is indeed scored on every Apgar assessment."}}}, {"id": "anking-reproductive-system-physiology-2041", "fuente": "anking", "tema": 32, "anki": "1463081820748", "q": "A newborn cries vigorously and pulls away when a suction catheter is used to clear its nasal passages. What score does this reflex irritability (grimace) response receive on the Apgar scale?", "o": {"A": "Score of 0", "B": "Score of 2", "C": "Score of 1", "D": "Grimace is not part of the Apgar assessment"}, "r": "B", "e": {"correcta": "On the grimace (reflex irritability) component of the Apgar score, an infant who cries vigorously and actively withdraws from a stimulus receives the maximum score of 2, indicating a robust and intact neurologic response to stimulation.", "incorrectas": {"A": "A score of 0 is given when there is no response at all to stimulation, which is a much more concerning finding than the vigorous crying and withdrawal described in this infant.", "C": "A score of 1 corresponds to a weaker response, such as grimacing or a weak cry with stimulation, rather than the full active crying and pulling away described in this case, which merits the higher score.", "D": "Grimace (reflex irritability) is one of the five core Apgar components, along with appearance, pulse, activity, and respiration, and is routinely assessed in every newborn exam using this scale."}}}, {"id": "anking-reproductive-system-physiology-2042", "fuente": "anking", "tema": 32, "anki": "1463081859526", "q": "A newborn shows active, spontaneous movement of all extremities during the Apgar assessment. What score does the activity (muscle tone) component receive?", "o": {"A": "Score of 1", "B": "Score of 0", "C": "Score of 2", "D": "Activity is only assessed at the 10-minute mark, not included in the standard 1- and 5-minute scores"}, "r": "C", "e": {"correcta": "For the activity (muscle tone) component of the Apgar score, active spontaneous movement earns the maximum score of 2, reflecting good muscular tone and neurologic function. A score of 1 is given for some flexion of the arms and legs, and a score of 0 is given for a limp infant with no movement.", "incorrectas": {"A": "A score of 1 corresponds to partial flexion of the extremities without active movement, a lesser finding than the active movement described in this infant.", "B": "A score of 0 indicates a completely limp infant with no movement at all, which is the opposite of the vigorous, active movement seen here and would suggest hypotonia or depression.", "D": "Activity, like the other four components, is assessed and scored at both the standard 1-minute and 5-minute time points (and additional intervals if resuscitation continues), not reserved for a separate 10-minute assessment."}}}, {"id": "anking-reproductive-system-physiology-2043", "fuente": "anking", "tema": 32, "anki": "1463081896488", "q": "A newborn is making slow, irregular respiratory efforts at the 1-minute Apgar assessment. What score does this respiration component receive?", "o": {"A": "Score of 2", "B": "Score of 0", "C": "Score of 1", "D": "Respiration is not weighted equally with the other Apgar components"}, "r": "C", "e": {"correcta": "On the respiration component of the Apgar score, slow or irregular breathing corresponds to a score of 1, an intermediate finding between no breathing at all (score 0) and a strong, vigorous cry (score 2), which reflects the best respiratory effort.", "incorrectas": {"A": "A score of 2 is reserved for a strong cry, indicating robust respiratory effort, which is a better finding than the slow, irregular breathing described in this infant.", "B": "A score of 0 is given when there is no breathing at all (apnea), a more severe finding than the slow, irregular respirations present here, which do at least demonstrate some respiratory effort.", "D": "All five Apgar components (appearance, pulse, grimace, activity, respiration) are weighted equally, each contributing 0-2 points to the total 10-point score; respiration is not given special weighting."}}}, {"id": "anking-reproductive-system-physiology-2044", "fuente": "anking", "tema": 32, "anki": "1463081930386", "q": "A neonate has a persistently low Apgar score even at the 10-minute reassessment despite resuscitative efforts. This is most predictive of increased long-term risk for which type of complication?", "o": {"A": "Musculoskeletal deformity", "B": "Cardiac malformation", "C": "Renal insufficiency", "D": "Neurologic damage"}, "r": "D", "e": {"correcta": "A persistently low Apgar score at later time points (such as 10 or 20 minutes) reflects prolonged hypoxia and inadequate perfusion during the perinatal period, and is associated with an increased risk of long-term neurologic damage, including conditions like cerebral palsy and hypoxic-ischemic encephalopathy.", "incorrectas": {"A": "Musculoskeletal deformities are typically related to intrauterine positioning, genetic syndromes, or teratogen exposure rather than to perinatal hypoxia reflected by a persistently low Apgar score.", "B": "Cardiac malformations are structural defects that arise during early embryonic development (weeks 3-8) and are not a consequence of perinatal hypoxia measured by the Apgar score, which assesses acute physiologic status at birth.", "C": "Renal insufficiency is not the classic long-term complication associated with low Apgar scores; the brain is particularly vulnerable to hypoxic injury during the perinatal period, making neurologic damage the primary concern."}}}, {"id": "anking-reproductive-system-physiology-2045", "fuente": "anking", "tema": 32, "anki": "1463081956910", "q": "A newborn weighs 2300 grams at birth. This weight meets the clinical definition of which condition?", "o": {"A": "Macrosomia", "B": "Low birth weight", "C": "Normal birth weight", "D": "Extremely low birth weight"}, "r": "B", "e": {"correcta": "Low birth weight is defined as a birth weight less than 2500 grams (approximately 5.5 pounds). It can result from prematurity (birth before term) or intrauterine growth restriction (IUGR), and 2300 grams falls below this threshold.", "incorrectas": {"A": "Macrosomia refers to an abnormally large newborn, typically defined as birth weight greater than 4000-4500 grams, often associated with maternal diabetes; this is the opposite extreme from the low weight described.", "C": "Normal birth weight generally falls between 2500 and 4000 grams; a weight of 2300 grams falls below this normal range and therefore meets criteria for low birth weight instead.", "D": "Extremely low birth weight is a more severe subcategory defined as less than 1000 grams, which is well below the 2300 grams described in this newborn."}}}, {"id": "anking-reproductive-system-physiology-2046", "fuente": "anking", "tema": 32, "anki": "1463082253672", "q": "A pediatrician counsels a new mother on infant feeding. Which of the following is considered the ideal source of nutrition for infants younger than 6 months old?", "o": {"A": "Iron-fortified infant formula", "B": "Cow's milk", "C": "Breast milk", "D": "Soy-based formula"}, "r": "C", "e": {"correcta": "Breast milk is considered the ideal nutrition source for infants younger than 6 months. It provides maternal immunoglobulins (particularly IgA), macrophages, and lymphocytes that support the infant's developing immune system, and breastfeeding is associated with decreased risk of asthma, allergies, diabetes, and obesity later in life.", "incorrectas": {"A": "Iron-fortified infant formula is a reasonable alternative when breastfeeding is not possible, but it lacks the maternal immunoglobulins, live immune cells, and specific bioactive components found in breast milk that confer additional immunologic and long-term health benefits.", "B": "Cow's milk is not recommended for infants under 1 year of age because it lacks adequate iron, contains excess protein and minerals that stress immature kidneys, and can cause gastrointestinal blood loss, making it an inappropriate and inferior choice compared to breast milk.", "D": "Soy-based formula is typically reserved for infants with specific conditions such as galactosemia or true cow's milk protein allergy, and does not confer the same immunologic advantages as breast milk for the general infant population."}}}, {"id": "anking-nutrition-2047", "fuente": "anking", "tema": 46, "anki": "1463082317584", "q": "An infant who is exclusively breastfed requires supplementation with which vitamin due to its low concentration in breast milk?", "o": {"A": "Vitamin D", "B": "Vitamin C", "C": "Vitamin B12", "D": "Vitamin K"}, "r": "A", "e": {"correcta": "Breast milk contains insufficient vitamin D to meet an infant's needs, so exclusively breastfed infants require vitamin D supplementation to prevent deficiency, which can otherwise lead to impaired bone mineralization and rickets.", "incorrectas": {"B": "Vitamin C is generally present in adequate amounts in breast milk from a well-nourished mother and is not the classic supplement recommended for exclusively breastfed infants.", "C": "Vitamin B12 deficiency in breastfed infants is a concern specifically when the mother herself is deficient (e.g., in strict vegans), rather than a routine, universal supplementation recommendation for all breastfed infants as with vitamin D.", "D": "Vitamin K is administered as a single intramuscular injection at birth to all newborns (breastfed or not) to prevent hemorrhagic disease of the newborn, since neonatal gut flora have not yet developed to synthesize it; this is a one-time perinatal injection, not an ongoing supplement tied to breastfeeding."}}}, {"id": "anking-reproductive-system-physiology-2048", "fuente": "anking", "tema": 32, "anki": "1463082333416", "q": "Breastfeeding is associated with a reduced maternal risk of which two malignancies?", "o": {"A": "Endometrial and cervical cancer", "B": "Colon and thyroid cancer", "C": "Lung and pancreatic cancer", "D": "Breast and ovarian cancer"}, "r": "D", "e": {"correcta": "Breastfeeding reduces maternal risk of breast and ovarian cancer, likely related to lactational suppression of ovulation and hormonal changes that decrease lifetime estrogen exposure. It also facilitates mother-child bonding as an additional benefit.", "incorrectas": {"A": "Endometrial and cervical cancer risk reduction is not the classically cited benefit of breastfeeding; cervical cancer risk is primarily driven by HPV infection, and endometrial cancer risk relates more to unopposed estrogen exposure from other causes such as anovulation or obesity.", "B": "Colon and thyroid cancer are not the malignancies specifically linked to reduced risk with breastfeeding; the well-established protective association is with the hormonally sensitive breast and ovarian tissues.", "C": "Lung and pancreatic cancer risks are driven predominantly by factors such as smoking and are not part of the recognized protective effect of lactation on maternal cancer risk."}}}, {"id": "anking-reproductive-system-physiology-2049", "fuente": "anking", "tema": 32, "anki": "1463082440269", "q": "How does cigarette smoking affect the timing of menopause onset?", "o": {"A": "No significant effect", "B": "Earlier onset", "C": "Later onset", "D": "Effect depends on parity but not smoking status"}, "r": "B", "e": {"correcta": "Smoking accelerates depletion of the ovarian follicular pool through toxic effects of tobacco constituents (such as polycyclic aromatic hydrocarbons) on oocytes, leading to earlier onset of menopause compared to nonsmokers.", "incorrectas": {"A": "Smoking does have a significant, well-documented effect on reproductive aging by accelerating follicular loss, so a claim of no effect is incorrect.", "C": "Smoking causes earlier, not later, menopause onset because it hastens the age-related decline in ovarian follicle number rather than preserving ovarian reserve.", "D": "While parity and other factors can influence menopausal timing, smoking itself is an independently established and clinically significant risk factor for earlier menopause, not merely a secondary variable dependent on parity."}}}, {"id": "anking-reproductive-system-physiology-2050", "fuente": "anking", "tema": 32, "anki": "1463082529466", "q": "A 52-year-old woman has not had a menstrual period in 14 months. Which laboratory finding is most specific for confirming menopause?", "o": {"A": "Elevated FSH", "B": "Elevated prolactin", "C": "Decreased LH", "D": "Elevated TSH"}, "r": "A", "e": {"correcta": "A very elevated FSH level is specific for menopause. As ovarian follicles become resistant and depleted, they no longer produce sufficient estrogen and inhibin to exert negative feedback on the hypothalamic-pituitary axis, resulting in markedly increased FSH secretion.", "incorrectas": {"B": "Elevated prolactin is associated with conditions like prolactinomas or hypothyroidism and can cause secondary amenorrhea through suppression of GnRH, but it is not the specific marker used to confirm menopause.", "C": "LH is actually increased, not decreased, in menopause due to the same loss of negative feedback from declining estrogen and inhibin, though FSH rises more dramatically and is considered more specific.", "D": "TSH elevation indicates primary hypothyroidism, which can be an alternate cause of menstrual irregularity, but it is not the hormone used to specifically diagnose menopause."}}}, {"id": "anking-reproductive-system-physiology-2051", "fuente": "anking", "tema": 32, "anki": "1463082620879", "q": "During menopause, which of the following describes the expected changes in FSH, LH, and GnRH levels?", "o": {"A": "Decreased FSH, LH, and GnRH", "B": "Increased FSH, LH, and GnRH", "C": "Increased FSH and LH with decreased GnRH", "D": "Decreased FSH and LH with increased GnRH"}, "r": "B", "e": {"correcta": "Menopause is associated with increased FSH, LH, and GnRH accompanied by decreased estrogen, because declining ovarian follicular function reduces estrogen and inhibin production, removing negative feedback on the hypothalamic-pituitary axis. After menopause, estrone (produced peripherally) replaces estradiol as the predominant circulating estrogen.", "incorrectas": {"A": "Decreased levels of all three hormones would suggest a hypothalamic or pituitary cause of hypogonadism (central/secondary), which is the opposite of the physiology in menopause, where the primary defect is ovarian failure driving compensatory increases in these hormones.", "C": "GnRH does not decrease in menopause; because the entire hypothalamic-pituitary-ovarian axis loses its negative feedback signal (estrogen/inhibin) from the failing ovaries, all three upstream hormones (GnRH, FSH, LH) increase together.", "D": "This pattern of decreased FSH/LH and increased GnRH does not reflect physiologic feedback logic in menopause, since a rise in GnRH would be expected to increase, not decrease, downstream FSH and LH secretion."}}}, {"id": "anking-reproductive-system-physiology-2052", "fuente": "anking", "tema": 32, "anki": "1463082697879", "q": "A 32-year-old woman presents with amenorrhea and hot flashes. Workup reveals menopausal-range FSH and LH. Menopause occurring before what age suggests primary ovarian insufficiency?", "o": {"A": "Age 45", "B": "Age 50", "C": "Age 40", "D": "Age 35"}, "r": "C", "e": {"correcta": "Menopause occurring before age 40 suggests primary ovarian insufficiency (also known as premature ovarian failure), a condition in which the ovaries stop functioning normally before the typical age of menopause. It can occur in women who smoke or who have received chemotherapy or radiation therapy.", "incorrectas": {"A": "Age 45 is younger than the average age of natural menopause (around 51) but is not the specific cutoff used to define primary ovarian insufficiency, which requires onset before age 40.", "B": "Age 50 is close to the average age of natural menopause and would not be considered premature or suggestive of primary ovarian insufficiency.", "D": "Age 35, while it would also fall under the age-40 cutoff for primary ovarian insufficiency, is not the threshold age itself used to define the diagnosis; the clinically defined cutoff is age 40."}}}, {"id": "anking-reproductive-system-physiology-2053", "fuente": "anking", "tema": 32, "anki": "1463082787001", "q": "After menopause, the primary source of circulating estrogen shifts to peripheral conversion of which precursor?", "o": {"A": "Cholesterol", "B": "Progesterone", "C": "Androgens", "D": "Cortisol"}, "r": "C", "e": {"correcta": "After menopause, the ovaries dramatically reduce estrogen production, so circulating estrogen (mainly estrone) is derived from peripheral conversion of androgens, particularly in adipose tissue via the enzyme aromatase. The persistence of androgen production (with reduced estrogen counterbalance) can lead to relative hyperandrogenism and symptoms like hirsutism.", "incorrectas": {"B": "Progesterone is not a precursor of estrogen in this peripheral pathway; progesterone and estrogen are both downstream products of cholesterol-derived steroidogenesis but progesterone itself is not converted to estrogen post-menopause.", "A": "While cholesterol is the ultimate backbone for all steroid hormone synthesis, the specific peripheral conversion process referenced in menopause is aromatization of androgens (like androstenedione) to estrone in adipose tissue, not direct conversion from cholesterol.", "D": "Cortisol is a glucocorticoid produced by the adrenal cortex and is not converted into estrogen; it is unrelated to the aromatase-mediated peripheral estrogen production pathway active after menopause."}}}, {"id": "anking-reproductive-system-physiology-2054", "fuente": "anking", "tema": 32, "anki": "1463082815704", "q": "Menopause results from a decline in which hormone due to an age-related decrease in the number of ovarian follicles?", "o": {"A": "Progesterone", "B": "Inhibin", "C": "Estrogen", "D": "Testosterone"}, "r": "C", "e": {"correcta": "Menopause is due to decreased estrogen production resulting from an age-linked decline in the number of ovarian follicles. Estrogen deficiency also decreases glycogen production in the vaginal epithelium, leading to flattening of the labial folds and vaginal rugae, which contributes to vaginal dryness and dyspareunia.", "incorrectas": {"A": "Progesterone levels also decline in menopause since it is produced by the corpus luteum after ovulation, but the classic hormone whose decline is directly tied to the diminishing follicular pool and defines the core physiology of menopause is estrogen.", "B": "Inhibin, produced by granulosa cells, does decline as follicles are depleted, contributing to the loss of FSH suppression, but it is not the hormone whose decreased peripheral and systemic effects (vaginal atrophy, vasomotor symptoms) define the clinical syndrome of menopause the way estrogen does.", "D": "Testosterone is produced mainly by the adrenal glands and ovarian stroma in women and does not show the same dramatic decline as estrogen at menopause; relative androgen excess (from unopposed peripheral androgens) is actually a feature of the menopausal transition."}}}, {"id": "anking-reproductive-system-physiology-2055", "fuente": "anking", "tema": 32, "anki": "1463082847360", "q": "A 53-year-old woman with bothersome hot flashes and vaginal dryness related to menopause is considering treatment options. Which therapy may be used to minimize her menopausal symptoms?", "o": {"A": "GnRH agonist therapy", "B": "Estrogen/progesterone replacement therapy", "C": "Selective estrogen receptor degrader therapy", "D": "Androgen replacement therapy"}, "r": "B", "e": {"correcta": "Estrogen/progesterone replacement therapy can be used to minimize the symptoms of menopause, such as hot flashes, vaginal atrophy, and mood changes, by supplementing the declining endogenous hormone levels. Progesterone is added in women with an intact uterus to protect against estrogen-induced endometrial hyperplasia.", "incorrectas": {"A": "GnRH agonists, when given continuously, actually suppress the hypothalamic-pituitary-gonadal axis and induce a hypoestrogenic state (used to treat conditions like fibroids or endometriosis), which would worsen rather than relieve menopausal symptoms.", "C": "Selective estrogen receptor degraders (like fulvestrant) block or downregulate estrogen receptors and are used in the treatment of estrogen receptor-positive breast cancer, not to relieve menopausal symptoms, which require estrogen supplementation rather than blockade.", "D": "Androgen replacement therapy is not the standard treatment for classic menopausal vasomotor and vaginal symptoms; estrogen (with progesterone) replacement directly addresses the underlying hormone deficiency responsible for these symptoms."}}}, {"id": "anking-reproductive-system-physiology-2056", "fuente": "anking", "tema": 32, "anki": "1463082863765", "q": "Menopausal symptoms tend to be less severe in obese women. What is the physiologic explanation for this observation?", "o": {"A": "Increased levels of estrogen from peripheral aromatization in adipose tissue", "B": "Increased levels of progesterone from adrenal tissue", "C": "Decreased FSH secretion due to leptin resistance", "D": "Increased testosterone clearance in adipose tissue"}, "r": "A", "e": {"correcta": "Menopause is less symptomatic in obese women because adipose tissue contains aromatase, which converts adrenal and ovarian androgens into estrogen (mainly estrone) peripherally. The additional estrogen produced from this larger fat mass partially compensates for the loss of ovarian estrogen production, softening the severity of vasomotor and other menopausal symptoms.", "incorrectas": {"B": "Progesterone is not the hormone responsible for buffering menopausal symptoms in obese women; adipose tissue is not a significant source of progesterone production, and progesterone levels decline in menopause regardless of body habitus.", "C": "While leptin levels are altered in obesity, the mechanism explaining reduced menopausal symptom severity is peripheral estrogen production via aromatization in fat tissue, not a leptin-mediated reduction in FSH secretion.", "D": "Increased testosterone clearance is not the explanation here; rather, adipose tissue converts androgens into estrogen via aromatase, increasing estrogen levels rather than simply clearing testosterone."}}}, {"id": "anking-reproductive-system-physiology-2057", "fuente": "anking", "tema": 32, "anki": "1463083035387", "q": "A woman in her late 40s begins experiencing irregular menstrual cycles that persist for several years before her periods stop entirely. What is this transitional period, typically preceding the final menstrual period by 4-5 years, called?", "o": {"A": "Perimenopause (leading to menopause)", "B": "Anovulatory cycle syndrome", "C": "Premature ovarian failure", "D": "Luteal phase defect"}, "r": "A", "e": {"correcta": "Menopause is usually preceded by 4-5 years of abnormal, irregular menstrual cycles, a transitional phase commonly referred to as perimenopause, during which fluctuating hormone levels cause unpredictable cycle length and flow before menstruation ceases entirely (average onset of menopause is 51 years).", "incorrectas": {"B": "Anovulatory cycle syndrome is not the standard term for this transition; while anovulatory cycles do increase in frequency as menopause approaches, the broader clinical term for this multi-year transitional phase is perimenopause.", "C": "Premature ovarian failure (primary ovarian insufficiency) refers to menopause occurring before age 40, a distinct and abnormal early process, not the typical years of irregular cycling that precede menopause at the normal average age.", "D": "Luteal phase defect refers to inadequate progesterone production or a shortened luteal phase, which can cause infertility or early miscarriage, and is not the term describing the years of irregular cycling preceding menopause."}}}, {"id": "anking-reproductive-system-physiology-2058", "fuente": "anking", "tema": 32, "anki": "1463083069015", "q": "What is the minimum duration of amenorrhea required to make the clinical diagnosis of menopause?", "o": {"A": "3 months", "B": "12 months", "C": "6 months", "D": "24 months"}, "r": "B", "e": {"correcta": "Menopause is diagnosed clinically by amenorrhea persisting for at least 12 consecutive months, in the absence of other causes, reflecting the permanent cessation of ovarian follicular activity and menstruation.", "incorrectas": {"A": "Three months of amenorrhea is too short a duration to meet the clinical criteria for menopause and could instead reflect other causes of secondary amenorrhea, such as pregnancy, stress, or a transient hormonal disturbance.", "C": "Six months of amenorrhea, while suggestive of an underlying process, still falls short of the 12-month threshold required for a formal diagnosis of menopause.", "D": "Twenty-four months is longer than the required diagnostic threshold; the standard clinical definition requires only 12 months of amenorrhea to confirm the diagnosis."}}}, {"id": "anking-reproductive-system-physiology-2059", "fuente": "anking", "tema": 32, "anki": "1463083081562", "q": "A pediatrician evaluates a teenager's pubertal development, scoring the genitalia, pubic hair, and breast tissue separately. What system is used to independently assess these three areas of sexual maturation?", "o": {"A": "Ballard scoring system", "B": "Tanner stages of sexual development", "C": "Bone age assessment", "D": "Denver developmental scale"}, "r": "B", "e": {"correcta": "The Tanner stages (also called the sexual maturity rating) assess pubertal development on a scale from I to V, and are assigned independently to genitalia, pubic hair, and breast development, since these characteristics may progress at different rates within the same individual.", "incorrectas": {"A": "The Ballard scoring system is used to estimate gestational age in newborns based on physical and neuromuscular maturity, a completely different clinical context from assessing pubertal development in adolescents.", "C": "Bone age assessment uses radiographs (commonly of the hand and wrist) to estimate skeletal maturity and is one tool that can correlate with pubertal timing, but it is not the system used to independently score genitalia, pubic hair, and breast development.", "D": "The Denver developmental scale assesses developmental milestones in young children (motor, language, social skills), and is unrelated to staging pubertal sexual maturation in adolescents."}}}, {"id": "anking-reproductive-system-physiology-2060", "fuente": "anking", "tema": 32, "anki": "1463083925825", "q": "A prepubertal child has no pubic hair and a flat chest on physical exam. Which Tanner stage does this describe?", "o": {"A": "Stage III", "B": "Stage II", "C": "Stage I", "D": "Stage IV"}, "r": "C", "e": {"correcta": "Tanner stage I represents the prepubertal, childhood state, characterized by no pubic hair and a flat chest (no breast development), before any signs of puberty have begun.", "incorrectas": {"B": "Tanner stage II marks the onset of puberty, with the appearance of pubic hair (pubarche), breast budding (thelarche) in females, and testicular enlargement in males, all findings that are absent in this prepubertal child.", "A": "Tanner stage III is characterized by coarsening of pubic hair and increasing penis size or breast enlargement, representing more advanced puberty than the complete absence of these features described here.", "D": "Tanner stage IV shows further increases in penis width/glans and breast enlargement with a raised areola, representing a much later pubertal stage than the flat chest and absent pubic hair in this prepubertal child."}}}, {"id": "anking-reproductive-system-physiology-2061", "fuente": "anking", "tema": 32, "anki": "1463084161585", "q": "A young adolescent boy is noted to have testicular enlargement along with early pubic hair growth, and a girl of similar age has breast budding along with early pubic hair growth. Which Tanner stage do these findings represent?", "o": {"A": "Stage I", "B": "Stage III", "C": "Stage II", "D": "Stage V"}, "r": "C", "e": {"correcta": "Tanner stage II marks the beginning of puberty, characterized by the appearance of pubic hair (pubarche), breast bud formation (thelarche) in females, and testicular enlargement in males, signaling the onset of gonadal hormone-driven changes.", "incorrectas": {"A": "Tanner stage I is the prepubertal stage with no pubic hair and a flat chest, which does not match the pubertal changes (testicular enlargement, breast budding, pubic hair) described in this case.", "B": "Tanner stage III involves coarsening of pubic hair with further increases in penis size and breast enlargement, representing more advanced changes than the initial pubertal signs (budding, early hair, testicular enlargement) described here.", "D": "Tanner stage V represents full adult development, with the penis and testes reaching adult size and areola flattening, far beyond the early pubertal changes described in this scenario."}}}, {"id": "anking-reproductive-system-physiology-2062", "fuente": "anking", "tema": 32, "anki": "1463084175199", "q": "An adolescent shows coarsening of pubic hair along with an increase in penis size, and a female adolescent of similar age shows coarsening pubic hair with breast enlargement. Which Tanner stage is this?", "o": {"A": "Stage II", "B": "Stage IV", "C": "Stage I", "D": "Stage III"}, "r": "D", "e": {"correcta": "Tanner stage III is characterized by coarsening of the pubic hair, an increase in penis size in males, and breast enlargement in females, representing an intermediate stage of pubertal progression beyond the initial changes of stage II.", "incorrectas": {"A": "Tanner stage II is the earlier stage marked by the initial appearance of pubic hair, breast budding, and testicular enlargement, preceding the coarsening of hair and further genital/breast growth seen in stage III.", "B": "Tanner stage IV involves further increases in penis width and glans development along with breast enlargement and a raised areola, representing a more advanced stage than the coarsening pubic hair and initial penis/breast growth described here.", "C": "Tanner stage I is the prepubertal stage with no pubic hair and a flat chest, which is inconsistent with the pubertal changes (coarsening hair, genital/breast growth) described in this scenario."}}}, {"id": "anking-reproductive-system-physiology-2063", "fuente": "anking", "tema": 32, "anki": "1463084186996", "q": "An adolescent male has increased penis width and glans development, and an adolescent female has breast enlargement with a raised areola forming a secondary mound. Which Tanner stage matches these findings?", "o": {"A": "Stage III", "B": "Stage V", "C": "Stage II", "D": "Stage IV"}, "r": "D", "e": {"correcta": "Tanner stage IV is characterized by an increase in penis width and glans development in males, along with breast enlargement and a raised areola forming a secondary mound in females, marking an advanced but not yet fully mature stage of puberty.", "incorrectas": {"A": "Tanner stage III involves coarsening pubic hair with increasing penis length and breast enlargement, but without the specific glans development and raised areola contour that distinguish stage IV.", "B": "Tanner stage V represents full adult maturity, where the penis and testes reach adult size and the areola flattens back into the contour of the breast, rather than remaining raised as a separate mound as in stage IV.", "C": "Tanner stage II is the earliest pubertal stage with initial pubic hair, breast budding, and testicular enlargement, far less developed than the glans and areolar changes described in this case."}}}, {"id": "anking-reproductive-system-physiology-2064", "fuente": "anking", "tema": 32, "anki": "1463084244802", "q": "A young adult has fully adult-sized penis and testes, with the areola now flattened into the contour of the breast. Which Tanner stage represents this adult development?", "o": {"A": "Stage IV", "B": "Stage III", "C": "Stage V", "D": "Stage II"}, "r": "C", "e": {"correcta": "Tanner stage V represents adulthood, the final stage of pubertal development, in which the penis and testes reach full adult size and the areola flattens back into the contour of the breast, indicating completion of puberty.", "incorrectas": {"A": "Tanner stage IV is an earlier, more transitional stage where the areola and papilla form a raised secondary mound above the breast contour and the genitalia are still developing toward, but have not yet reached, full adult size.", "B": "Tanner stage III shows coarsening pubic hair with increasing penis size and breast enlargement, well before the genitalia reach adult size and before the areola flattens, as seen in the fully mature stage V.", "D": "Tanner stage II is the earliest pubertal stage, characterized by initial pubic hair growth, breast budding, and testicular enlargement, far removed from the fully adult findings described in this case."}}}, {"id": "anking-reproductive-system-anatomy-2065", "fuente": "anking", "tema": 34, "anki": "1463089828836", "q": "Which anatomic term refers to the skin and mucosa of the female external genitalia located external to the hymen, including the labia majora, labia minora, mons pubis, and vestibule?", "o": {"A": "Vagina", "B": "Vulva", "C": "Cervix", "D": "Perineum"}, "r": "B", "e": {"correcta": "The vulva anatomically includes the skin and mucosa of the female genitalia external to the hymen, encompassing the labia majora, labia minora, mons pubis, and vestibule. This distinction is clinically important because it defines the region susceptible to vulvar-specific pathology such as lichen sclerosus and vulvar carcinoma.", "incorrectas": {"A": "The vagina is the internal muscular canal extending from the vestibule (external to the hymen) to the cervix, located internal to the hymen, distinct from the external vulvar structures.", "C": "The cervix is the lower, narrow portion of the uterus that opens into the vagina, an internal structure entirely separate from the external vulvar skin and mucosa.", "D": "The perineum is the broader region between the vulva/scrotum and the anus, including muscular and connective tissue support structures, and is a larger anatomic area that includes but is not limited to the vulva."}}}, {"id": "anking-reproductive-system-pathology-2066", "fuente": "anking", "tema": 8, "anki": "1463094303264", "q": "Vulvar carcinoma most commonly arises from which type of epithelium lining the vulva?", "o": {"A": "Transitional epithelium", "B": "Squamous epithelium", "C": "Columnar epithelium", "D": "Glandular epithelium"}, "r": "B", "e": {"correcta": "Vulvar carcinoma arises from the squamous epithelium lining the vulva, most commonly as a squamous cell carcinoma. It is a relatively rare tumor, accounting for only a small percentage of female genital cancers, and is often associated with HPV infection or chronic vulvar dermatoses like lichen sclerosus.", "incorrectas": {"A": "Transitional epithelium lines the urinary tract (bladder, ureters, proximal urethra) and is the tissue of origin for urothelial carcinoma, not vulvar carcinoma, which arises from squamous epithelium.", "C": "Columnar epithelium lines structures such as the endocervix and endometrium, giving rise to adenocarcinomas in those locations, rather than the squamous cell carcinomas typical of the vulva.", "D": "Glandular epithelium refers to secretory tissue found in organs like the breast or endometrium, giving rise to adenocarcinomas, which is a different tissue origin from the squamous epithelium of the vulva."}}}, {"id": "anking-reproductive-system-pathology-2067", "fuente": "anking", "tema": 8, "anki": "1463094312980", "q": "A 65-year-old woman presents with a white, thickened plaque on the vulva. Biopsy is required to distinguish vulvar carcinoma from which other benign condition that can also present as leukoplakia?", "o": {"A": "Bacterial vaginosis", "B": "Lichen sclerosus", "C": "Bartholin gland cyst", "D": "Condyloma acuminatum"}, "r": "B", "e": {"correcta": "Vulvar carcinoma classically presents as a leukoplakic (white, thickened) plaque, but this appearance is nonspecific and overlaps with benign conditions like lichen sclerosus and lichen simplex chronicus, so biopsy is required to distinguish true malignancy from these benign mimics.", "incorrectas": {"A": "Bacterial vaginosis causes a thin, malodorous vaginal discharge, not a vulvar white plaque, and is unrelated to the differential for leukoplakia-appearing lesions.", "C": "A Bartholin gland cyst presents as a fluctuant swelling near the vaginal introitus from duct obstruction, not as a whitish epithelial plaque requiring biopsy for carcinoma differentiation.", "D": "Condyloma acuminatum presents as a warty, papillary growth caused by low-risk HPV, which has a distinct gross appearance from the flat white plaque of leukoplakia."}}}, {"id": "anking-reproductive-system-pathology-2068", "fuente": "anking", "tema": 8, "anki": "1463094320615", "q": "Vulvar carcinoma can arise via two distinct pathways. Which of the following correctly represents these two pathways?", "o": {"A": "HPV-related and non-HPV-related (lichen sclerosus-associated)", "B": "BRCA1-related and BRCA2-related", "C": "Estrogen-dependent and estrogen-independent", "D": "Lynch syndrome-related and sporadic"}, "r": "A", "e": {"correcta": "Vulvar squamous cell carcinoma develops through two separate pathways: an HPV-related pathway (typically in younger women, via VIN) and a non-HPV-related pathway (typically in older women, arising from chronic lichen sclerosus). Recognizing these two distinct etiologies explains the differing demographics and precursor lesions.", "incorrectas": {"B": "BRCA1/BRCA2 mutations are classically associated with breast and ovarian cancer risk, not the two established etiologic pathways of vulvar carcinoma.", "C": "Estrogen dependence is a key concept in endometrial carcinoma (type I vs type II), not the mechanism distinguishing the two vulvar carcinoma pathways, which are defined by HPV status.", "D": "Lynch syndrome (HNPCC) increases risk for colorectal and endometrial cancer via mismatch repair defects, not vulvar carcinoma, which is not classically divided into Lynch-related and sporadic forms."}}}, {"id": "anking-reproductive-system-pathology-2069", "fuente": "anking", "tema": 8, "anki": "1463094343174", "q": "HPV-related vulvar carcinoma is most commonly caused by which high-risk HPV subtypes?", "o": {"A": "6 and 11", "B": "16 and 18", "C": "31 and 33", "D": "1 and 2"}, "r": "B", "e": {"correcta": "HPV types 16 and 18 are the high-risk oncogenic strains responsible for the majority of HPV-related vulvar carcinoma, as well as cervical and other anogenital carcinomas, via their E6 and E7 oncoproteins that inactivate p53 and Rb, respectively.", "incorrectas": {"A": "HPV types 6 and 11 are low-risk strains that cause condyloma acuminatum (genital warts) but are not the major drivers of malignant transformation in vulvar carcinoma.", "C": "HPV types 31 and 33 are also high-risk oncogenic strains capable of causing anogenital dysplasia and carcinoma, but they are far less commonly implicated than the predominant types 16 and 18.", "D": "HPV types 1 and 2 cause common cutaneous warts (verruca vulgaris) on the skin and hands, not anogenital malignancy."}}}, {"id": "anking-reproductive-system-pathology-2070", "fuente": "anking", "tema": 8, "anki": "1463094356469", "q": "HPV-related vulvar carcinoma is most commonly seen in which patient population?", "o": {"A": "Elderly women (average age >70 years)", "B": "Prepubertal girls", "C": "Women of reproductive age (<50 years old)", "D": "Postmenopausal women with diabetes"}, "r": "C", "e": {"correcta": "HPV-related vulvar carcinoma typically affects women of reproductive age (younger than 50), reflecting the timing of HPV acquisition through sexual activity and the progression through vulvar intraepithelial neoplasia (VIN) to invasive carcinoma over years to decades.", "incorrectas": {"B": "Prepubertal girls are not the typical population for either pathway of vulvar carcinoma; embryonal rhabdomyosarcoma (sarcoma botryoides) is the vaginal tumor characteristic of young children.", "A": "Elderly women (average age >70) are instead the classic population for non-HPV-related vulvar carcinoma, which arises from longstanding lichen sclerosus rather than HPV infection.", "D": "Postmenopausal women with diabetes is not a demographic classically linked to either vulvar carcinoma pathway; age and HPV/lichen sclerosus status are the relevant risk stratifiers, not diabetic status."}}}, {"id": "anking-reproductive-system-pathology-2071", "fuente": "anking", "tema": 8, "anki": "1463094362852", "q": "HPV-related vulvar carcinoma arises from a dysplastic precursor lesion characterized by koilocytic change, disordered maturation, and nuclear atypia. What is this precursor lesion called?", "o": {"A": "Cervical intraepithelial neoplasia (CIN)", "B": "Vulvar intraepithelial neoplasia (VIN)", "C": "Endometrial intraepithelial neoplasia (EIN)", "D": "Vaginal intraepithelial neoplasia (VAIN)"}, "r": "B", "e": {"correcta": "Vulvar intraepithelial neoplasia (VIN) is the precursor dysplastic lesion for HPV-related vulvar carcinoma, showing koilocytic atypia, disordered cellular maturation, nuclear atypia, and increased mitoses, analogous to CIN in the cervix but located on the vulva.", "incorrectas": {"A": "CIN is the analogous precursor lesion for cervical squamous cell carcinoma, located in the cervical transformation zone, not the vulva.", "C": "EIN is a precursor to endometrial (type I, endometrioid) carcinoma arising from unopposed estrogen exposure, an entirely different site and mechanism from vulvar carcinoma.", "D": "VAIN is the vaginal counterpart precursor lesion, associated with vaginal squamous cell carcinoma, not vulvar carcinoma."}}}, {"id": "anking-reproductive-system-pathology-2072", "fuente": "anking", "tema": 8, "anki": "1463094374637", "q": "Non-HPV-related vulvar carcinoma most often arises from long-standing chronic inflammation due to which condition?", "o": {"A": "Lichen planus", "B": "Lichen sclerosus", "C": "Psoriasis", "D": "Contact dermatitis"}, "r": "B", "e": {"correcta": "Non-HPV-related vulvar carcinoma classically develops from chronic lichen sclerosus, a condition of dermal thinning and fibrosis where longstanding inflammation and irritation eventually predispose to malignant transformation, typically in elderly women.", "incorrectas": {"A": "Lichen planus can affect the vulva with violaceous, pruritic papules, but it is not the classically described precursor to non-HPV vulvar carcinoma in this pathway.", "C": "Psoriasis can rarely involve the vulva with erythematous plaques, but it is not the recognized chronic inflammatory precursor linked to non-HPV vulvar carcinoma.", "D": "Contact dermatitis causes acute to subacute inflammatory skin reactions from irritants or allergens but is not associated with long-term malignant transformation in the vulva the way lichen sclerosus is."}}}, {"id": "anking-reproductive-system-pathology-2073", "fuente": "anking", "tema": 8, "anki": "1463094387931", "q": "Non-HPV-related vulvar carcinoma is most commonly seen in which patient population?", "o": {"A": "Women of reproductive age (<50 years old)", "B": "Adolescent girls", "C": "Elderly women (average age >70 years)", "D": "Pregnant women"}, "r": "C", "e": {"correcta": "Non-HPV-related vulvar carcinoma typically occurs in elderly women, with an average age greater than 70 years, reflecting its origin from decades of chronic lichen sclerosus-related inflammation rather than sexually transmitted HPV infection.", "incorrectas": {"A": "Women of reproductive age (<50) are instead characteristic of the HPV-related pathway, which develops through VIN following HPV 16/18 infection acquired through sexual activity.", "B": "Adolescent girls are not a typical population for either vulvar carcinoma pathway; pediatric vaginal tumors like sarcoma botryoides occur in much younger girls (<4 years).", "D": "Pregnancy is not a recognized risk factor or demographic association for non-HPV-related vulvar carcinoma, which is driven by chronic dermatologic inflammation in older age."}}}, {"id": "anking-reproductive-system-pathology-2074", "fuente": "anking", "tema": 8, "anki": "1463094420020", "q": "Paget disease of the vulva (and nipple) classically presents with which type of skin lesion?", "o": {"A": "Vesicular, non-pruritic rash", "B": "Erythematous, pruritic, ulcerated skin", "C": "Hyperpigmented, painless macule", "D": "Hypopigmented, scaly patch"}, "r": "B", "e": {"correcta": "Paget disease of the vulva or nipple presents as erythematous, pruritic, and ulcerated skin due to malignant epithelial (Paget) cells infiltrating the epidermis, mimicking eczema clinically but requiring biopsy to confirm the underlying neoplastic process.", "incorrectas": {"A": "A vesicular, non-pruritic rash is more suggestive of a viral or bullous dermatologic process (e.g., herpes), not the classic eczematous, itchy appearance of Paget disease.", "C": "A hyperpigmented, painless macule would raise concern for melanoma or a benign pigmented lesion, which is part of the differential to exclude, but not the described presentation of Paget disease itself.", "D": "A hypopigmented, scaly patch is more typical of a condition like vitiligo or certain lichenoid dermatoses, not the erythematous and pruritic picture of Paget disease."}}}, {"id": "anking-reproductive-system-pathology-2075", "fuente": "anking", "tema": 8, "anki": "1463094440828", "q": "Extramammary Paget disease of the vulva most often presents with or without an underlying invasive carcinoma?", "o": {"A": "Almost always with an underlying carcinoma", "B": "Without an underlying carcinoma", "C": "Only in postmenopausal women", "D": "Only when HPV co-infection is present"}, "r": "B", "e": {"correcta": "Unlike Paget disease of the nipple, extramammary Paget disease of the vulva usually occurs without an underlying invasive carcinoma; it typically represents an intraepithelial (in situ) neoplastic process confined to the epidermis rather than a marker of an underlying ductal malignancy.", "incorrectas": {"A": "This describes Paget disease of the nipple, which is almost always associated with an underlying ductal carcinoma of the breast — the opposite relationship seen in the vulvar (extramammary) form.", "C": "Menopausal status is not the key distinguishing factor determining whether an underlying carcinoma is present; the key distinction is the anatomic site (breast vs. extramammary), not hormonal status.", "D": "HPV status is not relevant to extramammary Paget disease, which arises from apocrine gland-associated epidermal cells rather than HPV-driven squamous dysplasia."}}}, {"id": "anking-reproductive-system-pathology-2076", "fuente": "anking", "tema": 8, "anki": "1463094447234", "q": "In contrast to the extramammary form, Paget disease of the nipple most often presents with or without an underlying carcinoma?", "o": {"A": "With an underlying carcinoma (usually ductal carcinoma)", "B": "Without any underlying carcinoma", "C": "Only after prior radiation exposure", "D": "Only in BRCA-negative patients"}, "r": "A", "e": {"correcta": "Paget disease of the nipple almost always signals an underlying invasive or in situ ductal carcinoma of the breast, since malignant ductal cells migrate along the lactiferous ducts into the epidermis of the nipple, producing the characteristic eczematous, erythematous change.", "incorrectas": {"B": "This describes the extramammary (vulvar) form of Paget disease, which typically lacks an associated underlying carcinoma, unlike the nipple form.", "C": "Prior radiation is not a prerequisite for nipple Paget disease; the condition arises from spread of ductal carcinoma cells, independent of radiation history.", "D": "BRCA status is not the determining factor for whether Paget disease of the nipple is associated with underlying carcinoma; nearly all cases have an associated ductal malignancy regardless of BRCA status."}}}, {"id": "anking-reproductive-system-pathology-2077", "fuente": "anking", "tema": 8, "anki": "1463094451459", "q": "Extramammary Paget disease of the vulva must be distinguished histologically from which other pigmented or infiltrative lesion that can rarely occur on the vulva?", "o": {"A": "Squamous cell carcinoma in situ", "B": "Melanoma", "C": "Basal cell carcinoma", "D": "Condyloma lata"}, "r": "B", "e": {"correcta": "Melanoma can rarely arise on the vulva and, like extramammary Paget disease, can show pagetoid spread of atypical cells within the epidermis, making the two difficult to distinguish on routine histology alone; immunohistochemistry is required to differentiate them.", "incorrectas": {"A": "Squamous cell carcinoma in situ (VIN) is HPV-related and shows koilocytic, dysplastic squamous cells rather than the large, pale, mucin-containing Paget cells, making it a less classic diagnostic dilemma than melanoma.", "C": "Basal cell carcinoma has a distinct histologic appearance (nests of basaloid cells with peripheral palisading) and is not the classic mimicker requiring IHC differentiation from Paget disease.", "D": "Condyloma lata is a manifestation of secondary syphilis, presenting as flat, wart-like lesions, and is not part of the classic histologic differential for Paget disease."}}}, {"id": "anking-reproductive-system-pathology-2078", "fuente": "anking", "tema": 8, "anki": "1463094456899", "q": "On immunohistochemistry, extramammary Paget disease of the vulva (compared to melanoma) is classically characterized by which staining pattern?", "o": {"A": "PAS negative, keratin negative, S100 positive", "B": "PAS positive, keratin positive, S100 negative", "C": "PAS negative, keratin positive, S100 positive", "D": "PAS positive, keratin negative, S100 positive"}, "r": "B", "e": {"correcta": "Extramammary Paget disease is PAS-positive (reflecting intracellular mucin production, since Paget cells arise from glandular/apocrine epithelium), keratin-positive (confirming epithelial/carcinoma origin), and S100-negative, distinguishing it from melanoma, which is S100-positive and PAS/keratin-negative.", "incorrectas": {"A": "This pattern (S100-positive, keratin-negative) actually describes melanoma, which arises from neural crest-derived melanocytes, not the epithelial-derived Paget cells.", "C": "PAS-negative, keratin-positive, S100-positive is an internally inconsistent combination not classically used to differentiate these two entities; melanoma should be keratin-negative since it is not of epithelial origin.", "D": "PAS-positive, keratin-negative, S100-positive is also inconsistent, as Paget disease (with PAS positivity from mucin) is epithelial in origin and should stain keratin-positive, not negative."}}}, {"id": "anking-reproductive-system-pathology-2079", "fuente": "anking", "tema": 8, "anki": "1463094486788", "q": "Which immunohistochemical staining pattern helps confirm a diagnosis of vulvar melanoma over extramammary Paget disease?", "o": {"A": "PAS positive, keratin positive, S100 negative", "B": "PAS negative, keratin negative, S100 positive", "C": "PAS positive, keratin negative, S100 negative", "D": "PAS negative, keratin positive, S100 positive"}, "r": "B", "e": {"correcta": "Melanoma is PAS-negative and keratin-negative (since melanocytes are not epithelial and do not produce the mucin detected by PAS) but S100-positive (a marker of neural crest-derived cells including melanocytes), the inverse of the profile seen in extramammary Paget disease.", "incorrectas": {"A": "This profile (PAS+, keratin+, S100−) describes extramammary Paget disease, reflecting its epithelial, mucin-producing origin, not melanoma.", "C": "PAS-positive with keratin- and S100-negative is not a recognized pattern for either entity; melanoma should be S100-positive given its melanocytic origin.", "D": "Keratin-positive with S100-positive would suggest an unusual mixed or aberrant staining pattern; melanoma is classically keratin-negative because it lacks epithelial differentiation."}}}, {"id": "anking-reproductive-system-pathology-2080", "fuente": "anking", "tema": 8, "anki": "1463098751199", "q": "The mucosa of the vagina is normally lined by which type of epithelium?", "o": {"A": "Simple columnar epithelium", "B": "Transitional epithelium", "C": "Non-keratinized stratified squamous epithelium", "D": "Keratinized stratified squamous epithelium"}, "r": "C", "e": {"correcta": "The vaginal mucosa is lined by non-keratinized stratified squamous epithelium, which provides a durable, moist barrier suited to the mechanical stresses of intercourse and childbirth while remaining pliable, unlike the keratinized squamous epithelium of the external skin.", "incorrectas": {"A": "Simple columnar epithelium lines the endocervix and is the fetal epithelium of the upper third of the vagina before squamous metaplasia occurs, but it is not the normal adult vaginal mucosal lining.", "B": "Transitional epithelium lines the urinary tract (bladder, ureters, proximal urethra) to accommodate distention, not the vagina.", "D": "Keratinized stratified squamous epithelium lines the external skin (e.g., vulva, labia majora) where a hardened surface barrier is needed, unlike the moist vaginal canal which remains non-keratinized."}}}, {"id": "anking-reproductive-system-embryology-2081", "fuente": "anking", "tema": 33, "anki": "1463101150767", "q": "The lower (distal) two-thirds of the vaginal canal is derived embryologically from which structure?", "o": {"A": "Paramesonephric (Müllerian) duct", "B": "Mesonephric (Wolffian) duct", "C": "Urogenital sinus", "D": "Genital tubercle"}, "r": "C", "e": {"correcta": "The lower two-thirds of the vagina arises from the urogenital sinus, which is lined initially by endodermally-derived epithelium that later undergoes squamous metaplasia to match the upper vagina, forming a continuous squamous-lined canal.", "incorrectas": {"A": "The paramesonephric (Müllerian) duct gives rise to the upper third of the vagina, as well as the fallopian tubes, uterus, and cervix, not the lower two-thirds.", "B": "The mesonephric (Wolffian) duct regresses in females (persisting only as vestigial remnants like Gartner duct cysts) and does not contribute to vaginal formation.", "D": "The genital tubercle gives rise to the glans clitoris (in females) or glans penis (in males), not the vaginal canal."}}}, {"id": "anking-reproductive-system-embryology-2082", "fuente": "anking", "tema": 33, "anki": "1463101154172", "q": "The normal fetal epithelium of the lower two-thirds of the vaginal canal, derived from the urogenital sinus, is which histologic type?", "o": {"A": "Columnar epithelium", "B": "Squamous epithelium", "C": "Transitional epithelium", "D": "Cuboidal epithelium"}, "r": "B", "e": {"correcta": "The urogenital sinus-derived lower two-thirds of the vagina is normally lined by squamous epithelium in the fetus, consistent with its origin and matching the epithelium that will ultimately extend to replace the columnar epithelium of the upper vagina.", "incorrectas": {"A": "Columnar epithelium is the fetal epithelium of the upper third of the vagina (Müllerian duct-derived), not the urogenital sinus-derived lower two-thirds.", "C": "Transitional epithelium characterizes the urinary tract lining, not the vaginal canal at any level.", "D": "Cuboidal epithelium is not the histologic descriptor used for either segment of the fetal vaginal epithelium; the relevant distinction is squamous (lower) versus columnar (upper)."}}}, {"id": "anking-reproductive-system-embryology-2083", "fuente": "anking", "tema": 33, "anki": "1463101157627", "q": "The upper (proximal) one-third of the vaginal canal is derived embryologically from which structure?", "o": {"A": "Urogenital sinus", "B": "Müllerian (paramesonephric) duct", "C": "Wolffian (mesonephric) duct", "D": "Cloaca"}, "r": "B", "e": {"correcta": "The upper third of the vagina originates from the caudal end of the fused Müllerian (paramesonephric) ducts, the same structures that give rise to the uterus, cervix, and fallopian tubes, explaining its initial columnar epithelial lining.", "incorrectas": {"A": "The urogenital sinus gives rise to the lower two-thirds of the vagina, not the upper third, and is lined by squamous epithelium rather than columnar.", "C": "The Wolffian (mesonephric) duct is the male-differentiating duct system that regresses in females, contributing only vestigial structures, not the vagina.", "D": "The cloaca is an earlier embryonic structure that partitions into the urogenital sinus and anorectal canal; it is not itself the direct precursor of the upper vagina."}}}, {"id": "anking-reproductive-system-embryology-2084", "fuente": "anking", "tema": 33, "anki": "1463101160605", "q": "The normal fetal epithelium of the upper one-third of the vaginal canal, derived from the Müllerian duct, is which histologic type?", "o": {"A": "Non-keratinized stratified squamous epithelium", "B": "Keratinized stratified squamous epithelium", "C": "Columnar epithelium", "D": "Transitional epithelium"}, "r": "C", "e": {"correcta": "The Müllerian duct-derived upper third of the fetal vagina is lined by columnar epithelium; persistence of this columnar epithelium into adulthood (rather than normal squamous replacement) is termed vaginal adenosis, classically associated with in utero DES exposure.", "incorrectas": {"A": "Non-keratinized stratified squamous epithelium is the mature adult epithelium of the entire vagina after squamous epithelium from the lower two-thirds grows upward to replace the fetal columnar epithelium.", "B": "Keratinized stratified squamous epithelium lines external skin surfaces, not the vaginal canal at any developmental stage.", "D": "Transitional epithelium lines the urinary tract, not any portion of the vaginal canal."}}}, {"id": "anking-reproductive-system-embryology-2085", "fuente": "anking", "tema": 33, "anki": "1463101164043", "q": "During normal vaginal development, squamous epithelium from the lower two-thirds of the vagina grows upward to replace which fetal epithelium in the upper third?", "o": {"A": "Transitional epithelium", "B": "Columnar epithelium", "C": "Keratinized squamous epithelium", "D": "Pseudostratified ciliated columnar epithelium"}, "r": "B", "e": {"correcta": "Squamous epithelium derived from the urogenital sinus grows cranially during development to replace the Müllerian duct-derived columnar epithelium of the upper vagina, resulting in a uniformly non-keratinized stratified squamous-lined vaginal canal at birth.", "incorrectas": {"A": "Transitional epithelium is never present in the vagina; it is confined to the urinary tract and is not part of this replacement process.", "C": "Keratinized squamous epithelium is the epithelium of external skin, not a normal component of vaginal development; the vagina remains non-keratinized.", "D": "Pseudostratified ciliated columnar epithelium lines structures like the fallopian tubes and respiratory tract, not the upper vagina, which has simple columnar epithelium prior to replacement."}}}, {"id": "anking-reproductive-system-pathology-2086", "fuente": "anking", "tema": 8, "anki": "1463101179451", "q": "Vaginal adenosis (persistence of columnar epithelium in the vagina), often associated with in utero diethylstilbestrol exposure, increases the risk of which malignancy?", "o": {"A": "Squamous cell carcinoma", "B": "Clear cell adenocarcinoma", "C": "Embryonal rhabdomyosarcoma", "D": "Choriocarcinoma"}, "r": "B", "e": {"correcta": "Vaginal adenosis, especially when related to in utero DES exposure, increases the risk of clear cell adenocarcinoma of the vagina, a rare malignant proliferation of glands with clear cytoplasm arising from the persistent columnar (glandular) epithelium.", "incorrectas": {"A": "Squamous cell carcinoma of the vagina is instead linked to HPV infection and VAIN, arising from the squamous epithelium, not from the glandular columnar epithelium of adenosis.", "C": "Embryonal rhabdomyosarcoma (sarcoma botryoides) is a pediatric vaginal tumor of skeletal muscle origin occurring in girls under 4, unrelated to DES exposure or adenosis.", "D": "Choriocarcinoma is a gestational trophoblastic malignancy arising from trophoblastic tissue, unrelated to vaginal columnar epithelium or DES exposure."}}}, {"id": "anking-reproductive-system-pathology-2087", "fuente": "anking", "tema": 8, "anki": "1463101187418", "q": "A rare vaginal malignancy linked to in utero diethylstilbestrol exposure is characterized by malignant glands with clear cytoplasm. What is this tumor called?", "o": {"A": "Clear cell adenocarcinoma", "B": "Sarcoma botryoides", "C": "Squamous cell carcinoma", "D": "Endometrioid adenocarcinoma"}, "r": "A", "e": {"correcta": "Clear cell adenocarcinoma is a rare complication of DES-associated vaginal adenosis, representing malignant proliferation of glandular cells with clear cytoplasm (from glycogen accumulation); its discovery, along with associated uterine anomalies, led to discontinuation of DES use in pregnancy.", "incorrectas": {"B": "Sarcoma botryoides is a pediatric embryonal rhabdomyosarcoma of the vagina/cervix in young girls, a mesenchymal (skeletal muscle) tumor unrelated to DES or glandular clear cell change.", "C": "Squamous cell carcinoma of the vagina arises from the squamous epithelium (often via HPV and VAIN), not from glandular clear cells, and is not the DES-associated tumor described.", "D": "Endometrioid adenocarcinoma is the most common type of endometrial (uterine) cancer, related to unopposed estrogen exposure, not a vaginal tumor linked to DES-induced adenosis."}}}, {"id": "anking-reproductive-system-pathology-2088", "fuente": "anking", "tema": 8, "anki": "1463101200000", "q": "Sarcoma botryoides (embryonal rhabdomyosarcoma) is a rare malignant mesenchymal proliferation of immature cells of which lineage?", "o": {"A": "Smooth muscle", "B": "Skeletal muscle", "C": "Cardiac muscle", "D": "Endothelial cells"}, "r": "B", "e": {"correcta": "Sarcoma botryoides is an embryonal rhabdomyosarcoma composed of immature skeletal muscle cells (rhabdomyoblasts), classically presenting as a grape-like cluster of tissue protruding from the vagina or cervix in young children.", "incorrectas": {"A": "Smooth muscle tumors of the female genital tract include leiomyoma and leiomyosarcoma, which arise in the myometrium rather than presenting as the grape-like vaginal mass of sarcoma botryoides.", "C": "Cardiac muscle tumors, such as rhabdomyoma, occur within the heart (notably associated with tuberous sclerosis) and are unrelated to vaginal or cervical mesenchymal proliferations.", "D": "Endothelial cell tumors, such as angiosarcoma, arise from vascular lining cells, a different cell lineage than the skeletal muscle origin of sarcoma botryoides."}}}, {"id": "anking-reproductive-system-pathology-2089", "fuente": "anking", "tema": 8, "anki": "1463101220961", "q": "Embryonal rhabdomyosarcoma (sarcoma botryoides) is most commonly seen in which patient population?", "o": {"A": "Adolescent boys", "B": "Postmenopausal women", "C": "Girls under 4 years old", "D": "Women of reproductive age"}, "r": "C", "e": {"correcta": "Sarcoma botryoides classically occurs in girls under 4 years of age, presenting as a grape-like mass protruding from the vagina, reflecting its origin from immature skeletal muscle precursor cells present during early childhood development.", "incorrectas": {"A": "Adolescent boys are not the population for this tumor, as it specifically arises in the vagina/cervix, structures unique to the female reproductive tract.", "B": "Postmenopausal women are instead the classic population for non-HPV-related vulvar carcinoma, a distinct entity with a completely different cell of origin (squamous epithelium versus rhabdomyoblasts).", "D": "Women of reproductive age are the typical population for HPV-related vulvar or cervical carcinoma, not sarcoma botryoides, which is a pediatric tumor of very young girls."}}}, {"id": "anking-reproductive-system-pathology-2090", "fuente": "anking", "tema": 8, "anki": "1463101224904", "q": "What is the malignant cell type that characterizes embryonal rhabdomyosarcoma?", "o": {"A": "Rhabdomyoblast", "B": "Osteoblast", "C": "Chondroblast", "D": "Lipoblast"}, "r": "A", "e": {"correcta": "The rhabdomyoblast, an immature skeletal muscle precursor cell, is the malignant cell type in embryonal rhabdomyosarcoma; these cells are spindle-shaped and can show cytoplasmic cross-striations reflecting nascent myofilament formation.", "incorrectas": {"B": "Osteoblasts are bone-forming cells characteristic of osteosarcoma, a bone malignancy, not the vaginal/cervical rhabdomyosarcoma described here.", "C": "Chondroblasts are cartilage-forming cells associated with chondrosarcoma, unrelated to the skeletal muscle lineage of rhabdomyosarcoma.", "D": "Lipoblasts are immature fat cells found in liposarcoma, a soft tissue tumor of adipocytic lineage rather than skeletal muscle lineage."}}}, {"id": "anking-reproductive-system-pathology-2091", "fuente": "anking", "tema": 8, "anki": "1463101228831", "q": "Rhabdomyoblasts, the malignant cells of embryonal rhabdomyosarcoma, are spindle-shaped cells that sometimes exhibit which characteristic cytoplasmic feature?", "o": {"A": "Birbeck granules", "B": "Cross-striations", "C": "Psammoma bodies", "D": "Russell bodies"}, "r": "B", "e": {"correcta": "Rhabdomyoblasts can show cytoplasmic cross-striations, corresponding to the organized sarcomeric actin-myosin filaments of developing skeletal muscle, a helpful histologic clue supporting the diagnosis of rhabdomyosarcoma.", "incorrectas": {"A": "Birbeck granules are tennis-racket-shaped intracytoplasmic organelles seen in Langerhans cells, characteristic of Langerhans cell histiocytosis, not rhabdomyoblasts.", "C": "Psammoma bodies are laminated, concentric calcifications seen in tumors like papillary thyroid carcinoma, meningioma, and serous ovarian carcinoma, not in rhabdomyosarcoma.", "D": "Russell bodies are eosinophilic inclusions of accumulated immunoglobulin found in plasma cells, unrelated to muscle differentiation or rhabdomyosarcoma."}}}, {"id": "anking-reproductive-system-pathology-2092", "fuente": "anking", "tema": 8, "anki": "1463101246153", "q": "Rhabdomyoblasts in embryonal rhabdomyosarcoma characteristically stain positive on immunohistochemistry for desmin and which transcription factor marker of immature muscle cells?", "o": {"A": "Myogenin", "B": "GATA3", "C": "TTF-1", "D": "Chromogranin"}, "r": "A", "e": {"correcta": "Myogenin is a transcription factor expressed in immature skeletal muscle cells and, together with desmin (a muscle intermediate filament), serves as a key immunohistochemical marker confirming rhabdomyoblast differentiation in rhabdomyosarcoma.", "incorrectas": {"B": "GATA3 is a transcription factor marker used in the diagnosis of breast and urothelial carcinomas, not a marker of skeletal muscle differentiation.", "C": "TTF-1 (thyroid transcription factor-1) marks cells of thyroid and lung (particularly adenocarcinoma) origin, unrelated to muscle lineage markers.", "D": "Chromogranin is a marker of neuroendocrine differentiation, used in tumors like carcinoid and pheochromocytoma, not in skeletal muscle-derived tumors."}}}, {"id": "anking-reproductive-system-pathology-2093", "fuente": "anking", "tema": 8, "anki": "1463101266778", "q": "Vaginal carcinoma most commonly arises from which epithelium lining the vaginal mucosa?", "o": {"A": "Simple columnar epithelium", "B": "Transitional epithelium", "C": "Stratified squamous epithelium", "D": "Pseudostratified columnar epithelium"}, "r": "C", "e": {"correcta": "Primary vaginal carcinoma (a rare tumor) most commonly arises as squamous cell carcinoma from the stratified squamous epithelium that normally lines the vaginal mucosa, typically preceded by vaginal intraepithelial neoplasia (VAIN) related to HPV infection.", "incorrectas": {"A": "Simple columnar epithelium is the fetal lining of the upper vagina (persisting abnormally in adenosis) and gives rise to clear cell adenocarcinoma rather than the more common squamous cell carcinoma.", "B": "Transitional epithelium lines the urinary tract, not the vagina, and is not the origin of vaginal carcinoma.", "D": "Pseudostratified columnar epithelium is found in structures like the respiratory tract and is not part of the vaginal lining."}}}, {"id": "anking-reproductive-system-pathology-2094", "fuente": "anking", "tema": 8, "anki": "1463101295333", "q": "Vaginal squamous cell carcinoma is usually related to infection with which pathogen?", "o": {"A": "Herpes simplex virus", "B": "High-risk HPV strains", "C": "Chlamydia trachomatis", "D": "Treponema pallidum"}, "r": "B", "e": {"correcta": "Vaginal squamous cell carcinoma is usually related to infection with high-risk HPV strains (such as HPV 16 and 18), which drive dysplastic changes through vaginal intraepithelial neoplasia (VAIN) that can progress to invasive carcinoma, mirroring the pathogenesis seen in cervical cancer.", "incorrectas": {"A": "Herpes simplex virus causes painful genital ulcers and vesicular lesions but is not the oncogenic driver of vaginal squamous cell carcinoma.", "C": "Chlamydia trachomatis is a common cause of pelvic inflammatory disease and cervicitis but is not linked to malignant transformation of vaginal epithelium.", "D": "Treponema pallidum causes syphilis, which can produce genital ulcers (chancre) or condyloma lata, but it is not associated with vaginal carcinogenesis."}}}, {"id": "anking-reproductive-system-pathology-2095", "fuente": "anking", "tema": 8, "anki": "1463101300781", "q": "What is the precursor lesion of vaginal squamous cell carcinoma?", "o": {"A": "Cervical intraepithelial neoplasia (CIN)", "B": "Vulvar intraepithelial neoplasia (VIN)", "C": "Vaginal intraepithelial neoplasia (VAIN)", "D": "Endometrial hyperplasia"}, "r": "C", "e": {"correcta": "Vaginal intraepithelial neoplasia (VAIN) is the dysplastic precursor lesion to vaginal squamous cell carcinoma, analogous to CIN in the cervix and VIN in the vulva, and is driven by high-risk HPV infection of the vaginal squamous epithelium.", "incorrectas": {"A": "CIN is the precursor lesion specific to cervical squamous cell carcinoma, located in the transformation zone of the cervix, not the vaginal mucosa.", "B": "VIN is the precursor lesion specific to vulvar squamous cell carcinoma, a different anatomic site than the vagina.", "D": "Endometrial hyperplasia is a precursor to endometrial (endometrioid) adenocarcinoma driven by unopposed estrogen, unrelated to squamous dysplasia of the vagina."}}}, {"id": "anking-reproductive-system-pathology-2096", "fuente": "anking", "tema": 8, "anki": "1463101305391", "q": "Vaginal squamous cell carcinoma is usually secondary to squamous cell carcinoma originating in which adjacent structure?", "o": {"A": "Vulva", "B": "Cervix", "C": "Bladder", "D": "Rectum"}, "r": "B", "e": {"correcta": "Vaginal squamous cell carcinoma is usually secondary to cervical squamous cell carcinoma extending or metastasizing into the vagina, since primary vaginal carcinoma is rare and the cervix is the much more common site of origin for HPV-driven squamous malignancy in this region.", "incorrectas": {"A": "Vulvar carcinoma is a distinct primary tumor of the vulva; while it can be locally invasive, the classic teaching is that vaginal SCC is secondary to cervical SCC, not vulvar carcinoma.", "C": "Bladder cancer is typically urothelial (transitional cell) carcinoma and, while anatomically close to the vagina, is not the classic source of secondary vaginal squamous cell carcinoma.", "D": "Rectal cancer is typically adenocarcinoma arising from colorectal mucosa and is not the classic source of secondary spread to the vagina in this context."}}}, {"id": "anking-reproductive-system-anatomy-2097", "fuente": "anking", "tema": 34, "anki": "1463101308955", "q": "Vaginal carcinoma arising in the lower two-thirds of the vagina drains first to which lymph node group?", "o": {"A": "Iliac nodes", "B": "Para-aortic nodes", "C": "Inguinal nodes", "D": "Obturator nodes"}, "r": "C", "e": {"correcta": "The lower two-thirds of the vagina drains first to the inguinal lymph nodes, mirroring the lymphatic drainage of the vulva, because this segment develops from the urogenital sinus and shares its lymphatic pathways with external genital structures.", "incorrectas": {"A": "The iliac nodes are the first drainage site for the upper third of the vagina, which shares lymphatic pathways with pelvic structures like the cervix and uterus, not the lower two-thirds.", "B": "Para-aortic nodes are a later or secondary drainage site for pelvic and retroperitoneal structures (e.g., ovaries, testes) rather than the first-echelon nodes for lower vaginal carcinoma.", "D": "Obturator nodes are part of the pelvic lymphatic chain draining structures like the bladder and prostate, not the primary first-station nodes for lower vaginal lymphatic drainage."}}}, {"id": "anking-reproductive-system-anatomy-2098", "fuente": "anking", "tema": 34, "anki": "1463101311443", "q": "Vaginal carcinoma arising in the upper one-third of the vagina drains first to which lymph node group?", "o": {"A": "Inguinal nodes", "B": "Iliac nodes", "C": "Superficial cervical nodes", "D": "Axillary nodes"}, "r": "B", "e": {"correcta": "The upper third of the vagina drains first to the iliac lymph nodes, consistent with its Müllerian duct origin and shared lymphatic drainage pathways with the cervix and uterus, which also drain to the iliac chain.", "incorrectas": {"A": "Inguinal nodes are the first drainage site for the lower two-thirds of the vagina (and the vulva), reflecting urogenital sinus origin, not the upper third.", "C": "Superficial cervical nodes refer to lymph nodes of the neck region and have no relationship to vaginal lymphatic drainage.", "D": "Axillary nodes drain the breast and upper limb, and are not involved in the lymphatic drainage of the vaginal canal."}}}, {"id": "anking-reproductive-system-anatomy-2099", "fuente": "anking", "tema": 34, "anki": "1463102395477", "q": "The ectocervix is normally lined by which type of epithelium?", "o": {"A": "Simple columnar epithelium", "B": "Non-keratinized stratified squamous epithelium", "C": "Transitional epithelium", "D": "Pseudostratified columnar epithelium"}, "r": "B", "e": {"correcta": "The ectocervix, the portion of the cervix visible on vaginal examination, is lined by non-keratinized stratified squamous epithelium, continuous with the vaginal mucosa, in contrast to the columnar epithelium lining the endocervix.", "incorrectas": {"A": "Simple columnar epithelium lines the endocervix, not the ectocervix; the junction between these two epithelial types forms the clinically important transformation zone.", "C": "Transitional epithelium is specific to the urinary tract and is not found in the cervix.", "D": "Pseudostratified columnar epithelium characterizes tissues like the respiratory tract and vas deferens, not the cervical epithelium."}}}, {"id": "anking-reproductive-system-anatomy-2100", "fuente": "anking", "tema": 34, "anki": "1463105819866", "q": "The endocervix is normally lined by which type of epithelium?", "o": {"A": "Non-keratinized stratified squamous epithelium", "B": "Keratinized stratified squamous epithelium", "C": "Simple columnar epithelium", "D": "Transitional epithelium"}, "r": "C", "e": {"correcta": "The endocervix, the canal leading into the uterine cavity, is lined by simple columnar epithelium, which produces mucus that changes in character across the menstrual cycle to regulate sperm passage, in contrast to the squamous epithelium of the ectocervix.", "incorrectas": {"A": "Non-keratinized stratified squamous epithelium lines the ectocervix and vagina, not the glandular endocervix.", "B": "Keratinized stratified squamous epithelium is found on external skin surfaces and is not present anywhere in the cervix.", "D": "Transitional epithelium lines the urinary tract and is unrelated to the cervical mucosal lining."}}}, {"id": "anking-reproductive-system-anatomy-2101", "fuente": "anking", "tema": 34, "anki": "1463105824837", "q": "The squamocolumnar junction between the ectocervix and endocervix, which is the most common site of cervical cancer, is known by what name?", "o": {"A": "External os", "B": "Internal os", "C": "Transformation zone", "D": "Isthmus"}, "r": "C", "e": {"correcta": "The transformation zone is the squamocolumnar junction where the squamous epithelium of the ectocervix meets the columnar epithelium of the endocervix; this area undergoes constant metaplastic change and is the most common site for the development of cervical dysplasia and carcinoma.", "incorrectas": {"A": "The external os is the anatomic opening of the cervix into the vagina, a landmark structure but not itself defined as the epithelial junction where cancer typically arises.", "B": "The internal os is the opening of the cervix into the uterine cavity, marking the boundary between the cervix and the uterine corpus, not the squamocolumnar junction.", "D": "The isthmus refers to the narrowed segment of the uterus between the body and the cervix, an anatomic region distinct from the squamocolumnar transformation zone."}}}, {"id": "anking-reproductive-system-pathology-2102", "fuente": "anking", "tema": 8, "anki": "1463105840341", "q": "HPV is a sexually transmitted DNA virus that preferentially infects the lower genital tract. At which anatomic site of the cervix does it most characteristically infect?", "o": {"A": "Endocervical glands", "B": "Transformation zone", "C": "Ectocervix (mature squamous epithelium)", "D": "Vaginal fornix"}, "r": "B", "e": {"correcta": "The transformation zone is the region where columnar endocervical epithelium undergoes metaplasia to squamous epithelium; this zone of immature, actively dividing squamous metaplastic cells is uniquely vulnerable to HPV infection and integration, making it the site of origin for nearly all cervical dysplasia and carcinoma.", "incorrectas": {"A": "The endocervical glands are lined by mucus-secreting columnar epithelium, which is not the site of active squamous metaplasia and is not the classic site of HPV-driven dysplastic change.", "C": "Mature ectocervical squamous epithelium is fully differentiated and less susceptible to HPV-driven transformation than the actively metaplastic transformation zone.", "D": "The vaginal fornix is not the primary site of cervical HPV infection; cervical dysplasia arises specifically at the transformation zone, not the vaginal epithelium."}}}, {"id": "anking-reproductive-system-pathology-2103", "fuente": "anking", "tema": 8, "anki": "1463105881914", "q": "A patient with persistent (non-cleared) HPV infection is at risk for developing cervical dysplasia. What is the pathologic term for this precancerous cervical lesion?", "o": {"A": "Cervical intraepithelial neoplasia (CIN)", "B": "Vulvar intraepithelial neoplasia (VIN)", "C": "Endometrial hyperplasia", "D": "Squamous cell hyperplasia of the vulva"}, "r": "A", "e": {"correcta": "Most HPV infections are cleared by the host's acute inflammatory response, but when infection persists, the virus can integrate into the host genome and drive dysplastic transformation of the transformation zone epithelium, termed cervical intraepithelial neoplasia (CIN) — the direct precursor to invasive cervical carcinoma.", "incorrectas": {"B": "VIN is the analogous precancerous lesion of the vulva, also HPV-related, but the question specifically describes cervical dysplasia, which is termed CIN.", "C": "Endometrial hyperplasia is a proliferation of endometrial glands typically driven by unopposed estrogen, unrelated to HPV infection of the cervix.", "D": "Squamous cell hyperplasia of the vulva is a benign reactive skin condition, not the HPV-driven premalignant lesion described here."}}}, {"id": "anking-reproductive-system-pathology-2104", "fuente": "anking", "tema": 8, "anki": "1463105890344", "q": "The oncogenic risk of a given HPV infection (i.e., whether it is a high-risk or low-risk strain) is determined by which method?", "o": {"A": "Viral culture and cytopathic effect", "B": "Serologic antibody titers", "C": "DNA sequencing (genotyping)", "D": "Electron microscopy of viral particles"}, "r": "C", "e": {"correcta": "HPV strains are classified as high-risk or low-risk based on their genomic DNA sequence, since different genotypes encode E6/E7 oncoproteins with varying capacity to inactivate p53 and Rb; DNA sequencing (genotyping) is the method used to identify the specific strain and thus its oncogenic potential.", "incorrectas": {"A": "HPV is difficult to culture in standard cell lines and viral culture is not how strain-specific oncogenic risk is determined clinically.", "B": "Serologic antibody titers reflect past exposure/immune response but do not identify the specific viral genotype or its oncogenic risk.", "D": "Electron microscopy can visualize viral particle morphology but cannot distinguish between HPV genotypes, which is done through molecular DNA analysis."}}}, {"id": "anking-reproductive-system-pathology-2105", "fuente": "anking", "tema": 8, "anki": "1463105896827", "q": "Which of the following HPV genotypes is classified as high-risk for progression to cervical cancer?", "o": {"A": "Type 6", "B": "Type 11", "C": "Type 16", "D": "Type 42"}, "r": "C", "e": {"correcta": "HPV types 16, 18, 31, and 33 are considered high-risk strains because their E6 and E7 oncoproteins efficiently degrade p53 and inactivate Rb, respectively, promoting uncontrolled cell cycle progression and malignant transformation of cervical epithelium.", "incorrectas": {"A": "HPV type 6 is a low-risk strain, classically associated with genital warts (condyloma acuminatum), not cervical cancer.", "B": "HPV type 11 is also low-risk and, like type 6, causes benign genital warts rather than driving oncogenic transformation.", "D": "HPV type 42 is not among the classic high-risk oncogenic strains tested on Step 1; the well-established high-risk genotypes are 16, 18, 31, and 33."}}}, {"id": "anking-reproductive-system-pathology-2106", "fuente": "anking", "tema": 8, "anki": "1463105905329", "q": "Which pair of HPV genotypes is classified as low-risk, causing genital warts rather than cervical carcinoma?", "o": {"A": "16 and 18", "B": "31 and 33", "C": "6 and 11", "D": "18 and 33"}, "r": "C", "e": {"correcta": "HPV types 6 and 11 are low-risk genotypes that typically cause condyloma acuminatum (genital warts) rather than malignant transformation, because their E6/E7 proteins have much weaker binding affinity for p53 and Rb compared to high-risk strains.", "incorrectas": {"A": "16 and 18 are the two most common high-risk oncogenic HPV genotypes, strongly associated with cervical carcinoma, not genital warts.", "B": "31 and 33 are also high-risk oncogenic strains associated with cervical dysplasia and cancer, not benign warts.", "D": "18 and 33 are both high-risk strains linked to cervical carcinoma; low-risk strains associated with genital warts are 6 and 11."}}}, {"id": "anking-reproductive-system-pathology-2107", "fuente": "anking", "tema": 8, "anki": "1463105924097", "q": "A cervical biopsy shows koilocytic change, nuclear atypia, and increased mitotic activity within the cervical epithelium. What is this histologic diagnosis?", "o": {"A": "Cervical intraepithelial neoplasia (CIN)", "B": "Invasive squamous cell carcinoma", "C": "Endocervical polyp", "D": "Chronic cervicitis"}, "r": "A", "e": {"correcta": "CIN (cervical dysplasia) is defined histologically by koilocytic change (perinuclear halos from HPV cytopathic effect), nuclear atypia, and increased mitoses confined within the epithelium above an intact basement membrane, representing a precancerous but non-invasive lesion.", "incorrectas": {"B": "Invasive squamous cell carcinoma requires penetration through the basement membrane into the underlying stroma, which is not present in dysplasia confined to the epithelium.", "C": "An endocervical polyp is a benign, often inflammatory or hyperplastic growth of endocervical tissue, lacking the koilocytic atypia characteristic of HPV-related dysplasia.", "D": "Chronic cervicitis is a nonspecific inflammatory process with lymphocytic infiltration, not defined by koilocytosis or dysplastic nuclear changes."}}}, {"id": "anking-reproductive-system-pathology-2108", "fuente": "anking", "tema": 8, "anki": "1463105932210", "q": "On cervical biopsy, immature dysplastic cells are confined to less than one-third of the epithelial thickness. How should this lesion be graded?", "o": {"A": "CIN I", "B": "CIN II", "C": "CIN III", "D": "Carcinoma in situ"}, "r": "A", "e": {"correcta": "CIN I (low-grade dysplasia) is defined by dysplastic, immature basal-type cells occupying less than one-third of the epithelial thickness, with the upper two-thirds still showing normal maturation; this low-grade lesion has the highest likelihood of spontaneous regression.", "incorrectas": {"B": "CIN II is high-grade dysplasia involving up to two-thirds of the epithelial thickness, more extensive than the less-than-one-third involvement described.", "C": "CIN III involves nearly the full thickness of the epithelium (all but the most superficial layer), far more extensive than the finding described.", "D": "Carcinoma in situ involves the entire thickness of the epithelium with no normal maturation at any level, which is more severe than the less-than-one-third involvement in CIN I."}}}, {"id": "anking-reproductive-system-pathology-2109", "fuente": "anking", "tema": 8, "anki": "1463105939506", "q": "A cervical biopsy demonstrates dysplastic cells occupying up to two-thirds of the epithelial thickness, with some surface maturation still present. What CIN grade does this represent?", "o": {"A": "CIN I", "B": "CIN II", "C": "CIN III", "D": "Carcinoma in situ"}, "r": "B", "e": {"correcta": "CIN II is defined by dysplastic cells extending through less than two-thirds of the epithelial thickness, an intermediate grade between the mild involvement of CIN I and the near-full-thickness involvement of CIN III; it is considered high-grade dysplasia requiring closer management.", "incorrectas": {"A": "CIN I involves less than one-third of the epithelial thickness, substantially less extensive than the two-thirds involvement described here.", "C": "CIN III involves slightly less than the entire thickness of the epithelium, more extensive than the up-to-two-thirds involvement of CIN II.", "D": "Carcinoma in situ involves the full thickness of the epithelium with no residual surface maturation, unlike the partial involvement seen in CIN II."}}}, {"id": "anking-reproductive-system-pathology-2110", "fuente": "anking", "tema": 8, "anki": "1463105943899", "q": "A cervical biopsy shows dysplastic cells occupying nearly the entire thickness of the epithelium, sparing only a thin superficial layer of maturation. What is the most likely grade?", "o": {"A": "CIN I", "B": "CIN II", "C": "CIN III", "D": "Invasive carcinoma"}, "r": "C", "e": {"correcta": "CIN III is defined by dysplastic cells occupying slightly less than the entire thickness of the epithelium, just short of full-thickness involvement (which would be carcinoma in situ); it represents severe, high-grade dysplasia with a low likelihood of spontaneous regression.", "incorrectas": {"A": "CIN I involves less than one-third of the epithelium, far less than the near-complete involvement described.", "B": "CIN II involves up to two-thirds of the epithelium, less extensive than the near-full-thickness involvement described here.", "D": "Invasive carcinoma requires penetration through the basement membrane into stroma; this description remains confined to the epithelium and is therefore still intraepithelial (CIN III), not invasive disease."}}}, {"id": "anking-reproductive-system-pathology-2111", "fuente": "anking", "tema": 8, "anki": "1463105947626", "q": "A cervical biopsy shows dysplastic cells replacing the full thickness of the epithelium, with cells failing to mature or become pink toward the surface, but the basement membrane remains intact. What is this diagnosis?", "o": {"A": "CIN I", "B": "CIN II", "C": "Carcinoma in situ", "D": "Invasive squamous cell carcinoma"}, "r": "C", "e": {"correcta": "Carcinoma in situ is characterized by full-thickness epithelial involvement by dysplastic cells that never mature or acquire the pink cytoplasmic staining of normal maturing squamous cells, while the basement membrane remains intact, distinguishing it from invasive carcinoma.", "incorrectas": {"A": "CIN I involves less than one-third of the epithelial thickness with preserved surface maturation, unlike the full-thickness involvement described.", "B": "CIN II involves up to two-thirds of the epithelium, not the entire thickness as described in carcinoma in situ.", "D": "Invasive squamous cell carcinoma requires breach of the basement membrane into the stroma; here the basement membrane remains intact, keeping the lesion in situ."}}}, {"id": "anking-reproductive-system-pathology-2112", "fuente": "anking", "tema": 8, "anki": "1463105962049", "q": "Approximately what percentage of CIN I lesions spontaneously regress to normal cervical epithelium if untreated?", "o": {"A": "10%", "B": "33%", "C": "66%", "D": "100%"}, "r": "C", "e": {"correcta": "CIN I has the highest regression rate of the dysplastic grades, with approximately 66% of cases returning to normal epithelium, reflecting the fact that many low-grade lesions represent transient HPV infection that the immune system ultimately clears.", "incorrectas": {"A": "10% regression is far too low for CIN I; low-grade dysplasia has a relatively favorable natural history with the majority of lesions regressing.", "B": "33% is the approximate regression rate for the more advanced CIN II, not the milder CIN I, which regresses more often.", "D": "100% regression does not occur even in CIN I; a meaningful fraction can persist or progress, which is why surveillance or treatment is still recommended."}}}, {"id": "anking-reproductive-system-pathology-2113", "fuente": "anking", "tema": 8, "anki": "1463105965577", "q": "Approximately what percentage of CIN II lesions spontaneously regress to normal cervical epithelium?", "o": {"A": "10%", "B": "33%", "C": "66%", "D": "90%"}, "r": "B", "e": {"correcta": "CIN II, a higher-grade lesion than CIN I, regresses spontaneously in only about 33% of cases, reflecting a greater degree of persistent HPV-driven genomic instability and a correspondingly higher likelihood of progression compared with CIN I.", "incorrectas": {"A": "10% is too low an estimate for CIN II regression; this rate is closer to what is expected for CIN III, which regresses far less often.", "C": "66% regression is the rate associated with the milder CIN I, which has a substantially better prognosis for spontaneous resolution than CIN II.", "D": "90% regression does not apply to any CIN grade; even the mildest lesion (CIN I) regresses only about two-thirds of the time."}}}, {"id": "anking-reproductive-system-pathology-2114", "fuente": "anking", "tema": 8, "anki": "1463105969236", "q": "Which statement best describes the likelihood of spontaneous regression to normal epithelium in CIN III?", "o": {"A": "It regresses in the majority of cases (>66%)", "B": "It regresses in about one-third of cases", "C": "Regression is possible but rare", "D": "Regression is impossible because the basement membrane has already been breached"}, "r": "C", "e": {"correcta": "CIN III represents severe dysplasia with near-full-thickness epithelial involvement; spontaneous regression is possible but slim, reflecting the advanced degree of genomic instability, which is why CIN III is generally treated definitively (e.g., excisional procedures) rather than observed.", "incorrectas": {"A": "Majority regression (>66%) describes CIN I, the mildest grade, which has a far more favorable natural history than the more advanced CIN III.", "B": "One-third regression is the approximate rate for CIN II, an intermediate-grade lesion, not the more severe CIN III.", "D": "CIN III is still an intraepithelial process, and the basement membrane is intact (not yet breached); breach of the basement membrane would instead define invasive carcinoma, not CIN III."}}}, {"id": "anking-reproductive-system-pathology-2115", "fuente": "anking", "tema": 8, "anki": "1463105972862", "q": "A cervical biopsy reveals carcinoma in situ. What is the expected likelihood of spontaneous reversal to normal epithelium without treatment?", "o": {"A": "66%", "B": "33%", "C": "Slim but possible", "D": "Not possible"}, "r": "D", "e": {"correcta": "Carcinoma in situ represents full-thickness dysplastic replacement of the epithelium with essentially no normal maturation anywhere in the epithelium; at this stage, spontaneous reversal to normal epithelium is not considered possible, and definitive treatment (excision/ablation) is required to prevent progression to invasive carcinoma.", "incorrectas": {"A": "66% regression describes the favorable natural history of mild dysplasia (CIN I), not the essentially irreversible carcinoma in situ.", "B": "33% regression corresponds to CIN II, a lesion with far less epithelial involvement than full-thickness carcinoma in situ.", "C": "\"Slim but possible\" describes CIN III, which retains a thin sliver of normal maturation; carcinoma in situ, with no maturation at all, does not spontaneously reverse."}}}, {"id": "anking-reproductive-system-pathology-2116", "fuente": "anking", "tema": 8, "anki": "1463105976747", "q": "A woman presents with abnormal vaginal bleeding, often noted after intercourse. Which cervical pathology classically presents this way, though it is more commonly detected asymptomatically on screening?", "o": {"A": "Cervical carcinoma", "B": "Endometrial polyp", "C": "Bacterial vaginosis", "D": "Ovarian cyst"}, "r": "A", "e": {"correcta": "Cervical carcinoma classically presents with postcoital bleeding or abnormal vaginal discharge due to the friable, vascular nature of the tumor surface, though most cases today are asymptomatic and detected through routine Pap smear screening before symptoms develop.", "incorrectas": {"B": "Endometrial polyps can cause abnormal uterine bleeding but are benign endometrial growths, not the malignant process being described here; they are not specifically associated with postcoital bleeding as a hallmark.", "C": "Bacterial vaginosis typically presents with malodorous discharge rather than postcoital bleeding, and is an infectious, not neoplastic, process.", "D": "Ovarian cysts typically present with pelvic pain or are asymptomatic, not with postcoital vaginal bleeding, which points to a cervical rather than ovarian source."}}}, {"id": "anking-reproductive-system-pathology-2117", "fuente": "anking", "tema": 8, "anki": "1463105983927", "q": "What is the single greatest risk factor for developing cervical carcinoma?", "o": {"A": "Multiple sexual partners", "B": "Cigarette smoking", "C": "Early menarche", "D": "Oral contraceptive use"}, "r": "A", "e": {"correcta": "Having multiple sexual partners is the number one risk factor for cervical carcinoma because it directly increases the likelihood of acquiring high-risk HPV, the necessary causative agent for nearly all cervical cancers; virtually all other risk factors act by increasing HPV acquisition or persistence.", "incorrectas": {"B": "Smoking is a genuine risk factor (carcinogens concentrate in cervical mucus and impair local immunity), but it is a secondary contributor, not the leading risk factor, which is HPV exposure via multiple partners.", "C": "Early coitarche (early age at first intercourse) increases HPV exposure risk and is a recognized risk factor, but it is not the single greatest risk factor compared to lifetime number of sexual partners.", "D": "Lack of barrier contraception (not oral contraceptive use per se) increases HPV transmission risk; oral contraceptives themselves are not the primary driver of cervical cancer risk in this context."}}}, {"id": "anking-reproductive-system-pathology-2118", "fuente": "anking", "tema": 8, "anki": "1463105999636", "q": "Cervical carcinoma is defined as an invasive process because malignant cells breach which structure?", "o": {"A": "Basement membrane", "B": "Perimetrium", "C": "Endocervical canal mucosa", "D": "Myometrium"}, "r": "A", "e": {"correcta": "Cervical carcinoma is defined by invasion of malignant epithelial cells through the basement membrane into the underlying cervical stroma, distinguishing true invasive carcinoma from intraepithelial neoplasia (CIN) or carcinoma in situ, which remain confined above the basement membrane.", "incorrectas": {"B": "The perimetrium is the outer serosal covering of the uterus, a structure invaded only in advanced, locally extensive disease, not the defining feature that separates in situ from invasive carcinoma.", "C": "The endocervical canal mucosa is where the tumor often originates, but invasion is defined by penetration through the basement membrane into stroma, not simply involvement of the mucosal surface.", "D": "The myometrium is the uterine muscular wall, a structure involved by invasion from an endometrial or advanced cervical tumor, not the primary boundary that defines invasiveness in cervical carcinoma."}}}, {"id": "anking-reproductive-system-pathology-2119", "fuente": "anking", "tema": 8, "anki": "1463106003755", "q": "Cervical carcinoma most commonly develops in which patient demographic?", "o": {"A": "Adolescents (13-19 years)", "B": "Young adults (20-30 years)", "C": "Middle-aged women (40-50 years)", "D": "Elderly women (>70 years)"}, "r": "C", "e": {"correcta": "Cervical carcinoma most commonly affects middle-aged women, average age 40-50 years, reflecting the typical decades-long latency between initial HPV infection (often acquired in the teens/20s), progression through CIN, and eventual development of invasive carcinoma.", "incorrectas": {"B": "Young adults are the age group in which HPV infection and early CIN are most commonly acquired, but invasive carcinoma itself typically manifests later, after years of dysplastic progression.", "A": "Adolescents may acquire HPV infection but rarely develop invasive cervical carcinoma given the long natural history from infection to cancer.", "D": "While cervical cancer can occur in elderly women, especially if unscreened, the peak incidence is in the middle-aged group (40-50 years), reflecting the typical progression timeline from HPV infection."}}}, {"id": "anking-reproductive-system-pathology-2120", "fuente": "anking", "tema": 8, "anki": "1463106011070", "q": "What is the most common histologic subtype of cervical carcinoma, accounting for approximately 80% of cases?", "o": {"A": "Adenocarcinoma", "B": "Squamous cell carcinoma", "C": "Small cell (neuroendocrine) carcinoma", "D": "Clear cell carcinoma"}, "r": "B", "e": {"correcta": "Squamous cell carcinoma accounts for roughly 80% of cervical carcinomas, arising from the squamous epithelium of the transformation zone through the HPV-driven CIN pathway, making it by far the most common histologic subtype.", "incorrectas": {"A": "Adenocarcinoma, arising from endocervical glandular epithelium, is the second most common subtype at around 15%, less common than squamous cell carcinoma.", "C": "Small cell (neuroendocrine) carcinoma of the cervix is a rare, highly aggressive subtype, representing only a small minority of cases, not the predominant histology.", "D": "Clear cell carcinoma of the cervix is a rare subtype historically associated with in utero diethylstilbestrol (DES) exposure, far less common than squamous cell carcinoma."}}}, {"id": "anking-reproductive-system-pathology-2121", "fuente": "anking", "tema": 8, "anki": "1463106014708", "q": "What is the second most common histologic subtype of cervical carcinoma, accounting for approximately 15% of cases?", "o": {"A": "Squamous cell carcinoma", "B": "Adenocarcinoma", "C": "Sarcoma", "D": "Melanoma"}, "r": "B", "e": {"correcta": "Adenocarcinoma, arising from the mucus-secreting glandular (columnar) epithelium of the endocervix, is the second most common subtype of cervical carcinoma at about 15%, and is notably less well detected by conventional Pap smear cytology than squamous lesions.", "incorrectas": {"A": "Squamous cell carcinoma is the most common subtype (about 80%), not the second most common, arising from squamous rather than glandular epithelium.", "C": "Sarcoma of the cervix is an extremely rare mesenchymal tumor, far less common than adenocarcinoma and not a major contributor to overall cervical carcinoma statistics.", "D": "Primary cervical melanoma is exceedingly rare and not a recognized major histologic subtype contributing meaningfully to cervical cancer incidence."}}}, {"id": "anking-reproductive-system-pathology-2122", "fuente": "anking", "tema": 8, "anki": "1463106018043", "q": "Advanced cervical carcinoma frequently invades anteriorly into the bladder and can obstruct which structure, potentially leading to hydronephrosis and renal failure?", "o": {"A": "Ureters", "B": "Urethra", "C": "Fallopian tubes", "D": "Renal artery"}, "r": "A", "e": {"correcta": "Locally advanced cervical carcinoma can invade through the anterior uterine wall into the bladder and compress or invade the ureters as they course near the cervix, causing bilateral obstruction, hydronephrosis, and ultimately renal failure — a leading cause of death in advanced cervical cancer.", "incorrectas": {"B": "Urethral obstruction is less classically emphasized as the mechanism of renal compromise in cervical cancer; it is ureteral obstruction near the cervix that leads to hydronephrosis.", "C": "The fallopian tubes are not in the direct path of anterior tumor extension into the bladder and are not implicated in the renal failure mechanism described.", "D": "The renal artery is far removed anatomically from the pelvis and is not compressed by locally invasive cervical carcinoma; the ureters, which run near the cervix, are the vulnerable structure."}}}, {"id": "anking-reproductive-system-pathology-2123", "fuente": "anking", "tema": 8, "anki": "1463106029685", "q": "What is the standard screening test used to detect precancerous and cancerous cervical lesions?", "o": {"A": "Transvaginal ultrasound", "B": "Pap smear", "C": "Serum CA-125", "D": "Endometrial biopsy"}, "r": "B", "e": {"correcta": "The Pap (Papanicolaou) smear is the standard screening test for cervical carcinoma, involving cytologic sampling of cells from the transformation zone to detect dysplastic changes before they progress to invasive cancer, dramatically reducing cervical cancer mortality since its introduction.", "incorrectas": {"A": "Transvaginal ultrasound is used to evaluate the endometrium and ovaries, not to screen for cervical epithelial dysplasia, which requires cytologic sampling.", "C": "CA-125 is a tumor marker used mainly in ovarian cancer surveillance, not a screening tool for cervical dysplasia or carcinoma.", "D": "Endometrial biopsy samples the endometrial lining to evaluate for endometrial pathology (e.g., hyperplasia or cancer), not the cervical transformation zone."}}}, {"id": "anking-reproductive-system-pathology-2124", "fuente": "anking", "tema": 8, "anki": "1463106033552", "q": "According to standard guidelines, at what age should routine Pap smear screening begin, and at what interval should it typically be repeated?", "o": {"A": "Age 18, annually", "B": "Age 21, every 3 years", "C": "Age 25, every 5 years", "D": "Age 30, every year"}, "r": "B", "e": {"correcta": "Routine cervical cancer screening with Pap smears begins at age 21 and is generally repeated every three years in average-risk women, balancing early detection of dysplasia against the high rate of transient HPV infections and low-grade changes that would otherwise lead to unnecessary intervention if screened too frequently or too early.", "incorrectas": {"A": "Screening does not begin at 18 nor is it performed annually as a default; starting too early captures many transient HPV-related changes that would spontaneously resolve.", "C": "Age 25 with 5-year intervals does not reflect the standard cytology-based screening protocol beginning at 21 with 3-year intervals (co-testing with HPV extends intervals differently at older ages).", "D": "Age 30 with annual screening does not match standard guidelines; screening starts earlier (21) and is spaced out to every 3 years rather than annually."}}}, {"id": "anking-reproductive-system-pathology-2125", "fuente": "anking", "tema": 8, "anki": "1463106055950", "q": "During a Pap smear, cells are scraped from which specific region of the cervix?", "o": {"A": "Endocervical canal only", "B": "Transformation zone", "C": "Posterior fornix", "D": "External cervical os only"}, "r": "B", "e": {"correcta": "The Pap smear samples cells from the transformation zone, where columnar endocervical epithelium meets squamous ectocervical epithelium, because this is the site of active squamous metaplasia and the origin of nearly all HPV-related dysplasia and carcinoma.", "incorrectas": {"A": "Sampling only the endocervical canal would miss the squamocolumnar junction where most dysplastic change begins, making the transformation zone the necessary target.", "C": "The posterior fornix is sampled in some contexts (e.g., for cytology in specific circumstances) but is not the primary site targeted for detecting cervical dysplasia.", "D": "Sampling only the external os would miss the metaplastic transformation zone tissue that may have migrated into the endocervical canal, especially in older women, risking a false-negative result."}}}, {"id": "anking-reproductive-system-pathology-2126", "fuente": "anking", "tema": 8, "anki": "1463106062110", "q": "On Pap smear cytology, which of the following nuclear features is characteristic of high-grade dysplasia?", "o": {"A": "Small, pyknotic nuclei with abundant pale cytoplasm", "B": "Dark nuclei with a high nuclear-to-cytoplasmic ratio", "C": "Absent nuclei with vacuolated cytoplasm", "D": "Binucleation with normal chromatin pattern"}, "r": "B", "e": {"correcta": "High-grade dysplastic cells on Pap smear show dark (hyperchromatic) nuclei with a high nuclear-to-cytoplasmic ratio, reflecting increased DNA content and immature, poorly differentiated cells crowding out normal cytoplasmic volume — a hallmark cytologic feature of malignant or premalignant transformation.", "incorrectas": {"A": "Small, pyknotic nuclei with abundant pale cytoplasm describes a more mature, differentiated (benign) squamous cell, the opposite of the immature, atypical appearance of high-grade dysplasia.", "C": "Absent nuclei with vacuolated cytoplasm is not a described feature of dysplasia; enucleated cells with vacuoles would suggest a degenerative or artifactual change rather than dysplastic atypia.", "D": "Binucleation with normal chromatin does not capture the essential feature of dysplasia, which is nuclear hyperchromasia and an increased nuclear-to-cytoplasmic ratio, not simply having two nuclei."}}}, {"id": "anking-reproductive-system-pathology-2127", "fuente": "anking", "tema": 8, "anki": "1463106074503", "q": "After an abnormal Pap smear result, what is the appropriate next diagnostic step to confirm the presence and grade of cervical dysplasia?", "o": {"A": "Repeat Pap smear in 6 months only", "B": "Colposcopy with biopsy", "C": "Empiric loop electrosurgical excision procedure (LEEP)", "D": "Pelvic MRI"}, "r": "B", "e": {"correcta": "An abnormal Pap smear is followed by colposcopy, direct visualization of the cervix using a magnifying instrument (often with acetic acid application to highlight abnormal areas), combined with directed biopsy to obtain histologic confirmation of the grade of dysplasia before deciding on management.", "incorrectas": {"A": "Simply repeating the Pap smear without further evaluation may be appropriate for certain very low-risk abnormal results but is not the standard confirmatory step for most abnormal findings, which require tissue diagnosis via colposcopy/biopsy.", "C": "LEEP is a treatment (excisional) procedure typically performed after a tissue diagnosis has already confirmed high-grade dysplasia via colposcopic biopsy, not as the immediate next step after an abnormal cytology result.", "D": "Pelvic MRI is used for staging invasive cervical cancer or evaluating extent of disease, not as the initial confirmatory test after an abnormal screening Pap smear."}}}, {"id": "anking-reproductive-system-pathology-2128", "fuente": "anking", "tema": 8, "anki": "1463106081948", "q": "A patient with biopsy-proven high-grade CIN had a Pap smear reported as normal one year earlier. What is the most likely explanation for this false-negative result?", "o": {"A": "Inadequate sampling of the transformation zone", "B": "Overwhelming immune clearance of HPV", "C": "Laboratory contamination with blood", "D": "Use of an outdated liquid-based cytology technique"}, "r": "A", "e": {"correcta": "A key limitation of the Pap smear is inadequate sampling of the transformation zone — if the brush or spatula does not adequately capture cells from this critical squamocolumnar junction, dysplastic cells can be missed entirely, producing a false-negative result despite underlying disease.", "incorrectas": {"B": "Immune clearance of HPV would be expected to reduce, not mask, underlying dysplasia; it does not explain a false-negative Pap smear in a patient who in fact has high-grade CIN.", "C": "Blood contamination can sometimes obscure a slide but is not the classically cited major limitation of Pap smear screening; sampling error at the transformation zone is the key issue.", "D": "Liquid-based cytology is actually a modern refinement that improves sample quality compared to older conventional smears; it is not itself a cause of false-negative results."}}}, {"id": "anking-reproductive-system-pathology-2129", "fuente": "anking", "tema": 8, "anki": "1463106094001", "q": "The Pap smear is highly effective at detecting squamous cell carcinoma and its precursors, but has limited sensitivity for which cervical cancer subtype?", "o": {"A": "Squamous cell carcinoma", "B": "Adenocarcinoma", "C": "Verrucous carcinoma", "D": "Basaloid carcinoma"}, "r": "B", "e": {"correcta": "The Pap smear has limited efficacy in screening for adenocarcinoma because this glandular tumor arises higher within the endocervical canal, where exfoliated cells are less reliably captured by the cervical scraping technique, unlike squamous lesions at the exposed transformation zone.", "incorrectas": {"A": "Squamous cell carcinoma and its precursor lesions (CIN) are the classic strength of Pap smear screening, since these arise at the accessible transformation zone that is directly sampled.", "C": "Verrucous carcinoma is a rare, well-differentiated variant of squamous cell carcinoma; it is not the subtype classically cited as a screening blind spot for Pap smears.", "D": "Basaloid carcinoma is a variant of squamous cell carcinoma, not the glandular tumor type (adenocarcinoma) that Pap smear screening is known to underdetect."}}}, {"id": "anking-reproductive-system-embryology-2130", "fuente": "anking", "tema": 33, "anki": "1463141251045", "q": "The posterior pituitary (neurohypophysis) is derived embryologically from which tissue?", "o": {"A": "Neuroectoderm", "B": "Surface ectoderm (Rathke's pouch)", "C": "Mesoderm", "D": "Endoderm"}, "r": "A", "e": {"correcta": "The posterior pituitary arises from neuroectoderm as a downward extension of the diencephalon (infundibulum), explaining why it is composed of neural tissue and axon terminals of hypothalamic neurons that secrete oxytocin and ADH, rather than being a true secretory gland with its own hormone-synthesizing cells.", "incorrectas": {"B": "Surface ectoderm gives rise to Rathke's pouch, which forms the anterior pituitary (adenohypophysis), not the posterior pituitary.", "C": "Mesoderm forms connective tissue, muscle, and vasculature; it is not the embryologic origin of any part of the pituitary gland.", "D": "Endoderm gives rise to gut-lining epithelium and its derivatives (e.g., thyroid, lungs, liver), not the pituitary gland, which derives from ectodermal tissues."}}}, {"id": "anking-reproductive-system-physiology-2131", "fuente": "anking", "tema": 32, "anki": "1463163260222", "q": "During the proliferative phase of the menstrual cycle, growth of the endometrium is driven primarily by which hormone?", "o": {"A": "Progesterone", "B": "Estrogen", "C": "Follicle-stimulating hormone (FSH)", "D": "Luteinizing hormone (LH)"}, "r": "B", "e": {"correcta": "The proliferative phase is driven by rising estrogen produced by the developing ovarian follicle, which stimulates regrowth and thickening of the endometrium (glands and stroma) following menstrual shedding, preparing the uterine lining ahead of ovulation.", "incorrectas": {"A": "Progesterone is the dominant hormone of the subsequent secretory phase (after ovulation, from the corpus luteum), acting to mature and stabilize the endometrium rather than drive its initial proliferation.", "C": "FSH acts on the ovary to stimulate follicular development and estrogen production, but it is the downstream estrogen itself, not FSH directly, that drives endometrial proliferation.", "D": "LH triggers ovulation and supports corpus luteum formation, but it is not the hormone directly responsible for endometrial growth during the proliferative phase."}}}, {"id": "anking-reproductive-system-physiology-2132", "fuente": "anking", "tema": 32, "anki": "1463163500200", "q": "Following ovulation, preparation of the endometrium for potential implantation (the secretory phase) is primarily driven by which hormone?", "o": {"A": "Estrogen", "B": "Progesterone", "C": "Prolactin", "D": "Human chorionic gonadotropin (hCG)"}, "r": "B", "e": {"correcta": "Progesterone, secreted by the corpus luteum after ovulation, drives the secretory phase by inducing glandular tortuosity, glycogen secretion, and stromal changes that prepare the endometrium for blastocyst implantation.", "incorrectas": {"A": "Estrogen dominates the earlier proliferative phase, driving endometrial growth, but it is progesterone that matures the endometrium for implantation in the secretory phase.", "C": "Prolactin is primarily involved in lactation and milk production, not in driving the endometrial secretory changes of the menstrual cycle.", "D": "hCG is produced by the trophoblast after implantation has already occurred, to rescue the corpus luteum; it is not the hormone responsible for the secretory transformation that precedes implantation."}}}, {"id": "anking-reproductive-system-physiology-2133", "fuente": "anking", "tema": 32, "anki": "1463163507048", "q": "Menstrual shedding of the endometrium occurs as a direct consequence of the loss of which hormone's support?", "o": {"A": "Estrogen", "B": "Progesterone", "C": "FSH", "D": "Inhibin"}, "r": "B", "e": {"correcta": "In the absence of fertilization, the corpus luteum regresses and progesterone levels fall; this loss of progesterone support causes spiral artery vasoconstriction and ischemic necrosis of the functional endometrial layer, resulting in menstrual shedding.", "incorrectas": {"A": "Estrogen withdrawal also occurs at the end of the cycle, but the classic teaching attributes the endometrial shedding trigger specifically to loss of progesterone support from the regressing corpus luteum.", "C": "FSH levels rise again after menses to recruit a new cohort of follicles, but FSH itself does not directly maintain or withdraw endometrial support to trigger shedding.", "D": "Inhibin, secreted by granulosa cells, suppresses FSH release but is not the hormone whose withdrawal directly triggers endometrial shedding."}}}, {"id": "anking-reproductive-system-pathology-2134", "fuente": "anking", "tema": 8, "anki": "1463172089555", "q": "Asherman syndrome, characterized by intrauterine adhesions and secondary amenorrhea, most commonly results from which iatrogenic procedure?", "o": {"A": "Overaggressive dilation and curettage (D&C)", "B": "Laparoscopic tubal ligation", "C": "Hysteroscopic myomectomy with minimal curettage", "D": "Endometrial biopsy with a Pipelle catheter"}, "r": "A", "e": {"correcta": "Asherman syndrome typically results from overaggressive dilation and curettage, which can scrape through and damage the stratum basalis of the endometrium — the layer containing the stem cells needed for endometrial regeneration — leading to intrauterine scarring (synechiae) and subsequent amenorrhea or infertility.", "incorrectas": {"B": "Tubal ligation involves occlusion of the fallopian tubes for sterilization and does not damage the endometrial basalis layer or cause intrauterine adhesions.", "C": "A carefully performed hysteroscopic procedure with minimal curettage is far less likely to damage the stratum basalis compared to overaggressive blind curettage, which is the classic cause of Asherman syndrome.", "D": "A Pipelle endometrial biopsy is a gentle, minimally invasive sampling technique that does not typically cause the deep basalis injury and scarring seen with aggressive D&C."}}}, {"id": "anking-reproductive-system-physiology-2135", "fuente": "anking", "tema": 32, "anki": "1463172095708", "q": "An anovulatory menstrual cycle is defined by the absence of which specific event?", "o": {"A": "Menstrual bleeding", "B": "Ovulation", "C": "Follicular development", "D": "Endometrial proliferation"}, "r": "B", "e": {"correcta": "An anovulatory cycle is defined by the failure of ovulation to occur — the dominant follicle fails to rupture and release an oocyte, so no corpus luteum forms and progesterone is never produced, even though estrogen-driven follicular and endometrial development still occurs.", "incorrectas": {"A": "Menstrual bleeding can still occur in anovulatory cycles (often irregular or breakthrough bleeding due to unopposed estrogen), so bleeding itself is not the defining absent feature.", "C": "Follicular development typically still occurs in anovulatory cycles (driving the estrogen-mediated proliferative phase); it is specifically the follicular rupture/ovulation step that fails.", "D": "Endometrial proliferation still occurs under estrogen stimulation in anovulatory cycles; what is missing is the subsequent progesterone-driven secretory transformation dependent on ovulation."}}}, {"id": "anking-reproductive-system-physiology-2136", "fuente": "anking", "tema": 32, "anki": "1463172100364", "q": "In an anovulatory cycle, the endometrium undergoes an estrogen-driven proliferative phase but fails to progress through which subsequent phase due to lack of progesterone?", "o": {"A": "Menstrual phase", "B": "Follicular phase", "C": "Secretory phase", "D": "Luteal surge phase"}, "r": "C", "e": {"correcta": "Because no corpus luteum forms without ovulation, progesterone is never produced, so the endometrium never transitions into the secretory phase; instead, it remains under unopposed estrogen stimulation, causing progressive endometrial overgrowth that eventually outgrows its blood supply and sloughs irregularly, producing breakthrough bleeding.", "incorrectas": {"A": "The menstrual phase (shedding) can still occur in anovulatory cycles, though it manifests as irregular breakthrough bleeding from an overgrown endometrium rather than the organized withdrawal bleeding of a normal cycle.", "B": "The follicular phase (the estrogen-driven, pre-ovulatory phase of ovarian development) still proceeds in anovulatory cycles; it is the ovarian, not endometrial, terminology and is not the missing phase in the endometrium.", "D": "There is no distinct \"luteal surge phase\" in the standard menstrual cycle terminology; the missing endometrial phase due to absent progesterone is specifically the secretory phase."}}}, {"id": "anking-reproductive-system-pathology-2137", "fuente": "anking", "tema": 8, "anki": "1463172108621", "q": "In anovulatory cycles, breakdown and shedding of proliferative endometrial glands (unopposed by progesterone-driven secretory transformation) results in what clinical finding?", "o": {"A": "Abnormal uterine bleeding", "B": "Galactorrhea", "C": "Cervical stenosis", "D": "Vaginal atrophy"}, "r": "A", "e": {"correcta": "Without ovulation there is no corpus luteum, and thus no progesterone to stabilize and convert the proliferative endometrium into a secretory pattern. The estrogen-driven proliferative endometrium becomes unstable, outgrows its blood supply, and breaks down unpredictably, producing abnormal (irregular, often heavy) uterine bleeding rather than an organized menstrual shed.", "incorrectas": {"B": "Galactorrhea results from hyperprolactinemia stimulating breast tissue, not from unopposed estrogen effects on the endometrium; it is unrelated to the mechanism of anovulatory bleeding.", "C": "Cervical stenosis is a structural narrowing of the cervical canal (often from prior surgery or atrophy) that can cause outflow obstruction, not a consequence of unopposed proliferative endometrium breaking down.", "D": "Vaginal atrophy occurs in a low-estrogen state such as menopause, the opposite hormonal picture from anovulatory cycles, which are typically driven by continued estrogen without progesterone."}}}, {"id": "anking-reproductive-system-pathology-2138", "fuente": "anking", "tema": 8, "anki": "1463172112650", "q": "Anovulatory menstrual cycles are most likely to occur during which two periods of a woman's reproductive life?", "o": {"A": "Menarche and menopause", "B": "Early and late pregnancy", "C": "The follicular and luteal phases of a normal cycle", "D": "Immediately before and after ovulation in a normal cycle"}, "r": "A", "e": {"correcta": "Anovulatory cycles are most common at the extremes of reproductive life: during menarche, when the hypothalamic-pituitary-ovarian axis is still immature, and during the menopausal transition, when the ovary has diminishing responsiveness to gonadotropins. In both settings, follicles may develop under estrogen stimulation without a dominant follicle reaching full maturation and ovulating.", "incorrectas": {"B": "Pregnancy is a state of sustained progesterone and hCG-driven decidualization, not the classic clinical window for anovulatory cycles, which describes non-pregnant menstrual irregularity.", "C": "The follicular and luteal phases are the two halves of a normal ovulatory cycle itself; anovulatory cycles refer to a failure to progress from a follicular to a true luteal (post-ovulatory) phase, not simply naming the phases.", "D": "The periovulatory window is when ovulation is expected to occur in normal cycles; anovulatory cycles are defined by the absence of this event, not a time frame surrounding it."}}}, {"id": "anking-reproductive-system-pathology-2139", "fuente": "anking", "tema": 8, "anki": "1463172117522", "q": "A patient presents with fever and pelvic pain shortly after a bacterial infection ascends into the uterus. Which condition is characterized by acute bacterial infection of the endometrium?", "o": {"A": "Adenomyosis", "B": "Acute endometritis", "C": "Endometrial hyperplasia", "D": "Endometrial polyp"}, "r": "B", "e": {"correcta": "Acute endometritis is inflammation of the endometrium caused by an acute bacterial infection, classically ascending from the lower genital tract after events that disrupt the normal cervical barrier, such as delivery, miscarriage, or instrumentation. It presents with fever, abnormal uterine bleeding, and pelvic pain.", "incorrectas": {"A": "Adenomyosis is the presence of endometrial glands and stroma within the myometrium, a structural/ectopic tissue problem rather than an acute bacterial infection.", "C": "Endometrial hyperplasia is a proliferative response of endometrial glands to unopposed estrogen, not an infectious or inflammatory process.", "D": "An endometrial polyp is a benign, well-circumscribed hyperplastic protrusion of endometrial tissue, unrelated to acute bacterial infection."}}}, {"id": "anking-reproductive-system-pathology-2140", "fuente": "anking", "tema": 8, "anki": "1463172122482", "q": "Acute endometritis is classically associated with retained products of what, or with foreign bodies such as an IUD?", "o": {"A": "Retained products of conception", "B": "Retained gallstones", "C": "Retained surgical mesh", "D": "Retained urinary calculi"}, "r": "A", "e": {"correcta": "Retained products of conception (tissue left behind after delivery or miscarriage) or a foreign body like an intrauterine device provide a nidus and disrupted barrier for ascending bacteria to infect the endometrium, leading to acute endometritis.", "incorrectas": {"B": "Gallstones are related to biliary pathology (cholelithiasis/cholecystitis), an entirely separate organ system with no relationship to endometrial infection.", "C": "Surgical mesh is used in hernia or pelvic organ prolapse repairs; while foreign material can be a nidus for infection elsewhere, it is not the classic association taught for acute endometritis.", "D": "Urinary calculi (kidney stones) form in the urinary tract and are unrelated to intrauterine infections following pregnancy or instrumentation."}}}, {"id": "anking-reproductive-system-pathology-2141", "fuente": "anking", "tema": 8, "anki": "1463172137015", "q": "A postpartum patient presents with fever, abnormal uterine bleeding, and pelvic pain. What is the most likely diagnosis?", "o": {"A": "Ovarian torsion", "B": "Acute endometritis", "C": "Ectopic pregnancy", "D": "Uterine fibroid degeneration"}, "r": "B", "e": {"correcta": "Acute endometritis classically presents with the triad of fever, abnormal uterine bleeding, and pelvic pain, often in the postpartum or post-instrumentation setting where bacteria ascend into the uterine cavity and retained tissue or foreign material fuels the infection.", "incorrectas": {"A": "Ovarian torsion presents with sudden severe unilateral pelvic pain and often nausea/vomiting from ovarian ischemia, not fever with abnormal bleeding from an infected endometrium.", "C": "Ectopic pregnancy presents with amenorrhea, abdominal pain, and vaginal bleeding in the setting of a positive pregnancy test, a different mechanism (abnormal implantation) rather than infection.", "D": "Degenerating fibroids can cause acute pain, sometimes with low-grade fever, but this is due to ischemic necrosis of a leiomyoma, not bacterial infection of the endometrial lining."}}}, {"id": "anking-reproductive-system-pathology-2142", "fuente": "anking", "tema": 8, "anki": "1463172143887", "q": "Persistent, low-grade inflammation of the endometrium (as opposed to an acute bacterial infection) is termed what?", "o": {"A": "Chronic endometritis", "B": "Acute salpingitis", "C": "Adenomyosis", "D": "Endometrial hyperplasia"}, "r": "A", "e": {"correcta": "Chronic endometritis is defined by chronic inflammation of the endometrium, histologically marked by plasma cells (which are not normally present in the endometrium), distinguishing it from the neutrophilic, acute-phase picture of acute endometritis.", "incorrectas": {"B": "Acute salpingitis refers to acute inflammation of the fallopian tubes, a related but anatomically distinct structure from the endometrium.", "C": "Adenomyosis is ectopic endometrial tissue within the myometrium, a structural abnormality rather than a chronic inflammatory process of the endometrial lining itself.", "D": "Endometrial hyperplasia is excessive glandular proliferation driven by unopposed estrogen, not an inflammatory condition."}}}, {"id": "anking-reproductive-system-pathology-2143", "fuente": "anking", "tema": 8, "anki": "1463172156994", "q": "On endometrial biopsy, which cell type, when found infiltrating the endometrium, is diagnostic of chronic endometritis because it is not normally present there?", "o": {"A": "Neutrophils", "B": "Eosinophils", "C": "Plasma cells", "D": "Mast cells"}, "r": "C", "e": {"correcta": "Plasma cells are not a normal resident cell population of the endometrium, so their presence (along with lymphocytes, which are normally found there) is the key histologic clue for diagnosing chronic endometritis.", "incorrectas": {"A": "Neutrophils are the hallmark of acute inflammation and are expected in acute endometritis, but their presence alone does not define the chronic form.", "B": "Eosinophils suggest an allergic or parasitic process and are not the characteristic finding used to diagnose chronic endometritis.", "D": "Mast cells are involved in immediate hypersensitivity reactions and are not the diagnostic cell type associated with chronic endometrial inflammation."}}}, {"id": "anking-reproductive-system-pathology-2144", "fuente": "anking", "tema": 8, "anki": "1463172179641", "q": "A patient with chronic endometritis is found to have long-standing untreated chlamydial infection. This most likely progressed to chronic endometritis via which condition?", "o": {"A": "Bacterial vaginosis", "B": "Pelvic inflammatory disease", "C": "Toxic shock syndrome", "D": "Tubo-ovarian torsion"}, "r": "B", "e": {"correcta": "Chronic, unresolved pelvic inflammatory disease (often from long-standing Chlamydia trachomatis or Neisseria gonorrhoeae infection) is a classic cause of chronic endometritis, along with retained products of conception, IUDs, and tuberculosis.", "incorrectas": {"A": "Bacterial vaginosis is a vaginal dysbiosis (loss of lactobacilli, overgrowth of anaerobes like Gardnerella) that causes discharge and odor, but it is not the classic pathway linking chlamydia to chronic endometritis.", "C": "Toxic shock syndrome is caused by TSST-1-producing Staphylococcus aureus (classically tampon-associated) causing a systemic superantigen-mediated illness, unrelated to chronic chlamydial endometritis.", "D": "Tubo-ovarian torsion is a mechanical/vascular emergency involving twisting of the adnexa, not an infectious progression from chlamydia."}}}, {"id": "anking-reproductive-system-pathology-2145", "fuente": "anking", "tema": 8, "anki": "1463172186799", "q": "Beyond abnormal uterine bleeding and pelvic pain, chronic endometritis classically also presents with which additional complaint related to reproduction?", "o": {"A": "Hirsutism", "B": "Infertility", "C": "Galactorrhea", "D": "Precocious puberty"}, "r": "B", "e": {"correcta": "Chronic inflammation of the endometrium impairs its receptivity for implantation, so chronic endometritis classically presents with the triad of abnormal uterine bleeding, pelvic pain, and infertility.", "incorrectas": {"A": "Hirsutism reflects androgen excess (e.g., PCOS, adrenal or ovarian tumors), a hormonal disorder unrelated to endometrial inflammation.", "C": "Galactorrhea is caused by hyperprolactinemia acting on breast tissue, not by inflammation localized to the endometrium.", "D": "Precocious puberty reflects early activation of the hypothalamic-pituitary-gonadal axis or a hormone-secreting lesion, an entirely different pediatric endocrine process."}}}, {"id": "anking-antimicrobials-2146", "fuente": "anking", "tema": 4, "anki": "1463172191913", "q": "Which antibiotic regimen is used to treat infectious (bacterial) endometritis?", "o": {"A": "Azithromycin plus doxycycline", "B": "Gentamicin plus clindamycin, with or without ampicillin", "C": "Fluconazole plus metronidazole", "D": "Vancomycin plus rifampin"}, "r": "B", "e": {"correcta": "Infectious endometritis, which is typically polymicrobial (aerobic and anaerobic organisms from the lower genital tract), is treated with broad-spectrum coverage using gentamicin (gram-negative aerobic coverage) plus clindamycin (anaerobic coverage), with ampicillin often added for enterococcal or additional coverage.", "incorrectas": {"A": "Azithromycin plus doxycycline is a regimen more associated with treating chlamydia or as part of PID outpatient therapy, not the standard combination for established infectious endometritis.", "C": "Fluconazole treats fungal infections (e.g., Candida), and metronidazole alone targets anaerobes/protozoa; this combination does not provide the broad aerobic-anaerobic coverage endometritis requires.", "D": "Vancomycin plus rifampin targets gram-positive organisms including resistant staphylococci, not the typical polymicrobial flora implicated in postpartum or post-instrumentation endometritis."}}}, {"id": "anking-reproductive-system-pathology-2147", "fuente": "anking", "tema": 8, "anki": "1463172198813", "q": "A well-circumscribed, hyperplastic protrusion of endometrial tissue seen on hysteroscopy is best described as what?", "o": {"A": "Endometrial polyp", "B": "Leiomyoma", "C": "Endometrial carcinoma", "D": "Adenomyosis"}, "r": "A", "e": {"correcta": "An endometrial polyp is a well-circumscribed, hyperplastic (localized overgrowth) protrusion of endometrial tissue projecting into the uterine cavity, distinct from the surrounding normal endometrium seen on biopsy or imaging.", "incorrectas": {"B": "A leiomyoma (fibroid) is a benign smooth muscle tumor arising from the myometrium, not a glandular/stromal overgrowth of the endometrium itself.", "C": "Endometrial carcinoma is a malignant glandular proliferation with invasive potential, not the benign, well-circumscribed lesion described here.", "D": "Adenomyosis is the presence of endometrial glands and stroma within the myometrium, producing a diffusely enlarged uterus rather than a discrete polypoid lesion."}}}, {"id": "anking-reproductive-system-pathology-2148", "fuente": "anking", "tema": 8, "anki": "1463172225574", "q": "A patient with an endometrial polyp reports intermittent, painless vaginal bleeding. Which statement best characterizes the typical presentation of endometrial polyps?", "o": {"A": "They are always symptomatic with severe dysmenorrhea", "B": "They may be asymptomatic or present with painless abnormal uterine bleeding", "C": "They always cause infertility", "D": "They present with acute pelvic pain and fever"}, "r": "B", "e": {"correcta": "Endometrial polyps are frequently incidental findings but can also cause painless abnormal uterine bleeding due to surface friability or disruption of normal endometrial shedding, without the pain or systemic signs seen in infectious or inflammatory uterine conditions.", "incorrectas": {"A": "Severe dysmenorrhea (painful cramping) is more characteristic of conditions like adenomyosis or endometriosis, not the typically painless bleeding pattern of polyps.", "C": "While large polyps can occasionally interfere with implantation, infertility is not a universal or defining feature of endometrial polyps.", "D": "Acute pelvic pain and fever suggest an infectious process like endometritis, not the benign, usually painless nature of an endometrial polyp."}}}, {"id": "anking-reproductive-pharmacology-2149", "fuente": "anking", "tema": 3, "anki": "1463172226538", "q": "A breast cancer patient on long-term hormonal therapy develops endometrial polyps and hyperplasia. Which selective estrogen receptor modulator used in breast cancer treatment is responsible?", "o": {"A": "Raloxifene", "B": "Tamoxifen", "C": "Clomiphene", "D": "Letrozole"}, "r": "B", "e": {"correcta": "Tamoxifen acts as an estrogen receptor antagonist in breast tissue (its therapeutic anti-cancer effect) but paradoxically behaves as a weak estrogen receptor agonist in the endometrium, driving proliferation that can lead to endometrial polyps, hyperplasia, and increased risk of endometrial cancer.", "incorrectas": {"A": "Raloxifene is also a SERM used for osteoporosis prevention, but it is antagonistic at both breast and endometrial receptors, which is precisely why it does not carry the same endometrial cancer risk as tamoxifen.", "C": "Clomiphene is a SERM used to induce ovulation in infertility treatment by blocking estrogen negative feedback at the hypothalamus; it is not used as breast cancer therapy and is not the classic cause of endometrial hyperplasia in this context.", "D": "Letrozole is an aromatase inhibitor that lowers estrogen synthesis systemically; rather than stimulating the endometrium, it would tend to reduce estrogenic stimulation, and it works by an entirely different mechanism than tamoxifen's mixed agonist/antagonist SERM activity."}}}, {"id": "anking-reproductive-system-pathology-2150", "fuente": "anking", "tema": 8, "anki": "1463172253954", "q": "What is the most widely supported theory explaining the etiology of endometriosis?", "o": {"A": "Retrograde menstruation", "B": "Direct hematogenous spread from the ovary", "C": "Autoimmune destruction of the myometrium", "D": "Congenital Müllerian duct fusion defect"}, "r": "A", "e": {"correcta": "The retrograde menstruation theory holds that menstrual blood containing viable endometrial cells flows backward through the fallopian tubes into the pelvic cavity instead of exiting the body, allowing these cells to implant at ectopic sites such as the ovary (as simple cuboidal cells) or peritoneum (as simple squamous cells), and from there to spread wherever peritoneal contact occurs.", "incorrectas": {"B": "Hematogenous spread is not the leading theory for endometriosis; when it is invoked at all, it is a minor proposed mechanism for rare distant-site disease, not the primary explanation taught for typical pelvic endometriosis.", "C": "Endometriosis is not primarily considered an autoimmune process targeting the myometrium; it is ectopic endometrial tissue implantation, and the myometrium is not the site of destruction in this disease.", "D": "A congenital Müllerian fusion defect describes structural anomalies like a bicornuate or septate uterus, a developmental issue distinct from the acquired, cyclic implantation of endometrial tissue seen in endometriosis."}}}, {"id": "anking-reproductive-system-pathology-2151", "fuente": "anking", "tema": 8, "anki": "1463172258965", "q": "Besides retrograde menstruation, another proposed mechanism for endometriosis involves which cellular process affecting multipotent cells?", "o": {"A": "Apoptosis", "B": "Metaplastic transformation", "C": "Dysplasia", "D": "Anaplasia"}, "r": "B", "e": {"correcta": "The metaplastic theory proposes that multipotent cells lining the peritoneum or other pelvic structures can undergo metaplastic transformation directly into endometrial-type tissue, explaining cases of endometriosis found at sites retrograde menstruation could not easily reach.", "incorrectas": {"A": "Apoptosis is programmed cell death, the opposite of the tissue formation seen in endometriosis, and is not a proposed causative mechanism.", "C": "Dysplasia refers to disordered, potentially premalignant cellular growth, which is not the process by which normal multipotent cells are thought to give rise to ectopic endometrial tissue.", "D": "Anaplasia describes a loss of differentiation typical of malignant cells, which is not implicated in the benign process of endometriosis formation."}}}, {"id": "anking-reproductive-system-pathology-2152", "fuente": "anking", "tema": 8, "anki": "1463172263963", "q": "One proposed theory for the spread of endometrial tissue to distant sites in endometriosis involves transportation via which system?", "o": {"A": "Lymphatic system", "B": "Portal venous system", "C": "Cerebrospinal fluid pathways", "D": "Biliary system"}, "r": "A", "e": {"correcta": "The lymphatic (and vascular) dissemination theory proposes that endometrial cells can be transported through lymphatic channels to explain cases of endometriosis occurring at sites distant from the pelvis, such as the lungs or lymph nodes, where retrograde menstruation could not account for the implant.", "incorrectas": {"B": "The portal venous system drains the gastrointestinal tract to the liver and is not a pathway implicated in endometrial tissue dissemination.", "C": "Cerebrospinal fluid pathways are relevant to central nervous system tumor spread (e.g., medulloblastoma drop metastases), not to endometrial tissue dissemination.", "D": "The biliary system carries bile from the liver to the duodenum and has no role in the spread of endometrial tissue."}}}, {"id": "anking-reproductive-system-pathology-2153", "fuente": "anking", "tema": 8, "anki": "1463172268325", "q": "What is the most common anatomic site to which endometriosis spreads?", "o": {"A": "Bladder", "B": "Ovary", "C": "Bowel serosa", "D": "Fallopian tube mucosa"}, "r": "B", "e": {"correcta": "The ovary is the most common site of endometriosis. On biopsy, the ovarian surface epithelium is simple cuboidal, and its high turnover to repair defects from repeated ovulation is thought to contribute to its susceptibility to ectopic endometrial implantation, which can form a blood-filled 'chocolate cyst' (endometrioma).", "incorrectas": {"A": "The bladder can be involved in endometriosis, causing dysuria, but it is a less common site than the ovary.", "C": "The bowel serosa can be affected, causing abdominal pain and adhesions, but this is also less frequent than ovarian involvement.", "D": "The fallopian tube mucosa can be affected, raising risk of ectopic pregnancy and infertility, but it is not the single most common site of spread."}}}, {"id": "anking-reproductive-system-pathology-2154", "fuente": "anking", "tema": 8, "anki": "1463172272323", "q": "On imaging or gross pathology, an ovarian mass filled with old, degenerated blood from cyclic endometrial bleeding is classically described as what?", "o": {"A": "Dermoid cyst", "B": "Chocolate cyst", "C": "Serous cystadenoma", "D": "Corpus luteum cyst"}, "r": "B", "e": {"correcta": "An ovarian endometrioma is classically called a 'chocolate cyst' because it is filled with dark, thick, old blood-like fluid that accumulates from cyclic bleeding of ectopic endometrial tissue implanted within the ovary.", "incorrectas": {"A": "A dermoid cyst (mature cystic teratoma) contains tissue from multiple germ layers such as hair, teeth, and sebaceous material, not accumulated menstrual blood products.", "C": "A serous cystadenoma is a benign ovarian epithelial tumor filled with thin, clear serous fluid, unrelated to endometriosis.", "D": "A corpus luteum cyst forms from a persistent corpus luteum and may contain blood, but it is a normal physiologic/functional cyst rather than the classic chocolate cyst produced by ectopic endometrial tissue."}}}, {"id": "anking-reproductive-system-pathology-2155", "fuente": "anking", "tema": 8, "anki": "1463172280966", "q": "When endometriosis involves the peritoneal soft tissue surfaces, the small dark implants are classically described using which descriptive term?", "o": {"A": "\"Gun-powder\" lesions", "B": "\"Coffee bean\" sign", "C": "\"Onion skin\" lesions", "D": "\"Cannonball\" lesions"}, "r": "A", "e": {"correcta": "Peritoneal and other soft tissue implants of endometriosis classically appear as small, dark-brown to black \"gun-powder\" lesions, reflecting old hemorrhage from cyclic bleeding of the ectopic endometrial tissue.", "incorrectas": {"B": "The \"coffee bean\" sign refers to a radiographic finding in sigmoid volvulus, an unrelated gastrointestinal condition.", "C": "\"Onion skin\" lesions describe the periosteal reaction seen in Ewing sarcoma on imaging, not a gynecologic finding.", "D": "\"Cannonball\" lesions describe large, round metastases classically seen in the lungs from renal cell carcinoma or choriocarcinoma, unrelated to endometriosis."}}}, {"id": "anking-reproductive-system-pathology-2156", "fuente": "anking", "tema": 8, "anki": "1463172294631", "q": "A patient with known endometriosis develops cyclic painful urination. Endometriosis spread to which structure most likely explains this symptom?", "o": {"A": "Bladder wall", "B": "Ovary", "C": "Cervix", "D": "Vagina"}, "r": "A", "e": {"correcta": "When ectopic endometrial tissue implants in the bladder wall, cyclic bleeding and inflammation there produce dysuria, often worsening around menses, reflecting the hormone-responsive nature of the ectopic tissue.", "incorrectas": {"B": "Ovarian involvement (the most common site) classically presents with a chocolate cyst/endometrioma and pelvic pain or a mass, not specifically dysuria.", "C": "Cervical involvement is uncommon and would not typically present primarily with dysuria, which points more specifically to bladder wall involvement.", "D": "Vaginal involvement can cause dyspareunia or visible lesions but is not the classic site associated with dysuria."}}}, {"id": "anking-reproductive-system-pathology-2157", "fuente": "anking", "tema": 8, "anki": "1463172298323", "q": "Endometriosis involving the bowel serosa most classically presents with which symptoms?", "o": {"A": "Dysuria and hematuria", "B": "Abdominal pain and adhesions", "C": "Painless rectal bleeding", "D": "Chronic diarrhea and malabsorption"}, "r": "B", "e": {"correcta": "Ectopic endometrial implants on the bowel serosa incite a cyclic inflammatory and fibrotic response, leading to abdominal pain and the formation of adhesions, which can also contribute to bowel obstruction or infertility from pelvic scarring.", "incorrectas": {"A": "Dysuria and hematuria would suggest bladder wall involvement rather than bowel serosal disease.", "C": "Painless rectal bleeding is more characteristic of a mucosal process like colorectal polyps or cancer, not the serosal (outer) surface implantation typical of endometriosis.", "D": "Chronic diarrhea and malabsorption suggest a mucosal or small bowel absorptive disorder (e.g., celiac disease), not the serosal adhesive disease caused by endometriosis."}}}, {"id": "anking-reproductive-system-pathology-2158", "fuente": "anking", "tema": 8, "anki": "1463172301905", "q": "Endometriosis involving the fallopian tube mucosa increases the risk of which two complications?", "o": {"A": "Ectopic tubal pregnancy and infertility", "B": "Ovarian torsion and hydrosalpinx", "C": "Uterine rupture and placenta accreta", "D": "Cervical incompetence and preterm labor"}, "r": "A", "e": {"correcta": "Endometrial implants within the fallopian tube mucosa can distort normal tubal architecture and function, impairing the transport of the fertilized egg and increasing the risk of ectopic (tubal) pregnancy, while the associated scarring and adhesions also raise the risk of infertility.", "incorrectas": {"B": "Ovarian torsion is a mechanical twisting event related to ovarian mass or mobility, and hydrosalpinx is fluid accumulation from tubal obstruction (often post-infectious), neither of which is the classic pairing taught for tubal mucosal endometriosis.", "C": "Uterine rupture and placenta accreta relate to abnormal myometrial integrity or abnormal placental invasion, conditions unrelated to tubal mucosal endometrial implants.", "D": "Cervical incompetence and preterm labor are obstetric complications related to cervical structural weakness, not consequences of endometriosis in the fallopian tube."}}}, {"id": "anking-reproductive-system-pathology-2159", "fuente": "anking", "tema": 8, "anki": "1463172307168", "q": "The presence of ectopic endometrial glands and stroma within the uterine myometrium is known as what condition?", "o": {"A": "Leiomyoma", "B": "Adenomyosis", "C": "Endometrial hyperplasia", "D": "Endocervical polyp"}, "r": "B", "e": {"correcta": "Adenomyosis is defined as endometrial tissue (glands and stroma) present within the myometrium, essentially endometriosis of the uterine muscle wall itself, presenting with dysmenorrhea, menorrhagia, and a uniformly enlarged, soft, globular uterus.", "incorrectas": {"A": "A leiomyoma is a benign smooth muscle tumor (fibroid) arising from the myometrium itself, a proliferation of muscle cells rather than ectopic endometrial glandular tissue.", "C": "Endometrial hyperplasia is confined to the endometrial lining itself (excess glandular proliferation from unopposed estrogen), not tissue found within the myometrium.", "D": "An endocervical polyp is a localized benign growth of the cervical canal lining, an entirely different anatomic location from the myometrium."}}}, {"id": "anking-reproductive-pharmacology-2160", "fuente": "anking", "tema": 3, "anki": "1463172319857", "q": "Continuous (non-pulsatile) administration of which hormone class can be used medically to treat adenomyosis by suppressing gonadotropin release?", "o": {"A": "Estrogen", "B": "GnRH agonists", "C": "Progesterone antagonists", "D": "Androgen receptor blockers"}, "r": "B", "e": {"correcta": "Continuous (rather than the normal pulsatile) administration of GnRH agonists desensitizes pituitary GnRH receptors, ultimately suppressing LH/FSH release and inducing a hypoestrogenic state that reduces the hormone-responsive endometrial tissue found in adenomyosis; definitive treatment remains hysterectomy.", "incorrectas": {"A": "Estrogen would stimulate rather than suppress the ectopic and eutopic endometrial tissue, worsening rather than treating adenomyosis.", "C": "Progesterone antagonists (like mifepristone) act at progesterone receptors, a different hormonal axis than the GnRH-pituitary-gonadal suppression achieved with continuous GnRH agonist therapy.", "D": "Androgen receptor blockers act on androgen signaling (used in conditions like prostate cancer or hirsutism) and are not the mechanism used to treat adenomyosis."}}}, {"id": "anking-neoplasia-2161", "fuente": "anking", "tema": 14, "anki": "1463172327723", "q": "Sites of endometriosis, especially in the ovary, carry an increased long-term risk of developing what?", "o": {"A": "Carcinoma", "B": "Tuberculosis", "C": "Pelvic inflammatory disease", "D": "Uterine prolapse"}, "r": "A", "e": {"correcta": "Chronic ectopic endometrial tissue, particularly within ovarian endometriomas, undergoes repeated cycles of proliferation, bleeding, and repair, which over time raises the risk of malignant transformation into carcinoma (most notably endometrioid and clear cell ovarian carcinomas).", "incorrectas": {"B": "Tuberculosis is an infectious cause of chronic endometritis, not a complication that arises from pre-existing endometriosis.", "C": "Pelvic inflammatory disease is typically caused by ascending sexually transmitted infections, not a long-term consequence of ectopic endometrial implants.", "D": "Uterine prolapse results from weakened pelvic floor support structures, unrelated to the malignant potential of endometriotic tissue."}}}, {"id": "anking-reproductive-system-pathology-2162", "fuente": "anking", "tema": 8, "anki": "1463172336780", "q": "A condition defined by proliferation of endometrial glands out of proportion to the surrounding stroma is called what?", "o": {"A": "Endometrial hyperplasia", "B": "Endometrial polyp", "C": "Adenomyosis", "D": "Endometrial carcinoma"}, "r": "A", "e": {"correcta": "Endometrial hyperplasia is defined as hyperplasia of the endometrial glands relative to the stroma, typically driven by unopposed estrogen stimulation without the counterbalancing effect of progesterone.", "incorrectas": {"B": "An endometrial polyp is a discrete, well-circumscribed protrusion of endometrial tissue, a localized structural lesion rather than the diffuse gland-to-stroma ratio change that defines hyperplasia.", "C": "Adenomyosis involves ectopic endometrial glands and stroma within the myometrium, a different anatomic problem from an abnormal gland-to-stroma ratio within the endometrium itself.", "D": "Endometrial carcinoma is a malignant, invasive glandular proliferation, a more advanced and distinct entity from the pre-malignant hyperplastic process."}}}, {"id": "anking-reproductive-system-pathology-2163", "fuente": "anking", "tema": 8, "anki": "1463172359613", "q": "Endometrial hyperplasia typically presents with abnormal uterine bleeding occurring in which clinical context?", "o": {"A": "Premenopausal only", "B": "Postmenopausal", "C": "Exclusively during pregnancy", "D": "Only during adolescence"}, "r": "B", "e": {"correcta": "Endometrial hyperplasia classically presents as postmenopausal uterine bleeding, since risk factors like obesity, unopposed estrogen therapy, and anovulatory states become more prevalent with age, and any bleeding after menopause warrants evaluation to exclude hyperplasia or carcinoma.", "incorrectas": {"A": "While hyperplasia can occur in premenopausal women (e.g., with PCOS-related chronic anovulation), the classic, high-yield presentation emphasized is postmenopausal bleeding.", "C": "Pregnancy involves a distinct hormonal milieu with high progesterone from the corpus luteum and placenta, actively opposing the unopposed estrogen effect that drives hyperplasia.", "D": "Adolescents can have anovulatory cycles causing abnormal bleeding, but endometrial hyperplasia as a distinct pathologic diagnosis is not the classic adolescent presentation; it is emphasized in the postmenopausal population."}}}, {"id": "anking-reproductive-system-pathology-2164", "fuente": "anking", "tema": 8, "anki": "1463172379407", "q": "Endometrial hyperplasia is histologically classified based on architectural growth pattern (simple vs. complex) and the presence or absence of which additional feature?", "o": {"A": "Vascular invasion", "B": "Cellular atypia", "C": "Mitotic rate greater than 50 per high-power field", "D": "Necrosis"}, "r": "B", "e": {"correcta": "Endometrial hyperplasia is classified along two axes: the architectural growth pattern of the glands (simple or complex) and whether cellular (cytologic) atypia is present or absent, with atypia being the single most important predictor of progression to carcinoma.", "incorrectas": {"A": "Vascular invasion is a feature assessed in established malignancy to determine staging and prognosis, not part of the histologic classification scheme for hyperplasia itself.", "C": "A specific mitotic rate cutoff is not the classification criterion used for endometrial hyperplasia; the key distinguishing features are architecture and atypia.", "D": "Necrosis is more characteristic of high-grade or advanced malignant tumors, not part of the standard classification of hyperplasia."}}}, {"id": "anking-reproductive-system-pathology-2165", "fuente": "anking", "tema": 8, "anki": "1463172386929", "q": "Among the histologic features of endometrial hyperplasia, which is the most important predictor of progression to carcinoma?", "o": {"A": "Simple architectural pattern", "B": "Cellular atypia", "C": "Presence of plasma cells", "D": "Gland-to-stroma ratio alone"}, "r": "B", "e": {"correcta": "Cellular (cytologic) atypia is the most important predictor of whether endometrial hyperplasia will progress to carcinoma; hyperplasia with atypia carries a substantially higher risk of malignant transformation than hyperplasia without atypia, regardless of architectural pattern.", "incorrectas": {"A": "A simple architectural pattern (versus complex) is a lower-risk feature on its own, but architecture alone is not as strong a predictor of malignant progression as the presence of atypia.", "C": "Plasma cells are a marker of chronic endometritis (an inflammatory condition), not a feature used to grade hyperplasia or predict its malignant potential.", "D": "The gland-to-stroma ratio helps define hyperplasia itself, but it is the added presence of cytologic atypia—not architecture or ratio alone—that most strongly predicts progression to cancer."}}}, {"id": "anking-reproductive-system-pathology-2166", "fuente": "anking", "tema": 8, "anki": "1463172390498", "q": "Between simple and complex architectural patterns of endometrial hyperplasia, which carries a higher risk of progression to carcinoma?", "o": {"A": "Simple", "B": "Complex", "C": "Both carry identical risk", "D": "Neither progresses to carcinoma"}, "r": "B", "e": {"correcta": "The complex architectural pattern, characterized by more crowded, irregularly branching glands with less intervening stroma, carries a higher risk of progression to carcinoma than the simple pattern, especially when combined with cytologic atypia.", "incorrectas": {"A": "The simple pattern shows more widely spaced, less crowded glands and carries a comparatively lower risk of malignant progression than the complex pattern.", "C": "The two patterns do not carry identical risk; complex architecture (particularly with atypia) confers meaningfully greater malignant potential than simple architecture.", "D": "Both patterns of hyperplasia, especially when atypia is present, can progress to carcinoma over time, so it is incorrect to say neither ever progresses."}}}, {"id": "anking-neoplasia-2167", "fuente": "anking", "tema": 14, "anki": "1463172394153", "q": "Endometrial hyperplasia, particularly when accompanied by cellular atypia, carries an increased risk of progression to which condition?", "o": {"A": "Endometrial carcinoma", "B": "Cervical carcinoma", "C": "Ovarian teratoma", "D": "Vulvar carcinoma"}, "r": "A", "e": {"correcta": "Endometrial hyperplasia represents a precursor lesion on the pathway to endometrial carcinoma; unopposed estrogen drives progressive glandular proliferation and, when atypia develops, the risk of transformation into invasive endometrial adenocarcinoma rises substantially.", "incorrectas": {"B": "Cervical carcinoma is driven predominantly by high-risk HPV infection of the cervical transformation zone, a distinct etiology and anatomic site from endometrial hyperplasia.", "C": "Ovarian teratomas arise from totipotent germ cells and contain tissue from multiple germ layers; they are not a progression of endometrial gland hyperplasia.", "D": "Vulvar carcinoma arises from the vulvar squamous epithelium, often related to HPV or chronic dermatologic conditions like lichen sclerosus, unrelated to endometrial gland pathology."}}}, {"id": "anking-neoplasia-2168", "fuente": "anking", "tema": 14, "anki": "1463172398226", "q": "What is the most common invasive (malignant) carcinoma of the female genital tract?", "o": {"A": "Cervical carcinoma", "B": "Endometrial carcinoma", "C": "Vulvar carcinoma", "D": "Vaginal carcinoma"}, "r": "B", "e": {"correcta": "Endometrial carcinoma is the most common invasive malignant carcinoma of the female genital tract, most often arising in postmenopausal women, frequently from a background of unopposed estrogen exposure and endometrial hyperplasia.", "incorrectas": {"A": "Cervical carcinoma, while historically significant and HPV-driven, is less common than endometrial carcinoma in regions with routine Pap smear screening, which detects and treats precursor lesions before invasion.", "C": "Vulvar carcinoma is a much rarer malignancy of the female genital tract compared to endometrial carcinoma.", "D": "Vaginal carcinoma is one of the rarest gynecologic malignancies, far less common than endometrial carcinoma."}}}, {"id": "anking-neoplasia-2169", "fuente": "anking", "tema": 14, "anki": "1463172406630", "q": "In approximately 25% of endometrial carcinoma cases, the tumor arises in an atrophic endometrium without any identifiable precursor lesion. This is known as which pathway?", "o": {"A": "Estrogen-dependent (Type I) pathway", "B": "Sporadic pathway", "C": "Lynch syndrome pathway", "D": "HPV-mediated pathway"}, "r": "B", "e": {"correcta": "The sporadic pathway accounts for roughly 25% of endometrial carcinomas and is characterized by tumor arising from an atrophic (not hyperplastic) endometrium with no identifiable precursor lesion, in contrast to the more common estrogen-driven pathway that progresses through endometrial hyperplasia.", "incorrectas": {"A": "The estrogen-dependent (Type I) pathway is the more common route (about 75-80% of cases), progressing from unopposed estrogen exposure through endometrial hyperplasia to low-grade endometrioid carcinoma, the opposite scenario from arising in an atrophic endometrium with no precursor.", "C": "Lynch syndrome (hereditary nonpolyposis colorectal cancer) increases lifetime risk of endometrial carcinoma through inherited DNA mismatch repair gene mutations, a genetic predisposition rather than the description of a sporadic, precursor-free tumor arising in atrophic tissue.", "D": "HPV-mediated carcinogenesis is the mechanism behind cervical and some vulvar/vaginal cancers, not endometrial carcinoma, which is not caused by HPV."}}}, {"id": "anking-neoplasia-2170", "fuente": "anking", "tema": 14, "anki": "1463172415056", "q": "A malignant proliferation of endometrial glands with invasive potential is termed what?", "o": {"A": "Endometrial polyp", "B": "Endometrial hyperplasia", "C": "Endometrial carcinoma", "D": "Adenomyosis"}, "r": "C", "e": {"correcta": "Endometrial carcinoma is defined as a malignant proliferation of endometrial glands capable of local invasion into the myometrium and beyond, distinguishing it from benign or pre-malignant glandular processes of the endometrium.", "incorrectas": {"A": "An endometrial polyp is a benign, well-circumscribed protrusion of endometrial tissue without malignant or invasive features.", "B": "Endometrial hyperplasia is a proliferative but non-invasive process, considered a precursor lesion rather than a malignancy itself.", "D": "Adenomyosis is the benign presence of endometrial glands and stroma within the myometrium, without the malignant transformation that defines carcinoma."}}}, {"id": "anking-neoplasia-2171", "fuente": "anking", "tema": 14, "anki": "1463172439331", "q": "Endometrial carcinoma most classically presents with bleeding occurring in which clinical setting?", "o": {"A": "Premenarchal bleeding", "B": "Postmenopausal bleeding", "C": "Mid-cycle spotting only", "D": "Bleeding exclusively during pregnancy"}, "r": "B", "e": {"correcta": "Endometrial carcinoma classically presents as postmenopausal bleeding, which is why any vaginal bleeding after menopause must be promptly evaluated (often with endometrial biopsy) to rule out malignancy, given that the tumor typically arises in older women with a history of estrogen exposure unopposed by progesterone.", "incorrectas": {"A": "Premenarchal bleeding, occurring before the onset of puberty, points toward entirely different causes such as precocious puberty or vaginal foreign bodies, not endometrial carcinoma, which occurs in older women.", "C": "Mid-cycle spotting is typically a benign phenomenon related to the estrogen dip around ovulation in reproductive-age women, not the classic presentation of endometrial carcinoma.", "D": "Bleeding during pregnancy suggests obstetric complications like placental abruption or previa, an entirely different clinical scenario from postmenopausal endometrial carcinoma."}}}, {"id": "anking-reproductive-system-pathology-2172", "fuente": "anking", "tema": 8, "anki": "1463172445552", "q": "Endometrial carcinoma is classically described as arising via two distinct pathogenic pathways. Which two pathways are these?", "o": {"A": "Hyperplasia pathway and sporadic pathway", "B": "Adenomyosis pathway and metaplasia pathway", "C": "Lynch syndrome pathway and BRCA pathway", "D": "HPV-driven pathway and radiation-induced pathway"}, "r": "A", "e": {"correcta": "Endometrial carcinoma arises via two pathways: the hyperplasia (estrogen-driven, type I/endometrioid) pathway, which follows a precursor lesion of endometrial hyperplasia typically related to unopposed estrogen, and the sporadic (type II, non-estrogen-related) pathway, which arises de novo in atrophic endometrium and is more aggressive, often serous or clear cell histology.", "incorrectas": {"B": "Adenomyosis (endometrium within myometrium) and metaplasia are not recognized pathogenic pathways for endometrial carcinoma; adenomyosis is a distinct benign condition unrelated to the two carcinogenesis pathways.", "C": "Lynch syndrome and BRCA mutations are risk factors/genetic syndromes associated with increased cancer risk (colon/endometrial and breast/ovarian respectively), but they are not themselves the two named pathophysiologic pathways of endometrial carcinoma.", "D": "HPV drives cervical carcinoma, not endometrial carcinoma, and radiation-induced carcinogenesis is not a described pathway for endometrial cancer; this option confuses cervical cancer pathogenesis with endometrial cancer pathogenesis."}}}, {"id": "anking-reproductive-system-pathology-2173", "fuente": "anking", "tema": 8, "anki": "1463172499947", "q": "A woman presents with endometrial carcinoma arising through the hyperplasia (estrogen-driven) pathway. What is the average age of presentation for this pathway?", "o": {"A": "40 years", "B": "50 years", "C": "60 years", "D": "70 years"}, "r": "C", "e": {"correcta": "The hyperplasia pathway of endometrial carcinoma, driven by chronic unopposed estrogen exposure leading to endometrial hyperplasia and then carcinoma, presents on average around age 60, somewhat younger than the sporadic pathway.", "incorrectas": {"A": "Age 40 is too young for either endometrial carcinoma pathway; endometrial cancer overall is a disease of postmenopausal or perimenopausal women, with the hyperplasia pathway centering closer to age 60.", "B": "Age 50 is below the typical presentation age for the hyperplasia pathway; while hyperplasia can begin perimenopausally, frank carcinoma from this pathway averages around a decade later.", "D": "Age 70 is the average age of presentation for the sporadic (type II) pathway, which is not estrogen-driven and behaves more aggressively, not the hyperplasia pathway described here."}}}, {"id": "anking-reproductive-system-pathology-2174", "fuente": "anking", "tema": 8, "anki": "1463172503888", "q": "The sporadic pathway of endometrial carcinoma, which is not estrogen-related and exhibits aggressive behavior, has an average age of presentation of approximately how many years?", "o": {"A": "50 years", "B": "60 years", "C": "70 years", "D": "80 years"}, "r": "C", "e": {"correcta": "The sporadic pathway of endometrial carcinoma presents at an average age of about 70 years, roughly a decade later than the hyperplasia pathway, and is characterized by more aggressive tumor behavior (often serous or clear cell histology arising in atrophic endometrium).", "incorrectas": {"A": "Age 50 is too young; neither endometrial carcinoma pathway typically presents this early, as endometrial cancer risk rises substantially after menopause.", "B": "Age 60 corresponds to the average presentation age of the hyperplasia (estrogen-driven) pathway, not the sporadic pathway, which presents about a decade later.", "D": "Age 80 overestimates the average presentation age; while sporadic-pathway tumors can occur in very elderly women, the classically cited average is closer to 70."}}}, {"id": "anking-genetics-2175", "fuente": "anking", "tema": 45, "anki": "1463172506951", "q": "Endometrial carcinoma arising via the sporadic (non-estrogen-related, aggressive) pathway is most commonly associated with mutation of which gene?", "o": {"A": "KRAS", "B": "PTEN", "C": "p53", "D": "APC"}, "r": "C", "e": {"correcta": "The sporadic pathway of endometrial carcinoma is characterized by p53 mutations, consistent with its more aggressive behavior and its association with serous-type carcinoma arising in atrophic endometrium rather than through a hyperplastic precursor.", "incorrectas": {"A": "KRAS mutations are more associated with mucinous ovarian tumors and various other carcinomas (e.g., colorectal, pancreatic), not the classic mutation defining the sporadic endometrial carcinoma pathway.", "B": "PTEN mutations are characteristic of the hyperplasia (estrogen-driven, endometrioid) pathway of endometrial carcinoma, not the sporadic pathway; PTEN loss promotes unchecked PI3K/AKT signaling in hyperplastic endometrium.", "D": "APC mutations are hallmark of the adenoma-carcinoma sequence in colorectal cancer (both sporadic and FAP-associated), not endometrial carcinoma pathogenesis."}}}, {"id": "anking-reproductive-system-pathology-2176", "fuente": "anking", "tema": 8, "anki": "1463172517382", "q": "Risk factors for endometrial carcinoma arising via the hyperplasia pathway (early menarche/late menopause, nulliparity, anovulatory cycles, obesity) all share which common underlying mechanism?", "o": {"A": "Chronic estrogen exposure", "B": "Chronic progesterone exposure", "C": "Chronic androgen exposure", "D": "Chronic prolactin exposure"}, "r": "A", "e": {"correcta": "All of these risk factors converge on increased lifetime estrogen exposure unopposed by progesterone: early menarche and late menopause extend the estrogenic window, nulliparity and anovulatory infertility mean fewer progesterone-dominant luteal phases, and obesity increases peripheral aromatization of androgens to estrone in adipose tissue, all driving endometrial hyperplasia that can progress to carcinoma.", "incorrectas": {"B": "Progesterone actually opposes estrogen's proliferative effect on the endometrium; it is a deficiency or relative lack of progesterone (as in anovulatory cycles), not excess progesterone exposure, that predisposes to hyperplasia and carcinoma.", "C": "While hyperandrogenism (as in PCOS) contributes indirectly by causing anovulation, the direct proliferative driver of endometrial hyperplasia and hyperplasia-pathway carcinoma is estrogen, not androgen itself.", "D": "Prolactin excess causes hypogonadism and amenorrhea but is not the mechanism linking these specific risk factors (early menarche, nulliparity, obesity) to endometrial carcinoma; the unifying factor is unopposed estrogen."}}}, {"id": "anking-genetics-2177", "fuente": "anking", "tema": 45, "anki": "1463172529545", "q": "A 45-year-old woman with a strong family history of colon cancer is diagnosed with endometrial carcinoma. Genetic testing reveals a germline mutation in a DNA mismatch repair gene. Which autosomal dominant syndrome, which increases risk of colon, ovarian, and endometrial carcinoma, does she likely have?", "o": {"A": "Familial adenomatous polyposis", "B": "Peutz-Jeghers syndrome", "C": "Lynch syndrome (HNPCC)", "D": "Li-Fraumeni syndrome"}, "r": "C", "e": {"correcta": "Lynch syndrome (hereditary nonpolyposis colorectal cancer, HNPCC) is an autosomal dominant disorder caused by germline mutations in DNA mismatch repair genes (e.g., MLH1, MSH2), leading to microsatellite instability and increased risk of colorectal cancer as well as extracolonic cancers, most notably endometrial and ovarian carcinoma.", "incorrectas": {"B": "Peutz-Jeghers syndrome is characterized by hamartomatous GI polyps and mucocutaneous hyperpigmentation with increased risk of various cancers (including some gynecologic tumors like sex cord tumors with annular tubules), but it is not the classic autosomal dominant syndrome linking colon, ovarian, and endometrial carcinoma via mismatch repair defects.", "A": "Familial adenomatous polyposis is caused by APC mutations, causes thousands of colonic adenomatous polyps progressing to colorectal cancer, but is not specifically associated with the triad of colon, ovarian, and endometrial cancer seen in Lynch syndrome.", "D": "Li-Fraumeni syndrome results from germline p53 mutations and predisposes to a broad range of cancers (sarcomas, breast, brain, adrenocortical), but it is not the syndrome classically linked to the colon-ovarian-endometrial cancer triad."}}}, {"id": "anking-reproductive-system-pathology-2178", "fuente": "anking", "tema": 8, "anki": "1463172533352", "q": "What is the most common tumor found in females?", "o": {"A": "Ovarian cystadenoma", "B": "Leiomyoma (fibroid)", "C": "Endometrial carcinoma", "D": "Leiomyosarcoma"}, "r": "B", "e": {"correcta": "Leiomyoma (uterine fibroid) is the most common tumor in females, a benign smooth muscle neoplasm of the myometrium that is estrogen-sensitive and extremely prevalent, especially in women of reproductive age.", "incorrectas": {"A": "Ovarian cystadenoma is the most common benign ovarian tumor specifically, but it is far less common overall than uterine leiomyoma when considering all tumors in females.", "C": "Endometrial carcinoma is a common gynecologic malignancy but is far less prevalent than the benign leiomyoma, which occurs in a very large proportion of women, most of whom are asymptomatic.", "D": "Leiomyosarcoma is a rare malignant tumor of myometrial smooth muscle; it is much less common than its benign counterpart, leiomyoma, and does not approach leiomyoma in overall prevalence."}}}, {"id": "anking-reproductive-system-pathology-2179", "fuente": "anking", "tema": 8, "anki": "1463172536516", "q": "Which demographic has an increased incidence of leiomyoma (uterine fibroid), with peak occurrence between 20-40 years old?", "o": {"A": "Asian American women", "B": "African American women", "C": "Hispanic women", "D": "Caucasian women"}, "r": "B", "e": {"correcta": "African American women have a markedly increased incidence of uterine leiomyomas, with peak occurrence between 20-40 years of age; they also tend to develop fibroids at a younger age and with more numerous or larger tumors compared to other groups.", "incorrectas": {"A": "Asian American women do not show the epidemiologically increased incidence of leiomyoma that is classically highlighted for African American women in USMLE-style teaching.", "C": "Hispanic women are not the demographic classically associated with increased fibroid incidence; this distinction is specifically attributed to African American women.", "D": "Caucasian women have a lower incidence of leiomyoma compared to African American women, who are disproportionately affected by this estrogen-sensitive tumor."}}}, {"id": "anking-reproductive-system-pathology-2180", "fuente": "anking", "tema": 8, "anki": "1463172540111", "q": "A benign neoplastic proliferation of smooth muscle arising from the myometrium is best described as which entity (distinct from a proliferation of endometrium within the myometrium, which is called adenomyosis)?", "o": {"A": "Endometrial polyp", "B": "Leiomyoma (uterine fibroid)", "C": "Leiomyosarcoma", "D": "Endometrial stromal sarcoma"}, "r": "B", "e": {"correcta": "Leiomyoma (uterine fibroid) is a benign neoplastic proliferation of smooth muscle cells arising from the myometrium; it is distinct from adenomyosis, which is the presence of endometrial glands and stroma within the myometrium (not a true neoplasm).", "incorrectas": {"A": "An endometrial polyp is a localized overgrowth of endometrial tissue projecting into the uterine cavity, not a smooth muscle tumor of the myometrium.", "C": "Leiomyosarcoma is the malignant counterpart, a malignant smooth muscle proliferation of the myometrium, whereas the question describes a benign proliferation, which is leiomyoma.", "D": "Endometrial stromal sarcoma is a malignant tumor of endometrial stromal cells, not a smooth muscle tumor, and is unrelated to the benign myometrial process described."}}}, {"id": "anking-reproductive-system-pathology-2181", "fuente": "anking", "tema": 8, "anki": "1463172544045", "q": "Leiomyoma (uterine fibroid) growth is most directly related to exposure to which hormone?", "o": {"A": "Estrogen", "B": "Cortisol", "C": "Testosterone", "D": "Prolactin"}, "r": "A", "e": {"correcta": "Leiomyomas are estrogen-sensitive tumors; their growth is stimulated by estrogen exposure, which is why they tend to enlarge during high-estrogen states like pregnancy and regress after menopause when estrogen levels fall.", "incorrectas": {"B": "Cortisol is not the hormone driving leiomyoma growth; glucocorticoids are not implicated in fibroid pathophysiology.", "C": "Testosterone is not the primary hormonal driver of leiomyoma growth; while androgens can be aromatized to estrogen peripherally, the direct sensitizing hormone for fibroid growth is estrogen itself.", "D": "Prolactin has no established role in stimulating leiomyoma growth; the well-documented estrogen sensitivity of these tumors is the key concept, not prolactin."}}}, {"id": "anking-reproductive-system-pathology-2182", "fuente": "anking", "tema": 8, "anki": "1463172547912", "q": "Because leiomyomas (fibroids) are estrogen-sensitive tumors, during which physiologic state would they be expected to increase in size, and during which would they be expected to decrease?", "o": {"A": "Increase with menopause; decrease with pregnancy", "B": "Increase with pregnancy; decrease with menopause", "C": "Increase with lactation; decrease with pregnancy", "D": "Increase with menopause; decrease with puberty"}, "r": "B", "e": {"correcta": "Leiomyomas are estrogen-sensitive, so they tend to enlarge during pregnancy when estrogen levels are markedly increased, and they tend to shrink after menopause when estrogen production declines significantly.", "incorrectas": {"A": "This reverses the correct relationship: menopause is a low-estrogen state associated with fibroid regression, while pregnancy is a high-estrogen state associated with fibroid growth.", "C": "Lactation is generally a relatively low-estrogen, hyperprolactinemic state and is not classically described as increasing fibroid size; the well-established relationship is growth with pregnancy and regression with menopause.", "D": "Puberty is a rising-estrogen state that could theoretically be associated with fibroid development, but it is not the classic paired contrast used; the standard teaching contrasts pregnancy (increase) with menopause (decrease)."}}}, {"id": "anking-reproductive-system-pathology-2183", "fuente": "anking", "tema": 8, "anki": "1463172572838", "q": "Gross examination of a uterine mass reveals multiple, well-defined, white, whorled masses distorting the uterus and impinging on pelvic structures. What is the most likely diagnosis?", "o": {"A": "Leiomyosarcoma", "B": "Endometrial polyp", "C": "Leiomyoma (fibroid)", "D": "Endometrial carcinoma"}, "r": "C", "e": {"correcta": "Leiomyoma classically presents grossly as multiple, well-circumscribed, white, whorled masses within the myometrium, which can distort the uterine contour and compress adjacent pelvic structures; the whorled appearance reflects the interlacing bundles of benign smooth muscle.", "incorrectas": {"A": "Leiomyosarcoma typically presents as a single mass with areas of hemorrhage and necrosis, in contrast to the multiple, well-defined, white, whorled masses characteristic of the benign leiomyoma.", "B": "Endometrial polyps are localized projections of endometrial tissue into the uterine cavity, not multiple whorled myometrial masses; their gross appearance and location differ substantially from leiomyoma.", "D": "Endometrial carcinoma typically presents as an infiltrative or exophytic endometrial lesion, not as discrete white whorled myometrial masses; the gross description given is classic for leiomyoma, not carcinoma."}}}, {"id": "anking-reproductive-system-pathology-2184", "fuente": "anking", "tema": 8, "anki": "1463172598605", "q": "What is the most common presentation of leiomyoma (fibroid), and if symptoms do occur, what is the most common symptom?", "o": {"A": "Usually causes infertility; when symptomatic, causes pelvic pain", "B": "Usually asymptomatic; when symptomatic, causes heavy menstrual bleeding", "C": "Usually causes constipation; when symptomatic, causes heavy menstrual bleeding", "D": "Usually causes heavy menstrual bleeding; when symptomatic, causes infertility"}, "r": "B", "e": {"correcta": "Most leiomyomas are asymptomatic and discovered incidentally; when they do cause symptoms, the most common is heavy or abnormal uterine bleeding, related to distortion of the endometrial cavity (especially with submucosal fibroids), though infertility and pelvic mass effect (including constipation from posterior fibroids pressing on the colon) can also occur.", "incorrectas": {"A": "Infertility and pelvic pain can occur with fibroids, but they are not the most common overall presentation (asymptomatic) or the most common symptom when symptoms occur (heavy menstrual bleeding).", "C": "Constipation can occur when a posterior fibroid compresses the colon, but this is a less common symptom than heavy menstrual bleeding, and the majority of fibroids remain entirely asymptomatic.", "D": "This reverses the correct hierarchy: the majority of fibroids are asymptomatic, not bleeding, and when symptoms do occur, heavy menstrual bleeding is more common than infertility."}}}, {"id": "anking-hematology-oncology-pathology-2185", "fuente": "anking", "tema": 6, "anki": "1463172608516", "q": "Severe or chronic bleeding caused by a leiomyoma (fibroid) may lead to which hematologic complication?", "o": {"A": "Iron deficiency anemia", "B": "Vitamin B12 deficiency anemia", "C": "Aplastic anemia", "D": "Hemolytic anemia"}, "r": "A", "e": {"correcta": "Chronic heavy menstrual bleeding from a leiomyoma leads to ongoing blood (and thus iron) loss, which can deplete iron stores faster than dietary intake can replace them, resulting in a microcytic, hypochromic iron deficiency anemia.", "incorrectas": {"B": "Vitamin B12 deficiency causes a macrocytic megaloblastic anemia typically due to malabsorption (e.g., pernicious anemia, ileal disease) or dietary deficiency, not chronic blood loss from uterine bleeding.", "C": "Aplastic anemia results from bone marrow failure (e.g., toxins, drugs, viral infections) causing pancytopenia, an entirely different mechanism unrelated to chronic menstrual blood loss.", "D": "Hemolytic anemia results from premature destruction of red blood cells (e.g., autoimmune, mechanical, or intrinsic RBC defects), not from external blood loss as seen with heavy fibroid-related bleeding."}}}, {"id": "anking-reproductive-system-pathology-2186", "fuente": "anking", "tema": 8, "anki": "1463172618384", "q": "A postmenopausal woman is found to have a malignant proliferation of smooth muscle arising from the myometrium. What is this tumor called?", "o": {"A": "Leiomyoma", "B": "Adenomyosis", "C": "Leiomyosarcoma", "D": "Endometrial stromal sarcoma"}, "r": "C", "e": {"correcta": "Leiomyosarcoma is a malignant proliferation of smooth muscle arising from the myometrium, typically seen in postmenopausal women, and is distinguished from the far more common benign leiomyoma by its malignant behavior and different gross/histologic features (single mass with necrosis/hemorrhage).", "incorrectas": {"A": "Leiomyoma is the benign counterpart of smooth muscle proliferation in the myometrium; it does not exhibit malignant behavior and is far more common, typically in reproductive-age women rather than specifically postmenopausal women.", "B": "Adenomyosis is the presence of endometrial glands and stroma within the myometrium, a benign condition, not a neoplastic smooth muscle proliferation.", "D": "Endometrial stromal sarcoma arises from malignant proliferation of endometrial stromal cells, not smooth muscle, making it histogenetically distinct from leiomyosarcoma."}}}, {"id": "anking-reproductive-system-pathology-2187", "fuente": "anking", "tema": 8, "anki": "1463172633135", "q": "What is the precursor lesion for uterine leiomyosarcoma?", "o": {"A": "Leiomyoma", "B": "Endometrial hyperplasia", "C": "None; it arises de novo and does not develop from leiomyoma", "D": "Adenomyosis"}, "r": "C", "e": {"correcta": "Leiomyosarcoma has no known precursor lesion; it arises de novo from myometrial smooth muscle and does not develop from pre-existing leiomyomas, despite the intuitive assumption that a malignant smooth muscle tumor would progress from a benign one.", "incorrectas": {"A": "Although leiomyoma and leiomyosarcoma both arise from myometrial smooth muscle, leiomyosarcoma does not develop from a leiomyoma; malignant transformation of a benign fibroid into leiomyosarcoma essentially does not occur.", "B": "Endometrial hyperplasia is the precursor lesion for hyperplasia-pathway endometrial carcinoma (a glandular epithelial tumor), not for leiomyosarcoma, which is a mesenchymal smooth muscle tumor.", "D": "Adenomyosis is a benign condition involving endometrial tissue within the myometrium and is not a recognized precursor to leiomyosarcoma."}}}, {"id": "anking-reproductive-system-pathology-2188", "fuente": "anking", "tema": 8, "anki": "1463172638754", "q": "Gross examination of the uterus reveals a single lesion with areas of necrosis and hemorrhage. This finding is most consistent with which diagnosis (as opposed to multiple, well-defined, white, whorled masses)?", "o": {"A": "Leiomyoma", "B": "Leiomyosarcoma", "C": "Endometrial polyp", "D": "Adenomyosis"}, "r": "B", "e": {"correcta": "Leiomyosarcoma classically presents grossly as a single lesion with areas of necrosis and hemorrhage, reflecting its rapid, disorganized malignant growth that outstrips its blood supply, in contrast to the benign leiomyoma's multiple, well-defined, white, whorled appearance.", "incorrectas": {"A": "Leiomyoma typically presents as multiple, well-defined, white, whorled masses without significant necrosis or hemorrhage, the opposite gross pattern from what is described in this question.", "C": "Endometrial polyps are localized endometrial projections into the uterine cavity, not myometrial masses with necrosis and hemorrhage; their gross appearance differs substantially from leiomyosarcoma.", "D": "Adenomyosis presents as a diffusely thickened, boggy myometrium due to ectopic endometrial tissue, not as a discrete single necrotic and hemorrhagic mass."}}}, {"id": "anking-reproductive-system-anatomy-2189", "fuente": "anking", "tema": 34, "anki": "1463174905508", "q": "An ovarian follicle consists of an oocyte surrounded by which two supporting cell types?", "o": {"A": "Sertoli and Leydig cells", "B": "Granulosa and theca cells", "C": "Cumulus and corona radiata cells only", "D": "Stromal and hilus cells"}, "r": "B", "e": {"correcta": "An ovarian follicle is composed of an oocyte surrounded by granulosa cells (which produce estrogen via aromatization and respond to FSH) and an outer layer of theca cells (which respond to LH to produce androgen precursors that granulosa cells convert to estrogen), together forming the functional hormone-producing unit of the follicle.", "incorrectas": {"A": "Sertoli and Leydig cells are the male gonadal analogues to granulosa and theca cells, respectively, but they are testicular cell types, not the cells surrounding an oocyte in the ovarian follicle.", "C": "Cumulus oophorus and corona radiata are specific granulosa cell layers immediately around the oocyte, but this option omits the theca cell layer, which is an essential second component of the follicle described in the classic granulosa-theca model.", "D": "Stromal and hilus cells are ovarian interstitial and hilar cell populations (hilus cells resemble testicular Leydig cells and can secrete androgens), but they are not the primary cells directly surrounding the oocyte within a developing follicle."}}}, {"id": "anking-reproductive-system-pathology-2190", "fuente": "anking", "tema": 8, "anki": "1463176730505", "q": "Hemorrhage into a corpus luteum, especially during early pregnancy, can result in which type of ovarian cyst?", "o": {"A": "Follicular cyst", "B": "Hemorrhagic corpus luteal cyst", "C": "Endometrioma", "D": "Theca lutein cyst"}, "r": "B", "e": {"correcta": "A hemorrhagic corpus luteal cyst forms when there is bleeding into the corpus luteum (the yellow, hormone-producing structure that persists after ovulation, especially to support early pregnancy); this can cause acute pelvic pain and, if it ruptures, hemoperitoneum.", "incorrectas": {"A": "A follicular cyst results from an unruptured graafian follicle failing to rupture or resorb, a different mechanism from hemorrhage into an already-formed corpus luteum.", "C": "An endometrioma is a cystic collection of ectopic endometrial tissue (a form of ovarian endometriosis, the classic 'chocolate cyst'), unrelated to hemorrhage into the corpus luteum.", "D": "Theca lutein cysts arise from excessive hCG stimulation (e.g., molar pregnancy, multiple gestation) causing luteinization of theca cells, a distinct process from bleeding into a corpus luteum."}}}, {"id": "anking-reproductive-system-pathology-2191", "fuente": "anking", "tema": 8, "anki": "1463176746263", "q": "Degeneration of ovarian follicles may result in which common, usually clinically insignificant, finding?", "o": {"A": "Follicular cysts", "B": "Endometriomas", "C": "Theca lutein cysts", "D": "Serous cystadenomas"}, "r": "A", "e": {"correcta": "Degeneration (or failure of normal rupture/resorption) of ovarian follicles commonly leads to follicular cysts; small numbers of these are extremely common in women of reproductive age and are typically of no clinical significance, often resolving spontaneously.", "incorrectas": {"B": "Endometriomas arise from ectopic endometrial tissue implanting on the ovary (a manifestation of endometriosis), not from degeneration of a normal ovarian follicle.", "C": "Theca lutein cysts result from excessive gonadotropin (hCG) stimulation, such as in gestational trophoblastic disease, not from simple follicular degeneration.", "D": "Serous cystadenomas are benign neoplasms of the ovarian surface epithelium, an entirely different process (true neoplasia) from the non-neoplastic degeneration of a follicle."}}}, {"id": "anking-reproductive-system-pathology-2192", "fuente": "anking", "tema": 8, "anki": "1463176758271", "q": "A young woman presents with multiple follicular cysts in the ovary and anovulation due to a hormonal imbalance. What is this classically named condition?", "o": {"A": "Asherman syndrome", "B": "Polycystic ovarian syndrome (Stein-Leventhal syndrome)", "C": "Turner syndrome", "D": "Sheehan syndrome"}, "r": "B", "e": {"correcta": "Polycystic ovarian syndrome, also known as Stein-Leventhal syndrome, is characterized by multiple follicular cysts in the ovaries and chronic anovulation resulting from a hormonal imbalance (elevated LH relative to FSH, hyperandrogenism, and insulin resistance); treatment includes weight reduction, OCPs, clomiphene citrate, and antiandrogens like spironolactone.", "incorrectas": {"A": "Asherman syndrome involves intrauterine adhesions (synechiae), usually following uterine instrumentation, causing amenorrhea or infertility, unrelated to follicular cysts or ovarian hormonal imbalance.", "C": "Turner syndrome (45,X) causes ovarian dysgenesis (streak gonads) with primary amenorrhea and estrogen deficiency, a chromosomal disorder distinct from the follicular cyst and anovulation picture of PCOS.", "D": "Sheehan syndrome is postpartum pituitary necrosis due to hemorrhage/hypotension, causing panhypopituitarism, and is unrelated to ovarian follicular cysts."}}}, {"id": "anking-endocrine-physiology-2193", "fuente": "anking", "tema": 23, "anki": "1463176773349", "q": "In polycystic ovarian syndrome, what is the characteristic pattern of LH and FSH levels?", "o": {"A": "Low LH, high FSH", "B": "High LH, low FSH", "C": "High LH, high FSH", "D": "Low LH, low FSH"}, "r": "B", "e": {"correcta": "PCOS is characterized by high LH and relatively low (or low-normal) FSH, a pattern driven by increased GnRH pulse frequency favoring LH synthesis; the elevated LH stimulates ovarian theca cells to overproduce androgens, contributing to the syndrome's hyperandrogenic features and anovulation.", "incorrectas": {"A": "This is the reverse of the actual pattern seen in PCOS; low LH with high FSH is not characteristic and would suggest a different endocrine process.", "C": "Both gonadotropins being elevated is not the classic PCOS pattern; the hallmark is a skewed LH:FSH ratio with LH predominating, not simultaneous elevation of both.", "D": "Both gonadotropins being low would suggest hypogonadotropic hypogonadism (e.g., hypothalamic dysfunction), which is a distinct picture from the elevated-LH pattern of PCOS."}}}, {"id": "anking-endocrine-physiology-2194", "fuente": "anking", "tema": 23, "anki": "1463176777704", "q": "In polycystic ovarian syndrome, the LH:FSH ratio is often greater than what value?", "o": {"A": "1", "B": "1.5", "C": "2", "D": "3"}, "r": "C", "e": {"correcta": "PCOS is classically associated with an LH:FSH ratio greater than 2, reflecting the relatively increased LH secretion (driven by altered GnRH pulsatility) compared to FSH; this elevated ratio supports increased theca cell androgen production and contributes to anovulation.", "incorrectas": {"A": "A ratio of 1 would represent roughly equal LH and FSH levels, which is a normal or non-PCOS pattern rather than the skewed elevation of LH characteristic of PCOS.", "B": "A ratio of 1.5, while elevated above 1, is not the classically cited threshold used to describe the LH:FSH imbalance in PCOS; the standard cutoff taught is greater than 2.", "D": "A ratio of 3 is higher than the classically cited threshold; while some patients may have ratios this high, the standard teaching point uses greater than 2 as the characteristic finding."}}}, {"id": "anking-reproductive-system-pathology-2195", "fuente": "anking", "tema": 8, "anki": "1463176787073", "q": "Which demographic is most commonly affected by polycystic ovarian syndrome (Stein-Leventhal syndrome)?", "o": {"A": "Thin, adolescent girls", "B": "Obese, young women", "C": "Postmenopausal women", "D": "Underweight women of advanced maternal age"}, "r": "B", "e": {"correcta": "PCOS most commonly affects obese, young women of reproductive age; obesity contributes to the syndrome's pathophysiology through peripheral aromatization of androgens to estrogens in adipose tissue and through insulin resistance, which further drives ovarian androgen production.", "incorrectas": {"A": "Thin adolescent girls are not the typical demographic for PCOS; obesity is a strong and characteristic association with this syndrome, not thinness.", "C": "PCOS is a disorder of the reproductive years driven by ongoing ovarian follicular and hormonal dysfunction; postmenopausal women, who have ceased ovarian follicular activity, are not the affected group.", "D": "Underweight status and advanced maternal age are not features associated with PCOS; the classic demographic is young, obese women, often presenting with oligomenorrhea and infertility earlier in reproductive life."}}}, {"id": "anking-endocrine-physiology-2196", "fuente": "anking", "tema": 23, "anki": "1463176792455", "q": "Polycystic ovarian syndrome is associated with which metabolic abnormality that may lead to type II diabetes mellitus 10-15 years later?", "o": {"A": "Insulin resistance", "B": "Growth hormone deficiency", "C": "Primary hyperaldosteronism", "D": "Hypothyroidism"}, "r": "A", "e": {"correcta": "PCOS is strongly associated with insulin resistance, which not only worsens hyperandrogenism (insulin stimulates ovarian theca cell androgen production and reduces hepatic SHBG synthesis) but also predisposes affected women to develop type II diabetes mellitus roughly 10-15 years after PCOS diagnosis.", "incorrectas": {"B": "Growth hormone deficiency is not part of the PCOS metabolic profile; PCOS is characterized by insulin resistance and hyperinsulinemia, not deficient growth hormone signaling.", "C": "Primary hyperaldosteronism is a distinct endocrine disorder involving excess aldosterone causing hypertension and hypokalemia, unrelated to the insulin resistance seen in PCOS.", "D": "Hypothyroidism is not the metabolic hallmark of PCOS; while thyroid dysfunction can cause menstrual irregularities, the classic metabolic link in PCOS is insulin resistance predisposing to diabetes."}}}, {"id": "anking-reproductive-system-pathology-2197", "fuente": "anking", "tema": 8, "anki": "1463176795022", "q": "Patients with polycystic ovarian syndrome have an increased risk of which carcinoma, secondary to unopposed estrogen effects from chronic anovulation?", "o": {"A": "Cervical carcinoma", "B": "Endometrial carcinoma", "C": "Vaginal carcinoma", "D": "Ovarian clear cell carcinoma"}, "r": "B", "e": {"correcta": "PCOS increases the risk of endometrial carcinoma because excess androgen leads to anovulatory cycles, preventing dominant follicle formation and progesterone secretion; the resulting unopposed estrogen (compounded by peripheral estrone production from adipose tissue) drives long-term endometrial hyperplasia that can progress to adenocarcinoma.", "incorrectas": {"A": "Cervical carcinoma is primarily driven by persistent high-risk HPV infection, not by the unopposed estrogen state seen in PCOS; there is no classic association between PCOS and cervical cancer risk.", "C": "Vaginal carcinoma is a rare malignancy most associated with HPV or, classically, in utero DES exposure (clear cell type), not with the chronic anovulation and unopposed estrogen of PCOS.", "D": "Ovarian clear cell carcinoma is a surface epithelial ovarian tumor associated with endometriosis, not specifically linked to the unopposed estrogen mechanism of PCOS; the endometrium, not the ovary, is the tissue at increased carcinoma risk in PCOS."}}}, {"id": "anking-reproductive-system-pathology-2198", "fuente": "anking", "tema": 8, "anki": "1463176881592", "q": "What is the most common ovarian mass in young women?", "o": {"A": "Serous cystadenoma", "B": "Follicular cyst", "C": "Corpus luteal cyst", "D": "Mucinous cystadenoma"}, "r": "B", "e": {"correcta": "The follicular cyst is the most common ovarian mass in young women, arising from a distended, unruptured graafian follicle; these are usually functional, benign, and often resolve spontaneously over one to a few menstrual cycles.", "incorrectas": {"A": "Serous cystadenoma is the most common benign true neoplasm of the ovary, but as a functional cyst rather than a neoplasm, the follicular cyst is more common overall as an ovarian mass in young women.", "C": "Corpus luteal cysts form from hemorrhage or persistence of the corpus luteum after ovulation; they are less common than follicular cysts as a cause of ovarian mass.", "D": "Mucinous cystadenoma is a benign surface epithelial neoplasm, occurring less frequently than serous cystadenoma among epithelial tumors, and is far less common than the simple functional follicular cyst as a cause of ovarian mass in young women."}}}, {"id": "anking-reproductive-system-pathology-2199", "fuente": "anking", "tema": 8, "anki": "1463177010540", "q": "A distention of an unruptured graafian follicle describes which type of ovarian cyst?", "o": {"A": "Corpus luteal cyst", "B": "Follicular cyst", "C": "Theca lutein cyst", "D": "Endometrioma"}, "r": "B", "e": {"correcta": "A follicular cyst results from distention of an unruptured graafian follicle that fails to release its oocyte or fails to involute normally; it may be associated with hyperestrogenism and endometrial hyperplasia due to continued granulosa cell estrogen production without ovulation.", "incorrectas": {"A": "A corpus luteal cyst forms after ovulation has already occurred, from hemorrhage into or persistence of the corpus luteum, a stage distinct from the pre-ovulatory unruptured follicle described here.", "C": "Theca lutein cysts arise from excessive hCG stimulation causing luteinization and are typically bilateral and associated with molar pregnancies, not simply an unruptured graafian follicle.", "D": "An endometrioma is a cyst formed by ectopic endometrial tissue and old blood within the ovary (endometriosis), unrelated to a distended unruptured follicle."}}}, {"id": "anking-reproductive-system-pathology-2200", "fuente": "anking", "tema": 8, "anki": "1463178466775", "q": "Ovarian tumors may arise from three different cell types. Which of the following is NOT one of these three primary cell-of-origin categories?", "o": {"A": "Surface epithelium", "B": "Germ cells", "C": "Sex cord-stromal tissue", "D": "Endometrial stromal cells"}, "r": "D", "e": {"correcta": "The three classic categories of ovarian tumor origin are surface (coelomic) epithelium, germ cells (e.g., oocyte-derived tumors like teratomas and dysgerminomas), and sex cord-stromal tissue (e.g., granulosa cell and theca cell tumors); ovarian tumors may also arise from metastasis, but endometrial stromal cells are not one of the three primary intrinsic ovarian cell-of-origin categories.", "incorrectas": {"A": "Surface epithelium is indeed one of the three classic categories and is the most common source of ovarian tumors (about 70%), so this is not the exception being sought.", "B": "Germ cells are one of the three classic categories, giving rise to tumors such as teratomas, dysgerminomas, and yolk sac tumors, so this is not the excluded category.", "C": "Sex cord-stromal tissue is one of the three classic categories, producing tumors like granulosa cell tumors and Sertoli-Leydig cell tumors, so this is not the excluded category."}}}, {"id": "anking-reproductive-system-pathology-2201", "fuente": "anking", "tema": 8, "anki": "1463187644766", "q": "Which class of ovarian tumor is the most common overall, accounting for approximately 70% of ovarian tumors?", "o": {"A": "Germ cell tumors", "B": "Sex cord-stromal tumors", "C": "Surface epithelial tumors", "D": "Metastatic tumors"}, "r": "C", "e": {"correcta": "Surface epithelial tumors are the most common class of ovarian tumor, making up about 70% of cases; these arise from the ovarian surface epithelium, which consists of simple cuboidal cells that proliferate rapidly to repair defects created by repeated ovulation, a process that likely predisposes to neoplastic transformation.", "incorrectas": {"A": "Germ cell tumors (e.g., teratomas, dysgerminomas) are common, particularly in younger women and children, but they do not account for the majority of ovarian tumors overall; surface epithelial tumors are more common.", "B": "Sex cord-stromal tumors (e.g., granulosa cell tumors, fibromas) are a less common category overall compared to surface epithelial tumors.", "D": "Metastatic tumors to the ovary (e.g., Krukenberg tumors from gastric cancer) do occur but represent a minority of ovarian masses compared to the dominant surface epithelial category."}}}, {"id": "anking-reproductive-system-embryology-2202", "fuente": "anking", "tema": 33, "anki": "1463187654764", "q": "Surface epithelial tumors of the ovary are derived embryologically from which type of epithelium that lines the ovary?", "o": {"A": "Mesonephric epithelium", "B": "Coelomic epithelium", "C": "Urogenital sinus epithelium", "D": "Paramesonephric duct epithelium"}, "r": "B", "e": {"correcta": "Surface epithelial tumors arise from the coelomic epithelium lining the ovary, the same embryologic tissue that gives rise to the epithelial lining of the fallopian tube (serous-type cells), endometrium, and endocervix (mucinous-type cells), which explains why these tumors can differentiate into serous, mucinous, or endometrioid histologic subtypes.", "incorrectas": {"A": "Mesonephric (Wolffian) epithelium contributes to male reproductive structures and vestigial remnants in females (e.g., Gartner duct cysts), not to the ovarian surface epithelium or its tumors.", "C": "Urogenital sinus epithelium contributes to structures like the lower vagina and bladder, not the ovarian surface epithelium from which surface epithelial tumors arise.", "D": "Paramesonephric (Müllerian) duct epithelium gives rise to the fallopian tubes, uterus, and upper vagina directly, but the ovarian surface epithelium itself derives from coelomic epithelium, which is the embryologic origin cited for these tumors."}}}, {"id": "anking-reproductive-system-pathology-2203", "fuente": "anking", "tema": 8, "anki": "1463187666186", "q": "What are the two most common subtypes of ovarian surface epithelial tumors, both of which are usually cystic?", "o": {"A": "Serous and mucinous", "B": "Endometrioid and clear cell", "C": "Brenner and transitional cell", "D": "Serous and Brenner"}, "r": "A", "e": {"correcta": "The two most common subtypes of ovarian surface epithelial tumors are serous and mucinous, classically named for the type of fluid they produce (serous = watery fluid resembling fallopian tube secretions, mucinous = thick mucus resembling endocervical secretions); both are typically cystic (cystadenomas when benign).", "incorrectas": {"B": "Endometrioid and clear cell tumors are recognized subtypes of surface epithelial ovarian tumors, often associated with endometriosis, but they are less common than the serous and mucinous subtypes.", "C": "Brenner tumors are a less common surface epithelial subtype composed of transitional (urothelial-like) epithelium; transitional cell carcinoma is not one of the two most common subtypes.", "D": "While serous is correctly one of the two most common subtypes, Brenner tumors are relatively uncommon and are not paired with serous as the two most common subtypes; that pairing is serous and mucinous."}}}, {"id": "anking-reproductive-system-pathology-2204", "fuente": "anking", "tema": 8, "anki": "1463187677022", "q": "A benign ovarian tumor composed of a single cyst with a simple, flat lining of epithelial cells is best classified as which entity?", "o": {"A": "Cystadenoma", "B": "Cystadenocarcinoma", "C": "Dermoid cyst (mature teratoma)", "D": "Fibroma"}, "r": "A", "e": {"correcta": "An ovarian cystadenoma is a benign surface epithelial tumor composed of a single cyst lined by a simple, flat layer of epithelial cells (serous or mucinous type), representing the benign end of the surface epithelial tumor spectrum.", "incorrectas": {"B": "Cystadenocarcinoma is the malignant counterpart of a cystadenoma, showing anaplastic epithelial cells with stromal invasion and papillary architecture with atypia, not the simple, flat, benign lining described.", "C": "A dermoid cyst (mature cystic teratoma) is a germ cell tumor containing tissue from all three germ layers (e.g., hair, teeth, sebaceous material), not a simple epithelial-lined cyst of surface epithelial origin.", "D": "A fibroma is a solid sex cord-stromal tumor composed of spindle-shaped fibroblasts, not a cystic surface epithelial tumor with a flat epithelial lining."}}}, {"id": "anking-reproductive-system-pathology-2205", "fuente": "anking", "tema": 8, "anki": "1463187698743", "q": "Ovarian cystadenomas (surface epithelial tumors) most commonly arise in premenopausal women within which age range?", "o": {"A": "10-20 years old", "B": "30-40 years old", "C": "50-60 years old", "D": "70-80 years old"}, "r": "B", "e": {"correcta": "Ovarian cystadenomas most commonly arise in premenopausal women aged 30-40 years, reflecting the period of active ovarian surface epithelial turnover and repair related to ongoing ovulatory cycles.", "incorrectas": {"A": "The 10-20 age range is more typical for germ cell tumors of the ovary (e.g., dermoid cysts, dysgerminomas), which predominate in younger women and adolescents, not for surface epithelial cystadenomas.", "C": "The 50-60 age range is older than the classic premenopausal presentation of benign cystadenomas; malignant surface epithelial tumors tend to occur somewhat later in life, but the benign cystadenoma peak is 30-40.", "D": "The 70-80 age range is far later than the typical presentation of benign ovarian cystadenoma; this age range would be more consistent with malignant epithelial ovarian carcinoma."}}}, {"id": "anking-reproductive-system-pathology-2206", "fuente": "anking", "tema": 8, "anki": "1463187709198", "q": "What is the most common benign ovarian tumor, classically lined with fallopian tube-like epithelium and often bilateral?", "o": {"A": "Mucinous cystadenoma", "B": "Serous cystadenoma", "C": "Brenner tumor", "D": "Mature cystic teratoma"}, "r": "B", "e": {"correcta": "Serous cystadenoma is the most common benign ovarian tumor; it is lined by epithelium resembling that of the fallopian tube (ciliated, tubal-type cells) and is frequently bilateral, distinguishing it from other surface epithelial tumor subtypes.", "incorrectas": {"A": "Mucinous cystadenoma is also a common benign surface epithelial tumor, lined by mucus-secreting (endocervical-like) epithelium, but it is less common than serous cystadenoma and is typically unilateral and can grow very large (potentially causing pseudomyxoma peritonei if ruptured).", "C": "Brenner tumor is a less common benign surface epithelial tumor composed of transitional (urothelial-like) epithelium, distinctly less frequent than serous cystadenoma.", "D": "Mature cystic teratoma (dermoid cyst) is the most common benign ovarian germ cell tumor, not a surface epithelial tumor, and is lined by tissues derived from all three germ layers rather than fallopian tube-like epithelium."}}}, {"id": "anking-reproductive-system-pathology-2207", "fuente": "anking", "tema": 8, "anki": "1463187720272", "q": "A benign ovarian cystic tumor is lined by fallopian tube-like (tubal) epithelium and is often bilateral. Which surface epithelial tumor is this?", "o": {"A": "Mucinous cystadenoma", "B": "Serous cystadenoma", "C": "Brenner tumor", "D": "Endometrioid tumor"}, "r": "B", "e": {"correcta": "Serous cystadenoma is the most common benign ovarian surface epithelial tumor, lined by a single layer of ciliated, tubal (fallopian tube)-like epithelium; it is bilateral in roughly a quarter to a third of cases, more often than its mucinous counterpart.", "incorrectas": {"A": "Mucinous cystadenoma is lined by mucus-secreting, cervix-like or intestinal-type epithelium rather than fallopian tube-like epithelium, and is typically multiloculated and unilateral, unlike the tubal-lined, often-bilateral serous cystadenoma.", "C": "Brenner tumor is a solid, encapsulated, yellow-tan tumor with transitional (urothelial)-like epithelium and characteristic \"coffee bean\" nuclei, not a cystic tumor lined by tubal epithelium.", "D": "Endometrioid tumor is composed of endometrial gland-like epithelium (often malignant and linked to endometriosis), which is histologically distinct from the ciliated tubal epithelium seen in serous cystadenoma."}}}, {"id": "anking-reproductive-system-pathology-2208", "fuente": "anking", "tema": 8, "anki": "1463187736885", "q": "An ovarian tumor shows complex cysts with a shaggy epithelial lining and frank invasion into the underlying connective tissue/stroma. What is this lesion?", "o": {"A": "Serous cystadenoma", "B": "Borderline serous tumor", "C": "Cystadenocarcinoma", "D": "Cystic teratoma"}, "r": "C", "e": {"correcta": "Cystadenocarcinoma is the malignant counterpart of the surface epithelial cystadenomas; it shows complex, irregular (\"shaggy\") papillary epithelial proliferation with clear stromal invasion, distinguishing it from benign or borderline lesions.", "incorrectas": {"A": "Serous cystadenoma is benign, with a smooth, simple lining of tubal-type epithelium and no invasion into the stroma, unlike the shaggy invasive lining described here.", "B": "Borderline tumors show epithelial atypia and papillary complexity intermediate between benign and malignant, but by definition lack destructive stromal invasion, which is present in cystadenocarcinoma.", "D": "Cystic teratoma is a germ cell tumor containing tissue from multiple embryologic layers (hair, teeth, skin), not a surface epithelial tumor with invasive glandular architecture."}}}, {"id": "anking-reproductive-system-pathology-2209", "fuente": "anking", "tema": 8, "anki": "1463187744728", "q": "Malignant ovarian surface epithelial tumors (adenocarcinomas) most commonly arise in women of which age group?", "o": {"A": "15-30 years old", "B": "30-40 years old", "C": "60-70 years old", "D": "40-50 years old"}, "r": "C", "e": {"correcta": "Malignant ovarian surface epithelial adenocarcinomas typically arise in postmenopausal women aged 60-70 years, reflecting cumulative epithelial damage/repair cycles from ovulation over decades.", "incorrectas": {"A": "15-30 years is the typical age range for ovarian germ cell tumors (e.g., dysgerminoma, teratoma), not surface epithelial carcinomas, which occur later in life.", "B": "30-40 years is the age range associated with benign surface epithelial tumors such as serous or mucinous cystadenomas, before the later malignant transformation risk peaks.", "D": "40-50 years falls between the benign (30-40) and malignant (60-70) peaks for surface epithelial tumors and is not the classically cited age for adenocarcinoma."}}}, {"id": "anking-reproductive-system-pathology-2210", "fuente": "anking", "tema": 8, "anki": "1463187754886", "q": "Ovarian tumors with epithelial features intermediate between clearly benign and clearly malignant are classified as which category?", "o": {"A": "Cystadenocarcinoma", "B": "Borderline tumor", "C": "Cystadenoma", "D": "Brenner tumor"}, "r": "B", "e": {"correcta": "Borderline tumors show cytologic atypia and increased epithelial proliferation beyond a benign cystadenoma but, unlike carcinoma, lack destructive stromal invasion, placing them histologically and prognostically between benign and malignant lesions.", "incorrectas": {"A": "Cystadenocarcinoma is frankly malignant with invasion into the stroma, which is a step beyond the atypia-without-invasion picture that defines a borderline tumor.", "C": "Cystadenoma is a purely benign tumor with a simple, uniform epithelial lining and no atypia, lacking the intermediate features that define borderline tumors.", "D": "Brenner tumor is a distinct benign transitional-cell tumor type, not a category describing an intermediate benign-malignant spectrum."}}}, {"id": "anking-reproductive-system-pathology-2211", "fuente": "anking", "tema": 8, "anki": "1463187760102", "q": "Compared to clearly malignant ovarian carcinomas, borderline ovarian tumors are best characterized by which combination of features?", "o": {"A": "Worse prognosis and no metastatic potential", "B": "Better prognosis and no metastatic potential", "C": "Better prognosis but retain some metastatic potential", "D": "Equivalent prognosis and equivalent metastatic potential"}, "r": "C", "e": {"correcta": "Borderline tumors carry a better overall prognosis than invasive carcinoma because they lack destructive stromal invasion, but they can still implant on peritoneal surfaces and recur, so they retain some metastatic/spread potential and require follow-up.", "incorrectas": {"A": "Borderline tumors have a better, not worse, prognosis than invasive carcinoma precisely because they lack frank stromal invasion, even though they are not entirely risk-free.", "B": "While prognosis is better than carcinoma, borderline tumors are not risk-free — they can still spread as peritoneal implants, so \"no metastatic potential\" is inaccurate.", "D": "Borderline tumors behave less aggressively than carcinoma overall, so equating their prognosis and spread potential to invasive cystadenocarcinoma understates their more favorable behavior."}}}, {"id": "anking-reproductive-system-pathology-2212", "fuente": "anking", "tema": 8, "anki": "1463187773649", "q": "A postmenopausal woman is found to have a bilateral ovarian mass with psammoma bodies on histology. Which is the most common malignant ovarian neoplasm overall?", "o": {"A": "Serous cystadenocarcinoma", "B": "Mucinous cystadenocarcinoma", "C": "Granulosa cell tumor", "D": "Dysgerminoma"}, "r": "A", "e": {"correcta": "Serous cystadenocarcinoma is the most common malignant ovarian neoplasm; it is frequently bilateral and classically shows psammoma bodies (concentric calcifications) on histology, reflecting its origin from the surface (tubal-type) epithelium.", "incorrectas": {"B": "Mucinous cystadenocarcinoma is less common than serous carcinoma, typically unilateral, and lined by mucinous rather than serous epithelium, and it is not the classic source of psammoma bodies.", "C": "Granulosa cell tumor is the most common malignant sex cord-stromal tumor (associated with estrogen excess and Call-Exner bodies), not the most common ovarian malignancy overall and not associated with psammoma bodies.", "D": "Dysgerminoma is the most common malignant germ cell tumor, typically in young women, but germ cell tumors overall are far less common than surface epithelial carcinomas as a cause of ovarian malignancy."}}}, {"id": "anking-reproductive-system-pathology-2213", "fuente": "anking", "tema": 8, "anki": "1463187812239", "q": "A rare ovarian surface epithelial tumor composed of glands resembling endometrial tissue, usually malignant and sometimes linked to endometriosis, is best classified as which tumor type?", "o": {"A": "Endometrioid tumor", "B": "Serous tumor", "C": "Brenner tumor", "D": "Mucinous tumor"}, "r": "A", "e": {"correcta": "Endometrioid ovarian tumors are composed of glands histologically resembling endometrium and are usually malignant; they can be associated with pelvic endometriosis, reflecting a shared endometrial-type epithelial origin.", "incorrectas": {"B": "Serous tumors are lined by tubal (fallopian tube)-like ciliated epithelium, not endometrial-gland morphology, and are more often benign (cystadenoma) than the typically malignant endometrioid tumor.", "C": "Brenner tumor shows transitional (urothelial)-like epithelium with coffee bean nuclei, a distinct histologic pattern unrelated to endometrial-type glands.", "D": "Mucinous tumors are lined by mucus-secreting epithelium resembling endocervix or intestine, not endometrial glands, and are more commonly benign or borderline than the typically malignant endometrioid tumor."}}}, {"id": "anking-reproductive-system-pathology-2214", "fuente": "anking", "tema": 8, "anki": "1463187820455", "q": "Approximately what percentage of ovarian endometrioid tumors are associated with a separate, independent primary endometrial (uterine) carcinoma?", "o": {"A": "50%", "B": "5%", "C": "15%", "D": "30%"}, "r": "C", "e": {"correcta": "About 15% of ovarian endometrioid tumors occur together with an independent primary endometrial carcinoma, reflecting a shared susceptibility of endometrial-type tissue at both sites (field effect) rather than metastasis from one to the other in most cases.", "incorrectas": {"B": "5% underestimates the well-established synchronous association; the classically cited figure for coexisting independent endometrial carcinoma is closer to 15%.", "A": "50% substantially overstates the association; while notable, only a minority (about 15%) of ovarian endometrioid tumors have a synchronous independent endometrial carcinoma.", "D": "30% is higher than the classically taught figure of approximately 15% for this synchronous tumor association."}}}, {"id": "anking-reproductive-system-pathology-2215", "fuente": "anking", "tema": 8, "anki": "1463187832044", "q": "A solid, encapsulated, yellow-tan ovarian tumor shows nuclei with a characteristic longitudinal groove on H&E, described as \"coffee bean\" nuclei. Which tumor is this?", "o": {"A": "Brenner tumor", "B": "Serous cystadenoma", "C": "Granulosa cell tumor", "D": "Krukenberg tumor"}, "r": "A", "e": {"correcta": "Brenner tumor is a benign, solid, encapsulated ovarian surface epithelial tumor with a yellow-tan cut surface, composed of transitional (urothelial-like) epithelial nests whose nuclei show a longitudinal groove, giving the classic \"coffee bean\" appearance.", "incorrectas": {"B": "Serous cystadenoma is a cystic tumor lined by tubal-type ciliated epithelium, not a solid tumor with transitional epithelium and coffee bean nuclei.", "C": "Granulosa cell tumor is a sex cord-stromal tumor associated with estrogen production and Call-Exner bodies (small follicles with eosinophilic material), a different histologic picture from Brenner tumor's coffee bean nuclei.", "D": "Krukenberg tumor is a metastatic mucinous (signet ring cell) tumor to the ovary, typically from a gastric primary, not a primary tumor with transitional epithelium and coffee bean nuclei."}}}, {"id": "anking-reproductive-system-pathology-2216", "fuente": "anking", "tema": 8, "anki": "1463187844705", "q": "Ovarian surface epithelial tumors generally have a poor prognosis largely because of which characteristic clinical feature?", "o": {"A": "Rapid hematogenous spread to bone", "B": "Early, easily detected symptoms", "C": "Late presentation due to vague/nonspecific symptoms", "D": "Universal chemoresistance"}, "r": "C", "e": {"correcta": "Ovarian surface epithelial tumors typically present late because early disease produces only vague abdominal symptoms, allowing the tumor to spread locally (especially to the peritoneum) before diagnosis — this delay contributes to their being the deadliest of the female genital tract cancers.", "incorrectas": {"A": "Ovarian carcinomas tend to spread locally via peritoneal seeding rather than primarily hematogenously to bone, so this is not the classic mechanism explaining their poor prognosis.", "B": "The opposite is true — ovarian tumors notoriously present with subtle, nonspecific symptoms (bloating, pelvic pressure) that are easily missed or attributed to other causes, delaying diagnosis.", "D": "Ovarian cancers are not universally chemoresistant; many respond at least partially to platinum-based chemotherapy, but the tumor is often already advanced (spread to peritoneum) by the time it is found."}}}, {"id": "anking-reproductive-system-pathology-2217", "fuente": "anking", "tema": 8, "anki": "1463187881126", "q": "Ovarian surface epithelial tumors typically present with vague abdominal pain/fullness along with which additional symptom reflecting local mass effect?", "o": {"A": "Hematuria from bladder invasion", "B": "Urinary frequency from bladder compression", "C": "Hematochezia from rectal invasion", "D": "Galactorrhea"}, "r": "B", "e": {"correcta": "As an enlarging pelvic mass, an ovarian tumor compresses adjacent structures such as the bladder, producing urinary frequency without actual tumor invasion — a classic \"compression\" sign alongside vague abdominal fullness.", "incorrectas": {"A": "Hematuria would suggest direct mucosal invasion of the urinary tract, which is not the typical early mechanism; compression causing frequency is far more characteristic than invasive hematuria.", "C": "Hematochexia implies rectal mucosal invasion or bleeding, which is not the classic early compressive symptom associated with an enlarging ovarian mass.", "D": "Galactorrhea reflects a prolactin-secreting process (e.g., pituitary prolactinoma), which is unrelated to mass effect from an ovarian tumor."}}}, {"id": "anking-reproductive-system-pathology-2218", "fuente": "anking", "tema": 8, "anki": "1463187887033", "q": "Which serum tumor marker is used to monitor treatment response and detect recurrence in ovarian surface epithelial neoplasms, despite being unreliable for screening?", "o": {"A": "AFP", "B": "CA-125", "C": "hCG", "D": "CA 19-9"}, "r": "B", "e": {"correcta": "CA-125 is produced by ovarian epithelial cells and is markedly elevated in most epithelial ovarian cancers, making it useful for tracking treatment response and detecting recurrence, though it is not sensitive or specific enough for general population screening since benign conditions like endometriosis also raise it.", "incorrectas": {"A": "AFP is the marker for yolk sac (endodermal sinus) tumors and hepatocellular carcinoma, not for surface epithelial ovarian tumors.", "C": "hCG is elevated in choriocarcinoma and some dysgerminomas (from syncytiotrophoblastic components), not characteristically used to monitor surface epithelial ovarian carcinoma.", "D": "CA 19-9 is more classically associated with pancreatic and other gastrointestinal cancers, not the standard marker for ovarian surface epithelial tumors."}}}, {"id": "anking-reproductive-system-pathology-2219", "fuente": "anking", "tema": 8, "anki": "1463187894899", "q": "Which category of ovarian tumor is the second most common overall, accounting for roughly 15% of ovarian tumors?", "o": {"A": "Sex cord-stromal tumors", "B": "Surface epithelial tumors", "C": "Germ cell tumors", "D": "Metastatic tumors"}, "r": "C", "e": {"correcta": "Germ cell tumors are the second most common class of ovarian tumor, making up about 15% of cases, behind surface epithelial tumors which are the most common overall; they typically occur in younger women (15-30 years old).", "incorrectas": {"A": "Sex cord-stromal tumors (e.g., granulosa cell, Sertoli-Leydig) are a less common category than germ cell tumors and are not the classic second-most-common class cited.", "B": "Surface epithelial tumors are the most common category of ovarian tumor overall, not the second most common — that distinction belongs to germ cell tumors.", "D": "Metastatic tumors to the ovary (e.g., Krukenberg tumors) are a distinct, less common category and not classically ranked as the second most common primary ovarian tumor type."}}}, {"id": "anking-reproductive-system-pathology-2220", "fuente": "anking", "tema": 8, "anki": "1463187899305", "q": "Ovarian germ cell tumors most commonly affect which demographic, in contrast to surface epithelial tumors which occur in older women?", "o": {"A": "Postmenopausal women 60-70 years old", "B": "Women of reproductive age, 15-30 years old", "C": "Perimenopausal women 45-55 years old", "D": "Prepubertal girls under age 10"}, "r": "B", "e": {"correcta": "Ovarian germ cell tumors classically occur in women of reproductive age, roughly 15-30 years old, in contrast to surface epithelial tumors which occur later in life (benign around 30-40, malignant around 60-70 years old).", "incorrectas": {"A": "60-70 years old is the classic age range for malignant surface epithelial tumors (e.g., serous cystadenocarcinoma), not germ cell tumors, which affect younger women.", "C": "Perimenopausal women are not the classic demographic for germ cell tumors; this age range does not match the typical 15-30 year presentation.", "D": "While germ cell tumors like yolk sac tumors can occur in young children, the group as a whole (including teratomas and dysgerminomas) is most classically associated with women of reproductive age (15-30), not prepubertal girls."}}}, {"id": "anking-reproductive-system-pathology-2221", "fuente": "anking", "tema": 8, "anki": "1463187910218", "q": "An ovarian cystic mass contains hair, teeth, bone, and skin, representing tissue derived from two or three embryologic germ layers. What is this tumor?", "o": {"A": "Dysgerminoma", "B": "Cystic teratoma", "C": "Endodermal sinus tumor", "D": "Choriocarcinoma"}, "r": "B", "e": {"correcta": "Cystic (mature) teratoma is a germ cell tumor composed of well-differentiated fetal tissue derived from ectoderm, mesoderm, and/or endoderm — producing structures like hair, teeth, bone, skin, gut, and thyroid tissue; it can cause pain from ovarian enlargement or torsion.", "incorrectas": {"A": "Dysgerminoma is composed of large cells resembling primordial germ cells (analogous to seminoma), without the multi-tissue differentiation (hair, teeth, bone) seen in teratoma.", "C": "Endodermal sinus (yolk sac) tumor mimics yolk sac tissue and produces AFP, but does not form the recognizable mature multi-germ-layer structures characteristic of teratoma.", "D": "Choriocarcinoma is composed of malignant syncytiotrophoblasts and cytotrophoblasts producing hCG, not differentiated tissues like hair, teeth, or bone."}}}, {"id": "anking-reproductive-system-pathology-2222", "fuente": "anking", "tema": 8, "anki": "1463187920919", "q": "In females aged 10-30, which is the most common germ cell tumor of the ovary, bilateral in about 10% of cases?", "o": {"A": "Dysgerminoma", "B": "Embryonal carcinoma", "C": "Cystic teratoma", "D": "Endodermal sinus tumor"}, "r": "C", "e": {"correcta": "Cystic (mature) teratoma is the most common germ cell tumor and the most common ovarian tumor overall in females aged 10-30, and is bilateral in about 10% of cases, reflecting its origin from totipotent germ cells that differentiate along multiple lineages.", "incorrectas": {"A": "Dysgerminoma is the most common malignant germ cell tumor, but it is far less common overall than the benign mature cystic teratoma in this age group.", "B": "Embryonal carcinoma is an aggressive, early-metastasizing germ cell tumor, but it is much rarer than cystic teratoma as a cause of ovarian masses in young women.", "D": "Endodermal sinus (yolk sac) tumor is most common in young children (especially male infants when found in the testis/sacrococcygeal region), not the leading ovarian germ cell tumor in women 10-30 years old."}}}, {"id": "anking-reproductive-system-pathology-2223", "fuente": "anking", "tema": 8, "anki": "1463187929584", "q": "What is the malignant potential of a mature cystic teratoma of the ovary?", "o": {"A": "Uniformly malignant", "B": "Benign", "C": "Borderline malignant potential", "D": "Always metastatic at diagnosis"}, "r": "B", "e": {"correcta": "A mature cystic teratoma is benign — its component tissues are fully differentiated (mature), which is why it behaves indolently, though it can still cause complications like pain from torsion or, rarely, undergo somatic malignant transformation (e.g., squamous cell carcinoma) in a small subset.", "incorrectas": {"A": "Mature teratomas are not uniformly malignant; malignancy is a feature of the immature teratoma variant, which contains embryonic (immature) neural tissue.", "C": "\"Borderline\" describes surface epithelial tumors with atypia but no invasion, a different tumor category; mature teratomas are simply classified as benign, not borderline.", "D": "Mature cystic teratomas are not inherently metastatic; they are benign tumors, and metastatic potential is a feature of the malignant immature teratoma, not the mature form."}}}, {"id": "anking-reproductive-system-pathology-2224", "fuente": "anking", "tema": 8, "anki": "1463187934796", "q": "What is the malignant potential of an immature ovarian teratoma?", "o": {"A": "Always benign", "B": "Malignancy is possible", "C": "Never contains neural tissue", "D": "Malignant only if bilateral"}, "r": "B", "e": {"correcta": "Unlike the mature (benign) cystic teratoma, an immature teratoma contains incompletely differentiated embryonic tissue (most often immature neuroectoderm), and this immaturity confers malignant potential, with behavior correlating to the amount of immature neural tissue present.", "incorrectas": {"A": "Immature teratomas are not always benign — the presence of immature (embryonic-like) tissue, especially neuroectoderm, is what gives them malignant potential, unlike their mature counterpart.", "C": "Immature teratomas classically do contain immature neuroectodermal tissue — that is in fact the tissue type most commonly responsible for their malignant behavior.", "D": "Malignant potential in immature teratoma is determined by the grade/amount of immature tissue (particularly neuroectoderm), not by laterality (bilaterality) of the tumor."}}}, {"id": "anking-reproductive-system-pathology-2225", "fuente": "anking", "tema": 8, "anki": "1463187938130", "q": "Which fetal tissue type is most commonly responsible for malignancy in an immature ovarian teratoma?", "o": {"A": "Immature cartilage", "B": "Immature skin", "C": "Immature neuroectoderm", "D": "Immature gut epithelium"}, "r": "C", "e": {"correcta": "Immature (embryonic-appearing) neuroectodermal tissue is the tissue type most commonly seen and most responsible for the malignant behavior of immature teratomas; the amount of this immature neural tissue correlates with tumor grade and prognosis.", "incorrectas": {"A": "Cartilage can be present in teratomas but is not the classic immature tissue driving malignancy in this tumor type.", "B": "Skin (and its appendages) is a common mature component of teratomas generally, but it is not the tissue associated with the malignant, immature component.", "D": "Gut epithelium can appear in teratomas as a mature element but is not the tissue type classically implicated in conferring malignant potential."}}}, {"id": "anking-reproductive-system-pathology-2226", "fuente": "anking", "tema": 8, "anki": "1463187941201", "q": "Beyond containing immature tissue, cystic teratomas can also become malignant through which additional mechanism?", "o": {"A": "Germline BRCA mutation", "B": "Somatic malignant transformation of a mature tissue component", "C": "Loss of imprinting", "D": "Chromosomal translocation t(11;22)"}, "r": "B", "e": {"correcta": "Cystic teratomas can rarely undergo somatic malignant transformation, meaning one of the mature tissue components within the tumor (most often skin) itself becomes malignant, giving rise most commonly to a squamous cell carcinoma arising within the teratoma.", "incorrectas": {"A": "BRCA mutations are associated with hereditary breast and ovarian (typically serous epithelial) cancer risk, not the mechanism by which a teratoma's own tissue becomes cancerous.", "C": "Loss of imprinting is a mechanism relevant to conditions like Beckwith-Wiedemann syndrome and certain germ cell tumor genetics, not the specific process of a teratoma's mature tissue turning malignant.", "D": "t(11;22) is the classic translocation of Ewing sarcoma, unrelated to the somatic malignant transformation seen within a cystic teratoma."}}}, {"id": "anking-reproductive-system-pathology-2227", "fuente": "anking", "tema": 8, "anki": "1463187950548", "q": "When a cystic teratoma undergoes somatic malignant transformation, which cancer type most commonly arises?", "o": {"A": "Adenocarcinoma of thyroid tissue", "B": "Squamous cell carcinoma of skin", "C": "Small cell carcinoma", "D": "Osteosarcoma of bone tissue"}, "r": "B", "e": {"correcta": "Because cystic teratomas commonly contain mature skin tissue, the most common somatic malignancy that arises within them is squamous cell carcinoma originating from that epidermal component.", "incorrectas": {"A": "Thyroid tissue can be present in a teratoma (struma ovarii), and can rarely become malignant, but this is much less common than squamous cell carcinoma arising from the skin component.", "C": "Small cell carcinoma is not the characteristic somatic malignancy described arising from teratoma tissue components.", "D": "Osteosarcoma arising from bone tissue within a teratoma is a rare, less classic occurrence compared to squamous cell carcinoma from skin, which is the most commonly cited transformation."}}}, {"id": "anking-reproductive-system-pathology-2228", "fuente": "anking", "tema": 8, "anki": "1463187961223", "q": "What is the most common malignant germ cell tumor of the ovary in females, accounting for about 30% of germ cell tumors?", "o": {"A": "Choriocarcinoma", "B": "Embryonal carcinoma", "C": "Endodermal sinus tumor", "D": "Dysgerminoma"}, "r": "D", "e": {"correcta": "Dysgerminoma is the most common malignant ovarian germ cell tumor, comprising about 30% of germ cell tumors (roughly 1% of all ovarian tumors); it is composed of large cells identical to primordial germ cells, analogous to testicular seminoma.", "incorrectas": {"A": "Choriocarcinoma is a highly aggressive but much rarer germ cell tumor producing hCG from malignant trophoblastic cells, not the most common malignant germ cell tumor.", "B": "Embryonal carcinoma is an aggressive tumor of primitive cells with early metastasis, but it occurs far less frequently than dysgerminoma among ovarian germ cell malignancies.", "C": "Endodermal sinus (yolk sac) tumor is the most common germ cell tumor in young children, but dysgerminoma remains the most common malignant germ cell tumor in females overall."}}}, {"id": "anking-reproductive-system-pathology-2229", "fuente": "anking", "tema": 8, "anki": "1463188002544", "q": "Ovarian dysgerminoma is the histologic and biologic equivalent of which testicular germ cell tumor in males?", "o": {"A": "Embryonal carcinoma", "B": "Yolk sac tumor", "C": "Seminoma", "D": "Choriocarcinoma"}, "r": "C", "e": {"correcta": "Dysgerminoma is the female counterpart of testicular seminoma — both arise from primordial germ cells, share similar histology (large cells with clear cytoplasm and lymphocytic infiltrate), and are notably radiosensitive with a good prognosis.", "incorrectas": {"A": "Embryonal carcinoma is a distinct, more aggressive germ cell tumor type in both sexes, not the tumor that dysgerminoma is considered equivalent to.", "B": "Yolk sac (endodermal sinus) tumor is the AFP-secreting germ cell tumor analog present in both ovary and testis, but it is a separate entity from dysgerminoma/seminoma.", "D": "Choriocarcinoma is the hCG-producing trophoblastic tumor type, a distinct germ cell tumor from dysgerminoma/seminoma."}}}, {"id": "anking-reproductive-system-pathology-2230", "fuente": "anking", "tema": 8, "anki": "1463188008567", "q": "What is the general prognosis of ovarian dysgerminoma, given its responsiveness to radiotherapy?", "o": {"A": "Poor, with rapid early metastasis", "B": "Good", "C": "Uniformly fatal within a year", "D": "Prognosis is unpredictable and unrelated to treatment"}, "r": "B", "e": {"correcta": "Dysgerminoma has a good prognosis, largely because it is highly radiosensitive (and also chemosensitive), allowing for effective treatment even though it is a malignant germ cell tumor.", "incorrectas": {"A": "Dysgerminoma does not behave like an aggressive, rapidly metastasizing tumor such as embryonal carcinoma or choriocarcinoma; its radiosensitivity contributes to a favorable outcome.", "C": "Dysgerminoma is not uniformly fatal — its excellent response to radiotherapy is exactly why it carries a favorable prognosis compared to other malignant germ cell tumors.", "D": "The prognosis is well characterized as good specifically because of its known responsiveness to radiotherapy, not unpredictable or unrelated to treatment."}}}, {"id": "anking-reproductive-system-pathology-2231", "fuente": "anking", "tema": 8, "anki": "1463188017836", "q": "Which two serum markers may be elevated in a patient with ovarian dysgerminoma?", "o": {"A": "AFP and CA-125", "B": "hCG and CA 19-9", "C": "LDH and hCG", "D": "AFP and LDH"}, "r": "C", "e": {"correcta": "Dysgerminoma can elevate LDH (a marker of high cellular turnover common to this tumor) and hCG, the latter reflecting occasional syncytiotrophoblastic giant cells within the tumor even though it is not a pure choriocarcinoma.", "incorrectas": {"A": "AFP is the classic marker for yolk sac (endodermal sinus) tumor, not dysgerminoma; CA-125 is associated with surface epithelial tumors, not germ cell tumors like dysgerminoma.", "B": "CA 19-9 is not a marker classically associated with dysgerminoma; it is more relevant to gastrointestinal and pancreatic malignancies.", "D": "AFP elevation points toward yolk sac tumor or mixed germ cell tumor with a yolk sac component, not pure dysgerminoma, which is marked by LDH and sometimes hCG instead."}}}, {"id": "anking-reproductive-system-pathology-2232", "fuente": "anking", "tema": 8, "anki": "1463188027127", "q": "Ovarian dysgerminoma is most commonly diagnosed in which patient population?", "o": {"A": "Postmenopausal women", "B": "Adolescent and young adult females", "C": "Prepubertal children under age 5", "D": "Women in their 40s and 50s"}, "r": "B", "e": {"correcta": "Dysgerminoma classically occurs in adolescent and young adult females, consistent with the general pattern of ovarian germ cell tumors arising in women of reproductive age rather than in postmenopausal women.", "incorrectas": {"A": "Postmenopausal women are the classic demographic for malignant surface epithelial tumors (e.g., serous cystadenocarcinoma), not germ cell tumors like dysgerminoma.", "C": "While germ cell tumors like yolk sac tumor can appear in young children, dysgerminoma specifically is most characteristic of adolescents and young women, not prepubertal children.", "D": "Women in their 40s-50s are not the classic age group for dysgerminoma; this tumor peaks earlier, in adolescence and young adulthood."}}}, {"id": "anking-reproductive-system-pathology-2233", "fuente": "anking", "tema": 8, "anki": "1463188032640", "q": "Which germ cell tumor is the most common cause of ovarian or testicular malignancy in young children, especially male infants, and can also arise in the sacrococcygeal area?", "o": {"A": "Dysgerminoma/seminoma", "B": "Choriocarcinoma", "C": "Embryonal carcinoma", "D": "Endodermal sinus (yolk sac) tumor"}, "r": "D", "e": {"correcta": "Endodermal sinus (yolk sac) tumor is the most common germ cell tumor in young children, particularly male infants, and characteristically arises in the gonads or the sacrococcygeal region, producing elevated AFP as it recapitulates yolk sac tissue.", "incorrectas": {"A": "Dysgerminoma/seminoma is the most common malignant germ cell tumor overall in adolescents and young adults, but yolk sac tumor is specifically the most common in young children and infants.", "B": "Choriocarcinoma is a rare, aggressive trophoblastic tumor typically related to gestational disease, not the characteristic pediatric germ cell tumor of the gonads/sacrococcygeal region.", "C": "Embryonal carcinoma is an aggressive germ cell tumor of primitive cells, but it is not the classic most common germ cell tumor described in young children/male infants."}}}, {"id": "anking-reproductive-system-pathology-2234", "fuente": "anking", "tema": 8, "anki": "1463188061833", "q": "Which malignant germ cell tumor histologically mimics the yolk sac and is also known as the endodermal sinus tumor?", "o": {"A": "Embryonal carcinoma", "B": "Endodermal sinus (yolk sac) tumor", "C": "Dysgerminoma", "D": "Immature teratoma"}, "r": "B", "e": {"correcta": "The endodermal sinus tumor, also called the yolk sac tumor, is a malignant germ cell neoplasm that recapitulates extraembryonic yolk sac tissue, which is why it characteristically secretes AFP, a protein normally produced by the yolk sac.", "incorrectas": {"A": "Embryonal carcinoma is composed of primitive, undifferentiated cells resembling early embryonic tissue, distinct from the specific yolk sac-like differentiation of the endodermal sinus tumor.", "C": "Dysgerminoma resembles primordial germ cells and lacks the yolk sac-like glomeruloid structures that define the endodermal sinus tumor.", "D": "Immature teratoma contains embryonic tissue from multiple germ layers (often neuroectoderm), which is a different pattern from the yolk sac mimicry of the endodermal sinus tumor."}}}, {"id": "anking-reproductive-system-pathology-2235", "fuente": "anking", "tema": 8, "anki": "1463188066226", "q": "Which serum marker is characteristically elevated in endodermal sinus (yolk sac) tumor, reflecting its resemblance to fetal yolk sac tissue?", "o": {"A": "hCG", "B": "CA-125", "C": "Alpha-fetoprotein (AFP)", "D": "LDH"}, "r": "C", "e": {"correcta": "Alpha-fetoprotein (AFP) is characteristically elevated in endodermal sinus (yolk sac) tumor because the tumor recapitulates yolk sac tissue, which normally produces AFP during fetal development — making AFP a useful marker for diagnosis and monitoring.", "incorrectas": {"A": "hCG is the marker for choriocarcinoma (and can be mildly elevated in dysgerminoma from syncytiotrophoblastic cells), not the characteristic marker for yolk sac tumor.", "B": "CA-125 is associated with surface epithelial ovarian tumors, not germ cell tumors like the endodermal sinus tumor.", "D": "LDH can be elevated in dysgerminoma reflecting high cell turnover, but AFP is the specific, characteristic marker tied to yolk sac tumor."}}}, {"id": "anking-reproductive-system-pathology-2236", "fuente": "anking", "tema": 8, "anki": "1463188070821", "q": "Endodermal sinus (yolk sac) tumors are characterized histologically, in about 50% of cases, by which structure?", "o": {"A": "Call-Exner bodies", "B": "Psammoma bodies", "C": "Schiller-Duval bodies (glomeruloid structures)", "D": "Reinke crystals"}, "r": "C", "e": {"correcta": "Schiller-Duval bodies are glomeruloid structures — a central blood vessel surrounded by a layer of tumor cells within a space lined by additional tumor cells — seen in about half of endodermal sinus (yolk sac) tumors, mimicking primitive glomeruli and reflecting the tumor's yolk sac differentiation.", "incorrectas": {"A": "Call-Exner bodies are small follicle-like structures containing eosinophilic material seen in granulosa cell tumors, a sex cord-stromal tumor, not the yolk sac tumor.", "B": "Psammoma bodies are concentric calcifications classically seen in serous (papillary) tumors, meningiomas, and papillary thyroid carcinoma, not yolk sac tumor.", "D": "Reinke crystals are cytoplasmic crystalline inclusions found in Leydig cell tumors of the testis, unrelated to the yolk sac tumor's Schiller-Duval bodies."}}}, {"id": "anking-reproductive-system-pathology-2237", "fuente": "anking", "tema": 8, "anki": "1463188088647", "q": "A patient with choriocarcinoma develops hemoptysis and shortness of breath. This reflects which characteristic pattern of spread for this tumor?", "o": {"A": "Slow lymphatic spread to pelvic nodes only", "B": "Early, diffuse hematogenous spread, especially to the lungs", "C": "Direct local invasion without distant spread", "D": "Spread confined to the peritoneal cavity"}, "r": "B", "e": {"correcta": "Choriocarcinoma is a small, hemorrhagic tumor that spreads early and diffusely via the bloodstream, with the lungs being a particularly common site — explaining presentations like hemoptysis and dyspnea; it can also metastasize to the brain.", "incorrectas": {"A": "Choriocarcinoma is not characterized by slow, node-limited lymphatic spread; its hallmark is rapid hematogenous dissemination, which explains distant lung and brain metastases rather than isolated nodal disease.", "C": "While local extension can occur, the defining and clinically significant feature of choriocarcinoma is its propensity for early, widespread hematogenous metastasis, not confinement to local tissue.", "D": "Peritoneal spread (as seen with ovarian surface epithelial tumors) is not the classic pattern for choriocarcinoma, which instead spreads through the blood to distant organs like lung and brain."}}}, {"id": "anking-reproductive-system-pathology-2238", "fuente": "anking", "tema": 8, "anki": "1463188095823", "q": "Which serum marker, produced by syncytiotrophoblasts, is characteristically elevated in choriocarcinoma?", "o": {"A": "AFP", "B": "LDH", "C": "hCG", "D": "CA-125"}, "r": "C", "e": {"correcta": "hCG is produced by the malignant syncytiotrophoblastic cells that make up choriocarcinoma, so serum hCG is characteristically markedly elevated; the resulting hCG excess can also stimulate the ovaries to form theca-lutein cysts.", "incorrectas": {"A": "AFP is the marker associated with yolk sac (endodermal sinus) tumor, produced by cells mimicking yolk sac tissue, not by the trophoblastic cells of choriocarcinoma.", "B": "LDH is elevated in dysgerminoma due to high cellular turnover, not the characteristic marker for choriocarcinoma, which is defined by its hCG-secreting trophoblastic cells.", "D": "CA-125 is associated with surface epithelial ovarian tumors and is not the marker produced by trophoblastic tissue in choriocarcinoma."}}}, {"id": "anking-reproductive-system-pathology-2239", "fuente": "anking", "tema": 8, "anki": "1463188103442", "q": "Choriocarcinoma is classically associated with which type of ovarian cyst, resulting from excess hCG stimulation?", "o": {"A": "Follicular cyst", "B": "Corpus luteum cyst", "C": "Theca-lutein cyst", "D": "Chocolate cyst (endometrioma)"}, "r": "C", "e": {"correcta": "Choriocarcinoma secretes very high levels of hCG, which over-stimulates the ovarian theca cells, producing bilateral theca-lutein cysts — a hallmark finding also seen in other conditions of hCG excess like hydatidiform mole.", "incorrectas": {"A": "Follicular cysts arise from a failure of a dominant follicle to rupture or from atresia and are not specifically driven by the marked hCG elevation seen in choriocarcinoma.", "B": "Corpus luteum cysts form from a hemorrhagic or persistent corpus luteum after ovulation, not from the hCG-driven theca cell hyperstimulation characteristic of choriocarcinoma.", "D": "Chocolate cysts (endometriomas) are cystic accumulations of old blood in ovarian endometriosis, unrelated to hCG-driven theca-lutein cyst formation in choriocarcinoma."}}}, {"id": "anking-reproductive-system-pathology-2240", "fuente": "anking", "tema": 8, "anki": "1463188119098", "q": "A malignant germ cell tumor of the ovary or testis composed of large, primitive cells with an aggressive course and early metastasis is best classified as which tumor?", "o": {"A": "Dysgerminoma", "B": "Embryonal carcinoma", "C": "Mature teratoma", "D": "Brenner tumor"}, "r": "B", "e": {"correcta": "Embryonal carcinoma is a highly aggressive germ cell tumor composed of large, primitive, undifferentiated cells that can arise in the ovary or testis and is notable for early hematogenous and lymphatic metastasis.", "incorrectas": {"A": "Dysgerminoma (seminoma in males) is composed of cells resembling primordial germ cells and, while malignant, is generally less aggressive and more radiosensitive than embryonal carcinoma.", "C": "Mature teratoma is a benign tumor of fully differentiated tissue, the opposite of the primitive, aggressive cell population that defines embryonal carcinoma.", "D": "Brenner tumor is a benign surface epithelial tumor with transitional-type epithelium, unrelated to the primitive germ cell population of embryonal carcinoma."}}}, {"id": "anking-reproductive-system-pathology-2241", "fuente": "anking", "tema": 8, "anki": "1463188127235", "q": "Which is the most common malignant sex cord-stromal tumor of the ovary?", "o": {"A": "Sertoli-Leydig cell tumor", "B": "Fibroma", "C": "Thecoma", "D": "Granulosa cell tumor"}, "r": "D", "e": {"correcta": "Granulosa cell tumor is the most common malignant ovarian sex cord-stromal tumor; it often secretes estrogen (causing precocious puberty in girls or endometrial hyperplasia/abnormal bleeding in adults) and classically shows Call-Exner bodies on histology.", "incorrectas": {"A": "Sertoli-Leydig cell tumor is a rarer sex cord-stromal tumor typically associated with androgen excess and virilization, not the most common malignant tumor in this category.", "B": "Fibroma is a benign sex cord-stromal tumor composed of fibroblasts, associated with Meigs syndrome, and is not malignant.", "C": "Thecoma is a generally benign, estrogen-secreting sex cord-stromal tumor, distinct from the more common and potentially malignant granulosa cell tumor."}}}, {"id": "anking-reproductive-system-pathology-2242", "fuente": "anking", "tema": 8, "anki": "1463188165692", "q": "Granulosa cell tumor of the ovary predominantly affects women in which decade of life?", "o": {"A": "20s", "B": "30s", "C": "50s", "D": "70s"}, "r": "C", "e": {"correcta": "Granulosa cell tumors are estrogen-secreting sex cord-stromal tumors that classically occur in women in their 50s, often around the time of menopause, presenting with abnormal uterine bleeding or precocious puberty in younger patients due to excess estrogen production.", "incorrectas": {"A": "Women in their 20s are more typically affected by germ cell tumors of the ovary (e.g., dysgerminoma, teratoma), which arise in a much younger population than granulosa cell tumors.", "B": "Women in their 30s are not the classic age group for granulosa cell tumors; this age range is more associated with early presentations of endometriosis or benign functional cysts rather than sex cord-stromal neoplasms.", "D": "Women in their 70s are less characteristic for granulosa cell tumor; while ovarian cancer risk rises with age generally, this particular estrogen-producing tumor is specifically associated with the perimenopausal to postmenopausal 50s age range."}}}, {"id": "anking-reproductive-system-pathology-2243", "fuente": "anking", "tema": 8, "anki": "1463188185291", "q": "A postmenopausal woman presents with abnormal uterine bleeding. Workup reveals an estrogen-secreting ovarian sex cord-stromal tumor composed of spindle cells resembling fibroblasts. What is the most likely diagnosis?", "o": {"A": "Thecoma", "B": "Sertoli-Leydig cell tumor", "C": "Fibroma", "D": "Krukenberg tumor"}, "r": "A", "e": {"correcta": "Thecoma is a benign sex cord-stromal tumor composed of theca cells that, like granulosa cell tumors, secretes estrogen, classically causing abnormal uterine bleeding in postmenopausal women due to unopposed endometrial stimulation.", "incorrectas": {"B": "Sertoli-Leydig cell tumor produces androgens rather than estrogen, leading to hirsutism and virilization rather than estrogen-mediated bleeding, making it the opposite hormonal profile from thecoma.", "C": "Fibroma is a hormonally inactive sex cord-stromal tumor composed of fibroblasts; it does not secrete estrogen and instead presents with a pulling sensation or as part of Meigs syndrome (ascites and pleural effusion).", "D": "Krukenberg tumor is a metastatic mucin-producing signet ring cell adenocarcinoma (usually from the GI tract, often stomach) to the ovary, which is not hormonally active and is unrelated to sex cord-stromal estrogen production."}}}, {"id": "anking-reproductive-system-pathology-2244", "fuente": "anking", "tema": 8, "anki": "1463188216971", "q": "A rare ovarian sex cord-stromal tumor secretes androgens. Which clinical finding would this tumor most likely cause in an affected woman?", "o": {"A": "Precocious puberty", "B": "Hirsutism/virilization", "C": "Galactorrhea", "D": "Postmenopausal bleeding"}, "r": "B", "e": {"correcta": "Sertoli-Leydig cell tumors are rare androgen-secreting ovarian sex cord-stromal tumors; the excess testosterone/androgen production leads to hirsutism and virilization, including features like clitoromegaly, deepening voice, and male-pattern hair growth.", "incorrectas": {"A": "Precocious puberty is more typical of estrogen-secreting tumors such as granulosa cell tumors, not androgen-secreting Sertoli-Leydig tumors, since precocious puberty in girls is driven by early estrogen exposure.", "C": "Galactorrhea results from hyperprolactinemia (e.g., prolactinoma), a distinct endocrine pathway unrelated to ovarian androgen secretion from Sertoli-Leydig cell tumors.", "D": "Postmenopausal bleeding is the classic presentation of estrogen-secreting tumors like granulosa cell tumor or thecoma, which stimulate the endometrium, not of androgen-secreting Sertoli-Leydig tumors."}}}, {"id": "anking-reproductive-system-pathology-2245", "fuente": "anking", "tema": 8, "anki": "1463188227727", "q": "A solid ovarian mass composed of bundles of spindle-shaped fibroblasts with white fibrous bands on gross exam, and no hormonal activity, is most consistent with which sex cord-stromal tumor?", "o": {"A": "Fibroma", "B": "Thecoma", "C": "Granulosa cell tumor", "D": "Sertoli-Leydig cell tumor"}, "r": "A", "e": {"correcta": "Fibromas are benign sex cord-stromal tumors composed of fibroblasts arranged in spindle-shaped bundles, grossly appearing as solid white masses with fibrous bands; unlike other sex cord-stromal tumors, they are typically hormonally silent.", "incorrectas": {"B": "Thecoma is composed of theca cells rather than fibroblasts and is hormonally active, secreting estrogen and causing abnormal bleeding, in contrast to the fibroblastic, non-secreting nature of fibroma.", "C": "Granulosa cell tumor arises from granulosa cells, not fibroblasts, and is characteristically estrogen-secreting, producing Call-Exner bodies histologically rather than fibrous spindle-cell bundles.", "D": "Sertoli-Leydig cell tumor is composed of Sertoli and Leydig cells that secrete androgens, a hormonally active tumor type distinct from the inactive, fibroblast-derived fibroma."}}}, {"id": "anking-reproductive-system-pathology-2246", "fuente": "anking", "tema": 8, "anki": "1463188240255", "q": "Which ovarian sex cord-stromal tumor may present with a \"pulling\" sensation in the groin, related to ovarian torsion or tumor traction?", "o": {"A": "Thecoma", "B": "Fibroma", "C": "Sertoli-Leydig cell tumor", "D": "Granulosa cell tumor"}, "r": "B", "e": {"correcta": "Fibroma, a solid benign ovarian sex cord-stromal tumor of fibroblasts, can be large and heavy, predisposing to ovarian torsion or traction on the ovarian ligaments, which classically produces a dull \"pulling\" sensation in the groin or pelvis.", "incorrectas": {"A": "Thecoma is more classically associated with estrogenic effects such as postmenopausal bleeding rather than the mechanical pulling sensation attributed to the solid, torsion-prone fibroma.", "C": "Sertoli-Leydig cell tumor is primarily recognized for its androgenic manifestations (hirsutism, virilization) rather than a mechanical groin-pulling sensation.", "D": "Granulosa cell tumor is best known for its estrogenic effects (abnormal bleeding, precocious puberty) rather than the mechanical traction symptoms characteristic of fibroma."}}}, {"id": "anking-reproductive-system-pathology-2247", "fuente": "anking", "tema": 8, "anki": "1463188251805", "q": "In contrast to primary mucinous ovarian tumors, which are usually unilateral, Krukenberg tumors of the ovary are typically what laterality?", "o": {"A": "Unilateral, right-sided only", "B": "Unilateral, left-sided only", "C": "Bilateral", "D": "Midline, involving the uterus"}, "r": "C", "e": {"correcta": "Krukenberg tumors are metastatic mucin-producing signet ring cell carcinomas (classically from the stomach) that spread to both ovaries, making them characteristically bilateral, which helps distinguish metastatic disease from primary ovarian mucinous tumors.", "incorrectas": {"A": "Krukenberg tumors are not restricted to unilateral right-sided involvement; their hematogenous or lymphatic/transperitoneal spread from a GI primary typically seeds both ovaries simultaneously.", "B": "Similarly, left-sided-only involvement does not describe the classic bilateral pattern seen with Krukenberg tumors, which is a key distinguishing feature from primary unilateral ovarian mucinous neoplasms.", "D": "Krukenberg tumors involve the ovaries themselves (as metastatic deposits), not the uterus; uterine involvement is not the defining laterality feature being tested here."}}}, {"id": "anking-reproductive-system-pathology-2248", "fuente": "anking", "tema": 8, "anki": "1463188255248", "q": "A patient with a mucinous tumor of the appendix develops massive accumulation of gelatinous mucus in the peritoneal cavity with metastasis to the ovary. What is this condition called?", "o": {"A": "Krukenberg tumor", "B": "Meigs syndrome", "C": "Pseudomyxoma peritonei", "D": "Peritoneal carcinomatosis"}, "r": "C", "e": {"correcta": "Pseudomyxoma peritonei is characterized by massive amounts of mucinous material filling the peritoneal cavity, most often arising from a ruptured mucinous tumor of the appendix that seeds the peritoneum and frequently metastasizes to the ovaries.", "incorrectas": {"A": "Krukenberg tumor refers specifically to bilateral ovarian metastases containing signet ring cells, typically from a gastric primary, rather than the diffuse mucinous peritoneal accumulation seen in pseudomyxoma peritonei.", "B": "Meigs syndrome is the triad of a benign ovarian tumor (typically fibroma), ascites, and pleural effusion, unrelated to appendiceal mucinous tumors or peritoneal mucus accumulation.", "D": "Peritoneal carcinomatosis is a general term for diffuse peritoneal metastatic spread of carcinoma, but it lacks the specific gelatinous mucinous character and appendiceal origin that define pseudomyxoma peritonei."}}}, {"id": "anking-reproductive-system-pathology-2249", "fuente": "anking", "tema": 8, "anki": "1463279445274", "q": "What is the most common specific anatomic site for an ectopic pregnancy to implant?", "o": {"A": "Ampulla of the fallopian tube", "B": "Ovary", "C": "Cervix", "D": "Abdominal cavity"}, "r": "A", "e": {"correcta": "The ampulla of the fallopian tube is the most common site of ectopic implantation because it is the widest and most common location for fertilization, and any obstruction or dysmotility of the tube (e.g., from scarring) can cause the embryo to implant there instead of migrating to the uterus.", "incorrectas": {"B": "Ovarian ectopic pregnancy is a rare form of ectopic pregnancy, accounting for a small minority of cases, and is far less common than tubal implantation in the ampulla.", "C": "Cervical ectopic pregnancy is also rare, occurring when the embryo implants in the endocervical canal, but this is a much less frequent site compared to the fallopian tube ampulla.", "D": "Abdominal ectopic pregnancy, where the embryo implants within the peritoneal cavity, is the rarest type of ectopic pregnancy and not the most common site."}}}, {"id": "anking-reproductive-system-pathology-2250", "fuente": "anking", "tema": 8, "anki": "1463279616645", "q": "A woman presents with right lower quadrant pain and a positive pregnancy test. This presentation of ectopic pregnancy is often clinically mistaken for which condition?", "o": {"A": "Cholecystitis", "B": "Appendicitis", "C": "Diverticulitis", "D": "Pyelonephritis"}, "r": "B", "e": {"correcta": "Ectopic pregnancy classically presents with lower quadrant abdominal pain (often on the right side), which overlaps significantly with the presentation of appendicitis, making the two diagnoses easily confused, especially since both can present with peritoneal signs.", "incorrectas": {"A": "Cholecystitis typically presents with right upper quadrant pain, often after fatty meals, a distinctly different location and trigger from the lower quadrant pain of ectopic pregnancy.", "C": "Diverticulitis classically presents with left lower quadrant pain, making it less commonly confused with a right-sided or nonspecific lower quadrant ectopic pregnancy presentation.", "D": "Pyelonephritis presents with flank pain, fever, and costovertebral angle tenderness, a symptom pattern distinct from the lower quadrant pain that leads to ectopic pregnancy being mistaken for appendicitis."}}}, {"id": "anking-reproductive-system-pathology-2251", "fuente": "anking", "tema": 8, "anki": "1463279630622", "q": "What is the key risk factor for ectopic pregnancy?", "o": {"A": "Uterine fibroids", "B": "Tubal scarring", "C": "Bicornuate uterus", "D": "Multiple gestation"}, "r": "B", "e": {"correcta": "Tubal scarring is the key risk factor for ectopic pregnancy because it impairs normal transport of the fertilized egg through the fallopian tube, causing it to implant within the tube itself; common causes include pelvic inflammatory disease, ruptured appendicitis, prior tubal surgery, prior ectopic pregnancy, and endometriosis.", "incorrectas": {"A": "Uterine fibroids can distort the uterine cavity and affect fertility or implantation within the uterus, but they are not the primary risk factor for tubal (ectopic) implantation compared to tubal scarring.", "C": "Bicornuate uterus is a congenital uterine anomaly associated with recurrent pregnancy loss and preterm labor, not specifically identified as the key risk factor for ectopic pregnancy.", "D": "Multiple gestation (e.g., from assisted reproduction) can slightly increase ectopic pregnancy risk in some contexts, but it is not considered the principal risk factor compared to tubal scarring from infection or prior surgery."}}}, {"id": "anking-reproductive-system-pathology-2252", "fuente": "anking", "tema": 8, "anki": "1463279639694", "q": "A woman presents with amenorrhea followed weeks later by abdominal pain. Which location of pain is classic for ectopic pregnancy?", "o": {"A": "Epigastric", "B": "Lower quadrant abdominal", "C": "Suprapubic midline only", "D": "Bilateral flank"}, "r": "B", "e": {"correcta": "The classic presentation of ectopic pregnancy is lower quadrant abdominal pain occurring weeks after a missed period (amenorrhea), most commonly around 6.5 weeks of gestation; this reflects the tubal location of implantation and warrants prompt evaluation with laparoscopy or methotrexate treatment.", "incorrectas": {"A": "Epigastric pain is more characteristic of upper GI processes (e.g., peptic ulcer disease, pancreatitis) or severe preeclampsia/HELLP syndrome with liver involvement, not the classic tubal ectopic pregnancy presentation.", "C": "Isolated suprapubic midline pain without lateralization is less typical, as ectopic pregnancy pain usually localizes to the lower quadrant corresponding to the affected fallopian tube.", "D": "Bilateral flank pain suggests a renal or retroperitoneal process such as pyelonephritis or bilateral hydronephrosis, not the lower quadrant abdominal pain classically seen with ectopic pregnancy."}}}, {"id": "anking-reproductive-system-pathology-2253", "fuente": "anking", "tema": 8, "anki": "1463279658641", "q": "Which of the following are major complications of ectopic pregnancy that make it a surgical emergency?", "o": {"A": "Placenta accreta and abruption", "B": "Hematosalpinx and rupture", "C": "Preeclampsia and eclampsia", "D": "Spontaneous abortion and stillbirth"}, "r": "B", "e": {"correcta": "Ectopic pregnancy can cause hematosalpinx (bleeding into the fallopian tube) and/or tubal rupture, both of which can lead to life-threatening intra-abdominal hemorrhage, making ectopic pregnancy a surgical emergency requiring prompt diagnosis and treatment.", "incorrectas": {"A": "Placenta accreta and abruption are complications of intrauterine pregnancies related to abnormal placental attachment or premature separation, not complications of an ectopic (extrauterine) pregnancy.", "C": "Preeclampsia and eclampsia are hypertensive disorders of pregnancy typically arising after 20 weeks gestation in an intrauterine pregnancy, unrelated to the early first-trimester complications of ectopic pregnancy.", "D": "Spontaneous abortion and stillbirth refer to pregnancy loss within the uterus at different gestational stages, not the tubal bleeding and rupture complications specific to ectopic implantation."}}}, {"id": "anking-reproductive-system-pathology-2254", "fuente": "anking", "tema": 8, "anki": "1463279666723", "q": "Spontaneous abortion is defined as miscarriage of a fetus before which gestational age?", "o": {"A": "12 weeks", "B": "16 weeks", "C": "20 weeks", "D": "24 weeks"}, "r": "C", "e": {"correcta": "Spontaneous abortion is defined as the loss of a pregnancy before 20 weeks of gestation; this cutoff distinguishes it from later fetal losses (stillbirth), which occur after 20 weeks and are managed and classified differently.", "incorrectas": {"A": "12 weeks marks the end of the first trimester, a period of high spontaneous abortion risk, but it is not the defined cutoff for the diagnosis of spontaneous abortion itself.", "B": "16 weeks falls within the second trimester and is not the standard gestational age cutoff used to define spontaneous abortion.", "D": "24 weeks is often used as a threshold for fetal viability in obstetric practice, but it is not the definitional cutoff for spontaneous abortion, which is set at 20 weeks."}}}, {"id": "anking-reproductive-system-pathology-2255", "fuente": "anking", "tema": 8, "anki": "1463279672655", "q": "Approximately what fraction of recognizable pregnancies end in spontaneous abortion?", "o": {"A": "1/10", "B": "1/4", "C": "1/2", "D": "3/4"}, "r": "B", "e": {"correcta": "Spontaneous abortion is common, occurring in up to 1 in 4 (25%) of recognizable pregnancies, reflecting the high baseline rate of early pregnancy loss, much of it due to chromosomal abnormalities incompatible with continued development.", "incorrectas": {"A": "1/10 underestimates the true frequency of spontaneous abortion among clinically recognized pregnancies, which is understood to be considerably higher.", "C": "1/2 overstates the incidence; while total pregnancy loss including unrecognized very early losses may be higher, the commonly cited figure for recognized pregnancies is about 1 in 4, not half.", "D": "3/4 substantially overstates the rate of spontaneous abortion in recognized pregnancies and does not reflect standard epidemiologic estimates."}}}, {"id": "anking-reproductive-system-pathology-2256", "fuente": "anking", "tema": 8, "anki": "1463279676639", "q": "A pregnant woman presents with vaginal bleeding, cramp-like pelvic pain, and passage of fetal tissue. What is the most likely diagnosis?", "o": {"A": "Placenta previa", "B": "Ectopic pregnancy", "C": "Spontaneous abortion", "D": "Placental abruption"}, "r": "C", "e": {"correcta": "Spontaneous abortion classically presents with vaginal bleeding, cramp-like lower abdominal pain, and passage of products of conception (fetal tissue), reflecting the uterus expelling a nonviable pregnancy before 20 weeks gestation.", "incorrectas": {"A": "Placenta previa classically presents with painless vaginal bleeding in the third trimester due to abnormal placental position over the cervical os, without cramping or passage of fetal tissue.", "B": "Ectopic pregnancy presents with lower quadrant abdominal pain and amenorrhea, often without passage of fetal tissue since the pregnancy is located outside the uterine cavity.", "D": "Placental abruption presents with painful vaginal bleeding and a rigid, tender uterus in later pregnancy due to premature separation of the placenta, not passage of fetal tissue characteristic of early miscarriage."}}}, {"id": "anking-reproductive-system-pathology-2257", "fuente": "anking", "tema": 8, "anki": "1463279681310", "q": "Spontaneous abortion is most often caused by which type of anomaly, especially trisomy 16?", "o": {"A": "Chromosomal", "B": "Infectious", "C": "Anatomic uterine", "D": "Autoimmune"}, "r": "A", "e": {"correcta": "The majority of spontaneous abortions are due to chromosomal anomalies, with trisomy 16 being the most common trisomy identified in early pregnancy loss; these abnormalities are typically incompatible with continued fetal development, resulting in early miscarriage.", "incorrectas": {"B": "Infectious causes (e.g., TORCH infections) can contribute to pregnancy loss but are not the most common overall cause of spontaneous abortion compared to chromosomal anomalies.", "C": "Anatomic uterine anomalies (e.g., bicornuate uterus, fibroids) are associated with recurrent pregnancy loss but are a less common cause overall than chromosomal abnormalities in sporadic spontaneous abortion.", "D": "Autoimmune conditions such as antiphospholipid syndrome are recognized causes of recurrent miscarriage, but chromosomal anomalies remain the most common cause of spontaneous abortion in general."}}}, {"id": "anking-reproductive-system-pathology-2258", "fuente": "anking", "tema": 8, "anki": "1463279705406", "q": "Exposure to a teratogen during the first two weeks of gestation (the \"all-or-none\" period) most commonly results in which outcome?", "o": {"A": "Organ hypoplasia", "B": "Organ malformation", "C": "Spontaneous abortion", "D": "Functional/behavioral defects only"}, "r": "C", "e": {"correcta": "During the first two weeks of gestation, often called the \"all-or-none\" period, teratogen exposure typically either causes no effect (if damage is minimal and cells are still totipotent) or leads to spontaneous abortion if the damage is severe enough, since organogenesis has not yet begun.", "incorrectas": {"A": "Organ hypoplasia is the classic effect of teratogen exposure after week 8 of gestation, during the fetal period when organs have already formed and are undergoing growth and maturation, not during the first two weeks.", "B": "Organ malformation is characteristic of teratogen exposure during weeks 3-8 of gestation (the embryonic period of organogenesis), not during the earliest pre-organogenesis weeks 1-2.", "D": "Functional or behavioral defects (e.g., from alcohol or certain neurotoxic exposures) are more typically associated with exposures throughout gestation, particularly later, rather than being the specific hallmark of the first two weeks."}}}, {"id": "anking-reproductive-system-pathology-2259", "fuente": "anking", "tema": 8, "anki": "1463279711383", "q": "Teratogen exposure during weeks 3-8 of gestation (the period of organogenesis) most commonly results in which outcome?", "o": {"A": "Spontaneous abortion", "B": "Organ malformation", "C": "Organ hypoplasia", "D": "No effect due to placental barrier"}, "r": "B", "e": {"correcta": "Weeks 3-8 of gestation constitute the embryonic period, during which organogenesis occurs; teratogen exposure during this critical window most commonly causes structural organ malformations, since the developing organ systems are highly sensitive to disruption at this stage.", "incorrectas": {"A": "Spontaneous abortion is the more typical outcome of teratogen exposure during the earliest all-or-none period (weeks 1-2), before organogenesis has begun, not during weeks 3-8.", "C": "Organ hypoplasia is characteristic of teratogen exposure after week 8, during the fetal period of growth and maturation, when organs have already formed and further insult impairs their growth rather than their structural formation.", "D": "The placenta does not provide a protective barrier against most teratogens during this period; in fact, weeks 3-8 represent peak vulnerability to structural malformation from teratogen exposure."}}}, {"id": "anking-reproductive-system-pathology-2260", "fuente": "anking", "tema": 8, "anki": "1463279718206", "q": "Teratogen exposure occurring after week 8 of gestation (the fetal period) most commonly results in which effect?", "o": {"A": "Spontaneous abortion", "B": "Organ malformation", "C": "Organ hypoplasia", "D": "Neural tube defects"}, "r": "C", "e": {"correcta": "After week 8 of gestation, organogenesis is largely complete and the fetus enters a period of growth and functional maturation; teratogen exposure during this fetal period most commonly causes organ hypoplasia (reduced growth/size) rather than structural malformation.", "incorrectas": {"A": "Spontaneous abortion is the characteristic outcome of teratogen exposure during the earliest all-or-none period (weeks 1-2), a much earlier stage than the fetal period after week 8.", "B": "Organ malformation is the hallmark of teratogen exposure during weeks 3-8 (organogenesis), when organ structures are actively forming, in contrast to the growth-phase hypoplasia seen after week 8.", "D": "Neural tube defects arise from disruptions during neural tube closure, which occurs by around week 4 of gestation (within the organogenesis window), not from teratogen exposure after week 8."}}}, {"id": "anking-reproductive-system-pathology-2261", "fuente": "anking", "tema": 8, "anki": "1463279752475", "q": "Which of the following is a recognized risk factor for placenta previa?", "o": {"A": "Nulliparity", "B": "Prior C-section", "C": "Preeclampsia", "D": "Post-term pregnancy"}, "r": "B", "e": {"correcta": "Prior cesarean section (along with multiparity) is a well-established risk factor for placenta previa, likely because uterine scarring from prior surgery alters normal endometrial vascularization and favors abnormal low placental implantation over the cervical os in subsequent pregnancies.", "incorrectas": {"A": "Nulliparity (never having given birth) is not a risk factor for placenta previa; in fact, multiparity, the opposite condition, increases risk due to cumulative uterine changes from prior pregnancies.", "C": "Preeclampsia is a hypertensive disorder of pregnancy related to abnormal placental vasculature and is a separate condition from placenta previa, which relates to placental position rather than blood pressure.", "D": "Post-term pregnancy (pregnancy extending beyond 42 weeks) is not associated with placenta previa; previa is typically identified earlier via ultrasound and relates to implantation location, not gestational duration."}}}, {"id": "anking-reproductive-system-pathology-2262", "fuente": "anking", "tema": 8, "anki": "1463279757292", "q": "Premature separation of the placenta from the uterine wall (decidua) prior to delivery of the fetus is known as placental what?", "o": {"A": "Previa", "B": "Abruption", "C": "Accreta", "D": "Percreta"}, "r": "B", "e": {"correcta": "Placental abruption is the premature separation of the placenta from the decidua before delivery, causing painful vaginal bleeding and fetal compromise; risk factors include trauma, smoking, hypertension, preeclampsia, and cocaine use.", "incorrectas": {"A": "Placenta previa refers to abnormal placental implantation over or near the internal cervical os, causing painless bleeding, rather than premature separation of a normally implanted placenta.", "C": "Placenta accreta refers to abnormal attachment of the placenta to the myometrium without penetrating it, a disorder of adherence rather than premature separation as seen in abruption.", "D": "Placenta percreta refers to placental penetration through the myometrium and into the uterine serosa (and sometimes adjacent organs), which is a disorder of invasion depth, not premature separation."}}}, {"id": "anking-reproductive-system-pathology-2263", "fuente": "anking", "tema": 8, "anki": "1463279770692", "q": "Placental abruption can compromise fetal oxygenation and blood supply, potentially leading to which severe fetal outcome?", "o": {"A": "Macrosomia", "B": "Stillbirth", "C": "Polyhydramnios", "D": "Post-term gestation"}, "r": "B", "e": {"correcta": "Placental abruption disrupts the maternal-fetal blood exchange at the site of separation, which can cause acute fetal hypoxia and distress; if severe or untreated, this can progress to fetal death in utero, i.e., stillbirth.", "incorrectas": {"A": "Macrosomia (excessive fetal growth) is associated with conditions like maternal diabetes, not with the acute vascular compromise caused by placental abruption.", "C": "Polyhydramnios (excess amniotic fluid) is linked to conditions such as fetal anomalies or maternal diabetes, not to the acute interruption of placental blood flow seen in abruption.", "D": "Post-term gestation refers to pregnancy extending beyond 42 weeks and is unrelated to the acute, potentially fatal fetal complication caused by placental abruption."}}}, {"id": "anking-reproductive-system-pathology-2264", "fuente": "anking", "tema": 8, "anki": "1463279790203", "q": "Which placenta accreta spectrum disorder is defined by abnormal attachment of the placenta directly to the myometrium without penetrating it?", "o": {"A": "Previa", "B": "Increta", "C": "Accreta", "D": "Percreta"}, "r": "C", "e": {"correcta": "Placenta accreta is the mildest and most common form of the placenta accreta spectrum, defined by abnormal attachment of the placenta directly to the myometrium (rather than the normal decidua basalis) without penetrating into or through the muscle; risk factors include prior C-section, inflammation, and placenta previa.", "incorrectas": {"A": "Placenta previa describes abnormal placental position over the cervical os, a distinct condition from the abnormal depth of placental attachment described in the accreta spectrum.", "B": "Placenta increta involves penetration of the placenta into the myometrium (a deeper level of invasion than accreta), rather than simple attachment without penetration.", "D": "Placenta percreta represents the most severe form, with placental penetration through the myometrium and into the uterine serosa (and potentially adjacent organs), well beyond the superficial attachment seen in accreta."}}}, {"id": "anking-reproductive-system-pathology-2265", "fuente": "anking", "tema": 8, "anki": "1463279800156", "q": "Which term describes abnormal penetration of the placenta into (but not through) the myometrium?", "o": {"A": "Accreta", "B": "Increta", "C": "Percreta", "D": "Previa"}, "r": "B", "e": {"correcta": "Placenta increta is defined by abnormal penetration of placental tissue into the myometrium, representing an intermediate severity within the placenta accreta spectrum, deeper than simple attachment (accreta) but not extending through the full uterine wall (percreta).", "incorrectas": {"A": "Placenta accreta involves attachment of the placenta to the myometrium without actually penetrating into it, making it a more superficial abnormality than increta.", "C": "Placenta percreta involves penetration through the entire myometrium and into the uterine serosa (and sometimes adjacent structures like bladder or rectum), a deeper and more severe process than increta.", "D": "Placenta previa refers to abnormal placental positioning over the cervical os, a completely separate concept from the depth of myometrial invasion described by the accreta spectrum terms."}}}, {"id": "anking-reproductive-system-pathology-2266", "fuente": "anking", "tema": 8, "anki": "1463279816657", "q": "Which placenta accreta spectrum disorder involves penetration of the placenta through the myometrium and into the uterine serosa, sometimes attaching to the bladder or rectum?", "o": {"A": "Accreta", "B": "Increta", "C": "Percreta", "D": "Abruption"}, "r": "C", "e": {"correcta": "Placenta percreta is the most severe form of the placenta accreta spectrum, in which placental tissue penetrates completely through the myometrium and into the uterine serosa, occasionally invading adjacent pelvic organs such as the bladder or rectum, and often requires extensive surgical management.", "incorrectas": {"A": "Placenta accreta describes superficial attachment to the myometrium without penetration, a much less invasive process than the full-thickness penetration seen in percreta.", "B": "Placenta increta describes penetration into the myometrium but not through the entire uterine wall or into the serosa/adjacent organs, making it less severe than percreta.", "D": "Placental abruption is the premature separation of a normally implanted placenta from the uterine wall, an entirely different process from the abnormal invasive attachment described in the accreta spectrum."}}}, {"id": "anking-reproductive-system-pathology-2267", "fuente": "anking", "tema": 8, "anki": "1463279826371", "q": "Placenta accreta spectrum disorders classically present after delivery with failure of placental separation and which additional finding?", "o": {"A": "Painless bleeding in the third trimester", "B": "Heavy post-partum bleeding", "C": "Elevated blood pressure with proteinuria", "D": "Recurrent early pregnancy loss"}, "r": "B", "e": {"correcta": "In placenta accreta (or increta/percreta), the placenta fails to separate normally after delivery, which leads to heavy post-partum bleeding as the uterus cannot contract properly around the retained, abnormally adherent placental tissue; this can progress to hypovolemic shock and, in severe cases, Sheehan syndrome (postpartum pituitary necrosis).", "incorrectas": {"A": "Painless bleeding in the third trimester is the classic presentation of placenta previa (due to abnormal placental position over the cervix), not the postpartum bleeding characteristic of the accreta spectrum.", "C": "Elevated blood pressure with proteinuria describes preeclampsia, a distinct hypertensive disorder of pregnancy unrelated to the abnormal placental attachment seen in the accreta spectrum.", "D": "Recurrent early pregnancy loss is more associated with chromosomal, anatomic, or autoimmune causes of miscarriage, not with the abnormal placental adherence problems of the accreta spectrum, which manifest at delivery."}}}, {"id": "anking-reproductive-system-pathology-2268", "fuente": "anking", "tema": 8, "anki": "1463279835082", "q": "Placenta accreta, due to abnormal attachment of the placenta to the uterus, often requires which definitive procedure after delivery?", "o": {"A": "Uterine curettage", "B": "Hysterectomy", "C": "Cervical cerclage", "D": "Tubal ligation"}, "r": "B", "e": {"correcta": "Because the placenta in accreta is abnormally attached to (or invading) the myometrium and cannot separate normally after delivery, hysterectomy is often required to control the resulting hemorrhage and remove the abnormally adherent placental tissue along with the uterus.", "incorrectas": {"A": "Uterine curettage is used to remove retained products of conception in cases like incomplete miscarriage, but it is generally insufficient and unsafe for the deeply adherent or invasive placental tissue of accreta, which often requires hysterectomy.", "C": "Cervical cerclage is a procedure used to reinforce a weak or incompetent cervix to prevent preterm birth, unrelated to managing abnormal placental attachment after delivery.", "D": "Tubal ligation is a permanent contraceptive procedure and has no role in managing the hemorrhagic complications of placenta accreta."}}}, {"id": "anking-reproductive-system-pathology-2269", "fuente": "anking", "tema": 8, "anki": "1463279839010", "q": "A pregnant woman at 24 weeks gestation has a blood pressure of 150/95 mmHg with no proteinuria, no pre-existing hypertension, and no end-organ damage. What is the most likely diagnosis?", "o": {"A": "Chronic hypertension", "B": "Preeclampsia", "C": "Gestational hypertension", "D": "Eclampsia"}, "r": "C", "e": {"correcta": "Gestational hypertension is defined as blood pressure greater than 140/90 mmHg arising after 20 weeks of gestation, in a patient without proteinuria, pre-existing hypertension, or evidence of end-organ damage; it is distinguished from preeclampsia by the absence of proteinuria or organ dysfunction.", "incorrectas": {"A": "Chronic hypertension refers to elevated blood pressure that predates pregnancy or is diagnosed before 20 weeks gestation, which does not match a new onset of hypertension after 20 weeks.", "B": "Preeclampsia requires hypertension after 20 weeks gestation plus proteinuria or evidence of end-organ damage, features that are explicitly absent in this patient, ruling it out.", "D": "Eclampsia refers to the occurrence of seizures in a patient with preeclampsia, which requires the preeclampsia criteria (proteinuria/end-organ damage) to be met first; this patient has neither seizures nor those criteria."}}}, {"id": "anking-reproductive-system-pathology-2270", "fuente": "anking", "tema": 8, "anki": "1463279871354", "q": "Preeclampsia typically presents in relation to which gestational milestone, such that presentation before this point should raise suspicion for molar pregnancy instead?", "o": {"A": "Before the 12th week", "B": "After the 20th week", "C": "Only in the third trimester after 36 weeks", "D": "Only during labor"}, "r": "B", "e": {"correcta": "Preeclampsia typically presents after the 20th week of gestation, reflecting the time needed for abnormal placentation to trigger the systemic endothelial dysfunction underlying the disease; presentation before 20 weeks is atypical and should raise suspicion for a molar pregnancy, which can cause early-onset preeclampsia-like features.", "incorrectas": {"A": "Presentation before the 12th week would be markedly atypical for preeclampsia and instead should prompt evaluation for gestational trophoblastic disease (molar pregnancy).", "C": "While preeclampsia often becomes clinically apparent later in pregnancy, it is defined as occurring any time after 20 weeks, not restricted only to the third trimester after 36 weeks.", "D": "Preeclampsia is not restricted to onset during labor; it can develop and be diagnosed at any point from 20 weeks gestation through the postpartum period."}}}, {"id": "anking-reproductive-system-pathology-2271", "fuente": "anking", "tema": 8, "anki": "1463279881373", "q": "Preeclampsia is caused by abnormal development of which placental structures, leading to endothelial dysfunction, vasoconstriction, and ischemia?", "o": {"A": "Spiral arteries", "B": "Umbilical veins", "C": "Chorionic villi capillaries", "D": "Uterine venous sinuses"}, "r": "A", "e": {"correcta": "Preeclampsia results from abnormal remodeling of the placental spiral arteries, which fail to properly dilate during placentation; this leads to release of inflammatory and anti-angiogenic factors, causing systemic endothelial dysfunction, vasoconstriction, and placental ischemia.", "incorrectas": {"B": "Umbilical veins carry oxygenated blood from the placenta to the fetus and are not the site of the abnormal vascular remodeling implicated in preeclampsia pathogenesis.", "C": "Chorionic villi capillaries are involved in fetal-maternal gas and nutrient exchange, but the primary pathologic lesion in preeclampsia is the failure of spiral artery remodeling, not villous capillary abnormality itself.", "D": "Uterine venous sinuses are not the structures implicated in the vascular pathology of preeclampsia; the disease centers on inadequate trophoblastic invasion and remodeling of the maternal spiral arteries."}}}, {"id": "anking-reproductive-system-pathology-2272", "fuente": "anking", "tema": 8, "anki": "1463279885403", "q": "Increased incidence of preeclampsia is seen in patients with pre-existing diabetes, chronic renal disease, autoimmune disorders, and which other pre-existing condition?", "o": {"A": "Hypertension", "B": "Asthma", "C": "Hypothyroidism", "D": "Osteoporosis"}, "r": "A", "e": {"correcta": "Pre-existing (chronic) hypertension is a recognized risk factor that increases the incidence of preeclampsia, along with pre-existing diabetes, chronic renal disease, and autoimmune disorders, likely because these conditions predispose to endothelial and vascular dysfunction that compounds the abnormal placentation seen in preeclampsia.", "incorrectas": {"B": "Asthma is a chronic airway disease that is not established as a significant risk factor for developing preeclampsia, unlike vascular and metabolic conditions such as hypertension and diabetes.", "C": "Hypothyroidism, while it should be adequately treated in pregnancy, is not classically listed among the major risk factors that increase preeclampsia incidence to the same degree as pre-existing hypertension.", "D": "Osteoporosis is a skeletal condition unrelated to vascular or placental pathology and is not a recognized risk factor for preeclampsia."}}}, {"id": "anking-reproductive-system-pathology-2273", "fuente": "anking", "tema": 8, "anki": "1463279909190", "q": "HELLP syndrome can lead to severe hypotension due to rupture of which hepatic complication?", "o": {"A": "Subcapsular hematoma", "B": "Hepatic abscess", "C": "Portal vein thrombosis", "D": "Cholangitis"}, "r": "A", "e": {"correcta": "HELLP syndrome (hemolysis, elevated liver enzymes, low platelets) can cause hepatic subcapsular hematomas due to hepatocellular damage and microvascular thrombosis; rupture of these hematomas can cause massive intra-abdominal hemorrhage and severe hypotension, representing a life-threatening emergency.", "incorrectas": {"B": "Hepatic abscess is typically an infectious or suppurative process unrelated to the microangiopathic hepatic injury and hematoma formation characteristic of HELLP syndrome.", "C": "Portal vein thrombosis is a distinct vascular complication not classically associated with HELLP syndrome, which instead causes periportal hemorrhage and subcapsular hematoma formation.", "D": "Cholangitis is an infection/inflammation of the biliary tree, unrelated to the hepatocellular and vascular pathology (hemolysis, elevated enzymes, hematoma) seen in HELLP syndrome."}}}, {"id": "anking-reproductive-system-pathology-2274", "fuente": "anking", "tema": 8, "anki": "1463279912679", "q": "What is the definitive management for both eclampsia and HELLP syndrome?", "o": {"A": "IV magnesium sulfate alone, continuing pregnancy to term", "B": "Immediate delivery of the baby", "C": "Bed rest and outpatient monitoring", "D": "High-dose corticosteroids to allow further fetal maturation before any intervention"}, "r": "B", "e": {"correcta": "Both eclampsia and HELLP syndrome are obstetric emergencies that warrant immediate delivery of the baby, as delivery removes the placental trigger driving the underlying pathophysiology and is the only definitive treatment to halt disease progression and protect maternal and fetal health.", "incorrectas": {"A": "Magnesium sulfate is used for seizure prophylaxis/treatment in eclampsia, but it is adjunctive, not definitive; continuing the pregnancy without delivery does not address the underlying disease process.", "C": "Bed rest and outpatient monitoring are inadequate for these life-threatening conditions, which require inpatient management and expedited delivery rather than conservative outpatient observation.", "D": "While corticosteroids may be given for fetal lung maturity if time allows, definitive management still centers on prompt delivery; these conditions are too dangerous to delay delivery solely to allow further fetal maturation."}}}, {"id": "anking-reproductive-system-physiology-2275", "fuente": "anking", "tema": 32, "anki": "1463279918927", "q": "The unexplained death of an apparently healthy infant between 1 month and 1 year of age, usually occurring during sleep, is known as what?", "o": {"A": "Apparent life-threatening event", "B": "Sudden Infant Death Syndrome", "C": "Neonatal sepsis", "D": "Congenital central hypoventilation syndrome"}, "r": "B", "e": {"correcta": "Sudden Infant Death Syndrome (SIDS) is defined as the sudden, unexplained death of an apparently healthy infant between 1 month and 1 year of age, typically occurring during sleep, with no identifiable cause found even after autopsy and death scene investigation.", "incorrectas": {"A": "An apparent life-threatening event (ALTE) describes an episode in which an infant experiences frightening symptoms (apnea, color change, choking) but survives, which is a distinct clinical entity from the fatal outcome that defines SIDS.", "C": "Neonatal sepsis is a specific, identifiable infectious cause of infant death, which by definition would exclude a diagnosis of SIDS, since SIDS requires that no cause be found.", "D": "Congenital central hypoventilation syndrome is a specific genetic disorder of respiratory drive that can be identified diagnostically, unlike SIDS, which is a diagnosis of exclusion with no identifiable cause."}}}, {"id": "anking-reproductive-system-physiology-2276", "fuente": "anking", "tema": 32, "anki": "1463279926558", "q": "Which sleeping position is a recognized risk factor for Sudden Infant Death Syndrome, along with exposure to cigarette smoke and prematurity?", "o": {"A": "Supine (on the back)", "B": "Prone (on the stomach)", "C": "Side-lying with a wedge", "D": "Semi-upright in a car seat"}, "r": "B", "e": {"correcta": "Sleeping in the prone position (on the stomach) is a well-established risk factor for SIDS, along with exposure to cigarette smoke and prematurity; this is why public health campaigns advocate placing infants supine (\"Back to Sleep\") to reduce SIDS risk.", "incorrectas": {"A": "The supine position (on the back) is actually the recommended, protective sleeping position that reduces SIDS risk, in direct contrast to the prone position, which increases risk.", "C": "Side-lying with a wedge is not the classic risk factor cited in SIDS risk-factor teaching; it is prone positioning, not side-lying, that is specifically associated with increased risk.", "D": "Semi-upright positioning in a car seat is not the sleep position implicated as a risk factor for SIDS in standard teaching, which focuses on prone sleeping in a crib/bed setting."}}}, {"id": "anking-reproductive-system-pathology-2277", "fuente": "anking", "tema": 8, "anki": "1463279938999", "q": "A pregnant woman in her first trimester presents with a uterine size that is significantly larger than expected for her gestational age. Which diagnosis is most consistent with this finding?", "o": {"A": "Ectopic pregnancy", "B": "Hydatidiform mole", "C": "Placenta previa", "D": "Threatened abortion"}, "r": "B", "e": {"correcta": "Hydatidiform mole causes excessive proliferation of trophoblastic (villous) tissue, which along with markedly elevated hCG drives uterine enlargement disproportionate to gestational age. This finding, combined with first-trimester bleeding and pelvic pressure, should prompt beta-hCG testing and pelvic ultrasound.", "incorrectas": {"A": "Ectopic pregnancy classically presents with a normal or even smaller uterus (since the pregnancy is not developing intrauterinely), often with adnexal pain and a positive but lower-than-expected hCG rise, not uterine enlargement.", "C": "Placenta previa is a third-trimester diagnosis involving abnormal placental implantation over the cervical os causing painless bleeding; it does not present with early excessive uterine enlargement.", "D": "Threatened abortion presents with vaginal bleeding in early pregnancy but with a uterus appropriately sized for gestational age, not the size-date discrepancy seen with molar pregnancy."}}}, {"id": "anking-reproductive-system-pathology-2278", "fuente": "anking", "tema": 8, "anki": "1463279946159", "q": "In a molar pregnancy, serum beta-hCG levels compared to the expected level for gestational age are typically:", "o": {"A": "Undetectable", "B": "Lower than expected", "C": "Higher than expected", "D": "Unchanged from expected"}, "r": "C", "e": {"correcta": "Hydatidiform moles consist of massively hyperplastic trophoblastic tissue, which secretes excessive amounts of hCG, resulting in serum levels markedly higher than expected for gestational age. This exaggerated hCG can also cause hyperemesis gravidarum and theca-lutein cysts via ovarian overstimulation.", "incorrectas": {"A": "Undetectable hCG would suggest no viable trophoblastic tissue at all (e.g., non-pregnant state), which contradicts the marked trophoblastic proliferation characteristic of a mole.", "B": "Lower than expected hCG is more consistent with a failing pregnancy, such as a missed or threatened abortion, or an ectopic pregnancy, not the hyperproliferative trophoblast of a mole.", "D": "Unchanged hCG would not raise suspicion for any pathology and does not reflect the excessive trophoblastic hormone secretion that defines molar disease."}}}, {"id": "anking-reproductive-system-pathology-2279", "fuente": "anking", "tema": 8, "anki": "1463279956478", "q": "In a region without access to prenatal ultrasound, a woman presents in the second trimester with a classic clinical sign of hydatidiform mole. What is this presenting sign?", "o": {"A": "Passage of grape-like masses (large, edematous villi) through the vaginal canal", "B": "Sudden onset of severe unilateral pelvic pain", "C": "Painless bright red vaginal bleeding in the third trimester", "D": "Rupture of membranes with clear fluid leakage"}, "r": "A", "e": {"correcta": "Without early ultrasound screening, a molar pregnancy may go undetected until the hydropic, grape-like villi are spontaneously passed through the vagina, a dramatic and classic presentation reflecting the massively edematous chorionic villi that give the uterus a 'honeycombed' appearance on imaging.", "incorrectas": {"B": "Sudden severe unilateral pelvic pain is more suggestive of ovarian torsion or ectopic pregnancy rupture, not the passage of molar tissue.", "C": "Painless bright red bleeding in the third trimester is the classic presentation of placenta previa, a distinct entity from a first/second-trimester molar pregnancy.", "D": "Clear fluid leakage suggests rupture of membranes in a viable pregnancy, which is inconsistent with a hydatidiform mole, which lacks a normal amniotic sac in complete moles."}}}, {"id": "anking-reproductive-system-pathology-2280", "fuente": "anking", "tema": 8, "anki": "1463279967084", "q": "In areas with adequate prenatal care, a hydatidiform mole is typically first identified early in the first trimester by which routine study?", "o": {"A": "Serum alpha-fetoprotein screening", "B": "Routine ultrasound", "C": "Karyotype analysis of amniotic fluid", "D": "Doppler flow study of the uterine artery"}, "r": "B", "e": {"correcta": "Routine first-trimester ultrasound is the standard screening tool that reveals the characteristic 'snow-storm' appearance of numerous hydropic villi and absence of a normal fetus, allowing early diagnosis of molar pregnancy before clinical complications like grape-like tissue passage occur.", "incorrectas": {"A": "Alpha-fetoprotein screening is typically performed later (second trimester) to screen for neural tube defects and aneuploidy, not as the primary early modality for detecting molar pregnancy.", "C": "Karyotype analysis of amniotic fluid via amniocentesis is an invasive, targeted test used for specific genetic concerns, not a routine early screening tool for molar pregnancy.", "D": "Doppler studies of uterine artery flow are used later in pregnancy to assess for conditions like preeclampsia-related placental insufficiency, not for early molar pregnancy detection."}}}, {"id": "anking-reproductive-system-pathology-2281", "fuente": "anking", "tema": 8, "anki": "1463279978747", "q": "Which finding on physical examination should raise suspicion for a hydatidiform mole in a pregnant patient?", "o": {"A": "Presence of fetal heart sounds", "B": "Absence of fetal heart sounds", "C": "Normal fundal height for gestational age", "D": "Regular uterine contractions"}, "r": "B", "e": {"correcta": "Because a complete hydatidiform mole contains no fetal tissue (and even a partial mole often has a non-viable fetus), the absence of expected fetal heart sounds on Doppler or auscultation at a gestational age when they should be detectable is a key clinical clue prompting further workup with hCG and ultrasound.", "incorrectas": {"A": "Presence of fetal heart sounds would argue against a complete mole (which lacks fetal tissue entirely) and is more consistent with a normal or partial molar pregnancy where some fetal tissue may transiently exist.", "C": "Normal fundal height would be reassuring and inconsistent with a mole, which classically causes a uterus larger than dates due to excessive trophoblastic proliferation.", "D": "Regular uterine contractions suggest labor or preterm labor, an unrelated process to the trophoblastic overgrowth seen in molar pregnancy."}}}, {"id": "anking-reproductive-system-pathology-2282", "fuente": "anking", "tema": 8, "anki": "1463279979722", "q": "On ultrasound, a hydatidiform mole classically produces which characteristic appearance?", "o": {"A": "\"Target sign\"", "B": "\"Snow-storm\" appearance", "C": "\"String sign\"", "D": "\"Onion skin\" appearance"}, "r": "B", "e": {"correcta": "The numerous hydropic (edematous) villi filling the uterine cavity in a hydatidiform mole create diffuse echogenic clusters resembling a snow-storm on ultrasound, corresponding pathologically to the grossly grape-like clusters of swollen villi.", "incorrectas": {"A": "The \"target sign\" refers to concentric rings seen in intussusception on ultrasound/CT, an unrelated gastrointestinal finding.", "C": "The \"string sign\" describes a narrowed contrast-filled lumen classically seen in Crohn disease strictures on barium studies, not obstetric ultrasound.", "D": "\"Onion skin\" describes the periosteal reaction seen in Ewing sarcoma on x-ray, an unrelated musculoskeletal imaging finding."}}}, {"id": "anking-reproductive-system-pathology-2283", "fuente": "anking", "tema": 8, "anki": "1463280027026", "q": "Which type of hydatidiform mole is characterized by the presence of fetal tissue?", "o": {"A": "Complete mole", "B": "Partial mole", "C": "Invasive mole", "D": "Choriocarcinoma"}, "r": "B", "e": {"correcta": "A partial mole arises when a normal ovum is fertilized by two sperm (triploidy, 69,XXY or similar), so maternal chromosomes are still present, allowing some fetal tissue and an amniotic sac to develop alongside the hydropic villi, distinguishing it from a complete mole.", "incorrectas": {"A": "A complete mole results from fertilization of an empty (enucleated) ovum, so there is no maternal genetic contribution and thus no fetal tissue forms at all.", "C": "Invasive mole refers to a mole (usually complete) that penetrates into the myometrium; it describes the depth of trophoblastic invasion, not the presence of fetal tissue.", "D": "Choriocarcinoma is a malignant trophoblastic tumor that can arise after a mole, but it is composed purely of malignant cytotrophoblast and syncytiotrophoblast without villi or fetal tissue."}}}, {"id": "anking-reproductive-system-pathology-2284", "fuente": "anking", "tema": 8, "anki": "1463280032221", "q": "A hydatidiform mole that contains no fetal tissue and arises from an enucleated egg fertilized by one or two sperm is classified as which type?", "o": {"A": "Partial mole", "B": "Complete mole", "C": "Invasive mole", "D": "Placental site trophoblastic tumor"}, "r": "B", "e": {"correcta": "A complete hydatidiform mole forms when an empty ovum (with no maternal nuclear DNA) is fertilized, typically by a single sperm that duplicates its genome (46,XX, all paternal), leaving no fetal tissue since there is no maternal genetic contribution to support embryogenesis.", "incorrectas": {"A": "A partial mole arises from a normal ovum fertilized by two sperm (triploid karyotype), and because maternal DNA is present, some fetal tissue can develop.", "C": "Invasive mole describes myometrial invasion by molar tissue (usually a complete mole that has become locally invasive), not a distinct genetic classification based on fetal tissue presence.", "D": "Placental site trophoblastic tumor is a rare, distinct neoplasm of intermediate trophoblast that secretes human placental lactogen, unrelated to the complete/partial mole classification."}}}, {"id": "anking-reproductive-system-pathology-2285", "fuente": "anking", "tema": 8, "anki": "1463280035157", "q": "Which type of hydatidiform mole is more commonly associated with a markedly increased uterine size, occasionally leading to early uterine rupture?", "o": {"A": "Partial mole", "B": "Complete mole", "C": "Choriocarcinoma in situ", "D": "Placental site trophoblastic tumor"}, "r": "B", "e": {"correcta": "Complete moles show circumferential, diffuse trophoblastic hyperplasia involving essentially all villi, producing a much greater bulk of tissue and higher hCG levels than partial moles, which explains the more pronounced uterine enlargement and rare risk of early uterine rupture.", "incorrectas": {"A": "Partial moles have only focal trophoblastic proliferation involving a subset of villi (the rest being normal), so uterine enlargement is typically less pronounced than with complete moles.", "C": "Choriocarcinoma in situ is not a standard clinical entity used to describe uterine size discrepancy; choriocarcinoma is an invasive malignancy, not defined by uterine enlargement patterns.", "D": "Placental site trophoblastic tumor is a rare tumor of intermediate trophoblasts and is not characterized by the marked uterine enlargement typical of complete moles."}}}, {"id": "anking-reproductive-system-pathology-2286", "fuente": "anking", "tema": 8, "anki": "1463280044881", "q": "Which type of hydatidiform mole carries a higher (though still low, roughly 2%) risk of progressing to choriocarcinoma?", "o": {"A": "Partial mole", "B": "Complete mole", "C": "Ectopic mole", "D": "Twin mole with coexisting fetus"}, "r": "B", "e": {"correcta": "Because complete moles are entirely paternally derived and show diffuse, more aggressive trophoblastic proliferation, they carry a higher risk (about 2%) of malignant transformation to choriocarcinoma, as well as a 15-20% risk of becoming a locally invasive mole, compared to partial moles.", "incorrectas": {"A": "Partial moles, which retain maternal genetic material and show only focal trophoblastic proliferation, have a much lower risk of progressing to choriocarcinoma or invasive mole (under 5%).", "C": "\"Ectopic mole\" is not a recognized classification of hydatidiform mole; ectopic pregnancy and molar pregnancy are distinct entities.", "D": "A twin pregnancy with a coexisting complete mole and normal fetus is a rare scenario, but risk stratification for choriocarcinoma is based on complete versus partial mole pathology, not on twinning status."}}}, {"id": "anking-reproductive-system-pathology-2287", "fuente": "anking", "tema": 8, "anki": "1463280058681", "q": "Which type of hydatidiform mole carries only a very small increased risk of progression to choriocarcinoma (and rarely becomes an invasive mole, under 5%)?", "o": {"A": "Complete mole", "B": "Partial mole", "C": "Invasive mole", "D": "Metastatic gestational trophoblastic neoplasia"}, "r": "B", "e": {"correcta": "Partial moles retain some maternal genetic contribution and show only focal (not diffuse) trophoblastic hyperplasia, so their malignant potential is much lower than complete moles, with invasive mole occurring in less than 5% of cases and choriocarcinoma being rare.", "incorrectas": {"A": "Complete moles, being entirely paternal in origin with diffuse trophoblastic proliferation, carry the higher risk (about 2% for choriocarcinoma, 15-20% for invasive mole) compared to partial moles.", "C": "Invasive mole is itself a form of malignant potential outcome (local myometrial invasion), not the classification being contrasted here between mole subtypes for baseline risk.", "D": "Metastatic gestational trophoblastic neoplasia refers to disseminated disease, an advanced complication far beyond the low baseline risk associated specifically with partial moles."}}}, {"id": "anking-reproductive-system-pathology-2288", "fuente": "anking", "tema": 8, "anki": "1463280070337", "q": "Histologically, a mole in which only some villi are hydropic and there is only partial (focal) trophoblastic proliferation around the villi is classified as which type?", "o": {"A": "Complete mole", "B": "Partial mole", "C": "Invasive mole", "D": "Placental site nodule"}, "r": "B", "e": {"correcta": "A partial mole shows a mixture of normal and hydropic villi with only focal trophoblastic hyperplasia, reflecting the triploid karyotype in which normal maternal chromosomes coexist with the excess paternal genetic material, limiting the extent of trophoblastic overgrowth compared to a complete mole.", "incorrectas": {"A": "A complete mole shows nearly all villi hydropic with circumferential (diffuse) trophoblastic proliferation, since there is no maternal genetic material to produce normal villi.", "C": "Invasive mole describes molar tissue that has penetrated the myometrium, a description of depth of invasion rather than the villous/trophoblastic pattern distinguishing partial from complete moles.", "D": "Placental site nodule is a distinct, usually incidental finding of degenerated intermediate trophoblast, unrelated to the hydropic villous change described here."}}}, {"id": "anking-reproductive-system-pathology-2289", "fuente": "anking", "tema": 8, "anki": "1463280075288", "q": "Histologically, a mole in which most villi are hydropic and there is circumferential trophoblastic proliferation around the villi is classified as which type?", "o": {"A": "Partial mole", "B": "Complete mole", "C": "Choriocarcinoma", "D": "Placental site trophoblastic tumor"}, "r": "B", "e": {"correcta": "A complete mole arises from an enucleated ovum, so essentially all villi lack a fetal capillary network and become uniformly hydropic, with trophoblast proliferating circumferentially around the entire villus rather than just focally, reflecting the absence of any normal maternal-derived tissue to limit the process.", "incorrectas": {"A": "A partial mole shows a mixture of normal and hydropic villi with only focal (not circumferential) trophoblastic proliferation, since maternal chromosomes are still present alongside the extra paternal set.", "C": "Choriocarcinoma is a malignant proliferation of trophoblast without villi at all, distinct from the villous, hydropic architecture that defines a mole.", "D": "Placental site trophoblastic tumor is composed of intermediate trophoblast infiltrating the myometrium without the characteristic hydropic villi of a mole."}}}, {"id": "anking-reproductive-system-pathology-2290", "fuente": "anking", "tema": 8, "anki": "1463280078411", "q": "What is the standard initial treatment for a hydatidiform mole?", "o": {"A": "Dilatation and curettage", "B": "Emergency hysterectomy", "C": "Expectant management until spontaneous delivery", "D": "High-dose combination chemotherapy"}, "r": "A", "e": {"correcta": "Dilatation and curettage (D&C) is the standard treatment to evacuate the molar tissue from the uterus. Serial hCG monitoring afterward is essential to confirm resolution, since persistently elevated hCG suggests residual or invasive disease, which is treated with methotrexate.", "incorrectas": {"B": "Hysterectomy is reserved for select cases (e.g., older patients who have completed childbearing or with invasive disease), not as first-line management for an uncomplicated mole, since D&C preserves fertility.", "C": "Expectant management is inappropriate because the mole poses risks including hemorrhage, hypertension, and malignant transformation; timely evacuation is indicated once diagnosed.", "D": "Chemotherapy (e.g., methotrexate) is reserved for cases where hCG levels remain elevated after D&C, indicating persistent or invasive gestational trophoblastic disease, not as initial treatment for an uncomplicated mole."}}}, {"id": "anking-reproductive-system-pathology-2291", "fuente": "anking", "tema": 8, "anki": "1463280093289", "q": "A pregnant patient develops hypertension before 20 weeks of gestation. Which underlying diagnosis should be strongly suspected?", "o": {"A": "Chronic essential hypertension", "B": "Hydatidiform mole", "C": "Preeclampsia", "D": "Gestational diabetes"}, "r": "B", "e": {"correcta": "Preeclampsia is defined as occurring after 20 weeks of gestation, so hypertension appearing earlier in pregnancy should raise suspicion for a hydatidiform mole, which can cause early-onset hypertension due to the markedly elevated hCG and trophoblastic mass effect.", "incorrectas": {"C": "Preeclampsia by definition occurs at or after 20 weeks gestation; hypertension before this threshold is, by definition, not classic preeclampsia and should prompt evaluation for molar pregnancy instead.", "A": "Chronic essential hypertension would be present before pregnancy or diagnosed before 20 weeks as a baseline condition, but the classic teaching point in this context is the association of early hypertension with molar pregnancy, not primary chronic hypertension.", "D": "Gestational diabetes is a disorder of glucose metabolism diagnosed via glucose tolerance testing, unrelated to blood pressure elevation or trophoblastic disease."}}}, {"id": "anking-reproductive-system-pathology-2292", "fuente": "anking", "tema": 8, "anki": "1463280096234", "q": "Which type of ovarian cyst is classically associated with a hydatidiform mole due to markedly elevated hCG levels?", "o": {"A": "Follicular cyst", "B": "Theca-lutein cyst", "C": "Corpus luteum cyst", "D": "Endometrioma"}, "r": "B", "e": {"correcta": "Theca-lutein cysts form when excessive hCG (as seen with a hydatidiform mole) overstimulates the ovarian theca cells, causing bilateral, often large cystic enlargement; they typically regress after the mole is evacuated and hCG normalizes.", "incorrectas": {"A": "Follicular cysts are common, usually small, and result from failure of a dominant follicle to rupture or involute; they are not specifically driven by pathologically high hCG.", "C": "Corpus luteum cysts form from a corpus luteum that fails to regress and can persist in early normal pregnancy, but they are not the classic hCG-driven cyst associated with molar disease.", "D": "Endometrioma is a cystic collection of ectopic endometrial tissue within the ovary (a \"chocolate cyst\"), associated with endometriosis, not with hCG-driven trophoblastic disease."}}}, {"id": "anking-reproductive-system-pathology-2293", "fuente": "anking", "tema": 8, "anki": "1463280612433", "q": "If hCG levels remain elevated after dilatation and curettage of a hydatidiform mole, which chemotherapeutic agent is used to treat the residual/invasive trophoblastic disease?", "o": {"A": "Cisplatin", "B": "Methotrexate", "C": "Bleomycin", "D": "Vincristine"}, "r": "B", "e": {"correcta": "Methotrexate, a folate antagonist that inhibits dihydrofolate reductase and blocks DNA synthesis, is highly effective against the rapidly dividing trophoblastic cells of persistent or invasive molar disease and choriocarcinoma, making it the standard chemotherapeutic choice when hCG fails to normalize after D&C.", "incorrectas": {"A": "Cisplatin is a platinum-based DNA cross-linking agent used in germ cell tumors (e.g., testicular cancer) and other solid tumors, but it is not the first-line agent for persistent gestational trophoblastic disease.", "C": "Bleomycin causes DNA strand breaks via free radical formation and is part of combination regimens for germ cell tumors (e.g., BEP), but is not the standard single agent for post-molar hCG elevation.", "D": "Vincristine is a vinca alkaloid that inhibits microtubule formation, used in various hematologic and pediatric malignancies, but is not the standard treatment for persistent trophoblastic disease after a mole."}}}, {"id": "anking-reproductive-system-pathology-2294", "fuente": "anking", "tema": 8, "anki": "1463330337199", "q": "Hypospadias, in which the urethral opening is located on the ventral surface of the penis, results from failure of fusion of which embryologic structure?", "o": {"A": "Genital tubercle", "B": "Urethral folds", "C": "Labioscrotal swellings", "D": "Paramesonephric ducts"}, "r": "B", "e": {"correcta": "The urethral folds normally fuse ventrally under the influence of dihydrotestosterone to form the penile urethra; failure of this fusion results in hypospadias, with the urethral meatus opening on the ventral surface anywhere along the penile shaft. Because it reflects a defect in androgen-dependent closure, hypospadias is often associated with other genital anomalies and warrants evaluation for undescended testes.", "incorrectas": {"A": "Abnormal positioning of the genital tubercle is implicated in epispadias (dorsal urethral opening), not in hypospadias, which results from a fusion defect rather than a positional defect.", "C": "The labioscrotal swellings give rise to the scrotum (in males) or labia majora (in females); a defect here would not produce ventral urethral displacement.", "D": "The paramesonephric (Müllerian) ducts give rise to female internal reproductive structures and normally regress in males under the influence of anti-Müllerian hormone; they play no role in urethral fold fusion."}}}, {"id": "anking-reproductive-system-pathology-2295", "fuente": "anking", "tema": 8, "anki": "1463331296522", "q": "Epispadias, in which the urethral opening is on the dorsal surface of the penis, results from abnormal positioning of which embryologic structure during the 5th week of gestation?", "o": {"A": "Urethral folds", "B": "Genital tubercle", "C": "Urogenital sinus", "D": "Mesonephric duct"}, "r": "B", "e": {"correcta": "Epispadias results from abnormal dorsal positioning of the genital tubercle during development, so the urethral folds close in an abnormal (dorsal) location; it is also strongly associated with bladder exstrophy due to the shared underlying defect in cloacal membrane and anterior abdominal wall development.", "incorrectas": {"A": "Failure of the urethral folds to close properly on the ventral surface causes hypospadias, not epispadias, which instead reflects a positional error of the genital tubercle itself.", "C": "The urogenital sinus gives rise to the bladder and parts of the urethra and vagina, but its abnormal development is not the specific embryologic mechanism cited for epispadias.", "D": "The mesonephric (Wolffian) duct gives rise to male internal genital structures like the epididymis, vas deferens, and seminal vesicles under testosterone; it is unrelated to external genital tubercle positioning."}}}, {"id": "anking-reproductive-system-pathology-2296", "fuente": "anking", "tema": 8, "anki": "1463331300043", "q": "Which sexually transmitted infection is characterized by necrotizing granulomatous inflammation of the inguinal lymphatics and lymph nodes?", "o": {"A": "Primary syphilis", "B": "Lymphogranuloma venereum", "C": "Granuloma inguinale", "D": "Chancroid"}, "r": "B", "e": {"correcta": "Lymphogranuloma venereum (LGV) classically produces necrotizing granulomatous lymphadenitis of the inguinal and perirectal lymph nodes, presenting with tender, matted, suppurative nodes (the \"groove sign\") following a transient, often unnoticed genital ulcer.", "incorrectas": {"A": "Primary syphilis presents with a painless genital chancre and nontender regional lymphadenopathy, not the necrotizing granulomatous suppurative lymphadenitis characteristic of LGV.", "C": "Granuloma inguinale (caused by Klebsiella granulomatis) causes painless, beefy-red ulcers with rolled edges and minimal lymphadenopathy, distinct from the prominent necrotizing lymph node involvement of LGV.", "D": "Chancroid (caused by Haemophilus ducreyi) causes painful genital ulcers with painful suppurative inguinal lymphadenopathy, but it is not characterized by the same necrotizing granulomatous histology as LGV."}}}, {"id": "anking-clinical-bacteriology-2297", "fuente": "anking", "tema": 21, "anki": "1463331303015", "q": "Lymphogranuloma venereum is caused by which serotypes of Chlamydia trachomatis?", "o": {"A": "Serotypes A-C", "B": "Serotypes D-K", "C": "Serotypes L1-L3", "D": "Serotype trachomatis biovar"}, "r": "C", "e": {"correcta": "Chlamydia trachomatis serotypes L1, L2, and L3 are invasive strains that cause lymphogranuloma venereum, infecting lymphatic tissue and producing painful, necrotizing granulomatous lymphadenitis, distinguishing them from the serotypes causing ocular and genital tract infections.", "incorrectas": {"A": "Serotypes A-C of Chlamydia trachomatis cause trachoma, a chronic conjunctivitis that is a leading cause of preventable blindness, not lymphogranuloma venereum.", "B": "Serotypes D-K cause the more common genital tract infections (urethritis, cervicitis, neonatal conjunctivitis, and pneumonia), which typically do not produce the severe lymphadenitis of LGV.", "D": "There is no distinct \"trachomatis biovar\" serotype grouping used in this classification; C. trachomatis serotypes are grouped as A-C (trachoma), D-K (genital), and L1-L3 (LGV)."}}}, {"id": "anking-reproductive-system-pathology-2298", "fuente": "anking", "tema": 8, "anki": "1463331306960", "q": "Perianal involvement of lymphogranuloma venereum can heal with fibrosis, leading to which long-term complication?", "o": {"A": "Rectal strictures", "B": "Rectovaginal fistula formation only", "C": "Anal squamous cell carcinoma", "D": "Perianal abscess recurrence"}, "r": "A", "e": {"correcta": "Chronic inflammation from LGV in the perianal/perirectal region ultimately resolves with fibrotic scarring, which can narrow the rectal lumen and produce rectal strictures, a recognized late complication requiring surgical management in some cases.", "incorrectas": {"B": "While fistulas can occur with severe chronic anorectal inflammation, the classic and most emphasized fibrotic complication of LGV is stricture formation, not fistula as the primary teaching point.", "C": "Anal squamous cell carcinoma is associated with HPV infection, not with the fibrotic healing process of LGV-related lymphadenitis and proctitis.", "D": "Recurrent perianal abscesses reflect ongoing acute suppurative infection, whereas the question describes the chronic fibrotic sequela after healing, which is stricture formation."}}}, {"id": "anking-reproductive-system-pathology-2299", "fuente": "anking", "tema": 8, "anki": "1463331309665", "q": "Which condition is defined as a malignant proliferation of squamous cells of the penile skin?", "o": {"A": "Bowenoid papulosis", "B": "Penile squamous cell carcinoma", "C": "Erythroplasia of Queyrat", "D": "Condyloma acuminatum"}, "r": "B", "e": {"correcta": "Penile squamous cell carcinoma is the invasive malignant proliferation of squamous epithelial cells of the penile skin, most commonly arising on the glans or foreskin, and is strongly linked to high-risk HPV infection and lack of circumcision.", "incorrectas": {"A": "Bowenoid papulosis is a precursor (in situ) lesion, typically seen in younger men, that does not progress to invasive carcinoma, distinguishing it from actual invasive SCC.", "C": "Erythroplasia of Queyrat is carcinoma in situ presenting as a red, velvety plaque on the glans; it is a precursor/in situ lesion that can progress to invasive SCC but is not itself the invasive malignancy.", "D": "Condyloma acuminatum refers to benign genital warts caused by low-risk HPV types (6 and 11), which are not malignant and do not represent squamous cell carcinoma."}}}, {"id": "anking-reproductive-system-pathology-2300", "fuente": "anking", "tema": 8, "anki": "1463331312916", "q": "Approximately two-thirds of penile squamous cell carcinoma cases are associated with which infectious agent?", "o": {"A": "Herpes simplex virus", "B": "High-risk HPV", "C": "Treponema pallidum", "D": "Molluscum contagiosum virus"}, "r": "B", "e": {"correcta": "High-risk HPV types (especially 16 and 18) are found in roughly two-thirds of penile squamous cell carcinoma cases, where viral oncoproteins E6 and E7 inactivate p53 and Rb tumor suppressors, promoting malignant transformation of penile epithelium, similar to their role in cervical cancer.", "incorrectas": {"A": "Herpes simplex virus causes painful genital ulcers/vesicles but is not the major oncogenic driver implicated in penile squamous cell carcinoma.", "C": "Treponema pallidum causes syphilis, presenting with a painless chancre in the primary stage, but it is not linked to malignant transformation of penile epithelium.", "D": "Molluscum contagiosum virus causes benign, umbilicated papules and is not associated with oncogenesis or penile squamous cell carcinoma."}}}, {"id": "anking-reproductive-system-pathology-2301", "fuente": "anking", "tema": 8, "anki": "1463331315899", "q": "Penile squamous cell carcinoma is associated with lack of which procedure, since retained tissue can act as a nidus for chronic irritation and carcinogen exposure?", "o": {"A": "Vasectomy", "B": "Circumcision", "C": "Orchiopexy", "D": "Prostatectomy"}, "r": "B", "e": {"correcta": "Lack of circumcision allows the foreskin to trap smegma, moisture, and carcinogens, creating chronic irritation and infection risk (including HPV) that predisposes to penile squamous cell carcinoma; circumcision is protective by removing this nidus.", "incorrectas": {"A": "Vasectomy is a method of male sterilization that interrupts the vas deferens and has no established relationship to penile skin carcinogenesis.", "C": "Orchiopexy is the surgical correction of an undescended testis (cryptorchidism), an unrelated procedure concerning the testes rather than penile skin.", "D": "Prostatectomy is surgical removal of the prostate, relevant to prostate cancer or BPH management, not to penile squamous cell carcinoma risk."}}}, {"id": "anking-reproductive-system-pathology-2302", "fuente": "anking", "tema": 8, "anki": "1463331331641", "q": "Which precursor lesion to penile squamous cell carcinoma is more commonly seen in younger patients (in their 40s)?", "o": {"A": "Erythroplasia of Queyrat", "B": "Bowenoid papulosis", "C": "Lichen sclerosus", "D": "Balanitis xerotica obliterans"}, "r": "B", "e": {"correcta": "Bowenoid papulosis is an HPV-related carcinoma in situ lesion that typically affects younger men (around their 40s), presenting as reddish-brown papules on the penile shaft, in contrast to erythroplasia of Queyrat and Bowen disease, which tend to occur in older patients.", "incorrectas": {"A": "Erythroplasia of Queyrat is also a carcinoma in situ lesion (on the glans), but it classically presents in older, uncircumcised men rather than the younger population associated with Bowenoid papulosis.", "C": "Lichen sclerosus is a chronic inflammatory skin condition that can predispose to SCC but is not itself defined as the classic younger-patient precursor lesion being described.", "D": "Balanitis xerotica obliterans is the penile manifestation of lichen sclerosus, causing scarring and phimosis, and is not the specific younger-age precursor lesion referenced here."}}}, {"id": "anking-reproductive-system-pathology-2303", "fuente": "anking", "tema": 8, "anki": "1463331334214", "q": "Which precursor lesion to penile squamous cell carcinoma does NOT progress to invasive carcinoma?", "o": {"A": "Erythroplasia of Queyrat", "B": "Bowen disease", "C": "Bowenoid papulosis", "D": "Carcinoma in situ of the glans"}, "r": "C", "e": {"correcta": "Bowenoid papulosis, unlike other penile carcinoma in situ variants, generally has a benign clinical course and does not progress to invasive squamous cell carcinoma, which is an important distinguishing feature despite its similar HPV-related histology.", "incorrectas": {"A": "Erythroplasia of Queyrat is a form of carcinoma in situ that can progress to invasive squamous cell carcinoma if untreated, unlike Bowenoid papulosis.", "B": "Bowen disease (carcinoma in situ of the penile shaft) also carries risk of progression to invasive carcinoma, distinguishing it from the more indolent course of Bowenoid papulosis.", "D": "Carcinoma in situ of the glans (erythroplasia of Queyrat) similarly has malignant potential and can progress to invasive disease, unlike Bowenoid papulosis."}}}, {"id": "anking-reproductive-system-pathology-2304", "fuente": "anking", "tema": 8, "anki": "1463331336497", "q": "Increased prevalence of penile squamous cell carcinoma is particularly associated with which three continents?", "o": {"A": "Europe, North America, Australia", "B": "Asia, Africa, South America", "C": "North America, Europe, Asia", "D": "Australia, Europe, South America"}, "r": "B", "e": {"correcta": "Penile squamous cell carcinoma shows increased prevalence in parts of Asia, Africa, and South America, likely reflecting lower rates of circumcision, differing HPV exposure patterns, and reduced access to genital hygiene and healthcare resources in some of these regions.", "incorrectas": {"A": "Europe, North America, and Australia have comparatively lower rates of penile SCC, partly due to higher circumcision rates and different HPV vaccination/screening infrastructure.", "C": "North America and Europe are lower-incidence regions for this cancer; only Asia among this option's continents carries elevated risk, making the group as a whole incorrect.", "D": "Australia and Europe are lower-incidence regions; grouping them with South America does not match the classic three continents (Asia, Africa, South America) associated with increased prevalence."}}}, {"id": "anking-reproductive-system-pathology-2305", "fuente": "anking", "tema": 8, "anki": "1463331360156", "q": "Peyronie disease, characterized by abnormal penile curvature due to fibrous plaque formation in the tunica albuginea, is associated with which functional complication?", "o": {"A": "Erectile dysfunction", "B": "Urinary retention", "C": "Infertility due to azoospermia", "D": "Priapism"}, "r": "A", "e": {"correcta": "The fibrous scar tissue in Peyronie disease distorts the normal architecture of the tunica albuginea, causing painful curvature during erection and mechanical/psychological difficulty achieving or maintaining an erection, resulting in erectile dysfunction.", "incorrectas": {"B": "Urinary retention is typically related to bladder outlet obstruction (e.g., BPH) or neurologic causes, not to the localized fibrous plaque of the tunica albuginea seen in Peyronie disease.", "C": "Peyronie disease affects penile erectile tissue architecture, not spermatogenesis or sperm transport, so it does not directly cause infertility via azoospermia.", "D": "Priapism is a prolonged, often painful erection typically due to venous outflow obstruction or vasoactive causes (e.g., sickle cell disease), a distinct mechanism from the fibrotic curvature of Peyronie disease."}}}, {"id": "anking-reproductive-system-pathology-2306", "fuente": "anking", "tema": 8, "anki": "1463331372090", "q": "Ischemic priapism (prolonged, painful erection due to impaired venous outflow) is classically associated with which hematologic disorder?", "o": {"A": "Sickle cell anemia", "B": "Hemophilia A", "C": "Polycythemia vera", "D": "Iron deficiency anemia"}, "r": "A", "e": {"correcta": "In sickle cell anemia, sickled red blood cells become trapped within the low-flow, hypoxic vascular channels of the corpus cavernosum, obstructing venous outflow and producing painful ischemic priapism, a recognized vaso-occlusive complication of the disease.", "incorrectas": {"B": "Hemophilia A is a bleeding disorder due to factor VIII deficiency; it predisposes to bleeding, not to the vaso-occlusive erythrocyte sickling that causes ischemic priapism.", "C": "Polycythemia vera increases blood viscosity and thrombotic risk generally, but it is not the classic hematologic condition linked with priapism in standard teaching.", "D": "Iron deficiency anemia causes microcytic anemia from decreased hemoglobin synthesis but does not cause red cell sickling or vaso-occlusion leading to priapism."}}}, {"id": "anking-reproductive-system-pathology-2307", "fuente": "anking", "tema": 8, "anki": "1463331383138", "q": "Which condition is defined as failure of the testicle to descend into the scrotal sac?", "o": {"A": "Varicocele", "B": "Cryptorchidism", "C": "Hydrocele", "D": "Testicular torsion"}, "r": "B", "e": {"correcta": "Cryptorchidism is the failure of one or both testes to descend into the scrotum during development; most cases resolve spontaneously in the first year of life, but persistent cryptorchidism warrants orchiopexy (ideally before 1-2 years of age) to reduce risks of infertility, torsion, and up to a 50-fold increased risk of testicular malignancy.", "incorrectas": {"A": "Varicocele is abnormal dilation of the pampiniform venous plexus within the scrotum, unrelated to testicular descent, and classically described as a \"bag of worms.\"", "C": "Hydrocele is an abnormal fluid collection within the tunica vaginalis surrounding the testis, a distinct scrotal finding from failure of testicular descent.", "D": "Testicular torsion is twisting of the spermatic cord causing acute testicular ischemia, a surgical emergency unrelated to failure of embryologic descent."}}}, {"id": "anking-reproductive-system-pathology-2308", "fuente": "anking", "tema": 8, "anki": "1463334066900", "q": "What is the most common congenital male reproductive abnormality?", "o": {"A": "Hypospadias", "B": "Cryptorchidism", "C": "Epispadias", "D": "Penile agenesis"}, "r": "B", "e": {"correcta": "Cryptorchidism, the failure of testicular descent into the scrotum, is the most common congenital anomaly of the male reproductive tract, particularly common in premature infants, and typically resolves spontaneously within the first year of life in most cases.", "incorrectas": {"A": "Hypospadias, a ventral urethral opening due to failure of urethral fold fusion, is also a relatively common congenital anomaly but is not as frequent as cryptorchidism overall.", "C": "Epispadias, involving abnormal dorsal urethral opening due to genital tubercle malposition, is considerably rarer than both hypospadias and cryptorchidism.", "D": "Penile agenesis is an extremely rare congenital anomaly, far less common than cryptorchidism."}}}, {"id": "anking-reproductive-system-pathology-2309", "fuente": "anking", "tema": 8, "anki": "1463334088123", "q": "What effect does cryptorchidism have on future fertility, and what is the underlying mechanism?", "o": {"A": "Increased fertility due to enhanced Leydig cell stimulation", "B": "Decreased fertility due to impaired spermatogenesis from increased testicular temperature", "C": "No effect on fertility as long as descent occurs before puberty", "D": "Decreased fertility due to obstruction of the vas deferens"}, "r": "B", "e": {"correcta": "Normal spermatogenesis requires a testicular temperature slightly below core body temperature, which the scrotum provides; when a testis remains in the abdomen or inguinal canal in cryptorchidism, the elevated temperature impairs germ cell development, reducing sperm count and fertility even after later surgical correction.", "incorrectas": {"A": "Cryptorchidism does not enhance fertility; rather, the abnormal thermal environment harms germ cell development and impairs, rather than improves, spermatogenesis.", "C": "Even with eventual descent or surgical correction, prior prolonged exposure to increased intra-abdominal temperature can cause lasting histologic damage and reduced fertility potential, so timing matters but risk is not eliminated.", "D": "Cryptorchidism does not primarily cause mechanical obstruction of the vas deferens; the fertility impairment is due to a thermally mediated defect in spermatogenesis within the testis itself."}}}, {"id": "anking-reproductive-system-pathology-2310", "fuente": "anking", "tema": 8, "anki": "1463334093889", "q": "Which factor increases the risk of cryptorchidism in a newborn?", "o": {"A": "Post-term delivery", "B": "Premature birth", "C": "Maternal diabetes without other complications", "D": "Cesarean delivery"}, "r": "B", "e": {"correcta": "Testicular descent normally occurs late in gestation, so premature birth increases the likelihood that the testes have not yet completed their descent into the scrotum at the time of delivery, making prematurity a well-recognized risk factor for cryptorchidism.", "incorrectas": {"A": "Post-term delivery would, if anything, allow more time for normal testicular descent to be completed, rather than increasing cryptorchidism risk.", "C": "Maternal diabetes is linked to other neonatal complications (e.g., macrosomia, hypoglycemia) but is not the classic risk factor cited for cryptorchidism; prematurity is the key association.", "D": "Mode of delivery (cesarean versus vaginal) is not a recognized risk factor for cryptorchidism, which relates to the timing of intrauterine testicular descent rather than the birth process itself."}}}, {"id": "anking-reproductive-system-pathology-2311", "fuente": "anking", "tema": 8, "anki": "1463334097647", "q": "Cryptorchidism increases the risk of which class of testicular tumor, particularly seminoma?", "o": {"A": "Sex cord-stromal tumors", "B": "Germ cell tumors", "C": "Lymphomas", "D": "Metastatic tumors"}, "r": "B", "e": {"correcta": "The abnormal intra-abdominal or inguinal environment in cryptorchidism predisposes germ cells to malignant transformation, most notably increasing the risk of seminoma (as well as other germ cell tumors), even in the contralateral, normally descended testis, underscoring the need for orchiopexy and ongoing surveillance.", "incorrectas": {"A": "Sex cord-stromal tumors (e.g., Leydig cell, Sertoli cell tumors) arise from supporting testicular tissue rather than germ cells and are not the tumor type classically linked to cryptorchidism.", "C": "Testicular lymphoma typically occurs in older men as part of systemic or primary extranodal lymphoma and is not specifically associated with a history of cryptorchidism.", "D": "Metastatic tumors to the testis are rare and unrelated to the germ cell malignant transformation risk that defines the cryptorchidism-cancer association."}}}, {"id": "anking-reproductive-system-pathology-2312", "fuente": "anking", "tema": 8, "anki": "1463334101161", "q": "A man with bilateral cryptorchidism undergoes hormone testing. What is the expected effect on serum inhibin B levels?", "o": {"A": "Increased, due to Sertoli cell hyperplasia", "B": "Decreased, due to decreased Sertoli cell activity", "C": "Unchanged, since Sertoli cells are unaffected", "D": "Decreased, due to decreased Leydig cell activity"}, "r": "B", "e": {"correcta": "Cryptorchidism exposes the undescended testis to the higher intra-abdominal temperature, which damages the heat-sensitive seminiferous tubules and their Sertoli cells. Since Sertoli cells are the source of inhibin B, their dysfunction leads to decreased inhibin B production, which in turn removes negative feedback on FSH, raising FSH levels.", "incorrectas": {"A": "Sertoli cells do not hyperplasia in cryptorchidism; instead, the heat-sensitive germinal epithelium and supporting Sertoli cells are damaged, reducing (not increasing) inhibin B secretion.", "C": "Sertoli cells are actually the primary cell type damaged by the increased temperature of an undescended testis, since spermatogenesis and the seminiferous tubule epithelium are exquisitely heat-sensitive, unlike Leydig cells.", "D": "Leydig cells are relatively spared in cryptorchidism, which is why testosterone (Leydig-derived) often remains normal in unilateral cases, but inhibin B (Sertoli-derived) still falls because the tubular epithelium is damaged."}}}, {"id": "anking-reproductive-system-pathology-2313", "fuente": "anking", "tema": 8, "anki": "1463334104014", "q": "In a patient with cryptorchidism, damage to Sertoli cells reduces inhibin B secretion. What is the resulting effect on serum FSH?", "o": {"A": "Increased", "B": "Decreased", "C": "No change", "D": "Initially increased, then decreased"}, "r": "A", "e": {"correcta": "Inhibin B, secreted by Sertoli cells, normally exerts negative feedback on the anterior pituitary to suppress FSH secretion. In cryptorchidism, heat-induced Sertoli cell dysfunction lowers inhibin B, removing this feedback and causing FSH to rise.", "incorrectas": {"B": "FSH would decrease only if inhibin B (or another negative feedback signal) increased; in cryptorchidism inhibin B falls, so FSH rises rather than falls.", "C": "FSH is expected to change because the hypothalamic-pituitary-gonadal axis is tightly regulated by inhibin B feedback, and loss of Sertoli cell function directly perturbs this axis.", "D": "There is no described biphasic pattern in cryptorchidism; the damage to Sertoli cells is a sustained process leading to a persistent decrease in inhibin B and a persistent rise in FSH."}}}, {"id": "anking-reproductive-system-pathology-2314", "fuente": "anking", "tema": 8, "anki": "1463334107038", "q": "A man has bilateral cryptorchidism. What is the expected effect on serum testosterone levels?", "o": {"A": "Increased", "B": "Normal", "C": "Decreased", "D": "Undetectable"}, "r": "C", "e": {"correcta": "In bilateral cryptorchidism, both testes are exposed to abnormal thermal stress, and over time Leydig cell function can become impaired bilaterally, leading to decreased testosterone. This contrasts with unilateral cryptorchidism, where the contralateral descended testis compensates and testosterone typically remains normal.", "incorrectas": {"A": "Testosterone does not increase in cryptorchidism; the abnormal intra-abdominal environment impairs, rather than stimulates, Leydig cell steroidogenesis when bilateral.", "B": "Testosterone remains normal specifically in unilateral cryptorchidism because the normally descended testis compensates; in bilateral disease, no compensating testis exists, so testosterone falls.", "D": "Testosterone is decreased, not eliminated; some Leydig cell function typically persists even in bilateral cryptorchidism, so levels are low rather than undetectable."}}}, {"id": "anking-reproductive-system-pathology-2315", "fuente": "anking", "tema": 8, "anki": "1463334117729", "q": "A sexually active 22-year-old man presents with acute unilateral testicular pain and swelling. Which pair of organisms is the most common infectious cause of orchitis in his age group?", "o": {"A": "Escherichia coli and Pseudomonas", "B": "Chlamydia trachomatis and Neisseria gonorrhoeae", "C": "Mumps virus and coxsackievirus", "D": "Mycobacterium tuberculosis and Treponema pallidum"}, "r": "B", "e": {"correcta": "In sexually active young adults, orchitis (often preceded by epididymitis) is most commonly caused by the sexually transmitted organisms Chlamydia trachomatis (serotypes D-K) and Neisseria gonorrhoeae. Because Leydig cells are spared, libido and testosterone production remain intact even though the infection increases the risk of sterility from damage to the seminiferous tubules.", "incorrectas": {"A": "E. coli and Pseudomonas are the typical causes of orchitis/epididymitis in older men, usually arising from an ascending urinary tract infection rather than sexual transmission.", "C": "Mumps virus causes orchitis classically in postpubertal adolescent males as a complication of parotitis, not as a sexually transmitted infection, and coxsackievirus is not a classic cause of orchitis in this age group.", "D": "Tuberculous and syphilitic involvement of the testis are rare, granulomatous or chronic causes of orchitis, not the common acute infectious causes seen in sexually active young men."}}}, {"id": "anking-reproductive-system-pathology-2316", "fuente": "anking", "tema": 8, "anki": "1463334127558", "q": "A 68-year-old man with a recent urinary tract infection develops orchitis. Which organisms are the most likely infectious cause?", "o": {"A": "Chlamydia trachomatis and Neisseria gonorrhoeae", "B": "E. coli and Pseudomonas", "C": "Mumps virus", "D": "Coxsackievirus and adenovirus"}, "r": "B", "e": {"correcta": "In older men, orchitis (often as an extension of epididymitis) is typically caused by the same gram-negative organisms responsible for urinary tract infections, particularly E. coli and Pseudomonas, spreading retrograde from the bladder or prostate.", "incorrectas": {"A": "Chlamydia and gonorrhea are the classic causes of orchitis/epididymitis in younger, sexually active men, not older men whose infections typically arise from urinary pathogens.", "C": "Mumps virus classically causes orchitis in postpubertal adolescents following parotitis, not in elderly men with a preceding UTI.", "D": "Coxsackievirus and adenovirus are not classic causes of orchitis; this patient's age and antecedent UTI point to an ascending bacterial infection rather than a viral etiology."}}}, {"id": "anking-reproductive-system-pathology-2317", "fuente": "anking", "tema": 8, "anki": "1463334134563", "q": "A 14-year-old boy develops parotitis followed by unilateral testicular pain and swelling. What virus is the likely cause of his orchitis?", "o": {"A": "Coxsackievirus B", "B": "Mumps virus", "C": "Epstein-Barr virus", "D": "Cytomegalovirus"}, "r": "B", "e": {"correcta": "Mumps virus is the classic viral cause of orchitis in postpubertal (teenage and older) males, typically occurring days after parotitis. It increases the risk of infertility, especially with bilateral involvement, and is rarely seen in prepubertal boys under 10 years old.", "incorrectas": {"A": "Coxsackievirus B is associated with myocarditis and pericarditis, not classically with orchitis following parotitis.", "C": "Epstein-Barr virus causes infectious mononucleosis with pharyngitis, lymphadenopathy, and splenomegaly, not the parotitis-orchitis syndrome characteristic of mumps.", "D": "Cytomegalovirus typically causes mononucleosis-like illness or congenital infection, not the postpubertal parotitis-associated orchitis seen with mumps."}}}, {"id": "anking-reproductive-system-pathology-2318", "fuente": "anking", "tema": 8, "anki": "1463334142308", "q": "A patient has granulomatous inflammation of the seminiferous tubules on testicular biopsy, raising concern for a granulomatous infection. What type of orchitis produces this histologic pattern in the absence of infection?", "o": {"A": "Autoimmune orchitis", "B": "Gonococcal orchitis", "C": "Mumps orchitis", "D": "E. coli orchitis"}, "r": "A", "e": {"correcta": "Autoimmune orchitis produces granulomatous inflammation confined to the seminiferous tubules and is an important noninfectious mimicker of tuberculous orchitis, which must be excluded (ddx: TB) since TB can also cause granulomatous inflammation of the testis.", "incorrectas": {"B": "Gonococcal orchitis produces an acute suppurative, neutrophil-rich inflammatory response as part of a sexually transmitted infection, not a granulomatous reaction.", "C": "Mumps orchitis causes an acute interstitial lymphocytic inflammation and edema of the testis following viral parotitis, not granulomatous inflammation of the tubules.", "D": "E. coli orchitis, typically arising from an ascending urinary tract infection in older men, causes acute bacterial suppurative inflammation rather than granulomas."}}}, {"id": "anking-reproductive-system-pathology-2319", "fuente": "anking", "tema": 8, "anki": "1463334145617", "q": "A neonate presents with a firm, tender, discolored hemiscrotum due to twisting of the spermatic cord. Over which vascular structures does this twisting primarily compromise blood flow first?", "o": {"A": "Thick-walled testicular arteries", "B": "Thin-walled veins of the scrotum/spermatic cord", "C": "The pampiniform venous plexus alone, sparing the spermatic cord", "D": "The inferior epigastric vessels"}, "r": "B", "e": {"correcta": "Testicular torsion occurs when the spermatic cord twists, compressing the thin-walled, low-pressure veins before the thick-walled, higher-pressure arteries are occluded. This is often due to a congenital defect in testicular fixation (e.g., absent or abnormal gubernacular attachment, the 'bell-clapper' deformity), allowing the testis to rotate freely around its vascular pedicle.", "incorrectas": {"A": "The thick, muscular walls of the testicular arteries make them more resistant to compression than the thin-walled veins, so arterial inflow initially continues even as venous outflow is obstructed.", "C": "The twisting involves the entire spermatic cord and its full vascular pedicle (arteries, veins, and ductus deferens), not merely an isolated segment of the pampiniform plexus.", "D": "The inferior epigastric vessels lie outside the spermatic cord and are not the vessels compromised by torsion; the relevant vasculature is the testicular artery and pampiniform plexus veins within the cord."}}}, {"id": "anking-reproductive-system-pathology-2320", "fuente": "anking", "tema": 8, "anki": "1463334152127", "q": "Testicular torsion, if not promptly corrected, leads to what type of infarction of the testicle?", "o": {"A": "Coagulative infarction", "B": "Liquefactive infarction", "C": "Hemorrhagic infarction", "D": "Caseous infarction"}, "r": "C", "e": {"correcta": "Testicular torsion compresses the thin-walled venous outflow while arterial inflow through the thick-walled testicular artery continues, causing the testis to become engorged with blood. This vascular congestion results in a hemorrhagic infarction, distinct from the typical coagulative infarcts seen in most solid organs.", "incorrectas": {"B": "Liquefactive infarction is characteristic of the brain (due to its high lipid content and lack of a strong stromal framework) or of abscess formation, not the venous congestion pattern of testicular torsion.", "A": "Coagulative infarction is the typical pattern in solid organs with a single dominant arterial supply (like the heart or kidney), where the tissue architecture is preserved as a 'ghost outline'; it does not describe the blood-engorged appearance from torsion.", "D": "Caseous infarction/necrosis is associated with granulomatous diseases like tuberculosis, producing a cheese-like appearance, unrelated to the acute vascular event of torsion."}}}, {"id": "anking-reproductive-system-pathology-2321", "fuente": "anking", "tema": 8, "anki": "1463334161746", "q": "A 'bag of worms' scrotal mass that increases in size with Valsalva is found to be due to dilated veins in a specific venous network. Which structure is affected?", "o": {"A": "Pampiniform plexus", "B": "Deep dorsal vein of the penis", "C": "Testicular artery", "D": "Vesical venous plexus"}, "r": "A", "e": {"correcta": "A varicocele results from dilation of the pampiniform plexus, the network of veins draining the testis that wraps around the testicular artery and functions as a countercurrent heat exchanger to keep testicular temperature lower than core body temperature. Increased venous pressure in this plexus causes the characteristic 'bag of worms' feel.", "incorrectas": {"B": "The deep dorsal vein of the penis drains the penis, not the testis, and is unrelated to the scrotal venous congestion seen in varicocele.", "C": "The testicular artery is the structure surrounded by the pampiniform plexus for heat exchange, but it is the venous plexus, not the artery, that dilates in a varicocele.", "D": "The vesical venous plexus drains the bladder and is anatomically and functionally distinct from the testicular venous drainage responsible for varicocele."}}}, {"id": "anking-reproductive-system-pathology-2322", "fuente": "anking", "tema": 8, "anki": "1463334164527", "q": "What is the most common cause of scrotal enlargement in adult males?", "o": {"A": "Hydrocele", "B": "Spermatocele", "C": "Varicocele", "D": "Testicular tumor"}, "r": "C", "e": {"correcta": "Varicocele, dilation of the pampiniform plexus due to increased venous pressure, is the most common cause of scrotal enlargement in adult men. It is typically painless, more common on the left due to the anatomy of the left testicular vein's drainage, and classically described as a 'bag of worms.'", "incorrectas": {"B": "Hydrocele is a common cause of scrotal swelling but is due to fluid accumulation within the tunica vaginalis, and it is not the single most common cause of scrotal enlargement overall in adults.", "A": "Spermatocele is a retention cyst of the epididymis or rete testis presenting as a discrete paratesticular nodule, much less common as a cause of overall scrotal enlargement than varicocele.", "D": "Testicular tumors are an important but far less common cause of scrotal enlargement compared with varicocele, and typically present as a firm, painless, non-transilluminating mass rather than diffuse enlargement."}}}, {"id": "anking-reproductive-system-pathology-2323", "fuente": "anking", "tema": 8, "anki": "1463334184167", "q": "A new-onset left-sided varicocele in an older man raises concern for which underlying malignancy invading the renal vein and increasing venous pressure?", "o": {"A": "Renal cell carcinoma", "B": "Wilms tumor", "C": "Transitional cell carcinoma of the bladder", "D": "Adrenocortical carcinoma"}, "r": "A", "e": {"correcta": "Renal cell carcinoma has a propensity to invade the left renal vein (which the left testicular vein drains into), raising venous pressure and causing a left-sided varicocele, particularly notable when it appears suddenly in an older man or does not decompress when supine.", "incorrectas": {"B": "Wilms tumor is a pediatric renal malignancy; it is not the classic adult tumor associated with new-onset varicocele via renal vein invasion.", "C": "Transitional cell carcinoma of the bladder does not characteristically invade the renal vein or cause varicocele; it more commonly presents with painless hematuria.", "D": "Adrenocortical carcinoma can invade the adrenal vein but is not the classic tumor linked to left-sided varicocele via renal vein compression; renal cell carcinoma is the classic association due to its direct anatomic relationship to the left renal vein."}}}, {"id": "anking-reproductive-system-pathology-2324", "fuente": "anking", "tema": 8, "anki": "1463334193640", "q": "A varicocele impairs the pampiniform plexus's heat-exchange function around the testicular artery. What effect does this have on fertility?", "o": {"A": "No effect on fertility", "B": "Increased fertility due to increased blood flow", "C": "Decreased fertility", "D": "Fertility effects only if bilateral"}, "r": "C", "e": {"correcta": "The pampiniform plexus normally cools arterial blood before it reaches the testis via a countercurrent mechanism; dysfunction from varicocele raises testicular temperature, impairing spermatogenesis and decreasing fertility. This is a correctable cause of male infertility.", "incorrectas": {"A": "Varicocele does have a real effect on fertility; it is one of the most common correctable causes of male subfertility due to impaired testicular thermoregulation.", "B": "Increased venous pressure and blood pooling do not enhance testicular function; instead, they raise local temperature and impair spermatogenesis, reducing rather than improving fertility.", "D": "Even unilateral varicocele (which is far more common, especially on the left) can impair fertility because the resulting temperature elevation affects sperm production, not only bilateral cases."}}}, {"id": "anking-reproductive-system-pathology-2325", "fuente": "anking", "tema": 8, "anki": "1463334197478", "q": "On physical exam, a scrotal mass does not transilluminate with a penlight. Which of the following is consistent with this finding?", "o": {"A": "Hydrocele", "B": "Varicocele", "C": "Spermatocele", "D": "Simple congenital hydrocele"}, "r": "B", "e": {"correcta": "A varicocele, being a solid mass of dilated, blood-filled veins rather than a fluid-filled sac, does not transilluminate, which helps differentiate it from a hydrocele on physical exam.", "incorrectas": {"A": "A hydrocele is a fluid collection within the tunica vaginalis and characteristically DOES transilluminate, which is the key feature used to distinguish it from solid masses like varicocele or tumor.", "C": "A spermatocele is a fluid-filled cystic dilation of the epididymal duct or rete testis and typically transilluminates, similar to a hydrocele, unlike the solid, non-transilluminating varicocele.", "D": "A congenital (communicating) hydrocele is a fluid collection connected to the peritoneal cavity via a patent processus vaginalis and, like other hydroceles, transilluminates."}}}, {"id": "anking-reproductive-system-pathology-2326", "fuente": "anking", "tema": 8, "anki": "1463334201001", "q": "Which imaging modality is used to confirm the diagnosis of a suspected varicocele?", "o": {"A": "Plain abdominal radiograph", "B": "CT of the abdomen and pelvis without contrast", "C": "Ultrasound with Doppler", "D": "MRI of the pelvis"}, "r": "C", "e": {"correcta": "Ultrasound with Doppler is the imaging modality of choice for varicocele, as it can visualize dilated, tortuous veins of the pampiniform plexus and demonstrate abnormal venous flow, particularly with Valsalva maneuver.", "incorrectas": {"A": "Plain radiographs do not have the soft tissue and vascular resolution needed to characterize venous dilation and flow in the scrotum, making them inadequate for diagnosing varicocele.", "B": "CT of the abdomen and pelvis is not first-line for scrotal pathology because it involves radiation and does not provide the dynamic vascular flow information that Doppler ultrasound offers.", "D": "MRI is not routinely used for the initial diagnosis of varicocele; ultrasound with Doppler is preferred due to its accessibility, low cost, and ability to assess venous flow directly."}}}, {"id": "anking-reproductive-system-embryology-2327", "fuente": "anking", "tema": 33, "anki": "1463334225957", "q": "An infant is found to have a congenital 'communicating' hydrocele that changes size with straining. This results from incomplete obliteration of which embryologic structure?", "o": {"A": "Gubernaculum", "B": "Processus vaginalis", "C": "Mesonephric duct", "D": "Paramesonephric duct"}, "r": "B", "e": {"correcta": "The processus vaginalis is a peritoneal evagination that the testis pulls along as it descends into the scrotum; it normally obliterates, sealing off a portion as the tunica vaginalis. Failure of complete closure allows peritoneal fluid to communicate with the scrotal sac, producing a communicating hydrocele that often resolves spontaneously by age 1 but can predispose to an indirect inguinal hernia later in life.", "incorrectas": {"A": "The gubernaculum is the fibrous cord that guides testicular descent into the scrotum and later becomes the scrotal ligament; it does not form the peritoneal-lined sac responsible for a communicating hydrocele.", "C": "The mesonephric (Wolffian) duct gives rise to structures like the epididymis, vas deferens, and seminal vesicles in males, not the peritoneal outpouching involved in hydrocele formation.", "D": "The paramesonephric (Müllerian) duct regresses in males under the influence of anti-Müllerian hormone and, when persistent, contributes to structures like the appendix testis, not to hydrocele formation."}}}, {"id": "anking-reproductive-system-pathology-2328", "fuente": "anking", "tema": 8, "anki": "1463334232508", "q": "An adult man develops a noncommunicating hydrocele following an episode of epididymitis. This type of acquired hydrocele is typically due to blockage of which type of drainage?", "o": {"A": "Venous drainage", "B": "Lymphatic drainage", "C": "Arterial supply", "D": "Vas deferens patency"}, "r": "B", "e": {"correcta": "Acquired (noncommunicating) hydroceles in adults arise secondary to infection, trauma, or tumor, which can obstruct lymphatic drainage of the tunica vaginalis, leading to fluid accumulation. If the fluid is bloody, it is termed a hematocele.", "incorrectas": {"A": "Venous obstruction causing scrotal swelling is more characteristic of a varicocele (dilated pampiniform plexus veins) rather than the serous fluid accumulation of an acquired hydrocele.", "C": "Arterial compromise would lead to ischemia or infarction (as in testicular torsion), not the fluid accumulation pattern seen in an acquired hydrocele.", "D": "Vas deferens obstruction affects sperm transport and can cause epididymal congestion, but it is not the mechanism behind fluid accumulation in the tunica vaginalis characteristic of hydrocele."}}}, {"id": "anking-reproductive-system-pathology-2329", "fuente": "anking", "tema": 8, "anki": "1463334264578", "q": "A scrotal mass transilluminates with a penlight. Which of the following is most consistent with this finding?", "o": {"A": "Testicular tumor", "B": "Varicocele", "C": "Hydrocele", "D": "Testicular torsion"}, "r": "C", "e": {"correcta": "A hydrocele is a collection of serous fluid within the tunica vaginalis, and fluid-filled structures transilluminate readily, producing a glow when a penlight is held against the scrotum. This helps differentiate a benign hydrocele from a solid mass such as a tumor.", "incorrectas": {"A": "Testicular tumors are solid masses and characteristically do NOT transilluminate, which is a key clinical clue used to distinguish them from a hydrocele.", "B": "A varicocele is a solid mass of dilated, blood-filled veins and does not transilluminate, unlike the fluid collection of a hydrocele.", "D": "Testicular torsion presents with an acutely tender, swollen, and often high-riding testicle due to ischemia and hemorrhagic infarction, not a fluid collection that transilluminates."}}}, {"id": "anking-reproductive-system-pathology-2330", "fuente": "anking", "tema": 8, "anki": "1463334269994", "q": "A paratesticular, fluctuant nodule is found to be a scrotal cyst arising from a dilated portion of the epididymis or rete testis. What is this lesion called?", "o": {"A": "Varicocele", "B": "Hydrocele", "C": "Spermatocele", "D": "Epididymal cyst of Müllerian origin"}, "r": "C", "e": {"correcta": "A spermatocele is a scrotal cyst caused by dilation of the epididymal duct or rete testis, classically presenting as a distinct, fluctuant, paratesticular nodule separate from the testis itself, often containing sperm-laden fluid.", "incorrectas": {"A": "A varicocele is a network of dilated veins in the pampiniform plexus, not a cystic dilation of a duct, and typically has a 'bag of worms' texture rather than a discrete fluctuant nodule.", "B": "A hydrocele is a fluid collection surrounding the testis within the tunica vaginalis, not a discrete cystic structure arising from the epididymal duct system.", "D": "There is no clinically recognized entity called an 'epididymal cyst of Müllerian origin' that matches this description; spermatocele arises from mesonephric (Wolffian) duct-derived structures, the epididymis and rete testis."}}}, {"id": "anking-reproductive-system-pathology-2331", "fuente": "anking", "tema": 8, "anki": "1463339050251", "q": "Testicular tumors are broadly classified based on their cell of origin. Which two categories account for essentially all testicular tumors?", "o": {"A": "Germ cell and sex-cord stromal tumors", "B": "Epithelial and mesenchymal tumors", "C": "Germ cell and epithelial tumors", "D": "Sex-cord stromal and lymphoid tumors"}, "r": "A", "e": {"correcta": "Testicular tumors are broadly divided into germ cell tumors (the vast majority, including seminoma and non-seminomatous types) and sex-cord stromal tumors (arising from Sertoli or Leydig cells), which together account for essentially all primary testicular neoplasms.", "incorrectas": {"B": "The terms 'epithelial' and 'mesenchymal' are not the standard classification framework used for testicular tumors; the testis-specific classification is germ cell versus sex-cord stromal origin.", "C": "'Epithelial tumors' is not a standard category for testicular neoplasms in this classification scheme; the paired category to germ cell tumors is sex-cord stromal tumors.", "D": "Lymphoid tumors (testicular lymphoma) can occur, especially in older men, but they are a distinct, less common category and not one of the two primary classifications (germ cell vs. sex-cord stromal) that account for the vast majority of testicular tumors."}}}, {"id": "anking-reproductive-system-pathology-2332", "fuente": "anking", "tema": 8, "anki": "1463339928621", "q": "A young man presents with a firm, painless testicular mass. Which finding on physical exam helps distinguish a testicular tumor from a hydrocele?", "o": {"A": "The mass transilluminates", "B": "The mass does not transilluminate", "C": "The mass is fluctuant", "D": "The mass increases with Valsalva"}, "r": "B", "e": {"correcta": "Testicular tumors present as firm, painless, solid testicular masses that do NOT transilluminate, an important distinguishing feature from a hydrocele, which is fluid-filled and does transilluminate. Ultrasound is typically the first imaging test used to further characterize the mass.", "incorrectas": {"A": "Transillumination is a feature of fluid-filled scrotal masses like hydroceles and spermatoceles, not solid testicular tumors, which block light transmission.", "C": "Fluctuance suggests a fluid-filled or cystic structure (such as a hydrocele or spermatocele), whereas a testicular tumor is characteristically firm and solid.", "D": "Increasing in size with Valsalva is characteristic of a varicocele due to increased venous pressure, not of a solid testicular tumor, which does not change with straining."}}}, {"id": "anking-reproductive-system-pathology-2333", "fuente": "anking", "tema": 8, "anki": "1463339955533", "q": "A suspected testicular tumor is identified on ultrasound. Why is a percutaneous biopsy avoided as part of the diagnostic workup?", "o": {"A": "It has no diagnostic yield", "B": "It carries an increased risk of seeding the scrotum with tumor cells", "C": "It requires general anesthesia unavailable for outpatients", "D": "It is contraindicated due to bleeding risk from the pampiniform plexus"}, "r": "B", "e": {"correcta": "Testicular tumors are not biopsied through the scrotum because doing so risks seeding tumor cells into the scrotal sac or altering lymphatic drainage, which could allow spread to inguinal lymph nodes instead of the normal retroperitoneal route. Instead, suspected tumors are managed with radical orchiectomy, removing the testicle and spermatic cord at the level where it exits the body.", "incorrectas": {"A": "Biopsy would actually have diagnostic yield; the concern is not lack of information but the risk of tumor seeding and altered lymphatic spread, which is why radical orchiectomy is performed instead of biopsy.", "C": "Anesthesia availability is not the reason biopsy is avoided; the central concern is oncologic, related to tumor seeding and disruption of normal lymphatic drainage pathways.", "D": "While the scrotum is vascular, the primary reason biopsy is avoided is oncologic risk of seeding, not simply a bleeding risk from the pampiniform plexus."}}}, {"id": "anking-reproductive-system-pathology-2334", "fuente": "anking", "tema": 8, "anki": "1463339968803", "q": "What is the most common class of testicular tumor, accounting for greater than 95% of cases?", "o": {"A": "Sex-cord stromal tumors", "B": "Lymphomas", "C": "Germ cell tumors", "D": "Metastatic tumors"}, "r": "C", "e": {"correcta": "Germ cell tumors make up more than 95% of testicular tumors and are further subdivided into seminomas and non-seminomatous germ cell tumors (embryonal carcinoma, yolk sac tumor, choriocarcinoma, teratoma), making them the dominant category to know for testicular neoplasia.", "incorrectas": {"A": "Sex-cord stromal tumors (Leydig cell, Sertoli cell tumors) make up a small minority of testicular tumors, far less than the germ cell category.", "B": "Primary testicular lymphoma is an important consideration especially in older men, but it represents a small fraction of testicular tumors overall, not the majority.", "D": "Metastatic tumors to the testis are rare and not the predominant category; the vast majority of testicular tumors are primary germ cell tumors."}}}, {"id": "anking-reproductive-system-pathology-2335", "fuente": "anking", "tema": 8, "anki": "1463339972200", "q": "Among testicular germ cell tumors, which single histologic subtype is the most common overall?", "o": {"A": "Embryonal carcinoma", "B": "Choriocarcinoma", "C": "Seminoma", "D": "Yolk sac tumor"}, "r": "C", "e": {"correcta": "Seminoma is the single most common testicular germ cell tumor, characteristically presenting in adult men, composed of large cells with clear cytoplasm and central nuclei, and it is notably radiosensitive with a generally favorable prognosis compared to non-seminomatous tumors.", "incorrectas": {"A": "Embryonal carcinoma is a non-seminomatous germ cell tumor that is aggressive with early metastasis, but it is less common than seminoma as a standalone tumor type.", "B": "Choriocarcinoma is a rare, highly aggressive non-seminomatous germ cell tumor with early hematogenous spread, but it is one of the least common subtypes, not the most common.", "D": "Yolk sac tumor is the most common testicular tumor in young children, but in the overall population of testicular germ cell tumors, seminoma remains the most frequent subtype."}}}, {"id": "anking-reproductive-system-pathology-2336", "fuente": "anking", "tema": 8, "anki": "1463339975628", "q": "Testicular germ cell tumors most commonly affect men in which age range?", "o": {"A": "Under 3 years", "B": "15-40 years", "C": "50-70 years", "D": "Over 70 years"}, "r": "B", "e": {"correcta": "Testicular germ cell tumors classically affect men aged 15-40 years, making testicular cancer one of the most common solid tumors in young adult men, in contrast to many other cancers that peak in older age.", "incorrectas": {"A": "Children under 3 years old are the classic age group for yolk sac (endodermal sinus) tumors specifically, not germ cell tumors as a whole, which peak in young adulthood.", "C": "Testicular lymphoma, rather than germ cell tumors, is the more common testicular malignancy in men over 50-60 years old.", "D": "Testicular germ cell tumors are uncommon in elderly men; when a testicular mass occurs in this age group, lymphoma is a more likely diagnosis than a primary germ cell tumor."}}}, {"id": "anking-reproductive-system-pathology-2337", "fuente": "anking", "tema": 8, "anki": "1463339978379", "q": "Which two conditions are established risk factors for testicular germ cell tumors?", "o": {"A": "Hydrocele and spermatocele", "B": "Cryptorchidism and Klinefelter syndrome", "C": "Varicocele and orchitis", "D": "Testicular torsion and epididymitis"}, "r": "B", "e": {"correcta": "Cryptorchidism (even after surgical correction) and Klinefelter syndrome (47,XXY) are established risk factors for testicular germ cell tumors, related to abnormal germ cell development and exposure of testicular tissue to abnormal conditions during development.", "incorrectas": {"A": "Hydrocele and spermatocele are benign fluid-filled scrotal masses with no established association with increased risk of germ cell tumor development.", "C": "Varicocele and orchitis are common scrotal conditions related to venous congestion and infection/inflammation, respectively, but are not established germ cell tumor risk factors.", "D": "Testicular torsion and epididymitis are acute vascular and infectious/inflammatory processes, respectively, without an established causal link to germ cell tumor risk."}}}, {"id": "anking-reproductive-system-pathology-2338", "fuente": "anking", "tema": 8, "anki": "1463339987206", "q": "Compared to seminomas, non-seminomatous germ cell tumors, which make up about 43% of testicular germ cell tumors, are characterized by what clinical behavior?", "o": {"A": "Uniform excellent response to radiotherapy and late metastasis", "B": "Variable response to radiotherapy and early metastasis", "C": "No metastatic potential", "D": "Exclusive lymphatic spread with no hematogenous dissemination"}, "r": "B", "e": {"correcta": "Non-seminomatous germ cell tumors (embryonal carcinoma, yolk sac tumor, choriocarcinoma, teratoma), comprising roughly 43% of testicular germ cell tumors, tend to have variable and generally poorer responses to radiotherapy compared with seminomas, and they metastasize early, often hematogenously, contributing to their relatively worse prognosis.", "incorrectas": {"A": "It is seminoma, not non-seminomatous tumors, that is exquisitely radiosensitive; non-seminomas have a variable and often poor response to radiotherapy and tend to metastasize early rather than late.", "C": "Non-seminomatous germ cell tumors, particularly embryonal carcinoma and choriocarcinoma, have significant and often early metastatic potential, contrary to having no metastatic potential.", "D": "Non-seminomatous tumors, especially choriocarcinoma and embryonal carcinoma, are notorious for early hematogenous spread (e.g., to lungs and liver), not exclusively lymphatic spread."}}}, {"id": "anking-hematology-oncology-physiology-2339", "fuente": "anking", "tema": 28, "anki": "1463340004334", "q": "A rare seminoma is found to secrete a hormone typically associated with pregnancy and choriocarcinoma. Which hormone can be elevated in some seminomas due to syncytiotrophoblastic cells?", "o": {"A": "AFP", "B": "hCG", "C": "LDH only", "D": "Placental lactogen"}, "r": "B", "e": {"correcta": "Although classic seminomas are typically not associated with significant tumor marker elevation, a subset can contain syncytiotrophoblastic giant cells that secrete hCG, causing modestly elevated serum hCG levels in some cases despite the absence of true choriocarcinoma elements.", "incorrectas": {"A": "Elevated AFP is characteristic of yolk sac tumor or mixed germ cell tumors with a yolk sac component; a pure seminoma with elevated AFP should prompt reclassification, since seminomas themselves do not produce AFP.", "C": "LDH can be elevated as a nonspecific marker of tumor burden in various germ cell tumors including seminoma, but it is not the specific hormone being asked about here; hCG is the hormone occasionally elevated in seminoma.", "D": "Placental lactogen is not a standard tumor marker used or classically elevated in testicular germ cell tumors, unlike hCG."}}}, {"id": "anking-reproductive-system-pathology-2340", "fuente": "anking", "tema": 8, "anki": "1463340008364", "q": "Seminomas are classically associated with increased levels of which enzyme, also known as PALP?", "o": {"A": "Alkaline phosphatase (placental type)", "B": "Lactate dehydrogenase only", "C": "Alpha-fetoprotein", "D": "Acid phosphatase"}, "r": "A", "e": {"correcta": "Seminomas are classically associated with elevated placental alkaline phosphatase (PLAP/PALP), an isoenzyme of alkaline phosphatase that serves as a relatively specific (though not universally used) tumor marker for this germ cell tumor subtype.", "incorrectas": {"B": "LDH can be elevated in seminoma as a marker of tumor bulk and turnover, but the enzyme specifically referred to as PALP is placental alkaline phosphatase, not LDH.", "C": "Alpha-fetoprotein (AFP) is not produced by pure seminomas; its presence should raise suspicion for a non-seminomatous component such as yolk sac tumor within a mixed germ cell tumor.", "D": "Acid phosphatase (specifically prostatic acid phosphatase) is historically associated with prostate cancer, not testicular seminoma."}}}, {"id": "anking-reproductive-system-pathology-2341", "fuente": "anking", "tema": 8, "anki": "1463340020371", "q": "Which testicular germ cell tumor is classically described as having a glandular or papillary histologic morphology and an aggressive course with early hematogenous spread?", "o": {"A": "Seminoma", "B": "Embryonal carcinoma", "C": "Mature teratoma", "D": "Leydig cell tumor"}, "r": "B", "e": {"correcta": "Embryonal carcinoma is a non-seminomatous germ cell tumor that often shows a glandular or papillary architecture on histology and is notably aggressive, with a tendency toward early hematogenous metastasis, distinguishing it from the more indolent seminoma.", "incorrectas": {"A": "Seminoma has a characteristic histology of sheets of large, uniform cells with clear cytoplasm and a 'fried egg' appearance, along with lymphocytic infiltrate, not the glandular/papillary pattern of embryonal carcinoma.", "C": "Mature teratoma contains tissue from multiple germ layers (e.g., hair, cartilage, teeth) and is generally more indolent in adults, quite distinct from the glandular/papillary, aggressive histology of embryonal carcinoma.", "D": "Leydig cell tumor is a sex-cord stromal tumor, not a germ cell tumor, and often produces androgens or estrogens rather than showing a glandular/papillary germ cell morphology."}}}, {"id": "anking-reproductive-system-pathology-2342", "fuente": "anking", "tema": 8, "anki": "1463340033880", "q": "After chemotherapy, an embryonal carcinoma may show what change in its histologic appearance?", "o": {"A": "Complete necrosis with no residual tissue", "B": "Differentiation, such as maturation into a teratoma", "C": "Transformation into seminoma", "D": "Dedifferentiation into small cell carcinoma"}, "r": "B", "e": {"correcta": "Chemotherapy can induce embryonal carcinoma to differentiate, sometimes maturing into a teratoma composed of more differentiated tissue types, a phenomenon important to recognize because residual teratoma after chemotherapy is typically chemoresistant and often requires surgical resection.", "incorrectas": {"A": "While chemotherapy can reduce tumor burden, embryonal carcinoma characteristically responds with maturation/differentiation into teratoma-like tissue rather than uniformly complete necrosis.", "C": "There is no described phenomenon of embryonal carcinoma transforming into seminoma after chemotherapy; the recognized pattern is differentiation toward teratoma.", "D": "Dedifferentiation into a more primitive or different malignant tumor type such as small cell carcinoma is not the classic post-chemotherapy pattern described for embryonal carcinoma; maturation into teratoma is the classic finding."}}}, {"id": "anking-reproductive-system-pathology-2343", "fuente": "anking", "tema": 8, "anki": "1463340037592", "q": "Because embryonal carcinoma is a non-seminomatous germ cell tumor, how does its prognosis generally compare to that of seminoma?", "o": {"A": "Better prognosis than seminoma", "B": "Equivalent prognosis to seminoma", "C": "Worse prognosis than seminoma", "D": "Prognosis depends only on patient age, not tumor type"}, "r": "C", "e": {"correcta": "As a non-seminomatous germ cell tumor, embryonal carcinoma tends to have a relatively worse prognosis than seminoma, owing to its more aggressive behavior, tendency for early metastasis, and variable response to radiotherapy; it is also frequently found mixed with other germ cell tumor types.", "incorrectas": {"A": "Embryonal carcinoma does not have a better prognosis than seminoma; seminomas are generally more indolent and highly radiosensitive, giving them a more favorable outlook.", "B": "The prognosis is not equivalent; non-seminomatous tumors like embryonal carcinoma behave more aggressively and have a worse prognosis compared to seminomas of similar stage.", "D": "While age and stage matter for prognosis generally, the histologic subtype itself carries significant prognostic weight, with non-seminomatous tumors like embryonal carcinoma behaving worse than seminoma independent of age."}}}, {"id": "anking-reproductive-system-pathology-2344", "fuente": "anking", "tema": 8, "anki": "1463340046881", "q": "Which tumor marker pattern is characteristic of embryonal carcinoma, including cases where it is mixed with other germ cell components?", "o": {"A": "Elevated hCG and normal or elevated AFP", "B": "Elevated AFP only, with hCG always normal", "C": "Elevated PSA and normal hCG", "D": "Elevated CA-125 and normal AFP"}, "r": "A", "e": {"correcta": "Embryonal carcinoma may show elevated hCG (from syncytiotrophoblastic-like cells) along with normal or elevated AFP; AFP elevation is particularly notable when the tumor is mixed with a yolk sac tumor component, reflecting its heterogeneous cellular origins.", "incorrectas": {"B": "AFP elevation alone with a fixed normal hCG does not capture the pattern; embryonal carcinoma can also show elevated hCG, especially with syncytiotrophoblastic differentiation.", "C": "PSA is a prostate-specific marker and is not relevant to testicular germ cell tumors like embryonal carcinoma.", "D": "CA-125 is a marker more associated with ovarian and other gynecologic malignancies, not testicular germ cell tumors such as embryonal carcinoma."}}}, {"id": "anking-reproductive-system-pathology-2345", "fuente": "anking", "tema": 8, "anki": "1463340062541", "q": "What is the most common testicular tumor in children younger than 3 years old?", "o": {"A": "Seminoma", "B": "Embryonal carcinoma", "C": "Yolk sac (endodermal sinus) tumor", "D": "Leydig cell tumor"}, "r": "C", "e": {"correcta": "Yolk sac (endodermal sinus) tumor is the most common testicular tumor in children under 3 years of age. It characteristically produces elevated alpha-fetoprotein (AFP), which serves as a useful tumor marker in this pediatric population.", "incorrectas": {"A": "Seminoma is the most common germ cell tumor overall but occurs predominantly in adult men aged 15-40 years, not in young children.", "B": "Embryonal carcinoma occurs more often in young adults as part of mixed non-seminomatous tumors, rather than being the predominant testicular tumor in very young children.", "D": "Leydig cell tumor is a sex-cord stromal tumor that can occur in children but is much less common than yolk sac tumor and often presents with precocious puberty due to androgen production rather than as the most common overall pediatric testicular tumor."}}}, {"id": "anking-reproductive-system-pathology-2346", "fuente": "anking", "tema": 8, "anki": "1463340066021", "q": "Histologic examination of a testicular tumor reveals glomeruloid structures known as Schiller-Duval bodies. Which tumor is characterized by this finding?", "o": {"A": "Seminoma", "B": "Choriocarcinoma", "C": "Endodermal sinus (yolk sac) tumor", "D": "Embryonal carcinoma"}, "r": "C", "e": {"correcta": "Schiller-Duval bodies, which resemble primitive glomeruli, are the classic histologic finding in endodermal sinus (yolk sac) tumor, the most common testicular tumor in young children and a tumor that characteristically secretes AFP.", "incorrectas": {"A": "Seminoma shows sheets of uniform, large cells with clear cytoplasm and a fibrous stroma with lymphocytic infiltrate, giving a 'fried egg' appearance, not glomeruloid Schiller-Duval bodies.", "B": "Choriocarcinoma is characterized by cytotrophoblasts and syncytiotrophoblasts producing very high hCG levels, with early hematogenous spread, not Schiller-Duval bodies.", "D": "Embryonal carcinoma shows sheets or glandular/papillary arrangements of primitive, anaplastic cells, but the glomeruloid Schiller-Duval body is specifically the hallmark of yolk sac tumor."}}}, {"id": "anking-reproductive-system-pathology-2347", "fuente": "anking", "tema": 8, "anki": "1463340079417", "q": "A mature cystic teratoma (dermoid cyst) is discovered in the testis of a 25-year-old man. Compared to the same tumor found in the ovary, what is the significance of this finding?", "o": {"A": "It is benign, identical to the ovarian counterpart", "B": "Malignancy is possible, unlike in females", "C": "It always represents metastatic disease", "D": "It requires no further workup regardless of location"}, "r": "B", "e": {"correcta": "Unlike in the ovary, where a mature cystic teratoma is essentially always benign, a mature teratoma in the adult testis is considered potentially malignant. Testicular germ cell tumors arise from a totipotent germ cell population and can behave aggressively or coexist with other malignant germ cell elements, so orchiectomy and staging are warranted even when the histology looks mature.", "incorrectas": {"A": "This describes the ovarian mature cystic teratoma, which is reliably benign; testicular teratomas do not share this favorable behavior because of the different biology of testicular germ cell tumors.", "C": "A testicular teratoma is a primary germ cell tumor arising from within the testis itself, not a metastatic deposit from another primary site.", "D": "Because testicular teratomas carry malignant potential, they require surgical excision (radical orchiectomy) and staging, unlike the ovarian counterpart which can sometimes be observed or managed more conservatively."}}}, {"id": "anking-reproductive-system-pathology-2348", "fuente": "anking", "tema": 8, "anki": "1463340099569", "q": "When a testicular germ cell tumor is composed of multiple histologic components (a mixed germ cell tumor), what determines the patient's prognosis?", "o": {"A": "The average behavior of all components combined", "B": "The most differentiated (best) component present", "C": "The most aggressive (worst) component present", "D": "Only the seminoma component, if present"}, "r": "C", "e": {"correcta": "Testicular germ cell tumors frequently present as mixed tumors containing more than one histologic subtype (e.g., embryonal carcinoma, yolk sac tumor, choriocarcinoma, teratoma, seminoma). Prognosis and treatment are driven by the most aggressive (worst) component present, since even a small focus of a highly malignant element like choriocarcinoma can dictate metastatic potential and outcome.", "incorrectas": {"A": "Prognosis is not an average of components; a single aggressive clone can drive metastasis and death even if it makes up a minority of the tumor volume.", "B": "Focusing on the best-differentiated component would underestimate risk, since the more malignant elements in a mixed tumor determine the true biologic behavior.", "D": "Seminoma is actually one of the more favorable, radiosensitive germ cell tumor types; if a more aggressive nonseminomatous component coexists, that component—not the seminoma—drives prognosis."}}}, {"id": "anking-reproductive-system-pathology-2349", "fuente": "anking", "tema": 8, "anki": "1463340102943", "q": "Testicular sex cord-stromal tumors, composed of Sertoli cells lining tubules with Leydig cells in the interstitium, are usually which of the following?", "o": {"A": "Malignant with early metastasis", "B": "Benign", "C": "Premalignant lesions requiring chemotherapy", "D": "Always hormonally silent"}, "r": "B", "e": {"correcta": "Sex cord-stromal tumors recapitulate the normal testicular architecture, with Sertoli cells forming tubule linings and Leydig cells occupying the interstitium, mirroring the normal seminiferous tubule/interstitial cell relationship. The vast majority of these tumors are benign, in contrast to germ cell tumors, which make up most malignant testicular neoplasms.", "incorrectas": {"A": "Unlike germ cell tumors, sex cord-stromal tumors are usually benign; only a small minority behave malignantly, so early metastasis is not the typical course.", "C": "These tumors are not generally considered premalignant precursors requiring chemotherapy; benign lesions are typically managed with surgical excision alone.", "D": "Leydig cell tumors in particular are often hormonally active, producing androgens or estrogens that can cause precocious puberty or gynecomastia, so silence is not a defining feature."}}}, {"id": "anking-reproductive-system-pathology-2350", "fuente": "anking", "tema": 8, "anki": "1463340128491", "q": "A testicular sex cord-stromal tumor composed of tubules and usually clinically silent (non-hormone-secreting) most likely arises from which cell type?", "o": {"A": "Leydig cells", "B": "Germ cells", "C": "Sertoli cells", "D": "Spermatogonia"}, "r": "C", "e": {"correcta": "Sertoli cell tumors are composed of tubular structures recapitulating the normal tubule-lining Sertoli cells. They are typically clinically silent because Sertoli cells do not characteristically secrete hormones in excess, in contrast to Leydig cell tumors.", "incorrectas": {"A": "Leydig cell tumors arise from the interstitial androgen-producing cells and are often hormonally active, causing precocious puberty in children or gynecomastia in adults—the opposite of the silent presentation described.", "B": "Germ cells give rise to seminomas and nonseminomatous germ cell tumors, which form solid or mixed masses rather than the tubular architecture of a sex cord-stromal tumor.", "D": "Spermatogonia are the germ cell precursors of sperm within the tubules; a tumor of spermatogonia would fall under germ cell tumors, not the tubule-forming Sertoli cell tumor."}}}, {"id": "anking-reproductive-system-pathology-2351", "fuente": "anking", "tema": 8, "anki": "1463340132352", "q": "In a man older than 60 years presenting with a testicular mass, what is the most likely underlying cause of testicular cancer?", "o": {"A": "Seminoma", "B": "Leydig cell tumor", "C": "Embryonal carcinoma", "D": "Lymphoma"}, "r": "D", "e": {"correcta": "In men over 60, testicular malignancy is most commonly lymphoma rather than a primary germ cell tumor. This typically represents metastatic (secondary) involvement of the testis by an aggressive lymphoma, and it is often bilateral.", "incorrectas": {"A": "Seminoma is the most common germ cell tumor overall but classically peaks in men in their 30s-40s, not older men, making it less likely than lymphoma in this age group.", "B": "Leydig cell tumors are uncommon sex cord-stromal tumors that can occur at any age but are not the predominant cause of testicular cancer in elderly men.", "C": "Embryonal carcinoma is an aggressive nonseminomatous germ cell tumor typically seen in younger men, not the classic cause of testicular masses in patients over 60."}}}, {"id": "anking-reproductive-system-pathology-2352", "fuente": "anking", "tema": 8, "anki": "1463340155475", "q": "The lymphoma that most commonly involves the testis in older men, presenting as an aggressive tumor, is best classified as which subtype?", "o": {"A": "Follicular lymphoma", "B": "Diffuse large B-cell lymphoma", "C": "Burkitt lymphoma", "D": "Mantle cell lymphoma"}, "r": "B", "e": {"correcta": "Diffuse large B-cell lymphoma (DLBCL) is the subtype that most commonly causes testicular lymphoma in elderly men. It is an aggressive non-Hodgkin lymphoma that can present as a rapidly enlarging, often bilateral testicular mass, frequently reflecting secondary/metastatic spread.", "incorrectas": {"A": "Follicular lymphoma is an indolent, low-grade B-cell lymphoma that typically presents with slow-growing lymphadenopathy rather than an aggressive testicular mass in the elderly.", "C": "Burkitt lymphoma is a highly aggressive lymphoma associated with EBV and characteristic translocations (e.g., t(8;14)), classically presenting as jaw or abdominal masses in children or in association with immunosuppression, not as the typical testicular lymphoma of older men.", "D": "Mantle cell lymphoma is a distinct B-cell lymphoma associated with cyclin D1 overexpression from t(11;14), and it is not the classic subtype implicated in testicular lymphoma in the elderly."}}}, {"id": "anking-reproductive-system-anatomy-2353", "fuente": "anking", "tema": 34, "anki": "1463343838534", "q": "During a digital rectal exam (DRE), which aspect of the prostate is directly palpable by the examining finger?", "o": {"A": "Anterior aspect", "B": "Posterior aspect", "C": "Lateral apex only", "D": "Transitional zone exclusively"}, "r": "B", "e": {"correcta": "The posterior aspect of the prostate lies directly against the anterior rectal wall, making it the surface accessible to the examining finger during a DRE. This is clinically important because most prostatic adenocarcinomas arise in the posterior peripheral zone, making DRE a useful (though imperfect) screening maneuver for detecting nodules or asymmetry.", "incorrectas": {"A": "The anterior aspect of the prostate faces the pubic symphysis and is not accessible via the rectum, so it cannot be assessed by DRE.", "C": "While the apex can be partially felt, the defining palpable surface on DRE is the posterior gland as a whole, not specifically a lateral apex.", "D": "The transitional (periurethral) zone, the site of BPH, surrounds the urethra centrally and is not the zone directly palpated on DRE; that role belongs to the posterior peripheral zone."}}}, {"id": "anking-reproductive-system-anatomy-2354", "fuente": "anking", "tema": 34, "anki": "1463345881327", "q": "The glands of the prostate secrete fluid of which pH characteristic, which is added to sperm and seminal vesicle fluid to form semen?", "o": {"A": "Strongly acidic", "B": "Neutral", "C": "Alkaline", "D": "Highly variable, unbuffered"}, "r": "C", "e": {"correcta": "Prostatic glandular secretions are alkaline, milky fluid that helps neutralize the acidic environment of the male urethra and female vaginal tract, protecting sperm motility and viability as semen is formed by mixing prostatic fluid with seminal vesicle secretions and sperm.", "incorrectas": {"A": "An acidic prostatic secretion would be hostile to sperm survival and motility; the prostate's alkalinity instead helps counteract the acidity of other reproductive tract environments.", "B": "The prostatic fluid is specifically alkaline, not neutral, which serves the functional purpose of buffering acidic conditions encountered by sperm.", "D": "Prostatic secretion pH is a consistent, characteristic alkaline value rather than an unpredictable or unbuffered quantity, reflecting a specific physiologic adaptation to protect sperm."}}}, {"id": "anking-clinical-bacteriology-2355", "fuente": "anking", "tema": 21, "anki": "1463345914020", "q": "A sexually active 24-year-old man presents with dysuria and a boggy, tender prostate. Which organisms are the most common infectious causes of acute prostatitis in this age group?", "o": {"A": "E. coli and Pseudomonas", "B": "Chlamydia trachomatis and Neisseria gonorrhoeae", "C": "Staphylococcus aureus and Streptococcus agalactiae", "D": "Candida albicans and Trichomonas vaginalis"}, "r": "B", "e": {"correcta": "In young, sexually active men, acute prostatitis is most commonly caused by sexually transmitted organisms, particularly Chlamydia trachomatis (serotypes D-K) and Neisseria gonorrhoeae, reflecting ascending infection from the urethra. This contrasts with the organisms typically responsible in older men.", "incorrectas": {"A": "E. coli and Pseudomonas are the classic causes of acute prostatitis in older men, often related to urinary tract instrumentation or chronic urinary pathology, not the typical picture in young sexually active men.", "C": "Staphylococcus aureus and Streptococcus agalactiae are not the classic pathogens implicated in acute bacterial prostatitis in either age group and are more associated with skin/soft tissue or neonatal infections respectively.", "D": "Candida albicans and Trichomonas vaginalis cause genital infections such as vaginitis/balanitis but are not the classic bacterial causes of acute prostatitis in young men."}}}, {"id": "anking-clinical-bacteriology-2356", "fuente": "anking", "tema": 21, "anki": "1463345919229", "q": "In an elderly man with acute prostatitis, which organisms are the most common infectious causes?", "o": {"A": "Chlamydia trachomatis and Neisseria gonorrhoeae", "B": "E. coli and Pseudomonas", "C": "Mycoplasma genitalium and Ureaplasma", "D": "Enterococcus faecalis exclusively"}, "r": "B", "e": {"correcta": "In older men, acute prostatitis is typically caused by common urinary tract pathogens such as E. coli and Pseudomonas, often related to bladder outlet obstruction (e.g., from BPH), urinary catheterization, or instrumentation that facilitates ascending infection, in contrast to the sexually transmitted organisms seen in younger men.", "incorrectas": {"A": "Chlamydia trachomatis and Neisseria gonorrhoeae are the classic causes of acute prostatitis in young, sexually active men, not the typical pathogens in the elderly population.", "C": "Mycoplasma genitalium and Ureaplasma are atypical genital pathogens implicated in some cases of urethritis but are not the classic teaching for acute prostatitis in older men.", "D": "While Enterococcus can occasionally cause urinary tract infections, it is not the classically taught predominant organism for acute prostatitis in older adults; E. coli and Pseudomonas are the standard answer."}}}, {"id": "anking-reproductive-system-pathology-2357", "fuente": "anking", "tema": 8, "anki": "1463345922819", "q": "A patient with acute prostatitis classically presents with fever, chills, and which additional urinary symptom?", "o": {"A": "Dysuria", "B": "Painless gross hematuria", "C": "Nocturnal enuresis only", "D": "Anuria"}, "r": "A", "e": {"correcta": "Acute prostatitis classically presents with systemic signs of infection (fever, chills) along with dysuria, reflecting inflammation of the prostate gland surrounding the proximal urethra, which irritates urination.", "incorrectas": {"B": "Painless gross hematuria is more suggestive of a urothelial malignancy (e.g., bladder cancer) than an acute infectious process like prostatitis, which typically causes painful voiding symptoms instead.", "C": "Nocturnal enuresis (bedwetting) is not a typical feature of acute prostatitis; obstructive/irritative symptoms like dysuria are more characteristic.", "D": "Anuria (absence of urine output) would suggest severe obstruction or renal failure, not the classic presentation of acute prostatitis, which usually still allows voiding, albeit painfully."}}}, {"id": "anking-reproductive-system-pathology-2358", "fuente": "anking", "tema": 8, "anki": "1463345925967", "q": "On digital rectal exam, a patient with acute prostatitis characteristically has a prostate described using which term?", "o": {"A": "Rock-hard and nodular", "B": "Boggy and tender", "C": "Atrophic and smooth", "D": "Cystic and non-tender"}, "r": "B", "e": {"correcta": "Acute prostatitis classically produces a tender, 'boggy' (soft, swollen, edematous) prostate on DRE, reflecting acute inflammatory edema of the gland. Vigorous prostatic massage should be avoided in suspected acute prostatitis due to risk of triggering bacteremia.", "incorrectas": {"A": "A rock-hard, nodular prostate is characteristic of prostatic adenocarcinoma, not acute infection, and reflects malignant infiltration rather than inflammatory edema.", "C": "An atrophic, smooth prostate would not be the expected finding in an acute inflammatory process; atrophy is more associated with aging or hormonal changes, not acute infection.", "D": "A cystic, non-tender gland does not fit the acute inflammatory presentation; tenderness is a hallmark of acute prostatitis and helps distinguish it from other prostatic conditions."}}}, {"id": "anking-reproductive-system-pathology-2359", "fuente": "anking", "tema": 8, "anki": "1463345936419", "q": "A patient with chronic prostatitis presents with dysuria and pelvic pain. What additional pain location is classically associated with this condition?", "o": {"A": "Low back pain", "B": "Bilateral flank pain radiating to the groin", "C": "Epigastric pain", "D": "Shoulder tip pain"}, "r": "A", "e": {"correcta": "Chronic prostatitis presents with dysuria along with pelvic pain and low back pain, reflecting ongoing, often relapsing, inflammation of the prostate that can be bacterial or (more commonly) non-bacterial (chronic pelvic pain syndrome).", "incorrectas": {"B": "Flank pain radiating to the groin is more typical of a ureteral process such as nephrolithiasis, not the pelvic/low back pain pattern of chronic prostatitis.", "C": "Epigastric pain suggests an upper gastrointestinal or pancreaticobiliary process and is not part of the classic chronic prostatitis symptom complex.", "D": "Shoulder tip pain is referred pain classically from diaphragmatic irritation (e.g., subphrenic abscess, splenic injury), unrelated to prostatic pathology."}}}, {"id": "anking-reproductive-system-pathology-2360", "fuente": "anking", "tema": 8, "anki": "1463345940337", "q": "Which condition is defined as the age-related hyperplasia of prostatic stroma and glands, related to DHT and typically occurring in men over 45?", "o": {"A": "Prostatic intraepithelial neoplasia", "B": "Benign prostatic hyperplasia (BPH)", "C": "Acute prostatitis", "D": "Prostatic adenocarcinoma"}, "r": "B", "e": {"correcta": "Benign prostatic hyperplasia is the age-related, DHT-driven hyperplasia of prostatic stromal and glandular tissue, typically occurring in men over 45. It classically produces 'nodular' hyperplasia concentrated in the transitional (periurethral) zone of the prostate, distinct from the peripheral zone favored by cancer.", "incorrectas": {"A": "Prostatic intraepithelial neoplasia is a precursor lesion to adenocarcinoma involving dysplastic epithelial changes within glands, not a hyperplastic stromal/glandular process like BPH.", "C": "Acute prostatitis is an infectious/inflammatory process presenting with fever and a tender, boggy prostate, not a chronic hyperplastic process driven by DHT.", "D": "Prostatic adenocarcinoma is a malignant proliferation typically arising in the posterior peripheral zone, distinct in both location and biology from the benign hyperplastic process of BPH."}}}, {"id": "anking-reproductive-system-pathology-2361", "fuente": "anking", "tema": 8, "anki": "1463345947474", "q": "Does benign prostatic hyperplasia increase a patient's risk of developing prostate cancer?", "o": {"A": "Yes, BPH is a direct precursor lesion to adenocarcinoma", "B": "No, BPH does not increase cancer risk", "C": "Only if BPH occurs in the peripheral zone", "D": "Yes, but only in patients with markedly elevated PSA"}, "r": "B", "e": {"correcta": "BPH does not increase the risk of prostate cancer. The two conditions arise in different zones of the prostate (BPH in the transitional/periurethral zone, cancer typically in the posterior peripheral zone) and are considered biologically distinct processes, even though both become more common with age and both can raise PSA.", "incorrectas": {"A": "BPH is a benign hyperplastic process and is not considered a premalignant precursor lesion to prostatic adenocarcinoma; the two conditions have distinct pathogenesis and typical locations within the gland.", "C": "BPH itself occurs in the transitional zone, not the peripheral zone, and its location does not confer increased cancer risk regardless of which zone is affected.", "D": "PSA elevation in BPH reflects increased glandular tissue mass, not malignant transformation, so an elevated PSA from BPH alone does not equate to increased cancer risk."}}}, {"id": "anking-reproductive-system-pathology-2362", "fuente": "anking", "tema": 8, "anki": "1463345952079", "q": "Benign prostatic hyperplasia most commonly develops in which zone of the prostate, resulting in urethral compression into a 'slit' shape?", "o": {"A": "Posterior peripheral zone", "B": "Periurethral (transitional) zone", "C": "Anterior fibromuscular stroma", "D": "Ejaculatory duct zone"}, "r": "B", "e": {"correcta": "BPH classically arises in the periurethral (transitional) zone, comprising the middle and lateral lobes of the prostate that surround the urethra. As the glandular and stromal tissue proliferates here, it compresses the urethra into a slit-like lumen, producing the classic obstructive urinary symptoms.", "incorrectas": {"A": "The posterior peripheral zone is the classic site of prostatic adenocarcinoma, not BPH, and its location away from the urethra explains why cancer is often clinically silent until advanced.", "C": "The anterior fibromuscular stroma is a non-glandular zone that contributes structural support to the prostate but is not the classic site of BPH nodule formation.", "D": "The ejaculatory ducts pass through the prostate but are not the zone where BPH hyperplasia is centered; the transitional zone surrounding the urethra is the classic site."}}}, {"id": "anking-reproductive-system-pathology-2363", "fuente": "anking", "tema": 8, "anki": "1463345960314", "q": "A man with benign prostatic hyperplasia reports difficulty both starting and stopping which activity?", "o": {"A": "Defecation", "B": "Urination", "C": "Ejaculation", "D": "Erection"}, "r": "B", "e": {"correcta": "BPH causes bladder outlet obstruction from urethral compression by hyperplastic periurethral prostatic tissue, leading to difficulty initiating and terminating urination, along with straining and a weak urinary stream.", "incorrectas": {"A": "Difficulty with defecation would suggest a rectal or colonic process rather than urethral compression from prostatic enlargement, which specifically affects urinary flow.", "C": "While BPH can occasionally be associated with ejaculatory changes, the classic hallmark symptom taught for BPH is obstructive urinary difficulty, not problems specifically with starting/stopping ejaculation.", "D": "Erectile function is primarily governed by vascular and neural mechanisms; BPH's primary mechanical effect is on the urethral lumen affecting urinary flow, not erection initiation/termination."}}}, {"id": "anking-reproductive-system-pathology-2364", "fuente": "anking", "tema": 8, "anki": "1463345963883", "q": "As benign prostatic hyperplasia progresses and obstructs outflow, patients may develop overflow incontinence due to impaired emptying of which organ?", "o": {"A": "Ureter", "B": "Bladder", "C": "Seminal vesicle", "D": "Kidney"}, "r": "B", "e": {"correcta": "Urethral obstruction from BPH impairs bladder emptying, leading to residual urine, bladder distension, and eventually overflow incontinence with dribbling, as the bladder cannot generate sufficient pressure to fully void against the obstruction.", "incorrectas": {"A": "The ureters carry urine from the kidneys to the bladder; while chronic obstruction can secondarily cause ureteral dilation (hydroureter), the impaired emptying described directly refers to the bladder, not the ureter itself.", "C": "The seminal vesicles contribute fluid to semen and are not involved in urinary storage or emptying, so they are not the organ affected by BPH-related outlet obstruction.", "D": "The kidneys can be secondarily affected by backup pressure (hydronephrosis) from longstanding obstruction, but the immediate structure with impaired emptying due to BPH is the bladder."}}}, {"id": "anking-reproductive-system-pathology-2365", "fuente": "anking", "tema": 8, "anki": "1463345966711", "q": "Increased urinary frequency occurring specifically throughout the night in a patient with benign prostatic hyperplasia is termed what?", "o": {"A": "Polyuria", "B": "Nocturia", "C": "Enuresis", "D": "Pollakiuria"}, "r": "B", "e": {"correcta": "Nocturia refers to increased urination occurring at night, a common irritative/obstructive symptom of BPH resulting from incomplete bladder emptying during the day, which leads to more frequent voiding attempts, including overnight.", "incorrectas": {"A": "Polyuria refers to an overall increased volume of urine production (often from causes like diabetes or diuretic use), not specifically increased frequency of nighttime voiding as seen with BPH.", "C": "Enuresis refers to involuntary urination, classically nocturnal bedwetting in children, which is a different clinical entity from the frequent nighttime voiding of BPH-related nocturia.", "D": "Pollakiuria describes frequent daytime urination in small amounts, sometimes seen in children, rather than the specific nighttime frequency pattern captured by the term nocturia."}}}, {"id": "anking-reproductive-system-pathology-2366", "fuente": "anking", "tema": 8, "anki": "1463345970431", "q": "Chronic bladder outlet obstruction from BPH leads to hypertrophy of the bladder wall smooth muscle, increasing the risk for formation of which structural abnormality?", "o": {"A": "Bladder diverticulum", "B": "Vesicoureteral reflux only", "C": "Urethral stricture", "D": "Bladder rupture"}, "r": "A", "e": {"correcta": "Chronic straining against an obstructed outlet causes detrusor smooth muscle hypertrophy and trabeculation of the bladder wall. Weak points between hypertrophied muscle bundles can herniate outward, forming bladder diverticula, which further impair complete bladder emptying and predispose to infection and stone formation.", "incorrectas": {"B": "Vesicoureteral reflux is more classically associated with pediatric congenital abnormalities of the ureterovesical junction rather than being the primary structural consequence of BPH-associated bladder wall hypertrophy, though chronic outlet obstruction can secondarily affect the upper tracts.", "C": "A urethral stricture is a separate condition of urethral narrowing from scarring (e.g., after trauma or infection), not a direct consequence of bladder wall smooth muscle hypertrophy from BPH.", "D": "Bladder rupture is a rare complication typically from trauma or severe overdistension, not a typical or expected consequence of chronic BPH-related bladder wall hypertrophy."}}}, {"id": "anking-reproductive-system-pathology-2367", "fuente": "anking", "tema": 8, "anki": "1463345973963", "q": "Benign prostatic hyperplasia may present with which finding on urinalysis, reflecting congestion of the enlarged prostatic vasculature?", "o": {"A": "Microscopic hematuria", "B": "Heavy proteinuria", "C": "Glucosuria", "D": "Pyuria with white cell casts"}, "r": "A", "e": {"correcta": "BPH can present with microscopic hematuria, thought to result from engorgement and rupture of small vessels within the hyperplastic, vascular prostatic tissue as it compresses and irritates the urethra.", "incorrectas": {"B": "Heavy proteinuria points toward a glomerular process (e.g., nephrotic syndrome) rather than a prostatic mechanical/vascular issue like BPH.", "C": "Glucosuria suggests hyperglycemia (e.g., diabetes mellitus) or a renal tubular defect, unrelated to prostatic enlargement.", "D": "Pyuria with white cell casts suggests infection or inflammation involving the renal tubules (e.g., pyelonephritis), not the microscopic hematuria typically described with BPH."}}}, {"id": "anking-reproductive-system-pathology-2368", "fuente": "anking", "tema": 8, "anki": "1463345977335", "q": "In a patient with benign prostatic hyperplasia, the serum PSA level is typically affected in which way?", "o": {"A": "Markedly elevated, often above 20 ng/mL", "B": "Slightly elevated due to increased glandular tissue", "C": "Always within the normal range", "D": "Decreased below normal due to glandular atrophy"}, "r": "B", "e": {"correcta": "PSA is produced by prostatic epithelial cells, so an increase in the amount of glandular tissue, as occurs in BPH, causes a mild elevation in PSA (commonly in the range of about 4-10 ng/mL), even in the absence of malignancy. This overlap with the range seen in early cancer is why PSA alone cannot distinguish BPH from cancer.", "incorrectas": {"A": "Markedly elevated PSA (often much higher than the 4-10 range) is more suggestive of malignancy, especially with metastatic disease, rather than the modest elevation typical of BPH alone.", "C": "PSA is not necessarily normal in BPH; the increased volume of benign glandular tissue commonly produces at least a mild elevation above the normal 0-4 ng/mL range.", "D": "BPH involves hyperplasia (increase), not atrophy, of glandular tissue, so PSA would be expected to rise modestly rather than fall."}}}, {"id": "anking-renal-pathology-2369", "fuente": "anking", "tema": 58, "anki": "1463345985953", "q": "A patient with longstanding untreated benign prostatic hyperplasia develops bilateral flank discomfort and progressive renal impairment due to backup of urine into the kidneys. What is this complication called?", "o": {"A": "Renal papillary necrosis", "B": "Hydronephrosis", "C": "Minimal change disease", "D": "Acute tubular necrosis from ischemia"}, "r": "B", "e": {"correcta": "Chronic bladder outlet obstruction from BPH can cause urine to back up through the ureters into the renal pelvis and calyces, producing hydronephrosis. Persistent reflux and pressure can cause parenchymal atrophy, scarring, and eventual chronic kidney disease if the obstruction is not relieved.", "incorrectas": {"A": "Renal papillary necrosis is classically associated with conditions like analgesic nephropathy, sickle cell disease, diabetes, or severe pyelonephritis, not directly with the mechanical back-pressure from BPH.", "C": "Minimal change disease is a glomerular podocyte disorder causing nephrotic syndrome in children, unrelated to obstructive uropathy from prostatic enlargement.", "D": "Acute tubular necrosis from ischemia is typically due to prolonged hypoperfusion (e.g., shock) or nephrotoxins, not the chronic pressure-mediated parenchymal damage from obstructive hydronephrosis in BPH."}}}, {"id": "anking-reproductive-system-pathology-2370", "fuente": "anking", "tema": 8, "anki": "1463346010918", "q": "Which term describes the malignant proliferation of prostatic glands?", "o": {"A": "Benign prostatic hyperplasia", "B": "Prostatic intraepithelial neoplasia only", "C": "Prostate adenocarcinoma", "D": "Prostatitis"}, "r": "C", "e": {"correcta": "Prostate adenocarcinoma is defined as the malignant proliferation of prostatic glandular epithelium. It is the most common cancer diagnosed in men and typically arises in the posterior peripheral zone, in contrast to the benign hyperplastic process of BPH, which occurs in the transitional zone.", "incorrectas": {"A": "BPH is a benign, non-neoplastic hyperplastic process of prostatic stroma and glands, distinct from the malignant transformation that defines adenocarcinoma.", "B": "Prostatic intraepithelial neoplasia is a precursor lesion showing dysplastic but non-invasive glandular changes; it precedes but is not itself the invasive malignant proliferation that defines adenocarcinoma.", "D": "Prostatitis is inflammation of the prostate, typically infectious or idiopathic in origin, and is not a neoplastic process at all."}}}, {"id": "anking-reproductive-system-pathology-2371", "fuente": "anking", "tema": 8, "anki": "1463346015128", "q": "Which cancer is the second most common cause of cancer death in men (though it is the most common cancer by incidence)?", "o": {"A": "Lung cancer", "B": "Colorectal cancer", "C": "Prostate cancer", "D": "Bladder cancer"}, "r": "C", "e": {"correcta": "Prostate cancer is the most commonly diagnosed cancer in men and ranks as the second leading cause of cancer death in men, after lung cancer, reflecting its high incidence combined with a generally slower, though sometimes lethal, natural history.", "incorrectas": {"A": "Lung cancer is the leading cause of cancer death in men overall, surpassing prostate cancer in mortality despite prostate cancer having a higher incidence.", "B": "Colorectal cancer is a common cause of cancer death in both men and women but ranks below prostate cancer in male cancer mortality statistics.", "D": "Bladder cancer, while significant, has a much lower incidence and mortality burden in men compared to prostate cancer and is not considered the second leading cause of cancer death."}}}, {"id": "anking-reproductive-system-pathology-2372", "fuente": "anking", "tema": 8, "anki": "1463346018491", "q": "Which ethnicity is associated with the highest risk of developing prostatic adenocarcinoma?", "o": {"A": "Asian", "B": "Caucasian", "C": "African American", "D": "Hispanic"}, "r": "C", "e": {"correcta": "African American men have the highest incidence and mortality from prostate adenocarcinoma, followed by Caucasians, with Asian populations having the lowest risk. This ordering (African American > Caucasian > Asian) reflects both genetic and possibly environmental/dietary factors and is a well-established epidemiologic pattern tested on Step 1.", "incorrectas": {"A": "Asian populations have the lowest risk among the commonly compared groups, the opposite end of the spectrum from African Americans, who have the highest risk.", "B": "Caucasian men have an intermediate risk, higher than Asian men but lower than African American men, so this is not the highest-risk group.", "D": "Hispanic ethnicity is not the group classically cited as having the highest risk in this well-known ordering used for testing purposes."}}}, {"id": "anking-nutrition-2373", "fuente": "anking", "tema": 46, "anki": "1463346021441", "q": "A diet high in which type of nutrient is associated with increased risk of prostatic adenocarcinoma?", "o": {"A": "Saturated fat", "B": "Dietary fiber", "C": "Complex carbohydrates", "D": "Plant-based protein"}, "r": "A", "e": {"correcta": "A diet high in saturated fat has been associated with increased risk of developing prostatic adenocarcinoma, one of several modifiable risk factors alongside non-modifiable factors like age, race, and family history.", "incorrectas": {"B": "Dietary fiber is generally associated with protective effects against several cancers (e.g., colorectal cancer) and is not the nutrient linked to increased prostate cancer risk.", "C": "Complex carbohydrates are not the dietary component specifically implicated in increased prostate cancer risk; saturated fat is the classically cited culprit.", "D": "Plant-based protein sources are generally not associated with increased prostate cancer risk and may even be considered relatively protective compared to diets high in saturated animal fat."}}}, {"id": "anking-reproductive-system-anatomy-2374", "fuente": "anking", "tema": 34, "anki": "1463346024760", "q": "Prostatic adenocarcinoma most commonly arises in which region of the prostate, explaining why it is often clinically silent until late in the disease course?", "o": {"A": "Periurethral transitional zone", "B": "Posterior periphery", "C": "Central zone near the ejaculatory ducts", "D": "Anterior fibromuscular stroma"}, "r": "B", "e": {"correcta": "Prostatic adenocarcinoma classically arises in the posterior peripheral zone of the gland, which is far from the urethra. Because this location does not compress the urethra early on, tumors often grow silently without causing obstructive urinary symptoms until they are advanced, in contrast to BPH which arises centrally around the urethra and causes symptoms early.", "incorrectas": {"A": "The periurethral transitional zone is the classic site of BPH, not adenocarcinoma; its proximity to the urethra is why BPH causes early obstructive symptoms, unlike peripheral zone cancer.", "C": "The central zone surrounds the ejaculatory ducts and is a less common site for adenocarcinoma compared to the peripheral zone.", "D": "The anterior fibromuscular stroma lacks significant glandular tissue and is not a typical site of origin for adenocarcinoma, which arises from glandular epithelium."}}}, {"id": "anking-epidemiology-biostatistics-2375", "fuente": "anking", "tema": 19, "anki": "1463346050168", "q": "Screening for prostatic adenocarcinoma has traditionally begun around age 50 using which two modalities?", "o": {"A": "Transrectal ultrasound and biopsy", "B": "Digital rectal exam and PSA", "C": "CT abdomen/pelvis and MRI", "D": "Urinalysis and cystoscopy"}, "r": "B", "e": {"correcta": "Traditional prostate cancer screening involves a combination of digital rectal exam (to detect palpable nodules/asymmetry in the posterior gland) and serum PSA level (a biomarker that can be elevated in cancer, though also in BPH and prostatitis), typically starting around age 50 in average-risk men.", "incorrectas": {"A": "Transrectal ultrasound and biopsy are used for further workup and definitive diagnosis when screening tests are abnormal, not as the initial screening modalities themselves.", "C": "CT and MRI are used for staging or further characterization of known or suspected cancer, not as first-line population screening tools for prostate cancer.", "D": "Urinalysis and cystoscopy are tools more relevant to evaluating hematuria or bladder pathology, not the standard screening approach for prostatic adenocarcinoma."}}}, {"id": "anking-epidemiology-biostatistics-2376", "fuente": "anking", "tema": 19, "anki": "1463346053358", "q": "A PSA level above what threshold (ng/mL) is considered worrisome for prostatic adenocarcinoma regardless of the patient's age?", "o": {"A": "4", "B": "10", "C": "20", "D": "50"}, "r": "B", "e": {"correcta": "A PSA greater than 10 ng/mL is considered worrisome for prostatic adenocarcinoma at any age, since this level is well above the range typically explained by BPH alone (roughly 4-10 ng/mL) and warrants further workup such as biopsy.", "incorrectas": {"A": "A PSA above 4 ng/mL is simply outside the traditional 'normal' range (0-4) but does not by itself strongly suggest cancer, since BPH commonly raises PSA into the 4-10 range.", "C": "A cutoff of 20 ng/mL is higher than the classically taught concerning threshold of 10 ng/mL; the teaching point is that levels above 10 are concerning at any age.", "D": "A threshold of 50 ng/mL is far above the level used to raise suspicion for cancer; PSA above 10 ng/mL is already considered worrisome and prompts further evaluation."}}}, {"id": "anking-renal-physiology-2377", "fuente": "anking", "tema": 12, "anki": "1463346056481", "q": "A decreased percentage of which form of PSA is suggestive of underlying prostatic adenocarcinoma?", "o": {"A": "Total PSA", "B": "Free PSA", "C": "Bound PSA", "D": "Complexed PSA only"}, "r": "B", "e": {"correcta": "A decreased percentage of free PSA (with a corresponding increase in protein-bound PSA) is suggestive of prostatic adenocarcinoma, since cancer cells tend to produce more PSA that circulates bound to plasma proteins rather than in the free form. This ratio helps refine risk when total PSA is in an equivocal range.", "incorrectas": {"A": "Total PSA alone (the sum of free and bound forms) is a less specific marker; it does not distinguish cancer from BPH as well as looking at the free-to-total PSA ratio does.", "C": "It is an increase, not simply the presence, of bound PSA relative to free PSA that raises suspicion for cancer; bound PSA rising is the flip side of free PSA falling as a percentage.", "D": "Complexed (bound) PSA is expected to increase as a proportion in cancer, so an isolated decrease in bound PSA would not be the concerning pattern; the concerning finding is a decreased percentage of free PSA."}}}, {"id": "anking-reproductive-system-pathology-2378", "fuente": "anking", "tema": 8, "anki": "1463346061489", "q": "Given an elevated PSA level, what test is required to definitively confirm the diagnosis of prostatic adenocarcinoma?", "o": {"A": "Repeat PSA in 6 months", "B": "Prostatic biopsy", "C": "Serum alkaline phosphatase", "D": "Urine cytology"}, "r": "B", "e": {"correcta": "PSA elevation alone cannot confirm cancer because it can also be elevated in BPH, prostatitis, or after prostatic manipulation. A prostatic biopsy, providing histologic tissue diagnosis, is required to definitively confirm prostatic adenocarcinoma.", "incorrectas": {"A": "Repeating PSA can help assess trends (e.g., PSA velocity) but cannot itself provide a tissue diagnosis; biopsy is still needed to confirm cancer.", "C": "Serum alkaline phosphatase can be elevated with bony metastases from prostate cancer, but it is not a diagnostic test for the primary tumor itself.", "D": "Urine cytology is used to evaluate for urothelial (bladder) malignancy, not for diagnosing prostatic adenocarcinoma, which requires direct tissue biopsy."}}}, {"id": "anking-reproductive-system-pathology-2379", "fuente": "anking", "tema": 8, "anki": "1463346064538", "q": "Prostatic adenocarcinoma is histologically characterized by small glands infiltrating normal tissue, with nuclei containing which feature?", "o": {"A": "Ground-glass nuclei", "B": "Dark nucleoli", "C": "Coffee-bean grooves", "D": "Orphan Annie eye nuclei"}, "r": "B", "e": {"correcta": "Prostatic adenocarcinoma classically shows small, crowded malignant glands infiltrating between normal benign glands, with nuclei containing prominent dark (hyperchromatic) nucleoli, a key histologic clue used to distinguish malignant glands from benign glandular tissue.", "incorrectas": {"A": "Ground-glass nuclei are the classic finding in papillary thyroid carcinoma, not prostatic adenocarcinoma.", "C": "Coffee-bean grooved nuclei are also characteristic of papillary thyroid carcinoma, unrelated to the prostatic gland histology described here.", "D": "'Orphan Annie eye' nuclei (with clearing) are another classic descriptor for papillary thyroid carcinoma, not a feature used to describe prostatic adenocarcinoma."}}}, {"id": "anking-reproductive-system-pathology-2380", "fuente": "anking", "tema": 8, "anki": "1463346071188", "q": "Which grading system is used to assess the histologic aggressiveness of prostatic adenocarcinoma?", "o": {"A": "Fuhrman grading system", "B": "Gleason grading system", "C": "Nottingham grading system", "D": "Bloom-Richardson system"}, "r": "B", "e": {"correcta": "The Gleason grading system is used specifically for prostatic adenocarcinoma. Pathologists typically score the two most predominant architectural patterns on a scale of 1-5 each and sum them for a total Gleason score of 2-10, with higher scores indicating a worse prognosis.", "incorrectas": {"A": "The Fuhrman grading system is used for renal cell carcinoma, based on nuclear features, and is unrelated to prostatic adenocarcinoma grading.", "C": "The Nottingham grading system (a modification of Bloom-Richardson) is used for breast cancer, not prostate cancer.", "D": "The Bloom-Richardson system is the classic grading system for breast carcinoma based on tubule formation, nuclear pleomorphism, and mitotic rate, not for prostate cancer."}}}, {"id": "anking-reproductive-system-pathology-2381", "fuente": "anking", "tema": 8, "anki": "1463346078318", "q": "The Gleason grading system for prostatic adenocarcinoma bases its score primarily on which histologic feature?", "o": {"A": "Nuclear atypia", "B": "Architecture (glandular pattern)", "C": "Mitotic count", "D": "Degree of necrosis"}, "r": "B", "e": {"correcta": "Unlike many other tumor grading systems, the Gleason system for prostatic adenocarcinoma is based on glandular architecture (how well-formed and organized the glands appear) rather than nuclear cytologic features such as atypia. Well-formed glands score low (favorable), while poorly formed or infiltrative sheets score high (aggressive).", "incorrectas": {"A": "Nuclear atypia is the basis for grading in many other cancers, but the Gleason system deliberately emphasizes architectural pattern over nuclear detail, which is one of its distinguishing features.", "C": "Mitotic count is a component of grading systems for other tumors (e.g., breast, sarcomas), but it is not the basis of the Gleason system.", "D": "Necrosis can be a feature noted in various tumor grading contexts (e.g., some renal or CNS tumor grading), but it is not the criterion underlying the Gleason architectural grading system."}}}, {"id": "anking-reproductive-system-pathology-2382", "fuente": "anking", "tema": 8, "anki": "1463346081917", "q": "In prostatic adenocarcinoma, a higher Gleason score reflects greater architectural loss of glandular differentiation. How does the Gleason score correlate with prognosis?", "o": {"A": "A higher score predicts a worse prognosis", "B": "A higher score predicts a better prognosis", "C": "The score does not correlate with prognosis", "D": "A higher score only matters if PSA is also elevated"}, "r": "A", "e": {"correcta": "The Gleason grading system evaluates the degree of glandular differentiation in prostatic adenocarcinoma based on architectural pattern (not nuclear features, unlike most other grading systems). Poorly differentiated, more disorganized glandular patterns receive higher scores, and these tumors behave more aggressively, invade more readily, and carry a worse prognosis than well-differentiated, lower-scoring tumors.", "incorrectas": {"B": "This inverts the actual relationship — a higher Gleason score reflects a less-differentiated, more aggressive tumor and is therefore associated with worse, not better, outcomes.", "C": "The Gleason score is specifically designed to be prognostic; it is one of the most important predictors of biological behavior and outcome in prostate cancer, so it does correlate with prognosis.", "D": "While PSA is a useful marker for monitoring prostate cancer, the prognostic value of the Gleason score is independent of PSA level; the score is based purely on histologic architecture."}}}, {"id": "anking-reproductive-system-pathology-2383", "fuente": "anking", "tema": 8, "anki": "1463346085076", "q": "Which two serum markers are classically elevated in men with prostatic adenocarcinoma?", "o": {"A": "CA-125 and CA 19-9", "B": "AFP and beta-hCG", "C": "PSA and PAP (prostatic acid phosphatase)", "D": "CEA and alkaline phosphatase"}, "r": "C", "e": {"correcta": "PSA (prostate-specific antigen) and PAP (prostatic acid phosphatase) are both produced by prostatic epithelium and are classically elevated in prostatic adenocarcinoma, reflecting increased glandular mass and disrupted tissue architecture that allows these proteins to leak into serum. PSA is used for screening and monitoring, though it lacks specificity since BPH and prostatitis can also raise it.", "incorrectas": {"A": "CA-125 is associated with ovarian carcinoma and CA 19-9 with pancreatic carcinoma; neither is used to evaluate prostate cancer.", "B": "AFP and beta-hCG are classic germ cell tumor markers (e.g., yolk sac tumor and choriocarcinoma, respectively), not markers used for prostatic adenocarcinoma.", "D": "CEA is a nonspecific marker most associated with colorectal cancer, and alkaline phosphatase reflects bone or liver involvement (such as bony metastases) rather than being a primary prostate tumor marker."}}}, {"id": "anking-reproductive-system-pathology-2384", "fuente": "anking", "tema": 8, "anki": "1463346088119", "q": "A patient with known prostatic adenocarcinoma develops bone pain from skeletal metastases. Which serum marker is characteristically elevated due to this bony spread?", "o": {"A": "Lactate dehydrogenase (LDH)", "B": "Alkaline phosphatase (ALP)", "C": "Amylase", "D": "Troponin"}, "r": "B", "e": {"correcta": "Prostatic adenocarcinoma classically metastasizes to bone, particularly the axial skeleton, producing osteoblastic (sclerotic) lesions. Osteoblasts respond to metastatic deposits by increasing bone turnover, which releases alkaline phosphatase, making serum ALP a useful marker of bony metastatic burden.", "incorrectas": {"A": "LDH is a nonspecific marker of cellular turnover and tissue damage seen in many malignancies and hemolysis, but it is not the classic marker linked to prostate cancer bone metastases.", "C": "Amylase is produced by the pancreas and salivary glands and is used to evaluate pancreatitis, not bone metastases from prostate cancer.", "D": "Troponin is a marker of myocardial injury and has no role in evaluating metastatic prostate cancer."}}}, {"id": "anking-reproductive-system-pathology-2385", "fuente": "anking", "tema": 8, "anki": "1463346099788", "q": "A patient is diagnosed with prostatic adenocarcinoma confined to the prostate gland without evidence of metastasis. Which treatment is appropriate for this localized disease?", "o": {"A": "Radical prostatectomy", "B": "Androgen deprivation therapy alone", "C": "Palliative chemotherapy", "D": "Bisphosphonate therapy"}, "r": "A", "e": {"correcta": "When prostatic adenocarcinoma is localized to the gland without metastatic spread, curative-intent surgery (radical prostatectomy) is an appropriate treatment option, aiming to remove the entire tumor-bearing organ before dissemination occurs.", "incorrectas": {"B": "Androgen deprivation therapy is primarily used for advanced or metastatic disease to slow androgen-dependent tumor growth, not as the primary curative approach for localized, resectable disease.", "C": "Palliative chemotherapy is reserved for advanced, metastatic, or castration-resistant disease where cure is not the goal, which does not apply to localized disease amenable to surgery.", "D": "Bisphosphonates are used to manage bony metastases and reduce skeletal complications in advanced disease, not to treat localized, non-metastatic prostate cancer."}}}, {"id": "anking-reproductive-system-anatomy-2386", "fuente": "anking", "tema": 34, "anki": "1463356243674", "q": "Ectopic breast tissue and supernumerary nipples can develop anywhere along which embryologic structure?", "o": {"A": "Urogenital ridge", "B": "Milk line", "C": "Wolffian duct", "D": "Paramesonephric duct"}, "r": "B", "e": {"correcta": "The milk line (mammary ridge) is an ectodermal thickening that extends from the axilla to the vulva during development; normally only the pectoral portion persists to form the breast, but ectopic breast tissue or supernumerary (accessory) nipples can appear anywhere along this line if remnants persist.", "incorrectas": {"A": "The urogenital ridge gives rise to the gonads and much of the urinary and reproductive tract, but it is not the structure along which breast tissue is distributed.", "C": "The Wolffian (mesonephric) duct gives rise to male internal genital structures (epididymis, vas deferens, seminal vesicles) and has no relationship to mammary tissue distribution.", "D": "The paramesonephric (Müllerian) duct gives rise to the female internal genital tract (fallopian tubes, uterus, upper vagina), not to breast tissue location."}}}, {"id": "anking-reproductive-system-anatomy-2387", "fuente": "anking", "tema": 34, "anki": "1463356248081", "q": "Which structure is considered the functional unit of the breast, where lobules produce milk that drains via ducts to the nipple?", "o": {"A": "Terminal duct-lobular unit (TDLU)", "B": "Cooper ligament", "C": "Areolar gland complex", "D": "Lactiferous sinus"}, "r": "A", "e": {"correcta": "The terminal duct-lobular unit (TDLU) consists of a lobule (the milk-producing acini) and its associated terminal duct, making it the functional secretory unit of the breast. Most breast pathology, both benign (fibrocystic change, fibroadenoma) and malignant, arises from this unit.", "incorrectas": {"B": "Cooper ligaments are fibrous suspensory ligaments that provide structural support to the breast; they are connective tissue structures, not the functional secretory unit.", "C": "There is no distinct 'areolar gland complex' serving as the breast's functional unit; the areola contains Montgomery glands, which are sebaceous, not the site of milk production.", "D": "The lactiferous sinus is a dilated portion of the duct near the nipple that stores milk before ejection, but it is a conduit/storage structure, not the site of milk production itself."}}}, {"id": "anking-reproductive-system-anatomy-2388", "fuente": "anking", "tema": 34, "anki": "1463356256794", "q": "The lobules and ducts of the breast are normally lined by how many layers of epithelium?", "o": {"A": "One layer", "B": "Two layers", "C": "Three layers", "D": "Four layers"}, "r": "B", "e": {"correcta": "Breast lobules and ducts are normally lined by two layers of epithelium: an inner luminal (epithelial) layer and an outer myoepithelial layer. Recognizing this two-layer architecture is important pathologically, since loss of the myoepithelial layer is a hallmark of invasive carcinoma, whereas its preservation supports an in situ or benign process.", "incorrectas": {"A": "A single epithelial layer would not account for the myoepithelial cells needed for milk ejection; the breast duct/lobule system is bilayered, not monolayered.", "C": "Three layers is not the normal histologic arrangement of breast ductal-lobular epithelium; only two distinct cell layers (luminal and myoepithelial) are present.", "D": "Four layers overstates the normal histology; the simplicity of the two-layer system (luminal plus myoepithelial) is actually diagnostically important, as extra layers or loss of the normal bilayer pattern raises concern for pathology."}}}, {"id": "anking-reproductive-system-anatomy-2389", "fuente": "anking", "tema": 34, "anki": "1463356260645", "q": "The inner cell layer lining the lobules and ducts of the breast is composed of which cell type?", "o": {"A": "Myoepithelial cells", "B": "Luminal (epithelial) cells", "C": "Basal squamous cells", "D": "Fibroblasts"}, "r": "B", "e": {"correcta": "The inner layer lining breast lobules and ducts is the luminal (epithelial) cell layer, which faces the duct lumen and is responsible for producing milk within the lobules. This layer is the origin of most ductal and lobular carcinomas of the breast.", "incorrectas": {"A": "Myoepithelial cells form the outer layer, not the inner layer; they lie between the luminal epithelium and the basement membrane and function in milk ejection via contraction.", "C": "Basal squamous cells are not a normal component of breast ductal-lobular histology; the breast epithelium is glandular (cuboidal/columnar), not squamous.", "D": "Fibroblasts are stromal cells found in the surrounding connective tissue, not part of the epithelial bilayer lining the ducts and lobules themselves."}}}, {"id": "anking-reproductive-system-anatomy-2390", "fuente": "anking", "tema": 34, "anki": "1463356264902", "q": "The luminal (epithelial) cell layer of the breast lobule is primarily responsible for which function?", "o": {"A": "Milk ejection toward the nipple", "B": "Milk production", "C": "Structural support of the duct", "D": "Immune surveillance within the lobule"}, "r": "B", "e": {"correcta": "The luminal (epithelial) cell layer lines the inner aspect of the lobules and is the site of milk production/secretion. These secretory cells respond to hormonal cues (prolactin, oxytocin priming, estrogen/progesterone) to synthesize milk components.", "incorrectas": {"A": "Milk ejection (propulsion toward the nipple) is the job of the outer myoepithelial layer, which contracts in response to oxytocin, not the luminal cells.", "C": "Structural support of the duct comes more from the surrounding stroma and basement membrane, and to some extent the myoepithelial layer, not the secretory luminal cells.", "D": "Immune surveillance is not a designated function of luminal epithelial cells; immune cells (such as macrophages and lymphocytes) that patrol breast tissue are distinct from the epithelial lining cells."}}}, {"id": "anking-reproductive-system-anatomy-2391", "fuente": "anking", "tema": 34, "anki": "1463356268349", "q": "The outer cell layer surrounding the lobules and ducts of the breast, lying beneath the luminal cells, is called which cell type?", "o": {"A": "Luminal (epithelial) cells", "B": "Myoepithelial cells", "C": "Adipocytes", "D": "Endothelial cells"}, "r": "B", "e": {"correcta": "The outer cell layer of the breast ductal-lobular unit is the myoepithelial cell layer, which contains contractile elements (similar to smooth muscle) that allow it to squeeze the lobules and ducts, propelling milk toward the nipple during let-down.", "incorrectas": {"A": "Luminal (epithelial) cells form the inner layer responsible for milk secretion, the opposite position and function from the myoepithelial cells described here.", "C": "Adipocytes make up the fatty stroma surrounding the glandular breast tissue, not the cellular lining of the ducts and lobules themselves.", "D": "Endothelial cells line blood vessels within the breast, not the ductal-lobular epithelium; they are unrelated to the two-layer glandular lining."}}}, {"id": "anking-reproductive-system-anatomy-2392", "fuente": "anking", "tema": 34, "anki": "1463356271940", "q": "The myoepithelial cell layer of breast tissue contracts to accomplish which function?", "o": {"A": "Producing milk components", "B": "Filtering blood-derived nutrients into milk", "C": "Propelling milk toward the nipple", "D": "Regenerating luminal epithelium after lactation"}, "r": "C", "e": {"correcta": "Myoepithelial cells have contractile properties (they express actin, similar to smooth muscle) and, in response to oxytocin released during suckling, contract to propel milk from the lobules through the ducts toward the nipple — the milk let-down reflex.", "incorrectas": {"A": "Milk production is carried out by the luminal epithelial cells, not the myoepithelial cells, which instead provide the contractile force for milk expulsion.", "B": "Filtering nutrients into milk is a secretory function of luminal cells' cellular machinery, not a role of the contractile myoepithelial layer.", "D": "While myoepithelial cells and the basal layer contribute to tissue architecture, their well-established classic function tested on exams is contraction for milk ejection, not epithelial regeneration."}}}, {"id": "anking-reproductive-system-anatomy-2393", "fuente": "anking", "tema": 34, "anki": "1463356275732", "q": "During pregnancy, rising estrogen and progesterone drive what change in breast lobules?", "o": {"A": "Atrophy", "B": "Hyperplasia", "C": "Dysplasia", "D": "Metaplasia"}, "r": "B", "e": {"correcta": "During pregnancy, increased estrogen and progesterone stimulate proliferation (hyperplasia) of breast lobules, increasing the number of glandular acini in preparation for lactation. This is a normal, reversible, hormonally-driven adaptive change.", "incorrectas": {"A": "Atrophy (shrinkage of tissue) is the opposite change, seen after menopause when estrogen and progesterone levels fall, not during the hormone-rich state of pregnancy.", "C": "Dysplasia refers to disordered, potentially pre-malignant cellular growth, which is not the normal physiologic response of breast tissue to pregnancy hormones.", "D": "Metaplasia is the replacement of one differentiated cell type with another (e.g., apocrine metaplasia in fibrocystic change), which is a distinct process from the numerical increase in glandular tissue seen in pregnancy."}}}, {"id": "anking-reproductive-system-anatomy-2394", "fuente": "anking", "tema": 34, "anki": "1463356283395", "q": "After menopause, declining estrogen and progesterone lead to what change in breast tissue?", "o": {"A": "Hyperplasia", "B": "Hypertrophy", "C": "Atrophy", "D": "Dysplasia"}, "r": "C", "e": {"correcta": "After menopause, the loss of ovarian estrogen and progesterone production leads to atrophy of breast lobular and glandular tissue, with relative replacement by adipose tissue — the reverse of the hyperplastic changes seen during pregnancy.", "incorrectas": {"A": "Hyperplasia (an increase in cell number) is the pregnancy-associated response to rising hormones, not the postmenopausal response to their decline.", "B": "Hypertrophy refers to an increase in cell size, which is not the characteristic postmenopausal breast change; the process is regression (atrophy) of glandular tissue, not enlargement.", "D": "Dysplasia describes abnormal, disordered cell growth with malignant potential, not the normal, expected hormone-withdrawal atrophy that occurs after menopause."}}}, {"id": "anking-reproductive-system-pathology-2395", "fuente": "anking", "tema": 8, "anki": "1463356293665", "q": "A non-pregnant, non-lactating woman presents with milk production from her breasts. What is this finding called?", "o": {"A": "Mastitis", "B": "Gynecomastia", "C": "Galactorrhea", "D": "Mammary duct ectasia"}, "r": "C", "e": {"correcta": "Galactorrhea is milk production/discharge occurring outside the context of pregnancy or normal lactation. Causes include physical nipple stimulation, prolactin-secreting pituitary adenomas (prolactinoma), and drugs that raise prolactin (e.g., antipsychotics) by blocking dopamine's inhibitory effect on the anterior pituitary.", "incorrectas": {"A": "Mastitis is inflammation of breast tissue, typically presenting with a warm, erythematous, tender breast (often with purulent discharge in the lactational form), not simply milk production outside of lactation.", "B": "Gynecomastia is enlargement of male breast tissue due to an estrogen/androgen imbalance; it is unrelated to inappropriate milk secretion, which is the defining feature of galactorrhea.", "D": "Mammary duct ectasia is a benign inflammatory condition of subareolar ducts in older, multiparous women, presenting with a mass and possibly thick discharge, but it is not defined by milk production outside of lactation."}}}, {"id": "anking-reproductive-system-pathology-2396", "fuente": "anking", "tema": 8, "anki": "1463356301740", "q": "Is galactorrhea typically considered a symptom of breast cancer?", "o": {"A": "Yes, it is a common presenting symptom of breast cancer", "B": "No, it is not a symptom of breast cancer", "C": "Only in postmenopausal women", "D": "Only when bilateral"}, "r": "B", "e": {"correcta": "Galactorrhea is not a symptom of breast cancer. It results from elevated prolactin or increased prolactin sensitivity of breast tissue and is more commonly associated with a pituitary adenoma (prolactinoma), medication effects, or nipple stimulation, rather than with malignancy of the breast itself.", "incorrectas": {"A": "This is a common misconception; breast cancer classically presents with a painless mass, skin/nipple retraction, or bloody nipple discharge, not milky (galactorrhea-type) discharge.", "C": "Menopausal status does not change this association; galactorrhea remains linked to hyperprolactinemia (often pituitary in origin) rather than becoming a cancer symptom based on age.", "D": "Laterality does not change the underlying association; whether unilateral or bilateral, galactorrhea reflects a prolactin-related process, not a marker of malignancy."}}}, {"id": "anking-reproductive-system-pathology-2397", "fuente": "anking", "tema": 8, "anki": "1463356309150", "q": "Acute (lactational) mastitis, in which nipple fissures allow bacterial entry into breast tissue, is classically associated with which activity?", "o": {"A": "Nipple piercing", "B": "Breastfeeding", "C": "Oral contraceptive use", "D": "Recent mammography"}, "r": "B", "e": {"correcta": "Acute lactational mastitis occurs in breastfeeding women when fissures develop in the nipple from repeated suckling, creating a portal of entry for skin flora (commonly Staphylococcus aureus) into breast tissue, resulting in localized infection and inflammation.", "incorrectas": {"A": "Nipple piercing can theoretically introduce infection but is not the classic clinical association taught for lactational mastitis; the defining risk factor is breastfeeding-related nipple trauma.", "C": "Oral contraceptive use is not linked to acute mastitis; it has no established role in creating the nipple fissures that permit bacterial entry.", "D": "Mammography is a diagnostic imaging procedure and does not cause nipple trauma or create a portal for infection leading to mastitis."}}}, {"id": "anking-reproductive-system-pathology-2398", "fuente": "anking", "tema": 8, "anki": "1463356317440", "q": "A breastfeeding woman presents with a warm, erythematous breast and nipple discharge. What type of discharge characterizes acute lactational mastitis?", "o": {"A": "Serous discharge", "B": "Purulent discharge", "C": "Milky discharge only", "D": "Bloody discharge"}, "r": "B", "e": {"correcta": "Acute lactational mastitis presents with a warm, erythematous, tender breast accompanied by purulent nipple discharge, reflecting a bacterial infection (commonly S. aureus) entering through nipple fissures; it may progress to form a palpable abscess.", "incorrectas": {"A": "Serous (clear, thin) discharge is not the characteristic finding in mastitis; the infectious/inflammatory process produces pus-containing discharge instead.", "C": "While the woman is lactating and milk is present, mastitis is distinguished by purulent discharge indicating infection, not simply normal milk discharge.", "D": "Bloody nipple discharge raises concern for an intraductal papilloma or malignancy, not the expected finding in acute lactational mastitis, which produces purulent discharge."}}}, {"id": "anking-reproductive-system-pathology-2399", "fuente": "anking", "tema": 8, "anki": "1463356325517", "q": "What is the appropriate management for acute (lactational) mastitis?", "o": {"A": "Immediate cessation of breastfeeding plus antifungals", "B": "Continued drainage (e.g., continued feeding) plus antibiotics such as dicloxacillin", "C": "Surgical mastectomy", "D": "Observation only, as it is self-limited"}, "r": "B", "e": {"correcta": "Treatment of acute lactational mastitis involves continued drainage of the breast (continuing to breastfeed or pump, which is safe and encouraged) combined with antibiotics such as dicloxacillin that cover the likely causative organism, Staphylococcus aureus. Continued emptying of the breast helps prevent milk stasis and abscess formation.", "incorrectas": {"A": "Stopping breastfeeding is not recommended and can worsen milk stasis and infection risk; antifungals are also inappropriate since the underlying pathogen is bacterial, not fungal.", "C": "Surgical mastectomy is a drastic, inappropriate treatment for a treatable bacterial infection; surgery (incision and drainage) may only be needed if a discrete abscess forms and fails to resolve with antibiotics.", "D": "Mastitis is not simply self-limited; untreated infection can progress to abscess formation, so timely antibiotics and continued drainage are recommended rather than watchful waiting alone."}}}, {"id": "anking-reproductive-system-pathology-2400", "fuente": "anking", "tema": 8, "anki": "1463356329258", "q": "Which type of mastitis specifically involves inflammation of the subareolar ducts?", "o": {"A": "Acute lactational mastitis", "B": "Periductal mastitis", "C": "Granulomatous mastitis", "D": "Tuberculous mastitis"}, "r": "B", "e": {"correcta": "Periductal mastitis is inflammation centered on the subareolar ducts, distinct from lactational mastitis, which is tied to breastfeeding-related infection. It typically occurs in smokers, in whom direct toxic damage to duct epithelium promotes squamous metaplasia and secondary inflammation of the ducts beneath the areola.", "incorrectas": {"A": "Acute lactational mastitis is a breastfeeding-associated infection from bacterial entry through nipple fissures, affecting the lactating breast generally rather than being defined by subareolar duct inflammation.", "C": "Granulomatous mastitis is a separate, less common entity often idiopathic or associated with autoimmune conditions, marked by granuloma formation, not specifically subareolar duct inflammation from smoking.", "D": "Tuberculous mastitis is a rare infectious cause of breast inflammation due to Mycobacterium tuberculosis, unrelated to the smoking-associated periductal process being described."}}}, {"id": "anking-reproductive-system-pathology-2401", "fuente": "anking", "tema": 8, "anki": "1463356342414", "q": "Periductal mastitis, involving inflammation of the subareolar ducts, is most classically seen in which population?", "o": {"A": "Postmenopausal multiparous women", "B": "Smokers", "C": "Breastfeeding women", "D": "Adolescent girls"}, "r": "B", "e": {"correcta": "Periductal mastitis is classically associated with smoking. Toxic constituents of cigarette smoke are thought to damage the subareolar duct epithelium directly, promoting squamous metaplasia of the ducts and predisposing to duct obstruction and secondary inflammation.", "incorrectas": {"A": "Postmenopausal multiparous women are the classic population for mammary duct ectasia, a different (though related) inflammatory ductal condition, not periductal mastitis.", "C": "Breastfeeding women are at risk for acute lactational mastitis from nipple fissures and bacterial entry, a distinct condition from smoking-associated periductal mastitis.", "D": "Adolescent girls are not the population associated with periductal mastitis; this condition is tied to cumulative smoking exposure, which is uncommon in this age group."}}}, {"id": "anking-reproductive-system-pathology-2402", "fuente": "anking", "tema": 8, "anki": "1463356369801", "q": "Periductal mastitis presents as a subareolar mass with which finding caused by myofibroblast contraction during the healing process?", "o": {"A": "Peau d'orange skin change", "B": "Nipple retraction", "C": "Axillary lymphadenopathy", "D": "Skin ulceration"}, "r": "B", "e": {"correcta": "Periductal mastitis can present as a subareolar mass associated with nipple retraction, caused by fibrosis and contraction of myofibroblasts during the healing/scarring process, pulling the nipple inward — a finding that can mimic the nipple retraction seen in breast cancer.", "incorrectas": {"A": "Peau d'orange (skin dimpling resembling orange peel) results from dermal lymphatic obstruction, classically seen in inflammatory breast cancer, not periductal mastitis.", "C": "Axillary lymphadenopathy is a concerning feature more typically associated with malignant spread or significant infection, not the classic hallmark finding of periductal mastitis, which is nipple retraction.", "D": "Skin ulceration is not a typical feature of periductal mastitis; the classic finding relates to fibrotic pulling of the nipple, not breakdown of the overlying skin."}}}, {"id": "anking-reproductive-system-pathology-2403", "fuente": "anking", "tema": 8, "anki": "1463356381503", "q": "Biopsy in mammary duct ectasia shows chronic inflammation with which predominant cell type?", "o": {"A": "Eosinophils", "B": "Plasma cells", "C": "Neutrophils", "D": "Mast cells"}, "r": "B", "e": {"correcta": "Mammary duct ectasia is characterized histologically by chronic inflammation with a prominent infiltrate of plasma cells surrounding dilated (ectatic), often lipid- and debris-filled subareolar ducts, reflecting a long-standing, non-infectious inflammatory process.", "incorrectas": {"A": "Eosinophils are typically associated with allergic or parasitic processes, not the chronic plasma cell-rich infiltrate that defines mammary duct ectasia.", "C": "Neutrophils dominate acute inflammatory and infectious processes, such as acute lactational mastitis, rather than the chronic, plasma cell-predominant picture seen in duct ectasia.", "D": "Mast cells are not the characteristic cell type described in mammary duct ectasia; the hallmark inflammatory cell in this condition is the plasma cell."}}}, {"id": "anking-reproductive-system-pathology-2404", "fuente": "anking", "tema": 8, "anki": "1463356385294", "q": "Mammary duct ectasia, an important benign cause of a breast mass, classically arises in which patient population?", "o": {"A": "Nulliparous, premenopausal women", "B": "Multiparous, postmenopausal women", "C": "Adolescent nulliparous girls", "D": "Pregnant women in the third trimester"}, "r": "B", "e": {"correcta": "Mammary duct ectasia classically occurs in multiparous, postmenopausal women, presenting as a subareolar mass often with thick, green-brown nipple discharge due to dilation and chronic inflammation of the subareolar ducts. It is an important benign mimicker of malignancy in this age group.", "incorrectas": {"A": "Nulliparous, premenopausal women are more typically affected by fibrocystic changes or fibroadenomas rather than the classic multiparous, postmenopausal presentation of duct ectasia.", "C": "Adolescent nulliparous girls are not the classic population for duct ectasia, which requires the cumulative ductal changes seen with parity and age.", "D": "Pregnant women in the third trimester would be expected to show physiologic lobular hyperplasia rather than the chronic ductal inflammatory changes of duct ectasia, which occurs later in life after childbearing and menopause."}}}, {"id": "anking-reproductive-system-pathology-2405", "fuente": "anking", "tema": 8, "anki": "1463356394363", "q": "Fat necrosis of the breast, which can mimic carcinoma on exam and imaging, is usually related to which prior event (though a history of it is not always reported)?", "o": {"A": "Infection", "B": "Trauma", "C": "Radiation exposure", "D": "Hormonal contraceptive use"}, "r": "B", "e": {"correcta": "Fat necrosis of the breast is usually related to trauma (e.g., a blow to the breast, surgery, or biopsy), which causes death of adipocytes and subsequent saponification of the released fat with calcium. Notably, patients often do not recall or report an inciting traumatic event, making the history unreliable.", "incorrectas": {"A": "Infection is the underlying cause of mastitis, characterized by warmth, erythema, and purulent discharge, not the mechanism behind fat necrosis, which is physical injury to adipose tissue.", "C": "Radiation exposure is not the classic inciting cause taught for fat necrosis of the breast; the classic and tested association is with trauma.", "D": "Hormonal contraceptive use affects glandular tissue via estrogen/progesterone signaling but is not linked to the traumatic fat necrosis process."}}}, {"id": "anking-reproductive-system-pathology-2406", "fuente": "anking", "tema": 8, "anki": "1463356413365", "q": "On physical exam, fat necrosis of the breast most characteristically presents as what type of finding?", "o": {"A": "A painful, fluctuant mass", "B": "A painless mass", "C": "Diffuse breast tenderness without a discrete mass", "D": "Bilateral nipple discharge"}, "r": "B", "e": {"correcta": "Fat necrosis of the breast typically presents as a painless mass on physical exam, which can clinically and radiographically mimic carcinoma, making biopsy important to confirm the benign diagnosis and avoid unnecessary anxiety or intervention.", "incorrectas": {"A": "A painful, fluctuant mass suggests an abscess (such as with acute mastitis), not the classically painless presentation of fat necrosis.", "C": "Diffuse tenderness without a discrete mass is more typical of conditions like fibrocystic change or mastitis, whereas fat necrosis characteristically forms a localized, palpable, painless mass.", "D": "Nipple discharge is not a typical feature of fat necrosis; this condition presents as a mass, not a ductal discharge process."}}}, {"id": "anking-reproductive-system-pathology-2407", "fuente": "anking", "tema": 8, "anki": "1463356420839", "q": "On mammography, fat necrosis of the breast (due to saponification of fat with calcium) classically appears as which finding?", "o": {"A": "Spiculated mass with microcalcifications", "B": "Calcified oil cyst", "C": "Diffuse skin thickening", "D": "Well-circumscribed hypoechoic mass without calcification"}, "r": "B", "e": {"correcta": "Fat necrosis classically appears on mammography as a calcified oil cyst — a radiolucent, fat-density cystic area with a rim of calcification, resulting from saponification of necrotic fat by calcium. This relatively specific imaging appearance helps distinguish it from malignancy.", "incorrectas": {"A": "A spiculated mass with microcalcifications is the classic worrisome appearance of invasive ductal carcinoma, the opposite of the more benign-appearing calcified oil cyst of fat necrosis.", "C": "Diffuse skin thickening is associated with inflammatory breast cancer or severe mastitis/edema, not the localized calcified lesion seen in fat necrosis.", "D": "A well-circumscribed hypoechoic mass without calcification is more typical of a simple cyst or fibroadenoma on ultrasound, not the calcified, fat-containing lesion characteristic of fat necrosis."}}}, {"id": "anking-reproductive-system-pathology-2408", "fuente": "anking", "tema": 8, "anki": "1463356429101", "q": "Biopsy of breast tissue with fat necrosis shows necrotic fat, calcifications, and which additional characteristic cell type?", "o": {"A": "Plasma cells", "B": "Giant cells", "C": "Neutrophils only", "D": "Reed-Sternberg cells"}, "r": "B", "e": {"correcta": "Histologically, fat necrosis shows necrotic adipocytes, dystrophic calcifications, and multinucleated giant cells (a foreign-body/macrophage response to the necrotic fat and released lipid), reflecting a chronic granulomatous-type reaction to the injured tissue.", "incorrectas": {"A": "Plasma cells are the hallmark of mammary duct ectasia's chronic inflammatory infiltrate, not the giant cell reaction characteristic of fat necrosis.", "C": "Neutrophils predominate in acute infectious processes such as lactational mastitis, not in the chronic granulomatous/giant cell response typical of fat necrosis.", "D": "Reed-Sternberg cells are the diagnostic cell of Hodgkin lymphoma and have no relationship to breast fat necrosis."}}}, {"id": "anking-reproductive-system-pathology-2409", "fuente": "anking", "tema": 8, "anki": "1463356441715", "q": "Fibrocystic change of the breast, common in the upper outer quadrant and often bilateral/multifocal, classically presents with what type of breast on exam?", "o": {"A": "A single, firm, well-defined mass", "B": "A 'lumpy' breast that may be painful", "C": "A hard, fixed, immobile mass", "D": "Skin dimpling with a fixed mass"}, "r": "B", "e": {"correcta": "Fibrocystic change presents as a 'lumpy' breast, often tender/painful, and characteristically bilateral and multifocal, particularly in premenopausal women aged 20-50. This distinguishes it from a fibroadenoma, which is a solitary, discrete, well-defined solid mass.", "incorrectas": {"A": "A single, firm, well-defined mass is the classic description of a fibroadenoma, not the diffusely lumpy, often bilateral presentation of fibrocystic change.", "C": "A hard, fixed, immobile mass raises concern for invasive carcinoma, which characteristically invades surrounding tissue, unlike the mobile, lumpy quality of fibrocystic change.", "D": "Skin dimpling with a fixed mass suggests malignant invasion of Cooper ligaments, a red-flag finding for cancer rather than the benign lumpiness of fibrocystic change."}}}, {"id": "anking-reproductive-system-pathology-2410", "fuente": "anking", "tema": 8, "anki": "1463356453700", "q": "On gross examination, cysts in fibrocystic change of the breast classically have what appearance?", "o": {"A": "Blue-domed", "B": "Yellow, caseous", "C": "Hemorrhagic, dark red", "D": "White, chalky"}, "r": "A", "e": {"correcta": "Fibrocystic change produces cysts filled with fluid that impart a characteristic 'blue-domed' appearance on gross examination, reflecting the thin-walled, fluid-distended cysts visible through overlying tissue.", "incorrectas": {"B": "A yellow, caseous appearance is more typical of caseating granulomatous processes (e.g., tuberculosis), not the fluid-filled cysts of fibrocystic change.", "C": "A hemorrhagic, dark red appearance would suggest bleeding into a lesion, which is not the classic description of fibrocystic cysts; these are typically described as blue-domed rather than hemorrhagic.", "D": "A white, chalky appearance would suggest calcification or necrotic debris, not the translucent, fluid-filled blue-domed cysts characteristic of fibrocystic change."}}}, {"id": "anking-reproductive-system-pathology-2411", "fuente": "anking", "tema": 8, "anki": "1463356457000", "q": "Fibrocystic changes of the breast, the most common cause of benign breast masses in premenopausal women aged 20-50, are generally classified as which of the following?", "o": {"A": "Malignant", "B": "Premalignant only", "C": "Benign", "D": "Borderline malignant potential in all cases"}, "r": "C", "e": {"correcta": "Fibrocystic changes are generally benign and represent the most common cause of benign breast masses in premenopausal women aged 20-50. While certain proliferative subtypes carry a slightly increased cancer risk, the overall category is considered a benign condition.", "incorrectas": {"A": "Fibrocystic changes are not malignant; they are a benign, common finding related to hormonal fluctuation in premenopausal women, distinct from carcinoma.", "B": "While specific proliferative variants (e.g., with atypia) can slightly raise future cancer risk, fibrocystic change as a whole is not classified as inherently premalignant.", "D": "Most fibrocystic changes (non-proliferative types like simple cysts, apocrine metaplasia) carry no increased cancer risk at all, so it is inaccurate to say all cases carry borderline malignant potential."}}}, {"id": "anking-reproductive-system-pathology-2412", "fuente": "anking", "tema": 8, "anki": "1463356461093", "q": "When certain fibrocystic-related changes do carry an increased risk for invasive carcinoma, does that increased risk apply to just the affected breast or both breasts?", "o": {"A": "Only the ipsilateral (affected) breast", "B": "Only the contralateral breast", "C": "Both breasts", "D": "Neither breast — risk applies only to axillary tissue"}, "r": "C", "e": {"correcta": "When fibrocystic-related changes (such as proliferative lesions with atypia) do confer increased breast cancer risk, that increased risk applies to both breasts, not just the one where the biopsy was taken — reflecting a field effect of hormonally-driven risk across the entire breast tissue field rather than a purely localized process.", "incorrectas": {"A": "Limiting the increased risk to only the ipsilateral breast misunderstands the bilateral nature of the risk elevation associated with certain proliferative fibrocystic lesions.", "B": "The risk is not isolated to the contralateral breast alone; both breasts share in the elevated risk, since the biological change reflects an increased susceptibility of breast tissue generally.", "D": "Axillary tissue is not the site of the increased cancer risk being described; the risk pertains to the breast tissue itself in both breasts."}}}, {"id": "anking-reproductive-system-pathology-2413", "fuente": "anking", "tema": 8, "anki": "1463356464886", "q": "What is the relative risk of developing invasive breast carcinoma in a patient with fibrosis and simple cysts (non-proliferative fibrocystic changes)?", "o": {"A": "Markedly increased risk (RR > 4)", "B": "Moderately increased risk (RR 2-4)", "C": "No increased risk", "D": "Risk only increases after menopause"}, "r": "C", "e": {"correcta": "Non-proliferative fibrocystic changes such as simple fibrosis and cysts confer no increased risk of developing invasive breast carcinoma. These are considered benign, low-risk lesions, in contrast to proliferative lesions with atypia, which do carry meaningfully elevated risk.", "incorrectas": {"A": "A markedly increased risk (RR > 4) is seen with lesions such as atypical hyperplasia with a strong family history, not with simple fibrosis and cysts, which are non-proliferative and low-risk.", "B": "A moderately increased risk (RR 2-4) is characteristic of proliferative changes without atypia (e.g., ductal hyperplasia, sclerosing adenosis), not simple fibrosis and cysts, which carry no increased risk at all.", "D": "The risk classification for fibrosis and cysts is not menopause-dependent; these non-proliferative changes carry no increased risk regardless of menopausal status."}}}, {"id": "anking-reproductive-system-pathology-2414", "fuente": "anking", "tema": 8, "anki": "1463356469862", "q": "Apocrine metaplasia (a fibrocystic change marked by cells with abundant pink cytoplasm and slightly enlarged nuclei) is associated with what relative risk of invasive breast carcinoma?", "o": {"A": "No increased risk", "B": "Slightly increased risk (RR ~1.5-2)", "C": "Moderately increased risk (RR 2-4)", "D": "Markedly increased risk (RR > 4)"}, "r": "A", "e": {"correcta": "Apocrine metaplasia, a benign fibrocystic change characterized by cells with abundant eosinophilic (pink) cytoplasm and slightly enlarged nuclei compared to normal, is classified as a non-proliferative change and confers no increased risk of invasive breast carcinoma.", "incorrectas": {"B": "A slightly increased risk is not the classification given to apocrine metaplasia; it is grouped among the non-proliferative changes that carry no elevation in cancer risk at all.", "C": "Moderately increased risk (RR 2-4) applies to proliferative lesions without atypia (such as usual ductal hyperplasia or sclerosing adenosis), not to apocrine metaplasia.", "D": "Markedly increased risk (RR > 4) is reserved for atypical hyperplasia in the setting of a strong family history, a very different risk category from the no-increased-risk classification of apocrine metaplasia."}}}, {"id": "anking-reproductive-system-pathology-2415", "fuente": "anking", "tema": 8, "anki": "1463356487232", "q": "A breast biopsy in a 45-year-old woman shows sclerosing adenosis, a proliferative fibrocystic change with increased acini and intralobular fibrosis. Compared to a woman with no fibrocystic changes, what is her relative risk of developing invasive breast carcinoma?", "o": {"A": "No increased risk", "B": "1.5-2x increased risk", "C": "5x increased risk", "D": "10x increased risk"}, "r": "B", "e": {"correcta": "Sclerosing adenosis is a proliferative fibrocystic change (without atypia) and confers a mild 1.5-2x increased relative risk of subsequent invasive breast carcinoma, the same magnitude of risk seen with epithelial hyperplasia without atypia. This places it in the 'proliferative, non-atypical' risk category, intermediate between non-proliferative changes and atypical hyperplasia.", "incorrectas": {"A": "Non-proliferative fibrocystic changes such as simple cysts, apocrine metaplasia, and mild hyperplasia carry no increased risk, but sclerosing adenosis is a proliferative lesion and therefore does carry a small increased risk.", "C": "A 5x increased risk corresponds to proliferative disease WITH atypia (atypical ductal or lobular hyperplasia), a higher-risk category than the non-atypical proliferative changes seen in sclerosing adenosis.", "D": "No fibrocystic change alone confers a 10x risk; this magnitude is more consistent with strong genetic predispositions (e.g., BRCA mutations), not fibrocystic breast changes."}}}, {"id": "anking-reproductive-system-pathology-2416", "fuente": "anking", "tema": 8, "anki": "1463356491082", "q": "Which fibrocystic breast change is defined as an increased number of cells in the terminal ductal-lobular unit epithelium?", "o": {"A": "Epithelial hyperplasia", "B": "Sclerosing adenosis", "C": "Fat necrosis", "D": "Simple cyst formation"}, "r": "A", "e": {"correcta": "Epithelial (ductal) hyperplasia is defined by an increased number of epithelial cells lining the terminal duct lobular unit, filling and distending the ductal/lobular spaces beyond the normal two-cell layer. It is a proliferative fibrocystic change and, depending on the presence of cytologic atypia, confers a variable increase in future breast cancer risk.", "incorrectas": {"B": "Sclerosing adenosis involves increased acini and stromal fibrosis compressing the glandular elements, not simply an increase in epithelial cell number lining the ducts, though both are proliferative fibrocystic changes.", "C": "Fat necrosis is a benign inflammatory reaction to adipose tissue injury (often after trauma), producing saponification and calcification, unrelated to epithelial cell proliferation.", "D": "Simple cyst formation reflects dilation of the terminal ducts filled with fluid, a non-proliferative fibrocystic change without an increase in epithelial cell number."}}}, {"id": "anking-reproductive-system-pathology-2417", "fuente": "anking", "tema": 8, "anki": "1463356494886", "q": "A patient has epithelial hyperplasia without atypia found on breast biopsy. What is her relative risk of developing invasive breast carcinoma compared to the general population?", "o": {"A": "No increased risk", "B": "1.5-2x increased risk", "C": "5x increased risk", "D": "8-10x increased risk"}, "r": "B", "e": {"correcta": "Epithelial hyperplasia without atypia is a proliferative fibrocystic change, placing it in the mild-risk category with a 1.5-2x relative risk of subsequent invasive carcinoma, similar to sclerosing adenosis. The risk rises substantially only when cytologic atypia is present.", "incorrectas": {"A": "Non-proliferative changes (simple cysts, mild apocrine metaplasia) carry no increased risk, but hyperplasia itself is a proliferative lesion and thus is not risk-neutral.", "C": "A 5x risk applies specifically to hyperplasia WITH atypia (atypical hyperplasia), reflecting the added risk conferred by cytologic atypia rather than proliferation alone.", "D": "An 8-10x risk is far higher than any fibrocystic change confers and is more in line with risk from a strong hereditary predisposition, not epithelial hyperplasia without atypia."}}}, {"id": "anking-reproductive-system-pathology-2418", "fuente": "anking", "tema": 8, "anki": "1463356505756", "q": "Histologic examination of an intraductal papilloma of the breast shows fibrovascular cores projecting into a dilated duct. Which cell types line these fibrovascular projections?", "o": {"A": "Only luminal epithelial cells", "B": "Both luminal epithelial and myoepithelial cells", "C": "Only myoepithelial cells", "D": "Squamous metaplastic cells"}, "r": "B", "e": {"correcta": "Intraductal papilloma is a benign papillary lesion in which the fibrovascular stalks are lined by a double layer of both luminal epithelial cells and an underlying myoepithelial cell layer, reflecting its benign nature. Preservation of the myoepithelial layer is the key histologic feature separating it from malignant papillary lesions.", "incorrectas": {"A": "Presence of only epithelial cells without an underlying myoepithelial layer is characteristic of papillary carcinoma, not the benign intraductal papilloma, which retains the two-cell-layer architecture.", "C": "Papillomas are not lined solely by myoepithelial cells; they retain the normal double layer with luminal epithelial cells on the surface and myoepithelial cells beneath.", "D": "Squamous metaplasia can rarely occur in various breast lesions but is not the defining lining of the fibrovascular cores in intraductal papilloma; the key feature is the intact luminal/myoepithelial double layer."}}}, {"id": "anking-reproductive-system-pathology-2419", "fuente": "anking", "tema": 8, "anki": "1463356514499", "q": "A 35-year-old premenopausal woman presents with unilateral bloody nipple discharge and a small subareolar mass. What is the most likely diagnosis?", "o": {"A": "Papillary carcinoma", "B": "Fibroadenoma", "C": "Intraductal papilloma", "D": "Phyllodes tumor"}, "r": "C", "e": {"correcta": "Intraductal papilloma classically presents in premenopausal women with unilateral bloody or serosanguinous nipple discharge, sometimes with a palpable small subareolar mass; the bleeding results from twisting of the papilloma's vascular fibrovascular stalk within the duct. It is the most common cause of bloody nipple discharge overall.", "incorrectas": {"A": "Papillary carcinoma also causes bloody nipple discharge but classically occurs in postmenopausal women, not the premenopausal population described here.", "B": "Fibroadenoma presents as a painless, mobile, well-circumscribed mass in young women but does not typically cause nipple discharge, since it does not arise within the ductal system near the nipple.", "D": "Phyllodes tumor presents as a large, sometimes rapidly enlarging breast mass in older (perimenopausal to postmenopausal) women and is not associated with nipple discharge."}}}, {"id": "anking-reproductive-system-pathology-2420", "fuente": "anking", "tema": 8, "anki": "1463356532940", "q": "What is the most common overall cause of nipple discharge (serous or bloody) in women?", "o": {"A": "Ductal carcinoma in situ", "B": "Fibroadenoma", "C": "Intraductal papilloma", "D": "Fat necrosis"}, "r": "C", "e": {"correcta": "Intraductal papilloma is the most common cause of nipple discharge, whether serous or (more classically) bloody/serosanguinous ('straw-colored'), due to its intraductal location near the nipple and its fragile, twisting vascular stalk.", "incorrectas": {"A": "DCIS can occasionally present with nipple discharge, particularly when it extends as Paget disease, but it is far less common as a cause of nipple discharge overall compared to the benign intraductal papilloma.", "B": "Fibroadenoma is the most common benign breast tumor but arises from stroma away from the ductal system near the nipple and does not typically cause nipple discharge.", "D": "Fat necrosis presents as a firm, sometimes calcified mass often following trauma, and is not a common cause of nipple discharge."}}}, {"id": "anking-reproductive-system-pathology-2421", "fuente": "anking", "tema": 8, "anki": "1463356558172", "q": "A papillary breast lesion is biopsied and the fibrovascular cores are found to be lined only by neoplastic epithelial cells with no myoepithelial layer. Which lesion does this describe?", "o": {"A": "Intraductal papilloma", "B": "Fibroadenoma", "C": "Papillary carcinoma", "D": "Sclerosing adenosis"}, "r": "C", "e": {"correcta": "Papillary carcinoma is characterized by fibrovascular projections lined by only a single layer of malignant epithelial cells, with complete absence of the myoepithelial layer, distinguishing it from the benign intraductal papilloma. Loss of the myoepithelial layer is a key histologic marker of malignancy in papillary breast lesions.", "incorrectas": {"A": "Intraductal papilloma retains both luminal epithelial cells AND an underlying myoepithelial layer on its fibrovascular cores, which is precisely the feature that is absent in this case.", "B": "Fibroadenoma is a stromal/glandular proliferation, not a papillary lesion with fibrovascular cores lined by epithelium, so the myoepithelial layer question does not apply to it in the same way.", "D": "Sclerosing adenosis is a fibrocystic change with distorted acini compressed by fibrosis, an entirely different architecture from papillary fibrovascular projections."}}}, {"id": "anking-reproductive-system-pathology-2422", "fuente": "anking", "tema": 8, "anki": "1463356564936", "q": "A 62-year-old postmenopausal woman presents with unilateral bloody nipple discharge. Which breast lesion is most classically associated with this presentation at her age?", "o": {"A": "Fibroadenoma", "B": "Intraductal papilloma", "C": "Papillary carcinoma", "D": "Phyllodes tumor"}, "r": "C", "e": {"correcta": "Papillary carcinoma classically presents with bloody nipple discharge in a postmenopausal woman, in contrast to the benign intraductal papilloma, which presents similarly but typically in premenopausal women. Age at presentation is a key clinical clue helping distinguish the benign from the malignant papillary lesion.", "incorrectas": {"A": "Fibroadenoma is a benign mass most common in women under 35 and is not associated with nipple discharge or a postmenopausal presentation.", "B": "Intraductal papilloma causes bloody nipple discharge but classically presents in premenopausal women, not the postmenopausal patient described here.", "D": "Phyllodes tumor presents as a large breast mass in perimenopausal to postmenopausal women but is not characterized by nipple discharge."}}}, {"id": "anking-reproductive-system-pathology-2423", "fuente": "anking", "tema": 8, "anki": "1463356568833", "q": "A 22-year-old woman presents with a small, well-circumscribed, mobile, rubbery breast mass. Ultrasound shows a hypoechoic, well-defined round lesion. What is the most likely diagnosis?", "o": {"A": "Phyllodes tumor", "B": "Invasive ductal carcinoma", "C": "Fibroadenoma", "D": "Intraductal papilloma"}, "r": "C", "e": {"correcta": "Fibroadenoma is a benign small, well-defined, mobile breast mass composed of fibrous tissue and glands, arising from intralobular stroma; it is the most common breast tumor in premenopausal women (especially under 30) and appears as a hypoechoic, well-circumscribed round mass on ultrasound.", "incorrectas": {"A": "Phyllodes tumor can resemble a fibroadenoma histologically but usually presents as a larger, sometimes rapidly growing mass in older (perimenopausal/postmenopausal) women, not a small mobile mass in a young woman.", "B": "Invasive ductal carcinoma typically presents as a firm, irregular, poorly mobile mass with indistinct or spiculated margins in an older woman, not a well-circumscribed mobile mass in someone this young.", "D": "Intraductal papilloma presents with nipple discharge and, if palpable, a small subareolar mass rather than the discrete, mobile, well-circumscribed peripheral mass typical of fibroadenoma."}}}, {"id": "anking-reproductive-system-pathology-2424", "fuente": "anking", "tema": 8, "anki": "1463356577083", "q": "What is the most common benign neoplasm of the breast, and also the most common breast tumor overall in women under 30?", "o": {"A": "Intraductal papilloma", "B": "Fibroadenoma", "C": "Phyllodes tumor", "D": "Sclerosing adenosis"}, "r": "B", "e": {"correcta": "Fibroadenoma is the most common benign breast neoplasm and the most common breast tumor overall in premenopausal women under 30. On ultrasound it appears hypoechoic (darker than surrounding tissue), well-circumscribed, and mobile on exam.", "incorrectas": {"A": "Intraductal papilloma is a common cause of nipple discharge but is much less common than fibroadenoma as a palpable breast mass, and it is not the most common benign breast neoplasm overall.", "C": "Phyllodes tumor is far less common than fibroadenoma and tends to occur in slightly older women, presenting as a larger, sometimes rapidly growing mass rather than the classic small mobile mass of youth.", "D": "Sclerosing adenosis is a fibrocystic change, not a discrete neoplasm, and does not typically present as a palpable, well-circumscribed mobile mass the way fibroadenoma does."}}}, {"id": "anking-reproductive-system-pathology-2425", "fuente": "anking", "tema": 8, "anki": "1463356589606", "q": "Fibroadenoma of the breast is most common in women of what age range?", "o": {"A": "Under 35 years old", "B": "35-50 years old", "C": "50-65 years old", "D": "Over 65 years old"}, "r": "A", "e": {"correcta": "Fibroadenoma is most common in women under 35 years old, typically in the reproductive years (roughly 15-35), reflecting its estrogen-sensitive growth from intralobular stroma. It tends to shrink after menopause when estrogen stimulation declines.", "incorrectas": {"B": "The 35-50 age range is more associated with fibrocystic changes and rising breast cancer risk, not the peak incidence of fibroadenoma, which is younger.", "C": "The 50-65 age range corresponds more to peak incidence of invasive breast carcinoma and phyllodes tumor, not fibroadenoma.", "D": "Fibroadenomas typically regress (hyalinize/shrink) after menopause due to loss of estrogen stimulation, making an age over 65 an unlikely peak incidence."}}}, {"id": "anking-reproductive-system-pathology-2426", "fuente": "anking", "tema": 8, "anki": "1463356597398", "q": "A young woman notices that her fibroadenoma becomes larger and more tender just before her menstrual period and during pregnancy. Increased size and tenderness of fibroadenoma is driven by exposure to which hormone?", "o": {"A": "Progesterone", "B": "Estrogen", "C": "Prolactin", "D": "Testosterone"}, "r": "B", "e": {"correcta": "Fibroadenoma is an estrogen-sensitive lesion; its size and tenderness increase with estrogen exposure, such as during pregnancy or the luteal/premenstrual phase, and it tends to shrink after menopause when estrogen levels fall.", "incorrectas": {"A": "While progesterone fluctuates with the menstrual cycle alongside estrogen, the classic driver of fibroadenoma growth and tenderness described in First Aid/Pathoma is estrogen, not progesterone specifically.", "C": "Prolactin drives lactation and breast development in a different context (postpartum milk production) but is not the hormone classically implicated in fibroadenoma growth and tenderness.", "D": "Testosterone is not relevant to fibroadenoma growth in women; interestingly, in males fibroadenoma-like changes have been linked to anti-androgen therapy (which increases relative estrogen effect), not testosterone itself."}}}, {"id": "anking-reproductive-system-pathology-2427", "fuente": "anking", "tema": 8, "anki": "1463356606383", "q": "Does the presence of a fibroadenoma increase a woman's risk of developing breast cancer?", "o": {"A": "Yes, by 1.5-2x", "B": "Yes, by 5x", "C": "No, it is a benign lesion with no increased risk", "D": "Only if it is larger than 5 cm"}, "r": "C", "e": {"correcta": "Fibroadenoma is a benign tumor of the breast and does not increase the risk of developing breast cancer, distinguishing it from proliferative fibrocystic changes (like epithelial hyperplasia or sclerosing adenosis) that do confer mildly increased risk.", "incorrectas": {"A": "A 1.5-2x increased risk applies to proliferative fibrocystic changes without atypia (e.g., epithelial hyperplasia, sclerosing adenosis), not to fibroadenoma, which carries no increased risk.", "B": "A 5x increased risk is associated with atypical hyperplasia, a very different lesion category from the benign, non-risk-elevating fibroadenoma.", "D": "Size is not the determinant of cancer risk for fibroadenoma; regardless of size, ordinary fibroadenoma remains a benign lesion without an associated increase in breast cancer risk (large or rapidly growing lesions instead raise suspicion for phyllodes tumor)."}}}, {"id": "anking-reproductive-system-pathology-2428", "fuente": "anking", "tema": 8, "anki": "1463356615982", "q": "Phyllodes tumor of the breast is most commonly seen in women of which reproductive status?", "o": {"A": "Premenarchal girls", "B": "Premenopausal women in their teens/20s", "C": "Postmenopausal women", "D": "Pregnant women only"}, "r": "C", "e": {"correcta": "Phyllodes tumor is most commonly seen in postmenopausal women, with peak incidence around the fifth decade of life (roughly age 40-50s, later than fibroadenoma), distinguishing it clinically from the more common fibroadenoma of younger women despite overlapping histology (leaf-like fibroepithelial architecture).", "incorrectas": {"A": "Phyllodes tumor essentially never occurs before puberty; it requires the hormonally mature breast stroma of adult women.", "B": "Fibroadenoma, not phyllodes tumor, is the classic fibroepithelial lesion of young premenopausal women in their teens and twenties.", "D": "Phyllodes tumor is not restricted to pregnancy; it occurs across the adult female population with a peak incidence around perimenopause/postmenopause, unrelated specifically to pregnancy."}}}, {"id": "anking-reproductive-system-pathology-2429", "fuente": "anking", "tema": 8, "anki": "1463356622263", "q": "A large, rapidly enlarging breast mass with leaf-like papillary projections of stroma is excised from a 50-year-old woman. Can phyllodes tumors of the breast be malignant?", "o": {"A": "No, they are always entirely benign", "B": "Yes, some phyllodes tumors are malignant", "C": "Only in men", "D": "Only if calcifications are present on mammography"}, "r": "B", "e": {"correcta": "Phyllodes tumor exists along a spectrum from benign to borderline to malignant, based on stromal cellularity, mitotic activity, and margin characteristics; unlike fibroadenoma, a subset of phyllodes tumors behave in a locally aggressive or even metastasizing fashion, so they do carry malignant potential.", "incorrectas": {"A": "While many phyllodes tumors are benign, a meaningful proportion show malignant features (increased stromal cellularity/mitoses, infiltrative margins) with potential for recurrence or metastasis, so 'always benign' is incorrect.", "C": "Phyllodes tumor is overwhelmingly a disease of women; malignant potential is not restricted to or defined by occurrence in men, and male occurrence is exceedingly rare regardless of malignancy status.", "D": "Malignant potential in phyllodes tumor is determined by histologic features (stromal overgrowth, cellular atypia, mitotic rate, margins), not by the presence of mammographic calcifications, which are more characteristic of DCIS or fat necrosis."}}}, {"id": "anking-reproductive-system-pathology-2430", "fuente": "anking", "tema": 8, "anki": "1463442436474", "q": "Malignant breast tumors most commonly occur in women of which reproductive status?", "o": {"A": "Premenopausal women under 30", "B": "Postmenopausal women", "C": "Pregnant women", "D": "Adolescent girls"}, "r": "B", "e": {"correcta": "Malignant breast tumors, including invasive ductal carcinoma (the most common type), most commonly occur in postmenopausal women, reflecting cumulative lifetime estrogen exposure and age-related accumulation of genetic mutations. This contrasts with benign lesions like fibroadenoma, which peak in younger, premenopausal women.", "incorrectas": {"A": "Premenopausal women under 30 are more classically associated with benign lesions such as fibroadenoma rather than malignant breast tumors, which increase in incidence with age.", "C": "Pregnancy-associated breast cancer exists but is a less common scenario overall; the general epidemiologic peak for breast malignancy is in postmenopausal women, not pregnancy specifically.", "D": "Breast malignancy in adolescent girls is exceedingly rare; the breast in this age group is far more likely to show benign fibroepithelial lesions if any mass occurs at all."}}}, {"id": "anking-reproductive-system-pathology-2431", "fuente": "anking", "tema": 8, "anki": "1463442475910", "q": "What is the most common location within the breast for an invasive carcinoma to arise?", "o": {"A": "Upper-outer quadrant", "B": "Lower-inner quadrant", "C": "Central/subareolar region", "D": "Lower-outer quadrant"}, "r": "A", "e": {"correcta": "The upper-outer quadrant is the most common site of invasive breast carcinoma because it contains the greatest density of breast tissue (glandular/ductal tissue extending toward the axilla), and most invasive carcinomas arise from the terminal duct lobular unit found throughout this tissue.", "incorrectas": {"B": "The lower-inner quadrant contains comparatively less glandular tissue than the upper-outer quadrant and is not the most common site of tumor origin.", "C": "The central/subareolar region is the classic site of intraductal papilloma and Paget disease-associated changes, but it is not the most common site for invasive carcinoma overall.", "D": "The lower-outer quadrant, while it contains more tissue than the inner quadrants, still has less glandular density than the upper-outer quadrant and is not the most common site."}}}, {"id": "anking-reproductive-system-pathology-2432", "fuente": "anking", "tema": 8, "anki": "1463442490849", "q": "Most established risk factors for breast cancer (early menarche, late menopause, obesity, nulliparity) share which common underlying mechanism?", "o": {"A": "Increased androgen exposure", "B": "Increased estrogen exposure", "C": "Chronic HPV infection", "D": "Increased prolactin exposure"}, "r": "B", "e": {"correcta": "The majority of classic breast cancer risk factors converge on increased lifetime estrogen exposure, whether through more menstrual cycles (early menarche, late menopause), peripheral estrogen production (obesity, via aromatization of androgens to estrone in adipose tissue), or delayed/absent pregnancy (which normally provides estrogen-free intervals via prolactin-dominant lactation).", "incorrectas": {"A": "Androgen exposure is not the mechanism linking these classic risk factors to breast cancer; if anything, estrogen (partly derived from androgen aromatization in fat) is the operative hormone.", "C": "HPV infection is linked to cervical, anal, and oropharyngeal cancers, not breast cancer, and is not implicated in these classic reproductive/hormonal risk factors.", "D": "Prolactin drives lactation, and lactation is actually protective against breast cancer (by suppressing estrogen-driven cycling), so increased prolactin exposure is not the mechanism behind these risk factors."}}}, {"id": "anking-reproductive-system-pathology-2433", "fuente": "anking", "tema": 8, "anki": "1463442496649", "q": "How does age at first live birth affect a woman's risk of developing breast cancer?", "o": {"A": "Younger age at first birth increases risk", "B": "Older age at first birth increases risk", "C": "Age at first birth has no effect on risk", "D": "Only multiple births affect risk, not age"}, "r": "B", "e": {"correcta": "An older age at first live birth is associated with increased breast cancer risk, because pregnancy (particularly an early first pregnancy) induces terminal differentiation of breast epithelium, which is thought to be protective; delaying this differentiation prolongs the window of undifferentiated, proliferation-prone epithelium exposed to cyclical estrogen.", "incorrectas": {"A": "A younger age at first birth is actually protective (lower risk), the opposite of what is stated; early full-term pregnancy promotes earlier terminal differentiation of breast tissue.", "C": "Age at first live birth is one of the well-established, classic reproductive risk factors for breast cancer, not a neutral variable.", "D": "While parity itself (nulliparity vs. having children) also matters, age at first live birth specifically is an independent, well-documented risk factor, not simply a proxy for total number of births."}}}, {"id": "anking-reproductive-system-pathology-2434", "fuente": "anking", "tema": 8, "anki": "1463442505682", "q": "Obesity increases the risk of developing breast cancer primarily through which mechanism?", "o": {"A": "Chronic low-grade inflammation from adipokines alone", "B": "Increased estrone production from peripheral aromatization in adipose tissue", "C": "Insulin resistance causing direct DNA mutation", "D": "Decreased hepatic clearance of testosterone"}, "r": "B", "e": {"correcta": "Adipose tissue expresses aromatase, which converts adrenal and ovarian androgen precursors into estrone, so obesity increases circulating estrogen (estrone) levels; this added estrogenic stimulation of breast epithelium raises breast cancer risk, particularly in postmenopausal women where adipose tissue becomes the dominant estrogen source.", "incorrectas": {"A": "While obesity does cause chronic inflammation, the specific, classically tested mechanism linking obesity to breast cancer risk is peripheral estrone production via aromatization, not inflammation per se.", "C": "Insulin resistance is associated with obesity and some cancers, but the well-established, testable mechanism for breast cancer specifically is increased estrogen (estrone) from adipose aromatization, not direct DNA mutation from insulin resistance.", "D": "Hepatic clearance of testosterone is not the mechanism invoked for obesity-related breast cancer risk; the key pathway is peripheral conversion of androgens to estrone in fat tissue."}}}, {"id": "anking-reproductive-system-pathology-2435", "fuente": "anking", "tema": 8, "anki": "1463442510727", "q": "Increased risk for breast carcinoma is associated with which combination of reproductive timing factors?", "o": {"A": "Late menarche and early menopause", "B": "Early menarche and late menopause", "C": "Early menarche and early menopause", "D": "Late menarche and late menopause"}, "r": "B", "e": {"correcta": "Early menarche and late menopause both increase the total number of lifetime menstrual cycles and therefore cumulative estrogen exposure to breast tissue, which is why this combination increases breast cancer risk. Anything that shortens this estrogen-exposure window (late menarche, early menopause) is comparatively protective.", "incorrectas": {"A": "Late menarche and early menopause shorten the total duration of cyclical estrogen exposure and are therefore protective, the opposite of the risk-increasing combination.", "C": "Early menarche does increase risk, but pairing it with early menopause shortens the overall exposure window, reducing the added risk compared to early menarche plus late menopause.", "D": "Late menarche reduces early-life estrogen exposure; combining it with late menopause does not reproduce the same magnitude of lifetime estrogen exposure as early menarche with late menopause."}}}, {"id": "anking-reproductive-system-pathology-2436", "fuente": "anking", "tema": 8, "anki": "1463442529940", "q": "Ductal carcinoma in situ (DCIS) is classically detected on screening mammography by which finding?", "o": {"A": "A well-circumscribed hypoechoic mass", "B": "Microcalcifications", "C": "Skin thickening and peau d'orange", "D": "A palpable rock-hard mass with spiculated margins"}, "r": "B", "e": {"correcta": "DCIS is classically detected as microcalcifications on mammography; central tumor cells often undergo necrosis due to inadequate blood supply (since DCIS remains confined by the basement membrane), and the resulting necrotic debris develops dystrophic calcifications visible radiographically before a mass is even palpable.", "incorrectas": {"A": "A well-circumscribed hypoechoic mass on ultrasound is the classic appearance of a benign fibroadenoma, not the microcalcification pattern typical of DCIS.", "C": "Skin thickening and peau d'orange are hallmarks of inflammatory breast cancer, caused by dermal lymphatic invasion, a distinct and more aggressive presentation than DCIS.", "D": "A palpable rock-hard mass with spiculated/stellate margins describes invasive ductal carcinoma on physical exam, whereas DCIS is often non-palpable and detected via mammographic microcalcifications before it becomes invasive."}}}, {"id": "anking-reproductive-system-pathology-2437", "fuente": "anking", "tema": 8, "anki": "1463442541618", "q": "A mammogram shows calcifications in a woman's breast. Aside from malignancy, which two benign conditions can also produce mammographic calcifications, requiring biopsy to distinguish from carcinoma?", "o": {"A": "Fibroadenoma and phyllodes tumor", "B": "Sclerosing adenosis and fat necrosis", "C": "Intraductal papilloma and Paget disease", "D": "Tubular carcinoma and invasive lobular carcinoma"}, "r": "B", "e": {"correcta": "Both sclerosing adenosis (a fibrocystic change with distorted, calcifying acini) and fat necrosis (dystrophic calcification following adipose tissue injury, often after trauma or surgery) can produce mammographic calcifications that mimic malignancy, so biopsy is required to definitively distinguish these benign entities from carcinoma.", "incorrectas": {"A": "Fibroadenoma and phyllodes tumor typically present as well-circumscribed masses, not primarily as sources of the microcalcifications that mimic malignant calcification patterns on mammography.", "C": "Intraductal papilloma classically causes nipple discharge rather than calcifications, and Paget disease presents with nipple skin changes (eczema-like ulceration/erythema), not mammographic calcifications.", "D": "Tubular carcinoma and invasive lobular carcinoma are themselves malignant processes, not benign mimics that would need to be distinguished FROM carcinoma on the basis of calcifications."}}}, {"id": "anking-reproductive-system-pathology-2438", "fuente": "anking", "tema": 8, "anki": "1463442563224", "q": "Which disease is characterized by ductal carcinoma in situ cells extending up the lactiferous ducts to involve the epidermis of the nipple?", "o": {"A": "Inflammatory breast cancer", "B": "Phyllodes tumor", "C": "Paget disease of the breast", "D": "Tubular carcinoma"}, "r": "C", "e": {"correcta": "Paget disease of the breast occurs when DCIS cells (Paget cells) spread along the lactiferous ducts and infiltrate the epidermis of the nipple, producing characteristic nipple skin changes; it is essentially DCIS made visible on the nipple surface, and it is almost always associated with an underlying carcinoma.", "incorrectas": {"A": "Inflammatory breast cancer is caused by dermal lymphatic invasion by tumor cells, producing erythema and peau d'orange over the breast skin generally, not specifically DCIS cells tracking up the ducts into nipple epidermis.", "B": "Phyllodes tumor is a fibroepithelial stromal neoplasm with leaf-like architecture, unrelated to intraductal spread of carcinoma cells to the nipple skin.", "D": "Tubular carcinoma is a well-differentiated subtype of invasive ductal carcinoma forming tubules in a desmoplastic stroma; it is not characterized by intraepidermal spread to the nipple."}}}, {"id": "anking-reproductive-system-pathology-2439", "fuente": "anking", "tema": 8, "anki": "1463442568414", "q": "A woman presents with a red, scaly, ulcerated nipple that has persisted for months. Biopsy shows large cells with clear halos in the epidermis. Which clinical findings classically characterize this condition?", "o": {"A": "Nipple retraction and peau d'orange", "B": "Nipple ulceration and erythema", "C": "Bloody discharge with a mobile mass", "D": "Painless firm axillary lymphadenopathy alone"}, "r": "B", "e": {"correcta": "Paget disease of the nipple classically presents with nipple ulceration and erythema, often resembling eczema, due to malignant Paget cells infiltrating the epidermis; unlike eczema, it is typically unilateral and does not resolve with topical treatment, which should prompt biopsy.", "incorrectas": {"A": "Nipple retraction and peau d'orange are more characteristic of underlying invasive carcinoma causing fibrosis/Cooper ligament traction (retraction) or dermal lymphatic invasion (peau d'orange), not the classic ulceration/erythema of Paget disease.", "C": "Bloody discharge with a mobile mass is more typical of intraductal papilloma, whereas Paget disease presents with nipple skin changes (ulceration, erythema) rather than a discrete mobile mass.", "D": "Painless axillary lymphadenopathy alone is nonspecific and not the classic presenting feature; Paget disease is defined by its visible nipple skin changes."}}}, {"id": "anking-reproductive-system-pathology-2440", "fuente": "anking", "tema": 8, "anki": "1463442577876", "q": "Paget disease of the nipple is almost always associated with which underlying finding?", "o": {"A": "An underlying carcinoma, such as DCIS", "B": "A benign intraductal papilloma", "C": "Isolated eczema with no breast pathology", "D": "Simple fibrocystic change without atypia"}, "r": "A", "e": {"correcta": "Paget disease of the nipple is almost always associated with an underlying carcinoma, most commonly DCIS (and sometimes invasive ductal carcinoma), because the malignant cells found in the nipple epidermis originate from and track along the ducts from a tumor deeper in the breast. Its presence should always prompt a thorough workup for underlying malignancy.", "incorrectas": {"B": "Intraductal papilloma is a benign lesion causing nipple discharge, not the carcinoma that is the hallmark association of Paget disease of the nipple.", "C": "Although Paget disease can be mistaken for eczema clinically, it is not itself benign or isolated skin disease; it virtually always reflects an underlying malignant process in the breast.", "D": "Simple non-atypical fibrocystic change does not carry the malignant potential required to produce the intraepidermal spread seen in Paget disease; an underlying carcinoma is required."}}}, {"id": "anking-reproductive-system-pathology-2441", "fuente": "anking", "tema": 8, "anki": "1463442589618", "q": "What is the most common histologic type of breast cancer, accounting for roughly 75% of cases?", "o": {"A": "Invasive lobular carcinoma", "B": "Invasive ductal carcinoma", "C": "Medullary carcinoma", "D": "Mucinous (colloid) carcinoma"}, "r": "B", "e": {"correcta": "Invasive ductal carcinoma (no special type) is the most common breast malignancy, accounting for approximately 75% of all breast cancers; it arises from the terminal duct lobular unit and typically forms firm, gritty, duct-like structures in a desmoplastic (fibrous) stroma.", "incorrectas": {"A": "Invasive lobular carcinoma is the second most common subtype, notable for its single-file infiltration pattern and loss of E-cadherin, but it accounts for a much smaller percentage of cases than invasive ductal carcinoma.", "C": "Medullary carcinoma is a rare subtype associated with BRCA1 mutations, characterized by fleshy, well-circumscribed tumors with lymphocytic infiltrate, representing only a small fraction of breast cancers.", "D": "Mucinous (colloid) carcinoma is an uncommon, typically better-prognosis subtype seen more often in older women, accounting for only a small minority of breast cancer cases."}}}, {"id": "anking-reproductive-system-pathology-2442", "fuente": "anking", "tema": 8, "anki": "1463442596495", "q": "On physical exam, invasive ductal carcinoma of the breast is classically described as a mass with which characteristic?", "o": {"A": "Soft, fluctuant, and freely mobile", "B": "Firm, fibrous, 'rock-hard' with sharp margins", "C": "Tender and rapidly fluctuating in size with menses", "D": "Cystic and compressible"}, "r": "B", "e": {"correcta": "Invasive ductal carcinoma classically presents as a firm, fibrous, 'rock-hard' mass with sharp, irregular margins on palpation, reflecting the dense desmoplastic (fibrotic) stromal reaction that the tumor incites, in contrast to the soft, mobile texture of benign lesions like fibroadenoma.", "incorrectas": {"A": "A soft, fluctuant, freely mobile mass is more characteristic of a benign lesion such as fibroadenoma or a simple cyst, not the firm, fixed quality typical of invasive carcinoma.", "C": "Tenderness that fluctuates with the menstrual cycle is characteristic of fibroadenoma (an estrogen-sensitive benign tumor), not the fixed, non-cyclical firmness of invasive ductal carcinoma.", "D": "A cystic, compressible mass suggests a simple breast cyst (a fibrocystic change), which is fluid-filled and soft, unlike the solid, rock-hard texture of invasive ductal carcinoma."}}}, {"id": "anking-reproductive-system-pathology-2443", "fuente": "anking", "tema": 8, "anki": "1463442600788", "q": "On histology, invasive ductal carcinoma of the breast classically forms which structures within a desmoplastic stroma?", "o": {"A": "Duct-like structures", "B": "Leaf-like fronds", "C": "Signet-ring cells in single-file rows", "D": "Papillary fronds lined by a double cell layer"}, "r": "A", "e": {"correcta": "Invasive ductal carcinoma classically forms duct-like glandular structures embedded within a dense, fibrous desmoplastic stroma, which is what produces its firm, gritty texture on gross and palpable exam. This 'ductal' pattern is the defining histologic feature distinguishing it from lobular and other special subtypes.", "incorrectas": {"B": "Leaf-like fronds/projections describe the architecture of phyllodes tumor, a fibroepithelial stromal neoplasm, not the glandular duct-forming pattern of invasive ductal carcinoma.", "C": "Signet-ring cells infiltrating in a single-file pattern are characteristic of invasive lobular carcinoma, which lacks E-cadherin and grows in linear cords rather than forming ducts.", "D": "Papillary fronds lined by a double cell layer (epithelial plus myoepithelial) describe benign intraductal papilloma, not the duct-forming pattern of invasive ductal carcinoma, which lacks the myoepithelial layer."}}}, {"id": "anking-reproductive-system-pathology-2444", "fuente": "anking", "tema": 8, "anki": "1463442609662", "q": "Invasive ductal carcinoma of the breast is typically detectable as a mass once it reaches what approximate size, comparing physical exam versus mammography?", "o": {"A": ">1cm by physical exam, >2cm by mammography", "B": ">2cm by physical exam, >1cm by mammography", "C": ">5cm by both physical exam and mammography", "D": ">0.5cm by both physical exam and mammography"}, "r": "B", "e": {"correcta": "Mammography is more sensitive for detecting invasive ductal carcinoma than manual palpation, so tumors are typically detectable by mammography once they exceed about 1 cm, whereas physical exam usually cannot detect a mass until it is larger, greater than about 2 cm; this difference underlies why screening mammography can catch cancers earlier than exam alone.", "incorrectas": {"A": "This reverses the actual relationship; mammography detects smaller masses (>1cm) than physical exam (>2cm), not the other way around, since imaging is more sensitive to subtle density changes than manual palpation.", "C": "A 5cm threshold for both modalities considerably overstates the size needed for detection by either method; mammography and exam can detect much smaller lesions (1cm and 2cm respectively).", "D": "A uniform 0.5cm threshold for both methods is too small, particularly for physical exam, which generally cannot reliably detect masses this size due to normal breast tissue texture variability."}}}, {"id": "anking-reproductive-system-pathology-2445", "fuente": "anking", "tema": 8, "anki": "1463442614906", "q": "On gross pathologic examination, invasive ductal carcinoma of the breast classically shows which infiltrative pattern?", "o": {"A": "Smooth, encapsulated borders", "B": "Stellate (star-like) infiltration", "C": "Cystic, fluid-filled cavities", "D": "Leaf-like papillary fronds"}, "r": "B", "e": {"correcta": "Invasive ductal carcinoma classically shows a stellate, or star-like, pattern of infiltration grossly, reflecting the tumor's irregular, desmoplastic invasion into surrounding fibrofatty breast tissue with radiating fibrous strands, correlating with the spiculated appearance often seen on mammography as well.", "incorrectas": {"A": "Smooth, encapsulated borders describe a benign, well-circumscribed lesion like fibroadenoma, the opposite of the irregular, infiltrative stellate pattern of invasive carcinoma.", "C": "Cystic, fluid-filled cavities describe simple breast cysts (a fibrocystic change), not the firm, infiltrative pattern of invasive ductal carcinoma.", "D": "Leaf-like papillary fronds describe the gross architecture of phyllodes tumor, a distinct fibroepithelial neoplasm, not the stellate infiltrative pattern of ductal carcinoma."}}}, {"id": "anking-reproductive-system-pathology-2446", "fuente": "anking", "tema": 8, "anki": "1463442627581", "q": "Which subtype of invasive ductal carcinoma is characterized by well-formed tubules embedded in a desmoplastic stroma?", "o": {"A": "Medullary carcinoma", "B": "Tubular carcinoma", "C": "Mucinous carcinoma", "D": "Inflammatory carcinoma"}, "r": "B", "e": {"correcta": "Tubular carcinoma is a well-differentiated subtype of invasive ductal carcinoma that forms distinct, well-organized tubular glandular structures set within a desmoplastic (fibrous) stroma, and it is notable for its generally favorable prognosis compared with ordinary invasive ductal carcinoma.", "incorrectas": {"A": "Medullary carcinoma is characterized by sheets of large, poorly differentiated cells with a prominent lymphocytic infiltrate and pushing (not infiltrative) borders, a very different histologic picture from the tubule-forming pattern described.", "C": "Mucinous (colloid) carcinoma is characterized by tumor cells floating in pools of extracellular mucin, not by well-formed tubules in fibrous stroma.", "D": "Inflammatory carcinoma is defined clinically by dermal lymphatic invasion causing skin erythema and peau d'orange, not by a specific glandular histologic pattern like tubule formation."}}}, {"id": "anking-reproductive-system-pathology-2447", "fuente": "anking", "tema": 8, "anki": "1463442637836", "q": "Tubular carcinoma of the breast can be distinguished from normal breast ductal tissue on histology by which two features?", "o": {"A": "Presence of myoepithelial cells and absence of stroma", "B": "Lack of myoepithelial cells and presence of desmoplastic stroma", "C": "Presence of a double epithelial layer and absence of fibrosis", "D": "Increased number of acini with intact basement membrane"}, "r": "B", "e": {"correcta": "Tubular carcinoma is distinguished from normal breast tissue by the absence of the myoepithelial cell layer (since it is a malignant, invasive process rather than a normal duct with an intact two-cell layer) and by the presence of a surrounding desmoplastic stromal reaction, which normal ducts and benign tubules lack.", "incorrectas": {"A": "Normal breast tissue, not tubular carcinoma, contains an intact myoepithelial layer; tubular carcinoma characteristically LACKS myoepithelial cells, and it also has notable desmoplastic stroma rather than an absence of stroma.", "C": "A double epithelial layer (luminal plus myoepithelial) is characteristic of normal ducts and benign papillary lesions, not tubular carcinoma, which lacks the myoepithelial component; tubular carcinoma also shows prominent fibrosis, not its absence.", "D": "An increased number of acini with an intact basement membrane describes sclerosing adenosis, a benign fibrocystic change, not the malignant, myoepithelial-cell-deficient tubules of tubular carcinoma."}}}, {"id": "anking-reproductive-system-pathology-2448", "fuente": "anking", "tema": 8, "anki": "1463442654763", "q": "What is the general prognosis of tubular carcinoma, a subtype of invasive ductal carcinoma of the breast?", "o": {"A": "Poor, with early distant metastasis", "B": "Good, generally better than typical invasive ductal carcinoma", "C": "Uniformly fatal within 1 year", "D": "Identical to inflammatory breast cancer"}, "r": "B", "e": {"correcta": "Tubular carcinoma is a well-differentiated subtype of invasive ductal carcinoma and carries a good prognosis, generally more favorable than typical (no special type) invasive ductal carcinoma, owing to its low-grade histology and lower likelihood of nodal metastasis.", "incorrectas": {"A": "Tubular carcinoma's well-differentiated, low-grade histology corresponds with a favorable clinical course, not early distant metastasis and poor outcomes.", "C": "Far from being uniformly fatal, tubular carcinoma has one of the better prognoses among invasive breast cancer subtypes when treated appropriately.", "D": "Inflammatory breast cancer is a highly aggressive presentation with a poor prognosis due to dermal lymphatic invasion, the opposite of the favorable outlook seen with tubular carcinoma."}}}, {"id": "anking-reproductive-system-pathology-2449", "fuente": "anking", "tema": 8, "anki": "1463442682381", "q": "A 68-year-old woman is found to have an invasive ductal carcinoma of the breast in which malignant cells are seen floating within extracellular pools of extracellular mucin on histology. What is this subtype called?", "o": {"A": "Medullary carcinoma", "B": "Mucinous (colloid) carcinoma", "C": "Tubular carcinoma", "D": "Inflammatory carcinoma"}, "r": "B", "e": {"correcta": "Mucinous (colloid) carcinoma is a subtype of invasive ductal carcinoma characterized by clusters of malignant epithelial cells suspended in large pools of extracellular mucin. It classically occurs in elderly women and carries a relatively good prognosis compared to other invasive ductal carcinomas.", "incorrectas": {"A": "Medullary carcinoma is a distinct subtype featuring sheets of large, high-grade cells with lymphocytic infiltrate and a pushing (not infiltrative) border, without the mucin pools seen in mucinous carcinoma; it is associated with BRCA1 mutations.", "C": "Tubular carcinoma is a well-differentiated subtype forming tubular structures lined by a single layer of epithelial cells, lacking the mucin lakes that define mucinous carcinoma.", "D": "Inflammatory carcinoma presents clinically with erythema and peau d'orange skin changes from dermal lymphatic invasion, not with a specific mucin-pool histology, and carries a poor prognosis, unlike mucinous carcinoma."}}}, {"id": "anking-reproductive-system-pathology-2450", "fuente": "anking", "tema": 8, "anki": "1463442690482", "q": "Compared to other invasive ductal carcinoma subtypes, what is the characteristic prognosis of mucinous (colloid) carcinoma of the breast?", "o": {"A": "Poor, with 50% five-year survival", "B": "Intermediate, similar to typical invasive ductal carcinoma", "C": "Good, relatively favorable prognosis", "D": "Uniformly fatal within one year"}, "r": "C", "e": {"correcta": "Mucinous carcinoma has a good prognosis relative to other invasive ductal carcinomas. The malignant tubules become trapped ('stuck') within thick mucus pools, which limits their ability to invade and spread locally, translating into a more indolent clinical course.", "incorrectas": {"A": "A 50% five-year survival with poor prognosis describes inflammatory carcinoma, which invades dermal lymphatics and presents at an advanced stage, not mucinous carcinoma.", "B": "Mucinous carcinoma is specifically noted for being more favorable than typical invasive ductal carcinoma, not merely equivalent to it.", "D": "Mucinous carcinoma is not uniformly fatal; its defining feature is a comparatively indolent, favorable course, especially in elderly patients."}}}, {"id": "anking-reproductive-system-pathology-2451", "fuente": "anking", "tema": 8, "anki": "1463442696094", "q": "Mucinous (colloid) carcinoma of the breast is classically seen in which patient population?", "o": {"A": "Elderly women, average age 70", "B": "Young women under 30", "C": "Pregnant women in the third trimester", "D": "Men over 60 with BRCA2 mutations"}, "r": "A", "e": {"correcta": "Mucinous carcinoma typically presents in elderly women, with an average age around 70 years, distinguishing its demographic pattern from other invasive ductal carcinoma subtypes that may present at younger ages.", "incorrectas": {"B": "Young women under 30 are more classically associated with medullary carcinoma, a BRCA1-related subtype, rather than mucinous carcinoma which skews toward much older patients.", "C": "Mucinous carcinoma is not specifically linked to pregnancy; inflammatory carcinoma and lactational changes are more relevant considerations during pregnancy and lactation.", "D": "Male breast cancer is strongly associated with BRCA2 mutations and typically presents as invasive ductal carcinoma of no special type, not the mucinous subtype, which is an elderly-female disease."}}}, {"id": "anking-reproductive-system-pathology-2452", "fuente": "anking", "tema": 8, "anki": "1463442712804", "q": "A breast biopsy shows sheets of large, poorly differentiated cells with a prominent lymphocytic infiltrate and a well-circumscribed pushing border. Despite the high-grade cytology, what is the expected prognosis of this medullary carcinoma?", "o": {"A": "Poor, similar to inflammatory carcinoma", "B": "Good, relatively favorable prognosis", "C": "Intermediate, dependent on hormone receptor status", "D": "Uniformly poor due to high nuclear grade"}, "r": "B", "e": {"correcta": "Despite appearing high-grade histologically, medullary carcinoma has a relatively good prognosis. The prominent lymphocytic infiltrate is thought to reflect an active host immune response against the tumor, and its pushing (non-infiltrative) border limits early local spread.", "incorrectas": {"A": "Inflammatory carcinoma has a poor prognosis due to dermal lymphatic invasion and rapid spread, which contrasts with the comparatively favorable course of medullary carcinoma.", "C": "Medullary carcinomas are often triple-negative (ER/PR/HER2 negative) yet still carry a favorable prognosis, so the prognosis is not primarily dictated by hormone receptor status in this subtype.", "D": "High nuclear grade would typically suggest a worse prognosis, but medullary carcinoma is a well-known exception where the immune infiltrate and pushing margin outweigh the cytologic grade."}}}, {"id": "anking-reproductive-system-pathology-2453", "fuente": "anking", "tema": 8, "anki": "1463442730408", "q": "Medullary carcinoma of the breast shows increased incidence in patients carrying mutations in which gene?", "o": {"A": "BRCA2", "B": "TP53", "C": "BRCA1", "D": "HER2/neu"}, "r": "C", "e": {"correcta": "Medullary carcinoma has a notable association with BRCA1 mutations. Patients with hereditary BRCA1-related breast cancer have a higher likelihood of developing this subtype compared to sporadic breast cancer patients.", "incorrectas": {"A": "BRCA2 mutations are more classically linked to male breast cancer and hereditary breast/ovarian cancer generally, but the specific medullary subtype association highlighted in this context is with BRCA1, not BRCA2.", "B": "TP53 mutations (Li-Fraumeni syndrome) increase risk of early-onset breast cancer broadly but are not the gene specifically associated with medullary carcinoma's increased incidence.", "D": "HER2/neu amplification is a receptor overexpression status used to guide treatment (e.g., trastuzumab), not a germline mutation associated with medullary carcinoma risk."}}}, {"id": "anking-reproductive-system-pathology-2454", "fuente": "anking", "tema": 8, "anki": "1463442763210", "q": "A patient presents with erythema, warmth, and skin thickening (peau d'orange) of the breast due to dermal lymphatic invasion by carcinoma. What is the expected prognosis of this inflammatory carcinoma?", "o": {"A": "Excellent, near 100% five-year survival", "B": "Good, similar to mucinous carcinoma", "C": "Poor, approximately 50% five-year survival", "D": "Intermediate, roughly 80% five-year survival"}, "r": "C", "e": {"correcta": "Inflammatory carcinoma carries a poor prognosis, with approximately 50% survival at 5 years. This aggressive subtype involves invasion of the dermal lymphatics, causing the characteristic peau d'orange appearance, and often presents at a locally advanced or metastatic stage.", "incorrectas": {"A": "A near 100% five-year survival is far too optimistic for inflammatory carcinoma, which is one of the most aggressive breast cancer presentations due to lymphatic invasion.", "B": "Mucinous carcinoma has a good prognosis due to indolent growth trapped in mucin pools, the opposite clinical behavior of inflammatory carcinoma, which is aggressive and rapidly spreading.", "D": "An 80% five-year survival is inconsistent with the known aggressive course of inflammatory carcinoma; the classically cited figure is closer to 50%."}}}, {"id": "anking-reproductive-system-pathology-2455", "fuente": "anking", "tema": 8, "anki": "1463442771028", "q": "Inflammatory carcinoma of the breast is often initially mistaken for which other clinical condition due to overlapping erythema and swelling?", "o": {"A": "Fibroadenoma", "B": "Acute mastitis", "C": "Fat necrosis", "D": "Fibrocystic change"}, "r": "B", "e": {"correcta": "Inflammatory carcinoma is frequently mistaken for acute mastitis because both present with breast erythema, warmth, and swelling. A key distinguishing feature is that mastitis typically resolves with antibiotics, while inflammatory carcinoma does not; it may also be confused with Paget disease of the breast.", "incorrectas": {"A": "Fibroadenoma presents as a discrete, mobile, painless breast mass in young women, without the diffuse erythema and skin changes that lead to confusion with inflammatory carcinoma.", "C": "Fat necrosis typically follows trauma and presents as a firm mass with possible skin retraction, but it is not the classic mimicker of inflammatory carcinoma described in this context.", "D": "Fibrocystic change causes lumpy, tender breasts that fluctuate with the menstrual cycle, a benign process distinct from the erythematous, lymphatic-invasive picture of inflammatory carcinoma."}}}, {"id": "anking-reproductive-system-pathology-2456", "fuente": "anking", "tema": 8, "anki": "1463442810974", "q": "Lobular carcinoma in situ (LCIS) is typically discovered in which manner, given that it does not produce a palpable mass or mammographic calcifications?", "o": {"A": "Through nipple discharge cytology", "B": "Incidentally on biopsy performed for another reason", "C": "By palpation during self-breast exam", "D": "By calcifications seen on mammography"}, "r": "B", "e": {"correcta": "LCIS does not form a mass or calcifications, so it is usually found incidentally on a breast biopsy performed for an unrelated finding. This contrasts with ductal carcinoma in situ, which classically presents with detectable calcifications on mammography.", "incorrectas": {"A": "Nipple discharge is not a typical presenting feature of LCIS, which is usually clinically silent and lacks mass effect or ductal involvement causing discharge.", "C": "LCIS does not produce a palpable mass, so it would not be detected by palpation on self or clinical breast exam.", "D": "Unlike DCIS, LCIS does not produce calcifications, making mammographic detection unreliable; this is exactly why it is found incidentally rather than through screening imaging."}}}, {"id": "anking-reproductive-system-pathology-2457", "fuente": "anking", "tema": 8, "anki": "1463442840892", "q": "To reduce the risk of subsequent invasive carcinoma, lobular carcinoma in situ (LCIS) is typically managed with which class of agents?", "o": {"A": "Aromatase inhibitors only", "B": "HER2-targeted monoclonal antibodies", "C": "Anti-estrogenic drugs such as tamoxifen", "D": "Cytotoxic chemotherapy"}, "r": "C", "e": {"correcta": "LCIS is considered a risk factor for future invasive carcinoma (in either breast) rather than a direct precursor lesion, so management centers on risk reduction with anti-estrogenic agents like tamoxifen, which lowers the likelihood of subsequent carcinoma development.", "incorrectas": {"A": "Aromatase inhibitors reduce estrogen production in postmenopausal women and can be used in some risk-reduction contexts, but the classic agent specifically paired with LCIS management is tamoxifen (also useful in premenopausal women).", "B": "HER2-targeted therapy such as trastuzumab is reserved for HER2-amplified invasive carcinomas, not for risk reduction in LCIS, which is not defined by HER2 status.", "D": "LCIS is not treated with cytotoxic chemotherapy, since it is a risk marker rather than an invasive malignancy requiring systemic cytotoxic treatment."}}}, {"id": "anking-reproductive-system-pathology-2458", "fuente": "anking", "tema": 8, "anki": "1463442860197", "q": "Which invasive breast carcinoma subtype is classically described as often bilateral, with multiple lesions occurring in the same location within each breast?", "o": {"A": "Invasive ductal carcinoma, no special type", "B": "Medullary carcinoma", "C": "Invasive lobular carcinoma", "D": "Tubular carcinoma"}, "r": "C", "e": {"correcta": "Invasive lobular carcinoma is notable for being frequently bilateral and multicentric, with multiple lesions arising in similar locations in both breasts, a pattern shared with its in situ precursor, lobular carcinoma in situ.", "incorrectas": {"A": "Invasive ductal carcinoma, no special type, is the most common breast cancer overall but is not particularly known for bilateral, multifocal presentation the way lobular carcinoma is.", "B": "Medullary carcinoma presents as a discrete, well-circumscribed mass and is not characterized by the bilateral, multicentric growth pattern typical of lobular carcinoma.", "D": "Tubular carcinoma is a low-grade, well-differentiated ductal subtype without the classic bilateral, multifocal distribution seen in lobular carcinoma."}}}, {"id": "anking-reproductive-system-pathology-2459", "fuente": "anking", "tema": 8, "anki": "1463442868302", "q": "Invasive lobular carcinoma classically grows in a single-file pattern without gland/duct formation. What underlying molecular defect explains this growth pattern?", "o": {"A": "Loss of E-cadherin expression", "B": "HER2/neu gene amplification", "C": "Loss of BRCA1 function", "D": "Overexpression of estrogen receptor"}, "r": "A", "e": {"correcta": "Invasive lobular carcinoma arises from loss of E-cadherin, a cell adhesion molecule that normally links epithelial cells together. Without E-cadherin, tumor cells fail to cohere or form ducts and instead infiltrate tissue in a characteristic single-file, non-cohesive pattern; cells may show signet-ring morphology.", "incorrectas": {"B": "HER2/neu amplification drives a specific molecular subtype of breast cancer relevant to trastuzumab therapy, but it does not explain the single-file, non-cohesive growth pattern, which is due to E-cadherin loss.", "C": "BRCA1 mutations increase risk of triple-negative and medullary breast carcinomas, but BRCA1 loss is not the mechanism behind the single-file architecture of lobular carcinoma.", "D": "Estrogen receptor overexpression affects hormonal responsiveness and treatment options but is unrelated to the cell adhesion defect responsible for the single-file invasion pattern."}}}, {"id": "anking-reproductive-system-pathology-2460", "fuente": "anking", "tema": 8, "anki": "1463442895605", "q": "What is considered the single most important overall factor in determining the prognosis of breast cancer?", "o": {"A": "Tumor grade on histology", "B": "Estrogen receptor status", "C": "Metastasis", "D": "Patient age at diagnosis"}, "r": "C", "e": {"correcta": "Metastasis is the most important overall determinant of breast cancer prognosis, since distant spread fundamentally changes survival outlook regardless of other tumor characteristics. Once metastatic disease is present, curative treatment becomes far less likely.", "incorrectas": {"A": "Tumor grade contributes to prognosis by describing how abnormal the cells appear, but it does not carry the same overriding prognostic weight as the presence of metastatic spread.", "B": "Estrogen receptor status predicts response to hormonal therapy and has some prognostic value, but it is secondary to the presence of metastasis in determining overall outcome.", "D": "Patient age can influence tumor biology and treatment tolerance, but age itself is not the most important prognostic factor compared to whether the cancer has metastasized."}}}, {"id": "anking-reproductive-system-pathology-2461", "fuente": "anking", "tema": 8, "anki": "1463442900258", "q": "Although distant metastasis is the single most important prognostic factor overall, what is the most clinically useful prognostic factor in early-stage breast cancer, since most patients do not yet have distant metastases?", "o": {"A": "HER2/neu amplification", "B": "Spread to axillary lymph nodes", "C": "Tumor size alone", "D": "Presence of estrogen receptor"}, "r": "B", "e": {"correcta": "Spread to axillary lymph nodes is the most useful prognostic factor in early-stage breast cancer because most patients at this stage do not yet have detectable distant metastasis, making nodal status the earliest and most practical indicator of tumor spread and future behavior.", "incorrectas": {"A": "HER2/neu amplification helps predict response to targeted therapy (trastuzumab) but is not considered as broadly prognostic for early-stage disease as axillary node involvement.", "C": "Tumor size correlates with prognosis to some degree, but nodal status provides more direct information about whether the cancer has already begun to spread, making it more clinically useful.", "D": "Estrogen receptor status guides treatment selection with anti-estrogen therapy but is not the most useful prognostic indicator; that role belongs to axillary lymph node involvement in early-stage disease."}}}, {"id": "anking-reproductive-system-pathology-2462", "fuente": "anking", "tema": 8, "anki": "1463442917303", "q": "Which procedure is used to assess axillary lymph node involvement in breast cancer while minimizing the extent of surgery?", "o": {"A": "Sentinel lymph node biopsy", "B": "Complete axillary lymph node dissection", "C": "Core needle biopsy of the primary tumor", "D": "Positron emission tomography (PET) scan"}, "r": "A", "e": {"correcta": "Sentinel lymph node biopsy is used to assess axillary spread: a radioactive dye or tracer is injected into the breast and taken up by the first ('sentinel') draining lymph node(s), which are then selectively removed and examined, avoiding a full axillary dissection if they are negative.", "incorrectas": {"B": "Complete axillary lymph node dissection removes many lymph nodes and carries higher morbidity (e.g., lymphedema); it is reserved for cases where sentinel nodes are positive, not as the initial assessment method.", "C": "Core needle biopsy of the primary tumor establishes the diagnosis and receptor status of the breast lesion itself, but it does not assess whether cancer has spread to axillary lymph nodes.", "D": "PET scanning can detect distant or bulky nodal disease but is not the standard, sensitive method used specifically to assess microscopic axillary lymph node spread; sentinel node biopsy fills that role."}}}, {"id": "anking-reproductive-system-pathology-2463", "fuente": "anking", "tema": 8, "anki": "1463442924234", "q": "Presence or absence of which three receptors/genes is most important in predicting a breast cancer's response to targeted treatment?", "o": {"A": "TP53, RB1, and APC", "B": "BRCA1, BRCA2, and TP53", "C": "Estrogen receptor, progesterone receptor, and HER2/neu", "D": "E-cadherin, cyclin D1, and p16"}, "r": "C", "e": {"correcta": "Estrogen receptor (ER), progesterone receptor (PR), and HER2/neu status together determine which targeted therapies a breast cancer will respond to: ER/PR positivity predicts response to anti-estrogen agents like tamoxifen, while HER2 amplification predicts response to HER2-targeted agents like trastuzumab.", "incorrectas": {"A": "TP53, RB1, and APC are tumor suppressor genes relevant to various cancers' pathogenesis, but they are not the standard clinical markers used to guide breast cancer treatment selection.", "B": "BRCA1 and BRCA2 are germline mutations that confer hereditary cancer risk and inform screening/prophylactic decisions, but they are not the receptor markers used to predict response to breast cancer-specific targeted therapy.", "D": "E-cadherin loss characterizes lobular carcinoma's growth pattern, and cyclin D1/p16 relate to cell cycle regulation, but none of these are the standard predictive markers for breast cancer treatment response."}}}, {"id": "anking-reproductive-system-pathology-2464", "fuente": "anking", "tema": 8, "anki": "1463442943662", "q": "A breast cancer that is estrogen receptor-positive and progesterone receptor-positive is most likely to respond to which class of therapy?", "o": {"A": "HER2-targeted monoclonal antibodies", "B": "Anti-estrogenic agents such as tamoxifen", "C": "CDK4/6 inhibitors alone as monotherapy", "D": "Broad-spectrum cytotoxic chemotherapy"}, "r": "B", "e": {"correcta": "ER+/PR+ breast cancers depend on estrogen signaling for growth, so they respond well to anti-estrogenic agents such as tamoxifen, a selective estrogen receptor modulator that blocks estrogen's growth-promoting effects on breast tissue. Palbociclib, a CDK4/6 inhibitor, can also be added in combination.", "incorrectas": {"A": "HER2-targeted antibodies like trastuzumab are used for HER2/neu-amplified tumors, a separate molecular category from ER/PR-driven cancers, and would not be the primary choice based solely on ER/PR positivity.", "C": "CDK4/6 inhibitors such as palbociclib are typically used in combination with hormonal therapy for ER+ disease, not as standalone monotherapy independent of anti-estrogen treatment.", "D": "Cytotoxic chemotherapy is not the targeted first-line approach for ER+/PR+ tumors; the hallmark of these hormone receptor-positive cancers is their responsiveness to anti-estrogen therapy specifically."}}}, {"id": "anking-reproductive-system-pathology-2465", "fuente": "anking", "tema": 8, "anki": "1463443062226", "q": "A breast cancer found to be negative for estrogen receptor, progesterone receptor, and HER2/neu ('triple-negative') is associated with what prognosis?", "o": {"A": "Excellent, better than ER+ tumors", "B": "Good, similar to mucinous carcinoma", "C": "Poor prognosis", "D": "No difference in prognosis compared to ER+/HER2+ tumors"}, "r": "C", "e": {"correcta": "Triple-negative breast cancer lacks ER, PR, and HER2/neu expression, meaning it cannot be targeted by anti-estrogen therapy or HER2-directed agents, leaving fewer effective treatment options. This translates into a poor prognosis compared to receptor-positive subtypes.", "incorrectas": {"A": "Triple-negative tumors have a worse, not better, prognosis than ER+ tumors, precisely because they lack the therapeutic targets available for hormone receptor-positive disease.", "B": "Mucinous carcinoma has a favorable prognosis due to its indolent mucin-trapped growth, which is the opposite of the aggressive, poor-prognosis behavior of triple-negative cancer.", "D": "There is a meaningful prognostic difference: ER+/HER2+ tumors have targeted therapy options (anti-estrogens, trastuzumab) that improve outcomes, while triple-negative tumors lack these options and fare worse."}}}, {"id": "anking-reproductive-system-pathology-2466", "fuente": "anking", "tema": 8, "anki": "1463443068528", "q": "Triple-negative breast cancer is most commonly associated with which demographic group?", "o": {"A": "Ashkenazi Jewish women", "B": "African American women", "C": "Elderly Caucasian women", "D": "Asian American women"}, "r": "B", "e": {"correcta": "Triple-negative breast cancer occurs with disproportionately higher frequency in African American women, and it tends to present at a younger age and with a more aggressive course than receptor-positive breast cancers.", "incorrectas": {"A": "Ashkenazi Jewish women have a higher prevalence of BRCA1/BRCA2 founder mutations, which increases hereditary breast cancer risk generally, but triple-negative status specifically is most classically linked with African American women.", "C": "Elderly Caucasian women are more classically associated with mucinous carcinoma, a good-prognosis subtype, rather than the more aggressive triple-negative phenotype.", "D": "Asian American women are not the demographic classically highlighted for increased triple-negative breast cancer incidence in USMLE-style associations."}}}, {"id": "anking-reproductive-system-pathology-2467", "fuente": "anking", "tema": 8, "anki": "1463443071372", "q": "What are the two single most important gene mutations associated with hereditary breast cancer?", "o": {"A": "TP53 and RB1", "B": "BRCA1 and BRCA2", "C": "APC and MLH1", "D": "PTEN and STK11"}, "r": "B", "e": {"correcta": "BRCA1 and BRCA2 are tumor suppressor genes involved in DNA double-strand break repair via homologous recombination; germline mutations in either gene are the two most important and well-established causes of hereditary breast (and ovarian) cancer.", "incorrectas": {"A": "TP53 mutations cause Li-Fraumeni syndrome, which includes increased breast cancer risk among other malignancies, but BRCA1/BRCA2 are the genes most specifically and strongly linked to hereditary breast cancer.", "C": "APC and MLH1 mutations are associated with familial colorectal cancer syndromes (FAP and Lynch syndrome, respectively), not hereditary breast cancer.", "D": "PTEN mutations cause Cowden syndrome and STK11 mutations cause Peutz-Jeghers syndrome; both carry some elevated breast cancer risk, but neither is the single most important hereditary breast cancer gene compared to BRCA1/BRCA2."}}}, {"id": "anking-reproductive-system-pathology-2468", "fuente": "anking", "tema": 8, "anki": "1463443074631", "q": "Women carrying BRCA1 mutations have an increased risk of which combination of cancers?", "o": {"A": "Breast, ovarian, and fallopian tube cancer", "B": "Breast, endometrial, and colorectal cancer", "C": "Breast, thyroid, and gastric cancer", "D": "Breast, cervical, and vulvar cancer"}, "r": "A", "e": {"correcta": "BRCA1 mutations increase the risk of breast, ovarian, and fallopian tube cancers in women, reflecting the gene's role in DNA repair across tissues of Müllerian and breast origin. This risk profile underlies recommendations for prophylactic mastectomy and salpingo-oophorectomy in carriers.", "incorrectas": {"B": "Endometrial and colorectal cancer risk is characteristic of Lynch syndrome (mismatch repair gene mutations), not BRCA1, which is specifically tied to breast, ovarian, and fallopian tube cancer.", "C": "Thyroid and gastric cancer are not part of the classic BRCA1-associated cancer spectrum; those associations belong to other hereditary cancer syndromes such as Cowden syndrome.", "D": "Cervical and vulvar cancers are primarily linked to HPV infection rather than BRCA1 mutations, which instead predispose to breast, ovarian, and fallopian tube malignancies."}}}, {"id": "anking-reproductive-system-pathology-2469", "fuente": "anking", "tema": 8, "anki": "1463443078086", "q": "A mutation in which gene is most strongly associated with breast carcinoma occurring in male patients?", "o": {"A": "BRCA1", "B": "TP53", "C": "BRCA2", "D": "PTEN"}, "r": "C", "e": {"correcta": "BRCA2 mutations are the gene mutation most strongly associated with male breast cancer. While both BRCA1 and BRCA2 raise female breast cancer risk substantially, BRCA2 carries a comparatively higher relative risk for breast carcinoma in men.", "incorrectas": {"A": "BRCA1 mutations are strongly linked to female breast, ovarian, and fallopian tube cancer and to medullary carcinoma subtype, but BRCA2 is the mutation classically emphasized for male breast cancer risk.", "B": "TP53 mutations (Li-Fraumeni syndrome) broadly increase cancer risk across many organs but are not the specific gene most associated with male breast cancer in standard associations.", "D": "PTEN mutations (Cowden syndrome) increase risk of several cancers including breast cancer in women, but are not the classic gene tied to male breast cancer, which is BRCA2."}}}, {"id": "anking-reproductive-system-pathology-2470", "fuente": "anking", "tema": 8, "anki": "1463443081183", "q": "A woman undergoes bilateral prophylactic mastectomy to reduce breast cancer risk. Can she still develop breast cancer afterward?", "o": {"A": "No, mastectomy completely eliminates all future risk", "B": "Yes, because a small amount of breast tissue always remains", "C": "No, unless she also carries a BRCA mutation", "D": "Yes, but only if she later becomes pregnant"}, "r": "B", "e": {"correcta": "Even after prophylactic mastectomy, a small amount of breast tissue inevitably remains (e.g., along the chest wall or axillary tail), so there remains a small residual risk of developing breast cancer from that leftover tissue, though the risk is substantially reduced.", "incorrectas": {"A": "Mastectomy dramatically reduces but does not completely eliminate risk, because surgeons cannot remove 100% of breast tissue, leaving a small residual chance of malignancy.", "C": "The residual risk after mastectomy applies regardless of BRCA mutation status; it exists simply because some breast tissue remains, not specifically because of an underlying BRCA mutation.", "D": "Residual cancer risk after mastectomy is related to leftover breast tissue itself, not conditioned specifically on a subsequent pregnancy."}}}, {"id": "anking-reproductive-system-pathology-2471", "fuente": "anking", "tema": 8, "anki": "1463443083596", "q": "Male breast cancer most commonly presents as which type of finding in older men?", "o": {"A": "Bilateral diffuse breast enlargement", "B": "A subareolar mass, sometimes with nipple discharge", "C": "Painful axillary lymphadenopathy without a breast mass", "D": "Peau d'orange skin changes without a discrete mass"}, "r": "B", "e": {"correcta": "Male breast cancer classically presents as a subareolar mass in an older man, and it may be accompanied by nipple discharge. Because men have minimal breast tissue concentrated near the nipple-areolar complex, tumors tend to arise in this subareolar location.", "incorrectas": {"A": "Bilateral diffuse enlargement is more suggestive of gynecomastia, a benign condition from hormonal imbalance, rather than the discrete subareolar mass typical of male breast carcinoma.", "C": "Isolated axillary lymphadenopathy without an identifiable breast mass is not the classic initial presentation; a palpable subareolar mass is the more typical finding.", "D": "Peau d'orange changes without a mass describe inflammatory carcinoma's presentation in women, not the typical discrete subareolar mass seen in male breast cancer."}}}, {"id": "anking-reproductive-system-pathology-2472", "fuente": "anking", "tema": 8, "anki": "1463443090416", "q": "Because male breast tissue develops very few lobules, which histologic type of breast cancer is most common in men?", "o": {"A": "Invasive lobular carcinoma", "B": "Lobular carcinoma in situ", "C": "Invasive ductal carcinoma", "D": "Mucinous carcinoma"}, "r": "C", "e": {"correcta": "Invasive ductal carcinoma is the most common type of breast cancer in men, since male breast tissue contains ducts but develops very few lobules, making lobular-origin cancers rare in this population.", "incorrectas": {"A": "Invasive lobular carcinoma arises from lobular epithelium, which is essentially absent in the underdeveloped male breast, making this subtype rare in men compared to ductal carcinoma.", "B": "Lobular carcinoma in situ likewise requires lobular tissue to arise from, which men largely lack, making it an uncommon finding in male breast pathology.", "D": "Mucinous carcinoma is a specific, less common ductal subtype seen classically in elderly women; it is not the predominant type of breast cancer diagnosed in men."}}}, {"id": "anking-reproductive-system-pathology-2473", "fuente": "anking", "tema": 8, "anki": "1463443100523", "q": "Male breast cancer risk is increased by a mutation in BRCA2 and by which chromosomal disorder characterized by an extra X chromosome (47,XXY)?", "o": {"A": "Turner syndrome", "B": "Klinefelter syndrome", "C": "Down syndrome", "D": "XYY syndrome"}, "r": "B", "e": {"correcta": "Klinefelter syndrome (47,XXY) increases the risk of male breast cancer, likely due to the relatively increased estrogen-to-testosterone ratio in these patients, along with the well-established contribution of BRCA2 mutations.", "incorrectas": {"A": "Turner syndrome (45,X) affects females, causing ovarian dysgenesis and short stature; it is not relevant to male breast cancer risk, which requires a male chromosomal complement.", "C": "Down syndrome (trisomy 21) is associated with increased risk of leukemia and Alzheimer disease, not with male breast cancer risk.", "D": "XYY syndrome is generally associated with tall stature and behavioral considerations, but it is not the sex chromosome disorder classically linked to increased male breast cancer risk; that association belongs to Klinefelter syndrome."}}}, {"id": "anking-reproductive-system-embryology-2474", "fuente": "anking", "tema": 33, "anki": "1463520595414", "q": "At approximately which week of gestation does the external genitalia of a developing fetus begin to show distinguishable male or female characteristics?", "o": {"A": "Week 4", "B": "Week 10", "C": "Week 16", "D": "Week 20"}, "r": "B", "e": {"correcta": "External genitalia begin to show male or female phenotypic characteristics by approximately week 10 of gestation, following earlier gonadal differentiation and hormone-driven development of the genital tubercle, folds, and swellings into sex-specific structures.", "incorrectas": {"A": "Week 4 is far too early; at this stage the embryo is still forming basic body structures, and the genital ridge/bipotential gonad has only just begun to form, well before external sex differences are visible.", "C": "By week 16, genitalia are already differentiated and often visible on ultrasound, but the process of distinguishable differentiation is described as beginning earlier, around week 10.", "D": "Week 20 is well past the period when genitalia first become distinguishable; differentiation is already established by this later gestational age."}}}, {"id": "anking-reproductive-system-embryology-2475", "fuente": "anking", "tema": 33, "anki": "1463520710247", "q": "Twins that arise from two separate eggs, each fertilized by a different sperm, are known by what term?", "o": {"A": "Monozygotic twins", "B": "Conjoined twins", "C": "Dizygotic (fraternal) twins", "D": "Chimeric twins"}, "r": "C", "e": {"correcta": "Dizygotic (fraternal) twins result from the independent fertilization of two separate eggs by two different sperm, meaning each twin has a distinct genetic makeup, similar to any other pair of siblings, just conceived at the same time.", "incorrectas": {"A": "Monozygotic twins arise from a single fertilized egg (one sperm and one egg) that splits into two embryos, making them genetically identical, unlike dizygotic twins which come from two separate fertilization events.", "B": "Conjoined twins result from incomplete splitting of a single fertilized egg very late after the embryonic disc has formed, a monozygotic phenomenon, not from two separately fertilized eggs.", "D": "Chimeric twins are not a standard classification of twinning based on fertilization; this term does not describe the dizygotic (two separate eggs, two separate sperm) mechanism being tested here."}}}, {"id": "anking-reproductive-system-embryology-2476", "fuente": "anking", "tema": 33, "anki": "1463526102619", "q": "Because dizygotic (fraternal) twins develop from two separately fertilized eggs that implant independently, what is the expected chorionicity and amnionicity of their placentas and sacs?", "o": {"A": "1 shared amnion and 1 shared chorion", "B": "2 separate amnions and 1 shared chorion", "C": "2 separate amniotic sacs and 2 separate placentas (chorions)", "D": "1 shared amnion and 2 separate chorions"}, "r": "C", "e": {"correcta": "Dizygotic twins each develop from an independently fertilized egg that implants separately, so each twin forms its own complete set of membranes: 2 separate amniotic sacs and 2 separate chorions/placentas, regardless of whether the placentas later fuse anatomically.", "incorrectas": {"A": "A single shared amnion and shared chorion describes a very late-splitting monozygotic twin pregnancy, not the always-separate membrane pattern of dizygotic twins.", "B": "Sharing a single chorion while having separate amnions is a pattern seen in monozygotic twins that split at the morula stage, not in dizygotic twins, who always have entirely separate membranes.", "D": "A shared amnion with separate chorions is not a biologically consistent or standard twinning pattern; dizygotic twins have fully separate amnions and chorions from the start."}}}, {"id": "anking-reproductive-system-embryology-2477", "fuente": "anking", "tema": 33, "anki": "1463526113458", "q": "Twins arising from a single fertilized egg (one egg and one sperm) that subsequently splits early in pregnancy are known by what term?", "o": {"A": "Dizygotic (fraternal) twins", "B": "Monozygotic (identical) twins", "C": "Superfetation twins", "D": "Heterokaryotic twins"}, "r": "B", "e": {"correcta": "Monozygotic (identical) twins arise from a single fertilized zygote that splits into two separate embryos early in development, resulting in twins with identical genetic material, in contrast to dizygotic twins formed from two separate fertilization events.", "incorrectas": {"A": "Dizygotic twins arise from two separate eggs each fertilized by a different sperm, producing genetically distinct siblings, the opposite mechanism from the single-zygote splitting that defines monozygotic twins.", "C": "Superfetation refers to a second, later fertilization occurring during an already established pregnancy, an exceedingly rare and distinct phenomenon, not the mechanism of splitting a single zygote.", "D": "Heterokaryotic twins is not a standard embryology term used to describe twinning from a single fertilized egg; the correct term for this process is monozygotic twinning."}}}, {"id": "anking-reproductive-system-embryology-2478", "fuente": "anking", "tema": 33, "anki": "1463526118760", "q": "If a developing monozygotic embryo splits at the 2-cell stage (0-4 days after fertilization), what chorionicity and amnionicity will the resulting twins have?", "o": {"A": "Monochorionic, monoamniotic", "B": "Monochorionic, diamniotic", "C": "Dichorionic, diamniotic", "D": "Dichorionic, monoamniotic"}, "r": "C", "e": {"correcta": "Splitting at the 2-cell stage (0-4 days, before the chorion or amnion has formed) results in dichorionic, diamniotic twins, since each resulting embryo independently develops its own separate chorion and amnion, mimicking a dizygotic pregnancy anatomically. This is remembered by the mnemonic SCAB: Separate Chorion And amnion at this earliest split.", "incorrectas": {"A": "Monochorionic, monoamniotic twinning occurs with a much later split (8-13 days, after both the chorion and amnion have formed), not with the earliest 0-4 day split described here.", "B": "Monochorionic, diamniotic twinning results from splitting at the morula/early blastocyst stage (4-8 days), after the chorion has formed but before the amnion has, which is later than the 0-4 day split in this question.", "D": "Dichorionic, monoamniotic is not an embryologically consistent combination for twinning splits; amnion formation always occurs after chorion formation, so a shared amnion with separate chorions does not occur."}}}, {"id": "anking-reproductive-system-embryology-2479", "fuente": "anking", "tema": 33, "anki": "1463526124762", "q": "If a developing monozygotic embryo splits during the morula stage (4-8 days after fertilization), what chorionicity and amnionicity will the resulting twins have?", "o": {"A": "Dichorionic, diamniotic", "B": "Monochorionic, diamniotic", "C": "Monochorionic, monoamniotic", "D": "Dichorionic, monoamniotic"}, "r": "B", "e": {"correcta": "A split during the morula stage (4-8 days), after the chorion has formed but before the amnion forms, produces monochorionic, diamniotic twins. This is the most common pattern of monozygotic twinning, accounting for about 75% of cases, occurring around the time the blastocyst's inner cell mass (embryoblast) and outer trophoblast are established.", "incorrectas": {"A": "Dichorionic, diamniotic twinning occurs when splitting happens even earlier, at the 2-cell stage (0-4 days), before the chorion has formed, which is earlier than the morula-stage split described here.", "C": "Monochorionic, monoamniotic twinning requires an even later split (8-13 days), after both chorion and amnion have already formed, which is later than the morula-stage timing in this question.", "D": "Dichorionic, monoamniotic is not an embryologically valid combination, since the chorion forms before the amnion; a shared amnion with separate chorions does not occur in twinning."}}}, {"id": "anking-reproductive-system-embryology-2480", "fuente": "anking", "tema": 33, "anki": "1463526131353", "q": "If a developing monozygotic embryo splits during the blastocyst stage (8-12 days after fertilization), what chorionicity and amnionicity will the resulting twins have, and why does this carry high fetal risk?", "o": {"A": "Dichorionic, diamniotic; low risk of complications", "B": "Monochorionic, diamniotic; moderate risk", "C": "Monochorionic, monoamniotic; high risk of umbilical cord entanglement", "D": "Dichorionic, monoamniotic; high risk of conjoined twinning"}, "r": "C", "e": {"correcta": "Splitting during the blastocyst stage (8-12 days), after both the chorion (forms around day 4) and amnion (forms around day 8) have already developed, results in monochorionic, monoamniotic twins. Because both fetuses share a single amniotic sac, there is a high risk of umbilical cord entanglement and consequent high fetal fatality, and this pattern occurs rarely.", "incorrectas": {"A": "Dichorionic, diamniotic twinning with low complication risk results from a much earlier split (0-4 days), before the chorion has even formed, not from the 8-12 day blastocyst-stage split described here.", "B": "Monochorionic, diamniotic twinning occurs with an earlier split at the morula stage (4-8 days), after the chorion but before the amnion has formed; this is a distinct, more common, lower-risk pattern than the blastocyst-stage split.", "D": "Dichorionic, monoamniotic is not an embryologically valid outcome, and conjoined twinning results from an even later split (after 13 days, once the embryonic disc has formed), not the 8-12 day blastocyst-stage split."}}}, {"id": "anking-reproductive-system-embryology-2481", "fuente": "anking", "tema": 33, "anki": "1463526137463", "q": "If a monozygotic embryo splits after the embryonic disc has already formed (greater than 13 days after fertilization), what is the resulting outcome for the twins?", "o": {"A": "Dichorionic, diamniotic twins", "B": "Monochorionic, diamniotic twins", "C": "Conjoined twins", "D": "Superfetation"}, "r": "C", "e": {"correcta": "A split occurring after day 13, once the embryonic disc has already formed, results in conjoined twins, since the splitting is incomplete and the twins share a single body to varying degrees. These twins are also monochorionic and monoamniotic, reflecting the very late timing of the split.", "incorrectas": {"A": "Dichorionic, diamniotic twinning occurs with the earliest possible split (0-4 days), long before the embryonic disc forms, the opposite extreme from the very late split producing conjoined twins.", "B": "Monochorionic, diamniotic twinning results from a morula-stage split (4-8 days), well before the embryonic disc forms and far earlier than the greater-than-13-day timing that produces conjoined twins.", "D": "Superfetation refers to a second, separate fertilization event occurring during an already established pregnancy, an entirely different and exceedingly rare phenomenon unrelated to late splitting of a single zygote."}}}, {"id": "anking-reproductive-system-embryology-2482", "fuente": "anking", "tema": 33, "anki": "1463526145718", "q": "Which umbilical vessel carries oxygenated blood from the placenta to the fetus?", "o": {"A": "Umbilical artery", "B": "Umbilical vein", "C": "Ductus arteriosus", "D": "Ductus venosus"}, "r": "B", "e": {"correcta": "The umbilical vein carries oxygenated, nutrient-rich blood from the placenta to the fetus, an exception to the general rule that veins carry deoxygenated blood, because it is transporting blood that has just been oxygenated at the placental interface.", "incorrectas": {"A": "The umbilical arteries (paired) carry deoxygenated blood away from the fetus back to the placenta, the opposite direction and oxygenation status of the umbilical vein.", "C": "The ductus arteriosus connects the pulmonary artery to the aorta in fetal circulation, shunting blood away from the fetal lungs, but it is not the vessel that transports oxygenated blood from the placenta.", "D": "The ductus venosus is a fetal shunt that allows oxygenated blood from the umbilical vein to bypass the liver and drain into the IVC, but it is a shunt downstream of the umbilical vein, not the vessel from the placenta itself."}}}, {"id": "anking-reproductive-system-embryology-2483", "fuente": "anking", "tema": 33, "anki": "1463526153463", "q": "Oxygenated blood in the umbilical vein drains into the fetal inferior vena cava (IVC) through the liver or through which fetal shunt that bypasses hepatic circulation?", "o": {"A": "Foramen ovale", "B": "Ductus arteriosus", "C": "Ductus venosus", "D": "Umbilical artery"}, "r": "C", "e": {"correcta": "The ductus venosus is a fetal vascular shunt that allows oxygenated blood from the umbilical vein to bypass the hepatic sinusoids and drain directly into the IVC, complementing the pathway where some blood also passes through the liver before reaching the IVC.", "incorrectas": {"A": "The foramen ovale is a separate fetal shunt located in the interatrial septum that allows blood to bypass the pulmonary circulation by moving from the right atrium to the left atrium, not a shunt bypassing the liver from the umbilical vein.", "B": "The ductus arteriosus connects the pulmonary artery to the aorta, diverting blood away from the fetal lungs; it plays no role in routing umbilical venous blood around the liver.", "D": "The umbilical artery carries deoxygenated blood from the fetus to the placenta, functioning in the opposite direction and vessel type from the umbilical vein and its hepatic bypass shunt."}}}, {"id": "anking-reproductive-system-embryology-2484", "fuente": "anking", "tema": 33, "anki": "1463526209818", "q": "Which fetal vessels return deoxygenated blood from the fetus to the placenta?", "o": {"A": "Umbilical vein", "B": "Umbilical arteries", "C": "Ductus venosus", "D": "Ductus arteriosus"}, "r": "B", "e": {"correcta": "The two umbilical arteries arise from the fetal internal iliac arteries and carry deoxygenated, waste-laden blood from the fetus back to the placenta for gas and waste exchange with maternal blood.", "incorrectas": {"A": "The single umbilical vein carries oxygenated, nutrient-rich blood from the placenta to the fetus, the opposite direction and oxygenation state of the umbilical arteries.", "C": "The ductus venosus is a fetal shunt that carries oxygenated blood from the umbilical vein past the liver directly into the IVC, not a vessel connecting the fetus to the placenta.", "D": "The ductus arteriosus shunts blood from the pulmonary artery to the aorta to bypass the fetal lungs; it plays no role in fetal-placental exchange."}}}, {"id": "anking-reproductive-system-embryology-2485", "fuente": "anking", "tema": 33, "anki": "1463526225721", "q": "How many umbilical veins and umbilical arteries are normally present in the umbilical cord?", "o": {"A": "Two veins and one artery", "B": "Two veins and two arteries", "C": "One vein and two arteries", "D": "One vein and one artery"}, "r": "C", "e": {"correcta": "The normal umbilical cord contains one umbilical vein (carrying oxygenated blood to the fetus) and two umbilical arteries (carrying deoxygenated blood back to the placenta), for a total of three vessels.", "incorrectas": {"A": "Two veins is incorrect; only a single umbilical vein persists after early development, as the right umbilical vein normally regresses.", "B": "Two veins and two arteries would total four vessels, more than the normal three-vessel cord.", "D": "A single umbilical artery (rather than two) defines the clinically important anomaly of single umbilical artery, not the normal anatomy."}}}, {"id": "anking-reproductive-system-embryology-2486", "fuente": "anking", "tema": 33, "anki": "1463526235140", "q": "The presence of a single umbilical artery (instead of the normal two) is associated with an increased risk of what?", "o": {"A": "Congenital and chromosomal anomalies", "B": "Polyhydramnios only", "C": "Postterm pregnancy", "D": "Placenta previa"}, "r": "A", "e": {"correcta": "A single umbilical artery, found in about 1% of pregnancies, is associated with an increased risk of congenital malformations (renal, cardiac) and chromosomal anomalies, prompting a detailed anatomy ultrasound when identified.", "incorrectas": {"B": "Polyhydramnios is linked to conditions impairing fetal swallowing (e.g., esophageal/duodenal atresia) or increased fetal urination, not specifically to umbilical vessel number.", "C": "Postterm pregnancy relates to gestational duration beyond 42 weeks and has no established link to umbilical artery number.", "D": "Placenta previa is an abnormality of placental implantation location over the cervix, unrelated to umbilical vessel count."}}}, {"id": "anking-reproductive-system-embryology-2487", "fuente": "anking", "tema": 33, "anki": "1463526248482", "q": "During the 3rd week of development, the yolk sac gives rise to which structure that extends into the urogenital sinus?", "o": {"A": "Vitelline duct", "B": "Notochord", "C": "Allantois", "D": "Cloaca"}, "r": "C", "e": {"correcta": "During the 3rd week, the yolk sac forms the allantois, which extends into the urogenital sinus and later becomes the urachus, a fibrous remnant connecting the bladder to the umbilicus.", "incorrectas": {"A": "The vitelline duct also arises from the yolk sac but connects it to the midgut lumen, and it does not extend into the urogenital sinus.", "B": "The notochord is a distinct axial structure derived from the primitive streak, not from the yolk sac, and it induces neural tube formation rather than contributing to the urogenital sinus.", "D": "The cloaca is the common terminal hindgut chamber that is later divided by the urorectal septum into the urogenital sinus and anorectal canal; it is not a yolk sac derivative."}}}, {"id": "anking-gastrointestinal-anatomy-2488", "fuente": "anking", "tema": 38, "anki": "1463526258452", "q": "What structure connects the embryonic yolk sac to the midgut lumen during development?", "o": {"A": "Allantois", "B": "Urachus", "C": "Vitelline duct", "D": "Ductus venosus"}, "r": "C", "e": {"correcta": "The vitelline duct (omphalomesenteric duct) connects the yolk sac to the midgut lumen; its persistence or partial closure underlies conditions such as Meckel diverticulum and vitelline fistula.", "incorrectas": {"A": "The allantois extends from the yolk sac into the urogenital sinus and gives rise to umbilical vessels and the urachus, not the connection to the midgut.", "B": "The urachus is the fibrous remnant of the allantois connecting the bladder to the umbilicus, unrelated to the midgut connection.", "D": "The ductus venosus is a fetal circulatory shunt directing oxygenated blood past the liver, structurally and functionally unrelated to the yolk sac-midgut connection."}}}, {"id": "anking-gastrointestinal-anatomy-2489", "fuente": "anking", "tema": 38, "anki": "1463526262145", "q": "The vitelline duct (omphalomesenteric duct) is normally obliterated during which week of development?", "o": {"A": "3rd week", "B": "5th week", "C": "7th week", "D": "10th week"}, "r": "C", "e": {"correcta": "The vitelline duct normally undergoes obliteration during the 7th week of development; failure of complete closure can lead to a spectrum of anomalies including Meckel diverticulum, vitelline cyst, or vitelline fistula.", "incorrectas": {"B": "The 3rd week is when the allantois forms from the yolk sac, an earlier and distinct embryologic event from vitelline duct obliteration.", "A": "The 5th week is too early; the vitelline duct is still patent and connecting the yolk sac to the midgut at this stage.", "D": "The 10th week is after the vitelline duct has already normally closed; by this point midgut herniation and rotation are also completing."}}}, {"id": "anking-gastrointestinal-anatomy-2490", "fuente": "anking", "tema": 38, "anki": "1463526273142", "q": "Incomplete closure of the vitelline duct, with the patent portion attached to the ileum, results in what congenital anomaly?", "o": {"A": "Meckel diverticulum", "B": "Hirschsprung disease", "C": "Malrotation", "D": "Omphalocele"}, "r": "A", "e": {"correcta": "Partial closure of the vitelline duct leaves a true diverticulum (containing all gut wall layers) attached to the antimesenteric border of the ileum, known as Meckel diverticulum, which can contain ectopic gastric or pancreatic tissue and cause painless GI bleeding or intussusception.", "incorrectas": {"B": "Hirschsprung disease results from failure of neural crest cell migration into the distal colon, causing aganglionosis, unrelated to vitelline duct closure.", "C": "Malrotation results from abnormal rotation of the midgut around the superior mesenteric artery during physiologic herniation, a separate embryologic process from vitelline duct obliteration.", "D": "Omphalocele is a persistent herniation of abdominal contents into the umbilical cord covered by peritoneum, caused by failure of intestines to return to the abdominal cavity, not by vitelline duct remnants."}}}, {"id": "anking-reproductive-system-anatomy-2491", "fuente": "anking", "tema": 34, "anki": "1463526291976", "q": "What vasculature runs within the suspensory ligament of the ovary (infundibulopelvic ligament)?", "o": {"A": "Uterine vessels", "B": "Ovarian vessels", "C": "Internal pudendal vessels", "D": "Vaginal vessels"}, "r": "B", "e": {"correcta": "The suspensory ligament of the ovary carries the ovarian vessels (artery arising from the abdominal aorta at L1/L2), along with nerves and lymphatics, from the pelvic wall to the ovary; it must be ligated during oophorectomy to control bleeding.", "incorrectas": {"A": "The uterine vessels travel within the cardinal (transverse cervical) ligament at the base of the broad ligament, not the suspensory ligament of the ovary.", "C": "The internal pudendal vessels supply the perineum and travel through the pudendal canal (Alcock's canal), unrelated to the ovarian suspensory ligament.", "D": "The vaginal vessels arise from branches of the internal iliac system supplying the vagina, not contained within the infundibulopelvic ligament."}}}, {"id": "anking-reproductive-system-anatomy-2492", "fuente": "anking", "tema": 34, "anki": "1463526337153", "q": "Which female structure, a derivative of the gubernaculum, travels through the inguinal canal to anchor the uterine fundus to the labia majora?", "o": {"A": "Suspensory ligament of the ovary", "B": "Cardinal ligament", "C": "Round ligament of the uterus", "D": "Broad ligament"}, "r": "C", "e": {"correcta": "The round ligament of the uterus is the remnant of the gubernaculum in females; it travels through the inguinal canal (alongside the artery of Sampson) to anchor the uterine fundus to the labia majora, and can be a site of indirect inguinal hernia or referred round ligament pain in pregnancy.", "incorrectas": {"A": "The suspensory ligament of the ovary carries the ovarian vessels from the pelvic wall to the ovary and is not derived from the gubernaculum, nor does it pass through the inguinal canal.", "B": "The cardinal ligament extends from the cervix to the lateral pelvic wall, carrying the uterine vessels, and does not traverse the inguinal canal.", "D": "The broad ligament is a peritoneal fold draping over the uterus, tubes, and ovaries; it is not a gubernaculum derivative and does not pass through the inguinal canal."}}}, {"id": "anking-reproductive-system-anatomy-2493", "fuente": "anking", "tema": 34, "anki": "1463526348352", "q": "Which three folds make up the broad ligament of the uterus?", "o": {"A": "Mesosalpinx, mesometrium, and mesovarium", "B": "Mesentery, mesocolon, and mesoappendix", "C": "Round ligament, cardinal ligament, and uterosacral ligament", "D": "Suspensory ligament, ovarian ligament, and cardinal ligament"}, "r": "A", "e": {"correcta": "The broad ligament is a peritoneal fold with three components: the mesosalpinx (covering the fallopian tubes), the mesometrium (covering the uterine body), and the mesovarium (covering the ovaries), collectively supporting these pelvic organs.", "incorrectas": {"B": "The mesentery, mesocolon, and mesoappendix are peritoneal folds suspending the small intestine, colon, and appendix, part of the GI tract rather than the female reproductive tract.", "C": "The round, cardinal, and uterosacral ligaments are separate discrete ligaments (fibrous condensations) that support the uterus, distinct from the broad ligament's three peritoneal folds.", "D": "The suspensory ligament of the ovary and ovarian ligament are distinct structures from the broad ligament's folds, and the cardinal ligament is a separate condensation at the base of the broad ligament, not one of its three named folds."}}}, {"id": "anking-reproductive-system-anatomy-2494", "fuente": "anking", "tema": 34, "anki": "1463526360408", "q": "What is the fibrous capsule that surrounds the seminiferous tubules within the testis?", "o": {"A": "Dartos fascia", "B": "Tunica vaginalis", "C": "Cremaster fascia", "D": "Tunica albuginea"}, "r": "D", "e": {"correcta": "The tunica albuginea is the tough fibrous capsule that directly surrounds and compartmentalizes the seminiferous tubules within the testis, providing structural support to the testicular parenchyma.", "incorrectas": {"A": "The dartos fascia is a layer of smooth muscle within the scrotal wall that helps regulate testicular temperature by wrinkling the scrotal skin, external to the testis itself.", "B": "The tunica vaginalis is the outermost serous covering derived from peritoneum that surrounds the testis, external to the tunica albuginea, and its involvement defines a hydrocele.", "C": "The cremaster fascia (with cremaster muscle) is derived from the internal oblique muscle and surrounds the spermatic cord, functioning in the cremasteric reflex, not directly encapsulating the seminiferous tubules."}}}, {"id": "anking-reproductive-system-anatomy-2495", "fuente": "anking", "tema": 34, "anki": "1463526370145", "q": "Injury to the posterior membranous urethra, as from a pelvic fracture, classically causes urine to leak into which space?", "o": {"A": "Superficial perineal space", "B": "Retropubic space", "C": "Peritoneal cavity", "D": "Ischiorectal fossa"}, "r": "B", "e": {"correcta": "The posterior membranous urethra lies above the urogenital diaphragm, so injury (typically from pelvic fracture) causes urine to extravasate superiorly into the retropubic (space of Retzius) space rather than into the perineum.", "incorrectas": {"A": "The superficial perineal space is where urine leaks with anterior (penile/bulbar) urethral injuries below Buck's fascia, not posterior membranous urethral injuries.", "C": "The peritoneal cavity is not the typical route of extravasation for extraperitoneal urethral injury; the retropubic space is extraperitoneal and anatomically distinct.", "D": "The ischiorectal fossa is a fat-filled space lateral to the anal canal involved in perianal abscesses, not a typical site of urine extravasation from urethral trauma."}}}, {"id": "anking-reproductive-system-anatomy-2496", "fuente": "anking", "tema": 34, "anki": "1463526376740", "q": "Injury to the anterior penile urethra, such as from a perineal straddle injury, causes urine to leak beneath which fascial layer?", "o": {"A": "Colles' fascia", "B": "Buck's fascia", "C": "Camper's fascia", "D": "Dartos fascia"}, "r": "B", "e": {"correcta": "The anterior (penile) urethra is enclosed by the deep fascia of Buck; a straddle injury tears the urethra beneath this fascia, and if Buck's fascia itself is torn, urine escapes further into the superficial perineal space (bounded by Colles' fascia).", "incorrectas": {"A": "Colles' fascia is the deep membranous layer of the superficial perineal space that limits further spread of extravasated urine and blood once it has already breached Buck's fascia, not the layer initially torn.", "C": "Camper's fascia is the superficial fatty layer of the anterior abdominal wall, unrelated to penile urethral anatomy.", "D": "The dartos fascia is a smooth-muscle-containing layer of the scrotum and penile skin, continuous with Colles' fascia, but it is not the layer classically named in anterior urethral injury."}}}, {"id": "anking-reproductive-system-anatomy-2497", "fuente": "anking", "tema": 34, "anki": "1463526385372", "q": "Which two conditions are associated with increased testicular temperature, leading to decreased sperm production and decreased inhibin B?", "o": {"A": "Varicocele and cryptorchidism", "B": "Hydrocele and spermatocele", "C": "Epididymitis and orchitis", "D": "Testicular torsion and hypospadias"}, "r": "A", "e": {"correcta": "Varicocele (dilation of the pampiniform plexus) and cryptorchidism (undescended testis) both raise scrotal/testicular temperature above the optimal range for spermatogenesis, impairing Sertoli cell function and reducing sperm production and inhibin B secretion.", "incorrectas": {"B": "Hydrocele (fluid in the tunica vaginalis) and spermatocele (cyst of the epididymis) are fluid collections that do not characteristically raise testicular temperature or impair spermatogenesis in the same way.", "C": "Epididymitis and orchitis are inflammatory/infectious conditions that can impair fertility through direct tissue damage and obstruction, not primarily through a thermoregulatory mechanism.", "D": "Testicular torsion causes acute ischemia (a surgical emergency) and hypospadias is a congenital urethral malposition; neither is defined by chronic testicular hyperthermia."}}}, {"id": "anking-reproductive-system-embryology-2498", "fuente": "anking", "tema": 33, "anki": "1463526393047", "q": "Which condition involves excess amniotic fluid and may be associated with fetal malformations such as esophageal or duodenal atresia due to impaired swallowing?", "o": {"A": "Oligohydramnios", "B": "Polyhydramnios", "C": "Chorioamnionitis", "D": "Placenta accreta"}, "r": "B", "e": {"correcta": "Polyhydramnios is an excess of amniotic fluid, classically caused by anything that impairs fetal swallowing of amniotic fluid (esophageal or duodenal atresia), as well as maternal diabetes, fetal anemia, and multiple gestations.", "incorrectas": {"A": "Oligohydramnios is the opposite condition, too little amniotic fluid, typically due to impaired fetal urination (e.g., bilateral renal agenesis, posterior urethral valves) rather than impaired swallowing.", "C": "Chorioamnionitis is infection/inflammation of the fetal membranes, not a disorder of amniotic fluid volume per se, though it can be associated with other complications.", "D": "Placenta accreta is abnormal placental attachment directly to the myometrium without an intervening decidua, unrelated to amniotic fluid volume regulation."}}}, {"id": "anking-reproductive-system-pathology-2499", "fuente": "anking", "tema": 8, "anki": "1463526404611", "q": "What is the most common gynecologic cancer worldwide, largely due to lack of screening or HPV vaccination in many regions?", "o": {"A": "Endometrial cancer", "B": "Ovarian cancer", "C": "Cervical cancer", "D": "Vulvar cancer"}, "r": "C", "e": {"correcta": "Cervical cancer is the most common gynecologic cancer worldwide because in many countries, widespread Pap smear screening and HPV vaccination (which prevent progression from HPV infection to invasive cancer) are not available, allowing more cases to progress to invasive disease.", "incorrectas": {"A": "Endometrial cancer is the most common gynecologic cancer in developed countries like the U.S., where cervical cancer is largely caught early through screening, but globally cervical cancer remains more prevalent.", "B": "Ovarian cancer, while it carries the worst prognosis among gynecologic cancers due to late detection, is not the most common gynecologic cancer worldwide or in the U.S.", "D": "Vulvar cancer is a much rarer gynecologic malignancy, not a leading cause of gynecologic cancer incidence globally."}}}, {"id": "anking-reproductive-system-pathology-2500", "fuente": "anking", "tema": 8, "anki": "1463526408165", "q": "What is the most common gynecologic cancer in the United States?", "o": {"A": "Cervical cancer", "B": "Ovarian cancer", "C": "Endometrial cancer", "D": "Vaginal cancer"}, "r": "C", "e": {"correcta": "Endometrial cancer is the most common gynecologic cancer in the U.S., reflecting the order of incidence: endometrial > ovarian > cervical, largely because effective Pap smear screening has reduced cervical cancer incidence in developed nations.", "incorrectas": {"A": "Cervical cancer is the most common gynecologic cancer worldwide but ranks third in incidence in the U.S. due to effective screening programs.", "B": "Ovarian cancer ranks second in incidence in the U.S. but carries the worst prognosis of the three due to its typically late-stage detection.", "D": "Vaginal cancer is a rare gynecologic malignancy and does not rank among the top three most common gynecologic cancers in the U.S."}}}, {"id": "anking-reproductive-system-pathology-2501", "fuente": "anking", "tema": 8, "anki": "1463526412603", "q": "Among endometrial, cervical, and ovarian cancer, which has the worst prognosis?", "o": {"A": "Cervical cancer", "B": "Endometrial cancer", "C": "Ovarian cancer", "D": "All three have similar prognoses"}, "r": "C", "e": {"correcta": "Ovarian cancer carries the worst prognosis of the three gynecologic cancers (ovarian > endometrial > cervical in mortality) largely because it is often asymptomatic until advanced stages, leading to late diagnosis when it has already spread beyond the ovary.", "incorrectas": {"A": "Cervical cancer generally has a better prognosis than ovarian cancer because it is detectable at precancerous stages via Pap smear screening, allowing early intervention.", "B": "Endometrial cancer typically presents early with abnormal uterine bleeding, prompting earlier diagnosis and generally better outcomes than ovarian cancer.", "D": "The three gynecologic cancers have distinctly different prognoses driven by differences in screening availability and typical stage at diagnosis, not similar outcomes."}}}, {"id": "anking-reproductive-system-pathology-2502", "fuente": "anking", "tema": 8, "anki": "1463526422510", "q": "A condition presenting with symptoms of menopause after puberty but before age 40, with decreased estrogen and increased FSH/LH, is known as what?", "o": {"A": "Polycystic ovary syndrome", "B": "Premature ovarian failure", "C": "Asherman syndrome", "D": "Turner syndrome"}, "r": "B", "e": {"correcta": "Premature ovarian failure (primary ovarian insufficiency) is depletion or dysfunction of ovarian follicles before age 40, causing decreased estrogen with compensatory elevation of FSH and LH due to loss of negative feedback, producing menopausal symptoms in a young woman.", "incorrectas": {"A": "Polycystic ovary syndrome typically presents with oligomenorrhea, hyperandrogenism, and elevated LH:FSH ratio due to anovulation, not with a menopausal hormone pattern of estrogen deficiency.", "C": "Asherman syndrome is intrauterine adhesions/scarring (often post-curettage) causing secondary amenorrhea due to a structural uterine problem, with normal ovarian hormone levels, not ovarian failure.", "D": "Turner syndrome (45,XO) causes ovarian dysgenesis presenting from birth/puberty with primary amenorrhea, not a later-onset premature menopause after normal puberty has already occurred."}}}, {"id": "anking-reproductive-system-pathology-2503", "fuente": "anking", "tema": 8, "anki": "1463529453311", "q": "A phenotypic male presents with gynecomastia, female pattern hair distribution, tall stature with long extremities, and a eunuchoid body shape. Which sex chromosome disorder is most likely?", "o": {"A": "Turner syndrome", "B": "Klinefelter syndrome (47,XXY)", "C": "Double Y syndrome (47,XYY)", "D": "Androgen insensitivity syndrome"}, "r": "B", "e": {"correcta": "Klinefelter syndrome (47,XXY) results from nondisjunction giving an extra X chromosome in a phenotypic male, causing seminiferous tubule dysgenesis and impaired Leydig cell function, leading to gynecomastia, female hair distribution, tall stature with long extremities, and a eunuchoid body habitus.", "incorrectas": {"A": "Turner syndrome (45,XO) occurs in phenotypic females, presenting with short stature and streak ovaries, not in males with gynecomastia and tall stature.", "C": "Double Y syndrome (47,XYY) males are phenotypically normal and very tall but do not have gynecomastia, female hair distribution, or infertility characteristic of Klinefelter syndrome.", "D": "Androgen insensitivity syndrome occurs in a 46,XY individual with a female external phenotype due to nonfunctional androgen receptors, distinct from the karyotype and phenotype of Klinefelter syndrome."}}}, {"id": "anking-reproductive-system-pathology-2504", "fuente": "anking", "tema": 8, "anki": "1463529461225", "q": "What is the expected testosterone level in a patient with Klinefelter syndrome?", "o": {"A": "Increased", "B": "Normal", "C": "Decreased", "D": "Undetectable"}, "r": "C", "e": {"correcta": "In Klinefelter syndrome, testosterone is decreased due to seminiferous tubule dysgenesis and abnormal Leydig cell function, contributing to infertility and the eunuchoid, gynecomastic phenotype.", "incorrectas": {"A": "Increased testosterone would be seen with a testosterone-secreting tumor or exogenous steroid use, not with the primary gonadal failure of Klinefelter syndrome.", "B": "Normal testosterone is inconsistent with the clinical picture of Klinefelter syndrome, where impaired testicular function reliably lowers testosterone production.", "D": "Testosterone is decreased but not completely undetectable in Klinefelter syndrome; some Leydig cell function typically persists at a reduced level."}}}, {"id": "anking-reproductive-system-pathology-2505", "fuente": "anking", "tema": 8, "anki": "1463529464624", "q": "What is the expected estrogen level in a patient with Klinefelter syndrome?", "o": {"A": "Decreased", "B": "Increased", "C": "Normal", "D": "Undetectable"}, "r": "B", "e": {"correcta": "In Klinefelter syndrome, estrogen is increased relative to testosterone (an altered testosterone-to-estrogen ratio), which contributes to the gynecomastia and feminized features characteristic of the syndrome.", "incorrectas": {"A": "Decreased estrogen would not explain the gynecomastia seen in Klinefelter syndrome; rather, a relative increase in estrogen (partly from peripheral aromatization) drives this feature.", "C": "Normal estrogen levels would not account for the prominent gynecomastia that is a hallmark clinical finding of Klinefelter syndrome.", "D": "Estrogen is elevated, not undetectable, in Klinefelter syndrome, which is why breast tissue development (gynecomastia) occurs."}}}, {"id": "anking-reproductive-system-pathology-2506", "fuente": "anking", "tema": 8, "anki": "1463529468266", "q": "Klinefelter syndrome is characteristically associated with which testicular finding?", "o": {"A": "Testicular enlargement", "B": "Testicular atrophy", "C": "Normal testicular size", "D": "Cryptorchidism"}, "r": "B", "e": {"correcta": "Klinefelter syndrome is associated with testicular atrophy due to seminiferous tubule dysgenesis (hyalinization and fibrosis), which also contributes to infertility and an increased risk of testicular germ cell tumors.", "incorrectas": {"A": "Testicular enlargement is not a feature of Klinefelter syndrome; rather, the testes are small and firm due to tubular dysgenesis.", "C": "Normal testicular size would not fit the pathophysiology of tubular dysgenesis and fibrosis seen in Klinefelter syndrome, which characteristically shrinks the testes.", "D": "Cryptorchidism refers to failure of testicular descent, a distinct congenital anatomic issue rather than the atrophic, dysgenetic change seen in Klinefelter syndrome."}}}, {"id": "anking-reproductive-system-pathology-2507", "fuente": "anking", "tema": 8, "anki": "1463529471830", "q": "A phenotypic female presents with short stature, a shield chest, and a webbed neck. Which sex chromosome disorder is most likely?", "o": {"A": "Klinefelter syndrome", "B": "Double Y syndrome", "C": "Turner syndrome", "D": "Androgen insensitivity syndrome"}, "r": "C", "e": {"correcta": "Turner syndrome (45,XO) presents in phenotypic females with short stature, a webbed neck, shield chest with widely spaced nipples, and streak ovaries, along with lymphatic defects (cystic hygroma), horseshoe kidney, and bicuspid aortic valve.", "incorrectas": {"A": "Klinefelter syndrome (47,XXY) affects phenotypic males, presenting with gynecomastia and tall stature, the opposite body habitus from the short stature seen in Turner syndrome.", "B": "Double Y syndrome (47,XYY) affects phenotypic males who are typically very tall and otherwise phenotypically normal, not short females with webbed necks.", "D": "Androgen insensitivity syndrome presents in a 46,XY individual with a female phenotype but normal or tall stature and absence of the characteristic Turner stigmata like webbed neck and shield chest."}}}, {"id": "anking-reproductive-system-pathology-2508", "fuente": "anking", "tema": 8, "anki": "1463529479421", "q": "What is the most common cause of primary amenorrhea?", "o": {"A": "Asherman syndrome", "B": "Polycystic ovary syndrome", "C": "Turner syndrome", "D": "Premature ovarian failure"}, "r": "C", "e": {"correcta": "Turner syndrome is the most common cause of primary amenorrhea (failure of menarche by age 15), due to ovarian dysgenesis (streak ovaries) resulting from the 45,XO karyotype, which prevents normal follicular development and estrogen production.", "incorrectas": {"A": "Asherman syndrome causes secondary amenorrhea due to intrauterine scarring in a woman who previously menstruated, not primary amenorrhea in someone who has never menstruated.", "B": "Polycystic ovary syndrome typically causes oligomenorrhea or secondary amenorrhea after menarche has occurred, rather than being the leading cause of primary amenorrhea.", "D": "Premature ovarian failure causes secondary amenorrhea, occurring after a period of normal menstrual cycling, distinguishing it from primary amenorrhea seen in Turner syndrome."}}}, {"id": "anking-reproductive-system-pathology-2509", "fuente": "anking", "tema": 8, "anki": "1463529483683", "q": "What is the expected estrogen level in a patient with Turner syndrome?", "o": {"A": "Increased", "B": "Decreased", "C": "Normal", "D": "Variable, depends on age"}, "r": "B", "e": {"correcta": "In Turner syndrome, estrogen is decreased due to ovarian dysgenesis (streak ovaries lacking functional follicles), which also drives compensatory elevation of FSH/LH; estrogen replacement therapy is a mainstay of treatment.", "incorrectas": {"A": "Increased estrogen is inconsistent with the ovarian dysgenesis of Turner syndrome, where the ovaries fail to develop functional follicles capable of producing estrogen.", "C": "Normal estrogen levels would not explain the failure of secondary sexual characteristic development and primary amenorrhea seen in Turner syndrome.", "D": "Estrogen deficiency in Turner syndrome is a consistent feature from birth due to congenital ovarian dysgenesis, not something that fluctuates meaningfully with age before treatment."}}}, {"id": "anking-reproductive-system-pathology-2510", "fuente": "anking", "tema": 8, "anki": "1463529503987", "q": "How do males with double Y syndrome (47,XYY) typically appear phenotypically?", "o": {"A": "Short stature with gynecomastia", "B": "Normal phenotype, very tall", "C": "Ambiguous genitalia", "D": "Webbed neck and shield chest"}, "r": "B", "e": {"correcta": "Males with double Y syndrome (47,XYY) are typically phenotypically normal but very tall, and may have an increased incidence of severe acne, learning disability, and autism spectrum behaviors, but generally normal fertility and testosterone levels.", "incorrectas": {"A": "Short stature with gynecomastia describes Klinefelter syndrome (47,XXY), not double Y syndrome, which is instead associated with tall stature and a normal male phenotype.", "C": "Ambiguous genitalia is seen in disorders of sexual differentiation like placental aromatase deficiency or congenital adrenal hyperplasia, not in double Y syndrome, which has normal male genitalia.", "D": "Webbed neck and shield chest are classic features of Turner syndrome in phenotypic females, unrelated to the normal-appearing tall male phenotype of double Y syndrome."}}}, {"id": "anking-reproductive-system-pathology-2511", "fuente": "anking", "tema": 8, "anki": "1463529510813", "q": "Ovotesticular disorder of sex development, also known as true hermaphroditism, is defined by the presence of what?", "o": {"A": "Only testicular tissue with ambiguous external genitalia", "B": "Both ovarian and testicular tissue", "C": "Only ovarian tissue with a 46,XY karyotype", "D": "Absent gonadal tissue bilaterally"}, "r": "B", "e": {"correcta": "Ovotesticular disorder of sex development (true hermaphroditism) is defined by the presence of both ovarian and testicular tissue in the same individual, most commonly occurring in individuals with a 46,XX karyotype.", "incorrectas": {"A": "Isolated testicular tissue with ambiguous genitalia describes conditions like partial androgen insensitivity or 5-alpha-reductase deficiency, not true hermaphroditism, which requires both gonadal tissue types.", "C": "Ovarian tissue alone with a 46,XY karyotype does not fit the definition; true hermaphroditism requires both ovarian and testicular tissue, and it is most commonly 46,XX rather than 46,XY.", "D": "Absent gonadal tissue describes gonadal agenesis or dysgenesis, the opposite scenario from true hermaphroditism, which involves the coexistence of both gonad types."}}}, {"id": "anking-reproductive-system-pathology-2512", "fuente": "anking", "tema": 8, "anki": "1463529514333", "q": "Placental aromatase deficiency results in an inability to synthesize estrogens from which precursor?", "o": {"A": "Cholesterol", "B": "Androgens", "C": "Progesterone", "D": "DHEA-S from the fetal adrenal only"}, "r": "B", "e": {"correcta": "Placental aromatase normally converts androgens (such as testosterone and androstenedione) into estrogens; deficiency of this enzyme blocks that conversion, allowing androgens to accumulate and cross into both fetal and maternal circulation.", "incorrectas": {"A": "Cholesterol is the ultimate precursor for all steroid hormones several enzymatic steps upstream, but aromatase specifically acts on androgens at the final step to produce estrogens, not directly on cholesterol.", "C": "Progesterone is synthesized independently of aromatase activity and is not the substrate that aromatase converts into estrogen.", "D": "While fetal adrenal DHEA-S is a source of androgen precursor delivered to the placenta, the enzyme itself acts broadly on androgens, and framing the deficiency around a single specific source oversimplifies the mechanism."}}}, {"id": "anking-reproductive-system-pathology-2513", "fuente": "anking", "tema": 8, "anki": "1463529518094", "q": "Placental aromatase deficiency in a 46,XX female infant classically results in what finding?", "o": {"A": "Feminization of external genitalia", "B": "Masculinization of external genitalia", "C": "Complete gonadal agenesis", "D": "Isosexual precocious puberty"}, "r": "B", "e": {"correcta": "Placental aromatase deficiency prevents conversion of fetal androgens to estrogens, so excess androgens accumulate and masculinize the external genitalia of a 46,XX female infant (ambiguous genitalia), and can also cause virilization of the mother during pregnancy since fetal androgens cross the placenta.", "incorrectas": {"A": "Feminization would be expected if estrogen production were increased or unaffected; the deficiency causes the opposite effect by allowing androgen accumulation.", "C": "Complete gonadal agenesis is a distinct developmental abnormality unrelated to an enzymatic block in steroid hormone conversion.", "D": "Isosexual precocious puberty refers to early puberty matching the genetic/gonadal sex and occurring later in childhood, not the in-utero genital masculinization seen with this enzyme deficiency."}}}, {"id": "anking-reproductive-system-pathology-2514", "fuente": "anking", "tema": 8, "anki": "1463529538028", "q": "In general, sex chromosome disorders such as Turner and Klinefelter syndromes present with which hormonal pattern?", "o": {"A": "Increased testosterone/estrogen and decreased LH", "B": "Decreased testosterone/estrogen and increased LH", "C": "Increased testosterone/estrogen and increased LH", "D": "Decreased testosterone/estrogen and decreased LH"}, "r": "B", "e": {"correcta": "Both Turner and Klinefelter syndromes involve primary gonadal failure (ovarian dysgenesis or seminiferous tubule dysgenesis, respectively), leading to decreased sex steroid production (estrogen or testosterone) with loss of negative feedback on the hypothalamic-pituitary axis, resulting in compensatory elevation of LH (and FSH).", "incorrectas": {"A": "Decreased LH would occur with secondary (hypothalamic/pituitary) hypogonadism, not primary gonadal failure as seen in these sex chromosome disorders, where LH rises due to loss of feedback inhibition.", "C": "Increased testosterone/estrogen contradicts the pathophysiology of gonadal failure in these syndromes, where impaired gonadal function lowers sex steroid output rather than raising it.", "D": "Decreased LH alongside decreased sex steroids would suggest a central (hypothalamic-pituitary) cause of hypogonadism, the opposite pattern from the primary gonadal failure with compensatory LH rise seen here."}}}, {"id": "anking-reproductive-system-pathology-2515", "fuente": "anking", "tema": 8, "anki": "1463529541032", "q": "A defective androgen receptor (as in androgen insensitivity syndrome) presents with what testosterone and LH pattern?", "o": {"A": "Decreased testosterone and decreased LH", "B": "Increased testosterone and increased LH", "C": "Decreased testosterone and increased LH", "D": "Increased testosterone and decreased LH"}, "r": "B", "e": {"correcta": "In androgen insensitivity syndrome, target tissues cannot respond to testosterone due to a defective androgen receptor; since testosterone cannot exert negative feedback effectively at the tissue level driving the reproductive phenotype, LH rises to stimulate testicular Leydig cells, which in turn increases testosterone secretion, so both are elevated.", "incorrectas": {"A": "Decreased testosterone and decreased LH would suggest primary or secondary hypogonadism with reduced hormone production, not a receptor-level defect where hormone synthesis is actually intact or increased.", "C": "Decreased testosterone with increased LH is the pattern seen in primary gonadal failure with impaired hormone synthesis (e.g., Klinefelter syndrome), not a receptor defect where testosterone production is preserved or increased.", "D": "Increased testosterone with decreased LH is the pattern seen with a testosterone-secreting tumor or exogenous steroid use, where excess testosterone suppresses LH via negative feedback, the opposite of the receptor-level insensitivity in AIS."}}}, {"id": "anking-reproductive-system-pathology-2516", "fuente": "anking", "tema": 8, "anki": "1463529546124", "q": "A testosterone-secreting tumor or use of exogenous anabolic steroids classically presents with what testosterone and LH pattern?", "o": {"A": "Decreased testosterone and increased LH", "B": "Increased testosterone and increased LH", "C": "Increased testosterone and decreased LH", "D": "Decreased testosterone and decreased LH"}, "r": "C", "e": {"correcta": "A testosterone-secreting tumor or exogenous steroid use raises circulating testosterone, which exerts negative feedback on the hypothalamic-pituitary axis, suppressing GnRH and thus LH secretion, producing a pattern of increased testosterone with decreased LH.", "incorrectas": {"A": "Decreased testosterone with increased LH describes primary gonadal failure (e.g., Klinefelter syndrome), the opposite pattern from an autonomous testosterone source, where testosterone is high and LH is suppressed.", "B": "Increased testosterone with increased LH describes a defective androgen receptor (androgen insensitivity), where the pituitary continues secreting LH because tissues cannot sense the testosterone, unlike an exogenous or tumor source that successfully suppresses LH.", "D": "Decreased testosterone with decreased LH suggests secondary (central) hypogonadism, not the picture of an autonomous testosterone-producing tumor or exogenous steroid administration."}}}, {"id": "anking-endocrine-physiology-2517", "fuente": "anking", "tema": 23, "anki": "1463529568699", "q": "A patient with primary hypogonadism (gonadal failure) would be expected to show which pattern of testosterone/estrogen and LH levels?", "o": {"A": "Decreased sex hormones, decreased LH", "B": "Decreased sex hormones, increased LH", "C": "Increased sex hormones, decreased LH", "D": "Increased sex hormones, increased LH"}, "r": "B", "e": {"correcta": "Primary hypogonadism reflects gonadal failure itself (testes/ovaries), so sex hormone output falls. The hypothalamic-pituitary axis senses low negative feedback and compensates by increasing GnRH-driven LH (and FSH), producing the classic hypergonadotropic hypogonadism pattern: low sex steroids with high LH/FSH.", "incorrectas": {"A": "Decreased sex hormones with decreased LH describes hypogonadotropic (secondary) hypogonadism, where the defect is at the hypothalamus or pituitary, not the gonad, so LH cannot rise appropriately.", "C": "Increased sex hormones with decreased LH would reflect an autonomous hormone-secreting source suppressing the axis via negative feedback, not gonadal failure.", "D": "Increased sex hormones with increased LH is not a physiologic feedback pattern seen in primary hypogonadism, since elevated sex steroids should suppress, not raise, LH."}}}, {"id": "anking-endocrine-physiology-2518", "fuente": "anking", "tema": 23, "anki": "1463529575275", "q": "Hypogonadotropic (secondary) hypogonadism is characterized by which laboratory pattern?", "o": {"A": "Decreased sex hormones with decreased LH and FSH", "B": "Decreased sex hormones with increased LH and FSH", "C": "Increased sex hormones with decreased LH and FSH", "D": "Normal sex hormones with increased LH and FSH"}, "r": "A", "e": {"correcta": "In hypogonadotropic (secondary) hypogonadism, the defect lies at the hypothalamus (impaired GnRH) or pituitary (impaired gonadotropin secretion), so LH and FSH are low, and the gonads receive insufficient stimulation, yielding low testosterone/estrogen as well.", "incorrectas": {"B": "Decreased sex hormones with increased LH and FSH describes primary (hypergonadotropic) hypogonadism, where the gonad itself fails and the pituitary compensates by raising gonadotropins.", "C": "Increased sex hormones with decreased LH and FSH would suggest an autonomous peripheral source of sex steroids suppressing the axis, not a hypothalamic-pituitary failure.", "D": "Normal sex hormones with increased LH and FSH is inconsistent with any hypogonadal state, since hypogonadism by definition involves inadequate sex hormone production."}}}, {"id": "anking-endocrine-physiology-2519", "fuente": "anking", "tema": 23, "anki": "1463529580634", "q": "Which condition is a rare genetic disorder that causes hypogonadotropic hypogonadism due to failure of GnRH neuron migration, resulting in incomplete puberty and anosmia?", "o": {"A": "Kallmann syndrome", "B": "Klinefelter syndrome", "C": "Turner syndrome", "D": "Androgen insensitivity syndrome"}, "r": "A", "e": {"correcta": "Kallmann syndrome results from failure of GnRH-secreting neurons to migrate properly from the olfactory placode to the hypothalamus during development. This causes hypogonadotropic hypogonadism (low GnRH leads to low LH/FSH and low sex steroids), classically presenting with delayed/absent puberty along with anosmia or hyposmia because the olfactory bulbs also fail to form normally.", "incorrectas": {"B": "Klinefelter syndrome (47,XXY) causes primary (hypergonadotropic) hypogonadism from testicular dysgenesis, not a GnRH migration defect, and is not associated with anosmia.", "C": "Turner syndrome (45,X) causes primary hypogonadism due to ovarian dysgenesis (streak gonads), presenting with elevated gonadotropins, not a hypothalamic GnRH deficiency.", "D": "Androgen insensitivity syndrome involves a defective androgen receptor in a genotypic male, leading to normal or elevated testosterone with female external phenotype, unrelated to GnRH neuron migration."}}}, {"id": "anking-endocrine-physiology-2520", "fuente": "anking", "tema": 23, "anki": "1463534046490", "q": "In 5-alpha-reductase deficiency, which hormonal pattern of testosterone and LH is typically seen?", "o": {"A": "Decreased testosterone, decreased LH", "B": "Normal testosterone, normal/increased LH", "C": "Increased testosterone, decreased LH", "D": "Decreased testosterone, increased LH"}, "r": "B", "e": {"correcta": "5-alpha-reductase deficiency impairs conversion of testosterone to dihydrotestosterone (DHT), which is required for normal external male genitalia development, but testosterone synthesis by the testes is intact, so serum testosterone is normal. Because DHT-mediated negative feedback and virilization are reduced, LH can be normal to mildly increased as the axis compensates for reduced androgen action peripherally.", "incorrectas": {"A": "Decreased testosterone with decreased LH would suggest a hypothalamic-pituitary defect, but 5-alpha-reductase deficiency is an enzymatic defect distal to normal testosterone production, so testosterone itself is not low.", "C": "Increased testosterone with decreased LH would suggest an autonomous androgen source suppressing the axis, which is not the mechanism in this enzyme deficiency.", "D": "Decreased testosterone with increased LH describes primary testicular failure (hypergonadotropic hypogonadism), not 5-alpha-reductase deficiency, where testosterone production is normal."}}}, {"id": "anking-renal-physiology-2521", "fuente": "anking", "tema": 12, "anki": "1463844417100", "q": "Antidiuretic hormone (ADH/vasopressin) exerts its main water-reabsorbing action at which segment of the nephron?", "o": {"A": "Proximal convoluted tubule", "B": "Thick ascending limb of the loop of Henle", "C": "Collecting duct", "D": "Distal convoluted tubule"}, "r": "C", "e": {"correcta": "ADH binds V2 receptors on the principal cells of the collecting duct, triggering a Gs-cAMP cascade that inserts aquaporin-2 water channels into the apical membrane, increasing water permeability and reabsorption there, which concentrates the urine.", "incorrectas": {"B": "The thick ascending limb is impermeable to water regardless of ADH; it reabsorbs Na+/K+/2Cl- via NKCC2 and helps build the medullary concentration gradient that ADH later exploits, but ADH does not act there.", "A": "The proximal convoluted tubule reabsorbs the bulk of filtered water and solutes isosmotically and constitutively, independent of ADH regulation.", "D": "The distal convoluted tubule is also relatively water-impermeable and is the site of action for thiazide diuretics (NCC transporter), not the primary ADH target."}}}, {"id": "anking-toxicities-side-effects-2522", "fuente": "anking", "tema": 29, "anki": "1463844549067", "q": "Which mood stabilizer used for bipolar disorder is a common cause of drug-induced nephrogenic diabetes insipidus?", "o": {"A": "Valproate", "B": "Lithium", "C": "Carbamazepine", "D": "Quetiapine"}, "r": "B", "e": {"correcta": "Lithium enters principal cells of the collecting duct through ENaC channels and impairs the ability of ADH to upregulate aquaporin-2 channels, causing nephrogenic diabetes insipidus (kidneys are unresponsive to ADH). This is treated with amiloride, which blocks ENaC and prevents lithium entry into the cells.", "incorrectas": {"A": "Valproate is associated with hepatotoxicity, pancreatitis, neural tube defects, and weight gain, not nephrogenic diabetes insipidus.", "C": "Carbamazepine can actually cause SIADH (hyponatremia) by stimulating ADH-like effects, essentially the opposite renal water problem from lithium.", "D": "Quetiapine, an atypical antipsychotic, is more associated with metabolic syndrome and sedation, not nephrogenic diabetes insipidus."}}}, {"id": "anking-toxicities-side-effects-2523", "fuente": "anking", "tema": 29, "anki": "1463844574977", "q": "Which drug-induced diabetes insipidus is amiloride useful for treating, by blocking the causative agent's entry into collecting duct cells?", "o": {"A": "Demeclocycline-induced diabetes insipidus", "B": "Lithium-induced diabetes insipidus", "C": "Foscarnet-induced diabetes insipidus", "D": "Cisplatin-induced diabetes insipidus"}, "r": "B", "e": {"correcta": "Amiloride is a K+-sparing diuretic that blocks the epithelial sodium channel (ENaC) in the collecting duct principal cells. Since lithium relies on ENaC to enter these cells and disrupt aquaporin-2 trafficking, blocking ENaC with amiloride prevents lithium uptake and reverses lithium-induced nephrogenic diabetes insipidus.", "incorrectas": {"A": "Demeclocycline itself is a tetracycline that can cause nephrogenic diabetes insipidus (used therapeutically for SIADH) by inhibiting ADH signaling at the V2 receptor/adenylate cyclase level, not via ENaC, so amiloride is not its antidote.", "C": "Foscarnet, an antiviral, is associated with nephrotoxicity and electrolyte disturbances (hypocalcemia, hypomagnesemia) rather than the ENaC-mediated mechanism that amiloride reverses.", "D": "Cisplatin causes nephrotoxicity and electrolyte wasting through direct tubular damage, not through the ENaC-dependent mechanism that amiloride specifically counters."}}}, {"id": "anking-endocrine-pharmacology-2524", "fuente": "anking", "tema": 24, "anki": "1463844954526", "q": "Central diabetes insipidus, caused by inadequate hypothalamic ADH secretion, is best treated with which agent?", "o": {"A": "Demeclocycline", "B": "Tolvaptan", "C": "Exogenous ADH (desmopressin)", "D": "Amiloride"}, "r": "C", "e": {"correcta": "Central diabetes insipidus results from insufficient production/release of ADH by the hypothalamus/posterior pituitary. Because the kidney's V2 receptors are still functional, replacing the missing hormone with exogenous ADH (desmopressin, DDAVP) restores collecting duct water reabsorption and corrects the polyuria.", "incorrectas": {"A": "Demeclocycline blocks ADH action at the collecting duct and is used to treat SIADH (excess ADH effect), the opposite problem from central DI where ADH is deficient.", "B": "Tolvaptan is a V2 receptor antagonist used for SIADH-associated hyponatremia; giving it to a patient with central DI would worsen the water loss.", "D": "Amiloride blocks ENaC and is used for lithium-induced nephrogenic DI, not central DI, since the defect in central DI is hormone deficiency, not a resistant collecting duct."}}}, {"id": "anking-hematology-oncology-pharmacology-2525", "fuente": "anking", "tema": 26, "anki": "1463845088254", "q": "Besides central diabetes insipidus, desmopressin (DDAVP) is used to treat which bleeding disorder characterized by increased bruisability and mucosal bleeding?", "o": {"A": "Hemophilia A", "B": "Von Willebrand disease", "C": "Immune thrombocytopenic purpura", "D": "Disseminated intravascular coagulation"}, "r": "B", "e": {"correcta": "Desmopressin stimulates release of von Willebrand factor (and factor VIII) stored in endothelial Weibel-Palade bodies. This raises vWF levels, improving platelet adhesion and correcting the mucocutaneous bleeding and easy bruising characteristic of von Willebrand disease.", "incorrectas": {"A": "Hemophilia A (factor VIII deficiency) can respond to desmopressin in mild cases since it also raises factor VIII, but the classic presentation of bruisability and mucosal bleeding described here is more characteristic of von Willebrand disease, a primary hemostasis disorder.", "C": "Immune thrombocytopenic purpura is caused by autoantibody-mediated platelet destruction and is treated with corticosteroids, IVIG, or splenectomy, not desmopressin.", "D": "DIC involves consumptive coagulopathy with both clotting and bleeding, treated by addressing the underlying cause and replacing consumed factors/platelets, not desmopressin."}}}, {"id": "anking-hematology-oncology-pharmacology-2526", "fuente": "anking", "tema": 26, "anki": "1463845129097", "q": "A hemophilia A patient with hemarthrosis and prolonged bleeding after minor procedures may be treated with desmopressin because it raises levels of which factor?", "o": {"A": "Factor VIII", "B": "Factor IX", "C": "Fibrinogen", "D": "Factor XI"}, "r": "A", "e": {"correcta": "Hemophilia A is an X-linked deficiency of factor VIII. Desmopressin promotes release of factor VIII (along with von Willebrand factor, its carrier protein) from endothelial stores, transiently raising plasma factor VIII levels enough to manage mild bleeding episodes or minor procedures.", "incorrectas": {"B": "Factor IX deficiency causes hemophilia B, which does not respond to desmopressin since desmopressin does not mobilize factor IX; hemophilia B requires factor IX replacement instead.", "C": "Fibrinogen deficiency causes a different coagulopathy (afibrinogenemia/hypofibrinogenemia) and is treated with cryoprecipitate or fibrinogen concentrate, not desmopressin.", "D": "Factor XI deficiency (hemophilia C) is managed with factor XI concentrate or FFP, not desmopressin, since desmopressin's effect is specific to factor VIII/vWF release."}}}, {"id": "anking-endocrine-pharmacology-2527", "fuente": "anking", "tema": 24, "anki": "1463845154729", "q": "Desmopressin can be used clinically to treat which common pediatric condition involving nighttime urination?", "o": {"A": "Vesicoureteral reflux", "B": "Nocturnal enuresis (bed wetting)", "C": "Overactive bladder", "D": "Urinary tract infection"}, "r": "B", "e": {"correcta": "Desmopressin mimics ADH, increasing renal water reabsorption at the collecting duct and reducing nighttime urine volume, which is a mainstay pharmacologic treatment for nocturnal enuresis in children who do not respond to behavioral measures alone.", "incorrectas": {"A": "Vesicoureteral reflux is a structural/functional problem with the ureterovesical junction allowing retrograde urine flow, managed with prophylactic antibiotics or surgical correction, not desmopressin.", "C": "Overactive bladder is treated with antimuscarinics (e.g., oxybutynin) or beta-3 agonists (mirabegron) that target detrusor contractility, not with ADH analogs.", "D": "Urinary tract infections are treated with antibiotics targeting the causative organism; desmopressin has no antimicrobial or infection-related role."}}}, {"id": "anking-toxicities-side-effects-2528", "fuente": "anking", "tema": 29, "anki": "1463845161067", "q": "Which electrolyte abnormality is an adverse effect of desmopressin (DDAVP) therapy?", "o": {"A": "Hypernatremia", "B": "Hyponatremia", "C": "Hyperkalemia", "D": "Hypokalemia"}, "r": "B", "e": {"correcta": "Desmopressin acts like ADH to increase free water reabsorption in the collecting duct. Excess water retention relative to sodium dilutes the serum, producing hyponatremia, which is the key adverse effect to monitor for during treatment.", "incorrectas": {"A": "Hypernatremia would result from water loss or ADH deficiency/resistance (e.g., untreated diabetes insipidus or vaptan use), the opposite of what excess ADH-like activity from desmopressin causes.", "C": "Hyperkalemia is not a typical effect of ADH/V2 receptor activity, which primarily governs water channels (aquaporin-2) rather than potassium handling.", "D": "Hypokalemia is more associated with loop or thiazide diuretics or mineralocorticoid excess, not with desmopressin's water-retaining V2-receptor-mediated mechanism."}}}, {"id": "anking-gastrointestinal-pathology-2529", "fuente": "anking", "tema": 10, "anki": "1463845168143", "q": "Exogenous ADH (vasopressin) is useful in managing which type of bleeding by reducing portal pressure via V1 receptor-mediated vasoconstriction?", "o": {"A": "Peptic ulcer bleeding", "B": "Esophageal variceal bleeding", "C": "Diverticular bleeding", "D": "Hemorrhoidal bleeding"}, "r": "B", "e": {"correcta": "Vasopressin acts on V1 receptors on vascular smooth muscle, causing splanchnic vasoconstriction. This reduces portal venous inflow and portal hypertension, decreasing blood flow through esophageal varices and helping control acute variceal hemorrhage.", "incorrectas": {"A": "Peptic ulcer bleeding is managed with endoscopic hemostasis and acid suppression (PPIs), not vasopressin, since it is not driven by portal hypertension.", "C": "Diverticular bleeding, typically arising from the vasa recta in the colon, is managed with endoscopic or angiographic intervention, not systemic vasopressin aimed at the portal circulation.", "D": "Hemorrhoidal bleeding arises from the anorectal venous plexus and is managed with local measures (banding, sclerotherapy), unrelated to splanchnic V1-mediated vasoconstriction."}}}, {"id": "anking-toxicities-side-effects-2530", "fuente": "anking", "tema": 29, "anki": "1463845182983", "q": "Treatment of SIADH with a vaptan (e.g., tolvaptan, conivaptan) carries the risk of which electrolyte disturbance?", "o": {"A": "Hyponatremia", "B": "Hyperkalemia", "C": "Hypernatremia", "D": "Hypocalcemia"}, "r": "C", "e": {"correcta": "Vaptans are V2 receptor antagonists that block ADH action, promoting free water excretion (aquaresis) without significant electrolyte loss. If diuresis is excessive, especially without adequate monitoring, it can lead to overcorrection and hypernatremia (volume/water loss relative to sodium).", "incorrectas": {"A": "Hyponatremia is actually the condition vaptans are used to treat (as seen in SIADH), not a side effect of the drugs themselves; blocking ADH action raises, not lowers, serum sodium.", "B": "Hyperkalemia is not a typical vaptan effect, since these drugs act on V2 receptors governing water channels rather than potassium-handling transporters.", "D": "Hypocalcemia is not associated with vaptan therapy; these drugs do not significantly affect calcium handling in the nephron."}}}, {"id": "anking-neurology-special-senses-pathology-2531", "fuente": "anking", "tema": 9, "anki": "1463845189086", "q": "If SIADH-induced hyponatremia treated with a vaptan is corrected too rapidly, which serious and irreversible CNS complication can occur?", "o": {"A": "Wernicke encephalopathy", "B": "Central pontine myelinolysis (osmotic demyelination syndrome)", "C": "Cerebral edema", "D": "Guillain-Barré syndrome"}, "r": "B", "e": {"correcta": "Rapid correction of chronic hyponatremia causes an abrupt osmotic shift that draws water out of neurons, particularly in the pons, damaging myelin sheaths. This produces central pontine myelinolysis (osmotic demyelination syndrome), which can cause irreversible quadriplegia, dysarthria, dysphagia, and altered consciousness — hence the rule to correct sodium slowly and cautiously.", "incorrectas": {"A": "Wernicke encephalopathy results from thiamine (B1) deficiency, presenting with ophthalmoplegia, ataxia, and confusion, unrelated to sodium correction rate.", "C": "Cerebral edema is actually the risk of overly rapid correction of hypernatremia (or too-slow correction of hyponatremia), where water shifts into brain cells, the opposite direction of osmotic injury from overcorrecting hyponatremia.", "D": "Guillain-Barré syndrome is an autoimmune demyelinating polyneuropathy typically triggered by antecedent infection (e.g., Campylobacter jejuni), not by rapid sodium correction."}}}, {"id": "anking-endocrine-pharmacology-2532", "fuente": "anking", "tema": 24, "anki": "1463845202003", "q": "Which tetracycline-class drug can be used as a second-line treatment for SIADH by inhibiting ADH signaling at the collecting duct?", "o": {"A": "Doxycycline", "B": "Demeclocycline", "C": "Minocycline", "D": "Tigecycline"}, "r": "B", "e": {"correcta": "Demeclocycline is a tetracycline derivative that induces a form of nephrogenic diabetes insipidus by blunting the collecting duct's response to ADH (inhibiting V2 receptor/adenylate cyclase signaling). This water-excreting effect is exploited therapeutically as a second-line agent for chronic SIADH when fluid restriction and vaptans are insufficient or contraindicated.", "incorrectas": {"A": "Doxycycline is a commonly used tetracycline for infections (e.g., Lyme disease, chlamydia) but is not used to treat SIADH; it lacks the ADH-antagonizing renal effect of demeclocycline.", "C": "Minocycline is notable for vestibular side effects and use in acne/certain infections, not for antagonizing ADH signaling in the kidney.", "D": "Tigecycline is a glycylcycline reserved for multidrug-resistant infections, unrelated to ADH antagonism or SIADH management."}}}, {"id": "anking-toxicities-side-effects-2533", "fuente": "anking", "tema": 29, "anki": "1463845210814", "q": "A drug used to treat SIADH can paradoxically induce which renal adverse effect due to blunting collecting duct ADH responsiveness?", "o": {"A": "Renal tubular acidosis", "B": "Nephrogenic diabetes insipidus", "C": "Minimal change disease", "D": "Fanconi syndrome"}, "r": "B", "e": {"correcta": "Demeclocycline, used to treat SIADH, works precisely by inducing a reversible nephrogenic diabetes insipidus — it desensitizes the collecting duct to ADH, promoting water excretion. Ironically, this therapeutic mechanism is itself a form of drug-induced nephrogenic DI if it goes too far.", "incorrectas": {"A": "Renal tubular acidosis involves impaired acid-base handling in specific tubular segments and is not the mechanism by which demeclocycline treats SIADH.", "C": "Minimal change disease is a glomerular podocyte disorder causing nephrotic syndrome, unrelated to demeclocycline's tubular ADH-blocking mechanism.", "D": "Fanconi syndrome is a generalized proximal tubular dysfunction causing wasting of glucose, amino acids, phosphate, and bicarbonate, a different tubular mechanism from ADH resistance at the collecting duct."}}}, {"id": "anking-endocrine-physiology-2534", "fuente": "anking", "tema": 23, "anki": "1463875484080", "q": "The growth hormone receptor belongs to which class of receptors?", "o": {"A": "G protein-coupled receptor", "B": "Receptor tyrosine kinase (intrinsic)", "C": "Receptor associated with (non-receptor) tyrosine kinase (JAK-STAT)", "D": "Ligand-gated ion channel"}, "r": "C", "e": {"correcta": "The GH receptor lacks intrinsic enzymatic activity; instead, ligand binding causes receptor dimerization that recruits and activates the cytoplasmic Janus kinase (JAK2), which phosphorylates STAT proteins. Phosphorylated STATs dimerize and translocate to the nucleus to regulate gene transcription — the JAK-STAT pathway shared by many cytokine and hormone receptors (e.g., prolactin, erythropoietin).", "incorrectas": {"A": "GPCRs (e.g., glucagon, ADH V2, most peptide hormone receptors acting via cAMP) signal through heterotrimeric G proteins and second messengers, not the JAK-STAT cascade used by GH.", "B": "Receptor tyrosine kinases (e.g., insulin, IGF-1 receptors) have intrinsic tyrosine kinase activity built into the receptor itself, unlike GH's receptor which relies on an associated, separate JAK kinase.", "D": "Ligand-gated ion channels (e.g., nicotinic ACh receptor, GABA-A receptor) directly open upon ligand binding to allow ion flux, an entirely different signaling mechanism from hormone-driven gene transcription."}}}, {"id": "anking-endocrine-physiology-2535", "fuente": "anking", "tema": 23, "anki": "1463875722646", "q": "Growth hormone exerts most of its growth-promoting effects indirectly through which mediator hormone?", "o": {"A": "Insulin-like growth factor 1 (IGF-1)", "B": "Thyroid hormone", "C": "Cortisol", "D": "Prolactin"}, "r": "A", "e": {"correcta": "GH stimulates the liver (and other tissues) to produce IGF-1, which acts locally and systemically to promote chondrocyte proliferation, protein synthesis, and overall tissue growth. Most of GH's anabolic and growth-promoting actions on bone and cartilage are mediated by IGF-1 rather than by GH acting directly on target tissues.", "incorrectas": {"B": "Thyroid hormone is essential for normal growth and CNS development (its deficiency causes cretinism), but it is not the direct downstream mediator of GH's growth-promoting signaling.", "C": "Cortisol has catabolic and growth-suppressing effects (e.g., inhibiting bone formation, causing growth retardation in excess), the opposite role from IGF-1 in mediating GH's anabolic actions.", "D": "Prolactin regulates lactation and is secreted from the same somatotroph lineage cells as GH but is not the mediator of GH's peripheral growth effects."}}}, {"id": "anking-endocrine-physiology-2536", "fuente": "anking", "tema": 23, "anki": "1463875730306", "q": "The pubertal growth spurt and long bone growth are primarily driven by which hormone?", "o": {"A": "Growth hormone directly", "B": "IGF-1", "C": "Testosterone alone", "D": "Estrogen alone"}, "r": "B", "e": {"correcta": "IGF-1, produced in response to GH stimulation, acts on the epiphyseal growth plates to drive chondrocyte proliferation and long bone elongation, making it the key mediator of the pubertal growth spurt. Sex steroids modulate the timing and eventual closure of the growth plates but the direct growth-promoting signal is IGF-1.", "incorrectas": {"A": "GH itself has some direct metabolic effects, but its growth-promoting action on bone length is predominantly indirect, mediated through hepatic and local IGF-1 production rather than acting directly at the growth plate.", "C": "Testosterone contributes to the pubertal growth spurt and eventual epiphyseal closure (via aromatization to estrogen), but it is not itself the primary mediator of long bone growth; that role belongs to IGF-1.", "D": "Estrogen is actually critical for epiphyseal plate closure (ending growth) in both sexes, rather than being the principal driver of the growth spurt itself."}}}, {"id": "anking-endocrine-physiology-2537", "fuente": "anking", "tema": 23, "anki": "1463875751991", "q": "What is the effect of growth hormone on muscle tissue?", "o": {"A": "Catabolic, increasing muscle protein breakdown", "B": "Anabolic, increasing muscle protein synthesis", "C": "No significant effect", "D": "Anabolic only in the presence of insulin deficiency"}, "r": "B", "e": {"correcta": "Growth hormone promotes anabolic effects in muscle, stimulating amino acid uptake and protein synthesis, which supports lean body mass accrual — this is part of why GH is abused for its muscle-building effects and why GH deficiency in children impairs growth and lean mass.", "incorrectas": {"A": "Catabolic effects (breakdown of protein) would oppose GH's actual physiologic role in muscle; GH instead favors nitrogen retention and protein synthesis in muscle tissue.", "C": "GH has well-documented, clinically significant anabolic effects on muscle (part of why it's used therapeutically and misused by athletes), so 'no significant effect' is incorrect.", "D": "GH's anabolic action on muscle is not contingent on insulin deficiency; in fact GH tends to antagonize insulin's effects on glucose metabolism (raising blood glucose), a distinct axis from its independent anabolic action on protein synthesis."}}}, {"id": "anking-endocrine-physiology-2538", "fuente": "anking", "tema": 23, "anki": "1463875758460", "q": "What is the effect of growth hormone on adipose tissue?", "o": {"A": "Anabolic, promoting fat storage", "B": "No effect on lipid metabolism", "C": "Catabolic, promoting lipolysis", "D": "Anabolic only during childhood"}, "r": "C", "e": {"correcta": "Growth hormone has catabolic (lipolytic) effects on adipose tissue, stimulating breakdown of triglycerides into free fatty acids for use as an energy substrate. This contrasts with its anabolic effects on muscle and is part of GH's broader role in shifting fuel utilization toward fat oxidation while sparing glucose and protein.", "incorrectas": {"A": "Promoting fat storage would be an anabolic (lipogenic) effect, which is the opposite of GH's actual catabolic action on adipocytes.", "B": "GH has a well-established, clinically relevant effect on lipid metabolism (lipolysis), so claiming no effect misrepresents its physiology.", "D": "GH's catabolic effect on adipose tissue is not restricted to childhood; it persists in adults and is part of why adult GH deficiency is associated with increased fat mass, while GH excess (acromegaly) can be associated with increased lipolysis."}}}, {"id": "anking-endocrine-pharmacology-2539", "fuente": "anking", "tema": 24, "anki": "1463875765045", "q": "Exogenous growth hormone (somatropin) is administered clinically primarily to treat which condition?", "o": {"A": "Growth hormone deficiency", "B": "Acromegaly", "C": "Cushing syndrome", "D": "Hyperthyroidism"}, "r": "A", "e": {"correcta": "Recombinant human growth hormone (somatropin) is given to replace deficient endogenous GH, most classically in children with GH deficiency causing short stature, and in certain adult GH-deficiency syndromes, to restore normal growth and metabolic effects.", "incorrectas": {"B": "Acromegaly is caused by GH excess (often from a pituitary adenoma), so treatment involves lowering GH/IGF-1 activity (e.g., octreotide, pegvisomant, cabergoline), the opposite of administering more GH.", "C": "Cushing syndrome results from cortisol excess and is treated by addressing the source of excess cortisol (e.g., surgery, ketoconazole, metyrapone), unrelated to GH replacement.", "D": "Hyperthyroidism is treated with antithyroid drugs, radioactive iodine, or surgery targeting excess thyroid hormone, not with growth hormone therapy."}}}, {"id": "anking-toxicities-side-effects-2540", "fuente": "anking", "tema": 29, "anki": "1463875809500", "q": "Mecasermin, a recombinant IGF-1 analog, carries which important metabolic adverse effect?", "o": {"A": "Hyperglycemia", "B": "Hypoglycemia", "C": "Hyperkalemia", "D": "Hypercalcemia"}, "r": "B", "e": {"correcta": "IGF-1 shares structural and receptor homology with insulin, so mecasermin can activate insulin receptor signaling and lower blood glucose, causing hypoglycemia as a key adverse effect that requires monitoring, particularly around meal timing.", "incorrectas": {"A": "Hyperglycemia is actually more characteristic of GH excess (acromegaly) since GH antagonizes insulin action, the opposite metabolic direction from IGF-1's insulin-like hypoglycemic effect.", "C": "Hyperkalemia is not a recognized adverse effect of mecasermin; its metabolic risk profile centers on glucose lowering due to insulin-receptor cross-reactivity.", "D": "Hypercalcemia is not associated with mecasermin; IGF-1's insulin-mimicking action affects glucose homeostasis, not calcium metabolism."}}}, {"id": "anking-endocrine-pathology-2541", "fuente": "anking", "tema": 5, "anki": "1463875820779", "q": "A growth hormone-secreting pituitary adenoma causes which condition when it occurs in adults, after the growth plates have already fused?", "o": {"A": "Gigantism", "B": "Acromegaly", "C": "Dwarfism", "D": "Cretinism"}, "r": "B", "e": {"correcta": "In adults, epiphyseal growth plates have already fused, so excess GH from a pituitary adenoma cannot cause linear growth. Instead, it causes acromegaly, characterized by enlargement of hands, feet, jaw (prognathism), soft tissue, and internal organs, along with insulin resistance.", "incorrectas": {"A": "Gigantism occurs when GH excess develops in children/adolescents before growth plate closure, allowing excessive linear (height) growth, which does not occur once the plates have fused in adulthood.", "C": "Dwarfism results from GH deficiency or resistance (e.g., Laron syndrome), the opposite hormonal problem from a GH-secreting adenoma.", "D": "Cretinism refers to congenital hypothyroidism causing severe growth and intellectual impairment, an entirely different hormonal axis from a GH-secreting tumor."}}}, {"id": "anking-gastrointestinal-pharmacology-2542", "fuente": "anking", "tema": 40, "anki": "1463875853686", "q": "Which somatostatin analog is used to treat VIPoma and carcinoid syndrome by inhibiting excessive hormone/mediator secretion?", "o": {"A": "Pegvisomant", "B": "Octreotide", "C": "Cabergoline", "D": "Mecasermin"}, "r": "B", "e": {"correcta": "Octreotide mimics somatostatin, broadly inhibiting secretion of numerous GI and endocrine hormones (including vasoactive intestinal peptide and serotonin/other vasoactive mediators). This makes it effective for symptomatic control of VIPoma (secretory diarrhea) and carcinoid syndrome (flushing, diarrhea, bronchospasm from serotonin and other mediators).", "incorrectas": {"A": "Pegvisomant is a GH receptor antagonist used specifically for acromegaly when other therapies fail, not for VIPoma or carcinoid syndrome.", "C": "Cabergoline is a dopamine D2 agonist used for prolactinoma and as adjunct therapy in acromegaly, not for inhibiting VIP or serotonin secretion.", "D": "Mecasermin is recombinant IGF-1 used for severe primary IGF-1 deficiency/GH insensitivity, unrelated to VIPoma or carcinoid syndrome management."}}}, {"id": "anking-gastrointestinal-pharmacology-2543", "fuente": "anking", "tema": 40, "anki": "1463875860762", "q": "Octreotide, a somatostatin analog, is used in the management of which pancreatic islet cell tumors?", "o": {"A": "Insulinoma, glucagonoma, and gastrinoma", "B": "Only insulinoma", "C": "Pancreatic adenocarcinoma", "D": "Pheochromocytoma"}, "r": "A", "e": {"correcta": "Somatostatin physiologically inhibits release of numerous GI and pancreatic hormones. Octreotide exploits this to suppress hormone hypersecretion from functioning islet cell tumors, providing symptomatic relief in insulinoma (hypoglycemia), glucagonoma (hyperglycemia, necrolytic migratory erythema), and gastrinoma (Zollinger-Ellison syndrome, acid hypersecretion).", "incorrectas": {"B": "Limiting octreotide's use to only insulinoma understates its broader utility across multiple hormone-secreting islet cell tumors, including glucagonoma and gastrinoma.", "C": "Pancreatic adenocarcinoma is an exocrine pancreatic malignancy typically managed with surgery/chemotherapy (e.g., FOLFIRINOX), not primarily with octreotide, since it isn't a hormone-hypersecreting islet cell tumor.", "D": "Pheochromocytoma is a catecholamine-secreting adrenal medullary tumor managed with alpha- then beta-blockade before surgery, not with octreotide."}}}, {"id": "anking-gastrointestinal-pharmacology-2544", "fuente": "anking", "tema": 40, "anki": "1463875872656", "q": "Octreotide can help manage which type of GI bleeding by reducing portal blood flow and variceal pressure?", "o": {"A": "Esophageal variceal bleeding", "B": "Mallory-Weiss tear bleeding", "C": "Angiodysplasia bleeding", "D": "Meckel diverticulum bleeding"}, "r": "A", "e": {"correcta": "Octreotide, like vasopressin, reduces splanchnic and portal blood flow (via inhibition of vasodilatory GI hormones such as glucagon), which lowers portal pressure and decreases flow through esophageal varices, making it a mainstay adjunct in acute variceal hemorrhage management alongside endoscopic therapy.", "incorrectas": {"B": "Mallory-Weiss tears (mucosal lacerations from forceful vomiting) are usually self-limited or managed endoscopically, not primarily with octreotide, since they are not driven by portal hypertension.", "C": "Angiodysplasia bleeding, often in the colon and associated with conditions like aortic stenosis, is managed endoscopically or surgically, not with portal-pressure-lowering agents like octreotide.", "D": "Meckel diverticulum bleeding (from ectopic gastric mucosa) is managed surgically, unrelated to portal hypertension or octreotide's mechanism."}}}, {"id": "anking-toxicities-side-effects-2545", "fuente": "anking", "tema": 29, "anki": "1463875878919", "q": "Octreotide commonly causes which category of adverse effects, including nausea, vomiting, and abdominal pain?", "o": {"A": "Cardiovascular side effects", "B": "GI side effects", "C": "Neurologic side effects", "D": "Dermatologic side effects"}, "r": "B", "e": {"correcta": "Because octreotide broadly suppresses GI hormone and secretory activity (reducing motility, pancreatic enzyme output, and gallbladder contraction), it commonly produces GI adverse effects such as nausea, vomiting, abdominal pain, and can predispose to gallstones and steatorrhea.", "incorrectas": {"A": "While octreotide can have some hemodynamic effects related to splanchnic vasoconstriction, its predominant and characteristic adverse effect profile is GI, not primarily cardiovascular.", "C": "Neurologic side effects are not a hallmark of octreotide therapy; its actions are concentrated on GI/endocrine secretion and motility.", "D": "Dermatologic side effects are not a typical or prominent feature of octreotide use; the well-documented adverse effects are gastrointestinal in nature."}}}, {"id": "anking-gastrointestinal-physiology-2546", "fuente": "anking", "tema": 39, "anki": "1463875891261", "q": "Octreotide can cause steatorrhea through which mechanism?", "o": {"A": "Increased pancreatic enzyme secretion", "B": "Decreased pancreatic secretions and gallbladder contractility", "C": "Direct mucosal toxicity to enterocytes", "D": "Increased bile acid synthesis"}, "r": "B", "e": {"correcta": "Octreotide suppresses secretin- and CCK-mediated pancreatic exocrine secretion and inhibits CCK-induced gallbladder contraction. The resulting deficiency of pancreatic lipase and impaired bile delivery to the gut lumen reduces fat digestion/emulsification, leading to malabsorption and steatorrhea; the reduced gallbladder emptying also predisposes to gallstones from bile stasis.", "incorrectas": {"A": "Increased pancreatic enzyme secretion would improve, not impair, fat digestion, which is the opposite of octreotide's actual inhibitory effect on the exocrine pancreas.", "C": "Octreotide's steatorrhea is a functional/secretory effect from hormone suppression, not from direct cytotoxic damage to the intestinal mucosa.", "D": "Octreotide decreases, rather than increases, CCK-driven gallbladder contraction and bile flow into the duodenum, contributing to fat malabsorption rather than enhancing bile-mediated digestion."}}}, {"id": "anking-endocrine-pharmacology-2547", "fuente": "anking", "tema": 24, "anki": "1463875916163", "q": "In addition to treating acromegaly, dopamine D2 receptor agonists like cabergoline and bromocriptine are used to treat which condition?", "o": {"A": "Hypoprolactinemia", "B": "Hyperprolactinemia (e.g., prolactinoma)", "C": "Hypothyroidism", "D": "Adrenal insufficiency"}, "r": "B", "e": {"correcta": "Dopamine normally acts as the tonic inhibitor of prolactin secretion from lactotrophs. D2 agonists like cabergoline and bromocriptine mimic this inhibitory tone, effectively lowering prolactin levels, which makes them first-line medical therapy for prolactinomas and other causes of hyperprolactinemia.", "incorrectas": {"A": "Hypoprolactinemia (low prolactin) is not a clinically significant treatment target, and D2 agonists would lower prolactin further, worsening rather than treating low prolactin states.", "C": "Hypothyroidism is treated with levothyroxine replacement, unrelated to dopaminergic modulation of prolactin.", "D": "Adrenal insufficiency is treated with glucocorticoid (and mineralocorticoid) replacement, not with dopamine agonists, which act on the pituitary lactotroph/prolactin axis, not the adrenal axis."}}}, {"id": "anking-endocrine-pathology-2548", "fuente": "anking", "tema": 5, "anki": "1463875952548", "q": "Which hormone-secreting pancreatic islet cell tumor is classically associated with necrolytic migratory erythema?", "o": {"A": "Insulinoma", "B": "Gastrinoma", "C": "Glucagonoma", "D": "Somatostatinoma"}, "r": "C", "e": {"correcta": "Glucagonoma, a glucagon-secreting pancreatic islet cell tumor, produces the classic tetrad of necrolytic migratory erythema (a characteristic spreading, blistering rash), diabetes/hyperglycemia, deep vein thrombosis, and depression, often summarized mnemonically as the '4 D's' (dermatitis, diabetes, DVT, depression).", "incorrectas": {"A": "Insulinoma causes hypoglycemia with Whipple's triad (low glucose, symptoms of hypoglycemia, relief with glucose), not the skin rash associated with glucagon excess.", "B": "Gastrinoma causes Zollinger-Ellison syndrome with recurrent peptic ulcers and diarrhea from gastric acid hypersecretion, not necrolytic migratory erythema.", "D": "Somatostatinoma causes the triad of diabetes, gallstones, and steatorrhea due to widespread inhibition of pancreatic and biliary secretions, not the characteristic rash of glucagonoma."}}}, {"id": "anking-endocrine-pharmacology-2549", "fuente": "anking", "tema": 24, "anki": "1463883728414", "q": "In its unbound (inactive) state, where is the glucocorticoid receptor primarily located within the cell?", "o": {"A": "Nucleus, bound to DNA", "B": "Plasma membrane", "C": "Cytoplasm", "D": "Endoplasmic reticulum"}, "r": "C", "e": {"correcta": "The glucocorticoid receptor is a cytoplasmic (intracellular) nuclear hormone receptor, held inactive in the cytoplasm in complex with heat shock proteins. Once a lipophilic glucocorticoid diffuses across the plasma membrane and binds the receptor, the complex dissociates from HSPs and translocates into the nucleus to modulate gene transcription.", "incorrectas": {"A": "The receptor moves to the nucleus and binds DNA/glucocorticoid response elements only after ligand binding and activation, not while unbound.", "B": "Glucocorticoid receptors are intracellular, not membrane-bound receptors; steroid hormones cross the lipid bilayer to reach their cytoplasmic receptor rather than binding a surface receptor.", "D": "The endoplasmic reticulum is not the resting location of the glucocorticoid receptor; it resides in the cytoplasm complexed with chaperone heat shock proteins until hormone binding occurs."}}}, {"id": "anking-endocrine-pharmacology-2550", "fuente": "anking", "tema": 24, "anki": "1463883746350", "q": "What effect do glucocorticoids have on the production/activity of phospholipase A2?", "o": {"A": "Increased (stimulation)", "B": "No effect", "C": "Decreased (inhibition)", "D": "Biphasic: increased acutely, decreased chronically"}, "r": "C", "e": {"correcta": "Glucocorticoids induce the synthesis of lipocortin (annexin-1), which inhibits phospholipase A2. This blocks release of arachidonic acid from membrane phospholipids, upstream of both the cyclooxygenase and lipoxygenase pathways, giving glucocorticoids their broad anti-inflammatory effect on prostaglandins and leukotrienes alike.", "incorrectas": {"A": "Increasing phospholipase A2 activity would promote arachidonic acid release and downstream inflammatory mediator synthesis, the opposite of glucocorticoids' anti-inflammatory mechanism.", "B": "Glucocorticoids have a well-defined inhibitory effect on phospholipase A2 via lipocortin induction; 'no effect' misses this central mechanism of their anti-inflammatory action.", "D": "There is no clinically significant biphasic pattern; the therapeutic and physiologic hallmark of glucocorticoids is consistent inhibition of phospholipase A2, not a shift from stimulation to inhibition over time."}}}, {"id": "anking-endocrine-pharmacology-2551", "fuente": "anking", "tema": 24, "anki": "1463883753623", "q": "Glucocorticoids reduce inflammation in part by inhibiting phospholipase A2, thereby preventing production of which molecule?", "o": {"A": "Thromboxane A2", "B": "Prostacyclin", "C": "Arachidonic acid", "D": "Leukotriene B4"}, "r": "C", "e": {"correcta": "Phospholipase A2 cleaves membrane phospholipids to liberate arachidonic acid, the precursor substrate for both the cyclooxygenase pathway (prostaglandins, thromboxane) and the lipoxygenase pathway (leukotrienes). By inhibiting phospholipase A2 (via lipocortin), glucocorticoids cut off arachidonic acid production at its source, broadly suppressing all downstream eicosanoid mediators of inflammation.", "incorrectas": {"A": "Thromboxane A2 is a downstream product of arachidonic acid via the COX pathway; it is reduced as a consequence of blocking arachidonic acid release, but it is not itself the molecule directly prevented by phospholipase A2 inhibition.", "B": "Prostacyclin, like thromboxane, is a COX-pathway product made from arachidonic acid, and its reduction is a downstream consequence, not the direct target of phospholipase A2 inhibition.", "D": "Leukotriene B4 arises from the lipoxygenase pathway acting on arachidonic acid; like the other eicosanoids, it decreases only because its arachidonic acid precursor is cut off upstream by phospholipase A2 inhibition."}}}, {"id": "anking-endocrine-pharmacology-2552", "fuente": "anking", "tema": 24, "anki": "1463883760907", "q": "Glucocorticoids reduce inflammation in part by inhibiting cyclooxygenase-mediated production of which inflammatory mediators?", "o": {"A": "Leukotrienes", "B": "Prostaglandins", "C": "Thromboxanes", "D": "Bradykinin"}, "r": "B", "e": {"correcta": "Glucocorticoids induce lipocortin (annexin-A1), which inhibits phospholipase A2 and reduces arachidonic acid release; downstream, this decreases cyclooxygenase-generated prostaglandins, which mediate vasodilation, pain, and fever during inflammation.", "incorrectas": {"A": "Leukotrienes are also reduced by glucocorticoids, but they are produced by the lipoxygenase pathway, not cyclooxygenase, making this the wrong pathway for this question.", "C": "Thromboxanes are synthesized from the cyclooxygenase pathway (via COX-1 in platelets) but are primarily involved in platelet aggregation and vasoconstriction, not the classic 'inflammatory' mediator emphasized in this glucocorticoid mechanism.", "D": "Bradykinin is generated by the kallikrein-kinin system, independent of both cyclooxygenase and lipoxygenase, so it is not directly affected by glucocorticoid inhibition of phospholipase A2."}}}, {"id": "anking-endocrine-pharmacology-2553", "fuente": "anking", "tema": 24, "anki": "1463883769980", "q": "Glucocorticoids reduce inflammation in part by inhibiting lipoxygenase-mediated production of which inflammatory mediators?", "o": {"A": "Prostaglandins", "B": "Thromboxanes", "C": "Leukotrienes", "D": "Prostacyclin"}, "r": "C", "e": {"correcta": "By inducing lipocortin to inhibit phospholipase A2, glucocorticoids decrease the arachidonic acid substrate available to lipoxygenase, lowering leukotriene production; leukotrienes drive neutrophil chemotaxis and bronchoconstriction, which is why glucocorticoids are effective in asthma.", "incorrectas": {"A": "Prostaglandins arise from the cyclooxygenase pathway, not lipoxygenase, so although glucocorticoids also reduce prostaglandins, that occurs via a different enzymatic route than the one asked about here.", "B": "Thromboxanes are cyclooxygenase (COX-1) products important in platelet aggregation, unrelated to the lipoxygenase pathway targeted in this question.", "D": "Prostacyclin (PGI2) is also a cyclooxygenase product (via COX-2 in endothelium) that promotes vasodilation and inhibits platelet aggregation, not a lipoxygenase product."}}}, {"id": "anking-endocrine-pharmacology-2554", "fuente": "anking", "tema": 24, "anki": "1463883777608", "q": "Glucocorticoids suppress production of proinflammatory cytokines such as IL-2 and TNF-alpha primarily by inhibiting which transcription factor?", "o": {"A": "AP-1", "B": "STAT3", "C": "NF-kB", "D": "NFAT"}, "r": "C", "e": {"correcta": "Glucocorticoids bind intracellular receptors that translocate to the nucleus and induce IkB, which sequesters NF-kB in the cytoplasm and prevents it from activating transcription of proinflammatory cytokine genes (e.g., IL-2, TNF-alpha, IL-1), producing broad anti-inflammatory and immunosuppressive effects.", "incorrectas": {"A": "AP-1 is another transcription factor involved in inflammatory gene expression that can be antagonized by glucocorticoid receptor interactions, but the classically tested, primary mechanism emphasized for glucocorticoids is inhibition of NF-kB.", "B": "STAT3 is activated downstream of cytokine receptors (e.g., IL-6) via the JAK-STAT pathway and is not the direct target of glucocorticoid-mediated anti-inflammatory action.", "D": "NFAT is the transcription factor inhibited by calcineurin inhibitors like cyclosporine and tacrolimus (which block IL-2 gene transcription), not the primary target of glucocorticoids."}}}, {"id": "anking-endocrine-pharmacology-2555", "fuente": "anking", "tema": 24, "anki": "1463883793510", "q": "Glucocorticoids inhibit production of IL-2, thereby preventing activation of which two lymphocyte populations?", "o": {"A": "NK cells and macrophages", "B": "T cells and B cells", "C": "Dendritic cells and eosinophils", "D": "Neutrophils and mast cells"}, "r": "B", "e": {"correcta": "IL-2 is required for clonal proliferation and activation of both T cells (autocrine/paracrine signaling from helper T cells) and, indirectly, B cells; by suppressing IL-2 and other cytokine transcription via NF-kB inhibition, glucocorticoids blunt both cellular and humoral adaptive immune activation.", "incorrectas": {"A": "NK cells and macrophages are part of innate immunity and are affected by glucocorticoids through other mechanisms (e.g., reduced cytokine signaling), but the classic IL-2-dependent activation step described here specifically concerns adaptive lymphocytes, T and B cells.", "C": "Dendritic cells and eosinophils are affected by glucocorticoids (e.g., eosinopenia occurs), but they are not the direct targets of the IL-2-dependent activation blockade being tested here.", "D": "Neutrophils actually increase in number with glucocorticoid use (due to demargination) rather than being suppressed, and mast cells are not the primary IL-2-dependent cell type in this mechanism."}}}, {"id": "anking-hematology-oncology-pathology-2556", "fuente": "anking", "tema": 6, "anki": "1463883801028", "q": "Glucocorticoids cause neutrophilia primarily through which mechanism?", "o": {"A": "Increased bone marrow neutrophil production", "B": "Decreased neutrophil apoptosis in tissues", "C": "Impaired neutrophil adhesion causing demargination", "D": "Inhibition of neutrophil extravasation receptors on endothelium alone"}, "r": "C", "e": {"correcta": "Glucocorticoids decrease expression of adhesion molecules on neutrophils and endothelium, impairing margination (the normal adherence of neutrophils to vessel walls); this releases the marginated pool into circulation, causing an apparent neutrophilia despite glucocorticoids actually impairing neutrophil function.", "incorrectas": {"A": "While glucocorticoids can have some effects on marrow release kinetics, the classically tested and predominant mechanism for the acute rise in circulating neutrophils is demargination of the pre-existing marginated pool, not new production.", "B": "Glucocorticoids do not primarily act by preventing neutrophil apoptosis; in fact, they promote apoptosis of lymphocytes, which is the opposite effect seen in lymphopenia, not the mechanism behind neutrophilia.", "D": "This option isolates only the endothelial side of adhesion, but the overall phenomenon requires impaired neutrophil-endothelial adhesion broadly (demargination), a more complete description than endothelial receptor inhibition alone."}}}, {"id": "anking-hematology-oncology-pathology-2557", "fuente": "anking", "tema": 6, "anki": "1463883821477", "q": "A patient started on high-dose prednisone develops an elevated absolute neutrophil count on routine labs despite no evidence of infection. What is the most likely explanation?", "o": {"A": "Steroid-induced bone marrow stimulation of granulopoiesis", "B": "Glucocorticoid-induced neutrophilia from demargination", "C": "Glucocorticoid-induced left shift from acute infection", "D": "Steroid-induced eosinophilia mistaken for neutrophilia"}, "r": "B", "e": {"correcta": "Glucocorticoids impair leukocyte adhesion molecule expression, causing the marginated pool of neutrophils (those loosely adherent to vessel walls) to be released into the circulating pool; this produces a benign, dose-related neutrophilia that is a known pharmacologic effect rather than a sign of infection.", "incorrectas": {"A": "Although chronic steroid use has various marrow effects, the acute and classically tested mechanism for the neutrophil count rise is demargination of the existing pool, not new stimulation of granulopoiesis.", "C": "A left shift (increased band forms) suggests bacterial infection driving new neutrophil release from the marrow reserve pool; glucocorticoid-induced neutrophilia does not require infection and does not represent a left shift.", "D": "Glucocorticoids cause eosinopenia (a decrease in eosinophils), the opposite of eosinophilia, so this explanation is inconsistent with known steroid pharmacology."}}}, {"id": "anking-hematology-oncology-pathology-2558", "fuente": "anking", "tema": 6, "anki": "1463883835006", "q": "Chronic glucocorticoid therapy has what effect on circulating lymphocyte counts, particularly T-helper cells?", "o": {"A": "Increase, due to redistribution from lymphoid organs", "B": "No significant change", "C": "Decrease, due to apoptosis and redistribution into lymphoid tissue", "D": "Increase, due to inhibited apoptosis"}, "r": "C", "e": {"correcta": "Glucocorticoids cause lymphopenia by inhibiting proinflammatory cytokine production, inducing apoptosis of lymphocytes (especially T-helper cells), and redistributing circulating lymphocytes into the spleen, lymph nodes, and bone marrow, all of which lower peripheral blood lymphocyte counts.", "incorrectas": {"A": "This reverses the actual direction of redistribution; glucocorticoids move lymphocytes out of the peripheral blood and into lymphoid organs, not from lymphoid organs into circulation.", "B": "Glucocorticoids have a well-documented, clinically significant lymphopenic effect, particularly targeting T-helper cells, which is why chronic steroid use increases susceptibility to opportunistic infections.", "D": "Glucocorticoids promote lymphocyte apoptosis rather than inhibiting it; this pro-apoptotic effect on lymphocytes contrasts with their anti-apoptotic effect on neutrophils in tissues."}}}, {"id": "anking-hematology-oncology-pathology-2559", "fuente": "anking", "tema": 6, "anki": "1463883881957", "q": "Glucocorticoid therapy in a patient with severe asthma exacerbation is expected to have what effect on peripheral eosinophil counts?", "o": {"A": "Increase (eosinophilia)", "B": "No change", "C": "Decrease (eosinopenia)", "D": "Transient increase followed by rebound decrease"}, "r": "C", "e": {"correcta": "Glucocorticoids reduce peripheral eosinophil counts (eosinopenia) by promoting eosinophil apoptosis and altering trafficking out of the circulation, which is part of why they are effective therapy for eosinophil-driven allergic conditions like asthma.", "incorrectas": {"A": "Eosinophilia would be expected in untreated allergic or parasitic disease, but glucocorticoid treatment has the opposite effect, lowering eosinophil counts as part of its anti-inflammatory action.", "B": "Glucocorticoids reliably and significantly reduce eosinophil counts; this effect is consistent and clinically relevant enough that a lack of change would be atypical and unexpected.", "D": "There is no well-described rebound eosinophilia phenomenon after glucocorticoid dosing; the expected effect is simply a sustained decrease in circulating eosinophils during therapy."}}}, {"id": "anking-endocrine-pharmacology-2560", "fuente": "anking", "tema": 24, "anki": "1463883894010", "q": "Glucocorticoids are therapeutically useful for which broad category of disorders, including gout, rheumatoid arthritis, asthma, and IBD?", "o": {"A": "Neoplastic disorders", "B": "Infectious disorders", "C": "Inflammatory disorders", "D": "Metabolic disorders"}, "r": "C", "e": {"correcta": "Glucocorticoids suppress the inflammatory cascade at multiple levels (reduced prostaglandins, leukotrienes, cytokines, and leukocyte trafficking), making them broadly useful across inflammatory conditions such as gout, rheumatoid arthritis, asthma, and inflammatory bowel disease.", "incorrectas": {"A": "Although glucocorticoids are used as adjunct chemotherapy in some hematologic malignancies (e.g., lymphoma, leukemia) due to lymphocytotoxic effects, this is a distinct application from their primary anti-inflammatory use in the conditions listed here.", "B": "Glucocorticoids are immunosuppressive and can worsen infections (e.g., reactivate latent TB); they are not used to treat infectious disorders directly and can actually predispose to them.", "D": "Glucocorticoids cause metabolic derangements (hyperglycemia, insulin resistance) as adverse effects, but they are not used therapeutically to treat metabolic disorders; the listed conditions (gout, RA, asthma, IBD) are inflammatory in nature."}}}, {"id": "anking-endocrine-pharmacology-2561", "fuente": "anking", "tema": 24, "anki": "1463883902817", "q": "Glucocorticoids are used clinically for what type of therapy in transplant rejection prevention and autoimmune disease treatment?", "o": {"A": "Antimicrobial therapy", "B": "Immunosuppressive therapy", "C": "Anticoagulant therapy", "D": "Chemotherapeutic cytoreduction"}, "r": "B", "e": {"correcta": "By inhibiting NF-kB-driven cytokine production and promoting lymphocyte apoptosis and redistribution, glucocorticoids broadly dampen adaptive immune responses, making them valuable immunosuppressants for preventing transplant rejection and treating autoimmune disorders such as lupus or rheumatoid arthritis.", "incorrectas": {"A": "Glucocorticoids have no direct antimicrobial activity; in fact, their immunosuppressive effects increase susceptibility to infection, the opposite of an antimicrobial therapy.", "C": "Glucocorticoids are not anticoagulants; pregnancy and other conditions affect coagulation, but glucocorticoids' therapeutic role here is immune suppression, not anticoagulation.", "D": "While glucocorticoids can induce apoptosis in some lymphoid malignancies as adjunct therapy, their primary described use in transplant and autoimmune disease is broad immunosuppression, not tumor cytoreduction."}}}, {"id": "anking-endocrine-pharmacology-2562", "fuente": "anking", "tema": 24, "anki": "1463883909077", "q": "What effect do glucocorticoids have on peripheral insulin sensitivity?", "o": {"A": "Increase insulin sensitivity", "B": "No effect on insulin action", "C": "Increase insulin resistance", "D": "Selectively increase hepatic insulin sensitivity only"}, "r": "C", "e": {"correcta": "Glucocorticoids antagonize insulin action in peripheral tissues (muscle and fat), increasing insulin resistance; combined with stimulated hepatic gluconeogenesis, this contributes to steroid-induced hyperglycemia and can unmask or worsen diabetes ('steroid diabetes').", "incorrectas": {"A": "This is the opposite of the actual effect; glucocorticoids are counter-regulatory hormones that oppose insulin action rather than enhancing it.", "B": "Glucocorticoids have a well-documented and clinically significant effect on glucose metabolism, making 'no effect' inconsistent with their known hyperglycemic and diabetogenic properties.", "D": "Glucocorticoids increase insulin resistance systemically in peripheral tissues (muscle, fat) in addition to promoting hepatic gluconeogenesis, so the effect is not limited to or selectively increasing hepatic insulin sensitivity."}}}, {"id": "anking-endocrine-pharmacology-2563", "fuente": "anking", "tema": 24, "anki": "1463883917060", "q": "Glucocorticoids can cause hyperglycemia by stimulating which hepatic metabolic process?", "o": {"A": "Glycogenolysis", "B": "Gluconeogenesis", "C": "Glycolysis", "D": "Lipogenesis"}, "r": "B", "e": {"correcta": "Glucocorticoids upregulate hepatic gluconeogenesis (synthesis of new glucose from amino acids, lactate, and glycerol), raising blood glucose; this, combined with increased peripheral insulin resistance, is the basis for steroid-induced hyperglycemia and 'steroid diabetes.'", "incorrectas": {"A": "Glycogenolysis (breakdown of stored glycogen) is more classically driven by glucagon and epinephrine in acute settings; glucocorticoids' major hepatic glucose-raising effect highlighted in pharmacology is gluconeogenesis, and they actually promote glycogen storage rather than its breakdown.", "C": "Glycolysis breaks down glucose for energy and would lower, not raise, blood glucose; this is not consistent with the hyperglycemic effect of glucocorticoids.", "D": "Lipogenesis refers to fat synthesis; while glucocorticoids do have complex effects on central fat distribution, the hepatic glucose-raising mechanism specifically described here is gluconeogenesis, not lipogenesis."}}}, {"id": "anking-endocrine-pharmacology-2564", "fuente": "anking", "tema": 24, "anki": "1463883924914", "q": "In addition to stimulating gluconeogenesis, glucocorticoids increase which hepatic storage process?", "o": {"A": "Glycogen storage", "B": "Triglyceride storage", "C": "Protein storage", "D": "Ketone body storage"}, "r": "A", "e": {"correcta": "Glucocorticoids increase hepatic glycogen storage by promoting glycogen synthase activity, working alongside increased gluconeogenesis; the liver both makes more glucose and stores more of it as glycogen, while peripheral tissues become insulin resistant and cannot take up glucose as effectively.", "incorrectas": {"B": "Glucocorticoids do promote fat redistribution (central/truncal obesity) but this occurs through complex effects on adipocyte differentiation and lipolysis in the periphery, not specifically through hepatic triglyceride storage as the classic teaching point.", "C": "Glucocorticoids are catabolic toward peripheral protein (muscle breakdown to supply amino acids for gluconeogenesis), the opposite of promoting protein storage.", "D": "Ketone body production and storage are not the primary hepatic effect described for glucocorticoids; their well-characterized hepatic effects are increased gluconeogenesis and glycogen storage."}}}, {"id": "anking-endocrine-pharmacology-2565", "fuente": "anking", "tema": 24, "anki": "1463883932504", "q": "Exogenous glucocorticoids are used as replacement therapy for which condition, which can otherwise progress to circulatory shock, hypoglycemia, and death?", "o": {"A": "Cushing syndrome", "B": "Adrenal insufficiency", "C": "Hyperaldosteronism", "D": "Pheochromocytoma"}, "r": "B", "e": {"correcta": "In adrenal insufficiency (e.g., Addison disease), the adrenal cortex fails to produce adequate cortisol, leading to hypoglycemia, hypotension, and potentially life-threatening adrenal crisis; exogenous glucocorticoid replacement restores the metabolic and hemodynamic support cortisol normally provides.", "incorrectas": {"A": "Cushing syndrome results from excess glucocorticoid activity (endogenous or iatrogenic), so administering more glucocorticoids would worsen, not treat, this condition.", "C": "Hyperaldosteronism involves excess mineralocorticoid activity causing hypertension and hypokalemia; glucocorticoid replacement is not the treatment, and this differs mechanistically from cortisol deficiency.", "D": "Pheochromocytoma is a catecholamine-secreting adrenal medullary tumor causing episodic hypertension; it is unrelated to cortisol deficiency and is not treated with glucocorticoid replacement."}}}, {"id": "anking-toxicities-side-effects-2566", "fuente": "anking", "tema": 29, "anki": "1463883949810", "q": "Chronic glucocorticoid use has what effect on peripheral skeletal muscle, contributing to weakness and thin extremities?", "o": {"A": "Anabolic effect", "B": "Catabolic effect", "C": "No significant effect", "D": "Hypertrophic effect"}, "r": "B", "e": {"correcta": "Glucocorticoids exert a catabolic (proteolytic) effect on peripheral skeletal muscle, breaking down muscle protein to supply amino acids for hepatic gluconeogenesis; over time, this produces muscle wasting, weakness, and thin extremities, a hallmark finding in Cushing syndrome and chronic steroid therapy.", "incorrectas": {"A": "This is the opposite effect on peripheral muscle; glucocorticoids are catabolic (not anabolic) in peripheral tissue, though they can have anabolic effects on central adipose tissue, causing truncal obesity.", "C": "The catabolic muscle-wasting effect of chronic glucocorticoid use is well documented and clinically significant (steroid myopathy), so 'no effect' is inconsistent with known pharmacology.", "D": "Muscle hypertrophy would require an anabolic stimulus (e.g., testosterone, growth hormone); glucocorticoids instead cause muscle atrophy through proteolysis."}}}, {"id": "anking-toxicities-side-effects-2567", "fuente": "anking", "tema": 29, "anki": "1463883989820", "q": "Glucocorticoids have what effect on peripheral (extremity) fat tissue, in contrast to their effect on central adiposity?", "o": {"A": "Anabolic (lipogenic) effect", "B": "Catabolic (lipolytic) effect", "C": "No effect", "D": "Effect identical to central fat tissue"}, "r": "B", "e": {"correcta": "Glucocorticoids have a catabolic, lipolytic effect on peripheral fat (extremities), breaking down fat stores there, while paradoxically having anabolic effects on central/truncal fat; this differential effect produces the classic 'thin extremities with truncal obesity and moon facies' appearance of Cushing syndrome.", "incorrectas": {"A": "An anabolic/lipogenic effect describes what happens in central fat depots, not peripheral fat; peripheral tissue undergoes lipolysis (fat breakdown) rather than fat accumulation under glucocorticoid excess.", "C": "Glucocorticoids have a clear and clinically apparent lipolytic effect on peripheral fat, contributing to the characteristic thin extremities seen with chronic steroid excess, so 'no effect' is incorrect.", "D": "Glucocorticoids act differently on central versus peripheral fat depots (anabolic centrally, catabolic peripherally); describing the effects as identical misses this key distinguishing feature of steroid-induced fat redistribution."}}}, {"id": "anking-endocrine-pathology-2568", "fuente": "anking", "tema": 5, "anki": "1463884000084", "q": "Prolonged administration of exogenous glucocorticoids (e.g., for an autoimmune condition) can cause which iatrogenic syndrome?", "o": {"A": "Addison disease", "B": "Conn syndrome", "C": "Cushing syndrome", "D": "Nelson syndrome"}, "r": "C", "e": {"correcta": "Chronic exogenous glucocorticoid use is the most common cause of Cushing syndrome overall (iatrogenic Cushing syndrome), producing features like truncal obesity, moon facies, buffalo hump, striae, hyperglycemia, hypertension, and osteoporosis due to sustained excess glucocorticoid activity.", "incorrectas": {"A": "Addison disease is primary adrenal insufficiency, characterized by cortisol deficiency, essentially the opposite condition from what results from excess exogenous glucocorticoid administration.", "B": "Conn syndrome is primary hyperaldosteronism due to excess mineralocorticoid activity, causing hypertension and hypokalemia, a distinct entity from glucocorticoid excess.", "D": "Nelson syndrome refers to an ACTH-secreting pituitary tumor that develops after bilateral adrenalectomy for Cushing disease, an unrelated and much rarer clinical scenario than straightforward iatrogenic steroid excess."}}}, {"id": "anking-toxicities-side-effects-2569", "fuente": "anking", "tema": 29, "anki": "1463884018201", "q": "Chronic glucocorticoid therapy can cause osteoporosis through which mechanism, and what supplementation helps prevent this adverse effect?", "o": {"A": "Inhibition of osteoclast activity; prevented with bisphosphonates only", "B": "Inhibition of osteoblast activity; prevented with calcium and vitamin D", "C": "Stimulation of osteoclast activity; prevented with estrogen replacement", "D": "Increased renal calcium reabsorption; prevented with loop diuretics"}, "r": "B", "e": {"correcta": "Glucocorticoids inhibit osteoblast activity (reducing new bone formation) and also increase bone resorption indirectly, leading to progressive bone loss and osteoporosis with long-term use; guidelines recommend calcium and vitamin D supplementation (and sometimes bisphosphonates) to help mitigate this risk in patients on chronic steroid therapy.", "incorrectas": {"A": "Glucocorticoids act mainly by suppressing osteoblasts (bone-forming cells) rather than directly inhibiting osteoclasts; and while bisphosphonates are used in some patients, the first-line preventive measure emphasized is calcium plus vitamin D supplementation.", "C": "Glucocorticoids do not directly stimulate osteoclasts as their primary mechanism; the dominant effect is suppression of osteoblast-mediated bone formation, and estrogen replacement is not the standard preventive measure for steroid-induced osteoporosis.", "D": "Increased renal calcium reabsorption would tend to preserve bone calcium, which is not the mechanism of glucocorticoid-induced bone loss; loop diuretics actually increase renal calcium excretion and are not used to prevent steroid osteoporosis."}}}, {"id": "anking-toxicities-side-effects-2570", "fuente": "anking", "tema": 29, "anki": "1463884026871", "q": "High-dose glucocorticoid therapy can cause a neuropsychiatric adverse effect characterized by hypomania, confusion, and hallucinations. What is this called?", "o": {"A": "Steroid-induced psychosis", "B": "Serotonin syndrome", "C": "Neuroleptic malignant syndrome", "D": "Wernicke encephalopathy"}, "r": "A", "e": {"correcta": "High-dose glucocorticoids can precipitate steroid-induced psychosis, presenting with mood disturbances such as hypomania or mania, confusion, and hallucinations; this is a recognized dose-dependent neuropsychiatric adverse effect that typically improves with steroid tapering or discontinuation.", "incorrectas": {"B": "Serotonin syndrome results from excess serotonergic activity (e.g., from combining SSRIs, MAOIs, or other serotonergic drugs), presenting with hyperthermia, clonus, and autonomic instability, not from glucocorticoid use.", "C": "Neuroleptic malignant syndrome is caused by dopamine receptor antagonists (antipsychotics), presenting with rigidity, hyperthermia, and autonomic instability, unrelated to glucocorticoid pharmacology.", "D": "Wernicke encephalopathy results from thiamine (B1) deficiency, presenting with confusion, ataxia, and ophthalmoplegia, a distinct nutritional deficiency syndrome not caused by glucocorticoids."}}}, {"id": "anking-toxicities-side-effects-2571", "fuente": "anking", "tema": 29, "anki": "1463884086021", "q": "Chronic glucocorticoid use predisposes to reactivation of latent infections, presenting as cavitary lesions in the upper lung lobes. Which organism is classically implicated?", "o": {"A": "Mycobacterium tuberculosis", "B": "Pneumocystis jirovecii", "C": "Aspergillus fumigatus", "D": "Histoplasma capsulatum"}, "r": "A", "e": {"correcta": "Glucocorticoid-induced immunosuppression (particularly impaired T-cell function) can reactivate latent tuberculosis, since cell-mediated immunity normally keeps M. tuberculosis contained within granulomas; reactivation classically presents with cavitary lesions in the upper lung lobes, which have higher oxygen tension favoring mycobacterial growth.", "incorrectas": {"B": "Pneumocystis jirovecii pneumonia is an opportunistic infection seen with glucocorticoid-induced immunosuppression, but it typically presents with diffuse interstitial infiltrates and hypoxia, not classic upper-lobe cavitary lesions.", "C": "Aspergillus can cause invasive disease in immunosuppressed patients and sometimes forms cavitary lesions (aspergilloma in pre-existing cavities), but it is not the organism classically associated with reactivation from latency the way TB is.", "D": "Histoplasma capsulatum can reactivate in immunosuppressed hosts and cause pulmonary disease, but it is not the classic organism highlighted for glucocorticoid-associated reactivation with upper-lobe cavitation; that is a hallmark of TB."}}}, {"id": "anking-toxicities-side-effects-2572", "fuente": "anking", "tema": 29, "anki": "1463884104334", "q": "A patient on chronic high-dose glucocorticoids develops new hyperglycemia requiring treatment. What is this drug-induced condition called?", "o": {"A": "Steroid diabetes", "B": "Diabetes insipidus", "C": "MODY", "D": "Latent autoimmune diabetes of adults"}, "r": "A", "e": {"correcta": "Chronic glucocorticoid use can induce 'steroid diabetes' through increased hepatic gluconeogenesis and peripheral insulin resistance; glucocorticoids also increase the risk of cataracts, another well-known adverse effect of long-term steroid therapy.", "incorrectas": {"B": "Diabetes insipidus involves impaired water reabsorption due to ADH deficiency or resistance, causing polyuria with dilute urine; it is unrelated to glucose metabolism or glucocorticoid effects.", "C": "MODY (maturity-onset diabetes of the young) is a monogenic form of diabetes with autosomal dominant inheritance presenting in young patients, unrelated to medication-induced hyperglycemia.", "D": "Latent autoimmune diabetes of adults is a slowly progressive autoimmune beta-cell destruction process resembling type 1 diabetes in adults, a distinct entity from the pharmacologic insulin resistance and gluconeogenesis caused by glucocorticoids."}}}, {"id": "anking-toxicities-side-effects-2573", "fuente": "anking", "tema": 29, "anki": "1463884142105", "q": "Which specific gastrointestinal adverse effect is associated with glucocorticoid use?", "o": {"A": "Peptic ulcers", "B": "Pseudomembranous colitis", "C": "Achalasia", "D": "Mallory-Weiss tears"}, "r": "A", "e": {"correcta": "Glucocorticoids increase the risk of peptic ulcers, likely due to reduced prostaglandin-mediated protection of the gastric mucosa (since prostaglandins normally promote mucus and bicarbonate secretion), an effect that is compounded when steroids are combined with NSAIDs.", "incorrectas": {"B": "Pseudomembranous colitis is caused by Clostridioides difficile overgrowth, typically following antibiotic use that disrupts normal gut flora, not a recognized direct effect of glucocorticoids.", "C": "Achalasia is a motility disorder caused by loss of inhibitory neurons in the lower esophageal sphincter, unrelated to glucocorticoid pharmacology.", "D": "Mallory-Weiss tears result from forceful vomiting or retching causing mucosal lacerations at the gastroesophageal junction, a mechanical injury unrelated to glucocorticoid-induced mucosal effects."}}}, {"id": "anking-gastrointestinal-pharmacology-2574", "fuente": "anking", "tema": 40, "anki": "1463930142523", "q": "Which two hormone or hormone-analog agents are used in the acute management of esophageal variceal bleeding?", "o": {"A": "Vasopressin analog (desmopressin) and somatostatin analog (octreotide)", "B": "Oxytocin and insulin", "C": "Glucagon and cortisol", "D": "Growth hormone and thyroxine"}, "r": "A", "e": {"correcta": "Octreotide (a somatostatin analog) reduces splanchnic blood flow and portal pressure by inhibiting vasodilatory hormone release, while vasopressin analogs like desmopressin cause splanchnic vasoconstriction; both are used to control acute esophageal variceal hemorrhage while more definitive treatment (endoscopic banding) is arranged.", "incorrectas": {"B": "Oxytocin is used to induce labor and control postpartum uterine bleeding, and insulin manages glucose, neither of which has a role in reducing portal venous pressure or controlling variceal bleeding.", "C": "Glucagon can be used to relax smooth muscle in some GI contexts (e.g., esophageal food bolus impaction) and cortisol has no established role in acute variceal bleeding management; neither reduces portal pressure the way octreotide and vasopressin analogs do.", "D": "Growth hormone and thyroxine have no established role in controlling acute gastrointestinal bleeding or portal hypertension; they are unrelated to this specific clinical scenario."}}}, {"id": "anking-reproductive-system-physiology-2575", "fuente": "anking", "tema": 32, "anki": "1463943419326", "q": "How does maternal cardiac output change during a normal pregnancy?", "o": {"A": "Decreases by approximately 50%", "B": "Remains unchanged", "C": "Increases by approximately 50%", "D": "Increases by approximately 10%"}, "r": "C", "e": {"correcta": "Maternal cardiac output increases by roughly 50% during pregnancy, driven by increased stroke volume and heart rate, to meet the higher metabolic demands of the growing fetus, placenta, and expanded maternal blood volume.", "incorrectas": {"A": "A decrease in cardiac output would be maladaptive and inconsistent with the increased perfusion demands of pregnancy; the actual physiologic change is a substantial increase, not a decrease.", "B": "Cardiac output changes significantly and predictably during pregnancy as part of well-documented hemodynamic adaptations; 'unchanged' does not reflect the known physiology.", "D": "A 10% increase understates the magnitude of the change; the classically cited and tested increase in cardiac output during pregnancy is approximately 50%, driven by increased preload and heart rate."}}}, {"id": "anking-reproductive-system-physiology-2576", "fuente": "anking", "tema": 32, "anki": "1463944180575", "q": "During pregnancy, plasma volume and RBC mass both increase, but by different amounts. Which pattern is correct?", "o": {"A": "Plasma volume increases 30%, RBC volume increases 50%", "B": "Plasma volume increases 50%, RBC volume increases 30%", "C": "Both increase equally by 50%", "D": "Plasma volume decreases, RBC volume increases"}, "r": "B", "e": {"correcta": "During pregnancy, plasma volume expands by about 50% while RBC mass increases by only about 30%; this disproportionate rise in plasma relative to red cells produces a dilutional effect, contributing to the physiologic anemia of pregnancy.", "incorrectas": {"A": "This reverses the actual proportions; it is plasma volume that increases more (50%), not RBC volume, and RBC volume that increases less (30%), not more.", "C": "If both increased equally, there would be no dilutional effect and no physiologic anemia of pregnancy, which contradicts the well-documented hemodilution seen clinically.", "D": "Plasma volume does not decrease during pregnancy; both plasma volume and RBC mass increase, just at different rates, with plasma volume increasing more."}}}, {"id": "anking-reproductive-system-physiology-2577", "fuente": "anking", "tema": 32, "anki": "1463944198038", "q": "The disproportionate increase in plasma volume (50%) relative to RBC volume (30%) during pregnancy results in what clinical finding, and what is its proposed benefit?", "o": {"A": "Polycythemia; improves oxygen delivery to the fetus", "B": "Anemia; decreases blood viscosity to reduce postpartum bleeding", "C": "Anemia; increases risk of thromboembolism", "D": "Polycythemia; increases risk of pre-eclampsia"}, "r": "B", "e": {"correcta": "The dilutional effect from a larger relative increase in plasma volume than RBC mass produces physiologic anemia of pregnancy; this decreases blood viscosity, which is thought to reduce cardiac workload and limit blood loss at delivery by facilitating easier flow through the uteroplacental circulation.", "incorrectas": {"A": "Polycythemia refers to an increase in red cell concentration, which is the opposite of what happens; the dilutional effect from disproportionate plasma expansion causes anemia, not polycythemia.", "C": "While pregnancy is a hypercoagulable state due to increased clotting factors (a separate physiologic change), the anemia itself is not the direct cause of the thromboembolism risk; the specific benefit of anemia described here is reduced viscosity aiding postpartum hemostasis.", "D": "Polycythemia is not the correct direction of change, and pre-eclampsia risk relates to different pathophysiology (placental and vascular factors), not to relative plasma/RBC volume changes."}}}, {"id": "anking-reproductive-system-physiology-2578", "fuente": "anking", "tema": 32, "anki": "1463944202361", "q": "How does maternal blood pressure typically change during early pregnancy?", "o": {"A": "Increases progressively throughout pregnancy", "B": "Remains constant", "C": "Decreases, then returns to normal near term", "D": "Decreases and stays low postpartum"}, "r": "C", "e": {"correcta": "Blood pressure typically decreases in early-to-mid pregnancy due to progesterone-mediated systemic vasodilation and decreased vascular resistance, then gradually returns toward pre-pregnancy levels as term approaches; a rising blood pressure late in pregnancy should prompt evaluation for pre-eclampsia.", "incorrectas": {"A": "A progressive increase throughout pregnancy is abnormal and would raise concern for gestational hypertension or pre-eclampsia, not the expected physiologic pattern.", "B": "Blood pressure is not static during pregnancy; it follows a characteristic dip in early-to-mid gestation due to hormonally mediated vasodilation, then normalizes by term.", "D": "Blood pressure returns toward baseline near term rather than staying low; persistently low pressure postpartum is not the typical described pattern."}}}, {"id": "anking-reproductive-system-physiology-2579", "fuente": "anking", "tema": 32, "anki": "1463944209580", "q": "How does minute ventilation change during pregnancy, and what primarily drives this change?", "o": {"A": "Increases, mainly due to increased respiratory rate", "B": "Decreases, mainly due to decreased tidal volume", "C": "Increases, mainly due to increased tidal volume", "D": "Remains unchanged despite increased oxygen demand"}, "r": "C", "e": {"correcta": "Minute ventilation increases during pregnancy primarily because tidal volume increases (partly progesterone-driven), while respiratory rate stays largely unchanged; this increased ventilation helps meet the higher metabolic and oxygen demands of pregnancy.", "incorrectas": {"A": "Respiratory rate remains largely unchanged during pregnancy; the increase in minute ventilation is driven by increased tidal volume, not an increased breathing rate.", "B": "Minute ventilation increases, not decreases, during pregnancy; tidal volume rises rather than falls to accommodate increased maternal and fetal oxygen and CO2 exchange needs.", "D": "Minute ventilation changes significantly during pregnancy (it increases) to support higher metabolic demand and facilitate fetal CO2 elimination, so 'unchanged' does not reflect actual physiology."}}}, {"id": "anking-reproductive-system-physiology-2580", "fuente": "anking", "tema": 32, "anki": "1463944212861", "q": "The increased minute ventilation of pregnancy leads to what acid-base change in maternal blood?", "o": {"A": "Mild respiratory acidosis", "B": "Mild metabolic alkalosis", "C": "Mild respiratory alkalosis", "D": "Mixed metabolic and respiratory acidosis"}, "r": "C", "e": {"correcta": "Increased minute ventilation (via increased tidal volume) leads to greater CO2 elimination, lowering maternal PCO2 and producing a mild, compensated respiratory alkalosis, which is a normal physiologic adaptation of pregnancy that also facilitates fetal CO2 offloading into maternal blood.", "incorrectas": {"A": "Respiratory acidosis would result from hypoventilation and CO2 retention, the opposite of what happens in pregnancy, where hyperventilation lowers CO2.", "B": "Metabolic alkalosis arises from processes like vomiting or bicarbonate excess, not from a change in ventilation; the acid-base disturbance driven by increased minute ventilation is respiratory, not metabolic, in origin.", "D": "This mixed picture does not reflect the pregnancy state, in which a single, mild, compensated respiratory alkalosis develops from hyperventilation, not a combined acidosis process."}}}, {"id": "anking-reproductive-system-physiology-2581", "fuente": "anking", "tema": 32, "anki": "1463944216868", "q": "How do maternal PCO2 levels change during pregnancy, and why?", "o": {"A": "Increased, due to decreased ventilation rate", "B": "Decreased, due to increased ventilation", "C": "Unchanged, due to compensatory renal mechanisms", "D": "Increased, due to increased metabolic CO2 production outpacing ventilation"}, "r": "B", "e": {"correcta": "Maternal PCO2 decreases during pregnancy because increased minute ventilation (from increased tidal volume) causes greater CO2 elimination from the lungs; this creates a favorable gradient that facilitates CO2 transfer from the fetus to the mother across the placenta.", "incorrectas": {"A": "Ventilation rate actually increases (via increased tidal volume) rather than decreasing during pregnancy, so a fall in ventilation is not the correct explanation, and PCO2 does not rise.", "C": "PCO2 does change (it decreases) during pregnancy as a direct consequence of increased ventilation; describing it as unchanged via renal compensation misrepresents the primary respiratory driver of this change.", "D": "While fetal metabolism does add some CO2 load, maternal hyperventilation outpaces this, resulting in a net decrease, not increase, in maternal PCO2."}}}, {"id": "anking-reproductive-system-physiology-2582", "fuente": "anking", "tema": 32, "anki": "1463944220761", "q": "What is the physiologic purpose of the decreased maternal PCO2 seen during pregnancy?", "o": {"A": "To reduce maternal oxygen consumption", "B": "To facilitate CO2 elimination from the fetus into maternal circulation", "C": "To prevent maternal metabolic alkalosis", "D": "To increase fetal hemoglobin oxygen affinity"}, "r": "B", "e": {"correcta": "By lowering maternal PCO2 through increased ventilation, a favorable CO2 gradient is created across the placenta, allowing fetal CO2 to diffuse into the maternal circulation and be eliminated via maternal lungs, supporting efficient fetal waste gas clearance.", "incorrectas": {"A": "Decreased PCO2 does not function to reduce maternal oxygen consumption; oxygen consumption actually increases during pregnancy to meet higher metabolic demands, unrelated to the CO2 gradient purpose.", "C": "The decreased PCO2 actually causes a mild respiratory alkalosis rather than preventing one; the purpose is about facilitating fetal gas exchange, not maintaining maternal acid-base neutrality as a goal in itself.", "D": "Fetal hemoglobin's higher oxygen affinity is an inherent property of hemoglobin F structure, unrelated to maternal PCO2 levels or ventilation changes."}}}, {"id": "anking-reproductive-system-physiology-2583", "fuente": "anking", "tema": 32, "anki": "1463944224537", "q": "How does coagulability change during pregnancy, and what is a proposed physiologic benefit of this change?", "o": {"A": "Increased (hypercoagulability), which decreases postpartum bleeding risk", "B": "Decreased (hypocoagulability), which prevents thromboembolism", "C": "Unchanged, since clotting factors are stable throughout gestation", "D": "Increased, primarily to support fetal iron transport"}, "r": "A", "e": {"correcta": "Pregnancy is a hypercoagulable state due to increased levels of clotting factors (e.g., fibrinogen, factors VII, VIII, X) and decreased fibrinolytic activity; this is thought to be an evolutionary adaptation that helps limit hemorrhage at the time of placental separation and delivery, though it also raises the risk of venous thromboembolism.", "incorrectas": {"B": "Pregnancy causes hypercoagulability, not hypocoagulability; this actually increases (rather than prevents) the risk of venous thromboembolism, a recognized complication of pregnancy.", "C": "Clotting factor levels change substantially during pregnancy (most increase), which is why pregnant patients are at elevated thromboembolic risk; describing them as stable is inconsistent with known physiology.", "D": "The hypercoagulable state of pregnancy relates to hemostatic protection around delivery, not to iron transport, which is a separate and unrelated physiologic process."}}}, {"id": "anking-reproductive-system-physiology-2584", "fuente": "anking", "tema": 32, "anki": "1463944228821", "q": "How does glomerular filtration rate (GFR) change during pregnancy, and what lab findings result?", "o": {"A": "Increases, causing decreased BUN and creatinine", "B": "Decreases, causing increased BUN and creatinine", "C": "Remains unchanged", "D": "Increases, causing increased BUN and creatinine"}, "r": "A", "e": {"correcta": "GFR increases during pregnancy due to increased renal plasma flow and cardiac output, leading to enhanced clearance of nitrogenous waste products; as a result, BUN and creatinine levels are typically lower than in the non-pregnant state, and values considered 'normal' outside pregnancy may actually reflect renal impairment in a pregnant patient.", "incorrectas": {"B": "A decrease in GFR would raise, not lower, BUN and creatinine, and would suggest renal impairment; this is the opposite of the expected physiologic renal adaptation of pregnancy.", "C": "GFR changes substantially and predictably during pregnancy (it increases), which is why reference ranges for renal function tests differ in pregnant patients; 'unchanged' does not reflect this adaptation.", "D": "While GFR does increase, this leads to decreased (not increased) BUN and creatinine, since a higher GFR means more efficient clearance of these waste products."}}}, {"id": "anking-reproductive-system-physiology-2585", "fuente": "anking", "tema": 32, "anki": "1463944239303", "q": "How does insulin resistance change during pregnancy, and what hormone primarily drives this change?", "o": {"A": "Decreases, due to increased progesterone", "B": "Increases, due to human placental lactogen", "C": "Increases, due to increased cortisol only", "D": "Remains unchanged throughout gestation"}, "r": "B", "e": {"correcta": "Insulin resistance increases during pregnancy largely due to rising levels of human placental lactogen (hPL), which antagonizes maternal insulin action; this diabetogenic effect ensures that more glucose remains available in maternal blood to freely cross the placenta and be used by the fetus for energy, but it can unmask gestational diabetes in susceptible women.", "incorrectas": {"A": "Insulin resistance increases, not decreases, during pregnancy; progesterone contributes to other physiologic changes but the key diabetogenic hormone driving insulin resistance is human placental lactogen.", "C": "While cortisol and other hormones contribute somewhat to the insulin-resistant state, the hormone most specifically and classically implicated in pregnancy-associated insulin resistance is human placental lactogen, not cortisol alone.", "D": "Insulin sensitivity changes progressively across pregnancy (increasing resistance especially in the second and third trimesters), which is why gestational diabetes screening is typically performed later in pregnancy; 'unchanged' is inconsistent with this pattern."}}}, {"id": "anking-reproductive-system-physiology-2586", "fuente": "anking", "tema": 32, "anki": "1463944246715", "q": "Around which gestational weeks do maternal hCG levels typically peak?", "o": {"A": "Weeks 2-4", "B": "Weeks 8-10", "C": "Weeks 20-22", "D": "Weeks 36-38"}, "r": "B", "e": {"correcta": "Maternal beta-hCG levels rise rapidly after implantation, peaking around weeks 8-10 of gestation, before declining and plateauing for the remainder of pregnancy; this peak timing is clinically relevant for interpreting first-trimester screening tests and pregnancy dating.", "incorrectas": {"A": "Weeks 2-4 are too early; hCG is just beginning to rise after implantation at this point (which is why home pregnancy tests become positive around the time of a missed period), but levels have not yet reached their peak.", "C": "By weeks 20-22, hCG levels have already declined substantially from their first-trimester peak and remain at a lower plateau level for the rest of pregnancy, so this window does not represent the peak.", "D": "By weeks 36-38 (late third trimester), hCG levels are well past their peak and remain at a relatively low, stable plateau compared to the surge seen in early pregnancy."}}}, {"id": "anking-reproductive-system-physiology-2587", "fuente": "anking", "tema": 32, "anki": "1463944253517", "q": "In the GTPAL system used to summarize a woman's obstetric history, what does the \"G\" represent?", "o": {"A": "Gravidity: total number of pregnancies", "B": "Gestational age at first pregnancy", "C": "Number of living children", "D": "Total number of deliveries after 37 weeks"}, "r": "A", "e": {"correcta": "Gravidity (G) is the total number of times a woman has been pregnant, regardless of the outcome, including the current pregnancy, miscarriages, and abortions. It is distinct from parity, which counts deliveries rather than pregnancies.", "incorrectas": {"B": "Gestational age at first pregnancy is not part of the GTPAL mnemonic at all; GTPAL summarizes pregnancy outcomes (term, preterm, abortion) and living children, not maternal age at conception.", "C": "Number of living children is represented by the \"L\" in GTPAL, not the \"G,\" and reflects outcome/survival rather than the count of pregnancies themselves.", "D": "Total deliveries after 37 weeks is the definition of the \"T\" (term deliveries), a subset counted only after the pregnancy has ended, whereas gravidity counts every pregnancy regardless of how far it progressed."}}}, {"id": "anking-reproductive-system-physiology-2588", "fuente": "anking", "tema": 32, "anki": "1463944257343", "q": "In the GTPAL obstetric history mnemonic, the letter \"T\" refers to which of the following?", "o": {"A": "Total number of pregnancies", "B": "Total number of deliveries after 37 weeks (term deliveries)", "C": "Total number of deliveries before 20 weeks", "D": "Total number of living children"}, "r": "B", "e": {"correcta": "\"T\" stands for term deliveries, defined as the number of deliveries occurring at or after 37 weeks gestation. This is one of the key outcome categories that, together with preterm deliveries and abortions, accounts for all pregnancy endpoints.", "incorrectas": {"A": "Total number of pregnancies is gravidity (\"G\"), which is counted independently of gestational age or outcome and includes the current pregnancy.", "C": "Deliveries before 20 weeks are classified as abortions (\"A\"), not term deliveries; the 20-week cutoff distinguishes an abortion from a preterm delivery.", "D": "Living children is the \"L\" category, which tracks survival outcome rather than the gestational age at delivery."}}}, {"id": "anking-reproductive-system-physiology-2589", "fuente": "anking", "tema": 32, "anki": "1463944261135", "q": "When using GTPAL to document obstetric history, what does the \"P\" stand for?", "o": {"A": "Parity as total pregnancies", "B": "Preterm deliveries: deliveries after 20 weeks but before 37 weeks", "C": "Postpartum hemorrhage episodes", "D": "Pregnancies ending in stillbirth only"}, "r": "B", "e": {"correcta": "\"P\" denotes preterm deliveries, defined as births occurring after 20 weeks gestation but before completion of 37 weeks. This category captures viable but premature deliveries, distinguishing them from earlier pregnancy losses (abortions) and full-term births.", "incorrectas": {"A": "Parity as a general total-pregnancies count is not how GTPAL uses \"P\"; gravidity already captures total pregnancies, while \"P\" specifically isolates the preterm delivery subset.", "C": "Postpartum hemorrhage is a delivery complication, not a component of the GTPAL classification, which only tracks pregnancy counts and outcomes by gestational age.", "D": "GTPAL's outcome categories are defined by gestational age at delivery (term, preterm, abortion), not by whether the infant was stillborn, so this does not correspond to \"P.\""}}}, {"id": "anking-reproductive-system-physiology-2590", "fuente": "anking", "tema": 32, "anki": "1463944264804", "q": "In a woman's GTPAL obstetric summary, the letter \"A\" corresponds to which category?", "o": {"A": "Total number of living children", "B": "Total pregnancies including the current one", "C": "Abortions: total deliveries before 20 weeks", "D": "Term deliveries after 37 weeks"}, "r": "C", "e": {"correcta": "\"A\" represents abortions, defined as pregnancy losses (spontaneous or induced) occurring before 20 weeks gestation. This 20-week threshold is the standard cutoff separating an abortion from a preterm delivery in obstetric terminology.", "incorrectas": {"A": "Living children corresponds to \"L,\" the final letter in GTPAL, which tallies surviving offspring rather than early pregnancy losses.", "B": "Total pregnancies including the current one is the definition of gravidity (\"G\"), a separate, broader count that does not depend on gestational age at loss or delivery.", "D": "Deliveries after 37 weeks are classified as term (\"T\"), the opposite end of the gestational age spectrum from the early losses captured by \"A.\""}}}, {"id": "anking-reproductive-system-physiology-2591", "fuente": "anking", "tema": 32, "anki": "1463944269114", "q": "In the GTPAL mnemonic for obstetric history, what does the final letter \"L\" indicate?", "o": {"A": "Number of living children", "B": "Number of low birth weight infants", "C": "Number of preterm labors induced", "D": "Number of pregnancy losses before 20 weeks"}, "r": "A", "e": {"correcta": "\"L\" stands for the number of living children the woman currently has, which can differ from the number of deliveries because of multiple gestations (e.g., twins count as one delivery but two living children) or neonatal/childhood deaths.", "incorrectas": {"B": "Low birth weight is not tracked in the GTPAL system; the mnemonic organizes pregnancies by gestational-age outcome and survival, not by birth weight.", "C": "Induced preterm labors would fall under the \"P\" (preterm deliveries) category if they resulted in delivery between 20 and 37 weeks, not under \"L,\" which is strictly about current living offspring.", "D": "Pregnancy losses before 20 weeks are captured by \"A\" (abortions); \"L\" instead reflects children who are currently alive, unrelated to early losses."}}}, {"id": "anking-reproductive-system-physiology-2592", "fuente": "anking", "tema": 32, "anki": "1463944272827", "q": "A pregnancy is classified as \"term\" if delivery occurs within which gestational age range?", "o": {"A": "34 to 37 weeks", "B": "37 to 42 weeks", "C": "20 to 37 weeks", "D": "42 to 44 weeks"}, "r": "B", "e": {"correcta": "Term gestation spans 37 to 42 weeks. Deliveries before 37 weeks are preterm, and those beyond 42 weeks are considered post-term, which carries its own risks such as macrosomia and placental insufficiency.", "incorrectas": {"A": "34 to 37 weeks falls within the late preterm period, not term; babies born in this window are still classified as preterm and may have increased respiratory and feeding complications.", "C": "20 to 37 weeks spans both the abortion cutoff (20 weeks) and the entire preterm range, incorrectly including pregnancy losses and premature births within the definition of \"term.\"", "D": "42 to 44 weeks is beyond the term window and is instead classified as post-term (or postdates) pregnancy, associated with oligohydramnios and placental aging."}}}, {"id": "anking-reproductive-system-physiology-2593", "fuente": "anking", "tema": 32, "anki": "1463944280705", "q": "A pregnant woman undergoes a quad screen. Which combination of results is classically associated with trisomy 21 (Down syndrome)?", "o": {"A": "Decreased AFP, decreased estriol, increased hCG, increased inhibin A", "B": "Increased AFP, increased estriol, decreased hCG, decreased inhibin A", "C": "Decreased AFP, increased estriol, decreased hCG, decreased inhibin A", "D": "Increased AFP, decreased estriol, increased hCG, increased inhibin A"}, "r": "A", "e": {"correcta": "Trisomy 21 classically shows decreased AFP, decreased estriol, and increased hCG and inhibin A. The elevated hCG and inhibin A are notably different from trisomy 18 and 13, which show decreased or normal levels of these two markers, making this pattern useful for distinguishing Down syndrome from other trisomies.", "incorrectas": {"B": "This pattern with increased AFP is more suggestive of a neural tube defect or abdominal wall defect (e.g., open spina bifida, gastroschisis), where AFP leaks into amniotic fluid, not the decreased AFP seen in trisomy 21.", "C": "Estriol is decreased, not increased, in trisomy 21 due to reduced placental/fetal steroidogenic function; an increased estriol with low AFP and hCG does not match any classic trisomy pattern taught for Step 1.", "D": "Trisomy 18 (Edwards syndrome) and trisomy 13 (Patau syndrome) present with decreased AFP, estriol, hCG, and inhibin A (all low), unlike trisomy 21, where hCG and inhibin A are actually increased — this option incorrectly shows all four markers elevated."}}}, {"id": "anking-reproductive-system-physiology-2594", "fuente": "anking", "tema": 32, "anki": "1463944330295", "q": "What effect does a multiple gestation (e.g., twins or triplets) typically have on maternal serum hCG levels?", "o": {"A": "No change compared to singleton pregnancy", "B": "Decreased", "C": "Increased", "D": "Initially increased, then decreased by the third trimester"}, "r": "C", "e": {"correcta": "Multiple gestations increase hCG because more placental (trophoblastic) tissue is present, producing more hormone overall. This same principle explains why hCG is also elevated in hydatidiform mole, choriocarcinoma, and Down syndrome pregnancies — all involve either excess or abnormal trophoblastic tissue.", "incorrectas": {"A": "hCG is produced by syncytiotrophoblast, and more fetuses mean more placental mass producing the hormone, so levels are not unchanged relative to a singleton pregnancy.", "B": "Decreased hCG would be more consistent with an ectopic pregnancy or an impending miscarriage where trophoblastic function is failing, the opposite of the increased trophoblastic mass seen with twins.", "D": "While hCG naturally peaks around the end of the first trimester and declines afterward in all pregnancies, the comparison being tested is multiples versus singleton at a given gestational age, where multiples show higher, not lower, levels."}}}, {"id": "anking-reproductive-system-physiology-2595", "fuente": "anking", "tema": 32, "anki": "1463944339139", "q": "Amniocentesis for prenatal genetic testing is typically performed no earlier than which gestational age?", "o": {"A": "10 to 13 weeks", "B": "15 to 17 weeks", "C": "20 to 24 weeks", "D": "6 to 9 weeks"}, "r": "B", "e": {"correcta": "Amniocentesis can be performed as early as 15 to 17 weeks gestation, once sufficient amniotic fluid has accumulated to safely sample. It allows karyotyping and measurement of alpha-fetoprotein, an advantage chorionic villus sampling lacks since it does not access amniotic fluid.", "incorrectas": {"A": "10 to 13 weeks is the window for chorionic villus sampling (CVS), which is performed earlier than amniocentesis by sampling placental (chorionic) tissue directly rather than amniotic fluid.", "C": "20 to 24 weeks is later than necessary; amniocentesis is generally available starting at 15 weeks once fluid volume is adequate, and waiting until 20+ weeks would unnecessarily delay results.", "D": "6 to 9 weeks is far too early for either amniocentesis or CVS; performing CVS this early specifically raises the risk of fetal limb defects, which is why 10 weeks is the earliest recommended time."}}}, {"id": "anking-reproductive-system-physiology-2596", "fuente": "anking", "tema": 32, "anki": "1463944348904", "q": "Chorionic villus sampling (CVS) can be performed as early as which gestational age range?", "o": {"A": "15 to 17 weeks", "B": "10 to 13 weeks", "C": "18 to 20 weeks", "D": "5 to 8 weeks"}, "r": "B", "e": {"correcta": "CVS can be performed as early as 10 to 13 weeks gestation, notably earlier than amniocentesis, because it samples chorionic (placental) villi directly rather than waiting for amniotic fluid to accumulate. This earlier timing allows for earlier karyotype results but at a slightly higher procedural risk and without the ability to measure AFP.", "incorrectas": {"A": "15 to 17 weeks is the earliest window for amniocentesis, not CVS; amniocentesis must wait longer because it requires an adequate volume of amniotic fluid for safe sampling.", "C": "18 to 20 weeks is well beyond the earliest CVS window and is more typical of the timing for a standard anatomy ultrasound, not genetic sampling procedures.", "D": "5 to 8 weeks is too early for CVS; performing it before 9-10 weeks is specifically associated with fetal limb defects, which is why practice guidelines recommend waiting until at least 10 weeks."}}}, {"id": "anking-reproductive-system-physiology-2597", "fuente": "anking", "tema": 32, "anki": "1463944355918", "q": "How do the risks of fetal loss compare between amniocentesis and chorionic villus sampling (CVS)?", "o": {"A": "Amniocentesis carries a higher risk (1%) than CVS (0.5%)", "B": "Amniocentesis carries a lower risk (0.5%) than CVS (1%)", "C": "Both procedures carry an equal fetal loss risk of about 2%", "D": "Neither procedure carries any measurable risk of fetal loss"}, "r": "B", "e": {"correcta": "Amniocentesis carries a lower fetal loss risk, approximately 0.5%, compared to about 1% for chorionic villus sampling. This modestly higher risk with CVS is a trade-off for being able to perform the procedure earlier in pregnancy, around 10-13 weeks versus 15-17 weeks for amniocentesis.", "incorrectas": {"A": "This reverses the actual risk profile; CVS, not amniocentesis, carries the higher fetal loss risk (~1% vs ~0.5%), partly because it is performed earlier and involves sampling directly from placental tissue near the developing embryo.", "C": "Both procedures carry real but low risks, and they are not equal — amniocentesis is roughly half the risk of CVS, an important consideration when counseling patients on which test to pursue.", "D": "Both amniocentesis and CVS are invasive procedures that carry a genuine, quantifiable risk of fetal loss, which is precisely why noninvasive screening (e.g., quad screen, cell-free DNA) is offered first to help decide who needs invasive testing."}}}, {"id": "anking-reproductive-system-physiology-2598", "fuente": "anking", "tema": 32, "anki": "1463944359553", "q": "Performing chorionic villus sampling before 9 weeks gestation is associated with which fetal complication?", "o": {"A": "Neural tube defects", "B": "Limb defects", "C": "Cardiac septal defects", "D": "Renal agenesis"}, "r": "B", "e": {"correcta": "CVS performed too early, before roughly 9-10 weeks, has been associated with fetal limb defects, thought to result from vascular disruption during a critical period of limb development. This is a key reason CVS timing is restricted to 10 weeks or later.", "incorrectas": {"A": "Neural tube defects are not caused by CVS timing; rather, CVS's inability to detect pre-existing neural tube defects (since it cannot measure amniotic AFP) is its limitation compared to amniocentesis.", "C": "Cardiac septal defects are not the classically described complication of early CVS; the well-documented association from case reports and studies is specifically with limb reduction defects.", "D": "Renal agenesis is not linked to CVS timing in the literature; the vascular disruption implicated in early CVS complications specifically affects the developing limb buds rather than renal development."}}}, {"id": "anking-reproductive-system-physiology-2599", "fuente": "anking", "tema": 32, "anki": "1463944364170", "q": "Compared to amniocentesis, chorionic villus sampling (CVS) has a notable limitation in detecting which type of defect?", "o": {"A": "Trisomy 21", "B": "Sex chromosome abnormalities", "C": "Neural tube defects", "D": "Single-gene mutations"}, "r": "C", "e": {"correcta": "CVS samples chorionic villi (placental tissue) rather than amniotic fluid, so it cannot measure alpha-fetoprotein (AFP), the marker elevated in amniotic fluid with open neural tube defects. Amniocentesis, by directly sampling amniotic fluid, can detect this elevation and is therefore superior for neural tube defect screening.", "incorrectas": {"A": "Both CVS and amniocentesis can detect trisomy 21 via karyotyping of fetal cells, since chromosomal analysis does not require amniotic fluid specifically.", "B": "Sex chromosome abnormalities are also detectable by karyotyping from either chorionic villi or amniocytes, so this is not a distinguishing limitation of CVS.", "D": "Single-gene mutations can be assessed via DNA extracted from chorionic villi just as well as from amniocytes, so CVS is not specifically limited in this regard; its limitation is tied to the lack of amniotic fluid for AFP measurement."}}}, {"id": "anking-reproductive-system-embryology-2600", "fuente": "anking", "tema": 33, "anki": "1463944377495", "q": "Chorion formation occurs by which day of early embryonic development, such that twinning after this point results in monochorionic twins?", "o": {"A": "Day 8", "B": "Day 4", "C": "Day 13", "D": "Day 1"}, "r": "B", "e": {"correcta": "The chorion forms by day 4 of development. If a single fertilized egg splits into twins after this point, both embryos will share the already-formed chorion, resulting in monochorionic twins, which carry higher risk for complications like twin-twin transfusion syndrome.", "incorrectas": {"A": "Day 8 is when the amnion forms, a later event than chorion formation; splitting after day 8 determines monoamnionicity, not monochorionicity.", "C": "Day 13 is well past both chorion and amnion formation; splitting this late (or later) risks incomplete separation, leading to conjoined twins rather than simply determining chorionicity.", "D": "Day 1 is essentially fertilization itself, far too early for chorion formation; splitting at this stage (as in dizygotic-like early division) would produce dichorionic, diamniotic twins since neither membrane has formed yet."}}}, {"id": "anking-reproductive-system-embryology-2601", "fuente": "anking", "tema": 33, "anki": "1463944389120", "q": "Amnion formation occurs by which day of embryonic development, such that twinning after this day produces monoamniotic twins?", "o": {"A": "Day 4", "B": "Day 8", "C": "Day 1", "D": "Day 13"}, "r": "B", "e": {"correcta": "The amnion forms by day 8 of development. If splitting of the embryonic disc occurs after this point, both twins will be enclosed within the same amniotic sac, producing monoamniotic twins, which carry substantial risk of cord entanglement.", "incorrectas": {"A": "Day 4 corresponds to chorion formation, which occurs earlier; splitting after day 4 but before day 8 still allows separate amnions to form, resulting in monochorionic-diamniotic twins.", "C": "Day 1 is around the time of fertilization, well before either the chorion or amnion has formed; splitting this early yields dichorionic, diamniotic twins (essentially as if from two separate zygotes structurally).", "D": "Day 13 is beyond the point where monoamniotic twinning would already be established (from splitting between days 8-13); splitting at or after day 13 instead risks incomplete separation and conjoined twins."}}}, {"id": "anking-reproductive-system-embryology-2602", "fuente": "anking", "tema": 33, "anki": "1463944398823", "q": "On ultrasound, the presence of a single yolk sac with two fetal poles is most indicative of which type of twin pregnancy?", "o": {"A": "Dichorionic, diamniotic twins", "B": "Monochorionic, diamniotic twins", "C": "Monoamniotic twins", "D": "Conjoined twins"}, "r": "C", "e": {"correcta": "A single yolk sac containing two fetal poles indicates monoamniotic twins, since the yolk sac develops within the amniotic cavity and a shared yolk sac implies the twins share one amniotic sac. This finding carries important clinical implications given the high risk of cord entanglement in monoamniotic pregnancies.", "incorrectas": {"A": "Dichorionic, diamniotic twins would show two separate gestational sacs each with its own yolk sac, the opposite ultrasound picture of a single shared yolk sac.", "B": "Monochorionic, diamniotic twins share one placenta/chorion but have two separate amniotic sacs, and therefore each twin would typically have its own yolk sac rather than a single shared one.", "D": "Conjoined twins result from incomplete splitting very late in development (typically after day 13) and are suggested by ultrasound findings of fused body parts or an inability to separate the fetal poles, not merely a shared yolk sac."}}}, {"id": "anking-reproductive-system-embryology-2603", "fuente": "anking", "tema": 33, "anki": "1463944402230", "q": "Cord entanglement on prenatal imaging is a hallmark finding of which type of twin gestation?", "o": {"A": "Dichorionic, diamniotic twins", "B": "Monochorionic, diamniotic twins", "C": "Monoamniotic twins", "D": "Dizygotic twins with separate placentas"}, "r": "C", "e": {"correcta": "Cord entanglement is characteristic of monoamniotic twins because both fetuses share a single amniotic cavity with no dividing membrane, allowing their umbilical cords to intertwine freely and potentially compromise fetal blood flow. This makes monoamniotic twin pregnancies high-risk and typically requires close monitoring and early delivery.", "incorrectas": {"A": "Dichorionic, diamniotic twins have completely separate placentas and amniotic sacs, so their umbilical cords are physically isolated from one another and cannot become entangled.", "B": "Monochorionic, diamniotic twins share a placenta but have separate amniotic sacs divided by a membrane, which keeps each cord within its own compartment and prevents entanglement, though this configuration does carry risk for twin-twin transfusion syndrome instead.", "D": "Dizygotic twins arise from two separate fertilized eggs and always have separate placentas and sacs (dichorionic, diamniotic), making cord entanglement essentially impossible in this scenario."}}}, {"id": "anking-reproductive-system-embryology-2604", "fuente": "anking", "tema": 33, "anki": "1463944405911", "q": "In twin-twin transfusion syndrome, which twin develops anastomotic vascular connections that lead to anemia, pallor, and growth restriction?", "o": {"A": "The recipient twin", "B": "The donor twin", "C": "Both twins equally", "D": "Neither twin, only the placenta is affected"}, "r": "B", "e": {"correcta": "In twin-twin transfusion syndrome, the donor twin loses blood volume through shared vascular anastomoses in a monochorionic placenta, resulting in anemia, pale skin, and restricted growth due to reduced perfusion and nutrient delivery.", "incorrectas": {"A": "The recipient twin experiences the opposite physiology, receiving excess blood volume that leads to polycythemia, volume overload, and risk of heart failure, rather than anemia and growth restriction.", "C": "The syndrome is defined by an imbalance between the two twins via shared placental anastomoses, so the effects are markedly asymmetric rather than equal between the two fetuses.", "D": "The vascular anastomoses occur within the shared monochorionic placenta, but the physiologic consequences manifest directly in each fetus (anemia in one, volume overload in the other), not merely as an isolated placental finding."}}}, {"id": "anking-reproductive-system-embryology-2605", "fuente": "anking", "tema": 33, "anki": "1463944408999", "q": "In twin-twin transfusion syndrome, the recipient twin is at risk for which of the following due to receiving excess blood volume?", "o": {"A": "Anemia and growth restriction", "B": "Heart failure from volume overload and polycythemia", "C": "Limb defects from vascular disruption", "D": "Neural tube defects"}, "r": "B", "e": {"correcta": "The recipient twin receives a disproportionate share of blood through placental vascular anastomoses, leading to polycythemia, hypervolemia, and increased risk of high-output cardiac failure, along with polyhydramnios from increased fetal urine output.", "incorrectas": {"A": "Anemia and growth restriction describe the donor twin, who loses blood volume to the recipient through the same anastomotic connections, producing essentially opposite physiology.", "C": "Limb defects are associated with early chorionic villus sampling (before 9-10 weeks), not with the vascular shunting seen in twin-twin transfusion syndrome.", "D": "Neural tube defects are unrelated to twin-twin transfusion syndrome; they arise from failure of neural tube closure early in development and are not a consequence of interfetal blood shunting."}}}, {"id": "anking-reproductive-system-embryology-2606", "fuente": "anking", "tema": 33, "anki": "1463945003632", "q": "The umbilical arteries carry deoxygenated fetal blood to the placenta, arising as branches of which fetal vessels?", "o": {"A": "External iliac arteries", "B": "Internal iliac arteries", "C": "Common iliac arteries", "D": "Inferior mesenteric arteries"}, "r": "B", "e": {"correcta": "The paired umbilical arteries arise from the fetal internal iliac arteries and carry deoxygenated, waste-laden blood from the fetus to the placenta for gas and nutrient exchange. After birth, the distal portions of these arteries obliterate to become the medial umbilical ligaments.", "incorrectas": {"A": "The external iliac arteries continue into the lower limb as the femoral arteries and do not give rise to the umbilical arteries; that vascular relationship belongs to the internal iliac arteries.", "C": "The common iliac arteries are the proximal trunks that bifurcate into internal and external iliac arteries; the umbilical arteries specifically branch from the internal, not the common, iliac vessels.", "D": "The inferior mesenteric artery supplies the hindgut structures (distal colon, rectum) and has no direct relationship to the umbilical arteries or placental circulation."}}}, {"id": "anking-renal-embryology-2607", "fuente": "anking", "tema": 60, "anki": "1463945063263", "q": "Total failure of the urachus to obliterate results in which congenital anomaly?", "o": {"A": "Urachal cyst", "B": "Vesicourachal diverticulum", "C": "Patent urachus", "D": "Meckel diverticulum"}, "r": "C", "e": {"correcta": "A patent urachus results from complete failure of the urachus (allantois remnant connecting the bladder to the umbilicus) to obliterate, creating a direct connection that allows urine to leak from the umbilicus, a distinctive presenting sign in a newborn.", "incorrectas": {"A": "A urachal cyst results from partial, focal failure of obliteration in the middle segment of the urachus, creating an enclosed fluid-filled cavity rather than a fully patent connection between bladder and umbilicus.", "B": "A vesicourachal diverticulum results from a slight, localized failure of obliteration near the bladder end of the urachus, producing an outpouching of the bladder rather than a complete open tract to the umbilicus.", "D": "A Meckel diverticulum arises from incomplete obliteration of the vitelline (omphalomesenteric) duct in the gastrointestinal tract, an entirely different embryologic structure unrelated to the urachus."}}}, {"id": "anking-renal-embryology-2608", "fuente": "anking", "tema": 60, "anki": "1463945257858", "q": "Partial failure of the urachus to obliterate, resulting in a fluid-filled cavity, is best described as which entity?", "o": {"A": "Patent urachus", "B": "Urachal cyst", "C": "Vesicourachal diverticulum", "D": "Urachal fistula"}, "r": "B", "e": {"correcta": "A urachal cyst arises from partial failure of the urachus to obliterate at a point along its middle segment, trapping fluid within an enclosed cavity lined by uroepithelium. Unlike a patent urachus, there is no continuous open tract to the umbilicus, so urine does not leak externally.", "incorrectas": {"A": "A patent urachus reflects total failure of obliteration along the entire length of the urachus, producing a continuously open communication between the bladder and umbilicus with urine drainage, unlike the enclosed cavity of a cyst.", "C": "A vesicourachal diverticulum arises from failure of obliteration specifically near the bladder, forming an outpouching continuous with the bladder lumen, rather than an isolated fluid-filled cavity elsewhere along the urachus.", "D": "A urachal fistula is not a standard distinct term used in this classification; the continuous open connection scenario is specifically termed a patent urachus."}}}, {"id": "anking-renal-embryology-2609", "fuente": "anking", "tema": 60, "anki": "1463945263919", "q": "A fluid-filled cavity lined with uroepithelium located between the umbilicus and the bladder describes which structure?", "o": {"A": "Vesicourachal diverticulum", "B": "Patent urachus", "C": "Urachal cyst", "D": "Omphalomesenteric duct remnant"}, "r": "C", "e": {"correcta": "This describes a urachal cyst, an enclosed, uroepithelium-lined remnant located along the course of the urachus between the umbilicus and bladder. It can become infected or, though rarely, serve as a nidus for adenocarcinoma later in life.", "incorrectas": {"A": "A vesicourachal diverticulum is an outpouching that remains in continuity with the bladder itself, not an isolated cyst located between the umbilicus and bladder.", "B": "A patent urachus is a fully open tract allowing urine drainage from the bladder to the umbilicus, not an enclosed, fluid-filled cyst structure.", "D": "An omphalomesenteric duct remnant relates to incomplete obliteration of the vitelline duct connecting the midgut to the yolk sac, an entirely separate embryologic structure from the urachus."}}}, {"id": "anking-renal-embryology-2610", "fuente": "anking", "tema": 60, "anki": "1463945273041", "q": "A slight, localized failure of the urachus to obliterate near the bladder produces which anomaly?", "o": {"A": "Patent urachus", "B": "Vesicourachal diverticulum", "C": "Urachal cyst", "D": "Bladder exstrophy"}, "r": "B", "e": {"correcta": "A vesicourachal diverticulum results from a minor, localized failure of urachal obliteration near the bladder, producing an outpouching that remains in continuity with the bladder lumen.", "incorrectas": {"A": "A patent urachus involves complete failure of obliteration along the whole urachal tract, producing a continuously open communication from bladder to umbilicus, a far more extensive defect than a localized diverticulum.", "C": "A urachal cyst forms from partial obliteration failure along the middle portion of the urachus, creating an isolated cavity rather than an outpouching continuous with the bladder.", "D": "Bladder exstrophy is a distinct congenital anomaly involving failure of the anterior abdominal wall and bladder to close properly, unrelated to urachal remnant obliteration."}}}, {"id": "anking-renal-embryology-2611", "fuente": "anking", "tema": 60, "anki": "1463945278650", "q": "A vesicourachal diverticulum presents as an outpouching of which structure?", "o": {"A": "Umbilicus", "B": "Bladder", "C": "Ureter", "D": "Urethra"}, "r": "B", "e": {"correcta": "A vesicourachal diverticulum is an outpouching of the bladder itself, formed when the portion of the urachus adjacent to the bladder fails to fully obliterate, leaving a small pouch continuous with the bladder wall.", "incorrectas": {"A": "The umbilicus is the opposite end of the urachal remnant; a patent urachus, not a vesicourachal diverticulum, involves an open connection reaching all the way to the umbilicus.", "C": "The ureter is a separate structure connecting the kidney to the bladder and is not involved in urachal remnant anomalies, which arise from the allantois-derived urachus.", "D": "The urethra carries urine from the bladder to the exterior and is a distinct structure from the urachus; it is not the site of outpouching in this anomaly."}}}, {"id": "anking-reproductive-system-pathology-2612", "fuente": "anking", "tema": 8, "anki": "1463947013821", "q": "An invasive mole most commonly represents the malignant progression of which type of hydatidiform mole?", "o": {"A": "Partial mole", "B": "Complete mole", "C": "Choriocarcinoma", "D": "Placental site trophoblastic tumor"}, "r": "B", "e": {"correcta": "Invasive moles most commonly arise from complete hydatidiform moles, which occur in about 15-20% of complete mole cases, compared to less than 5% of partial moles. Complete moles carry a 46,XX (or XY) karyotype entirely of paternal origin and lack fetal tissue, features associated with their higher malignant potential.", "incorrectas": {"A": "Partial moles, which contain triploid genetic material with both maternal and paternal contributions and often some fetal tissue, progress to invasive mole far less frequently (under 5%) than complete moles.", "C": "Choriocarcinoma is itself a further, more aggressive step in gestational trophoblastic disease that can arise from a mole (or normal pregnancy), but the question asks about the precursor lesion for invasive mole, which is the complete mole, not choriocarcinoma.", "D": "Placental site trophoblastic tumor is a separate, rarer form of gestational trophoblastic disease arising from intermediate trophoblast, not typically described as progressing from a complete hydatidiform mole in this classic pathway."}}}, {"id": "anking-reproductive-system-pathology-2613", "fuente": "anking", "tema": 8, "anki": "1463947088822", "q": "Invasive moles are diagnosed histologically by identifying chorionic villi invading which layer, typically seen on a hysterectomy specimen?", "o": {"A": "Endometrium only", "B": "Myometrium", "C": "Serosa", "D": "Cervical stroma"}, "r": "B", "e": {"correcta": "Invasive moles are diagnosed by histologic evidence of chorionic villi penetrating into the myometrium, distinguishing them from a non-invasive complete or partial mole confined to the endometrial cavity. This local invasion can cause uterine perforation and bleeding, and diagnosis often requires a hysterectomy specimen for definitive tissue examination.", "incorrectas": {"A": "Confinement to the endometrium alone describes a non-invasive hydatidiform mole; invasion beyond the endometrium into the deeper myometrial layer is what defines the invasive mole.", "C": "Invasion reaching the serosa would represent a more extensive, later-stage process (with risk of perforation), but the defining histologic threshold for calling a mole \"invasive\" is villi within the myometrium, not necessarily reaching the outer serosal surface.", "D": "Cervical stromal invasion is not the classic site described for invasive mole; this entity is defined by myometrial invasion of the uterine body, not spread to the cervix."}}}, {"id": "anking-reproductive-system-pathology-2614", "fuente": "anking", "tema": 8, "anki": "1463947774175", "q": "Which of the following is a recognized risk factor for placental abruption?", "o": {"A": "Trauma (e.g., motor vehicle accident, physical abuse)", "B": "Prior cesarean section", "C": "Advanced maternal age with no other risk factors", "D": "Multiple prior vaginal deliveries alone"}, "r": "A", "e": {"correcta": "Trauma, such as a motor vehicle accident or physical abuse, is a well-recognized risk factor for placental abruption because sudden mechanical shearing forces can separate the placenta from the uterine wall prematurely, leading to painful bleeding and potential fetal compromise.", "incorrectas": {"B": "A prior cesarean section is a classic risk factor for placenta accreta spectrum disorders (due to a scarred, deficient decidua basalis allowing abnormal placental attachment), not specifically for placental abruption.", "C": "Advanced maternal age alone, without other contributing factors like hypertension or trauma, is not the primary risk factor emphasized for abruption; it is more classically linked to accreta and aneuploidy risk.", "D": "Multiple prior vaginal deliveries by themselves are not a specifically cited risk factor for abruption; abruption is more strongly linked to hypertension, cocaine use, and trauma."}}}, {"id": "anking-reproductive-system-pathology-2615", "fuente": "anking", "tema": 8, "anki": "1463947850134", "q": "A prior cesarean section increases the risk of placenta accreta primarily because it results in which uterine change?", "o": {"A": "Increased myometrial thickness", "B": "A scar with a deficient or absent decidua basalis", "C": "Cervical incompetence", "D": "Increased uterine vascularity throughout the fundus"}, "r": "B", "e": {"correcta": "A prior C-section leaves a scar with a deficient decidua basalis, the layer that normally limits how deeply the placenta can invade the uterine wall. Without an adequate decidual barrier, chorionic villi attach directly to the myometrium, preventing normal placental separation after delivery and causing severe postpartum hemorrhage; prior D&C and advanced maternal age are additional risk factors.", "incorrectas": {"A": "Increased myometrial thickness is not the mechanism; in fact, the scarred area is often thinner and structurally abnormal, and the key issue is the absent decidual layer, not a thickness change.", "C": "Cervical incompetence refers to premature cervical dilation leading to preterm birth or second-trimester loss, an unrelated process to the myometrial scarring that predisposes to placenta accreta.", "D": "Placenta accreta is related to a defective decidual barrier at the scar site allowing abnormal trophoblastic invasion, not a global increase in uterine vascularity throughout the fundus."}}}, {"id": "anking-reproductive-system-pathology-2616", "fuente": "anking", "tema": 8, "anki": "1463947911732", "q": "What is the standard diagnostic modality used to identify placenta previa?", "o": {"A": "Digital cervical examination", "B": "Ultrasound", "C": "Amniocentesis", "D": "MRI of the pelvis"}, "r": "B", "e": {"correcta": "Placenta previa, in which the placenta implants over or near the internal cervical os, is diagnosed by ultrasound, which safely visualizes the relationship between the placental edge and the cervix without risking bleeding.", "incorrectas": {"A": "Digital cervical examination is contraindicated when placenta previa is suspected because it can provoke severe hemorrhage by directly disrupting the low-lying placenta.", "C": "Amniocentesis is used for genetic and biochemical testing of amniotic fluid, not for evaluating placental location relative to the cervix.", "D": "MRI can occasionally be used as an adjunct in complex cases (e.g., suspected accreta spectrum), but it is not the standard, first-line diagnostic tool for placenta previa; ultrasound remains the routine modality."}}}, {"id": "anking-reproductive-system-pathology-2617", "fuente": "anking", "tema": 8, "anki": "1463951406234", "q": "A pregnant patient presents with rupture of membranes, painless vaginal bleeding, and fetal bradycardia (<110 bpm). Which diagnosis best fits this triad?", "o": {"A": "Placental abruption", "B": "Placenta previa", "C": "Vasa previa", "D": "Uterine rupture"}, "r": "C", "e": {"correcta": "Vasa previa presents classically with the triad of membrane rupture, painless vaginal bleeding, and fetal bradycardia, because fetal vessels running unprotected through the membranes near the cervix tear when the membranes rupture, causing fetal blood loss and resulting bradycardia — an obstetric emergency requiring immediate delivery.", "incorrectas": {"A": "Placental abruption classically presents with painful vaginal bleeding and a tender, possibly rigid uterus, in contrast to the painless bleeding characteristic of vasa previa.", "B": "Placenta previa causes painless third-trimester bleeding as well, but it is not typically accompanied by fetal bradycardia at presentation, since it does not usually cause direct fetal blood loss the way ruptured vasa previa vessels do.", "D": "Uterine rupture classically presents with sudden severe abdominal pain, loss of fetal station, and maternal hemodynamic instability, a different clinical picture from the painless bleeding and bradycardia of vasa previa."}}}, {"id": "anking-reproductive-system-pathology-2618", "fuente": "anking", "tema": 8, "anki": "1463951418297", "q": "A pregnant woman in the third trimester presents with painless vaginal bleeding and no fetal bradycardia. Which condition is most likely responsible?", "o": {"A": "Vasa previa", "B": "Placenta previa", "C": "Placental abruption", "D": "Preterm labor"}, "r": "B", "e": {"correcta": "Placenta previa typically presents with painless third-trimester bleeding without associated fetal bradycardia, because the bleeding originates from disrupted maternal placental vessels near the cervix rather than from torn fetal vessels.", "incorrectas": {"A": "Vasa previa also causes painless bleeding, but it is classically accompanied by fetal bradycardia due to fetal blood loss from ruptured unprotected fetal vessels, distinguishing it from previa without bradycardia.", "C": "Placental abruption presents with painful bleeding and a tender or rigid uterus due to premature separation of the placenta, contrasting with the painless presentation described here.", "D": "Preterm labor presents with regular uterine contractions and cervical change, not primarily as painless vaginal bleeding, making it a less fitting explanation for this scenario."}}}, {"id": "anking-reproductive-system-pathology-2619", "fuente": "anking", "tema": 8, "anki": "1463951426347", "q": "A pregnant patient has painless third-trimester bleeding accompanied by fetal bradycardia (HR <110 bpm). Which diagnosis is most consistent with this presentation?", "o": {"A": "Placenta previa", "B": "Vasa previa", "C": "Placental abruption", "D": "Chorioamnionitis"}, "r": "B", "e": {"correcta": "Vasa previa is characterized by painless third-trimester bleeding with fetal bradycardia, since unprotected fetal vessels traversing the membranes near the cervix rupture along with the membranes, causing direct fetal hemorrhage and rapid fetal decompensation.", "incorrectas": {"A": "Placenta previa causes painless bleeding as well, but it does not typically present with fetal bradycardia, since the bleeding source is maternal placental vessels rather than exposed fetal vessels.", "C": "Placental abruption is characterized by painful bleeding with uterine tenderness or rigidity, a fundamentally different pain profile from the painless presentation described in this vignette.", "D": "Chorioamnionitis presents with fever, uterine tenderness, and foul-smelling discharge due to infection, not primarily with painless bleeding and fetal bradycardia from vessel rupture."}}}, {"id": "anking-reproductive-system-pathology-2620", "fuente": "anking", "tema": 8, "anki": "1463951456776", "q": "Painful vaginal bleeding in the third trimester, often accompanied by uterine tenderness or rigidity, is most characteristic of which condition?", "o": {"A": "Vasa previa", "B": "Placenta previa", "C": "Placental abruption", "D": "Cervical insufficiency"}, "r": "C", "e": {"correcta": "Placental abruption is the classic cause of painful third-trimester bleeding, resulting from premature separation of the placenta from the uterine wall, which causes both hemorrhage and a tender, sometimes rigid, uterus due to concealed or retroplacental blood accumulation.", "incorrectas": {"A": "Vasa previa presents with painless bleeding accompanied by fetal bradycardia, not the painful, tender uterine presentation seen with abruption.", "B": "Placenta previa similarly causes painless bleeding without uterine tenderness, distinguishing it from the painful presentation of abruption.", "D": "Cervical insufficiency classically presents with painless cervical dilation, often leading to second-trimester pregnancy loss, rather than the painful bleeding and uterine tenderness characteristic of abruption."}}}, {"id": "anking-reproductive-system-embryology-2621", "fuente": "anking", "tema": 33, "anki": "1463951464989", "q": "A newborn is noted to have pulmonary hypoplasia and facial/limb deformities. Prenatal ultrasounds had shown a markedly reduced amniotic fluid volume. Which amniotic fluid abnormality was present, classically associated with placental insufficiency, bilateral renal agenesis, or posterior urethral valves?", "o": {"A": "Polyhydramnios", "B": "Oligohydramnios", "C": "Amniotic band rupture", "D": "Vasa previa"}, "r": "B", "e": {"correcta": "Oligohydramnios is too little amniotic fluid, most often from decreased fetal urine output (bilateral renal agenesis, posterior urethral valves) or placental insufficiency shunting blood away from the kidneys. Since the fetus normally swallows and excretes fluid to maintain volume, anything that impairs urination collapses the amniotic fluid pool, and severe cases produce Potter sequence: oligohydramnios plus limb/facial deformities and pulmonary hypoplasia from fetal compression and lack of fluid to expand the lungs.", "incorrectas": {"A": "Polyhydramnios is excess amniotic fluid, typically from impaired fetal swallowing (esophageal/duodenal atresia, anencephaly) or increased fetal urination (maternal diabetes), the opposite mechanism and opposite clinical picture from the compression deformities described.", "C": "Amniotic band rupture refers to fibrous bands from a ruptured amnion entangling fetal parts, causing constriction rings or amputations, not a fluid volume abnormality tied to renal function or placental insufficiency.", "D": "Vasa previa is fetal vessels crossing the internal cervical os unprotected by the umbilical cord or placenta, risking catastrophic fetal hemorrhage at membrane rupture; it has no direct relationship to amniotic fluid volume or Potter sequence."}}}, {"id": "anking-reproductive-system-pathology-2622", "fuente": "anking", "tema": 8, "anki": "1463951475639", "q": "A pregnant woman at 32 weeks with severe preeclampsia is started on a medication to prevent progression to eclamptic seizures. Which drug is used?", "o": {"A": "Phenytoin", "B": "Labetalol", "C": "IV magnesium sulfate", "D": "Diazepam"}, "r": "C", "e": {"correcta": "IV magnesium sulfate is the standard prophylaxis and treatment for eclamptic seizures in severe preeclampsia/eclampsia. Magnesium acts as an NMDA receptor antagonist and calcium channel blocker in neurons, raising the seizure threshold and reducing neuronal excitability, while also having some vasodilatory benefit; toxicity (loss of deep tendon reflexes, respiratory depression) is monitored and reversed with calcium gluconate.", "incorrectas": {"A": "Phenytoin is an anticonvulsant used for generalized tonic-clonic seizures in general neurology but is not the first-line agent for eclampsia prophylaxis; trials have shown magnesium sulfate is superior for this specific indication.", "B": "Labetalol is used to control the hypertension of preeclampsia (along with hydralazine and nifedipine) but does not itself prevent seizures; blood pressure control and seizure prophylaxis are separate treatment goals.", "D": "Diazepam is a benzodiazepine sometimes used to acutely terminate an ongoing seizure, but it is not the agent used prophylactically to prevent eclamptic seizures in preeclampsia."}}}, {"id": "anking-reproductive-system-physiology-2623", "fuente": "anking", "tema": 32, "anki": "1463951480447", "q": "A woman develops glucose intolerance around 26 weeks of gestation. Elevated levels of which placental hormone are responsible for the increased insulin resistance underlying gestational diabetes?", "o": {"A": "Human chorionic gonadotropin", "B": "Progesterone", "C": "Human placental lactogen", "D": "Estriol"}, "r": "C", "e": {"correcta": "Human placental lactogen (hPL), produced by the syncytiotrophoblast, rises progressively through pregnancy and antagonizes maternal insulin action, increasing lipolysis and diverting glucose to the fetus. This physiologic insulin resistance normally increases maternal insulin secretion to compensate; when a woman cannot compensate adequately, gestational diabetes emerges, typically not before 20-24 weeks when hPL levels become high enough to matter.", "incorrectas": {"A": "Human chorionic gonadotropin (hCG) is used to detect and support early pregnancy (maintaining the corpus luteum) but is not the hormone responsible for the insulin resistance of later pregnancy.", "B": "Progesterone maintains the endometrium and uterine quiescence during pregnancy; it contributes modestly to metabolic changes but is not the classic hormone cited as driving gestational insulin resistance.", "D": "Estriol is a marker of fetoplacental well-being (part of the triple/quad screen) reflecting fetal adrenal and hepatic function, not the key mediator of maternal insulin resistance in pregnancy."}}}, {"id": "anking-reproductive-system-pathology-2624", "fuente": "anking", "tema": 8, "anki": "1463951489067", "q": "A pregnant woman at 34 weeks has new hypertension (150/95 mmHg) on two occasions. What level of proteinuria supports the diagnosis of preeclampsia?", "o": {"A": "≥ 100 mg/day", "B": "≥ 300 mg/day", "C": "≥ 1000 mg/day", "D": "≥ 5000 mg/day"}, "r": "B", "e": {"correcta": "Preeclampsia is diagnosed as new-onset hypertension after 20 weeks' gestation plus proteinuria of at least 300 mg/day (or a protein/creatinine ratio greater than 0.3), or hypertension with evidence of end-organ damage even without proteinuria. This threshold reflects glomerular endothelial injury (endotheliosis) characteristic of the disease.", "incorrectas": {"A": "100 mg/day is below the diagnostic threshold and would not by itself meet criteria for the proteinuria component of preeclampsia.", "C": "1000 mg/day (1 g/day) is well above the diagnostic cutoff; while higher levels of proteinuria may support a diagnosis of severe features, the minimum diagnostic threshold is 300 mg/day, not 1 g/day.", "D": "5000 mg/day (5 g/day) was historically used as a cutoff for severe preeclampsia in older classifications, not as the threshold to establish the diagnosis itself, which is 300 mg/day."}}}, {"id": "anking-reproductive-system-pathology-2625", "fuente": "anking", "tema": 8, "anki": "1463951492922", "q": "A woman has significant vaginal bleeding immediately after a vaginal delivery, and on exam the uterine fundus is soft and boggy rather than firm. What is the most likely cause of this postpartum hemorrhage?", "o": {"A": "Uterine atony", "B": "Retained placental tissue", "C": "Genital tract laceration", "D": "Coagulopathy"}, "r": "A", "e": {"correcta": "Uterine atony, failure of the myometrium to contract adequately after delivery, is the most common cause of postpartum hemorrhage. Normally, myometrial contraction compresses the spiral arteries at the placental bed to achieve hemostasis; when the uterus stays soft (boggy) instead of firm, these vessels continue to bleed. Massive hemorrhage can cause hypotension and pituitary infarction, producing Sheehan syndrome.", "incorrectas": {"B": "Retained placental tissue is an important cause of postpartum hemorrhage (preventing full uterine contraction locally) but is less common overall than atony and would classically show incomplete placental tissue on examination.", "C": "Genital tract lacerations (cervical, vaginal, perineal) cause postpartum bleeding, often with a firm, well-contracted uterus, which helps distinguish this cause from atony where the uterus is soft.", "D": "Coagulopathy (e.g., DIC from amniotic fluid embolism or abruption) can cause postpartum hemorrhage but is a less common and usually clinically distinct cause compared to the far more frequent uterine atony."}}}, {"id": "anking-reproductive-pharmacology-2626", "fuente": "anking", "tema": 3, "anki": "1463951509378", "q": "A hemodynamically stable woman is diagnosed with an unruptured ectopic pregnancy and low, declining beta-hCG levels. Which chemotherapeutic agent may be used to medically manage this pregnancy?", "o": {"A": "Cyclophosphamide", "B": "Methotrexate", "C": "Vincristine", "D": "5-Fluorouracil"}, "r": "B", "e": {"correcta": "Methotrexate, a folic acid analog that inhibits dihydrofolate reductase and blocks DNA synthesis, is used to medically terminate an early, unruptured, hemodynamically stable ectopic pregnancy by halting trophoblastic proliferation. It is the same drug used in gestational trophoblastic disease given its efficacy against rapidly dividing trophoblastic tissue.", "incorrectas": {"A": "Cyclophosphamide is an alkylating agent used in various malignancies and autoimmune conditions but is not the standard medical therapy for ectopic pregnancy; its toxicity profile (hemorrhagic cystitis) makes it unsuitable for this indication.", "C": "Vincristine is a vinca alkaloid that disrupts microtubule/mitotic spindle formation, used in lymphomas and other cancers, but has no role in ectopic pregnancy management.", "D": "5-Fluorouracil is a pyrimidine analog used in GI and skin cancers; it is not the folate-antagonist chemotherapy chosen for ectopic pregnancy, where methotrexate's mechanism against trophoblast is preferred."}}}, {"id": "anking-genetics-2627", "fuente": "anking", "tema": 45, "anki": "1463954126962", "q": "A phenotypic male with gynecomastia, small testes, and a karyotype of 47,XXY undergoes buccal smear analysis. Is a Barr body expected to be present?", "o": {"A": "No, because only one X chromosome is present", "B": "Yes, because the extra X chromosome is inactivated", "C": "No, Barr bodies only occur in females", "D": "Yes, but only in half of cells (mosaicism)"}, "r": "B", "e": {"correcta": "Klinefelter syndrome (47,XXY) has two X chromosomes, and as in normal females, all but one X chromosome is inactivated (Lyonization) to form a Barr body, visible on buccal smear. This distinguishes it from Turner syndrome (45,X), which has only a single X chromosome and therefore no Barr body.", "incorrectas": {"A": "This is incorrect because Klinefelter patients have two X chromosomes (47,XXY), not one; the presence of two X's is exactly why a Barr body forms after inactivation of the extra X.", "C": "Barr bodies form whenever a cell has more than one X chromosome, regardless of phenotypic sex; a 47,XXY male has two X chromosomes and therefore does form a Barr body, just like a normal 46,XX female.", "D": "Klinefelter syndrome is a constitutional karyotype (47,XXY in essentially all cells), not a mosaic pattern, so the Barr body is consistently present, not seen in only a subset of cells."}}}, {"id": "anking-genetics-2628", "fuente": "anking", "tema": 45, "anki": "1463955278825", "q": "A short female with webbed neck, wide-spaced nipples, and primary amenorrhea has a karyotype of 45,X. Is a Barr body expected on buccal smear?", "o": {"A": "Yes, one Barr body is present", "B": "No, because there is only one X chromosome", "C": "Yes, two Barr bodies are present", "D": "It cannot be determined without further testing"}, "r": "B", "e": {"correcta": "Turner syndrome (45,X) has only a single X chromosome, so there is no extra X to inactivate and no Barr body forms, unlike Klinefelter syndrome (47,XXY) where the additional X is inactivated to produce one Barr body. This absence of a Barr body is a classic laboratory clue distinguishing Turner syndrome.", "incorrectas": {"A": "A Barr body requires at least two X chromosomes so that one can be inactivated; since Turner syndrome patients have only one X chromosome, no Barr body is formed.", "C": "Two Barr bodies would require three X chromosomes (as in triple X syndrome, 47,XXX), not the single X chromosome present in Turner syndrome.", "D": "The karyotype (45,X) already establishes that only one X chromosome is present, which is sufficient to determine that no Barr body will be seen — no additional testing is needed for this conclusion."}}}, {"id": "anking-reproductive-system-pathology-2629", "fuente": "anking", "tema": 8, "anki": "1463956522023", "q": "Which two benign breast pathologies are characterized by proliferation primarily of the fibrous stroma rather than the glandular epithelium?", "o": {"A": "Fibrocystic change and fat necrosis", "B": "Intraductal papilloma and ductal ectasia", "C": "Fibroadenoma and phyllodes tumor", "D": "Sclerosing adenosis and mastitis"}, "r": "C", "e": {"correcta": "Fibroadenoma and phyllodes tumor are both stromal (mesenchymal) proliferations of the breast, distinguishing them from most other breast lesions that are primarily epithelial or ductal. Fibroadenoma is a benign, well-circumscribed, estrogen-sensitive stromal/epithelial tumor common in young women, while phyllodes tumor is a similar but potentially more cellular and larger stromal proliferation, most often seen in older women and occasionally malignant, presenting classically with a leaf-like (\"phyllodes\") architecture.", "incorrectas": {"A": "Fibrocystic change involves cystic dilation and fibrosis of the ducts/lobules from hormonal fluctuation, and fat necrosis is an inflammatory response to trauma or surgery causing lipid-laden macrophages — neither is a true proliferative stromal neoplasm like fibroadenoma or phyllodes tumor.", "B": "Intraductal papilloma is an epithelial proliferation within a lactiferous duct (presenting with nipple discharge), and ductal ectasia is duct dilation with periductal inflammation — both are epithelial/ductal processes, not primarily stromal.", "D": "Sclerosing adenosis is a proliferative lesion of acini with stromal fibrosis but centered on the epithelial acinar component, and mastitis is an infectious/inflammatory condition, not a stromal neoplasm like fibroadenoma or phyllodes tumor."}}}, {"id": "anking-reproductive-system-pathology-2630", "fuente": "anking", "tema": 8, "anki": "1463957692573", "q": "A breast biopsy shows small, discohesive cells growing in a single-file pattern with occasional cells containing a mucin vacuole that pushes the nucleus to one side, giving a signet ring appearance. Which type of breast cancer is this?", "o": {"A": "Invasive ductal carcinoma", "B": "Medullary carcinoma", "C": "Lobular carcinoma (in situ or invasive)", "D": "Inflammatory breast carcinoma"}, "r": "C", "e": {"correcta": "Lobular carcinoma, both in situ and invasive forms, characteristically shows loss of E-cadherin, leading to discohesive cells that grow in a single-file (\"Indian file\") pattern and may show signet ring morphology from intracytoplasmic mucin vacuoles. This distinguishes it from ductal carcinoma, which retains cell-cell cohesion.", "incorrectas": {"A": "Invasive ductal carcinoma is the most common breast cancer subtype, forming duct-like or solid nests with retained cellular cohesion (E-cadherin intact), and is not classically associated with the single-file, signet-ring pattern.", "B": "Medullary carcinoma is characterized by sheets of large, high-grade pleomorphic cells with a prominent lymphocytic infiltrate and pushing borders, a very different histologic picture from the discohesive signet ring cells of lobular carcinoma.", "D": "Inflammatory breast carcinoma is a clinical diagnosis based on tumor cells invading dermal lymphatics causing peau d'orange skin changes, not a histologic description of cell morphology like the signet ring pattern seen in lobular carcinoma."}}}, {"id": "anking-reproductive-system-pathology-2631", "fuente": "anking", "tema": 8, "anki": "1463957763047", "q": "A 55-year-old man develops unilateral breast tissue enlargement. This condition results from an imbalance favoring which hormonal activity relative to androgen activity?", "o": {"A": "Increased estrogen activity", "B": "Increased prolactin activity", "C": "Increased cortisol activity", "D": "Increased thyroid hormone activity"}, "r": "A", "e": {"correcta": "Gynecomastia is breast tissue enlargement in males caused by an increase in the estrogen-to-androgen activity ratio, whether from increased estrogen production, decreased androgen production/action, or drugs that shift this balance. Common causes include physiologic states (puberty, aging with increased peripheral aromatization, obesity), cirrhosis, Klinefelter syndrome, and certain medications.", "incorrectas": {"B": "Prolactin excess (e.g., from a prolactinoma) classically causes galactorrhea rather than the ductal/stromal proliferation of gynecomastia, and is not the hormonal ratio classically implicated in gynecomastia's definition.", "C": "Cortisol excess causes features of Cushing syndrome (central obesity, striae, hypertension) but is not the mechanism underlying breast tissue enlargement in gynecomastia.", "D": "Thyroid hormone abnormalities can indirectly affect sex hormone-binding globulin and estrogen levels, but the classic, directly implicated imbalance in gynecomastia is increased estrogen relative to androgen activity, not thyroid hormone itself."}}}, {"id": "anking-toxicities-side-effects-2632", "fuente": "anking", "tema": 29, "anki": "1463957828496", "q": "A patient develops gynecomastia after starting a new medication regimen. Which of the following is LEAST likely to be the causative drug, based on drugs classically linked to gynecomastia (remembered by 'Some Hormones Create Knockers')?", "o": {"A": "Spironolactone", "B": "Cimetidine", "C": "Ketoconazole", "D": "Metoprolol"}, "r": "D", "e": {"correcta": "Metoprolol is a beta-1 selective blocker not classically associated with gynecomastia; the mnemonic 'Some Hormones Create Knockers' captures Spironolactone, Hormones (estrogens), Cimetidine, and Ketoconazole as the classic offenders, each interfering with androgen synthesis/action or acting as estrogen-like compounds or antiandrogens.", "incorrectas": {"A": "Spironolactone is an aldosterone antagonist that also blocks androgen receptors and inhibits androgen synthesis, making it a classic cause of gynecomastia and part of the mnemonic.", "B": "Cimetidine, an H2 blocker, has antiandrogenic activity (blocking androgen receptors) and is a well-known cause of gynecomastia, included in the mnemonic.", "C": "Ketoconazole inhibits steroidogenic cytochrome P450 enzymes, blocking androgen synthesis, and is a classic cause of gynecomastia captured by the mnemonic ('Knockers')."}}}, {"id": "anking-reproductive-system-pathology-2633", "fuente": "anking", "tema": 8, "anki": "1463958394262", "q": "A young woman presents with an ovarian mass; on gross pathology it appears as a yellow, friable, hemorrhagic solid mass, and serum AFP is markedly elevated. Which germ cell tumor is this?", "o": {"A": "Dysgerminoma", "B": "Mature teratoma", "C": "Yolk sac (endodermal sinus) tumor", "D": "Choriocarcinoma"}, "r": "C", "e": {"correcta": "Yolk sac (endodermal sinus) tumor is a malignant germ cell tumor that classically presents as a yellow, friable, hemorrhagic solid mass, most often in children and young women, and secretes alpha-fetoprotein (AFP), reflecting its differentiation resembling the yolk sac. Schiller-Duval bodies (glomeruloid structures) are a characteristic histologic finding.", "incorrectas": {"A": "Dysgerminoma is the ovarian counterpart of testicular seminoma, composed of sheets of uniform cells, and is associated with elevated LDH (and sometimes hCG), not AFP, and does not have the yellow, hemorrhagic gross appearance described.", "B": "Mature (cystic) teratoma is the most common benign ovarian germ cell tumor, containing tissue from all three germ layers (hair, teeth, sebum) typically within a cystic structure, not a solid hemorrhagic mass with AFP elevation.", "D": "Choriocarcinoma is composed of malignant trophoblastic tissue (cytotrophoblast and syncytiotrophoblast) and produces hCG, not AFP; it also has a characteristic hematogenous spread pattern rather than the yellow friable gross description given."}}}, {"id": "anking-reproductive-system-pathology-2634", "fuente": "anking", "tema": 8, "anki": "1463958628607", "q": "A young woman is found to have an ovarian germ cell tumor with markedly elevated serum LDH. Which tumor is most classically associated with this laboratory finding?", "o": {"A": "Yolk sac tumor", "B": "Dysgerminoma", "C": "Choriocarcinoma", "D": "Immature teratoma"}, "r": "B", "e": {"correcta": "Dysgerminoma, the ovarian analog of testicular seminoma, is composed of large cells with abundant glycogen and is classically associated with elevated LDH, making LDH a useful tumor marker for diagnosis and monitoring. It is the most common malignant germ cell tumor of the ovary and is radiosensitive.", "incorrectas": {"A": "Yolk sac tumor is associated with elevated AFP rather than LDH, reflecting its resemblance to yolk sac tissue, which normally produces AFP during early development.", "C": "Choriocarcinoma is associated with markedly elevated beta-hCG from syncytiotrophoblastic differentiation, not LDH, and often presents with early hematogenous metastasis (e.g., to the lungs).", "D": "Immature teratoma contains embryonic (immature) neural tissue and is graded by the amount of immature neuroepithelium; it does not have a specific classic association with LDH elevation like dysgerminoma does."}}}, {"id": "anking-reproductive-system-pathology-2635", "fuente": "anking", "tema": 8, "anki": "1463958668258", "q": "An ovarian germ cell tumor is found to secrete markedly elevated alpha-fetoprotein (AFP). Which tumor is this?", "o": {"A": "Dysgerminoma", "B": "Yolk sac (endodermal sinus) tumor", "C": "Choriocarcinoma", "D": "Struma ovarii"}, "r": "B", "e": {"correcta": "Yolk sac (endodermal sinus) tumor recapitulates yolk sac differentiation and secretes alpha-fetoprotein, the same protein normally produced by the fetal yolk sac and liver, making AFP a key serum marker for diagnosis and surveillance of this tumor.", "incorrectas": {"A": "Dysgerminoma is marked by elevated LDH (and occasionally hCG from syncytiotrophoblastic giant cells), not AFP, reflecting its seminoma-like cellular composition rather than yolk sac differentiation.", "C": "Choriocarcinoma produces beta-hCG from trophoblastic tissue, not AFP; hCG elevation drives its clinical presentation and monitoring, distinct from the AFP marker of yolk sac tumor.", "D": "Struma ovarii is a monodermal teratoma composed of mature thyroid tissue that can cause hyperthyroidism, and is not associated with AFP secretion since it does not contain yolk sac elements."}}}, {"id": "anking-reproductive-system-pathology-2636", "fuente": "anking", "tema": 8, "anki": "1463958744601", "q": "A woman with a markedly elevated beta-hCG level (from a hydatidiform mole or choriocarcinoma) is found to have bilateral, multiloculated ovarian cysts on ultrasound. Which type of ovarian cyst is this, resulting from gonadotropin overstimulation?", "o": {"A": "Follicular cyst", "B": "Corpus luteum cyst", "C": "Theca-lutein cyst", "D": "Endometrioma"}, "r": "C", "e": {"correcta": "Theca-lutein cysts arise from excessive stimulation of the ovarian theca cells by very high levels of hCG, as seen with hydatidiform moles and choriocarcinoma (and also with multiple gestation or ovulation induction). They are often bilateral and multiple, and typically regress once the source of hCG is removed.", "incorrectas": {"A": "Follicular cysts result from a mature follicle that fails to rupture or from atresia of an early antral follicle; they are common, usually unilateral and unrelated to markedly elevated hCG from trophoblastic disease.", "B": "Corpus luteum cysts form when the corpus luteum fails to regress and continues to accumulate fluid, sometimes hemorrhaging; this is a normal luteal structure phenomenon, not the gonadotropin-driven theca cell hyperstimulation of theca-lutein cysts.", "D": "Endometrioma (\"chocolate cyst\") is an ovarian cyst filled with old blood from ectopic endometrial tissue as part of endometriosis, unrelated to hCG-driven stimulation seen with gestational trophoblastic disease."}}}, {"id": "anking-endocrine-pathology-2637", "fuente": "anking", "tema": 5, "anki": "1464061527306", "q": "A young woman with hyperthyroidism, exophthalmos, and a diffusely enlarged thyroid is found to carry two specific HLA alleles associated with this autoimmune disease. Which HLA alleles are classically linked to Graves disease?", "o": {"A": "HLA-DR4 and HLA-DQ8", "B": "HLA-B27 and HLA-DR2", "C": "HLA-B8 and HLA-DR3", "D": "HLA-DR5 and HLA-DQ2"}, "r": "C", "e": {"correcta": "Graves disease, an autoimmune hyperthyroidism caused by TSH receptor-stimulating autoantibodies, is classically associated with HLA-B8 and HLA-DR3, reflecting the broader pattern in which many autoimmune endocrinopathies cluster with specific HLA class I and II alleles that influence antigen presentation and self-tolerance.", "incorrectas": {"A": "HLA-DR4 and HLA-DQ8 are more classically associated with type 1 diabetes mellitus and rheumatoid arthritis, not Graves disease.", "B": "HLA-B27 is associated with the seronegative spondyloarthropathies (ankylosing spondylitis, reactive arthritis, psoriatic arthritis, IBD-associated arthritis), and HLA-DR2 is linked to conditions like Goodpasture syndrome and multiple sclerosis, not Graves disease.", "D": "HLA-DR5 is associated with Hashimoto thyroiditis and pernicious anemia, and HLA-DQ2 with celiac disease; these alleles pair with different autoimmune diseases than the HLA-B8/DR3 combination seen in Graves disease."}}}, {"id": "anking-endocrine-pharmacology-2638", "fuente": "anking", "tema": 24, "anki": "1464061546338", "q": "A woman in her first trimester of pregnancy is diagnosed with Graves disease requiring thionamide therapy. Which drug is preferred during the first trimester due to a lower teratogenic risk than its alternative?", "o": {"A": "Methimazole", "B": "Propylthiouracil (PTU)", "C": "Levothyroxine", "D": "Radioactive iodine"}, "r": "B", "e": {"correcta": "Propylthiouracil (PTU) is preferred in the first trimester of pregnancy because methimazole carries a risk of causing aplasia cutis (a congenital scalp defect) and other embryopathy when used during this critical period of organogenesis. PTU has its own risk of hepatotoxicity, which is why it is typically switched to methimazole after the first trimester once the teratogenic risk window has passed.", "incorrectas": {"A": "Methimazole is generally preferred over PTU in the second and third trimesters (due to PTU's hepatotoxicity risk), but it is avoided in the first trimester because of its association with aplasia cutis and other fetal malformations.", "C": "Levothyroxine is a treatment for hypothyroidism, not hyperthyroidism; it would not be appropriate therapy for a pregnant woman with Graves disease-driven hyperthyroidism.", "D": "Radioactive iodine is absolutely contraindicated in pregnancy because it crosses the placenta and can ablate or damage the fetal thyroid gland, unlike the thionamides which are used cautiously during pregnancy."}}}, {"id": "anking-endocrine-pharmacology-2639", "fuente": "anking", "tema": 24, "anki": "1464061625945", "q": "A pregnant woman with Graves disease is now in her second trimester. Which thionamide becomes the preferred agent at this point in pregnancy, given PTU's own toxicity profile?", "o": {"A": "Propylthiouracil (PTU)", "B": "Methimazole", "C": "Iodide (Lugol's solution)", "D": "Propranolol"}, "r": "B", "e": {"correcta": "Methimazole becomes the preferred thionamide in the second and third trimesters because the risk period for its aplasia cutis teratogenicity (associated with first-trimester exposure) has passed, while continuing PTU raises concern for maternal hepatotoxicity, an idiosyncratic and potentially severe adverse effect linked to prolonged PTU use.", "incorrectas": {"A": "PTU remains reserved for the first trimester specifically to avoid methimazole's teratogenicity; continuing it long-term into later trimesters increases the risk of PTU-associated hepatotoxicity without added teratogenic benefit.", "C": "Iodide solutions are used short-term for thyroid storm or preoperative preparation (Wolff-Chaikoff effect) rather than as chronic maintenance thionamide therapy for Graves disease throughout pregnancy.", "D": "Propranolol is used adjunctively to control the adrenergic symptoms of hyperthyroidism (tachycardia, tremor) but does not block thyroid hormone synthesis the way methimazole does, so it does not replace thionamide therapy."}}}, {"id": "anking-endocrine-pathology-2640", "fuente": "anking", "tema": 5, "anki": "1464111583705", "q": "A healthcare worker presents with symptoms of hyperthyroidism, recent unexplained weight loss, and low radioactive iodine uptake on thyroid scan. Which cause of hyperthyroidism is most consistent with this presentation?", "o": {"A": "Subacute (de Quervain) thyroiditis", "B": "Factitious thyrotoxicosis (exogenous thyroid hormone)", "C": "Toxic multinodular goiter", "D": "TSH-secreting pituitary adenoma"}, "r": "B", "e": {"correcta": "Factitious thyrotoxicosis results from surreptitious or excessive ingestion of exogenous thyroid hormone, classically seen in healthcare workers who have access to thyroid medication (or others seeking weight loss). Because thyroid hormone is coming from outside the gland, the thyroid's own iodine uptake and hormone synthesis are suppressed, producing low radioactive iodine uptake despite clinical hyperthyroidism.", "incorrectas": {"A": "Subacute (de Quervain) thyroiditis also causes low radioactive iodine uptake (due to follicular disruption releasing preformed hormone) but classically presents with a painful, tender thyroid and often follows a viral URI, not simply weight loss in a healthcare worker.", "C": "Toxic multinodular goiter causes hyperthyroidism with increased (not decreased) radioactive iodine uptake in the autonomously functioning nodules, distinguishing it from factitious thyrotoxicosis.", "D": "A TSH-secreting pituitary adenoma causes hyperthyroidism with elevated TSH and increased iodine uptake by an overstimulated gland, which is the opposite uptake pattern from the low uptake seen with exogenous hormone intake."}}}, {"id": "anking-toxicities-side-effects-2641", "fuente": "anking", "tema": 29, "anki": "1464300805950", "q": "A patient taking a thionamide for hyperthyroidism develops a new skin eruption. Which of the following is a well-known possible skin complication common to both propylthiouracil and methimazole?", "o": {"A": "Rash", "B": "Aplasia cutis", "C": "Hyperpigmentation", "D": "Photosensitivity with bullae"}, "r": "A", "e": {"correcta": "Rash is a recognized adverse effect that can occur with either propylthiouracil or methimazole, reflecting a hypersensitivity-type skin reaction to these thionamide drugs; it is generally managed by monitoring or switching agents rather than by drug discontinuation alone in most cases.", "incorrectas": {"B": "Aplasia cutis is a specific fetal/congenital scalp defect associated with methimazole exposure during the first trimester of pregnancy, not a skin complication that occurs in patients (adults) taking the drug themselves.", "C": "Hyperpigmentation is a classic side effect of fludrocortisone and of primary adrenal insufficiency (via elevated ACTH/MSH), not a described complication of thionamide antithyroid drugs.", "D": "Photosensitivity with bullae is more characteristic of drugs like tetracyclines or amiodarone-related phototoxicity, not a recognized classic side effect of propylthiouracil or methimazole."}}}, {"id": "anking-endocrine-pharmacology-2642", "fuente": "anking", "tema": 24, "anki": "1464300810389", "q": "A patient with hypothyroidism and myxedema is started on a synthetic hormone analog structurally identical to T4. Which drug is this?", "o": {"A": "Triiodothyronine", "B": "Levothyroxine", "C": "Propylthiouracil", "D": "Methimazole"}, "r": "B", "e": {"correcta": "Levothyroxine is a synthetic T4 (thyroxine) analog used as first-line replacement therapy for hypothyroidism and myxedema. As a prohormone, it is peripherally converted to the more active T3 in target tissues, providing a steady, long half-life supply of thyroid hormone that closely mimics normal physiology.", "incorrectas": {"A": "Triiodothyronine (liothyronine) is the T3 analog rather than T4; it has a shorter half-life and more rapid onset, sometimes used in specific situations like myxedema coma but is not the standard first-line chronic replacement like levothyroxine.", "C": "Propylthiouracil is an antithyroid thionamide used to treat hyperthyroidism by blocking thyroid hormone synthesis and peripheral T4-to-T3 conversion, the opposite therapeutic goal from replacing deficient thyroid hormone.", "D": "Methimazole is likewise an antithyroid drug for hyperthyroidism, inhibiting thyroid peroxidase-mediated hormone synthesis, not a hormone replacement for hypothyroidism."}}}, {"id": "anking-endocrine-pharmacology-2643", "fuente": "anking", "tema": 24, "anki": "1464300815685", "q": "A patient in myxedema coma is given a fast-acting synthetic thyroid hormone identical to T3 for rapid effect. Which drug is this?", "o": {"A": "Levothyroxine", "B": "Triiodothyronine", "C": "Cinacalcet", "D": "Fludrocortisone"}, "r": "B", "e": {"correcta": "Triiodothyronine (liothyronine) is a synthetic T3 hormone analog used to treat hypothyroidism and myxedema; because T3 is the more biologically active form and does not require peripheral conversion, it has a faster onset of action, useful in urgent situations like myxedema coma.", "incorrectas": {"A": "Levothyroxine (T4) requires peripheral deiodination to the active T3 form, giving it a slower onset of action compared to directly administering T3 (triiodothyronine), which is why T3 is favored when rapid effect is needed.", "C": "Cinacalcet is a calcimimetic that increases the sensitivity of the calcium-sensing receptor in the parathyroid gland, unrelated to thyroid hormone replacement.", "D": "Fludrocortisone is a synthetic mineralocorticoid (aldosterone analog) used in adrenal insufficiency, entirely unrelated to thyroid hormone physiology or replacement."}}}, {"id": "anking-toxicities-side-effects-2644", "fuente": "anking", "tema": 29, "anki": "1464300819838", "q": "Beyond treating hypothyroidism, thyroid hormone replacement drugs like levothyroxine and triiodothyronine are sometimes misused off-label for which purpose?", "o": {"A": "Weight loss supplement", "B": "Appetite stimulation", "C": "Sedation", "D": "Blood pressure lowering in hypertensive emergencies"}, "r": "A", "e": {"correcta": "Thyroid hormone replacement drugs are sometimes misused off-label as weight loss supplements because increased thyroid hormone raises basal metabolic rate; however, this comes at the cost of iatrogenic hyperthyroidism symptoms such as tachycardia, arrhythmias, tremor, and heat intolerance, making this an unsafe and inappropriate use.", "incorrectas": {"B": "Thyroid hormone excess actually tends to increase metabolic demand and can be associated with increased appetite in true hyperthyroidism, but appetite stimulation is not the recognized off-label use being described for these drugs.", "C": "Thyroid hormone causes a hypermetabolic, stimulant-like state (tachycardia, anxiety, tremor) rather than sedation, so it would not be used off-label for a sedative effect.", "D": "Excess thyroid hormone tends to increase heart rate and cardiac output and can precipitate arrhythmias, the opposite of a blood-pressure-lowering effect useful in hypertensive emergencies."}}}, {"id": "anking-toxicities-side-effects-2645", "fuente": "anking", "tema": 29, "anki": "1464300847477", "q": "A patient on levothyroxine for hypothyroidism is inadvertently overdosed and develops palpitations on ECG monitoring. Which cardiac adverse effects are classically associated with excess thyroid hormone replacement?", "o": {"A": "Bradycardia and heart block", "B": "Tachycardia and arrhythmias", "C": "Pericardial effusion", "D": "Orthostatic hypotension"}, "r": "B", "e": {"correcta": "Excess thyroid hormone (from over-replacement with levothyroxine or triiodothyronine) increases cardiac beta-adrenergic receptor sensitivity and myocardial oxygen demand, producing tachycardia and arrhythmias (including atrial fibrillation), alongside other hyperthyroid symptoms like tremor and heat intolerance.", "incorrectas": {"A": "Bradycardia and heart block are more typical of hypothyroidism itself (untreated or under-treated) rather than an adverse effect of excess thyroid hormone replacement, which instead speeds the heart rate.", "C": "Pericardial effusion is a recognized finding in severe, longstanding hypothyroidism (myxedema), not a toxicity of thyroid hormone replacement overdose.", "D": "Orthostatic hypotension is not a classic cardiac effect of thyroid hormone excess; hyperthyroid states more typically raise heart rate and can even increase systolic blood pressure via increased cardiac output."}}}, {"id": "anking-endocrine-physiology-2646", "fuente": "anking", "tema": 23, "anki": "1464300876421", "q": "A woman at term is being induced for labor. Which posterior pituitary hormone is administered to stimulate uterine contractions?", "o": {"A": "Vasopressin (ADH)", "B": "Oxytocin", "C": "Prolactin", "D": "Follicle-stimulating hormone"}, "r": "B", "e": {"correcta": "Oxytocin, released from the posterior pituitary (synthesized in the hypothalamus), stimulates rhythmic uterine smooth muscle contraction via oxytocin receptors, making it useful both to induce/augment labor and to control postpartum uterine hemorrhage by promoting sustained uterine contraction after delivery.", "incorrectas": {"A": "Vasopressin (ADH) shares the same hypothalamic origin and posterior pituitary storage as oxytocin but functions in water reabsorption via renal V2 receptors, not in stimulating uterine contractions for labor.", "C": "Prolactin, an anterior pituitary hormone, stimulates milk production in the mammary glands but has no direct role in inducing uterine contractions during labor.", "D": "Follicle-stimulating hormone (FSH), also from the anterior pituitary, regulates follicular development and spermatogenesis, unrelated to the induction of labor contractions."}}}, {"id": "anking-endocrine-pharmacology-2647", "fuente": "anking", "tema": 24, "anki": "1464300929572", "q": "A patient with primary adrenal insufficiency (Addison disease) requires replacement of deficient mineralocorticoid activity in addition to glucocorticoid replacement. Which drug, an aldosterone analog, is used for this purpose?", "o": {"A": "Hydrocortisone", "B": "Fludrocortisone", "C": "Spironolactone", "D": "Cinacalcet"}, "r": "B", "e": {"correcta": "Fludrocortisone is a synthetic aldosterone analog used to replace mineralocorticoid activity in primary adrenal insufficiency, restoring sodium/water retention and potassium excretion at the renal distal nephron. It has minimal glucocorticoid activity, so it can be safely combined with glucocorticoid replacement (e.g., hydrocortisone) without the added risk of iatrogenic Cushing syndrome.", "incorrectas": {"A": "Hydrocortisone provides glucocorticoid replacement (and has some intrinsic mineralocorticoid activity at high doses) but is primarily used to replace cortisol, not as the dedicated mineralocorticoid replacement that fludrocortisone provides.", "C": "Spironolactone is a mineralocorticoid receptor antagonist, doing the opposite of what is needed in adrenal insufficiency — it would worsen mineralocorticoid deficiency rather than replace it.", "D": "Cinacalcet is a calcimimetic used to increase calcium-sensing receptor sensitivity in the parathyroid gland to reduce PTH secretion, entirely unrelated to adrenal hormone replacement."}}}, {"id": "anking-toxicities-side-effects-2648", "fuente": "anking", "tema": 29, "anki": "1464300939755", "q": "A patient on fludrocortisone for adrenal insufficiency develops darkened patches of skin. Which skin complication is associated with this drug?", "o": {"A": "Vitiligo", "B": "Hyperpigmentation", "C": "Erythema nodosum", "D": "Acanthosis nigricans"}, "r": "B", "e": {"correcta": "Hyperpigmentation is a described skin complication associated with fludrocortisone use; in primary adrenal insufficiency itself, hyperpigmentation is also classically seen due to elevated ACTH (and its precursor POMC, which also yields melanocyte-stimulating hormone), so this finding can occur both from the underlying disease and reportedly with treatment.", "incorrectas": {"A": "Vitiligo is an autoimmune process causing depigmented (not hyperpigmented) patches from melanocyte destruction; it is associated with autoimmune Addison disease as a comorbid autoimmune condition, not as a drug side effect of fludrocortisone.", "C": "Erythema nodosum is a panniculitis presenting as tender red nodules, associated with conditions like sarcoidosis, infections, and certain drugs (e.g., sulfonamides, OCPs), not classically linked to fludrocortisone.", "D": "Acanthosis nigricans is velvety hyperpigmented skin thickening associated with insulin resistance and certain malignancies, not a described adverse effect of mineralocorticoid replacement therapy."}}}, {"id": "anking-toxicities-side-effects-2649", "fuente": "anking", "tema": 29, "anki": "1464300945786", "q": "A patient on fludrocortisone develops peripheral edema and worsening dyspnea on exertion. Which underlying condition is being exacerbated by this aldosterone analog's sodium and water retention?", "o": {"A": "Heart failure", "B": "Chronic kidney disease", "C": "Cirrhosis", "D": "Hypothyroidism"}, "r": "A", "e": {"correcta": "Fludrocortisone, by mimicking aldosterone, promotes sodium and water retention (and potassium excretion) at the renal collecting duct, which can lead to volume overload and edema, and can precipitate or worsen heart failure in susceptible patients, requiring careful monitoring of volume status.", "incorrectas": {"B": "While fludrocortisone's electrolyte effects (sodium retention, potassium loss) require monitoring in kidney disease, the classic adverse effect emphasized for fludrocortisone is volume overload precipitating or worsening heart failure, not primarily causing progression of chronic kidney disease.", "C": "Cirrhosis itself causes its own sodium retention via secondary hyperaldosteronism, but the specific adverse effect linked to fludrocortisone use is exacerbation of heart failure from fluid retention, not cirrhosis.", "D": "Hypothyroidism is unrelated to the sodium/water retention mechanism of a mineralocorticoid like fludrocortisone; it is not a condition classically worsened by this drug's edema-inducing effect."}}}, {"id": "anking-endocrine-pharmacology-2650", "fuente": "anking", "tema": 24, "anki": "1464300958946", "q": "A patient with secondary hyperparathyroidism from chronic kidney disease is started on a drug that increases the sensitivity of calcium-sensing receptors in the parathyroid gland. Which drug is this?", "o": {"A": "Teriparatide", "B": "Cinacalcet", "C": "Sevelamer", "D": "Calcitriol"}, "r": "B", "e": {"correcta": "Cinacalcet is a calcimimetic that increases the sensitivity of calcium-sensing receptors (CaSR) on parathyroid chief cells to extracellular calcium, making the gland perceive calcium levels as higher than they actually are. This suppresses PTH secretion, useful in secondary hyperparathyroidism of chronic kidney disease and in parathyroid carcinoma.", "incorrectas": {"A": "Teriparatide is a recombinant PTH analog that, when given intermittently, stimulates osteoblastic bone formation for osteoporosis treatment — essentially the opposite therapeutic direction (increasing PTH-like activity) from cinacalcet's PTH-suppressing effect.", "C": "Sevelamer is a non-calcium, non-aluminum phosphate binder used to control hyperphosphatemia in chronic kidney disease; it works in the gut to bind dietary phosphate rather than acting on the parathyroid calcium-sensing receptor.", "D": "Calcitriol is active vitamin D, used to treat vitamin D deficiency and secondary hyperparathyroidism by increasing intestinal calcium absorption and directly suppressing PTH gene transcription, a different mechanism than sensitizing the calcium-sensing receptor."}}}, {"id": "anking-toxicities-side-effects-2651", "fuente": "anking", "tema": 29, "anki": "1464301013983", "q": "A patient started on cinacalcet for secondary hyperparathyroidism develops perioral numbness and tingling in the fingertips. Which adverse effect explains these symptoms?", "o": {"A": "Hypercalcemia", "B": "Hypocalcemia (due to decreased PTH)", "C": "Hyperkalemia", "D": "Hypermagnesemia"}, "r": "B", "e": {"correcta": "Cinacalcet increases calcium-sensing receptor sensitivity, suppressing PTH secretion; since PTH normally raises serum calcium (via bone resorption, renal reabsorption, and activation of vitamin D), a drug-induced drop in PTH can cause hypocalcemia, producing perioral numbness, paresthesias, and even tetany in more severe cases.", "incorrectas": {"A": "Hypercalcemia would be the expected complication of excess PTH activity (e.g., primary hyperparathyroidism) or of PTH analogs, not of cinacalcet, which lowers PTH and therefore serum calcium.", "C": "Hyperkalemia is not a characteristic adverse effect of cinacalcet; its principal metabolic effect relates to calcium and PTH, not potassium homeostasis.", "D": "Hypermagnesemia is not a recognized adverse effect of cinacalcet; the drug's mechanism centers on the calcium-sensing receptor and calcium/PTH regulation, not magnesium handling."}}}, {"id": "anking-gastrointestinal-pharmacology-2652", "fuente": "anking", "tema": 40, "anki": "1464476674889", "q": "A patient using an antacid regularly for dyspepsia develops muscle weakness, and labs reveal a common electrolyte abnormality shared by essentially all antacids. Which adverse effect is this?", "o": {"A": "Hyperkalemia", "B": "Hypokalemia", "C": "Hypernatremia", "D": "Hyponatremia"}, "r": "B", "e": {"correcta": "Hypokalemia is an adverse effect common to all antacids, thought to relate to the alkalinization of gastric/urinary environments and shifts in electrolyte handling that promote renal potassium wasting; this is a class effect to keep in mind regardless of which specific antacid (aluminum, magnesium, or calcium-based) is used.", "incorrectas": {"A": "Hyperkalemia is the opposite electrolyte disturbance from what antacids classically cause; antacids are more associated with potassium loss (hypokalemia), not retention.", "C": "Hypernatremia is not the shared electrolyte disturbance emphasized for antacids as a class; the classic shared adverse effect relates to potassium loss, not sodium excess.", "D": "Hyponatremia is likewise not the classic class-wide antacid adverse effect; the electrolyte abnormality common to all antacids is hypokalemia."}}}, {"id": "anking-gastrointestinal-pharmacology-2653", "fuente": "anking", "tema": 40, "anki": "1464478354579", "q": "A patient who has been overusing an antacid for chronic heartburn develops significant constipation. Which antacid, remembered by the mnemonic 'aluminimum amount of feces,' is most associated with this side effect?", "o": {"A": "Magnesium hydroxide", "B": "Calcium carbonate", "C": "Aluminum hydroxide", "D": "Sodium bicarbonate"}, "r": "C", "e": {"correcta": "Aluminum hydroxide is associated with constipation when overused, captured by the mnemonic 'aluminimum amount of feces.' This occurs because aluminum ions slow gastrointestinal motility, contrasting with magnesium-based antacids which instead cause diarrhea, motivating the common practice of combining aluminum and magnesium hydroxide antacids to balance bowel effects.", "incorrectas": {"A": "Magnesium hydroxide characteristically causes diarrhea rather than constipation ('Mg = Must go'), the opposite bowel effect from aluminum hydroxide.", "B": "Calcium carbonate is associated with hypercalcemia and rebound acid hypersecretion (milk-alkali syndrome) rather than being the classic antacid linked to constipation.", "D": "Sodium bicarbonate is a systemic antacid associated with metabolic alkalosis and sodium overload; it is not the antacid classically linked to constipation from decreased GI motility."}}}, {"id": "anking-gastrointestinal-pharmacology-2654", "fuente": "anking", "tema": 40, "anki": "1464478399061", "q": "A patient on long-term high-dose antacid therapy develops bone pain and is found to have low serum phosphate along with radiographic evidence of osteodystrophy. Which antacid is most likely responsible?", "o": {"A": "Calcium carbonate", "B": "Magnesium hydroxide", "C": "Aluminum hydroxide", "D": "Sodium bicarbonate"}, "r": "C", "e": {"correcta": "Aluminum hydroxide binds dietary phosphate in the gut, reducing its absorption and potentially causing hypophosphatemia with chronic overuse; sustained phosphate depletion impairs bone mineralization and can lead to osteodystrophy (osteomalacia-like bone disease).", "incorrectas": {"A": "Calcium carbonate is more associated with hypercalcemia and milk-alkali syndrome from excess calcium absorption, not with phosphate binding causing hypophosphatemia and osteodystrophy.", "B": "Magnesium hydroxide's classic adverse effect is diarrhea (and hypermagnesemia in renal impairment), not hypophosphatemic bone disease from phosphate binding.", "D": "Sodium bicarbonate causes systemic alkalosis and sodium overload, unrelated to phosphate binding or the bone demineralization seen with chronic aluminum hydroxide use."}}}, {"id": "anking-gastrointestinal-pharmacology-2655", "fuente": "anking", "tema": 40, "anki": "1464478432028", "q": "A patient using large amounts of an antacid for dyspepsia develops hypercalcemia, metabolic alkalosis, and renal insufficiency (milk-alkali syndrome), along with rebound acid hypersecretion. Which antacid is responsible?", "o": {"A": "Aluminum hydroxide", "B": "Magnesium hydroxide", "C": "Calcium carbonate", "D": "Sodium bicarbonate"}, "r": "C", "e": {"correcta": "Calcium carbonate, when taken in excess (especially with dairy or vitamin D), can cause milk-alkali syndrome (hypercalcemia, metabolic alkalosis, and renal injury). The hypercalcemia paradoxically stimulates gastrin release, causing rebound acid hypersecretion once the antacid effect wears off; calcium can also chelate and reduce the absorption/effectiveness of other drugs.", "incorrectas": {"A": "Aluminum hydroxide is linked to constipation and, with chronic use, hypophosphatemia and osteodystrophy, not the hypercalcemic milk-alkali picture described here.", "B": "Magnesium hydroxide causes diarrhea and, in renal failure, hypermagnesemia, but is not the antacid classically responsible for milk-alkali syndrome and rebound acid hypersecretion.", "D": "Sodium bicarbonate can cause metabolic alkalosis and sodium overload but is not specifically tied to hypercalcemia or the milk-alkali syndrome, which is a calcium carbonate-specific phenomenon."}}}, {"id": "anking-gastrointestinal-pharmacology-2656", "fuente": "anking", "tema": 40, "anki": "1464478447015", "q": "By altering gastric and urinary pH, antacids can affect which pharmacokinetic property of other co-administered drugs?", "o": {"A": "Bioavailability", "B": "Protein binding", "C": "Volume of distribution", "D": "Hepatic clearance"}, "r": "A", "e": {"correcta": "Antacids raise gastric pH, which can alter the ionization, solubility, and dissolution of other orally administered drugs, changing how much of the dose is absorbed into the systemic circulation (bioavailability). They can also change urinary pH, which affects renal excretion of weak acids and bases, further altering the effective drug exposure.", "incorrectas": {"B": "Protein binding depends on plasma protein levels and drug-protein affinity, not gastric or urinary pH, so antacids do not directly alter this parameter.", "C": "Volume of distribution reflects tissue partitioning of a drug throughout the body and is not a property that gastric pH changes directly affect.", "D": "Hepatic clearance depends on hepatic blood flow and enzymatic metabolism (e.g., cytochrome P450 activity), which is unrelated to gastric or urinary pH changes caused by antacids."}}}, {"id": "anking-gastrointestinal-pharmacology-2657", "fuente": "anking", "tema": 40, "anki": "1464478461799", "q": "Which class of GI drugs works by binding directly to the ulcer base to form a physical barrier, allowing HCO3- secretion to reestablish the mucosal pH gradient?", "o": {"A": "Proton pump inhibitors", "B": "H2 receptor antagonists", "C": "Bismuth and sucralfate", "D": "Prostaglandin analogs"}, "r": "C", "e": {"correcta": "Bismuth and sucralfate bind to the base of an ulcer, creating a physical protective coating that shields the damaged mucosa from acid and pepsin. This barrier allows local bicarbonate secretion to reestablish the normal mucus-bicarbonate pH gradient, promoting healing.", "incorrectas": {"A": "Proton pump inhibitors (e.g., omeprazole) irreversibly inhibit the H+/K+ ATPase in parietal cells to reduce acid secretion; they do not act by physically coating the ulcer.", "B": "H2 receptor antagonists (e.g., ranitidine) block histamine-mediated acid secretion at parietal cells but do not form a protective physical barrier over the ulcer.", "D": "Prostaglandin analogs like misoprostol increase mucus/bicarbonate production and maintain mucosal blood flow, but they act on secretory physiology rather than physically adhering to the ulcer base."}}}, {"id": "anking-gastrointestinal-pharmacology-2658", "fuente": "anking", "tema": 40, "anki": "1464478477613", "q": "Bismuth and sucralfate are used clinically to increase the rate of which process?", "o": {"A": "Gastric emptying", "B": "Ulcer healing", "C": "Gastric acid secretion", "D": "Intestinal motility"}, "r": "B", "e": {"correcta": "Bismuth and sucralfate physically bind to the ulcer base, protecting it from further acid/pepsin damage and allowing local bicarbonate secretion to restore the mucosal pH gradient, which promotes and accelerates ulcer healing.", "incorrectas": {"A": "Gastric emptying is regulated by motility agents like metoclopramide, not by mucosal-protective agents such as bismuth or sucralfate.", "C": "These drugs do not increase gastric acid secretion; in fact, their benefit comes from protecting the mucosa despite ongoing acid exposure, not from stimulating more acid.", "D": "Intestinal motility is affected by prokinetic agents or antidiarrheals, not by the mucosal-coating mechanism of bismuth and sucralfate."}}}, {"id": "anking-gastrointestinal-pharmacology-2659", "fuente": "anking", "tema": 40, "anki": "1464478483665", "q": "In addition to promoting ulcer healing, bismuth and sucralfate can also be used to treat which condition?", "o": {"A": "Traveler's diarrhea", "B": "Clostridioides difficile colitis", "C": "Gastroparesis", "D": "Achalasia"}, "r": "A", "e": {"correcta": "Bismuth subsalicylate has antisecretory, antimicrobial, and anti-inflammatory properties in the gut, making it useful in treating traveler's diarrhea in addition to its mucosal-protective role in ulcer healing.", "incorrectas": {"B": "C. difficile colitis is treated with antibiotics such as vancomycin or fidaxomicin, not with bismuth or sucralfate, which do not target C. difficile specifically.", "C": "Gastroparesis is treated with prokinetic agents like metoclopramide that increase gastric motility, a mechanism unrelated to bismuth/sucralfate's mucosal protection.", "D": "Achalasia is a motility disorder of the lower esophageal sphincter treated with pneumatic dilation, botulinum toxin, or myotomy, not with mucosal-protective agents."}}}, {"id": "anking-gastrointestinal-pharmacology-2660", "fuente": "anking", "tema": 40, "anki": "1464478488483", "q": "Which drug used in inflammatory bowel disease is a combination of an antibacterial sulfapyridine moiety and the anti-inflammatory agent 5-aminosalicylic acid?", "o": {"A": "Mesalamine", "B": "Sulfasalazine", "C": "Infliximab", "D": "Balsalazide"}, "r": "B", "e": {"correcta": "Sulfasalazine is composed of sulfapyridine (an antibacterial component) linked to 5-aminosalicylic acid (5-ASA, the anti-inflammatory component). It is used to treat ulcerative colitis, where colonic bacteria cleave the azo bond to release the active 5-ASA at the site of inflammation.", "incorrectas": {"A": "Mesalamine is a formulation of 5-ASA alone, without the sulfapyridine antibacterial moiety, and is used when patients cannot tolerate the sulfa component of sulfasalazine.", "C": "Infliximab is a monoclonal antibody against TNF-alpha used in IBD, structurally and mechanistically unrelated to the sulfapyridine/5-ASA combination of sulfasalazine.", "D": "Balsalazide is another 5-ASA prodrug linked to an inert carrier (not sulfapyridine) that is cleaved by colonic bacteria, distinguishing it from sulfasalazine's specific antibacterial-plus-anti-inflammatory combination."}}}, {"id": "anking-gastrointestinal-pharmacology-2661", "fuente": "anking", "tema": 40, "anki": "1464478504625", "q": "Sulfasalazine requires activation of its 5-aminosalicylic acid component by which process?", "o": {"A": "Hepatic first-pass metabolism", "B": "Colonic bacterial cleavage", "C": "Gastric acid hydrolysis", "D": "Pancreatic enzyme digestion"}, "r": "B", "e": {"correcta": "Sulfasalazine is a prodrug in which colonic bacteria cleave the azo bond linking sulfapyridine to 5-aminosalicylic acid, releasing the active anti-inflammatory 5-ASA locally within the colon, which is ideal for treating colonic inflammation in ulcerative colitis.", "incorrectas": {"A": "Hepatic first-pass metabolism refers to drug transformation in the liver after absorption, but sulfasalazine's activation occurs in the colon before significant systemic absorption of the active moiety.", "C": "Gastric acid does not cleave the azo bond of sulfasalazine; the drug passes through the stomach largely intact to reach the colon where bacteria perform the cleavage.", "D": "Pancreatic enzymes act on macronutrients (proteins, fats, carbohydrates) in the small intestine and are not responsible for activating sulfasalazine, which depends on colonic bacterial azoreductases."}}}, {"id": "anking-gastrointestinal-pharmacology-2662", "fuente": "anking", "tema": 40, "anki": "1464478510802", "q": "A reversible adverse effect associated with sulfasalazine therapy is which of the following?", "o": {"A": "Irreversible infertility", "B": "Oligospermia", "C": "Testicular atrophy", "D": "Gynecomastia"}, "r": "B", "e": {"correcta": "Sulfasalazine can cause reversible oligospermia (reduced sperm count), an adverse effect that typically resolves after discontinuing the drug. It can also cause sulfonamide-related toxicity (e.g., hypersensitivity reactions) as well as malaise and nausea due to the sulfapyridine component.", "incorrectas": {"A": "The oligospermia caused by sulfasalazine is reversible upon stopping the drug, not a permanent/irreversible form of infertility, which distinguishes it from causes of fixed sterility.", "C": "Testicular atrophy is a chronic structural change (seen with conditions like cirrhosis or anabolic steroid use), not the mechanism of sulfasalazine's reversible effect on sperm count.", "D": "Gynecomastia results from hormonal imbalances (e.g., increased estrogen-to-androgen ratio) caused by drugs like spironolactone or ketoconazole, not from sulfasalazine's antibacterial sulfapyridine component."}}}, {"id": "anking-gastrointestinal-pharmacology-2663", "fuente": "anking", "tema": 40, "anki": "1464478523728", "q": "Orlistat is primarily indicated for which clinical use?", "o": {"A": "Treatment of hyperlipidemia", "B": "Weight loss", "C": "Treatment of steatorrhea", "D": "Management of type 2 diabetes"}, "r": "B", "e": {"correcta": "Orlistat is a lipase inhibitor used clinically for weight loss. By inhibiting pancreatic and gastric lipases, it decreases the breakdown and subsequent absorption of dietary fats, reducing caloric intake and promoting weight reduction in overweight or obese patients.", "incorrectas": {"A": "Hyperlipidemia is treated with agents like statins, fibrates, or ezetimibe that target lipid synthesis or absorption pathways; orlistat's role is weight loss via fat malabsorption, not primary lipid-lowering therapy.", "C": "Steatorrhea (fatty stools) is actually an adverse effect of orlistat, not something it treats — the drug intentionally causes fat malabsorption, which manifests as steatorrhea.", "D": "Type 2 diabetes is managed with agents like metformin, sulfonylureas, or GLP-1 agonists; while weight loss can secondarily improve glycemic control, orlistat is not a diabetes medication itself."}}}, {"id": "anking-gastrointestinal-pharmacology-2664", "fuente": "anking", "tema": 40, "anki": "1464478534072", "q": "A patient taking orlistat for weight loss develops oily, loose stools and is found to have reduced absorption of vitamins A, D, E, and K. Which adverse effect of orlistat explains both findings?", "o": {"A": "Osmotic diarrhea", "B": "Steatorrhea", "C": "Bile acid malabsorption", "D": "Bacterial overgrowth"}, "r": "B", "e": {"correcta": "Orlistat inhibits pancreatic and gastric lipases, preventing the breakdown of dietary triglycerides into absorbable free fatty acids. The resulting unabsorbed fat passes into the stool, causing steatorrhea, and because vitamins A, D, E, and K require fat solubilization for absorption, their uptake decreases as well, sometimes necessitating supplementation.", "incorrectas": {"A": "Osmotic diarrhea results from unabsorbed solutes (e.g., lactose, certain laxatives) drawing water into the gut lumen, a different mechanism than the fat malabsorption seen with lipase inhibition by orlistat.", "C": "Bile acid malabsorption occurs with ileal disease or resection and causes bile-acid-induced secretory diarrhea, not the lipase-inhibition mechanism responsible for orlistat's steatorrhea.", "D": "Bacterial overgrowth can cause fat malabsorption and diarrhea via bacterial deconjugation of bile acids, but this is unrelated to orlistat's direct pharmacologic inhibition of lipase enzymes."}}}, {"id": "anking-gastrointestinal-pharmacology-2665", "fuente": "anking", "tema": 40, "anki": "1464478571996", "q": "A dopamine D2 receptor antagonist that increases gastric resting tone, contractility, and lower esophageal sphincter (LES) tone is used to treat which condition?", "o": {"A": "Achalasia", "B": "Diabetic or post-surgical gastroparesis", "C": "Peptic ulcer disease", "D": "Gastroesophageal reflux from hiatal hernia"}, "r": "B", "e": {"correcta": "Metoclopramide is a D2 receptor antagonist that acts as a prokinetic agent, increasing gastric resting tone, contractility, and LES tone. This makes it useful in diabetic or post-surgical gastroparesis, where delayed gastric emptying from autonomic neuropathy or surgical disruption impairs normal motility.", "incorrectas": {"A": "Achalasia involves failure of LES relaxation due to loss of inhibitory neurons in the myenteric plexus; it is treated with pneumatic dilation, botulinum toxin injection, or myotomy, not primarily with D2 antagonists.", "C": "Peptic ulcer disease is treated with acid-suppressing agents (PPIs, H2 blockers) or mucosal protectants, not with prokinetic D2 antagonists like metoclopramide.", "D": "While increased LES tone from metoclopramide can reduce reflux to some degree, its primary indication highlighted here is gastroparesis; hiatal hernia-related reflux is more classically managed with acid suppression or surgical correction."}}}, {"id": "anking-gastrointestinal-pharmacology-2666", "fuente": "anking", "tema": 40, "anki": "1464478577325", "q": "Does metoclopramide, a D2 receptor antagonist that increases gastric resting tone, contractility, and LES tone, also affect colon transit time?", "o": {"A": "Yes, it markedly slows colon transit time", "B": "Yes, it markedly increases colon transit time", "C": "No, it has no significant effect on colon transit time", "D": "It only affects colon transit time in diabetic patients"}, "r": "C", "e": {"correcta": "Metoclopramide's prokinetic effects are localized to the upper GI tract, increasing gastric resting tone, contractility, and LES tone via D2 receptor antagonism, but it does not have a significant clinically relevant effect on colon transit time.", "incorrectas": {"A": "Metoclopramide does not slow colon transit; its known prokinetic actions are limited to gastric motility and the LES, not colonic function.", "B": "Although one might expect a prokinetic agent to speed up all GI transit, metoclopramide's mechanism specifically targets gastric and esophageal motility, without a significant increase in colonic transit.", "D": "The lack of effect on colon transit time is a general pharmacologic property of metoclopramide's mechanism, not something restricted to or altered specifically in diabetic patients."}}}, {"id": "anking-reproductive-system-physiology-2667", "fuente": "anking", "tema": 32, "anki": "1464523822689", "q": "How do maternal serum alpha-fetoprotein (AFP) levels typically change in a fetus with a neural tube defect?", "o": {"A": "Decreased", "B": "Increased", "C": "Unchanged", "D": "Initially decreased, then increased"}, "r": "B", "e": {"correcta": "Neural tube defects (e.g., spina bifida, anencephaly) leave an open neural tube, allowing AFP produced by the fetal liver to leak into the amniotic fluid and subsequently into maternal serum in elevated amounts, making increased AFP a key screening marker for these defects.", "incorrectas": {"A": "Decreased AFP is characteristically associated with Down syndrome (trisomy 21), not with neural tube defects, which instead show elevated levels due to leakage through the open defect.", "C": "AFP levels are not unchanged in neural tube defects; the open communication between fetal CSF/tissue and amniotic fluid causes a measurable rise in AFP that is used diagnostically.", "D": "There is no biphasic pattern of initially decreased then increased AFP in neural tube defects; the elevation is a consistent finding used in quad screen and other prenatal testing."}}}, {"id": "anking-gastrointestinal-pharmacology-2668", "fuente": "anking", "tema": 40, "anki": "1464524897579", "q": "Which drug used in the treatment of ulcerative colitis is associated with reversible oligospermia as an adverse effect?", "o": {"A": "Mesalamine", "B": "Sulfasalazine", "C": "Infliximab", "D": "Azathioprine"}, "r": "B", "e": {"correcta": "Sulfasalazine, composed of sulfapyridine and 5-aminosalicylic acid, is specifically associated with reversible oligospermia, which typically resolves once the medication is discontinued. This adverse effect is attributed to the sulfapyridine component.", "incorrectas": {"A": "Mesalamine, the 5-ASA-only formulation without sulfapyridine, is generally better tolerated and does not carry the same association with oligospermia as sulfasalazine.", "C": "Infliximab, a TNF-alpha inhibitor, carries risks of infection (including reactivation of latent TB) and infusion reactions, but oligospermia is not a hallmark adverse effect of this biologic agent.", "D": "Azathioprine, an immunosuppressant sometimes used in IBD, is associated with bone marrow suppression and increased infection/malignancy risk, but reversible oligospermia is the classic teaching point for sulfasalazine specifically."}}}, {"id": "anking-molecular-biology-2669", "fuente": "anking", "tema": 44, "anki": "1467682141963", "q": "During which phase of the cell cycle does DNA condense to form visible chromosomes?", "o": {"A": "S phase", "B": "G1 phase", "C": "Mitosis", "D": "G2 phase"}, "r": "C", "e": {"correcta": "During mitosis (specifically prophase), chromatin condenses into tightly coiled, visible chromosomes to facilitate accurate segregation of genetic material into two daughter cells. This condensation is essential for preventing DNA entanglement during chromosome separation.", "incorrectas": {"A": "S phase is when DNA replication occurs, duplicating the genome, but the chromatin remains in its extended, less condensed form during this phase rather than forming visible chromosomes.", "B": "G1 phase is a growth phase preceding DNA synthesis, during which the cell prepares for replication; chromatin is in its normal, decondensed interphase state, not condensed into chromosomes.", "D": "G2 phase follows DNA replication and involves preparation for mitosis (e.g., checking for DNA damage), but visible chromosome condensation itself occurs during mitosis, not G2."}}}, {"id": "anking-molecular-biology-2670", "fuente": "anking", "tema": 44, "anki": "1467682233616", "q": "Which epigenetic process is responsible for genomically imprinting DNA during gametogenesis, silencing one parental allele while the other remains expressed?", "o": {"A": "Histone acetylation", "B": "DNA methylation", "C": "Alternative splicing", "D": "RNA interference"}, "r": "B", "e": {"correcta": "Genomic imprinting occurs via DNA methylation during gametogenesis, silencing either the maternal or paternal allele of specific genes depending on the imprinting pattern. In maternal imprinting, the maternal allele is silenced (paternal allele expressed), and vice versa for paternal imprinting; these genes are not X- or Y-linked.", "incorrectas": {"A": "Histone acetylation generally loosens chromatin structure and promotes transcription broadly, but it is not the specific mechanism responsible for establishing heritable, parent-of-origin-specific imprinting marks during gametogenesis.", "C": "Alternative splicing generates different mRNA transcripts (and protein isoforms) from the same pre-mRNA after transcription; it has no role in silencing a parental allele at the DNA level.", "D": "RNA interference involves small RNAs (siRNA/miRNA) silencing gene expression post-transcriptionally or via chromatin modification in some contexts, but classic genomic imprinting in humans is established through DNA methylation, not RNAi."}}}, {"id": "anking-molecular-biology-2671", "fuente": "anking", "tema": 44, "anki": "1467682438089", "q": "Which molecular process uses a DNA template to synthesize new DNA?", "o": {"A": "Transcription", "B": "Translation", "C": "Replication", "D": "Reverse transcription"}, "r": "C", "e": {"correcta": "DNA replication is the process by which a cell copies its DNA template to produce two identical DNA molecules, ensuring each daughter cell receives a complete genome. This occurs during S phase and relies on DNA polymerases synthesizing new strands complementary to each parental strand.", "incorrectas": {"A": "Transcription synthesizes RNA from a DNA template, not DNA from DNA, representing a different information flow step in the central dogma of molecular biology.", "B": "Translation converts an RNA (mRNA) template into a protein sequence at the ribosome; it does not involve DNA synthesis at all.", "D": "Reverse transcription synthesizes DNA from an RNA template (used by retroviruses via reverse transcriptase), which is distinct from replication, where DNA is synthesized from a DNA template."}}}, {"id": "anking-molecular-biology-2672", "fuente": "anking", "tema": 44, "anki": "1467683632126", "q": "Which molecular process converts a DNA template into RNA?", "o": {"A": "Replication", "B": "Transcription", "C": "Translation", "D": "Reverse transcription"}, "r": "B", "e": {"correcta": "Transcription is the process by which RNA polymerase synthesizes RNA using a DNA template strand, producing mRNA, tRNA, rRNA, and other RNA species. This is the first step in gene expression, converting genetic information from DNA into an RNA intermediate.", "incorrectas": {"A": "Replication produces new DNA from a DNA template, maintaining the same type of nucleic acid, unlike transcription which converts DNA information into RNA.", "C": "Translation uses an RNA (mRNA) template to synthesize protein at the ribosome; it does not involve producing RNA from DNA.", "D": "Reverse transcription synthesizes DNA from an RNA template, essentially the reverse informational flow compared to transcription, which goes from DNA to RNA."}}}, {"id": "anking-molecular-biology-2673", "fuente": "anking", "tema": 44, "anki": "1467683640354", "q": "Which molecular process converts an RNA template into a protein?", "o": {"A": "Transcription", "B": "Replication", "C": "Translation", "D": "Reverse transcription"}, "r": "C", "e": {"correcta": "Translation occurs at the ribosome, where mRNA codons are read and matched with complementary tRNA anticodons carrying specific amino acids, assembling them into a polypeptide chain. This is the final step of gene expression, converting nucleic acid sequence information into functional protein.", "incorrectas": {"A": "Transcription produces RNA from a DNA template; it does not generate protein and precedes translation in the gene expression pathway.", "B": "Replication copies DNA to produce more DNA, an entirely separate process from protein synthesis, which requires the ribosomal machinery of translation.", "D": "Reverse transcription converts RNA into DNA, which is the opposite informational direction from translation, and does not produce protein."}}}, {"id": "anking-molecular-biology-2674", "fuente": "anking", "tema": 44, "anki": "1467683646912", "q": "Which molecular process converts an RNA template into DNA?", "o": {"A": "Transcription", "B": "Translation", "C": "Replication", "D": "Reverse transcription"}, "r": "D", "e": {"correcta": "Reverse transcription is carried out by the enzyme reverse transcriptase, which synthesizes a complementary DNA (cDNA) strand from an RNA template. This process is used by retroviruses (e.g., HIV) to integrate their RNA genome into host DNA and is also exploited in laboratory techniques like RT-PCR.", "incorrectas": {"A": "Transcription goes in the opposite direction, synthesizing RNA from a DNA template, rather than DNA from RNA as in reverse transcription.", "B": "Translation converts RNA into protein, not DNA, and occurs at ribosomes rather than through a polymerase acting on nucleic acid templates to produce DNA.", "C": "Replication produces DNA from a DNA template (not an RNA template), which is mechanistically distinct from reverse transcription's RNA-to-DNA conversion."}}}, {"id": "anking-molecular-biology-2675", "fuente": "anking", "tema": 44, "anki": "1467683654087", "q": "In terms of size, how does DNA typically compare to RNA within a cell?", "o": {"A": "DNA is much smaller than RNA", "B": "DNA is much larger than RNA", "C": "DNA and RNA are approximately equal in size", "D": "Size varies randomly with no consistent pattern"}, "r": "B", "e": {"correcta": "DNA molecules (such as entire chromosomes) are typically much larger than RNA molecules, which are usually transcribed as shorter segments corresponding to individual genes or functional units. This size difference has practical laboratory implications, such as differing susceptibility to fragmentation.", "incorrectas": {"A": "DNA is not smaller than RNA; genomic DNA is organized into long chromosomes far exceeding the length of typical RNA transcripts.", "C": "DNA and RNA are not approximately equal in size; DNA encompasses the entire genome in long continuous molecules, while RNA transcripts are much shorter, gene-specific copies.", "D": "The size difference between DNA and RNA follows a predictable and consistent pattern based on their biological roles (genome storage vs. transcript synthesis), not random variation."}}}, {"id": "anking-molecular-biology-2676", "fuente": "anking", "tema": 44, "anki": "1467683661152", "q": "Are RNA and protein samples typically fragmented prior to laboratory analysis?", "o": {"A": "Yes, both are routinely fragmented before analysis", "B": "No, they are typically analyzed without fragmentation", "C": "Only protein is fragmented, RNA is not", "D": "Only RNA is fragmented, protein is not"}, "r": "B", "e": {"correcta": "Because RNA and protein molecules are comparatively short (relative to genomic DNA), they are typically analyzed intact without needing fragmentation prior to techniques such as gel electrophoresis or blotting, in contrast to DNA, which is large and usually fragmented first.", "incorrectas": {"A": "Routine fragmentation of both RNA and protein is unnecessary because they are already short enough to be resolved and analyzed without prior cutting, unlike large DNA molecules.", "C": "Protein is also not typically fragmented before standard analysis (e.g., Western blot uses full-length denatured protein), so singling out protein as fragmented while RNA is not is incorrect.", "D": "RNA is not the one requiring fragmentation before analysis — DNA is the molecule commonly fragmented due to its large size, not RNA."}}}, {"id": "anking-molecular-biology-2677", "fuente": "anking", "tema": 44, "anki": "1467683666150", "q": "Is DNA typically fragmented before being analyzed in laboratory techniques such as Southern blotting?", "o": {"A": "No, DNA is analyzed as a whole chromosome", "B": "Yes, DNA is typically fragmented before analysis", "C": "Only mitochondrial DNA requires fragmentation", "D": "Fragmentation is only needed for RNA, not DNA"}, "r": "B", "e": {"correcta": "Because DNA molecules (entire chromosomes) are extremely large, they are typically cut into smaller fragments, often using restriction enzymes, before being separated and analyzed by techniques like Southern blotting or gel electrophoresis. This is in contrast to RNA and protein, which are usually short enough to analyze without fragmentation.", "incorrectas": {"A": "Analyzing DNA as a whole intact chromosome is generally impractical for standard laboratory techniques; fragmentation into manageable pieces is the standard approach.", "C": "Fragmentation is not limited to mitochondrial DNA — nuclear genomic DNA is also routinely fragmented before analysis due to its large size.", "D": "Fragmentation is specifically necessary for DNA because of its large size, whereas RNA is typically analyzed without needing to be fragmented first."}}}, {"id": "anking-molecular-biology-2678", "fuente": "anking", "tema": 44, "anki": "1467683671375", "q": "How many rings make up the core structure of a purine base?", "o": {"A": "One", "B": "Two", "C": "Three", "D": "Four"}, "r": "B", "e": {"correcta": "Purines have a two-ring structure, consisting of a fused five-membered ring and six-membered ring, giving them a larger overall molecular structure compared to pyrimidines. Adenine and guanine are the two purine bases found in nucleic acids.", "incorrectas": {"A": "A single ring structure describes pyrimidines (cytosine, uracil, thymine), not purines, which have an additional fused ring making them structurally larger.", "C": "Three fused rings is not characteristic of the standard purine or pyrimidine bases found in DNA/RNA; purines have exactly two fused rings (one five-membered, one six-membered).", "D": "Four rings would be an even larger structure than seen in any of the standard nitrogenous bases; purines are defined by their two-ring (five- and six-membered) fused structure."}}}, {"id": "anking-molecular-biology-2679", "fuente": "anking", "tema": 44, "anki": "1467683685406", "q": "How many rings make up the core structure of a pyrimidine base?", "o": {"A": "One", "B": "Two", "C": "Three", "D": "Zero (no ring structure)"}, "r": "A", "e": {"correcta": "Pyrimidines (cytosine, uracil, and thymine) have a single six-membered ring structure, making them smaller molecules than purines, which have two fused rings. This structural difference is fundamental to base pairing rules in DNA and RNA.", "incorrectas": {"B": "Two rings describes the fused five- and six-membered ring structure of purines (adenine, guanine), not the single-ring structure of pyrimidines.", "C": "Three rings does not correspond to any of the standard nitrogenous bases; pyrimidines have exactly one six-membered ring.", "D": "Pyrimidines do have a ring structure — specifically one six-membered aromatic ring — so stating they have no ring structure is incorrect."}}}, {"id": "anking-molecular-biology-2680", "fuente": "anking", "tema": 44, "anki": "1467683698106", "q": "Which two nitrogenous bases are classified as purines?", "o": {"A": "Cytosine and thymine", "B": "Adenine and guanine", "C": "Guanine and cytosine", "D": "Adenine and uracil"}, "r": "B", "e": {"correcta": "Adenine and guanine are the two purine bases, each having a two-ring (fused five- and six-membered) structure. The mnemonic 'PURe As Gold' helps recall that purines include Adenine and Guanine.", "incorrectas": {"A": "Cytosine and thymine are both pyrimidines (single-ring structures), not purines, making this pairing incorrect for the purine category.", "C": "Guanine is a purine, but cytosine is a pyrimidine, so this combination mixes one correct purine with an incorrect pyrimidine.", "D": "Adenine is a purine, but uracil is a pyrimidine (found in RNA in place of thymine), so this pairing incorrectly includes a pyrimidine as if it were a purine."}}}, {"id": "anking-molecular-biology-2681", "fuente": "anking", "tema": 44, "anki": "1467683705831", "q": "Which three nitrogenous bases are classified as pyrimidines?", "o": {"A": "Adenine, guanine, and cytosine", "B": "Cytosine, uracil, and thymine", "C": "Adenine, uracil, and thymine", "D": "Guanine, uracil, and thymine"}, "r": "B", "e": {"correcta": "Cytosine, uracil, and thymine are the three pyrimidine bases, each with a single six-membered ring structure. The mnemonic 'CUT the PY (pie)' helps recall that Cytosine, Uracil, and Thymine are pyrimidines.", "incorrectas": {"A": "Adenine and guanine are purines (two-ring structures), not pyrimidines, so including them alongside cytosine misclassifies two of the three bases.", "C": "Adenine is a purine, not a pyrimidine; while uracil and thymine are correctly pyrimidines, adenine does not belong in this group.", "D": "Guanine is a purine, not a pyrimidine; despite uracil and thymine being correctly classified as pyrimidines, guanine's inclusion makes this answer incorrect."}}}, {"id": "anking-molecular-biology-2682", "fuente": "anking", "tema": 44, "anki": "1467683713918", "q": "Which purine base is characterized by having an amino group at the 12 o'clock position on its ring structure?", "o": {"A": "Guanine", "B": "Adenine", "C": "Cytosine", "D": "Thymine"}, "r": "B", "e": {"correcta": "Adenine is the purine base with an amino group positioned at the 12 o'clock location on its ring structure, a structural feature commonly used to distinguish it from guanine when studying nucleotide chemistry.", "incorrectas": {"A": "Guanine, the other purine, lacks an amino group at the 12 o'clock position (it instead has a carbonyl/keto group there with an amino group elsewhere), distinguishing it structurally from adenine.", "C": "Cytosine is a pyrimidine, not a purine, and while it does have an amino group at its 12 o'clock-equivalent position, it does not belong to the purine category being asked about here.", "D": "Thymine is a pyrimidine characterized by methyl groups rather than an amino group at the relevant position, and it is not classified as a purine."}}}, {"id": "anking-molecular-biology-2683", "fuente": "anking", "tema": 44, "anki": "1467683722745", "q": "Which purine base lacks an amino group at the 12 o'clock position on its ring structure?", "o": {"A": "Adenine", "B": "Guanine", "C": "Uracil", "D": "Thymine"}, "r": "B", "e": {"correcta": "Guanine is the purine that lacks an amino group at the 12 o'clock position on its ring (it has a keto/carbonyl group there instead, with its amino group located elsewhere on the ring), distinguishing it structurally from adenine.", "incorrectas": {"A": "Adenine is defined by the presence of an amino group at the 12 o'clock position, the opposite of the feature being asked about, which makes it structurally distinct from guanine.", "C": "Uracil is a pyrimidine, not a purine, so it does not fit into this comparison of purine ring structures at all.", "D": "Thymine is also a pyrimidine, structurally unrelated to the purine ring system being discussed, and is characterized by methyl groups rather than the amino group pattern relevant to purines."}}}, {"id": "anking-molecular-biology-2684", "fuente": "anking", "tema": 44, "anki": "1467683729345", "q": "Which pyrimidine base is characterized by having an amino group at the 12 o'clock position on its ring structure?", "o": {"A": "Thymine", "B": "Uracil", "C": "Cytosine", "D": "Guanine"}, "r": "C", "e": {"correcta": "Cytosine is the pyrimidine base with an amino group at the 12 o'clock position of its ring, distinguishing it from uracil and thymine, which instead have a carbonyl (keto) group at that position.", "incorrectas": {"A": "Thymine lacks an amino group at the 12 o'clock position; instead, it is distinguished by the presence of a methyl group, differentiating it from cytosine's amino group.", "B": "Uracil also lacks the 12 o'clock amino group seen in cytosine, and additionally lacks the methyl group found in thymine, making it structurally the simplest of the three pyrimidines.", "D": "Guanine is a purine, not a pyrimidine, so it does not belong in this comparison of pyrimidine ring substituents."}}}, {"id": "anking-molecular-biology-2685", "fuente": "anking", "tema": 44, "anki": "1467683736978", "q": "Which pyrimidine base lacks both an amino group at the 12 o'clock position and any methyl group substituents?", "o": {"A": "Cytosine", "B": "Thymine", "C": "Uracil", "D": "Guanine"}, "r": "C", "e": {"correcta": "Uracil is the simplest pyrimidine, lacking both the 12 o'clock amino group found in cytosine and the methyl group found in thymine. This structural simplicity is consistent with uracil's role as the RNA-specific base that replaces thymine.", "incorrectas": {"A": "Cytosine has an amino group at the 12 o'clock position, which distinguishes it from uracil, ruling it out as the base lacking that feature.", "B": "Thymine has a methyl group (distinguishing it from uracil) even though it also lacks the 12 o'clock amino group, so it does not meet both criteria of lacking amino group AND methyl group.", "D": "Guanine is a purine, not a pyrimidine, so it is unrelated to this comparison of pyrimidine substituent patterns."}}}, {"id": "anking-molecular-biology-2686", "fuente": "anking", "tema": 44, "anki": "1467683748989", "q": "Which pyrimidine base is characterized by the presence of a methyl group but lacks an amino group at the 12 o'clock position?", "o": {"A": "Cytosine", "B": "Uracil", "C": "Thymine", "D": "Adenine"}, "r": "C", "e": {"correcta": "Thymine is distinguished by having a methyl group on its ring while lacking the 12 o'clock amino group seen in cytosine. This methyl group is the key structural difference between thymine and uracil, and thymine is found exclusively in DNA.", "incorrectas": {"A": "Cytosine has an amino group at the 12 o'clock position and lacks a methyl group, the opposite substituent pattern compared to thymine.", "B": "Uracil lacks both the amino group and the methyl group, differing from thymine specifically by the absence of the methyl group (uracil is essentially demethylated thymine, structurally).", "D": "Adenine is a purine, not a pyrimidine, and is therefore unrelated to this comparison of pyrimidine substituents."}}}, {"id": "anking-molecular-biology-2687", "fuente": "anking", "tema": 44, "anki": "1467683773187", "q": "What is the key structural difference between thymine and uracil?", "o": {"A": "Thymine has an amino group, uracil does not", "B": "Thymine has a methyl group, uracil does not", "C": "Uracil has a methyl group, thymine does not", "D": "Thymine has two rings, uracil has one"}, "r": "B", "e": {"correcta": "Thymine differs from uracil by the presence of a methyl group on its pyrimidine ring; uracil lacks this methyl group. This distinction explains why thymine is found in DNA (providing additional stability) while uracil, the demethylated counterpart, is found in RNA.", "incorrectas": {"A": "Neither thymine nor uracil has an amino group at the relevant position; both lack it, which is why this is not the distinguishing feature (that would apply to cytosine instead).", "C": "This reverses the correct relationship; it is thymine, not uracil, that possesses the methyl group, making uracil the simpler, non-methylated base.", "D": "Both thymine and uracil are pyrimidines with a single six-membered ring structure; neither has two rings, so ring number is not the distinguishing feature between them."}}}, {"id": "anking-molecular-biology-2688", "fuente": "anking", "tema": 44, "anki": "1467683782311", "q": "Which pyrimidine base is found exclusively in DNA and not in RNA?", "o": {"A": "Cytosine", "B": "Uracil", "C": "Thymine", "D": "Guanine"}, "r": "C", "e": {"correcta": "Thymine, distinguished by its methyl group, is found exclusively in DNA, where it pairs with adenine. In RNA, thymine is replaced by uracil, which lacks the methyl group but otherwise base-pairs similarly with adenine.", "incorrectas": {"A": "Cytosine is present in both DNA and RNA, pairing with guanine in each nucleic acid, so it is not unique to DNA alone.", "B": "Uracil is the pyrimidine found exclusively in RNA (replacing thymine), which is the opposite of what is being asked, making it incorrect as a DNA-only base.", "D": "Guanine is a purine, not a pyrimidine, and is present in both DNA and RNA, so it does not answer this question about a DNA-exclusive pyrimidine."}}}, {"id": "anking-molecular-biology-2689", "fuente": "anking", "tema": 44, "anki": "1467683785823", "q": "Which pyrimidine base is found exclusively in RNA and not in DNA?", "o": {"A": "Thymine", "B": "Cytosine", "C": "Uracil", "D": "Guanine"}, "r": "C", "e": {"correcta": "Uracil is the pyrimidine base found exclusively in RNA, where it base-pairs with adenine in place of thymine. Uracil lacks the methyl group present on thymine, which is instead found only in DNA.", "incorrectas": {"A": "Thymine is the DNA-exclusive pyrimidine (containing a methyl group), the opposite of what is being asked, since RNA uses uracil in place of thymine.", "B": "Cytosine is present in both DNA and RNA, pairing with guanine in each, so it is not restricted to RNA alone.", "D": "Guanine is a purine found in both DNA and RNA, not a pyrimidine restricted to RNA, making it irrelevant to this specific comparison."}}}, {"id": "anking-molecular-biology-2690", "fuente": "anking", "tema": 44, "anki": "1467683788745", "q": "A molecule consisting of a nitrogenous base attached to a sugar (ribose or deoxyribose), without a phosphate group, is called a what?", "o": {"A": "Nucleotide", "B": "Nucleoside", "C": "Polynucleotide", "D": "Nucleic acid"}, "r": "B", "e": {"correcta": "A nucleoside is composed of a nitrogenous base linked to a sugar (either ribose in RNA or deoxyribose in DNA), without a phosphate group. Adding one or more phosphate groups to a nucleoside converts it into a nucleotide, the actual building block of DNA and RNA polymers.", "incorrectas": {"A": "A nucleotide includes a phosphate group in addition to the base and sugar; the absence of phosphate is precisely what distinguishes a nucleoside from a nucleotide.", "C": "A polynucleotide is a chain of many linked nucleotides (each containing a phosphate group) forming DNA or RNA strands, a much larger structure than a single base-sugar unit.", "D": "Nucleic acid is the broad term for DNA or RNA polymers made of many nucleotides; it does not refer to the single base-plus-sugar unit described here."}}}]};
